class ExternalDataManager:
    """
    Unified external data source manager that consolidates all duplicate API functionality
    Provides centralized management for USGS, Copernicus, ESA, IRIS/FDSN, and other external APIs
    """
    
    def __init__(self, config: Dict[str, Any]):
        self.config = config
        self.logger = logging.getLogger(__name__)
        self.session = requests.Session()
        self.rate_limiters = {}
        self.cache = {}
        self.auth_tokens = {}
        
        # Initialize API endpoints
        self.endpoints = {
            'usgs_earthquake': 'https://earthquake.usgs.gov/fdsnws/event/1/',
            'iris_fdsn': 'http://service.iris.edu/fdsnws/',
            'copernicus_cds': 'https://cds.climate.copernicus.eu/api/v2/',
            'copernicus_dataspace': 'https://catalogue.dataspace.copernicus.eu/odata/v1/',
            'esa_sentinel_hub': 'https://services.sentinel-hub.com/',
            'usgs_landsat': 'https://landsatlook.usgs.gov/sat-api/',
            'noaa_ncei': 'https://www.ncei.noaa.gov/data/api/v1/',
            'gbif': 'https://api.gbif.org/v1/',
            'worldbank': 'https://api.worldbank.org/v2/'
        }
        
        # Initialize rate limiting (requests per minute)
        self.rate_limits = {
            'usgs_earthquake': 60,
            'iris_fdsn': 120,
            'copernicus_cds': 30,
            'copernicus_dataspace': 100,
            'esa_sentinel_hub': 200,
            'usgs_landsat': 100,
            'noaa_ncei': 60,
            'gbif': 300,
            'worldbank': 120
        }
        
        self._initialize_rate_limiters()
        self._initialize_authentication()
    
    def _initialize_rate_limiters(self):
        """Initialize rate limiters for each service"""
        for service, limit in self.rate_limits.items():
            self.rate_limiters[service] = {
                'requests': deque(),
                'limit': limit,
                'window': 60  # 1 minute window
            }
    
    def _initialize_authentication(self):
        """Initialize authentication tokens and credentials"""
        try:
            # Copernicus CDS authentication
            if 'copernicus_cds_key' in self.config:
                self.auth_tokens['copernicus_cds'] = self.config['copernicus_cds_key']
            
            # ESA Sentinel Hub authentication
            if 'esa_client_id' in self.config and 'esa_client_secret' in self.config:
                self._get_esa_token()
            
            # Other API keys
            for service in ['usgs', 'noaa', 'gbif', 'worldbank']:
                key_name = f"{service}_api_key"
                if key_name in self.config:
                    self.auth_tokens[service] = self.config[key_name]
                    
        except Exception as e:
            self.logger.error(f"Failed to initialize authentication: {e}")
    
    def _get_esa_token(self):
        """Get OAuth token for ESA Sentinel Hub"""
        try:
            token_url = "https://services.sentinel-hub.com/oauth/token"
            data = {
                'grant_type': 'client_credentials',
                'client_id': self.config['esa_client_id'],
                'client_secret': self.config['esa_client_secret']
            }
            response = requests.post(token_url, data=data)
            if response.status_code == 200:
                token_data = response.json()
                self.auth_tokens['esa_sentinel_hub'] = token_data['access_token']
        except Exception as e:
            self.logger.error(f"Failed to get ESA token: {e}")
    
    def _check_rate_limit(self, service: str) -> bool:
        """Check if request is within rate limit"""
        now = time.time()
        rate_limiter = self.rate_limiters[service]
        
        # Remove old requests outside the window
        while rate_limiter['requests'] and now - rate_limiter['requests'][0] > rate_limiter['window']:
            rate_limiter['requests'].popleft()
        
        # Check if under limit
        if len(rate_limiter['requests']) < rate_limiter['limit']:
            rate_limiter['requests'].append(now)
            return True
        
        return False
    
    def _get_cache_key(self, service: str, endpoint: str, params: Dict) -> str:
        """Generate cache key for request"""
        key_data = f"{service}:{endpoint}:{json.dumps(params, sort_keys=True)}"
        return hashlib.md5(key_data.encode()).hexdigest()
    
    async def _make_request(self, service: str, endpoint: str, params: Dict = None, method: str = 'GET') -> Dict:
        """Make unified API request with rate limiting and caching"""
        if not self._check_rate_limit(service):
            wait_time = 60 / self.rate_limits[service]
            await asyncio.sleep(wait_time)
        
        # Check cache
        cache_key = self._get_cache_key(service, endpoint, params or {})
        if cache_key in self.cache:
            cache_entry = self.cache[cache_key]
            if time.time() - cache_entry['timestamp'] < 300:  # 5 minute cache
                return cache_entry['data']
        
        try:
            headers = {'User-Agent': 'Prometheus-Geological-System/1.0'}
            
            # Add service-specific authentication
            if service in self.auth_tokens:
                if service == 'copernicus_cds':
                    headers['Authorization'] = f"Bearer {self.auth_tokens[service]}"
                elif service == 'esa_sentinel_hub':
                    headers['Authorization'] = f"Bearer {self.auth_tokens[service]}"
                else:
                    if params is None:
                        params = {}
                    params['api_key'] = self.auth_tokens[service]
            
            # Make request
            if method == 'GET':
                response = self.session.get(endpoint, params=params, headers=headers, timeout=30)
            else:
                response = self.session.post(endpoint, json=params, headers=headers, timeout=30)
            
            response.raise_for_status()
            data = response.json() if response.content else {}
            
            # Cache successful response
            self.cache[cache_key] = {
                'data': data,
                'timestamp': time.time()
            }
            
            return data
            
        except Exception as e:
            self.logger.error(f"Request failed for {service} at {endpoint}: {e}")
            return {}
    
    async def query_usgs_earthquakes(self, params: Dict) -> Dict:
        """Unified USGS earthquake data query"""
        endpoint = f"{self.endpoints['usgs_earthquake']}query"
        return await self._make_request('usgs_earthquake', endpoint, params)
    
    async def query_iris_fdsn(self, data_type: str, params: Dict) -> Dict:
        """Unified IRIS FDSN data query"""
        endpoint = f"{self.endpoints['iris_fdsn']}{data_type}/1/query"
        return await self._make_request('iris_fdsn', endpoint, params)
    
    async def query_copernicus_cds(self, dataset: str, params: Dict) -> Dict:
        """Unified Copernicus Climate Data Store query"""
        endpoint = f"{self.endpoints['copernicus_cds']}resources/{dataset}"
        return await self._make_request('copernicus_cds', endpoint, params, method='POST')
    
    async def query_copernicus_dataspace(self, collection: str, params: Dict) -> Dict:
        """Unified Copernicus Data Space query"""
        endpoint = f"{self.endpoints['copernicus_dataspace']}{collection}"
        return await self._make_request('copernicus_dataspace', endpoint, params)
    
    async def query_esa_sentinel(self, service_type: str, params: Dict) -> Dict:
        """Unified ESA Sentinel Hub query"""
        endpoint = f"{self.endpoints['esa_sentinel_hub']}{service_type}"
        return await self._make_request('esa_sentinel_hub', endpoint, params)
    
    async def query_sentinel_1(self, bbox: List, time_range: Tuple, params: Dict = None) -> Dict:
        """Unified Sentinel-1 InSAR data query"""
        if params is None:
            params = {}
        
        params.update({
            'bbox': bbox,
            'time_range': time_range,
            'productType': 'SLC',
            'sensorMode': 'IW',
            'orbitDirection': 'ASCENDING'
        })
        
        return await self.query_copernicus_dataspace('Products', params)
    
    async def query_sentinel_2(self, bbox: List, time_range: Tuple, params: Dict = None) -> Dict:
        """Unified Sentinel-2 optical data query"""
        if params is None:
            params = {}
        
        params.update({
            'bbox': bbox,
            'time_range': time_range,
            'productType': 'L2A',
            'cloudCoverage': '[0,20]'
        })
        
        return await self.query_copernicus_dataspace('Products', params)
    
    async def validate_usgs_catalog(self, event_data: Dict) -> Dict:
        """Unified USGS catalog validation"""
        params = {
            'minmagnitude': event_data.get('magnitude', 0) - 0.5,
            'maxmagnitude': event_data.get('magnitude', 10) + 0.5,
            'minlatitude': event_data.get('latitude', 0) - 0.1,
            'maxlatitude': event_data.get('latitude', 0) + 0.1,
            'minlongitude': event_data.get('longitude', 0) - 0.1,
            'maxlongitude': event_data.get('longitude', 0) + 0.1,
            'starttime': event_data.get('time', datetime.now() - timedelta(hours=1)),
            'endtime': event_data.get('time', datetime.now() + timedelta(hours=1))
        }
        
        return await self.query_usgs_earthquakes(params)
    
    async def query_emsc_earthquakes(self, params: Dict) -> Dict:
        """Query EMSC (European-Mediterranean Seismological Centre) earthquake data"""
        # EMSC doesn't have a direct API, so we'll use alternative approach or fallback
        try:
            # For now, return empty results as EMSC doesn't provide a reliable public API
            self.logger.warning("EMSC direct API not available, consider using USGS or IRIS data")
            return {'earthquakes': [], 'source': 'EMSC', 'status': 'api_unavailable'}
        except Exception as e:
            self.logger.error(f"EMSC query failed: {e}")
            return {'earthquakes': [], 'source': 'EMSC', 'error': str(e)}
    
    def clear_cache(self):
        """Clear API response cache"""
        self.cache.clear()
    
    def get_service_status(self) -> Dict:
        """Get status of all external services"""
        status = {}
        for service in self.endpoints.keys():
            rate_limiter = self.rate_limiters[service]
            status[service] = {
                'authenticated': service in self.auth_tokens,
                'requests_in_window': len(rate_limiter['requests']),
                'rate_limit': rate_limiter['limit'],
                'cached_responses': len([k for k in self.cache.keys() if k.startswith(service)])
            }
        return status

class AdvancedPerformanceMonitor:
    """Advanced performance monitoring system with database persistence, real-time analytics, and alerting"""
    
    def __init__(self, db_path: str = "performance_metrics.db", 
                 max_memory_records: int = 10000,
                 alert_thresholds: Dict[str, float] = None,
                 enable_system_monitoring: bool = True):
        self.db_path = db_path
        self.max_memory_records = max_memory_records
        self.alert_thresholds = alert_thresholds or {
            'operation_time': 10.0,  # seconds
            'memory_usage': 80.0,    # percentage
            'cpu_usage': 90.0        # percentage
        }
        self.enable_system_monitoring = enable_system_monitoring
        
        # Thread-safe data structures
        self._lock = threading.RLock()
        self.active_operations = {}
        self.operation_history = deque(maxlen=max_memory_records)
        self.performance_metrics = defaultdict(list)
        self.error_log = deque(maxlen=1000)
        self.warning_log = deque(maxlen=1000)
        self.event_log = deque(maxlen=1000)
        
        # Statistics tracking
        self.operation_stats = defaultdict(lambda: {
            'count': 0,
            'total_time': 0.0,
            'min_time': float('inf'),
            'max_time': 0.0,
            'error_count': 0,
            'success_count': 0
        })
        
        # System monitoring
        if enable_system_monitoring:
            self.system_stats = deque(maxlen=1000)
            self._start_system_monitoring()
        
        # Initialize database
        self._initialize_database()
        
        # Load historical data
        self._load_historical_stats()
        
        # Alert handlers
        self.alert_handlers = []
        
    def _initialize_database(self):
        """Initialize PostgreSQL database with TimescaleDB for performance monitoring"""
        try:
            # Try PostgreSQL first
            self._initialize_postgresql_database()
        except Exception as e:
            logging.warning(f"PostgreSQL initialization failed, using SQLite fallback: {e}")
            # Fallback to SQLite
            self.db_conn = sqlite3.connect(self.db_path, check_same_thread=False)
            self.db_conn.execute("""
                CREATE TABLE IF NOT EXISTS operations (
                    id TEXT PRIMARY KEY,
                    name TEXT NOT NULL,
                    start_time REAL NOT NULL,
                    end_time REAL,
                    duration REAL,
                    status TEXT DEFAULT 'running',
                    error_message TEXT,
                    metadata TEXT,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            self.db_conn.execute("""
                CREATE TABLE IF NOT EXISTS performance_metrics (
                    id TEXT PRIMARY KEY,
                    metric_name TEXT NOT NULL,
                    metric_value REAL NOT NULL,
                    metric_type TEXT DEFAULT 'gauge',
                    metadata TEXT,
                    timestamp REAL NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            self.db_conn.execute("""
                CREATE TABLE IF NOT EXISTS system_metrics (
                    id TEXT PRIMARY KEY,
                    cpu_percent REAL,
                    memory_percent REAL,
                    disk_usage REAL,
                    network_sent REAL,
                    network_recv REAL,
                    timestamp REAL NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            self.db_conn.execute("""
                CREATE TABLE IF NOT EXISTS alerts (
                    id TEXT PRIMARY KEY,
                    alert_type TEXT NOT NULL,
                    message TEXT NOT NULL,
                    severity TEXT DEFAULT 'warning',
                    metadata TEXT,
                    resolved BOOLEAN DEFAULT FALSE,
                    timestamp REAL NOT NULL,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            
            # Create indexes for better query performance
            self.db_conn.execute('CREATE INDEX IF NOT EXISTS idx_operations_name ON operations(name)')
            self.db_conn.execute('CREATE INDEX IF NOT EXISTS idx_operations_status ON operations(status)')
            self.db_conn.execute('CREATE INDEX IF NOT EXISTS idx_metrics_name ON performance_metrics(metric_name)')
            self.db_conn.execute('CREATE INDEX IF NOT EXISTS idx_metrics_timestamp ON performance_metrics(timestamp)')
            self.db_conn.execute('CREATE INDEX IF NOT EXISTS idx_system_timestamp ON system_metrics(timestamp)')
            
            self.db_conn.commit()
            
        except Exception as e:
            logging.error(f"Database initialization failed: {e}")
            self.db_conn = None
    
    def _initialize_postgresql_database(self):
        """Initialize PostgreSQL database with TimescaleDB for performance monitoring"""
        from .database_integration import PostgreSQLGISIntegrator, DatabaseConfig
        import psycopg2
        from psycopg2.pool import ThreadedConnectionPool
        
        # Configure PostgreSQL connection
        db_config = DatabaseConfig(
            host=os.environ.get('DB_HOST', 'localhost'),
            port=int(os.environ.get('DB_PORT', 5432)),
            database=os.environ.get('DB_NAME', 'prometheus_geo'),
            username=os.environ.get('DB_USER', 'prometheus_user'),
            password=os.environ.get('DB_PASSWORD', 'prometheus_password'),
            enable_timescaledb=True,
            max_connections=10
        )
        
        # Create connection pool
        self.db_pool = ThreadedConnectionPool(
            minconn=2,
            maxconn=10,
            host=db_config.host,
            port=db_config.port,
            database=db_config.database,
            user=db_config.username,
            password=db_config.password
        )
        
        # Initialize tables
        conn = self.db_pool.getconn()
        try:
            with conn.cursor() as cursor:
                # Enable TimescaleDB
                cursor.execute("CREATE EXTENSION IF NOT EXISTS timescaledb CASCADE;")
                
                # Create operations table
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS operations (
                        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                        name VARCHAR(255) NOT NULL,
                        start_time TIMESTAMPTZ NOT NULL,
                        end_time TIMESTAMPTZ,
                        duration DOUBLE PRECISION,
                        status VARCHAR(50) DEFAULT 'running',
                        error_message TEXT,
                        stack_trace TEXT,
                        metadata JSONB,
                        parent_operation_id UUID,
                        tags TEXT[],
                        created_at TIMESTAMPTZ DEFAULT NOW(),
                        updated_at TIMESTAMPTZ DEFAULT NOW()
                    );
                """)
                
                # Create performance metrics hypertable
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS performance_metrics (
                        time TIMESTAMPTZ NOT NULL,
                        metric_name VARCHAR(255) NOT NULL,
                        metric_value DOUBLE PRECISION NOT NULL,
                        metric_type VARCHAR(50) DEFAULT 'gauge',
                        unit VARCHAR(50),
                        operation_id UUID,
                        metadata JSONB,
                        tags TEXT[]
                    );
                """)
                
                # Convert to hypertable
                cursor.execute("""
                    SELECT create_hypertable('performance_metrics', 'time',
                        chunk_time_interval => INTERVAL '1 hour',
                        if_not_exists => TRUE);
                """)
                
                # Create system metrics hypertable
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS system_metrics (
                        time TIMESTAMPTZ NOT NULL,
                        host_name VARCHAR(255) DEFAULT 'localhost',
                        cpu_percent DOUBLE PRECISION,
                        memory_percent DOUBLE PRECISION,
                        disk_usage DOUBLE PRECISION,
                        network_sent DOUBLE PRECISION,
                        network_recv DOUBLE PRECISION,
                        metadata JSONB
                    );
                """)
                
                # Convert to hypertable
                cursor.execute("""
                    SELECT create_hypertable('system_metrics', 'time',
                        chunk_time_interval => INTERVAL '1 hour',
                        if_not_exists => TRUE);
                """)
                
                # Create alerts table
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS alerts (
                        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                        alert_type VARCHAR(100) NOT NULL,
                        message TEXT NOT NULL,
                        severity VARCHAR(20) DEFAULT 'warning',
                        metadata JSONB,
                        resolved BOOLEAN DEFAULT FALSE,
                        timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        created_at TIMESTAMPTZ DEFAULT NOW()
                    );
                """)
                
                # Create indexes
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_operations_name_time ON operations(name, start_time DESC);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_metrics_name_time ON performance_metrics(metric_name, time DESC);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_alerts_type_time ON alerts(alert_type, timestamp DESC);")
                
                conn.commit()
                
            # Store connection pool as db_conn for compatibility
            self.db_conn = self.db_pool
            self.using_postgresql = True
            logging.info("PostgreSQL database initialized for performance monitoring")
            
        finally:
            self.db_pool.putconn(conn)
            
    def _start_system_monitoring(self):
        """Start background system monitoring thread"""
        def monitor_system():
            while True:
                try:
                    cpu_percent = psutil.cpu_percent(interval=1)
                    memory = psutil.virtual_memory()
                    disk = psutil.disk_usage('/')
                    net_io = psutil.net_io_counters()
                    
                    system_data = {
                        'cpu_percent': cpu_percent,
                        'memory_percent': memory.percent,
                        'disk_usage': (disk.used / disk.total) * 100,
                        'network_sent': net_io.bytes_sent,
                        'network_recv': net_io.bytes_recv,
                        'timestamp': time.time()
                    }
                    
                    with self._lock:
                        self.system_stats.append(system_data)
                        
                    # Store in database
                    if self.db_conn:
                        try:
                            self.db_conn.execute("""
                                INSERT INTO system_metrics (id, cpu_percent, memory_percent, disk_usage, 
                                                           network_sent, network_recv, timestamp)
                                VALUES (?, ?, ?, ?, ?, ?, ?)
                            """, (str(uuid.uuid4()), cpu_percent, memory.percent, 
                                 (disk.used / disk.total) * 100, net_io.bytes_sent, 
                                 net_io.bytes_recv, time.time()))
                            self.db_conn.commit()
                        except Exception as e:
                            logging.error(f"Failed to store system metrics: {e}")
                    
                    # Check for alerts
                    self._check_system_alerts(system_data)
                    
                    time.sleep(30)  # Monitor every 30 seconds
                    
                except Exception as e:
                    logging.error(f"System monitoring error: {e}")
                    time.sleep(60)  # Wait longer on error
                    
        monitor_thread = threading.Thread(target=monitor_system, daemon=True)
        monitor_thread.start()
        
    def _check_system_alerts(self, system_data: Dict[str, Any]):
        """Check system metrics against alert thresholds"""
        alerts = []
        
        if system_data['cpu_percent'] > self.alert_thresholds.get('cpu_usage', 90):
            alerts.append({
                'type': 'high_cpu',
                'message': f"High CPU usage: {system_data['cpu_percent']:.1f}%",
                'severity': 'warning' if system_data['cpu_percent'] < 95 else 'critical'
            })
            
        if system_data['memory_percent'] > self.alert_thresholds.get('memory_usage', 80):
            alerts.append({
                'type': 'high_memory',
                'message': f"High memory usage: {system_data['memory_percent']:.1f}%",
                'severity': 'warning' if system_data['memory_percent'] < 90 else 'critical'
            })
            
        for alert in alerts:
            self._trigger_alert(alert)
            
    def _trigger_alert(self, alert: Dict[str, Any]):
        """Trigger an alert and notify handlers"""
        alert_id = str(uuid.uuid4())
        alert_record = {
            'id': alert_id,
            'timestamp': time.time(),
            **alert
        }
        
        # Store alert in database
        if self.db_conn:
            try:
                self.db_conn.execute("""
                    INSERT INTO alerts (id, alert_type, message, severity, metadata, timestamp)
                    VALUES (?, ?, ?, ?, ?, ?)
                """, (alert_id, alert['type'], alert['message'], 
                     alert['severity'], json.dumps(alert), time.time()))
                self.db_conn.commit()
            except Exception as e:
                logging.error(f"Failed to store alert: {e}")
        
        # Notify alert handlers
        for handler in self.alert_handlers:
            try:
                handler(alert_record)
            except Exception as e:
                logging.error(f"Alert handler failed: {e}")
                
    def add_alert_handler(self, handler: Callable[[Dict[str, Any]], None]):
        """Add custom alert handler function"""
        self.alert_handlers.append(handler)
        
    def record_operation(self, name: str, duration: float, status: str = 'completed', 
                        error: str = None, metadata: Dict[str, Any] = None):
        """Record a completed operation"""
        with self._lock:
            operation_id = str(uuid.uuid4())
            operation_data = {
                'id': operation_id,
                'name': name,
                'duration': duration,
                'status': status,
                'error': error,
                'metadata': metadata,
                'timestamp': time.time()
            }
            
            # Update in-memory statistics
            stats = self.operation_stats[name]
            stats['count'] += 1
            if status == 'completed':
                stats['success_count'] += 1
                stats['total_time'] += duration
                stats['min_time'] = min(stats['min_time'], duration)
                stats['max_time'] = max(stats['max_time'], duration)
            else:
                stats['error_count'] += 1
            
            self.operation_history.append(operation_data)
            
            # Store in database
            if self.db_conn:
                try:
                    self.db_conn.execute("""
                        INSERT INTO operations (id, name, start_time, end_time, duration, status, error_message, metadata)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """, (operation_id, name, time.time() - duration, time.time(), 
                         duration, status, error, json.dumps(metadata) if metadata else None))
                    self.db_conn.commit()
                except Exception as e:
                    logging.error(f"Failed to store operation: {e}")
            
            # Check for performance alerts
            if duration > self.alert_thresholds.get('operation_time', 10.0):
                self._trigger_alert({
                    'type': 'slow_operation',
                    'message': f"Slow operation '{name}': {duration:.2f}s",
                    'severity': 'warning'
                })
    
    def start_operation(self, name: str, metadata: Dict[str, Any] = None) -> str:
        """Start tracking an operation and return operation ID"""
        operation_id = str(uuid.uuid4())
        start_time = time.time()
        
        with self._lock:
            self.active_operations[operation_id] = {
                'name': name,
                'start_time': start_time,
                'metadata': metadata
            }
            
        return operation_id
        
    def end_operation(self, operation_id: str = None, name: str = None, 
                     error: str = None, metadata: Dict[str, Any] = None):
        """End tracking an operation"""
        end_time = time.time()
        
        with self._lock:
            if operation_id and operation_id in self.active_operations:
                op_data = self.active_operations.pop(operation_id)
                duration = end_time - op_data['start_time']
                status = 'error' if error else 'completed'
                
                # Merge metadata
                final_metadata = op_data.get('metadata', {})
                if metadata:
                    final_metadata.update(metadata)
                    
                self.record_operation(op_data['name'], duration, status, error, final_metadata)
                
            elif name:
                # Find most recent operation with this name
                for op_id, op_data in list(self.active_operations.items()):
                    if op_data['name'] == name:
                        duration = end_time - op_data['start_time']
                        status = 'error' if error else 'completed'
                        self.active_operations.pop(op_id)
                        
                        final_metadata = op_data.get('metadata', {})
                        if metadata:
                            final_metadata.update(metadata)
                            
                        self.record_operation(name, duration, status, error, final_metadata)
                        break
    
    @contextmanager
    def timer(self, name: str, metadata: Dict[str, Any] = None):
        """Context manager for timing operations"""
        operation_id = self.start_operation(name, metadata)
        start_time = time.time()
        try:
            yield
        except Exception as e:
            self.end_operation(operation_id, error=str(e))
            raise
        else:
            self.end_operation(operation_id)
    
    @contextmanager        
    def measure_time(self, name: str, metadata: Dict[str, Any] = None):
        """Alternative context manager name for timing operations"""
        with self.timer(name, metadata):
            yield
            
    def time_it(self, func: Callable, name: str = None, metadata: Dict[str, Any] = None):
        """Decorator for timing function execution"""
        operation_name = name or func.__name__
        
        def wrapper(*args, **kwargs):
            with self.timer(operation_name, metadata):
                return func(*args, **kwargs)
        return wrapper
    
    def log_performance_metric(self, name: str, value: float, 
                              metric_type: str = 'gauge', 
                              metadata: Dict[str, Any] = None):
        """Log a performance metric"""
        with self._lock:
            metric_data = {
                'name': name,
                'value': value,
                'type': metric_type,
                'metadata': metadata,
                'timestamp': time.time()
            }
            
            self.performance_metrics[name].append(metric_data)
            
            # Limit memory usage
            if len(self.performance_metrics[name]) > self.max_memory_records // 10:
                self.performance_metrics[name] = deque(
                    list(self.performance_metrics[name])[-self.max_memory_records // 20:],
                    maxlen=self.max_memory_records // 10
                )
            
            # Store in database
            if self.db_conn:
                try:
                    self.db_conn.execute("""
                        INSERT INTO performance_metrics (id, metric_name, metric_value, metric_type, metadata, timestamp)
                        VALUES (?, ?, ?, ?, ?, ?)
                    """, (str(uuid.uuid4()), name, value, metric_type, 
                         json.dumps(metadata) if metadata else None, time.time()))
                    self.db_conn.commit()
                except Exception as e:
                    logging.error(f"Failed to store performance metric: {e}")
    
    def log_performance(self, data: Dict[str, Any]):
        """Log multiple performance metrics"""
        for name, value in data.items():
            if isinstance(value, (int, float)):
                self.log_performance_metric(name, float(value))
    
    def record_computation(self, name: str, value: Any, metadata: Dict[str, Any] = None):
        """Record computation result for analysis"""
        if isinstance(value, (int, float)):
            self.log_performance_metric(f"computation_{name}", float(value), 'counter', metadata)
    
    def record_analysis(self, name: str, data: Any, metadata: Dict[str, Any] = None):
        """Record analysis results"""
        analysis_metadata = {'analysis_type': name}
        if metadata:
            analysis_metadata.update(metadata)
        
        # Extract numeric metrics from data
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(value, (int, float)):
                    self.log_performance_metric(f"analysis_{name}_{key}", float(value), 
                                              'gauge', analysis_metadata)
    
    def log_operation(self, name: str, duration: float):
        """Log operation completion time"""
        self.record_operation(name, duration)
    
    def log_warning(self, msg: str, metadata: Dict[str, Any] = None):
        """Log warning message"""
        warning_data = {
            'message': msg,
            'metadata': metadata,
            'timestamp': time.time()
        }
        with self._lock:
            self.warning_log.append(warning_data)
        logging.warning(msg)
    
    def log_error(self, msg: str, metadata: Dict[str, Any] = None):
        """Log error message"""
        error_data = {
            'message': msg,
            'metadata': metadata,
            'timestamp': time.time()
        }
        with self._lock:
            self.error_log.append(error_data)
        logging.error(msg)
    
    def log_event(self, event: str, metadata: Dict[str, Any] = None):
        """Log system event"""
        event_data = {
            'event': event,
            'metadata': metadata,
            'timestamp': time.time()
        }
        with self._lock:
            self.event_log.append(event_data)
        logging.info(f"Event: {event}")
    
    def get_stats(self) -> Dict[str, Any]:
        """Get comprehensive performance statistics"""
        with self._lock:
            stats = {
                'operations': dict(self.operation_stats),
                'active_operations': len(self.active_operations),
                'total_operations': len(self.operation_history),
                'total_errors': len(self.error_log),
                'total_warnings': len(self.warning_log),
                'performance_metrics': {
                    name: {
                        'count': len(metrics),
                        'latest': metrics[-1]['value'] if metrics else None,
                        'average': statistics.mean([m['value'] for m in metrics]) if metrics else None,
                        'min': min([m['value'] for m in metrics]) if metrics else None,
                        'max': max([m['value'] for m in metrics]) if metrics else None
                    }
                    for name, metrics in self.performance_metrics.items()
                }
            }
            
            # Add system statistics if available
            if self.enable_system_monitoring and self.system_stats:
                recent_system = list(self.system_stats)[-10:]  # Last 10 samples
                stats['system'] = {
                    'cpu_percent_avg': statistics.mean([s['cpu_percent'] for s in recent_system]),
                    'memory_percent_avg': statistics.mean([s['memory_percent'] for s in recent_system]),
                    'disk_usage_avg': statistics.mean([s['disk_usage'] for s in recent_system])
                }
            
            return stats
    
    def get_operation_history(self, name: str = None, limit: int = 100) -> List[Dict[str, Any]]:
        """Get operation history with optional filtering"""
        with self._lock:
            history = list(self.operation_history)
            
            if name:
                history = [op for op in history if op['name'] == name]
            
            return history[-limit:]
    
    def get_performance_trends(self, metric_name: str, 
                             time_window_hours: int = 24) -> Dict[str, Any]:
        """Get performance trends for a specific metric"""
        with self._lock:
            if metric_name not in self.performance_metrics:
                return {}
            
            cutoff_time = time.time() - (time_window_hours * 3600)
            recent_metrics = [
                m for m in self.performance_metrics[metric_name]
                if m['timestamp'] > cutoff_time
            ]
            
            if not recent_metrics:
                return {}
            
            values = [m['value'] for m in recent_metrics]
            
            return {
                'count': len(values),
                'average': statistics.mean(values),
                'min': min(values),
                'max': max(values),
                'std_dev': statistics.stdev(values) if len(values) > 1 else 0,
                'trend': 'increasing' if values[-1] > values[0] else 'decreasing' if values[-1] < values[0] else 'stable'
            }
    
    def cleanup_old_data(self, days_to_keep: int = 30):
        """Clean up old performance data"""
        cutoff_time = time.time() - (days_to_keep * 24 * 3600)
        
        if self.db_conn:
            try:
                self.db_conn.execute('DELETE FROM operations WHERE start_time < ?', (cutoff_time,))
                self.db_conn.execute('DELETE FROM performance_metrics WHERE timestamp < ?', (cutoff_time,))
                self.db_conn.execute('DELETE FROM system_metrics WHERE timestamp < ?', (cutoff_time,))
                self.db_conn.execute('DELETE FROM alerts WHERE timestamp < ? AND resolved = 1', (cutoff_time,))
                self.db_conn.commit()
            except Exception as e:
                logging.error(f"Failed to cleanup old data: {e}")
    
    def _load_historical_stats(self):
        """Load historical statistics from database"""
        if not self.db_conn:
            return
            
        try:
            # Load recent operation statistics
            cursor = self.db_conn.execute("""
                SELECT name, COUNT(*) as count, AVG(duration) as avg_duration, 
                       MIN(duration) as min_duration, MAX(duration) as max_duration,
                       SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) as success_count,
                       SUM(CASE WHEN status = 'error' THEN 1 ELSE 0 END) as error_count
                FROM operations 
                WHERE start_time > ? 
                GROUP BY name
            """, (time.time() - 86400,))  # Last 24 hours
            
            for row in cursor.fetchall():
                name, count, avg_duration, min_duration, max_duration, success_count, error_count = row
                self.operation_stats[name].update({
                    'count': count,
                    'total_time': avg_duration * count,
                    'min_time': min_duration or float('inf'),
                    'max_time': max_duration or 0.0,
                    'success_count': success_count,
                    'error_count': error_count
                })
                
        except Exception as e:
            logging.error(f"Failed to load historical stats: {e}")
    
    def export_metrics(self, filename: str, format: str = 'json', 
                      time_window_hours: int = 24):
        """Export performance metrics to file"""
        cutoff_time = time.time() - (time_window_hours * 3600)
        
        export_data = {
            'timestamp': time.time(),
            'time_window_hours': time_window_hours,
            'operations': [],
            'metrics': [],
            'system_metrics': []
        }
        
        if self.db_conn:
            try:
                # Export operations
                cursor = self.db_conn.execute(
                    'SELECT * FROM operations WHERE start_time > ? ORDER BY start_time',
                    (cutoff_time,)
                )
                export_data['operations'] = [
                    dict(zip([col[0] for col in cursor.description], row))
                    for row in cursor.fetchall()
                ]
                
                # Export performance metrics
                cursor = self.db_conn.execute(
                    'SELECT * FROM performance_metrics WHERE timestamp > ? ORDER BY timestamp',
                    (cutoff_time,)
                )
                export_data['metrics'] = [
                    dict(zip([col[0] for col in cursor.description], row))
                    for row in cursor.fetchall()
                ]
                
                # Export system metrics if available
                if self.enable_system_monitoring:
                    cursor = self.db_conn.execute(
                        'SELECT * FROM system_metrics WHERE timestamp > ? ORDER BY timestamp',
                        (cutoff_time,)
                    )
                    export_data['system_metrics'] = [
                        dict(zip([col[0] for col in cursor.description], row))
                        for row in cursor.fetchall()
                    ]
                
            except Exception as e:
                logging.error(f"Failed to export metrics: {e}")
                return False
        
        try:
            if format == 'json':
                with open(filename, 'w') as f:
                    json.dump(export_data, f, indent=2)
            elif format == 'csv':
                import csv
                # Export operations to CSV
                with open(filename.replace('.csv', '_operations.csv'), 'w', newline='') as f:
                    if export_data['operations']:
                        writer = csv.DictWriter(f, fieldnames=export_data['operations'][0].keys())
                        writer.writeheader()
                        writer.writerows(export_data['operations'])
                        
        except Exception as e:
            logging.error(f"Failed to write export file: {e}")
            return False
            
        return True
    
    def close(self):
        """Close database connection and cleanup"""
        if self.db_conn:
            self.db_conn.close()

class PerformanceMonitor(AdvancedPerformanceMonitor):
    """Alias for backward compatibility"""
    pass

# Global instance
performance_monitor = PerformanceMonitor()

class AdvancedEmbeddingSystem:
    """Advanced embedding system with multiple model support and optimizations"""
    
    def __init__(self, model_name: str = "sentence-transformers/all-MiniLM-L6-v2", device: str = 'cpu'):
        """
        Initialize advanced embedding system with fallback support
        
        Args:
            model_name: Name of the embedding model
            device: Device to run model on ('cpu' or 'cuda')
        """
        self.model_name = model_name
        self.device = device
        self.model = None
        self.tokenizer = None
        self.embedding_cache = {}
        self.cache_size_limit = 10000
        self.embedding_dim = None
        
        # Initialize the embedding model
        self._initialize_model()
        
    def _initialize_model(self):
        """Initialize the embedding model with fallbacks"""
        try:
            # Try to use sentence transformers
            from sentence_transformers import SentenceTransformer
            self.model = SentenceTransformer(self.model_name)
            self.model.to(self.device)
            self.embedding_dim = self.model.get_sentence_embedding_dimension()
            self.model_type = 'sentence_transformer'
        except ImportError:
            # Fallback to transformer models
            try:
                from transformers import AutoModel, AutoTokenizer
                self.tokenizer = AutoTokenizer.from_pretrained(self.model_name)
                self.model = AutoModel.from_pretrained(self.model_name).to(self.device)
                self.embedding_dim = self.model.config.hidden_size
                self.model_type = 'transformer'
            except:
                # Ultimate fallback to TF-IDF
                from sklearn.feature_extraction.text import TfidfVectorizer
                self.model = TfidfVectorizer(max_features=768, stop_words='english')
                self.embedding_dim = 768
                self.model_type = 'tfidf'
                self._fitted = False
    
    def encode(self, texts: Union[str, List[str]], batch_size: int = 32, 
               normalize: bool = True, show_progress: bool = False) -> np.ndarray:
        """
        Encode texts into embeddings
        
        Args:
            texts: Single text or list of texts to encode
            batch_size: Batch size for encoding
            normalize: Whether to normalize embeddings
            show_progress: Show progress bar
            
        Returns:
            Embeddings array
        """
        if isinstance(texts, str):
            texts = [texts]
        
        # Check cache
        embeddings = []
        uncached_texts = []
        uncached_indices = []
        
        for i, text in enumerate(texts):
            cache_key = hashlib.md5(text.encode()).hexdigest()
            if cache_key in self.embedding_cache:
                embeddings.append(self.embedding_cache[cache_key])
            else:
                embeddings.append(None)
                uncached_texts.append(text)
                uncached_indices.append(i)
        
        # Encode uncached texts
        if uncached_texts:
            new_embeddings = self._encode_batch(uncached_texts, batch_size, show_progress)
            
            # Add to cache and results
            for idx, emb, text in zip(uncached_indices, new_embeddings, uncached_texts):
                embeddings[idx] = emb
                
                # Cache management
                if len(self.embedding_cache) < self.cache_size_limit:
                    cache_key = hashlib.md5(text.encode()).hexdigest()
                    self.embedding_cache[cache_key] = emb
        
        embeddings = np.array(embeddings)
        
        if normalize:
            embeddings = embeddings / (np.linalg.norm(embeddings, axis=1, keepdims=True) + 1e-8)
        
        return embeddings
    
    def _encode_batch(self, texts: List[str], batch_size: int, show_progress: bool) -> np.ndarray:
        """Encode a batch of texts"""
        if self.model_type == 'sentence_transformer':
            return self.model.encode(texts, batch_size=batch_size, 
                                    show_progress_bar=show_progress, 
                                    convert_to_numpy=True)
        
        elif self.model_type == 'transformer':
            # Transformer encoding with pooling
            all_embeddings = []
            for i in range(0, len(texts), batch_size):
                batch = texts[i:i + batch_size]
                inputs = self.tokenizer(batch, padding=True, truncation=True, 
                                       return_tensors='pt', max_length=512)
                inputs = {k: v.to(self.device) for k, v in inputs.items()}
                
                with torch.no_grad():
                    outputs = self.model(**inputs)
                    # Mean pooling
                    embeddings = outputs.last_hidden_state.mean(dim=1)
                    all_embeddings.append(embeddings.cpu().numpy())
            
            return np.vstack(all_embeddings)
        
        else:  # TF-IDF
            if not self._fitted:
                self.model.fit(texts)
                self._fitted = True
            return self.model.transform(texts).toarray()
    
    def compute_similarity(self, embeddings1: np.ndarray, embeddings2: np.ndarray, 
                          metric: str = 'cosine') -> np.ndarray:
        """
        Compute similarity between embeddings
        
        Args:
            embeddings1: First set of embeddings
            embeddings2: Second set of embeddings
            metric: Similarity metric ('cosine', 'euclidean', 'dot')
            
        Returns:
            Similarity matrix
        """
        if metric == 'cosine':
            from sklearn.metrics.pairwise import cosine_similarity
            return cosine_similarity(embeddings1, embeddings2)
        elif metric == 'euclidean':
            from sklearn.metrics.pairwise import euclidean_distances
            return 1.0 / (1.0 + euclidean_distances(embeddings1, embeddings2))
        elif metric == 'dot':
            return np.dot(embeddings1, embeddings2.T)
        else:
            raise ValueError(f"Unknown metric: {metric}")
    
    def get_embedding_dim(self) -> int:
        """Get embedding dimension"""
        return self.embedding_dim


class AdvancedVectorStore:
    """Advanced vector store with multiple backend support and production features"""
    
    def __init__(self, embedding_model: AdvancedEmbeddingSystem, store_path: str,
                 backend: str = 'hybrid', enable_persistence: bool = True,
                 enable_sharding: bool = False, shard_size: int = 100000,
                 enable_compression: bool = False):
        """
        Initialize advanced vector store
        
        Args:
            embedding_model: Embedding model to use
            store_path: Path to store data
            backend: Backend type ('faiss', 'chroma', 'hybrid')
            enable_persistence: Enable persistent storage
            enable_sharding: Enable sharding for large datasets
            shard_size: Number of documents per shard
            enable_compression: Enable compression for storage
        """
        self.embedding_model = embedding_model
        self.store_path = Path(store_path)
        self.store_path.mkdir(parents=True, exist_ok=True)
        self.backend = backend
        self.enable_persistence = enable_persistence
        self.enable_sharding = enable_sharding
        self.shard_size = shard_size
        self.enable_compression = enable_compression
        
        # Storage components
        self.documents = []
        self.embeddings = []
        self.metadatas = []
        self.document_ids = []
        self.indices = {}
        self.shards = []
        
        # Initialize backend
        self._initialize_backend()
        
        # Load existing data if available
        if enable_persistence:
            self._load_from_disk()
    
    def _initialize_backend(self):
        """Initialize the vector store backend"""
        if self.backend in ['faiss', 'hybrid']:
            self._initialize_faiss()
        
        if self.backend in ['chroma', 'hybrid']:
            self._initialize_chroma()
        
        # Initialize metadata database with PostgreSQL or fallback to SQLite
        try:
            self._initialize_postgresql_metadata_db()
        except Exception as e:
            logging.warning(f"PostgreSQL metadata DB failed, using SQLite: {e}")
            self.metadata_db = sqlite3.connect(
                self.store_path / "metadata.db",
                check_same_thread=False
            )
            self._create_metadata_tables()
    
    def _initialize_faiss(self):
        """Initialize FAISS backend"""
        try:
            import faiss
            
            embedding_dim = self.embedding_model.get_embedding_dim()
            
            # Create FAISS index with optimizations
            if self.backend == 'hybrid':
                # Use IVF index for large scale
                nlist = 100  # Number of clusters
                self.faiss_index = faiss.IndexIVFFlat(
                    faiss.IndexFlatL2(embedding_dim), 
                    embedding_dim, 
                    nlist
                )
            else:
                # Use flat index for smaller datasets
                self.faiss_index = faiss.IndexFlatL2(embedding_dim)
            
            self.faiss_available = True
            
        except ImportError:
            # Fallback to numpy-based similarity search
            self.faiss_index = None
            self.faiss_available = False
    
    def _initialize_chroma(self):
        """Initialize ChromaDB backend"""
        try:
            import chromadb
            from chromadb.config import Settings
            
            self.chroma_client = chromadb.PersistentClient(
                path=str(self.store_path / "chroma"),
                settings=Settings(
                    anonymized_telemetry=False,
                    allow_reset=True
                )
            )
            
            self.chroma_collection = self.chroma_client.get_or_create_collection(
                name="geological_knowledge",
                metadata={"hnsw:space": "cosine"}
            )
            
            self.chroma_available = True
            
        except ImportError:
            self.chroma_client = None
            self.chroma_collection = None
            self.chroma_available = False
    
    def _initialize_postgresql_metadata_db(self):
        """Initialize PostgreSQL metadata database for vector store"""
        from .database_integration import PostgreSQLGISIntegrator, DatabaseConfig
        import psycopg2
        from psycopg2.pool import ThreadedConnectionPool
        
        # Configure PostgreSQL connection
        db_config = DatabaseConfig(
            host=os.environ.get('DB_HOST', 'localhost'),
            port=int(os.environ.get('DB_PORT', 5432)),
            database=os.environ.get('DB_NAME', 'prometheus_geo'),
            username=os.environ.get('DB_USER', 'prometheus_user'),
            password=os.environ.get('DB_PASSWORD', 'prometheus_password'),
            enable_postgis=True,
            max_connections=5
        )
        
        # Create connection pool
        self.metadata_pool = ThreadedConnectionPool(
            minconn=1,
            maxconn=5,
            host=db_config.host,
            port=db_config.port,
            database=db_config.database,
            user=db_config.username,
            password=db_config.password
        )
        
        # Initialize tables
        conn = self.metadata_pool.getconn()
        try:
            with conn.cursor() as cursor:
                # Enable required extensions
                cursor.execute("CREATE EXTENSION IF NOT EXISTS vector;")
                cursor.execute("CREATE EXTENSION IF NOT EXISTS btree_gin;")
                
                # Create documents table
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS documents (
                        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                        collection VARCHAR(255) NOT NULL,
                        content TEXT NOT NULL,
                        embedding vector(1536),
                        metadata JSONB,
                        source VARCHAR(500),
                        chunk_index INT,
                        total_chunks INT,
                        created_at TIMESTAMPTZ DEFAULT NOW(),
                        updated_at TIMESTAMPTZ DEFAULT NOW()
                    );
                """)
                
                # Create embeddings table
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS embeddings (
                        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                        document_id UUID REFERENCES documents(id) ON DELETE CASCADE,
                        embedding vector(1536) NOT NULL,
                        model VARCHAR(100),
                        dimension INT,
                        metadata JSONB,
                        created_at TIMESTAMPTZ DEFAULT NOW()
                    );
                """)
                
                # Create collections table
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS collections (
                        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
                        name VARCHAR(255) UNIQUE NOT NULL,
                        dimension INT DEFAULT 1536,
                        distance_metric VARCHAR(50) DEFAULT 'cosine',
                        metadata JSONB,
                        created_at TIMESTAMPTZ DEFAULT NOW(),
                        updated_at TIMESTAMPTZ DEFAULT NOW()
                    );
                """)
                
                # Create indexes for performance
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_documents_collection ON documents(collection);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_documents_metadata ON documents USING GIN(metadata);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_documents_embedding ON documents USING ivfflat(embedding vector_cosine_ops) WITH (lists = 100);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_embeddings_document ON embeddings(document_id);")
                cursor.execute("CREATE INDEX IF NOT EXISTS idx_embeddings_vector ON embeddings USING ivfflat(embedding vector_cosine_ops) WITH (lists = 100);")
                
                conn.commit()
                
            # Store connection pool as metadata_db for compatibility
            self.metadata_db = self.metadata_pool
            self.using_postgresql_metadata = True
            logging.info("PostgreSQL metadata database initialized for vector store")
            
        finally:
            self.metadata_pool.putconn(conn)
    
    def _create_metadata_tables(self):
        """Create metadata tables in SQLite"""
        cursor = self.metadata_db.cursor()
        
        # Documents table
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS documents (
                id TEXT PRIMARY KEY,
                content TEXT NOT NULL,
                metadata TEXT,
                embedding_id INTEGER,
                shard_id INTEGER,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        
        # Indices table
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS indices (
                name TEXT PRIMARY KEY,
                filter TEXT,
                document_ids TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        
        # Clusters table
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS clusters (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                centroid TEXT,
                document_ids TEXT,
                metadata TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)
        
        self.metadata_db.commit()
    
    async def add_documents_batch(self, documents: List[str], metadatas: List[Dict] = None,
                                  batch_size: int = 1000, enable_deduplication: bool = True,
                                  compute_clusters: bool = False) -> List[str]:
        """
        Add documents in batch with advanced features
        
        Args:
            documents: List of documents to add
            metadatas: List of metadata dicts
            batch_size: Batch size for processing
            enable_deduplication: Enable deduplication
            compute_clusters: Compute document clusters
            
        Returns:
            List of document IDs
        """
        if metadatas is None:
            metadatas = [{}] * len(documents)
        
        document_ids = []
        
        for i in range(0, len(documents), batch_size):
            batch_docs = documents[i:i + batch_size]
            batch_meta = metadatas[i:i + batch_size]
            
            # Deduplication
            if enable_deduplication:
                batch_docs, batch_meta = self._deduplicate(batch_docs, batch_meta)
            
            if not batch_docs:
                continue
            
            # Generate embeddings
            embeddings = self.embedding_model.encode(batch_docs, show_progress=True)
            
            # Generate IDs
            batch_ids = [str(uuid.uuid4()) for _ in batch_docs]
            
            # Store in backends
            if self.faiss_available and self.faiss_index is not None:
                if hasattr(self.faiss_index, 'train'):
                    # Train IVF index if needed
                    if not self.faiss_index.is_trained:
                        self.faiss_index.train(embeddings.astype('float32'))
                self.faiss_index.add(embeddings.astype('float32'))
            
            if self.chroma_available and self.chroma_collection is not None:
                self.chroma_collection.add(
                    embeddings=embeddings.tolist(),
                    documents=batch_docs,
                    metadatas=batch_meta,
                    ids=batch_ids
                )
            
            # Store in local arrays
            self.documents.extend(batch_docs)
            self.embeddings.extend(embeddings)
            self.metadatas.extend(batch_meta)
            self.document_ids.extend(batch_ids)
            
            # Store in metadata database
            cursor = self.metadata_db.cursor()
            for doc_id, doc, meta in zip(batch_ids, batch_docs, batch_meta):
                cursor.execute("""
                    INSERT OR REPLACE INTO documents (id, content, metadata)
                    VALUES (?, ?, ?)
                """, (doc_id, doc, json.dumps(meta)))
            
            self.metadata_db.commit()
            
            document_ids.extend(batch_ids)
        
        # Compute clusters if requested
        if compute_clusters and len(self.embeddings) > 10:
            await self._compute_clusters()
        
        # Save to disk if persistence enabled
        if self.enable_persistence:
            self._save_to_disk()
        
        return document_ids
    
    def _deduplicate(self, documents: List[str], metadatas: List[Dict]) -> Tuple[List[str], List[Dict]]:
        """Remove duplicate documents"""
        seen_hashes = set()
        unique_docs = []
        unique_meta = []
        
        # Check existing documents
        cursor = self.metadata_db.cursor()
        for doc, meta in zip(documents, metadatas):
            doc_hash = hashlib.md5(doc.encode()).hexdigest()
            
            # Check if already exists
            cursor.execute("SELECT id FROM documents WHERE content = ?", (doc,))
            if not cursor.fetchone() and doc_hash not in seen_hashes:
                unique_docs.append(doc)
                unique_meta.append(meta)
                seen_hashes.add(doc_hash)
        
        return unique_docs, unique_meta
    
    async def _compute_clusters(self, n_clusters: int = None):
        """Compute document clusters using k-means"""
        if not self.embeddings:
            return
        
        embeddings_array = np.array(self.embeddings)
        
        if n_clusters is None:
            # Automatically determine number of clusters
            n_clusters = min(int(np.sqrt(len(self.embeddings) / 2)), 20)
        
        if n_clusters < 2:
            return
        
        # Perform k-means clustering
        from sklearn.cluster import KMeans
        
        kmeans = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
        cluster_labels = kmeans.fit_predict(embeddings_array)
        
        # Store clusters in database
        cursor = self.metadata_db.cursor()
        
        for cluster_id in range(n_clusters):
            cluster_mask = cluster_labels == cluster_id
            cluster_doc_ids = [self.document_ids[i] for i, mask in enumerate(cluster_mask) if mask]
            
            if cluster_doc_ids:
                centroid = kmeans.cluster_centers_[cluster_id].tolist()
                
                cursor.execute("""
                    INSERT INTO clusters (centroid, document_ids)
                    VALUES (?, ?)
                """, (json.dumps(centroid), json.dumps(cluster_doc_ids)))
        
        self.metadata_db.commit()
    
    async def create_index(self, index_name: str, filter: Dict = None):
        """
        Create a specialized index for filtered searches
        
        Args:
            index_name: Name of the index
            filter: Filter criteria for documents
        """
        cursor = self.metadata_db.cursor()
        
        # Find matching documents
        matching_ids = []
        for doc_id, meta in zip(self.document_ids, self.metadatas):
            if self._matches_filter(meta, filter):
                matching_ids.append(doc_id)
        
        # Store index
        cursor.execute("""
            INSERT OR REPLACE INTO indices (name, filter, document_ids)
            VALUES (?, ?, ?)
        """, (index_name, json.dumps(filter), json.dumps(matching_ids)))
        
        self.metadata_db.commit()
        
        self.indices[index_name] = {
            'filter': filter,
            'document_ids': matching_ids
        }
    
    def _matches_filter(self, metadata: Dict, filter: Dict) -> bool:
        """Check if metadata matches filter"""
        if not filter:
            return True
        
        for key, value in filter.items():
            if key not in metadata:
                return False
            if metadata[key] != value:
                return False
        
        return True
    
    def search(self, query: str, k: int = 10, filter: Dict = None, 
              index_name: str = None) -> List[Dict]:
        """
        Search for similar documents
        
        Args:
            query: Query text
            k: Number of results
            filter: Filter criteria
            index_name: Name of index to use
            
        Returns:
            List of search results with documents and scores
        """
        # Encode query
        query_embedding = self.embedding_model.encode(query)
        
        # Get candidate document IDs
        if index_name and index_name in self.indices:
            candidate_ids = set(self.indices[index_name]['document_ids'])
        elif filter:
            candidate_ids = set()
            for doc_id, meta in zip(self.document_ids, self.metadatas):
                if self._matches_filter(meta, filter):
                    candidate_ids.add(doc_id)
        else:
            candidate_ids = set(self.document_ids)
        
        if not candidate_ids:
            return []
        
        # Search using available backends
        results = []
        
        if self.faiss_available and self.faiss_index is not None and self.faiss_index.ntotal > 0:
            # FAISS search
            distances, indices = self.faiss_index.search(
                query_embedding.reshape(1, -1).astype('float32'), 
                min(k * 2, self.faiss_index.ntotal)
            )
            
            for dist, idx in zip(distances[0], indices[0]):
                if idx < len(self.document_ids) and self.document_ids[idx] in candidate_ids:
                    results.append({
                        'id': self.document_ids[idx],
                        'document': self.documents[idx],
                        'metadata': self.metadatas[idx],
                        'score': float(1.0 / (1.0 + dist))
                    })
        
        elif self.chroma_available and self.chroma_collection is not None:
            # ChromaDB search
            chroma_results = self.chroma_collection.query(
                query_embeddings=[query_embedding.tolist()],
                n_results=k * 2,
                where=filter if filter else None
            )
            
            if chroma_results['ids'][0]:
                for i, doc_id in enumerate(chroma_results['ids'][0]):
                    if doc_id in candidate_ids:
                        results.append({
                            'id': doc_id,
                            'document': chroma_results['documents'][0][i],
                            'metadata': chroma_results['metadatas'][0][i] if chroma_results['metadatas'] else {},
                            'score': 1.0 - chroma_results['distances'][0][i] if chroma_results['distances'] else 1.0
                        })
        
        else:
            # Fallback to numpy similarity search
            if self.embeddings:
                embeddings_array = np.array(self.embeddings)
                similarities = self.embedding_model.compute_similarity(
                    query_embedding.reshape(1, -1), 
                    embeddings_array
                )[0]
                
                # Get top k indices
                top_indices = np.argsort(similarities)[::-1]
                
                for idx in top_indices[:k * 2]:
                    if self.document_ids[idx] in candidate_ids:
                        results.append({
                            'id': self.document_ids[idx],
                            'document': self.documents[idx],
                            'metadata': self.metadatas[idx],
                            'score': float(similarities[idx])
                        })
        
        # Sort by score and return top k
        results.sort(key=lambda x: x['score'], reverse=True)
        return results[:k]
    
    def get_collection_size(self) -> int:
        """Get total number of documents in store"""
        return len(self.document_ids)
    
    def _save_to_disk(self):
        """Save vector store to disk"""
        if not self.enable_persistence:
            return
        
        # Save FAISS index
        if self.faiss_available and self.faiss_index is not None:
            import faiss
            faiss.write_index(self.faiss_index, str(self.store_path / "faiss.index"))
        
        # Save embeddings and metadata
        if self.embeddings:
            embeddings_array = np.array(self.embeddings)
            if self.enable_compression:
                np.savez_compressed(
                    self.store_path / "embeddings.npz",
                    embeddings=embeddings_array,
                    document_ids=self.document_ids
                )
            else:
                np.save(self.store_path / "embeddings.npy", embeddings_array)
                
            # Save documents
            with open(self.store_path / "documents.json", 'w') as f:
                json.dump({
                    'documents': self.documents,
                    'metadatas': self.metadatas,
                    'document_ids': self.document_ids
                }, f)
    
    def _load_from_disk(self):
        """Load vector store from disk"""
        if not self.enable_persistence:
            return
        
        # Load FAISS index
        if self.faiss_available:
            faiss_path = self.store_path / "faiss.index"
            if faiss_path.exists():
                import faiss
                self.faiss_index = faiss.read_index(str(faiss_path))
        
        # Load embeddings
        if (self.store_path / "embeddings.npz").exists():
            data = np.load(self.store_path / "embeddings.npz")
            self.embeddings = data['embeddings'].tolist()
            self.document_ids = data['document_ids'].tolist()
        elif (self.store_path / "embeddings.npy").exists():
            self.embeddings = np.load(self.store_path / "embeddings.npy").tolist()
        
        # Load documents
        docs_path = self.store_path / "documents.json"
        if docs_path.exists():
            with open(docs_path, 'r') as f:
                data = json.load(f)
                self.documents = data.get('documents', [])
                self.metadatas = data.get('metadatas', [])
                if 'document_ids' in data:
                    self.document_ids = data['document_ids']


class AdvancedGeologicalEmbeddingModel:
    """Advanced geological embedding model with domain-specific semantic understanding"""
    
    def __init__(self, model_name: str):
        import logging
        from pathlib import Path
        
        self.logger = logging.getLogger(__name__)
        self.model_name = model_name
        self.embedding_dim = 768  # Higher dimensional embeddings
        
        # Initialize domain-specific embedding components
        self._initialize_geological_vocabulary()
        self._initialize_multi_level_embeddings()
        self._initialize_semantic_attention()
        self._initialize_domain_adapters()
        
        # Load pre-trained geological knowledge if available
        self._load_geological_knowledge_base()
        
    def _initialize_geological_vocabulary(self):
        """Initialize comprehensive geological vocabulary and term relationships"""
        self.geological_vocab = {
            'igneous_terms': {
                'intrusive': ['pluton', 'batholith', 'dike', 'sill', 'laccolith', 'stock'],
                'extrusive': ['lava', 'pyroclastic', 'tuff', 'obsidian', 'basalt', 'andesite'],
                'composition': ['felsic', 'mafic', 'ultramafic', 'intermediate', 'alkaline'],
                'texture': ['phaneritic', 'aphanitic', 'porphyritic', 'vesicular', 'glassy']
            },
            'metamorphic_terms': {
                'grade': ['low', 'medium', 'high', 'contact', 'regional', 'dynamic'],
                'textures': ['foliated', 'non_foliated', 'schistose', 'gneissic', 'mylonitic'],
                'facies': ['greenschist', 'amphibolite', 'granulite', 'blueschist', 'eclogite'],
                'processes': ['recrystallization', 'metamorphism', 'metasomatism', 'migmatization']
            },
            'structural_terms': {
                'folds': ['anticline', 'syncline', 'monocline', 'chevron', 'isoclinal'],
                'faults': ['normal', 'reverse', 'thrust', 'strike_slip', 'oblique'],
                'joints': ['tension', 'shear', 'cooling', 'unloading', 'tectonic'],
                'fabric': ['foliation', 'lineation', 'cleavage', 'schistosity', 'gneissosity']
            },
            'geophysical_terms': {
                'seismic': ['p_wave', 's_wave', 'surface_wave', 'velocity', 'attenuation'],
                'gravity': ['anomaly', 'bouger', 'isostasy', 'density', 'geoid'],
                'magnetic': ['declination', 'inclination', 'intensity', 'susceptibility', 'remanence'],
                'electrical': ['resistivity', 'conductivity', 'induced_polarization', 'self_potential']
            }
        }
        
        # Create term relationship matrices
        self._create_term_relationships()
        
    def _create_term_relationships(self):
        """Create semantic relationship matrices between geological terms"""
        all_terms = []
        term_categories = {}
        
        # Flatten vocabulary and track categories
        for category, subcategories in self.geological_vocab.items():
            for subcat, terms in subcategories.items():
                for term in terms:
                    all_terms.append(term)
                    term_categories[term] = (category, subcat)
        
        self.all_geological_terms = list(set(all_terms))
        self.term_to_idx = {term: i for i, term in enumerate(self.all_geological_terms)}
        self.term_categories = term_categories
        
        # Create relationship matrix based on semantic similarity
        n_terms = len(self.all_geological_terms)
        self.term_relationship_matrix = np.zeros((n_terms, n_terms))
        
        for i, term1 in enumerate(self.all_geological_terms):
            for j, term2 in enumerate(self.all_geological_terms):
                if i != j:
                    similarity = self._compute_geological_term_similarity(term1, term2)
                    self.term_relationship_matrix[i, j] = similarity
                else:
                    self.term_relationship_matrix[i, j] = 1.0
        
    def _compute_geological_term_similarity(self, term1: str, term2: str) -> float:
        """Compute semantic similarity between geological terms"""
        if term1 == term2:
            return 1.0
        
        cat1 = self.term_categories.get(term1, ('unknown', 'unknown'))
        cat2 = self.term_categories.get(term2, ('unknown', 'unknown'))
        
        # Same subcategory = high similarity
        if cat1 == cat2:
            return 0.8
        # Same main category = medium similarity
        elif cat1[0] == cat2[0]:
            return 0.5
        # Different categories but related processes
        elif self._are_related_processes(cat1[0], cat2[0]):
            return 0.3
        else:
            return 0.1
            
    def _are_related_processes(self, cat1: str, cat2: str) -> bool:
        """Check if two geological process categories are related"""
        related_pairs = [
            ('igneous_terms', 'metamorphic_terms'),  # Igneous-metamorphic relationships
            ('structural_terms', 'metamorphic_terms'),  # Structural-metamorphic relationships
            ('geophysical_terms', 'structural_terms'),  # Geophysical-structural relationships
            ('igneous_terms', 'structural_terms')  # Igneous-structural relationships
        ]
        
        return (cat1, cat2) in related_pairs or (cat2, cat1) in related_pairs
    
    def _initialize_multi_level_embeddings(self):
        """Initialize multi-level embedding architecture"""
        # Character-level embeddings for handling technical terms
        self.char_embedding_dim = 64
        self.char_vocab = list(set(''.join(self.all_geological_terms)))
        self.char_to_idx = {char: i for i, char in enumerate(self.char_vocab)}
        
        # Word-level embeddings
        self.word_embedding_dim = 256
        
        # Sentence-level embeddings
        self.sentence_embedding_dim = 384
        
        # Document-level embeddings
        self.document_embedding_dim = 768
        
        # Initialize embedding matrices
        self._initialize_embedding_matrices()
        
    def _initialize_embedding_matrices(self):
        """Initialize all embedding matrices with geological domain knowledge"""
        # Character embeddings
        self.char_embeddings = np.random.randn(
            len(self.char_vocab), self.char_embedding_dim
        ) * 0.1
        
        # Word embeddings with geological initialization
        self.word_embeddings = {}
        for term in self.all_geological_terms:
            # Initialize with domain-specific patterns
            embedding = self._create_domain_specific_embedding(term)
            self.word_embeddings[term] = embedding
        
        # Positional embeddings for sequence modeling
        self.max_sequence_length = 512
        self.positional_embeddings = self._create_positional_embeddings(
            self.max_sequence_length, self.word_embedding_dim
        )
        
    def _create_domain_specific_embedding(self, term: str) -> np.ndarray:
        """Create domain-specific embedding for geological term"""
        base_embedding = np.random.randn(self.word_embedding_dim) * 0.1
        
        # Add domain-specific biases based on term category
        if term in self.term_categories:
            category, subcategory = self.term_categories[term]
            
            # Category-specific initialization
            if category == 'igneous_terms':
                base_embedding[0:64] += 0.5  # Boost igneous-specific dimensions
            elif category == 'metamorphic_terms':
                base_embedding[64:128] += 0.5  # Boost metamorphic-specific dimensions
            elif category == 'structural_terms':
                base_embedding[128:192] += 0.5  # Boost structural-specific dimensions
            elif category == 'geophysical_terms':
                base_embedding[192:256] += 0.5  # Boost geophysical-specific dimensions
        
        return base_embedding
    
    def _create_positional_embeddings(self, max_length: int, dim: int) -> np.ndarray:
        """Create sinusoidal positional embeddings"""
        pe = np.zeros((max_length, dim))
        position = np.arange(0, max_length).reshape(-1, 1)
        div_term = np.exp(np.arange(0, dim, 2) * -(np.log(10000.0) / dim))
        
        pe[:, 0::2] = np.sin(position * div_term)
        pe[:, 1::2] = np.cos(position * div_term)
        
        return pe
    
    def _initialize_semantic_attention(self):
        """Initialize multi-head attention for semantic processing"""
        self.attention_heads = 12
        self.attention_dim = self.embedding_dim // self.attention_heads
        
        # Query, Key, Value projection matrices
        self.query_projection = np.random.randn(
            self.embedding_dim, self.embedding_dim
        ) * np.sqrt(2.0 / self.embedding_dim)
        
        self.key_projection = np.random.randn(
            self.embedding_dim, self.embedding_dim
        ) * np.sqrt(2.0 / self.embedding_dim)
        
        self.value_projection = np.random.randn(
            self.embedding_dim, self.embedding_dim
        ) * np.sqrt(2.0 / self.embedding_dim)
        
        # Output projection
        self.output_projection = np.random.randn(
            self.embedding_dim, self.embedding_dim
        ) * np.sqrt(2.0 / self.embedding_dim)
        
    def _initialize_domain_adapters(self):
        """Initialize domain-specific adapter networks"""
        self.domain_adapters = {}
        
        # Different adapters for different geological domains
        domains = ['petrology', 'structural_geology', 'geophysics', 'stratigraphy', 'tectonics']
        
        for domain in domains:
            adapter = {
                'down_project': np.random.randn(self.embedding_dim, 128) * 0.1,
                'up_project': np.random.randn(128, self.embedding_dim) * 0.1,
                'bias_down': np.zeros(128),
                'bias_up': np.zeros(self.embedding_dim)
            }
            self.domain_adapters[domain] = adapter
    
    def _load_geological_knowledge_base(self):
        """Load pre-trained geological knowledge base if available"""
        try:
            # In practice, this would load from external geological databases
            # For now, create synthetic knowledge base
            self.geological_knowledge = {
                'mineral_properties': self._create_mineral_knowledge(),
                'rock_relationships': self._create_rock_relationships(),
                'process_signatures': self._create_process_signatures(),
                'spatial_patterns': self._create_spatial_patterns()
            }
            
        except Exception as e:
            self.logger.warning(f"Could not load geological knowledge base: {e}")
            self.geological_knowledge = {}
    
    def _create_mineral_knowledge(self) -> Dict[str, Any]:
        """Create mineral property knowledge base"""
        return {
            'quartz': {'hardness': 7, 'density': 2.65, 'crystal_system': 'hexagonal'},
            'feldspar': {'hardness': 6, 'density': 2.56, 'crystal_system': 'triclinic'},
            'mica': {'hardness': 2, 'density': 2.8, 'crystal_system': 'monoclinic'},
            'olivine': {'hardness': 6.5, 'density': 3.3, 'crystal_system': 'orthorhombic'},
            'pyroxene': {'hardness': 6, 'density': 3.4, 'crystal_system': 'monoclinic'}
        }
    
    def _create_rock_relationships(self) -> Dict[str, List[str]]:
        """Create rock type relationships"""
        return {
            'granite': ['feldspar', 'quartz', 'mica'],
            'basalt': ['pyroxene', 'olivine', 'plagioclase'],
            'gneiss': ['feldspar', 'quartz', 'mica'],
            'schist': ['mica', 'quartz', 'garnet'],
            'sandstone': ['quartz', 'feldspar', 'rock_fragments']
        }
    
    def _create_process_signatures(self) -> Dict[str, Dict[str, float]]:
        """Create geological process signatures"""
        return {
            'metamorphism': {'temperature_factor': 0.8, 'pressure_factor': 0.9, 'time_factor': 0.7},
            'weathering': {'temperature_factor': 0.3, 'water_factor': 0.9, 'time_factor': 0.8},
            'magmatism': {'temperature_factor': 0.95, 'pressure_factor': 0.6, 'composition_factor': 0.85},
            'deformation': {'stress_factor': 0.9, 'strain_rate_factor': 0.7, 'temperature_factor': 0.5}
        }
    
    def _create_spatial_patterns(self) -> Dict[str, Any]:
        """Create spatial pattern knowledge"""
        return {
            'fault_systems': {'strike_length_km': [1, 1000], 'displacement_m': [0.1, 10000]},
            'intrusion_sizes': {'diameter_km': [0.1, 100], 'volume_km3': [0.001, 10000]},
            'fold_wavelengths': {'wavelength_km': [0.01, 50], 'amplitude_km': [0.001, 10]}
        }
    
    def encode(self, texts: Union[str, List[str]], **kwargs) -> np.ndarray:
        """Advanced geological text encoding with multi-level processing"""
        if isinstance(texts, str):
            texts = [texts]
        
        embeddings = []
        
        for text in texts:
            # Multi-level encoding
            embedding = self._encode_single_text(text, **kwargs)
            embeddings.append(embedding)
        
        return np.array(embeddings)
    
    def _encode_single_text(self, text: str, domain: str = None, **kwargs) -> np.ndarray:
        """Encode single text with geological domain awareness"""
        # Tokenize and preprocess
        tokens = self._geological_tokenize(text)
        
        # Character-level encoding
        char_embeddings = self._encode_characters(text)
        
        # Word-level encoding with geological awareness
        word_embeddings = self._encode_words(tokens)
        
        # Apply positional embeddings
        word_embeddings = self._add_positional_embeddings(word_embeddings)
        
        # Apply multi-head attention
        attended_embeddings = self._apply_attention(word_embeddings)
        
        # Apply domain-specific adapter if specified
        if domain and domain in self.domain_adapters:
            attended_embeddings = self._apply_domain_adapter(attended_embeddings, domain)
        
        # Aggregate to final embedding
        final_embedding = self._aggregate_embeddings(
            char_embeddings, word_embeddings, attended_embeddings
        )
        
        return final_embedding
    
    def _geological_tokenize(self, text: str) -> List[str]:
        """Geological domain-aware tokenization"""
        import re
        
        # Handle geological compound terms
        text = text.lower()
        
        # Preserve important geological terms
        protected_terms = []
        for term in self.all_geological_terms:
            if term in text:
                protected_terms.append(term)
        
        # Simple tokenization preserving geological terms
        tokens = re.findall(r'\w+', text)
        
        # Merge tokens that form geological terms
        merged_tokens = []
        i = 0
        while i < len(tokens):
            # Check for multi-word geological terms
            found_term = False
            for term in protected_terms:
                term_words = term.split('_')
                if (i + len(term_words) <= len(tokens) and 
                    tokens[i:i+len(term_words)] == term_words):
                    merged_tokens.append(term)
                    i += len(term_words)
                    found_term = True
                    break
            
            if not found_term:
                merged_tokens.append(tokens[i])
                i += 1
        
        return merged_tokens
    
    def _encode_characters(self, text: str) -> np.ndarray:
        """Character-level encoding for handling technical terms"""
        char_ids = [self.char_to_idx.get(c, 0) for c in text[:100]]  # Truncate to 100 chars
        char_embeddings = self.char_embeddings[char_ids]
        
        # Apply convolutional filters for character patterns
        char_embedding = np.mean(char_embeddings, axis=0)
        
        return char_embedding
    
    def _encode_words(self, tokens: List[str]) -> np.ndarray:
        """Word-level encoding with geological awareness"""
        embeddings = []
        
        for token in tokens[:50]:  # Limit to 50 tokens
            if token in self.word_embeddings:
                # Use pre-trained geological embedding
                embedding = self.word_embeddings[token].copy()
            else:
                # Create embedding for unknown term
                embedding = self._create_unknown_word_embedding(token)
            
            embeddings.append(embedding)
        
        # Pad or truncate to fixed length
        while len(embeddings) < 50:
            embeddings.append(np.zeros(self.word_embedding_dim))
        
        return np.array(embeddings[:50])
    
    def _create_unknown_word_embedding(self, token: str) -> np.ndarray:
        """Create embedding for unknown word using geological context"""
        # Hash-based embedding with geological domain bias
        hash_value = hash(token) % 1000000
        np.random.seed(hash_value)
        
        embedding = np.random.randn(self.word_embedding_dim) * 0.1
        
        # Add geological domain bias if token contains geological patterns
        if any(geo_term in token for geo_term in self.all_geological_terms):
            embedding += 0.2  # Boost for geological-like terms
        
        np.random.seed()  # Reset seed
        return embedding
    
    def _add_positional_embeddings(self, word_embeddings: np.ndarray) -> np.ndarray:
        """Add positional embeddings to word embeddings"""
        seq_len = word_embeddings.shape[0]
        pos_embeddings = self.positional_embeddings[:seq_len, :word_embeddings.shape[1]]
        
        return word_embeddings + pos_embeddings
    
    def _apply_attention(self, embeddings: np.ndarray) -> np.ndarray:
        """Apply multi-head attention to embeddings"""
        seq_len, embed_dim = embeddings.shape
        
        # Project to query, key, value
        queries = np.dot(embeddings, self.query_projection)
        keys = np.dot(embeddings, self.key_projection)
        values = np.dot(embeddings, self.value_projection)
        
        # Reshape for multi-head attention
        queries = queries.reshape(seq_len, self.attention_heads, self.attention_dim)
        keys = keys.reshape(seq_len, self.attention_heads, self.attention_dim)
        values = values.reshape(seq_len, self.attention_heads, self.attention_dim)
        
        # Compute attention scores
        attention_outputs = []
        for head in range(self.attention_heads):
            q = queries[:, head, :]
            k = keys[:, head, :]
            v = values[:, head, :]
            
            # Scaled dot-product attention
            scores = np.dot(q, k.T) / np.sqrt(self.attention_dim)
            attention_weights = self._softmax(scores)
            attended = np.dot(attention_weights, v)
            
            attention_outputs.append(attended)
        
        # Concatenate heads
        concatenated = np.concatenate(attention_outputs, axis=1)
        
        # Output projection
        output = np.dot(concatenated, self.output_projection)
        
        return output
    
    def _softmax(self, x: np.ndarray) -> np.ndarray:
        """Compute softmax with numerical stability"""
        exp_x = np.exp(x - np.max(x, axis=-1, keepdims=True))
        return exp_x / np.sum(exp_x, axis=-1, keepdims=True)
    
    def _apply_domain_adapter(self, embeddings: np.ndarray, domain: str) -> np.ndarray:
        """Apply domain-specific adapter to embeddings"""
        adapter = self.domain_adapters[domain]
        
        # Down-projection
        hidden = np.dot(embeddings, adapter['down_project']) + adapter['bias_down']
        hidden = np.maximum(hidden, 0)  # ReLU activation
        
        # Up-projection
        adapted = np.dot(hidden, adapter['up_project']) + adapter['bias_up']
        
        # Residual connection
        return embeddings + adapted
    
    def _aggregate_embeddings(self, char_emb: np.ndarray, word_emb: np.ndarray, 
                             attended_emb: np.ndarray) -> np.ndarray:
        """Aggregate multi-level embeddings into final representation"""
        # Aggregate word-level embeddings
        word_aggregate = np.mean(word_emb, axis=0)
        attended_aggregate = np.mean(attended_emb, axis=0)
        
        # Pad/truncate to match embedding dimensions
        char_emb_padded = np.pad(char_emb, (0, max(0, self.embedding_dim - len(char_emb))))[:self.embedding_dim]
        word_agg_padded = np.pad(word_aggregate, (0, max(0, self.embedding_dim - len(word_aggregate))))[:self.embedding_dim]
        attended_agg_padded = np.pad(attended_aggregate, (0, max(0, self.embedding_dim - len(attended_aggregate))))[:self.embedding_dim]
        
        # Weighted combination
        final_embedding = (
            0.2 * char_emb_padded +
            0.3 * word_agg_padded +
            0.5 * attended_agg_padded
        )
        
        # Apply layer normalization
        mean = np.mean(final_embedding)
        std = np.std(final_embedding) + 1e-8
        final_embedding = (final_embedding - mean) / std
        
        return final_embedding
    
    def get_embedding_dim(self) -> int:
        return self.embedding_dim


class AdvancedGeologicalVectorStore:
    """Advanced geological vector store with semantic indexing and domain-specific retrieval"""
    
    def __init__(self, store_path: str):
        self.store_path = Path(store_path)
        self.store_path.mkdir(parents=True, exist_ok=True)
        
