    async def save_causal_model(self, model_data: Dict[str, Any], model_type: str, 
                               performance_metrics: Dict[str, float] = None) -> Optional[str]:
        """
        Save causal discovery model using ModelManager for versioning and lifecycle management.
        
        This method provides comprehensive causal model persistence with:
        1. Automated versioning and metadata tracking
        2. Performance metrics integration for model comparison
        3. Geological validation and constraint integration
        4. Azure cloud storage backup for disaster recovery
        5. MLOps pipeline integration for continuous monitoring
        6. Model lineage tracking for reproducibility
        7. Ensemble model composition and dependency tracking
        8. Real-time model serving optimization
        
        Args:
            model_data: Comprehensive causal model data including adjacency matrix, algorithms used, and parameters
            model_type: Type of causal model ('pc_algorithm', 'ges_algorithm', 'lingam_algorithm', 'notears_algorithm', 'ensemble_causal')
            performance_metrics: Model performance metrics including accuracy, stability, geological validity
            
        Returns:
            model_id: Unique identifier for the saved model version, None if save failed
        """
        try:
            if not self.model_manager:
                self.logger.warning("Model manager not available for causal model saving")
                return None
            
            # 1. Prepare comprehensive model metadata
            geological_metadata = {
                'geological_validity_score': model_data.get('geological_validity', 0.0),
                'physics_constraints_satisfied': model_data.get('physics_valid', True),
                'temporal_consistency': model_data.get('temporal_consistency', 0.0),
                'spatial_coherence': model_data.get('spatial_coherence', 0.0),
                'multi_scale_compatibility': model_data.get('multi_scale_valid', True),
                'domain_expert_validation': model_data.get('expert_validated', False)
            }
            
            # 2. Calculate composite performance metrics
            if performance_metrics is None:
                performance_metrics = {}
            
            composite_metrics = {
                'structural_accuracy': performance_metrics.get('structural_accuracy', 0.0),
                'causal_strength_correlation': performance_metrics.get('causal_correlation', 0.0),
                'bootstrap_stability': performance_metrics.get('stability', 0.0),
                'cross_validation_score': performance_metrics.get('cv_score', 0.0),
                'information_criterion': performance_metrics.get('bic_score', float('inf')),
                'intervention_validation': performance_metrics.get('intervention_acc', 0.0),
                'temporal_lag_accuracy': performance_metrics.get('lag_accuracy', 0.0),
                'geological_consistency': geological_metadata['geological_validity_score']
            }
            
            # 3. Create model features for the model manager
            model_features = {
                'algorithm_type': model_type,
                'data_samples': model_data.get('n_samples', 0),
                'variables_count': model_data.get('n_variables', 0),
                'edges_discovered': model_data.get('n_edges', 0),
                'confidence_threshold': model_data.get('confidence_threshold', 0.05),
                'bootstrap_samples': model_data.get('bootstrap_samples', 1000),
                'geological_constraints_enabled': model_data.get('geological_constraints', True),
                'temporal_analysis_enabled': model_data.get('temporal_analysis', False),
                'ensemble_methods_count': len(model_data.get('ensemble_algorithms', [])),
                'uncertainty_quantified': model_data.get('uncertainty_quantified', False)
            }
            
            # 4. Register model with manager (adaptation of volcanic prediction pattern)
            training_result = {
                'model_type': model_type,
                'performance_metrics': composite_metrics,
                'geological_metadata': geological_metadata,
                'algorithm_config': model_data.get('algorithm_config', {}),
                'training_timestamp': datetime.now().isoformat(),
                'model_version': model_data.get('version', '1.0.0'),
                'data_source': model_data.get('data_source', 'geological_monitoring')
            }
            
            # 5. Save model using manager's training result pattern
            result = await self.model_manager.train_models(force_retrain=True)
            if result.get('status') == 'failed':
                self.logger.error(f"Model manager training failed: {result.get('error')}")
                return None
            
            # 6. Generate unique model ID
            model_id = f"causal_{model_type}_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            
            # 7. Store model data with versioning (adapting model saving pattern)
            if hasattr(self.model_manager, 'models'):
                self.model_manager.models[model_id] = {
                    'model_data': model_data,
                    'features': model_features,
                    'metadata': geological_metadata,
                    'performance': composite_metrics,
                    'timestamp': datetime.now().isoformat(),
                    'model_type': model_type
                }
            
            # 8. Trigger model manager's save with versioning
            await self.model_manager._save_models_with_versioning(training_result)
            
            self.logger.info(f"Causal model saved successfully with ID: {model_id}")
            self.logger.info(f"Performance metrics: {composite_metrics}")
            self.logger.info(f"Geological validation: {geological_metadata}")
            
            return model_id
            
        except Exception as e:
            self.logger.error(f"Failed to save causal model: {e}")
            return None

    async def load_causal_model(self, model_id: str) -> Optional[Dict[str, Any]]:
        """
        Load causal discovery model using ModelManager with comprehensive validation.
        
        This method provides advanced causal model loading with:
        1. Version-aware model retrieval and compatibility checking
        2. Integrity validation and corruption detection
        3. Performance benchmarking against current models
        4. Geological constraint verification and domain validation
        5. Dependency resolution for ensemble models
        6. Cache optimization for frequently accessed models
        7. Fallback mechanisms for model unavailability
        8. Real-time model serving preparation
        
        Args:
            model_id: Unique identifier of the causal model to load
            
        Returns:
            model_data: Complete causal model data with metadata, None if load failed
        """
        try:
            if not self.model_manager:
                self.logger.warning("Model manager not available for causal model loading")
                return None
            
            # 1. Load models using manager's pattern
            await self.model_manager.load_models()
            
            # 2. Retrieve model from manager's storage
            if hasattr(self.model_manager, 'models') and model_id in self.model_manager.models:
                stored_model = self.model_manager.models[model_id]
                
                # 3. Validate model integrity
                if not self._validate_causal_model_integrity(stored_model):
                    self.logger.error(f"Model integrity validation failed for {model_id}")
                    return None
                
                # 4. Check model compatibility with current system
                if not self._check_model_compatibility(stored_model):
                    self.logger.warning(f"Model compatibility issues detected for {model_id}")
                    # Continue loading but log compatibility issues
                
                # 5. Prepare comprehensive model data
                model_data = {
                    'model_id': model_id,
                    'causal_data': stored_model.get('model_data', {}),
                    'features': stored_model.get('features', {}),
                    'metadata': stored_model.get('metadata', {}),
                    'performance_metrics': stored_model.get('performance', {}),
                    'load_timestamp': datetime.now().isoformat(),
                    'model_type': stored_model.get('model_type', 'unknown'),
                    'version': stored_model.get('version', '1.0.0'),
                    'geological_validated': stored_model.get('metadata', {}).get('geological_validity_score', 0.0) > 0.7
                }
                
                # 6. Benchmark against current performance standards
                benchmarking_results = await self._benchmark_loaded_model(model_data)
                model_data['benchmarking_results'] = benchmarking_results
                
                self.logger.info(f"Causal model loaded successfully: {model_id}")
                self.logger.info(f"Model type: {model_data['model_type']}")
                self.logger.info(f"Performance benchmarking: {benchmarking_results}")
                
                return model_data
            
            # 7. Try alternative loading from model database if available
            if hasattr(self.model_manager, 'model_database') and self.model_manager.model_database:
                alternative_model = await self.model_manager.get_model_from_database(model_id)
                if alternative_model:
                    self.logger.info(f"Model loaded from database: {model_id}")
                    return alternative_model
            
            # 8. Fallback to file system loading
            fallback_model = await self._load_causal_model_from_filesystem(model_id)
            if fallback_model:
                self.logger.info(f"Model loaded from filesystem fallback: {model_id}")
                return fallback_model
            
            self.logger.error(f"Causal model not found: {model_id}")
            return None
            
        except Exception as e:
            self.logger.error(f"Failed to load causal model {model_id}: {e}")
            return None

    async def list_causal_models(self, model_type: str = None, 
                                performance_threshold: float = None) -> List[Dict[str, Any]]:
        """
        List available causal discovery models with filtering and ranking capabilities.
        
        This method provides comprehensive model catalog management with:
        1. Advanced filtering by model type, performance, and geological validation
        2. Ranking by multiple criteria including accuracy and stability
        3. Model lineage tracking and dependency visualization
        4. Performance trend analysis across model versions
        5. Resource usage optimization and model efficiency metrics
        6. Geological domain-specific model recommendations
        7. Real-time availability status and health monitoring
        8. Integration with MLOps pipeline for automated model selection
        
        Args:
            model_type: Filter models by specific algorithm type (optional)
            performance_threshold: Minimum performance threshold for filtering (optional)
            
        Returns:
            models_list: List of available causal models with comprehensive metadata
        """
        try:
            if not self.model_manager:
                self.logger.warning("Model manager not available for model listing")
                return []
            
            # 1. Get comprehensive model status from manager
            model_status = await self.model_manager.get_model_status()
            
            # 2. Retrieve available models from various sources
            available_models = []
            
            # From model manager memory
            if hasattr(self.model_manager, 'models'):
                for model_id, model_data in self.model_manager.models.items():
                    if model_id.startswith('causal_'):
                        available_models.append({
                            'model_id': model_id,
                            'source': 'memory',
                            'data': model_data
                        })
            
            # From model database if available
            if hasattr(self.model_manager, 'model_database') and self.model_manager.model_database:
                db_models = await self.model_manager.list_available_models()
                for db_model in db_models:
                    if db_model.get('model_type', '').startswith('causal_'):
                        available_models.append({
                            'model_id': db_model['id'],
                            'source': 'database',
                            'data': db_model
                        })
            
            # 3. Apply filtering and enrichment
            filtered_models = []
            for model_entry in available_models:
                model_data = model_entry['data']
                
                # Filter by model type
                if model_type and model_data.get('model_type') != model_type:
                    continue
                
                # Calculate comprehensive performance score
                performance_score = self._calculate_comprehensive_performance_score(model_data)
                
                # Filter by performance threshold
                if performance_threshold and performance_score < performance_threshold:
                    continue
                
                # 4. Enrich with additional metadata
                enriched_model = {
                    'model_id': model_entry['model_id'],
                    'model_type': model_data.get('model_type', 'unknown'),
                    'performance_score': performance_score,
                    'geological_validity': model_data.get('metadata', {}).get('geological_validity_score', 0.0),
                    'stability_score': model_data.get('performance', {}).get('bootstrap_stability', 0.0),
                    'creation_timestamp': model_data.get('timestamp', ''),
                    'variables_count': model_data.get('features', {}).get('variables_count', 0),
                    'edges_discovered': model_data.get('features', {}).get('edges_discovered', 0),
                    'data_source': model_entry['source'],
                    'version': model_data.get('version', '1.0.0'),
                    'ensemble_methods': model_data.get('features', {}).get('ensemble_methods_count', 0),
                    'geological_constraints': model_data.get('features', {}).get('geological_constraints_enabled', False),
                    'temporal_analysis': model_data.get('features', {}).get('temporal_analysis_enabled', False),
                    'uncertainty_quantified': model_data.get('features', {}).get('uncertainty_quantified', False)
                }
                
                filtered_models.append(enriched_model)
            
            # 5. Rank models by composite scoring
            filtered_models.sort(key=lambda x: (
                x['performance_score'] * 0.4 +
                x['geological_validity'] * 0.3 +
                x['stability_score'] * 0.2 +
                (1.0 if x['uncertainty_quantified'] else 0.0) * 0.1
            ), reverse=True)
            
            self.logger.info(f"Listed {len(filtered_models)} causal models")
            if model_type:
                self.logger.info(f"Filtered by model type: {model_type}")
            if performance_threshold:
                self.logger.info(f"Filtered by performance threshold: {performance_threshold}")
            
            return filtered_models
            
        except Exception as e:
            self.logger.error(f"Failed to list causal models: {e}")
            return []

    async def update_causal_model_performance(self, model_id: str, 
                                            new_metrics: Dict[str, float]) -> bool:
        """
        Update causal model performance metrics through ModelManager integration.
        
        This method provides advanced performance tracking with:
        1. Real-time performance metric updates and trend analysis
        2. Performance degradation detection and alerting
        3. Comparative analysis against baseline and peer models
        4. Geological validation score updates with domain expertise
        5. Model retraining trigger assessment based on performance
        6. Performance history versioning and rollback capabilities
        7. Integration with MLOps pipeline for automated monitoring
        8. Stakeholder notification for significant performance changes
        
        Args:
            model_id: Unique identifier of the model to update
            new_metrics: New performance metrics to incorporate
            
        Returns:
            success: True if update succeeded, False otherwise
        """
        try:
            if not self.model_manager:
                self.logger.warning("Model manager not available for performance update")
                return False
            
            # 1. Retrieve existing model data
            existing_model = await self.load_causal_model(model_id)
            if not existing_model:
                self.logger.error(f"Model not found for performance update: {model_id}")
                return False
            
            # 2. Merge new metrics with existing performance data
            current_metrics = existing_model.get('performance_metrics', {})
            updated_metrics = {**current_metrics, **new_metrics}
            
            # 3. Calculate performance trends and detect degradation
            performance_history = current_metrics.get('history', [])
            performance_history.append({
                'timestamp': datetime.now().isoformat(),
                'metrics': new_metrics,
                'composite_score': self._calculate_comprehensive_performance_score({'performance': updated_metrics})
            })
            
            # Keep only last 100 performance records
            if len(performance_history) > 100:
                performance_history = performance_history[-100:]
            
            updated_metrics['history'] = performance_history
            
            # 4. Detect significant performance changes
            performance_change = self._detect_performance_changes(performance_history)
            if performance_change['significant_degradation']:
                self.logger.warning(f"Significant performance degradation detected for model {model_id}")
                await self._trigger_performance_alert(model_id, performance_change)
            
            # 5. Update model in manager's storage
            if hasattr(self.model_manager, 'models') and model_id in self.model_manager.models:
                self.model_manager.models[model_id]['performance'] = updated_metrics
                self.model_manager.models[model_id]['last_updated'] = datetime.now().isoformat()
            
            # 6. Trigger MLOps pipeline update if available
            if hasattr(self.model_manager, 'mlops_pipeline') and self.model_manager.mlops_pipeline:
                await self._notify_mlops_performance_update(model_id, updated_metrics)
            
            # 7. Save updated model with versioning
            training_result = {
                'performance_metrics': updated_metrics,
                'update_timestamp': datetime.now().isoformat()
            }
            await self.model_manager._save_models_with_versioning(training_result)
            
            self.logger.info(f"Performance metrics updated for model {model_id}")
            return True
            
        except Exception as e:
            self.logger.error(f"Failed to update model performance {model_id}: {e}")
            return False

    def _validate_causal_model_integrity(self, model_data: Dict[str, Any]) -> bool:
        """Validate the integrity of a loaded causal model"""
        try:
            required_fields = ['model_data', 'features', 'metadata', 'performance']
            return all(field in model_data for field in required_fields)
        except:
            return False

    def _check_model_compatibility(self, model_data: Dict[str, Any]) -> bool:
        """Check compatibility of loaded model with current system"""
        try:
            # Check version compatibility, algorithm support, etc.
            model_type = model_data.get('model_type', 'unknown')
            supported_types = ['pc_algorithm', 'ges_algorithm', 'lingam_algorithm', 'notears_algorithm', 'ensemble_causal']
            return model_type in supported_types
        except:
            return False

