    async def _load_ridge_classification_model(self):
        """Load pre-trained ridge classification neural network"""
        try:
            from .model_manager import ModelManager
            model_manager = ModelManager()
            model = await model_manager.load_model('ridge_classifier_v2')
            if model is None:
                # Create default model if not found
                model = self._create_default_ridge_classifier()
            return model
        except Exception as e:
            self.logger.warning(f"Failed to load ridge classifier: {e}")
            return self._create_default_ridge_classifier()
    
    def _create_default_ridge_classifier(self):
        """Create default ridge classification model"""
        import torch.nn as nn
        
        class RidgeClassifier(nn.Module):
            def __init__(self):
                super().__init__()
                self.fc1 = nn.Linear(11, 64)
                self.fc2 = nn.Linear(64, 32)
                self.fc3 = nn.Linear(32, 1)
                self.dropout = nn.Dropout(0.2)
                self.relu = nn.ReLU()
                
            def forward(self, x):
                x = self.relu(self.fc1(x))
                x = self.dropout(x)
                x = self.relu(self.fc2(x))
                x = self.dropout(x)
                return self.fc3(x)
        
        return RidgeClassifier()
    
    def _calculate_epistemic_uncertainty(self, features):
        """Calculate epistemic uncertainty using Monte Carlo dropout"""
        try:
            n_samples = 100
            predictions = []
            
            for _ in range(n_samples):
                with torch.no_grad():
                    pred = self.ridge_classifier(features.unsqueeze(0))
                    predictions.append(torch.sigmoid(pred).item())
            
            return np.std(predictions)
        except Exception:
            return 0.1
    
    def _evaluate_bathymetric_criterion(self, ridge_data):
        """Evaluate bathymetric criterion for ridge detection"""
        depth = ridge_data['water_depth']
        gradient = ridge_data['bathymetric_gradient']
        
        # Ridge axis typically at 2000-4000m depth
        if -4000 <= depth <= -2000:
            depth_score = 1.0
        elif -5000 <= depth <= -1500:
            depth_score = 0.7
        else:
            depth_score = max(0, 1 - abs(depth + 3000) / 3000)
        
        # High gradient indicates ridge flanks
        gradient_score = min(1.0, gradient / 0.1)
        
        score = 0.7 * depth_score + 0.3 * gradient_score
        uncertainty = 0.1 if ridge_data['multibeam_resolution'] < 50 else 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_spreading_criterion(self, ridge_data):
        """Evaluate spreading rate criterion"""
        rate = ridge_data['spreading_rate_mm_yr']
        distance = ridge_data['distance_to_axis_km']
        
        if distance < 50:
            distance_factor = 1.0
        elif distance < 100:
            distance_factor = 0.7
        elif distance < 200:
            distance_factor = 0.4
        else:
            distance_factor = max(0, 1 - distance / 500)
        
        if 10 <= rate <= 200:
            rate_score = 1.0
        else:
            rate_score = 0.3
        
        score = distance_factor * rate_score
        uncertainty = 0.15 if distance < 100 else 0.25
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_magnetic_criterion(self, ridge_data):
        """Evaluate magnetic anomaly patterns"""
        anomaly = abs(ridge_data['magnetic_anomaly_nT'])
        pattern = ridge_data['magnetic_reversal_pattern']
        
        # Strong anomalies near ridges
        if anomaly > 500:
            anomaly_score = 1.0
        elif anomaly > 200:
            anomaly_score = 0.7
        else:
            anomaly_score = anomaly / 500
        
        # Symmetric reversal patterns indicate spreading
        pattern_score = 0.5 if len(pattern) > 0 else 0
        
        score = 0.6 * anomaly_score + 0.4 * pattern_score
        uncertainty = 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_thermal_criterion(self, ridge_data):
        """Evaluate thermal characteristics"""
        heat_flow = ridge_data['heat_flow_mW_m2']
        
        # High heat flow at ridges (>100 mW/m²)
        if heat_flow > 150:
            score = 1.0
        elif heat_flow > 100:
            score = 0.8
        elif heat_flow > 70:
            score = 0.5
        else:
            score = heat_flow / 150
        
        uncertainty = 0.2
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_seismic_criterion(self, ridge_data):
        """Evaluate seismic velocity structure"""
        velocity = ridge_data['seismic_velocity_km_s']
        thickness = ridge_data['crustal_thickness_km']
        
        # Thin crust and low velocities at ridges
        if thickness < 8 and velocity < 6.5:
            score = 1.0
        elif thickness < 10 and velocity < 7.0:
            score = 0.7
        else:
            score = max(0, 1 - (thickness - 7) / 10) * max(0, 1 - (velocity - 6) / 2)
        
        uncertainty = 0.15
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_hydrothermal_criterion(self, ridge_data):
        """Evaluate hydrothermal activity"""
        activity = ridge_data['hydrothermal_score']
        density = ridge_data['vent_density']
        
        score = 0.6 * activity + 0.4 * min(1.0, density / 5)
        uncertainty = 0.25
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _bayesian_model_combination(self, ml_prob, ml_unc, phys_score, phys_unc):
        """Bayesian combination of ML and physical models"""
        # Prior weights based on uncertainties
        ml_weight = 1 / (1 + ml_unc)
        phys_weight = 1 / (1 + phys_unc)
        
        # Normalize weights
        total_weight = ml_weight + phys_weight
        ml_weight /= total_weight
        phys_weight /= total_weight
        
        # Combined probability
        combined_prob = ml_weight * ml_prob + phys_weight * phys_score
        
        # Propagate uncertainty
        combined_unc = np.sqrt(
            (ml_weight * ml_unc)**2 + 
            (phys_weight * phys_unc)**2 + 
            (ml_weight * phys_weight * abs(ml_prob - phys_score))**2
        )
        
        # Confidence based on agreement and uncertainty
        agreement = 1 - abs(ml_prob - phys_score)
        confidence = agreement * (1 - combined_unc)
        
        return {
            'probability': combined_prob,
            'uncertainty': combined_unc,
            'confidence': confidence
        }
    
    def _classify_ridge_type(self, ridge_data):
        """Classify ridge type based on spreading rate and morphology"""
        rate = ridge_data['spreading_rate_mm_yr']
        
        if rate < 20:
            return 'ultraslow_spreading'
        elif rate < 50:
            return 'slow_spreading'
        elif rate < 80:
            return 'intermediate_spreading'
        elif rate < 120:
            return 'fast_spreading'
        else:
            return 'superfast_spreading'
    
    def _classify_spreading_rate(self, rate_mm_yr):
        """Classify spreading rate category"""
        if rate_mm_yr < 10:
            return 'ultra_slow'
        elif rate_mm_yr < 20:
            return 'very_slow'
        elif rate_mm_yr < 50:
            return 'slow'
        elif rate_mm_yr < 80:
            return 'intermediate'
        elif rate_mm_yr < 120:
            return 'fast'
        else:
            return 'super_fast'
    
