    def _get_data_provenance(self, results):
        """Track data sources and quality"""
        sources = []
        for i, result in enumerate(results):
            if not isinstance(result, Exception):
                sources.append({
                    'index': i,
                    'success': True,
                    'has_data': bool(result)
                })
            else:
                sources.append({
                    'index': i,
                    'success': False,
                    'error': str(result)
                })
        return sources
    
    def _assess_data_quality(self, results):
        """Assess overall data quality"""
        successful = sum(1 for r in results if not isinstance(r, Exception))
        total = len(results)
        
        if successful == total:
            return 'excellent'
        elif successful >= 0.75 * total:
            return 'good'
        elif successful >= 0.5 * total:
            return 'moderate'
        elif successful >= 0.25 * total:
            return 'poor'
        else:
            return 'very_poor'
    
