    def _create_default_rift_classifier(self):
        """Create default rift classification model"""
        import torch.nn as nn
        
        class RiftClassifier(nn.Module):
            def __init__(self):
                super().__init__()
                self.fc1 = nn.Linear(16, 128)
                self.fc2 = nn.Linear(128, 64)
                self.fc3 = nn.Linear(64, 32)
                self.fc4 = nn.Linear(32, 3)  # 3 classes: no_rift, active_rift, nascent_rift
                self.dropout = nn.Dropout(0.3)
                self.relu = nn.ReLU()
                self.bn1 = nn.BatchNorm1d(128)
                self.bn2 = nn.BatchNorm1d(64)
                
            def forward(self, x):
                x = self.relu(self.bn1(self.fc1(x)))
                x = self.dropout(x)
                x = self.relu(self.bn2(self.fc2(x)))
                x = self.dropout(x)
                x = self.relu(self.fc3(x))
                return self.fc4(x)
        
        return RiftClassifier()
    
    def _calculate_aleatoric_uncertainty(self, features):
        """Calculate aleatoric uncertainty for rift classification"""
        # Estimate based on feature variability
        feature_std = features.std().item()
        return min(0.5, feature_std * 0.3)
    
    def _evaluate_crustal_thinning(self, rift_data):
        """Evaluate crustal thinning criterion"""
        thickness = rift_data['crustal_thickness_km']
        thinning = rift_data['crustal_thinning_factor']
        
        if thinning > 1.5:
            score = 1.0
        elif thinning > 1.2:
            score = 0.7
        elif thickness < 30:
            score = 0.6
        else:
            score = max(0, 1 - thickness / 70)
        
        uncertainty = 0.15
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_extension_regime(self, rift_data):
        """Evaluate extensional regime"""
        extension_rate = rift_data['extension_rate_mm_yr']
        divergence = rift_data['divergence_rate']
        
        if extension_rate > 10:
            rate_score = 1.0
        elif extension_rate > 5:
            rate_score = 0.7
        elif extension_rate > 2:
            rate_score = 0.4
        else:
            rate_score = extension_rate / 10
        
        divergence_score = min(1.0, abs(divergence) * 1e8)
        
        score = 0.7 * rate_score + 0.3 * divergence_score
        uncertainty = 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_gravity_signature(self, rift_data):
        """Evaluate gravity anomaly signature"""
        bouguer = rift_data['bouguer_anomaly_mgal']
        isostatic = rift_data['isostatic_anomaly_mgal']
        
        # Negative Bouguer anomaly in rifts
        if bouguer < -50:
            bouguer_score = 1.0
        elif bouguer < -20:
            bouguer_score = 0.7
        elif bouguer < 0:
            bouguer_score = 0.4
        else:
            bouguer_score = 0.1
        
        # Positive isostatic anomaly
        isostatic_score = min(1.0, max(0, isostatic / 30))
        
        score = 0.6 * bouguer_score + 0.4 * isostatic_score
        uncertainty = 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_seismic_structure(self, rift_data):
        """Evaluate seismic structure indicators"""
        velocity_anomaly = rift_data['seismic_velocity_anomaly']
        upwelling = rift_data['mantle_upwelling_index']
        
        # Negative velocity anomaly indicates hot/weak material
        if velocity_anomaly < -2:
            velocity_score = 1.0
        elif velocity_anomaly < -1:
            velocity_score = 0.7
        elif velocity_anomaly < 0:
            velocity_score = 0.4
        else:
            velocity_score = 0.1
        
        upwelling_score = min(1.0, upwelling)
        
        score = 0.6 * velocity_score + 0.4 * upwelling_score
        uncertainty = 0.25
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_fault_pattern(self, rift_data):
        """Evaluate fault patterns"""
        density = rift_data['fault_density_km_per_km2']
        normal_ratio = rift_data['normal_fault_percentage']
        
        # High fault density
        density_score = min(1.0, density / 5)
        
        # Dominance of normal faults
        normal_score = normal_ratio
        
        score = 0.5 * density_score + 0.5 * normal_score
        uncertainty = 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_thermal_state(self, rift_data):
        """Evaluate thermal state"""
        gradient = rift_data['geothermal_gradient_C_km']
        
        if gradient > 40:
            score = 1.0
        elif gradient > 30:
            score = 0.7
        elif gradient > 25:
            score = 0.4
        else:
            score = gradient / 50
        
        uncertainty = 0.2
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_volcanic_association(self, rift_data):
        """Evaluate volcanic association"""
        activity = rift_data['volcanic_activity_index']
        score = activity
        uncertainty = 0.3
        return {'score': score, 'uncertainty': uncertainty}
    
    def _ensemble_rift_prediction(self, ml_prob, ml_unc, phys_score, phys_unc, rift_data):
        """Ensemble prediction for rift detection"""
        # Weight based on data quality
        if rift_data['rift_system'] != 'none':
            # Known rift system - higher weight to physical
            ml_weight = 0.3
            phys_weight = 0.7
        else:
            # Unknown area - balance weights
            ml_weight = 0.5
            phys_weight = 0.5
        
        combined_prob = ml_weight * ml_prob + phys_weight * phys_score
        combined_unc = np.sqrt((ml_weight * ml_unc)**2 + (phys_weight * phys_unc)**2)
        
        confidence = (1 - combined_unc) * (1 - abs(ml_prob - phys_score))
        
        return {
            'probability': combined_prob,
            'uncertainty': combined_unc,
            'confidence': confidence
        }
    
    def _classify_rift_stage(self, rift_data):
        """Classify rift evolution stage"""
        extension = rift_data['extension_rate_mm_yr']
        thinning = rift_data['crustal_thinning_factor']
        volcanism = rift_data['volcanic_activity_index']
        
        if thinning > 2.0 and extension > 20:
            return 'advanced_rifting'
        elif thinning > 1.5 and extension > 10:
            return 'active_rifting'
        elif thinning > 1.2 and extension > 5:
            return 'early_rifting'
        elif extension > 2:
            return 'incipient_rifting'
        else:
            return 'pre_rift'
    
    def _classify_extension_rate(self, rate_mm_yr):
        """Classify extension rate"""
        if rate_mm_yr > 20:
            return 'very_fast'
        elif rate_mm_yr > 10:
            return 'fast'
        elif rate_mm_yr > 5:
            return 'moderate'
        elif rate_mm_yr > 2:
            return 'slow'
        else:
            return 'very_slow'
    
    def _classify_rift_type(self, rift_data):
        """Classify rift type"""
        volcanism = rift_data['volcanic_activity_index']
        extension = rift_data['extension_rate_mm_yr']
        
        if volcanism > 0.5:
            return 'volcanic_rift'
        elif volcanism > 0.2:
            return 'magmatic_rift'
        elif extension > 10:
            return 'amagmatic_wide_rift'
        else:
            return 'amagmatic_narrow_rift'
    
    def _assess_rift_data_quality(self, results):
        """Assess rift data quality"""
