    async def _load_stability_classification_model(self):
        """Load stability classification model"""
        try:
            from .model_manager import ModelManager
            model_manager = ModelManager()
            model = await model_manager.load_model('stability_classifier_v2')
            if model is None:
                model = self._create_default_stability_classifier()
            return model
        except Exception:
            return self._create_default_stability_classifier()
    
    def _create_default_stability_classifier(self):
        """Create default stability classifier"""
        import torch.nn as nn
        
        class StabilityClassifier(nn.Module):
            def __init__(self):
                super().__init__()
                self.fc1 = nn.Linear(14, 128)
                self.fc2 = nn.Linear(128, 64)
                self.fc3 = nn.Linear(64, 32)
                self.fc4 = nn.Linear(32, 4)  # 4 classes: unstable, transitional, stable, very_stable
                self.dropout = nn.Dropout(0.25)
                self.relu = nn.ReLU()
                self.bn1 = nn.BatchNorm1d(128)
                self.bn2 = nn.BatchNorm1d(64)
                
            def forward(self, x):
                x = self.relu(self.bn1(self.fc1(x)))
                x = self.dropout(x)
                x = self.relu(self.bn2(self.fc2(x)))
                x = self.dropout(x)
                x = self.relu(self.fc3(x))
                return self.fc4(x)
        
        return StabilityClassifier()
    
    def _calculate_model_uncertainty(self, features):
        """Calculate model uncertainty for stability classification"""
        # Monte Carlo dropout approach
        n_forward = 50
        predictions = []
        
        try:
            for _ in range(n_forward):
                with torch.no_grad():
                    pred = self.stability_classifier(features.unsqueeze(0))
                    predictions.append(torch.softmax(pred, dim=1).cpu().numpy())
            
            predictions = np.array(predictions)
            return np.mean(np.std(predictions, axis=0))
        except Exception:
            return 0.2
    
    def _evaluate_age_stability(self, data):
        """Evaluate age-based stability"""
        age = data['crustal_age_ga']
        uncertainty = data['age_uncertainty_ga']
        
        if age > 2.5:  # Archean
            score = 1.0
        elif age > 1.6:  # Paleoproterozoic
            score = 0.8
        elif age > 1.0:  # Mesoproterozoic
            score = 0.6
        elif age > 0.5:  # Neoproterozoic
            score = 0.4
        else:
            score = 0.2
        
        if data['is_craton']:
            score = min(1.0, score * 1.2)
        
        return {'score': score, 'uncertainty': uncertainty * 0.1}
    
    def _evaluate_seismic_quiescence(self, data):
        """Evaluate seismic quiescence"""
        moment = data['seismic_moment_release']
        max_mag = data['max_magnitude_100yr']
        rate = data['seismicity_rate']
        
        if moment == 0 and max_mag == 0:
            score = 1.0
        elif max_mag < 4.0:
            score = 0.8
        elif max_mag < 5.0:
            score = 0.5
        elif max_mag < 6.0:
            score = 0.2
        else:
            score = 0.0
        
        # Adjust for seismicity rate
        if rate > 0:
            score *= max(0.1, 1 - np.log10(rate + 1) / 2)
        
        uncertainty = 0.15
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_thermal_stability(self, data):
        """Evaluate thermal stability"""
        heat_flow = data['heat_flow_mW_m2']
        moho_temp = data['moho_temperature_c']
        
        if heat_flow < 40 and moho_temp < 600:
            score = 1.0
        elif heat_flow < 50 and moho_temp < 700:
            score = 0.7
        elif heat_flow < 60 and moho_temp < 800:
            score = 0.4
        else:
            score = 0.1
        
        uncertainty = 0.2
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_mechanical_strength(self, data):
        """Evaluate mechanical strength"""
        litho_thick = data['lithosphere_thickness_km']
        strength = np.log10(data['lithosphere_strength_pa'])
        
        if litho_thick > 200 and strength > 23:
            score = 1.0
        elif litho_thick > 150 and strength > 22.5:
            score = 0.7
        elif litho_thick > 100:
            score = 0.4
        else:
            score = 0.1
        
        uncertainty = 0.15
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_tectonic_regime(self, data):
        """Evaluate tectonic regime stability"""
        regime = data['stress_regime']
        shear_stress = data['max_shear_stress_mpa']
        
        regime_scores = {
            'unknown': 0.5,
            'normal': 0.3,
            'strike_slip': 0.4,
            'thrust': 0.5,
            'stable': 0.9,
            'isotropic': 1.0
        }
        
        regime_score = regime_scores.get(regime, 0.5)
        
        # Low stress is more stable
        if shear_stress < 10:
            stress_score = 1.0
        elif shear_stress < 30:
            stress_score = 0.7
        elif shear_stress < 50:
            stress_score = 0.4
        else:
            stress_score = 0.1
        
        score = 0.6 * regime_score + 0.4 * stress_score
        uncertainty = 0.2
        
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_crustal_integrity(self, data):
        """Evaluate crustal integrity"""
        thickness = data['crustal_thickness_km']
        
        if 35 <= thickness <= 45:
            score = 1.0
        elif 30 <= thickness <= 50:
            score = 0.7
        elif 25 <= thickness <= 55:
            score = 0.4
        else:
            score = 0.1
        
        uncertainty = 0.15
        return {'score': score, 'uncertainty': uncertainty}
    
    def _evaluate_strain_stability(self, data):
        """Evaluate strain rate stability"""
        strain_rate = data['strain_rate_per_yr']
        
        if strain_rate < 1e-10:
            score = 1.0
        elif strain_rate < 1e-9:
            score = 0.7
        elif strain_rate < 1e-8:
            score = 0.4
        else:
            score = 0.1
        
        uncertainty = 0.2
        return {'score': score, 'uncertainty': uncertainty}
    
    def _hierarchical_stability_assessment(self, ml_prob, ml_unc, phys_score, phys_unc, data):
        """Hierarchical Bayesian assessment of stability"""
        # Prior based on geological age
        age_prior = min(1.0, data['crustal_age_ga'] / 3.0)
        
        # Weighted combination with prior
        ml_weight = (1 - ml_unc) * 0.4
        phys_weight = (1 - phys_unc) * 0.4
        prior_weight = 0.2
        
        total_weight = ml_weight + phys_weight + prior_weight
        ml_weight /= total_weight
        phys_weight /= total_weight
        prior_weight /= total_weight
        
        combined_prob = ml_weight * ml_prob + phys_weight * phys_score + prior_weight * age_prior
        
        # Uncertainty propagation
        combined_unc = np.sqrt(
            (ml_weight * ml_unc)**2 + 
            (phys_weight * phys_unc)**2 + 
            (prior_weight * 0.1)**2
        )
        
        # Confidence assessment
        agreement = 1 - np.std([ml_prob, phys_score, age_prior])
        confidence = agreement * (1 - combined_unc)
        
        return {
            'probability': combined_prob,
            'uncertainty': combined_unc,
            'confidence': confidence
        }
    
    def _classify_stability_level(self, probability):
        """Classify stability level"""
        if probability > 0.8:
            return 'very_stable'
        elif probability > 0.6:
            return 'stable'
        elif probability > 0.4:
            return 'transitional'
        elif probability > 0.2:
            return 'unstable'
        else:
            return 'very_unstable'
    
    def _assess_seismic_hazard(self, data):
        """Assess seismic hazard level"""
        max_mag = data['max_magnitude_100yr']
        
        if max_mag == 0:
            return 'very_low'
        elif max_mag < 4:
            return 'low'
        elif max_mag < 5:
            return 'moderate'
        elif max_mag < 6:
            return 'high'
        else:
            return 'very_high'
    
    def _assess_long_term_stability(self, data):
        """Assess long-term stability prospects"""
        age = data['crustal_age_ga']
        craton = data['is_craton']
        strain = data['strain_rate_per_yr']
        
        if craton and age > 2.5 and strain < 1e-10:
            return 'excellent'
        elif age > 1.5 and strain < 1e-9:
            return 'good'
        elif age > 0.5 and strain < 1e-8:
            return 'moderate'
        else:
            return 'poor'
    
    def _assess_stability_data_quality(self, results):
        """Assess stability data quality"""
        return self._assess_data_quality(results)
    
