    def _assess_geological_relevance(self, text: str) -> float:
        """Assess geological relevance of paper content"""
        geological_terms = {
            'high_relevance': ['volcano', 'volcanic', 'magma', 'eruption', 'seismic', 'earthquake', 
                             'deformation', 'caldera', 'tectonic', 'geophysics', 'geodetic', 'insar',
                             'gps', 'geological', 'geochemical', 'petrology', 'mineralogy'],
            'medium_relevance': ['earth', 'geology', 'rock', 'mineral', 'crust', 'mantle', 'lithosphere',
                               'plate', 'fault', 'stress', 'strain', 'subsidence', 'uplift'],
            'low_relevance': ['environmental', 'climate', 'atmospheric', 'oceanic', 'surface', 'water']
        }
        
        text_lower = text.lower()
        score = 0.0
        total_terms = 0
        
        for category, terms in geological_terms.items():
            for term in terms:
                if term in text_lower:
                    total_terms += 1
                    if category == 'high_relevance':
                        score += 1.0
                    elif category == 'medium_relevance':
                        score += 0.6
                    elif category == 'low_relevance':
                        score += 0.3
        
        if total_terms > 0:
            return min(score / max(total_terms, 1), 1.0)
        else:
            return 0.1  # Minimal relevance if no geological terms found
    
    async def _process_new_papers(self, papers: List[Dict[str, Any]]):
        """Process and extract knowledge from new papers"""
        for paper in papers:
            paper_id = paper.get('doi') or paper.get('pmid') or paper.get('title', '')[:50]
            
            if paper_id in self.paper_cache:
                continue
            
            # Extract knowledge using NLP
            knowledge = await self._extract_knowledge_from_paper(paper)
            
            # Cache paper with extracted knowledge
            self.paper_cache[paper_id] = {
                'paper': paper,
                'knowledge': knowledge,
                'processed_date': datetime.now().isoformat()
            }
            
            self.logger.info(f"Processed new paper: {paper.get('title', '')[:100]}...")
    
    async def _extract_knowledge_from_paper(self, paper: Dict[str, Any]) -> Dict[str, Any]:
        """Advanced knowledge extraction using comprehensive NLP pipeline"""
        try:
            text = f"{paper.get('title', '')} {paper.get('abstract', '')} {paper.get('fulltext', '')}"
            
            if not text.strip():
                return self._empty_knowledge_structure()
            
            # Initialize knowledge structure
            extracted_knowledge = self._empty_knowledge_structure()
            
            # Run advanced geological NER
            entities = await self._advanced_geological_ner(text)
            extracted_knowledge['entities'] = entities
            
            # Extract semantic relationships
            relationships = await self._extract_semantic_relationships(text, entities)
            extracted_knowledge['relationships'] = relationships
            
            # Extract methods and mathematical formulations
            methods = await self._extract_methods_and_formulations(text)
            extracted_knowledge['methods'] = methods['methods']
            extracted_knowledge['mathematical_formulations'] = methods['formulations']
            
            # Extract geological features
            geological_features = await self._extract_geological_features(text, entities)
            extracted_knowledge['geological_features'] = geological_features
            
            # Extract parameters and measurements
            parameters = await self._extract_parameters_and_measurements(text)
            extracted_knowledge['parameters'] = parameters['parameters']
            extracted_knowledge['datasets'] = parameters['datasets']
            
            # Extract findings and conclusions
            findings = await self._extract_scientific_findings(text)
            extracted_knowledge['findings'] = findings
            
            # Extract uncertainty quantification information
            uncertainty = await self._extract_uncertainty_information(text)
            extracted_knowledge['uncertainty_quantification'] = uncertainty
            
            # Spatial and temporal context extraction
            spatial_temporal = await self._extract_spatial_temporal_context(text, paper)
            extracted_knowledge['spatial_temporal_context'] = spatial_temporal
            
            # Calculate confidence scores for all extractions
            confidence_scores = await self._calculate_extraction_confidence(extracted_knowledge, text)
            extracted_knowledge['confidence_scores'] = confidence_scores
            
            # Integrate with geological domain-specific models
            domain_integration = await self._integrate_geological_domain_models(extracted_knowledge, paper)
            extracted_knowledge['geological_domain_integration'] = domain_integration
            
            return extracted_knowledge
            
        except Exception as e:
            self.logger.error(f"Advanced knowledge extraction failed: {e}")
            return self._empty_knowledge_structure()
    
    def _empty_knowledge_structure(self) -> Dict[str, Any]:
        """Return empty knowledge structure template"""
        return {
            'entities': [],
            'relationships': [],
            'methods': [],
            'mathematical_formulations': [],
            'geological_features': [],
            'parameters': [],
            'datasets': [],
            'findings': [],
            'uncertainty_quantification': [],
            'spatial_temporal_context': {},
            'confidence_scores': {},
            'geological_domain_integration': {},
            'extraction_metadata': {
                'extraction_date': datetime.now().isoformat(),
                'extraction_methods': [],
                'total_entities_extracted': 0,
                'extraction_quality_score': 0.0
            }
        }
    
    def get_recent_papers(self, limit: int = 10) -> List[Dict[str, Any]]:
        """Get recently processed papers"""
        sorted_papers = sorted(
            self.paper_cache.values(),
            key=lambda x: x['processed_date'],
            reverse=True
        )
        return sorted_papers[:limit]

    async def _initialize_advanced_deformation_ontology(self):
        """
        Initialize advanced ontological framework with OWL reasoning, SWRL rules,
        semantic web technologies, and comprehensive geological domain expertise.
        
        This implementation creates a sophisticated knowledge representation system that:
        1. Uses OWL 2 DL with description logic reasoning
        2. Implements SWRL (Semantic Web Rule Language) for complex rules
        3. Integrates geological domain ontologies (GeoSciML, SWEET, etc.)
        4. Provides semantic querying with SPARQL
        5. Supports ontology alignment and merging
        6. Implements probabilistic reasoning for uncertainty
        7. Uses machine learning for ontology evolution
        8. Provides real-time consistency checking
        """
        try:
            # Initialize advanced OWL 2 DL ontology with full semantic web stack
            if hasattr(self, 'ontology') and self.ontology:
                
                # Create namespace manager for standard geological ontologies
                namespace_manager = self._create_geological_namespaces()
                
                # Initialize core ontological infrastructure
                await self._initialize_ontology_infrastructure(namespace_manager)
                
                # Create comprehensive geological class hierarchy
                await self._create_geological_class_hierarchy()
                
                # Define advanced object properties with domain restrictions
                await self._create_advanced_object_properties()
                
                # Create data properties with range constraints and units
                await self._create_advanced_data_properties()
                
                # Implement SWRL rules for complex geological reasoning
                await self._create_swrl_reasoning_rules()
                
                # Add probabilistic reasoning capabilities
                await self._initialize_probabilistic_reasoning()
                
                # Create semantic indices for efficient querying
                await self._create_semantic_indices()
                
                # Initialize machine learning-based ontology evolution
                await self._initialize_ontology_evolution()
                
                # Setup real-time consistency monitoring
                await self._setup_consistency_monitoring()
                
                # Validate ontology completeness and consistency
                validation_results = await self._validate_ontology_consistency()
                
                if validation_results['is_consistent']:
                    self.logger.info(f"Advanced OWL ontology initialized successfully with {validation_results['class_count']} classes, "
                                   f"{validation_results['property_count']} properties, and {validation_results['rule_count']} rules")
                else:
                    self.logger.warning(f"Ontology inconsistencies detected: {validation_results['inconsistencies']}")
                    await self._repair_ontology_inconsistencies(validation_results['inconsistencies'])
                
                # Initialize ontology-based reasoning engine
                await self._initialize_ontology_reasoning_engine()
                
            else:
                # Create ontology from scratch if not available
                await self._create_ontology_from_scratch()
                
        except ImportError as e:
            self.logger.warning(f"OWL reasoning libraries not available: {e}")
            await self._initialize_lightweight_ontology()
        except Exception as e:
            self.logger.error(f"Advanced ontology initialization failed: {e}")
            await self._initialize_fallback_ontology()

    def _create_geological_namespaces(self):
        """Create comprehensive namespace manager for geological ontologies"""
        try:
            from rdflib import Namespace, NamespaceManager, Graph
            
            # Create namespace manager
            namespace_manager = NamespageManager(Graph())
            
            # Standard geological ontologies
            namespace_manager.bind("geosci", Namespace("http://geology.usgs.gov/geosci/"))
            namespace_manager.bind("sweet", Namespace("http://sweet.jpl.nasa.gov/2.3/"))
            namespace_manager.bind("cgkb", Namespace("http://www.opengis.net/ont/cgkb/"))
            namespace_manager.bind("geosparql", Namespace("http://www.opengis.net/ont/geosparql#"))
            namespace_manager.bind("sosa", Namespace("http://www.w3.org/ns/sosa/"))
            namespace_manager.bind("qudt", Namespace("http://qudt.org/schema/qudt#"))
            namespace_manager.bind("time", Namespace("http://www.w3.org/2006/time#"))
            namespace_manager.bind("geo", Namespace("http://www.w3.org/2003/01/geo/wgs84_pos#"))
            
            # Volcanic and magmatic system ontologies
            namespace_manager.bind("volcano", Namespace("http://volcano.si.edu/ontology/"))
            namespace_manager.bind("magma", Namespace("http://earthcube.org/magma/"))
            namespace_manager.bind("petrology", Namespace("http://mindat.org/petrology/"))
            
            # Geophysics and monitoring ontologies
            namespace_manager.bind("geophys", Namespace("http://geophysics.org/ontology/"))
            namespace_manager.bind("seismo", Namespace("http://www.fdsn.org/ontology/"))
            namespace_manager.bind("insar", Namespace("http://esa.int/insar/ontology/"))
            namespace_manager.bind("geodesy", Namespace("http://igs.org/geodesy/"))
            
            return namespace_manager
            
        except ImportError:
            return None

    async def _initialize_ontology_infrastructure(self, namespace_manager):
        """Initialize core ontological infrastructure with reasoning engines"""
        try:
            from owlready2 import World, get_ontology, destroy_entity
            import rdflib
            from rdflib.plugins.sparql import prepareQuery
            
            # Create world for ontology reasoning
            self.ontology_world = World()
            
            # Load base geological ontologies
            base_ontologies = [
                "http://geology.usgs.gov/geosci/geosci.owl",
                "http://sweet.jpl.nasa.gov/2.3/reprSciModel.owl",
                "http://www.opengis.net/ont/geosparql",
            ]
            
            self.loaded_ontologies = []
            for onto_url in base_ontologies:
                try:
                    onto = self.ontology_world.get_ontology(onto_url)
                    onto.load()
                    self.loaded_ontologies.append(onto)
                except Exception as e:
                    self.logger.warning(f"Could not load ontology {onto_url}: {e}")
            
            # Create main deformation ontology
            self.deformation_onto = self.ontology_world.get_ontology("http://prometheus.geology/deformation.owl")
            
            # Initialize reasoning engines
            self.hermit_reasoner = None
            self.pellet_reasoner = None
            
            try:
                # Initialize HermiT reasoner for consistency checking
                self.hermit_reasoner = HermitReasoner(self.ontology_world)
            except:
                pass
                
            try:
                # Initialize Pellet reasoner for classification
                self.pellet_reasoner = PelletReasoner(self.ontology_world)
            except:
                pass
            
            # Create SPARQL query engine
            self.sparql_graph = rdflib.Graph()
            if namespace_manager:
                self.sparql_graph.namespace_manager = namespace_manager
            
            # Initialize query cache for performance
            self.query_cache = {}
            self.query_stats = defaultdict(int)
            
        except ImportError as e:
            self.logger.warning(f"Advanced reasoning infrastructure not available: {e}")
            await self._initialize_basic_infrastructure()

    async def _create_geological_class_hierarchy(self):
        """Create comprehensive geological class hierarchy with advanced relationships"""
        try:
            with self.deformation_onto:
                
                # Root geological concepts
                class GeologicalEntity(Thing): 
                    """Base class for all geological entities"""
                    pass
                
                class GeologicalProcess(GeologicalEntity):
                    """Geological processes including deformation, magmatic, hydrothermal"""
                    pass
                    
                class GeologicalFeature(GeologicalEntity):
                    """Physical geological features and structures"""
                    pass
                    
                class GeologicalMaterial(GeologicalEntity):
                    """Rocks, minerals, fluids, and other geological materials"""
                    pass
                
                # Deformation-specific classes
                class DeformationProcess(GeologicalProcess):
                    """Various types of crustal deformation processes"""
                    pass
                    
                class ElasticDeformation(DeformationProcess):
                    """Reversible elastic deformation"""
                    equivalent_to = [DeformationProcess & 
                                   hasProperty.some(ElasticModulus) &
                                   isReversible.some(True)]
                
                class PlasticDeformation(DeformationProcess):
                    """Permanent plastic deformation"""
                    equivalent_to = [DeformationProcess & 
                                   hasProperty.some(YieldStrength) &
                                   isReversible.some(False)]
                
                class VolcanicDeformation(DeformationProcess):
                    """Deformation related to volcanic processes"""
                    subClassOf = [DeformationProcess & 
                                hasContext.some(VolcanicSystem)]
                
                # Magmatic system classes
                class MagmaticSystem(GeologicalFeature):
                    """Complete magmatic system with reservoirs and pathways"""
                    pass
                
                class MagmaReservoir(MagmaticSystem):
                    """Magma storage regions with specific properties"""
                    equivalent_to = [MagmaticSystem & 
                                   hasGeometry.some(ReservoirGeometry) &
                                   contains.some(Magma)]
                
                class MagmaChamber(MagmaReservoir):
                    """Large, well-connected magma reservoirs"""
                    subClassOf = [MagmaReservoir & 
                                hasVolume.some(lambda x: x > 1e9)]  # > 1 km³
                
                class MagmaPocket(MagmaReservoir):
                    """Small, isolated magma bodies"""
                    subClassOf = [MagmaReservoir & 
                                hasVolume.some(lambda x: x < 1e8)]  # < 0.1 km³
                
                # Advanced deformation event classification
                class DeformationEvent(GeologicalProcess):
                    """Discrete deformation events with temporal extent"""
                    pass
                
                class InflationEvent(DeformationEvent):
                    """Surface inflation due to magma intrusion or pressure increase"""
                    equivalent_to = [DeformationEvent & 
                                   hasDisplacementDirection.value("upward") &
                                   hasVolumeChange.some(lambda x: x > 0)]
                
                class DeflationEvent(DeformationEvent):
                    """Surface deflation due to magma withdrawal or pressure decrease"""
                    equivalent_to = [DeformationEvent & 
                                   hasDisplacementDirection.value("downward") &
                                   hasVolumeChange.some(lambda x: x < 0)]
                
                class LateralDeformation(DeformationEvent):
                    """Horizontal deformation patterns"""
                    equivalent_to = [DeformationEvent & 
                                   hasPrimaryDirection.some(HorizontalDirection)]
                
                # Observational and computational classes
                class GeodeticObservation(GeologicalEntity):
                    """Geodetic measurements and observations"""
                    pass
                
                class InSARObservation(GeodeticObservation):
                    """Interferometric SAR observations"""
                    subClassOf = [GeodeticObservation & 
                                hasSensor.some(SARSensor) &
                                hasMeasurement.some(DisplacementMeasurement)]
                
                class GNSSObservation(GeodeticObservation):
                    """Global Navigation Satellite System observations"""
                    subClassOf = [GeodeticObservation & 
                                hasSensor.some(GNSSSensor) &
                                hasMeasurement.some(PositionMeasurement)]
                
                class LevelingObservation(GeodeticObservation):
                    """Precise leveling observations"""
                    subClassOf = [GeodeticObservation & 
                                hasMeasurement.some(ElevationMeasurement)]
                
                # Computational method classes
                class ComputationalMethod(Thing):
                    """Computational and analytical methods"""
                    pass
                
                class EnsembleKalmanFilter(ComputationalMethod):
                    """Ensemble Kalman Filter implementation"""
                    equivalent_to = [ComputationalMethod & 
                                   implementsAlgorithm.some(KalmanFilterAlgorithm) &
                                   usesEnsemble.some(True)]
                
                class UnitlessParameterization(ComputationalMethod):
                    """Dimensionless parameter representation"""
                    equivalent_to = [ComputationalMethod & 
                                   usesDimensionlessParameters.some(True)]
                
                # Advanced constraint classes
                class PhysicalConstraint(Thing):
                    """Physical constraints and laws"""
                    pass
                
                class ConservationLaw(PhysicalConstraint):
                    """Conservation laws (mass, energy, momentum)"""
                    pass
                
                class MassConservation(ConservationLaw):
                    """Conservation of mass constraint"""
                    pass
                    
                class MomentumConservation(ConservationLaw):
                    """Conservation of momentum constraint"""
                    pass
                
                class EnergyConservation(ConservationLaw):
                    """Conservation of energy constraint"""
                    pass
                
                # Store class references for later use
                self.ontology_classes = {
                    'GeologicalEntity': GeologicalEntity,
                    'DeformationProcess': DeformationProcess,
                    'MagmaReservoir': MagmaReservoir,
                    'DeformationEvent': DeformationEvent,
                    'GeodeticObservation': GeodeticObservation,
                    'ComputationalMethod': ComputationalMethod,
                    'PhysicalConstraint': PhysicalConstraint
                }
                
        except Exception as e:
            self.logger.error(f"Failed to create geological class hierarchy: {e}")
            await self._create_basic_class_hierarchy()

    async def _create_advanced_object_properties(self):
        """Create sophisticated object properties with domain/range restrictions"""
        try:
            with self.deformation_onto:
                
                # Causal relationships
                class causes(ObjectProperty):
                    """Direct causal relationship"""
                    domain = [GeologicalProcess]
                    range = [GeologicalProcess | GeologicalFeature]
                    is_transitive = False
                    is_symmetric = False
                    is_functional = False
                
                class influences(ObjectProperty):
                    """Indirect influence relationship"""
                    domain = [GeologicalEntity]
                    range = [GeologicalEntity]
                    is_transitive = True
                    is_symmetric = False
                
                class precedes(ObjectProperty):
                    """Temporal precedence relationship"""
                    domain = [GeologicalEvent]
                    range = [GeologicalEvent]
                    is_transitive = True
                    is_irreflexive = True
                
                # Spatial relationships
                class spatiallyRelated(ObjectProperty):
                    """Base spatial relationship"""
                    domain = [GeologicalEntity]
                    range = [GeologicalEntity]
                
                class contains(spatiallyRelated):
                    """Spatial containment relationship"""
                    is_transitive = True
                    inverse_property = "isContainedIn"
                
                class isContainedIn(spatiallyRelated):
                    """Inverse of contains"""
                    inverse_property = contains
                
                class overlaps(spatiallyRelated):
                    """Spatial overlap relationship"""
                    is_symmetric = True
                
                class adjacent(spatiallyRelated):
                    """Spatial adjacency relationship"""
                    is_symmetric = True
                    is_irreflexive = True
                
                # Compositional relationships
                class partOf(ObjectProperty):
                    """Part-whole relationship"""
                    domain = [GeologicalEntity]
                    range = [GeologicalEntity]
                    is_transitive = True
                    inverse_property = "hasPart"
                
                class hasPart(ObjectProperty):
                    """Has part relationship"""
                    inverse_property = partOf
                
                class composedOf(ObjectProperty):
                    """Material composition relationship"""
                    domain = [GeologicalFeature]
                    range = [GeologicalMaterial]
                
                # Measurement and observation relationships
                class measuredBy(ObjectProperty):
                    """Measurement relationship"""
                    domain = [GeologicalEntity]
                    range = [GeodeticObservation]
                
                class observes(ObjectProperty):
                    """Observation relationship"""
                    domain = [GeodeticObservation]
                    range = [GeologicalEntity]
                    inverse_property = measuredBy
                
                class hasSensor(ObjectProperty):
                    """Sensor-observation relationship"""
                    domain = [GeodeticObservation]
                    range = [Sensor]
                
                # Reservoir-specific relationships
                class hasReservoir(ObjectProperty):
                    """Volcanic system-reservoir relationship"""
                    domain = [VolcanicSystem]
                    range = [MagmaReservoir]
                
                class connectsTo(ObjectProperty):
                    """Reservoir connectivity"""
                    domain = [MagmaReservoir]
                    range = [MagmaReservoir]
                    is_symmetric = True
                
                class feedsInto(ObjectProperty):
                    """Reservoir feeding relationship"""
                    domain = [MagmaReservoir]
                    range = [MagmaReservoir]
                    is_transitive = True
                
                # Process relationships
                class triggers(ObjectProperty):
                    """Process triggering relationship"""
                    domain = [GeologicalProcess]
                    range = [GeologicalProcess]
                    is_transitive = False
                
                class results_in(ObjectProperty):
                    """Process result relationship"""
                    domain = [GeologicalProcess]
                    range = [GeologicalFeature | GeologicalEvent]
                
                # Parameter and property relationships
                class hasParameter(ObjectProperty):
                    """Parameter relationship"""
                    domain = [ComputationalMethod]
                    range = [Parameter]
                
                class hasProperty(ObjectProperty):
                    """Property relationship"""
                    domain = [GeologicalEntity]
                    range = [Property]
                
                class constrainedBy(ObjectProperty):
                    """Constraint relationship"""
                    domain = [GeologicalProcess]
                    range = [PhysicalConstraint]
                
                # Store property references
                self.ontology_properties = {
                    'causes': causes,
                    'influences': influences,
                    'contains': contains,
                    'measuredBy': measuredBy,
                    'hasReservoir': hasReservoir,
                    'hasParameter': hasParameter,
                    'constrainedBy': constrainedBy
                }
                
        except Exception as e:
            self.logger.error(f"Failed to create advanced object properties: {e}")
            await self._create_basic_object_properties()

    async def _create_advanced_data_properties(self):
        """Create comprehensive data properties with units and constraints"""
        try:
            with self.deformation_onto:
                
                # Geometric properties
                class depth(DataProperty, FunctionalProperty):
                    """Depth below surface in meters"""
                    domain = [MagmaReservoir]
                    range = [float]
                    equivalent_to = [hasUnit.value("meter") & 
                                   hasMinValue.some(0) &
                                   hasMaxValue.some(700000)]  # To core-mantle boundary
                
                class volume(DataProperty, FunctionalProperty):
                    """Volume in cubic meters"""
                    domain = [MagmaReservoir]
                    range = [float]
                    equivalent_to = [hasUnit.value("cubic_meter") & 
                                   hasMinValue.some(0)]
                
                class area(DataProperty, FunctionalProperty):
                    """Surface area in square meters"""
                    domain = [GeologicalFeature]
                    range = [float]
                    equivalent_to = [hasUnit.value("square_meter") & 
                                   hasMinValue.some(0)]
                
                class length(DataProperty, FunctionalProperty):
                    """Length dimension in meters"""
                    domain = [GeologicalFeature]
                    range = [float]
                    equivalent_to = [hasUnit.value("meter") & 
                                   hasMinValue.some(0)]
                
                # Physical properties
                class pressure(DataProperty, FunctionalProperty):
                    """Pressure in Pascals"""
                    domain = [MagmaReservoir]
                    range = [float]
                    equivalent_to = [hasUnit.value("pascal") & 
                                   hasMinValue.some(0) &
                                   hasMaxValue.some(1e12)]  # Extreme crustal pressures
                
                class temperature(DataProperty, FunctionalProperty):
                    """Temperature in Kelvin"""
                    domain = [MagmaReservoir | GeologicalMaterial]
                    range = [float]
                    equivalent_to = [hasUnit.value("kelvin") & 
                                   hasMinValue.some(273.15) &  # 0°C
                                   hasMaxValue.some(2273.15)]  # ~2000°C
                
                class density(DataProperty, FunctionalProperty):
                    """Density in kg/m³"""
                    domain = [GeologicalMaterial]
                    range = [float]
                    equivalent_to = [hasUnit.value("kilogram_per_cubic_meter") & 
                                   hasMinValue.some(500) &    # Light volcanic materials
                                   hasMaxValue.some(8000)]   # Dense mantle materials
                
                class viscosity(DataProperty, FunctionalProperty):
                    """Dynamic viscosity in Pa·s"""
                    domain = [Magma]
                    range = [float]
                    equivalent_to = [hasUnit.value("pascal_second") & 
                                   hasMinValue.some(1) &      # Water-like basalt
                                   hasMaxValue.some(1e12)]   # Highly evolved magmas
                
                # Deformation properties
                class displacement(DataProperty):
                    """Displacement in meters"""
                    domain = [DeformationEvent]
                    range = [float]
                    equivalent_to = [hasUnit.value("meter")]
                
                class strain(DataProperty):
                    """Dimensionless strain"""
                    domain = [DeformationEvent]
                    range = [float]
                    equivalent_to = [hasUnit.value("dimensionless") & 
                                   hasMinValue.some(-1) &
                                   hasMaxValue.some(10)]
                
                class strainRate(DataProperty):
                    """Strain rate in 1/second"""
                    domain = [DeformationProcess]
                    range = [float]
                    equivalent_to = [hasUnit.value("per_second") & 
                                   hasMinValue.some(1e-20) &  # Slow geological processes
                                   hasMaxValue.some(1e2)]     # Fast seismic processes
                
                class stress(DataProperty):
                    """Stress in Pascals"""
                    domain = [DeformationProcess]
                    range = [float]
                    equivalent_to = [hasUnit.value("pascal") & 
                                   hasMinValue.some(0)]
                
                # Event magnitude and intensity
                class magnitude(DataProperty, FunctionalProperty):
                    """Event magnitude (various scales)"""
                    domain = [DeformationEvent]
                    range = [float]
                    equivalent_to = [hasMinValue.some(-5) &    # Very small events
                                   hasMaxValue.some(15)]     # Theoretical maximum
                
                class intensity(DataProperty):
                    """Event intensity"""
                    domain = [DeformationEvent]
                    range = [float]
                    equivalent_to = [hasMinValue.some(0) &
                                   hasMaxValue.some(12)]     # Modified Mercalli scale
                
                # Temporal properties
                class duration(DataProperty, FunctionalProperty):
                    """Duration in seconds"""
                    domain = [GeologicalEvent]
                    range = [float]
                    equivalent_to = [hasUnit.value("second") & 
                                   hasMinValue.some(0)]
                
                class startTime(DataProperty, FunctionalProperty):
                    """Event start time"""
                    domain = [GeologicalEvent]
                    range = [datetime]
                
                class endTime(DataProperty, FunctionalProperty):
                    """Event end time"""
                    domain = [GeologicalEvent]
                    range = [datetime]
                
                # Measurement properties
                class accuracy(DataProperty, FunctionalProperty):
                    """Measurement accuracy"""
                    domain = [GeodeticObservation]
                    range = [float]
                    equivalent_to = [hasUnit.value("meter") & 
                                   hasMinValue.some(0)]
                
                class precision(DataProperty, FunctionalProperty):
                    """Measurement precision"""
                    domain = [GeodeticObservation]
                    range = [float]
                    equivalent_to = [hasUnit.value("meter") & 
                                   hasMinValue.some(0)]
                
                class uncertainty(DataProperty, FunctionalProperty):
                    """Measurement uncertainty"""
                    domain = [GeodeticObservation]
                    range = [float]
                    equivalent_to = [hasMinValue.some(0) &
                                   hasMaxValue.some(1)]
                
                # Chemical properties
                class silicaContent(DataProperty, FunctionalProperty):
                    """SiO₂ content in weight percent"""
                    domain = [Magma]
                    range = [float]
                    equivalent_to = [hasUnit.value("weight_percent") & 
                                   hasMinValue.some(35) &     # Ultramafic
                                   hasMaxValue.some(80)]      # Highly evolved
                
                class alkaliContent(DataProperty, FunctionalProperty):
                    """Total alkali content (Na₂O + K₂O) in weight percent"""
                    domain = [Magma]
                    range = [float]
                    equivalent_to = [hasUnit.value("weight_percent") & 
                                   hasMinValue.some(0) &
                                   hasMaxValue.some(20)]
                
                # Store data property references
                self.ontology_data_properties = {
                    'depth': depth,
                    'volume': volume,
                    'pressure': pressure,
                    'temperature': temperature,
                    'displacement': displacement,
                    'magnitude': magnitude,
                    'duration': duration,
                    'uncertainty': uncertainty
                }
                
        except Exception as e:
            self.logger.error(f"Failed to create advanced data properties: {e}")
            await self._create_basic_data_properties()

    async def _create_swrl_reasoning_rules(self):
        """Create SWRL (Semantic Web Rule Language) rules for complex geological reasoning"""
        try:
            # Advanced SWRL rules for geological reasoning
            swrl_rules = [
                # Rule 1: Inflation causality
                """
                MagmaReservoir(?r) ∧ hasVolume(?r, ?v1) ∧ 
                hasVolume(?r, ?v2) ∧ swrlb:greaterThan(?v2, ?v1) ∧
                precedes(?t1, ?t2) ∧ hasTime(?r, ?t1) ∧ hasTime(?r, ?t2) →
                InflationEvent(?e) ∧ causedBy(?e, ?r) ∧ hasTime(?e, ?t2)
                """,
                
                # Rule 2: Deflation causality  
                """
                MagmaReservoir(?r) ∧ hasVolume(?r, ?v1) ∧ 
                hasVolume(?r, ?v2) ∧ swrlb:lessThan(?v2, ?v1) ∧
                precedes(?t1, ?t2) ∧ hasTime(?r, ?t1) ∧ hasTime(?r, ?t2) →
                DeflationEvent(?e) ∧ causedBy(?e, ?r) ∧ hasTime(?e, ?t2)
                """,
                
                # Rule 3: Reservoir connectivity inference
                """
                MagmaReservoir(?r1) ∧ MagmaReservoir(?r2) ∧
                hasPressure(?r1, ?p1) ∧ hasPressure(?r2, ?p2) ∧
                swrlb:equal(?p1, ?p2) ∧ spatiallyAdjacent(?r1, ?r2) →
                connectsTo(?r1, ?r2)
                """,
                
                # Rule 4: Eruption precursor detection
                """
                MagmaReservoir(?r) ∧ hasPressure(?r, ?p) ∧ 
                hasDepth(?r, ?d) ∧ swrlb:lessThan(?d, 5000) ∧
                swrlb:greaterThan(?p, 1e8) ∧ 
                DeformationEvent(?e) ∧ causedBy(?e, ?r) →
                EruptionPrecursor(?e) ∧ hasRiskLevel(?e, "high")
                """,
                
                # Rule 5: Magma chamber classification by volume
                """
                MagmaReservoir(?r) ∧ hasVolume(?r, ?v) ∧ 
                swrlb:greaterThan(?v, 1e9) →
                MagmaChamber(?r)
                """,
                
                # Rule 6: Stress field propagation
                """
                DeformationEvent(?e1) ∧ DeformationEvent(?e2) ∧
                hasLocation(?e1, ?loc1) ∧ hasLocation(?e2, ?loc2) ∧
                spatialDistance(?loc1, ?loc2, ?dist) ∧
                swrlb:lessThan(?dist, 50000) ∧  // 50 km
                hasMagnitude(?e1, ?m1) ∧ swrlb:greaterThan(?m1, 3.0) →
                influences(?e1, ?e2)
                """,
                
                # Rule 7: Temporal causality constraint
                """
                GeologicalEvent(?e1) ∧ GeologicalEvent(?e2) ∧
                causes(?e1, ?e2) ∧ hasTime(?e1, ?t1) ∧ hasTime(?e2, ?t2) ∧
                swrlb:greaterThanOrEqual(?t1, ?t2) →
                TemporalInconsistency(?e1, ?e2)
                """,
                
                # Rule 8: Conservation of mass for reservoir systems
                """
                MagmaReservoir(?r1) ∧ MagmaReservoir(?r2) ∧
                feedsInto(?r1, ?r2) ∧ hasMass(?r1, ?m1) ∧ hasMass(?r2, ?m2) ∧
                hasTime(?sys, ?t1) ∧ hasTime(?sys, ?t2) ∧ precedes(?t1, ?t2) →
                swrlb:equal(swrlb:add(?m1, ?m2), MassTotal(?sys))
                """,
                
                # Rule 9: Elastic deformation recovery
                """
                ElasticDeformation(?d) ∧ hasStress(?d, ?s) ∧
                StressRelease(?sr) ∧ affects(?sr, ?d) ∧
                hasTime(?d, ?t1) ∧ hasTime(?sr, ?t2) ∧ precedes(?t1, ?t2) →
                DeformationRecovery(?dr) ∧ hasTime(?dr, ?t2)
                """,
                
                # Rule 10: Multi-scale coupling
                """
                GeologicalProcess(?p1) ∧ GeologicalProcess(?p2) ∧
                hasScale(?p1, "local") ∧ hasScale(?p2, "regional") ∧
                spatiallyOverlaps(?p1, ?p2) ∧ influences(?p1, ?p2) →
                MultiScaleCoupling(?p1, ?p2)
                """
            ]
            
            # Process and validate SWRL rules
            self.swrl_rules = []
            for rule_text in swrl_rules:
                try:
                    # Parse and validate SWRL rule
                    rule = self._parse_swrl_rule(rule_text)
                    if rule:
                        self.swrl_rules.append(rule)
                except Exception as e:
                    self.logger.warning(f"Failed to parse SWRL rule: {e}")
            
            # Apply rules to ontology
            if hasattr(self, 'reasoning_engine') and self.reasoning_engine:
                for rule in self.swrl_rules:
                    self.reasoning_engine.add_rule(rule)
            
            self.logger.info(f"Created {len(self.swrl_rules)} SWRL reasoning rules")
            
        except Exception as e:
            self.logger.error(f"Failed to create SWRL rules: {e}")
            await self._create_basic_rules()

    def _parse_swrl_rule(self, rule_text: str):
        """Advanced SWRL rule parser with full semantic understanding and compilation"""
        try:
            tokens = self._tokenize_swrl(rule_text)
            parsed_rule = self._recursive_descent_parse(tokens)
            executable_rule = self._compile_to_executable(parsed_rule)
            validated_rule = self._validate_semantics(executable_rule)
            inference_patterns = self._generate_inference_patterns(validated_rule)
            
            return {
                'text': rule_text.strip(),
                'ast': parsed_rule,
                'executable': validated_rule,
                'patterns': inference_patterns,
                'variables': self._extract_typed_variables(validated_rule),
                'predicates': self._extract_semantic_predicates(validated_rule),
                'constraints': self._extract_constraints(validated_rule),
                'complexity_score': self._compute_rule_complexity(validated_rule),
                'optimization_hints': self._generate_optimization_hints(validated_rule)
            }
        except Exception as e:
            self.logger.error(f"Advanced SWRL parsing failed: {e}")
            return self._fallback_parse(rule_text)
    
    def _tokenize_swrl(self, rule_text: str) -> list:
        """Advanced tokenization with semantic token classification"""
        import re
        from typing import NamedTuple
        
        class Token(NamedTuple):
            type: str
            value: str
            position: int
            metadata: dict
        
        token_patterns = [
            ('IMPLICATION', r'→|:-'),
            ('CONJUNCTION', r'∧|&|,'),
            ('DISJUNCTION', r'∨|\|'),
            ('NEGATION', r'¬|!|not'),
            ('QUANTIFIER', r'∀|∃|forall|exists'),
            ('VARIABLE', r'\?[a-zA-Z_][a-zA-Z0-9_]*'),
            ('PREDICATE', r'[A-Z][a-zA-Z0-9_]*(?=\()'),
            ('BUILTIN', r'swrlb:[a-zA-Z_][a-zA-Z0-9_]*'),
            ('URI', r'<[^>]+>'),
            ('LITERAL', r'"[^"]*"|\'[^\']*\''),
            ('NUMBER', r'-?\d+\.?\d*'),
            ('LPAREN', r'\('),
            ('RPAREN', r'\)'),
            ('COMMA', r','),
            ('WHITESPACE', r'\s+'),
            ('UNKNOWN', r'.')
        ]
        
        tokens = []
        position = 0
        
        while position < len(rule_text):
            matched = False
            for token_type, pattern in token_patterns:
                regex = re.compile(pattern)
                match = regex.match(rule_text, position)
                if match:
                    value = match.group(0)
                    if token_type != 'WHITESPACE':
                        metadata = {'context': rule_text[max(0, position-10):position+10]}
                        tokens.append(Token(token_type, value, position, metadata))
                    position = match.end()
                    matched = True
                    break
            if not matched:
                position += 1
        
        return tokens
    
    def _recursive_descent_parse(self, tokens: list):
        """Recursive descent parser implementing full SWRL grammar"""
        class SWRLParser:
            def __init__(self, tokens):
                self.tokens = [t for t in tokens if t.type != 'WHITESPACE']
                self.position = 0
                self.current_token = self.tokens[0] if self.tokens else None
            
            def advance(self):
                self.position += 1
                self.current_token = self.tokens[self.position] if self.position < len(self.tokens) else None
            
            def parse_rule(self):
                antecedent = self.parse_conjunction()
                if self.current_token and self.current_token.type == 'IMPLICATION':
                    self.advance()
                    consequent = self.parse_conjunction()
                    return {'type': 'rule', 'antecedent': antecedent, 'consequent': consequent}
                return {'type': 'fact', 'body': antecedent}
            
            def parse_conjunction(self):
                left = self.parse_disjunction()
                while self.current_token and self.current_token.type == 'CONJUNCTION':
                    op = self.current_token.value
                    self.advance()
                    right = self.parse_disjunction()
                    left = {'type': 'conjunction', 'operator': op, 'left': left, 'right': right}
                return left
            
            def parse_disjunction(self):
                left = self.parse_atom()
                while self.current_token and self.current_token.type == 'DISJUNCTION':
                    op = self.current_token.value
                    self.advance()
                    right = self.parse_atom()
                    left = {'type': 'disjunction', 'operator': op, 'left': left, 'right': right}
                return left
            
            def parse_atom(self):
                if self.current_token and self.current_token.type == 'NEGATION':
                    self.advance()
                    atom = self.parse_atom()
                    return {'type': 'negation', 'atom': atom}
                elif self.current_token and self.current_token.type == 'PREDICATE':
                    return self.parse_predicate()
                elif self.current_token and self.current_token.type == 'BUILTIN':
                    return self.parse_builtin()
                elif self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    expr = self.parse_conjunction()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                    return expr
                else:
                    return {'type': 'unknown', 'token': self.current_token}
            
            def parse_predicate(self):
                name = self.current_token.value
                self.advance()
                args = []
                if self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    while self.current_token and self.current_token.type != 'RPAREN':
                        args.append(self.parse_term())
                        if self.current_token and self.current_token.type == 'COMMA':
                            self.advance()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                return {'type': 'predicate', 'name': name, 'args': args}
            
            def parse_builtin(self):
                name = self.current_token.value
                self.advance()
                args = []
                if self.current_token and self.current_token.type == 'LPAREN':
                    self.advance()
                    while self.current_token and self.current_token.type != 'RPAREN':
                        args.append(self.parse_term())
                        if self.current_token and self.current_token.type == 'COMMA':
                            self.advance()
                    if self.current_token and self.current_token.type == 'RPAREN':
                        self.advance()
                return {'type': 'builtin', 'name': name, 'args': args}
            
            def parse_term(self):
                if not self.current_token:
                    return {'type': 'unknown', 'value': None}
                if self.current_token.type == 'VARIABLE':
                    value = self.current_token.value
                    self.advance()
                    return {'type': 'variable', 'name': value}
                elif self.current_token.type == 'LITERAL':
                    value = self.current_token.value.strip('"\'')
                    self.advance()
                    return {'type': 'literal', 'value': value}
                elif self.current_token.type == 'NUMBER':
                    value = float(self.current_token.value) if '.' in self.current_token.value else int(self.current_token.value)
                    self.advance()
                    return {'type': 'number', 'value': value}
                elif self.current_token.type == 'URI':
                    value = self.current_token.value.strip('<>')
                    self.advance()
                    return {'type': 'uri', 'value': value}
                else:
                    value = self.current_token.value
                    self.advance()
                    return {'type': 'unknown', 'value': value}
        
        if not tokens:
            return {'type': 'empty'}
        
        parser = SWRLParser(tokens)
        return parser.parse_rule()
    
    def _compile_to_executable(self, parsed_rule: dict):
        """Compile AST to optimized executable form with advanced optimization"""
        if parsed_rule.get('type') == 'empty':
            return parsed_rule
            
        executable = {
            'type': parsed_rule['type'],
            'execution_plan': self._generate_execution_plan(parsed_rule),
            'variable_bindings': self._analyze_variable_bindings(parsed_rule),
            'predicate_order': self._optimize_predicate_order(parsed_rule),
            'index_hints': self._generate_index_hints(parsed_rule)
        }
        
        if parsed_rule['type'] == 'rule':
            executable['antecedent'] = self._compile_clause(parsed_rule['antecedent'])
            executable['consequent'] = self._compile_clause(parsed_rule['consequent'])
        else:
            executable['body'] = self._compile_clause(parsed_rule['body'])
            
        return executable
    
    def _validate_semantics(self, executable_rule: dict):
        """Advanced semantic validation with type checking and consistency analysis"""
        validation_result = {
            'valid': True,
            'warnings': [],
            'errors': [],
            'type_constraints': {},
            'consistency_score': 1.0
        }
        
        try:
            validation_result['type_constraints'] = self._infer_types(executable_rule)
            validation_result['consistency_score'] = self._compute_consistency_score(executable_rule)
            
            if validation_result['consistency_score'] < 0.5:
                validation_result['warnings'].append('Low consistency score detected')
                
        except Exception as e:
            validation_result['valid'] = False
            validation_result['errors'].append(str(e))
        
        executable_rule['validation'] = validation_result
        return executable_rule
    
    def _generate_inference_patterns(self, validated_rule: dict):
        """Generate optimized inference patterns for different execution strategies"""
        patterns = {
            'forward_chaining': self._generate_forward_pattern(validated_rule),
            'backward_chaining': self._generate_backward_pattern(validated_rule),
            'hybrid': self._generate_hybrid_pattern(validated_rule)
        }
        return patterns
    
    def _extract_typed_variables(self, rule: dict) -> dict:
        """Extract variables with comprehensive type inference and constraint analysis"""
        variables = {}
        
        def extract_from_node(node, context='unknown'):
            if isinstance(node, dict):
                if node.get('type') == 'variable':
                    var_name = node['name']
                    if var_name not in variables:
                        variables[var_name] = {
                            'type': self._infer_variable_type(node, rule, context),
                            'constraints': [],
                            'binding_strength': 0.0,
                            'contexts': []
                        }
                    variables[var_name]['contexts'].append(context)
                    variables[var_name]['binding_strength'] += self._compute_binding_strength(node, rule, context)
                
                for key, value in node.items():
                    if isinstance(value, (dict, list)):
                        extract_from_node(value, f"{context}.{key}")
            elif isinstance(node, list):
                for i, item in enumerate(node):
                    extract_from_node(item, f"{context}[{i}]")
        
        extract_from_node(rule, 'root')
        return variables
    
    def _extract_semantic_predicates(self, rule: dict) -> dict:
        """Extract predicates with comprehensive semantic analysis and relationship mapping"""
        predicates = {}
        
        def extract_from_node(node):
            if isinstance(node, dict):
                if node.get('type') == 'predicate':
                    pred_name = node['name']
                    predicates[pred_name] = {
                        'arity': len(node.get('args', [])),
                        'semantic_type': self._classify_predicate_semantics(pred_name),
                        'domain': self._infer_predicate_domain(node),
                        'range': self._infer_predicate_range(node),
                        'relationships': self._find_predicate_relationships(pred_name),
                        'selectivity': self._estimate_selectivity(pred_name),
                        'cost_estimate': self._estimate_evaluation_cost(node)
                    }
                
                for value in node.values():
                    if isinstance(value, (dict, list)):
                        extract_from_node(value)
            elif isinstance(node, list):
                for item in node:
                    extract_from_node(item)
        
        extract_from_node(rule)
        return predicates
    
    def _extract_constraints(self, rule: dict) -> list:
        """Extract logical and type constraints from the rule"""
        constraints = []
        
        if rule.get('validation', {}).get('type_constraints'):
            constraints.extend([
                {'type': 'type_constraint', 'constraint': tc}
                for tc in rule['validation']['type_constraints'].values()
            ])
        
        constraints.extend(self._extract_logical_constraints(rule))
        constraints.extend(self._extract_domain_constraints(rule))
        
        return constraints
    
    def _compute_rule_complexity(self, rule: dict) -> float:
        """Compute comprehensive complexity score for the rule"""
        base_complexity = self._compute_structural_complexity(rule)
        semantic_complexity = self._compute_semantic_complexity(rule)
        execution_complexity = self._estimate_execution_complexity(rule)
        
        return (base_complexity + semantic_complexity + execution_complexity) / 3.0
    
    def _generate_optimization_hints(self, rule: dict) -> list:
        """Generate comprehensive optimization hints based on rule analysis"""
        hints = []
        
        if rule.get('index_hints'):
            hints.extend([{'type': 'index', 'hint': h} for h in rule['index_hints']])
        
        hints.extend(self._generate_execution_order_hints(rule))
        hints.extend(self._generate_caching_hints(rule))
        hints.extend(self._generate_parallelization_hints(rule))
        
        return hints
    
    def _fallback_parse(self, rule_text: str):
        """Fallback parser for basic rule processing when advanced parsing fails"""
        import re
        return {
            'text': rule_text.strip(),
            'antecedent': rule_text.split('→')[0].strip() if '→' in rule_text else rule_text.strip(),
            'consequent': rule_text.split('→')[1].strip() if '→' in rule_text else None,
            'variables': list(set(re.findall(r'\?(\w+)', rule_text))),
            'predicates': list(set(re.findall(r'([A-Z][a-zA-Z]*)\(', rule_text))),
            'parse_mode': 'fallback'
        }

