    async def _monte_carlo_uncertainty(self, variables: Dict, n_samples: int = 10000) -> Dict:
        """Advanced Monte Carlo uncertainty propagation with geological domain integration"""
        try:
            self.logger.info(f"Using advanced Monte Carlo uncertainty propagation with {n_samples} samples")
            
            # Use the advanced uncertainty engine for Monte Carlo sampling
            if hasattr(self, 'advanced_uncertainty_engine'):
                # Call advanced Monte Carlo with standard method
                advanced_results = await self.advanced_uncertainty_engine._advanced_monte_carlo(
                    variables, n_samples, method='standard'
                )
                
                # Integrate with existing Bayesian network relationships
                if self.bayesian_network and advanced_results and 'error' not in advanced_results:
                    relationship_results = {}
                    
                    # Extract samples from advanced results
                    samples = {}
                    for var, var_results in advanced_results.items():
                        if isinstance(var_results, dict) and 'samples' in var_results:
                            samples[var] = var_results['samples']
                    
                    # Propagate uncertainty through geological relationships
                    for relationship, network in self.bayesian_network.items():
                        relationship_samples = []
                        for i in range(min(n_samples, len(list(samples.values())[0]) if samples else 0)):
                            sample_values = {var: samples[var][i] for var in samples if var in samples}
                            prob = self._evaluate_probabilistic_relationship(
                                relationship, sample_values
                            )
                            relationship_samples.append(prob)
                        
                        if relationship_samples:
                            relationship_results[relationship] = {
                                'mean': float(np.mean(relationship_samples)),
                                'std': float(np.std(relationship_samples)),
                                'percentiles': {
                                    '5': float(np.percentile(relationship_samples, 5)),
                                    '25': float(np.percentile(relationship_samples, 25)),
                                    '50': float(np.percentile(relationship_samples, 50)),
                                    '75': float(np.percentile(relationship_samples, 75)),
                                    '95': float(np.percentile(relationship_samples, 95))
                                },
                                'samples': relationship_samples,
                                'geological_relationship': True
                            }
                    
                    # Combine advanced results with relationship results
                    combined_results = advanced_results.copy()
                    combined_results['geological_relationships'] = relationship_results
                    return combined_results
                
                return advanced_results
            else:
                # Fallback to simplified implementation if advanced engine not available
                self.logger.warning("Advanced uncertainty engine not available, using fallback implementation")
                return await self._fallback_monte_carlo_uncertainty(variables, n_samples)
            
        except Exception as e:
            self.logger.error(f"Advanced Monte Carlo uncertainty propagation failed: {e}")
            # Fallback to simplified implementation
            return await self._fallback_monte_carlo_uncertainty(variables, n_samples)
    
    async def _fallback_monte_carlo_uncertainty(self, variables: Dict, n_samples: int = 10000) -> Dict:
        """Fallback Monte Carlo implementation for when advanced engine is not available"""
        try:
            import numpy as np
            
            results = {}
            samples = {}
            
            # Generate samples for each uncertain variable
            for var, params in variables.items():
                if params.get('distribution') == 'normal':
                    samples[var] = np.random.normal(
                        params.get('mean', 0), params.get('std', 1), n_samples
                    )
                elif params.get('distribution') == 'uniform':
                    samples[var] = np.random.uniform(
                        params.get('min', 0), params.get('max', 1), n_samples
                    )
                elif params.get('distribution') == 'lognormal':
                    samples[var] = np.random.lognormal(
                        params.get('mean', 0), params.get('std', 1), n_samples
                    )
                else:
                    samples[var] = np.random.normal(0, 1, n_samples)
            
            # Basic statistics for each variable
            for var, sample_data in samples.items():
                results[var] = {
                    'samples': sample_data,
                    'mean': float(np.mean(sample_data)),
                    'std': float(np.std(sample_data)),
                    'percentiles': {
                        '5': float(np.percentile(sample_data, 5)),
                        '25': float(np.percentile(sample_data, 25)),
                        '50': float(np.percentile(sample_data, 50)),
                        '75': float(np.percentile(sample_data, 75)),
                        '95': float(np.percentile(sample_data, 95))
                    }
                }
            
            # Propagate uncertainty through relationships
            for relationship, network in self.bayesian_network.items():
                relationship_samples = []
                for i in range(n_samples):
                    sample_values = {var: samples[var][i] for var in samples}
                    prob = self._evaluate_probabilistic_relationship(
                        relationship, sample_values
                    )
                    relationship_samples.append(prob)
                
                results[f'{relationship}_relationship'] = {
                    'mean': float(np.mean(relationship_samples)),
                    'std': float(np.std(relationship_samples)),
                    'percentiles': {
                        '5': float(np.percentile(relationship_samples, 5)),
                        '25': float(np.percentile(relationship_samples, 25)),
                        '50': float(np.percentile(relationship_samples, 50)),
                        '75': float(np.percentile(relationship_samples, 75)),
                        '95': float(np.percentile(relationship_samples, 95))
                    },
                    'samples': relationship_samples
                }
            
            return results
            
        except Exception as e:
            self.logger.error(f"Fallback Monte Carlo uncertainty propagation failed: {e}")
            return {}
    
