                validation_results['database_comparisons']['usgs'] = usgs_validation
                
                # Validate against geological survey databases
                geological_survey_validation = await self._validate_against_geological_surveys(
                    results, geological_context
                )
                validation_results['database_comparisons']['geological_surveys'] = geological_survey_validation
                
                # Cross-reference with published literature
