    async def _validate_ontology_consistency(self) -> Dict:
        """Comprehensive ontology consistency validation"""
        try:
            validation_results = {
                'is_consistent': True,
                'inconsistencies': [],
                'class_count': 0,
                'property_count': 0,
                'rule_count': 0,
                'warnings': []
            }
            
            # Run consistency checking with available reasoners
            if self.hermit_reasoner:
                try:
                    consistency = self.hermit_reasoner.is_consistent()
                    validation_results['is_consistent'] = consistency
                    if not consistency:
                        validation_results['inconsistencies'].append(
                            "Logical inconsistencies detected by HermiT reasoner"
                        )
                except Exception as e:
                    validation_results['warnings'].append(f"HermiT reasoning failed: {e}")
            
            # Count ontology elements
            if hasattr(self, 'deformation_onto'):
                validation_results['class_count'] = len(list(self.deformation_onto.classes()))
                validation_results['property_count'] = len(list(self.deformation_onto.properties()))
            
            validation_results['rule_count'] = len(getattr(self, 'swrl_rules', []))
            
            return validation_results
            
        except Exception as e:
            self.logger.error(f"Ontology validation failed: {e}")
            return {'is_consistent': False, 'inconsistencies': [str(e)]}

