    def _compute_magmatic_causality(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Compute magmatic process causality."""
        return {
            'magma_chamber_connectivity': float(np.sum(attention_matrix > 0.5)),
            'fractional_crystallization_index': self._compute_crystallization_index(attention_matrix),
            'volatile_transport_efficiency': float(np.mean(attention_matrix))
        }
    
    def _compute_metamorphic_causality(self, attention_matrix: np.ndarray) -> float:
        """Compute metamorphic causality index."""
        # Metamorphic processes show progressive patterns
        n = attention_matrix.shape[0]
        progressive_pattern = 0
        
        for i in range(n-1):
            for j in range(i+1, n):
                progressive_pattern += attention_matrix[i, j] * (j - i) / n
        
        return float(progressive_pattern / (n * (n-1) / 2))
    
    def _compute_structural_causality(self, attention_matrix: np.ndarray) -> Dict[str, Any]:
        """Compute structural causality network metrics."""
        return {
            'fold_limb_correlation': float(np.corrcoef(attention_matrix[0], attention_matrix[-1])[0, 1]),
            'fracture_network_density': float(np.sum(attention_matrix > np.mean(attention_matrix))),
            'structural_domain_coherence': self._compute_domain_coherence(attention_matrix)
        }
    
    def _construct_influence_networks(self, attention_matrix: np.ndarray, geological_features: np.ndarray) -> Dict[str, Any]:
        """Construct weighted influence networks."""
        try:
            import networkx as nx
            
            influence_networks = {}
            
            # Create weighted directed graph
            G = nx.DiGraph()
            n_features = attention_matrix.shape[-1]
            
            # Add nodes with geological feature attributes
            for i in range(n_features):
                G.add_node(i, feature_vector=geological_features[:, i].tolist() if geological_features.ndim > 1 else [geological_features[i]])
            
            # Add weighted edges across all attention heads
            for head in range(attention_matrix.shape[0]):
                for i in range(n_features):
                    for j in range(n_features):
                        if i != j:
                            weight = attention_matrix[head, i, j]
                            if weight > 0.1:  # Threshold for significant influences
                                if G.has_edge(i, j):
                                    G[i][j]['weight'] += weight
                                else:
                                    G.add_edge(i, j, weight=weight, head_contributions=[head])
                                    
            # Analyze network properties
            influence_networks['network_metrics'] = {
                'nodes': G.number_of_nodes(),
                'edges': G.number_of_edges(),
                'density': nx.density(G),
                'average_clustering': nx.average_clustering(G),
                'transitivity': nx.transitivity(G)
            }
            
            # Community detection
            try:
                communities = nx.community.greedy_modularity_communities(G.to_undirected())
                influence_networks['communities'] = [list(community) for community in communities]
                influence_networks['modularity'] = nx.community.modularity(G.to_undirected(), communities)
            except:
                influence_networks['communities'] = []
                influence_networks['modularity'] = 0.0
            
            return influence_networks
            
        except Exception as e:
            self.logger.warning(f"Network construction failed: {e}")
            return {'error': str(e), 'basic_network_stats': self._basic_network_stats(attention_matrix)}
    
