    def _create_feature_vector_for_ml(self, strengths: np.ndarray, features: Dict) -> np.ndarray:
        """Create feature vector for machine learning models"""
        try:
            feature_vector = []
            
            # Add strength statistics
            if len(strengths) > 0:
                feature_vector.extend([
                    np.mean(strengths),
                    np.std(strengths),
                    np.min(strengths),
                    np.max(strengths)
                ])
            
            # Add geological feature statistics
            for feature_name, feature_data in features.items():
                if isinstance(feature_data, np.ndarray) and len(feature_data) > 0:
                    if feature_data.ndim == 1:
                        feature_vector.extend([
                            np.mean(feature_data),
                            np.std(feature_data)
                        ])
                    else:
                        # Multi-dimensional features
                        feature_vector.extend([
                            np.mean(feature_data),
                            np.std(feature_data)
                        ])
            
            return np.array(feature_vector)
            
        except Exception as e:
            self.logger.debug(f"Error creating feature vector: {e}")
            return np.array([])

    async def _detect_anomalous_causal_patterns(self, geological_data: Any) -> Dict[str, Any]:
        """Detect anomalous causal patterns using statistical and machine learning methods."""
        try:
            anomaly_results = {
                'statistical_anomalies': {},
                'network_anomalies': {},
                'temporal_anomalies': {},
                'spatial_anomalies': {},
                'causal_strength_outliers': {}
            }
            
            # Advanced real-time causal strength computation from integrated geological data sources
            causal_strengths = await self._compute_advanced_causal_strengths(geological_data)
            
            # Statistical anomaly detection
            mean_strength = np.mean(causal_strengths)
            std_strength = np.std(causal_strengths)
            
            # Z-score based outlier detection
            z_scores = np.abs((causal_strengths - mean_strength) / (std_strength + 1e-8))
            statistical_outliers = np.where(z_scores > 2.5)[0]
            
            anomaly_results['statistical_anomalies'] = {
                'outlier_count': len(statistical_outliers),
                'outlier_indices': statistical_outliers.tolist(),
                'mean_strength': float(mean_strength),
                'std_strength': float(std_strength),
                'outlier_threshold': 2.5
            }
            
            # IQR-based outlier detection
            q1 = np.percentile(causal_strengths, 25)
            q3 = np.percentile(causal_strengths, 75)
            iqr = q3 - q1
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            
            iqr_outliers = np.where((causal_strengths < lower_bound) | (causal_strengths > upper_bound))[0]
            
            anomaly_results['causal_strength_outliers'] = {
                'iqr_outlier_count': len(iqr_outliers),
                'iqr_outlier_indices': iqr_outliers.tolist(),
                'lower_bound': float(lower_bound),
                'upper_bound': float(upper_bound),
                'iqr_value': float(iqr)
            }
            
            # Advanced real-time network anomaly detection with Graph Neural Networks
            anomaly_results['network_anomalies'] = await self._detect_advanced_network_anomalies(
                geological_data, causal_strength
            )
            
            # Advanced temporal anomaly detection with time series analysis
            anomaly_results['temporal_anomalies'] = await self._detect_advanced_temporal_anomalies(
                geological_data, causal_strength
            )
            
            # Advanced spatial anomaly detection with geological constraints
            anomaly_results['spatial_anomalies'] = await self._detect_advanced_spatial_anomalies(
                geological_data, causal_strength
            )
            
            return anomaly_results
            
        except Exception as e:
            self.logger.error(f"Error detecting anomalous causal patterns: {e}")
            return {'error': str(e), 'confidence': 0.0}

