    def _calculate_seismic_stability_impact(self, seismic_event):
        """Calculate how seismic events impact system stability."""
        try:
            magnitude = seismic_event.get('magnitude', 0.0)
            depth = seismic_event.get('depth', 10.0)
            
            # Larger, shallower earthquakes have more stability impact
            magnitude_impact = min(magnitude / 7.0, 1.0)  # Normalize to M7
            depth_impact = max(0, (50.0 - depth) / 50.0)  # Shallower = more impact
            
            stability_impact = 1.0 - (magnitude_impact * 0.7 + depth_impact * 0.3)
            return max(0.1, min(0.9, stability_impact))
            
        except Exception:
            return 0.8  # Default moderate stability
    
    def _calculate_deformation_stability_impact(self, deformation_measurement):
        """Calculate how deformation affects system stability."""
        try:
            displacement = abs(deformation_measurement.get('displacement_mm', 0.0))
            velocity = abs(deformation_measurement.get('velocity_mm_per_day', 0.0))
            
            # Higher deformation rates decrease stability
            displacement_impact = min(displacement / 10.0, 1.0)  # Normalize to 10mm
            velocity_impact = min(velocity / 5.0, 1.0)  # Normalize to 5mm/day
            
            stability_impact = 1.0 - (displacement_impact * 0.6 + velocity_impact * 0.4)
            return max(0.2, min(0.9, stability_impact))
            
        except Exception:
            return 0.8  # Default moderate stability
    
    def _calculate_geochemical_stability_impact(self, geochemical_sample):
        """Calculate how geochemical changes affect system stability."""
        try:
            co2 = geochemical_sample.get('co2_ppm', 0.0)
            so2 = geochemical_sample.get('so2_ppm', 0.0)
            h2s = geochemical_sample.get('h2s_ppm', 0.0)
            temp = geochemical_sample.get('temperature_celsius', 20.0)
            
            # Elevated gas concentrations and temperatures indicate instability
            co2_impact = min(co2 / 1000.0, 1.0)  # Normalize to 1000ppm
            so2_impact = min(so2 / 100.0, 1.0)   # Normalize to 100ppm
            h2s_impact = min(h2s / 50.0, 1.0)    # Normalize to 50ppm
            temp_impact = max(0, (temp - 20.0) / 80.0)  # Above 20C baseline
            
            chemical_instability = (co2_impact * 0.3 + so2_impact * 0.3 + 
                                  h2s_impact * 0.2 + temp_impact * 0.2)
            
            stability_impact = 1.0 - chemical_instability
            return max(0.1, min(0.9, stability_impact))
            
        except Exception:
            return 0.8  # Default moderate stability

