    async def _calculate_causal_graph_relevance(self, graph_data: Dict[str, Any], query: Dict[str, Any]) -> float:
        """Calculate relevance score for causal graph search results"""
        try:
            relevance_score = 0.0
            
            # Base relevance from quality metrics
            quality_metrics = graph_data.get('quality_metrics', {})
            if 'geological_consistency_score' in quality_metrics:
                relevance_score += quality_metrics['geological_consistency_score'] * 0.3
            
            # Variable overlap bonus
            if 'variables' in query:
                query_vars = set(query['variables'])
                graph_vars = set(graph_data['graph'].get('variables', []))
                overlap_ratio = len(query_vars.intersection(graph_vars)) / len(query_vars) if query_vars else 0
                relevance_score += overlap_ratio * 0.4
            
            # Geological context matching
            if 'geological_region' in query:
                geological_context = graph_data.get('geological_context', {})
                if geological_context.get('region') == query['geological_region']:
                    relevance_score += 0.2
            
            # Statistical significance bonus
            p_values = graph_data['graph'].get('p_values', {})
            significant_count = len([p for p in p_values.values() if p < 0.05])
            total_relationships = len(p_values) if p_values else 1
            significance_ratio = significant_count / total_relationships
            relevance_score += significance_ratio * 0.1
            
            return min(relevance_score, 1.0)  # Cap at 1.0
            
        except Exception as e:
            self.logger.error(f"Failed to calculate relevance score: {e}")
            return 0.0
    
    async def _validate_retrieved_causal_graph(self, graph_data: Dict[str, Any]) -> Dict[str, Any]:
        """Validate integrity and consistency of retrieved causal graph data"""
        try:
            validation_result = {'valid': True, 'issues': []}
            
            # Check required fields
            required_fields = ['graph', 'metadata', 'geological_context']
            for field in required_fields:
                if field not in graph_data:
                    validation_result['issues'].append(f"Missing required field: {field}")
                    validation_result['valid'] = False
            
            # Validate graph structure
            graph = graph_data.get('graph', {})
            if 'nodes' in graph and 'edges' in graph:
                # Check edge consistency
                nodes = set(graph['nodes'])
                for edge in graph['edges']:
                    if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                        if edge[0] not in nodes or edge[1] not in nodes:
                            validation_result['issues'].append(f"Edge references non-existent node: {edge}")
                            validation_result['valid'] = False
            
            # Check statistical significance consistency
            if 'p_values' in graph:
                p_values = graph['p_values']
                for rel, p_value in p_values.items():
                    if not (0 <= p_value <= 1):
                        validation_result['issues'].append(f"Invalid p-value for {rel}: {p_value}")
                        validation_result['valid'] = False
            
            return validation_result
            
        except Exception as e:
            self.logger.error(f"Graph validation failed: {e}")
            return {'valid': False, 'issues': [f"Validation error: {e}"]}
    
    async def _fallback_causal_graph_storage(self, graph: Dict[str, Any], metadata: Dict[str, Any]) -> str:
        """Fallback storage mechanism for causal graphs"""
        try:
            import json
            from pathlib import Path
            
            # Create fallback directory
            fallback_dir = Path("./fallback_causal_storage")
            fallback_dir.mkdir(exist_ok=True)
            
            # Generate fallback ID
            fallback_id = f"fallback_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{hash(str(graph))}"
            
            # Store data
            fallback_data = {
                'graph': graph,
                'metadata': metadata,
                'storage_timestamp': datetime.now().isoformat(),
                'storage_type': 'fallback'
            }
            
            fallback_path = fallback_dir / f"{fallback_id}.json"
            with open(fallback_path, 'w') as f:
                json.dump(fallback_data, f, indent=2, default=str)
            
            self.logger.info(f"Causal graph stored in fallback location: {fallback_id}")
            return fallback_id
            
        except Exception as e:
            self.logger.error(f"Fallback storage failed: {e}")
            return f"storage_failed_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
    
    async def _fallback_causal_graph_retrieval(self, graph_id: str) -> Optional[Dict[str, Any]]:
        """Fallback retrieval mechanism for causal graphs"""
        try:
            from pathlib import Path
            import json
            
            # Check fallback directory
            fallback_dir = Path("./fallback_causal_storage")
            fallback_path = fallback_dir / f"{graph_id}.json"
            
            if fallback_path.exists():
                with open(fallback_path, 'r') as f:
                    fallback_data = json.load(f)
                
                self.logger.info(f"Retrieved causal graph from fallback: {graph_id}")
                return fallback_data
            
            return None
            
        except Exception as e:
            self.logger.error(f"Fallback retrieval failed: {e}")
            return None
    
    async def _fallback_causal_graph_search(self, query: Dict[str, Any], limit: int) -> List[Dict[str, Any]]:
        """Fallback search mechanism for causal graphs"""
        try:
            from pathlib import Path
            import json
            
            results = []
            fallback_dir = Path("./fallback_causal_storage")
            
            if not fallback_dir.exists():
                return []
            
            # Search through fallback files
            for fallback_file in fallback_dir.glob("*.json"):
                try:
                    with open(fallback_file, 'r') as f:
                        data = json.load(f)
                    
                    # Simple matching
                    graph = data.get('graph', {})
                    metadata = data.get('metadata', {})
                    
                    # Check basic criteria
                    match = True
                    if 'variables' in query:
                        query_vars = set(query['variables'])
                        graph_vars = set(graph.get('variables', []))
                        if not query_vars.issubset(graph_vars):
                            match = False
                    
                    if match:
                        results.append({
                            'graph_id': fallback_file.stem,
                            'metadata': metadata,
                            'relevance_score': 0.5,  # Default score
                            'preview': {
                                'node_count': len(graph.get('nodes', [])),
                                'edge_count': len(graph.get('edges', [])),
                                'source': 'fallback_storage'
                            }
                        })
                        
                        if len(results) >= limit:
                            break
                            
                except Exception as e:
                    self.logger.warning(f"Failed to process fallback file {fallback_file}: {e}")
                    continue
            
            return results
            
        except Exception as e:
            self.logger.error(f"Fallback search failed: {e}")
            return []
    
    async def _calculate_geological_consistency_score(self, graph: Dict[str, Any]) -> float:
        """Calculate geological consistency score for causal relationships"""
        try:
            if not graph or 'edges' not in graph:
                return 0.0
            
            consistency_score = 0.0
            total_relationships = len(graph['edges'])
            
            if total_relationships == 0:
                return 0.0
            
            for edge in graph['edges']:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    # Check if causal relationship makes geological sense
                    cause, effect = edge[0], edge[1]
                    
                    # Geological domain knowledge validation
                    geological_validity = await self._validate_geological_causal_relationship(cause, effect)
                    consistency_score += geological_validity
            
            return consistency_score / total_relationships
            
        except Exception as e:
            self.logger.error(f"Failed to calculate geological consistency score: {e}")
            return 0.0
    
