    def _get_default_hyperparameters(self, algorithm: str) -> Dict[str, Any]:
        """Get default hyperparameters for specific algorithm"""
        hyperparameter_defaults = {
            'pc': {'alpha': 0.05, 'max_cond_vars': 5, 'method': 'stable'},
            'ges': {'score_type': 'bic', 'penalization_factor': 1.0, 'max_iter': 1000},
            'lingam': {'prior_knowledge': None, 'measure': 'pwling', 'thresh': 0.01},
            'notears': {'lambda1': 0.01, 'lambda2': 0.01, 'max_iter': 100, 'h_tol': 1e-8},
            'causal_ensemble': {'voting_strategy': 'majority', 'confidence_threshold': 0.8, 'algorithm_weights': None}
        }
        
        return hyperparameter_defaults.get(algorithm, {})
    
    def _get_expected_metrics(self, algorithm: str) -> List[str]:
        """Get expected performance metrics for specific algorithm"""
        metric_mappings = {
            'pc': ['precision', 'recall', 'f1_score', 'structural_hamming_distance'],
            'ges': ['bic_score', 'aic_score', 'structural_accuracy'],
            'lingam': ['causal_order_accuracy', 'independence_score'],
            'notears': ['dag_constraint_violation', 'mse_loss', 'sparsity'],
            'causal_ensemble': ['ensemble_agreement', 'prediction_uncertainty', 'robustness_score']
        }
        
        return metric_mappings.get(algorithm, ['accuracy', 'precision', 'recall'])
    
