    async def _validate_geological_causal_relationship(self, cause: str, effect: str) -> float:
        """Validate causal relationship against geological domain knowledge"""
        try:
            # Define geological causal relationship patterns
            geological_patterns = {
                'pressure': {'temperature', 'deformation', 'seismic_activity'},
                'temperature': {'gas_emission', 'thermal_anomaly', 'mineral_alteration'},
                'seismic_activity': {'ground_deformation', 'acoustic_emission'},
                'ground_deformation': {'stress_field', 'surface_displacement'},
                'gas_emission': {'chemical_composition', 'atmospheric_detection'},
                'magma_chamber': {'pressure', 'temperature', 'volume_change'},
                'hydrothermal': {'temperature', 'fluid_flow', 'chemical_alteration'}
            }
            
            # Check if causal relationship follows geological patterns
            for cause_pattern, effect_patterns in geological_patterns.items():
                if cause_pattern in cause.lower():
                    for effect_pattern in effect_patterns:
                        if effect_pattern in effect.lower():
                            return 1.0  # Strong geological consistency
            
            # Check temporal geological constraints
            temporal_constraints = {
                'seismic_precursor': ['eruption', 'deformation'],
                'gas_precursor': ['eruption', 'thermal_anomaly'],
                'deformation_precursor': ['eruption', 'pressure_increase']
            }
            
            for temporal_pattern, effects in temporal_constraints.items():
                if temporal_pattern in cause.lower():
                    for effect_pattern in effects:
                        if effect_pattern in effect.lower():
                            return 0.9  # Good temporal consistency
            
            # Default moderate consistency for other relationships
            return 0.5
            
        except Exception as e:
            self.logger.error(f"Failed to validate geological causal relationship: {e}")
            return 0.0
    
