    async def _create_connector_stream_adapter(self, connector_name: str, connector, stream_config: Dict) -> Dict:
        """Create stream adapter for external data connector."""
        try:
            from .stream_processing import StreamEvent, StreamEventType
            
            adapter = {
                'connector': connector,
                'stream_topic': f"prometheus_{connector_name.lower()}_stream",
                'data_transformer': await self._create_data_transformer(connector_name),
                'event_parser': await self._create_event_parser(connector_name),
                'quality_assessor': await self._create_quality_assessor(connector_name),
                'rate_limiter': self._create_adaptive_rate_limiter(connector_name),
                'error_handler': await self._create_error_handler(connector_name),
                'metrics_collector': await self._create_metrics_collector(connector_name),
                'last_data_fetch': datetime.utcnow(),
                'fetch_interval': self._get_optimal_fetch_interval(connector_name),
                'active': True
            }
            
            # Setup periodic data fetching for this connector
            asyncio.create_task(self._periodic_connector_fetch(connector_name, adapter))
            
            return adapter
            
        except Exception as e:
            self.logger.error(f"Failed to create stream adapter for {connector_name}: {e}")
            return None
    
