    def _calculate_name_match_confidence(self, target: str, candidate: str) -> float:
        """Calculate confidence score for name matching"""
        try:
            if not target or not candidate:
                return 0.0
            
            target_lower = target.lower().strip()
            candidate_lower = candidate.lower().strip()
            
            # Exact match
            if target_lower == candidate_lower:
                return 1.0
            
            # Substring match
            if target_lower in candidate_lower or candidate_lower in target_lower:
                return 0.8
            
            # Fuzzy matching using word overlap
            target_words = set(target_lower.split())
            candidate_words = set(candidate_lower.split())
            
            if target_words and candidate_words:
                overlap = len(target_words.intersection(candidate_words))
                total = len(target_words.union(candidate_words))
                return overlap / total if total > 0 else 0.0
            
            return 0.0
            
        except Exception:
            return 0.0
    
    async def _cache_regional_boundary(self, region: str, bbox: Tuple[float, float, float, float]):
        """Cache regional boundary result for performance optimization"""
        try:
            if hasattr(self, 'database_integration') and self.database_integration:
                await self.database_integration.execute_query("""
                    INSERT INTO regional_boundaries_cache 
                    (region_name, bbox_west, bbox_south, bbox_east, bbox_north, created_at, expires_at)
                    VALUES (%s, %s, %s, %s, %s, NOW(), NOW() + INTERVAL '7 days')
                    ON CONFLICT (region_name) DO UPDATE SET
                        bbox_west = EXCLUDED.bbox_west,
                        bbox_south = EXCLUDED.bbox_south,
                        bbox_east = EXCLUDED.bbox_east,
                        bbox_north = EXCLUDED.bbox_north,
                        created_at = NOW(),
                        expires_at = NOW() + INTERVAL '7 days'
                """, [region.lower(), bbox[0], bbox[1], bbox[2], bbox[3]])
                
        except Exception as e:
            self.logger.debug(f"Failed to cache boundary for {region}: {e}")
    
