    async def _handle_sensor_stream_event(self, event):
        """Handle general sensor data events from stream processing."""
        try:
            sensor_type = event.data.get('sensor_type', 'unknown')
            measurement = event.data.get('measurement', 0)
            
            # Route to appropriate sensor-specific handler
            sensor_handlers = {
                'accelerometer': self._handle_accelerometer_data,
                'magnetometer': self._handle_magnetometer_data,
                'pressure_sensor': self._handle_pressure_data,
                'temperature_sensor': self._handle_temperature_data
            }
            
            handler = sensor_handlers.get(sensor_type)
            if handler:
                await handler(event)
            
        except Exception as e:
            self.logger.error(f"Error handling sensor stream event: {e}")
    
    async def _collect_stream_metrics(self):
        """Collect stream processing metrics continuously."""
        try:
            while True:
                if hasattr(self, 'kafka_stream_manager') and self.kafka_stream_manager:
                    # Collect Kafka metrics
                    kafka_metrics = await self._get_kafka_metrics()
                    self.stream_metrics.update(kafka_metrics)
                
                if hasattr(self, 'real_time_aggregator') and self.real_time_aggregator:
                    # Collect aggregation metrics
                    agg_metrics = await self._get_aggregation_metrics()
                    self.stream_metrics.update(agg_metrics)
                
                # Calculate derived metrics
                self._calculate_derived_metrics()
                
                # Check alerting thresholds
                await self._check_stream_alerting_thresholds()
                
                await asyncio.sleep(30)  # Collect metrics every 30 seconds
                
        except Exception as e:
            self.logger.error(f"Error collecting stream metrics: {e}")
    
    async def _fallback_event_processor(self, queue_name: str):
        """Fallback event processor for in-memory queues."""
        try:
            while True:
                if queue_name in self.fallback_stream_processing['event_queues']:
                    queue = self.fallback_stream_processing['event_queues'][queue_name]
                    
                    try:
                        # Wait for event with timeout
                        event = await asyncio.wait_for(queue.get(), timeout=1.0)
                        
                        # Process event based on queue type
                        if queue_name == 'earthquake_events':
                            await self._handle_earthquake_stream_event(event)
                        elif queue_name == 'volcanic_events':
                            await self._handle_volcanic_stream_event(event)
                        elif queue_name == 'deformation_events':
                            await self._handle_deformation_stream_event(event)
                        elif queue_name == 'seismic_data':
                            await self._handle_seismic_stream_event(event)
                        elif queue_name == 'alerts':
                            await self._handle_alert_stream_event(event)
                        else:
                            # Generic processing
                            await self._handle_generic_event(event)
                            
                        queue.task_done()
                        
                    except asyncio.TimeoutError:
                        # No events to process, continue
                        continue
                
                await asyncio.sleep(0.1)
                
        except Exception as e:
            self.logger.error(f"Fallback processor error for {queue_name}: {e}")

    async def _handle_geological_alert(self, alert_data: Dict[str, Any]):
        """
        Handle real-time geological alerts from external data connectors
        Integrates alerts into knowledge graph and triggers appropriate responses
        """
        try:
            alert_type = alert_data.get('type', 'unknown')
            timestamp = alert_data.get('timestamp', datetime.now())
            coordinates = alert_data.get('coordinates', (0, 0, 0))
            
            self.logger.info(f"Processing geological alert: {alert_type} at {coordinates}")
            
            # Create knowledge graph entity for the alert
            alert_entity = {
                'id': f"alert_{alert_type}_{int(timestamp.timestamp())}",
                'type': f'geological_{alert_type}_alert',
                'label': f"{alert_type.capitalize()} Alert",
                'properties': {
                    'alert_type': alert_type,
                    'timestamp': timestamp.isoformat(),
                    'coordinates': coordinates,
                    'source': alert_data.get('source', 'external_connector'),
                    'severity': self._calculate_alert_severity(alert_data),
                    **alert_data  # Include all alert data
                }
            }
            
            # Add alert entity to knowledge graph
            if self.knowledge_graph:
                await self.knowledge_graph.add_entity(alert_entity)
                
                # Create relationships to nearby geological features
                await self._link_alert_to_geological_features(alert_entity, coordinates)
            
            # Store in vector store for semantic search
            if self.vector_store:
                alert_text = self._generate_alert_description(alert_data)
                self.vector_store.add_texts(
                    texts=[alert_text],
                    metadatas=[{
                        'type': 'geological_alert',
                        'alert_type': alert_type,
                        'timestamp': timestamp.isoformat(),
                        'coordinates': coordinates,
                        'entity_id': alert_entity['id']
                    }]
                )
            
            # Process specific alert types
            if alert_type == 'earthquake':
                await self._process_earthquake_alert(alert_data, alert_entity)
            elif alert_type == 'volcano':
                await self._process_volcano_alert(alert_data, alert_entity)
            
            # Update performance monitoring
            if hasattr(self, 'performance_monitor') and self.performance_monitor:
                self.performance_monitor.record_operation(
                    name=f"geological_alert_processing",
                    duration=time.time() - timestamp.timestamp(),
                    status='completed',
                    metadata={
                        'alert_type': alert_type,
                        'coordinates': coordinates,
                        'severity': alert_entity['properties']['severity']
                    }
                )
            
            # Trigger additional analysis if high severity
            if alert_entity['properties']['severity'] >= 0.8:
                await self._trigger_high_severity_analysis(alert_data, alert_entity)
            
            self.logger.info(f"Successfully processed {alert_type} alert with severity {alert_entity['properties']['severity']:.2f}")
            
        except Exception as e:
            self.logger.error(f"Error handling geological alert: {e}")
    
    def _calculate_alert_severity(self, alert_data: Dict[str, Any]) -> float:
        """Calculate severity score for geological alert (0.0 to 1.0)"""
        try:
            alert_type = alert_data.get('type', 'unknown')
            severity = 0.5  # Default moderate severity
            
            if alert_type == 'earthquake':
                magnitude = alert_data.get('magnitude', 0)
                if magnitude:
                    # Earthquake severity based on magnitude
                    if magnitude >= 7.0:
                        severity = 1.0  # Major earthquake
                    elif magnitude >= 6.0:
                        severity = 0.9
                    elif magnitude >= 5.0:
                        severity = 0.7
                    elif magnitude >= 4.0:
                        severity = 0.5
                    else:
                        severity = 0.3
                
            elif alert_type == 'volcano':
                alert_level = alert_data.get('alert_level', '').upper()
                if alert_level == 'WARNING':
                    severity = 1.0
                elif alert_level == 'WATCH':
                    severity = 0.8
                elif alert_level == 'ADVISORY':
                    severity = 0.6
                else:
                    severity = 0.4
            
            return min(severity, 1.0)
            
        except Exception as e:
            self.logger.warning(f"Error calculating alert severity: {e}")
            return 0.5
    
    def _generate_alert_description(self, alert_data: Dict[str, Any]) -> str:
        """Generate natural language description of geological alert"""
        try:
            alert_type = alert_data.get('type', 'geological event')
            location = alert_data.get('location', 'Unknown location')
            
            if alert_type == 'earthquake':
                magnitude = alert_data.get('magnitude', 0)
                depth = alert_data.get('depth', 0)
                return f"Magnitude {magnitude} earthquake detected at {location}, depth {depth}km"
                
            elif alert_type == 'volcano':
                name = alert_data.get('name', 'volcanic system')
                alert_level = alert_data.get('alert_level', 'unknown')
                activity = alert_data.get('activity', 'volcanic activity')
                return f"Volcano alert for {name}: {alert_level} level, {activity}"
            
            return f"{alert_type.capitalize()} alert detected at {location}"
            
        except Exception as e:
            self.logger.warning(f"Error generating alert description: {e}")
            return f"Geological alert: {alert_data.get('type', 'unknown')}"
    
    async def _link_alert_to_geological_features(self, alert_entity: Dict, coordinates: Tuple[float, float, float]):
        """Link geological alert to nearby features in knowledge graph"""
        try:
            if not self.knowledge_graph:
                return
            
            # Search for nearby geological features (simplified - would use spatial queries in production)
            lat, lon, depth = coordinates
            
            # Create relationships to general geological concepts
            relationships = [
                {
                    'subject': alert_entity['id'],
                    'predicate': 'located_at',
                    'object': f"coordinates_{lat:.2f}_{lon:.2f}",
                    'properties': {
                        'latitude': lat,
                        'longitude': lon,
                        'depth': depth,
                        'coordinate_system': 'WGS84'
                    }
                },
                {
                    'subject': alert_entity['id'],
                    'predicate': 'temporal_event',
                    'object': 'geological_timeline',
                    'properties': {
                        'timestamp': alert_entity['properties']['timestamp'],
                        'event_type': 'real_time_detection'
                    }
                }
            ]
            
            # Add relationships to knowledge graph
            for relationship in relationships:
                await self.knowledge_graph.add_relationship(relationship)
            
        except Exception as e:
            self.logger.warning(f"Error linking alert to geological features: {e}")
    
    async def _process_earthquake_alert(self, alert_data: Dict[str, Any], alert_entity: Dict):
        """Process specific earthquake alert data"""
        try:
            magnitude = alert_data.get('magnitude', 0)
            
            # Trigger additional analysis for significant earthquakes
            if magnitude >= 5.0:
                # Query related seismic activity
                if self.external_data_connectors and 'USGS' in self.external_data_connectors:
                    coords = alert_data.get('coordinates', (0, 0, 0))
                    recent_activity = self.external_data_connectors['USGS'].get_earthquake_data(
                        min_latitude=coords[0] - 1.0,
                        max_latitude=coords[0] + 1.0,
                        min_longitude=coords[1] - 1.0,
                        max_longitude=coords[1] + 1.0,
                        start_time=datetime.now() - timedelta(days=7),
                        limit=50
                    )
                    
                    # Add context about regional seismic activity
                    alert_entity['properties']['regional_context'] = {
                        'recent_earthquakes_count': len(recent_activity),
                        'analysis_radius_km': 111,  # Approx 1 degree
                        'analysis_timeframe_days': 7
                    }
            
        except Exception as e:
            self.logger.warning(f"Error processing earthquake alert: {e}")
    
    async def _process_volcano_alert(self, alert_data: Dict[str, Any], alert_entity: Dict):
        """Process specific volcano alert data"""
        try:
            alert_level = alert_data.get('alert_level', '').upper()
            
            # Trigger additional analysis for high-level volcano alerts
            if alert_level in ['WATCH', 'WARNING']:
                # Query volcano database for additional information
                volcano_name = alert_data.get('name', '')
                if volcano_name and self.external_data_connectors and 'GVP' in self.external_data_connectors:
                    historical_data = self.external_data_connectors['GVP'].get_volcano_data(
                        volcano_name=volcano_name,
                        limit=10
                    )
                    
                    if historical_data:
                        alert_entity['properties']['historical_context'] = {
                            'last_known_eruption': historical_data[0].properties.get('last_eruption'),
                            'volcano_type': historical_data[0].properties.get('type'),
                            'tectonic_setting': historical_data[0].properties.get('tectonic_setting')
                        }
            
        except Exception as e:
            self.logger.warning(f"Error processing volcano alert: {e}")
    
    async def _trigger_high_severity_analysis(self, alert_data: Dict[str, Any], alert_entity: Dict):
        """Trigger comprehensive analysis for high-severity geological alerts"""
        try:
            self.logger.info(f"Triggering high-severity analysis for {alert_data.get('type', 'unknown')} alert")
            
            # Start real-time monitoring if not already active
            if hasattr(self.external_data_connector, 'start_realtime_monitoring') and not self.data_stream_active:
                self.data_stream_active = True
                asyncio.create_task(self.external_data_connector.start_realtime_monitoring())
                
            # Trigger additional data collection
            coordinates = alert_data.get('coordinates', (0, 0, 0))
            
            # Collect multi-source data for the region
            if self.external_data_connector:
                comprehensive_data = self.external_data_connector.get_all_available_data(
                    min_latitude=coordinates[0] - 0.5,
                    max_latitude=coordinates[0] + 0.5,
                    min_longitude=coordinates[1] - 0.5,
                    max_longitude=coordinates[1] + 0.5,
                    start_time=datetime.now() - timedelta(hours=24),
                    limit=100
                )
                
                # Process and integrate the additional data
                for data_type, records in comprehensive_data.items():
                    for record in records[:10]:  # Limit processing for performance
                        entity = {
                            'id': f"related_{record.record_id}",
                            'type': f'related_{record.data_type}',
                            'label': f"Related {record.data_type}",
                            'properties': {
                                'source': record.source,
                                'coordinates': record.coordinates,
                                'quality_score': record.quality_score,
                                **record.properties
                            }
                        }
                        
                        if self.knowledge_graph:
                            await self.knowledge_graph.add_entity(entity)
                            
                            # Create relationship to the alert
                            relationship = {
                                'subject': alert_entity['id'],
                                'predicate': 'related_to',
                                'object': entity['id'],
                                'properties': {
                                    'relationship_type': 'spatial_temporal_correlation',
                                    'distance_km': self._calculate_distance(coordinates, record.coordinates),
                                    'temporal_proximity': 'concurrent'
                                }
                            }
                            await self.knowledge_graph.add_relationship(relationship)
            
        except Exception as e:
            self.logger.error(f"Error in high-severity analysis: {e}")
    
    def _calculate_distance(self, coord1: Tuple[float, float, float], coord2: Tuple[float, float, float]) -> float:
        """Calculate approximate distance between two coordinates in km"""
        try:
            from math import radians, cos, sin, asin, sqrt
            
            lat1, lon1, _ = coord1
            lat2, lon2, _ = coord2
            
            # Convert to radians
            lat1, lon1, lat2, lon2 = map(radians, [lat1, lon1, lat2, lon2])
            
            # Haversine formula
            dlat = lat2 - lat1
            dlon = lon2 - lon1
            a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
            c = 2 * asin(sqrt(a))
            r = 6371  # Radius of earth in kilometers
            
            return c * r
            
        except Exception as e:
            self.logger.warning(f"Error calculating distance: {e}")
            return 0.0
    
    async def start_realtime_data_streaming(self):
        """Start real-time data streaming from external connectors"""
        try:
            if not self.external_data_connector:
                self.logger.warning("External data connector not available for real-time streaming")
                return
            
            if hasattr(self.external_data_connector, 'start_realtime_monitoring'):
                self.data_stream_active = True
                await self.external_data_connector.start_realtime_monitoring()
                self.logger.info("Real-time geological data streaming started")
            else:
                self.logger.warning("Real-time monitoring not supported by current connector")
                
        except Exception as e:
            self.logger.error(f"Error starting real-time data streaming: {e}")
    
    async def stop_realtime_data_streaming(self):
        """Stop real-time data streaming"""
        try:
            if self.external_data_connector and hasattr(self.external_data_connector, 'stop_monitoring'):
                self.external_data_connector.stop_monitoring()
                self.data_stream_active = False
                self.logger.info("Real-time geological data streaming stopped")
                
        except Exception as e:
            self.logger.error(f"Error stopping real-time data streaming: {e}")
    
    async def get_realtime_stream_status(self) -> Dict[str, Any]:
        """Get status of real-time data streams"""
        try:
            if not self.external_data_connector:
                return {'status': 'unavailable', 'reason': 'connector_not_initialized'}
            
            # Test connectivity to all sources
            if hasattr(self.external_data_connector, '_test_all_connections'):
                connectivity_status = await self.external_data_connector._test_all_connections()
            else:
                connectivity_status = {}
            
            return {
                'status': 'active' if self.data_stream_active else 'inactive',
                'feeds_configured': len(self.realtime_data_feeds) if self.realtime_data_feeds else 0,
                'connectors_available': len(self.external_data_connectors) if self.external_data_connectors else 0,
                'connectivity_status': connectivity_status,
                'monitoring_thresholds': getattr(self.external_data_connector, 'monitoring_thresholds', {}),
                'last_updated': datetime.now().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Error getting realtime stream status: {e}")
            return {'status': 'error', 'error': str(e)}
    
    async def semantic_similarity_search(self, query: str, top_k: int = 5) -> List[Dict[str, Any]]:
        """Perform semantic similarity search on knowledge entities"""
        try:
            if not self.vector_store:
                self.logger.warning("Vector store not available for similarity search")
                return []
            
            # Perform similarity search
            results = self.vector_store.similarity_search_with_score(query, k=top_k)
            
            # Format results
            formatted_results = []
            for doc, score in results:
                formatted_results.append({
                    'text': doc.page_content,
                    'similarity_score': float(1 - score),  # Convert distance to similarity
                    'metadata': doc.metadata
                })
            
            self.logger.info(f"Found {len(formatted_results)} similar entities for query: {query[:50]}...")
            return formatted_results
            
        except Exception as e:
            self.logger.error(f"Semantic similarity search failed: {e}")
            return []

