    def _evaluate_expert_expectation(self, cause: str, effect: str, expected_relationships: Dict[str, List[str]]) -> float:
        """Evaluate if a causal relationship aligns with expert expectations"""
        try:
            # Check if this relationship is expected by domain experts
            for cause_pattern, expected_effects in expected_relationships.items():
                if cause_pattern.lower() in cause.lower():
                    if any(effect_pattern.lower() in effect.lower() for effect_pattern in expected_effects):
                        return 1.0  # Strong expert alignment
                    else:
                        return 0.4  # Cause matches but effect is unexpected
            
            # Check reverse relationships (sometimes unexpected but valid)
            for cause_pattern, expected_effects in expected_relationships.items():
                if cause_pattern.lower() in effect.lower():
                    if any(effect_pattern.lower() in cause.lower() for effect_pattern in expected_effects):
                        return 0.3  # Reverse relationship (might be valid in some contexts)
            
            # If no specific expert knowledge, assume moderate alignment
            return 0.6
            
        except Exception:
            return 0.6
    
    async def _pc_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Implement PC (Peter-Clark) algorithm for causal discovery
        
        The PC algorithm is a constraint-based approach that uses conditional independence
        tests to learn the structure of a causal graph.
        """
        n_vars = data.shape[1]
        
        # Initialize complete graph
        adjacency = np.ones((n_vars, n_vars)) - np.eye(n_vars)
        separating_sets = {}
        
        # Phase 1: Edge removal based on conditional independence
        for order in range(n_vars - 1):
            edge_removed = True
            while edge_removed:
                edge_removed = False
                
                for i in range(n_vars):
                    for j in range(i + 1, n_vars):
                        if adjacency[i, j] == 0:
                            continue
                        
                        # Get neighbors of i excluding j
                        neighbors_i = [k for k in range(n_vars) if k != j and adjacency[i, k] == 1]
                        
                        # Test all subsets of size 'order'
                        if len(neighbors_i) >= order:
                            from itertools import combinations
                            for conditioning_set in combinations(neighbors_i, order):
                                # Conditional independence test
                                if len(conditioning_set) == 0:
                                    ci_result = self.ci_tester.independence_test(
                                        data[:, i], data[:, j]
                                    )
                                else:
                                    Z = data[:, list(conditioning_set)]
                                    ci_result = self.ci_tester.independence_test(
                                        data[:, i], data[:, j], Z
                                    )
                                
                                if ci_result['independent']:
                                    # Remove edge
                                    adjacency[i, j] = adjacency[j, i] = 0
                                    separating_sets[(i, j)] = conditioning_set
                                    separating_sets[(j, i)] = conditioning_set
                                    edge_removed = True
                                    break
                        
                        if edge_removed:
                            break
                    if edge_removed:
                        break
        
        # Phase 2: Advanced Geological Edge Orientation with Database Integration
        directed_adjacency = await self._advanced_geological_edge_orientation_pc(
            adjacency, separating_sets, n_vars, data, variable_names, db_integrator
        )
        
        # Calculate confidence scores
        confidence_scores = self._calculate_confidence_scores_pc(
            data, directed_adjacency, separating_sets
        )
        
        # Determine causal order
        causal_order = self._topological_sort(directed_adjacency)
        
        return {
            'adjacency_matrix': directed_adjacency,
            'undirected_adjacency': adjacency,
            'separating_sets': separating_sets,
            'causal_order': causal_order,
            'confidence_scores': confidence_scores,
            'method': 'PC'
        }
    
    def _ges_algorithm(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Advanced GES (Greedy Equivalence Search) algorithm using causal-learn library
        
        GES is a score-based causal discovery algorithm that greedily searches
        over the space of equivalence classes of DAGs using advanced scoring functions
        and optimal search strategies from the causal-learn library.
        """
        try:
            # Import causal-learn library for advanced GES implementation
            try:
                from causallearn.search.ScoreBased.GES import ges
                from causallearn.utils.cit import CIT
                from causallearn.score.LocalScore import local_score_BIC, local_score_BDeu, local_score_cv_general
                from causallearn.utils.PCUtils.BackgroundKnowledge import BackgroundKnowledge
                causal_learn_available = True
            except ImportError:
                self.logger.warning("causal-learn library not available. Using advanced custom implementation.")
                causal_learn_available = False
            
            if causal_learn_available:
                return self._advanced_causal_learn_ges(data, variable_names)
            else:
                return self._advanced_custom_ges_implementation(data, variable_names)
                
        except Exception as e:
            self.logger.error(f"Error in advanced GES algorithm: {e}")
            return self._fallback_ges_implementation(data, variable_names)
    
    def _advanced_causal_learn_ges(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Advanced GES implementation using causal-learn library
        
        Features:
        - Multiple scoring functions (BIC, BDeu, cross-validation)
        - Advanced search strategies with equivalence class handling
        - Background knowledge integration
        - Bootstrap confidence estimation
        - Multiple initialization strategies
        """
        from causallearn.search.ScoreBased.GES import ges
        from causallearn.utils.cit import CIT
        from causallearn.score.LocalScore import local_score_BIC, local_score_BDeu
        from causallearn.utils.PCUtils.BackgroundKnowledge import BackgroundKnowledge
        import pandas as pd
        
        n_vars = data.shape[1]
        n_samples = data.shape[0]
        
        try:
            # Standardize data for better numerical stability
            data_std = (data - np.mean(data, axis=0)) / (np.std(data, axis=0) + 1e-8)
            
            # Create background knowledge object for geological constraints
            bk = BackgroundKnowledge()
            
            # Add geological domain knowledge constraints
            self._add_geological_background_knowledge(bk, variable_names)
            
            # Configure advanced GES parameters
            ges_params = {
                'score_func': 'local_score_BIC',  # Start with BIC
                'maxP': None,  # No limit on parents
                'parameters': None,  # Let algorithm determine
                'node_names': variable_names if variable_names else [f'X{i}' for i in range(n_vars)]
            }
            
            # Multiple scoring function evaluation for robustness
            scoring_results = {}
            
            # 1. BIC-based GES
            try:
                Record_bic = ges(data_std, score_func='local_score_BIC', **{k:v for k,v in ges_params.items() if k != 'score_func'})
                scoring_results['BIC'] = {
                    'graph': Record_bic['G'].graph,
                    'score': Record_bic.get('score', 0)
                }
            except Exception as e:
                self.logger.warning(f"BIC scoring failed: {e}")
            
            # 2. BDeu-based GES (for discrete/discretized data)
            try:
                if n_samples > 50:  # BDeu works better with more samples
                    Record_bdeu = ges(data_std, score_func='local_score_BDeu', **{k:v for k,v in ges_params.items() if k != 'score_func'})
                    scoring_results['BDeu'] = {
                        'graph': Record_bdeu['G'].graph,
                        'score': Record_bdeu.get('score', 0)
                    }
            except Exception as e:
                self.logger.warning(f"BDeu scoring failed: {e}")
            
            # Select best result based on score and validation
            best_result = self._select_best_ges_result(scoring_results, data_std)
            
            if best_result is None:
                return self._fallback_ges_implementation(data, variable_names)
            
            # Extract adjacency matrix
            adjacency_matrix = np.array(best_result['graph'])
            
            # Advanced confidence estimation using bootstrap
            confidence_scores = self._bootstrap_ges_confidence(data_std, adjacency_matrix, n_bootstrap=100)
            
            # Advanced causal ordering using topological sort with stability analysis
            causal_order = self._robust_topological_sort(adjacency_matrix)
            
            # Edge strength analysis
            edge_strengths = self._analyze_edge_strengths(data_std, adjacency_matrix)
            
            # Equivalence class analysis
            equivalence_info = self._analyze_equivalence_classes(adjacency_matrix)
            
            # Statistical significance testing
            significance_tests = self._perform_edge_significance_tests(data_std, adjacency_matrix, alpha=0.05)
            
            return {
                'adjacency_matrix': adjacency_matrix,
                'causal_order': causal_order,
                'confidence_scores': confidence_scores,
                'edge_strengths': edge_strengths,
                'equivalence_classes': equivalence_info,
                'significance_tests': significance_tests,
                'best_score': best_result['score'],
                'scoring_method': best_result.get('method', 'BIC'),
                'n_edges': np.sum(adjacency_matrix > 0),
                'method': 'Advanced_GES_CausalLearn',
                'library_version': 'causal-learn'
            }
            
        except Exception as e:
            self.logger.error(f"Error in causal-learn GES: {e}")
            return self._fallback_ges_implementation(data, variable_names)
    
    def _advanced_custom_ges_implementation(self, data: np.ndarray, variable_names: List[str]) -> Dict[str, Any]:
        """
        Advanced custom GES implementation with state-of-the-art techniques
        
        Features:
        - Advanced scoring functions (BIC, AIC, MDL, cross-validation)
        - Intelligent search strategies with look-ahead
        - Multi-start optimization
        - Advanced equivalence class handling
        - Constraint propagation
        - Adaptive scoring threshold
        """
        n_vars = data.shape[1]
        n_samples = data.shape[0]
        
        # Standardize data
        data_std = (data - np.mean(data, axis=0)) / (np.std(data, axis=0) + 1e-8)
        
        # Multi-start GES with different initialization strategies
        best_result = None
        best_score = -np.inf
        
        initialization_strategies = ['empty', 'random', 'correlation_based', 'mutual_information']
        
        for init_strategy in initialization_strategies:
            try:
                result = self._run_advanced_ges_iteration(data_std, variable_names, init_strategy)
                
                if result['total_score'] > best_score:
                    best_score = result['total_score']
                    best_result = result
                    
            except Exception as e:
                self.logger.warning(f"GES iteration with {init_strategy} failed: {e}")
                continue
        
        if best_result is None:
            return self._fallback_ges_implementation(data, variable_names)
        
        return best_result
    
    def _run_advanced_ges_iteration(self, data: np.ndarray, variable_names: List[str], 
                                  init_strategy: str) -> Dict[str, Any]:
        """
        Run single advanced GES iteration with specified initialization
        """
        n_vars = data.shape[1]
        
        # Initialize graph based on strategy
        adjacency = self._initialize_graph(data, init_strategy)
        
        # Advanced scoring with multiple criteria
        current_scores = self._compute_comprehensive_scores(data, adjacency)
        best_total_score = current_scores['total_score']
        
        # Phase 1: Forward search with look-ahead and constraint propagation
        adjacency = self._advanced_forward_search(data, adjacency, max_iterations=n_vars * n_vars)
        
        # Phase 2: Backward search with statistical validation
        adjacency = self._advanced_backward_search(data, adjacency, max_iterations=n_vars * n_vars)
        
        # Phase 3: Edge orientation optimization
        adjacency = self._optimize_edge_orientations(data, adjacency)
        
        # Final scoring and validation
        final_scores = self._compute_comprehensive_scores(data, adjacency)
        
        # Advanced confidence estimation
        confidence_scores = self._compute_advanced_confidence_scores(data, adjacency)
        
        # Causal ordering with stability analysis
        causal_order = self._robust_topological_sort(adjacency)
        
        # Edge significance testing
