    def _calculate_lyapunov_stability(self) -> Dict[str, float]:
        """Calculate Lyapunov stability using dynamical systems analysis"""
        try:
            from .database_integration import DatabaseIntegration
            from scipy.integrate import odeint
            from scipy.optimize import minimize
            
            db_integration = DatabaseIntegration()
            
            # Query recent system state trajectories
            trajectory_query = """
            SELECT 
                t.system_state_vector,
                t.state_derivatives,
                t.timestamp,
                t.perturbation_response,
                s.stress_tensor_components,
                s.deformation_gradients
            FROM system_trajectories t
            JOIN stability_analysis s ON t.analysis_id = s.analysis_id
            WHERE t.timestamp >= NOW() - INTERVAL '7 days'
            AND t.trajectory_quality >= 0.8
            ORDER BY t.timestamp DESC
            LIMIT 1000;
            """
            
            trajectory_data = db_integration.execute_query_sync(trajectory_query)
            
            if not trajectory_data or len(trajectory_data) < 10:
                return {'score': 0.5, 'confidence': 0.1}
            
            # Extract state vectors and derivatives
            states = np.array([json.loads(d['system_state_vector']) for d in trajectory_data[:50]])
            derivatives = np.array([json.loads(d['state_derivatives']) for d in trajectory_data[:50]])
            
            # Calculate Lyapunov exponents using QR decomposition method
            lyapunov_exponents = self._compute_lyapunov_exponents(states, derivatives)
            
            # Stability classification based on largest Lyapunov exponent
            largest_exponent = np.max(lyapunov_exponents)
            
            if largest_exponent < -0.1:
                stability_score = 0.9  # Highly stable
            elif largest_exponent < -0.01:
                stability_score = 0.7  # Stable
            elif largest_exponent < 0.01:
                stability_score = 0.5  # Marginally stable
            elif largest_exponent < 0.1:
                stability_score = 0.3  # Unstable
            else:
                stability_score = 0.1  # Highly unstable
            
            # Confidence based on data quality and consistency
            confidence = min(1.0, len(trajectory_data) / 100.0) * 0.8
            
            return {
                'score': stability_score,
                'confidence': confidence,
                'lyapunov_exponents': lyapunov_exponents.tolist(),
                'largest_exponent': largest_exponent
            }
            
        except Exception as e:
            self.logger.warning(f"Lyapunov stability calculation failed: {e}")
            return {'score': 0.5, 'confidence': 0.0}
    
    def _extract_convergence_features(self, history: np.ndarray) -> np.ndarray:
        """Extract advanced multi-scale features for sophisticated ML-based convergence analysis"""
        try:
            from scipy import signal, stats
            from scipy.fft import fft, fftfreq
            from sklearn.preprocessing import RobustScaler
            import pywt
            
            features = []
            
            # 1. ADVANCED STATISTICAL FEATURES
            if len(history) >= 2:
                robust_scaler = RobustScaler()
                scaled_history = robust_scaler.fit_transform(history.reshape(-1, 1)).flatten()
                
                # Robust statistics
                features.extend([
                    np.mean(history),
                    np.median(history),
                    stats.trim_mean(history, 0.1),  # 10% trimmed mean
                    stats.iqr(history),  # Interquartile range
                    stats.mad(history),  # Median absolute deviation
                    np.ptp(history),  # Peak-to-peak
                    np.sqrt(np.mean(np.square(history - np.mean(history)))),  # RMS
                ])
                
                # Distribution shape features
                features.extend([
                    stats.skew(history),
                    stats.kurtosis(history),
                    stats.jarque_bera(history)[0],  # Normality test statistic
                    len(history[history > np.mean(history)]) / len(history),  # Above-mean ratio
                ])
            
            # 2. MULTI-SCALE TREND ANALYSIS
            if len(history) >= 5:
                x = np.arange(len(history))
                
                # Polynomial trends of different orders
                for order in [1, 2, 3]:
                    if len(history) > order:
                        poly_coeffs = np.polyfit(x, history, order)
                        features.extend(poly_coeffs.tolist())
                        
                        # Trend strength (R²)
                        poly_pred = np.polyval(poly_coeffs, x)
                        r_squared = 1 - np.sum((history - poly_pred)**2) / np.sum((history - np.mean(history))**2)
                        features.append(r_squared)
                
                # Change point detection features
                diff_history = np.diff(history)
                if len(diff_history) > 0:
                    features.extend([
                        np.std(diff_history),
                        np.max(np.abs(diff_history)),
                        len(np.where(np.abs(diff_history) > 2*np.std(diff_history))[0]) / len(diff_history)  # Outlier ratio
                    ])
            
            # 3. SPECTRAL AND FREQUENCY DOMAIN FEATURES
            if len(history) >= 8:
                # FFT-based features
                fft_values = np.abs(fft(history))
                freqs = fftfreq(len(history))
                
                # Dominant frequency components
                dominant_freq_idx = np.argmax(fft_values[1:len(history)//2]) + 1
                features.extend([
                    freqs[dominant_freq_idx],  # Dominant frequency
                    fft_values[dominant_freq_idx] / np.sum(fft_values),  # Relative power
                    np.sum(fft_values[:len(history)//4]) / np.sum(fft_values),  # Low-frequency power ratio
                ])
                
                # Spectral entropy
                power_spectrum = fft_values**2
                power_spectrum = power_spectrum / np.sum(power_spectrum)
                spectral_entropy = -np.sum(power_spectrum * np.log(power_spectrum + 1e-12))
                features.append(spectral_entropy)
            
            # 4. WAVELET DECOMPOSITION FEATURES
            if len(history) >= 16:
                try:
                    # Multi-resolution analysis using Daubechies wavelets
                    coeffs = pywt.wavedec(history, 'db4', level=min(3, int(np.log2(len(history)))))
                    
                    for level, coeff in enumerate(coeffs):
                        if len(coeff) > 0:
                            features.extend([
                                np.std(coeff),  # Energy at this level
                                np.max(np.abs(coeff)),  # Maximum coefficient
                                np.sum(coeff**2) / len(coeff)  # Average power
                            ])
                except:
                    # Fallback if wavelet decomposition fails
                    features.extend([0.0] * 9)  # 3 levels × 3 features
            
            # 5. ADVANCED AUTOCORRELATION AND LONG-RANGE DEPENDENCE
            if len(history) >= 10:
                # Multi-lag autocorrelation
                max_lag = min(len(history)//3, 10)
                autocorrs = []
                
                for lag in range(1, max_lag + 1):
                    if lag < len(history):
                        autocorr = np.corrcoef(history[:-lag], history[lag:])[0, 1]
                        autocorrs.append(autocorr if not np.isnan(autocorr) else 0.0)
                
                if autocorrs:
                    features.extend([
                        np.mean(autocorrs),
                        np.std(autocorrs),
                        np.max(np.abs(autocorrs)),
                        np.sum(np.abs(autocorrs)),  # Total correlation
                    ])
                    
                    # Hurst exponent estimation (simplified)
                    if len(history) >= 20:
                        def hurst_rs(series):
                            """R/S analysis for Hurst exponent"""
                            n = len(series)
                            if n < 10:
                                return 0.5
                            
                            mean_series = np.mean(series)
                            cumsum = np.cumsum(series - mean_series)
                            R = np.max(cumsum) - np.min(cumsum)
                            S = np.std(series)
                            
                            return np.log(R/S) / np.log(n) if S > 0 and R > 0 else 0.5
                        
                        hurst_exp = hurst_rs(history)
                        features.append(hurst_exp)
            
            # 6. CONVERGENCE-SPECIFIC FEATURES
            if len(history) >= 6:
                # Convergence velocity (how fast values are approaching a limit)
                recent_third = history[-len(history)//3:]
                if len(recent_third) >= 3:
                    convergence_target = np.median(recent_third)
                    distances = np.abs(history - convergence_target)
                    
                    # Exponential decay fitting
                    if np.any(distances > 0):
                        try:
                            log_distances = np.log(distances + 1e-12)
                            x_vals = np.arange(len(log_distances))
                            slope, _ = np.polyfit(x_vals, log_distances, 1)
                            features.append(-slope)  # Convergence rate (negative of decay rate)
                        except:
                            features.append(0.0)
                    else:
                        features.append(1.0)  # Already converged
                
                # Stability windows analysis
                window_size = max(3, len(history)//5)
                stability_scores = []
                
                for i in range(window_size, len(history)):
                    window = history[i-window_size:i]
                    cv = np.std(window) / (np.mean(np.abs(window)) + 1e-12)  # Coefficient of variation
                    stability_scores.append(1.0 / (1.0 + cv))
                
                if stability_scores:
                    features.extend([
                        np.mean(stability_scores),
                        np.std(stability_scores),
                        np.min(stability_scores),
                        np.max(stability_scores)
                    ])
            
            # Ensure consistent feature vector length
            target_length = 50  # Fixed feature vector size
            current_length = len(features)
            
            if current_length < target_length:
                # Pad with zeros
                features.extend([0.0] * (target_length - current_length))
            elif current_length > target_length:
                # Truncate to target length
                features = features[:target_length]
            
            return np.array(features, dtype=np.float32)
            
        except Exception as e:
            self.logger.warning(f"Advanced feature extraction failed: {e}")
            # Return zero-padded fallback vector
            return np.zeros(50, dtype=np.float32)
    
    def _extract_window_features(self, window: np.ndarray) -> np.ndarray:
        """Extract features from a sliding window for ML analysis"""
        try:
            features = [
                np.mean(window),
                np.std(window),
                np.max(window) - np.min(window),  # Range
                window[-1] - window[0] if len(window) > 1 else 0.0,  # Total change
                np.sum(np.abs(np.diff(window))) if len(window) > 1 else 0.0  # Total variation
            ]
            
            # Add trend if window is long enough
            if len(window) >= 3:
                x = np.arange(len(window))
                slope = np.polyfit(x, window, 1)[0]
                features.append(slope)
            
            return np.array(features)
            
        except Exception as e:
            return np.array([0.0] * 6)
    
    def _simple_convergence_rate(self, history: np.ndarray) -> float:
        """Simple fallback convergence rate calculation"""
        if len(history) < 2:
            return 0.5
        
        diffs = np.abs(np.diff(history))
        if len(diffs) == 0:
            return 1.0
        
        # Simple exponential decay estimation
        recent_diffs = diffs[-min(5, len(diffs)):]
        if len(recent_diffs) >= 2:
            decay_ratio = recent_diffs[-1] / (recent_diffs[0] + 1e-10)
            return min(1.0, max(0.0, 1.0 - decay_ratio))
        
        return 0.5
    
    # Advanced supporting methods for new implementations
    
    def _get_geological_context_convergence(self) -> float:
        """Calculate convergence rate based on geological context"""
        try:
            from .geological_statistics import GeologicalStatistics
            from .external_data_connectors import GeologicalDataConnector
            
            geo_stats = GeologicalStatistics()
            geo_connector = GeologicalDataConnector()
            
            # Get current location context
            current_location = getattr(self, 'current_location', {'lat': 0.0, 'lon': 0.0})
            
            # Query geological complexity factors
            complexity_data = geo_connector.get_geological_complexity(
                current_location['lat'], current_location['lon']
            )
            
            # Calculate convergence rate based on complexity
            base_rate = 0.7
            
            # Adjust for tectonic setting
            tectonic_setting = complexity_data.get('tectonic_setting', 'stable')
            tectonic_multipliers = {
                'stable_craton': 0.9,
                'passive_margin': 0.85,
                'active_margin': 0.7,
                'rift_zone': 0.6,
                'subduction_zone': 0.5,
                'transform_fault': 0.55
            }
            
            tectonic_factor = tectonic_multipliers.get(tectonic_setting, 0.7)
            
            # Adjust for lithological complexity
            lithology_complexity = complexity_data.get('lithology_complexity', 1.0)
            lithology_factor = max(0.5, 1.0 - (lithology_complexity - 1.0) * 0.2)
            
            # Adjust for structural complexity
            structural_complexity = complexity_data.get('structural_complexity', 1.0)
            structural_factor = max(0.5, 1.0 - (structural_complexity - 1.0) * 0.15)
            
            final_rate = base_rate * tectonic_factor * lithology_factor * structural_factor
            return max(0.1, min(0.95, final_rate))
            
        except Exception as e:
            self.logger.warning(f"Geological context convergence calculation failed: {e}")
            return 0.6
    
    def _predict_convergence_rate_ml(self) -> float:
        """Predict convergence rate using machine learning models"""
        try:
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.preprocessing import StandardScaler
            from sklearn.model_selection import cross_val_score
            import joblib
            import os
            
            # Try to load pre-trained model
            model_path = os.path.join(os.path.dirname(__file__), 'models', 'convergence_predictor.pkl')
            scaler_path = os.path.join(os.path.dirname(__file__), 'models', 'convergence_scaler.pkl')
            
            if os.path.exists(model_path) and os.path.exists(scaler_path):
                try:
                    model = joblib.load(model_path)
                    scaler = joblib.load(scaler_path)
                    
                    # Extract features from current context
                    features = self._extract_context_features_for_ml()
                    if features is not None and len(features) > 0:
                        features_scaled = scaler.transform(features.reshape(1, -1))
                        prediction = model.predict(features_scaled)[0]
                        return max(0.1, min(0.95, prediction))
                        
                except Exception as e:
                    self.logger.warning(f"Pre-trained model prediction failed: {e}")
            
            # Fallback: create and train a simple model with synthetic data
            return self._train_simple_convergence_model()
            
        except Exception as e:
            self.logger.warning(f"ML convergence prediction failed: {e}")
            return 0.65
    
    def _extract_context_features_for_ml(self) -> np.ndarray:
        """Extract contextual features for ML convergence prediction"""
        try:
            features = []
            
            # Problem characteristics
            problem_size = getattr(self, 'problem_dimension', 100)
            features.append(np.log10(problem_size + 1))
            
            # Matrix properties
            condition_number = getattr(self, 'condition_number', 100.0)
            features.append(np.log10(condition_number + 1))
            
            # Data quality indicators
            data_quality = getattr(self, 'data_quality_score', 0.8)
            features.append(data_quality)
            
            # Geological complexity
            geological_complexity = getattr(self, 'geological_complexity', 1.0)
            features.extend([geological_complexity, geological_complexity**2])
            
            # Noise level
            noise_level = getattr(self, 'noise_level', 0.1)
            features.append(noise_level)
            
            # Temporal factors
            temporal_complexity = getattr(self, 'temporal_complexity', 1.0)
            features.append(temporal_complexity)
            
            # Method-specific factors
            method_complexity = getattr(self, 'method_complexity_score', 0.5)
            features.append(method_complexity)
            
            return np.array(features, dtype=np.float32)
            
        except Exception as e:
            self.logger.warning(f"Context feature extraction failed: {e}")
            return np.array([0.5] * 8, dtype=np.float32)
    
    def _train_simple_convergence_model(self) -> float:
        """Train a simple convergence model using domain knowledge"""
        try:
            from sklearn.ensemble import RandomForestRegressor
            from sklearn.preprocessing import StandardScaler
            import random
            
            # Generate synthetic training data based on domain knowledge
            n_samples = 200
            X_synthetic = []
            y_synthetic = []
            
            for _ in range(n_samples):
                # Random problem characteristics
                problem_size = random.uniform(10, 1000)
                condition_number = random.uniform(1, 1000)
                data_quality = random.uniform(0.5, 1.0)
                geological_complexity = random.uniform(0.5, 3.0)
                noise_level = random.uniform(0.01, 0.5)
                
                features = [
                    np.log10(problem_size + 1),
                    np.log10(condition_number + 1),
                    data_quality,
                    geological_complexity,
                    geological_complexity**2,
                    noise_level,
                    random.uniform(0.5, 2.0),  # temporal_complexity
                    random.uniform(0.3, 0.8)   # method_complexity
                ]
                
                # Calculate target convergence rate based on domain rules
                base_rate = 0.7
                
                # Adjustments based on features
                base_rate *= max(0.5, 1.0 - (np.log10(condition_number + 1) - 1) * 0.1)  # Condition number effect
                base_rate *= data_quality  # Data quality effect
                base_rate *= max(0.4, 1.0 - (geological_complexity - 1.0) * 0.2)  # Geological complexity effect
                base_rate *= max(0.5, 1.0 - noise_level)  # Noise effect
                
                # Add some randomness
                base_rate += random.gauss(0, 0.05)
                base_rate = max(0.1, min(0.95, base_rate))
                
                X_synthetic.append(features)
                y_synthetic.append(base_rate)
            
            # Train model
            X_synthetic = np.array(X_synthetic)
            y_synthetic = np.array(y_synthetic)
            
            scaler = StandardScaler()
            X_scaled = scaler.fit_transform(X_synthetic)
            
            model = RandomForestRegressor(n_estimators=50, random_state=42)
            model.fit(X_scaled, y_synthetic)
            
            # Make prediction for current context
            current_features = self._extract_context_features_for_ml()
            if current_features is not None:
                current_features_scaled = scaler.transform(current_features.reshape(1, -1))
                prediction = model.predict(current_features_scaled)[0]
                return max(0.1, min(0.95, prediction))
            
            return 0.65
            
        except Exception as e:
            self.logger.warning(f"Simple model training failed: {e}")
            return 0.65
    
    def _simple_stability_calculation(self, history: np.ndarray) -> float:
        """Simple fallback stability calculation"""
        if len(history) < 3:
            return 0.5
        
        # Use coefficient of variation of recent data
        recent_data = history[-min(10, len(history)):]
        mean_val = np.mean(np.abs(recent_data))
        std_val = np.std(recent_data)
        
        if mean_val > 0:
            cv = std_val / mean_val
            stability = 1.0 / (1.0 + cv)
            return max(0.0, min(1.0, stability))
        
        return 0.5
    
    # Advanced supporting methods for stability calculation
    
    def _calculate_eigenvalue_stability(self) -> Dict[str, float]:
        """Calculate stability based on eigenvalue analysis"""
        try:
            from .database_integration import DatabaseIntegration
            from scipy.linalg import eigvals, cond
            
            db_integration = DatabaseIntegration()
            
            # Query recent Jacobian matrices from system analyses
            jacobian_query = """
            SELECT 
                j.jacobian_matrix,
                j.eigenvalues,
                j.condition_number,
                j.spectral_radius,
                j.timestamp,
                s.system_dimension,
                s.analysis_type
            FROM jacobian_analysis j
            JOIN system_analysis s ON j.analysis_id = s.analysis_id
            WHERE j.timestamp >= NOW() - INTERVAL '24 hours'
            AND j.matrix_quality >= 0.8
            ORDER BY j.timestamp DESC
            LIMIT 20;
            """
            
            jacobian_data = db_integration.execute_query_sync(jacobian_query)
            
            if not jacobian_data or len(jacobian_data) < 3:
                return {'score': 0.5, 'confidence': 0.1}
            
            stability_scores = []
            spectral_radii = []
            condition_numbers = []
            
            for data in jacobian_data:
                # Parse eigenvalues
                eigenvalues = json.loads(data['eigenvalues']) if data['eigenvalues'] else []
                spectral_radius = data['spectral_radius'] or 1.0
                condition_number = data['condition_number'] or 1.0
                
                spectral_radii.append(spectral_radius)
                condition_numbers.append(condition_number)
                
                # Stability analysis based on eigenvalues
                if eigenvalues:
                    real_parts = [complex(ev).real if isinstance(ev, str) else float(ev.real if hasattr(ev, 'real') else ev) for ev in eigenvalues]
                    max_real_part = max(real_parts) if real_parts else 0.0
                    
                    # Stability classification
                    if max_real_part < -0.1:
                        stability_score = 0.95
                    elif max_real_part < -0.01:
                        stability_score = 0.8
                    elif max_real_part < 0.01:
                        stability_score = 0.6
                    elif max_real_part < 0.1:
                        stability_score = 0.4
                    else:
                        stability_score = 0.2
                    
                    stability_scores.append(stability_score)
            
            if not stability_scores:
                return {'score': 0.5, 'confidence': 0.1}
            
            # Aggregate stability assessment
            mean_stability = np.mean(stability_scores)
            stability_consistency = 1.0 - np.std(stability_scores)
            mean_spectral_radius = np.mean(spectral_radii)
            mean_condition_number = np.mean(condition_numbers)
            
            # Adjust for spectral radius and condition number
            if mean_spectral_radius < 1.0:
                spectral_bonus = 0.1
            else:
                spectral_penalty = min(0.3, (mean_spectral_radius - 1.0) * 0.2)
                spectral_bonus = -spectral_penalty
            
            condition_penalty = min(0.2, np.log10(mean_condition_number) * 0.05)
            
            final_stability = mean_stability + spectral_bonus - condition_penalty
            final_stability = max(0.0, min(1.0, final_stability))
            
            confidence = min(1.0, len(stability_scores) / 20.0) * stability_consistency
            
            return {
                'score': final_stability,
                'confidence': confidence,
                'mean_spectral_radius': mean_spectral_radius,
                'mean_condition_number': mean_condition_number,
                'stability_consistency': stability_consistency
            }
            
        except Exception as e:
            self.logger.warning(f"Eigenvalue stability calculation failed: {e}")
            return {'score': 0.5, 'confidence': 0.0}
    
    def _calculate_statistical_stability(self) -> Dict[str, float]:
        """Calculate stability using advanced statistical methods"""
        try:
            from .database_integration import DatabaseIntegration
            from scipy import stats
            from sklearn.preprocessing import StandardScaler
            from sklearn.ensemble import IsolationForest
            
            db_integration = DatabaseIntegration()
            
            # Query time series data for statistical analysis
            timeseries_query = """
            SELECT 
                ts.value_series,
                ts.timestamp_series,
                ts.statistical_metrics,
                ts.stationarity_pvalue,
                ts.autocorrelation_function,
                m.measurement_uncertainty,
                m.quality_score
            FROM time_series_analysis ts
            JOIN measurements m ON ts.measurement_id = m.id
            WHERE ts.timestamp >= NOW() - INTERVAL '30 days'
            AND ts.series_length >= 20
            AND m.quality_score >= 0.7
            ORDER BY ts.timestamp DESC
            LIMIT 50;
            """
            
            timeseries_data = db_integration.execute_query_sync(timeseries_query)
            
            if not timeseries_data or len(timeseries_data) < 5:
                return {'score': 0.5, 'confidence': 0.1}
            
            stability_indicators = []
            
            for data in timeseries_data:
                value_series = json.loads(data['value_series']) if data['value_series'] else []
                
                if len(value_series) < 10:
                    continue
                
                series_array = np.array(value_series, dtype=np.float32)
                
                # 1. Stationarity test
                stationarity_pvalue = data['stationarity_pvalue'] or 0.5
                stationarity_score = min(1.0, stationarity_pvalue * 2)  # Higher p-value = more stationary
                
                # 2. Variance stability (using sliding windows)
                window_size = max(5, len(series_array) // 5)
                windowed_variances = []
                
                for i in range(window_size, len(series_array), window_size//2):
                    window = series_array[i-window_size:i]
                    windowed_variances.append(np.var(window))
                
                if len(windowed_variances) >= 3:
                    variance_cv = np.std(windowed_variances) / (np.mean(windowed_variances) + 1e-12)
                    variance_stability = 1.0 / (1.0 + variance_cv)
                else:
                    variance_stability = 0.5
                
                # 3. Outlier analysis
                if len(series_array) >= 10:
                    isolation_forest = IsolationForest(contamination=0.1, random_state=42)
                    outlier_scores = isolation_forest.fit_predict(series_array.reshape(-1, 1))
                    outlier_ratio = np.sum(outlier_scores == -1) / len(outlier_scores)
                    outlier_stability = 1.0 - outlier_ratio
                else:
                    outlier_stability = 0.7
                
                # 4. Trend stability
                if len(series_array) >= 8:
                    x = np.arange(len(series_array))
                    slope, _, r_value, p_value, _ = stats.linregress(x, series_array)
                    trend_significance = 1.0 - p_value if not np.isnan(p_value) else 0.5
                    
                    # Strong trends can indicate instability
                    if abs(slope) > np.std(series_array) / len(series_array):
                        trend_stability = max(0.3, 1.0 - trend_significance)
                    else:
                        trend_stability = 0.8
                else:
                    trend_stability = 0.6
                
                # 5. Autocorrelation stability
                autocorr_data = json.loads(data['autocorrelation_function']) if data['autocorrelation_function'] else []
                if len(autocorr_data) >= 5:
                    # Look for persistent autocorrelation patterns
                    high_autocorr_lags = sum(1 for ac in autocorr_data[:5] if abs(ac) > 0.5)
                    autocorr_stability = max(0.4, 1.0 - high_autocorr_lags * 0.15)
                else:
                    autocorr_stability = 0.6
                
                # Weight by data quality
                quality_weight = data['quality_score'] or 0.7
                
                # Combine indicators
                combined_stability = (
                    stationarity_score * 0.25 +
                    variance_stability * 0.25 +
                    outlier_stability * 0.2 +
                    trend_stability * 0.15 +
                    autocorr_stability * 0.15
                ) * quality_weight
                
                stability_indicators.append({
                    'stability': combined_stability,
                    'quality_weight': quality_weight,
                    'components': {
                        'stationarity': stationarity_score,
                        'variance': variance_stability,
                        'outlier': outlier_stability,
                        'trend': trend_stability,
                        'autocorr': autocorr_stability
                    }
                })
            
            if not stability_indicators:
                return {'score': 0.5, 'confidence': 0.1}
            
            # Aggregate results
            stability_scores = [ind['stability'] for ind in stability_indicators]
            quality_weights = [ind['quality_weight'] for ind in stability_indicators]
            
            # Weighted average
            total_weight = sum(quality_weights)
            if total_weight > 0:
                weighted_stability = sum(score * weight for score, weight in zip(stability_scores, quality_weights)) / total_weight
            else:
                weighted_stability = np.mean(stability_scores)
            
            # Confidence based on sample size and consistency
            consistency = 1.0 - np.std(stability_scores) if len(stability_scores) > 1 else 0.8
            confidence = min(1.0, len(stability_indicators) / 20.0) * consistency
            
            return {
                'score': max(0.0, min(1.0, weighted_stability)),
                'confidence': confidence,
                'sample_size': len(stability_indicators),
                'consistency': consistency
            }
            
        except Exception as e:
            self.logger.warning(f"Statistical stability calculation failed: {e}")
            return {'score': 0.5, 'confidence': 0.0}
    
