            template_lengths = [2, 3, 4, 5]
            tolerances = [0.1, 0.15, 0.2, 0.25, 0.3]
            
            entropy_matrix = np.zeros((len(template_lengths), len(tolerances)))
            
            for i, m in enumerate(template_lengths):
                for j, r_factor in enumerate(tolerances):
                    if n > m * 10:  # Ensure sufficient data
                        r = r_factor * np.std(data)
                        entropy_val = self._robust_sample_entropy(data, m, r)
                        entropy_matrix[i, j] = entropy_val
            
            # 3. Advanced entropy variants
            results['sample_entropy_fuzzy'] = self._fuzzy_sample_entropy(data)
            results['sample_entropy_weighted'] = self._weighted_sample_entropy(data)
            results['sample_entropy_conditional'] = self._conditional_sample_entropy(data)
            results['sample_entropy_refined'] = self._refined_sample_entropy(data)
            
            # 4. Quadratic sample entropy (more robust)
            results['quadratic_sample_entropy'] = self._quadratic_sample_entropy(data)
            
            # 5. Kernel-based sample entropy
            results['kernel_sample_entropy'] = self._kernel_based_sample_entropy(data)
            
            # 6. Approximate entropy (ApEn) for comparison
            results['approximate_entropy'] = self._approximate_entropy(data)
            
            # 7. Cross-sample entropy (if sufficient data)
            if n > 50:
                mid_point = n // 2
                results['cross_sample_entropy'] = self._cross_sample_entropy(
                    data[:mid_point], data[mid_point:]
                )
            
            # Ensemble sample entropy
