    def _adjust_for_confounding(self, data: np.ndarray, scm_analysis: Dict) -> float:
        """Advanced confounding adjustment using multiple causal identification strategies"""
        try:
            from scipy import linalg, stats
            from sklearn.linear_model import LinearRegression, Ridge
            from sklearn.preprocessing import StandardScaler, PolynomialFeatures
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern
            
            if len(data) < 10:
                return self._minimal_confounding_adjustment(data, scm_analysis)
            
            adjustment_methods = {}
            
            # 1. Backdoor criterion-based adjustment
            backdoor_adjustment = self._backdoor_criterion_adjustment(data, scm_analysis)
            adjustment_methods['backdoor'] = backdoor_adjustment
            
            # 2. Front-door criterion when applicable
            frontdoor_adjustment = self._frontdoor_criterion_adjustment(data, scm_analysis)
            adjustment_methods['frontdoor'] = frontdoor_adjustment
            
            # 3. Instrumental variables with geological constraints
            iv_adjustment = self._geological_instrumental_variables(data, scm_analysis)
            adjustment_methods['instrumental_variables'] = iv_adjustment
            
            # 4. Regression discontinuity approximation
            rd_adjustment = self._regression_discontinuity_adjustment(data, scm_analysis)
            adjustment_methods['regression_discontinuity'] = rd_adjustment
            
            # 5. Propensity score-based methods
            ps_adjustment = self._propensity_score_adjustment(data, scm_analysis)
            adjustment_methods['propensity_score'] = ps_adjustment
            
            # 6. Difference-in-differences when temporal structure exists
            did_adjustment = self._difference_in_differences_adjustment(data, scm_analysis)
            adjustment_methods['difference_in_differences'] = did_adjustment
            
            # 7. Causal forests / machine learning confounder adjustment
            ml_adjustment = self._ml_confounder_adjustment(data, scm_analysis)
            adjustment_methods['machine_learning'] = ml_adjustment
            
            # 8. Sensitivity analysis for unmeasured confounding
            sensitivity_bounds = self._unmeasured_confounding_sensitivity(data, scm_analysis)
            
            # Combine adjustments using Bayesian model averaging
            posterior_weights = self._compute_adjustment_posterior_weights(
                adjustment_methods, data, scm_analysis
            )
            
            # Weighted combination of adjustment estimates
            combined_adjustment = sum(
                posterior_weights[method] * adjustment['estimate']
                for method, adjustment in adjustment_methods.items()
                if adjustment['valid']
            )
            
            # Uncertainty quantification
            adjustment_uncertainty = self._compute_adjustment_uncertainty(
                adjustment_methods, posterior_weights, sensitivity_bounds
            )
            
            # Apply geological domain knowledge constraints
            geo_constrained_adjustment = self._apply_geological_constraints(
                combined_adjustment, data, scm_analysis
            )
            
            # Final precision with uncertainty propagation
            final_precision = self._compute_final_precision(
                geo_constrained_adjustment, adjustment_uncertainty, scm_analysis
            )
            
            return min(1.0, max(0.0, final_precision))
            
        except Exception as e:
            self.logger.debug(f"Advanced confounding adjustment failed: {e}")
            return self._robust_confounding_fallback(data, scm_analysis)
    
