    def _fallback_complexity_measure(self, data: np.ndarray) -> float:
        """Fallback complexity measure using basic entropy"""
        try:
            hist, _ = np.histogram(data, bins=min(20, len(data)//3))
            prob = hist / np.sum(hist + 1e-10)
            prob = prob[prob > 0]
            return -np.sum(prob * np.log(prob)) / np.log(len(prob))
        except:
            return 0.5
    
    def _advanced_sample_entropy(self, data: np.ndarray, m: int = 2, r: float = None) -> float:
        """Advanced sample entropy implementation"""
        try:
            from scipy.spatial.distance import pdist, squareform
            N = len(data)
            if N < 10 or r is None:
                return 0.0
            
            def _maxdist(xi, xj, m):
                return max([abs(ua - va) for ua, va in zip(xi, xj)])
            
            def _phi(m):
                patterns = np.array([data[i:i+m] for i in range(N-m+1)])
                C = np.zeros(N-m+1)
                for i in range(N-m+1):
                    template = patterns[i]
                    C[i] = np.sum([_maxdist(template, patterns[j], m) <= r for j in range(N-m+1)])
                return np.mean(np.log(C / (N - m + 1)))
            
            return _phi(m) - _phi(m + 1)
        except:
            return 0.0
    
    def _compute_permutation_entropy(self, data: np.ndarray, order: int = 3) -> float:
        """Compute permutation entropy with improved ordinal pattern analysis"""
        try:
            from itertools import permutations
            from collections import Counter
            
            if len(data) < order:
                return 0.0
            
            # Extract ordinal patterns
            ordinal_patterns = []
            for i in range(len(data) - order + 1):
                segment = data[i:i + order]
                ordinal_pattern = tuple(np.argsort(segment))
                ordinal_patterns.append(ordinal_pattern)
            
            # Count pattern occurrences
            pattern_counts = Counter(ordinal_patterns)
            total_patterns = len(ordinal_patterns)
            
            # Calculate relative frequencies and entropy
            probabilities = [count / total_patterns for count in pattern_counts.values()]
            entropy_val = -np.sum([p * np.log(p) for p in probabilities if p > 0])
            
            # Normalize by maximum possible entropy
            max_entropy = np.log(np.math.factorial(order))
            return entropy_val / max_entropy if max_entropy > 0 else 0.0
            
        except:
            return 0.0
    
    def _compute_topological_complexity_approx(self, data: np.ndarray) -> float:
        """Approximate topological complexity using embedding and distance metrics"""
        try:
            from scipy.spatial.distance import pdist
            from sklearn.neighbors import NearestNeighbors
            
            # Time-delay embedding for topological structure
            embed_dim = min(3, len(data) // 10)
            tau = max(1, len(data) // 20)
            embedded = self._time_delay_embedding(data, embed_dim, tau)
            
            if len(embedded) < 10:
                return 0.3
            
            # Approximate persistence using nearest neighbor distances
            nn = NearestNeighbors(n_neighbors=min(5, len(embedded)))
            nn.fit(embedded)
            distances, _ = nn.kneighbors(embedded)
            
            # Topological complexity from distance distribution
            mean_dist = np.mean(distances[:, 1:])  # Exclude self-distance
            std_dist = np.std(distances[:, 1:])
            complexity = (std_dist / (mean_dist + 1e-10)) * 0.5
            
            return min(1.0, complexity)
        except:
            return 0.3
    
    def _estimate_time_delay(self, data: np.ndarray) -> int:
        """Estimate optimal time delay using mutual information"""
        try:
            max_tau = min(20, len(data) // 5)
            if max_tau < 2:
                return 1
            
            mutual_infos = []
            for tau in range(1, max_tau):
                x = data[:-tau]
                y = data[tau:]
                # Approximate mutual information using correlation
                corr = abs(np.corrcoef(x, y)[0, 1])
                mutual_infos.append(corr)
            
            # Find first local minimum
            first_min = 1
            for i in range(1, len(mutual_infos) - 1):
                if mutual_infos[i] < mutual_infos[i-1] and mutual_infos[i] < mutual_infos[i+1]:
                    first_min = i + 1
                    break
            
            return first_min
        except:
            return 1
    
    def _time_delay_embedding(self, data: np.ndarray, embed_dim: int, tau: int) -> np.ndarray:
        """Perform time-delay embedding"""
        try:
            if len(data) < embed_dim * tau:
                return data.reshape(-1, 1)
            
            embedded = np.zeros((len(data) - (embed_dim - 1) * tau, embed_dim))
            for i in range(embed_dim):
                embedded[:, i] = data[i * tau:len(data) - (embed_dim - 1 - i) * tau]
            
            return embedded
        except:
            return data.reshape(-1, 1)
    
    def _estimate_correlation_dimension(self, embedded: np.ndarray) -> float:
        """Estimate correlation dimension using Grassberger-Procaccia algorithm"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            if len(embedded) < 20:
                return 1.0
            
            # Compute pairwise distances
            distances = pdist(embedded)
            
            # Use a range of radius values
            r_values = np.logspace(-2, 0, 20) * np.std(distances)
            correlations = []
            
            for r in r_values:
                correlation = np.mean(distances < r)
                if correlation > 0:
                    correlations.append(correlation)
                else:
                    correlations.append(1e-10)
            
            # Estimate dimension from slope
            log_r = np.log(r_values[:len(correlations)])
            log_c = np.log(correlations)
            
            # Linear fit to estimate slope
            if len(log_r) > 5:
                slope = np.polyfit(log_r[2:8], log_c[2:8], 1)[0]
                return max(0.5, min(embedded.shape[1], slope))
            else:
                return 1.0
        except:
            return 1.0
    
    def _information_bottleneck_complexity(self, data: np.ndarray) -> float:
        """Compute information bottleneck complexity"""
        try:
            if len(data) < 20:
                return 0.3
            
            # Split data for mutual information estimation
            split_point = len(data) // 2
            X = data[:split_point]
            Y = data[split_point:]
            
            min_len = min(len(X), len(Y))
            X, Y = X[:min_len], Y[:min_len]
            
            # Approximate mutual information using correlation
            if len(X) > 1:
                mi_xy = -0.5 * np.log(max(1e-10, 1 - np.corrcoef(X, Y)[0, 1]**2))
                
                # Information bottleneck score
                compression_ratio = 1.0 - (np.std(X) / (np.mean(np.abs(X)) + 1e-10))
                ib_score = mi_xy * max(0, compression_ratio)
                
                return min(1.0, max(0.0, ib_score))
            else:
                return 0.3
        except:
            return 0.3
    
    def _compute_renyi_entropy_spectrum_complexity(self, data: np.ndarray) -> float:
        """Compute R\u00e9nyi entropy spectrum for complexity analysis"""
        try:
            # Histogram-based probability estimation
            n_bins = min(20, len(data) // 3)
            if n_bins < 2:
                return 0.3
            
            hist, _ = np.histogram(data, bins=n_bins)
            prob = hist / np.sum(hist)
            prob = prob[prob > 0]
            
            if len(prob) < 2:
                return 0.3
            
            # R\u00e9nyi entropies for different alpha values
            alphas = [0.5, 2.0, np.inf]
            renyi_entropies = []
            
            for alpha in alphas:
                if alpha == np.inf:
                    # Min-entropy
                    renyi_ent = -np.log(np.max(prob))
                else:
                    renyi_ent = (1 / (1 - alpha)) * np.log(np.sum(prob**alpha))
                renyi_entropies.append(renyi_ent)
            
            # Complexity from entropy spectrum variation
            entropy_var = np.var(renyi_entropies)
            entropy_mean = np.mean(renyi_entropies)
            
            complexity = entropy_var / (entropy_mean + 1e-10)
            return min(1.0, max(0.0, complexity))
        except:
            return 0.3
    
    def _advanced_lempel_ziv_complexity(self, data: np.ndarray) -> float:
        """Advanced Lempel-Ziv complexity with improved encoding"""
        try:
            # Multi-threshold binary encoding
            thresholds = [np.mean(data), np.median(data), np.percentile(data, 75)]
            lz_values = []
            
            for threshold in thresholds:
                binary_seq = (data > threshold).astype(int)
                lz_val = self._lz_complexity_binary(binary_seq)
                lz_values.append(lz_val)
            
            # Also compute for original symbolic sequence
            if np.std(data) > 0:
                # Convert to symbolic sequence
                n_symbols = min(8, len(np.unique(data)))
                symbols = np.digitize(data, np.linspace(np.min(data), np.max(data), n_symbols))
                symbolic_lz = self._lz_complexity_symbolic(symbols)
                lz_values.append(symbolic_lz)
            
            return np.mean(lz_values) if lz_values else 0.3
        except:
            return 0.3
    
    def _lz_complexity_binary(self, binary_seq: np.ndarray) -> float:
        """Binary Lempel-Ziv complexity"""
        try:
            n = len(binary_seq)
            if n < 2:
                return 0.0
            
            complexity = 0
            i = 0
            
            while i < n:
                substring_length = 1
                
                # Find longest previously seen substring
                while i + substring_length <= n:
                    current_sub = binary_seq[i:i + substring_length]
                    found = False
                    
                    for j in range(i):
                        if j + substring_length <= i:
                            if np.array_equal(binary_seq[j:j + substring_length], current_sub):
                                found = True
                                break
                    
                    if found:
                        substring_length += 1
                    else:
                        break
                
                complexity += 1
                i += substring_length
            
            return complexity / n
        except:
            return 0.0
    
    def _lz_complexity_symbolic(self, symbols: np.ndarray) -> float:
        """Symbolic Lempel-Ziv complexity"""
        try:
            n = len(symbols)
            if n < 2:
                return 0.0
            
            complexity = 0
            i = 0
            vocabulary = {}
            
            while i < n:
                substring_length = 1
                while i + substring_length <= n:
                    current_sub = tuple(symbols[i:i + substring_length])
                    
                    if current_sub in vocabulary:
                        substring_length += 1
                    else:
                        vocabulary[current_sub] = True
                        break
                
                complexity += 1
                i += substring_length
            
            return complexity / n
        except:
            return 0.0
    
    def _compute_adaptive_complexity_weights(self, complexity_components: list, data: np.ndarray) -> np.ndarray:
        """Compute adaptive weights for complexity measures"""
        try:
            n_components = len(complexity_components)
            if n_components == 0:
                return np.array([])
            
            # Base weights
            weights = np.ones(n_components) / n_components
            
            # Adjust based on data characteristics
            data_length = len(data)
            data_variance = np.var(data)
            
            # Weight adjustments
            if data_length < 50:  # Short series - emphasize simpler measures
                weights[0] *= 1.5  # MSE
                weights[-1] *= 0.5  # LZ complexity
            
            if data_variance < 0.01:  # Low variance - emphasize regularity measures
                if n_components > 2:
                    weights[1] *= 1.3  # Permutation entropy
            
            # Normalize
            weights = weights / np.sum(weights)
            return weights
        except:
            return np.ones(len(complexity_components)) / len(complexity_components)
    
    def _geological_complexity_scaling(self, data: np.ndarray, complexity: float) -> float:
        """Apply geological domain-specific complexity scaling"""
        try:
            # Geological time series often have specific characteristics
            # Scale based on data properties that are geologically meaningful
            
            # Temporal persistence scaling
            if len(data) > 10:
                autocorr_1 = abs(np.corrcoef(data[:-1], data[1:])[0, 1])
                persistence_factor = 1.0 + 0.2 * autocorr_1
            else:
                persistence_factor = 1.0
            
            # Magnitude scaling for seismic/geological data
            if np.mean(data) > 0:
                magnitude_factor = 1.0 + 0.1 * np.log10(np.mean(np.abs(data)) + 1)
            else:
                magnitude_factor = 1.0
            
            scaling = persistence_factor * magnitude_factor
            return min(2.0, max(0.5, scaling))
        except:
            return 1.0
    
