    def _analyze_markov_equivalence(self, causal_graph: Dict, data: np.ndarray) -> float:
        """Advanced Markov equivalence class analysis with CPDAG and orientation rules"""
        try:
            if 'adjacency_matrix' not in causal_graph:
                return self._estimate_baseline_equivalence(data)
                
            adj_matrix = causal_graph['adjacency_matrix']
            n = adj_matrix.shape[0]
            
            if n < 3:
                return self._estimate_baseline_equivalence(data)
            
            # 1. Complete Partially Directed Acyclic Graph (CPDAG) construction
            cpdag = self._construct_cpdag(adj_matrix, data)
            
            # 2. V-structure identification with statistical validation
            v_structures = self._identify_validated_v_structures(adj_matrix, data)
            
            # 3. Meek orientation rules application
            oriented_edges = self._apply_meek_rules(cpdag, v_structures)
            
            # 4. Compute identifiability score using multiple metrics
            identifiability_scores = {
                'v_structure_ratio': len(v_structures) / max(1, n * (n-1) * (n-2) / 6),
                'orientation_ratio': len(oriented_edges) / max(1, np.sum(adj_matrix > 0)),
                'essential_edges': self._count_essential_edges(cpdag),
                'reversible_edges': self._count_reversible_edges(cpdag)
            }
            
            # 5. Information-theoretic identifiability measure
            information_gain = self._compute_orientation_information_gain(cpdag, data)
            
            # 6. Bayesian model averaging for equivalence class precision
            bayesian_precision = self._bayesian_equivalence_precision(cpdag, data)
            
            # Combine multiple measures for robust precision estimate
            combined_precision = (
                0.3 * identifiability_scores['v_structure_ratio'] +
                0.25 * identifiability_scores['orientation_ratio'] +
                0.2 * information_gain +
                0.15 * bayesian_precision +
                0.1 * (identifiability_scores['essential_edges'] / max(1, identifiability_scores['essential_edges'] + identifiability_scores['reversible_edges']))
            )
            
            return max(0.1, min(0.95, 0.5 + combined_precision))
            
        except Exception as e:
            self.logger.warning(f"Markov equivalence analysis failed: {e}")
            return self._estimate_baseline_equivalence(data)
    
    def _compute_adaptive_causal_threshold(self, data: np.ndarray) -> float:
        """Advanced adaptive causal threshold using Bayesian mixture models with temporal dependencies."""
        try:
            if len(data) < 10:
                return self._fallback_threshold_estimation(data)
            
            import numpy as np
            from scipy import stats
            from sklearn.mixture import BayesianGaussianMixture
            from sklearn.cluster import DBSCAN
            from scipy.optimize import minimize_scalar
            from scipy.special import logsumexp
            
            # Preprocessing: Handle outliers and temporal autocorrelation
            data_clean = self._preprocess_causal_data(data)
            
            # 1. Bayesian Gaussian Mixture Model with Dirichlet Process Prior
            bgmm = BayesianGaussianMixture(
                n_components=10, 
                covariance_type='full',
                weight_concentration_prior_type='dirichlet_process',
                weight_concentration_prior=0.1,
                mean_precision_prior=1.0,
                degrees_of_freedom_prior=None,
                random_state=42,
                max_iter=500,
                tol=1e-6
            )
            
            X_reshaped = data_clean.reshape(-1, 1)
            bgmm.fit(X_reshaped)
            
            # Extract effective components (non-zero weights)
            effective_weights = bgmm.weights_[bgmm.weights_ > 1e-3]
            effective_means = bgmm.means_[bgmm.weights_ > 1e-3].flatten()
            effective_covariances = bgmm.covariances_[bgmm.weights_ > 1e-3]
            
            if len(effective_means) <= 1:
                return np.median(data_clean)
            
            # 2. Information-Theoretic Threshold Selection
            threshold_candidates = self._generate_threshold_candidates(
                effective_means, effective_covariances, effective_weights
            )
            
            best_threshold = 0.5
            best_score = -np.inf
            
            for threshold in threshold_candidates:
                # Compute mutual information between threshold-based classification and true structure
                mi_score = self._compute_mutual_information_score(data_clean, threshold, bgmm)
                
                # Add temporal consistency penalty
                temporal_penalty = self._compute_temporal_consistency_penalty(data_clean, threshold)
                
                # Combined score: MI - temporal penalty
                combined_score = mi_score - 0.1 * temporal_penalty
                
                if combined_score > best_score:
                    best_score = combined_score
                    best_threshold = threshold
            
            # 3. Bayesian Model Selection with Cross-Validation
            cv_threshold = self._cross_validate_threshold(data_clean, best_threshold)
            
            # 4. Domain-specific adjustment for geological processes
            final_threshold = self._apply_geological_threshold_constraints(
                cv_threshold, data_clean
            )
            
            return np.clip(final_threshold, 0.01, 0.99)
            
        except Exception as e:
            self.logger.warning(f"Advanced threshold computation failed: {e}")
            return self._fallback_threshold_estimation(data)
    
    def _preprocess_causal_data(self, data: np.ndarray) -> np.ndarray:
        """Preprocess data for causal threshold computation."""
        from scipy import signal
        from sklearn.preprocessing import RobustScaler
        
        # Remove temporal autocorrelation
        if len(data) > 5:
            # Apply Hodrick-Prescott filter for trend removal
            try:
                cycle, trend = signal.filtfilt([1, -1], [1, -0.95], data), signal.filtfilt([0.95], [1], data)
                data_detrended = cycle
            except:
                data_detrended = signal.detrend(data)
        else:
            data_detrended = data - np.mean(data)
        
        # Robust scaling
        scaler = RobustScaler()
        data_scaled = scaler.fit_transform(data_detrended.reshape(-1, 1)).flatten()
        
        # Outlier removal using modified Z-score
        median = np.median(data_scaled)
        mad = np.median(np.abs(data_scaled - median))
        modified_z_scores = 0.6745 * (data_scaled - median) / (mad + 1e-10)
        data_clean = data_scaled[np.abs(modified_z_scores) < 3.5]
        
        return data_clean if len(data_clean) > 3 else data_scaled
    
    def _fallback_graph_structure(self, data: np.ndarray) -> Dict:
        """Fallback method for insufficient data cases"""
        n = len(data)
        return {
            'nodes': n, 
            'edges': 0, 
            'density': 0.0,
            'adjacency_matrix': np.zeros((n, n)),
            'structure': 'insufficient_data',
            'confidence_scores': [0.0] * n
        }
    
    def _ensemble_causal_discovery(self, data: np.ndarray) -> Dict:
        """Multi-algorithm ensemble causal discovery with advanced integration"""
        try:
            from .causal_inference_engine import CausalInferenceEngine, CausalAlgorithm
            import networkx as nx
            from scipy import stats
            from sklearn.feature_selection import mutual_info_regression
            
            results = {'algorithms': [], 'graphs': [], 'weights': []}
            
            # Initialize causal inference engine
            causal_engine = CausalInferenceEngine()
            
            # Preprocess data for causal discovery
            data_processed = self._preprocess_for_causal_discovery(data)
            
            algorithms_to_try = [
                ('PC', self._pc_algorithm_discovery),
                ('GES', self._ges_algorithm_discovery),
                ('NOTEARS', self._notears_discovery),
                ('VAR_LINGAM', self._var_lingam_discovery),
                ('NEURAL_CAUSAL', self._neural_causal_discovery)
            ]
            
            for alg_name, alg_func in algorithms_to_try:
                try:
                    graph_result = alg_func(data_processed)
                    if graph_result['success']:
                        results['algorithms'].append(alg_name)
                        results['graphs'].append(graph_result['graph'])
                        results['weights'].append(graph_result['confidence'])
                except Exception as e:
                    self.logger.debug(f"Algorithm {alg_name} failed: {e}")
            
            # Ensemble combination using weighted voting
            if results['graphs']:
                ensemble_graph = self._combine_causal_graphs(results['graphs'], results['weights'])
                results['ensemble_graph'] = ensemble_graph
            else:
                results['ensemble_graph'] = self._create_empty_graph(data.shape[0])
            
            return results
            
        except Exception as e:
            self.logger.warning(f"Ensemble causal discovery failed: {e}")
            return {'algorithms': [], 'graphs': [], 'ensemble_graph': self._create_empty_graph(len(data))}
    
