    def _apply_physics_constraints(self, causal_results: Dict, constraints: List[Dict]) -> Dict:
        """Apply geological physics constraints to causal graph"""
        try:
            if 'ensemble_graph' not in causal_results:
                return causal_results
            
            graph = causal_results['ensemble_graph'].copy()
            adj_matrix = graph.get('adjacency_matrix', np.array([]))
            
            if adj_matrix.size == 0:
                return causal_results
            
            # Apply each constraint type
            for constraint in constraints:
                adj_matrix = self._apply_single_physics_constraint(adj_matrix, constraint)
            
            # Update graph with constrained adjacency matrix
            graph['adjacency_matrix'] = adj_matrix
            graph['edge_count'] = np.sum(adj_matrix > 0)
            graph['density'] = graph['edge_count'] / (adj_matrix.shape[0] * (adj_matrix.shape[0] - 1))
            
            causal_results['physics_constrained_graph'] = graph
            return causal_results
            
        except Exception as e:
            self.logger.warning(f"Physics constraint application failed: {e}")
            return causal_results
    
