    def _assess_interventional_identifiability(self, temporal_graph: Dict, data: np.ndarray) -> Dict:
        """Assess identifiability of causal effects through interventions"""
        try:
            adj_matrix = temporal_graph.get('adjacency_matrix', np.array([]))
            if adj_matrix.size == 0:
                return {'identifiable_effects': [], 'intervention_targets': []}
            
            n_vars = adj_matrix.shape[0]
            
            # Identify valid intervention targets (no incoming edges in true graph)
            intervention_targets = []
            for i in range(n_vars):
                if np.sum(adj_matrix[:, i]) < np.mean(np.sum(adj_matrix, axis=0)):  # Low incoming degree
                    intervention_targets.append(i)
            
            # Assess identifiability using do-calculus principles
            identifiable_effects = []
            for target in intervention_targets:
                for outcome in range(n_vars):
                    if target != outcome:
                        identifiability = self._assess_causal_effect_identifiability(
                            adj_matrix, target, outcome
                        )
                        if identifiability['identifiable']:
                            identifiable_effects.append({
                                'intervention': target,
                                'outcome': outcome,
                                'method': identifiability['method'],
                                'confidence': identifiability['confidence']
                            })
            
            return {
                'identifiable_effects': identifiable_effects,
                'intervention_targets': intervention_targets,
                'total_possible_effects': n_vars * (n_vars - 1),
                'identifiability_ratio': len(identifiable_effects) / (n_vars * (n_vars - 1))
            }
            
        except Exception as e:
            self.logger.warning(f"Interventional identifiability assessment failed: {e}")
            return {'identifiable_effects': [], 'intervention_targets': []}
    
    def _estimate_baseline_equivalence(self, data: np.ndarray) -> float:
        """Estimate baseline equivalence precision from data properties"""
        try:
            # Use data dimensionality and sample size for baseline estimate
            n_samples = len(data) if data.ndim == 1 else data.shape[1]
            n_vars = 1 if data.ndim == 1 else data.shape[0]
            
            # Statistical power-based estimate
            power_factor = min(1.0, n_samples / (n_vars * 10))
            complexity_penalty = max(0.1, 1.0 - n_vars / 20)
            
            baseline = 0.3 + 0.4 * power_factor + 0.3 * complexity_penalty
            return max(0.1, min(0.8, baseline))
        except:
            return 0.4
    
    def _construct_cpdag(self, adj_matrix: np.ndarray, data: np.ndarray) -> Dict:
        """Construct Complete Partially Directed Acyclic Graph"""
        try:
            n = adj_matrix.shape[0]
            
            # Start with skeleton (undirected graph)
            skeleton = (adj_matrix + adj_matrix.T) > 0
            
            # Identify v-structures using conditional independence tests
            v_structures = self._identify_validated_v_structures(adj_matrix, data)
            
            # Initialize CPDAG with v-structures oriented
            directed = np.zeros_like(adj_matrix, dtype=bool)
            undirected = skeleton.copy()
            
            for v_struct in v_structures:
                i, j, k = v_struct['nodes']
                if skeleton[i, j] and skeleton[k, j]:
                    directed[i, j] = True
                    directed[k, j] = True
                    undirected[i, j] = False
                    undirected[j, i] = False
                    undirected[k, j] = False
                    undirected[j, k] = False
            
            # Apply Meek orientation rules
            directed, undirected = self._apply_meek_orientation_rules(directed, undirected)
            
            return {
                'directed': directed,
                'undirected': undirected,
                'v_structures': v_structures
            }
        except Exception as e:
            self.logger.warning(f"CPDAG construction failed: {e}")
            return {
                'directed': np.zeros_like(adj_matrix, dtype=bool),
                'undirected': np.zeros_like(adj_matrix, dtype=bool),
                'v_structures': []
            }
    
    def _identify_validated_v_structures(self, adj_matrix: np.ndarray, data: np.ndarray) -> List[Dict]:
        """Identify and statistically validate v-structures (colliders)"""
        try:
            from scipy import stats
            from sklearn.feature_selection import mutual_info_regression
            
            n = adj_matrix.shape[0]
            v_structures = []
            
            for j in range(n):
                for i in range(n):
                    for k in range(i+1, n):
                        if i != j and k != j:
                            # Check for i -> j <- k pattern (i and k not connected)
                            if adj_matrix[i, j] > 0 and adj_matrix[k, j] > 0 and adj_matrix[i, k] == 0:
                                # Statistical validation using conditional independence
                                validation = self._validate_v_structure(data, i, j, k)
                                if validation['is_valid']:
                                    v_structures.append({
                                        'nodes': (i, j, k),
                                        'confidence': validation['confidence'],
                                        'test_statistic': validation['statistic'],
                                        'p_value': validation['p_value']
                                    })
            
            return v_structures
        except Exception as e:
            self.logger.warning(f"V-structure identification failed: {e}")
            return []
    
    def _apply_meek_orientation_rules(self, directed: np.ndarray, undirected: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:
        """Apply Meek orientation rules for CPDAG completion"""
        try:
            n = directed.shape[0]
            changed = True
            
            while changed:
                changed = False
                
                # Rule 1: Orient i-j into i->j whenever there is k->i and no edge k-j
                for i in range(n):
                    for j in range(n):
                        if undirected[i, j]:
                            for k in range(n):
                                if k != i and k != j and directed[k, i] and not (directed[k, j] or undirected[k, j]):
                                    directed[i, j] = True
                                    undirected[i, j] = False
                                    undirected[j, i] = False
                                    changed = True
                
                # Rule 2: Orient i-j into i->j whenever there is i->k->j and i-j
                for i in range(n):
                    for j in range(n):
                        if undirected[i, j]:
                            for k in range(n):
                                if k != i and k != j and directed[i, k] and directed[k, j]:
                                    directed[i, j] = True
                                    undirected[i, j] = False
                                    undirected[j, i] = False
                                    changed = True
                
                # Rule 3: Orient i-j into i->j whenever there are i-k->j and i-l->j with k-l
                for i in range(n):
                    for j in range(n):
                        if undirected[i, j]:
                            for k in range(n):
                                for l in range(k+1, n):
                                    if (k != i and k != j and l != i and l != j and
                                        undirected[i, k] and directed[k, j] and
                                        undirected[i, l] and directed[l, j] and
                                        not undirected[k, l] and not directed[k, l] and not directed[l, k]):
                                        directed[i, j] = True
                                        undirected[i, j] = False
                                        undirected[j, i] = False
                                        changed = True
            
            return directed, undirected
        except Exception as e:
            self.logger.warning(f"Meek rule application failed: {e}")
            return directed, undirected
    
    def _compute_orientation_information_gain(self, cpdag: Dict, data: np.ndarray) -> float:
        """Compute information gain from edge orientations"""
        try:
            directed = cpdag.get('directed', np.array([]))
            undirected = cpdag.get('undirected', np.array([]))
            
            if directed.size == 0:
                return 0.0
            
            total_edges = np.sum(directed) + np.sum(undirected) // 2
            oriented_edges = np.sum(directed)
            
            if total_edges == 0:
                return 0.0
            
            # Information-theoretic measure of orientation certainty
            orientation_ratio = oriented_edges / total_edges
            information_gain = -orientation_ratio * np.log2(orientation_ratio + 1e-10) - (1 - orientation_ratio) * np.log2(1 - orientation_ratio + 1e-10)
            
            return 1.0 - information_gain  # Higher is better
        except:
            return 0.0
    
    def _bayesian_equivalence_precision(self, cpdag: Dict, data: np.ndarray) -> float:
        """Bayesian model averaging for equivalence class precision"""
        try:
            from scipy import stats
            from sklearn.preprocessing import StandardScaler
            
            # Simplified Bayesian approach using BIC approximation
            directed = cpdag.get('directed', np.array([]))
            if directed.size == 0:
                return 0.5
            
            n_edges = np.sum(directed)
            n_samples = len(data) if data.ndim == 1 else data.shape[1]
            n_vars = directed.shape[0]
            
            # BIC-based model selection approximation
            likelihood_term = n_samples * 0.1  # Simplified likelihood
            penalty_term = n_edges * np.log(n_samples)
            
            bic_score = likelihood_term - penalty_term
            precision = 1.0 / (1.0 + np.exp(-bic_score / n_samples))  # Sigmoid transform
            
            return max(0.1, min(0.9, precision))
        except:
            return 0.5
    
