    def _compute_temporal_consistency_penalty(self, data, threshold):
        """Compute penalty for temporal inconsistency in threshold application."""
        if len(data) < 3:
            return 0.0
        
        # Apply threshold to get binary sequence
        binary_seq = (data > threshold).astype(int)
        
        # Count transitions
        transitions = np.sum(np.diff(binary_seq) != 0)
        
        # Penalty is proportional to transition rate
        transition_rate = transitions / (len(binary_seq) - 1)
        
        return transition_rate
    
    def _cross_validate_threshold(self, data, initial_threshold):
        """Cross-validate threshold using time series splits."""
        if len(data) < 20:
            return initial_threshold
        
        from sklearn.model_selection import TimeSeriesSplit
        
        tscv = TimeSeriesSplit(n_splits=5)
        scores = []
        
        for train_idx, test_idx in tscv.split(data):
            train_data = data[train_idx]
            test_data = data[test_idx]
            
            # Optimize threshold on training data
            def objective(threshold):
                binary_train = (train_data > threshold).astype(int)
                binary_test = (test_data > threshold).astype(int)
                
                # Consistency score between train and test
                train_ratio = np.mean(binary_train)
                test_ratio = np.mean(binary_test)
                
                return abs(train_ratio - test_ratio)
            
            result = minimize_scalar(objective, bounds=(np.min(data), np.max(data)), method='bounded')
            scores.append(-result.fun)  # Negative because we want to minimize
        
        # Return threshold if cross-validation is consistent
        if np.std(scores) < 0.1:  # Low variance in scores
            return initial_threshold
        else:
            return np.median(data)  # Fallback
    
