            robust_scaler = RobustScaler().fit(normal_data.reshape(-1, 1))
            
            # Multi-objective constraint optimization
            def constraint_objective(x):
                score = 0.0
                
                # Statistical robustness penalty
                stat_bounds = constraint_framework['statistical_robustness']
                if not (stat_bounds['lower'] <= x <= stat_bounds['upper']):
                    score += 1000.0 * min(abs(x - stat_bounds['lower']), abs(x - stat_bounds['upper']))
                
                # Geological domain penalty
                geo_bounds = constraint_framework['geological_domain_bounds']
                if not (geo_bounds['lower'] <= x <= geo_bounds['upper']):
                    score += 500.0 * min(abs(x - geo_bounds['lower']), abs(x - geo_bounds['upper']))
                
                # Physical feasibility penalty
                phys_bounds = constraint_framework['physical_feasibility_bounds']
