    def _ultimate_statistical_fallback(self, threshold, data):
        """Ultimate statistical fallback using robust statistical methods."""
        try:
            from scipy.stats import trim_mean, scoreatpercentile
            from scipy.robust import mad
            
            if len(data) == 0:
                return 0.5
            
            # Robust statistical measures
            median = np.median(data)
            trimmed_mean = trim_mean(data, 0.1)  # 10% trimmed mean
            mad_estimate = mad(data)  # Median absolute deviation
            
            # Interquartile range bounds
            q25 = scoreatpercentile(data, 25)
            q75 = scoreatpercentile(data, 75)
            iqr = q75 - q25
            
            # Robust bounds using Tukey's fences
            lower_fence = q25 - 1.5 * iqr
            upper_fence = q75 + 1.5 * iqr
            
            # Constrain threshold within robust bounds
            constrained_threshold = np.clip(threshold, lower_fence, upper_fence)
            
            # Further refinement using trimmed statistics
            if abs(constrained_threshold - median) > 2 * mad_estimate:
                constrained_threshold = median + np.sign(constrained_threshold - median) * mad_estimate
            
            return constrained_threshold
            
        except Exception:
            return np.median(data) if len(data) > 0 else 0.5

    def _compute_statistical_robustness_constraints(self, data):
        """Compute statistical robustness constraints using advanced robust statistics."""
        try:
            from scipy.stats import trim_mean, scoreatpercentile, iqr
            from scipy.robust import mad
            
            if len(data) == 0:
                return {'lower': 0.0, 'upper': 1.0}
            
            # Multiple robust estimators
            median_val = np.median(data)
            mad_val = mad(data)
            trimmed_mean_val = trim_mean(data, 0.1)
            iqr_val = iqr(data)
            
            # Robust bounds computation
            lower_bound = median_val - 2.5 * mad_val
            upper_bound = median_val + 2.5 * mad_val
            
            # Tukey's fences as secondary bounds
            q25, q75 = scoreatpercentile(data, [25, 75])
            tukey_lower = q25 - 1.5 * iqr_val
            tukey_upper = q75 + 1.5 * iqr_val
            
            # Conservative bounds selection
            final_lower = max(lower_bound, tukey_lower, np.min(data))
            final_upper = min(upper_bound, tukey_upper, np.max(data))
            
            return {
                'lower': final_lower,
                'upper': final_upper,
                'median': median_val,
                'mad': mad_val,
                'trimmed_mean': trimmed_mean_val,
                'robustness_score': min(1.0, mad_val / (abs(median_val) + 1e-10))
            }
            
        except Exception:
            return {'lower': np.min(data) if len(data) > 0 else 0.0, 
                    'upper': np.max(data) if len(data) > 0 else 1.0}

    def _compute_geological_domain_bounds(self, data, geological_context, physical_constraints):
        """Compute geological domain-specific bounds using expert knowledge."""
        try:
            # Default geological bounds
            geological_bounds = {
                'volcanic': {'lower': 0.1, 'upper': 0.9},
                'sedimentary': {'lower': 0.2, 'upper': 0.8},
                'metamorphic': {'lower': 0.15, 'upper': 0.85},
                'igneous': {'lower': 0.1, 'upper': 0.9},
                'hydrothermal': {'lower': 0.05, 'upper': 0.95}
            }
            
            # Extract geological regime
            regime = geological_context.get('geological_regime', 'unknown') if geological_context else 'unknown'
            lithology = geological_context.get('lithology', 'unknown') if geological_context else 'unknown'
            
            # Select appropriate bounds
            if regime in geological_bounds:
                base_bounds = geological_bounds[regime]
            elif lithology in geological_bounds:
                base_bounds = geological_bounds[lithology]
            else:
                # Default bounds based on data distribution
                base_bounds = {'lower': np.percentile(data, 10), 'upper': np.percentile(data, 90)}
            
            # Adjust bounds based on physical constraints
            if physical_constraints:
                temperature = physical_constraints.get('temperature', 298.15)
                pressure = physical_constraints.get('pressure', 101325.0)
                
                # Temperature-dependent adjustments
                if temperature > 1000:  # High-temperature processes
                    base_bounds['lower'] *= 0.8
                    base_bounds['upper'] *= 1.1
                elif temperature < 273:  # Low-temperature processes
                    base_bounds['lower'] *= 1.2
                    base_bounds['upper'] *= 0.9
                
                # Pressure-dependent adjustments
                if pressure > 1e8:  # High-pressure conditions
                    base_bounds['lower'] *= 0.9
                    base_bounds['upper'] *= 1.05
            
            return {
                'lower': max(base_bounds['lower'], np.min(data) if len(data) > 0 else 0),
                'upper': min(base_bounds['upper'], np.max(data) if len(data) > 0 else 1),
                'regime': regime,
                'lithology': lithology
            }
            
        except Exception:
            return {'lower': np.min(data) if len(data) > 0 else 0.0,
                    'upper': np.max(data) if len(data) > 0 else 1.0}

