    async def _multi_method_phase_directionality(self, phase_diff: np.ndarray, 
                                               frequencies: np.ndarray,
                                               signal1: np.ndarray, 
                                               signal2: np.ndarray) -> Dict:
        """Multi-method phase-based directionality analysis with advanced algorithms."""
        try:
            phase_results = {
                'classical_phase_analysis': {},
                'circular_statistics_analysis': {},
                'instantaneous_phase_analysis': {},
                'phase_coherence_analysis': {},
                'phase_coupling_analysis': {}
            }
            
            # 1. Classical Phase Analysis (Enhanced)
            directionality_index = np.zeros(len(frequencies))
            phase_consistency = np.zeros(len(frequencies))
            
            for i, freq in enumerate(frequencies):
                phase_row = phase_diff[i, :]
                
                # Enhanced directionality with consistency measures
                sin_phase = np.sin(phase_row)
                cos_phase = np.cos(phase_row)
                
                directionality_index[i] = -np.mean(sin_phase)  # Negative means signal1 leads
                phase_consistency[i] = np.sqrt(np.mean(cos_phase)**2 + np.mean(sin_phase)**2)
                
            phase_results['classical_phase_analysis'] = {
                'directionality_index': directionality_index,
                'phase_consistency': phase_consistency,
                'mean_phase_difference': np.mean(phase_diff, axis=1),
                'phase_stability': np.std(phase_diff, axis=1)
            }
            
            # 2. Circular Statistics Analysis
            circular_results = await self._circular_statistics_phase_analysis(phase_diff, frequencies)
            phase_results['circular_statistics_analysis'] = circular_results
            
            # 3. Instantaneous Phase Analysis
            instantaneous_results = await self._instantaneous_phase_analysis(phase_diff, signal1, signal2)
            phase_results['instantaneous_phase_analysis'] = instantaneous_results
            
            # 4. Phase Coherence Analysis
            coherence_results = await self._phase_coherence_analysis(phase_diff, frequencies)
            phase_results['phase_coherence_analysis'] = coherence_results
            
            # 5. Phase Coupling Analysis
            coupling_results = await self._phase_coupling_analysis(phase_diff, frequencies)
            phase_results['phase_coupling_analysis'] = coupling_results
            
            return phase_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'multi_method_phase_directionality'}

    async def _circular_statistics_phase_analysis(self, phase_diff: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Advanced circular statistics for phase analysis."""
        try:
            import scipy.stats as stats
            
            circular_results = {}
            
            for i, freq in enumerate(frequencies):
                phase_row = phase_diff[i, :]
                
                # Circular mean and variance
                circular_mean = np.arctan2(np.mean(np.sin(phase_row)), np.mean(np.cos(phase_row)))
                circular_var = 1 - np.sqrt(np.mean(np.cos(phase_row))**2 + np.mean(np.sin(phase_row))**2)
                
                # Rayleigh test for uniformity
                rayleigh_stat = len(phase_row) * (np.mean(np.cos(phase_row))**2 + np.mean(np.sin(phase_row))**2)
                rayleigh_pvalue = np.exp(-rayleigh_stat) * (1 + (2*rayleigh_stat - rayleigh_stat**2)/(4*len(phase_row)))
                
                # Watson's U² test for circular uniformity
                phase_sorted = np.sort(phase_row % (2*np.pi))
                uniform_expected = np.linspace(0, 2*np.pi, len(phase_row), endpoint=False)
                watson_stat = np.sum((phase_sorted - uniform_expected)**2)
                
                circular_results[f'freq_{freq:.4f}'] = {
                    'circular_mean': circular_mean,
                    'circular_variance': circular_var,
                    'rayleigh_statistic': rayleigh_stat,
                    'rayleigh_pvalue': rayleigh_pvalue,
                    'watson_statistic': watson_stat,
                    'phase_concentration': 1 - circular_var,
                    'preferred_direction': circular_mean
                }
            
            return circular_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'circular_statistics_phase_analysis'}

    async def _instantaneous_phase_analysis(self, phase_diff: np.ndarray, 
                                          signal1: np.ndarray, signal2: np.ndarray) -> Dict:
        """Instantaneous phase analysis with Hilbert transform."""
        try:
            from scipy.signal import hilbert
            
            # Hilbert transform for instantaneous phase
            analytic1 = hilbert(signal1)
            analytic2 = hilbert(signal2)
            
            inst_phase1 = np.unwrap(np.angle(analytic1))
            inst_phase2 = np.unwrap(np.angle(analytic2))
            
            inst_phase_diff = inst_phase1 - inst_phase2
            
            # Phase synchronization index
            sync_index = np.abs(np.mean(np.exp(1j * inst_phase_diff)))
            
            # Phase locking value
            plv = np.abs(np.mean(np.exp(1j * inst_phase_diff)))
            
            # Instantaneous frequency
            inst_freq1 = np.diff(inst_phase1) / (2.0 * np.pi)
            inst_freq2 = np.diff(inst_phase2) / (2.0 * np.pi)
            
            return {
                'instantaneous_phase_difference': inst_phase_diff,
                'phase_synchronization_index': sync_index,
                'phase_locking_value': plv,
                'instantaneous_frequency_1': inst_freq1,
                'instantaneous_frequency_2': inst_freq2,
                'mean_phase_difference': np.mean(inst_phase_diff),
                'phase_difference_variance': np.var(inst_phase_diff)
            }
            
        except Exception as e:
            return {'error': str(e), 'method': 'instantaneous_phase_analysis'}

    async def _phase_coherence_analysis(self, phase_diff: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Advanced phase coherence analysis."""
        try:
            coherence_results = {}
            
            for i, freq in enumerate(frequencies):
                phase_row = phase_diff[i, :]
                
                # Compute coherence at this frequency
                coherence = np.abs(np.mean(np.exp(1j * phase_row)))
                
                # Phase dispersion
                phase_dispersion = np.std(phase_row)
                
                # Coherence strength categories
                if coherence > 0.8:
                    strength = 'very_strong'
                elif coherence > 0.6:
                    strength = 'strong'
                elif coherence > 0.4:
                    strength = 'moderate'
                elif coherence > 0.2:
                    strength = 'weak'
                else:
                    strength = 'very_weak'
                
                coherence_results[f'freq_{freq:.4f}'] = {
                    'coherence_magnitude': coherence,
                    'phase_dispersion': phase_dispersion,
                    'coherence_strength': strength,
                    'phase_stability': 1.0 / (1.0 + phase_dispersion)
                }
            
            return coherence_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'phase_coherence_analysis'}

    async def _phase_coupling_analysis(self, phase_diff: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Advanced phase coupling analysis with cross-frequency interactions."""
        try:
            coupling_results = {
                'within_frequency_coupling': {},
                'cross_frequency_coupling': {},
                'phase_amplitude_coupling': {}
            }
            
            # Within-frequency coupling strength
            for i, freq in enumerate(frequencies):
                phase_row = phase_diff[i, :]
                
                # Phase coupling strength
                coupling_strength = np.abs(np.mean(np.exp(1j * phase_row)))
                
                # Phase lag consistency
                phase_lags = np.diff(phase_row)
                lag_consistency = 1.0 / (1.0 + np.std(phase_lags))
                
                coupling_results['within_frequency_coupling'][f'freq_{freq:.4f}'] = {
                    'coupling_strength': coupling_strength,
                    'phase_lag_consistency': lag_consistency,
                    'mean_phase_lag': np.mean(phase_lags),
                    'phase_coupling_quality': coupling_strength * lag_consistency
                }
            
            # Cross-frequency coupling analysis
            for i in range(len(frequencies) - 1):
                for j in range(i + 1, len(frequencies)):
                    freq1, freq2 = frequencies[i], frequencies[j]
                    phase1, phase2 = phase_diff[i, :], phase_diff[j, :]
                    
                    # Cross-frequency phase coupling
                    cross_coupling = np.abs(np.mean(np.exp(1j * (phase1 - phase2))))
                    
                    coupling_results['cross_frequency_coupling'][f'freq_{freq1:.4f}_vs_{freq2:.4f}'] = {
                        'cross_coupling_strength': cross_coupling,
                        'frequency_ratio': freq2 / freq1 if freq1 > 0 else np.inf
                    }
            
            return coupling_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'phase_coupling_analysis'}

    async def _coherence_based_directional_analysis(self, signal1: np.ndarray, signal2: np.ndarray,
                                                  cross_wavelet: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Advanced coherence-based directional analysis."""
        try:
            from scipy import signal as scipy_signal
            
            # Compute cross-spectral density and coherence
            f, Cxy = scipy_signal.coherence(signal1, signal2, nperseg=min(len(signal1)//4, 256))
            
            # Compute cross power spectral density
            f_csd, Pxy = scipy_signal.csd(signal1, signal2, nperseg=min(len(signal1)//4, 256))
            
            # Advanced coherence metrics
            coherence_results = {
                'coherence_spectrum': Cxy,
                'cross_power_spectrum': Pxy,
                'frequency_grid': f,
                'coherence_based_directionality': {},
                'partial_coherence_analysis': {},
                'coherence_significance_test': {}
            }
            
            # Coherence-based directionality at each frequency
            for i, freq in enumerate(frequencies):
                # Find closest frequency in coherence spectrum
                freq_idx = np.argmin(np.abs(f - freq))
                
                coherence_val = Cxy[freq_idx] if freq_idx < len(Cxy) else 0
                cross_power = Pxy[freq_idx] if freq_idx < len(Pxy) else 0+0j
                
                # Directionality from cross-power phase
                cross_phase = np.angle(cross_power)
                coherence_directionality = -np.sin(cross_phase)  # Negative means signal1 leads
                
                coherence_results['coherence_based_directionality'][f'freq_{freq:.4f}'] = {
                    'coherence_magnitude': coherence_val,
                    'cross_power_phase': cross_phase,
                    'coherence_directionality': coherence_directionality,
                    'directionality_confidence': coherence_val,
                    'significant_coherence': coherence_val > 0.5
                }
            
            return coherence_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'coherence_based_directional_analysis'}

    async def _granger_causality_directional_analysis(self, signal1: np.ndarray, signal2: np.ndarray,
                                                    frequencies: np.ndarray) -> Dict:
        """Advanced Granger causality analysis for directionality."""
        try:
            from statsmodels.tsa.stattools import grangercausalitytests
            from sklearn.linear_model import LinearRegression
            
            granger_results = {
                'granger_causality_12': {},  # signal1 -> signal2
                'granger_causality_21': {},  # signal2 -> signal1
                'bidirectional_granger': {},
                'optimal_lag_analysis': {}
            }
            
            # Prepare data for Granger causality
            max_lag = min(10, len(signal1) // 10)  # Reasonable lag limit
            
            try:
                # Test different lags
                best_lag = 1
                best_pvalue = 1.0
                
                for lag in range(1, max_lag + 1):
                    try:
                        # Create lagged data
                        data = np.column_stack([signal2[lag:], signal1[:-lag]])
                        
                        # Simple F-test for causality
                        X_restricted = signal2[lag-1:-1].reshape(-1, 1)  # Only past of signal2
                        X_full = np.column_stack([signal2[lag-1:-1], signal1[:-lag]])  # Past of both signals
                        y = signal2[lag:]
                        
                        # Fit models
                        reg_restricted = LinearRegression().fit(X_restricted, y)
                        reg_full = LinearRegression().fit(X_full, y)
                        
                        # F-test for causality
                        rss_restricted = np.sum((y - reg_restricted.predict(X_restricted))**2)
                        rss_full = np.sum((y - reg_full.predict(X_full))**2)
                        
                        if rss_restricted > 0:
                            f_stat = ((rss_restricted - rss_full) / 1) / (rss_full / (len(y) - 2))
                            # Approximate p-value
                            from scipy.stats import f as f_dist
                            pvalue = 1 - f_dist.cdf(f_stat, 1, len(y) - 2)
                            
                            if pvalue < best_pvalue:
                                best_lag = lag
                                best_pvalue = pvalue
                        
                    except Exception:
                        continue
                
                granger_results['optimal_lag_analysis'] = {
                    'optimal_lag': best_lag,
                    'best_pvalue': best_pvalue,
                    'causality_detected': best_pvalue < 0.05
                }
                
                # Granger causality in both directions with optimal lag
                if best_lag > 0:
                    # Direction 1->2
                    X_12 = np.column_stack([signal2[best_lag-1:-1], signal1[:-best_lag]])
                    y_12 = signal2[best_lag:]
                    reg_12_full = LinearRegression().fit(X_12, y_12)
                    reg_12_restricted = LinearRegression().fit(signal2[best_lag-1:-1].reshape(-1, 1), y_12)
                    
                    rss_12_full = np.sum((y_12 - reg_12_full.predict(X_12))**2)
                    rss_12_restricted = np.sum((y_12 - reg_12_restricted.predict(signal2[best_lag-1:-1].reshape(-1, 1)))**2)
                    
                    granger_12_strength = (rss_12_restricted - rss_12_full) / rss_12_restricted if rss_12_restricted > 0 else 0
                    
                    # Direction 2->1
                    X_21 = np.column_stack([signal1[best_lag-1:-1], signal2[:-best_lag]])
                    y_21 = signal1[best_lag:]
                    reg_21_full = LinearRegression().fit(X_21, y_21)
                    reg_21_restricted = LinearRegression().fit(signal1[best_lag-1:-1].reshape(-1, 1), y_21)
                    
                    rss_21_full = np.sum((y_21 - reg_21_full.predict(X_21))**2)
                    rss_21_restricted = np.sum((y_21 - reg_21_restricted.predict(signal1[best_lag-1:-1].reshape(-1, 1)))**2)
                    
                    granger_21_strength = (rss_21_restricted - rss_21_full) / rss_21_restricted if rss_21_restricted > 0 else 0
                    
                    granger_results['granger_causality_12'] = {
                        'causality_strength': granger_12_strength,
                        'direction': 'signal1_causes_signal2',
                        'lag': best_lag
                    }
                    
                    granger_results['granger_causality_21'] = {
                        'causality_strength': granger_21_strength,
                        'direction': 'signal2_causes_signal1',
                        'lag': best_lag
                    }
                    
                    granger_results['bidirectional_granger'] = {
                        'net_causality': granger_12_strength - granger_21_strength,
                        'total_causality': granger_12_strength + granger_21_strength,
                        'dominant_direction': 'signal1_leads' if granger_12_strength > granger_21_strength else 'signal2_leads'
                    }
                
            except Exception as e:
                granger_results['error'] = f"Granger causality computation failed: {str(e)}"
            
            return granger_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'granger_causality_directional_analysis'}

    async def _advanced_lead_lag_analysis(self, signal1: np.ndarray, signal2: np.ndarray,
                                        cross_wavelet: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Advanced lead-lag analysis with optimal delay estimation."""
        try:
            leadlag_results = {
                'cross_correlation_analysis': {},
                'optimal_delay_estimation': {},
                'frequency_dependent_delays': {},
                'delay_stability_analysis': {}
            }
            
            # Cross-correlation analysis
            from scipy.signal import correlate
            correlation = correlate(signal1, signal2, mode='full')
            lags = np.arange(-len(signal2)+1, len(signal1))
            
            # Find optimal delay
            max_corr_idx = np.argmax(np.abs(correlation))
            optimal_delay = lags[max_corr_idx]
            max_correlation = correlation[max_corr_idx]
            
            leadlag_results['cross_correlation_analysis'] = {
                'correlation_function': correlation,
                'lag_vector': lags,
                'optimal_delay': optimal_delay,
                'maximum_correlation': max_correlation,
                'delay_direction': 'signal1_leads' if optimal_delay > 0 else 'signal2_leads'
            }
            
            # Frequency-dependent delay analysis
            for i, freq in enumerate(frequencies):
                # Phase-based delay estimation at this frequency
                phase_diff_freq = np.angle(cross_wavelet[i, :])
                mean_phase_diff = np.mean(phase_diff_freq)
                
                # Convert phase to time delay
                if freq > 0:
                    time_delay = mean_phase_diff / (2 * np.pi * freq)
                else:
                    time_delay = 0
                
                # Phase stability
                phase_stability = 1.0 / (1.0 + np.std(phase_diff_freq))
                
                leadlag_results['frequency_dependent_delays'][f'freq_{freq:.4f}'] = {
                    'time_delay_seconds': time_delay,
                    'phase_delay_radians': mean_phase_diff,
                    'phase_stability': phase_stability,
                    'delay_confidence': phase_stability,
                    'leading_signal': 'signal1' if time_delay < 0 else 'signal2'
                }
            
            # Delay stability analysis across frequencies
            delays = [result['time_delay_seconds'] for result in leadlag_results['frequency_dependent_delays'].values()]
            if delays:
                leadlag_results['delay_stability_analysis'] = {
                    'mean_delay': np.mean(delays),
                    'delay_variance': np.var(delays),
                    'delay_consistency': 1.0 / (1.0 + np.std(delays)),
                    'frequency_dependent_stability': np.std(delays) < 0.1
                }
            
            return leadlag_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'advanced_lead_lag_analysis'}

    async def _frequency_dependent_causality_analysis(self, phase_diff: np.ndarray,
                                                    cross_wavelet: np.ndarray, 
                                                    frequencies: np.ndarray) -> Dict:
        """Frequency-dependent causality mapping."""
        try:
            causality_map = {}
            
            for i, freq in enumerate(frequencies):
                # Phase-based causality at this frequency
                phase_row = phase_diff[i, :]
                cross_power_row = cross_wavelet[i, :]
                
                # Causality strength based on phase consistency
                phase_consistency = np.abs(np.mean(np.exp(1j * phase_row)))
                
                # Directionality index
                directionality = -np.mean(np.sin(phase_row))
                
                # Cross-power magnitude
                cross_power_magnitude = np.mean(np.abs(cross_power_row))
                
                # Combined causality measure
                causality_strength = phase_consistency * cross_power_magnitude
                
                # Frequency band classification
                if freq < 0.1:
                    freq_band = 'ultra_low'
                elif freq < 1.0:
                    freq_band = 'low'
                elif freq < 10.0:
                    freq_band = 'medium'
                else:
                    freq_band = 'high'
                
                causality_map[f'freq_{freq:.4f}'] = {
                    'frequency_hz': freq,
                    'frequency_band': freq_band,
                    'causality_strength': causality_strength,
                    'directionality_index': directionality,
                    'phase_consistency': phase_consistency,
                    'cross_power_magnitude': cross_power_magnitude,
                    'dominant_direction': 'signal1_leads' if directionality < -0.1 else 'signal2_leads' if directionality > 0.1 else 'bidirectional'
                }
            
            return {
                'frequency_causality_map': causality_map,
                'causality_spectrum': [result['causality_strength'] for result in causality_map.values()],
                'directionality_spectrum': [result['directionality_index'] for result in causality_map.values()]
            }
            
        except Exception as e:
            return {'error': str(e), 'method': 'frequency_dependent_causality_analysis'}

    async def _bidirectional_coupling_analysis(self, signal1: np.ndarray, signal2: np.ndarray,
                                             cross_wavelet: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Bidirectional coupling strength assessment."""
        try:
            coupling_results = {
                'coupling_strength_analysis': {},
                'asymmetry_analysis': {},
                'coupling_stability': {},
                'nonlinear_coupling': {}
            }
            
            for i, freq in enumerate(frequencies):
                cross_power_row = cross_wavelet[i, :]
                
                # Coupling strength based on cross-wavelet magnitude
                coupling_strength = np.mean(np.abs(cross_power_row))
                
                # Phase coupling strength
                phase_coupling = np.abs(np.mean(np.exp(1j * np.angle(cross_power_row))))
                
                # Coupling asymmetry
                phase_angles = np.angle(cross_power_row)
                forward_coupling = np.mean(phase_angles < 0)  # signal1 leads
                backward_coupling = np.mean(phase_angles > 0)  # signal2 leads
                asymmetry_index = forward_coupling - backward_coupling
                
                # Coupling stability over time
                coupling_stability = 1.0 / (1.0 + np.std(np.abs(cross_power_row)))
                
                coupling_results['coupling_strength_analysis'][f'freq_{freq:.4f}'] = {
                    'total_coupling_strength': coupling_strength,
                    'phase_coupling_strength': phase_coupling,
                    'coupling_quality': coupling_strength * phase_coupling
                }
                
                coupling_results['asymmetry_analysis'][f'freq_{freq:.4f}'] = {
                    'forward_coupling_fraction': forward_coupling,
                    'backward_coupling_fraction': backward_coupling,
                    'asymmetry_index': asymmetry_index,
                    'coupling_symmetry': 1.0 - np.abs(asymmetry_index)
                }
                
                coupling_results['coupling_stability'][f'freq_{freq:.4f}'] = {
                    'temporal_stability': coupling_stability,
                    'coupling_variability': np.std(np.abs(cross_power_row)),
                    'stable_coupling': coupling_stability > 0.7
                }
            
            return coupling_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'bidirectional_coupling_analysis'}

    async def _statistical_significance_testing(self, directional_results: Dict,
                                              signal1: np.ndarray, signal2: np.ndarray,
                                              frequencies: np.ndarray) -> Dict:
        """Advanced statistical significance testing for directional results."""
        try:
            from scipy import stats
            
            significance_results = {
                'permutation_tests': {},
                'bootstrap_confidence_intervals': {},
                'fdr_correction': {},
                'multiple_comparison_correction': {}
            }
            
            # Permutation tests for directionality significance
            n_permutations = 1000
            alpha_level = 0.05
            
            for i, freq in enumerate(frequencies):
                # Get observed directionality measures
                observed_directionality = 0
                if 'ensemble_directionality' in directional_results:
                    ensemble_results = directional_results['ensemble_directionality']
                    if 'ensemble_directionality_index' in ensemble_results:
                        observed_directionality = ensemble_results['ensemble_directionality_index'][i]
                
                # Permutation test
                permuted_directionalities = []
                for _ in range(n_permutations):
                    # Randomly shuffle one signal to break causality
                    shuffled_signal2 = np.random.permutation(signal2)
                    
                    # Compute directionality for shuffled data
                    # Simple phase-based measure for permutation
                    try:
                        from scipy.signal import hilbert
                        analytic1 = hilbert(signal1)
                        analytic2 = hilbert(shuffled_signal2)
                        phase_diff_perm = np.angle(analytic1) - np.angle(analytic2)
                        perm_directionality = -np.mean(np.sin(phase_diff_perm))
                        permuted_directionalities.append(perm_directionality)
                    except:
                        permuted_directionalities.append(0)
                
                # Calculate p-value
                if permuted_directionalities:
                    p_value = np.mean(np.abs(permuted_directionalities) >= np.abs(observed_directionality))
                    significant = p_value < alpha_level
                else:
                    p_value = 1.0
                    significant = False
                
                significance_results['permutation_tests'][f'freq_{freq:.4f}'] = {
                    'observed_directionality': observed_directionality,
                    'p_value': p_value,
                    'significant': significant,
                    'alpha_level': alpha_level,
                    'n_permutations': n_permutations
                }
            
            # FDR correction for multiple comparisons
            p_values = [result['p_value'] for result in significance_results['permutation_tests'].values()]
            if p_values:
                try:
                    from statsmodels.stats.multitest import multipletests
                    rejected, p_corrected, _, _ = multipletests(p_values, alpha=alpha_level, method='fdr_bh')
                    
                    significance_results['fdr_correction'] = {
                        'corrected_p_values': p_corrected.tolist(),
                        'significant_after_correction': rejected.tolist(),
                        'correction_method': 'benjamini_hochberg'
                    }
                except ImportError:
                    # Simple Bonferroni correction as fallback
                    bonferroni_alpha = alpha_level / len(p_values)
                    bonferroni_significant = [p < bonferroni_alpha for p in p_values]
                    
                    significance_results['fdr_correction'] = {
                        'corrected_alpha': bonferroni_alpha,
                        'significant_after_correction': bonferroni_significant,
                        'correction_method': 'bonferroni'
                    }
            
            return significance_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'statistical_significance_testing'}

    async def _confidence_interval_estimation(self, directional_results: Dict,
                                            phase_diff: np.ndarray, frequencies: np.ndarray) -> Dict:
        """Confidence interval estimation for directional measures."""
        try:
            confidence_results = {
                'bootstrap_intervals': {},
                'analytical_intervals': {},
                'uncertainty_quantification': {}
            }
            
            n_bootstrap = 1000
            confidence_level = 0.95
            alpha = 1 - confidence_level
            
            for i, freq in enumerate(frequencies):
                phase_row = phase_diff[i, :]
                
                # Bootstrap confidence intervals
                bootstrap_directionalities = []
                for _ in range(n_bootstrap):
                    # Bootstrap resample
                    bootstrap_indices = np.random.choice(len(phase_row), size=len(phase_row), replace=True)
                    bootstrap_phases = phase_row[bootstrap_indices]
                    
                    # Compute directionality for bootstrap sample
                    bootstrap_directionality = -np.mean(np.sin(bootstrap_phases))
                    bootstrap_directionalities.append(bootstrap_directionality)
                
                # Calculate confidence interval
                lower_percentile = (alpha / 2) * 100
                upper_percentile = (1 - alpha / 2) * 100
                
                ci_lower = np.percentile(bootstrap_directionalities, lower_percentile)
                ci_upper = np.percentile(bootstrap_directionalities, upper_percentile)
                
                # Uncertainty measures
                bootstrap_std = np.std(bootstrap_directionalities)
                bootstrap_mean = np.mean(bootstrap_directionalities)
                
                confidence_results['bootstrap_intervals'][f'freq_{freq:.4f}'] = {
                    'confidence_level': confidence_level,
                    'lower_bound': ci_lower,
                    'upper_bound': ci_upper,
                    'bootstrap_mean': bootstrap_mean,
                    'bootstrap_std': bootstrap_std,
                    'interval_width': ci_upper - ci_lower
                }
                
                # Analytical confidence intervals (approximate)
                observed_directionality = -np.mean(np.sin(phase_row))
                analytical_std = np.std(np.sin(phase_row)) / np.sqrt(len(phase_row))
                
                # Normal approximation
                z_critical = 1.96  # For 95% confidence
                analytical_lower = observed_directionality - z_critical * analytical_std
                analytical_upper = observed_directionality + z_critical * analytical_std
                
                confidence_results['analytical_intervals'][f'freq_{freq:.4f}'] = {
                    'lower_bound': analytical_lower,
                    'upper_bound': analytical_upper,
                    'standard_error': analytical_std,
                    'z_critical': z_critical
                }
                
                # Uncertainty quantification
                confidence_results['uncertainty_quantification'][f'freq_{freq:.4f}'] = {
                    'bootstrap_uncertainty': bootstrap_std,
                    'analytical_uncertainty': analytical_std,
                    'relative_uncertainty': bootstrap_std / np.abs(bootstrap_mean) if np.abs(bootstrap_mean) > 0 else np.inf,
                    'uncertainty_category': 'low' if bootstrap_std < 0.1 else 'medium' if bootstrap_std < 0.3 else 'high'
                }
            
            return confidence_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'confidence_interval_estimation'}

    async def _ensemble_directional_decision(self, directional_results: Dict, frequencies: np.ndarray) -> Dict:
        """Ensemble decision making for directional analysis."""
        try:
            ensemble_results = {
                'method_weights': {},
                'weighted_ensemble': {},
                'consensus_analysis': {},
                'final_directionality': {}
            }
            
            # Method reliability weights based on available results
            method_weights = {
                'phase_based': 0.3,
                'coherence_based': 0.25,
                'granger_causality': 0.25,
                'lead_lag': 0.2
            }
            
            # Initialize ensemble arrays
            ensemble_directionality = np.zeros(len(frequencies))
            signal1_leads_count = np.zeros(len(frequencies))
            signal2_leads_count = np.zeros(len(frequencies))
            bidirectional_count = np.zeros(len(frequencies))
            
            for i, freq in enumerate(frequencies):
                freq_key = f'freq_{freq:.4f}'
                weighted_sum = 0
                total_weight = 0
                
                # Phase-based contribution
                if 'phase_based_directionality' in directional_results:
                    phase_results = directional_results['phase_based_directionality']
                    if 'classical_phase_analysis' in phase_results:
                        classical = phase_results['classical_phase_analysis']
                        if 'directionality_index' in classical and i < len(classical['directionality_index']):
                            weighted_sum += method_weights['phase_based'] * classical['directionality_index'][i]
                            total_weight += method_weights['phase_based']
                            
                            # Count directional decisions
                            if classical['directionality_index'][i] < -0.1:
                                signal1_leads_count[i] += method_weights['phase_based']
                            elif classical['directionality_index'][i] > 0.1:
                                signal2_leads_count[i] += method_weights['phase_based']
                            else:
                                bidirectional_count[i] += method_weights['phase_based']
                
                # Coherence-based contribution
                if 'coherence_based_directionality' in directional_results:
                    coherence_results = directional_results['coherence_based_directionality']
                    if 'coherence_based_directionality' in coherence_results and freq_key in coherence_results['coherence_based_directionality']:
                        coherence_dir = coherence_results['coherence_based_directionality'][freq_key]
                        if 'coherence_directionality' in coherence_dir:
                            coherence_weight = method_weights['coherence_based'] * coherence_dir.get('directionality_confidence', 1)
                            weighted_sum += coherence_weight * coherence_dir['coherence_directionality']
                            total_weight += coherence_weight
                            
                            # Count directional decisions
                            if coherence_dir['coherence_directionality'] < -0.1:
                                signal1_leads_count[i] += coherence_weight
                            elif coherence_dir['coherence_directionality'] > 0.1:
                                signal2_leads_count[i] += coherence_weight
                            else:
                                bidirectional_count[i] += coherence_weight
                
                # Granger causality contribution
                if 'granger_causality_analysis' in directional_results:
                    granger_results = directional_results['granger_causality_analysis']
                    if 'bidirectional_granger' in granger_results:
                        bidirectional = granger_results['bidirectional_granger']
                        if 'net_causality' in bidirectional:
                            net_causality = bidirectional['net_causality']
                            weighted_sum += method_weights['granger_causality'] * net_causality
                            total_weight += method_weights['granger_causality']
                            
                            # Count directional decisions based on net causality
                            if net_causality > 0.1:  # Signal1 -> Signal2 dominates
                                signal1_leads_count[i] += method_weights['granger_causality']
                            elif net_causality < -0.1:  # Signal2 -> Signal1 dominates
                                signal2_leads_count[i] += method_weights['granger_causality']
                            else:
                                bidirectional_count[i] += method_weights['granger_causality']
                
                # Lead-lag contribution
                if 'lead_lag_analysis' in directional_results:
                    leadlag_results = directional_results['lead_lag_analysis']
                    if 'frequency_dependent_delays' in leadlag_results and freq_key in leadlag_results['frequency_dependent_delays']:
                        delay_info = leadlag_results['frequency_dependent_delays'][freq_key]
                        if 'time_delay_seconds' in delay_info and 'delay_confidence' in delay_info:
                            delay_weight = method_weights['lead_lag'] * delay_info['delay_confidence']
                            # Convert time delay to directionality index
                            delay_directionality = -np.sign(delay_info['time_delay_seconds']) * min(abs(delay_info['time_delay_seconds']), 1.0)
                            weighted_sum += delay_weight * delay_directionality
                            total_weight += delay_weight
                            
                            # Count directional decisions
                            if delay_info['time_delay_seconds'] < -0.01:  # signal1 leads
                                signal1_leads_count[i] += delay_weight
                            elif delay_info['time_delay_seconds'] > 0.01:  # signal2 leads
                                signal2_leads_count[i] += delay_weight
                            else:
                                bidirectional_count[i] += delay_weight
                
                # Compute ensemble directionality
                if total_weight > 0:
                    ensemble_directionality[i] = weighted_sum / total_weight
                else:
                    ensemble_directionality[i] = 0
            
            # Normalize vote counts
            total_votes = signal1_leads_count + signal2_leads_count + bidirectional_count
            signal1_leads_fraction = np.divide(signal1_leads_count, total_votes, 
                                             out=np.zeros_like(signal1_leads_count), where=total_votes>0)
            signal2_leads_fraction = np.divide(signal2_leads_count, total_votes,
                                             out=np.zeros_like(signal2_leads_count), where=total_votes>0)
            bidirectional_fraction = np.divide(bidirectional_count, total_votes,
                                             out=np.ones_like(bidirectional_count), where=total_votes>0)
            
            # Final directional decisions with adaptive thresholds
            adaptive_threshold = 0.15  # Slightly higher than default for robustness
            signal1_leads_mask = (ensemble_directionality < -adaptive_threshold) & (signal1_leads_fraction > 0.5)
            signal2_leads_mask = (ensemble_directionality > adaptive_threshold) & (signal2_leads_fraction > 0.5)
            bidirectional_mask = ~(signal1_leads_mask | signal2_leads_mask)
            
            ensemble_results.update({
                'ensemble_directionality_index': ensemble_directionality,
                'signal1_leads_mask': signal1_leads_mask,
                'signal2_leads_mask': signal2_leads_mask,
                'bidirectional_mask': bidirectional_mask,
                'signal1_leads_fraction': signal1_leads_fraction,
                'signal2_leads_fraction': signal2_leads_fraction,
                'bidirectional_fraction': bidirectional_fraction,
                'ensemble_confidence': np.abs(ensemble_directionality),
                'consensus_strength': np.maximum(signal1_leads_fraction, signal2_leads_fraction),
                'decision_certainty': 1 - bidirectional_fraction
            })
            
            # Summary statistics
            ensemble_results['final_directionality'] = {
                'dominant_frequencies_signal1_leads': frequencies[signal1_leads_mask].tolist(),
                'dominant_frequencies_signal2_leads': frequencies[signal2_leads_mask].tolist(),
                'bidirectional_frequencies': frequencies[bidirectional_mask].tolist(),
                'overall_directionality': np.mean(ensemble_directionality),
                'directional_consistency': 1 - np.std(ensemble_directionality),
                'strong_directionality_fraction': np.mean(np.abs(ensemble_directionality) > adaptive_threshold)
            }
            
            return ensemble_results
            
        except Exception as e:
            return {'error': str(e), 'method': 'ensemble_directional_decision'}

