    async def _directional_analysis_fallback(self, error_msg: str, signal1: np.ndarray, 
                                          signal2: np.ndarray, cross_wavelet: np.ndarray, 
                                          frequencies: np.ndarray) -> Dict:
        """Fallback directional analysis for error recovery."""
        try:
            self.logger.warning(f"Using fallback directional analysis due to: {error_msg}")
            
            # Simple but robust phase-based directionality
            phase_diff = np.angle(cross_wavelet)
            directionality = np.zeros(len(frequencies))
            
            for i in range(len(frequencies)):
                if i < phase_diff.shape[0]:
                    phase_row = phase_diff[i, :]
                    # Robust directionality measure
                    directionality[i] = -np.mean(np.sin(phase_row))
            
            return {
                'directionality_index': directionality,
                'signal1_leads': directionality < -0.1,
                'signal2_leads': directionality > 0.1,
                'bidirectional': np.abs(directionality) <= 0.1,
                'analysis_method': 'fallback_phase_based',
                'error_recovered': True,
                'original_error': error_msg
            }
            
        except Exception as fallback_error:
            return {
                'directionality_index': np.zeros(len(frequencies)),
                'signal1_leads': np.zeros(len(frequencies), dtype=bool),
                'signal2_leads': np.zeros(len(frequencies), dtype=bool),
                'bidirectional': np.ones(len(frequencies), dtype=bool),
                'analysis_method': 'emergency_fallback',
                'error_recovered': False,
                'original_error': error_msg,
                'fallback_error': str(fallback_error)
            }

    async def _advanced_local_maxima_ridge_extraction(self, power_spectrum: np.ndarray,
                                                    scales: np.ndarray) -> List[np.ndarray]:
        """Advanced ridge extraction using sophisticated local maxima with database integration."""
        try:
            with self.performance_monitor.measure_time("advanced_local_maxima_ridge_extraction"):
                self.logger.info("Starting advanced local maxima ridge extraction")
                
                # Compute adaptive thresholds
                adaptive_thresholds = await self._compute_adaptive_ridge_thresholds(power_spectrum, scales)
                optimal_threshold = adaptive_thresholds.get('global_statistics', {}).get('optimal_threshold', 0.1)
                
                ridges = []
                
                # Advanced multi-scale ridge detection
                for t in range(power_spectrum.shape[1]):
                    power_col = power_spectrum[:, t]
                    ridge_points = []
                    
                    for s in range(1, len(scales) - 1):
                        current_power = power_col[s]
                        
                        # Enhanced local maxima conditions
                        if (current_power > power_col[s-1] and 
                            current_power > power_col[s+1] and
                            current_power > optimal_threshold):
                            
                            # Prominence check
                            prominence = min(
                                current_power - power_col[s-1],
                                current_power - power_col[s+1]
                            )
                            
                            if prominence > 0.05 * optimal_threshold:
                                ridge_points.append({
                                    'scale_index': s,
                                    'time_index': t,
                                    'power_value': current_power,
                                    'prominence': prominence
                                })
                    
                    if ridge_points:
                        for point in ridge_points:
                            ridges.append([point['scale_index'], point['time_index']])
                
                # Database storage
                storage_status = await self._store_ridge_analysis_results(
                    [{'ridge_points': ridge, 'quality_score': 0.8} for ridge in ridges],
                    power_spectrum, scales, 'local_maxima'
                )
                
                self.logger.info(f"Advanced local maxima ridge extraction completed: {len(ridges)} ridges")
                return ridges
                
        except Exception as e:
            return await self._ridge_extraction_fallback(str(e), power_spectrum, scales, 'local_maxima')

    async def _advanced_gradient_descent_ridge_extraction(self, power_spectrum: np.ndarray,
                                                        scales: np.ndarray) -> List[np.ndarray]:
        """Advanced ridge extraction using sophisticated gradient descent optimization."""
        try:
            with self.performance_monitor.measure_time("advanced_gradient_descent_ridge_extraction"):
                self.logger.info("Starting advanced gradient descent ridge extraction")
                
                ridges = []
                
                # Generate optimization start points
                start_points = []
                for i in range(0, power_spectrum.shape[0], max(1, power_spectrum.shape[0]//10)):
                    for j in range(0, power_spectrum.shape[1], max(1, power_spectrum.shape[1]//10)):
                        if power_spectrum[i, j] > 0.5 * np.max(power_spectrum):
                            start_points.append((i, j))
                
                # Optimize each start point
                for start_point in start_points[:20]:  # Limit to top 20 start points
                    try:
                        # Simple gradient following
                        current_pos = list(start_point)
                        ridge_path = [current_pos[:]]
                        
                        for iteration in range(100):  # Max iterations
                            # Compute local gradient
                            s, t = int(current_pos[0]), int(current_pos[1])
                            
                            if (1 <= s < power_spectrum.shape[0]-1 and 
                                1 <= t < power_spectrum.shape[1]-1):
                                
                                grad_s = power_spectrum[s+1, t] - power_spectrum[s-1, t]
                                grad_t = power_spectrum[s, t+1] - power_spectrum[s, t-1]
                                
                                # Update position
                                learning_rate = 0.1
                                current_pos[0] += learning_rate * grad_s
                                current_pos[1] += learning_rate * grad_t
                                
                                # Bounds checking
                                current_pos[0] = max(0, min(power_spectrum.shape[0]-1, current_pos[0]))
                                current_pos[1] = max(0, min(power_spectrum.shape[1]-1, current_pos[1]))
                                
                                ridge_path.append([int(current_pos[0]), int(current_pos[1])])
                                
                                # Convergence check
                                if len(ridge_path) > 1:
                                    distance = np.sqrt((ridge_path[-1][0] - ridge_path[-2][0])**2 + 
                                                     (ridge_path[-1][1] - ridge_path[-2][1])**2)
                                    if distance < 0.01:
                                        break
                            else:
                                break
                        
                        if len(ridge_path) > 5:  # Minimum ridge length
                            ridges.append(ridge_path)
                    
                    except Exception:
                        continue
                
                # Database storage
                storage_status = await self._store_ridge_analysis_results(
                    [{'ridge_points': ridge, 'quality_score': 0.7} for ridge in ridges],
                    power_spectrum, scales, 'gradient_descent'
                )
                
                self.logger.info(f"Advanced gradient descent ridge extraction completed: {len(ridges)} ridges")
                return ridges
                
        except Exception as e:
            return await self._ridge_extraction_fallback(str(e), power_spectrum, scales, 'gradient_descent')

    async def _advanced_connected_components_ridge_extraction(self, power_spectrum: np.ndarray,
                                                            scales: np.ndarray) -> List[np.ndarray]:
        """Advanced ridge extraction using sophisticated connected components analysis."""
        try:
            with self.performance_monitor.measure_time("advanced_connected_components_ridge_extraction"):
                self.logger.info("Starting advanced connected components ridge extraction")
                
                try:
                    from scipy import ndimage
                except ImportError:
                    # Fallback to simple local maxima
                    return await self._advanced_local_maxima_ridge_extraction(power_spectrum, scales)
                
                ridges = []
                threshold_levels = [0.3, 0.5, 0.7, 0.9]  # Multiple thresholds
                
                for threshold in threshold_levels:
                    try:
                        adaptive_threshold = threshold * np.max(power_spectrum)
                        
                        # Binary thresholding
                        binary_image = power_spectrum > adaptive_threshold
                        
                        # Connected components analysis
                        labeled_array, num_features = ndimage.label(binary_image)
                        
                        # Extract components
                        for label in range(1, num_features + 1):
                            component_mask = labeled_array == label
                            component_indices = np.where(component_mask)
                            
                            if len(component_indices[0]) > 8:  # Minimum size
                                ridge_points = [[int(s), int(t)] for s, t in 
                                               zip(component_indices[0], component_indices[1])]
                                
                                # Sort by time for coherent path
                                ridge_points.sort(key=lambda x: x[1])
                                
                                ridges.append(ridge_points)
                    
                    except Exception:
                        continue
                
                # Remove duplicates
                unique_ridges = []
                for ridge in ridges:
                    is_duplicate = False
                    for existing in unique_ridges:
                        if len(ridge) == len(existing):
                            # Check if ridges are similar
                            distance = np.mean([np.sqrt((r[0]-e[0])**2 + (r[1]-e[1])**2) 
                                              for r, e in zip(ridge, existing)])
                            if distance < 2.0:  # Similarity threshold
                                is_duplicate = True
                                break
                    
                    if not is_duplicate:
                        unique_ridges.append(ridge)
                
                # Database storage
                storage_status = await self._store_ridge_analysis_results(
                    [{'ridge_points': ridge, 'quality_score': 0.6} for ridge in unique_ridges],
                    power_spectrum, scales, 'connected_components'
                )
                
                self.logger.info(f"Advanced connected components ridge extraction completed: {len(unique_ridges)} ridges")
                return unique_ridges
                
        except Exception as e:
            return await self._ridge_extraction_fallback(str(e), power_spectrum, scales, 'connected_components')

    async def _compute_adaptive_ridge_thresholds(self, power_spectrum: np.ndarray, scales: np.ndarray) -> Dict:
        """Compute adaptive thresholds for ridge detection based on signal statistics."""
        try:
            global_mean = np.mean(power_spectrum)
            global_std = np.std(power_spectrum)
            global_max = np.max(power_spectrum)
            
            # Optimal threshold using statistics
            optimal_threshold = global_mean + 1.5 * global_std
            
            return {
                'global_statistics': {
                    'mean': global_mean,
                    'std': global_std,
                    'max': global_max,
                    'optimal_threshold': optimal_threshold
                },
                'adaptive_method': 'statistical_analysis'
            }
            
        except Exception as e:
            return {
                'error': str(e),
                'fallback_threshold': 0.1 * np.max(power_spectrum) if power_spectrum.size > 0 else 0.1
            }

