    # SUPPORTING ANALYSIS METHODS
    # ================================================================================================
    
    def _calculate_skewness(self, data: np.ndarray) -> List[float]:
        """Calculate skewness for each feature"""
        try:
            from scipy.stats import skew
            return skew(data, axis=0).tolist()
        except Exception:
            # Fallback manual calculation
            skewness = []
            for col in range(data.shape[1]):
                x = data[:, col]
                mean_x = np.mean(x)
                std_x = np.std(x)
                if std_x > 0:
                    skew_val = np.mean(((x - mean_x) / std_x) ** 3)
                    skewness.append(skew_val)
                else:
                    skewness.append(0.0)
            return skewness
    
    def _calculate_kurtosis(self, data: np.ndarray) -> List[float]:
        """Calculate kurtosis for each feature"""
        try:
            from scipy.stats import kurtosis
            return kurtosis(data, axis=0).tolist()
        except Exception:
            # Fallback manual calculation
            kurt_values = []
            for col in range(data.shape[1]):
                x = data[:, col]
                mean_x = np.mean(x)
                std_x = np.std(x)
                if std_x > 0:
                    kurt_val = np.mean(((x - mean_x) / std_x) ** 4) - 3
                    kurt_values.append(kurt_val)
                else:
                    kurt_values.append(0.0)
            return kurt_values
    
    def _test_normality(self, data: np.ndarray) -> Dict[str, Any]:
        """Test for normality of features"""
        try:
            from scipy.stats import shapiro, normaltest
            
            normality_results = {
                'shapiro_p_values': [],
                'dagostino_p_values': [],
                'non_normal_features': [],
                'non_normal_fraction': 0.0
            }
            
            non_normal_count = 0
            
            for col in range(min(data.shape[1], 10)):  # Limit to first 10 features
                x = data[:, col]
                
                # Shapiro-Wilk test (for smaller samples)
                if len(x) <= 5000:
                    try:
                        _, shapiro_p = shapiro(x[:5000])  # Shapiro limited to 5000 samples
                        normality_results['shapiro_p_values'].append(shapiro_p)
                        if shapiro_p < 0.05:
                            non_normal_count += 1
                            normality_results['non_normal_features'].append(f'feature_{col}')
                    except Exception:
                        normality_results['shapiro_p_values'].append(1.0)
                
                # D'Agostino's test
                try:
                    _, dagostino_p = normaltest(x)
                    normality_results['dagostino_p_values'].append(dagostino_p)
                except Exception:
                    normality_results['dagostino_p_values'].append(1.0)
            
            normality_results['non_normal_fraction'] = non_normal_count / min(data.shape[1], 10)
            
            return normality_results
            
        except Exception as e:
            return {
                'error': str(e),
                'non_normal_fraction': 0.5  # Assume moderate non-normality
            }
    
    def _test_heteroscedasticity(self, data: np.ndarray) -> Dict[str, Any]:
        """Test for heteroscedasticity (non-constant variance)"""
        try:
            if data.shape[1] < 2:
                return {'heteroscedastic': False, 'test_statistic': 0.0}
            
            # Use Breusch-Pagan-like test
            x, y = data[:, 0], data[:, 1]
            
            # Fit linear model and get residuals
            coeffs = np.polyfit(x, y, 1)
            y_pred = np.polyval(coeffs, x)
            residuals = y - y_pred
            
            # Test if residual variance depends on x
            squared_residuals = residuals ** 2
            variance_corr = abs(np.corrcoef(x, squared_residuals)[0, 1])
            
            return {
                'heteroscedastic': variance_corr > 0.3,
                'test_statistic': variance_corr,
                'interpretation': 'heteroscedastic' if variance_corr > 0.3 else 'homoscedastic'
            }
            
        except Exception as e:
            return {'error': str(e), 'heteroscedastic': False}
    
    def _detect_outliers(self, data: np.ndarray) -> Dict[str, Any]:
        """Detect outliers using multiple methods"""
        try:
            outlier_results = {
                'iqr_outliers': [],
                'zscore_outliers': [],
                'total_outliers': 0,
                'outlier_fraction': 0.0
            }
            
            n_samples = data.shape[0]
            total_outliers = set()
            
            for col in range(data.shape[1]):
                x = data[:, col]
                
                # IQR method
                q1, q3 = np.percentile(x, [25, 75])
                iqr = q3 - q1
                lower_bound = q1 - 1.5 * iqr
                upper_bound = q3 + 1.5 * iqr
                
                iqr_outliers = np.where((x < lower_bound) | (x > upper_bound))[0]
                outlier_results['iqr_outliers'].extend(iqr_outliers.tolist())
                total_outliers.update(iqr_outliers)
                
                # Z-score method
                if np.std(x) > 0:
                    z_scores = np.abs((x - np.mean(x)) / np.std(x))
                    zscore_outliers = np.where(z_scores > 3)[0]
                    outlier_results['zscore_outliers'].extend(zscore_outliers.tolist())
                    total_outliers.update(zscore_outliers)
            
            outlier_results['total_outliers'] = len(total_outliers)
            outlier_results['outlier_fraction'] = len(total_outliers) / n_samples
            
            return outlier_results
            
        except Exception as e:
            return {'error': str(e), 'outlier_fraction': 0.0}
    
    def _identify_distribution_type(self, data: np.ndarray) -> Dict[str, Any]:
        """Identify likely distribution types for features"""
        try:
            distribution_results = {
                'likely_distributions': [],
                'distribution_scores': {},
                'overall_assessment': 'mixed'
            }
            
            for col in range(min(data.shape[1], 5)):  # Limit analysis
                x = data[:, col]
                
                # Simple heuristics for distribution identification
                skew_val = np.abs(np.mean(((x - np.mean(x)) / max(np.std(x), 1e-10)) ** 3))
                
                if skew_val < 0.5:
                    dist_type = 'normal'
                elif skew_val < 1.0:
                    dist_type = 'moderate_skew'
                else:
                    dist_type = 'heavy_skew'
                
                distribution_results['likely_distributions'].append(dist_type)
                distribution_results['distribution_scores'][f'feature_{col}'] = skew_val
            
            # Overall assessment
            normal_count = distribution_results['likely_distributions'].count('normal')
            total_features = len(distribution_results['likely_distributions'])
            
            if normal_count / max(total_features, 1) > 0.7:
                distribution_results['overall_assessment'] = 'mostly_normal'
            elif normal_count / max(total_features, 1) > 0.3:
                distribution_results['overall_assessment'] = 'mixed'
            else:
                distribution_results['overall_assessment'] = 'mostly_non_normal'
            
            return distribution_results
            
        except Exception as e:
            return {'error': str(e), 'overall_assessment': 'unknown'}
    
    def _analyze_time_series_properties(self, data: np.ndarray) -> Dict[str, Any]:
        """Analyze time series properties if applicable"""
        try:
            time_series_results = {
                'is_time_series': False,
                'trend_detected': False,
                'seasonality_detected': False,
                'autocorrelation': 0.0,
                'stationarity': 'unknown'
            }
            
            # Simple heuristic: check if data might be time series
            # Look for temporal patterns in first feature
            if data.shape[0] > 10:
                x = data[:, 0]
                
                # Check for trend
                indices = np.arange(len(x))
                trend_corr = abs(np.corrcoef(indices, x)[0, 1])
                time_series_results['trend_detected'] = trend_corr > 0.3
                
                # Check for autocorrelation (lag-1)
                if len(x) > 1:
                    autocorr = abs(np.corrcoef(x[:-1], x[1:])[0, 1])
                    time_series_results['autocorrelation'] = autocorr
                    time_series_results['is_time_series'] = autocorr > 0.2
                
                # Simple stationarity check
                first_half_mean = np.mean(x[:len(x)//2])
                second_half_mean = np.mean(x[len(x)//2:])
                mean_diff = abs(first_half_mean - second_half_mean) / max(np.std(x), 1e-10)
                
                if mean_diff < 0.5:
                    time_series_results['stationarity'] = 'likely_stationary'
                else:
                    time_series_results['stationarity'] = 'likely_non_stationary'
            
            return time_series_results
            
        except Exception as e:
            return {'error': str(e), 'is_time_series': False}
    
    def _estimate_intrinsic_dimension(self, data: np.ndarray) -> float:
        """Estimate intrinsic dimension of data"""
        try:
            # Use PCA to estimate effective dimension
            from sklearn.decomposition import PCA
            
            pca = PCA()
            pca.fit(data)
            
            # Find number of components needed for 90% variance
            cumsum_variance = np.cumsum(pca.explained_variance_ratio_)
            n_components_90 = np.sum(cumsum_variance < 0.9) + 1
            
            return min(n_components_90, data.shape[1])
            
        except Exception:
            # Fallback: use correlation-based estimate
            try:
                corr_matrix = np.corrcoef(data.T)
                eigenvals = np.linalg.eigvals(corr_matrix)
                eigenvals = eigenvals[eigenvals > 0.1]  # Threshold for significant dimensions
                return len(eigenvals)
            except Exception:
                return data.shape[1] * 0.7  # Rough estimate
    
    def _estimate_entropy(self, data: np.ndarray) -> float:
        """Estimate entropy of data"""
        try:
            if data.shape[1] == 1:
                # Univariate entropy using histogram
                x = data.flatten()
                n_bins = min(50, int(np.sqrt(len(x))))
                hist, _ = np.histogram(x, bins=n_bins, density=True)
                hist = hist[hist > 0]  # Remove empty bins
                return -np.sum(hist * np.log(hist))
            else:
                # Multivariate entropy approximation
                det_cov = np.linalg.det(np.cov(data.T))
                if det_cov > 0:
                    return 0.5 * np.log(2 * np.pi * np.e * det_cov)
                else:
                    return 0.0
                    
        except Exception:
            return 1.0  # Default entropy value
    
    def _estimate_fractal_dimension(self, data: np.ndarray) -> float:
        """Estimate fractal dimension using box-counting method"""
        try:
            # Simplified fractal dimension for multivariate data
            if data.shape[1] == 1:
                x = data.flatten()
                # Use correlation dimension approximation
                n = len(x)
                if n < 10:
                    return 1.0
                
                # Simple correlation sum approach
                distances = []
                for i in range(0, min(n, 100), 10):
                    for j in range(i+1, min(n, 100), 10):
                        distances.append(abs(x[i] - x[j]))
                
                if distances:
                    # Rough fractal dimension estimate
                    return min(2.0, 1.0 + np.std(distances) / max(np.mean(distances), 1e-10))
                else:
                    return 1.0
            else:
                # For multivariate data, use correlation dimension
                corr_matrix = np.corrcoef(data.T)
                eigenvals = np.linalg.eigvals(corr_matrix)
                eigenvals = eigenvals[eigenvals > 0.01]
                
                if len(eigenvals) > 0:
                    return min(data.shape[1], len(eigenvals) * 0.8)
                else:
                    return 1.0
                    
        except Exception:
            return 1.5  # Default fractal dimension
    
    # Additional supporting methods for meta-learning and validation
    def _apply_meta_learning(self, individual_results: Dict[str, Any], 
                            data_characteristics: Dict[str, Any],
                            ensemble_result: Dict[str, Any]) -> Dict[str, Any]:
        """Apply meta-learning to improve ensemble results"""
        try:
            meta_result = {
                'adjusted_confidence': ensemble_result.get('confidence', 0.0),
                'meta_recommendations': [],
                'reliability_score': 0.0,
                'consistency_score': 0.0
            }
            
            # Calculate consistency across tests
            decisions = [r.get('interpretation', 'unknown') for r in individual_results.values() 
                        if r.get('success', False)]
            
            if decisions:
                independent_count = decisions.count('independent')
                dependent_count = decisions.count('dependent')
                total_decisions = len(decisions)
                
                consistency_score = max(independent_count, dependent_count) / total_decisions
                meta_result['consistency_score'] = consistency_score
                
                # Adjust confidence based on consistency
                if consistency_score > 0.8:
                    meta_result['adjusted_confidence'] = min(1.0, ensemble_result.get('confidence', 0.0) * 1.2)
                    meta_result['meta_recommendations'].append('High consistency across tests')
                elif consistency_score < 0.6:
                    meta_result['adjusted_confidence'] = ensemble_result.get('confidence', 0.0) * 0.8
                    meta_result['meta_recommendations'].append('Low consistency - interpret cautiously')
            
            # Calculate reliability based on test success rate
            successful_tests = sum(1 for r in individual_results.values() if r.get('success', False))
            total_tests = len(individual_results)
            reliability_score = successful_tests / max(total_tests, 1)
            meta_result['reliability_score'] = reliability_score
            
            if reliability_score < 0.5:
                meta_result['meta_recommendations'].append('Many tests failed - results less reliable')
            
            return meta_result
            
        except Exception as e:
            self.logger.error(f"Error in meta-learning: {e}")
            return {
                'adjusted_confidence': ensemble_result.get('confidence', 0.0),
                'error': str(e)
            }
    
    def _validate_ensemble_result(self, data: np.ndarray, results: Dict[str, Any], 
                                 validation_method: str, individual_results: Dict[str, Any]) -> Dict[str, Any]:
        """Validate ensemble results using cross-validation or bootstrap"""
        try:
            validation_result = {
                'validation_method': validation_method,
                'validation_score': 0.0,
                'stability_score': 0.0,
                'confidence_interval': [0.0, 1.0]
            }
            
            if validation_method == 'cross_validation' and len(data) > 20:
                # Simple k-fold cross-validation
                k_folds = min(5, len(data) // 10)
                fold_results = []
                
                for fold in range(k_folds):
                    # Create train/test split
                    fold_size = len(data) // k_folds
                    start_idx = fold * fold_size
                    end_idx = start_idx + fold_size if fold < k_folds - 1 else len(data)
                    
                    test_data = data[start_idx:end_idx]
                    
                    if len(test_data) > 5:
                        # Run simplified ensemble on fold
                        fold_result = self._run_simplified_ensemble(test_data)
                        fold_results.append(fold_result.get('confidence', 0.0))
                
                if fold_results:
                    validation_result['validation_score'] = np.mean(fold_results)
                    validation_result['stability_score'] = 1.0 - np.std(fold_results)
                    validation_result['confidence_interval'] = [
                        np.percentile(fold_results, 2.5),
                        np.percentile(fold_results, 97.5)
                    ]
            
            elif validation_method == 'bootstrap' and len(data) > 10:
                # Bootstrap validation
                n_bootstrap = min(100, max(10, len(data) // 5))
                bootstrap_results = []
                
                for _ in range(n_bootstrap):
                    # Bootstrap sample
                    indices = np.random.choice(len(data), size=len(data), replace=True)
                    bootstrap_data = data[indices]
                    
                    # Run simplified ensemble
                    bootstrap_result = self._run_simplified_ensemble(bootstrap_data)
                    bootstrap_results.append(bootstrap_result.get('confidence', 0.0))
                
                if bootstrap_results:
                    validation_result['validation_score'] = np.mean(bootstrap_results)
                    validation_result['stability_score'] = 1.0 - np.std(bootstrap_results)
                    validation_result['confidence_interval'] = [
                        np.percentile(bootstrap_results, 2.5),
                        np.percentile(bootstrap_results, 97.5)
                    ]
            
            return validation_result
            
        except Exception as e:
            self.logger.error(f"Error in ensemble validation: {e}")
            return {
                'validation_method': validation_method,
                'error': str(e),
                'validation_score': 0.5
            }
    
    def _run_simplified_ensemble(self, data: np.ndarray) -> Dict[str, Any]:
        """Run a simplified ensemble for validation purposes"""
        try:
            # Use only core tests for efficiency
            core_tests = ['pearson_correlation', 'spearman_correlation', 'distance_correlation']
            
            results = {}
            for test_name in core_tests:
                try:
                    result = self._execute_individual_test(test_name, data, {})
                    if result.get('success', False):
                        results[test_name] = result
                except Exception:
                    continue
            
            if results:
                return self._majority_voting_aggregation(results, {})
            else:
                return {'confidence': 0.0, 'ensemble_decision': 'unknown'}
                
        except Exception as e:
            return {'confidence': 0.0, 'error': str(e)}
    
    def _generate_recommendations(self, results: Dict[str, Any], 
                                data_characteristics: Dict[str, Any],
                                individual_results: Dict[str, Any]) -> List[str]:
        """Generate recommendations based on analysis results"""
        try:
            recommendations = []
            
            # Based on ensemble confidence
            confidence = results.get('confidence', 0.0)
            if confidence > 0.8:
                recommendations.append("High confidence in ensemble result")
            elif confidence < 0.5:
                recommendations.append("Low confidence - consider additional tests or more data")
            
            # Based on data characteristics
            n_samples = data_characteristics.get('n_samples', 0)
            if n_samples < 100:
                recommendations.append("Small sample size may limit test reliability")
            
            complexity = data_characteristics.get('complexity_measures', {}).get('complexity_score', 0.5)
            if complexity > 0.7:
                recommendations.append("High data complexity - advanced methods recommended")
            
            # Based on test consistency
            successful_tests = sum(1 for r in individual_results.values() if r.get('success', False))
            total_tests = len(individual_results)
            
            if successful_tests / max(total_tests, 1) < 0.7:
                recommendations.append("Many tests failed - check data quality and preprocessing")
            
            # Based on decision
            decision = results.get('ensemble_decision', 'unknown')
            if decision == 'dependent':
                recommendations.append("Variables show dependence - investigate relationship further")
            elif decision == 'independent':
                recommendations.append("Variables appear independent - suitable for independent analysis")
            
            return recommendations
            
        except Exception as e:
            return [f"Error generating recommendations: {e}"]
    
    def _update_performance_history(self, results: Dict[str, Any], data_characteristics: Dict[str, Any]) -> None:
        """Update performance tracking history"""
        try:
            timestamp = datetime.now().isoformat()
            
            # Track ensemble performance
            self.performance_history['ensemble_performance'][timestamp] = {
                'confidence': results.get('confidence', 0.0),
                'n_samples': data_characteristics.get('n_samples', 0),
                'n_features': data_characteristics.get('n_features', 0),
                'aggregation_method': results.get('aggregation_method', 'unknown')
            }
            
            # Limit history size
            max_history = 1000
            if len(self.performance_history['ensemble_performance']) > max_history:
                # Keep only recent entries
                sorted_keys = sorted(self.performance_history['ensemble_performance'].keys())
                for old_key in sorted_keys[:-max_history]:
                    del self.performance_history['ensemble_performance'][old_key]
                    
        except Exception as e:
            self.logger.warning(f"Error updating performance history: {e}")
    
    def _generate_cache_key(self, data: np.ndarray, ensemble_strategy: str, test_selection: str) -> str:
        """Generate cache key for results"""
        try:
            # Create hash of data characteristics and parameters
            data_hash = hash(f"{data.shape}_{np.mean(data)}_{np.std(data)}")
            return f"{data_hash}_{ensemble_strategy}_{test_selection}"
        except Exception:
            return f"default_{ensemble_strategy}_{test_selection}"
    
    def _cache_result(self, cache_key: str, results: Dict[str, Any]) -> None:
        """Cache analysis results"""
        try:
            if len(self.ensemble_cache) >= self.cache_size_limit:
                # Remove oldest entry
                oldest_key = next(iter(self.ensemble_cache))
                del self.ensemble_cache[oldest_key]
            
            self.ensemble_cache[cache_key] = {
                'results': results,
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            self.logger.warning(f"Error caching results: {e}")


