    def _compute_advanced_attention_patterns(self, data: np.ndarray, features: Dict, config: Dict) -> Dict[str, Any]:
        """Compute advanced multi-head attention patterns for anomaly detection."""
        try:
            seq_len = len(data)
            num_heads = config['num_heads']
            hidden_size = config['hidden_size']
            
            # Initialize multi-head attention
            attention_weights = np.zeros((num_heads, seq_len, seq_len))
            head_specializations = [
                'temporal_dynamics', 'amplitude_variations', 'frequency_content',
                'phase_relationships', 'geological_processes', 'anomaly_patterns',
                'seasonal_trends', 'short_term_fluctuations', 'long_term_evolution',
                'correlation_patterns', 'causal_relationships', 'uncertainty_patterns'
            ]
            
            # Compute attention for each head with specialized focus
            for head_idx in range(num_heads):
                specialization = head_specializations[head_idx % len(head_specializations)]
                
                # Query, Key, Value computation with geological specialization
                queries, keys, values = self._compute_qkv_with_specialization(
                    data, features, specialization, hidden_size
                )
                
                # Scaled dot-product attention with geological masking
                attention_scores = self._scaled_dot_product_attention(
                    queries, keys, values, specialization
                )
                
                # Apply geological attention masks
                geological_mask = self._create_geological_attention_mask(
                    seq_len, specialization
                )
                
                attention_weights[head_idx] = attention_scores * geological_mask
            
            # Cross-head attention fusion
            fused_attention = self._fuse_multi_head_attention(attention_weights)
            
            # Attention pattern analysis
            pattern_analysis = self._analyze_attention_patterns(attention_weights)
            
            return {
                'attention_weights': attention_weights,
                'fused_attention': fused_attention,
                'pattern_analysis': pattern_analysis,
                'head_specializations': head_specializations[:num_heads],
                'geological_attention_insights': self._extract_geological_attention_insights(
                    attention_weights, head_specializations[:num_heads]
                )
            }
            
        except Exception as e:
            self.logger.error(f"Advanced attention computation failed: {e}")
            return self._fallback_attention_computation(data, config)
    
    def _compute_geological_anomaly_scores(self, data: np.ndarray, attention_results: Dict, stream_id: str) -> np.ndarray:
        """Compute geological domain-specific anomaly scores using attention patterns."""
        try:
            attention_weights = attention_results['attention_weights']
            num_heads, seq_len, _ = attention_weights.shape
            
            # Multi-perspective anomaly scoring
            anomaly_scores = np.zeros(seq_len)
            
            # Attention-based anomaly detection
            for head_idx in range(num_heads):
                head_attention = attention_weights[head_idx]
                
                # Compute attention entropy (low entropy = focused attention = potential anomaly)
                attention_entropy = -np.sum(head_attention * np.log(head_attention + 1e-8), axis=1)
                
                # Compute attention divergence from expected patterns
                expected_attention = self._get_expected_attention_pattern(stream_id, seq_len)
                attention_divergence = np.sum(np.abs(head_attention - expected_attention), axis=1)
                
                # Combine entropy and divergence scores
                head_scores = (1.0 - attention_entropy / np.max(attention_entropy + 1e-8)) * 0.6 + \
                             (attention_divergence / np.max(attention_divergence + 1e-8)) * 0.4
                
                # Weight by head importance for geological processes
                head_weight = self._get_head_geological_importance(head_idx, stream_id)
                anomaly_scores += head_scores * head_weight
            
            # Normalize scores
            anomaly_scores = anomaly_scores / num_heads
            
            # Apply geological domain knowledge for score refinement
            refined_scores = self._refine_scores_with_geological_knowledge(
                anomaly_scores, data, stream_id
            )
            
            return refined_scores
            
        except Exception as e:
            self.logger.error(f"Geological anomaly scoring failed: {e}")
            return np.abs(zscore(data))  # Fallback to statistical anomaly detection
    
    def _advanced_short_sequence_detection(self, data: np.ndarray, stream_id: str) -> Dict[str, Any]:
        """Advanced detection for short sequences using specialized techniques."""
        try:
            from scipy.stats import normaltest, jarque_bera, shapiro
            
            # Short sequence statistical analysis
            statistical_metrics = {
                'normality_test': normaltest(data)[1] if len(data) >= 3 else 1.0,
                'jarque_bera': jarque_bera(data)[1] if len(data) >= 3 else 1.0,
                'shapiro_wilk': shapiro(data)[1] if len(data) >= 3 else 1.0,
                'kurtosis': float(np.abs(np.mean((data - np.mean(data))**4) / (np.var(data)**2) - 3)),
                'skewness': float(np.abs(np.mean((data - np.mean(data))**3) / (np.std(data)**3)))
            }
            
            # Pattern-based anomaly detection for short sequences
            pattern_scores = np.zeros_like(data)
            for i in range(len(data)):
                # Local deviation scoring
                local_context = data[max(0, i-2):min(len(data), i+3)]
                if len(local_context) > 1:
                    local_mean = np.mean(local_context)
                    local_std = np.std(local_context) + 1e-8
                    pattern_scores[i] = abs(data[i] - local_mean) / local_std
            
            # Combine statistical and pattern-based scores
            anomaly_confidence = np.mean([
                1.0 - statistical_metrics['normality_test'],
                statistical_metrics['kurtosis'] / 10.0,
                statistical_metrics['skewness'] / 10.0
            ])
            
            return {
                'anomaly_scores': pattern_scores,
                'statistical_metrics': statistical_metrics,
                'detection_confidence': min(0.8, anomaly_confidence),
                'geological_relevance': 0.7,  # Moderate relevance for short sequences
                'analysis_type': 'short_sequence_specialized',
                'stream_id': stream_id,
                'recommendation': 'collect_longer_sequences_for_transformer_analysis'
            }
            
        except Exception as e:
            return self._basic_short_sequence_fallback(data, stream_id, str(e))
    
    def _robust_transformer_fallback(self, data: np.ndarray, stream_id: str, error_msg: str) -> Dict[str, Any]:
        """Robust fallback when advanced transformer detection fails."""
        try:
            from scipy.stats import zscore
            from scipy.signal import find_peaks
            
            # Statistical anomaly detection
            z_scores = np.abs(zscore(data))
            
            # Peak-based anomaly detection
            peaks, peak_properties = find_peaks(data, height=np.mean(data) + 2*np.std(data))
            peak_scores = np.zeros_like(data)
            if len(peaks) > 0:
                peak_scores[peaks] = peak_properties['peak_heights'] / np.max(peak_properties['peak_heights'])
            
            # Combine scores
            combined_scores = (z_scores * 0.7) + (peak_scores * 0.3)
            
            return {
                'anomaly_scores': combined_scores,
                'detection_method': 'statistical_with_peak_detection',
                'detection_confidence': 0.65,
                'geological_relevance': 0.6,
                'error_info': error_msg,
                'stream_id': stream_id,
                'fallback_reason': 'transformer_computation_failed',
                'recommendation': 'check_data_quality_and_dependencies'
            }
            
        except Exception as fallback_error:
            return self._basic_anomaly_detection_fallback(data, stream_id, str(fallback_error))
            
