    async def _assess_selection_bias_importance(self, state, action, reward, next_state, known_confounders):
        """Assess importance for selection bias detection."""
        selection_bias_factors = []
        
        # Sample selection indicators
        selection_indicators = await self._detect_sample_selection_indicators(
            state, action, reward, next_state
        )
        selection_bias_factors.append(selection_indicators)
        
        # Berkson's paradox detection
        berkson_detection = await self._detect_berksons_paradox(
            state, action, reward, next_state, known_confounders
        )
        selection_bias_factors.append(berkson_detection)
        
        # Survivorship bias assessment
        survivorship_bias = await self._assess_survivorship_bias(
            state, action, reward, next_state
        )
        selection_bias_factors.append(survivorship_bias)
        
        # Attrition bias evaluation
        attrition_bias = await self._evaluate_attrition_bias(
            state, action, reward, next_state
        )
        selection_bias_factors.append(attrition_bias)
        
        # Healthy worker effect detection
        healthy_worker_effect = await self._detect_healthy_worker_effect(
            state, action, reward, next_state
        )
        selection_bias_factors.append(healthy_worker_effect)
        
        return sum(selection_bias_factors) / len(selection_bias_factors)
    
    async def _assess_unmeasured_confounding_risk(self, state, action, reward, next_state, known_confounders):
        """Assess risk of unmeasured confounding."""
        unmeasured_risk_factors = []
        
        # E-value calculation
        e_value_analysis = await self._calculate_e_values(
            state, action, reward, next_state, known_confounders
        )
