    async def _rank_and_validate_feedback_loops(self, feedback_loops: List[Dict]) -> List[Dict]:
        """Rank and validate detected feedback loops."""
        try:
            # Calculate comprehensive ranking scores
            for loop in feedback_loops:
                ranking_score = (
                    0.25 * loop.get('strength', 0.0) +
                    0.20 * loop.get('strength_reliability', 0.0) +
                    0.15 * loop.get('geological_relevance', 0.5) +
                    0.15 * loop.get('flow_efficiency', 0.5) +
                    0.10 * loop.get('temporal_stability', 0.5) +
                    0.10 * loop.get('evolution_confidence', 0.5) +
                    0.05 * (1.0 if loop.get('statistically_significant', False) else 0.0)
                )
                loop['ranking_score'] = ranking_score
            
            # Sort by ranking score
            feedback_loops.sort(key=lambda x: x['ranking_score'], reverse=True)
            
            # Select top feedback loops
            top_feedback_loops = feedback_loops[:20]
            
            # Add validation metadata
            for i, loop in enumerate(top_feedback_loops):
                loop['validation_rank'] = i + 1
                loop['validation_confidence'] = min(1.0, loop['ranking_score'] / 0.8)
                loop['validation_status'] = 'validated' if loop['ranking_score'] > 0.6 else 'tentative'
            
            return top_feedback_loops
            
        except Exception as e:
            self.logger.error(f"Feedback loop ranking failed: {e}")
            return feedback_loops[:15]

    async def _enhanced_traditional_feedback_detection(self) -> List[Dict]:
        """Enhanced traditional feedback loop detection as fallback."""
        try:
            feedback_loops = []
            
            # Enhanced graph construction
            graph = self.causal_knowledge.get('discovered_relationships', {})
            
            # Build weighted adjacency representation
            adj_matrix, node_mapping = await self._build_weighted_adjacency_matrix(graph)
            
            # Strongly Connected Components detection
            scc_components = await self._detect_strongly_connected_components(adj_matrix)
            
            # Cycle enumeration with strength estimation
            for component in scc_components:
                if len(component) > 1:  # True cycles
                    cycle_strength = await self._estimate_cycle_strength(component, adj_matrix)
                    cycle_nodes = [list(node_mapping.keys())[i] for i in component]
                    
                    feedback_loops.append({
                        'nodes': cycle_nodes,
                        'strength': cycle_strength,
                        'detection_method': 'enhanced_traditional',
                        'component_size': len(component),
                        'ranking_score': cycle_strength,
                        'validation_status': 'fallback_detected'
                    })
            
            # Sort by strength
            feedback_loops.sort(key=lambda x: x['strength'], reverse=True)
            
            return feedback_loops[:10]
            
        except Exception as e:
            self.logger.error(f"Enhanced traditional detection failed: {e}")
            
            # Final fallback: simple cycle detection
            return await self._simple_cycle_detection_fallback()

    async def _simple_cycle_detection_fallback(self) -> List[Dict]:
        """Simple cycle detection as final fallback."""
        feedback_loops = []
        
        try:
            # Simple cycle detection from original implementation
            graph = self.causal_knowledge.get('discovered_relationships', {})
            
            # Build adjacency list
            adj_list = {}
            for edge in graph:
                if isinstance(edge, str) and '_to_' in edge:
                    parts = edge.split('_to_')
                    if len(parts) == 2:
                        source, target = parts
                        if source not in adj_list:
                            adj_list[source] = []
                        adj_list[source].append(target)
            
            # Find simple cycles
            visited = set()
            for node in adj_list:
                if node not in visited:
                    path = [node]
                    if await self._async_dfs_find_cycle(node, adj_list, visited, path):
                        feedback_loops.append({
                            'nodes': path,
                            'strength': 0.5,
                            'detection_method': 'simple_fallback',
                            'ranking_score': 0.5,
                            'validation_status': 'simple_detected'
                        })
            
            return feedback_loops[:5]
            
        except Exception as e:
            self.logger.error(f"Simple cycle detection failed: {e}")
            return []

    async def _async_dfs_find_cycle(self, node: str, adj_list: Dict, visited: set, path: List) -> bool:
        """Async DFS helper for cycle detection."""
        visited.add(node)
        
        if node in adj_list:
            for neighbor in adj_list[node]:
                if neighbor in path:
                    return True
                if neighbor not in visited:
                    path.append(neighbor)
                    if await self._async_dfs_find_cycle(neighbor, adj_list, visited, path):
                        return True
                    path.pop()
        
        return False
    
    async def _test_non_linearity(self, edge: str) -> float:
        """
        Comprehensive non-linearity testing using advanced statistical methods and geological physics validation.
        
        This method implements a sophisticated 8-component system for detecting and quantifying
        non-linear causal relationships in geological data, combining statistical rigor with
        domain-specific geological physics constraints.
        
        Args:
            edge: String representation of causal edge (format: "cause->effect")
            
        Returns:
            float: Non-linearity score [0, 1] with uncertainty bounds and geological validation
            
        Components:
        1. Polynomial and spline regression non-linearity detection
        2. Information-theoretic non-linearity measures (mutual information, entropy)
        3. Kernel-based non-parametric statistical tests (Hilbert-Schmidt Independence)
        4. Phase space reconstruction and embedding dimension analysis
        5. Geological physics-informed non-linearity constraints and validation
        6. Bootstrap confidence intervals and statistical significance testing
        7. Multi-scale wavelet analysis for frequency-dependent non-linearity
        8. Bayesian non-linear model comparison with uncertainty quantification
        """
        try:
            # Parse causal edge
            if '->' not in edge:
                self.logger.warning(f"Invalid edge format: {edge}")
                return 0.0
                
            cause, effect = edge.split('->')
            
            # Extract relevant data for cause-effect pair
            data_extraction_results = await self._extract_causal_pair_data(cause, effect)
            if not data_extraction_results:
                return await self._fallback_non_linearity_test(edge)
            
            # 1. Polynomial and spline regression non-linearity detection
            regression_non_linearity = await self._detect_regression_non_linearity(
                data_extraction_results, cause, effect
            )
            
            # 2. Information-theoretic non-linearity measures
            information_theoretic_measures = await self._compute_information_non_linearity(
                data_extraction_results, regression_non_linearity
            )
            
            # 3. Kernel-based non-parametric statistical tests
            kernel_statistical_tests = await self._perform_kernel_independence_tests(
                data_extraction_results, information_theoretic_measures
            )
            
            # 4. Phase space reconstruction and embedding analysis
            phase_space_non_linearity = await self._analyze_phase_space_non_linearity(
                kernel_statistical_tests, data_extraction_results
            )
            
            # 5. Geological physics-informed validation
            physics_validated_results = await self._validate_geological_physics_non_linearity(
                phase_space_non_linearity, cause, effect
            )
            
            # 6. Bootstrap confidence intervals and significance testing
            bootstrap_validated_results = await self._compute_bootstrap_non_linearity_confidence(
                physics_validated_results, data_extraction_results
            )
            
            # 7. Multi-scale wavelet analysis for frequency-dependent non-linearity
            wavelet_multi_scale_analysis = await self._perform_wavelet_non_linearity_analysis(
                bootstrap_validated_results, data_extraction_results
            )
            
            # 8. Bayesian non-linear model comparison with uncertainty quantification
            bayesian_model_comparison = await self._bayesian_non_linear_model_comparison(
                wavelet_multi_scale_analysis, cause, effect
            )
            
            # Integrate results with geological constraints
            final_non_linearity_score = await self._integrate_non_linearity_components(
                regression_non_linearity, information_theoretic_measures,
                kernel_statistical_tests, phase_space_non_linearity,
                physics_validated_results, bootstrap_validated_results,
                wavelet_multi_scale_analysis, bayesian_model_comparison
            )
            
            # Store non-linearity analysis results for model database integration
            await self._store_non_linearity_analysis(
                edge, final_non_linearity_score, bayesian_model_comparison
            )
            
            # Update performance tracking for MLOps pipeline integration
            await self._update_non_linearity_performance_tracking(
                edge, final_non_linearity_score, data_extraction_results
            )
            
            return min(1.0, max(0.0, final_non_linearity_score))
            
        except Exception as e:
            self.logger.error(f"Comprehensive non-linearity testing failed for {edge}: {e}")
            return await self._fallback_non_linearity_test(edge)
    
    async def _estimate_temporal_lag(self, edge: str) -> int:
        """
        Advanced temporal lag estimation using cross-correlation analysis and geological process timing.
        
        This method implements a sophisticated 8-component system for estimating temporal lags
        in causal relationships, combining statistical analysis with geological domain expertise
        and physics-informed constraints.
        
        Args:
            edge: String representation of causal edge (format: "cause->effect")
            
        Returns:
            int: Estimated temporal lag in time steps with confidence intervals
            
        Components:
        1. Cross-correlation analysis with multiple time series preprocessing approaches
        2. Granger causality lag optimization with information criteria (AIC, BIC, HQC)
        3. Geological process timing constraints and domain-specific lag priors
        4. Wavelet coherence analysis for frequency-dependent lag estimation
        5. Transfer entropy lag optimization with symbolic dynamics
        6. Phase-locking analysis and synchronization strength estimation
        7. Bayesian lag estimation with geological prior distributions
        8. Ensemble lag estimation with uncertainty quantification and confidence intervals
        """
        try:
            # Parse causal edge
            if '->' not in edge:
                self.logger.warning(f"Invalid edge format: {edge}")
                return 1
                
            cause, effect = edge.split('->')
            
            # Extract time series data for cause-effect pair
            time_series_data = await self._extract_temporal_causal_data(cause, effect)
            if not time_series_data:
                return await self._fallback_temporal_lag_estimation(edge)
            
            # 1. Cross-correlation analysis with multiple preprocessing approaches
            cross_correlation_results = await self._perform_cross_correlation_analysis(
                time_series_data, cause, effect
            )
            
            # 2. Granger causality lag optimization with information criteria
            granger_lag_optimization = await self._optimize_granger_causality_lag(
                time_series_data, cross_correlation_results
            )
            
            # 3. Geological process timing constraints and domain-specific priors
            geological_timing_constraints = await self._apply_geological_timing_constraints(
                granger_lag_optimization, cause, effect
            )
            
            # 4. Wavelet coherence analysis for frequency-dependent lag estimation
            wavelet_coherence_analysis = await self._analyze_wavelet_coherence_lag(
                geological_timing_constraints, time_series_data
            )
            
            # 5. Transfer entropy lag optimization with symbolic dynamics
            transfer_entropy_optimization = await self._optimize_transfer_entropy_lag(
                wavelet_coherence_analysis, time_series_data
            )
            
            # 6. Phase-locking analysis and synchronization strength estimation
            phase_locking_analysis = await self._analyze_phase_locking_lag(
                transfer_entropy_optimization, time_series_data
            )
            
            # 7. Bayesian lag estimation with geological prior distributions
            bayesian_lag_estimation = await self._bayesian_temporal_lag_estimation(
                phase_locking_analysis, cause, effect
            )
            
            # 8. Ensemble lag estimation with uncertainty quantification
            ensemble_lag_results = await self._ensemble_temporal_lag_estimation(
                cross_correlation_results, granger_lag_optimization,
                geological_timing_constraints, wavelet_coherence_analysis,
                transfer_entropy_optimization, phase_locking_analysis,
                bayesian_lag_estimation
            )
            
            # Extract final lag estimate with confidence bounds
            final_lag_estimate = await self._integrate_lag_estimation_components(
                ensemble_lag_results, cause, effect
            )
            
            # Validate against geological process timescales
            validated_lag = await self._validate_geological_process_timescales(
                final_lag_estimate, cause, effect, time_series_data
            )
            
            # Store temporal lag analysis results for model database integration
            await self._store_temporal_lag_analysis(
                edge, validated_lag, ensemble_lag_results
            )
            
            # Update performance tracking for MLOps pipeline integration
            await self._update_temporal_lag_performance_tracking(
                edge, validated_lag, time_series_data
            )
            
            return max(1, int(validated_lag))
            
        except Exception as e:
            self.logger.error(f"Advanced temporal lag estimation failed for {edge}: {e}")
            return await self._fallback_temporal_lag_estimation(edge)
    
