            if 'elevation' in spatial1 and 'elevation' in spatial2:
                elev_diff = abs(spatial1['elevation'] - spatial2['elevation'])
                elev_sim = 1.0 - min(elev_diff / 5000.0, 1.0)  # Normalize by 5km
                similarities.append(elev_sim)
            
