    def _compare_spatial_densities(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Compare spatial density distributions using kernel density estimation."""
        try:
            from sklearn.neighbors import KernelDensity
            from scipy.spatial.distance import wasserstein_distance
            from scipy.stats import entropy
            
            if len(coords1) < 2 or len(coords2) < 2:
                return 0.0
                
            # Determine optimal bounds for both datasets
            all_coords = np.vstack([coords1, coords2])
            x_min, x_max = all_coords[:, 0].min() - 1, all_coords[:, 0].max() + 1
            y_min, y_max = all_coords[:, 1].min() - 1, all_coords[:, 1].max() + 1
            
            # Create evaluation grid
            grid_size = min(100, int(np.sqrt(max(len(coords1), len(coords2)))))
            x_grid = np.linspace(x_min, x_max, grid_size)
            y_grid = np.linspace(y_min, y_max, grid_size)
            XX, YY = np.meshgrid(x_grid, y_grid)
            grid_points = np.vstack([XX.ravel(), YY.ravel()]).T
            
            # Adaptive bandwidth selection using Scott's rule
            n1, n2 = len(coords1), len(coords2)
            d = coords1.shape[1]  # dimensionality
            bandwidth1 = n1 ** (-1. / (d + 4))
            bandwidth2 = n2 ** (-1. / (d + 4))
            
            # Fit kernel density estimators
            kde1 = KernelDensity(bandwidth=bandwidth1, kernel='gaussian')
            kde2 = KernelDensity(bandwidth=bandwidth2, kernel='gaussian')
            
            kde1.fit(coords1)
            kde2.fit(coords2)
            
            # Evaluate densities on grid
            density1 = np.exp(kde1.score_samples(grid_points))
            density2 = np.exp(kde2.score_samples(grid_points))
            
            # Normalize densities
            density1 = density1 / np.sum(density1)
            density2 = density2 / np.sum(density2)
            
            # Multiple similarity measures
            similarities = []
            
            # 1. Wasserstein distance similarity
            wasserstein_dist = wasserstein_distance(density1, density2)
            max_possible_dist = np.sqrt(2)  # theoretical maximum for normalized densities
            wasserstein_sim = 1.0 - min(1.0, wasserstein_dist / max_possible_dist)
            similarities.append(wasserstein_sim)
            
            # 2. Jensen-Shannon divergence similarity
            def jensen_shannon_divergence(p, q):
                p, q = np.asarray(p), np.asarray(q)
                p, q = p / p.sum(), q / q.sum()  # normalize
                m = 0.5 * (p + q)
                return 0.5 * entropy(p, m, base=2) + 0.5 * entropy(q, m, base=2)
            
            js_div = jensen_shannon_divergence(density1, density2)
            js_sim = 1.0 - min(1.0, js_div)
            similarities.append(js_sim)
            
            # 3. Bhattacharyya coefficient
            bhatt_coeff = np.sum(np.sqrt(density1 * density2))
            similarities.append(bhatt_coeff)
            
            # 4. Cross-correlation at zero lag
            cross_corr = np.corrcoef(density1, density2)[0, 1]
            if not np.isnan(cross_corr):
                similarities.append((cross_corr + 1) / 2)  # normalize to [0,1]
            
            # 5. Overlap coefficient
            overlap = np.sum(np.minimum(density1, density2))
            similarities.append(overlap)
            
            # Weighted average of similarities
            weights = [0.25, 0.25, 0.2, 0.15, 0.15]
            final_similarity = np.average(similarities[:len(weights)], weights=weights[:len(similarities)])
            
            return float(np.clip(final_similarity, 0.0, 1.0))
            
        except Exception as e:
            # Fallback to simpler grid-based comparison
            try:
                # Create coarse grid
                all_coords = np.vstack([coords1, coords2])
                x_bins = np.linspace(all_coords[:, 0].min(), all_coords[:, 0].max(), 20)
                y_bins = np.linspace(all_coords[:, 1].min(), all_coords[:, 1].max(), 20)
                
                hist1, _, _ = np.histogram2d(coords1[:, 0], coords1[:, 1], bins=[x_bins, y_bins])
                hist2, _, _ = np.histogram2d(coords2[:, 0], coords2[:, 1], bins=[x_bins, y_bins])
                
                # Normalize
                hist1 = hist1 / np.sum(hist1) if np.sum(hist1) > 0 else hist1
                hist2 = hist2 / np.sum(hist2) if np.sum(hist2) > 0 else hist2
                
                # Compute correlation
                correlation = np.corrcoef(hist1.flatten(), hist2.flatten())[0, 1]
                return float((correlation + 1) / 2) if not np.isnan(correlation) else 0.0
                
            except Exception:
                return 0.0
    
    def _compare_value_distributions(self, values1: np.ndarray, values2: np.ndarray) -> float:
        """Compare value distributions at spatial locations."""
        try:
            # Statistical comparison of value distributions
            from scipy import stats
            statistic, p_value = stats.ks_2samp(values1, values2)
            return 1.0 - min(1.0, statistic)  # Convert to similarity
        except Exception:
            return 0.5
    
    def _compare_spatial_clusters(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Compare spatial clustering patterns using advanced clustering algorithms."""
        try:
            from sklearn.cluster import DBSCAN, AgglomerativeClustering
            from sklearn.metrics import silhouette_score, calinski_harabasz_score
            from scipy.spatial.distance import pdist, squareform
            from scipy.stats import ks_2samp
            
            if len(coords1) < 3 or len(coords2) < 3:
                return 0.0
            
            similarities = []
            
            # 1. DBSCAN clustering comparison
            def analyze_dbscan_clustering(coords):
                # Adaptive epsilon selection based on k-distance
                if len(coords) > 10:
                    distances = pdist(coords)
                    k = min(4, len(coords) // 3)
                    kth_distances = np.sort(pdist(coords))[::k]
                    eps = np.percentile(kth_distances, 75)
                else:
                    eps = np.std(pdist(coords)) * 0.5
                
                clustering = DBSCAN(eps=eps, min_samples=max(2, len(coords) // 10))
                labels = clustering.fit_predict(coords)
                
                # Extract clustering metrics
                n_clusters = len(set(labels)) - (1 if -1 in labels else 0)
                n_noise = list(labels).count(-1)
                noise_ratio = n_noise / len(coords) if len(coords) > 0 else 0
                
                # Silhouette score for non-noise points
                non_noise_mask = labels != -1
                if np.sum(non_noise_mask) > 1 and n_clusters > 1:
                    sil_score = silhouette_score(coords[non_noise_mask], labels[non_noise_mask])
                else:
                    sil_score = -1
                
                return {
                    'n_clusters': n_clusters,
                    'noise_ratio': noise_ratio,
                    'silhouette': sil_score,
                    'labels': labels
                }
            
            dbscan1 = analyze_dbscan_clustering(coords1)
            dbscan2 = analyze_dbscan_clustering(coords2)
            
            # Compare DBSCAN results
            cluster_sim = 1.0 - abs(dbscan1['n_clusters'] - dbscan2['n_clusters']) / max(dbscan1['n_clusters'], dbscan2['n_clusters'], 1)
            noise_sim = 1.0 - abs(dbscan1['noise_ratio'] - dbscan2['noise_ratio'])
            
            if dbscan1['silhouette'] > 0 and dbscan2['silhouette'] > 0:
                sil_sim = 1.0 - abs(dbscan1['silhouette'] - dbscan2['silhouette']) / 2
            else:
                sil_sim = 0.5
            
            dbscan_similarity = np.mean([cluster_sim, noise_sim, sil_sim])
            similarities.append(dbscan_similarity)
            
            # 2. Hierarchical clustering comparison
            def analyze_hierarchical_clustering(coords, n_clusters=None):
                if n_clusters is None:
                    n_clusters = max(2, min(len(coords) // 3, 10))
                
                clustering = AgglomerativeClustering(n_clusters=n_clusters, linkage='ward')
                labels = clustering.fit_predict(coords)
                
                # Compute clustering quality metrics
                sil_score = silhouette_score(coords, labels) if n_clusters > 1 else -1
                ch_score = calinski_harabasz_score(coords, labels) if n_clusters > 1 else 0
                
                return {
                    'labels': labels,
                    'silhouette': sil_score,
                    'calinski_harabasz': ch_score,
                    'n_clusters': n_clusters
                }
            
            # Use similar number of clusters for comparison
            n_clust = max(2, min(len(coords1) // 5, len(coords2) // 5, 8))
            hier1 = analyze_hierarchical_clustering(coords1, n_clust)
            hier2 = analyze_hierarchical_clustering(coords2, n_clust)
            
            hier_sil_sim = 1.0 - abs(hier1['silhouette'] - hier2['silhouette']) / 2 if hier1['silhouette'] > 0 and hier2['silhouette'] > 0 else 0.5
            hier_ch_sim = 1.0 - abs(hier1['calinski_harabasz'] - hier2['calinski_harabasz']) / max(hier1['calinski_harabasz'], hier2['calinski_harabasz'], 1)
            
            hierarchical_similarity = np.mean([hier_sil_sim, hier_ch_sim])
            similarities.append(hierarchical_similarity)
            
            # 3. Nearest neighbor distance distribution comparison
            def nn_distance_distribution(coords):
                distances = pdist(coords)
                if len(distances) == 0:
                    return np.array([0])
                # Get k nearest neighbors (k=3 for robustness)
                k = min(3, len(coords) - 1)
                nn_dists = []
                for i in range(len(coords)):
                    other_coords = np.delete(coords, i, axis=0)
                    if len(other_coords) > 0:
                        dists_to_others = np.linalg.norm(other_coords - coords[i], axis=1)
                        nn_dists.extend(sorted(dists_to_others)[:k])
                return np.array(nn_dists)
            
            nn_dist1 = nn_distance_distribution(coords1)
            nn_dist2 = nn_distance_distribution(coords2)
            
            if len(nn_dist1) > 0 and len(nn_dist2) > 0:
                # Kolmogorov-Smirnov test for distribution similarity
                ks_stat, p_value = ks_2samp(nn_dist1, nn_dist2)
                nn_similarity = 1.0 - min(1.0, ks_stat)
                similarities.append(nn_similarity)
            
            # 4. Clustering tendency comparison (Hopkins statistic)
            def hopkins_statistic(coords, n_samples=None):
                if n_samples is None:
                    n_samples = min(len(coords) // 2, 50)
                if n_samples < 2:
                    return 0.5
                
                # Sample points
                sample_indices = np.random.choice(len(coords), min(n_samples, len(coords)), replace=False)
                sampled_points = coords[sample_indices]
                
                # Generate uniform random points in same space
                min_vals = np.min(coords, axis=0)
                max_vals = np.max(coords, axis=0)
                uniform_points = np.random.uniform(min_vals, max_vals, (n_samples, coords.shape[1]))
                
                # Calculate nearest neighbor distances
                def nearest_distance(points, reference_set):
                    distances = []
                    for point in points:
                        dists = np.linalg.norm(reference_set - point, axis=1)
                        distances.append(np.min(dists[dists > 0]) if np.sum(dists > 0) > 0 else 0)
                    return np.array(distances)
                
                u_distances = nearest_distance(uniform_points, coords)
                w_distances = nearest_distance(sampled_points, coords)
                
                if np.sum(u_distances) + np.sum(w_distances) == 0:
                    return 0.5
                
                hopkins = np.sum(u_distances) / (np.sum(u_distances) + np.sum(w_distances))
                return hopkins
            
            hopkins1 = hopkins_statistic(coords1)
            hopkins2 = hopkins_statistic(coords2)
            
            hopkins_similarity = 1.0 - abs(hopkins1 - hopkins2)
            similarities.append(hopkins_similarity)
            
            # Weighted combination of all similarity measures
            weights = [0.3, 0.3, 0.25, 0.15]  # DBSCAN, Hierarchical, NN distances, Hopkins
            final_similarity = np.average(similarities[:len(weights)], weights=weights[:len(similarities)])
            
            return float(np.clip(final_similarity, 0.0, 1.0))
            
        except Exception as e:
            # Fallback to simple centroid-based comparison
            try:
                centroid1 = np.mean(coords1, axis=0)
                centroid2 = np.mean(coords2, axis=0)
                
                spread1 = np.mean(np.linalg.norm(coords1 - centroid1, axis=1))
                spread2 = np.mean(np.linalg.norm(coords2 - centroid2, axis=1))
                
                centroid_dist = np.linalg.norm(centroid1 - centroid2)
                max_spread = max(spread1, spread2, 1e-10)
                
                return float(max(0.0, 1.0 - centroid_dist / max_spread))
            except Exception:
                return 0.0
    
    def _compare_nearest_neighbor_distributions(self, coords1: np.ndarray, coords2: np.ndarray) -> float:
        """Compare nearest neighbor distance distributions with advanced statistical analysis."""
        try:
            from scipy.stats import ks_2samp, anderson_ksamp, wasserstein_distance
            from scipy.spatial.distance import cdist
            from sklearn.neighbors import NearestNeighbors
            
            if len(coords1) < 2 or len(coords2) < 2:
                return 0.0
            
            def comprehensive_nn_analysis(coords):
                """Perform comprehensive nearest neighbor analysis."""
                n_points = len(coords)
                if n_points < 2:
                    return {}
                
                # Multi-order nearest neighbor analysis (1st through kth neighbors)
                max_k = min(10, n_points - 1)
                nn_distances = {}
                
                nbrs = NearestNeighbors(n_neighbors=max_k + 1, algorithm='auto').fit(coords)
                distances, indices = nbrs.kneighbors(coords)
                
                # Skip first column (distance to self = 0)
                for k in range(1, max_k + 1):
                    nn_distances[f'{k}_nn'] = distances[:, k]
                
                # Aggregate statistics
                all_nn_distances = distances[:, 1:].flatten()  # All NN distances
                
                # Statistical moments
                mean_nn = np.mean(all_nn_distances)
                std_nn = np.std(all_nn_distances)
                skew_nn = float(stats.skew(all_nn_distances)) if len(all_nn_distances) > 0 else 0
                kurtosis_nn = float(stats.kurtosis(all_nn_distances)) if len(all_nn_distances) > 0 else 0
                
                # Nearest neighbor index (measure of clustering vs randomness)
                # R = observed mean / expected mean for random distribution
                area = (np.max(coords[:, 0]) - np.min(coords[:, 0])) * (np.max(coords[:, 1]) - np.min(coords[:, 1]))
                expected_mean_nn = 0.5 * np.sqrt(area / n_points) if area > 0 and n_points > 0 else 1
                nn_index = mean_nn / expected_mean_nn if expected_mean_nn > 0 else 1
                
                # Clark-Evans nearest neighbor index
                # Values: <1 clustered, =1 random, >1 dispersed
                clark_evans_index = mean_nn / (0.5 * np.sqrt(area / n_points)) if area > 0 and n_points > 0 else 1
                
                # Average nearest neighbor distance by order
                avg_distances_by_order = [np.mean(distances[:, k]) for k in range(1, min(6, max_k + 1))]
                
                # Distance variance analysis
                distance_variance = np.var(distances[:, 1])  # 1st NN variance
                coefficient_variation = std_nn / mean_nn if mean_nn > 0 else 0
                
                # Spatial randomness tests
                # Ripley's K-function approximation for small datasets
                def simplified_ripley_k(coords, r_values=None):
                    if r_values is None:
                        max_dist = np.max(all_nn_distances) if len(all_nn_distances) > 0 else 1
                        r_values = np.linspace(0.1 * max_dist, 0.5 * max_dist, 5)
                    
                    k_values = []
                    for r in r_values:
                        # Count pairs within distance r
                        pair_distances = cdist(coords, coords)
                        within_r = np.sum(pair_distances <= r) - n_points  # subtract diagonal
                        k_val = within_r / (n_points * (n_points - 1)) * area if n_points > 1 else 0
                        k_values.append(k_val)
                    return k_values
                
                ripley_k = simplified_ripley_k(coords)
                
                return {
                    'mean_nn': mean_nn,
                    'std_nn': std_nn,
                    'skewness': skew_nn,
                    'kurtosis': kurtosis_nn,
                    'nn_index': nn_index,
                    'clark_evans': clark_evans_index,
                    'distance_variance': distance_variance,
                    'cv': coefficient_variation,
                    'avg_by_order': avg_distances_by_order,
                    'ripley_k': ripley_k,
                    'all_distances': all_nn_distances,
                    'first_nn_distances': distances[:, 1]
                }
            
            # Analyze both coordinate sets
            analysis1 = comprehensive_nn_analysis(coords1)
            analysis2 = comprehensive_nn_analysis(coords2)
            
            if not analysis1 or not analysis2:
                return 0.0
            
            similarities = []
            
            # 1. Distribution similarity tests
            if len(analysis1['all_distances']) > 0 and len(analysis2['all_distances']) > 0:
                # Kolmogorov-Smirnov test
                ks_stat, ks_p = ks_2samp(analysis1['all_distances'], analysis2['all_distances'])
                ks_similarity = 1.0 - min(1.0, ks_stat)
                similarities.append(('ks_test', ks_similarity, 0.25))
                
                # Wasserstein distance
                wasserstein_dist = wasserstein_distance(analysis1['all_distances'], analysis2['all_distances'])
                max_dist = max(np.max(analysis1['all_distances']), np.max(analysis2['all_distances']))
                wasserstein_sim = 1.0 - min(1.0, wasserstein_dist / max_dist) if max_dist > 0 else 1.0
                similarities.append(('wasserstein', wasserstein_sim, 0.2))
            
            # 2. Statistical moments comparison
            moment_similarities = []
            
            # Mean similarity
            max_mean = max(analysis1['mean_nn'], analysis2['mean_nn'], 1e-10)
            mean_sim = 1.0 - abs(analysis1['mean_nn'] - analysis2['mean_nn']) / max_mean
            moment_similarities.append(mean_sim)
            
            # Standard deviation similarity
            max_std = max(analysis1['std_nn'], analysis2['std_nn'], 1e-10)
            std_sim = 1.0 - abs(analysis1['std_nn'] - analysis2['std_nn']) / max_std
            moment_similarities.append(std_sim)
            
            # Skewness similarity
            skew_sim = 1.0 - min(1.0, abs(analysis1['skewness'] - analysis2['skewness']) / 4.0)
            moment_similarities.append(skew_sim)
            
            # Kurtosis similarity
            kurtosis_sim = 1.0 - min(1.0, abs(analysis1['kurtosis'] - analysis2['kurtosis']) / 10.0)
            moment_similarities.append(kurtosis_sim)
            
            overall_moment_sim = np.mean(moment_similarities)
            similarities.append(('moments', overall_moment_sim, 0.2))
            
            # 3. Spatial pattern indices comparison
            pattern_similarities = []
            
            # Nearest neighbor index similarity
            max_nn_idx = max(analysis1['nn_index'], analysis2['nn_index'], 1e-10)
            nn_idx_sim = 1.0 - abs(analysis1['nn_index'] - analysis2['nn_index']) / max_nn_idx
            pattern_similarities.append(nn_idx_sim)
            
            # Clark-Evans index similarity
            max_ce = max(analysis1['clark_evans'], analysis2['clark_evans'], 1e-10)
            ce_sim = 1.0 - abs(analysis1['clark_evans'] - analysis2['clark_evans']) / max_ce
            pattern_similarities.append(ce_sim)
            
            # Coefficient of variation similarity
            max_cv = max(analysis1['cv'], analysis2['cv'], 1e-10)
            cv_sim = 1.0 - abs(analysis1['cv'] - analysis2['cv']) / max_cv
            pattern_similarities.append(cv_sim)
            
            overall_pattern_sim = np.mean(pattern_similarities)
            similarities.append(('patterns', overall_pattern_sim, 0.15))
            
            # 4. Multi-order neighbor comparison
            if analysis1['avg_by_order'] and analysis2['avg_by_order']:
                order_similarities = []
                min_orders = min(len(analysis1['avg_by_order']), len(analysis2['avg_by_order']))
                
                for i in range(min_orders):
                    max_dist = max(analysis1['avg_by_order'][i], analysis2['avg_by_order'][i], 1e-10)
                    order_sim = 1.0 - abs(analysis1['avg_by_order'][i] - analysis2['avg_by_order'][i]) / max_dist
                    order_similarities.append(order_sim)
                
                multi_order_sim = np.mean(order_similarities) if order_similarities else 0.5
                similarities.append(('multi_order', multi_order_sim, 0.1))
            
            # 5. Ripley's K-function comparison
            if analysis1['ripley_k'] and analysis2['ripley_k']:
                ripley_similarities = []
                min_k = min(len(analysis1['ripley_k']), len(analysis2['ripley_k']))
                
                for i in range(min_k):
                    max_k_val = max(analysis1['ripley_k'][i], analysis2['ripley_k'][i], 1e-10)
                    k_sim = 1.0 - abs(analysis1['ripley_k'][i] - analysis2['ripley_k'][i]) / max_k_val
                    ripley_similarities.append(k_sim)
                
                ripley_sim = np.mean(ripley_similarities) if ripley_similarities else 0.5
                similarities.append(('ripley', ripley_sim, 0.1))
            
            # Calculate weighted average
            total_weight = sum(weight for _, _, weight in similarities)
            if total_weight > 0:
                weighted_similarity = sum(sim * weight for _, sim, weight in similarities) / total_weight
            else:
                weighted_similarity = 0.5
            
            return float(np.clip(weighted_similarity, 0.0, 1.0))
            
        except Exception as e:
            # Fallback to simple nearest neighbor comparison
            try:
                from scipy.spatial.distance import cdist
                
                # Simple 1st nearest neighbor comparison
                def simple_nn_distances(coords):
                    if len(coords) < 2:
                        return np.array([0])
                    
                    distances = cdist(coords, coords)
                    np.fill_diagonal(distances, np.inf)  # Ignore self-distances
                    return np.min(distances, axis=1)
                
                nn1 = simple_nn_distances(coords1)
                nn2 = simple_nn_distances(coords2)
                
                if len(nn1) > 0 and len(nn2) > 0:
                    mean1, mean2 = np.mean(nn1), np.mean(nn2)
                    max_mean = max(mean1, mean2, 1e-10)
                    return float(1.0 - abs(mean1 - mean2) / max_mean)
                
                return 0.0
                
            except Exception:
                return 0.0
    
    # Spatial statistics methods (full implementations)
    def _morans_i_statistic(self, data: Dict) -> float:
        """Calculate Moran's I spatial autocorrelation statistic."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 3:
                return 0.0
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            # Create spatial weights matrix using inverse distance weighting
            from scipy.spatial.distance import cdist
            
            # Calculate distances
            distances = cdist(coords, coords)
            
            # Create weights matrix (inverse distance with threshold)
            weights = np.zeros_like(distances)
            
            # Use adaptive distance threshold (e.g., average of k-nearest neighbors)
            k = min(8, n - 1)  # Consider up to 8 nearest neighbors
            distance_thresholds = []
            
            for i in range(n):
                sorted_distances = np.sort(distances[i])[1:k+1]  # Exclude self (distance=0)
                if len(sorted_distances) > 0:
                    threshold = np.mean(sorted_distances)
                    distance_thresholds.append(threshold)
            
            avg_threshold = np.mean(distance_thresholds) if distance_thresholds else np.mean(distances[distances > 0])
            
            # Apply inverse distance weighting with cutoff
            for i in range(n):
                for j in range(n):
                    if i != j and distances[i, j] <= avg_threshold * 2:  # 2x threshold for connectivity
                        if distances[i, j] > 0:
                            weights[i, j] = 1.0 / distances[i, j]
                        else:
                            weights[i, j] = 0  # Same location
            
            # Row-standardize weights
            row_sums = np.sum(weights, axis=1)
            for i in range(n):
                if row_sums[i] > 0:
                    weights[i, :] /= row_sums[i]
            
            # Calculate Moran's I
            mean_val = np.mean(values)
            
            # Numerator: sum of weighted cross-products of deviations
            numerator = 0.0
            for i in range(n):
                for j in range(n):
                    numerator += weights[i, j] * (values[i] - mean_val) * (values[j] - mean_val)
            
            # Denominator: sum of squared deviations
            denominator = np.sum((values - mean_val) ** 2)
            
            # Total sum of weights
            S0 = np.sum(weights)
            
            if denominator > 0 and S0 > 0:
                morans_i = numerator / denominator
                
                # Expected value under null hypothesis of no spatial autocorrelation
                expected_i = -1.0 / (n - 1)
                
                # Variance calculation (simplified)
                S1 = 0.5 * np.sum((weights + weights.T) ** 2)
                S2 = np.sum(np.sum(weights, axis=1) ** 2)
                
                b2 = n * np.sum((values - mean_val) ** 4) / (np.sum((values - mean_val) ** 2) ** 2)
                
                var_i_num = (n * ((n**2 - 3*n + 3) * S1 - n*S2 + 3*S0**2) - 
                           b2 * ((n**2 - n) * S1 - 2*n*S2 + 6*S0**2))
                var_i_den = (n - 1) * (n - 2) * (n - 3) * S0**2
                
                if var_i_den != 0:
                    var_i = var_i_num / var_i_den - expected_i**2
                    
                    # Z-score (standardized Moran's I)
                    if var_i > 0:
                        z_score = (morans_i - expected_i) / np.sqrt(var_i)
                        
                        # Convert to similarity measure (0-1 scale)
                        # High positive values indicate clustering, high negative values indicate dispersion
                        # We convert to similarity where 1 = strong positive autocorrelation, 0 = strong negative
                        similarity = (morans_i + 1) / 2  # Rescale from [-1,1] to [0,1]
                        return float(np.clip(similarity, 0.0, 1.0))
                
                # Fallback: simple normalized Moran's I
                return float(np.clip((morans_i + 1) / 2, 0.0, 1.0))
            
            return 0.5  # Neutral value when calculation fails
            
        except Exception as e:
            # Fallback calculation using simple spatial correlation
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 2 or len(values) < 2:
                    return 0.5
                
                # Simple distance-weighted correlation
                from scipy.spatial.distance import pdist, squareform
                
                distances = squareform(pdist(coords))
                n = len(values)
                
                # Create simple binary connectivity (nearest neighbors)
                weights = np.zeros((n, n))
                for i in range(n):
                    if n > 1:
                        nearest_idx = np.argsort(distances[i])[1]  # Closest neighbor (excluding self)
                        weights[i, nearest_idx] = 1
                        weights[nearest_idx, i] = 1  # Make symmetric
                
                # Simple Moran's I calculation
                mean_val = np.mean(values)
                num = sum(weights[i, j] * (values[i] - mean_val) * (values[j] - mean_val) 
                         for i in range(n) for j in range(n))
                den = sum((values[i] - mean_val) ** 2 for i in range(n))
                W = sum(sum(weights[i, :]) for i in range(n))
                
                if den > 0 and W > 0:
                    moran = num / den
                    return float(np.clip((moran + 1) / 2, 0.0, 1.0))
                
                return 0.5
                
            except Exception:
                return 0.5
    
    def _gearys_c_statistic(self, data: Dict) -> float:
        """Calculate Geary's C spatial autocorrelation statistic."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 3:
                return 0.5
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            # Create spatial weights matrix using inverse distance weighting
            from scipy.spatial.distance import cdist
            
            distances = cdist(coords, coords)
            weights = np.zeros_like(distances)
            
            # Adaptive distance threshold based on nearest neighbors
            k = min(8, n - 1)
            avg_nn_distance = np.mean([np.mean(np.sort(distances[i])[1:k+1]) for i in range(n)])
            threshold = avg_nn_distance * 1.5
            
            # Create weights matrix with distance decay
            for i in range(n):
                for j in range(n):
                    if i != j and distances[i, j] <= threshold:
                        if distances[i, j] > 0:
                            weights[i, j] = np.exp(-distances[i, j] / (threshold / 3))  # Exponential decay
            
            # Row-standardize weights
            row_sums = np.sum(weights, axis=1)
            for i in range(n):
                if row_sums[i] > 0:
                    weights[i, :] /= row_sums[i]
            
            # Calculate Geary's C
            # C = (n-1)/(2*W) * sum_ij(w_ij * (x_i - x_j)^2) / sum_i(x_i - x_mean)^2
            
            mean_val = np.mean(values)
            
            # Numerator: weighted sum of squared differences
            numerator = 0.0
            for i in range(n):
                for j in range(n):
                    numerator += weights[i, j] * (values[i] - values[j]) ** 2
            
            # Denominator: sum of squared deviations from mean
            denominator = np.sum((values - mean_val) ** 2)
            
            # Total sum of weights
            W = np.sum(weights)
            
            if denominator > 0 and W > 0:
                gearys_c = (n - 1) * numerator / (2 * W * denominator)
                
                # Expected value under null hypothesis
                expected_c = 1.0
                
                # Variance calculation (simplified)
                S1 = 0.5 * np.sum((weights + weights.T) ** 2)
                S2 = np.sum(np.sum(weights, axis=1) ** 2)
                
                # Kurtosis term
                b2 = n * np.sum((values - mean_val) ** 4) / (np.sum((values - mean_val) ** 2) ** 2)
                
                # Variance of Geary's C
                term1 = (2 * S1 + S2) * (n - 1) - 4 * W**2
                term2 = (b2 - 1) * (2 * S1 - S2) * (n - 1) * (n - 2)
                
                var_c_num = term1 + term2
                var_c_den = 2 * (n + 1) * W**2
                
                if var_c_den > 0:
                    var_c = var_c_num / var_c_den
                    
                    # Z-score
                    if var_c > 0:
                        z_score = (gearys_c - expected_c) / np.sqrt(var_c)
                
                # Convert Geary's C to similarity measure
                # C = 1: no autocorrelation, C < 1: positive autocorrelation, C > 1: negative autocorrelation
                # We want similarity where 1 = strong positive autocorrelation, 0 = strong negative
                
                if gearys_c <= 1:
                    # Positive spatial autocorrelation (similarity increases as C approaches 0)
                    similarity = 1.0 - gearys_c  # Maps [0,1] -> [1,0]
                else:
                    # Negative spatial autocorrelation (similarity decreases as C increases above 1)
                    similarity = max(0.0, 1.0 - (gearys_c - 1.0))  # Maps [1,2] -> [0,-1], then clip to [0,0]
                
                return float(np.clip(similarity, 0.0, 1.0))
            
            return 0.5  # Neutral value
            
        except Exception as e:
            # Fallback calculation
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 2 or len(values) < 2:
                    return 0.5
                
                from scipy.spatial.distance import pdist, squareform
                
                distances = squareform(pdist(coords))
                n = len(values)
                mean_val = np.mean(values)
                
                # Simple binary weights (nearest neighbors)
                weights = np.zeros((n, n))
                for i in range(n):
                    if n > 1:
                        nearest_indices = np.argsort(distances[i])[1:min(4, n)]  # Up to 3 nearest neighbors
                        for j in nearest_indices:
                            weights[i, j] = 1.0 / len(nearest_indices)
                
                # Simple Geary's C
                numerator = sum(weights[i, j] * (values[i] - values[j]) ** 2 
                              for i in range(n) for j in range(n))
                denominator = sum((values[i] - mean_val) ** 2 for i in range(n))
                W = sum(sum(weights[i, :]) for i in range(n))
                
                if denominator > 0 and W > 0:
                    c = (n - 1) * numerator / (2 * W * denominator)
                    # Convert to similarity measure
                    similarity = max(0.0, 1.0 - abs(c - 1.0))  # Closer to 1 = higher similarity
                    return float(np.clip(similarity, 0.0, 1.0))
                
                return 0.5
                
            except Exception:
                return 0.5
    
    def _local_indicators_analysis(self, data: Dict) -> float:
        """Analyze local indicators of spatial association (LISA)."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 3:
                return 0.5
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            from scipy.spatial.distance import cdist
            from scipy import stats
            
            # Create spatial weights matrix
            distances = cdist(coords, coords)
            
            # Adaptive bandwidth for local analysis
            k = min(6, n - 1)
            local_bandwidths = []
            for i in range(n):
                knn_distances = np.sort(distances[i])[1:k+1]
                local_bandwidths.append(np.mean(knn_distances))
            
            # Calculate Local Moran's I for each location
            global_mean = np.mean(values)
            local_morans = []
            significant_locals = 0
            
            for i in range(n):
                # Local weights (neighbors within adaptive bandwidth)
                bandwidth = local_bandwidths[i] * 1.5  # Expand slightly
                weights_i = np.zeros(n)
                
                for j in range(n):
                    if i != j and distances[i, j] <= bandwidth:
                        if distances[i, j] > 0:
                            weights_i[j] = 1.0 / distances[i, j]
                
                # Row standardize
                weight_sum = np.sum(weights_i)
                if weight_sum > 0:
                    weights_i /= weight_sum
                
                # Calculate local Moran's I_i
                zi = values[i] - global_mean
                
                local_i = zi * np.sum(weights_i * (values - global_mean))
                local_morans.append(local_i)
                
                # Simple significance test (z-score > 1.96 for 95% confidence)
                if weight_sum > 0:
                    # Simplified variance calculation
                    variance_approx = np.sum(weights_i ** 2) * np.var(values)
                    if variance_approx > 0:
                        z_score = abs(local_i / np.sqrt(variance_approx))
                        if z_score > 1.96:  # Approximately significant
                            significant_locals += 1
            
            local_morans = np.array(local_morans)
            
            # Analyze local patterns
            analysis_results = {
                'mean_local_moran': np.mean(local_morans),
                'std_local_moran': np.std(local_morans),
                'significant_proportion': significant_locals / n if n > 0 else 0,
                'positive_locals': np.sum(local_morans > 0) / n if n > 0 else 0,
                'negative_locals': np.sum(local_morans < 0) / n if n > 0 else 0
            }
            
            # Identify local clusters and outliers
            # High-High: high value surrounded by high values (positive local Moran)
            # Low-Low: low value surrounded by low values (positive local Moran)
            # High-Low: high value surrounded by low values (negative local Moran)
            # Low-High: low value surrounded by high values (negative local Moran)
            
            median_value = np.median(values)
            cluster_types = {'HH': 0, 'LL': 0, 'HL': 0, 'LH': 0}
            
            for i in range(n):
                if abs(local_morans[i]) > np.std(local_morans):  # Only significant locals
                    is_high = values[i] > median_value
                    is_positive_local = local_morans[i] > 0
                    
                    if is_high and is_positive_local:
                        cluster_types['HH'] += 1
                    elif not is_high and is_positive_local:
                        cluster_types['LL'] += 1
                    elif is_high and not is_positive_local:
                        cluster_types['HL'] += 1
                    else:
                        cluster_types['LH'] += 1
            
            # Calculate spatial heterogeneity measures
            heterogeneity = np.std(local_morans) / (abs(np.mean(local_morans)) + 1e-10)
            
            # Create comprehensive LISA score
            # Higher values indicate stronger and more significant local spatial patterns
            lisa_score = (
                0.3 * analysis_results['significant_proportion'] +
                0.2 * min(1.0, abs(analysis_results['mean_local_moran'])) +
                0.2 * (1.0 - min(1.0, heterogeneity)) +  # Less heterogeneity = more coherent patterns
                0.15 * analysis_results['positive_locals'] +
                0.15 * (1.0 - analysis_results['negative_locals'])  # Fewer outliers = better
            )
            
            return float(np.clip(lisa_score, 0.0, 1.0))
            
        except Exception as e:
            # Fallback to simple local variance analysis
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 3 or len(values) < 3:
                    return 0.5
                
                from scipy.spatial.distance import cdist
                
                distances = cdist(coords, coords)
                n = len(values)
                local_variations = []
                
                # Simple local variation analysis
                for i in range(n):
                    # Find nearest neighbors
                    neighbor_indices = np.argsort(distances[i])[1:min(4, n)]  # 3 nearest neighbors
                    neighbor_values = values[neighbor_indices]
                    
                    # Calculate local variation
                    local_mean = np.mean(neighbor_values)
                    local_var = np.var(neighbor_values) if len(neighbor_values) > 1 else 0
                    
                    # Local association measure
                    central_deviation = abs(values[i] - np.mean(values))
                    neighbor_deviation = abs(local_mean - np.mean(values))
                    
                    if central_deviation + neighbor_deviation > 0:
                        local_assoc = 1.0 - abs(central_deviation - neighbor_deviation) / (central_deviation + neighbor_deviation)
                    else:
                        local_assoc = 1.0
                    
                    local_variations.append(local_assoc)
                
                return float(np.clip(np.mean(local_variations), 0.0, 1.0))
                
            except Exception:
                return 0.5
    
    def _getis_ord_statistics(self, data: Dict) -> float:
        """Calculate Getis-Ord spatial statistics (G and G*)."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 3:
                return 0.5
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            from scipy.spatial.distance import cdist
            from scipy import stats
            
            # Calculate distance matrix
            distances = cdist(coords, coords)
            
            # Determine critical distance (bandwidth) for neighborhood definition
            # Use average of k-nearest neighbor distances
            k = min(6, n - 1)
            critical_distances = []
            for i in range(n):
                knn_dists = np.sort(distances[i])[1:k+1]
                critical_distances.append(np.mean(knn_dists))
            
            avg_critical_distance = np.mean(critical_distances) * 1.2  # Slightly expand
            
            # Global statistics
            global_mean = np.mean(values)
            global_var = np.var(values)
            global_sum = np.sum(values)
            
            # Calculate G* statistics (includes focal location)
            g_star_stats = []
            significant_hotspots = 0
            significant_coldspots = 0
            
            for i in range(n):
                # Define neighborhood (including focal point)
                neighbors = distances[i] <= avg_critical_distance
                neighbor_indices = np.where(neighbors)[0]
                
                if len(neighbor_indices) < 2:  # Need at least focal + 1 neighbor
                    g_star_stats.append(0.0)
                    continue
                
                # Calculate G*_i statistic
                neighbor_values = values[neighbor_indices]
                neighbor_sum = np.sum(neighbor_values)
                num_neighbors = len(neighbor_indices)
                
                # G*_i = (sum of neighbor values) / (sum of all values)
                g_star_i = neighbor_sum / global_sum if global_sum > 0 else 0
                
                # Expected value and variance for G*_i
                expected_g_star = num_neighbors / n
                
                # Variance calculation
                if n > 1 and global_var > 0:
                    var_numerator = num_neighbors * (n - num_neighbors) * global_var
                    var_denominator = (n - 1) * (global_sum ** 2 / n)
                    
                    if var_denominator > 0:
                        var_g_star = var_numerator / var_denominator
                        
                        # Z-score
                        if var_g_star > 0:
                            z_score = (g_star_i - expected_g_star) / np.sqrt(var_g_star)
                            
                            # Classify as significant hotspot or coldspot
                            if z_score > 1.96:  # 95% confidence
                                significant_hotspots += 1
                            elif z_score < -1.96:
                                significant_coldspots += 1
                            
                            g_star_stats.append(z_score)
                        else:
                            g_star_stats.append(0.0)
                    else:
                        g_star_stats.append(0.0)
                else:
                    g_star_stats.append(0.0)
            
            g_star_stats = np.array(g_star_stats)
            
            # Calculate G statistics (excludes focal location)
            g_stats = []
            for i in range(n):
                # Define neighborhood (excluding focal point)
                neighbors = (distances[i] <= avg_critical_distance) & (distances[i] > 0)
                neighbor_indices = np.where(neighbors)[0]
                
                if len(neighbor_indices) < 1:
                    g_stats.append(0.0)
                    continue
                
                # Calculate G_i statistic
                neighbor_values = values[neighbor_indices]
                neighbor_sum = np.sum(neighbor_values)
                remaining_sum = global_sum - values[i]  # Exclude focal value
                
                g_i = neighbor_sum / remaining_sum if remaining_sum > 0 else 0
                g_stats.append(g_i)
            
            g_stats = np.array(g_stats)
            
            # Comprehensive Getis-Ord analysis results
            analysis_results = {
                'mean_g_star': np.mean(g_star_stats),
                'std_g_star': np.std(g_star_stats),
                'mean_g': np.mean(g_stats),
                'std_g': np.std(g_stats),
                'hotspot_proportion': significant_hotspots / n if n > 0 else 0,
                'coldspot_proportion': significant_coldspots / n if n > 0 else 0,
                'spatial_clustering_strength': np.std(g_star_stats),  # Higher std = more clustering
                'positive_autocorr_locations': np.sum(g_star_stats > 0) / n if n > 0 else 0
            }
            
            # Calculate overall Getis-Ord spatial pattern strength
            # High values indicate strong spatial clustering (hot/cold spots)
            pattern_strength = (
                0.25 * analysis_results['hotspot_proportion'] +
                0.25 * analysis_results['coldspot_proportion'] +
                0.2 * min(1.0, analysis_results['spatial_clustering_strength']) +
                0.15 * analysis_results['positive_autocorr_locations'] +
                0.15 * min(1.0, abs(analysis_results['mean_g_star']))
            )
            
            return float(np.clip(pattern_strength, 0.0, 1.0))
            
        except Exception as e:
            # Fallback to simple hot/cold spot detection
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 3 or len(values) < 3:
                    return 0.5
                
                from scipy.spatial.distance import cdist
                
                distances = cdist(coords, coords)
                n = len(values)
                global_mean = np.mean(values)
                
                # Simple hot/cold spot analysis
                local_intensity_ratios = []
                
                for i in range(n):
                    # Find nearest neighbors
                    neighbor_indices = np.argsort(distances[i])[1:min(5, n)]  # 4 nearest neighbors
                    neighbor_values = values[neighbor_indices]
                    
                    if len(neighbor_values) > 0:
                        local_mean = np.mean(neighbor_values)
                        # Ratio of local mean to global mean (hotspot indicator)
                        ratio = local_mean / global_mean if global_mean != 0 else 1
                        local_intensity_ratios.append(abs(ratio - 1))  # Deviation from expected
                
                if local_intensity_ratios:
                    # Higher values indicate stronger hot/cold spot patterns
                    return float(np.clip(np.mean(local_intensity_ratios), 0.0, 1.0))
                
                return 0.5
                
            except Exception:
                return 0.5
    
    def _variogram_analysis(self, data: Dict) -> float:
        """Perform variogram analysis for spatial correlation."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 4:
                return 0.5
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            from scipy.spatial.distance import pdist, squareform
            from scipy.optimize import curve_fit
            
            # Calculate all pairwise distances and semivariances
            distances = squareform(pdist(coords))
            
            # Calculate experimental variogram
            max_distance = np.max(distances) * 0.5  # Only use up to half max distance
            n_lags = min(15, n // 2)  # Reasonable number of lag classes
            lag_interval = max_distance / n_lags
            
            lag_centers = []
            semivariances = []
            pair_counts = []
            
            for lag in range(1, n_lags + 1):
                lag_min = (lag - 1) * lag_interval
                lag_max = lag * lag_interval
                lag_center = (lag_min + lag_max) / 2
                
                # Find all pairs within this lag distance
                pairs_in_lag = []
                for i in range(n):
                    for j in range(i + 1, n):
                        dist = distances[i, j]
                        if lag_min < dist <= lag_max:
                            semivar = 0.5 * (values[i] - values[j]) ** 2
                            pairs_in_lag.append(semivar)
                
                if len(pairs_in_lag) >= 2:  # Need minimum pairs for reliable estimate
                    lag_centers.append(lag_center)
                    semivariances.append(np.mean(pairs_in_lag))
                    pair_counts.append(len(pairs_in_lag))
            
            if len(lag_centers) < 3:  # Need minimum points to fit variogram
                return 0.5
            
            lag_centers = np.array(lag_centers)
            semivariances = np.array(semivariances)
            pair_counts = np.array(pair_counts)
            
            # Theoretical variogram models
            def spherical_model(h, nugget, sill, range_param):
                """Spherical variogram model."""
                result = np.zeros_like(h)
                mask = h <= range_param
                result[mask] = nugget + (sill - nugget) * (1.5 * h[mask] / range_param - 0.5 * (h[mask] / range_param) ** 3)
                result[~mask] = sill
                return result
            
            def exponential_model(h, nugget, sill, range_param):
                """Exponential variogram model."""
                return nugget + (sill - nugget) * (1 - np.exp(-3 * h / range_param))
            
            def gaussian_model(h, nugget, sill, range_param):
                """Gaussian variogram model."""
                return nugget + (sill - nugget) * (1 - np.exp(-3 * (h / range_param) ** 2))
            
            def linear_model(h, nugget, slope):
                """Linear variogram model."""
                return nugget + slope * h
            
            # Fit different variogram models
            models = {
                'spherical': (spherical_model, 3),
                'exponential': (exponential_model, 3),
                'gaussian': (gaussian_model, 3),
                'linear': (linear_model, 2)
            }
            
            best_model = None
            best_params = None
            best_r_squared = -np.inf
            best_model_name = ''
            
            # Initial parameter estimates
            max_semivar = np.max(semivariances)
            min_semivar = np.min(semivariances)
            max_distance_fit = np.max(lag_centers)
            
            for model_name, (model_func, n_params) in models.items():
                try:
                    if n_params == 3:  # Nugget, sill, range
                        initial_guess = [min_semivar, max_semivar, max_distance_fit / 3]
                        bounds = ([0, min_semivar, 0], [max_semivar, max_semivar * 2, max_distance_fit])
                    else:  # Linear: nugget, slope
                        slope_estimate = (max_semivar - min_semivar) / max_distance_fit
                        initial_guess = [min_semivar, slope_estimate]
                        bounds = ([0, 0], [max_semivar, slope_estimate * 10])
                    
                    # Weighted fitting (more weight to lags with more pairs)
                    weights = np.sqrt(pair_counts)
                    
                    popt, pcov = curve_fit(model_func, lag_centers, semivariances, 
                                         p0=initial_guess, bounds=bounds, 
                                         sigma=1/weights, maxfev=1000)
                    
                    # Calculate R-squared
                    predicted = model_func(lag_centers, *popt)
                    ss_res = np.sum((semivariances - predicted) ** 2)
                    ss_tot = np.sum((semivariances - np.mean(semivariances)) ** 2)
                    r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                    
                    if r_squared > best_r_squared:
                        best_r_squared = r_squared
                        best_model = model_func
                        best_params = popt
                        best_model_name = model_name
                        
                except Exception:
                    continue
            
            # Analyze variogram characteristics
            if best_params is not None and len(best_params) >= 2:
                analysis_results = {
                    'model_fit_quality': max(0, best_r_squared),
                    'spatial_structure_strength': 0,
                    'range_effectiveness': 0,
                    'nugget_effect': 0
                }
                
                if best_model_name in ['spherical', 'exponential', 'gaussian'] and len(best_params) == 3:
                    nugget, sill, range_param = best_params
                    
                    # Spatial structure strength (proportion of spatially structured variance)
                    if sill > 0:
                        structure_strength = (sill - nugget) / sill
                        analysis_results['spatial_structure_strength'] = max(0, min(1, structure_strength))
                    
                    # Range effectiveness (normalized range)
                    max_dist = np.max(lag_centers)
                    if max_dist > 0:
                        analysis_results['range_effectiveness'] = min(1, range_param / max_dist)
                    
                    # Nugget effect (measure of micro-scale variability)
                    if sill > 0:
                        analysis_results['nugget_effect'] = 1 - min(1, nugget / sill)
                
                elif best_model_name == 'linear':
                    # Linear model indicates trend or lack of sill
                    nugget, slope = best_params
                    analysis_results['spatial_structure_strength'] = min(1, slope / max_semivar) if max_semivar > 0 else 0
                    analysis_results['range_effectiveness'] = 0.5  # Intermediate for linear
                    analysis_results['nugget_effect'] = 0.5
                
                # Overall variogram quality score
                variogram_score = (
                    0.4 * analysis_results['model_fit_quality'] +
                    0.3 * analysis_results['spatial_structure_strength'] +
                    0.2 * analysis_results['range_effectiveness'] +
                    0.1 * analysis_results['nugget_effect']
                )
                
                return float(np.clip(variogram_score, 0.0, 1.0))
            
            # Fallback: simple correlation analysis
            if len(semivariances) > 1:
                # Check for spatial correlation by examining variogram shape
                correlation_coeff = np.corrcoef(lag_centers, semivariances)[0, 1]
                if not np.isnan(correlation_coeff):
                    # Positive correlation suggests spatial structure
                    return float(np.clip((correlation_coeff + 1) / 2, 0.0, 1.0))
            
            return 0.5
            
        except Exception as e:
            # Simple fallback variogram
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 3 or len(values) < 3:
                    return 0.5
                
                from scipy.spatial.distance import pdist, squareform
                
                distances = squareform(pdist(coords))
                n = len(values)
                
                # Simple binned variogram
                max_dist = np.max(distances) * 0.5
                n_bins = min(5, n // 2)
                bin_edges = np.linspace(0, max_dist, n_bins + 1)
                
                bin_variances = []
                for i in range(n_bins):
                    bin_pairs = []
                    for j in range(n):
                        for k in range(j + 1, n):
                            dist = distances[j, k]
                            if bin_edges[i] < dist <= bin_edges[i + 1]:
                                semivar = 0.5 * (values[j] - values[k]) ** 2
                                bin_pairs.append(semivar)
                    
                    if len(bin_pairs) > 0:
                        bin_variances.append(np.mean(bin_pairs))
                
                if len(bin_variances) > 1:
                    # Simple trend analysis
                    trend = np.polyfit(range(len(bin_variances)), bin_variances, 1)[0]
                    # Positive trend suggests spatial correlation
                    return float(np.clip((trend / np.var(values) + 1) / 2, 0.0, 1.0)) if np.var(values) > 0 else 0.5
                
                return 0.5
                
            except Exception:
                return 0.5
    
    def _covariogram_analysis(self, data: Dict) -> float:
        """Perform covariogram analysis for spatial covariance structure."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or values is None or len(coords) != len(values) or len(coords) < 4:
                return 0.5
            
            coords = np.asarray(coords)
            values = np.asarray(values)
            n = len(values)
            
            from scipy.spatial.distance import pdist, squareform
            from scipy.optimize import curve_fit
            
            # Calculate distances and global statistics
            distances = squareform(pdist(coords))
            global_mean = np.mean(values)
            global_var = np.var(values)
            
            if global_var == 0:  # No variation in data
                return 0.5
            
            # Calculate experimental covariogram
            max_distance = np.max(distances) * 0.5
            n_lags = min(12, n // 2)
            lag_interval = max_distance / n_lags
            
            lag_centers = []
            covariances = []
            pair_counts = []
            
            for lag in range(1, n_lags + 1):
                lag_min = (lag - 1) * lag_interval
                lag_max = lag * lag_interval
                lag_center = (lag_min + lag_max) / 2
                
                # Calculate covariance for pairs within this lag distance
                covar_pairs = []
                for i in range(n):
                    for j in range(i + 1, n):
                        dist = distances[i, j]
                        if lag_min < dist <= lag_max:
                            # Covariance = (x_i - mean) * (x_j - mean)
                            covar = (values[i] - global_mean) * (values[j] - global_mean)
                            covar_pairs.append(covar)
                
                if len(covar_pairs) >= 2:
                    lag_centers.append(lag_center)
                    covariances.append(np.mean(covar_pairs))
                    pair_counts.append(len(covar_pairs))
            
            if len(lag_centers) < 3:
                return 0.5
            
            lag_centers = np.array(lag_centers)
            covariances = np.array(covariances)
            pair_counts = np.array(pair_counts)
            
            # Normalize covariances by global variance
            normalized_covariances = covariances / global_var
            
            # Theoretical covariance models
            def exponential_cov(h, sill, range_param):
                """Exponential covariance model."""
                return sill * np.exp(-h / range_param)
            
            def gaussian_cov(h, sill, range_param):
                """Gaussian covariance model."""
                return sill * np.exp(-(h / range_param) ** 2)
            
            def spherical_cov(h, sill, range_param):
                """Spherical covariance model."""
                result = np.zeros_like(h)
                mask = h <= range_param
                result[mask] = sill * (1 - 1.5 * h[mask] / range_param + 0.5 * (h[mask] / range_param) ** 3)
                result[~mask] = 0
                return result
            
            def matern_cov(h, sill, range_param, nu=1.5):
                """Matérn covariance model."""
                from scipy.special import kv, gamma
                if nu == 0.5:  # Exponential
                    return sill * np.exp(-h / range_param)
                elif nu == 1.5:
                    scaled_dist = np.sqrt(3) * h / range_param
                    return sill * (1 + scaled_dist) * np.exp(-scaled_dist)
                else:
                    # General Matérn (simplified)
                    scaled_dist = h / range_param
                    return sill * np.exp(-scaled_dist)
            
            # Fit covariance models
            models = {
                'exponential': exponential_cov,
                'gaussian': gaussian_cov,
                'spherical': spherical_cov,
                'matern': matern_cov
            }
            
            best_model = None
            best_params = None
            best_r_squared = -np.inf
            best_model_name = ''
            
            # Estimate initial parameters
            max_covar = max(abs(np.max(normalized_covariances)), abs(np.min(normalized_covariances)))
            effective_range = np.max(lag_centers) / 3
            
            for model_name, model_func in models.items():
                try:
                    # Initial parameter guesses
                    if normalized_covariances[0] > 0:  # Positive correlation at short distances
                        initial_sill = max_covar
                    else:
                        initial_sill = max_covar
                    
                    initial_guess = [initial_sill, effective_range]
                    bounds = ([0, 0], [max_covar * 2, np.max(lag_centers)])
                    
                    # Weight by number of pairs
                    weights = np.sqrt(pair_counts)
                    
                    popt, pcov = curve_fit(model_func, lag_centers, normalized_covariances,
                                         p0=initial_guess, bounds=bounds,
                                         sigma=1/weights, maxfev=1000)
                    
                    # Calculate goodness of fit
                    predicted = model_func(lag_centers, *popt)
                    ss_res = np.sum((normalized_covariances - predicted) ** 2)
                    ss_tot = np.sum((normalized_covariances - np.mean(normalized_covariances)) ** 2)
                    r_squared = 1 - (ss_res / ss_tot) if ss_tot > 0 else 0
                    
                    if r_squared > best_r_squared:
                        best_r_squared = r_squared
                        best_model = model_func
                        best_params = popt
                        best_model_name = model_name
                        
                except Exception:
                    continue
            
            # Analyze covariance structure
            if best_params is not None and len(best_params) >= 2:
                sill, range_param = best_params[:2]
                
                # Covariance analysis metrics
                analysis_results = {
                    'model_fit_quality': max(0, best_r_squared),
                    'correlation_strength': 0,
                    'effective_range': 0,
                    'correlation_decay_rate': 0,
                    'positive_correlation_extent': 0
                }
                
                # Correlation strength (normalized sill)
                if global_var > 0:
                    analysis_results['correlation_strength'] = min(1, abs(sill))
                
                # Effective range (normalized)
                max_dist = np.max(lag_centers)
                if max_dist > 0:
                    analysis_results['effective_range'] = min(1, range_param / max_dist)
                
                # Correlation decay rate
                if len(lag_centers) > 1 and range_param > 0:
                    # Measure how quickly correlation decays
                    mid_distance = np.max(lag_centers) / 2
                    mid_correlation = best_model(mid_distance, *best_params)
                    if sill > 0:
                        decay_rate = 1 - abs(mid_correlation / sill)
                        analysis_results['correlation_decay_rate'] = min(1, decay_rate)
                
                # Extent of positive correlation
                positive_correlations = normalized_covariances > 0
                if len(positive_correlations) > 0:
                    analysis_results['positive_correlation_extent'] = np.mean(positive_correlations)
                
                # Overall covariance structure quality
                covariance_score = (
                    0.3 * analysis_results['model_fit_quality'] +
                    0.25 * analysis_results['correlation_strength'] +
                    0.2 * analysis_results['effective_range'] +
                    0.15 * analysis_results['positive_correlation_extent'] +
                    0.1 * (1 - analysis_results['correlation_decay_rate'])  # Slower decay = better structure
                )
                
                return float(np.clip(covariance_score, 0.0, 1.0))
            
            # Fallback analysis
            if len(normalized_covariances) > 0:
                # Simple metrics
                initial_correlation = abs(normalized_covariances[0]) if len(normalized_covariances) > 0 else 0
                mean_positive_correlation = np.mean(normalized_covariances[normalized_covariances > 0]) if np.any(normalized_covariances > 0) else 0
                correlation_range = np.max(normalized_covariances) - np.min(normalized_covariances) if len(normalized_covariances) > 0 else 0
                
                fallback_score = (
                    0.4 * min(1, initial_correlation) +
                    0.3 * min(1, mean_positive_correlation) +
                    0.3 * min(1, correlation_range)
                )
                
                return float(np.clip(fallback_score, 0.0, 1.0))
            
            return 0.5
            
        except Exception as e:
            # Simple covariance estimation
            try:
                coords = np.asarray(data.get('coordinates', []))
                values = np.asarray(data.get('values', []))
                
                if len(coords) < 3 or len(values) < 3:
                    return 0.5
                
                from scipy.spatial.distance import pdist, squareform
                
                distances = squareform(pdist(coords))
                global_mean = np.mean(values)
                n = len(values)
                
                # Simple distance-binned covariance
                short_range_covar = 0
                long_range_covar = 0
                short_count = 0
                long_count = 0
                
                median_distance = np.median(distances[distances > 0])
                
                for i in range(n):
                    for j in range(i + 1, n):
                        dist = distances[i, j]
                        covar = (values[i] - global_mean) * (values[j] - global_mean)
                        
                        if dist <= median_distance:
                            short_range_covar += covar
                            short_count += 1
                        else:
                            long_range_covar += covar
                            long_count += 1
                
                short_avg = short_range_covar / short_count if short_count > 0 else 0
                long_avg = long_range_covar / long_count if long_count > 0 else 0
                
                # Covariance structure indicator
                if np.var(values) > 0:
                    short_correlation = short_avg / np.var(values)
                    covariance_strength = min(1, abs(short_correlation))
                    return float(covariance_strength)
                
                return 0.5
                
            except Exception:
                return 0.5
    
    # Shape analysis methods (full implementations)
    def _geometric_moments_analysis(self, data: Dict) -> Dict:
        """Analyze geometric moments for shape characterization."""
        try:
            coords = data.get('coordinates')
            if coords is None or len(coords) < 3:
                return {'moments': [0, 0, 0], 'central_moments': [0, 0, 0], 'normalized_moments': [0, 0, 0]}
            
            coords = np.asarray(coords)
            
            # Calculate centroid
            centroid = np.mean(coords, axis=0)
            
            # Center coordinates
            centered_coords = coords - centroid
            
            # Raw moments (up to 3rd order)
            raw_moments = []
            
            # 0th moment (area/count)
            m00 = len(coords)
            raw_moments.append(m00)
            
            # 1st moments (centroid * area)
            m10 = np.sum(coords[:, 0])
            m01 = np.sum(coords[:, 1])
            raw_moments.extend([m10, m01])
            
            # 2nd moments
            m20 = np.sum(coords[:, 0] ** 2)
            m11 = np.sum(coords[:, 0] * coords[:, 1])
            m02 = np.sum(coords[:, 1] ** 2)
            raw_moments.extend([m20, m11, m02])
            
            # 3rd moments  
            m30 = np.sum(coords[:, 0] ** 3)
            m21 = np.sum((coords[:, 0] ** 2) * coords[:, 1])
            m12 = np.sum(coords[:, 0] * (coords[:, 1] ** 2))
            m03 = np.sum(coords[:, 1] ** 3)
            raw_moments.extend([m30, m21, m12, m03])
            
            # Central moments (translation invariant)
            central_moments = []
            
            # 2nd central moments
            mu20 = np.sum((coords[:, 0] - centroid[0]) ** 2)
            mu11 = np.sum((coords[:, 0] - centroid[0]) * (coords[:, 1] - centroid[1]))
            mu02 = np.sum((coords[:, 1] - centroid[1]) ** 2)
            central_moments.extend([mu20, mu11, mu02])
            
            # 3rd central moments
            mu30 = np.sum((coords[:, 0] - centroid[0]) ** 3)
            mu21 = np.sum(((coords[:, 0] - centroid[0]) ** 2) * (coords[:, 1] - centroid[1]))
            mu12 = np.sum((coords[:, 0] - centroid[0]) * ((coords[:, 1] - centroid[1]) ** 2))
            mu03 = np.sum((coords[:, 1] - centroid[1]) ** 3)
            central_moments.extend([mu30, mu21, mu12, mu03])
            
            # Normalized central moments (scale invariant)
            normalized_moments = []
            if m00 > 0:
                # Hu moments (7 invariant moments)
                eta20 = mu20 / (m00 ** 2)
                eta11 = mu11 / (m00 ** 2)
                eta02 = mu02 / (m00 ** 2)
                eta30 = mu30 / (m00 ** 2.5)
                eta21 = mu21 / (m00 ** 2.5)
                eta12 = mu12 / (m00 ** 2.5)
                eta03 = mu03 / (m00 ** 2.5)
                
                # Hu's 7 invariant moments
                hu1 = eta20 + eta02
                hu2 = (eta20 - eta02) ** 2 + 4 * eta11 ** 2
                hu3 = (eta30 - 3 * eta12) ** 2 + (3 * eta21 - eta03) ** 2
                hu4 = (eta30 + eta12) ** 2 + (eta21 + eta03) ** 2
                hu5 = (eta30 - 3 * eta12) * (eta30 + eta12) * ((eta30 + eta12) ** 2 - 3 * (eta21 + eta03) ** 2) + \
                      (3 * eta21 - eta03) * (eta21 + eta03) * (3 * (eta30 + eta12) ** 2 - (eta21 + eta03) ** 2)
                hu6 = (eta20 - eta02) * ((eta30 + eta12) ** 2 - (eta21 + eta03) ** 2) + \
                      4 * eta11 * (eta30 + eta12) * (eta21 + eta03)
                hu7 = (3 * eta21 - eta03) * (eta30 + eta12) * ((eta30 + eta12) ** 2 - 3 * (eta21 + eta03) ** 2) - \
                      (eta30 - 3 * eta12) * (eta21 + eta03) * (3 * (eta30 + eta12) ** 2 - (eta21 + eta03) ** 2)
                
                normalized_moments = [hu1, hu2, hu3, hu4, hu5, hu6, hu7]
            
            # Additional shape descriptors
            shape_descriptors = {}
            
            # Eccentricity and orientation
            if mu20 + mu02 > 0:
                # Principal moments
                lambda1 = 0.5 * (mu20 + mu02) + 0.5 * np.sqrt(4 * mu11 ** 2 + (mu20 - mu02) ** 2)
                lambda2 = 0.5 * (mu20 + mu02) - 0.5 * np.sqrt(4 * mu11 ** 2 + (mu20 - mu02) ** 2)
                
                # Eccentricity
                if lambda1 > 0:
                    eccentricity = np.sqrt(1 - lambda2 / lambda1) if lambda2 >= 0 else 0
                    shape_descriptors['eccentricity'] = min(1, eccentricity)
                else:
                    shape_descriptors['eccentricity'] = 0
                
                # Orientation angle
                if mu20 != mu02:
                    orientation = 0.5 * np.arctan2(2 * mu11, mu20 - mu02)
                    shape_descriptors['orientation'] = orientation
                else:
                    shape_descriptors['orientation'] = 0
            
            # Compactness (circularity)
            if len(coords) > 2:
                from scipy.spatial import ConvexHull
                try:
                    hull = ConvexHull(coords)
                    perimeter = hull.area  # In 2D, area gives perimeter
                    area = hull.volume    # In 2D, volume gives area
                    
                    if perimeter > 0:
                        compactness = 4 * np.pi * area / (perimeter ** 2)
                        shape_descriptors['compactness'] = min(1, compactness)
                    else:
                        shape_descriptors['compactness'] = 0
                except Exception:
                    shape_descriptors['compactness'] = 0
            
            # Aspect ratio
            x_range = np.max(coords[:, 0]) - np.min(coords[:, 0])
            y_range = np.max(coords[:, 1]) - np.min(coords[:, 1])
            if min(x_range, y_range) > 0:
                aspect_ratio = max(x_range, y_range) / min(x_range, y_range)
                shape_descriptors['aspect_ratio'] = aspect_ratio
            else:
                shape_descriptors['aspect_ratio'] = 1
            
            return {
                'raw_moments': raw_moments,
                'central_moments': central_moments,
                'normalized_moments': normalized_moments,
                'hu_moments': normalized_moments[:7] if len(normalized_moments) >= 7 else normalized_moments,
                'shape_descriptors': shape_descriptors,
                'centroid': centroid.tolist()
            }
            
        except Exception as e:
            # Fallback to basic moments
            try:
                coords = np.asarray(data.get('coordinates', []))
                if len(coords) < 2:
                    return {'moments': [0], 'central_moments': [0], 'normalized_moments': [0]}
                
                # Basic statistics as moments
                x_mean, y_mean = np.mean(coords, axis=0)
                x_var, y_var = np.var(coords, axis=0)
                covariance = np.cov(coords[:, 0], coords[:, 1])[0, 1]
                
                return {
                    'raw_moments': [len(coords), x_mean, y_mean],
                    'central_moments': [x_var, covariance, y_var],
                    'normalized_moments': [1, x_var / (x_var + y_var + 1e-10), y_var / (x_var + y_var + 1e-10)]
                }
            except Exception:
                return {'moments': [0], 'central_moments': [0], 'normalized_moments': [0]}
    
    def _fourier_descriptors(self, data: Dict) -> Dict:
        """Calculate Fourier descriptors for shape analysis."""
        try:
            coords = data.get('coordinates')
            if coords is None or len(coords) < 4:
                return {'descriptors': [0], 'magnitude_spectrum': [0], 'phase_spectrum': [0]}
            
            coords = np.asarray(coords)
            n_points = len(coords)
            
            # Create complex representation of boundary points
            # If we have a closed boundary, use it; otherwise create one
            
            # Method 1: Treat coordinates as complex numbers
            complex_coords = coords[:, 0] + 1j * coords[:, 1]
            
            # Method 2: If we can determine a boundary ordering, use it
            # For now, we'll assume the points represent a shape boundary
            
            # Calculate centroid for center-referencing
            centroid = np.mean(coords, axis=0)
            
            # Convert to polar representation from centroid
            relative_coords = coords - centroid
            radii = np.sqrt(relative_coords[:, 0] ** 2 + relative_coords[:, 1] ** 2)
            angles = np.arctan2(relative_coords[:, 1], relative_coords[:, 0])
            
            # Sort by angle to create a proper boundary sequence
            angle_order = np.argsort(angles)
            sorted_coords = coords[angle_order]
            sorted_complex = sorted_coords[:, 0] + 1j * sorted_coords[:, 1]
            
            # Discrete Fourier Transform of the boundary
            n_fourier = min(32, n_points)  # Limit number of Fourier coefficients
            
            # FFT of complex coordinate sequence
            fourier_coeffs = np.fft.fft(sorted_complex, n_fourier)
            
            # Normalize coefficients (make invariant to translation)
            if fourier_coeffs[0] != 0:
                normalized_coeffs = fourier_coeffs / fourier_coeffs[0]
            else:
                normalized_coeffs = fourier_coeffs
            
            # Extract magnitude and phase spectra
            magnitude_spectrum = np.abs(normalized_coeffs)
            phase_spectrum = np.angle(normalized_coeffs)
            
            # Scale and rotation invariant descriptors
            # Remove DC component (translation invariance)
            if len(magnitude_spectrum) > 1:
                scale_invariant_descriptors = magnitude_spectrum[1:] / (magnitude_spectrum[1] + 1e-10)
            else:
                scale_invariant_descriptors = magnitude_spectrum
            
            # Alternative method: Curvature-based Fourier descriptors
            try:
                # Calculate curvature at each point
                curvatures = []
                for i in range(len(sorted_coords)):
                    # Use 3-point curvature approximation
                    p1 = sorted_coords[i - 1] if i > 0 else sorted_coords[-1]
                    p2 = sorted_coords[i]
                    p3 = sorted_coords[(i + 1) % len(sorted_coords)]
                    
                    # Vectors
                    v1 = p2 - p1
                    v2 = p3 - p2
                    
                    # Cross product for curvature (in 2D, this gives the z-component)
                    cross_prod = v1[0] * v2[1] - v1[1] * v2[0]
                    v1_norm = np.linalg.norm(v1)
                    v2_norm = np.linalg.norm(v2)
                    
                    if v1_norm > 0 and v2_norm > 0:
                        # Curvature approximation
                        curvature = cross_prod / (v1_norm * v2_norm + 1e-10)
                        curvatures.append(curvature)
                    else:
                        curvatures.append(0)
                
                # FFT of curvature function
                curvature_fft = np.fft.fft(curvatures, min(16, len(curvatures)))
                curvature_descriptors = np.abs(curvature_fft)
                
                # Normalize
                if curvature_descriptors[0] != 0:
                    curvature_descriptors = curvature_descriptors / curvature_descriptors[0]
                
            except Exception:
                curvature_descriptors = scale_invariant_descriptors[:min(8, len(scale_invariant_descriptors))]
            
            # Combine different descriptor types
            primary_descriptors = scale_invariant_descriptors[:min(8, len(scale_invariant_descriptors))]
            secondary_descriptors = curvature_descriptors[:min(4, len(curvature_descriptors))]
            
            # Shape complexity measures from Fourier analysis
            shape_complexity = {
                'spectral_energy': float(np.sum(magnitude_spectrum ** 2)),
                'dominant_frequency_ratio': float(magnitude_spectrum[1] / (np.sum(magnitude_spectrum[2:5]) + 1e-10)) if len(magnitude_spectrum) > 4 else 0,
                'high_frequency_content': float(np.mean(magnitude_spectrum[len(magnitude_spectrum)//2:])) if len(magnitude_spectrum) > 2 else 0,
                'fourier_compactness': float(magnitude_spectrum[1] / (np.sum(magnitude_spectrum) + 1e-10)) if len(magnitude_spectrum) > 0 else 0
            }
            
            return {
                'descriptors': primary_descriptors.tolist(),
                'curvature_descriptors': secondary_descriptors.tolist(),
                'magnitude_spectrum': magnitude_spectrum.tolist(),
                'phase_spectrum': phase_spectrum.tolist(),
                'shape_complexity': shape_complexity,
                'fourier_coefficients': fourier_coeffs.tolist(),
                'n_coefficients': len(fourier_coeffs)
            }
            
        except Exception as e:
            # Fallback to simple spectral analysis
            try:
                coords = np.asarray(data.get('coordinates', []))
                if len(coords) < 3:
                    return {'descriptors': [0], 'magnitude_spectrum': [0], 'phase_spectrum': [0]}
                
                # Simple coordinate-based FFT
                x_fft = np.fft.fft(coords[:, 0], min(8, len(coords)))
                y_fft = np.fft.fft(coords[:, 1], min(8, len(coords)))
                
                # Combined spectral descriptors
                combined_magnitude = np.abs(x_fft) + np.abs(y_fft)
                if combined_magnitude[0] > 0:
                    normalized_descriptors = combined_magnitude[1:] / combined_magnitude[0]
                else:
                    normalized_descriptors = combined_magnitude[1:]
                
                return {
                    'descriptors': normalized_descriptors.tolist(),
                    'magnitude_spectrum': combined_magnitude.tolist(),
                    'phase_spectrum': np.angle(x_fft + 1j * y_fft).tolist()
                }
                
            except Exception:
                return {'descriptors': [0], 'magnitude_spectrum': [0], 'phase_spectrum': [0]}
    
    def _wavelet_spatial_features(self, data: Dict) -> Dict:
        """Extract wavelet-based spatial features for multi-scale analysis."""
        try:
            coords = data.get('coordinates')
            values = data.get('values')
            
            if coords is None or len(coords) < 4:
                return {'features': [0], 'scales': [0], 'coefficients': [0]}
            
            coords = np.asarray(coords)
            n_points = len(coords)
            
            # If values are provided, use them; otherwise use spatial density
            if values is not None and len(values) == len(coords):
                signal = np.asarray(values)
            else:
                # Create a signal from spatial coordinates
                # Use distance from centroid as signal
                centroid = np.mean(coords, axis=0)
                signal = np.linalg.norm(coords - centroid, axis=1)
            
            # Multi-scale wavelet analysis
            wavelet_features = {}
            
            try:
                from scipy import signal as scipy_signal
                
                # Create wavelet-like filters for multi-scale analysis
                # Mexican hat (Ricker) wavelet analysis
                def ricker_wavelet(points, a):
                    """Ricker wavelet (Mexican hat) at scale a."""
                    A = 2 / (np.sqrt(3 * a) * (np.pi ** 0.25))
                    wsq = points ** 2 / (a ** 2)
                    vec = A * (1 - wsq) * np.exp(-wsq / 2)
                    return vec
                
                # Define scales for analysis
                max_scale = min(n_points // 4, 16)
                scales = np.logspace(0, np.log10(max_scale), min(8, max_scale))
                
                # Wavelet transform at different scales
                wavelet_coefficients = []
                scale_energies = []
                scale_entropies = []
                
                for scale in scales:
                    # Create analysis points
                    analysis_points = np.linspace(-3 * scale, 3 * scale, int(6 * scale) + 1)
                    wavelet = ricker_wavelet(analysis_points, scale)
                    
                    # Convolution with signal (simplified continuous wavelet transform)
                    if len(signal) >= len(wavelet):
                        coeffs = scipy_signal.convolve(signal, wavelet, mode='valid')
                    else:
                        # Pad signal or truncate wavelet
                        if len(wavelet) > len(signal):
                            wavelet = wavelet[:len(signal)]
                        coeffs = scipy_signal.convolve(signal, wavelet, mode='same')
                    
                    if len(coeffs) > 0:
                        wavelet_coefficients.extend(coeffs)
                        
                        # Scale energy
                        energy = np.sum(coeffs ** 2)
                        scale_energies.append(energy)
                        
                        # Scale entropy (measure of complexity at this scale)
                        if energy > 0:
                            normalized_coeffs = (coeffs ** 2) / energy
                            entropy = -np.sum(normalized_coeffs * np.log(normalized_coeffs + 1e-10))
                            scale_entropies.append(entropy)
                        else:
                            scale_entropies.append(0)
                
                wavelet_features['scale_energies'] = scale_energies
                wavelet_features['scale_entropies'] = scale_entropies
                wavelet_features['dominant_scale'] = scales[np.argmax(scale_energies)] if scale_energies else 0
                
                # Energy distribution across scales
                total_energy = sum(scale_energies) if scale_energies else 1
                wavelet_features['energy_distribution'] = [e / total_energy for e in scale_energies]
                
            except ImportError:
                # Fallback without scipy.signal
                wavelet_coefficients = signal.tolist()
                wavelet_features['scale_energies'] = [np.var(signal)]
                wavelet_features['scale_entropies'] = [1.0]
            
            # 2D Spatial wavelet analysis on coordinate grid
            try:
                # Create regular grid for 2D analysis
                x_min, x_max = np.min(coords[:, 0]), np.max(coords[:, 0])
                y_min, y_max = np.min(coords[:, 1]), np.max(coords[:, 1])
                
                grid_size = min(32, int(np.sqrt(n_points)) * 2)
                x_grid = np.linspace(x_min, x_max, grid_size)
                y_grid = np.linspace(y_min, y_max, grid_size)
                X_grid, Y_grid = np.meshgrid(x_grid, y_grid)
                
                # Interpolate signal onto grid
                from scipy.interpolate import griddata
                grid_signal = griddata(coords, signal, (X_grid, Y_grid), method='linear', fill_value=0)
                
                # 2D Wavelet-like analysis using gradient and Laplacian
                # Gradient magnitude (edge detection)
                grad_x = np.gradient(grid_signal, axis=1)
                grad_y = np.gradient(grid_signal, axis=0)
                gradient_magnitude = np.sqrt(grad_x ** 2 + grad_y ** 2)
                
                # Laplacian (second-order features)
                laplacian = np.gradient(grad_x, axis=1) + np.gradient(grad_y, axis=0)
                
                # Multi-scale features
                spatial_features = {
                    'gradient_energy': float(np.sum(gradient_magnitude ** 2)),
                    'gradient_mean': float(np.mean(gradient_magnitude)),
                    'gradient_std': float(np.std(gradient_magnitude)),
                    'laplacian_energy': float(np.sum(laplacian ** 2)),
                    'laplacian_mean': float(np.mean(np.abs(laplacian))),
                    'edge_density': float(np.sum(gradient_magnitude > np.mean(gradient_magnitude)) / gradient_magnitude.size)
                }
                
                wavelet_features.update(spatial_features)
                
            except Exception:
                # Simple spatial variation analysis
                x_var = np.var(coords[:, 0])
                y_var = np.var(coords[:, 1])
                spatial_features = {
                    'x_variation': float(x_var),
                    'y_variation': float(y_var),
                    'spatial_anisotropy': float(abs(x_var - y_var) / (x_var + y_var + 1e-10))
                }
                wavelet_features.update(spatial_features)
            
            # Texture analysis using local binary patterns
            try:
                # Simple local pattern analysis
                local_patterns = []
                for i in range(min(len(coords), 100)):  # Limit for performance
                    # Find k nearest neighbors
                    distances = np.linalg.norm(coords - coords[i], axis=1)
                    k_nearest = min(8, len(coords) - 1)
                    nearest_indices = np.argsort(distances)[1:k_nearest + 1]
                    
                    # Compare values with neighbors
                    center_value = signal[i]
                    pattern = 0
                    for j, neighbor_idx in enumerate(nearest_indices):
                        if signal[neighbor_idx] > center_value:
                            pattern += 2 ** j
                    
                    local_patterns.append(pattern)
                
                # Pattern statistics
                unique_patterns = len(set(local_patterns))
                pattern_entropy = 0
                if len(local_patterns) > 0:
                    pattern_counts = np.bincount(local_patterns)
                    pattern_probs = pattern_counts / len(local_patterns)
                    pattern_entropy = -np.sum(pattern_probs * np.log(pattern_probs + 1e-10))
                
                wavelet_features['texture_patterns'] = unique_patterns
                wavelet_features['texture_entropy'] = float(pattern_entropy)
                
            except Exception:
                wavelet_features['texture_patterns'] = 1
                wavelet_features['texture_entropy'] = 0.0
            
            # Combine all features into main feature vector
            main_features = []
            
            # Add scale-based features
            if 'scale_energies' in wavelet_features and wavelet_features['scale_energies']:
                main_features.extend(wavelet_features['scale_energies'][:5])  # Top 5 scale energies
            
            # Add spatial features
            spatial_keys = ['gradient_energy', 'laplacian_energy', 'edge_density']
            for key in spatial_keys:
                if key in wavelet_features:
                    main_features.append(wavelet_features[key])
            
            # Add texture features
            if 'texture_entropy' in wavelet_features:
                main_features.append(wavelet_features['texture_entropy'])
            
            # Normalize features
            if main_features:
                max_feature = max(abs(f) for f in main_features)
                if max_feature > 0:
                    main_features = [f / max_feature for f in main_features]
            
            return {
                'features': main_features,
                'scales': scales.tolist() if 'scales' in locals() else [1.0],
                'coefficients': wavelet_coefficients[:20] if len(wavelet_coefficients) > 20 else wavelet_coefficients,  # Limit size
                'wavelet_analysis': wavelet_features
            }
            
        except Exception as e:
            # Basic fallback analysis
            try:
                coords = np.asarray(data.get('coordinates', []))
                if len(coords) < 2:
                    return {'features': [0], 'scales': [0], 'coefficients': [0]}
                
                # Simple multi-scale variance analysis
                centroid = np.mean(coords, axis=0)
                distances = np.linalg.norm(coords - centroid, axis=1)
                
                # Different scale analysis
                features = []
                features.append(float(np.var(distances)))  # Global scale
                
                # Local scale analysis
                n_regions = min(4, len(coords) // 2)
                if n_regions > 1:
                    region_size = len(coords) // n_regions
                    for i in range(n_regions):
                        start_idx = i * region_size
                        end_idx = start_idx + region_size if i < n_regions - 1 else len(coords)
                        region_coords = coords[start_idx:end_idx]
                        if len(region_coords) > 1:
                            region_centroid = np.mean(region_coords, axis=0)
                            region_distances = np.linalg.norm(region_coords - region_centroid, axis=1)
                            features.append(float(np.var(region_distances)))
                
                return {
                    'features': features,
                    'scales': list(range(1, len(features) + 1)),
                    'coefficients': distances.tolist()[:10]  # First 10 distances
                }
                
            except Exception:
                return {'features': [0], 'scales': [0], 'coefficients': [0]}
    
    def _fractal_dimension_analysis(self, data: Dict) -> Dict:
        """Analyze fractal dimensions of spatial patterns using multiple methods."""
        try:
            coords = data.get('coordinates')
            if coords is None or len(coords) < 4:
                return {'fractal_dim': 1.0, 'box_counting_dim': 1.0, 'correlation_dim': 1.0}
            
            coords = np.asarray(coords)
            n_points = len(coords)
            
            # Method 1: Box-counting dimension
            def box_counting_dimension(points):
                """Calculate fractal dimension using box-counting method."""
                # Normalize coordinates to [0,1] x [0,1]
                min_coords = np.min(points, axis=0)
                max_coords = np.max(points, axis=0)
                
                if np.any(max_coords - min_coords == 0):
                    return 1.0  # Degenerate case
                
                normalized_points = (points - min_coords) / (max_coords - min_coords)
                
                # Range of box sizes (powers of 2 for efficiency)
                max_divisions = min(8, int(np.log2(np.sqrt(n_points))) + 1)
                box_sizes = [1.0 / (2 ** i) for i in range(1, max_divisions + 1)]
                
                counts = []
                sizes = []
                
                for box_size in box_sizes:
                    # Create grid
                    n_boxes = int(1.0 / box_size)
                    occupied_boxes = set()
                    
                    # Count occupied boxes
                    for point in normalized_points:
                        box_x = min(int(point[0] / box_size), n_boxes - 1)
                        box_y = min(int(point[1] / box_size), n_boxes - 1)
                        occupied_boxes.add((box_x, box_y))
                    
                    counts.append(len(occupied_boxes))
                    sizes.append(box_size)
                
                # Linear regression on log-log plot
                if len(counts) >= 3 and all(c > 0 for c in counts):
                    log_sizes = np.log(sizes)
                    log_counts = np.log(counts)
                    
                    # Fit line: log(count) = -D * log(size) + constant
                    coeffs = np.polyfit(log_sizes, log_counts, 1)
                    fractal_dim = -coeffs[0]  # Negative slope gives dimension
                    
                    # Ensure reasonable bounds
                    return max(1.0, min(2.0, fractal_dim))
                
                return 1.5  # Default value
            
            box_counting_dim = box_counting_dimension(coords)
            
            # Method 2: Correlation dimension (Grassberger-Procaccia)
            def correlation_dimension(points, max_radius_fraction=0.5):
                """Calculate correlation dimension."""
                n = len(points)
                if n < 4:
                    return 1.0
                
                # Calculate all pairwise distances
                distances = []
                for i in range(n):
                    for j in range(i + 1, n):
                        dist = np.linalg.norm(points[i] - points[j])
                        distances.append(dist)
                
                distances = np.array(distances)
                max_dist = np.max(distances)
                
                if max_dist == 0:
                    return 1.0
                
                # Range of radii
                min_radius = max_dist * 0.01
                max_radius = max_dist * max_radius_fraction
                n_radii = min(10, len(distances) // 5)
                radii = np.logspace(np.log10(min_radius), np.log10(max_radius), n_radii)
                
                correlations = []
                for radius in radii:
                    # Count pairs within radius
                    count = np.sum(distances <= radius)
                    correlation = count / len(distances)
                    correlations.append(max(correlation, 1e-10))  # Avoid log(0)
                
                # Linear regression on log-log plot
                if len(correlations) >= 3:
                    log_radii = np.log(radii)
                    log_correlations = np.log(correlations)
                    
                    # Fit line in the scaling region (middle portion)
                    start_idx = len(log_radii) // 4
                    end_idx = 3 * len(log_radii) // 4
                    
                    if end_idx > start_idx:
                        coeffs = np.polyfit(log_radii[start_idx:end_idx], 
                                          log_correlations[start_idx:end_idx], 1)
                        corr_dim = coeffs[0]  # Slope gives dimension
                        return max(1.0, min(2.0, corr_dim))
                
                return 1.5
            
            correlation_dim = correlation_dimension(coords)
            
            # Method 3: Higuchi fractal dimension (for time series-like data)
            def higuchi_dimension(points):
                """Calculate Higuchi fractal dimension using path-like analysis."""
                # Create a path through the points (simple ordering by angle from centroid)
                centroid = np.mean(points, axis=0)
                angles = np.arctan2(points[:, 1] - centroid[1], points[:, 0] - centroid[0])
                order = np.argsort(angles)
                ordered_points = points[order]
                
                n = len(ordered_points)
                if n < 4:
                    return 1.0
                
                # Calculate curve lengths for different intervals
                max_k = min(8, n // 2)
                k_values = range(1, max_k + 1)
                lengths = []
                
                for k in k_values:
                    # Calculate length with interval k
                    total_length = 0
                    count = 0
                    
                    for m in range(k):
                        path_length = 0
                        indices = range(m, n, k)
                        
                        if len(indices) > 1:
                            for i in range(len(indices) - 1):
                                idx1, idx2 = indices[i], indices[i + 1]
                                path_length += np.linalg.norm(ordered_points[idx2] - ordered_points[idx1])
                            
                            # Normalize
                            path_length = path_length * (n - 1) / ((len(indices) - 1) * k)
                            total_length += path_length
                            count += 1
                    
                    if count > 0:
                        avg_length = total_length / count
                        lengths.append(avg_length)
                    else:
                        lengths.append(0)
                
                # Linear regression
                if len(lengths) >= 3 and all(l > 0 for l in lengths):
                    log_k = np.log(k_values[:len(lengths)])
                    log_lengths = np.log(lengths)
                    
                    coeffs = np.polyfit(log_k, log_lengths, 1)
                    higuchi_dim = -coeffs[0]  # Negative slope
                    return max(1.0, min(2.0, higuchi_dim))
                
                return 1.5
            
            higuchi_dim = higuchi_dimension(coords)
            
            # Method 4: Perimeter-area relationship (for closed curves)
            def perimeter_area_dimension(points):
                """Estimate dimension from perimeter-area scaling."""
                try:
                    from scipy.spatial import ConvexHull
                    
                    if len(points) < 3:
                        return 1.0
                    
                    # Calculate convex hull
                    hull = ConvexHull(points)
                    area = hull.volume  # In 2D, volume gives area
                    perimeter = hull.area  # In 2D, area gives perimeter
                    
                    if area > 0 and perimeter > 0:
                        # For a fractal boundary: A ~ P^(2/D) where D is the boundary dimension
                        # So D = 2 * log(P) / log(A) + constant
                        # Simplified estimation
                        shape_index = perimeter ** 2 / (4 * np.pi * area)  # Isoperimetric ratio
                        
                        # Convert to fractal dimension estimate
                        if shape_index > 1:
                            boundary_dim = 1 + 0.5 * np.log(shape_index) / np.log(2)
                            return max(1.0, min(2.0, boundary_dim))
                    
                    return 1.0
                    
                except Exception:
                    return 1.0
            
            perimeter_area_dim = perimeter_area_dimension(coords)
            
            # Lacunarity analysis (measure of "gappiness")
            def lacunarity_analysis(points):
                """Calculate lacunarity as a complement to fractal dimension."""
                # Create binary grid
                min_coords = np.min(points, axis=0)
                max_coords = np.max(points, axis=0)
                
                if np.any(max_coords - min_coords == 0):
                    return 0.0
                
                grid_size = min(32, int(np.sqrt(len(points)) * 2))
                x_bins = np.linspace(min_coords[0], max_coords[0], grid_size)
                y_bins = np.linspace(min_coords[1], max_coords[1], grid_size)
                
                # Create occupancy grid
                grid = np.zeros((grid_size - 1, grid_size - 1))
                
                for point in points:
                    x_idx = np.searchsorted(x_bins, point[0]) - 1
                    y_idx = np.searchsorted(y_bins, point[1]) - 1
                    
                    x_idx = max(0, min(grid_size - 2, x_idx))
                    y_idx = max(0, min(grid_size - 2, y_idx))
                    
                    grid[y_idx, x_idx] = 1
                
                # Calculate lacunarity for different box sizes
                box_sizes = [2, 4, 8, min(16, grid_size // 2)]
                lacunarities = []
                
                for box_size in box_sizes:
                    if box_size >= grid_size:
                        continue
                    
                    mass_sums = []
                    for i in range(0, grid_size - box_size, box_size // 2):
                        for j in range(0, grid_size - box_size, box_size // 2):
                            box = grid[i:i+box_size, j:j+box_size]
                            mass = np.sum(box)
                            mass_sums.append(mass)
                    
                    if len(mass_sums) > 1:
                        mean_mass = np.mean(mass_sums)
                        var_mass = np.var(mass_sums)
                        
                        if mean_mass > 0:
                            lacunarity = (var_mass / (mean_mass ** 2)) + 1
                            lacunarities.append(lacunarity)
                
                return np.mean(lacunarities) if lacunarities else 1.0
            
            lacunarity = lacunarity_analysis(coords)
            
            # Combine results and create comprehensive analysis
            fractal_dimensions = {
                'box_counting_dim': float(box_counting_dim),
                'correlation_dim': float(correlation_dim),
                'higuchi_dim': float(higuchi_dim),
                'perimeter_area_dim': float(perimeter_area_dim),
                'lacunarity': float(lacunarity)
            }
            
            # Calculate weighted average dimension
            dims = [box_counting_dim, correlation_dim, higuchi_dim]
            weights = [0.4, 0.3, 0.3]  # Box-counting is often most reliable
            
            avg_fractal_dim = np.average(dims, weights=weights)
            
            # Fractal complexity metrics
            complexity_metrics = {
                'dimensional_consistency': 1.0 - np.std(dims) / np.mean(dims) if np.mean(dims) > 0 else 0,
                'fractal_complexity': (avg_fractal_dim - 1.0),  # How much more complex than a line
                'spatial_irregularity': float(lacunarity - 1.0),
                'multifractal_tendency': float(np.std(dims))  # Variation suggests multifractality
            }
            
            return {
                'fractal_dim': float(avg_fractal_dim),
                **fractal_dimensions,
                'complexity_metrics': complexity_metrics,
                'analysis_quality': float(min(1.0, len(coords) / 20))  # Quality improves with more points
            }
            
        except Exception as e:
            # Simple fallback dimension estimate
            try:
                coords = np.asarray(data.get('coordinates', []))
                if len(coords) < 3:
                    return {'fractal_dim': 1.0, 'box_counting_dim': 1.0, 'correlation_dim': 1.0}
                
                # Simple space-filling estimate
                # Calculate how much area the points cover
                min_coords = np.min(coords, axis=0)
                max_coords = np.max(coords, axis=0)
                
                total_area = np.prod(max_coords - min_coords)
                if total_area > 0:
                    # Rough dimension based on point density
                    point_density = len(coords) / total_area
                    dimension_estimate = 1 + min(1.0, np.log10(point_density + 1) / 2)
                else:
                    dimension_estimate = 1.0
                
                return {
                    'fractal_dim': float(dimension_estimate),
                    'box_counting_dim': float(dimension_estimate),
                    'correlation_dim': float(dimension_estimate)
                }
                
            except Exception:
                return {'fractal_dim': 1.5, 'box_counting_dim': 1.5, 'correlation_dim': 1.5}
    
    def _topological_analysis(self, data: Dict) -> Dict:
        """Perform topological analysis of spatial structures using computational topology."""
        try:
            coords = data.get('coordinates')
            if coords is None or len(coords) < 3:
                return {'topology': 'simple', 'betti_numbers': [0, 0], 'euler_characteristic': 0}
            
            coords = np.asarray(coords)
            n_points = len(coords)
            
            # Topological analysis using computational geometry approaches
            topological_features = {}
            
            # Method 1: Delaunay triangulation and simplicial complex analysis
            try:
                from scipy.spatial import Delaunay, ConvexHull
                
                if len(coords) >= 3:
                    # Delaunay triangulation
                    tri = Delaunay(coords)
                    
                    # Basic topological invariants
                    n_vertices = len(coords)
                    n_edges = len(tri.simplices) * 3 // 2  # Each triangle has 3 edges, shared edges counted twice
                    n_faces = len(tri.simplices)
                    
                    # Euler characteristic for 2D: V - E + F
                    euler_char = n_vertices - n_edges + n_faces
                    
                    topological_features['vertices'] = n_vertices
                    topological_features['edges'] = n_edges
                    topological_features['faces'] = n_faces
                    topological_features['euler_characteristic'] = euler_char
                    
                    # Estimate Betti numbers
                    # B0: number of connected components (approximate)
                    # B1: number of holes (approximate from Euler characteristic)
                    
                    # Simple connectivity analysis
                    # Build adjacency from triangulation
                    adjacency = {i: set() for i in range(n_vertices)}
                    for simplex in tri.simplices:
                        for i in range(3):
                            for j in range(i + 1, 3):
                                adjacency[simplex[i]].add(simplex[j])
                                adjacency[simplex[j]].add(simplex[i])
                    
                    # Count connected components (B0)
                    visited = set()
                    components = 0
                    for vertex in range(n_vertices):
                        if vertex not in visited:
                            components += 1
                            # BFS to mark connected component
                            queue = [vertex]
                            while queue:
                                current = queue.pop(0)
                                if current not in visited:
                                    visited.add(current)
                                    queue.extend(adjacency[current] - visited)
                    
                    betti_0 = components
                    
                    # Estimate B1 (holes) from Euler characteristic
                    # For a connected planar graph: V - E + F = 2 (no holes)
                    # Each hole reduces Euler characteristic by 1
                    betti_1 = max(0, 2 - euler_char) if components == 1 else 0
                    
                    topological_features['betti_numbers'] = [betti_0, betti_1]
                    topological_features['connected_components'] = betti_0
                    topological_features['holes'] = betti_1
            
            except Exception:
                # Fallback to simple geometric analysis
                topological_features['euler_characteristic'] = 1
                topological_features['betti_numbers'] = [1, 0]
            
            # Method 2: Persistent homology approximation
            def approximate_persistence(points, max_radius_fraction=0.3):
                """Approximate persistent homology using distance-based filtration."""
                try:
                    from scipy.spatial.distance import pdist, squareform
                    
                    distances = squareform(pdist(points))
                    max_dist = np.max(distances)
                    
                    # Create filtration at different scales
                    n_scales = min(10, len(points) // 2)
                    scales = np.linspace(0, max_dist * max_radius_fraction, n_scales)
                    
                    persistence_data = []
                    
                    for scale in scales:
                        # Build neighborhood graph
                        adjacency_matrix = distances <= scale
                        
                        # Count connected components at this scale
                        n_components = 0
                        visited = np.zeros(len(points), dtype=bool)
                        
                        for i in range(len(points)):
                            if not visited[i]:
                                n_components += 1
                                # BFS
                                queue = [i]
                                while queue:
                                    current = queue.pop(0)
                                    if not visited[current]:
                                        visited[current] = True
                                        neighbors = np.where(adjacency_matrix[current])[0]
                                        queue.extend([n for n in neighbors if not visited[n]])
                        
                        persistence_data.append((scale, n_components))
                    
                    # Analyze persistence
                    if persistence_data:
                        initial_components = persistence_data[0][1]
                        final_components = persistence_data[-1][1]
                        
                        # Persistence measures
                        component_persistence = initial_components - final_components
                        max_components = max(data[1] for data in persistence_data)
                        
                        return {
                            'persistence_length': component_persistence,
                            'max_components': max_components,
                            'final_components': final_components,
                            'persistence_ratio': component_persistence / max(initial_components, 1)
                        }
                    
                    return {'persistence_length': 0, 'max_components': 1}
                    
                except Exception:
                    return {'persistence_length': 0, 'max_components': 1}
            
            persistence_analysis = approximate_persistence(coords)
            topological_features.update(persistence_analysis)
            
            # Method 3: Shape topology classification
            def classify_topology(points, features):
                """Classify the topological type of the point cloud."""
                n = len(points)
                
                # Convexity analysis
                try:
                    from scipy.spatial import ConvexHull
                    hull = ConvexHull(points)
                    convex_ratio = len(hull.vertices) / n
                    
                    # Classify based on various measures
                    if convex_ratio > 0.8:
                        topology_class = 'convex'
                    elif features.get('holes', 0) > 0:
                        topology_class = 'non_trivial'
                    elif features.get('connected_components', 1) > 1:
                        topology_class = 'disconnected'
                    else:
                        topology_class = 'connected_non_convex'
                    
                    return {
                        'topology_class': topology_class,
                        'convex_ratio': float(convex_ratio),
                        'topological_complexity': features.get('holes', 0) + max(0, features.get('connected_components', 1) - 1)
                    }
                    
                except Exception:
                    return {'topology_class': 'simple', 'convex_ratio': 0.5, 'topological_complexity': 0}
            
            topology_classification = classify_topology(coords, topological_features)
            topological_features.update(topology_classification)
            
            # Method 4: Topological invariants for spatial networks
            def network_topology_analysis(points):
                """Analyze topology as a spatial network."""
                try:
                    from scipy.spatial.distance import pdist, squareform
                    
                    # Create proximity network
                    distances = squareform(pdist(points))
                    
                    # Adaptive threshold for network construction
                    threshold = np.percentile(distances[distances > 0], 20)  # Connect to ~20% closest neighbors
                    
                    # Build adjacency matrix
                    adjacency = distances <= threshold
                    np.fill_diagonal(adjacency, False)  # Remove self-loops
                    
                    # Network topological measures
                    n_edges = np.sum(adjacency) // 2  # Undirected edges
                    n_vertices = len(points)
                    
                    # Average degree
                    degrees = np.sum(adjacency, axis=1)
                    avg_degree = np.mean(degrees)
                    
                    # Clustering coefficient (local)
                    clustering_coeffs = []
                    for i in range(n_vertices):
                        neighbors = np.where(adjacency[i])[0]
                        if len(neighbors) > 1:
                            # Count triangles
                            triangles = 0
                            possible_triangles = len(neighbors) * (len(neighbors) - 1) // 2
                            
                            for j in range(len(neighbors)):
                                for k in range(j + 1, len(neighbors)):
                                    if adjacency[neighbors[j], neighbors[k]]:
                                        triangles += 1
                            
                            clustering = triangles / possible_triangles if possible_triangles > 0 else 0
                            clustering_coeffs.append(clustering)
                    
                    avg_clustering = np.mean(clustering_coeffs) if clustering_coeffs else 0
                    
                    return {
                        'network_edges': int(n_edges),
                        'average_degree': float(avg_degree),
                        'clustering_coefficient': float(avg_clustering),
                        'network_density': float(n_edges / (n_vertices * (n_vertices - 1) // 2)) if n_vertices > 1 else 0
                    }
                    
                except Exception:
                    return {'network_edges': 0, 'average_degree': 0, 'clustering_coefficient': 0}
            
            network_analysis = network_topology_analysis(coords)
            topological_features.update(network_analysis)
            
            # Overall topology summary
            topology_summary = topology_classification.get('topology_class', 'unknown')
            
            return {
                'topology': topology_summary,
                **topological_features
            }
            
        except Exception as e:
            # Basic fallback analysis
            try:
                coords = np.asarray(data.get('coordinates', []))
                n = len(coords)
                
                if n < 3:
                    return {'topology': 'simple', 'betti_numbers': [1, 0], 'euler_characteristic': 1}
                
                # Simple convex hull analysis
                from scipy.spatial import ConvexHull
                hull = ConvexHull(coords)
                convex_ratio = len(hull.vertices) / n
                
                if convex_ratio > 0.7:
                    topology_type = 'convex'
                else:
                    topology_type = 'non_convex'
                
                return {
                    'topology': topology_type,
                    'betti_numbers': [1, 0],
                    'euler_characteristic': 1,
                    'convex_ratio': float(convex_ratio)
                }
                
            except Exception:
                return {'topology': 'unknown', 'betti_numbers': [1, 0], 'euler_characteristic': 1}
    
    def _morphological_analysis(self, data: Dict) -> Dict:
        """Analyze morphological features using mathematical morphology and shape descriptors."""
        try:
            coords = data.get('coordinates')
            if coords is None or len(coords) < 3:
                return {'features': ['point_cloud'], 'morphology_metrics': {}}
            
            coords = np.asarray(coords)
            n_points = len(coords)
            
            morphological_features = {}
            feature_list = []
            
            # Basic geometric properties
            centroid = np.mean(coords, axis=0)
            
            # Bounding box analysis
            min_coords = np.min(coords, axis=0)
            max_coords = np.max(coords, axis=0)
            bbox_dimensions = max_coords - min_coords
            
            # Aspect ratio and elongation
            if bbox_dimensions[1] > 0:
                aspect_ratio = bbox_dimensions[0] / bbox_dimensions[1]
                morphological_features['aspect_ratio'] = float(aspect_ratio)
                
                if aspect_ratio > 2.0:
                    feature_list.append('elongated_horizontal')
                elif aspect_ratio < 0.5:
                    feature_list.append('elongated_vertical')
                else:
                    feature_list.append('compact')
            
            # Principal component analysis for orientation and shape
            try:
                centered_coords = coords - centroid
                cov_matrix = np.cov(centered_coords.T)
                eigenvals, eigenvecs = np.linalg.eig(cov_matrix)
                
                # Sort by eigenvalue magnitude
                idx = np.argsort(eigenvals)[::-1]
                eigenvals = eigenvals[idx]
                eigenvecs = eigenvecs[:, idx]
                
                # Shape anisotropy
                if eigenvals[0] > 0:
                    anisotropy = (eigenvals[0] - eigenvals[1]) / eigenvals[0]
                    morphological_features['anisotropy'] = float(anisotropy)
                    
                    if anisotropy > 0.7:
                        feature_list.append('highly_anisotropic')
                    elif anisotropy < 0.3:
                        feature_list.append('isotropic')
                    else:
                        feature_list.append('moderately_anisotropic')
                
                # Orientation angle of major axis
                major_axis_angle = np.arctan2(eigenvecs[1, 0], eigenvecs[0, 0])
                morphological_features['orientation_angle'] = float(major_axis_angle)
                
                # Eccentricity
                if eigenvals[0] > 0 and eigenvals[1] >= 0:
                    eccentricity = np.sqrt(1 - eigenvals[1] / eigenvals[0])
                    morphological_features['eccentricity'] = float(eccentricity)
                
            except Exception:
                morphological_features['anisotropy'] = 0.5
                morphological_features['eccentricity'] = 0.5
            
            # Convexity analysis
            try:
                from scipy.spatial import ConvexHull
                
                hull = ConvexHull(coords)
                
                # Convex hull properties
                hull_area = hull.volume  # In 2D, volume gives area
                hull_perimeter = hull.area  # In 2D, area gives perimeter
                
                # Solidity (ratio of point cloud area to convex hull area)
                # Approximate point cloud area using triangulation or grid
                try:
                    from scipy.spatial import Delaunay
                    tri = Delaunay(coords)
                    
                    # Calculate area of triangulated surface
                    triangulated_area = 0
                    for simplex in tri.simplices:
                        # Triangle area using cross product
                        v1 = coords[simplex[1]] - coords[simplex[0]]
                        v2 = coords[simplex[2]] - coords[simplex[0]]
                        triangle_area = 0.5 * abs(np.cross(v1, v2))
                        triangulated_area += triangle_area
                    
                    if hull_area > 0:
                        solidity = triangulated_area / hull_area
                        morphological_features['solidity'] = float(min(1.0, solidity))
                    
                except Exception:
                    # Fallback: use ratio of hull vertices to total points
                    solidity = len(hull.vertices) / n_points
                    morphological_features['solidity'] = float(solidity)
                
                # Convexity classification
                if morphological_features.get('solidity', 0) > 0.8:
                    feature_list.append('convex')
                elif morphological_features.get('solidity', 0) < 0.4:
                    feature_list.append('highly_concave')
                else:
                    feature_list.append('moderately_convex')
                
                # Compactness (isoperimetric ratio)
                if hull_perimeter > 0:
                    compactness = 4 * np.pi * hull_area / (hull_perimeter ** 2)
                    morphological_features['compactness'] = float(compactness)
                    
                    if compactness > 0.8:
                        feature_list.append('circular')
                    elif compactness < 0.3:
                        feature_list.append('irregular')
                
            except Exception:
                morphological_features['solidity'] = 0.5
                morphological_features['compactness'] = 0.5
                feature_list.append('unknown_convexity')
            
            # Morphological skeleton analysis (simplified)
            def skeleton_analysis(points):
                """Simplified morphological skeleton analysis."""
                try:
                    # Create binary image on grid
                    grid_size = min(64, int(np.sqrt(len(points)) * 4))
                    
                    x_range = max_coords[0] - min_coords[0]
                    y_range = max_coords[1] - min_coords[1]
                    
                    if x_range == 0 or y_range == 0:
                        return {'skeleton_length': 0, 'branch_points': 0, 'endpoints': 0}
                    
                    # Create grid
                    x_bins = np.linspace(min_coords[0], max_coords[0], grid_size)
                    y_bins = np.linspace(min_coords[1], max_coords[1], grid_size)
                    
                    # Rasterize points
                    binary_grid = np.zeros((grid_size - 1, grid_size - 1))
                    
                    for point in points:
                        x_idx = np.searchsorted(x_bins, point[0]) - 1
                        y_idx = np.searchsorted(y_bins, point[1]) - 1
                        
                        x_idx = max(0, min(grid_size - 2, x_idx))
                        y_idx = max(0, min(grid_size - 2, y_idx))
                        
                        binary_grid[y_idx, x_idx] = 1
                    
                    # Simple skeleton approximation using erosion
                    skeleton_pixels = 0
                    branch_points = 0
                    endpoints = 0
                    
                    # Count connected components and structure
                    for i in range(1, grid_size - 2):
                        for j in range(1, grid_size - 2):
                            if binary_grid[i, j] == 1:
                                # Count neighbors
                                neighborhood = binary_grid[i-1:i+2, j-1:j+2]
                                neighbors = np.sum(neighborhood) - 1  # Exclude center
                                
                                if neighbors == 1:
                                    endpoints += 1
                                elif neighbors > 2:
                                    branch_points += 1
                                
                                skeleton_pixels += 1
                    
                    return {
                        'skeleton_length': skeleton_pixels,
                        'branch_points': branch_points,
                        'endpoints': endpoints,
                        'branching_ratio': branch_points / max(skeleton_pixels, 1)
                    }
                    
                except Exception:
                    return {'skeleton_length': 0, 'branch_points': 0, 'endpoints': 0}
            
            skeleton_analysis_result = skeleton_analysis(coords)
            morphological_features.update(skeleton_analysis_result)
            
            # Shape complexity classification based on skeleton
            if skeleton_analysis_result.get('branch_points', 0) > n_points * 0.1:
                feature_list.append('highly_branched')
            elif skeleton_analysis_result.get('branch_points', 0) > 0:
                feature_list.append('branched')
            else:
                feature_list.append('simple_structure')
            
            # Roundness and rectangularity
            try:
                # Minimum enclosing circle approximation
                distances_from_centroid = np.linalg.norm(coords - centroid, axis=1)
                min_enclosing_radius = np.max(distances_from_centroid)
                
                # Average distance from centroid
                avg_radius = np.mean(distances_from_centroid)
                
                if min_enclosing_radius > 0:
                    roundness = avg_radius / min_enclosing_radius
                    morphological_features['roundness'] = float(roundness)
                    
                    if roundness > 0.8:
                        feature_list.append('round')
                    elif roundness < 0.5:
                        feature_list.append('star_shaped')
                
                # Rectangularity (how well it fits a rectangle)
                bbox_area = bbox_dimensions[0] * bbox_dimensions[1]
                if bbox_area > 0 and 'solidity' in morphological_features:
                    rectangularity = morphological_features['solidity']  # Approximation
                    morphological_features['rectangularity'] = float(rectangularity)
                    
                    if rectangularity > 0.9:
                        feature_list.append('rectangular')
                
            except Exception:
                pass
            
            # Size-based classifications
            total_extent = np.sum(bbox_dimensions)
            
            if n_points > 100:
                feature_list.append('dense')
            elif n_points < 20:
                feature_list.append('sparse')
            
            if total_extent > np.mean(bbox_dimensions) * 10:
                feature_list.append('large_scale')
            elif total_extent < np.mean(bbox_dimensions):
                feature_list.append('small_scale')
            
            # Remove duplicate features
            feature_list = list(set(feature_list))
            
            return {
                'features': feature_list,
                'morphology_metrics': morphological_features,
                'primary_shape': feature_list[0] if feature_list else 'undefined',
                'complexity_score': len(feature_list) / 10.0  # Normalized complexity
            }
            
        except Exception as e:
            # Fallback analysis
            try:
                coords = np.asarray(data.get('coordinates', []))
                
                if len(coords) < 2:
                    return {'features': ['point'], 'morphology_metrics': {}}
                
                # Basic shape classification
                min_coords = np.min(coords, axis=0)
                max_coords = np.max(coords, axis=0)
                dimensions = max_coords - min_coords
                
                features = []
                
                if dimensions[0] > dimensions[1] * 2:
                    features.append('elongated_horizontal')
                elif dimensions[1] > dimensions[0] * 2:
                    features.append('elongated_vertical')
                else:
                    features.append('compact')
                
                if len(coords) > 50:
                    features.append('dense')
                else:
                    features.append('sparse')
                
                return {
                    'features': features,
                    'morphology_metrics': {
                        'aspect_ratio': float(dimensions[0] / max(dimensions[1], 1e-10))
                    }
                }
                
            except Exception:
                return {'features': ['undefined'], 'morphology_metrics': {}}
    
    def _compare_shape_features(self, features1: Dict, features2: Dict) -> float:
        """Compare shape features between datasets using comprehensive similarity measures."""
        try:
            if not features1 or not features2:
                return 0.0
            
            similarities = []
            
            # 1. Compare geometric moments
            if 'hu_moments' in features1 and 'hu_moments' in features2:
                moments1 = np.array(features1['hu_moments'])
                moments2 = np.array(features2['hu_moments'])
                
                if len(moments1) > 0 and len(moments2) > 0:
                    min_len = min(len(moments1), len(moments2))
                    moments1 = moments1[:min_len]
                    moments2 = moments2[:min_len]
                    
                    # Use log transform for Hu moments (they can span many orders of magnitude)
                    log_moments1 = np.sign(moments1) * np.log10(np.abs(moments1) + 1e-10)
                    log_moments2 = np.sign(moments2) * np.log10(np.abs(moments2) + 1e-10)
                    
                    # Normalized difference
                    moment_diff = np.mean(np.abs(log_moments1 - log_moments2))
                    moment_similarity = 1.0 / (1.0 + moment_diff)
                    similarities.append(('hu_moments', moment_similarity, 0.25))
            
            # 2. Compare Fourier descriptors
            if 'descriptors' in features1 and 'descriptors' in features2:
                desc1 = np.array(features1['descriptors'])
                desc2 = np.array(features2['descriptors'])
                
                if len(desc1) > 0 and len(desc2) > 0:
                    min_len = min(len(desc1), len(desc2))
                    desc1 = desc1[:min_len]
                    desc2 = desc2[:min_len]
                    
                    # Correlation coefficient
                    if np.std(desc1) > 0 and np.std(desc2) > 0:
                        fourier_corr = np.corrcoef(desc1, desc2)[0, 1]
                        if not np.isnan(fourier_corr):
                            fourier_similarity = (fourier_corr + 1) / 2
                            similarities.append(('fourier_descriptors', fourier_similarity, 0.2))
                    
                    # Euclidean distance similarity
                    euclidean_dist = np.linalg.norm(desc1 - desc2)
                    max_possible_dist = np.linalg.norm(desc1) + np.linalg.norm(desc2)
                    if max_possible_dist > 0:
                        euclidean_similarity = 1.0 - min(1.0, euclidean_dist / max_possible_dist)
                        similarities.append(('fourier_euclidean', euclidean_similarity, 0.15))
            
            # 3. Compare fractal dimensions
            if 'fractal_dim' in features1 and 'fractal_dim' in features2:
                dim1 = features1['fractal_dim']
                dim2 = features2['fractal_dim']
                
                # Similarity based on relative difference
                max_dim = max(dim1, dim2, 1.0)
                fractal_similarity = 1.0 - abs(dim1 - dim2) / max_dim
                similarities.append(('fractal_dimension', fractal_similarity, 0.1))
            
            # 4. Compare topological features
            if 'betti_numbers' in features1 and 'betti_numbers' in features2:
                betti1 = features1['betti_numbers']
                betti2 = features2['betti_numbers']
                
                if len(betti1) > 0 and len(betti2) > 0:
                    # Compare Betti numbers
                    min_len = min(len(betti1), len(betti2))
                    betti_diff = sum(abs(betti1[i] - betti2[i]) for i in range(min_len))
                    max_betti = max(sum(betti1), sum(betti2), 1)
                    topology_similarity = 1.0 - min(1.0, betti_diff / max_betti)
                    similarities.append(('topology', topology_similarity, 0.1))
            
            # 5. Compare morphological features
            morphology_similarities = []
            
            # Shape descriptors comparison
            shape_metrics = ['aspect_ratio', 'eccentricity', 'compactness', 'solidity', 'roundness']
            
            for metric in shape_metrics:
                if metric in features1.get('shape_descriptors', {}) and metric in features2.get('shape_descriptors', {}):
                    val1 = features1['shape_descriptors'][metric]
                    val2 = features2['shape_descriptors'][metric]
                    
                    max_val = max(val1, val2, 1e-10)
                    metric_similarity = 1.0 - abs(val1 - val2) / max_val
                    morphology_similarities.append(metric_similarity)
                
                # Also check in morphology_metrics
                elif metric in features1.get('morphology_metrics', {}) and metric in features2.get('morphology_metrics', {}):
                    val1 = features1['morphology_metrics'][metric]
                    val2 = features2['morphology_metrics'][metric]
                    
                    max_val = max(val1, val2, 1e-10)
                    metric_similarity = 1.0 - abs(val1 - val2) / max_val
                    morphology_similarities.append(metric_similarity)
            
            if morphology_similarities:
                overall_morphology = np.mean(morphology_similarities)
                similarities.append(('morphology', overall_morphology, 0.15))
            
            # 6. Compare feature lists (categorical features)
            if 'features' in features1 and 'features' in features2:
                feats1 = set(features1['features']) if isinstance(features1['features'], list) else set()
                feats2 = set(features2['features']) if isinstance(features2['features'], list) else set()
                
                if feats1 or feats2:
                    # Jaccard similarity
                    intersection = len(feats1.intersection(feats2))
                    union = len(feats1.union(feats2))
                    
                    if union > 0:
                        jaccard_similarity = intersection / union
                        similarities.append(('categorical_features', jaccard_similarity, 0.1))
            
            # 7. Compare wavelet features
            if 'features' in features1.get('wavelet_analysis', {}) and 'features' in features2.get('wavelet_analysis', {}):
                wavelet1 = np.array(features1['wavelet_analysis']['features'])
                wavelet2 = np.array(features2['wavelet_analysis']['features'])
                
                if len(wavelet1) > 0 and len(wavelet2) > 0:
                    min_len = min(len(wavelet1), len(wavelet2))
                    wavelet1 = wavelet1[:min_len]
                    wavelet2 = wavelet2[:min_len]
                    
                    # Correlation-based similarity
                    if np.std(wavelet1) > 0 and np.std(wavelet2) > 0:
                        wavelet_corr = np.corrcoef(wavelet1, wavelet2)[0, 1]
                        if not np.isnan(wavelet_corr):
                            wavelet_similarity = (wavelet_corr + 1) / 2
                            similarities.append(('wavelet_features', wavelet_similarity, 0.05))
            
            # Calculate weighted average
            if similarities:
                total_weight = sum(weight for _, _, weight in similarities)
                if total_weight > 0:
                    weighted_similarity = sum(sim * weight for _, sim, weight in similarities) / total_weight
                else:
                    weighted_similarity = np.mean([sim for _, sim, _ in similarities])
                
                return float(np.clip(weighted_similarity, 0.0, 1.0))
            
            # Fallback comparison using available numeric values
            numeric_features1 = {}
            numeric_features2 = {}
            
            # Extract all numeric features from both datasets
            for feature_dict in [features1, features2]:
                numeric_dict = numeric_features1 if feature_dict is features1 else numeric_features2
                
                for key, value in feature_dict.items():
                    if isinstance(value, (int, float)):
                        numeric_dict[key] = value
                    elif isinstance(value, dict):
                        for subkey, subvalue in value.items():
                            if isinstance(subvalue, (int, float)):
                                numeric_dict[f"{key}_{subkey}"] = subvalue
                    elif isinstance(value, list) and all(isinstance(v, (int, float)) for v in value):
                        for i, v in enumerate(value[:5]):  # Limit to first 5 elements
                            numeric_dict[f"{key}_{i}"] = v
            
            # Compare common numeric features
            common_keys = set(numeric_features1.keys()).intersection(set(numeric_features2.keys()))
            
            if common_keys:
                similarities = []
                for key in common_keys:
                    val1, val2 = numeric_features1[key], numeric_features2[key]
                    max_val = max(abs(val1), abs(val2), 1e-10)
                    similarity = 1.0 - abs(val1 - val2) / max_val
                    similarities.append(similarity)
                
                return float(np.clip(np.mean(similarities), 0.0, 1.0))
            
            return 0.5  # Default neutral similarity
            
        except Exception as e:
            # Final fallback
            return 0.5
    
