    def quantify_uncertainty_reduction_potential(self, system: Dict[str, Any]) -> Dict[str, Any]:
        """
        Quantify the potential for reducing uncertainty in the geological system.
        
        Args:
            system: Geological system with uncertainty information
            
        Returns:
            Dictionary containing uncertainty reduction potential analysis
        """
        uncertainty_info = self._extract_system_uncertainty(system)
        
        # Analyze uncertainty sources for reducibility
        reducible_sources = self._identify_reducible_uncertainty_sources(uncertainty_info)
        reduction_strategies = self._develop_uncertainty_reduction_strategies(uncertainty_info)
        information_value = self._calculate_information_value_analysis(uncertainty_info)
        
        # Prioritize reduction efforts
        reduction_priorities = self._prioritize_reduction_efforts(
            reducible_sources, reduction_strategies, information_value
        )
        
        return {
            'reducible_sources': reducible_sources,
            'reduction_strategies': reduction_strategies,
            'information_value': information_value,
            'reduction_priorities': reduction_priorities,
            'expected_reduction': self._estimate_expected_reduction(reduction_strategies),
            'cost_benefit_analysis': self._perform_cost_benefit_analysis(reduction_strategies)
        }
    
    def perform_uncertainty_attribution(self, system: Dict[str, Any]) -> Dict[str, Any]:
        """
        Perform comprehensive uncertainty attribution analysis.
        
        Args:
            system: Geological system with uncertainty information
            
        Returns:
            Dictionary containing uncertainty attribution results
        """
        uncertainty_info = self._extract_system_uncertainty(system)
        
        # Decompose total uncertainty into components
        uncertainty_decomposition = self._decompose_total_uncertainty(uncertainty_info)
        
        # Attribute uncertainty to specific sources
        source_attribution = self._attribute_uncertainty_to_sources(uncertainty_info)
        
        # Analyze uncertainty interactions
        interaction_analysis = self._analyze_uncertainty_interactions(uncertainty_info)
        
        # Create uncertainty budget
        uncertainty_budget = self._create_detailed_uncertainty_budget(
            uncertainty_decomposition, source_attribution, interaction_analysis
        )
        
        return {
            'uncertainty_decomposition': uncertainty_decomposition,
            'source_attribution': source_attribution,
            'interaction_analysis': interaction_analysis,
            'uncertainty_budget': uncertainty_budget,
            'dominant_contributors': self._identify_dominant_contributors(uncertainty_budget),
            'attribution_confidence': self._assess_attribution_confidence(uncertainty_budget)
        }
    
    def _analyze_aleatory_uncertainty(self, system: Dict[str, Any]) -> Dict[str, Any]:
        """Analyze aleatory (irreducible) uncertainty in the system using advanced stochastic methods."""
        try:
            # Extract aleatory components
            random_variables = self._extract_random_variables(system)
            stochastic_processes = self._extract_stochastic_processes(system)
            noise_characteristics = self._extract_noise_characteristics(system)
            
            # Monte Carlo uncertainty propagation
            mc_results = self._monte_carlo_uncertainty_propagation(system, random_variables)
            
            # Polynomial chaos expansion for efficient uncertainty quantification
            pce_results = self._polynomial_chaos_expansion(system, random_variables)
            
            # Stochastic finite element analysis for spatial aleatory uncertainty
            sfem_results = self._stochastic_finite_element_analysis(system)
            
            # Random field analysis for spatially correlated uncertainty
            random_field_analysis = self._analyze_random_fields(system, stochastic_processes)
            
            # Extreme value analysis for tail behavior
            extreme_value_analysis = self._extreme_value_analysis(mc_results)
            
            # Sensitivity analysis for aleatory parameters
            sensitivity_analysis = self._aleatory_sensitivity_analysis(system, random_variables)
            
            # Statistical convergence assessment
            convergence_metrics = self._assess_statistical_convergence(mc_results, pce_results)
            
            # Uncertainty interaction analysis
            interaction_effects = self._analyze_aleatory_interactions(random_variables)
            
            return {
                'analysis_type': 'aleatory_uncertainty',
                'random_variables': random_variables,
                'stochastic_processes': stochastic_processes,
                'noise_characteristics': noise_characteristics,
                'monte_carlo_results': mc_results,
                'polynomial_chaos_expansion': pce_results,
                'stochastic_fem_results': sfem_results,
                'random_field_analysis': random_field_analysis,
                'extreme_value_analysis': extreme_value_analysis,
                'sensitivity_analysis': sensitivity_analysis,
                'convergence_metrics': convergence_metrics,
                'interaction_effects': interaction_effects,
                'uncertainty_bounds': self._calculate_aleatory_bounds(mc_results, pce_results),
                'statistical_moments': self._calculate_statistical_moments(mc_results),
                'probability_distributions': self._fit_probability_distributions(mc_results),
                'confidence_intervals': self._calculate_confidence_intervals(mc_results),
                'reliability_metrics': self._calculate_reliability_metrics(mc_results, system)
            }
        except Exception as e:
            self._log_error(f"Aleatory uncertainty analysis failed: {str(e)}")
            return self._get_default_uncertainty_analysis('aleatory')
    
