    def _extract_temporal_data(self, experiences: List[Dict]) -> Dict[str, Any]:
        """Extract temporal data from experiences."""
        try:
            temporal_data = {
                'timestamps': [],
                'values': [],
                'features': {},
                'metadata': {}
            }
            
            # Extract core temporal information
            for exp in experiences:
                timestamp = exp.get('timestamp', time.time())
                temporal_data['timestamps'].append(timestamp)
                
                # Extract primary value (quality score, reward, etc.)
                value = exp.get('quality_score', exp.get('reward', exp.get('value', 0.0)))
                temporal_data['values'].append(value)
                
                # Extract additional features for multivariate analysis
                for key in ['action', 'state', 'observation', 'prediction']:
                    if key in exp:
                        if key not in temporal_data['features']:
                            temporal_data['features'][key] = []
                        temporal_data['features'][key].append(exp[key])
            
            # Convert to arrays for analysis
            temporal_data['timestamps'] = np.array(temporal_data['timestamps'])
            temporal_data['values'] = np.array(temporal_data['values'])
            
            # Sort by timestamp
            sorted_indices = np.argsort(temporal_data['timestamps'])
            temporal_data['timestamps'] = temporal_data['timestamps'][sorted_indices]
            temporal_data['values'] = temporal_data['values'][sorted_indices]
            
            # Calculate time differences
            temporal_data['time_deltas'] = np.diff(temporal_data['timestamps'])
            temporal_data['sampling_rate'] = 1.0 / np.mean(temporal_data['time_deltas']) if len(temporal_data['time_deltas']) > 0 else 1.0
            
            return temporal_data
            
        except Exception as e:
            logging.error(f"Error extracting temporal data: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_temporal_scale(self, temporal_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Analyze temporal patterns at specific scale."""
        try:
            scale_config = self.scale_definitions.get(scale, {})
            
            scale_analysis = {
                'scale': scale,
                'duration': scale_config.get('duration', 'unknown'),
                'resolution': scale_config.get('resolution', 1.0),
                'patterns_detected': 0,
                'dominant_frequency': 0.0,
                'temporal_stability': 0.0,
                'characteristic_features': {}
            }
            
            # Apply scale-specific filtering
            filtered_data = self._apply_scale_filtering(temporal_data, scale)
            
            # Scale-specific pattern detection
            patterns = self._detect_scale_patterns(filtered_data, scale)
            scale_analysis['patterns_detected'] = len(patterns)
            scale_analysis['patterns'] = patterns
            
            # Frequency analysis at scale
            frequency_analysis = self._analyze_scale_frequencies(filtered_data, scale)
            scale_analysis['frequency_analysis'] = frequency_analysis
            scale_analysis['dominant_frequency'] = frequency_analysis.get('dominant_frequency', 0.0)
            
            # Stability analysis
            stability_score = self._calculate_scale_stability(filtered_data)
            scale_analysis['temporal_stability'] = stability_score
            
            # Characteristic features
            features = self._extract_scale_features(filtered_data, scale)
            scale_analysis['characteristic_features'] = features
            
            return scale_analysis
            
        except Exception as e:
            logging.error(f"Error analyzing temporal scale {scale}: {str(e)}")
            return {'scale': scale, 'error': str(e)}
    
    def _apply_scale_filtering(self, temporal_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Apply scale-specific temporal filtering."""
        try:
            # Get scale configuration
            scale_config = self.scale_definitions.get(scale, {})
            resolution = scale_config.get('resolution', 1.0)
            
            # Apply appropriate filtering based on scale
            filtered_data = temporal_data.copy()
            
            if scale == 'micro':
                # High-pass filtering for micro-scale
                filtered_data['values'] = self._apply_highpass_filter(temporal_data['values'])
            elif scale == 'short':
                # Band-pass filtering for short-term patterns
                filtered_data['values'] = self._apply_bandpass_filter(temporal_data['values'], 0.1, 1.0)
            elif scale == 'medium':
                # Medium-term trend extraction
                filtered_data['values'] = self._apply_moving_average(temporal_data['values'], window=24)
            elif scale == 'long':
                # Long-term trend analysis
                filtered_data['values'] = self._apply_seasonal_decomposition(temporal_data['values'])
            elif scale == 'geological':
                # Very long-term trend extraction
                filtered_data['values'] = self._apply_lowpass_filter(temporal_data['values'])
            
            return filtered_data
            
        except Exception as e:
            logging.error(f"Error applying scale filtering for {scale}: {str(e)}")
            return temporal_data
    
    def _detect_scale_patterns(self, filtered_data: Dict[str, Any], scale: str) -> List[Dict[str, Any]]:
        """Detect patterns at specific temporal scale."""
        try:
            patterns = []
            
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return patterns
            
            # Pattern detection based on scale
            if scale == 'micro':
                # Detect rapid events and spikes
                patterns.extend(self._detect_spike_patterns(values))
                patterns.extend(self._detect_burst_patterns(values))
                
            elif scale == 'short':
                # Detect daily patterns and cycles
                patterns.extend(self._detect_daily_patterns(values))
                patterns.extend(self._detect_periodic_patterns(values, period_range=(1, 24)))
                
            elif scale == 'medium':
                # Detect weekly and monthly patterns
                patterns.extend(self._detect_weekly_patterns(values))
                patterns.extend(self._detect_monthly_patterns(values))
                
            elif scale == 'long':
                # Detect seasonal patterns
                patterns.extend(self._detect_seasonal_patterns(values))
                patterns.extend(self._detect_annual_patterns(values))
                
            elif scale == 'geological':
                # Detect long-term trends and geological cycles
                patterns.extend(self._detect_longterm_trends(values))
                patterns.extend(self._detect_geological_cycles(values))
            
            return patterns
            
        except Exception as e:
            logging.error(f"Error detecting patterns for scale {scale}: {str(e)}")
            return []
    
    def _analyze_scale_frequencies(self, filtered_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Analyze frequency characteristics at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return {'error': 'Insufficient data for frequency analysis'}
            
            # Perform FFT analysis
            fft_result = np.fft.fft(values)
            frequencies = np.fft.fftfreq(len(values))
            power_spectrum = np.abs(fft_result) ** 2
            
            # Find dominant frequency
            dominant_idx = np.argmax(power_spectrum[1:len(power_spectrum)//2]) + 1
            dominant_frequency = abs(frequencies[dominant_idx])
            
            # Calculate spectral features
            spectral_centroid = np.sum(frequencies[1:len(frequencies)//2] * power_spectrum[1:len(power_spectrum)//2]) / np.sum(power_spectrum[1:len(power_spectrum)//2])
            spectral_rolloff = self._calculate_spectral_rolloff(frequencies, power_spectrum)
            spectral_bandwidth = self._calculate_spectral_bandwidth(frequencies, power_spectrum, spectral_centroid)
            
            return {
                'dominant_frequency': dominant_frequency,
                'spectral_centroid': spectral_centroid,
                'spectral_rolloff': spectral_rolloff,
                'spectral_bandwidth': spectral_bandwidth,
                'power_spectrum_peak': np.max(power_spectrum),
                'frequency_resolution': frequencies[1] - frequencies[0] if len(frequencies) > 1 else 0.0
            }
            
        except Exception as e:
            logging.error(f"Error in frequency analysis for scale {scale}: {str(e)}")
            return {'error': str(e)}
    
    def _calculate_scale_stability(self, filtered_data: Dict[str, Any]) -> float:
        """Calculate temporal stability at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 10:
                return 0.0
            
            # Calculate various stability metrics
            cv = np.std(values) / np.mean(values) if np.mean(values) != 0 else float('inf')
            stability_cv = max(0.0, 1.0 - cv)
            
            # Trend stability
            trend_stability = 1.0 - abs(np.polyfit(range(len(values)), values, 1)[0])
            trend_stability = max(0.0, min(1.0, trend_stability))
            
            # Autocorrelation stability
            autocorr = np.corrcoef(values[:-1], values[1:])[0, 1] if len(values) > 1 else 0.0
            autocorr_stability = abs(autocorr) if not np.isnan(autocorr) else 0.0
            
            # Combined stability score
            stability_score = (stability_cv + trend_stability + autocorr_stability) / 3.0
            
            return max(0.0, min(1.0, stability_score))
            
        except Exception as e:
            logging.error(f"Error calculating scale stability: {str(e)}")
            return 0.0
    
    def _extract_scale_features(self, filtered_data: Dict[str, Any], scale: str) -> Dict[str, Any]:
        """Extract characteristic features at specific scale."""
        try:
            values = filtered_data.get('values', [])
            if len(values) < 5:
                return {}
            
            features = {
                'mean': np.mean(values),
                'std': np.std(values),
                'min': np.min(values),
                'max': np.max(values),
                'range': np.max(values) - np.min(values),
                'skewness': self._calculate_skewness(values),
                'kurtosis': self._calculate_kurtosis(values),
                'trend_slope': np.polyfit(range(len(values)), values, 1)[0] if len(values) > 1 else 0.0,
                'autocorrelation': np.corrcoef(values[:-1], values[1:])[0, 1] if len(values) > 1 else 0.0,
                'energy': np.sum(np.square(values)),
                'zero_crossings': self._count_zero_crossings(values),
                'peak_count': self._count_peaks(values),
                'entropy': self._calculate_temporal_entropy(values)
            }
            
            # Scale-specific features
            if scale == 'micro':
                features['spike_rate'] = self._calculate_spike_rate(values)
                features['burst_duration'] = self._calculate_burst_duration(values)
            elif scale in ['short', 'medium']:
                features['periodicity_strength'] = self._calculate_periodicity_strength(values)
                features['cycle_regularity'] = self._calculate_cycle_regularity(values)
            elif scale in ['long', 'geological']:
                features['trend_strength'] = abs(features['trend_slope'])
                features['seasonal_strength'] = self._calculate_seasonal_strength(values)
            
            return features
            
        except Exception as e:
            logging.error(f"Error extracting scale features for {scale}: {str(e)}")
            return {}
    
    def _detect_temporal_patterns(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Detect comprehensive temporal patterns."""
        try:
            pattern_analysis = {
                'total_patterns': 0,
                'pattern_types': {},
                'pattern_strength': 0.0,
                'pattern_confidence': 0.0
            }
            
            values = temporal_data.get('values', [])
            if len(values) < 20:
                return pattern_analysis
            
            # Various pattern detection methods
            pattern_detectors = {
                'periodic_patterns': self._detect_periodic_patterns,
                'trend_patterns': self._detect_trend_patterns,
                'cyclic_patterns': self._detect_cyclic_patterns,
                'seasonal_patterns': self._detect_seasonal_patterns,
                'anomaly_patterns': self._detect_anomaly_patterns,
                'regime_changes': self._detect_regime_changes,
                'oscillatory_patterns': self._detect_oscillatory_patterns,
                'burst_patterns': self._detect_burst_patterns
            }
            
            all_patterns = []
            for pattern_type, detector in pattern_detectors.items():
                try:
                    patterns = detector(values)
                    pattern_analysis['pattern_types'][pattern_type] = len(patterns)
                    all_patterns.extend(patterns)
                except Exception as e:
                    logging.error(f"Error in {pattern_type} detection: {str(e)}")
                    pattern_analysis['pattern_types'][pattern_type] = 0
            
            pattern_analysis['total_patterns'] = len(all_patterns)
            
            # Calculate overall pattern strength and confidence
            if all_patterns:
                strengths = [p.get('strength', 0.0) for p in all_patterns]
                confidences = [p.get('confidence', 0.0) for p in all_patterns]
                
                pattern_analysis['pattern_strength'] = np.mean(strengths)
                pattern_analysis['pattern_confidence'] = np.mean(confidences)
            
            pattern_analysis['detected_patterns'] = all_patterns
            
            return pattern_analysis
            
        except Exception as e:
            logging.error(f"Error in temporal pattern detection: {str(e)}")
            return {'total_patterns': 0, 'error': str(e)}
    
    def _perform_trend_decomposition(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive trend decomposition analysis."""
        try:
            values = temporal_data.get('values', [])
            if len(values) < 24:  # Minimum for seasonal decomposition
                return {'error': 'Insufficient data for trend decomposition'}
            
            trend_analysis = {
                'decomposition_method': 'seasonal_decompose',
                'trend_strength': 0.0,
                'seasonal_strength': 0.0,
                'residual_variance': 0.0,
                'decomposition_quality': 0.0
            }
            
            try:
                from statsmodels.tsa.seasonal import seasonal_decompose
                
                # Perform seasonal decomposition
                decomposition = seasonal_decompose(values, model='additive', period=min(12, len(values)//2))
                
                # Extract components
                trend = decomposition.trend
                seasonal = decomposition.seasonal
                residual = decomposition.resid
                
                # Remove NaN values
                trend = trend[~np.isnan(trend)]
                seasonal = seasonal[~np.isnan(seasonal)]
                residual = residual[~np.isnan(residual)]
                
                # Calculate component strengths
                if len(trend) > 0:
                    trend_analysis['trend_strength'] = np.var(trend) / np.var(values) if np.var(values) > 0 else 0.0
                
                if len(seasonal) > 0:
                    trend_analysis['seasonal_strength'] = np.var(seasonal) / np.var(values) if np.var(values) > 0 else 0.0
                
                if len(residual) > 0:
                    trend_analysis['residual_variance'] = np.var(residual)
                
                # Quality of decomposition
                explained_variance = trend_analysis['trend_strength'] + trend_analysis['seasonal_strength']
                trend_analysis['decomposition_quality'] = min(1.0, explained_variance)
                
                # Store components
                trend_analysis['components'] = {
                    'trend': trend.tolist() if len(trend) > 0 else [],
                    'seasonal': seasonal.tolist() if len(seasonal) > 0 else [],
                    'residual': residual.tolist() if len(residual) > 0 else []
                }
                
                # Trend characteristics
                if len(trend) > 1:
                    trend_slope = np.polyfit(range(len(trend)), trend, 1)[0]
                    trend_analysis['trend_direction'] = 'increasing' if trend_slope > 0.01 else 'decreasing' if trend_slope < -0.01 else 'stable'
                    trend_analysis['trend_slope'] = trend_slope
                
            except ImportError:
                # Fallback to simple trend analysis without statsmodels
                trend_analysis.update(self._simple_trend_analysis(values))
                
            return trend_analysis
            
        except Exception as e:
            logging.error(f"Error in trend decomposition: {str(e)}")
            return {'error': str(e)}
    
    def _simple_trend_analysis(self, values: List[float]) -> Dict[str, Any]:
        """Simple trend analysis without external dependencies."""
        try:
            # Linear trend
            x = np.arange(len(values))
            trend_slope, trend_intercept = np.polyfit(x, values, 1)
            trend_line = trend_slope * x + trend_intercept
            
            # Detrended values
            detrended = np.array(values) - trend_line
            
            # Moving average (simple seasonal component)
            window = min(12, len(values) // 4)
            if window > 0:
                seasonal = np.convolve(detrended, np.ones(window)/window, mode='same')
            else:
                seasonal = np.zeros_like(detrended)
            
            # Residual
            residual = detrended - seasonal
            
            return {
                'trend_strength': np.var(trend_line) / np.var(values) if np.var(values) > 0 else 0.0,
                'seasonal_strength': np.var(seasonal) / np.var(values) if np.var(values) > 0 else 0.0,
                'residual_variance': np.var(residual),
                'trend_slope': trend_slope,
                'trend_direction': 'increasing' if trend_slope > 0.01 else 'decreasing' if trend_slope < -0.01 else 'stable',
                'decomposition_method': 'simple_linear'
            }
            
        except Exception as e:
            logging.error(f"Error in simple trend analysis: {str(e)}")
            return {'error': str(e)}
    
    def _perform_seasonal_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive seasonal pattern analysis."""
        try:
            values = temporal_data.get('values', [])
            timestamps = temporal_data.get('timestamps', [])
            
            seasonal_analysis = {
                'seasonal_periods_detected': 0,
                'seasonal_strength': 0.0,
                'dominant_period': 0,
                'seasonal_patterns': []
            }
            
            if len(values) < 20:
                return seasonal_analysis
            
            # Detect multiple seasonal periods
            periods_to_test = [7, 12, 24, 30, 365] if len(values) >= 365 else [7, 12, 24]
            periods_to_test = [p for p in periods_to_test if p < len(values) // 3]
            
            detected_periods = []
            
            for period in periods_to_test:
                seasonal_strength = self._test_seasonal_period(values, period)
                
                if seasonal_strength > self.seasonal_threshold:
                    detected_periods.append({
                        'period': period,
                        'strength': seasonal_strength,
                        'pattern': self._extract_seasonal_pattern(values, period)
                    })
            
            # Sort by strength
            detected_periods.sort(key=lambda x: x['strength'], reverse=True)
            
            seasonal_analysis['seasonal_periods_detected'] = len(detected_periods)
            seasonal_analysis['seasonal_patterns'] = detected_periods
            
            if detected_periods:
                seasonal_analysis['dominant_period'] = detected_periods[0]['period']
                seasonal_analysis['seasonal_strength'] = detected_periods[0]['strength']
            
            # Additional seasonal analysis
            seasonal_analysis['seasonality_tests'] = self._perform_seasonality_tests(values)
            
            return seasonal_analysis
            
        except Exception as e:
            logging.error(f"Error in seasonal analysis: {str(e)}")
            return {'error': str(e)}
    
    def _test_seasonal_period(self, values: List[float], period: int) -> float:
        """Test for seasonal pattern with specific period."""
        try:
            if len(values) < 2 * period:
                return 0.0
            
            # Reshape data into seasonal periods
            n_complete_periods = len(values) // period
            reshaped = np.array(values[:n_complete_periods * period]).reshape(n_complete_periods, period)
            
            # Calculate mean seasonal pattern
            seasonal_mean = np.mean(reshaped, axis=0)
            
            # Calculate seasonal strength as correlation with mean pattern
            correlations = []
            for i in range(n_complete_periods):
                corr = np.corrcoef(reshaped[i], seasonal_mean)[0, 1]
                if not np.isnan(corr):
                    correlations.append(abs(corr))
            
            return np.mean(correlations) if correlations else 0.0
            
        except Exception as e:
            logging.error(f"Error testing seasonal period {period}: {str(e)}")
            return 0.0
    
    def _extract_seasonal_pattern(self, values: List[float], period: int) -> List[float]:
        """Extract the seasonal pattern for a given period."""
        try:
            n_complete_periods = len(values) // period
            if n_complete_periods < 2:
                return []
            
            reshaped = np.array(values[:n_complete_periods * period]).reshape(n_complete_periods, period)
            seasonal_pattern = np.mean(reshaped, axis=0)
            
            return seasonal_pattern.tolist()
            
        except Exception as e:
            logging.error(f"Error extracting seasonal pattern for period {period}: {str(e)}")
            return []
    
    def _perform_seasonality_tests(self, values: List[float]) -> Dict[str, Any]:
        """Perform statistical tests for seasonality."""
        try:
            tests = {}
            
            # Autocorrelation test
            if len(values) > 24:
                autocorr_12 = self._calculate_autocorrelation(values, 12)
                autocorr_24 = self._calculate_autocorrelation(values, 24)
                
                tests['autocorr_test'] = {
                    'lag_12': autocorr_12,
                    'lag_24': autocorr_24,
                    'seasonal_evidence': max(abs(autocorr_12), abs(autocorr_24)) > 0.3
                }
            
            # Periodogram test
            if len(values) > 50:
                periodogram_result = self._calculate_periodogram(values)
                tests['periodogram_test'] = periodogram_result
            
            return tests
            
        except Exception as e:
            logging.error(f"Error in seasonality tests: {str(e)}")
            return {'error': str(e)}
    
    def _perform_causality_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal causality analysis."""
        try:
            causality_analysis = {
                'granger_causality': {},
                'cross_correlation': {},
                'lag_analysis': {},
                'causal_strength': 0.0
            }
            
            # Multi-variate causality analysis if features available
            features = temporal_data.get('features', {})
            values = temporal_data.get('values', [])
            
            if len(values) < 20:
                return causality_analysis
            
            # Self-causality (autocorrelation)
            self_causality = self._analyze_self_causality(values)
            causality_analysis['self_causality'] = self_causality
            
            # Cross-variable causality if multiple features
            if features:
                for feature_name, feature_values in features.items():
                    if isinstance(feature_values[0], (int, float)) and len(feature_values) == len(values):
                        cross_analysis = self._analyze_cross_causality(values, feature_values, feature_name)
                        causality_analysis['cross_causality'][feature_name] = cross_analysis
            
            # Overall causal strength
            all_strengths = []
            all_strengths.append(self_causality.get('strength', 0.0))
            
            for cross_causal in causality_analysis.get('cross_causality', {}).values():
                all_strengths.append(cross_causal.get('strength', 0.0))
            
            causality_analysis['causal_strength'] = np.mean(all_strengths) if all_strengths else 0.0
            
            return causality_analysis
            
        except Exception as e:
            logging.error(f"Error in causality analysis: {str(e)}")
            return {'error': str(e)}
    
    def _analyze_self_causality(self, values: List[float]) -> Dict[str, Any]:
        """Analyze self-causality (autocorrelation structure)."""
        try:
            max_lag = min(20, len(values) // 4)
            autocorrelations = []
            
            for lag in range(1, max_lag + 1):
                autocorr = self._calculate_autocorrelation(values, lag)
                autocorrelations.append({'lag': lag, 'correlation': autocorr})
            
            # Find most significant lag
            max_autocorr = max(autocorrelations, key=lambda x: abs(x['correlation']))
            
            return {
                'autocorrelations': autocorrelations,
                'max_lag': max_autocorr['lag'],
                'max_correlation': max_autocorr['correlation'],
                'strength': abs(max_autocorr['correlation'])
            }
            
        except Exception as e:
            logging.error(f"Error in self-causality analysis: {str(e)}")
            return {'strength': 0.0}
    
    def _analyze_cross_causality(self, target_values: List[float], feature_values: List[float], feature_name: str) -> Dict[str, Any]:
        """Analyze cross-causality between target and feature."""
        try:
            max_lag = min(10, len(target_values) // 4)
            cross_correlations = []
            
            for lag in range(max_lag + 1):
                if lag == 0:
                    cross_corr = np.corrcoef(target_values, feature_values)[0, 1]
                else:
                    if lag < len(feature_values):
                        cross_corr = np.corrcoef(target_values[lag:], feature_values[:-lag])[0, 1]
                    else:
                        cross_corr = 0.0
                
                if not np.isnan(cross_corr):
                    cross_correlations.append({'lag': lag, 'correlation': cross_corr})
            
            # Find most significant lag
            if cross_correlations:
                max_cross_corr = max(cross_correlations, key=lambda x: abs(x['correlation']))
                
                return {
                    'feature_name': feature_name,
                    'cross_correlations': cross_correlations,
                    'max_lag': max_cross_corr['lag'],
                    'max_correlation': max_cross_corr['correlation'],
                    'strength': abs(max_cross_corr['correlation']),
                    'causal_direction': 'feature_to_target' if max_cross_corr['lag'] > 0 else 'contemporaneous'
                }
            
            return {'feature_name': feature_name, 'strength': 0.0}
            
        except Exception as e:
            logging.error(f"Error in cross-causality analysis for {feature_name}: {str(e)}")
            return {'feature_name': feature_name, 'strength': 0.0}
    
    def _perform_anomaly_detection(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal anomaly detection."""
        try:
            values = temporal_data.get('values', [])
            
            anomaly_analysis = {
                'anomalies_detected': 0,
                'anomaly_rate': 0.0,
                'anomaly_types': {},
                'anomaly_locations': []
            }
            
            if len(values) < 10:
                return anomaly_analysis
            
            # Multiple anomaly detection methods
            anomaly_detectors = {
                'statistical_outliers': self._detect_statistical_outliers,
                'zscore_anomalies': self._detect_zscore_anomalies,
                'isolation_forest': self._detect_isolation_anomalies,
                'change_points': self._detect_change_points,
                'temporal_outliers': self._detect_temporal_outliers
            }
            
            all_anomalies = []
            
            for anomaly_type, detector in anomaly_detectors.items():
                try:
                    anomalies = detector(values)
                    anomaly_analysis['anomaly_types'][anomaly_type] = len(anomalies)
                    all_anomalies.extend([(idx, anomaly_type) for idx in anomalies])
                except Exception as e:
                    logging.error(f"Error in {anomaly_type} detection: {str(e)}")
                    anomaly_analysis['anomaly_types'][anomaly_type] = 0
            
            # Remove duplicates and sort
            unique_anomalies = list(set([idx for idx, _ in all_anomalies]))
            unique_anomalies.sort()
            
            anomaly_analysis['anomalies_detected'] = len(unique_anomalies)
            anomaly_analysis['anomaly_rate'] = len(unique_anomalies) / len(values)
            anomaly_analysis['anomaly_locations'] = unique_anomalies
            
            return anomaly_analysis
            
        except Exception as e:
            logging.error(f"Error in anomaly detection: {str(e)}")
            return {'error': str(e)}
    
    def _perform_forecasting_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform temporal forecasting analysis."""
        try:
            values = temporal_data.get('values', [])
            
            forecast_analysis = {
                'forecast_horizon': 10,
                'forecasting_methods': {},
                'ensemble_forecast': [],
                'forecast_confidence': 0.0
            }
            
            if len(values) < 20:
                return forecast_analysis
            
            # Try multiple forecasting methods
            forecasting_methods = {
                'simple_moving_average': self._forecast_moving_average,
                'exponential_smoothing': self._forecast_exponential_smoothing,
                'linear_trend': self._forecast_linear_trend,
                'seasonal_naive': self._forecast_seasonal_naive
            }
            
            all_forecasts = []
            
            for method_name, method_func in forecasting_methods.items():
                try:
                    forecast_result = method_func(values)
                    forecast_analysis['forecasting_methods'][method_name] = forecast_result
                    
                    if 'forecast' in forecast_result:
                        all_forecasts.append(forecast_result['forecast'])
                except Exception as e:
                    logging.error(f"Error in {method_name} forecasting: {str(e)}")
                    forecast_analysis['forecasting_methods'][method_name] = {'error': str(e)}
            
            # Ensemble forecast
            if all_forecasts:
                ensemble_forecast = np.mean(all_forecasts, axis=0)
                forecast_analysis['ensemble_forecast'] = ensemble_forecast.tolist()
                
                # Calculate forecast confidence
                forecast_std = np.std(all_forecasts, axis=0)
                forecast_analysis['forecast_confidence'] = 1.0 / (1.0 + np.mean(forecast_std))
            
            return forecast_analysis
            
        except Exception as e:
            logging.error(f"Error in forecasting analysis: {str(e)}")
            return {'error': str(e)}
    
    def _perform_correlation_analysis(self, temporal_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive temporal correlation analysis."""
        try:
            values = temporal_data.get('values', [])
            features = temporal_data.get('features', {})
            
            correlation_analysis = {
                'auto_correlations': {},
                'cross_correlations': {},
                'correlation_strength': 0.0
            }
            
            if len(values) < 10:
                return correlation_analysis
            
            # Auto-correlation analysis
            max_lag = min(20, len(values) // 3)
            auto_correlations = []
            
            for lag in range(1, max_lag + 1):
                autocorr = self._calculate_autocorrelation(values, lag)
                auto_correlations.append({'lag': lag, 'correlation': autocorr})
            
            correlation_analysis['auto_correlations'] = auto_correlations
            
            # Cross-correlation with features
            for feature_name, feature_values in features.items():
                if isinstance(feature_values[0], (int, float)) and len(feature_values) == len(values):
                    cross_corr = np.corrcoef(values, feature_values)[0, 1]
                    if not np.isnan(cross_corr):
                        correlation_analysis['cross_correlations'][feature_name] = cross_corr
            
            # Overall correlation strength
            all_correlations = [abs(ac['correlation']) for ac in auto_correlations if not np.isnan(ac['correlation'])]
            all_correlations.extend([abs(cc) for cc in correlation_analysis['cross_correlations'].values()])
            
            correlation_analysis['correlation_strength'] = np.mean(all_correlations) if all_correlations else 0.0
            
            return correlation_analysis
            
        except Exception as e:
            logging.error(f"Error in correlation analysis: {str(e)}")
            return {'error': str(e)}
    
    def _calculate_temporal_coherence(self, temporal_analysis: Dict[str, Any]) -> float:
        """Calculate overall temporal coherence score."""
        try:
            coherence_factors = []
            
            # Pattern analysis coherence
            pattern_analysis = temporal_analysis.get('pattern_analysis', {})
            if pattern_analysis.get('total_patterns', 0) > 0:
                coherence_factors.append(pattern_analysis.get('pattern_confidence', 0.0))
            
            # Trend analysis coherence
            trend_analysis = temporal_analysis.get('trend_analysis', {})
            if 'decomposition_quality' in trend_analysis:
                coherence_factors.append(trend_analysis['decomposition_quality'])
            
            # Seasonal analysis coherence
            seasonal_analysis = temporal_analysis.get('seasonal_analysis', {})
            if seasonal_analysis.get('seasonal_strength', 0.0) > 0:
                coherence_factors.append(seasonal_analysis['seasonal_strength'])
            
            # Correlation analysis coherence
            correlation_analysis = temporal_analysis.get('correlation_analysis', {})
            if 'correlation_strength' in correlation_analysis:
                coherence_factors.append(correlation_analysis['correlation_strength'])
            
            # Scale analysis coherence
            scale_coherence = []
            for scale in self.temporal_scales:
                scale_analysis = temporal_analysis.get(f'{scale}_scale', {})
                if 'temporal_stability' in scale_analysis:
                    scale_coherence.append(scale_analysis['temporal_stability'])
            
            if scale_coherence:
                coherence_factors.append(np.mean(scale_coherence))
            
            # Overall coherence
            if coherence_factors:
                return min(1.0, np.mean(coherence_factors))
            else:
                return 0.5  # Default neutral coherence
                
        except Exception as e:
            logging.error(f"Error calculating temporal coherence: {str(e)}")
            return 0.0
    
    def _assess_temporal_quality(self, temporal_analysis: Dict[str, Any]) -> Dict[str, Any]:
        """Assess quality of temporal analysis."""
        try:
            quality_metrics = {
                'data_completeness': 0.0,
                'analysis_coverage': 0.0,
                'pattern_reliability': 0.0,
                'forecast_accuracy': 0.0,
                'overall_quality': 0.0
            }
            
            # Data completeness
            total_analyses = len(self.temporal_analyzers)
            completed_analyses = sum(1 for key in temporal_analysis.keys() 
                                   if not key.endswith('error') and temporal_analysis[key])
            
            quality_metrics['data_completeness'] = completed_analyses / total_analyses if total_analyses > 0 else 0.0
            
            # Analysis coverage
            expected_components = ['pattern_analysis', 'trend_analysis', 'seasonal_analysis', 'correlation_analysis']
            available_components = sum(1 for comp in expected_components if comp in temporal_analysis)
            quality_metrics['analysis_coverage'] = available_components / len(expected_components)
            
            # Pattern reliability
            pattern_analysis = temporal_analysis.get('pattern_analysis', {})
            quality_metrics['pattern_reliability'] = pattern_analysis.get('pattern_confidence', 0.0)
            
            # Forecast accuracy (if available)
            forecast_analysis = temporal_analysis.get('forecast_analysis', {})
            quality_metrics['forecast_accuracy'] = forecast_analysis.get('forecast_confidence', 0.0)
            
            # Overall quality
            quality_metrics['overall_quality'] = np.mean([
                quality_metrics['data_completeness'],
                quality_metrics['analysis_coverage'],
                quality_metrics['pattern_reliability'],
                quality_metrics['forecast_accuracy']
            ])
            
            return quality_metrics
            
        except Exception as e:
            logging.error(f"Error assessing temporal quality: {str(e)}")
            return {'overall_quality': 0.0, 'error': str(e)}
    
    def _update_temporal_cache(self, temporal_analysis: Dict[str, Any]):
        """Update temporal patterns cache."""
        try:
            # Cache key patterns
            if 'pattern_analysis' in temporal_analysis:
                pattern_analysis = temporal_analysis['pattern_analysis']
                if pattern_analysis.get('total_patterns', 0) > 0:
                    cache_key = f"patterns_{time.time()}"
                    self.pattern_cache[cache_key] = {
                        'timestamp': time.time(),
                        'patterns': pattern_analysis.get('detected_patterns', []),
                        'strength': pattern_analysis.get('pattern_strength', 0.0)
                    }
            
            # Limit cache size
            if len(self.pattern_cache) > 100:
                oldest_key = min(self.pattern_cache.keys(), 
                               key=lambda k: self.pattern_cache[k]['timestamp'])
                del self.pattern_cache[oldest_key]
                
        except Exception as e:
            logging.error(f"Error updating temporal cache: {str(e)}")
    
