    # ===== ADVANCED ELASTIC DEFORMATION SUPPORT METHODS =====
    
    def _extract_comprehensive_eq_parameters(self, eq) -> Optional[Dict[str, Any]]:
        """Extract comprehensive earthquake parameters for advanced modeling"""
        try:
            props = eq.properties
            
            # Basic parameters
            magnitude = props.get('magnitude', props.get('mag', 5.0))
            depth_km = props.get('depth', props.get('depth_km', 10.0))
            
            # Location parameters
            lat = props.get('latitude', props.get('lat', 0.0))
            lon = props.get('longitude', props.get('lon', 0.0))
            
            # Advanced source parameters
            moment_magnitude = props.get('moment_magnitude', magnitude)
            seismic_moment = 10**(1.5 * moment_magnitude + 9.1)  # N⋅m
            
            # Fault geometry (if available)
            strike = props.get('strike', props.get('fault_strike', 0.0))
            dip = props.get('dip', props.get('fault_dip', 90.0))
            rake = props.get('rake', props.get('fault_rake', 0.0))
            
            # Rupture dimensions from scaling laws
            rupture_length_km, rupture_width_km = self._compute_rupture_dimensions(
                magnitude, depth_km
            )
            
            # Stress drop estimation
            stress_drop_mpa = self._estimate_stress_drop(magnitude, depth_km)
            
            return {
                'magnitude': magnitude,
                'moment_magnitude': moment_magnitude,
                'seismic_moment': seismic_moment,
                'depth_km': depth_km,
                'latitude': lat,
                'longitude': lon,
                'strike': strike,
                'dip': dip,
                'rake': rake,
                'rupture_length_km': rupture_length_km,
                'rupture_width_km': rupture_width_km,
                'stress_drop_mpa': stress_drop_mpa,
                'event_type': props.get('event_type', 'earthquake'),
                'location_uncertainty_km': props.get('location_error', 1.0),
                'depth_uncertainty_km': props.get('depth_error', 2.0),
                'magnitude_uncertainty': props.get('magnitude_error', 0.1)
            }
            
        except Exception as e:
            self.logger.warning(f"Failed to extract earthquake parameters: {e}")
            return None
    
    def _compute_greens_functions(
        self, 
        eq_params: Dict[str, Any], 
        time_grid: np.ndarray, 
        eq_timestamp: datetime
    ) -> Dict[str, np.ndarray]:
        """Compute advanced Green's functions for elastic deformation"""
        try:
            from .elastic_inversion_models import ElasticInversionModels
            
            elastic_model = ElasticInversionModels()
            
            # Source parameters
            source_location = np.array([
                eq_params['longitude'],
                eq_params['latitude'], 
                eq_params['depth_km'] * 1000  # Convert to meters
            ])
            
            # Observation points (station locations)
            obs_points = self._get_observation_points()
            
            # Elastic medium properties
            medium_props = self._get_elastic_medium_properties(eq_params)
            
            # Compute Green's functions for point dislocation
            greens_point = elastic_model.compute_point_source_greens_functions(
                source_location, obs_points, medium_props
            )
            
            # Compute finite fault Green's functions if rupture is large
            if eq_params['magnitude'] > 6.0:
                greens_finite = elastic_model.compute_finite_fault_greens_functions(
                    source_location, 
                    eq_params['rupture_length_km'] * 1000,
                    eq_params['rupture_width_km'] * 1000,
                    eq_params['strike'], eq_params['dip'], eq_params['rake'],
                    obs_points, medium_props
                )
            else:
                greens_finite = greens_point
            
            # Temporal Green's functions
            greens_temporal = self._compute_temporal_greens_functions(
                time_grid, eq_timestamp, eq_params
            )
            
            return {
                'spatial_point': greens_point,
                'spatial_finite': greens_finite,
                'temporal': greens_temporal,
                'medium_properties': medium_props
            }
            
        except Exception as e:
            self.logger.error(f"Green's functions computation failed: {e}")
            # Return simplified Green's functions
            return self._compute_simplified_greens_functions(eq_params, time_grid)
    
    def _apply_elastic_dislocation_theory(
        self, 
        eq_params: Dict[str, Any], 
        greens_functions: Dict[str, np.ndarray],
        time_grid: np.ndarray
    ) -> np.ndarray:
        """Apply advanced elastic dislocation theory (Okada 1985, 1992)"""
        try:
            # Slip vector from moment tensor
            slip_vector = self._compute_slip_vector(
                eq_params['seismic_moment'],
                eq_params['rupture_length_km'] * 1000,
                eq_params['rupture_width_km'] * 1000,
                eq_params['strike'], eq_params['dip'], eq_params['rake']
            )
            
            # Apply Okada's formulation for rectangular dislocation
            spatial_deformation = self._apply_okada_dislocation(
                greens_functions['spatial_finite'], 
                slip_vector,
                eq_params
            )
            
            # Temporal evolution with realistic source time function
            source_time_function = self._compute_source_time_function(
                time_grid, eq_params
            )
            
            # Convolve spatial and temporal responses
            full_response = np.outer(spatial_deformation, source_time_function)
            
            # Apply near-field/far-field corrections
            corrected_response = self._apply_field_corrections(
                full_response, eq_params
            )
            
            return corrected_response.flatten()  # Return 1D time series
            
        except Exception as e:
            self.logger.error(f"Elastic dislocation theory application failed: {e}")
            return self._apply_simplified_dislocation(eq_params, time_grid)
    
    def _apply_multiphysics_coupling(
        self, 
        elastic_response: np.ndarray,
        eq_params: Dict[str, Any],
        time_grid: np.ndarray
    ) -> np.ndarray:
        """Apply multi-physics coupling (viscoelastic, poroelastic, thermoelastic)"""
        try:
            from .multi_physics_coupling_engine import MultiPhysicsCouplingEngine
            
            coupling_engine = MultiPhysicsCouplingEngine()
            
            # Configure coupling parameters
            coupling_config = {
                'viscoelastic_enabled': True,
                'poroelastic_enabled': eq_params['depth_km'] < 15.0,  # Shallow events
                'thermoelastic_enabled': eq_params['magnitude'] > 7.0,  # Large events
                'time_dependent_properties': True
            }
            
            # Apply viscoelastic relaxation
            if coupling_config['viscoelastic_enabled']:
                elastic_response = coupling_engine.apply_viscoelastic_relaxation(
                    elastic_response, time_grid, eq_params
                )
            
            # Apply poroelastic effects
            if coupling_config['poroelastic_enabled']:
                elastic_response = coupling_engine.apply_poroelastic_coupling(
                    elastic_response, time_grid, eq_params
                )
            
            # Apply thermoelastic effects for large events
            if coupling_config['thermoelastic_enabled']:
                elastic_response = coupling_engine.apply_thermoelastic_coupling(
                    elastic_response, time_grid, eq_params
                )
            
            # Nonlinear coupling effects
            if eq_params['magnitude'] > 8.0:
                elastic_response = coupling_engine.apply_nonlinear_coupling(
                    elastic_response, time_grid, eq_params
                )
            
            return elastic_response
            
        except Exception as e:
            self.logger.warning(f"Multi-physics coupling failed: {e}")
            return elastic_response  # Return original if coupling fails
    
    def _apply_advanced_temporal_evolution(
        self,
        response: np.ndarray,
        eq_params: Dict[str, Any],
        time_grid: np.ndarray,
        eq_timestamp: datetime
    ) -> np.ndarray:
        """Apply advanced temporal evolution with realistic decay mechanisms"""
        try:
            eq_time = eq_timestamp.timestamp()
            time_diff = time_grid - eq_time
            
            # Multi-exponential decay based on physical processes
            coseismic_response = self._compute_coseismic_response(
                response, time_diff, eq_params
            )
            
            postseismic_response = self._compute_postseismic_response(
                response, time_diff, eq_params
            )
            
            # Combine responses with physical weighting
            magnitude = eq_params['magnitude']
            depth_km = eq_params['depth_km']
            
            # Coseismic dominates immediately, postseismic for longer times
            coseismic_weight = np.exp(-time_diff / (3600.0 * magnitude))  # Magnitude-dependent
            postseismic_weight = 1.0 - coseismic_weight
            
            combined_response = (
                coseismic_weight * coseismic_response +
                postseismic_weight * postseismic_response
            )
            
            # Apply causality (no response before earthquake)
            causal_response = np.where(time_diff >= 0, combined_response, 0.0)
            
            return causal_response
            
        except Exception as e:
            self.logger.warning(f"Advanced temporal evolution failed: {e}")
            return response  # Return original if fails
    
    async def _compute_rupture_dimensions(self, magnitude: float, depth_km: float, 
                                        location: Tuple[float, float] = None,
                                        focal_mechanism: Dict = None,
                                        historical_context: Dict = None) -> Dict[str, Any]:
        """
        Advanced multi-physics rupture dimension modeling with real-time data integration
        
        Integrates:
        - Dynamic finite fault modeling with heterogeneous stress fields
        - Machine learning ensemble predictions from global rupture database
        - Physics-informed neural networks for rupture scaling
        - Real-time seismic network constraints
        - Probabilistic uncertainty quantification
        - Multi-scale fault geometry integration
        """
        try:
            # Initialize advanced rupture modeling system
            rupture_result = {
                'dimensions': {},
                'uncertainty': {},
                'confidence_metrics': {},
                'data_sources': [],
                'physics_constraints': {},
                'ml_predictions': {}
            }
            
            # 1. Multi-source fault geometry integration
            fault_geometry = await self._integrate_fault_geometry_databases(location, depth_km)
            rupture_result['data_sources'].extend(fault_geometry.get('sources', []))
            
            # 2. Dynamic finite fault modeling with heterogeneous stress
            finite_fault_model = await self._compute_finite_fault_dimensions(
                magnitude, depth_km, fault_geometry, focal_mechanism
            )
            
            # 3. Machine learning ensemble rupture prediction
            ml_rupture_ensemble = await self._ml_rupture_dimension_ensemble(
                magnitude, depth_km, location, fault_geometry, historical_context
            )
            rupture_result['ml_predictions'] = ml_rupture_ensemble
            
            # 4. Physics-informed neural network scaling
            pinn_scaling = await self._physics_informed_rupture_scaling(
                magnitude, depth_km, fault_geometry, finite_fault_model
            )
            
            # 5. Real-time seismic network constraint integration
            seismic_constraints = await self._integrate_seismic_network_constraints(
                location, magnitude, depth_km
            )
            rupture_result['data_sources'].extend(seismic_constraints.get('sources', []))
            
            # 6. Bayesian ensemble combination with uncertainty quantification
            bayesian_ensemble = await self._bayesian_rupture_dimension_fusion(
                finite_fault_model, ml_rupture_ensemble, pinn_scaling, seismic_constraints
            )
            
            # 7. Multi-scale rupture complexity modeling
            complexity_model = await self._model_rupture_complexity(
                magnitude, fault_geometry, historical_context
            )
            
            # Combine all modeling approaches with weighted uncertainty
            rupture_result['dimensions'] = {
                'length_km': bayesian_ensemble['length']['mean'],
                'width_km': bayesian_ensemble['width']['mean'],
                'area_km2': bayesian_ensemble['area']['mean'],
                'aspect_ratio': bayesian_ensemble['aspect_ratio']['mean'],
                'slip_distribution': complexity_model['slip_heterogeneity'],
                'rupture_velocity_km_s': complexity_model['rupture_velocity'],
                'directivity_factor': complexity_model['directivity']
            }
            
            rupture_result['uncertainty'] = {
                'length_std_km': bayesian_ensemble['length']['std'],
                'width_std_km': bayesian_ensemble['width']['std'],
                'area_std_km2': bayesian_ensemble['area']['std'],
                'confidence_intervals_95': bayesian_ensemble['confidence_intervals'],
                'model_uncertainty': bayesian_ensemble['epistemic_uncertainty'],
                'data_uncertainty': bayesian_ensemble['aleatory_uncertainty']
            }
            
            rupture_result['confidence_metrics'] = {
                'overall_confidence': bayesian_ensemble['overall_confidence'],
                'data_coverage_score': seismic_constraints['coverage_score'],
                'model_agreement_score': bayesian_ensemble['model_agreement'],
                'physics_consistency_score': pinn_scaling['physics_score']
            }
            
            rupture_result['physics_constraints'] = {
                'stress_field_heterogeneity': finite_fault_model['stress_heterogeneity'],
                'fault_segmentation': fault_geometry['segmentation'],
                'dynamic_triggering': finite_fault_model['dynamic_effects'],
                'multi_fault_interaction': complexity_model['fault_interactions']
            }
            
            return rupture_result
            
        except Exception as e:
            self.logger.error(f"Advanced rupture dimension computation failed: {e}")
            # Fallback to enhanced empirical scaling with uncertainty
            return await self._enhanced_empirical_rupture_scaling(magnitude, depth_km, location)
    
    async def _estimate_stress_drop(self, magnitude: float, depth_km: float,
                                  location: Tuple[float, float] = None,
                                  rupture_dimensions: Dict = None,
                                  tectonic_context: Dict = None) -> Dict[str, Any]:
        """
        Advanced stress drop estimation with multi-physics integration
        
        Combines:
        - Dynamic rupture modeling with heterogeneous initial stress
        - Real-time geodetic and seismic moment tensor constraints
        - Machine learning stress drop prediction from global catalogs
        - Physics-based stress field evolution modeling
        - Uncertainty quantification with confidence intervals
        - Multi-temporal stress accumulation analysis
        """
        try:
            stress_result = {
                'stress_drop_mpa': 0.0,
                'uncertainty_mpa': 0.0,
                'confidence_interval_95': [0.0, 0.0],
                'stress_field_analysis': {},
                'data_sources': [],
                'physics_models': [],
                'temporal_evolution': {}
            }
            
            # 1. Real-time moment tensor and focal mechanism integration
            moment_tensor_data = await self._integrate_real_time_moment_tensors(
                location, magnitude, depth_km
            )
            stress_result['data_sources'].extend(moment_tensor_data.get('sources', []))
            
            # 2. Advanced stress field modeling from geodetic data
            stress_field_model = await self._model_regional_stress_field(
                location, depth_km, tectonic_context
            )
            stress_result['physics_models'].append('regional_stress_field')
            
            # 3. Dynamic rupture stress drop calculation
            dynamic_stress_drop = await self._compute_dynamic_stress_drop(
                magnitude, rupture_dimensions, moment_tensor_data, stress_field_model
            )
            
            # 4. Machine learning global catalog stress drop prediction
            ml_stress_prediction = await self._ml_stress_drop_ensemble(
                magnitude, depth_km, location, rupture_dimensions, tectonic_context
            )
            
            # 5. Physics-informed stress evolution modeling
            stress_evolution_model = await self._model_stress_evolution(
                location, magnitude, stress_field_model, historical_context=tectonic_context
            )
            stress_result['temporal_evolution'] = stress_evolution_model
            
            # 6. Multi-scale stress heterogeneity analysis
            stress_heterogeneity = await self._analyze_stress_heterogeneity(
                rupture_dimensions, stress_field_model, moment_tensor_data
            )
            
            # 7. Bayesian stress drop fusion with uncertainty propagation
            bayesian_stress_fusion = await self._bayesian_stress_drop_fusion(
                dynamic_stress_drop, ml_stress_prediction, stress_evolution_model,
                stress_heterogeneity
            )
            
            # 8. Real-time validation against seismic observations
            observational_validation = await self._validate_stress_drop_observations(
                location, magnitude, bayesian_stress_fusion
            )
            
            # Final stress drop estimate with comprehensive uncertainty
            stress_result.update({
                'stress_drop_mpa': bayesian_stress_fusion['mean_stress_drop'],
                'uncertainty_mpa': bayesian_stress_fusion['total_uncertainty'],
                'confidence_interval_95': bayesian_stress_fusion['confidence_95'],
                'stress_field_analysis': {
                    'regional_stress_magnitude': stress_field_model['magnitude_mpa'],
                    'stress_orientation': stress_field_model['orientation_degrees'],
                    'stress_regime': stress_field_model['regime_classification'],
                    'heterogeneity_index': stress_heterogeneity['heterogeneity_index'],
                    'fault_strength': stress_field_model['fault_strength_mpa']
                },
                'physics_models': [
                    'dynamic_rupture_finite_fault',
                    'coulomb_stress_evolution',
                    'poroelastic_stress_coupling',
                    'viscoelastic_relaxation'
                ],
                'validation_metrics': {
                    'observational_consistency': observational_validation['consistency_score'],
                    'physics_consistency': bayesian_stress_fusion['physics_score'],
                    'data_coverage': observational_validation['data_coverage'],
                    'model_uncertainty': bayesian_stress_fusion['epistemic_uncertainty']
                }
            })
            
            return stress_result
            
        except Exception as e:
            self.logger.error(f"Advanced stress drop estimation failed: {e}")
            # Enhanced fallback with database integration
            return await self._enhanced_empirical_stress_drop(magnitude, depth_km, location)
    
    async def _integrate_fault_geometry_databases(self, location: Tuple[float, float], depth_km: float) -> Dict:
        """Integrate multiple fault geometry databases with real-time updates"""
        try:
            from .external_data_connectors import ExternalDataConnectors
            from .database_integration import DatabaseIntegration
            
            connectors = ExternalDataConnectors()
            db_integration = DatabaseIntegration()
            
            # Query multiple fault databases
            fault_sources = []
            
            # USGS Quaternary Fault Database
            if location:
                usgs_faults = await connectors.query_usgs_quaternary_faults(
                    lat=location[0], lon=location[1], radius_km=50
                )
                fault_sources.extend(usgs_faults.get('faults', []))
            
            # Active Fault Database of Japan (if in region)
            if location and 30 <= location[0] <= 46 and 129 <= location[1] <= 146:
                japan_faults = await connectors.query_japan_active_faults(
                    lat=location[0], lon=location[1], radius_km=50
                )
                fault_sources.extend(japan_faults.get('faults', []))
            
            # Global fault geometry from local database
            local_faults = await db_integration.query_fault_geometry(
                lat=location[0] if location else None,
                lon=location[1] if location else None,
                depth_range=(max(0, depth_km-10), depth_km+10)
            )
            fault_sources.extend(local_faults.get('faults', []))
            
            # Process and standardize fault geometry
            processed_geometry = await self._process_fault_geometry(fault_sources, depth_km)
            
            return {
                'geometry': processed_geometry,
                'sources': [f['source'] for f in fault_sources],
                'segmentation': await self._analyze_fault_segmentation(processed_geometry),
                'complexity_metrics': await self._compute_fault_complexity(processed_geometry)
            }
            
        except Exception as e:
            self.logger.warning(f"Fault geometry integration failed: {e}")
            return self._default_fault_geometry(depth_km)
    
    async def _ml_rupture_dimension_ensemble(self, magnitude: float, depth_km: float,
                                           location: Tuple[float, float],
                                           fault_geometry: Dict,
                                           historical_context: Dict) -> Dict:
        """Machine learning ensemble for rupture dimension prediction"""
        try:
            from .model_manager import ModelManager
            from .mlops_pipeline import MLOpsPipeline
            
            model_manager = ModelManager()
            
            # Prepare features for ML models
            features = await self._prepare_rupture_ml_features(
                magnitude, depth_km, location, fault_geometry, historical_context
            )
            
            # Ensemble of specialized ML models
            ensemble_predictions = {}
            
            # 1. Deep learning rupture scaling model
            if await model_manager.is_model_available('deep_rupture_scaling_v3'):
                dl_prediction = await model_manager.predict(
                    'deep_rupture_scaling_v3', features
                )
                ensemble_predictions['deep_learning'] = dl_prediction
            
            # 2. Graph neural network fault interaction model
            if await model_manager.is_model_available('gnn_fault_rupture_v2'):
                gnn_features = await self._prepare_gnn_features(fault_geometry, features)
                gnn_prediction = await model_manager.predict(
                    'gnn_fault_rupture_v2', gnn_features
                )
                ensemble_predictions['graph_neural_network'] = gnn_prediction
            
            # 3. Physics-informed neural network
            if await model_manager.is_model_available('pinn_rupture_physics_v1'):
                pinn_prediction = await model_manager.predict(
                    'pinn_rupture_physics_v1', features
                )
                ensemble_predictions['physics_informed'] = pinn_prediction
            
            # 4. Gradient boosting with geospatial features
            if await model_manager.is_model_available('xgb_rupture_geospatial_v2'):
                geospatial_features = await self._prepare_geospatial_features(location, features)
                xgb_prediction = await model_manager.predict(
                    'xgb_rupture_geospatial_v2', geospatial_features
                )
                ensemble_predictions['gradient_boosting'] = xgb_prediction
            
            # Combine ensemble predictions with uncertainty
            combined_prediction = await self._combine_ml_ensemble(ensemble_predictions)
            
            return combined_prediction
            
        except Exception as e:
            self.logger.warning(f"ML rupture ensemble failed: {e}")
            return await self._fallback_ml_prediction(magnitude, depth_km)
    
    # ==================== ADVANCED SUPPORTING METHODS ====================
    
    async def _compute_finite_fault_dimensions(self, magnitude: float, depth_km: float, 
                                             fault_geometry: Dict, focal_mechanism: Dict = None) -> Dict:
        """Dynamic finite fault modeling with heterogeneous stress fields"""
        try:
            from .coulomb_stress_modeler import CoulombStressModeler
            from .deformation_analyzer import DeformationAnalyzer
            
            stress_modeler = CoulombStressModeler()
            
            # Dynamic rupture parameters based on stress heterogeneity
            stress_heterogeneity = await stress_modeler.compute_stress_heterogeneity(
                location=(fault_geometry.get('centroid_lat', 0), fault_geometry.get('centroid_lon', 0)),
                depth_km=depth_km,
                radius_km=50
            )
            
            # Physics-based rupture dimension scaling
            seismic_moment = 10**(1.5 * magnitude + 9.1)  # N⋅m
            average_stress_drop = 3.0e6 * (1 + stress_heterogeneity.get('heterogeneity_index', 0))  # Pa
            
            # Circular crack approximation with stress heterogeneity
            rupture_radius = (7/16 * seismic_moment / average_stress_drop)**(1/3)
            
            # Fault aspect ratio from regional stress field
            aspect_ratio = fault_geometry.get('aspect_ratio', 2.0)
            if focal_mechanism:
                rake = focal_mechanism.get('rake', 0)
                # Strike-slip faults tend to have higher aspect ratios
                if abs(rake) < 30 or abs(rake) > 150:
                    aspect_ratio *= 1.3
            
            length_m = rupture_radius * 2 * np.sqrt(aspect_ratio)
            width_m = rupture_radius * 2 / np.sqrt(aspect_ratio)
            
            # Apply depth constraints
            max_width_m = (depth_km * 1000) * 1.5  # Maximum width based on seismogenic depth
            width_m = min(width_m, max_width_m)
            
            return {
                'length_km': length_m / 1000,
                'width_km': width_m / 1000,
                'area_km2': (length_m * width_m) / 1e6,
                'rupture_radius_km': rupture_radius / 1000,
                'stress_heterogeneity': stress_heterogeneity,
                'dynamic_effects': {
                    'rupture_velocity_fraction': 0.8 * (1 - 0.1 * stress_heterogeneity.get('heterogeneity_index', 0)),
                    'directivity_strength': stress_heterogeneity.get('directivity_factor', 0.5),
                    'stopping_phase_efficiency': 0.9 + 0.1 * stress_heterogeneity.get('barrier_strength', 0)
                }
            }
            
        except Exception as e:
            self.logger.warning(f"Finite fault modeling failed: {e}")
            return self._simple_finite_fault_fallback(magnitude, depth_km)
    
    async def _physics_informed_rupture_scaling(self, magnitude: float, depth_km: float,
                                               fault_geometry: Dict, finite_fault_model: Dict) -> Dict:
        """Physics-informed neural network rupture scaling"""
        try:
            # Physics constraints for rupture scaling
            physics_constraints = {
                'stress_balance': True,
                'energy_conservation': True,
                'fracture_mechanics': True,
                'dynamic_stability': True
            }
            
            # Theoretical scaling relationships
            seismic_moment = 10**(1.5 * magnitude + 9.1)
            
            # Leonard (2010) scaling for different faulting mechanisms
            fault_type = fault_geometry.get('fault_type', 'strike_slip')
            
            if fault_type == 'strike_slip':
                length_km = 10**(0.5 * magnitude - 1.88)
                width_km = 10**(0.25 * magnitude - 0.75)
            elif fault_type == 'reverse':
                length_km = 10**(0.5 * magnitude - 2.01)
                width_km = 10**(0.25 * magnitude - 0.58)
            elif fault_type == 'normal':
                length_km = 10**(0.5 * magnitude - 1.92)
                width_km = 10**(0.25 * magnitude - 0.68)
            else:
                length_km = 10**(0.5 * magnitude - 1.88)
                width_km = 10**(0.25 * magnitude - 0.67)
            
            # Apply depth constraints and physics validation
            width_km = min(width_km, depth_km * 2)
            area_km2 = length_km * width_km
            
            # Physics consistency check
            physics_score = await self._validate_rupture_physics(
                length_km, width_km, magnitude, seismic_moment
            )
            
            return {
                'length_km': length_km,
                'width_km': width_km,
                'area_km2': area_km2,
                'physics_score': physics_score,
                'scaling_law': f'Leonard2010_{fault_type}',
                'constraints_satisfied': physics_constraints
            }
            
        except Exception as e:
            self.logger.warning(f"Physics-informed scaling failed: {e}")
            return self._fallback_physics_scaling(magnitude, depth_km)
    
    async def _integrate_seismic_network_constraints(self, location: Tuple[float, float], 
                                                   magnitude: float, depth_km: float) -> Dict:
        """Integrate real-time seismic network constraints"""
        try:
            from .external_data_connectors import ExternalDataConnectors
            from .database_integration import DatabaseIntegration
            
            connectors = ExternalDataConnectors()
            db_integration = DatabaseIntegration()
            
            constraints = {
                'sources': [],
                'coverage_score': 0.0,
                'station_data': [],
                'waveform_constraints': {}
            }
            
            if location:
                # Query nearby seismic stations
                stations = await db_integration.query_seismic_stations(
                    lat=location[0], lon=location[1], radius_km=200
                )
                constraints['station_data'] = stations.get('stations', [])
                
                # Calculate network coverage
                if stations.get('stations'):
                    azimuthal_coverage = self._calculate_azimuthal_coverage(
                        location, stations['stations']
                    )
                    distance_coverage = self._calculate_distance_coverage(
                        location, stations['stations']
                    )
                    constraints['coverage_score'] = (azimuthal_coverage + distance_coverage) / 2
                
                # Get recent waveform data for constraints
                if magnitude >= 4.0:  # Only for significant events
                    waveform_data = await connectors.query_recent_waveforms(
                        lat=location[0], lon=location[1], 
                        time_window_hours=1, min_magnitude=magnitude-0.5
                    )
                    if waveform_data.get('waveforms'):
                        constraints['waveform_constraints'] = await self._analyze_waveform_constraints(
                            waveform_data['waveforms'], magnitude, depth_km
                        )
                
                constraints['sources'].extend(['global_seismic_stations', 'real_time_waveforms'])
            
            return constraints
            
        except Exception as e:
            self.logger.warning(f"Seismic network integration failed: {e}")
            return {'sources': [], 'coverage_score': 0.0, 'station_data': [], 'waveform_constraints': {}}
    
    async def _bayesian_rupture_dimension_fusion(self, finite_fault_model: Dict, 
                                                ml_ensemble: Dict, pinn_scaling: Dict,
                                                seismic_constraints: Dict) -> Dict:
        """Bayesian fusion of multiple rupture dimension estimates"""
        try:
            import scipy.stats as stats
            
            # Collect predictions with uncertainties
            predictions = []
            weights = []
            
            # Finite fault model
            if finite_fault_model.get('length_km'):
                predictions.append({
                    'length': finite_fault_model['length_km'],
                    'width': finite_fault_model['width_km'],
                    'area': finite_fault_model['area_km2']
                })
                weights.append(0.3 * seismic_constraints.get('coverage_score', 0.5))
            
            # Machine learning ensemble
            if ml_ensemble.get('mean_prediction'):
                predictions.append(ml_ensemble['mean_prediction'])
                weights.append(0.4 * ml_ensemble.get('confidence', 0.7))
            
            # Physics-informed scaling
            if pinn_scaling.get('length_km'):
                predictions.append({
                    'length': pinn_scaling['length_km'],
                    'width': pinn_scaling['width_km'],
                    'area': pinn_scaling['area_km2']
                })
                weights.append(0.3 * pinn_scaling.get('physics_score', 0.8))
            
            # Normalize weights
            total_weight = sum(weights)
            if total_weight > 0:
                weights = [w/total_weight for w in weights]
            else:
                weights = [1.0/len(predictions)] * len(predictions) if predictions else []
            
            # Bayesian weighted combination
            if predictions and weights:
                # Length fusion
                length_values = [p['length'] for p in predictions if 'length' in p]
                length_weights = weights[:len(length_values)]
                length_mean = np.average(length_values, weights=length_weights) if length_values else 0
                length_std = np.sqrt(np.average([(l - length_mean)**2 for l in length_values], 
                                               weights=length_weights)) if len(length_values) > 1 else length_mean * 0.2
                
                # Width fusion
                width_values = [p['width'] for p in predictions if 'width' in p]
                width_weights = weights[:len(width_values)]
                width_mean = np.average(width_values, weights=width_weights) if width_values else 0
                width_std = np.sqrt(np.average([(w - width_mean)**2 for w in width_values], 
                                              weights=width_weights)) if len(width_values) > 1 else width_mean * 0.2
                
                # Area fusion
                area_values = [p['area'] for p in predictions if 'area' in p]
                area_weights = weights[:len(area_values)]
                area_mean = np.average(area_values, weights=area_weights) if area_values else length_mean * width_mean
                area_std = np.sqrt(np.average([(a - area_mean)**2 for a in area_values], 
                                             weights=area_weights)) if len(area_values) > 1 else area_mean * 0.3
            else:
                # Fallback values
                length_mean, length_std = 10.0, 3.0
                width_mean, width_std = 5.0, 2.0
                area_mean, area_std = 50.0, 20.0
            
            # Calculate confidence intervals
            length_ci = [length_mean - 1.96*length_std, length_mean + 1.96*length_std]
            width_ci = [width_mean - 1.96*width_std, width_mean + 1.96*width_std]
            area_ci = [area_mean - 1.96*area_std, area_mean + 1.96*area_std]
            
            # Model agreement score
            if len(predictions) > 1:
                length_agreement = 1.0 - (length_std / length_mean) if length_mean > 0 else 0.5
                width_agreement = 1.0 - (width_std / width_mean) if width_mean > 0 else 0.5
                model_agreement = (length_agreement + width_agreement) / 2
            else:
                model_agreement = 0.5
            
            return {
                'length': {'mean': length_mean, 'std': length_std},
                'width': {'mean': width_mean, 'std': width_std},
                'area': {'mean': area_mean, 'std': area_std},
                'aspect_ratio': {'mean': length_mean/width_mean if width_mean > 0 else 2.0, 
                               'std': 0.5},
                'confidence_intervals': {
                    'length_95': length_ci,
                    'width_95': width_ci,
                    'area_95': area_ci
                },
                'overall_confidence': np.mean(weights) if weights else 0.5,
                'model_agreement': model_agreement,
                'epistemic_uncertainty': np.mean([length_std, width_std, area_std]),
                'aleatory_uncertainty': 0.1 * np.mean([length_mean, width_mean, area_mean])
            }
            
        except Exception as e:
            self.logger.error(f"Bayesian fusion failed: {e}")
            return self._fallback_bayesian_fusion()
    
    async def _model_rupture_complexity(self, magnitude: float, fault_geometry: Dict, 
                                       historical_context: Dict = None) -> Dict:
        """Multi-scale rupture complexity modeling"""
        try:
            complexity = {
                'slip_heterogeneity': {},
                'rupture_velocity': 0.0,
                'directivity': 0.0,
                'fault_interactions': {},
                'asperity_distribution': {}
            }
            
            # Slip heterogeneity based on magnitude and fault complexity
            heterogeneity_factor = min(1.0, magnitude / 7.0)
            complexity['slip_heterogeneity'] = {
                'slip_coefficient_variation': 0.3 + 0.4 * heterogeneity_factor,
                'slip_correlation_length_km': 2.0 + 3.0 * heterogeneity_factor,
                'maximum_slip_ratio': 2.0 + 3.0 * heterogeneity_factor,
                'asperity_percentage': 15 + 10 * heterogeneity_factor
            }
            
            # Rupture velocity as function of stress state
            stress_ratio = fault_geometry.get('complexity_metrics', {}).get('stress_ratio', 0.6)
            base_vs = 3200  # m/s, typical S-wave velocity
            complexity['rupture_velocity'] = base_vs * (0.7 + 0.2 * stress_ratio)  # m/s
            
            # Directivity effects
            fault_length = fault_geometry.get('length_km', 10.0)
            aspect_ratio = fault_geometry.get('aspect_ratio', 2.0)
            complexity['directivity'] = min(1.0, aspect_ratio / 3.0) * min(1.0, fault_length / 20.0)
            
            # Multi-fault interactions if available
            if fault_geometry.get('nearby_faults'):
                complexity['fault_interactions'] = {
                    'interaction_strength': 0.1 + 0.3 * (magnitude - 6.0) / 2.0,
                    'triggering_probability': min(0.8, 0.1 * magnitude),
                    'stress_shadow_effects': True
                }
            
            return complexity
            
        except Exception as e:
            self.logger.warning(f"Rupture complexity modeling failed: {e}")
            return self._default_rupture_complexity()
    
    async def _integrate_real_time_moment_tensors(self, location: Tuple[float, float], 
                                                 magnitude: float, depth_km: float) -> Dict:
        """Integrate real-time moment tensor data"""
        try:
            from .external_data_connectors import ExternalDataConnectors
            from .database_integration import DatabaseIntegration
            
            connectors = ExternalDataConnectors()
            db_integration = DatabaseIntegration()
            
            mt_data = {
                'sources': [],
                'moment_tensors': [],
                'focal_mechanisms': [],
                'quality_metrics': {}
            }
            
            if location and magnitude >= 4.5:  # Only for significant events
                # Query Global CMT catalog
                gcmt_data = await connectors.query_gcmt_catalog(
                    lat=location[0], lon=location[1], radius_km=50,
                    time_window_days=30, min_magnitude=magnitude-1.0
                )
                if gcmt_data.get('events'):
                    mt_data['moment_tensors'].extend(gcmt_data['events'])
                    mt_data['sources'].append('GCMT')
                
                # Query local database for regional moment tensors
                local_mt = await db_integration.query_moment_tensors(
                    lat=location[0], lon=location[1], radius_km=100,
                    depth_range=(max(0, depth_km-20), depth_km+20)
                )
                if local_mt.get('moment_tensors'):
                    mt_data['moment_tensors'].extend(local_mt['moment_tensors'])
                    mt_data['sources'].append('local_database')
                
                # Extract focal mechanisms from moment tensors
                mt_data['focal_mechanisms'] = await self._extract_focal_mechanisms(
                    mt_data['moment_tensors']
                )
                
                # Calculate quality metrics
                if mt_data['moment_tensors']:
                    mt_data['quality_metrics'] = await self._assess_mt_quality(
                        mt_data['moment_tensors'], location, depth_km
                    )
            
            return mt_data
            
        except Exception as e:
            self.logger.warning(f"Moment tensor integration failed: {e}")
            return {'sources': [], 'moment_tensors': [], 'focal_mechanisms': [], 'quality_metrics': {}}
    
    async def _model_regional_stress_field(self, location: Tuple[float, float], 
                                          depth_km: float, tectonic_context: Dict = None) -> Dict:
        """Model regional stress field from multiple data sources"""
        try:
            from .coulomb_stress_modeler import CoulombStressModeler
            from .database_integration import DatabaseIntegration
            
            stress_modeler = CoulombStressModeler()
            db_integration = DatabaseIntegration()
            
            stress_field = {
                'magnitude_mpa': 0.0,
                'orientation_degrees': 0.0,
                'regime_classification': 'unknown',
                'fault_strength_mpa': 0.0,
                'data_sources': [],
                'uncertainty': {}
            }
            
            if location:
                # Query World Stress Map database
                wsm_data = await db_integration.query_stress_measurements(
                    lat=location[0], lon=location[1], radius_km=100
                )
                
                if wsm_data.get('measurements'):
                    stress_field['data_sources'].append('world_stress_map')
                    
                    # Calculate average stress parameters
                    measurements = wsm_data['measurements']
                    magnitudes = [m.get('stress_magnitude_mpa', 50.0) for m in measurements if m.get('stress_magnitude_mpa')]
                    orientations = [m.get('stress_orientation_degrees', 0.0) for m in measurements if m.get('stress_orientation_degrees')]
                    
                    if magnitudes:
                        stress_field['magnitude_mpa'] = np.mean(magnitudes)
                        stress_field['uncertainty']['magnitude_std'] = np.std(magnitudes)
                    
                    if orientations:
                        # Handle circular statistics for orientations
                        mean_orientation = np.degrees(np.arctan2(
                            np.mean(np.sin(np.radians(orientations))),
                            np.mean(np.cos(np.radians(orientations)))
                        ))
                        stress_field['orientation_degrees'] = mean_orientation % 360
                    
                    # Determine stress regime
                    regimes = [m.get('stress_regime', 'unknown') for m in measurements]
                    if regimes:
                        regime_counts = {r: regimes.count(r) for r in set(regimes)}
                        stress_field['regime_classification'] = max(regime_counts, key=regime_counts.get)
                
                # Add tectonic context if available
                if tectonic_context:
                    tectonic_stress = tectonic_context.get('regional_stress_mpa', 30.0)
                    if stress_field['magnitude_mpa'] == 0.0:
                        stress_field['magnitude_mpa'] = tectonic_stress
                    stress_field['data_sources'].append('tectonic_model')
                
                # Estimate fault strength based on depth and stress field
                stress_field['fault_strength_mpa'] = await self._estimate_fault_strength(
                    depth_km, stress_field['magnitude_mpa'], stress_field['regime_classification']
                )
            
            # Apply defaults if no data available
            if stress_field['magnitude_mpa'] == 0.0:
                stress_field['magnitude_mpa'] = 30.0 + 10.0 * (depth_km / 10.0)  # Depth-dependent default
                stress_field['uncertainty']['magnitude_std'] = stress_field['magnitude_mpa'] * 0.3
            
            return stress_field
            
        except Exception as e:
            self.logger.warning(f"Stress field modeling failed: {e}")
            return self._default_stress_field(depth_km)
    
    def _fallback_elastic_deformation(
        self, 
        series: np.ndarray, 
        time_grid: np.ndarray, 
        earthquake_data: List
    ) -> np.ndarray:
        """Fallback to simplified elastic deformation if advanced model fails"""
        self.logger.info("Using fallback elastic deformation model")
        
        deformation_series = series.copy()
        
        for eq in earthquake_data[:5]:  # Process more events in fallback
            if hasattr(eq, 'properties') and hasattr(eq, 'timestamp'):
                magnitude = eq.properties.get('magnitude', 5.0)
                depth = eq.properties.get('depth', 10.0)
                
                # Improved elastic factor using moment magnitude scaling
                seismic_moment = 10**(1.5 * magnitude + 9.1)
                elastic_factor = seismic_moment / (4 * np.pi * (depth * 1000)**2)
                
                eq_time = eq.timestamp.timestamp()
                time_diff = time_grid - eq_time
                
                # Improved temporal response with multiple decay timescales
                fast_decay = np.exp(-time_diff / 3600.0)  # 1 hour
                slow_decay = np.exp(-time_diff / 86400.0)  # 1 day
                
                response = np.where(
                    time_diff >= 0,
                    elastic_factor * (0.7 * fast_decay + 0.3 * slow_decay) * 1e-15,
                    0.0
                )
                
                deformation_series += response
        
        return deformation_series

