    async def _fuse_displacement_datasets(
        self, 
        datasets: List[Dict[str, Any]], 
        interpolator, 
        start_time: datetime, 
        end_time: datetime
    ) -> np.ndarray:
        """Advanced data fusion using Kalman filtering and spatio-temporal interpolation"""
        try:
            from .enhanced_kalman_filter import EnhancedKalmanFilter
            
            # Initialize enhanced Kalman filter for data fusion
            kalman = EnhancedKalmanFilter()
            
            # Prepare datasets for fusion
            processed_datasets = []
            for dataset in datasets:
                processed_data = interpolator.process_displacement_dataset(
                    dataset['data'], 
                    quality_weight=self._get_quality_weight(dataset['quality']),
                    temporal_bounds=(start_time, end_time)
                )
                processed_datasets.append(processed_data)
            
            # Multi-sensor fusion with uncertainty quantification
            fused_data = kalman.fuse_multisensor_displacement_data(
                processed_datasets,
                fusion_method='adaptive_weighted',
                uncertainty_propagation=True
            )
            
            # Apply spatio-temporal smoothing
            smoothed_data = interpolator.apply_spatiotemporal_smoothing(
                fused_data,
                smoothing_kernel='adaptive_gaussian',
                preserve_discontinuities=True
            )
            
            return smoothed_data
            
        except Exception as e:
            self.logger.error(f"Displacement dataset fusion failed: {e}")
            # Return simple average if fusion fails
            return self._simple_dataset_average(datasets)
    
    def _validate_displacement_data(
        self, 
        displacement_data: np.ndarray, 
        earthquake_data: List
    ) -> np.ndarray:
        """Comprehensive displacement data validation with physical constraints"""
        try:
            from .advanced_error_handling_validation import DisplacementValidator
            
            validator = DisplacementValidator()
            
            # Physical constraint validation
            validated_data = validator.validate_physical_constraints(
                displacement_data,
                max_displacement_m=10.0,  # 10m maximum reasonable displacement
                max_velocity_m_s=0.1,    # 10cm/s maximum velocity
                causality_check=True
            )
            
            # Statistical outlier detection
            outlier_free_data = validator.detect_and_remove_outliers(
                validated_data,
                method='modified_z_score',
                threshold=3.5
            )
            
            # Temporal consistency validation
            consistent_data = validator.validate_temporal_consistency(
                outlier_free_data,
                earthquake_data,
                consistency_threshold=0.95
            )
            
            # Quality scoring
            quality_scores = validator.compute_quality_scores(consistent_data)
            
            # Apply quality-based filtering
            filtered_data = validator.apply_quality_filtering(
                consistent_data, 
                quality_scores,
                min_quality_score=0.7
            )
            
            return filtered_data
            
        except Exception as e:
            self.logger.warning(f"Displacement data validation failed: {e}")
            return displacement_data  # Return original if validation fails
    
