    def _get_elastic_medium_properties(self, eq_params: Dict[str, Any]) -> Dict[str, Any]:
        """Get elastic medium properties for the analysis region"""
        try:
            from .geological_constraints import GeologicalConstraints
            
            geo_constraints = GeologicalConstraints()
            
            # Get regional crustal properties
            crustal_properties = geo_constraints.get_regional_crustal_properties(
                lat=eq_params['latitude'],
                lon=eq_params['longitude'],
                depth_km=eq_params['depth_km']
            )
            
            # Standard elastic constants for the region
            properties = {
                'density': crustal_properties.get('density', 2700.0),  # kg/m³
                'vp': crustal_properties.get('p_velocity', 6000.0),   # m/s
                'vs': crustal_properties.get('s_velocity', 3500.0),   # m/s
                'poisson_ratio': crustal_properties.get('poisson_ratio', 0.25),
                'shear_modulus': None,  # Will be computed
                'bulk_modulus': None,   # Will be computed
                'layered_medium': crustal_properties.get('layered', True),
                'attenuation_qp': crustal_properties.get('qp', 1000.0),
                'attenuation_qs': crustal_properties.get('qs', 600.0)
            }
            
            # Compute derived elastic constants
            density = properties['density']
            vp, vs = properties['vp'], properties['vs']
            
            # Shear modulus
            properties['shear_modulus'] = density * vs**2
            
            # Bulk modulus  
            properties['bulk_modulus'] = density * (vp**2 - (4/3) * vs**2)
            
            # Lame parameters
            properties['lame_lambda'] = properties['bulk_modulus'] - (2/3) * properties['shear_modulus']
            properties['lame_mu'] = properties['shear_modulus']
            
            return properties
            
        except Exception as e:
            self.logger.warning(f"Failed to get elastic medium properties: {e}")
            return self._get_default_elastic_properties()
    
    def _compute_temporal_greens_functions(
        self, 
        time_grid: np.ndarray, 
        eq_timestamp: datetime, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Compute temporal Green's functions for realistic source time function"""
        try:
            eq_time = eq_timestamp.timestamp()
            time_diff = time_grid - eq_time
            
            # Source time function based on magnitude
            magnitude = eq_params['magnitude']
            
            # Characteristic rupture duration (Somerville et al., 1999)
            if magnitude < 6.0:
                rupture_duration = 0.5 * 10**(0.5 * magnitude - 2.5)  # seconds
            else:
                rupture_duration = 2.0 * 10**(0.5 * magnitude - 3.0)  # seconds
            
            # Gaussian source time function
            source_time_function = np.where(
                time_diff >= 0,
                np.exp(-0.5 * (time_diff / rupture_duration)**2) / (rupture_duration * np.sqrt(2 * np.pi)),
                0.0
            )
            
            # Normalize
            if np.sum(source_time_function) > 0:
                source_time_function /= np.sum(source_time_function)
            
            return source_time_function
            
        except Exception as e:
            self.logger.warning(f"Temporal Green's functions computation failed: {e}")
            return np.ones_like(time_grid)
    
    def _compute_slip_vector(
        self, 
        seismic_moment: float, 
        length: float, 
        width: float, 
        strike: float, 
        dip: float, 
        rake: float
    ) -> np.ndarray:
        """Compute slip vector from fault geometry and moment"""
        try:
            # Average slip from moment (Hanks & Kanamori, 1979)
            fault_area = length * width  # m²
            shear_modulus = 30e9  # Pa (typical crustal value)
            
            average_slip = seismic_moment / (shear_modulus * fault_area)
            
            # Slip vector components in fault coordinate system
            slip_strike = average_slip * np.cos(np.radians(rake))
            slip_dip = average_slip * np.sin(np.radians(rake))
            
            return np.array([slip_strike, slip_dip, 0.0])
            
        except Exception as e:
            self.logger.warning(f"Slip vector computation failed: {e}")
            return np.array([1.0, 0.0, 0.0])  # Default to strike-slip
    
    def _apply_okada_dislocation(
        self, 
        greens_functions: Dict[str, np.ndarray], 
        slip_vector: np.ndarray, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Apply Okada's rectangular dislocation model"""
        try:
            # This would typically call the full Okada formulation
            # For now, return a simplified response based on Green's functions
            if 'displacement' in greens_functions:
                spatial_response = greens_functions['displacement'] @ slip_vector
            else:
                # Fallback to simple scaling
                magnitude = eq_params['magnitude']
                spatial_response = np.ones(100) * (10**(magnitude - 5)) * 1e-3  # mm
            
            return spatial_response
            
        except Exception as e:
            self.logger.warning(f"Okada dislocation application failed: {e}")
            return np.ones(100) * 1e-3  # 1mm default response
    
    def _compute_source_time_function(
        self, 
        time_grid: np.ndarray, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Compute realistic source time function"""
        try:
            magnitude = eq_params['magnitude']
            rupture_duration = 2.0 * 10**(0.5 * magnitude - 3.0)  # seconds
            
            # Brune source model
            corner_frequency = 4.9e6 * eq_params['vs'] * (eq_params['stress_drop_mpa'] / eq_params['seismic_moment'])**(1/3)
            
            # Time function
            time_function = np.exp(-time_grid * corner_frequency) * np.heaviside(time_grid, 1)
            
            return time_function / np.sum(time_function) if np.sum(time_function) > 0 else time_function
            
        except Exception as e:
            self.logger.warning(f"Source time function computation failed: {e}")
            return np.ones_like(time_grid)
    
    def _apply_field_corrections(
        self, 
        response: np.ndarray, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Apply near-field and far-field corrections"""
        try:
            # Distance-dependent corrections would be applied here
            # For now, return response with basic scaling
            depth_factor = 1.0 / (1.0 + eq_params['depth_km'] / 10.0)
            return response * depth_factor
            
        except Exception as e:
            self.logger.warning(f"Field corrections failed: {e}")
            return response
    
    def _compute_coseismic_response(
        self, 
        response: np.ndarray, 
        time_diff: np.ndarray, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Compute coseismic response with step function"""
        magnitude = eq_params['magnitude']
        response_duration = 60.0 * magnitude  # Magnitude-dependent duration
        
        return response * np.where(
            (time_diff >= 0) & (time_diff <= response_duration),
            1.0,
            0.0
        )
    
    def _compute_postseismic_response(
        self, 
        response: np.ndarray, 
        time_diff: np.ndarray, 
        eq_params: Dict[str, Any]
    ) -> np.ndarray:
        """Compute postseismic response with logarithmic decay"""
        magnitude = eq_params['magnitude']
        decay_time = 86400.0 * (magnitude - 4.0)  # Days to seconds
        
        return response * np.where(
            time_diff > 0,
            np.log(1 + time_diff / decay_time) / np.log(1 + 86400.0 / decay_time),
            0.0
        )
    
    def _compute_observation_scaling(self, eq_params: Dict[str, Any]) -> float:
        """Compute scaling factor for observations"""
        try:
            # Distance-based scaling (simplified)
            magnitude = eq_params['magnitude']
            depth_km = eq_params['depth_km']
            
            # Empirical scaling based on moment magnitude
            scaling = 10**(magnitude - 6.0) * (10.0 / (depth_km + 1.0))
            
            return min(scaling, 1.0)  # Cap at 1.0
            
        except Exception as e:
            self.logger.warning(f"Observation scaling computation failed: {e}")
            return 0.1
    
    def _apply_postprocessing_corrections(
        self, 
        deformation_series: np.ndarray, 
        earthquake_data: List, 
        time_grid: np.ndarray
    ) -> np.ndarray:
        """Apply final post-processing corrections"""
        try:
            # Remove any unphysical values
            deformation_series = np.clip(deformation_series, -10.0, 10.0)  # ±10m max
            
            # Apply temporal smoothing if needed
            if len(deformation_series) > 10:
                from scipy.signal import savgol_filter
                window_length = min(11, len(deformation_series) if len(deformation_series) % 2 == 1 else len(deformation_series) - 1)
                if window_length >= 3:
                    deformation_series = savgol_filter(deformation_series, window_length, 3)
            
            return deformation_series
            
        except Exception as e:
            self.logger.warning(f"Post-processing corrections failed: {e}")
            return deformation_series
    
