    # ===== ADVANCED SIGNAL QUALITY ASSESSMENT METHODS =====
    
    def _advanced_signal_preprocessing(self, signal: np.ndarray) -> np.ndarray:
        """Advanced signal preprocessing with adaptive filtering and denoising"""
        try:
            from scipy import signal as scipy_signal
            from scipy.ndimage import gaussian_filter1d
            
            # Remove DC component and linear trends
            signal_detrended = scipy_signal.detrend(signal, type='linear')
            
            # Adaptive noise estimation using wavelet denoising
            try:
                import pywt
                # Wavelet denoising
                wavelet = 'db4'
                coeffs = pywt.wavedec(signal_detrended, wavelet, level=4)
                threshold = np.std(signal_detrended) * np.sqrt(2 * np.log(len(signal_detrended)))
                coeffs_thresh = [pywt.threshold(c, threshold, mode='soft') for c in coeffs]
                signal_clean = pywt.waverec(coeffs_thresh, wavelet)
            except ImportError:
                # Fallback to Gaussian filtering
                sigma = max(1, len(signal_detrended) // 100)
                signal_clean = gaussian_filter1d(signal_detrended, sigma=sigma)
            
            return signal_clean[:len(signal)]
            
        except Exception as e:
            self.logger.warning(f"Signal preprocessing failed: {e}")
            return signal

    def _compute_comprehensive_quality_metrics(self, signal: np.ndarray) -> Dict[str, float]:
        """Compute comprehensive signal quality metrics"""
        try:
            from scipy import signal as scipy_signal
            from scipy.stats import kurtosis, skew
            
            metrics = {}
            
            # Time-domain metrics
            metrics['signal_power'] = np.mean(signal**2)
            metrics['peak_amplitude'] = np.max(np.abs(signal))
            metrics['rms_amplitude'] = np.sqrt(np.mean(signal**2))
            metrics['dynamic_range'] = metrics['peak_amplitude'] / (np.std(signal) + 1e-10)
            
            # Statistical metrics
            metrics['kurtosis'] = kurtosis(signal)
            metrics['skewness'] = skew(signal)
            metrics['entropy'] = -np.sum(signal**2 * np.log(signal**2 + 1e-10))
            
            # Frequency domain metrics
            freqs, psd = scipy_signal.welch(signal, nperseg=min(256, len(signal)//4))
            metrics['spectral_centroid'] = np.sum(freqs * psd) / (np.sum(psd) + 1e-10)
            metrics['spectral_spread'] = np.sqrt(np.sum((freqs - metrics['spectral_centroid'])**2 * psd) / (np.sum(psd) + 1e-10))
            metrics['spectral_flatness'] = scipy_signal.spectral_flatness(psd)
            
            # SNR estimation using multiple methods
            metrics['snr_welch'] = self._estimate_snr_welch(signal)
            metrics['snr_periodogram'] = self._estimate_snr_periodogram(signal)
            metrics['snr_autocorrelation'] = self._estimate_snr_autocorrelation(signal)
            
            # Continuity and completeness metrics
            metrics['continuity_index'] = self._compute_continuity_index(signal)
            metrics['completeness_ratio'] = self._compute_completeness_ratio(signal)
            metrics['outlier_ratio'] = self._compute_outlier_ratio(signal)
            
            return metrics
            
        except Exception as e:
            self.logger.error(f"Quality metrics computation failed: {e}")
            return {'signal_power': 0.1, 'snr_welch': 1.0}

    def _ml_quality_assessment(self, quality_metrics: Dict[str, float]) -> Dict[str, float]:
        """Machine learning-based quality assessment using trained models"""
        try:
            from .model_manager import ModelManager
            
            # Initialize model manager for signal quality models
            model_manager = ModelManager()
            
            # Prepare feature vector from quality metrics
            feature_names = ['signal_power', 'dynamic_range', 'snr_welch', 'spectral_centroid', 
                           'spectral_flatness', 'continuity_index', 'completeness_ratio']
            
            features = np.array([quality_metrics.get(name, 0.0) for name in feature_names]).reshape(1, -1)
            
            # Try to load and use trained quality assessment model
            try:
                quality_model = model_manager.load_model('signal_quality_classifier')
                if quality_model is not None:
                    ml_score = float(quality_model.predict_proba(features)[0, 1])  # Probability of good quality
                    confidence = float(np.max(quality_model.predict_proba(features)[0]))
                    
                    return {
                        'ml_quality_score': ml_score,
                        'confidence': confidence,
                        'model_version': getattr(quality_model, 'version', 'unknown')
                    }
            except Exception as model_e:
                self.logger.debug(f"ML model loading failed: {model_e}")
            
            # Fallback to heuristic ML scoring
            ml_score = self._heuristic_quality_scoring(quality_metrics)
            
            return {
                'ml_quality_score': ml_score,
                'confidence': 0.6,
                'model_version': 'heuristic_fallback'
            }
            
        except Exception as e:
            self.logger.error(f"ML quality assessment failed: {e}")
            return {'ml_quality_score': 0.5, 'confidence': 0.3}

    def _apply_physics_quality_constraints(self, signal: np.ndarray) -> Dict[str, float]:
        """Apply physics-based quality constraints for seismic signals"""
        try:
            constraints = {}
            
            # Seismic frequency band constraints (0.01 - 50 Hz typical)
            freqs, psd = scipy_signal.welch(signal, nperseg=min(256, len(signal)//4))
            seismic_band_power = np.sum(psd[(freqs >= 0.01) & (freqs <= 50.0)])
            total_power = np.sum(psd) + 1e-10
            constraints['seismic_band_ratio'] = seismic_band_power / total_power
            
            # Amplitude constraints based on typical seismic ranges
            max_amplitude = np.max(np.abs(signal))
            if max_amplitude > 1e6:  # Unrealistically high
                constraints['amplitude_constraint'] = 0.1
            elif max_amplitude < 1e-9:  # Too weak
                constraints['amplitude_constraint'] = 0.2
            else:
                constraints['amplitude_constraint'] = 1.0
            
            # Temporal coherence constraint
            autocorr = np.correlate(signal, signal, mode='full')
            autocorr = autocorr[len(autocorr)//2:]
            autocorr = autocorr / autocorr[0]
            coherence_length = np.argmax(autocorr < 0.1)
            constraints['temporal_coherence'] = min(1.0, coherence_length / (len(signal) * 0.1))
            
            return constraints
            
        except Exception as e:
            self.logger.error(f"Physics constraints application failed: {e}")
            return {'seismic_band_ratio': 0.5, 'amplitude_constraint': 0.5}

    def _ensemble_quality_estimation(self, quality_metrics: Dict, ml_quality: Dict, 
                                   physics_constraints: Dict) -> Dict[str, float]:
        """Ensemble quality estimation with uncertainty quantification"""
        try:
            # Weight different assessment methods
            weights = {
                'metrics': 0.4,
                'ml': 0.35,
                'physics': 0.25
            }
            
            # Compute individual scores
            metrics_score = self._compute_metrics_score(quality_metrics)
            ml_score = ml_quality.get('ml_quality_score', 0.5)
            physics_score = self._compute_physics_score(physics_constraints)
            
            # Weighted ensemble score
            ensemble_score = (weights['metrics'] * metrics_score + 
                            weights['ml'] * ml_score + 
                            weights['physics'] * physics_score)
            
            # Uncertainty estimation based on agreement between methods
            scores = [metrics_score, ml_score, physics_score]
            uncertainty = np.std(scores) / np.mean(scores) if np.mean(scores) > 0 else 1.0
            
            # Confidence based on individual confidences and agreement
            confidences = [0.8, ml_quality.get('confidence', 0.5), 0.7]
            ensemble_confidence = np.mean(confidences) * (1.0 - uncertainty)
            
            return {
                'score': float(np.clip(ensemble_score, 0.0, 1.0)),
                'uncertainty': float(np.clip(uncertainty, 0.0, 1.0)),
                'confidence': float(np.clip(ensemble_confidence, 0.0, 1.0)),
                'individual_scores': {
                    'metrics': float(metrics_score),
                    'ml': float(ml_score),
                    'physics': float(physics_score)
                }
            }
            
        except Exception as e:
            self.logger.error(f"Ensemble quality estimation failed: {e}")
            return {'score': 0.5, 'uncertainty': 0.5, 'confidence': 0.3}

