    def _fallback_quality_assessment(self, signal: np.ndarray) -> float:
        """Simple fallback quality assessment"""
        try:
            if len(signal) == 0:
                return 0.0
            
            # Basic SNR estimation
            signal_power = np.mean(signal**2)
            noise_estimate = np.var(np.diff(signal))
            
            if noise_estimate > 0:
                snr = signal_power / noise_estimate
                return float(np.clip(snr / 100.0, 0.0, 1.0))
            else:
                return 0.8  # Assume good quality if no noise detected
                
        except Exception:
            return 0.3

