    def _extract_earthquake_parameters_with_uncertainty(self, eq) -> Dict[str, Any]:
        """Extract earthquake parameters with uncertainty quantification"""
        try:
            params = {
                'magnitude': eq.properties.get('magnitude', 5.0),
                'depth_km': eq.properties.get('depth', 10.0),
                'latitude': eq.properties.get('latitude', 0.0),
                'longitude': eq.properties.get('longitude', 0.0),
                'timestamp': eq.timestamp.timestamp() if hasattr(eq, 'timestamp') else 0.0,
                'magnitude_type': eq.properties.get('magtype', 'ml'),
                'location_uncertainty_km': eq.properties.get('location_uncertainty', 5.0),
                'depth_uncertainty_km': eq.properties.get('depth_uncertainty', 2.0),
                'magnitude_uncertainty': eq.properties.get('magnitude_error', 0.2),
                'strike': eq.properties.get('strike', 0.0),
                'dip': eq.properties.get('dip', 90.0),
                'rake': eq.properties.get('rake', 0.0)
            }
            
            # Add derived parameters
            params['moment'] = 10**(1.5 * params['magnitude'] + 9.1)  # Seismic moment
            params['rupture_area'] = (params['moment'] / 3e6)**(2/3)  # Rupture area estimate
            params['distance_km'] = self._calculate_epicentral_distance(params)
            
            return params
            
        except Exception as e:
            self.logger.error(f"Earthquake parameter extraction failed: {e}")
            return self._default_earthquake_parameters()

    def _compute_multi_phase_wave_propagation(self, eq_params: Dict, geological_model: Dict, 
                                            crustal_structure: Dict, time_grid: np.ndarray) -> Dict[str, np.ndarray]:
        """Compute multi-phase wave propagation (P, S, surface waves)"""
        try:
            wave_phases = {}
            
            # P-wave propagation
            wave_phases['p_wave'] = self._compute_p_wave_propagation(
                eq_params, geological_model, crustal_structure, time_grid
            )
            
            # S-wave propagation  
            wave_phases['s_wave'] = self._compute_s_wave_propagation(
                eq_params, geological_model, crustal_structure, time_grid
            )
            
            # Surface wave propagation (Rayleigh and Love waves)
            wave_phases['surface_waves'] = self._compute_surface_wave_propagation(
                eq_params, geological_model, crustal_structure, time_grid
            )
            
            # Coda waves from scattering
            wave_phases['coda_waves'] = self._compute_coda_wave_propagation(
                eq_params, crustal_structure, time_grid
            )
            
            return wave_phases
            
        except Exception as e:
            self.logger.error(f"Multi-phase wave computation failed: {e}")
            return self._simple_wave_propagation_fallback(eq_params, time_grid)

    def _apply_frequency_dependent_attenuation(self, wave_contributions: Dict, 
                                             eq_params: Dict, geological_model: Dict) -> Dict[str, np.ndarray]:
        """Apply frequency-dependent attenuation using Q-model"""
        try:
            from scipy.fft import fft, ifft, fftfreq
            
            attenuated_waves = {}
            
            for wave_type, waveform in wave_contributions.items():
                # Transform to frequency domain
                waveform_fft = fft(waveform)
                freqs = fftfreq(len(waveform))
                
                # Apply Q-model attenuation
                q_factor = self._get_q_factor(wave_type, eq_params, geological_model)
                distance_km = eq_params.get('distance_km', 100.0)
                
                # Frequency-dependent attenuation
                attenuation_factor = np.exp(-np.pi * np.abs(freqs) * distance_km * 1000 / 
                                          (geological_model['vp'][0] * q_factor))
                
                # Apply attenuation in frequency domain
                waveform_attenuated_fft = waveform_fft * attenuation_factor
                
                # Transform back to time domain
                attenuated_waves[wave_type] = np.real(ifft(waveform_attenuated_fft))
            
            return attenuated_waves
            
        except Exception as e:
            self.logger.error(f"Frequency-dependent attenuation failed: {e}")
            return wave_contributions

    def _apply_site_amplification_effects(self, attenuated_waves: Dict, 
                                        geological_model: Dict, eq_params: Dict) -> Dict[str, np.ndarray]:
        """Apply site amplification effects based on local geology"""
        try:
            amplified_waves = {}
            
            # Get site classification (rock, soft soil, etc.)
            site_class = self._determine_site_class(geological_model)
            
            # Site amplification factors by frequency and site class
            amplification_factors = self._get_site_amplification_factors(site_class)
            
            for wave_type, waveform in attenuated_waves.items():
                # Apply frequency-dependent amplification
                amplified_waveform = self._apply_frequency_dependent_amplification(
                    waveform, amplification_factors, wave_type
                )
                
                amplified_waves[wave_type] = amplified_waveform
            
            return amplified_waves
            
        except Exception as e:
            self.logger.error(f"Site amplification failed: {e}")
            return attenuated_waves

    def _apply_scattering_effects(self, amplified_waves: Dict, crustal_structure: Dict, 
                                eq_params: Dict) -> Dict[str, np.ndarray]:
        """Apply scattering effects from heterogeneous media"""
        try:
            scattered_waves = {}
            
            # Get scattering parameters from crustal heterogeneities
            scattering_strength = self._compute_scattering_strength(crustal_structure)
            
            for wave_type, waveform in amplified_waves.items():
                # Apply random scattering using Born approximation
                scattered_waveform = self._apply_born_scattering(
                    waveform, scattering_strength, eq_params
                )
                
                scattered_waves[wave_type] = scattered_waveform
            
            return scattered_waves
            
        except Exception as e:
            self.logger.error(f"Scattering effects failed: {e}")
            return amplified_waves

    def _superimpose_wave_effects(self, propagated_series: np.ndarray, scattered_waves: Dict,
                                time_grid: np.ndarray, eq_params: Dict) -> np.ndarray:
        """Superimpose wave effects with proper phase relationships"""
        try:
            # Calculate arrival times for different phases
            arrival_times = self._calculate_phase_arrival_times(eq_params)
            
            # Superimpose each wave phase at correct arrival time
            for wave_type, waveform in scattered_waves.items():
                arrival_time = arrival_times.get(wave_type, 0.0)
                
                # Find insertion point in time grid
                insertion_idx = np.searchsorted(time_grid, arrival_time)
                
                # Insert waveform at correct time with proper amplitude scaling
                amplitude_scale = self._get_amplitude_scaling(wave_type, eq_params)
                
                end_idx = min(insertion_idx + len(waveform), len(propagated_series))
                waveform_len = end_idx - insertion_idx
                
                if waveform_len > 0:
                    propagated_series[insertion_idx:end_idx] += (
                        waveform[:waveform_len] * amplitude_scale
                    )
            
            return propagated_series
            
        except Exception as e:
            self.logger.error(f"Wave superposition failed: {e}")
            return propagated_series

    def _apply_propagation_uncertainty(self, propagated_series: np.ndarray, 
                                     eq_params: Dict, geological_model: Dict) -> np.ndarray:
        """Apply uncertainty quantification to propagation results"""
        try:
            # Monte Carlo uncertainty propagation
            n_samples = 100
            uncertainty_series = []
            
            for _ in range(n_samples):
                # Perturb parameters within uncertainty bounds
                perturbed_params = self._perturb_earthquake_parameters(eq_params)
                perturbed_model = self._perturb_geological_model(geological_model)
                
                # Compute uncertainty contribution (simplified)
                uncertainty_factor = np.random.normal(1.0, 0.1, len(propagated_series))
                uncertainty_series.append(propagated_series * uncertainty_factor)
            
            # Compute ensemble statistics
            uncertainty_mean = np.mean(uncertainty_series, axis=0)
            uncertainty_std = np.std(uncertainty_series, axis=0)
            
            # Return mean with uncertainty bounds
            return uncertainty_mean
            
        except Exception as e:
            self.logger.error(f"Uncertainty quantification failed: {e}")
            return propagated_series

    def _validate_against_seismometer_network(self, propagated_series: np.ndarray,
                                            time_grid: np.ndarray, earthquake_data: List) -> np.ndarray:
        """Validate propagation results against real seismometer network data"""
        try:
            from .external_data_connectors import USGSConnector, IRISConnector
            
            # Get real seismometer data for validation
            validation_data = self._fetch_validation_seismometer_data(time_grid, earthquake_data)
            
            if validation_data is None:
                return propagated_series
            
            # Cross-correlation with real data
            correlation = np.corrcoef(
                propagated_series[:min(len(propagated_series), len(validation_data))],
                validation_data[:min(len(propagated_series), len(validation_data))]
            )[0, 1]
            
            # Apply validation-based correction if correlation is reasonable
            if correlation > 0.3:
                correction_factor = self._compute_validation_correction(
                    propagated_series, validation_data, correlation
                )
                return propagated_series * correction_factor
            
            return propagated_series
            
        except Exception as e:
            self.logger.error(f"Seismometer validation failed: {e}")
            return propagated_series

