    def _fallback_propagation_model(self, series: np.ndarray, 
                                  time_grid: np.ndarray, earthquake_data: List) -> np.ndarray:
        """Fallback to simple propagation model"""
        try:
            propagated_series = series.copy()
            
            # Simple distance-based attenuation
            for eq in earthquake_data[:5]:  # Process up to 5 earthquakes
                if hasattr(eq, 'properties') and hasattr(eq, 'timestamp'):
                    magnitude = eq.properties.get('magnitude', 5.0)
                    distance = eq.properties.get('distance_km', 100.0)
                    
                    # Simple attenuation law
                    attenuation = magnitude / (1.0 + distance / 50.0)
                    
                    # Apply time-dependent effect
                    eq_time = eq.timestamp.timestamp()
                    time_diff = np.abs(time_grid - eq_time)
                    time_decay = np.exp(-time_diff / 7200.0)  # 2-hour decay
                    
                    propagated_series += attenuation * time_decay * 0.05
            
            return propagated_series
            
        except Exception:
            return series

    # ===== SUPPORTING UTILITY METHODS =====

    def _estimate_snr_welch(self, signal: np.ndarray, metadata: Dict[str, Any] = None) -> Dict[str, float]:
        """Advanced SNR estimation using Welch's method with real-time database integration and ML enhancement"""
        try:
            from scipy import signal as scipy_signal
            import asyncio
            from .model_manager import ModelManager
            from .external_data_connectors_wrapper import ExternalDataConnectors
            
            # Enhanced Welch parameters based on signal characteristics
            sampling_rate = metadata.get('sampling_rate', 100) if metadata else 100
            signal_type = metadata.get('signal_type', 'seismic') if metadata else 'seismic'
            location = metadata.get('location', None) if metadata else None
            
            # Adaptive window sizing based on signal characteristics
            if signal_type == 'seismic':
                nperseg = min(1024, len(signal)//8)  # Better resolution for seismic
                overlap = nperseg // 2
            elif signal_type == 'magnetic':
                nperseg = min(512, len(signal)//6)
                overlap = nperseg // 4
            else:
                nperseg = min(256, len(signal)//4)
                overlap = nperseg // 8
            
            # Compute advanced PSD with multiple window functions
            windows = ['hann', 'blackman', 'hamming', 'tukey']
            psd_results = {}
            snr_estimates = {}
            
            for window in windows:
                freqs, psd = scipy_signal.welch(
                    signal, 
                    fs=sampling_rate,
                    window=window,
                    nperseg=nperseg,
                    noverlap=overlap,
                    detrend='linear',
                    scaling='density'
                )
                psd_results[window] = {'freqs': freqs, 'psd': psd}
                
                # Signal-specific frequency band analysis
                if signal_type == 'seismic':
                    # Seismic P-wave (1-15 Hz), S-wave (0.5-5 Hz), surface waves (0.05-1 Hz)
                    signal_bands = {
                        'p_wave': (1.0, 15.0),
                        's_wave': (0.5, 5.0),
                        'surface_wave': (0.05, 1.0)
                    }
                    noise_bands = {
                        'cultural': (15.0, 50.0),
                        'instrumental': (0.001, 0.05)
                    }
                elif signal_type == 'magnetic':
                    signal_bands = {
                        'geomagnetic': (0.001, 0.1),
                        'pulsations': (0.1, 5.0)
                    }
                    noise_bands = {
                        'powerline': (50.0, 60.0),
                        'high_freq': (10.0, 50.0)
                    }
                else:
                    # Generic signal analysis
                    signal_bands = {'primary': (freqs[1], np.percentile(freqs, 60))}
                    noise_bands = {'secondary': (np.percentile(freqs, 60), freqs[-2])}
                
                # Calculate SNR for each band combination
                band_snrs = {}
                for sig_name, (sig_low, sig_high) in signal_bands.items():
                    sig_mask = (freqs >= sig_low) & (freqs <= sig_high)
                    signal_power = np.mean(psd[sig_mask]) if np.any(sig_mask) else 0
                    
                    for noise_name, (noise_low, noise_high) in noise_bands.items():
                        noise_mask = (freqs >= noise_low) & (freqs <= noise_high)
                        noise_power = np.mean(psd[noise_mask]) if np.any(noise_mask) else 1e-12
                        
                        snr = signal_power / (noise_power + 1e-12)
                        band_snrs[f'{sig_name}_{noise_name}'] = float(snr)
                
                snr_estimates[window] = band_snrs
            
            # Get historical SNR data from database for location-based calibration
            if location and self.db_manager:
                historical_snr = asyncio.run(self._get_historical_snr_data(location, signal_type))
                if historical_snr:
                    # Apply location-specific calibration
                    snr_estimates = self._apply_location_calibration(snr_estimates, historical_snr)
            
            # Get real-time noise characteristics from external sources
            if self.external_data_connectors and location:
                noise_conditions = asyncio.run(self._get_real_time_noise_conditions(location))
                if noise_conditions:
                    snr_estimates = self._apply_noise_correction(snr_estimates, noise_conditions)
            
            # ML-enhanced SNR estimation using trained models
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    ml_snr = self._ml_enhanced_snr_estimation(signal, snr_estimates, metadata)
                    if ml_snr:
                        snr_estimates['ml_enhanced'] = ml_snr
                except Exception as e:
                    self.logger.warning(f"ML SNR estimation failed: {e}")
            
            # Compute ensemble SNR estimate
            all_snr_values = []
            for window_snrs in snr_estimates.values():
                if isinstance(window_snrs, dict):
                    all_snr_values.extend(window_snrs.values())
                else:
                    all_snr_values.append(window_snrs)
            
            if all_snr_values:
                ensemble_snr = np.median(all_snr_values)  # Robust central tendency
                snr_std = np.std(all_snr_values)
                confidence = max(0.0, 1.0 - (snr_std / (ensemble_snr + 1e-10)))
            else:
                ensemble_snr = 1.0
                confidence = 0.5
            
            # Store results in database for future calibration
            if self.db_manager and location:
                asyncio.run(self._store_snr_analysis({
                    'location': location,
                    'signal_type': signal_type,
                    'ensemble_snr': ensemble_snr,
                    'confidence': confidence,
                    'detailed_results': snr_estimates,
                    'timestamp': datetime.utcnow()
                }))
            
            return {
                'ensemble_snr': float(ensemble_snr),
                'confidence': float(confidence),
                'detailed_estimates': snr_estimates,
                'frequency_analysis': psd_results,
                'signal_type': signal_type,
                'location': location
            }
            
        except Exception as e:
            self.logger.error(f"Advanced Welch SNR estimation failed: {e}")
            return {'ensemble_snr': 1.0, 'confidence': 0.1, 'error': str(e)}

    def _estimate_snr_periodogram(self, signal: np.ndarray, metadata: Dict[str, Any] = None) -> Dict[str, float]:
        """Advanced multi-taper periodogram SNR estimation with real-time streaming data integration"""
        try:
            from scipy import signal as scipy_signal
            from scipy.signal import lombscargle
            import asyncio
            from .stream_processing import StreamProcessor
            
            sampling_rate = metadata.get('sampling_rate', 100) if metadata else 100
            signal_type = metadata.get('signal_type', 'seismic') if metadata else 'seismic'
            station_id = metadata.get('station_id', 'unknown') if metadata else 'unknown'
            
            # Multi-taper periodogram for better spectral estimation
            try:
                from spectrum import pmtm
                # Multi-taper method with adaptive number of tapers
                time_bandwidth = min(4.0, len(signal) * sampling_rate / 1000)  # Adaptive NW parameter
                n_tapers = int(2 * time_bandwidth - 1)
                
                psd_mtm, freqs_mtm = pmtm(signal, NW=time_bandwidth, k=n_tapers, method='eigen')
                freqs_mtm = freqs_mtm * sampling_rate / (2 * np.pi)
                
                # Store multi-taper results
                mtm_results = {'freqs': freqs_mtm, 'psd': psd_mtm, 'method': 'multitaper'}
                
            except ImportError:
                self.logger.warning("Spectrum library not available, using scipy periodogram")
                freqs_mtm, psd_mtm = scipy_signal.periodogram(signal, fs=sampling_rate, scaling='density')
                mtm_results = {'freqs': freqs_mtm, 'psd': psd_mtm, 'method': 'periodogram'}
            
            # Lomb-Scargle periodogram for unevenly sampled data robustness
            time_axis = np.arange(len(signal)) / sampling_rate
            freqs_ls = np.linspace(0.01, sampling_rate/2, len(signal)//2)
            psd_ls = lombscargle(time_axis, signal, 2*np.pi*freqs_ls, normalize=True)
            ls_results = {'freqs': freqs_ls, 'psd': psd_ls, 'method': 'lomb_scargle'}
            
            # Real-time comparison with streaming network data
            network_snr_data = None
            if hasattr(self, 'realtime_data_feeds') and self.realtime_data_feeds:
                try:
                    network_snr_data = asyncio.run(
                        self._get_network_snr_comparison(station_id, signal_type, freqs_mtm, psd_mtm)
                    )
                except Exception as e:
                    self.logger.warning(f"Network SNR comparison failed: {e}")
            
            # Advanced peak detection and characterization
            snr_estimates = {}
            
            for method_name, spec_data in [('multitaper', mtm_results), ('lomb_scargle', ls_results)]:
                freqs = spec_data['freqs']
                psd = spec_data['psd']
                
                # Sophisticated peak detection
                from scipy.signal import find_peaks, peak_prominences, peak_widths
                
                # Find spectral peaks above noise floor
                psd_smooth = scipy_signal.savgol_filter(psd, window_length=min(21, len(psd)//10), polyorder=3)
                noise_floor = np.percentile(psd_smooth, 25)
                
                peaks, peak_props = find_peaks(
                    psd_smooth, 
                    height=noise_floor * 2,
                    distance=max(1, len(psd) // 50),
                    prominence=noise_floor * 1.5
                )
                
                if len(peaks) > 0:
                    # Characterize each peak
                    peak_powers = psd_smooth[peaks]
                    prominences = peak_prominences(psd_smooth, peaks)[0]
                    widths = peak_widths(psd_smooth, peaks, rel_height=0.5)[0]
                    
                    # Calculate various SNR metrics
                    max_peak_snr = np.max(peak_powers) / (noise_floor + 1e-12)
                    avg_peak_snr = np.mean(peak_powers) / (noise_floor + 1e-12)
                    prominence_snr = np.max(prominences) / (noise_floor + 1e-12)
                    
                    # Frequency-specific SNR analysis
                    peak_freqs = freqs[peaks]
                    freq_snr_dict = {}
                    
                    for i, (freq, power, prom) in enumerate(zip(peak_freqs, peak_powers, prominences)):
                        # Local noise estimation around each peak
                        freq_window = max(1, int(len(freqs) * 0.02))  # 2% window
                        start_idx = max(0, peaks[i] - freq_window)
                        end_idx = min(len(psd), peaks[i] + freq_window)
                        
                        local_noise = np.percentile(psd[start_idx:end_idx], 10)  # Low percentile for noise
                        local_snr = power / (local_noise + 1e-12)
                        
                        freq_snr_dict[f'peak_{i}_at_{freq:.2f}Hz'] = {
                            'snr': float(local_snr),
                            'prominence': float(prom),
                            'width': float(widths[i]) if i < len(widths) else 1.0,
                            'frequency': float(freq),
                            'power': float(power)
                        }
                    
                    snr_estimates[method_name] = {
                        'max_peak_snr': float(max_peak_snr),
                        'avg_peak_snr': float(avg_peak_snr),
                        'prominence_snr': float(prominence_snr),
                        'n_significant_peaks': len(peaks),
                        'noise_floor': float(noise_floor),
                        'frequency_specific': freq_snr_dict
                    }
                else:
                    # No significant peaks found
                    total_power = np.mean(psd)
                    snr_estimates[method_name] = {
                        'max_peak_snr': float(total_power / (noise_floor + 1e-12)),
                        'avg_peak_snr': 1.0,
                        'prominence_snr': 1.0,
                        'n_significant_peaks': 0,
                        'noise_floor': float(noise_floor)
                    }
            
            # Integration with network-wide SNR statistics
            if network_snr_data:
                snr_estimates['network_comparison'] = self._compare_with_network_snr(
                    snr_estimates, network_snr_data
                )
            
            # Temporal coherence analysis across frequency bands
            coherence_analysis = self._analyze_spectral_coherence(
                signal, freqs_mtm, psd_mtm, sampling_rate
            )
            snr_estimates['coherence_metrics'] = coherence_analysis
            
            # Store detailed analysis in time-series database
            if hasattr(self, 'timeseries_db') and self.timeseries_db:
                asyncio.run(self._store_periodogram_analysis({
                    'station_id': station_id,
                    'signal_type': signal_type,
                    'snr_estimates': snr_estimates,
                    'spectral_data': {
                        'multitaper': mtm_results,
                        'lomb_scargle': ls_results
                    },
                    'timestamp': datetime.utcnow()
                }))
            
            # Compute ensemble periodogram SNR
            all_max_snrs = [est.get('max_peak_snr', 1.0) for est in snr_estimates.values() if isinstance(est, dict) and 'max_peak_snr' in est]
            ensemble_snr = np.median(all_max_snrs) if all_max_snrs else 1.0
            
            return {
                'ensemble_snr': float(ensemble_snr),
                'detailed_estimates': snr_estimates,
                'spectral_methods': ['multitaper', 'lomb_scargle'],
                'peak_count': sum(est.get('n_significant_peaks', 0) for est in snr_estimates.values() if isinstance(est, dict)),
                'signal_type': signal_type,
                'station_id': station_id
            }
            
        except Exception as e:
            self.logger.error(f"Advanced periodogram SNR estimation failed: {e}")
            return {'ensemble_snr': 1.0, 'confidence': 0.1, 'error': str(e)}

    def _estimate_snr_autocorrelation(self, signal: np.ndarray, metadata: Dict[str, Any] = None) -> Dict[str, float]:
        """Advanced autocorrelation-based SNR with multi-scale analysis and ML-enhanced pattern recognition"""
        try:
            import asyncio
            from scipy.signal import correlate, correlation_lags, hilbert
            from scipy.stats import kurtosis, skew
            from .geological_statistics import GeologicalStatistics
            
            signal_type = metadata.get('signal_type', 'seismic') if metadata else 'seismic'
            sampling_rate = metadata.get('sampling_rate', 100) if metadata else 100
            location = metadata.get('location', None) if metadata else None
            
            # Multi-scale autocorrelation analysis
            scales = [1, 2, 4, 8, 16] if len(signal) > 64 else [1, 2, 4]
            autocorr_results = {}
            snr_estimates = {}
            
            for scale in scales:
                # Downsample signal for multi-scale analysis
                if scale > 1:
                    downsampled = signal[::scale]
                else:
                    downsampled = signal.copy()
                
                # Full autocorrelation
                autocorr_full = correlate(downsampled, downsampled, mode='full')
                lags = correlation_lags(len(downsampled), len(downsampled), mode='full')
                
                # Normalize autocorrelation
                autocorr_norm = autocorr_full / autocorr_full[len(autocorr_full)//2]
                
                # Extract positive lags only
                positive_mask = lags >= 0
                autocorr_pos = autocorr_norm[positive_mask]
                lags_pos = lags[positive_mask]
                
                # Advanced decay analysis
                decay_metrics = self._analyze_autocorr_decay(autocorr_pos, lags_pos, sampling_rate/scale)
                
                # Coherence length estimation
                coherence_length = self._estimate_coherence_length(
                    autocorr_pos, lags_pos, signal_type
                )
                
                # Periodic component detection
                periodic_components = self._detect_periodic_components(
                    autocorr_pos, lags_pos, sampling_rate/scale
                )
                
                # Statistical moments of autocorrelation
                autocorr_stats = {
                    'mean': float(np.mean(autocorr_pos[1:])),  # Exclude zero-lag
                    'std': float(np.std(autocorr_pos[1:])),
                    'kurtosis': float(kurtosis(autocorr_pos[1:])),
                    'skewness': float(skew(autocorr_pos[1:]))
                }
                
                # SNR estimation based on autocorrelation structure
                if signal_type == 'seismic':
                    # Seismic signals: coherent arrivals vs background noise
                    snr_decay = self._seismic_autocorr_snr(autocorr_pos, decay_metrics)
                    snr_coherence = coherence_length / (len(signal) / sampling_rate)  # Normalized coherence
                    snr_periodic = max(periodic_components.values()) if periodic_components else 1.0
                    
                elif signal_type == 'magnetic':
                    # Magnetic signals: geomagnetic variations vs instrument noise
                    snr_decay = self._magnetic_autocorr_snr(autocorr_pos, decay_metrics)
                    snr_coherence = coherence_length / 3600  # Normalized by 1-hour typical coherence
                    snr_periodic = max(periodic_components.values()) if periodic_components else 1.0
                    
                else:
                    # Generic signal analysis
                    snr_decay = decay_metrics.get('exponential_decay_rate', 1.0)
                    snr_coherence = coherence_length / len(signal)
                    snr_periodic = max(periodic_components.values()) if periodic_components else 1.0
                
                # Ensemble SNR for this scale
                scale_snr = np.sqrt(
                    snr_decay * snr_coherence * snr_periodic
                )  # Geometric mean for multiplicative effects
                
                snr_estimates[f'scale_{scale}'] = {
                    'ensemble_snr': float(scale_snr),
                    'decay_snr': float(snr_decay),
                    'coherence_snr': float(snr_coherence),
                    'periodic_snr': float(snr_periodic),
                    'coherence_length': float(coherence_length),
                    'decay_metrics': decay_metrics,
                    'periodic_components': periodic_components,
                    'statistics': autocorr_stats
                }
                
                autocorr_results[f'scale_{scale}'] = {
                    'autocorr': autocorr_pos,
                    'lags': lags_pos,
                    'sampling_rate': sampling_rate/scale
                }
            
            # Cross-scale coherence analysis
            cross_scale_coherence = self._analyze_cross_scale_coherence(
                autocorr_results, scales
            )
            
            # ML-enhanced pattern recognition
            if hasattr(self, 'geological_stats') and self.geological_stats:
                try:
                    pattern_analysis = self._ml_autocorr_pattern_recognition(
                        signal, autocorr_results, metadata
                    )
                    snr_estimates['ml_pattern'] = pattern_analysis
                except Exception as e:
                    self.logger.warning(f"ML pattern recognition failed: {e}")
            
            # Integration with geological database for location-specific calibration
            if location and hasattr(self, 'db_manager') and self.db_manager:
                try:
                    geological_context = asyncio.run(
                        self._get_geological_autocorr_context(location, signal_type)
                    )
                    if geological_context:
                        snr_estimates = self._apply_geological_calibration(
                            snr_estimates, geological_context
                        )
                except Exception as e:
                    self.logger.warning(f"Geological calibration failed: {e}")
            
            # Real-time comparison with streaming network data
            if hasattr(self, 'realtime_data_feeds') and location:
                try:
                    network_autocorr = asyncio.run(
                        self._get_network_autocorr_reference(location, signal_type)
                    )
                    if network_autocorr:
                        snr_estimates['network_comparison'] = self._compare_autocorr_with_network(
                            autocorr_results, network_autocorr
                        )
                except Exception as e:
                    self.logger.warning(f"Network autocorr comparison failed: {e}")
            
            # Final ensemble SNR computation
            all_ensemble_snrs = [
                est.get('ensemble_snr', 1.0) 
                for est in snr_estimates.values() 
                if isinstance(est, dict) and 'ensemble_snr' in est
            ]
            
            if all_ensemble_snrs:
                final_snr = np.median(all_ensemble_snrs)  # Robust estimate
                snr_uncertainty = np.std(all_ensemble_snrs) / np.sqrt(len(all_ensemble_snrs))
                confidence = max(0.0, 1.0 - snr_uncertainty / (final_snr + 1e-10))
            else:
                final_snr = 1.0
                confidence = 0.5
            
            # Store analysis results
            if hasattr(self, 'timeseries_db') and location:
                asyncio.run(self._store_autocorr_analysis({
                    'location': location,
                    'signal_type': signal_type,
                    'final_snr': final_snr,
                    'confidence': confidence,
                    'cross_scale_coherence': cross_scale_coherence,
                    'detailed_results': snr_estimates,
                    'timestamp': datetime.utcnow()
                }))
            
            return {
                'ensemble_snr': float(final_snr),
                'confidence': float(confidence),
                'cross_scale_coherence': float(cross_scale_coherence),
                'scale_analysis': snr_estimates,
                'signal_type': signal_type,
                'location': location,
                'n_scales': len(scales)
            }
            
        except Exception as e:
            self.logger.error(f"Advanced autocorrelation SNR estimation failed: {e}")
            return {'ensemble_snr': 1.0, 'confidence': 0.1, 'error': str(e)}

    def _compute_continuity_index(self, signal: np.ndarray, metadata: Dict[str, Any] = None) -> Dict[str, float]:
        """Advanced continuity analysis with real-time data quality monitoring and ML-based anomaly detection"""
        try:
            import asyncio
            from scipy import stats
            from scipy.signal import find_peaks, savgol_filter
            from .data_quality_monitor import DataQualityMonitor
            
            signal_type = metadata.get('signal_type', 'seismic') if metadata else 'seismic'
            sampling_rate = metadata.get('sampling_rate', 100) if metadata else 100
            station_id = metadata.get('station_id', 'unknown') if metadata else 'unknown'
            
            # Multi-method continuity analysis
            continuity_metrics = {}
            
            # 1. Classical discontinuity detection
            diff_signal = np.diff(signal)
            robust_std = stats.median_abs_deviation(diff_signal) * 1.4826  # Robust std estimate
            
            # Adaptive threshold based on signal characteristics
            if signal_type == 'seismic':
                threshold_factor = 4.0  # More sensitive for seismic
            elif signal_type == 'magnetic':
                threshold_factor = 5.0  # Less sensitive for magnetic
            else:
                threshold_factor = 3.0  # Default
            
            threshold = threshold_factor * robust_std
            discontinuities = np.sum(np.abs(diff_signal) > threshold)
            classical_continuity = 1.0 - (discontinuities / len(signal))
            
            continuity_metrics['classical'] = {
                'continuity_index': float(np.clip(classical_continuity, 0.0, 1.0)),
                'n_discontinuities': int(discontinuities),
                'threshold_used': float(threshold),
                'robust_std': float(robust_std)
            }
            
            # 2. Smoothness-based continuity
            try:
                # Apply Savitzky-Golay filter to estimate smooth trend
                window_length = min(51, len(signal)//10 if len(signal) > 50 else 5)
                if window_length % 2 == 0:
                    window_length += 1
                    
                smooth_signal = savgol_filter(signal, window_length, polyorder=3)
                smoothness_residual = signal - smooth_signal
                smoothness_var = np.var(smoothness_residual)
                signal_var = np.var(signal)
                
                smoothness_ratio = 1.0 - (smoothness_var / (signal_var + 1e-12))
                continuity_metrics['smoothness'] = {
                    'continuity_index': float(np.clip(smoothness_ratio, 0.0, 1.0)),
                    'residual_variance': float(smoothness_var),
                    'signal_variance': float(signal_var)
                }
                
            except Exception as e:
                self.logger.warning(f"Smoothness continuity analysis failed: {e}")
                continuity_metrics['smoothness'] = {'continuity_index': 0.8}
            
            # 3. Spectral coherence continuity
            try:
                from scipy.signal import coherence, welch
                
                # Split signal into overlapping segments
                segment_length = min(512, len(signal)//4)
                if segment_length < 32:
                    segment_length = len(signal)//2
                
                # Calculate coherence between consecutive segments
                coherence_values = []
                for i in range(0, len(signal) - segment_length, segment_length//2):
                    seg1 = signal[i:i+segment_length]
                    seg2 = signal[i+segment_length//2:i+3*segment_length//2]
                    
                    if len(seg2) >= segment_length:
                        f, coh = coherence(seg1, seg2, fs=sampling_rate, nperseg=min(64, len(seg1)//4))
                        mean_coherence = np.mean(coh[1:])  # Exclude DC component
                        coherence_values.append(mean_coherence)
                
                if coherence_values:
                    spectral_continuity = np.mean(coherence_values)
                else:
                    spectral_continuity = 0.8
                
                continuity_metrics['spectral'] = {
                    'continuity_index': float(spectral_continuity),
                    'n_segments': len(coherence_values),
                    'coherence_std': float(np.std(coherence_values)) if coherence_values else 0.0
                }
                
            except Exception as e:
                self.logger.warning(f"Spectral continuity analysis failed: {e}")
                continuity_metrics['spectral'] = {'continuity_index': 0.8}
            
            # 4. ML-based anomaly detection for continuity
            if hasattr(self, 'data_quality_monitor'):
                try:
                    anomaly_score = self.data_quality_monitor.detect_continuity_anomalies(
                        signal, signal_type, sampling_rate
                    )
                    ml_continuity = 1.0 - anomaly_score
                    
                    continuity_metrics['ml_anomaly'] = {
                        'continuity_index': float(np.clip(ml_continuity, 0.0, 1.0)),
                        'anomaly_score': float(anomaly_score)
                    }
                except Exception as e:
                    self.logger.warning(f"ML anomaly detection failed: {e}")
            
            # 5. Real-time comparison with network stations
            if hasattr(self, 'realtime_data_feeds'):
                try:
                    network_continuity = asyncio.run(
                        self._get_network_continuity_reference(station_id, signal_type)
                    )
                    
                    if network_continuity:
                        # Compare local continuity with network average
                        network_avg = network_continuity.get('average_continuity', 0.8)
                        relative_continuity = classical_continuity / (network_avg + 1e-10)
                        
                        continuity_metrics['network_comparison'] = {
                            'relative_continuity': float(relative_continuity),
                            'network_average': float(network_avg),
                            'network_std': float(network_continuity.get('std_continuity', 0.1)),
                            'z_score': float((classical_continuity - network_avg) / 
                                           (network_continuity.get('std_continuity', 0.1) + 1e-10))
                        }
                except Exception as e:
                    self.logger.warning(f"Network continuity comparison failed: {e}")
            
            # 6. Temporal variation analysis
            try:
                # Analyze continuity over time windows
                window_size = max(100, len(signal) // 10)
                windowed_continuity = []
                
                for i in range(0, len(signal) - window_size, window_size//2):
                    window = signal[i:i+window_size]
                    window_diff = np.diff(window)
                    window_threshold = threshold_factor * np.std(window_diff)
                    window_disc = np.sum(np.abs(window_diff) > window_threshold)
                    window_cont = 1.0 - (window_disc / len(window))
                    windowed_continuity.append(window_cont)
                
                if windowed_continuity:
                    temporal_metrics = {
                        'mean_continuity': float(np.mean(windowed_continuity)),
                        'std_continuity': float(np.std(windowed_continuity)),
                        'min_continuity': float(np.min(windowed_continuity)),
                        'max_continuity': float(np.max(windowed_continuity)),
                        'continuity_trend': float(np.corrcoef(
                            np.arange(len(windowed_continuity)), windowed_continuity
                        )[0, 1]) if len(windowed_continuity) > 2 else 0.0
                    }
                else:
                    temporal_metrics = {'mean_continuity': classical_continuity}
                
                continuity_metrics['temporal'] = temporal_metrics
                
            except Exception as e:
                self.logger.warning(f"Temporal continuity analysis failed: {e}")
            
            # Ensemble continuity estimate
            continuity_values = []
            weights = []
            
            for method, data in continuity_metrics.items():
                if isinstance(data, dict) and 'continuity_index' in data:
                    continuity_values.append(data['continuity_index'])
                    
                    # Assign weights based on method reliability
                    if method == 'classical':
                        weights.append(0.3)
                    elif method == 'smoothness':
                        weights.append(0.25)
                    elif method == 'spectral':
                        weights.append(0.2)
                    elif method == 'ml_anomaly':
                        weights.append(0.15)
                    else:
                        weights.append(0.1)
            
            if continuity_values:
                weights = np.array(weights[:len(continuity_values)])
                weights = weights / np.sum(weights)  # Normalize
                
                ensemble_continuity = np.average(continuity_values, weights=weights)
                continuity_std = np.sqrt(np.average(
                    (continuity_values - ensemble_continuity)**2, weights=weights
                ))
                confidence = max(0.0, 1.0 - continuity_std)
            else:
                ensemble_continuity = 0.8
                confidence = 0.5
            
            # Store detailed continuity analysis
            if hasattr(self, 'timeseries_db') and station_id != 'unknown':
                asyncio.run(self._store_continuity_analysis({
                    'station_id': station_id,
                    'signal_type': signal_type,
                    'ensemble_continuity': ensemble_continuity,
                    'confidence': confidence,
                    'detailed_metrics': continuity_metrics,
                    'timestamp': datetime.utcnow()
                }))
            
            return {
                'ensemble_continuity': float(ensemble_continuity),
                'confidence': float(confidence),
                'detailed_metrics': continuity_metrics,
                'n_methods': len(continuity_values),
                'signal_type': signal_type,
                'station_id': station_id
            }
            
        except Exception as e:
            self.logger.error(f"Advanced continuity analysis failed: {e}")
            return {'ensemble_continuity': 0.8, 'confidence': 0.1, 'error': str(e)}

    def _compute_completeness_ratio(self, signal: np.ndarray, metadata: Dict[str, Any] = None) -> Dict[str, float]:
        """Advanced signal completeness analysis with data quality scoring and real-time validation"""
        try:
            import asyncio
            from .data_quality_monitor import DataQualityMonitor
            
            signal_type = metadata.get('signal_type', 'seismic') if metadata else 'seismic'
            expected_range = metadata.get('expected_range', None) if metadata else None
            station_id = metadata.get('station_id', 'unknown') if metadata else 'unknown'
            
            completeness_metrics = {}
            
            # 1. Basic completeness (finite, non-zero values)
            finite_mask = np.isfinite(signal)
            nonzero_mask = signal != 0
            valid_mask = finite_mask & nonzero_mask
            
            basic_completeness = np.sum(valid_mask) / len(signal) if len(signal) > 0 else 0.0
            
            completeness_metrics['basic'] = {
                'completeness_ratio': float(basic_completeness),
                'n_finite': int(np.sum(finite_mask)),
                'n_nonzero': int(np.sum(nonzero_mask)),
                'n_valid': int(np.sum(valid_mask)),
                'n_total': len(signal)
            }
            
            # 2. Physical range completeness (values within expected physical range)
            if expected_range:
                min_val, max_val = expected_range
                range_mask = (signal >= min_val) & (signal <= max_val)
                physical_completeness = np.sum(range_mask & valid_mask) / len(signal)
                
                completeness_metrics['physical_range'] = {
                    'completeness_ratio': float(physical_completeness),
                    'n_in_range': int(np.sum(range_mask)),
                    'expected_min': float(min_val),
                    'expected_max': float(max_val),
                    'actual_min': float(np.min(signal[valid_mask])) if np.any(valid_mask) else 0.0,
                    'actual_max': float(np.max(signal[valid_mask])) if np.any(valid_mask) else 0.0
                }
            else:
                # Estimate reasonable range based on signal type
                if signal_type == 'seismic':
                    # Typical acceleration range in m/s²
                    std_val = np.std(signal[valid_mask]) if np.any(valid_mask) else 1.0
                    range_threshold = 10 * std_val  # 10-sigma outliers
                elif signal_type == 'magnetic':
                    # Typical magnetic field range in nT
                    range_threshold = 100000  # 100,000 nT
                else:
                    # Generic range based on data statistics
                    range_threshold = 5 * np.std(signal[valid_mask]) if np.any(valid_mask) else 1.0
                
                reasonable_mask = np.abs(signal) <= range_threshold
                statistical_completeness = np.sum(reasonable_mask & valid_mask) / len(signal)
                
                completeness_metrics['statistical_range'] = {
                    'completeness_ratio': float(statistical_completeness),
                    'n_within_threshold': int(np.sum(reasonable_mask)),
                    'range_threshold': float(range_threshold)
                }
            
            # 3. Temporal completeness (no large gaps in time series)
            try:
                sampling_rate = metadata.get('sampling_rate', 100) if metadata else 100
                expected_interval = 1.0 / sampling_rate
                
                # Find gaps in data (assuming regular sampling)
                time_diffs = np.diff(np.where(valid_mask)[0]) if np.any(valid_mask) else []
                
                if len(time_diffs) > 0:
                    # Convert index differences to time differences
                    time_gaps = np.array(time_diffs) / sampling_rate
                    large_gaps = time_gaps > (2 * expected_interval)  # Gaps > 2x expected
                    
                    temporal_completeness = 1.0 - (np.sum(large_gaps) / len(time_diffs))
                    
                    completeness_metrics['temporal'] = {
                        'completeness_ratio': float(temporal_completeness),
                        'n_gaps': int(np.sum(large_gaps)),
                        'max_gap_seconds': float(np.max(time_gaps)) if len(time_gaps) > 0 else 0.0,
                        'mean_gap_seconds': float(np.mean(time_gaps)) if len(time_gaps) > 0 else 0.0,
                        'expected_interval': expected_interval
                    }
                else:
                    completeness_metrics['temporal'] = {'completeness_ratio': 0.0}
                    
            except Exception as e:
                self.logger.warning(f"Temporal completeness analysis failed: {e}")
                completeness_metrics['temporal'] = {'completeness_ratio': basic_completeness}
            
            # 4. ML-based data quality assessment
            if hasattr(self, 'data_quality_monitor'):
                try:
                    quality_score = self.data_quality_monitor.assess_data_completeness(
                        signal, signal_type, metadata
                    )
                    
                    completeness_metrics['ml_quality'] = {
                        'completeness_ratio': float(quality_score),
                        'assessment_confidence': 0.8  # Default confidence
                    }
                except Exception as e:
                    self.logger.warning(f"ML quality assessment failed: {e}")
            
            # 5. Real-time validation against network data
            if hasattr(self, 'realtime_data_feeds') and station_id != 'unknown':
                try:
                    network_validation = asyncio.run(
                        self._validate_completeness_with_network(station_id, signal, signal_type)
                    )
                    
                    if network_validation:
                        completeness_metrics['network_validation'] = network_validation
                        
                except Exception as e:
                    self.logger.warning(f"Network validation failed: {e}")
            
            # Ensemble completeness estimate
            completeness_values = []
            weights = []
            
            for method, data in completeness_metrics.items():
                if isinstance(data, dict) and 'completeness_ratio' in data:
                    completeness_values.append(data['completeness_ratio'])
                    
                    # Weight assignment based on method reliability
                    if method == 'basic':
                        weights.append(0.4)
                    elif method == 'physical_range':
                        weights.append(0.3)
                    elif method == 'temporal':
                        weights.append(0.2)
                    elif method == 'ml_quality':
                        weights.append(0.1)
                    else:
                        weights.append(0.05)
            
            if completeness_values:
                weights = np.array(weights[:len(completeness_values)])
                weights = weights / np.sum(weights)  # Normalize
                
                ensemble_completeness = np.average(completeness_values, weights=weights)
                completeness_std = np.sqrt(np.average(
                    (completeness_values - ensemble_completeness)**2, weights=weights
                ))
                confidence = max(0.0, 1.0 - completeness_std)
            else:
                ensemble_completeness = 0.0
                confidence = 0.1
            
            # Store completeness analysis
            if hasattr(self, 'timeseries_db') and station_id != 'unknown':
                asyncio.run(self._store_completeness_analysis({
                    'station_id': station_id,
                    'signal_type': signal_type,
                    'ensemble_completeness': ensemble_completeness,
                    'confidence': confidence,
                    'detailed_metrics': completeness_metrics,
                    'timestamp': datetime.utcnow()
                }))
            
            return {
                'ensemble_completeness': float(ensemble_completeness),
                'confidence': float(confidence),
                'detailed_metrics': completeness_metrics,
                'n_methods': len(completeness_values),
                'signal_type': signal_type,
                'station_id': station_id
            }
            
        except Exception as e:
            self.logger.error(f"Advanced completeness analysis failed: {e}")
            return {'ensemble_completeness': 0.9, 'confidence': 0.1, 'error': str(e)}

    def _compute_outlier_ratio(self, signal: np.ndarray) -> float:
        """Compute outlier ratio using IQR method"""
        try:
            Q1 = np.percentile(signal, 25)
            Q3 = np.percentile(signal, 75)
            IQR = Q3 - Q1
            
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            
            outliers = np.sum((signal < lower_bound) | (signal > upper_bound))
            return float(outliers / len(signal))
            
        except Exception:
            return 0.05

    def _heuristic_quality_scoring(self, quality_metrics: Dict[str, float]) -> float:
        """Heuristic quality scoring when ML models are unavailable"""
        try:
            # Weighted combination of key metrics
            snr_score = min(1.0, quality_metrics.get('snr_welch', 1.0) / 20.0)
            continuity_score = quality_metrics.get('continuity_index', 0.8)
            completeness_score = quality_metrics.get('completeness_ratio', 0.9)
            outlier_penalty = 1.0 - quality_metrics.get('outlier_ratio', 0.05)
            
            heuristic_score = (0.4 * snr_score + 0.25 * continuity_score + 
                             0.2 * completeness_score + 0.15 * outlier_penalty)
            
            return float(np.clip(heuristic_score, 0.0, 1.0))
            
        except Exception:
            return 0.5

    def _compute_metrics_score(self, quality_metrics: Dict[str, float]) -> float:
        """Compute score from quality metrics"""
        return self._heuristic_quality_scoring(quality_metrics)

    def _compute_physics_score(self, physics_constraints: Dict[str, float]) -> float:
        """Compute physics-based quality score"""
        try:
            seismic_band_score = physics_constraints.get('seismic_band_ratio', 0.5)
            amplitude_score = physics_constraints.get('amplitude_constraint', 0.5)
            coherence_score = physics_constraints.get('temporal_coherence', 0.5)
            
            physics_score = (seismic_band_score + amplitude_score + coherence_score) / 3.0
            return float(np.clip(physics_score, 0.0, 1.0))
            
        except Exception:
            return 0.5

    # ===== ADVANCED SNR SUPPORTING METHODS =====
    
    async def _get_historical_snr_data(self, location: Tuple[float, float], signal_type: str) -> Dict[str, Any]:
        """Fetch historical SNR data from database for location-based calibration"""
        try:
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return None
                
            lat, lon = location[:2]
            query = """
            SELECT 
                AVG(ensemble_snr) as avg_snr,
                STDDEV(ensemble_snr) as std_snr,
                COUNT(*) as sample_count,
                MAX(confidence) as max_confidence,
                AVG(confidence) as avg_confidence
            FROM snr_analysis_results 
            WHERE signal_type = %s
            AND ST_DWithin(location::geography, ST_MakePoint(%s, %s)::geography, 10000)
            AND timestamp > NOW() - INTERVAL '30 days'
            """
            
            result = await self.db_manager.execute_query_async(query, (signal_type, lon, lat))
            
            if result and len(result) > 0 and result[0]['sample_count'] > 5:
                return {
                    'historical_avg_snr': float(result[0]['avg_snr']),
                    'historical_std_snr': float(result[0]['std_snr']),
                    'sample_count': int(result[0]['sample_count']),
                    'avg_confidence': float(result[0]['avg_confidence'])
                }
            return None
            
        except Exception as e:
            self.logger.warning(f"Failed to fetch historical SNR data: {e}")
            return None
    
    def _apply_location_calibration(self, snr_estimates: Dict, historical_data: Dict) -> Dict:
        """Apply location-specific calibration based on historical data"""
        try:
            calibration_factor = historical_data['historical_avg_snr'] / 10.0  # Normalize
            
            for method, estimates in snr_estimates.items():
                if isinstance(estimates, dict):
                    for key, value in estimates.items():
                        if isinstance(value, (int, float)) and 'snr' in key.lower():
                            estimates[key] = float(value * calibration_factor)
                            
            return snr_estimates
            
        except Exception as e:
            self.logger.warning(f"Location calibration failed: {e}")
            return snr_estimates
    
    async def _get_real_time_noise_conditions(self, location: Tuple[float, float]) -> Dict[str, Any]:
        """Get real-time noise conditions from external data sources"""
        try:
            if not hasattr(self, 'external_data_connectors'):
                return None
                
            lat, lon = location[:2]
            noise_data = {}
            
            # Get weather conditions that affect noise levels
            try:
                weather_connector = self.external_data_connectors.get('NOAA')
                if weather_connector:
                    weather = await weather_connector.get_current_weather(lat, lon)
                    if weather:
                        # Wind affects seismic noise
                        wind_speed = weather.get('wind_speed', 0)
                        noise_factor = 1.0 + (wind_speed / 20.0)  # Increase noise with wind
                        noise_data['weather_noise_factor'] = noise_factor
                        
            except Exception as e:
                self.logger.warning(f"Weather noise conditions failed: {e}")
            
            # Get cultural noise indicators
            try:
                # Urban areas have higher cultural noise
                population_density = await self._get_population_density(lat, lon)
                if population_density:
                    cultural_noise = min(2.0, population_density / 1000)  # Cap at 2x
                    noise_data['cultural_noise_factor'] = cultural_noise
                    
            except Exception as e:
                self.logger.warning(f"Cultural noise assessment failed: {e}")
            
            return noise_data if noise_data else None
            
        except Exception as e:
            self.logger.warning(f"Real-time noise conditions failed: {e}")
            return None
    
    def _apply_noise_correction(self, snr_estimates: Dict, noise_conditions: Dict) -> Dict:
        """Apply noise condition corrections to SNR estimates"""
        try:
            total_noise_factor = 1.0
            
            # Accumulate noise factors
            for factor_name, factor_value in noise_conditions.items():
                if 'factor' in factor_name and isinstance(factor_value, (int, float)):
                    total_noise_factor *= factor_value
            
            # Apply inverse correction (higher noise = lower effective SNR)
            correction_factor = 1.0 / (total_noise_factor + 1e-10)
            
            for method, estimates in snr_estimates.items():
                if isinstance(estimates, dict):
                    for key, value in estimates.items():
                        if isinstance(value, (int, float)) and 'snr' in key.lower():
                            estimates[key] = float(value * correction_factor)
                            
            return snr_estimates
            
        except Exception as e:
            self.logger.warning(f"Noise correction failed: {e}")
            return snr_estimates
    
    def _ml_enhanced_snr_estimation(self, signal: np.ndarray, snr_estimates: Dict, metadata: Dict) -> Dict:
        """ML-enhanced SNR estimation using trained models"""
        try:
            if not hasattr(self, 'model_manager') or not self.model_manager:
                return None
                
            # Extract features for ML model
            features = self._extract_snr_features(signal, snr_estimates, metadata)
            
            # Get ML model prediction
            model_name = f"snr_estimator_{metadata.get('signal_type', 'generic')}"
            
            try:
                prediction = self.model_manager.predict(
                    model_name, features, return_uncertainty=True
                )
                
                if prediction:
                    return {
                        'ml_snr_estimate': float(prediction['prediction']),
                        'ml_uncertainty': float(prediction.get('uncertainty', 0.1)),
                        'model_confidence': float(prediction.get('confidence', 0.8)),
                        'feature_importance': prediction.get('feature_importance', {})
                    }
                    
            except Exception as e:
                self.logger.warning(f"ML model prediction failed: {e}")
                
            return None
            
        except Exception as e:
            self.logger.warning(f"ML enhanced SNR estimation failed: {e}")
            return None
    
    def _extract_snr_features(self, signal: np.ndarray, snr_estimates: Dict, metadata: Dict) -> Dict:
        """Extract features for ML SNR estimation"""
        try:
            features = {}
            
            # Signal statistics
            features['signal_mean'] = float(np.mean(signal))
            features['signal_std'] = float(np.std(signal))
            features['signal_skew'] = float(stats.skew(signal))
            features['signal_kurtosis'] = float(stats.kurtosis(signal))
            features['signal_length'] = len(signal)
            
            # Metadata features
            if metadata:
                features['sampling_rate'] = metadata.get('sampling_rate', 100)
                features['signal_type_encoded'] = self._encode_signal_type(metadata.get('signal_type', 'unknown'))
                
                if 'location' in metadata and metadata['location']:
                    lat, lon = metadata['location'][:2]
                    features['latitude'] = lat
                    features['longitude'] = lon
            
            # SNR estimate features
            for method, estimates in snr_estimates.items():
                if isinstance(estimates, dict):
                    for key, value in estimates.items():
                        if isinstance(value, (int, float)):
                            features[f'{method}_{key}'] = float(value)
            
            return features
            
        except Exception as e:
            self.logger.warning(f"Feature extraction failed: {e}")
            return {}
    
    def _encode_signal_type(self, signal_type: str) -> int:
        """Encode signal type for ML features"""
        encoding = {
            'seismic': 1,
            'magnetic': 2,
            'electromagnetic': 3,
            'gravity': 4,
            'temperature': 5,
            'pressure': 6
        }
        return encoding.get(signal_type.lower(), 0)
    
    async def _store_snr_analysis(self, analysis_data: Dict):
        """Store SNR analysis results in database"""
        try:
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return
                
            # Create table if not exists
            create_table_query = """
            CREATE TABLE IF NOT EXISTS snr_analysis_results (
                id SERIAL PRIMARY KEY,
                location GEOGRAPHY(POINTZ, 4326),
                signal_type VARCHAR(50),
                ensemble_snr REAL,
                confidence REAL,
                detailed_results JSONB,
                timestamp TIMESTAMP DEFAULT NOW()
            );
            
            CREATE INDEX IF NOT EXISTS idx_snr_location ON snr_analysis_results USING GIST (location);
            CREATE INDEX IF NOT EXISTS idx_snr_type ON snr_analysis_results (signal_type);
            CREATE INDEX IF NOT EXISTS idx_snr_timestamp ON snr_analysis_results (timestamp);
            """
            
            await self.db_manager.execute_query_async(create_table_query)
            
            # Insert analysis data
            if analysis_data.get('location'):
                lat, lon = analysis_data['location'][:2]
                alt = analysis_data['location'][2] if len(analysis_data['location']) > 2 else 0
                
                insert_query = """
                INSERT INTO snr_analysis_results (location, signal_type, ensemble_snr, confidence, detailed_results)
                VALUES (ST_MakePoint(%s, %s, %s), %s, %s, %s, %s)
                """
                
                await self.db_manager.execute_query_async(insert_query, (
                    lon, lat, alt,
                    analysis_data['signal_type'],
                    analysis_data['ensemble_snr'],
                    analysis_data['confidence'],
                    json.dumps(analysis_data['detailed_results'])
                ))
                
        except Exception as e:
            self.logger.warning(f"Failed to store SNR analysis: {e}")
    
