    async def _fetch_seismic_tomography_models(self) -> Dict[str, Any]:
        """Fetch multiple seismic tomography models for velocity perturbations"""
        try:
            from .external_data_connectors import TomographyConnector
            
            tomo_connector = TomographyConnector()
            tomography_models = {}
            
            model_names = ['LLNL-G3Dv3', 'S40RTS', 'SAVANI']
            depths = [100, 200, 400, 600]
            
            for model_name in model_names:
                try:
                    model_data = {}
                    for depth in depths:
                        depth_data = await tomo_connector.query_mantle_structure(0, 0, depth_km=depth)
                        if depth_data:
                            model_data[f'depth_{depth}km'] = depth_data
                    
                    if model_data:
                        tomography_models[model_name] = model_data
                except Exception:
                    continue
            
            return {
                'available_models': list(tomography_models.keys()),
                'velocity_perturbations': tomography_models
            }
            
        except Exception as e:
            self.logger.error(f"Error fetching seismic tomography models: {e}")
            return {}
    
    async def _query_validated_crustal_measurements(self, db_integration) -> Dict[str, Any]:
        """Query database for validated crustal structure measurements"""
        try:
            measurement_query = """
            SELECT 
                ST_X(gs.location::geometry) as longitude,
                ST_Y(gs.location::geometry) as latitude,
                ST_Z(gs.location::geometry) as depth_km,
                gs.structure_type,
                gs.lithology,
                rmp.density_kg_m3,
                rmp.elastic_modulus_gpa,
                gs.data_quality_score
            FROM geological_structures gs
            LEFT JOIN rock_mechanical_properties rmp ON gs.lithology = rmp.lithology
            WHERE gs.data_quality_score > 0.7
            AND gs.structure_type IN ('moho', 'conrad', 'layer', 'basement')
            ORDER BY gs.data_quality_score DESC
            LIMIT 1000
            """
            
            results = await db_integration.execute_query_async(measurement_query)
            
            return {
                'total_measurements': len(results),
                'crustal_measurements': results
            }
            
        except Exception as e:
            self.logger.error(f"Error querying validated crustal measurements: {e}")
            return {}
    
