    async def _fetch_heterogeneity_data(self) -> List[Dict]:
        """Fetch heterogeneity data from geological databases"""
        try:
            from .database_integration import DatabaseIntegration, DatabaseConfig
            
            db_config = DatabaseConfig(
                host=os.getenv('POSTGRES_HOST', 'localhost'),
                database=os.getenv('POSTGRES_DB', 'prometheus_geo'),
                username=os.getenv('POSTGRES_USER', 'prometheus_user'),
                password=os.getenv('POSTGRES_PASSWORD', 'prometheus_password')
            )
            db_integration = DatabaseIntegration(db_config)
            
            # Query geological structures that create velocity heterogeneities
            heterogeneity_query = """
            SELECT 
                structure_id,
                structure_type,
                lithology,
                ST_X(location::geometry) as longitude,
                ST_Y(location::geometry) as latitude,
                ST_Z(location::geometry) as depth_km,
                ST_Area(location::geography) / 1000000 as area_km2,
                properties,
                strike,
                dip,
                age
            FROM geological_structures 
            WHERE structure_type IN (
                'fault_zone', 'fracture_zone', 'intrusion', 'dike', 'sill',
                'contact_zone', 'alteration_zone', 'mineralization', 'fluid_inclusion'
            )
            AND ST_Z(location::geometry) BETWEEN 0 AND 70  -- Crustal depths
            ORDER BY ST_Z(location::geometry), area_km2 DESC
            LIMIT 200
            """
            
            geological_heterogeneities = await db_integration.execute_query_async(heterogeneity_query)
            
            # Query rock property variations
            variation_query = """
            SELECT 
                formation_id,
                lithology,
                STDDEV(elastic_modulus_gpa) as elastic_std,
                STDDEV(density_kg_m3) as density_std,
                STDDEV(porosity) as porosity_std,
                COUNT(*) as sample_count,
                AVG(ST_Z(sample_location::geometry)) as avg_depth,
                ST_ConvexHull(ST_Collect(sample_location::geometry)) as spatial_extent
            FROM rock_mechanical_properties
            WHERE data_quality_grade IN ('A', 'B')
            GROUP BY formation_id, lithology
            HAVING COUNT(*) > 3 AND STDDEV(elastic_modulus_gpa) > 5.0
            ORDER BY STDDEV(elastic_modulus_gpa) DESC
            """
            
            property_variations = await db_integration.execute_query_async(variation_query)
            
            # Query volcanic features for thermal heterogeneities
            volcanic_heterogeneity_query = """
            SELECT 
                chamber_id,
                'thermal_anomaly' as heterogeneity_type,
                ST_X(location::geometry) as longitude,
                ST_Y(location::geometry) as latitude,
                chamber_depth_km,
                chamber_volume_km3,
                temperature_c,
                melt_fraction,
                chamber_shape
            FROM volcanic_chambers
            WHERE temperature_c > 700  -- High temperature anomalies
            UNION ALL
            SELECT 
                zone_id,
                'stress_anomaly' as heterogeneity_type,
                ST_X(location::geometry) as longitude,
                ST_Y(location::geometry) as latitude,
                depth_km,
                NULL as chamber_volume_km3,
                NULL as temperature_c,
                NULL as melt_fraction,
                failure_mechanism as chamber_shape
            FROM critical_failure_zones
            WHERE stress_ratio > 0.8  -- High stress zones
            """
            
            volcanic_thermal = await db_integration.execute_query_async(volcanic_heterogeneity_query)
            
            # Process and combine heterogeneity data
            heterogeneities = []
            
            # Process geological structure heterogeneities
            for struct in geological_heterogeneities:
                heterogeneity = self._process_structural_heterogeneity(struct)
                if heterogeneity:
                    heterogeneities.append(heterogeneity)
            
            # Process property variation heterogeneities
            for variation in property_variations:
                heterogeneity = self._process_property_variation_heterogeneity(variation)
                if heterogeneity:
                    heterogeneities.append(heterogeneity)
            
            # Process thermal heterogeneities
            for thermal in volcanic_thermal:
                heterogeneity = self._process_thermal_heterogeneity(thermal)
                if heterogeneity:
                    heterogeneities.append(heterogeneity)
            
            return heterogeneities
            
        except Exception as e:
            self.logger.error(f"Error fetching heterogeneity data: {e}")
            return []
    
    def _process_structural_heterogeneity(self, struct: Dict) -> Dict:
        """Process structural heterogeneity from geological structure"""
        try:
            structure_type = struct['structure_type']
            lithology = struct.get('lithology', 'unknown')
            depth = float(struct.get('depth_km', 0))
            
            # Calculate velocity perturbations based on structure type
            velocity_perturbations = {
                'fault_zone': {'vp_change': -0.15, 'vs_change': -0.20, 'density_change': -0.05},
                'fracture_zone': {'vp_change': -0.10, 'vs_change': -0.15, 'density_change': -0.03},
                'intrusion': {'vp_change': 0.08, 'vs_change': 0.10, 'density_change': 0.05},
                'dike': {'vp_change': 0.12, 'vs_change': 0.15, 'density_change': 0.08},
                'alteration_zone': {'vp_change': -0.08, 'vs_change': -0.12, 'density_change': -0.02},
                'contact_zone': {'vp_change': 0.05, 'vs_change': 0.07, 'density_change': 0.03}
            }
            
            perturbation = velocity_perturbations.get(structure_type, 
                                                    {'vp_change': 0.0, 'vs_change': 0.0, 'density_change': 0.0})
            
            # Calculate spatial extent
            area_km2 = float(struct.get('area_km2', 1.0))
            characteristic_length = np.sqrt(area_km2)  # km
            
            return {
                'heterogeneity_id': struct['structure_id'],
                'type': 'structural',
                'subtype': structure_type,
                'location': {
                    'longitude': float(struct.get('longitude', 0)),
                    'latitude': float(struct.get('latitude', 0)),
                    'depth_km': depth
                },
                'spatial_extent': {
                    'characteristic_length_km': characteristic_length,
                    'area_km2': area_km2,
                    'depth_extent_km': max(0.5, characteristic_length * 0.2)
                },
                'velocity_perturbations': perturbation,
                'lithology': lithology,
                'properties': struct.get('properties', {}),
                'orientation': {
                    'strike': struct.get('strike'),
                    'dip': struct.get('dip')
                },
                'age_ma': struct.get('age'),
                'confidence': 0.8
            }
            
        except Exception as e:
            self.logger.error(f"Error processing structural heterogeneity: {e}")
            return None
    
    def _process_property_variation_heterogeneity(self, variation: Dict) -> Dict:
        """Advanced heterogeneity processing with real data integration and ML predictions"""
        import asyncio
