    def _extract_crustal_heterogeneities(self, structures: List[Dict], chambers: List[Dict]) -> List[Dict]:
        """Extract heterogeneities from structural and volcanic data"""
        try:
            heterogeneities = []
            
            # Process geological structures
            for struct in structures:
                if struct.get('structure_type') in ['fault_zone', 'fracture_zone', 'intrusion']:
                    heterogeneity = self._process_structural_heterogeneity(struct)
                    if heterogeneity:
                        heterogeneities.append(heterogeneity)
            
            # Process volcanic chambers
            for chamber in chambers:
                thermal_data = {
                    'chamber_id': chamber['chamber_id'],
                    'heterogeneity_type': 'thermal_anomaly',
                    'longitude': chamber['longitude'],
                    'latitude': chamber['latitude'],
                    'chamber_depth_km': chamber['chamber_depth_km'],
                    'chamber_volume_km3': chamber['chamber_volume_km3'],
                    'temperature_c': chamber['temperature_c'],
                    'melt_fraction': chamber['melt_fraction']
                }
                
                heterogeneity = self._process_thermal_heterogeneity(thermal_data)
                if heterogeneity:
                    heterogeneities.append(heterogeneity)
            
            return heterogeneities
            
        except Exception as e:
            self.logger.error(f"Error extracting crustal heterogeneities: {e}")
            return []

