    def _calculate_epicentral_distance(self, eq_params: Dict) -> float:
        """Calculate accurate epicentral distance using geodetic methods"""
        try:
            # Get earthquake coordinates
            eq_lat = float(eq_params.get('latitude', 0.0))
            eq_lon = float(eq_params.get('longitude', 0.0))
            eq_depth = float(eq_params.get('depth_km', 0.0))
            
            # Get receiver/station coordinates (would be from monitoring network)
            receiver_coords = self._get_receiver_coordinates()
            
            if not receiver_coords:
                # Fallback: use regional average distance
                return self._estimate_regional_distance(eq_params)
            
            # Calculate distances to all receivers and return minimum or average
            distances = []
            
            for receiver in receiver_coords:
                recv_lat = receiver['latitude']
                recv_lon = receiver['longitude']
                recv_elevation = receiver.get('elevation_km', 0.0)
                
                # Calculate great circle distance using geodetic methods
                surface_distance = self._calculate_great_circle_distance(
                    eq_lat, eq_lon, recv_lat, recv_lon
                )
                
                # Calculate 3D distance including depth
                depth_difference = eq_depth + recv_elevation  # Both relative to sea level
                total_distance = np.sqrt(surface_distance**2 + depth_difference**2)
                
                distances.append(total_distance)
            
            # Return minimum distance (closest receiver)
            return min(distances) if distances else 100.0
            
        except Exception as e:
            self.logger.error(f"Error calculating epicentral distance: {e}")
            return 100.0  # Fallback
    
    def _calculate_great_circle_distance(self, lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Calculate great circle distance using Haversine formula"""
        try:
            # Convert degrees to radians
            lat1_rad = np.radians(lat1)
            lon1_rad = np.radians(lon1)
            lat2_rad = np.radians(lat2)
            lon2_rad = np.radians(lon2)
            
            # Haversine formula
            dlat = lat2_rad - lat1_rad
            dlon = lon2_rad - lon1_rad
            
            a = (np.sin(dlat/2)**2 + 
                 np.cos(lat1_rad) * np.cos(lat2_rad) * np.sin(dlon/2)**2)
            
            c = 2 * np.arcsin(np.sqrt(a))
            
            # Earth's radius in kilometers
            earth_radius_km = 6371.0
            
            distance = earth_radius_km * c
            return distance
            
        except Exception as e:
            self.logger.error(f"Error calculating great circle distance: {e}")
            return 100.0

