    def _analyze_earthquake_anisotropy(self, earthquakes: List, lat: float, lon: float) -> Dict[str, float]:
        """Analyze earthquake data for stress-induced anisotropy patterns"""
        try:
            if not earthquakes:
                return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
            
            import numpy as np
            from scipy import stats
            
            # Extract focal mechanisms and stress orientations
            stress_orientations = []
            magnitudes = []
            
            for eq in earthquakes:
                if hasattr(eq, 'properties'):
                    props = eq.properties
                    mag = props.get('magnitude', 0.0)
                    if mag > 3.0:  # Focus on significant earthquakes
                        magnitudes.append(mag)
                        
                        # Estimate stress orientation from earthquake location patterns
                        eq_lat = eq.coordinates[0] if hasattr(eq, 'coordinates') else 0
                        eq_lon = eq.coordinates[1] if hasattr(eq, 'coordinates') else 0
                        
                        # Calculate relative position and infer stress direction
                        dx = eq_lon - lon
                        dy = eq_lat - lat
                        azimuth = np.arctan2(dx, dy) * 180 / np.pi
                        stress_orientations.append(azimuth)
            
            if not stress_orientations:
                return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
            
            # Statistical analysis of stress patterns
            orientations = np.array(stress_orientations)
            mags = np.array(magnitudes)
            
            # Calculate anisotropy from stress alignment
            circular_variance = stats.circvar(np.radians(orientations))
            stress_intensity = np.mean(mags) / 10.0  # Normalize
            
            # Convert to Thomsen parameters
            epsilon = min(0.15, circular_variance * stress_intensity * 0.1)
            gamma = min(0.20, circular_variance * stress_intensity * 0.15)
            delta = min(0.12, circular_variance * stress_intensity * 0.08)
            
            confidence = min(1.0, len(earthquakes) / 50.0)
            
            return {
                'epsilon': epsilon,
                'gamma': gamma,
                'delta': delta,
                'confidence': confidence,
                'earthquake_count': len(earthquakes),
                'mean_magnitude': float(np.mean(mags))
            }
            
        except Exception as e:
            self.logger.error(f"Error analyzing earthquake anisotropy: {e}")
            return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
    
    def _analyze_mineral_resource_anisotropy(self, mineral_resources: List, lat: float, lon: float) -> Dict[str, float]:
        """Analyze mineral resource distribution for structural anisotropy"""
        try:
            if not mineral_resources:
                return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
            
            import numpy as np
            from sklearn.cluster import DBSCAN
            
            # Extract mineral types and locations
            resource_data = []
            for resource in mineral_resources:
                if hasattr(resource, 'coordinates') and hasattr(resource, 'properties'):
                    coords = resource.coordinates
                    props = resource.properties
                    
                    resource_data.append({
                        'lat': coords[0],
                        'lon': coords[1],
                        'type': props.get('commodity', 'unknown'),
                        'host_rock': props.get('host_rock_type', 'unknown'),
                        'deposit_type': props.get('deposit_type', 'unknown')
                    })
            
            if not resource_data:
                return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
            
            # Analyze spatial clustering and orientations
            coords = np.array([[r['lat'], r['lon']] for r in resource_data])
            
            # DBSCAN clustering to identify structural trends
            clustering = DBSCAN(eps=0.1, min_samples=2)
            cluster_labels = clustering.fit_predict(coords)
            
            # Calculate structural orientations from clusters
            orientations = []
            for cluster_id in set(cluster_labels):
                if cluster_id != -1:  # Ignore noise
                    cluster_coords = coords[cluster_labels == cluster_id]
                    if len(cluster_coords) >= 2:
                        # Principal component analysis for trend direction
                        from sklearn.decomposition import PCA
                        pca = PCA(n_components=1)
                        pca.fit(cluster_coords)
                        
                        # Get orientation angle
                        principal_direction = pca.components_[0]
                        angle = np.arctan2(principal_direction[1], principal_direction[0]) * 180 / np.pi
                        orientations.append(angle)
            
            # Convert structural trends to anisotropy parameters
            if orientations:
                orientation_variance = np.var(orientations)
                structural_complexity = len(set(cluster_labels)) / len(resource_data)
                
                epsilon = min(0.12, orientation_variance * structural_complexity * 0.001)
                gamma = min(0.18, orientation_variance * structural_complexity * 0.0015)
                delta = min(0.10, orientation_variance * structural_complexity * 0.0008)
                
                confidence = min(1.0, len(resource_data) / 20.0)
            else:
                epsilon = gamma = delta = confidence = 0.0
            
            return {
                'epsilon': epsilon,
                'gamma': gamma,
                'delta': delta,
                'confidence': confidence,
                'resource_count': len(resource_data),
                'cluster_count': len(set(cluster_labels))
            }
            
        except Exception as e:
            self.logger.error(f"Error analyzing mineral resource anisotropy: {e}")
            return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0, 'confidence': 0.0}
    
