    def _calculate_orientation_tensor(self, structural_data: List[Dict]) -> Dict[str, float]:
        """Calculate 3D orientation tensor from structural measurements"""
        try:
            if not structural_data:
                return {'eigenvalue_1': 0.33, 'eigenvalue_2': 0.33, 'eigenvalue_3': 0.33}
            
            import numpy as np
            
            # Convert structural measurements to 3D unit vectors
            vectors = []
            for measurement in structural_data:
                strike = measurement.get('strike')
                dip = measurement.get('dip')
                
                if strike is not None and dip is not None:
                    # Convert to 3D vector representation
                    strike_rad = np.radians(strike)
                    dip_rad = np.radians(dip)
                    
                    # Calculate normal vector to plane
                    x = np.sin(dip_rad) * np.sin(strike_rad)
                    y = np.sin(dip_rad) * np.cos(strike_rad)
                    z = np.cos(dip_rad)
                    
                    vectors.append([x, y, z])
            
            if not vectors:
                return {'eigenvalue_1': 0.33, 'eigenvalue_2': 0.33, 'eigenvalue_3': 0.33}
            
            # Calculate orientation tensor
            vectors = np.array(vectors)
            orientation_tensor = np.zeros((3, 3))
            
            for v in vectors:
                orientation_tensor += np.outer(v, v)
            
            orientation_tensor /= len(vectors)
            
            # Calculate eigenvalues and eigenvectors
            eigenvalues, eigenvectors = np.linalg.eigh(orientation_tensor)
            
            # Sort by eigenvalue magnitude
            idx = np.argsort(eigenvalues)[::-1]
            eigenvalues = eigenvalues[idx]
            
            return {
                'eigenvalue_1': float(eigenvalues[0]),
                'eigenvalue_2': float(eigenvalues[1]),
                'eigenvalue_3': float(eigenvalues[2]),
                'anisotropy_degree': float(eigenvalues[0] - eigenvalues[2]),
                'sample_count': len(vectors)
            }
            
        except Exception as e:
            self.logger.error(f"Error calculating orientation tensor: {e}")
            return {'eigenvalue_1': 0.33, 'eigenvalue_2': 0.33, 'eigenvalue_3': 0.33}
    
