    def _integrate_anisotropy_estimates(self, estimates: Dict[str, Dict]) -> Dict[str, float]:
        """Integrate multiple anisotropy estimates with uncertainty weighting"""
        try:
            import numpy as np
            
            # Extract estimates and confidences
            epsilon_values = []
            gamma_values = []
            delta_values = []
            weights = []
            
            for source, estimate in estimates.items():
                if isinstance(estimate, dict) and 'epsilon' in estimate:
                    confidence = estimate.get('confidence', 0.5)
                    if confidence > 0:
                        epsilon_values.append(estimate['epsilon'])
                        gamma_values.append(estimate['gamma'])
                        delta_values.append(estimate['delta'])
                        weights.append(confidence)
            
            if not weights:
                return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0}
            
            # Weighted average
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize
            
            integrated_epsilon = np.average(epsilon_values, weights=weights)
            integrated_gamma = np.average(gamma_values, weights=weights)  
            integrated_delta = np.average(delta_values, weights=weights)
            
            # Calculate overall confidence
            overall_confidence = np.sum(weights * np.array([e.get('confidence', 0.5) for e in estimates.values() if isinstance(e, dict)]))
            overall_confidence = min(1.0, overall_confidence / len(estimates))
            
            return {
                'epsilon': float(integrated_epsilon),
                'gamma': float(integrated_gamma),
                'delta': float(integrated_delta),
                'confidence': float(overall_confidence),
                'integration_method': 'weighted_average',
                'source_count': len(estimates)
            }
            
        except Exception as e:
            self.logger.error(f"Error integrating anisotropy estimates: {e}")
            return {'epsilon': 0.0, 'gamma': 0.0, 'delta': 0.0}
    
    def _validate_anisotropy_estimates(self, anisotropy: Dict[str, float], lat: float, lon: float) -> Dict[str, float]:
        """Validate anisotropy estimates against physical constraints and regional models"""
        try:
            validated = anisotropy.copy()
            
            # Physical constraints for crustal anisotropy
            max_constraints = {
                'epsilon': 0.25,  # Maximum 25% P-wave anisotropy
                'gamma': 0.35,    # Maximum 35% S-wave anisotropy
                'delta': 0.20     # Maximum 20% delta parameter
            }
            
            # Apply constraints
            for param, max_val in max_constraints.items():
                if param in validated:
                    validated[param] = max(0.0, min(max_val, validated[param]))
            
            # Physical relationships (Thomsen parameters)
            if 'epsilon' in validated and 'gamma' in validated and 'delta' in validated:
                # Typically gamma >= epsilon for most rock types
                if validated['gamma'] < validated['epsilon']:
                    validated['gamma'] = validated['epsilon'] * 1.2
                
                # Delta usually between 0 and epsilon
                validated['delta'] = max(0.0, min(validated['epsilon'], validated['delta']))
            
            # Add validation metadata
            validated['validation_applied'] = True
            validated['validation_timestamp'] = datetime.now().isoformat()
            
            return validated
            
        except Exception as e:
            self.logger.error(f"Error validating anisotropy estimates: {e}")
            return anisotropy
    
