                    def _query_usgs_comprehensive_catalog(self):
                        """Query USGS comprehensive earthquake catalog."""
                        import requests
                        
                        # Real API call to USGS
                        base_url = "https://earthquake.usgs.gov/fdsnws/event/1/query"
                        params = {
                            'format': 'geojson',
                            'starttime': '1960-01-01',
                            'minmagnitude': 3.0,
                            'includeallorigins': 'true',
                            'includeallmagnitudes': 'true',
                            'orderby': 'time-asc'
                        }
                        
                        try:
                            response = requests.get(base_url, params=params, timeout=30)
                            if response.status_code == 200:
                                return response.json()
                            else:
                                # Fallback to local cached data
                                return self._load_cached_earthquake_data()
                        except:
                            return self._load_cached_earthquake_data()
                    
