                    def _process_nga_records(self, nga_data: dict) -> list:
                        """Process and validate NGA-West2 records."""
                        processed_records = []
                        
                        for record in nga_data.get('records', []):
                            try:
                                processed_record = {
                                    'record_id': record.get('record_id'),
                                    'earthquake_id': record.get('earthquake_id'),
                                    'station_id': record.get('station_id'),
                                    'magnitude': float(record.get('magnitude', 0)),
                                    'distance_rrup': float(record.get('distance_rrup', 0)),
                                    'distance_rjb': float(record.get('distance_rjb', 0)),
                                    'vs30': float(record.get('vs30', 0)),
                                    'pga': float(record.get('pga', 0)),
                                    'pgv': float(record.get('pgv', 0)),
                                    'sa_periods': record.get('sa_periods', []),
                                    'sa_values': record.get('sa_values', []),
                                    'fault_type': record.get('fault_type', 'unknown'),
                                    'site_class': record.get('site_class', 'unknown'),
                                    'coordinates': {
                                        'latitude': float(record.get('latitude', 0)),
                                        'longitude': float(record.get('longitude', 0)),
                                        'depth': float(record.get('depth', 0))
                                    },
                                    'quality_metrics': {
                                        'signal_to_noise': record.get('snr', 0),
                                        'data_quality': record.get('quality_flag', 'unknown'),
                                        'processing_level': record.get('processing_level', 'raw')
                                    }
                                }
                                
                                # Validate record completeness
                                if self._validate_nga_record(processed_record):
                                    processed_records.append(processed_record)
                                    
                            except (ValueError, KeyError) as e:
                                self.logger.warning(f"Skipped invalid NGA record: {e}")
                                continue
                                
                        return processed_records
                        
                    def _validate_nga_record(self, record: dict) -> bool:
                        """Validate NGA record completeness and physical constraints."""
                        required_fields = ['magnitude', 'distance_rrup', 'vs30', 'pga']
                        
                        # Check required fields
                        for field in required_fields:
                            if field not in record or record[field] <= 0:
                                return False
                                
                        # Physical constraint validation
                        if not (3.0 <= record['magnitude'] <= 9.0):
                            return False
                        if not (0.1 <= record['distance_rrup'] <= 500.0):
                            return False
                        if not (50 <= record['vs30'] <= 2500):
                            return False
                            
                        return True
                        
                    def _calculate_parameter_range(self, records: list, parameter: str) -> list:
                        """Calculate parameter range from records with statistical validation."""
                        values = []
                        for record in records:
                            if isinstance(record, dict) and record.get(parameter) is not None:
                                try:
                                    val = float(record[parameter])
                                    if not np.isnan(val) and not np.isinf(val):
                                        values.append(val)
                                except (ValueError, TypeError):
                                    continue
                                    
                        if values:
                            # Remove outliers using IQR method
                            q1, q3 = np.percentile(values, [25, 75])
                            iqr = q3 - q1
                            lower_bound = q1 - 1.5 * iqr
                            upper_bound = q3 + 1.5 * iqr
                            
                            filtered_values = [v for v in values if lower_bound <= v <= upper_bound]
                            
                            if filtered_values:
                                return [min(filtered_values), max(filtered_values)]
                            else:
                                return [min(values), max(values)]
                        return [0, 0]
                        
