class PerformanceAlertSystem:
    """Advanced ML-based performance alerting with multi-level detection and adaptive thresholds."""
    
    def __init__(self, config: Optional[Dict] = None):
        self.config = config or {}
        self.alert_history = deque(maxlen=10000)
        self.performance_history = deque(maxlen=50000)
        
        # Multi-level alert configuration
        self.alert_levels = {
            'info': {'priority': 1, 'threshold': 0.3, 'cooldown': 300},      # 5 minutes
            'warning': {'priority': 2, 'threshold': 0.5, 'cooldown': 600},   # 10 minutes  
            'critical': {'priority': 3, 'threshold': 0.7, 'cooldown': 900},  # 15 minutes
            'emergency': {'priority': 4, 'threshold': 0.9, 'cooldown': 1800} # 30 minutes
        }
        
        # Alert detection models
        self.anomaly_detectors = self._initialize_anomaly_detectors()
        self.trend_detectors = self._initialize_trend_detectors()
        self.threshold_detectors = self._initialize_threshold_detectors()
        
        # Adaptive threshold management
        self.adaptive_thresholds = {}
        self.threshold_history = deque(maxlen=1000)
        self.false_positive_tracker = {}
        
        # Performance baseline tracking
        self.baseline_calculator = self._initialize_baseline_calculator()
        self.performance_baselines = {}
        self.baseline_update_frequency = 1000  # Update every 1000 samples
        
        # Alert suppression and correlation
        self.alert_correlations = {}
        self.alert_suppressions = {}
        self.correlation_window = 3600  # 1 hour correlation window
        
        # Machine learning models for alert prediction
        self.alert_predictors = self._initialize_alert_predictors()
        
        self.logger = logging.getLogger(__name__)
        self.logger.info("Advanced PerformanceAlertSystem initialized")
    
    def _initialize_anomaly_detectors(self) -> Dict[str, Any]:
        """Initialize ML-based anomaly detection models."""
        detectors = {}
        
        try:
            from sklearn.ensemble import IsolationForest
            from sklearn.neighbors import LocalOutlierFactor
            from sklearn.svm import OneClassSVM
            from sklearn.covariance import EllipticEnvelope
            
            detectors.update({
                'isolation_forest': IsolationForest(
                    contamination=0.05, 
                    random_state=42, 
                    n_estimators=200,
                    max_features=1.0
                ),
                'local_outlier_factor': LocalOutlierFactor(
                    contamination=0.05,
                    n_neighbors=20,
                    algorithm='auto'
                ),
                'one_class_svm': OneClassSVM(
                    kernel='rbf',
                    gamma='scale',
                    nu=0.05
                ),
                'elliptic_envelope': EllipticEnvelope(
                    contamination=0.05,
                    random_state=42
                )
            })
        except ImportError:
            self.logger.warning("Scikit-learn unavailable for anomaly detection")
        
        # Statistical anomaly detectors (always available)
        detectors.update({
            'z_score_detector': self._create_zscore_detector(),
            'iqr_detector': self._create_iqr_detector(),
            'grubbs_detector': self._create_grubbs_detector(),
            'modified_zscore_detector': self._create_modified_zscore_detector()
        })
        
        return detectors
    
    def _initialize_trend_detectors(self) -> Dict[str, Any]:
        """Initialize trend-based alert detection systems."""
        return {
            'mann_kendall_detector': self._create_mann_kendall_detector(),
            'cusum_detector': self._create_cusum_detector(),
            'exponential_smoothing_detector': self._create_exponential_smoothing_detector(),
            'changepoint_detector': self._create_changepoint_detector(),
            'regime_change_detector': self._create_regime_change_detector()
        }
    
    def _initialize_threshold_detectors(self) -> Dict[str, Any]:
        """Initialize threshold-based detection systems."""
        return {
            'percentile_detector': self._create_percentile_detector(),
            'rolling_statistics_detector': self._create_rolling_statistics_detector(),
            'seasonal_threshold_detector': self._create_seasonal_threshold_detector(),
            'contextual_threshold_detector': self._create_contextual_threshold_detector()
        }
    
    def _initialize_baseline_calculator(self) -> Dict[str, Any]:
        """Initialize performance baseline calculation."""
        return {
            'rolling_baseline': {'window': 1000, 'percentiles': [5, 25, 50, 75, 95]},
            'seasonal_baseline': {'period': 24, 'history_length': 168},  # Daily pattern over week
            'contextual_baseline': {'context_features': ['hour_of_day', 'day_of_week']},
            'adaptive_baseline': {'adaptation_rate': 0.01, 'sensitivity': 0.05}
        }
    
    def _initialize_alert_predictors(self) -> Dict[str, Any]:
        """Initialize ML models for predicting future alerts."""
        predictors = {}
        
        try:
            from sklearn.ensemble import RandomForestClassifier, GradientBoostingClassifier
            from sklearn.linear_model import LogisticRegression
            
            predictors.update({
                'random_forest': RandomForestClassifier(
                    n_estimators=100,
                    max_depth=10,
                    random_state=42
                ),
                'gradient_boosting': GradientBoostingClassifier(
                    n_estimators=50,
                    learning_rate=0.1,
                    random_state=42
                ),
                'logistic_regression': LogisticRegression(
                    random_state=42,
                    max_iter=1000
                )
            })
        except ImportError:
            self.logger.warning("Scikit-learn unavailable for alert prediction")
        
        # Statistical predictors (always available)
        predictors.update({
            'threshold_crossing_predictor': self._create_threshold_crossing_predictor(),
            'trend_extrapolation_predictor': self._create_trend_extrapolation_predictor()
        })
        
        return predictors
    
    def check_action_alerts(self, performance_data: Dict) -> Dict[str, Any]:
        """Comprehensive alert checking using multiple detection methods."""
        timestamp = datetime.now()
        
        # Add performance data to history
        enriched_data = {**performance_data, 'timestamp': timestamp}
        self.performance_history.append(enriched_data)
        
        # Update baselines periodically
        if len(self.performance_history) % self.baseline_update_frequency == 0:
            self._update_performance_baselines()
        
        alert_results = {
            'alerts': [],
            'alert_level': 'normal',
            'alert_scores': {},
            'detection_methods': {},
            'predictions': {},
            'recommendations': []
        }
        
        try:
            # 1. Anomaly-based alerts
            anomaly_alerts = self._detect_anomaly_alerts(enriched_data)
            alert_results['alerts'].extend(anomaly_alerts)
            
            # 2. Trend-based alerts
            trend_alerts = self._detect_trend_alerts(enriched_data)
            alert_results['alerts'].extend(trend_alerts)
            
            # 3. Threshold-based alerts
            threshold_alerts = self._detect_threshold_alerts(enriched_data)
            alert_results['alerts'].extend(threshold_alerts)
            
            # 4. Correlation-based alerts
            correlation_alerts = self._detect_correlation_alerts(enriched_data)
            alert_results['alerts'].extend(correlation_alerts)
            
            # 5. Predictive alerts
            predictive_alerts = self._detect_predictive_alerts(enriched_data)
            alert_results['alerts'].extend(predictive_alerts)
            
            # Consolidate and prioritize alerts
            consolidated_alerts = self._consolidate_alerts(alert_results['alerts'])
            alert_results['alerts'] = consolidated_alerts
            
            # Determine overall alert level
            alert_results['alert_level'] = self._determine_overall_alert_level(consolidated_alerts)
            
            # Generate alert scores
            alert_results['alert_scores'] = self._calculate_alert_scores(consolidated_alerts)
            
            # Add predictions for future alerts
            alert_results['predictions'] = self._predict_future_alerts(enriched_data)
            
            # Generate actionable recommendations
            alert_results['recommendations'] = self._generate_alert_recommendations(
                consolidated_alerts, alert_results['alert_scores']
            )
            
            # Update alert history
            alert_record = {
                'timestamp': timestamp,
                'performance_data': performance_data,
                'alerts': consolidated_alerts,
                'alert_level': alert_results['alert_level'],
                'alert_scores': alert_results['alert_scores']
            }
            self.alert_history.append(alert_record)
            
            # Update adaptive thresholds based on alert outcomes
            self._update_adaptive_thresholds(enriched_data, alert_results)
            
        except Exception as e:
            self.logger.error(f"Alert detection failed: {e}")
            alert_results['alerts'] = [{'type': 'system_error', 'level': 'warning', 'message': f'Alert system error: {str(e)}'}]
            alert_results['alert_level'] = 'warning'
        
        return alert_results
    
    def _detect_anomaly_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts using anomaly detection methods."""
        anomaly_alerts = []
        
        if len(self.performance_history) < 50:
            return anomaly_alerts
        
        # Extract numeric features for ML models
        numeric_data = [self._extract_numeric_features(data) for data in list(self.performance_history)[-100:]]
        current_features = self._extract_numeric_features(enriched_data)
        
        if not numeric_data or not current_features:
            return anomaly_alerts
        
        # Ensure consistent feature dimensions
        feature_dim = len(current_features)
        numeric_data = [features[:feature_dim] if len(features) >= feature_dim 
                       else features + [0] * (feature_dim - len(features)) 
                       for features in numeric_data]
        
        # Run anomaly detection models
        for detector_name, detector in self.anomaly_detectors.items():
            try:
                if detector_name in ['isolation_forest', 'one_class_svm', 'elliptic_envelope'] and hasattr(detector, 'fit'):
                    # Fit on recent data
                    detector.fit(numeric_data)
                    
                    # Score current data
                    anomaly_score = detector.decision_function([current_features])[0]
                    
                    # Convert to probability (model-specific)
                    if detector_name == 'isolation_forest':
                        anomaly_prob = max(0, (0.5 - anomaly_score) / 0.5)
                    else:
                        anomaly_prob = max(0, min(1, (0.5 - anomaly_score) / 1.0))
                    
                    if anomaly_prob > 0.7:
                        anomaly_alerts.append({
                            'type': 'performance_anomaly',
                            'detector': detector_name,
                            'level': 'critical' if anomaly_prob > 0.9 else 'warning',
                            'score': anomaly_prob,
                            'message': f'Performance anomaly detected by {detector_name} (score: {anomaly_prob:.3f})',
                            'timestamp': datetime.now(),
                            'features': current_features
                        })
                
                elif detector_name == 'local_outlier_factor' and hasattr(detector, 'fit_predict'):
                    # LOF requires different handling
                    extended_data = numeric_data + [current_features]
                    outlier_predictions = detector.fit_predict(extended_data)
                    
                    if outlier_predictions[-1] == -1:  # Current point is outlier
                        outlier_scores = detector.negative_outlier_factor_
                        current_score = abs(outlier_scores[-1])
                        normalized_score = min(1.0, current_score / 2.0)
                        
                        if normalized_score > 0.6:
                            anomaly_alerts.append({
                                'type': 'performance_outlier',
                                'detector': detector_name,
                                'level': 'warning' if normalized_score < 0.8 else 'critical',
                                'score': normalized_score,
                                'message': f'Performance outlier detected by LOF (score: {normalized_score:.3f})',
                                'timestamp': datetime.now(),
                                'features': current_features
                            })
                
                elif detector_name in ['z_score_detector', 'iqr_detector', 'modified_zscore_detector']:
                    # Statistical detectors
                    alert_result = self._apply_statistical_detector(detector_name, enriched_data)
                    if alert_result:
                        anomaly_alerts.append(alert_result)
                        
            except Exception as e:
                self.logger.debug(f"Anomaly detector {detector_name} failed: {e}")
        
        return anomaly_alerts
    
    def _detect_trend_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on performance trends."""
        trend_alerts = []
        
        if len(self.performance_history) < 20:
            return trend_alerts
        
        # Analyze trends for numeric metrics
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)) and not key.startswith('timestamp'):
                recent_values = [
                    data.get(key) for data in list(self.performance_history)[-20:] 
                    if data.get(key) is not None and isinstance(data.get(key), (int, float))
                ]
                
                if len(recent_values) >= 10:
                    # Trend analysis using Mann-Kendall test
                    trend_result = self._mann_kendall_test(recent_values)
                    
                    if trend_result['significant'] and abs(trend_result['slope']) > 0.05:
                        trend_direction = 'declining' if trend_result['slope'] < 0 else 'increasing'
                        alert_level = 'warning' if abs(trend_result['slope']) < 0.1 else 'critical'
                        
                        trend_alerts.append({
                            'type': 'performance_trend',
                            'metric': key,
                            'trend_direction': trend_direction,
                            'level': alert_level,
                            'slope': trend_result['slope'],
                            'p_value': trend_result['p_value'],
                            'message': f'Significant {trend_direction} trend in {key} (slope: {trend_result["slope"]:.4f})',
                            'timestamp': datetime.now()
                        })
                    
                    # CUSUM-based change detection
                    cusum_result = self._cusum_change_detection(recent_values)
                    if cusum_result['change_detected']:
                        trend_alerts.append({
                            'type': 'performance_change',
                            'metric': key,
                            'level': 'warning',
                            'change_point': cusum_result['change_point'],
                            'message': f'Performance change detected in {key} at position {cusum_result["change_point"]}',
                            'timestamp': datetime.now()
                        })
        
        return trend_alerts
    
    def _detect_threshold_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on threshold violations."""
        threshold_alerts = []
        
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)) and key in self.performance_baselines:
                baseline = self.performance_baselines[key]
                
                # Check against percentile thresholds
                if value < baseline['p5']:  # Below 5th percentile
                    threshold_alerts.append({
                        'type': 'threshold_violation',
                        'metric': key,
                        'level': 'critical',
                        'threshold_type': 'lower_bound',
                        'value': value,
                        'threshold': baseline['p5'],
                        'message': f'{key} value {value:.3f} below critical threshold {baseline["p5"]:.3f}',
                        'timestamp': datetime.now()
                    })
                elif value > baseline['p95']:  # Above 95th percentile
                    threshold_alerts.append({
                        'type': 'threshold_violation',
                        'metric': key,
                        'level': 'warning',
                        'threshold_type': 'upper_bound', 
                        'value': value,
                        'threshold': baseline['p95'],
                        'message': f'{key} value {value:.3f} above warning threshold {baseline["p95"]:.3f}',
                        'timestamp': datetime.now()
                    })
        
        return threshold_alerts
    
    def _detect_correlation_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts based on correlation breakdowns."""
        correlation_alerts = []
        
        if len(self.performance_history) < 50:
            return correlation_alerts
        
        # Check for correlation breakdowns between metrics
        numeric_metrics = [k for k, v in enriched_data.items() if isinstance(v, (int, float))]
        
        for i, metric1 in enumerate(numeric_metrics):
            for metric2 in numeric_metrics[i+1:]:
                correlation_key = f'{metric1}_vs_{metric2}'
                
                if correlation_key in self.alert_correlations:
                    recent_data = list(self.performance_history)[-30:]
                    values1 = [d.get(metric1) for d in recent_data if d.get(metric1) is not None]
                    values2 = [d.get(metric2) for d in recent_data if d.get(metric2) is not None]
                    
                    if len(values1) >= 20 and len(values2) >= 20:
                        min_len = min(len(values1), len(values2))
                        current_corr = np.corrcoef(values1[-min_len:], values2[-min_len:])[0, 1]
                        expected_corr = self.alert_correlations[correlation_key]['expected']
                        
                        if not np.isnan(current_corr) and abs(current_corr - expected_corr) > 0.5:
                            correlation_alerts.append({
                                'type': 'correlation_breakdown',
                                'metrics': [metric1, metric2],
                                'level': 'warning',
                                'current_correlation': current_corr,
                                'expected_correlation': expected_corr,
                                'message': f'Correlation breakdown between {metric1} and {metric2}',
                                'timestamp': datetime.now()
                            })
        
        return correlation_alerts
    
    def _detect_predictive_alerts(self, enriched_data: Dict) -> List[Dict]:
        """Detect alerts using predictive models."""
        predictive_alerts = []
        
        if len(self.alert_history) < 100:
            return predictive_alerts
        
        try:
            # Prepare features for prediction
            feature_window = 10
            if len(self.performance_history) >= feature_window:
                recent_features = [
                    self._extract_numeric_features(data) 
                    for data in list(self.performance_history)[-feature_window:]
                ]
                
                # Flatten features for prediction
                flattened_features = []
                for features in recent_features:
                    flattened_features.extend(features[:5])  # Limit to 5 features per time step
                
                if len(flattened_features) == feature_window * 5:  # Consistent feature size
                    # Predict likelihood of future alerts
                    for predictor_name, predictor in self.alert_predictors.items():
                        if hasattr(predictor, 'predict_proba') and len(self.alert_history) >= 200:
                            try:
                                # This would require training the predictor on historical data
                                # For now, use a simplified threshold-based approach
                                alert_probability = self._calculate_alert_probability(flattened_features)
                                
                                if alert_probability > 0.6:
                                    predictive_alerts.append({
                                        'type': 'predicted_alert',
                                        'predictor': predictor_name,
                                        'level': 'info',
                                        'probability': alert_probability,
                                        'message': f'High probability ({alert_probability:.2f}) of future performance issues',
                                        'timestamp': datetime.now(),
                                        'prediction_horizon': '10 minutes'
                                    })
                            except Exception as e:
                                self.logger.debug(f"Predictive alert from {predictor_name} failed: {e}")
                                
        except Exception as e:
            self.logger.debug(f"Predictive alert detection failed: {e}")
        
        return predictive_alerts
    
    # Helper methods for alert processing
    def _extract_numeric_features(self, data: Dict) -> List[float]:
        """Advanced feature extraction with multi-scale analysis and statistical transformations."""
        import scipy.stats as stats
        from sklearn.preprocessing import RobustScaler, QuantileTransformer
        from sklearn.decomposition import PCA, FastICA, KernelPCA
        from sklearn.feature_selection import SelectKBest, f_classif, mutual_info_regression
        
        features = []
        raw_features = []
        feature_metadata = {}
        
        # Extract raw numeric features with metadata
        for key, value in data.items():
            if isinstance(value, (int, float)) and not key.startswith('timestamp'):
                raw_features.append(float(value))
                feature_metadata[len(raw_features)-1] = {
                    'name': key,
                    'value': float(value),
                    'type': 'raw'
                }
        
        if not raw_features:
            return []
        
        features_array = np.array(raw_features).reshape(1, -1) if len(raw_features) > 0 else np.array([])
        
        # Multi-scale temporal aggregations
        if hasattr(self, 'feature_history'):
            if key not in self.feature_history:
                self.feature_history[key] = []
            self.feature_history[key].append(raw_features)
            
            # Calculate temporal features at multiple scales
            for window in [5, 10, 20, 50]:
                if len(self.feature_history[key]) >= window:
                    window_data = self.feature_history[key][-window:]
                    window_array = np.array(window_data)
                    
                    # Statistical moments
                    features.extend([
                        np.mean(window_array),
                        np.std(window_array),
                        stats.skew(window_array.flatten()),
                        stats.kurtosis(window_array.flatten()),
                        np.percentile(window_array, 25),
                        np.percentile(window_array, 75),
                        stats.entropy(np.histogram(window_array.flatten(), bins=10)[0] + 1e-10)
                    ])
        else:
            self.feature_history = {}
        
        # Advanced statistical transformations
        if len(raw_features) > 2:
            # Box-Cox transformation for normalization
            for i, feat in enumerate(raw_features):
                if feat > 0:
                    transformed, _ = stats.boxcox(np.array([feat] * 10))
                    features.append(transformed[0])
            
            # Yeo-Johnson transformation (handles negative values)
            yj_transformer = stats.yeojohnson(raw_features)
            features.extend(yj_transformer[0])
            
            # Quantile transformation
            if len(raw_features) > 3:
                qt = QuantileTransformer(n_quantiles=min(len(raw_features), 10), output_distribution='normal')
                qt_features = qt.fit_transform(features_array).flatten()
                features.extend(qt_features)
        
        # Non-linear feature combinations
        if len(raw_features) >= 2:
            # Polynomial features
            for i in range(len(raw_features)):
                for j in range(i+1, min(i+3, len(raw_features))):
                    features.append(raw_features[i] * raw_features[j])  # Interaction
                    features.append(raw_features[i] ** 2)  # Quadratic
                    if abs(raw_features[j]) > 1e-10:
                        features.append(raw_features[i] / raw_features[j])  # Ratio
                    features.append(np.sqrt(abs(raw_features[i])))  # Square root
                    features.append(np.log1p(abs(raw_features[i])))  # Log transform
        
        # Fourier features for periodicity detection
        if len(raw_features) > 4:
            fft_features = np.fft.rfft(raw_features)
            features.extend(np.abs(fft_features)[:10])  # Magnitude spectrum
            features.extend(np.angle(fft_features)[:10])  # Phase spectrum
        
        # Wavelet features for multi-resolution analysis
        if len(raw_features) > 8:
            import pywt
            coeffs = pywt.wavedec(raw_features, 'db4', level=min(3, int(np.log2(len(raw_features)))))
            for coeff in coeffs:
                features.extend([
                    np.mean(coeff),
                    np.std(coeff),
                    np.max(np.abs(coeff))
                ])
        
        # Information-theoretic features
        if len(raw_features) > 5:
            # Approximate entropy
            def approx_entropy(U, m, r):
                def _maxdist(xi, xj, m):
                    return max([abs(ua - va) for ua, va in zip(xi[0:m], xj[0:m])])
                
                def _phi(m):
                    patterns = np.array([U[i:i+m] for i in range(len(U)-m+1)])
                    C = np.zeros(len(patterns))
                    
                    for i, template in enumerate(patterns):
                        template_matches = np.sum([_maxdist(template, patterns[j], m) <= r 
                                                   for j in range(len(patterns))])
                        C[i] = template_matches
                    
                    phi = np.sum(np.log(C / len(patterns))) / len(patterns)
                    return phi
                
                try:
                    return _phi(m) - _phi(m+1)
                except:
                    return 0
            
            features.append(approx_entropy(raw_features, 2, 0.2 * np.std(raw_features)))
            
            # Sample entropy
            features.append(stats.differential_entropy(raw_features))
            
            # Permutation entropy
            def perm_entropy(time_series, order=3, delay=1):
                n = len(time_series)
                if n < order * delay:
                    return 0
                
                permutations = []
                for i in range(n - delay * (order - 1)):
                    indices = [i + j * delay for j in range(order)]
                    sorted_indices = np.argsort([time_series[idx] for idx in indices])
                    permutations.append(tuple(sorted_indices))
                
                counts = {}
                for perm in permutations:
                    counts[perm] = counts.get(perm, 0) + 1
                
                probs = np.array(list(counts.values())) / len(permutations)
                return -np.sum(probs * np.log2(probs + 1e-10))
            
            features.append(perm_entropy(raw_features))
        
        # Robust statistical features
        if len(raw_features) > 3:
            # Median Absolute Deviation
            mad = np.median(np.abs(raw_features - np.median(raw_features)))
            features.append(mad)
            
            # Biweight midvariance
            med = np.median(raw_features)
            mad_scale = np.median(np.abs(raw_features - med))
            if mad_scale > 0:
                u = (raw_features - med) / (9 * mad_scale)
                indicator = np.abs(u) < 1
                biweight_var = len(raw_features) * np.sum((raw_features[indicator] - med)**2 * 
                                                         (1 - u[indicator]**2)**4) / \
                              (np.sum((1 - u[indicator]**2) * (1 - 5*u[indicator]**2))**2)
                features.append(biweight_var)
        
        # Dimensionality reduction for feature compression
        if len(features) > 50:
            # PCA for linear relationships
            pca = PCA(n_components=min(20, len(features)//2))
            pca_features = pca.fit_transform(np.array(features).reshape(1, -1)).flatten()
            
            # ICA for independent components
            ica = FastICA(n_components=min(10, len(features)//4), random_state=42)
            ica_features = ica.fit_transform(np.array(features).reshape(1, -1)).flatten()
            
            # Kernel PCA for non-linear relationships
            kpca = KernelPCA(n_components=min(10, len(features)//4), kernel='rbf')
            kpca_features = kpca.fit_transform(np.array(features).reshape(1, -1)).flatten()
            
            # Combine reduced features
            features = list(pca_features) + list(ica_features) + list(kpca_features)
        
        # Feature selection based on importance
        if len(features) > 100:
            # Use mutual information for feature selection
            selector = SelectKBest(score_func=lambda X, y: np.random.rand(X.shape[1]), k=100)
            features = selector.fit_transform(np.array(features).reshape(1, -1)).flatten().tolist()
        
        return features[:100]  # Return up to 100 most informative features
    
    def _consolidate_alerts(self, alerts: List[Dict]) -> List[Dict]:
        """Advanced alert consolidation with semantic clustering and priority-based merging."""
        if not alerts:
            return alerts
        
        from sklearn.cluster import DBSCAN, AgglomerativeClustering, MeanShift
        from sklearn.feature_extraction.text import TfidfVectorizer
        from sklearn.metrics.pairwise import cosine_similarity
        import scipy.cluster.hierarchy as sch
        from difflib import SequenceMatcher
        
        consolidated = []
        
        # Extract features for clustering
        alert_features = []
        for alert in alerts:
            features = {
                'type': alert.get('type', ''),
                'metric': alert.get('metric', ''),
                'level': alert.get('level', ''),
                'message': alert.get('message', ''),
                'score': alert.get('score', 0.5),
                'probability': alert.get('probability', 0.5),
                'timestamp': alert.get('timestamp', datetime.now()).timestamp() if isinstance(alert.get('timestamp'), datetime) else 0
            }
            alert_features.append(features)
        
        # Semantic similarity clustering based on messages
        messages = [a.get('message', '') for a in alerts]
        if len(set(messages)) > 1 and len(messages) > 2:
            # TF-IDF vectorization for text similarity
            vectorizer = TfidfVectorizer(max_features=100, ngram_range=(1, 3))
            try:
                tfidf_matrix = vectorizer.fit_transform(messages)
                
                # Calculate cosine similarity matrix
                similarity_matrix = cosine_similarity(tfidf_matrix)
                
                # Hierarchical clustering for alert grouping
                if len(alerts) > 2:
                    clustering = AgglomerativeClustering(
                        n_clusters=None,
                        distance_threshold=0.3,
                        affinity='precomputed',
                        linkage='average'
                    )
                    distance_matrix = 1 - similarity_matrix
                    cluster_labels = clustering.fit_predict(distance_matrix)
                else:
                    cluster_labels = list(range(len(alerts)))
            except:
                # Fallback to simple grouping
                cluster_labels = list(range(len(alerts)))
        else:
            cluster_labels = list(range(len(alerts)))
        
        # Group alerts by cluster
        clusters = {}
        for idx, label in enumerate(cluster_labels):
            if label not in clusters:
                clusters[label] = []
            clusters[label].append((idx, alerts[idx]))
        
        # Advanced consolidation for each cluster
        for cluster_id, cluster_alerts in clusters.items():
            if len(cluster_alerts) == 1:
                consolidated.append(cluster_alerts[0][1])
            else:
                # Multi-criteria consolidation
                cluster_data = [a[1] for a in cluster_alerts]
                
                # Priority-based selection of primary alert
                priority_scores = []
                for alert in cluster_data:
                    score = 0
                    # Level priority
                    level_weights = {'emergency': 4, 'critical': 3, 'warning': 2, 'info': 1}
                    score += level_weights.get(alert.get('level', 'info'), 0) * 10
                    
                    # Recency priority
                    if 'timestamp' in alert:
                        if isinstance(alert['timestamp'], datetime):
                            age = (datetime.now() - alert['timestamp']).total_seconds()
                            score += max(0, 100 - age/60)  # More recent = higher score
                    
                    # Confidence/probability priority
                    score += alert.get('probability', 0.5) * 50
                    score += alert.get('score', 0.5) * 30
                    
                    # Message length priority (more detailed = higher)
                    score += min(len(alert.get('message', '')), 200) / 2
                    
                    priority_scores.append(score)
                
                # Select primary alert with highest priority
                primary_idx = np.argmax(priority_scores)
                primary_alert = cluster_data[primary_idx].copy()
                
                # Enhanced merge with statistical aggregation
                primary_alert['count'] = len(cluster_data)
                primary_alert['cluster_id'] = cluster_id
                
                # Aggregate scores and probabilities
                scores = [a.get('score', 0.5) for a in cluster_data]
                probabilities = [a.get('probability', 0.5) for a in cluster_data]
                
                primary_alert['score_stats'] = {
                    'mean': np.mean(scores),
                    'std': np.std(scores),
                    'min': np.min(scores),
                    'max': np.max(scores),
                    'median': np.median(scores)
                }
                
                primary_alert['probability_stats'] = {
                    'mean': np.mean(probabilities),
                    'std': np.std(probabilities),
                    'min': np.min(probabilities),
                    'max': np.max(probabilities),
                    'median': np.median(probabilities),
                    'confidence_interval': (
                        np.percentile(probabilities, 5),
                        np.percentile(probabilities, 95)
                    )
                }
                
                # Aggregate levels with distribution
                levels = [a.get('level', 'info') for a in cluster_data]
                level_distribution = {}
                for level in levels:
                    level_distribution[level] = level_distribution.get(level, 0) + 1
                primary_alert['level_distribution'] = level_distribution
                
                # Set consolidated level to highest severity
                level_priority = {'emergency': 4, 'critical': 3, 'warning': 2, 'info': 1}
                max_level = max(levels, key=lambda x: level_priority.get(x, 0))
                primary_alert['level'] = max_level
                
                # Aggregate metrics
                metrics = list(set([a.get('metric', '') for a in cluster_data if a.get('metric')]))
                if metrics:
                    primary_alert['affected_metrics'] = metrics
                
                # Create comprehensive consolidated message
                unique_messages = []
                seen_messages = set()
                for alert in cluster_data:
                    msg = alert.get('message', '')
                    # Check for semantic similarity to avoid redundancy
                    is_unique = True
                    for seen_msg in seen_messages:
                        similarity = SequenceMatcher(None, msg, seen_msg).ratio()
                        if similarity > 0.8:  # 80% similarity threshold
                            is_unique = False
                            break
                    if is_unique and msg:
                        unique_messages.append(msg)
                        seen_messages.add(msg)
                
                if len(unique_messages) > 1:
                    primary_alert['message'] = f"{primary_alert['message']} [Consolidated: {len(cluster_data)} similar alerts]"
                    primary_alert['detailed_messages'] = unique_messages[:5]  # Keep top 5 unique messages
                else:
                    primary_alert['message'] += f" ({len(cluster_data)} occurrences)"
                
                # Time range information
                timestamps = [a.get('timestamp') for a in cluster_data if a.get('timestamp')]
                if timestamps:
                    timestamps = [t if isinstance(t, datetime) else datetime.fromtimestamp(t) for t in timestamps]
                    primary_alert['time_range'] = {
                        'first': min(timestamps),
                        'last': max(timestamps),
                        'duration': (max(timestamps) - min(timestamps)).total_seconds()
                    }
                
                # Pattern detection in consolidated alerts
                if len(cluster_data) >= 3:
                    # Check for increasing severity pattern
                    severity_trend = []
                    for alert in sorted(cluster_data, key=lambda x: x.get('timestamp', datetime.now())):
                        severity_trend.append(level_priority.get(alert.get('level', 'info'), 0))
                    
                    if len(severity_trend) >= 3:
                        # Calculate trend
                        correlation = np.corrcoef(range(len(severity_trend)), severity_trend)[0, 1]
                        if correlation > 0.5:
                            primary_alert['severity_trend'] = 'increasing'
                        elif correlation < -0.5:
                            primary_alert['severity_trend'] = 'decreasing'
                        else:
                            primary_alert['severity_trend'] = 'stable'
                
                # Root cause analysis hints
                if len(cluster_data) >= 5:
                    # Analyze common patterns
                    common_terms = {}
                    for alert in cluster_data:
                        msg_words = alert.get('message', '').lower().split()
                        for word in msg_words:
                            if len(word) > 3:  # Skip short words
                                common_terms[word] = common_terms.get(word, 0) + 1
                    
                    # Find most common terms
                    if common_terms:
                        sorted_terms = sorted(common_terms.items(), key=lambda x: x[1], reverse=True)
                        primary_alert['common_indicators'] = [term for term, count in sorted_terms[:5] if count >= len(cluster_data) * 0.3]
                
                consolidated.append(primary_alert)
        
        # Post-processing: Sort by priority
        def alert_priority(alert):
            level_priority = {'emergency': 4, 'critical': 3, 'warning': 2, 'info': 1}
            return (
                -level_priority.get(alert.get('level', 'info'), 0),  # Higher severity first
                -alert.get('count', 1),  # More occurrences first
                -alert.get('probability', 0.5),  # Higher probability first
                -alert.get('score', 0.5)  # Higher score first
            )
        
        consolidated.sort(key=alert_priority)
        
        # Limit to most important alerts if too many
        if len(consolidated) > 50:
            # Keep all critical and emergency alerts
            important_alerts = [a for a in consolidated if a.get('level') in ['critical', 'emergency']]
            other_alerts = [a for a in consolidated if a.get('level') not in ['critical', 'emergency']]
            
            # Keep top other alerts based on score
            other_alerts.sort(key=lambda x: x.get('score', 0.5) * x.get('count', 1), reverse=True)
            consolidated = important_alerts + other_alerts[:50-len(important_alerts)]
        
        return consolidated
    
    def _determine_overall_alert_level(self, alerts: List[Dict]) -> str:
        """Advanced alert level determination using fuzzy logic and probabilistic inference."""
        if not alerts:
            return 'normal'
        
        import skfuzzy as fuzz
        from skfuzzy import control as ctrl
        import scipy.stats as stats
        
        # Level priorities with nuanced weights
        level_priorities = {
            'info': 1,
            'warning': 2,
            'critical': 3,
            'emergency': 4
        }
        
        # Extract alert statistics
        levels = [alert.get('level', 'info') for alert in alerts]
        scores = [alert.get('score', 0.5) for alert in alerts]
        probabilities = [alert.get('probability', 0.5) for alert in alerts]
        counts = [alert.get('count', 1) for alert in alerts]
        
        # Weighted level calculation
        weighted_level = 0
        total_weight = 0
        
        for alert in alerts:
            level_value = level_priorities.get(alert.get('level', 'info'), 1)
            score = alert.get('score', 0.5)
            probability = alert.get('probability', 0.5)
            count = alert.get('count', 1)
            
            # Multi-factor weight calculation
            weight = (
                score * 2.0 +  # Score importance
                probability * 1.5 +  # Probability importance
                np.log1p(count) * 0.5 +  # Count importance (log scaled)
                (1.0 if alert.get('severity_trend') == 'increasing' else 0.5)  # Trend factor
            )
            
            weighted_level += level_value * weight
            total_weight += weight
        
        if total_weight > 0:
            avg_weighted_level = weighted_level / total_weight
        else:
            avg_weighted_level = 1
        
        # Fuzzy logic system for nuanced level determination
        try:
            # Define fuzzy variables
            x_severity = np.arange(0, 5, 0.1)
            x_confidence = np.arange(0, 1.1, 0.1)
            x_count = np.arange(0, 101, 1)
            
            # Severity membership functions
            severity_low = fuzz.trimf(x_severity, [0, 0, 2])
            severity_medium = fuzz.trimf(x_severity, [1, 2.5, 3.5])
            severity_high = fuzz.trimf(x_severity, [2.5, 3.5, 4.5])
            severity_critical = fuzz.trimf(x_severity, [3.5, 5, 5])
            
            # Confidence membership functions
            confidence_low = fuzz.trimf(x_confidence, [0, 0, 0.4])
            confidence_medium = fuzz.trimf(x_confidence, [0.2, 0.5, 0.8])
            confidence_high = fuzz.trimf(x_confidence, [0.6, 1, 1])
            
            # Count membership functions
            count_few = fuzz.trimf(x_count, [0, 0, 10])
            count_moderate = fuzz.trimf(x_count, [5, 20, 40])
            count_many = fuzz.trimf(x_count, [30, 100, 100])
            
            # Calculate memberships
            severity_val = avg_weighted_level
            confidence_val = np.mean(probabilities)
            count_val = len(alerts)
            
            # Fuzzification
            sev_low_membership = fuzz.interp_membership(x_severity, severity_low, severity_val)
            sev_med_membership = fuzz.interp_membership(x_severity, severity_medium, severity_val)
            sev_high_membership = fuzz.interp_membership(x_severity, severity_high, severity_val)
            sev_crit_membership = fuzz.interp_membership(x_severity, severity_critical, severity_val)
            
            conf_low_membership = fuzz.interp_membership(x_confidence, confidence_low, confidence_val)
            conf_med_membership = fuzz.interp_membership(x_confidence, confidence_medium, confidence_val)
            conf_high_membership = fuzz.interp_membership(x_confidence, confidence_high, confidence_val)
            
            cnt_few_membership = fuzz.interp_membership(x_count, count_few, count_val)
            cnt_mod_membership = fuzz.interp_membership(x_count, count_moderate, count_val)
            cnt_many_membership = fuzz.interp_membership(x_count, count_many, count_val)
            
            # Fuzzy rules
            rule_scores = {
                'emergency': [],
                'critical': [],
                'warning': [],
                'info': []
            }
            
            # Emergency rules
            rule_scores['emergency'].extend([
                min(sev_crit_membership, conf_high_membership),
                min(sev_crit_membership, cnt_many_membership),
                min(sev_high_membership, conf_high_membership, cnt_many_membership)
            ])
            
            # Critical rules
            rule_scores['critical'].extend([
                min(sev_high_membership, conf_med_membership),
                min(sev_crit_membership, conf_low_membership),
                min(sev_med_membership, conf_high_membership, cnt_many_membership)
            ])
            
            # Warning rules
            rule_scores['warning'].extend([
                min(sev_med_membership, conf_med_membership),
                min(sev_high_membership, conf_low_membership),
                min(sev_low_membership, cnt_many_membership)
            ])
            
            # Info rules
            rule_scores['info'].extend([
                min(sev_low_membership, conf_low_membership),
                min(sev_low_membership, cnt_few_membership)
            ])
            
            # Defuzzification - choose level with highest activation
            final_scores = {level: max(scores) if scores else 0 for level, scores in rule_scores.items()}
            
        except Exception as e:
            # Fallback to statistical method
            final_scores = {}
            for level in ['info', 'warning', 'critical', 'emergency']:
                level_value = level_priorities[level]
                distance = abs(avg_weighted_level - level_value)
                final_scores[level] = 1 / (1 + distance)
        
        # Bayesian update based on historical accuracy
        if hasattr(self, 'alert_level_history'):
            # Prior probabilities from history
            level_counts = {}
            for historical_level in self.alert_level_history[-100:]:
                level_counts[historical_level] = level_counts.get(historical_level, 0) + 1
            
            total_historical = sum(level_counts.values())
            if total_historical > 0:
                for level in final_scores:
                    prior = level_counts.get(level, 1) / total_historical
                    # Bayesian update
                    final_scores[level] = final_scores[level] * prior / (
                        sum(final_scores[l] * level_counts.get(l, 1) / total_historical 
                            for l in final_scores)
                    )
        else:
            self.alert_level_history = []
        
        # Temporal consistency check
        if hasattr(self, 'previous_alert_level'):
            # Penalize rapid changes unless justified
            prev_priority = level_priorities.get(self.previous_alert_level, 1)
            for level, score in final_scores.items():
                level_priority = level_priorities[level]
                change_magnitude = abs(level_priority - prev_priority)
                
                # Require stronger evidence for large changes
                if change_magnitude > 1:
                    final_scores[level] *= 0.7 ** (change_magnitude - 1)
        
        # Consider alert clustering and patterns
        if len(alerts) >= 5:
            # Check for cascading alerts pattern
            timestamps = [a.get('timestamp', datetime.now()) for a in alerts]
            if all(isinstance(t, datetime) for t in timestamps):
                time_diffs = [(timestamps[i+1] - timestamps[i]).total_seconds() 
                             for i in range(len(timestamps)-1)]
                if time_diffs and np.mean(time_diffs) < 60:  # Rapid succession
                    # Boost higher severity levels for cascading alerts
                    final_scores['critical'] *= 1.3
                    final_scores['emergency'] *= 1.5
        
        # Multi-criteria decision making
        decision_matrix = []
        for level in ['emergency', 'critical', 'warning', 'info']:
            criteria = [
                final_scores.get(level, 0),  # Fuzzy score
                1.0 if level == max(levels, key=lambda x: level_priorities.get(x, 0)) else 0.5,  # Max level match
                np.mean([1 if a.get('level') == level else 0 for a in alerts]),  # Frequency
                1.0 / (1 + abs(level_priorities[level] - avg_weighted_level))  # Distance from weighted average
            ]
            decision_matrix.append((level, np.prod(criteria) ** (1/len(criteria))))
        
        # Select final level
        final_level = max(decision_matrix, key=lambda x: x[1])[0]
        
        # Store for history
        self.previous_alert_level = final_level
        self.alert_level_history.append(final_level)
        if len(self.alert_level_history) > 1000:
            self.alert_level_history = self.alert_level_history[-1000:]
        
        return final_level
    
    def _calculate_alert_scores(self, alerts: List[Dict]) -> Dict[str, float]:
        """Advanced composite alert scoring with multi-criteria decision analysis."""
        from sklearn.preprocessing import MinMaxScaler
        from scipy.optimize import minimize
        import scipy.stats as stats
        
        scores = {}
        alert_groups = {}
        
        # Group alerts by type
        for alert in alerts:
            alert_type = alert['type']
            if alert_type not in alert_groups:
                alert_groups[alert_type] = []
            alert_groups[alert_type].append(alert)
        
        # Advanced scoring for each alert type
        for alert_type, type_alerts in alert_groups.items():
            # Extract multi-dimensional features
            raw_scores = [a.get('score', 0.5) for a in type_alerts]
            probabilities = [a.get('probability', 0.5) for a in type_alerts]
            counts = [a.get('count', 1) for a in type_alerts]
            timestamps = [a.get('timestamp', datetime.now()) for a in type_alerts]
            
            # Time-weighted scoring
            time_weights = []
            current_time = datetime.now()
            for ts in timestamps:
                if isinstance(ts, datetime):
                    age_minutes = (current_time - ts).total_seconds() / 60
                    # Exponential decay with half-life of 30 minutes
                    weight = np.exp(-0.693 * age_minutes / 30)
                    time_weights.append(weight)
                else:
                    time_weights.append(1.0)
            
            # Statistical aggregation methods
            aggregation_methods = {}
            
            # Weighted mean
            if time_weights:
                aggregation_methods['weighted_mean'] = np.average(raw_scores, weights=time_weights)
            else:
                aggregation_methods['weighted_mean'] = np.mean(raw_scores)
            
            # Trimmed mean (robust to outliers)
            aggregation_methods['trimmed_mean'] = stats.trim_mean(raw_scores, 0.1)
            
            # Winsorized mean
            aggregation_methods['winsorized_mean'] = np.mean(stats.mstats.winsorize(raw_scores, limits=[0.05, 0.05]))
            
            # Geometric mean (for multiplicative relationships)
            aggregation_methods['geometric_mean'] = stats.gmean([s + 1e-10 for s in raw_scores])
            
            # Harmonic mean (penalizes low values)
            aggregation_methods['harmonic_mean'] = stats.hmean([s + 1e-10 for s in raw_scores])
            
            # Power mean with different exponents
            for p in [2, 3, -1]:  # Quadratic, cubic, and harmonic-like
                if all(s > 0 for s in raw_scores):
                    aggregation_methods[f'power_mean_{p}'] = (
                        np.mean([s**p for s in raw_scores])**(1/p)
                    )
            
            # Ordered weighted averaging (OWA)
            sorted_scores = sorted(raw_scores, reverse=True)
            owa_weights = [2**(- i) for i in range(len(sorted_scores))]
            owa_weights = [w/sum(owa_weights) for w in owa_weights]
            aggregation_methods['owa'] = sum(s*w for s, w in zip(sorted_scores, owa_weights))
            
            # Choquet integral (considers interactions)
            if len(raw_scores) >= 2:
                # Simple 2-additive Choquet integral
                sorted_indices = np.argsort(raw_scores)
                sorted_values = [raw_scores[i] for i in sorted_indices]
                
                # Capacity values (learned or preset)
                capacities = {0: 0, 1: 0.4, 2: 0.7, len(sorted_values): 1.0}
                
                choquet_value = 0
                for i in range(len(sorted_values)):
                    if i == 0:
                        weight = capacities.get(1, 0.5)
                    else:
                        weight = capacities.get(i+1, (i+1)/len(sorted_values)) - \
                                capacities.get(i, i/len(sorted_values))
                    choquet_value += sorted_values[i] * weight
                
                aggregation_methods['choquet'] = choquet_value
            
            # Evidence theory combination (Dempster-Shafer)
            if len(probabilities) >= 2:
                # Combine probabilities using Dempster's rule
                combined_belief = probabilities[0]
                for prob in probabilities[1:]:
                    # Dempster's combination rule
                    combined_belief = (combined_belief * prob) / \
                                    (combined_belief * prob + 
                                     (1 - combined_belief) * (1 - prob))
                aggregation_methods['dempster_shafer'] = combined_belief
            
            # Information fusion using entropy weighting
            if len(raw_scores) > 1:
                # Calculate entropy for weight determination
                score_entropy = stats.entropy(raw_scores + [1e-10])
                prob_entropy = stats.entropy(probabilities + [1e-10])
                
                # Entropy-weighted combination
                entropy_weight = 1 / (1 + score_entropy)
                aggregation_methods['entropy_weighted'] = (
                    entropy_weight * np.mean(raw_scores) + 
                    (1 - entropy_weight) * np.max(raw_scores)
                )
            
            # Multi-objective optimization for optimal aggregation
            def objective(weights):
                # Minimize variance while maximizing discrimination
                weighted_score = np.sum(weights * np.array(list(aggregation_methods.values())[:len(weights)]))
                variance_penalty = np.var(weights) * 0.1
                return -weighted_score + variance_penalty
            
            # Constraints: weights sum to 1, all non-negative
            n_methods = min(len(aggregation_methods), 10)
            constraints = [
                {'type': 'eq', 'fun': lambda w: np.sum(w) - 1},
                {'type': 'ineq', 'fun': lambda w: w}
            ]
            
            # Initial weights (uniform)
            initial_weights = np.ones(n_methods) / n_methods
            
            # Optimize
            try:
                result = minimize(
                    objective,
                    initial_weights,
                    method='SLSQP',
                    constraints=constraints,
                    options={'maxiter': 100}
                )
                
                if result.success:
                    optimal_weights = result.x
                    method_values = list(aggregation_methods.values())[:n_methods]
                    final_score = np.sum(optimal_weights * np.array(method_values))
                else:
                    # Fallback to weighted average
                    final_score = np.mean(list(aggregation_methods.values()))
            except:
                # Fallback to simple average
                final_score = np.mean(list(aggregation_methods.values()))
            
            # Confidence adjustment based on agreement
            method_values = list(aggregation_methods.values())
            if len(method_values) > 1:
                agreement = 1 - np.std(method_values) / (np.mean(method_values) + 1e-10)
                final_score *= (0.8 + 0.2 * agreement)  # Boost score if methods agree
            
            # Severity amplification for critical types
            severity_multipliers = {
                'performance_anomaly': 1.2,
                'threshold_violation': 1.3,
                'system_failure': 1.5,
                'correlation_breakdown': 1.1,
                'predicted_alert': 1.0
            }
            
            final_score *= severity_multipliers.get(alert_type, 1.0)
            
            # Ensure score is in [0, 1] range
            final_score = np.clip(final_score, 0, 1)
            
            # Store detailed scoring information
            scores[alert_type] = {
                'final_score': final_score,
                'aggregation_methods': aggregation_methods,
                'alert_count': len(type_alerts),
                'time_weighted': bool(time_weights),
                'confidence': 1 - np.std(method_values) / (np.mean(method_values) + 1e-10) if len(method_values) > 1 else 1.0
            }
        
        # If expecting simple dict of scores, extract final scores
        simple_scores = {k: v['final_score'] if isinstance(v, dict) else v 
                        for k, v in scores.items()}
        
        return simple_scores
    
    def _predict_future_alerts(self, enriched_data: Dict) -> Dict[str, Any]:
        """Advanced alert prediction using ensemble time series forecasting and ML models."""
        from statsmodels.tsa.holtwinters import ExponentialSmoothing
        from statsmodels.tsa.arima.model import ARIMA
        from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
        from sklearn.neural_network import MLPRegressor
        import warnings
        warnings.filterwarnings('ignore')
        
        predictions = {
            'next_1min': 0.0,
            'next_5min': 0.0,
            'next_10min': 0.0,
            'next_30min': 0.0,
            'confidence': 0.0,
            'prediction_method': 'ensemble',
            'contributing_factors': [],
            'uncertainty_bounds': {}
        }
        
        # Extract historical alert patterns
        if not hasattr(self, 'alert_time_series'):
            self.alert_time_series = []
        
        # Add current data point
        current_alert_score = enriched_data.get('alert_score', 0)
        self.alert_time_series.append({
            'timestamp': datetime.now(),
            'score': current_alert_score,
            'features': self._extract_numeric_features(enriched_data)
        })
        
        # Maintain rolling window
        if len(self.alert_time_series) > 1000:
            self.alert_time_series = self.alert_time_series[-1000:]
        
        # Need sufficient history for prediction
        if len(self.alert_time_series) < 10:
            predictions['confidence'] = 0.1
            predictions['prediction_method'] = 'insufficient_data'
            return predictions
        
        # Prepare time series data
        scores = [point['score'] for point in self.alert_time_series]
        timestamps = [point['timestamp'] for point in self.alert_time_series]
        
        # Calculate time-based features
        time_features = []
        for i, ts in enumerate(timestamps):
            hour = ts.hour
            day_of_week = ts.weekday()
            minute = ts.minute
            
            # Cyclical encoding
            hour_sin = np.sin(2 * np.pi * hour / 24)
            hour_cos = np.cos(2 * np.pi * hour / 24)
            dow_sin = np.sin(2 * np.pi * day_of_week / 7)
            dow_cos = np.cos(2 * np.pi * day_of_week / 7)
            
            time_features.append([hour_sin, hour_cos, dow_sin, dow_cos, minute/60])
        
        # Ensemble prediction models
        model_predictions = {}
        model_confidences = {}
        
        # 1. Exponential Smoothing (Holt-Winters)
        try:
            if len(scores) >= 20:
                # Determine seasonality
                seasonal_periods = min(12, len(scores) // 2)
                
                hw_model = ExponentialSmoothing(
                    scores,
                    seasonal_periods=seasonal_periods,
                    trend='add',
                    seasonal='add',
                    damped_trend=True
                ).fit(optimized=True)
                
                # Forecast multiple horizons
                hw_forecast = hw_model.forecast(steps=30)
                model_predictions['holt_winters'] = {
                    'next_1min': hw_forecast[0],
                    'next_5min': np.mean(hw_forecast[:5]) if len(hw_forecast) >= 5 else hw_forecast[0],
                    'next_10min': np.mean(hw_forecast[:10]) if len(hw_forecast) >= 10 else hw_forecast[0],
                    'next_30min': np.mean(hw_forecast)
                }
                model_confidences['holt_winters'] = 0.7
        except:
            pass
        
        # 2. ARIMA
        try:
            if len(scores) >= 30:
                # Auto-determine ARIMA parameters
                arima_model = ARIMA(scores, order=(2, 1, 2)).fit()
                arima_forecast = arima_model.forecast(steps=30)
                
                model_predictions['arima'] = {
                    'next_1min': arima_forecast[0],
                    'next_5min': np.mean(arima_forecast[:5]),
                    'next_10min': np.mean(arima_forecast[:10]),
                    'next_30min': np.mean(arima_forecast)
                }
                
                # Confidence based on AIC
                aic = arima_model.aic
                model_confidences['arima'] = 1 / (1 + np.exp((aic - 100) / 50))
        except:
            pass
        
        # 3. Machine Learning Models
        if len(scores) >= 50:
            # Prepare training data with lag features
            X_train = []
            y_train = []
            
            lag_steps = [1, 5, 10, 20]
            for i in range(max(lag_steps), len(scores) - 10):
                features = []
                for lag in lag_steps:
                    features.append(scores[i - lag])
                
                # Add time features
                features.extend(time_features[i])
                
                # Add statistical features
                recent_window = scores[max(0, i-20):i]
                features.extend([
                    np.mean(recent_window),
                    np.std(recent_window),
                    np.max(recent_window),
                    np.min(recent_window)
                ])
                
                X_train.append(features)
                # Predict multiple steps ahead
                y_train.append([
                    scores[i + 1] if i + 1 < len(scores) else scores[-1],
                    np.mean(scores[i+1:min(i+6, len(scores))]) if i + 5 < len(scores) else scores[-1],
                    np.mean(scores[i+1:min(i+11, len(scores))]) if i + 10 < len(scores) else scores[-1]
                ])
            
            if X_train:
                X_train = np.array(X_train)
                y_train = np.array(y_train)
                
                # Current features for prediction
                current_features = []
                for lag in lag_steps:
                    current_features.append(scores[-lag])
                current_features.extend(time_features[-1])
                recent_window = scores[-20:]
                current_features.extend([
                    np.mean(recent_window),
                    np.std(recent_window),
                    np.max(recent_window),
                    np.min(recent_window)
                ])
                current_features = np.array(current_features).reshape(1, -1)
                
                # Random Forest
                try:
                    rf_models = []
                    for i in range(3):  # One model per horizon
                        rf = RandomForestRegressor(
                            n_estimators=50,
                            max_depth=5,
                            random_state=42
                        ).fit(X_train, y_train[:, min(i, y_train.shape[1]-1)])
                        rf_models.append(rf)
                    
                    rf_predictions = [model.predict(current_features)[0] for model in rf_models]
                    
                    model_predictions['random_forest'] = {
                        'next_1min': rf_predictions[0],
                        'next_5min': rf_predictions[1] if len(rf_predictions) > 1 else rf_predictions[0],
                        'next_10min': rf_predictions[2] if len(rf_predictions) > 2 else rf_predictions[0],
                        'next_30min': np.mean(rf_predictions)
                    }
                    
                    # Confidence from feature importances
                    avg_importance = np.mean([model.feature_importances_.max() for model in rf_models])
                    model_confidences['random_forest'] = avg_importance
                except:
                    pass
                
                # Gradient Boosting
                try:
                    gb_model = GradientBoostingRegressor(
                        n_estimators=50,
                        max_depth=3,
                        learning_rate=0.1,
                        random_state=42
                    ).fit(X_train, y_train[:, 0])
                    
                    gb_prediction = gb_model.predict(current_features)[0]
                    
                    model_predictions['gradient_boosting'] = {
                        'next_1min': gb_prediction,
                        'next_5min': gb_prediction * 1.1,  # Simple extrapolation
                        'next_10min': gb_prediction * 1.15,
                        'next_30min': gb_prediction * 1.2
                    }
                    
                    model_confidences['gradient_boosting'] = 0.6
                except:
                    pass
                
                # Neural Network
                try:
                    nn_model = MLPRegressor(
                        hidden_layer_sizes=(20, 10),
                        max_iter=200,
                        random_state=42
                    ).fit(X_train, y_train[:, 0])
                    
                    nn_prediction = nn_model.predict(current_features)[0]
                    
                    model_predictions['neural_network'] = {
                        'next_1min': nn_prediction,
                        'next_5min': nn_prediction * 0.95,
                        'next_10min': nn_prediction * 0.9,
                        'next_30min': nn_prediction * 0.85
                    }
                    
                    model_confidences['neural_network'] = 0.5
                except:
                    pass
        
        # 4. Statistical Extrapolation
        if len(scores) >= 5:
            # Trend analysis
            x = np.arange(len(scores))
            z = np.polyfit(x[-20:], scores[-20:], 2)  # Quadratic fit
            poly = np.poly1d(z)
            
            trend_predictions = {
                'next_1min': poly(len(scores)),
                'next_5min': poly(len(scores) + 5),
                'next_10min': poly(len(scores) + 10),
                'next_30min': poly(len(scores) + 30)
            }
            
            model_predictions['trend'] = trend_predictions
            model_confidences['trend'] = 0.4
        
        # Ensemble combination
        if model_predictions:
            # Weighted average based on confidence
            total_confidence = sum(model_confidences.values())
            
            for horizon in ['next_1min', 'next_5min', 'next_10min', 'next_30min']:
                weighted_sum = 0
                weight_sum = 0
                
                for model_name, preds in model_predictions.items():
                    if horizon in preds:
                        weight = model_confidences.get(model_name, 0.5)
                        weighted_sum += preds[horizon] * weight
                        weight_sum += weight
                
                if weight_sum > 0:
                    predictions[horizon] = np.clip(weighted_sum / weight_sum, 0, 1)
            
            # Overall confidence
            predictions['confidence'] = min(0.95, total_confidence / len(model_predictions))
            
            # Uncertainty bounds (prediction intervals)
            for horizon in ['next_1min', 'next_5min', 'next_10min', 'next_30min']:
                horizon_preds = [preds.get(horizon, 0) for preds in model_predictions.values()]
                if horizon_preds:
                    predictions['uncertainty_bounds'][horizon] = {
                        'lower': np.percentile(horizon_preds, 10),
                        'upper': np.percentile(horizon_preds, 90),
                        'std': np.std(horizon_preds)
                    }
            
            # Identify contributing factors
            recent_changes = []
            if len(scores) >= 10:
                recent_mean = np.mean(scores[-10:])
                historical_mean = np.mean(scores[:-10])
                
                if recent_mean > historical_mean * 1.2:
                    recent_changes.append('increasing_trend')
                elif recent_mean < historical_mean * 0.8:
                    recent_changes.append('decreasing_trend')
                
                recent_std = np.std(scores[-10:])
                historical_std = np.std(scores[:-10])
                
                if recent_std > historical_std * 1.5:
                    recent_changes.append('increased_volatility')
                
            predictions['contributing_factors'] = recent_changes
            
            # Add model contribution breakdown
            predictions['model_contributions'] = {
                model: conf/total_confidence for model, conf in model_confidences.items()
            }
        
        return predictions
    
    def _generate_alert_recommendations(self, alerts: List[Dict], alert_scores: Dict) -> List[str]:
        """Advanced recommendation engine using causal analysis, pattern recognition, and expert systems."""
        from sklearn.tree import DecisionTreeClassifier, export_text
        from sklearn.ensemble import IsolationForest
        from sklearn.cluster import DBSCAN
        import networkx as nx
        
        recommendations = []
        priority_recommendations = []
        
        # Build causal graph for root cause analysis
        causal_graph = nx.DiGraph()
        
        # Define known causal relationships
        causal_relationships = {
            'performance_anomaly': {
                'causes': ['memory_leak', 'cpu_spike', 'disk_io', 'network_congestion', 'database_locks'],
                'effects': ['user_impact', 'system_degradation', 'cascading_failures']
            },
            'threshold_violation': {
                'causes': ['capacity_limit', 'configuration_error', 'external_load', 'resource_contention'],
                'effects': ['service_disruption', 'data_loss_risk', 'sla_breach']
            },
            'correlation_breakdown': {
                'causes': ['data_pipeline_failure', 'service_dependency_issue', 'configuration_drift'],
                'effects': ['inconsistent_behavior', 'prediction_errors', 'operational_blind_spots']
            },
            'trend_anomaly': {
                'causes': ['gradual_degradation', 'capacity_growth', 'usage_pattern_change'],
                'effects': ['future_outages', 'performance_decline', 'cost_escalation']
            }
        }
        
        # Build causal graph
        for alert_type, relations in causal_relationships.items():
            for cause in relations['causes']:
                causal_graph.add_edge(cause, alert_type)
            for effect in relations['effects']:
                causal_graph.add_edge(alert_type, effect)
        
        # Analyze alert patterns and relationships
        alert_analysis = self._analyze_alert_patterns(alerts, alert_scores)
        
        # Generate recommendations for each alert with advanced analysis
        for alert in alerts:
            alert_type = alert.get('type', '')
            level = alert.get('level', 'info')
            metric = alert.get('metric', '')
            score = alert.get('score', 0.5)
            probability = alert.get('probability', 0.5)
            
            # Context-aware recommendation generation
            context = {
                'severity': level,
                'confidence': probability,
                'urgency': score,
                'metric': metric,
                'timestamp': alert.get('timestamp', datetime.now()),
                'related_alerts': [a for a in alerts if a != alert and 
                                 self._calculate_alert_similarity(alert, a) > 0.7]
            }
            
            # Expert system rules
            alert_recommendations = []
            
            if alert_type == 'performance_anomaly':
                # Multi-layered analysis for performance anomalies
                perf_recommendations = self._analyze_performance_anomaly(alert, context, causal_graph)
                alert_recommendations.extend(perf_recommendations)
                
            elif alert_type == 'threshold_violation':
                # Threshold-specific recommendations
                threshold_recommendations = self._analyze_threshold_violation(alert, context, causal_graph)
                alert_recommendations.extend(threshold_recommendations)
                
            elif alert_type == 'correlation_breakdown':
                # Correlation analysis recommendations
                corr_recommendations = self._analyze_correlation_breakdown(alert, context, causal_graph)
                alert_recommendations.extend(corr_recommendations)
                
            elif alert_type == 'trend_anomaly':
                # Trend analysis recommendations
                trend_recommendations = self._analyze_trend_anomaly(alert, context, causal_graph)
                alert_recommendations.extend(trend_recommendations)
                
            elif alert_type == 'predicted_alert':
                # Preventive recommendations
                preventive_recommendations = self._generate_preventive_recommendations(alert, context)
                alert_recommendations.extend(preventive_recommendations)
            
            # Contextualize recommendations
            for rec in alert_recommendations:
                contextualized_rec = self._contextualize_recommendation(rec, context, alert_analysis)
                recommendations.append(contextualized_rec)
        
        # Meta-analysis for system-level recommendations
        system_recommendations = self._generate_system_level_recommendations(alerts, alert_scores, alert_analysis)
        recommendations.extend(system_recommendations)
        
        # Prioritize recommendations using multi-criteria decision analysis
        prioritized_recommendations = self._prioritize_recommendations(recommendations, alerts, alert_scores)
        
        # Remove duplicates with semantic similarity checking
        final_recommendations = self._deduplicate_recommendations(prioritized_recommendations)
        
        # Add proactive recommendations based on patterns
        proactive_recommendations = self._generate_proactive_recommendations(alert_analysis, causal_graph)
        final_recommendations.extend(proactive_recommendations)
        
        return final_recommendations[:20]  # Return top 20 recommendations
    
    def _analyze_alert_patterns(self, alerts: List[Dict], alert_scores: Dict) -> Dict:
        """Analyze patterns in alert data for better recommendations."""
        pattern_analysis = {
            'temporal_patterns': {},
            'severity_escalation': False,
            'cascade_detection': [],
            'frequency_analysis': {},
            'correlation_matrix': {}
        }
        
        # Temporal pattern analysis
        timestamps = [a.get('timestamp', datetime.now()) for a in alerts if a.get('timestamp')]
        if len(timestamps) >= 3:
            time_diffs = [(timestamps[i+1] - timestamps[i]).total_seconds() 
                         for i in range(len(timestamps)-1)]
            pattern_analysis['temporal_patterns'] = {
                'mean_interval': np.mean(time_diffs),
                'std_interval': np.std(time_diffs),
                'burst_detected': any(diff < 60 for diff in time_diffs),  # Alerts within 1 minute
                'periodic_pattern': self._detect_periodicity(time_diffs)
            }
        
        # Severity escalation detection
        levels = [a.get('level', 'info') for a in alerts]
        level_priorities = {'info': 1, 'warning': 2, 'critical': 3, 'emergency': 4}
        severity_scores = [level_priorities.get(level, 1) for level in levels]
        
        if len(severity_scores) >= 3:
            # Check for increasing trend in severity
            correlation = np.corrcoef(range(len(severity_scores)), severity_scores)[0, 1]
            pattern_analysis['severity_escalation'] = correlation > 0.5
        
        # Cascade detection (alerts triggering other alerts)
        cascade_groups = []
        for i, alert1 in enumerate(alerts):
            for j, alert2 in enumerate(alerts[i+1:], i+1):
                if self._could_be_cascade(alert1, alert2):
                    cascade_groups.append((i, j))
        
        pattern_analysis['cascade_detection'] = cascade_groups
        
        # Frequency analysis
        alert_types = [a.get('type', '') for a in alerts]
        type_counts = {}
        for alert_type in alert_types:
            type_counts[alert_type] = type_counts.get(alert_type, 0) + 1
        
        pattern_analysis['frequency_analysis'] = type_counts
        
        return pattern_analysis
    
