    def _prioritize_recommendations(self, recommendations: List[str], alerts: List[Dict], alert_scores: Dict) -> List[str]:
        """Prioritize recommendations using multi-criteria analysis."""
        # Extract priority levels from recommendations
        priority_order = {'🔴 HIGH PRIORITY': 3, '🟡 MEDIUM PRIORITY': 2, '🟢 LOW PRIORITY': 1}
        
        def get_priority_score(rec):
            for prefix, score in priority_order.items():
                if rec.startswith(prefix):
                    return score
            return 0
        
        # Sort by priority and confidence
        return sorted(recommendations, 
                     key=lambda x: (get_priority_score(x), 
                                   'HIGH CONFIDENCE' in x,
                                   'URGENT' in x,
                                   len(x)), 
                     reverse=True)
    
    def _deduplicate_recommendations(self, recommendations: List[str]) -> List[str]:
        """Remove duplicate or very similar recommendations."""
        from difflib import SequenceMatcher
        
        unique_recommendations = []
        
        for rec in recommendations:
            # Clean recommendation for comparison
            clean_rec = rec.lower().replace('🔴', '').replace('🟡', '').replace('🟢', '')
            clean_rec = clean_rec.replace('high priority:', '').replace('medium priority:', '').replace('low priority:', '')
            
            is_unique = True
            for existing in unique_recommendations:
                clean_existing = existing.lower().replace('🔴', '').replace('🟡', '').replace('🟢', '')
                clean_existing = clean_existing.replace('high priority:', '').replace('medium priority:', '').replace('low priority:', '')
                
                similarity = SequenceMatcher(None, clean_rec, clean_existing).ratio()
                if similarity > 0.7:  # 70% similarity threshold
                    is_unique = False
                    break
            
            if is_unique:
                unique_recommendations.append(rec)
        
        return unique_recommendations
    
    def _generate_proactive_recommendations(self, alert_analysis: Dict, causal_graph) -> List[str]:
        """Generate proactive recommendations based on patterns."""
        recommendations = []
        
        # Pattern-based proactive recommendations
        if alert_analysis.get('temporal_patterns', {}).get('periodic_pattern'):
            recommendations.append("🔵 PROACTIVE: Periodic alert pattern detected - implement scheduled maintenance")
        
        if len(alert_analysis.get('cascade_detection', [])) > 2:
            recommendations.append("🔵 PROACTIVE: Cascade patterns detected - implement circuit breakers")
        
        # Causal graph analysis for prevention
        for node in causal_graph.nodes():
            successors = list(causal_graph.successors(node))
            if len(successors) > 3:  # High impact node
                recommendations.append(f"🔵 PROACTIVE: Monitor {node} closely - high impact on system")
        
        return recommendations
    
    def _calculate_alert_similarity(self, alert1: Dict, alert2: Dict) -> float:
        """Calculate similarity between two alerts."""
        similarity = 0.0
        
        # Type similarity
        if alert1.get('type') == alert2.get('type'):
            similarity += 0.4
        
        # Metric similarity
        if alert1.get('metric') == alert2.get('metric'):
            similarity += 0.3
        
        # Level similarity
        level_map = {'info': 1, 'warning': 2, 'critical': 3, 'emergency': 4}
        level1 = level_map.get(alert1.get('level', 'info'), 1)
        level2 = level_map.get(alert2.get('level', 'info'), 1)
        level_diff = abs(level1 - level2) / 3.0
        similarity += 0.2 * (1 - level_diff)
        
        # Temporal similarity (within 10 minutes)
        ts1 = alert1.get('timestamp', datetime.now())
        ts2 = alert2.get('timestamp', datetime.now())
        if isinstance(ts1, datetime) and isinstance(ts2, datetime):
            time_diff = abs((ts1 - ts2).total_seconds())
            if time_diff < 600:  # 10 minutes
                similarity += 0.1 * (1 - time_diff / 600)
        
        return similarity
    
    def _could_be_cascade(self, alert1: Dict, alert2: Dict) -> bool:
        """Determine if alert2 could be caused by alert1."""
        # Simple cascade detection based on timing and type
        ts1 = alert1.get('timestamp', datetime.now())
        ts2 = alert2.get('timestamp', datetime.now())
        
        if isinstance(ts1, datetime) and isinstance(ts2, datetime):
            time_diff = (ts2 - ts1).total_seconds()
            if 0 < time_diff < 300:  # alert2 follows alert1 within 5 minutes
                # Check for logical cascade patterns
                cascade_patterns = {
                    'performance_anomaly': ['threshold_violation', 'correlation_breakdown'],
                    'threshold_violation': ['performance_anomaly', 'system_failure'],
                    'correlation_breakdown': ['predicted_alert']
                }
                
                type1 = alert1.get('type', '')
                type2 = alert2.get('type', '')
                
                return type2 in cascade_patterns.get(type1, [])
        
        return False
    
    def _detect_periodicity(self, time_diffs: List[float]) -> bool:
        """Detect if there's a periodic pattern in time differences."""
        if len(time_diffs) < 3:
            return False
        
        # Check for regular intervals (within 20% tolerance)
        mean_diff = np.mean(time_diffs)
        std_diff = np.std(time_diffs)
        
        return std_diff / mean_diff < 0.2 if mean_diff > 0 else False
    
    def _update_adaptive_thresholds(self, enriched_data: Dict, alert_results: Dict):
        """Advanced adaptive threshold updating using reinforcement learning and Bayesian optimization."""
        import scipy.stats as stats
        from sklearn.gaussian_process import GaussianProcessRegressor
        from sklearn.gaussian_process.kernels import RBF, Matern, WhiteKernel
        from sklearn.preprocessing import StandardScaler
        
        # Initialize advanced threshold structures
        if not hasattr(self, 'threshold_history'):
            self.threshold_history = {}
        if not hasattr(self, 'threshold_performance'):
            self.threshold_performance = {}
        if not hasattr(self, 'threshold_gp_models'):
            self.threshold_gp_models = {}
        if not hasattr(self, 'threshold_rl_state'):
            self.threshold_rl_state = {}
        
        # Process each metric with advanced adaptive methods
        for key, value in enriched_data.items():
            if isinstance(value, (int, float)) and not np.isnan(value) and np.isfinite(value):
                # Initialize metric tracking
                if key not in self.adaptive_thresholds:
                    self.adaptive_thresholds[key] = {
                        'mean': value,
                        'std': 0.0,
                        'count': 1,
                        'robust_stats': {},
                        'distribution_params': {},
                        'confidence_intervals': {},
                        'threshold_levels': {},
                        'seasonality_params': {},
                        'change_detection': {},
                        'performance_metrics': {}
                    }
                    self.threshold_history[key] = []
                    self.threshold_performance[key] = []
                
                # Add to history
                self.threshold_history[key].append({
                    'value': value,
                    'timestamp': datetime.now(),
                    'alerts_generated': len(alert_results.get('alerts', [])),
                    'alert_accuracy': self._calculate_alert_accuracy(key, alert_results)
                })
                
                # Maintain rolling window
                if len(self.threshold_history[key]) > 10000:
                    self.threshold_history[key] = self.threshold_history[key][-10000:]
                
                # Multi-method threshold adaptation
                self._update_statistical_thresholds(key, value, alert_results)
                self._update_bayesian_thresholds(key, value, alert_results)
                self._update_rl_thresholds(key, value, alert_results)
                self._update_seasonal_thresholds(key, value)
                self._update_change_point_thresholds(key, value)
                self._update_distribution_based_thresholds(key, value)
        
        # Global threshold optimization
        self._optimize_threshold_ensemble()
        
        # Periodic threshold evaluation and adjustment
        if hasattr(self, 'last_threshold_optimization'):
            time_since_optimization = (datetime.now() - self.last_threshold_optimization).total_seconds()
            if time_since_optimization > 3600:  # Every hour
                self._comprehensive_threshold_optimization(enriched_data, alert_results)
        else:
            self.last_threshold_optimization = datetime.now()
    
    def _update_statistical_thresholds(self, key: str, value: float, alert_results: Dict):
        """Update thresholds using advanced statistical methods."""
        history = [point['value'] for point in self.threshold_history[key]]
        
        if len(history) < 10:
            return
        
        # Robust statistics
        median_val = np.median(history)
        mad = np.median(np.abs(history - median_val))
        
        # Biweight statistics for outlier resistance
        c = 6.0  # tuning constant
        u = (history - median_val) / (c * mad + 1e-10)
        weights = [(1 - ui**2)**2 if abs(ui) <= 1 else 0 for ui in u]
        
        if sum(weights) > 0:
            biweight_mean = sum(w * h for w, h in zip(weights, history)) / sum(weights)
            biweight_var = len(history) * sum(w * (h - biweight_mean)**2 for w, h in zip(weights, history)) / sum(weights)**2
        else:
            biweight_mean = median_val
            biweight_var = mad**2
        
        # Multiple distribution fitting
        distributions = [
            stats.norm, stats.lognorm, stats.gamma, stats.beta,
            stats.weibull_min, stats.expon, stats.chi2, stats.pareto
        ]
        
        best_dist = None
        best_params = None
        best_aic = np.inf
        
        for dist in distributions:
            try:
                params = dist.fit(history)
                log_likelihood = sum(dist.logpdf(history, *params))
                aic = 2 * len(params) - 2 * log_likelihood
                
                if aic < best_aic:
                    best_aic = aic
                    best_dist = dist
                    best_params = params
            except:
                continue
        
        # Update threshold statistics
        self.adaptive_thresholds[key].update({
            'mean': np.mean(history),
            'std': np.std(history),
            'median': median_val,
            'mad': mad,
            'biweight_mean': biweight_mean,
            'biweight_var': biweight_var,
            'count': len(history)
        })
        
        # Store robust statistics
        self.adaptive_thresholds[key]['robust_stats'] = {
            'trimmed_mean_10': stats.trim_mean(history, 0.1),
            'trimmed_mean_20': stats.trim_mean(history, 0.2),
            'winsorized_mean': np.mean(stats.mstats.winsorize(history, limits=[0.05, 0.05])),
            'huber_mean': self._huber_mean(history),
            'hampel_mean': self._hampel_mean(history)
        }
        
        # Store distribution parameters
        if best_dist:
            self.adaptive_thresholds[key]['distribution_params'] = {
                'name': best_dist.name,
                'params': best_params,
                'aic': best_aic
            }
        
        # Calculate multiple confidence intervals
        confidence_levels = [0.95, 0.99, 0.999]
        for conf_level in confidence_levels:
            if best_dist and best_params:
                lower = best_dist.ppf((1 - conf_level) / 2, *best_params)
                upper = best_dist.ppf(1 - (1 - conf_level) / 2, *best_params)
            else:
                # Bootstrap confidence intervals
                n_bootstrap = 1000
                bootstrap_means = []
                for _ in range(n_bootstrap):
                    bootstrap_sample = np.random.choice(history, size=len(history), replace=True)
                    bootstrap_means.append(np.mean(bootstrap_sample))
                
                lower = np.percentile(bootstrap_means, (1 - conf_level) / 2 * 100)
                upper = np.percentile(bootstrap_means, (1 + conf_level) / 2 * 100)
            
            self.adaptive_thresholds[key]['confidence_intervals'][conf_level] = {
                'lower': lower,
                'upper': upper
            }
        
        # Multi-level thresholds
        percentiles = [50, 75, 90, 95, 99, 99.9]
        threshold_levels = {}
        for percentile in percentiles:
            threshold_levels[f'p{percentile}'] = np.percentile(history, percentile)
        
        # Adaptive percentile-based thresholds
        alert_history = [point['alerts_generated'] for point in self.threshold_history[key]]
        if len(alert_history) > 20:
            # Adjust thresholds based on alert frequency
            recent_alert_rate = np.mean(alert_history[-20:])
            target_alert_rate = 0.05  # 5% target alert rate
            
            adjustment_factor = target_alert_rate / (recent_alert_rate + 1e-10)
            
            for level, threshold in threshold_levels.items():
                threshold_levels[level] *= adjustment_factor
        
        self.adaptive_thresholds[key]['threshold_levels'] = threshold_levels
    
    def _update_bayesian_thresholds(self, key: str, value: float, alert_results: Dict):
        """Update thresholds using Bayesian inference."""
        if len(self.threshold_history[key]) < 20:
            return
        
        # Bayesian updating of distribution parameters
        history = [point['value'] for point in self.threshold_history[key]]
        
        # Prior beliefs (initially non-informative)
        if 'bayesian_params' not in self.adaptive_thresholds[key]:
            self.adaptive_thresholds[key]['bayesian_params'] = {
                'mean_prior_mean': np.mean(history[:10]),
                'mean_prior_var': np.var(history[:10]),
                'precision_alpha': 1.0,
                'precision_beta': 1.0,
                'posterior_samples': []
            }
        
        bayesian = self.adaptive_thresholds[key]['bayesian_params']
        
        # Normal-Gamma conjugate prior update
        n = len(history)
        sample_mean = np.mean(history)
        sample_var = np.var(history)
        
        # Update hyperparameters
        posterior_mean_mean = (bayesian['mean_prior_var'] * sample_mean + 
                               bayesian['mean_prior_mean'] * sample_var / n) / \
                              (bayesian['mean_prior_var'] + sample_var / n)
        
        posterior_mean_var = (bayesian['mean_prior_var'] * sample_var / n) / \
                             (bayesian['mean_prior_var'] + sample_var / n)
        
        posterior_alpha = bayesian['precision_alpha'] + n / 2
        posterior_beta = (bayesian['precision_beta'] + 
                          0.5 * (n - 1) * sample_var + 
                          0.5 * n * bayesian['mean_prior_var'] * 
                          (sample_mean - bayesian['mean_prior_mean'])**2 / 
                          (bayesian['mean_prior_var'] + sample_var / n))
        
        # Generate posterior samples
        n_samples = 1000
        precision_samples = stats.gamma.rvs(posterior_alpha, scale=1/posterior_beta, size=n_samples)
        mean_samples = stats.norm.rvs(posterior_mean_mean, 
                                      np.sqrt(posterior_mean_var), 
                                      size=n_samples)
        
        # Calculate Bayesian thresholds
        bayesian_thresholds = {}
        for conf_level in [0.95, 0.99, 0.999]:
            threshold_samples = []
            for mean_samp, prec_samp in zip(mean_samples, precision_samples):
                std_samp = 1 / np.sqrt(prec_samp)
                threshold_samples.append(mean_samp + stats.norm.ppf(conf_level) * std_samp)
            
            bayesian_thresholds[conf_level] = {
                'mean': np.mean(threshold_samples),
                'lower': np.percentile(threshold_samples, 2.5),
                'upper': np.percentile(threshold_samples, 97.5)
            }
        
        bayesian.update({
            'posterior_mean_mean': posterior_mean_mean,
            'posterior_mean_var': posterior_mean_var,
            'posterior_alpha': posterior_alpha,
            'posterior_beta': posterior_beta,
            'thresholds': bayesian_thresholds
        })
    
    def _update_rl_thresholds(self, key: str, value: float, alert_results: Dict):
        """Update thresholds using reinforcement learning."""
        if key not in self.threshold_rl_state:
            self.threshold_rl_state[key] = {
                'q_table': {},
                'epsilon': 0.1,
                'learning_rate': 0.01,
                'discount_factor': 0.9,
                'state_discretization': 10,
                'action_space': [-0.1, -0.05, 0, 0.05, 0.1],  # Threshold adjustments
                'current_threshold': np.percentile([point['value'] for point in self.threshold_history[key]], 95) if len(self.threshold_history[key]) > 5 else value * 1.2,
                'last_action': 0,
                'episode_reward': 0
            }
        
        rl_state = self.threshold_rl_state[key]
        
        # State representation (discretized current value relative to threshold)
        if len(self.threshold_history[key]) < 5:
            return
        
        relative_value = value / (rl_state['current_threshold'] + 1e-10)
        state = min(int(relative_value * rl_state['state_discretization']), 
                    rl_state['state_discretization'] - 1)
        
        # Calculate reward based on alert performance
        alert_accuracy = self._calculate_alert_accuracy(key, alert_results)
        alert_frequency = len(alert_results.get('alerts', []))
        
        # Reward function: balance accuracy and frequency
        target_frequency = 0.05  # 5% alert rate
        frequency_penalty = abs(alert_frequency - target_frequency) * 10
        accuracy_reward = alert_accuracy * 5
        
        reward = accuracy_reward - frequency_penalty
        rl_state['episode_reward'] = reward
        
        # Q-learning update
        if state not in rl_state['q_table']:
            rl_state['q_table'][state] = [0.0] * len(rl_state['action_space'])
        
        # Update Q-value for last state-action pair
        if hasattr(rl_state, 'last_state'):
            last_state = rl_state.last_state
            last_action = rl_state['last_action']
            
            # Q-learning update rule
            old_q = rl_state['q_table'][last_state][last_action]
            max_next_q = max(rl_state['q_table'][state]) if state in rl_state['q_table'] else 0
            
            new_q = old_q + rl_state['learning_rate'] * (
                reward + rl_state['discount_factor'] * max_next_q - old_q
            )
            
            rl_state['q_table'][last_state][last_action] = new_q
        
        # Epsilon-greedy action selection
        if np.random.random() < rl_state['epsilon']:
            # Explore
            action_idx = np.random.randint(len(rl_state['action_space']))
        else:
            # Exploit
            if state in rl_state['q_table']:
                action_idx = np.argmax(rl_state['q_table'][state])
            else:
                action_idx = len(rl_state['action_space']) // 2  # No change
        
        # Apply action to threshold
        threshold_adjustment = rl_state['action_space'][action_idx]
        rl_state['current_threshold'] *= (1 + threshold_adjustment)
        
        # Store state and action for next update
        rl_state.last_state = state
        rl_state['last_action'] = action_idx
        
        # Decay exploration rate
        rl_state['epsilon'] *= 0.999
        rl_state['epsilon'] = max(0.01, rl_state['epsilon'])
        
        # Store RL threshold
        self.adaptive_thresholds[key]['rl_threshold'] = rl_state['current_threshold']
    
    def _update_seasonal_thresholds(self, key: str, value: float):
        """Update thresholds considering seasonal patterns."""
        if len(self.threshold_history[key]) < 100:
            return
        
        # Extract temporal features
        timestamps = [point['timestamp'] for point in self.threshold_history[key]]
        values = [point['value'] for point in self.threshold_history[key]]
        
        # Create time-based features
        hours = [ts.hour for ts in timestamps]
        days_of_week = [ts.weekday() for ts in timestamps]
        days_of_month = [ts.day for ts in timestamps]
        
        # Seasonal decomposition
        from statsmodels.tsa.seasonal import seasonal_decompose
        
        try:
            if len(values) >= 24:  # Need at least one day of hourly data
                # Create hourly averages
                hourly_avgs = {}
                for hour, val in zip(hours, values):
                    if hour not in hourly_avgs:
                        hourly_avgs[hour] = []
                    hourly_avgs[hour].append(val)
                
                seasonal_patterns = {}
                for hour in range(24):
                    if hour in hourly_avgs:
                        seasonal_patterns[f'hour_{hour}'] = {
                            'mean': np.mean(hourly_avgs[hour]),
                            'std': np.std(hourly_avgs[hour]),
                            'p95': np.percentile(hourly_avgs[hour], 95)
                        }
                
                # Day of week patterns
                dow_avgs = {}
                for dow, val in zip(days_of_week, values):
                    if dow not in dow_avgs:
                        dow_avgs[dow] = []
                    dow_avgs[dow].append(val)
                
                for dow in range(7):
                    if dow in dow_avgs:
                        seasonal_patterns[f'dow_{dow}'] = {
                            'mean': np.mean(dow_avgs[dow]),
                            'std': np.std(dow_avgs[dow]),
                            'p95': np.percentile(dow_avgs[dow], 95)
                        }
                
                self.adaptive_thresholds[key]['seasonality_params'] = seasonal_patterns
        
        except Exception as e:
            self.logger.debug(f"Seasonal decomposition failed for {key}: {e}")
    
    def _update_change_point_thresholds(self, key: str, value: float):
        """Update thresholds using change point detection."""
        if len(self.threshold_history[key]) < 50:
            return
        
        values = [point['value'] for point in self.threshold_history[key]]
        
        # PELT (Pruned Exact Linear Time) change point detection
        try:
            import ruptures as rpt
            
            # Change point detection
            algo = rpt.Pelt(model="rbf").fit(np.array(values))
            change_points = algo.predict(pen=10)  # Penalty parameter
            
            # Analyze segments between change points
            segments = []
            start = 0
            for cp in change_points:
                segment_values = values[start:cp]
                if len(segment_values) > 5:
                    segments.append({
                        'start': start,
                        'end': cp,
                        'mean': np.mean(segment_values),
                        'std': np.std(segment_values),
                        'trend': self._calculate_segment_trend(segment_values)
                    })
                start = cp
            
            # Adaptive thresholds based on current segment
            current_segment = segments[-1] if segments else None
            if current_segment:
                # Use current segment statistics for thresholds
                segment_mean = current_segment['mean']
                segment_std = current_segment['std']
                
                change_point_thresholds = {
                    'mean': segment_mean,
                    'upper_2sigma': segment_mean + 2 * segment_std,
                    'upper_3sigma': segment_mean + 3 * segment_std,
                    'lower_2sigma': segment_mean - 2 * segment_std,
                    'lower_3sigma': segment_mean - 3 * segment_std,
                }
                
                self.adaptive_thresholds[key]['change_detection'] = {
                    'change_points': change_points,
                    'current_segment': current_segment,
                    'thresholds': change_point_thresholds,
                    'n_change_points': len(change_points) - 1
                }
        
        except ImportError:
            # Fallback: simple variance-based change detection
            window_size = 20
            if len(values) >= window_size * 2:
                variances = []
                for i in range(window_size, len(values) - window_size):
                    var1 = np.var(values[i-window_size:i])
                    var2 = np.var(values[i:i+window_size])
                    variances.append(abs(var1 - var2))
                
                change_threshold = np.percentile(variances, 95)
                change_points = [i + window_size for i, var in enumerate(variances) 
                               if var > change_threshold]
                
                if change_points:
                    self.adaptive_thresholds[key]['change_detection'] = {
                        'simple_change_points': change_points,
                        'variance_threshold': change_threshold
                    }
    
    def _update_distribution_based_thresholds(self, key: str, value: float):
        """Update thresholds using distribution-based methods."""
        if len(self.threshold_history[key]) < 30:
            return
        
        values = [point['value'] for point in self.threshold_history[key]]
        
        # Extreme Value Theory for tail modeling
        from scipy.stats import genextreme, genpareto
        
        try:
            # Fit Generalized Extreme Value distribution
            gev_params = genextreme.fit(values)
            
            # Fit Generalized Pareto Distribution to excesses
            threshold_95 = np.percentile(values, 95)
            excesses = [v - threshold_95 for v in values if v > threshold_95]
            
            if len(excesses) > 10:
                gpd_params = genpareto.fit(excesses)
                
                # Calculate extreme quantiles
                extreme_quantiles = {}
                for prob in [0.99, 0.999, 0.9999]:
                    gev_quantile = genextreme.ppf(prob, *gev_params)
                    
                    # GPD-based threshold (over threshold model)
                    if len(excesses) > 0:
                        n_excesses = len(excesses)
                        n_total = len(values)
                        
                        # Return level calculation
                        return_period = 1 / (1 - prob)
                        expected_excesses = n_total / return_period
                        
                        if expected_excesses > n_excesses:
                            gpd_quantile = threshold_95 + genpareto.ppf(
                                1 - n_excesses / expected_excesses, *gpd_params
                            )
                        else:
                            gpd_quantile = gev_quantile
                    else:
                        gpd_quantile = gev_quantile
                    
                    extreme_quantiles[prob] = {
                        'gev': gev_quantile,
                        'gpd': gpd_quantile,
                        'combined': (gev_quantile + gpd_quantile) / 2
                    }
                
                self.adaptive_thresholds[key]['extreme_value'] = {
                    'gev_params': gev_params,
                    'gpd_params': gpd_params,
                    'threshold_95': threshold_95,
                    'extreme_quantiles': extreme_quantiles
                }
        
        except Exception as e:
            self.logger.debug(f"EVT analysis failed for {key}: {e}")
    
    def _optimize_threshold_ensemble(self):
        """Optimize ensemble of different threshold methods."""
        for key, threshold_data in self.adaptive_thresholds.items():
            if len(self.threshold_history.get(key, [])) < 50:
                continue
            
            # Collect all threshold estimates
            threshold_methods = {}
            
            # Statistical thresholds
            if 'threshold_levels' in threshold_data:
                threshold_methods.update(threshold_data['threshold_levels'])
            
            # Bayesian thresholds
            if 'bayesian_params' in threshold_data and 'thresholds' in threshold_data['bayesian_params']:
                for conf, bayes_thresh in threshold_data['bayesian_params']['thresholds'].items():
                    threshold_methods[f'bayesian_{conf}'] = bayes_thresh['mean']
            
            # RL threshold
            if 'rl_threshold' in threshold_data:
                threshold_methods['rl'] = threshold_data['rl_threshold']
            
            # Change point thresholds
            if 'change_detection' in threshold_data and 'thresholds' in threshold_data['change_detection']:
                for name, cp_thresh in threshold_data['change_detection']['thresholds'].items():
                    threshold_methods[f'changepoint_{name}'] = cp_thresh
            
            # Extreme value thresholds
            if 'extreme_value' in threshold_data and 'extreme_quantiles' in threshold_data['extreme_value']:
                for prob, ev_thresh in threshold_data['extreme_value']['extreme_quantiles'].items():
                    threshold_methods[f'extreme_{prob}'] = ev_thresh['combined']
            
            # Ensemble combination using performance weighting
            if len(threshold_methods) > 1:
                # Calculate performance-based weights
                method_weights = {}
                total_weight = 0
                
                for method_name in threshold_methods.keys():
                    # Base weight
                    weight = 1.0
                    
                    # Adjust based on method characteristics
                    if 'bayesian' in method_name:
                        weight *= 1.2  # Bayesian methods get slight boost
                    elif 'extreme' in method_name:
                        weight *= 0.8  # EVT methods are more specialized
                    elif 'rl' in method_name:
                        weight *= 1.1  # RL adapts well
                    
                    method_weights[method_name] = weight
                    total_weight += weight
                
                # Normalize weights
                for method_name in method_weights:
                    method_weights[method_name] /= total_weight
                
                # Calculate ensemble threshold
                ensemble_threshold = sum(
                    threshold_methods[method] * method_weights[method]
                    for method in threshold_methods.keys()
                )
                
                threshold_data['ensemble_threshold'] = ensemble_threshold
                threshold_data['method_weights'] = method_weights
    
    def _comprehensive_threshold_optimization(self, enriched_data: Dict, alert_results: Dict):
        """Perform comprehensive threshold optimization."""
        # Multi-objective optimization of thresholds
        from sklearn.model_selection import GridSearchCV
        from sklearn.metrics import make_scorer
        
        for key in self.adaptive_thresholds.keys():
            if len(self.threshold_history.get(key, [])) < 100:
                continue
            
            # Create optimization dataset
            history = self.threshold_history[key]
            values = [h['value'] for h in history]
            alert_counts = [h['alerts_generated'] for h in history]
            accuracies = [h['alert_accuracy'] for h in history]
            
            # Define optimization objective
            def threshold_objective(threshold_multiplier):
                # Simulate threshold performance
                base_threshold = np.percentile(values, 95)
                test_threshold = base_threshold * threshold_multiplier
                
                # Count would-be alerts
                simulated_alerts = sum(1 for v in values if v > test_threshold)
                alert_rate = simulated_alerts / len(values)
                
                # Penalize deviation from target alert rate (5%)
                target_rate = 0.05
                rate_penalty = abs(alert_rate - target_rate) * 10
                
                # Reward based on historical accuracy when available
                accuracy_reward = np.mean(accuracies) if accuracies else 0.5
                
                return accuracy_reward - rate_penalty
            
            # Optimize threshold multiplier
            multipliers = np.linspace(0.5, 2.0, 20)
            best_multiplier = 1.0
            best_score = -np.inf
            
            for mult in multipliers:
                score = threshold_objective(mult)
                if score > best_score:
                    best_score = score
                    best_multiplier = mult
            
            # Update optimized threshold
            base_threshold = np.percentile(values, 95)
            optimized_threshold = base_threshold * best_multiplier
            
            self.adaptive_thresholds[key]['optimized_threshold'] = optimized_threshold
            self.adaptive_thresholds[key]['optimization_score'] = best_score
        
        self.last_threshold_optimization = datetime.now()
    
    def _calculate_alert_accuracy(self, key: str, alert_results: Dict) -> float:
        """Advanced multi-faceted alert accuracy calculation using ensemble validation methods."""
        from sklearn.metrics import precision_recall_curve, roc_auc_score, accuracy_score
        from sklearn.ensemble import IsolationForest, OneClassSVM
        from sklearn.cluster import DBSCAN
        from scipy import stats
        import warnings
        warnings.filterwarnings('ignore')
        
        try:
            alerts = alert_results.get('alerts', [])
            key_alerts = [a for a in alerts if a.get('metric') == key]
            
            if not key_alerts:
                return 0.5  # Neutral baseline
            
            # Initialize accuracy assessment components
            accuracy_components = {}
            
            # 1. Statistical Validation Accuracy
            accuracy_components['statistical'] = self._calculate_statistical_validation_accuracy(key, key_alerts)
            
            # 2. Temporal Consistency Accuracy 
            accuracy_components['temporal'] = self._calculate_temporal_consistency_accuracy(key, key_alerts)
            
            # 3. Cross-Validation Accuracy
            accuracy_components['cross_validation'] = self._calculate_cross_validation_accuracy(key, key_alerts)
            
            # 4. Ensemble Detector Accuracy
            accuracy_components['ensemble'] = self._calculate_ensemble_detector_accuracy(key, key_alerts)
            
            # 5. Feature Correlation Accuracy
            accuracy_components['correlation'] = self._calculate_feature_correlation_accuracy(key, key_alerts)
            
            # 6. Bayesian Validation Accuracy
            accuracy_components['bayesian'] = self._calculate_bayesian_validation_accuracy(key, key_alerts)
            
            # 7. Causal Inference Accuracy
            accuracy_components['causal'] = self._calculate_causal_inference_accuracy(key, key_alerts)
            
            # 8. Multi-Scale Validation Accuracy
            accuracy_components['multi_scale'] = self._calculate_multi_scale_validation_accuracy(key, key_alerts)
            
            # 9. Information Theoretic Accuracy
            accuracy_components['information'] = self._calculate_information_theoretic_accuracy(key, key_alerts)
            
            # 10. Robust Statistical Accuracy
            accuracy_components['robust'] = self._calculate_robust_statistical_accuracy(key, key_alerts)
            
            # Ensemble accuracy calculation with adaptive weighting
            weights = self._calculate_accuracy_component_weights(accuracy_components, key_alerts)
            
            # Calculate weighted ensemble accuracy
            weighted_accuracy = 0.0
            total_weight = 0.0
            
            for component, weight in weights.items():
                if component in accuracy_components and accuracy_components[component] is not None:
                    weighted_accuracy += accuracy_components[component] * weight
                    total_weight += weight
            
            if total_weight > 0:
                final_accuracy = weighted_accuracy / total_weight
            else:
                final_accuracy = 0.5
            
            # Apply confidence adjustment based on sample size
            confidence_adjustment = self._calculate_accuracy_confidence_adjustment(key_alerts)
            adjusted_accuracy = final_accuracy * confidence_adjustment
            
            # Clamp to valid range
            return np.clip(adjusted_accuracy, 0.0, 1.0)
            
        except Exception as e:
            self.logger.error(f"Error calculating alert accuracy for {key}: {str(e)}")
            return 0.5
    
    def _calculate_statistical_validation_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy based on statistical validation of alert features."""
        try:
            from scipy.stats import ks_2samp, anderson_ksamp, normaltest, jarque_bera
            from sklearn.preprocessing import StandardScaler
            
            if len(alerts) < 2:
                return 0.5
                
            # Extract alert features
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            timestamps = [a.get('timestamp', 0) for a in alerts]
            
            # Statistical consistency tests
            consistency_scores = []
            
            # 1. Distribution consistency test
            if len(probabilities) > 10:
                # Test if probabilities follow expected distribution
                ks_stat, ks_p = ks_2samp(probabilities, np.random.beta(2, 2, len(probabilities)))
                consistency_scores.append(1 - min(ks_stat, 1.0))
            
            # 2. Normality test on standardized scores
            if len(scores) > 8:
                scaler = StandardScaler()
                normalized_scores = scaler.fit_transform(np.array(scores).reshape(-1, 1)).flatten()
                _, normality_p = normaltest(normalized_scores)
                consistency_scores.append(min(normality_p * 2, 1.0))  # Higher p-value = better
            
            # 3. Temporal spacing analysis
            if len(timestamps) > 5:
                time_diffs = np.diff(sorted(timestamps))
                if len(time_diffs) > 0:
                    cv_time = np.std(time_diffs) / np.mean(time_diffs) if np.mean(time_diffs) > 0 else 1
                    temporal_consistency = np.exp(-cv_time)  # Lower CV = better consistency
                    consistency_scores.append(temporal_consistency)
            
            # 4. Cross-correlation analysis
            if len(probabilities) == len(scores) and len(probabilities) > 3:
                correlation = np.corrcoef(probabilities, scores)[0, 1]
                if not np.isnan(correlation):
                    # Expect moderate positive correlation for valid alerts
                    expected_corr = 0.3
                    corr_accuracy = np.exp(-abs(correlation - expected_corr))
                    consistency_scores.append(corr_accuracy)
            
            return np.mean(consistency_scores) if consistency_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_temporal_consistency_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy based on temporal consistency of alerts."""
        try:
            from scipy.signal import find_peaks, savgol_filter
            from sklearn.cluster import KMeans
            
            if len(alerts) < 3:
                return 0.5
                
            # Sort alerts by timestamp
            sorted_alerts = sorted(alerts, key=lambda x: x.get('timestamp', 0))
            timestamps = [a.get('timestamp', 0) for a in sorted_alerts]
            probabilities = [a.get('probability', 0.5) for a in sorted_alerts]
            
            temporal_scores = []
            
            # 1. Smoothness analysis
            if len(probabilities) > 5:
                # Apply Savitzky-Golay filter for smoothing
                window_length = min(len(probabilities), 5)
                if window_length % 2 == 0:
                    window_length -= 1
                if window_length >= 3:
                    smoothed = savgol_filter(probabilities, window_length, 2)
                    smoothness = 1 - np.mean(np.abs(np.array(probabilities) - smoothed))
                    temporal_scores.append(max(smoothness, 0))
            
            # 2. Peak detection consistency
            if len(probabilities) > 10:
                peaks, _ = find_peaks(probabilities, height=0.7)
                peak_ratio = len(peaks) / len(probabilities)
                # Expect reasonable peak density (not too many, not too few)
                optimal_peak_ratio = 0.1
                peak_consistency = np.exp(-abs(peak_ratio - optimal_peak_ratio) * 10)
                temporal_scores.append(peak_consistency)
            
            # 3. Time interval analysis
            if len(timestamps) > 4:
                intervals = np.diff(timestamps)
                if len(intervals) > 0:
                    # Check for temporal clustering patterns
                    kmeans = KMeans(n_clusters=min(3, len(intervals)), random_state=42, n_init=10)
                    clusters = kmeans.fit_predict(intervals.reshape(-1, 1))
                    
                    # Calculate silhouette-like score for temporal clusters
                    cluster_quality = 0
                    unique_clusters = np.unique(clusters)
                    if len(unique_clusters) > 1:
                        intra_cluster_distances = []
                        inter_cluster_distances = []
                        
                        for cluster_id in unique_clusters:
                            cluster_intervals = intervals[clusters == cluster_id]
                            if len(cluster_intervals) > 1:
                                intra_dist = np.mean(np.abs(cluster_intervals - np.mean(cluster_intervals)))
                                intra_cluster_distances.append(intra_dist)
                                
                                # Inter-cluster distance
                                other_intervals = intervals[clusters != cluster_id]
                                if len(other_intervals) > 0:
                                    inter_dist = np.mean(np.abs(cluster_intervals.reshape(-1, 1) - 
                                                               other_intervals.reshape(1, -1)))
                                    inter_cluster_distances.append(inter_dist)
                        
                        if intra_cluster_distances and inter_cluster_distances:
                            avg_intra = np.mean(intra_cluster_distances)
                            avg_inter = np.mean(inter_cluster_distances)
                            if avg_intra > 0:
                                cluster_quality = avg_inter / (avg_inter + avg_intra)
                    
                    temporal_scores.append(cluster_quality)
            
            # 4. Trend analysis
            if len(probabilities) > 6:
                # Linear trend strength
                x = np.arange(len(probabilities))
                correlation = np.corrcoef(x, probabilities)[0, 1]
                if not np.isnan(correlation):
                    # Moderate trends are more realistic than extreme trends
                    trend_quality = 1 - abs(correlation) if abs(correlation) > 0.8 else 1
                    temporal_scores.append(trend_quality)
            
            return np.mean(temporal_scores) if temporal_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_cross_validation_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using cross-validation approaches."""
        try:
            from sklearn.model_selection import KFold, cross_val_score
            from sklearn.ensemble import RandomForestClassifier
            from sklearn.linear_model import LogisticRegression
            from sklearn.svm import SVC
            
            if len(alerts) < 10:  # Need sufficient data for cross-validation
                return 0.5
            
            # Prepare features and labels
            features = []
            labels = []
            
            for alert in alerts:
                feature_vector = [
                    alert.get('probability', 0.5),
                    alert.get('score', 0.5),
                    alert.get('severity', 1),
                    len(alert.get('message', '')),
                    alert.get('timestamp', 0) % 86400,  # Time of day
                    hash(alert.get('source', '')) % 1000,  # Source hash
                ]
                
                # Generate real ground truth using multi-source validation
                ground_truth = self._validate_alert_against_ground_truth(alert, key)
                
                features.append(feature_vector)
                labels.append(ground_truth)
            
            features = np.array(features)
            labels = np.array(labels)
            
            cv_scores = []
            
            # Multiple classifiers for ensemble validation
            classifiers = [
                RandomForestClassifier(n_estimators=50, random_state=42),
                LogisticRegression(random_state=42, max_iter=1000),
                SVC(probability=True, random_state=42)
            ]
            
            kf = KFold(n_splits=min(5, len(alerts) // 2), shuffle=True, random_state=42)
            
            for classifier in classifiers:
                try:
                    scores = cross_val_score(classifier, features, labels, cv=kf, scoring='accuracy')
                    cv_scores.extend(scores)
                except:
                    continue
            
            return np.mean(cv_scores) if cv_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_ensemble_detector_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using ensemble anomaly detection methods."""
        try:
            from sklearn.ensemble import IsolationForest, OneClassSVM
            from sklearn.covariance import EllipticEnvelope
            from sklearn.neighbors import LocalOutlierFactor
            
            if len(alerts) < 5:
                return 0.5
            
            # Extract features for anomaly detection
            features = []
            for alert in alerts:
                feature_vector = [
                    alert.get('probability', 0.5),
                    alert.get('score', 0.5),
                    alert.get('severity', 1),
                    len(alert.get('message', '')) / 100.0,  # Normalized message length
                ]
                features.append(feature_vector)
            
            features = np.array(features)
            
            # Ensemble of anomaly detectors
            detectors = [
                IsolationForest(contamination=0.1, random_state=42),
                EllipticEnvelope(contamination=0.1, random_state=42),
                LocalOutlierFactor(contamination=0.1, novelty=True)
            ]
            
            ensemble_scores = []
            
            for detector in detectors:
                try:
                    if hasattr(detector, 'fit_predict'):
                        detector.fit(features)
                        if hasattr(detector, 'decision_function'):
                            scores = detector.decision_function(features)
                        else:
                            scores = detector.score_samples(features)
                    else:
                        scores = detector.fit_predict(features)
                    
                    # Convert to accuracy-like metric
                    if isinstance(scores, np.ndarray):
                        # Higher scores should indicate better (more normal) alerts
                        normalized_scores = (scores - np.min(scores)) / (np.max(scores) - np.min(scores) + 1e-8)
                        ensemble_scores.extend(normalized_scores)
                except:
                    continue
            
            if ensemble_scores:
                return np.mean(ensemble_scores)
            else:
                return 0.5
                
        except Exception as e:
            return 0.5
    
    def _calculate_feature_correlation_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy based on feature correlation analysis."""
        try:
            from sklearn.feature_selection import mutual_info_regression
            from scipy.stats import spearmanr, kendalltau
            
            if len(alerts) < 5:
                return 0.5
            
            # Extract multiple features
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            severities = [a.get('severity', 1) for a in alerts]
            message_lengths = [len(a.get('message', '')) for a in alerts]
            
            correlation_scores = []
            
            # 1. Pearson correlations
            features_matrix = np.array([probabilities, scores, severities, message_lengths]).T
            if features_matrix.shape[0] > 3 and features_matrix.shape[1] > 1:
                corr_matrix = np.corrcoef(features_matrix.T)
                
                # Check for expected correlations
                prob_score_corr = corr_matrix[0, 1] if not np.isnan(corr_matrix[0, 1]) else 0
                prob_severity_corr = corr_matrix[0, 2] if not np.isnan(corr_matrix[0, 2]) else 0
                
                # Expect moderate positive correlations
                expected_prob_score = 0.4
                expected_prob_severity = 0.3
                
                corr_accuracy_1 = np.exp(-abs(prob_score_corr - expected_prob_score))
                corr_accuracy_2 = np.exp(-abs(prob_severity_corr - expected_prob_severity))
                
                correlation_scores.extend([corr_accuracy_1, corr_accuracy_2])
            
            # 2. Spearman rank correlations
            if len(probabilities) > 3:
                spearman_corr, _ = spearmanr(probabilities, scores)
                if not np.isnan(spearman_corr):
                    rank_accuracy = np.exp(-abs(spearman_corr - 0.3))
                    correlation_scores.append(rank_accuracy)
            
            # 3. Mutual information
            if len(alerts) > 10:
                try:
                    mi_score = mutual_info_regression(
                        np.array(probabilities).reshape(-1, 1), 
                        np.array(scores)
                    )[0]
                    mi_accuracy = min(mi_score * 2, 1.0)  # Scale to [0, 1]
                    correlation_scores.append(mi_accuracy)
                except:
                    pass
            
            return np.mean(correlation_scores) if correlation_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_bayesian_validation_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using Bayesian validation methods."""
        try:
            from scipy.stats import beta, gamma, norm
            
            if len(alerts) < 3:
                return 0.5
            
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            
            bayesian_scores = []
            
            # 1. Beta distribution fitting for probabilities
            if len(probabilities) > 5:
                try:
                    # Fit beta distribution to probabilities
                    params = beta.fit(probabilities)
                    
                    # Calculate likelihood of observed data under fitted distribution
                    log_likelihood = np.sum(beta.logpdf(probabilities, *params))
                    
                    # Convert to accuracy-like score
                    likelihood_accuracy = np.exp(log_likelihood / len(probabilities))
                    bayesian_scores.append(min(likelihood_accuracy, 1.0))
                except:
                    pass
            
            # 2. Prior-posterior consistency
            # Assume Beta(2, 2) prior for probabilities
            prior_alpha, prior_beta = 2, 2
            
            # Update with observed data
            observed_successes = sum(1 for p in probabilities if p > 0.7)  # High probability alerts
            observed_failures = len(probabilities) - observed_successes
            
            posterior_alpha = prior_alpha + observed_successes
            posterior_beta = prior_beta + observed_failures
            
            # Calculate posterior predictive accuracy
            expected_success_rate = posterior_alpha / (posterior_alpha + posterior_beta)
            observed_success_rate = observed_successes / len(probabilities)
            
            posterior_accuracy = np.exp(-abs(expected_success_rate - observed_success_rate))
            bayesian_scores.append(posterior_accuracy)
            
            # 3. Bayesian model comparison
            if len(scores) > 5:
                # Compare different distributions for scores
                models = [
                    lambda x: norm.fit(x),
                    lambda x: gamma.fit(x),
                    lambda x: beta.fit(x)
                ]
                
                model_likelihoods = []
                for model_fit in models:
                    try:
                        params = model_fit(scores)
                        if model_fit == models[0]:  # Normal
                            log_likelihood = np.sum(norm.logpdf(scores, *params))
                        elif model_fit == models[1]:  # Gamma
                            log_likelihood = np.sum(gamma.logpdf(scores, *params))
                        else:  # Beta
                            log_likelihood = np.sum(beta.logpdf(scores, *params))
                        
                        model_likelihoods.append(log_likelihood)
                    except:
                        model_likelihoods.append(-np.inf)
                
                if model_likelihoods:
                    max_likelihood = max(model_likelihoods)
                    model_accuracy = np.exp(max_likelihood / len(scores))
                    bayesian_scores.append(min(model_accuracy, 1.0))
            
            return np.mean(bayesian_scores) if bayesian_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_causal_inference_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using causal inference methods."""
        try:
            from sklearn.linear_model import LinearRegression
            import networkx as nx
            
            if len(alerts) < 8:
                return 0.5
            
            # Extract features for causal analysis
            timestamps = [a.get('timestamp', 0) for a in alerts]
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            severities = [a.get('severity', 1) for a in alerts]
            
            causal_scores = []
            
            # 1. Granger causality approximation
            # Test if past probabilities help predict future scores
            if len(probabilities) > 10:
                # Create lagged features
                lag = min(3, len(probabilities) // 4)
                
                X_lagged = []
                y_target = []
                
                for i in range(lag, len(probabilities)):
                    lagged_features = probabilities[i-lag:i] + scores[i-lag:i]
                    X_lagged.append(lagged_features)
                    y_target.append(scores[i])
                
                if len(X_lagged) > 5:
                    try:
                        # Fit model with lagged features
                        model_with_lags = LinearRegression()
                        model_with_lags.fit(X_lagged, y_target)
                        r2_with_lags = model_with_lags.score(X_lagged, y_target)
                        
                        # Fit model without probability lags (only score lags)
                        X_no_prob_lags = [features[lag:] for features in X_lagged]
                        model_no_prob = LinearRegression()
                        model_no_prob.fit(X_no_prob_lags, y_target)
                        r2_no_prob = model_no_prob.score(X_no_prob_lags, y_target)
                        
                        # Causal strength approximation
                        causal_strength = max(0, r2_with_lags - r2_no_prob)
                        causal_scores.append(causal_strength)
                    except:
                        pass
            
            # 2. Causal graph structure analysis
            # Build simple causal graph
            G = nx.DiGraph()
            nodes = ['probability', 'score', 'severity', 'timestamp']
            G.add_nodes_from(nodes)
            
            # Add edges based on expected causal relationships
            expected_edges = [
                ('timestamp', 'probability'),
                ('probability', 'score'),
                ('score', 'severity'),
                ('probability', 'severity')
            ]
            G.add_edges_from(expected_edges)
            
            # Validate causal structure with data
            feature_data = {
                'probability': probabilities,
                'score': scores,
                'severity': severities,
                'timestamp': timestamps
            }
            
            # Check if data supports causal edges
            edge_validations = []
            for source, target in expected_edges:
                try:
                    source_data = np.array(feature_data[source])
                    target_data = np.array(feature_data[target])
                    
                    # Simple correlation as proxy for causal strength
                    correlation = np.corrcoef(source_data, target_data)[0, 1]
                    if not np.isnan(correlation) and correlation > 0:
                        edge_validations.append(correlation)
                except:
                    continue
            
            if edge_validations:
                causal_structure_score = np.mean(edge_validations)
                causal_scores.append(causal_structure_score)
            
            # 3. Instrumental variable analysis approximation
            # Use timestamp as instrument for probability
            if len(timestamps) > 15:
                try:
                    # First stage: regress probability on timestamp
                    X_instrument = np.array(timestamps).reshape(-1, 1)
                    y_endogenous = np.array(probabilities)
                    
                    first_stage = LinearRegression()
                    first_stage.fit(X_instrument, y_endogenous)
                    predicted_prob = first_stage.predict(X_instrument)
                    
                    # Second stage: regress scores on predicted probability
                    second_stage = LinearRegression()
                    second_stage.fit(predicted_prob.reshape(-1, 1), scores)
                    
                    iv_score = max(0, second_stage.score(predicted_prob.reshape(-1, 1), scores))
                    causal_scores.append(iv_score)
                except:
                    pass
            
            return np.mean(causal_scores) if causal_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_multi_scale_validation_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy across multiple time scales."""
        try:
            from scipy.signal import welch, periodogram
            from sklearn.cluster import KMeans
            
            if len(alerts) < 10:
                return 0.5
            
            # Sort alerts by timestamp
            sorted_alerts = sorted(alerts, key=lambda x: x.get('timestamp', 0))
            timestamps = [a.get('timestamp', 0) for a in sorted_alerts]
            probabilities = [a.get('probability', 0.5) for a in sorted_alerts]
            scores = [a.get('score', 0.5) for a in sorted_alerts]
            
            multi_scale_scores = []
            
            # 1. Short-term scale analysis (immediate correlations)
            window_size = min(5, len(alerts) // 3)
            short_term_accuracies = []
            
            for i in range(0, len(probabilities) - window_size + 1, window_size):
                window_probs = probabilities[i:i + window_size]
                window_scores = scores[i:i + window_size]
                
                if len(window_probs) > 2:
                    correlation = np.corrcoef(window_probs, window_scores)[0, 1]
                    if not np.isnan(correlation):
                        short_term_accuracies.append(abs(correlation))
            
            if short_term_accuracies:
                multi_scale_scores.append(np.mean(short_term_accuracies))
            
            # 2. Medium-term scale analysis (pattern consistency)
            if len(probabilities) > 15:
                # Divide into 3 segments
                segment_size = len(probabilities) // 3
                segments = [
                    probabilities[:segment_size],
                    probabilities[segment_size:2*segment_size],
                    probabilities[2*segment_size:]
                ]
                
                # Calculate consistency across segments
                segment_means = [np.mean(seg) for seg in segments if len(seg) > 0]
                segment_stds = [np.std(seg) for seg in segments if len(seg) > 0]
                
                if len(segment_means) == 3:
                    mean_consistency = 1 - np.std(segment_means)
                    std_consistency = 1 - np.std(segment_stds)
                    
                    medium_term_accuracy = (mean_consistency + std_consistency) / 2
                    multi_scale_scores.append(max(0, medium_term_accuracy))
            
            # 3. Long-term scale analysis (overall trend)
            if len(probabilities) > 20:
                # Fit polynomial trend
                x = np.arange(len(probabilities))
                trend_coeffs = np.polyfit(x, probabilities, 2)  # Quadratic trend
                trend_values = np.polyval(trend_coeffs, x)
                
                # Calculate trend quality
                trend_r2 = 1 - np.sum((probabilities - trend_values)**2) / np.sum((probabilities - np.mean(probabilities))**2)
                trend_accuracy = max(0, min(1, trend_r2))
                multi_scale_scores.append(trend_accuracy)
            
            # 4. Frequency domain analysis
            if len(probabilities) > 32:  # Need sufficient data for frequency analysis
                try:
                    # Compute power spectral density
                    freqs, psd = welch(probabilities, nperseg=min(16, len(probabilities)//2))
                    
                    # Analyze frequency distribution
                    # Good alerts should have balanced frequency content
                    normalized_psd = psd / np.sum(psd)
                    entropy = -np.sum(normalized_psd * np.log(normalized_psd + 1e-8))
                    max_entropy = np.log(len(normalized_psd))
                    
                    frequency_accuracy = entropy / max_entropy if max_entropy > 0 else 0
                    multi_scale_scores.append(frequency_accuracy)
                except:
                    pass
            
            # 5. Multi-resolution clustering
            if len(alerts) > 12:
                # Cluster at different resolutions
                feature_matrix = np.array([probabilities, scores]).T
                
                cluster_consistencies = []
                for n_clusters in [2, 3, 4]:
                    if n_clusters < len(alerts):
                        try:
                            kmeans = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
                            cluster_labels = kmeans.fit_predict(feature_matrix)
                            
                            # Calculate cluster quality (inertia-based)
                            cluster_quality = 1 / (1 + kmeans.inertia_ / len(alerts))
                            cluster_consistencies.append(cluster_quality)
                        except:
                            continue
                
                if cluster_consistencies:
                    multi_scale_scores.append(np.mean(cluster_consistencies))
            
            return np.mean(multi_scale_scores) if multi_scale_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_information_theoretic_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using information theory metrics."""
        try:
            from scipy.stats import entropy
            from sklearn.feature_selection import mutual_info_classif
            
            if len(alerts) < 5:
                return 0.5
            
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            severities = [a.get('severity', 1) for a in alerts]
            
            info_scores = []
            
            # 1. Shannon entropy analysis
            # Discretize continuous values for entropy calculation
            prob_bins = np.histogram_bin_edges(probabilities, bins=min(10, len(probabilities)//2))
            score_bins = np.histogram_bin_edges(scores, bins=min(10, len(scores)//2))
            
            prob_discrete = np.digitize(probabilities, prob_bins)
            score_discrete = np.digitize(scores, score_bins)
            
            # Calculate entropy
            prob_entropy = entropy(np.bincount(prob_discrete))
            score_entropy = entropy(np.bincount(score_discrete))
            
            # Optimal entropy should be moderate (not too low, not too high)
            optimal_entropy = np.log(min(5, len(set(prob_discrete))))
            
            entropy_accuracy_1 = np.exp(-abs(prob_entropy - optimal_entropy))
            entropy_accuracy_2 = np.exp(-abs(score_entropy - optimal_entropy))
            
            info_scores.extend([entropy_accuracy_1, entropy_accuracy_2])
            
            # 2. Mutual information
            if len(alerts) > 8:
                try:
                    # Create binary classification target
                    high_severity_target = [1 if s > np.median(severities) else 0 for s in severities]
                    
                    if len(set(high_severity_target)) > 1:  # Need both classes
                        features = np.array([probabilities, scores]).T
                        mi_scores = mutual_info_classif(features, high_severity_target, random_state=42)
                        
                        # Average mutual information
                        avg_mi = np.mean(mi_scores)
                        mi_accuracy = min(avg_mi * 2, 1.0)  # Scale to [0, 1]
                        info_scores.append(mi_accuracy)
                except:
                    pass
            
            # 3. Conditional entropy
            if len(probabilities) > 10:
                # H(Score | Probability)
                joint_hist, _, _ = np.histogram2d(prob_discrete, score_discrete, bins=5)
                joint_prob = joint_hist / np.sum(joint_hist)
                
                # Calculate conditional entropy H(Y|X)
                conditional_entropy = 0
                prob_marginal = np.sum(joint_prob, axis=1)
                
                for i in range(len(prob_marginal)):
                    if prob_marginal[i] > 0:
                        conditional_dist = joint_prob[i, :] / prob_marginal[i]
                        conditional_dist = conditional_dist[conditional_dist > 0]
                        if len(conditional_dist) > 0:
                            h_y_given_x = -np.sum(conditional_dist * np.log(conditional_dist))
                            conditional_entropy += prob_marginal[i] * h_y_given_x
                
                # Lower conditional entropy indicates better predictability
                max_conditional_entropy = np.log(5)  # Max possible with 5 bins
                conditional_accuracy = 1 - (conditional_entropy / max_conditional_entropy)
                info_scores.append(max(0, conditional_accuracy))
            
            # 4. Information gain
            if len(alerts) > 12:
                # Calculate information gain for different splits
                # Split based on probability threshold
                thresholds = np.percentile(probabilities, [25, 50, 75])
                
                for threshold in thresholds:
                    # Create binary split
                    split_labels = [1 if p > threshold else 0 for p in probabilities]
                    
                    if len(set(split_labels)) > 1:  # Need both splits
                        # Calculate information gain
                        original_entropy = entropy(np.bincount([1 if s > np.median(scores) else 0 for s in scores]))
                        
                        # Weighted entropy after split
                        left_indices = [i for i, label in enumerate(split_labels) if label == 0]
                        right_indices = [i for i, label in enumerate(split_labels) if label == 1]
                        
                        if len(left_indices) > 0 and len(right_indices) > 0:
                            left_scores = [scores[i] for i in left_indices]
                            right_scores = [scores[i] for i in right_indices]
                            
                            left_labels = [1 if s > np.median(left_scores) else 0 for s in left_scores]
                            right_labels = [1 if s > np.median(right_scores) else 0 for s in right_scores]
                            
                            left_entropy = entropy(np.bincount(left_labels)) if len(set(left_labels)) > 1 else 0
                            right_entropy = entropy(np.bincount(right_labels)) if len(set(right_labels)) > 1 else 0
                            
                            weighted_entropy = (len(left_indices) * left_entropy + 
                                              len(right_indices) * right_entropy) / len(split_labels)
                            
                            information_gain = original_entropy - weighted_entropy
                            info_scores.append(max(0, information_gain))
            
            return np.mean(info_scores) if info_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_robust_statistical_accuracy(self, key: str, alerts: List[Dict]) -> float:
        """Calculate accuracy using robust statistical methods."""
        try:
            from scipy.stats import trim_mean, iqr, jarque_bera, anderson
            from sklearn.covariance import MinCovDet
            
            if len(alerts) < 5:
                return 0.5
            
            probabilities = np.array([a.get('probability', 0.5) for a in alerts])
            scores = np.array([a.get('score', 0.5) for a in alerts])
            severities = np.array([a.get('severity', 1) for a in alerts])
            
            robust_scores = []
            
            # 1. Robust location and scale estimates
            # Compare robust vs non-robust estimates
            prob_mean = np.mean(probabilities)
            prob_trim_mean = trim_mean(probabilities, 0.1)  # 10% trimmed mean
            prob_median = np.median(probabilities)
            
            # Good data should have consistent location estimates
            location_consistency = 1 - np.std([prob_mean, prob_trim_mean, prob_median]) / np.mean([prob_mean, prob_trim_mean, prob_median])
            robust_scores.append(max(0, location_consistency))
            
            # 2. Robust scale estimates
            prob_std = np.std(probabilities)
            prob_mad = np.median(np.abs(probabilities - prob_median))
            prob_iqr = iqr(probabilities)
            
            if prob_std > 0:
                # Scale consistency
                scale_estimates = [prob_std, prob_mad * 1.4826, prob_iqr / 1.349]  # Normalize to std equivalents
                scale_consistency = 1 - np.std(scale_estimates) / np.mean(scale_estimates)
                robust_scores.append(max(0, scale_consistency))
            
            # 3. Outlier detection consistency
            if len(probabilities) > 8:
                # Multiple outlier detection methods
                outlier_methods = []
                
                # IQR method
                Q1 = np.percentile(probabilities, 25)
                Q3 = np.percentile(probabilities, 75)
                IQR = Q3 - Q1
                iqr_outliers = set(np.where((probabilities < Q1 - 1.5 * IQR) | 
                                           (probabilities > Q3 + 1.5 * IQR))[0])
                outlier_methods.append(iqr_outliers)
                
                # MAD method
                mad_threshold = 2.5
                mad_outliers = set(np.where(np.abs(probabilities - prob_median) / prob_mad > mad_threshold)[0])
                outlier_methods.append(mad_outliers)
                
                # Z-score method (modified for robustness)
                modified_z_scores = 0.6745 * (probabilities - prob_median) / prob_mad
                zscore_outliers = set(np.where(np.abs(modified_z_scores) > 3.5)[0])
                outlier_methods.append(zscore_outliers)
                
                # Consensus among methods
                all_indices = set(range(len(probabilities)))
                method_agreements = []
                
                for i in all_indices:
                    votes = sum(1 for method_outliers in outlier_methods if i in method_outliers)
                    method_agreements.append(votes)
                
                # Good data should have consistent outlier detection
                agreement_score = 1 - np.std(method_agreements) / (len(outlier_methods) + 1)
                robust_scores.append(max(0, agreement_score))
            
            # 4. Minimum Covariance Determinant (MCD) for multivariate robustness
            if len(alerts) > 10:
                try:
                    feature_matrix = np.column_stack([probabilities, scores, severities])
                    mcd = MinCovDet(random_state=42)
                    mcd.fit(feature_matrix)
                    
                    # Mahalanobis distances
                    mahal_distances = mcd.mahalanobis(feature_matrix)
                    
                    # Compare with standard covariance
                    standard_cov = np.cov(feature_matrix.T)
                    if np.linalg.det(standard_cov) > 1e-10:  # Check for singularity
                        inv_cov = np.linalg.inv(standard_cov)
                        mean_vec = np.mean(feature_matrix, axis=0)
                        
                        standard_mahal = []
                        for row in feature_matrix:
                            diff = row - mean_vec
                            dist = np.sqrt(diff.T @ inv_cov @ diff)
                            standard_mahal.append(dist)
                        
                        # Compare robust vs standard distances
                        distance_correlation = np.corrcoef(mahal_distances, standard_mahal)[0, 1]
                        if not np.isnan(distance_correlation):
                            # High correlation indicates consistent structure
                            robust_scores.append(abs(distance_correlation))
                except:
                    pass
            
            # 5. Robust normality tests
            if len(probabilities) > 7:
                # Jarque-Bera test
                try:
                    jb_stat, jb_p = jarque_bera(probabilities)
                    # Higher p-value indicates more normal distribution
                    normality_score = min(jb_p * 2, 1.0)
                    robust_scores.append(normality_score)
                except:
                    pass
                
                # Anderson-Darling test
                try:
                    ad_stat, critical_values, significance_levels = anderson(probabilities, dist='norm')
                    # Compare with critical value at 5% significance
                    if len(critical_values) > 2:  # Usually has critical values for [15%, 10%, 5%, 2.5%, 1%]
                        critical_5pct = critical_values[2]
                        ad_score = np.exp(-(ad_stat - critical_5pct)) if ad_stat > critical_5pct else 1.0
                        robust_scores.append(max(0, min(1, ad_score)))
                except:
                    pass
            
            # 6. Robust correlation analysis
            if len(probabilities) == len(scores) and len(probabilities) > 5:
                from scipy.stats import spearmanr, kendalltau
                
                # Multiple correlation measures
                pearson_corr = np.corrcoef(probabilities, scores)[0, 1]
                spearman_corr, _ = spearmanr(probabilities, scores)
                kendall_corr, _ = kendalltau(probabilities, scores)
                
                correlations = [corr for corr in [pearson_corr, spearman_corr, kendall_corr] 
                              if not np.isnan(corr)]
                
                if correlations:
                    # Consistency among correlation measures
                    corr_consistency = 1 - np.std(correlations) / (np.mean(np.abs(correlations)) + 1e-8)
                    robust_scores.append(max(0, corr_consistency))
            
            return np.mean(robust_scores) if robust_scores else 0.5
            
        except Exception as e:
            return 0.5
    
    def _calculate_accuracy_component_weights(self, accuracy_components: Dict[str, float], alerts: List[Dict]) -> Dict[str, float]:
        """Calculate adaptive weights for different accuracy components."""
        try:
            weights = {}
            n_alerts = len(alerts)
            
            # Base weights
            base_weights = {
                'statistical': 0.15,
                'temporal': 0.12,
                'cross_validation': 0.18,
                'ensemble': 0.14,
                'correlation': 0.10,
                'bayesian': 0.11,
                'causal': 0.08,
                'multi_scale': 0.05,
                'information': 0.04,
                'robust': 0.03
            }
            
            # Adjust weights based on data size
            if n_alerts < 10:
                # Favor simpler methods for small datasets
                base_weights['statistical'] *= 1.5
                base_weights['correlation'] *= 1.3
                base_weights['cross_validation'] *= 0.3
                base_weights['ensemble'] *= 0.5
            elif n_alerts > 50:
                # Favor complex methods for large datasets
                base_weights['cross_validation'] *= 1.4
                base_weights['ensemble'] *= 1.3
                base_weights['multi_scale'] *= 2.0
                base_weights['information'] *= 1.8
            
            # Adjust based on component reliability
            for component, score in accuracy_components.items():
                if score is not None and component in base_weights:
                    # Boost weight if component gives reasonable scores
                    if 0.3 <= score <= 0.9:
                        base_weights[component] *= 1.2
                    elif score < 0.1 or score > 0.95:
                        # Reduce weight for extreme scores
                        base_weights[component] *= 0.7
            
            # Normalize weights
            total_weight = sum(base_weights.values())
            for component in base_weights:
                weights[component] = base_weights[component] / total_weight
            
            return weights
            
        except Exception as e:
            # Return uniform weights as fallback
            n_components = len(accuracy_components)
            return {comp: 1.0 / n_components for comp in accuracy_components.keys()}
    
    def _calculate_accuracy_confidence_adjustment(self, alerts: List[Dict]) -> float:
        """Calculate confidence adjustment factor based on sample characteristics."""
        try:
            n_alerts = len(alerts)
            
            # Base confidence based on sample size
            if n_alerts < 5:
                base_confidence = 0.6
            elif n_alerts < 15:
                base_confidence = 0.8
            elif n_alerts < 50:
                base_confidence = 0.95
            else:
                base_confidence = 1.0
            
            # Adjust based on data quality indicators
            quality_adjustments = []
            
            # 1. Timestamp regularity
            timestamps = [a.get('timestamp', 0) for a in alerts]
            if len(timestamps) > 3:
                time_diffs = np.diff(sorted(timestamps))
                if len(time_diffs) > 0:
                    cv_time = np.std(time_diffs) / np.mean(time_diffs) if np.mean(time_diffs) > 0 else 1
                    time_regularity = np.exp(-cv_time)
                    quality_adjustments.append(time_regularity)
            
            # 2. Feature completeness
            complete_alerts = 0
            for alert in alerts:
                if all(key in alert for key in ['probability', 'score', 'severity', 'timestamp']):
                    complete_alerts += 1
            
            completeness_ratio = complete_alerts / len(alerts)
            quality_adjustments.append(completeness_ratio)
            
            # 3. Value range sanity
            probabilities = [a.get('probability', 0.5) for a in alerts]
            scores = [a.get('score', 0.5) for a in alerts]
            
            prob_in_range = sum(1 for p in probabilities if 0 <= p <= 1) / len(probabilities)
            score_reasonableness = sum(1 for s in scores if 0 <= s <= 1) / len(scores)
            
            quality_adjustments.extend([prob_in_range, score_reasonableness])
            
            # Calculate final confidence adjustment
            if quality_adjustments:
                quality_factor = np.mean(quality_adjustments)
                final_confidence = base_confidence * (0.7 + 0.3 * quality_factor)
            else:
                final_confidence = base_confidence
            
            return np.clip(final_confidence, 0.5, 1.0)
            
        except Exception as e:
            return 0.8  # Conservative default
    
    def _validate_alert_against_ground_truth(self, alert: Dict, key: str) -> int:
        """Validate alert against real ground truth using multi-source verification."""
        try:
            # Multi-source ground truth validation
            validation_sources = {
                'seismic_validation': self._validate_against_seismic_networks(alert, key),
                'geological_validation': self._validate_against_geological_data(alert, key), 
                'historical_validation': self._validate_against_historical_records(alert, key),
                'external_api_validation': self._validate_against_external_apis(alert, key),
                'database_validation': self._validate_against_stored_ground_truth(alert, key),
                'cross_correlation_validation': self._validate_cross_correlation_analysis(alert, key),
                'statistical_validation': self._validate_statistical_consistency(alert, key),
                'temporal_validation': self._validate_temporal_coherence(alert, key)
            }
            
            # Calculate weighted consensus with uncertainty quantification
            weights = self._calculate_validation_source_weights(alert, key)
            confidence_scores = []
            weighted_sum = 0.0
            total_weight = 0.0
            
            for source, result in validation_sources.items():
                if result is not None:
                    weight = weights.get(source, 1.0)
                    confidence = result.get('confidence', 0.5)
                    validation = result.get('validation', 0)
                    
                    weighted_sum += validation * weight * confidence
                    total_weight += weight * confidence
                    confidence_scores.append(confidence)
            
            if total_weight > 0:
                consensus_score = weighted_sum / total_weight
            else:
                consensus_score = 0.5
                
            # Apply uncertainty adjustment based on source agreement
            uncertainty = self._calculate_validation_uncertainty(validation_sources, confidence_scores)
            adjusted_score = consensus_score * (1.0 - uncertainty * 0.3)
            
            # Convert to binary with adaptive threshold
            adaptive_threshold = self._calculate_adaptive_threshold(alert, key, confidence_scores)
            return 1 if adjusted_score > adaptive_threshold else 0
            
        except Exception as e:
            self.logger.error(f"Error validating alert ground truth: {str(e)}")
            return 0  # Conservative default
    
    async def _validate_against_seismic_networks(self, alert: Dict, key: str) -> Dict:
        """Validate alert against real-time seismic network data using existing stream processing infrastructure."""
        try:
            # Use existing Kafka stream manager for real-time seismic validation
            if hasattr(self, 'kafka_stream_manager') and self.kafka_stream_manager:
                try:
                    # Query recent seismic events from stream
                    alert_time = alert.get('timestamp', datetime.utcnow())
                    alert_location = alert.get('location', {})
                    lat = alert_location.get('lat', 0.0)
                    lon = alert_location.get('lon', 0.0)
                    
                    stream_events = await self.kafka_stream_manager.get_recent_events(
                        topic='prometheus_seismic_stream',
                        time_window=timedelta(hours=2),
                        location_filter={'lat': lat, 'lon': lon, 'radius_km': 100}
                    )
                    
                    if stream_events:
                        correlation_score = await self._calculate_stream_event_correlation(alert, stream_events)
                        return {
                            'validation': 1 if correlation_score > 0.7 else 0,
                            'confidence': correlation_score,
                            'stream_events_found': len(stream_events),
                            'source': 'kafka_stream'
                        }
                except Exception as stream_error:
                    self.logger.warning(f"Stream validation failed: {stream_error}")
            
            # Use existing external data connectors as fallback
            if hasattr(self, 'external_data_connectors') and self.external_data_connectors:
                validation_results = []
                
                # USGS connector
                if 'USGS' in self.external_data_connectors:
                    try:
                        usgs_data = await self.external_data_connectors['USGS'].get_earthquake_data(
                            start_time=alert_time - timedelta(hours=1),
                            end_time=alert_time + timedelta(hours=1),
                            min_latitude=lat - 0.5, max_latitude=lat + 0.5,
                            min_longitude=lon - 0.5, max_longitude=lon + 0.5,
                            min_magnitude=2.0
                        )
                        
                        usgs_validation = 1 if usgs_data and len(usgs_data) > 0 else 0
                        usgs_confidence = min(1.0, len(usgs_data) * 0.3) if usgs_data else 0.2
                        validation_results.append({'network': 'USGS', 'validation': usgs_validation, 'confidence': usgs_confidence})
                        
                    except Exception as usgs_error:
                        validation_results.append({'network': 'USGS', 'validation': 0, 'confidence': 0.1, 'error': str(usgs_error)})
                
                # Use database integration for historical comparison
                if hasattr(self, 'database_integration') and self.database_integration:
                    try:
                        historical_events = await self.database_integration.query_seismic_events(
                            lat, lon, radius_km=50, time_window_days=30
                        )
                        
                        if historical_events:
                            historical_validation = await self._validate_against_historical_pattern(alert, historical_events)
                            validation_results.append({
                                'network': 'HISTORICAL_DB',
                                'validation': historical_validation['validation'],
                                'confidence': historical_validation['confidence']
                            })
                        else:
                            validation_results.append({'network': 'HISTORICAL_DB', 'validation': 0, 'confidence': 0.3})
                            
                    except Exception as db_error:
                        validation_results.append({'network': 'HISTORICAL_DB', 'validation': 0, 'confidence': 0.1, 'error': str(db_error)})
                
                # Calculate consensus
                if validation_results:
                    validations = [r.get('validation', 0) for r in validation_results]
                    confidences = [r.get('confidence', 0.3) for r in validation_results]
                    
                    weighted_validation = np.average(validations, weights=confidences) if confidences else 0
                    consensus_confidence = np.mean(confidences)
                    
                    return {
                        'validation': int(weighted_validation > 0.5),
                        'confidence': consensus_confidence,
                        'details': validation_results
                    }
            
            return {'validation': 0, 'confidence': 0.3, 'error': 'No validation infrastructure available'}
            
        except Exception as e:
            self.logger.error(f"Seismic network validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.3, 'error': str(e)}
    
    async def _validate_against_geological_data(self, alert: Dict, key: str) -> Dict:
        """Validate alert against geological databases using existing database integration and geological survey connectors."""
        try:
            alert_location = alert.get('location', {})
            if not alert_location:
                return {'validation': 0, 'confidence': 0.2}
            
            lat = alert_location.get('lat', 0)
            lon = alert_location.get('lon', 0)
            geological_validations = []
            
            # Use existing database integration for geological context
            if hasattr(self, 'database_integration') and self.database_integration:
                try:
                    geological_context = await self.database_integration.get_geological_context(
                        lat, lon, radius_km=100
                    )
                    
                    if geological_context:
                        # Tectonic setting validation
                        tectonic_data = geological_context.get('tectonic_setting', {})
                        geological_validations.append({
                            'source': 'DATABASE_TECTONIC',
                            'validation': 1 if tectonic_data.get('seismic_potential', 0) > 0.3 else 0,
                            'confidence': tectonic_data.get('confidence', 0.7),
                            'setting': tectonic_data.get('setting', 'unknown')
                        })
                        
                        # Geological hazards validation
                        hazards = geological_context.get('hazards', {})
                        hazard_level = hazards.get('seismic_hazard_level', 0)
                        geological_validations.append({
                            'source': 'DATABASE_HAZARDS',
                            'validation': 1 if hazard_level > 0.4 else 0,
                            'confidence': 0.8,
                            'hazard_level': hazard_level
                        })
                        
                except Exception as db_error:
                    self.logger.warning(f"Database geological validation failed: {db_error}")
            
            # Use existing geological survey connectors
            if hasattr(self, 'data_connectors') and 'geological_surveys' in self.data_connectors:
                geological_surveys = self.data_connectors['geological_surveys']
                
                for survey_name, survey_connector in geological_surveys.items():
                    try:
                        survey_data = await survey_connector.get_geological_data(
                            latitude=lat,
                            longitude=lon,
                            radius_km=50,
                            data_types=['seismic_hazard', 'geological_units', 'faults']
                        )
                        
                        if survey_data:
                            seismic_hazard = survey_data.get('seismic_hazard_level', 0)
                            fault_proximity = survey_data.get('fault_proximity_km', 1000)
                            
                            validation_score = 0
                            if seismic_hazard > 0.3:
                                validation_score += 0.5
                            if fault_proximity < 50:  # Within 50km of known fault
                                validation_score += 0.5
                            
                            geological_validations.append({
                                'source': f'SURVEY_{survey_name.upper()}',
                                'validation': 1 if validation_score >= 0.5 else 0,
                                'confidence': survey_data.get('data_quality', 0.7),
                                'seismic_hazard': seismic_hazard,
                                'fault_proximity': fault_proximity
                            })
                        else:
                            geological_validations.append({
                                'source': f'SURVEY_{survey_name.upper()}',
                                'validation': 0,
                                'confidence': 0.3
                            })
                            
                    except Exception as survey_error:
                        self.logger.warning(f"Survey {survey_name} validation failed: {survey_error}")
                        geological_validations.append({
                            'source': f'SURVEY_{survey_name.upper()}',
                            'validation': 0,
                            'confidence': 0.1,
                            'error': str(survey_error)
                        })
            
            # Use existing external data manager for additional validation
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                try:
                    geological_features = await self.external_data_manager.query_geological_features(
                        location={'lat': lat, 'lon': lon},
                        feature_types=['seismic_zones', 'volcanic_regions', 'fault_systems']
                    )
                    
                    if geological_features:
                        feature_score = min(1.0, len(geological_features) * 0.3)
                        geological_validations.append({
                            'source': 'EXTERNAL_FEATURES',
                            'validation': 1 if feature_score > 0.4 else 0,
                            'confidence': feature_score,
                            'features_found': len(geological_features)
                        })
                    else:
                        geological_validations.append({
                            'source': 'EXTERNAL_FEATURES',
                            'validation': 0,
                            'confidence': 0.4
                        })
                        
                except Exception as external_error:
                    self.logger.warning(f"External features validation failed: {external_error}")
            
            # Use existing knowledge graph for geological relationships
            if hasattr(self, 'knowledge_graph') and self.knowledge_graph:
                try:
                    geological_entities = await self.knowledge_graph.query_spatial_entities(
                        lat, lon, 
                        entity_types=['geological_unit', 'seismic_zone', 'fault_system', 'volcanic_feature'],
                        radius_km=100
                    )
                    
                    if geological_entities:
                        entity_score = min(1.0, len(geological_entities) * 0.2)
                        geological_validations.append({
                            'source': 'KNOWLEDGE_GRAPH',
                            'validation': 1 if entity_score > 0.3 else 0,
                            'confidence': entity_score,
                            'entities_found': len(geological_entities)
                        })
                    else:
                        geological_validations.append({
                            'source': 'KNOWLEDGE_GRAPH',
                            'validation': 0,
                            'confidence': 0.3
                        })
                        
                except Exception as kg_error:
                    self.logger.warning(f"Knowledge graph geological validation failed: {kg_error}")
            
            # Calculate consensus validation
            if not geological_validations:
                return {'validation': 0, 'confidence': 0.2}
            
            validations = [v.get('validation', 0) for v in geological_validations]
            confidences = [v.get('confidence', 0.5) for v in geological_validations]
            
            weighted_validation = np.average(validations, weights=confidences) if confidences else 0
            consensus_confidence = np.mean(confidences)
            
            return {
                'validation': int(weighted_validation > 0.5),
                'confidence': consensus_confidence,
                'details': geological_validations,
                'sources_validated': len(geological_validations)
            }
            
        except Exception as e:
            self.logger.error(f"Geological validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.2, 'error': str(e)}
    
    def _validate_against_historical_records(self, alert: Dict, key: str) -> Dict:
        """Validate alert against historical seismic and geological records."""
        try:
            # Query historical database for similar events
            historical_matches = self._query_historical_database(
                alert.get('location', {}),
                alert.get('magnitude', 0),
                alert.get('depth', 0),
                key
            )
            
            if not historical_matches:
                return {'validation': 0, 'confidence': 0.6}
            
            # Calculate similarity scores
            similarity_scores = []
            for match in historical_matches:
                spatial_similarity = self._calculate_spatial_similarity(
                    alert.get('location', {}), 
                    match.get('location', {})
                )
                magnitude_similarity = self._calculate_magnitude_similarity(
                    alert.get('magnitude', 0),
                    match.get('magnitude', 0)
                )
                temporal_pattern_similarity = self._calculate_temporal_pattern_similarity(
                    alert.get('timestamp', 0),
                    match.get('timestamp', 0)
                )
                
                overall_similarity = (
                    0.4 * spatial_similarity +
                    0.3 * magnitude_similarity +
                    0.3 * temporal_pattern_similarity
                )
                
                similarity_scores.append({
                    'match_id': match.get('id'),
                    'similarity': overall_similarity,
                    'confirmed': match.get('confirmed', False)
                })
            
            # Find best matches
            best_matches = sorted(similarity_scores, key=lambda x: x['similarity'], reverse=True)[:5]
            
            if best_matches:
                # Calculate validation based on historical confirmation
                confirmed_matches = [m for m in best_matches if m['confirmed'] and m['similarity'] > 0.7]
                high_similarity_matches = [m for m in best_matches if m['similarity'] > 0.8]
                
                if confirmed_matches:
                    validation = 1
                    confidence = min(0.95, np.mean([m['similarity'] for m in confirmed_matches]))
                elif high_similarity_matches:
                    validation = 1
                    confidence = 0.7
                else:
                    validation = 0
                    confidence = 0.8
                    
                return {
                    'validation': validation,
                    'confidence': confidence,
                    'matches_found': len(historical_matches),
                    'best_similarity': best_matches[0]['similarity'],
                    'confirmed_matches': len(confirmed_matches)
                }
            else:
                return {'validation': 0, 'confidence': 0.6}
                
        except Exception as e:
            self.logger.error(f"Historical validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.4}
    
    def _validate_against_external_apis(self, alert: Dict, key: str) -> Dict:
        """Validate alert against external seismic and geological APIs."""
        try:
            import requests
            import asyncio
            import aiohttp
            from concurrent.futures import ThreadPoolExecutor, as_completed
            
            validation_apis = [
                {
                    'name': 'EMSC',
                    'url': 'https://www.seismicportal.eu/fdsnws/event/1/query',
                    'params': self._build_emsc_params(alert)
                },
                {
                    'name': 'GeoNet',
                    'url': 'https://api.geonet.org.nz/quake',
                    'params': self._build_geonet_params(alert)
                },
                {
                    'name': 'JMA',
                    'url': 'https://www.data.jma.go.jp/svd/eqev/data/bulletin/hypo.php',
                    'params': self._build_jma_params(alert)
                }
            ]
            
            api_results = []
            
            def validate_single_api(api_config):
                try:
                    response = requests.get(
                        api_config['url'], 
                        params=api_config['params'],
                        timeout=15,
                        headers={'User-Agent': 'Prometheus-SeismicValidation/1.0'}
                    )
                    
                    if response.status_code == 200:
                        return self._process_api_response(api_config['name'], response, alert, key)
                    else:
                        return {'name': api_config['name'], 'validation': 0, 'confidence': 0.3}
                        
                except Exception as e:
                    self.logger.warning(f"API {api_config['name']} validation failed: {str(e)}")
                    return {'name': api_config['name'], 'validation': 0, 'confidence': 0.2}
            
            # Parallel API validation
            with ThreadPoolExecutor(max_workers=3) as executor:
                futures = [executor.submit(validate_single_api, api) for api in validation_apis]
                
                for future in as_completed(futures, timeout=20):
                    try:
                        result = future.result()
                        api_results.append(result)
                    except Exception as e:
                        self.logger.warning(f"API validation thread failed: {str(e)}")
            
            if not api_results:
                return {'validation': 0, 'confidence': 0.2}
            
            # Calculate consensus from external APIs
            validations = [r.get('validation', 0) for r in api_results]
            confidences = [r.get('confidence', 0.3) for r in api_results]
            
            # Weight by API reliability
            api_weights = {'EMSC': 0.9, 'GeoNet': 0.8, 'JMA': 0.85}
            
            weighted_validation = 0.0
            total_weight = 0.0
            
            for result in api_results:
                weight = api_weights.get(result['name'], 0.7)
                weighted_validation += result['validation'] * weight * result['confidence']
                total_weight += weight * result['confidence']
            
            if total_weight > 0:
                final_validation = weighted_validation / total_weight
                consensus_confidence = np.mean(confidences)
            else:
                final_validation = 0.0
                consensus_confidence = 0.2
            
            return {
                'validation': int(final_validation > 0.5),
                'confidence': consensus_confidence,
                'api_results': api_results,
                'apis_responded': len(api_results)
            }
            
        except Exception as e:
            self.logger.error(f"External API validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.2}
    
    def _validate_against_stored_ground_truth(self, alert: Dict, key: str) -> Dict:
        """Validate alert against stored ground truth database."""
        try:
            # Query ground truth database
            ground_truth_records = self._query_ground_truth_database(alert, key)
            
            if not ground_truth_records:
                return {'validation': 0, 'confidence': 0.4}
            
            # Find exact and similar matches
            exact_matches = []
            similar_matches = []
            
            for record in ground_truth_records:
                match_score = self._calculate_ground_truth_match_score(alert, record)
                
                if match_score > 0.95:
                    exact_matches.append(record)
                elif match_score > 0.8:
                    similar_matches.append(record)
            
            validation_result = 0
            confidence = 0.4
            
            if exact_matches:
                # Use exact match validation
                confirmed_exact = [r for r in exact_matches if r.get('confirmed', False)]
                if confirmed_exact:
                    validation_result = 1
                    confidence = 0.98
                else:
                    disputed_exact = [r for r in exact_matches if r.get('disputed', False)]
                    if disputed_exact:
                        validation_result = 0
                        confidence = 0.85
                    else:
                        validation_result = int(len(exact_matches) > len(exact_matches) // 2)
                        confidence = 0.9
            
            elif similar_matches:
                # Use similar match validation with weighted scoring
                confirmed_similar = [r for r in similar_matches if r.get('confirmed', False)]
                disputed_similar = [r for r in similar_matches if r.get('disputed', False)]
                
                if confirmed_similar and len(confirmed_similar) > len(disputed_similar):
                    validation_result = 1
                    confidence = 0.8
                elif disputed_similar and len(disputed_similar) > len(confirmed_similar):
                    validation_result = 0
                    confidence = 0.75
                else:
                    # Use statistical validation
                    similarity_scores = [self._calculate_ground_truth_match_score(alert, r) for r in similar_matches]
                    avg_similarity = np.mean(similarity_scores)
                    validation_result = int(avg_similarity > 0.85)
                    confidence = min(0.7, avg_similarity)
            
            return {
                'validation': validation_result,
                'confidence': confidence,
                'exact_matches': len(exact_matches),
                'similar_matches': len(similar_matches),
                'total_records': len(ground_truth_records)
            }
            
        except Exception as e:
            self.logger.error(f"Stored ground truth validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.3}
    
    def _validate_cross_correlation_analysis(self, alert: Dict, key: str) -> Dict:
        """Validate alert using cross-correlation with multiple data streams."""
        try:
            from scipy.signal import correlate, find_peaks
            from scipy.stats import pearsonr, spearmanr
            
            # Get time series data around alert time
            alert_time = alert.get('timestamp', 0)
            time_window = 3600  # 1 hour window
            
            # Collect multiple data streams for correlation
            data_streams = self._collect_correlation_data_streams(alert_time, time_window, key)
            
            if len(data_streams) < 2:
                return {'validation': 0, 'confidence': 0.3}
            
            correlation_results = []
            
            # Cross-correlate all pairs of data streams
            for i, stream1 in enumerate(data_streams):
                for j, stream2 in enumerate(data_streams[i+1:], i+1):
                    try:
                        # Calculate cross-correlation
                        correlation = correlate(stream1['data'], stream2['data'], mode='full')
                        max_correlation = np.max(np.abs(correlation))
                        
                        # Calculate Pearson correlation
                        if len(stream1['data']) == len(stream2['data']):
                            pearson_corr, p_value = pearsonr(stream1['data'], stream2['data'])
                            spearman_corr, _ = spearmanr(stream1['data'], stream2['data'])
                        else:
                            # Align data for correlation
                            min_len = min(len(stream1['data']), len(stream2['data']))
                            pearson_corr, p_value = pearsonr(
                                stream1['data'][:min_len], 
                                stream2['data'][:min_len]
                            )
                            spearman_corr, _ = spearmanr(
                                stream1['data'][:min_len], 
                                stream2['data'][:min_len]
                            )
                        
                        correlation_results.append({
                            'stream1': stream1['name'],
                            'stream2': stream2['name'],
                            'max_correlation': max_correlation,
                            'pearson_correlation': abs(pearson_corr),
                            'spearman_correlation': abs(spearman_corr),
                            'p_value': p_value,
                            'significant': p_value < 0.05 if not np.isnan(p_value) else False
                        })
                        
                    except Exception as e:
                        self.logger.warning(f"Correlation calculation failed: {str(e)}")
                        continue
            
            if not correlation_results:
                return {'validation': 0, 'confidence': 0.3}
            
            # Analyze correlation patterns
            significant_correlations = [r for r in correlation_results if r['significant']]
            high_correlations = [r for r in correlation_results if r['pearson_correlation'] > 0.7]
            
            # Validation based on correlation strength and significance
            if significant_correlations and high_correlations:
                avg_correlation = np.mean([r['pearson_correlation'] for r in high_correlations])
                validation = 1
                confidence = min(0.9, avg_correlation)
            elif significant_correlations:
                avg_correlation = np.mean([r['pearson_correlation'] for r in significant_correlations])
                validation = int(avg_correlation > 0.5)
                confidence = min(0.7, avg_correlation)
            else:
                avg_correlation = np.mean([r['pearson_correlation'] for r in correlation_results])
                validation = int(avg_correlation > 0.6)
                confidence = min(0.6, avg_correlation)
            
            return {
                'validation': validation,
                'confidence': confidence,
                'correlations_analyzed': len(correlation_results),
                'significant_correlations': len(significant_correlations),
                'high_correlations': len(high_correlations),
                'avg_correlation': np.mean([r['pearson_correlation'] for r in correlation_results])
            }
            
        except Exception as e:
            self.logger.error(f"Cross-correlation validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.3}
    
    def _validate_statistical_consistency(self, alert: Dict, key: str) -> Dict:
        """Validate alert using advanced statistical consistency tests."""
        try:
            from scipy import stats
            from scipy.stats import kstest, anderson, shapiro, jarque_bera
            
            # Collect statistical validation data
            validation_data = self._collect_statistical_validation_data(alert, key)
            
            if not validation_data or len(validation_data) < 10:
                return {'validation': 0, 'confidence': 0.3}
            
            statistical_tests = {}
            
            # Normality tests
            try:
                shapiro_stat, shapiro_p = shapiro(validation_data)
                statistical_tests['shapiro'] = {'statistic': shapiro_stat, 'p_value': shapiro_p}
                
                jb_stat, jb_p = jarque_bera(validation_data)
                statistical_tests['jarque_bera'] = {'statistic': jb_stat, 'p_value': jb_p}
                
                anderson_result = anderson(validation_data, dist='norm')
                statistical_tests['anderson'] = {
                    'statistic': anderson_result.statistic,
                    'critical_values': anderson_result.critical_values,
                    'significance_level': anderson_result.significance_level
                }
            except Exception as e:
                self.logger.warning(f"Normality tests failed: {str(e)}")
            
            # Distribution comparison tests
            alert_metrics = [
                alert.get('probability', 0.5),
                alert.get('score', 0.5),
                alert.get('magnitude', 0) / 10.0,  # Normalize
                alert.get('severity', 1) / 5.0     # Normalize
            ]
            
            # Two-sample tests
            try:
                if len(validation_data) >= 8:  # Minimum for meaningful comparison
                    ks_stat, ks_p = stats.ks_2samp(alert_metrics, validation_data[:len(alert_metrics)])
                    statistical_tests['ks_2samp'] = {'statistic': ks_stat, 'p_value': ks_p}
                    
                    mannwhitney_stat, mannwhitney_p = stats.mannwhitneyu(
                        alert_metrics, validation_data[:len(alert_metrics)], 
                        alternative='two-sided'
                    )
                    statistical_tests['mann_whitney'] = {
                        'statistic': mannwhitney_stat, 
                        'p_value': mannwhitney_p
                    }
            except Exception as e:
                self.logger.warning(f"Two-sample tests failed: {str(e)}")
            
            # Outlier detection
            try:
                z_scores = np.abs(stats.zscore(validation_data))
                outliers = np.sum(z_scores > 3)
                statistical_tests['outlier_analysis'] = {
                    'outliers_count': outliers,
                    'outlier_percentage': outliers / len(validation_data)
                }
                
                # IQR-based outlier detection
                q1, q3 = np.percentile(validation_data, [25, 75])
                iqr = q3 - q1
                lower_bound = q1 - 1.5 * iqr
                upper_bound = q3 + 1.5 * iqr
                iqr_outliers = np.sum((validation_data < lower_bound) | (validation_data > upper_bound))
                
                statistical_tests['iqr_outliers'] = {
                    'count': iqr_outliers,
                    'percentage': iqr_outliers / len(validation_data)
                }
            except Exception as e:
                self.logger.warning(f"Outlier detection failed: {str(e)}")
            
            # Calculate validation based on statistical tests
            validation_score = 0.0
            confidence_factors = []
            
            # Normality test evaluation
            if 'shapiro' in statistical_tests:
                shapiro_p = statistical_tests['shapiro']['p_value']
                if shapiro_p > 0.05:  # Normal distribution
                    validation_score += 0.3
                    confidence_factors.append(0.8)
                else:
                    confidence_factors.append(0.6)
            
            # Two-sample test evaluation  
            if 'ks_2samp' in statistical_tests:
                ks_p = statistical_tests['ks_2samp']['p_value']
                if ks_p > 0.05:  # Distributions are similar
                    validation_score += 0.4
                    confidence_factors.append(0.85)
                else:
                    confidence_factors.append(0.7)
            
            # Outlier evaluation
            if 'outlier_analysis' in statistical_tests:
                outlier_pct = statistical_tests['outlier_analysis']['outlier_percentage']
                if outlier_pct < 0.05:  # Less than 5% outliers
                    validation_score += 0.3
                    confidence_factors.append(0.8)
                else:
                    confidence_factors.append(0.6)
            
            final_validation = int(validation_score > 0.5)
            final_confidence = np.mean(confidence_factors) if confidence_factors else 0.5
            
            return {
                'validation': final_validation,
                'confidence': final_confidence,
                'statistical_tests': statistical_tests,
                'validation_score': validation_score,
                'data_points': len(validation_data)
            }
            
        except Exception as e:
            self.logger.error(f"Statistical consistency validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.3}
    
    def _validate_temporal_coherence(self, alert: Dict, key: str) -> Dict:
        """Validate alert temporal coherence with historical patterns."""
        try:
            from scipy.signal import find_peaks, savgol_filter
            from scipy.stats import autocorr
            
            alert_time = alert.get('timestamp', 0)
            
            # Get temporal sequence data
            temporal_data = self._get_temporal_sequence_data(key, alert_time)
            
            if not temporal_data or len(temporal_data) < 20:
                return {'validation': 0, 'confidence': 0.4}
            
            # Extract time series values
            timestamps = [d['timestamp'] for d in temporal_data]
            values = [d['value'] for d in temporal_data]
            
            # Smooth the time series
            if len(values) > 5:
                smoothed_values = savgol_filter(values, 
                                              window_length=min(5, len(values) if len(values) % 2 == 1 else len(values)-1),
                                              polyorder=min(3, len(values)-1))
            else:
                smoothed_values = values
            
            coherence_metrics = {}
            
            # Trend analysis
            try:
                from scipy.stats import linregress
                slope, intercept, r_value, p_value, std_err = linregress(timestamps, values)
                coherence_metrics['trend'] = {
                    'slope': slope,
                    'r_squared': r_value**2,
                    'p_value': p_value,
                    'significant': p_value < 0.05
                }
            except Exception as e:
                self.logger.warning(f"Trend analysis failed: {str(e)}")
            
            # Seasonality detection
            try:
                # Find peaks to identify periodic patterns
                peaks, _ = find_peaks(smoothed_values, height=np.mean(smoothed_values))
                if len(peaks) > 2:
                    peak_intervals = np.diff(peaks)
                    avg_interval = np.mean(peak_intervals)
                    interval_std = np.std(peak_intervals)
                    
                    coherence_metrics['seasonality'] = {
                        'peaks_found': len(peaks),
                        'avg_interval': avg_interval,
                        'interval_consistency': 1.0 - (interval_std / max(avg_interval, 1.0))
                    }
            except Exception as e:
                self.logger.warning(f"Seasonality analysis failed: {str(e)}")
            
            # Autocorrelation analysis
            try:
                if len(values) > 10:
                    autocorr_values = []
                    for lag in range(1, min(10, len(values)//2)):
                        if lag < len(values):
                            corr_coef = np.corrcoef(values[:-lag], values[lag:])[0, 1]
                            if not np.isnan(corr_coef):
                                autocorr_values.append(abs(corr_coef))
                    
                    if autocorr_values:
                        coherence_metrics['autocorr'] = {
                            'max_autocorr': max(autocorr_values),
                            'mean_autocorr': np.mean(autocorr_values),
                            'temporal_persistence': max(autocorr_values) > 0.3
                        }
            except Exception as e:
                self.logger.warning(f"Autocorrelation analysis failed: {str(e)}")
            
            # Change point detection
            try:
                # Simple change point detection using cumulative sum
                cumsum = np.cumsum(values - np.mean(values))
                change_points = find_peaks(np.abs(np.diff(cumsum)), 
                                         height=np.std(np.diff(cumsum)) * 2)
                
                coherence_metrics['change_points'] = {
                    'detected': len(change_points[0]),
                    'stability_score': 1.0 - min(len(change_points[0]) / len(values), 1.0)
                }
            except Exception as e:
                self.logger.warning(f"Change point detection failed: {str(e)}")
            
            # Calculate temporal coherence validation
            validation_factors = []
            
            # Trend coherence
            if 'trend' in coherence_metrics:
                trend = coherence_metrics['trend']
                if trend['significant'] and trend['r_squared'] > 0.3:
                    validation_factors.append(0.8)
                elif trend['r_squared'] > 0.1:
                    validation_factors.append(0.6)
                else:
                    validation_factors.append(0.4)
            
            # Seasonality coherence
            if 'seasonality' in coherence_metrics:
                seasonality = coherence_metrics['seasonality']
                if seasonality['interval_consistency'] > 0.7:
                    validation_factors.append(0.9)
                elif seasonality['interval_consistency'] > 0.4:
                    validation_factors.append(0.7)
                else:
                    validation_factors.append(0.5)
            
            # Autocorrelation coherence
            if 'autocorr' in coherence_metrics:
                autocorr = coherence_metrics['autocorr']
                if autocorr['temporal_persistence']:
                    validation_factors.append(0.8)
                else:
                    validation_factors.append(0.6)
            
            # Stability coherence
            if 'change_points' in coherence_metrics:
                change_points = coherence_metrics['change_points']
                validation_factors.append(change_points['stability_score'])
            
            if validation_factors:
                coherence_score = np.mean(validation_factors)
                validation = int(coherence_score > 0.6)
                confidence = coherence_score
            else:
                validation = 0
                confidence = 0.4
            
            return {
                'validation': validation,
                'confidence': confidence,
                'coherence_metrics': coherence_metrics,
                'temporal_data_points': len(temporal_data),
                'coherence_score': coherence_score if validation_factors else 0.0
            }
            
        except Exception as e:
            self.logger.error(f"Temporal coherence validation error: {str(e)}")
            return {'validation': 0, 'confidence': 0.4}
    
    def _calculate_validation_source_weights(self, alert: Dict, key: str) -> Dict[str, float]:
        """Calculate adaptive weights for different validation sources."""
        try:
            base_weights = {
                'seismic_validation': 0.25,
                'geological_validation': 0.20,
                'historical_validation': 0.15,
                'external_api_validation': 0.15,
                'database_validation': 0.10,
                'cross_correlation_validation': 0.08,
                'statistical_validation': 0.04,
                'temporal_validation': 0.03
            }
            
            # Adjust weights based on alert characteristics
            alert_location = alert.get('location', {})
            alert_magnitude = alert.get('magnitude', 0)
            
            # Increase seismic weight for high-magnitude events
            if alert_magnitude > 6.0:
                base_weights['seismic_validation'] *= 1.3
                base_weights['external_api_validation'] *= 1.2
            
            # Increase geological weight for volcanic alerts
            if 'volcanic' in key.lower() or 'eruption' in key.lower():
                base_weights['geological_validation'] *= 1.4
                base_weights['historical_validation'] *= 1.2
            
            # Increase database weight if location has rich historical data
            if alert_location and self._has_rich_historical_data(alert_location):
                base_weights['database_validation'] *= 1.3
                base_weights['historical_validation'] *= 1.2
            
            # Normalize weights to sum to 1
            total_weight = sum(base_weights.values())
            return {k: v/total_weight for k, v in base_weights.items()}
            
        except Exception as e:
            self.logger.error(f"Error calculating validation weights: {str(e)}")
            return {'seismic_validation': 0.4, 'geological_validation': 0.3, 
                   'historical_validation': 0.2, 'external_api_validation': 0.1}
    
    def _calculate_validation_uncertainty(self, validation_sources: Dict, confidence_scores: List[float]) -> float:
        """Calculate uncertainty in validation based on source agreement."""
        try:
            if not validation_sources or not confidence_scores:
                return 0.8  # High uncertainty
            
            # Calculate validation agreement
            validations = []
            for source, result in validation_sources.items():
                if result is not None:
                    validations.append(result.get('validation', 0))
            
            if not validations:
                return 0.8
            
            # Agreement-based uncertainty
            validation_agreement = 1.0 - np.std(validations) / max(np.mean(validations), 0.1)
            
            # Confidence-based uncertainty
            avg_confidence = np.mean(confidence_scores)
            confidence_uncertainty = 1.0 - avg_confidence
            
            # Source diversity uncertainty
            sources_available = len([r for r in validation_sources.values() if r is not None])
            diversity_uncertainty = max(0, (8 - sources_available) / 8.0)  # Expect up to 8 sources
            
            # Combined uncertainty
            total_uncertainty = (
                0.4 * (1.0 - validation_agreement) +
                0.3 * confidence_uncertainty +
                0.3 * diversity_uncertainty
            )
            
            return np.clip(total_uncertainty, 0.0, 1.0)
            
        except Exception as e:
            self.logger.error(f"Error calculating validation uncertainty: {str(e)}")
            return 0.7
    
    def _calculate_adaptive_threshold(self, alert: Dict, key: str, confidence_scores: List[float]) -> float:
        """Calculate adaptive threshold for binary classification."""
        try:
            base_threshold = 0.5
            
            # Adjust based on alert severity
            severity = alert.get('severity', 1)
            if severity >= 4:  # High severity
                base_threshold *= 0.8  # Lower threshold (more sensitive)
            elif severity <= 2:  # Low severity
                base_threshold *= 1.2  # Higher threshold (more specific)
            
            # Adjust based on confidence
            if confidence_scores:
                avg_confidence = np.mean(confidence_scores)
                if avg_confidence > 0.8:
                    base_threshold *= 0.9  # Lower threshold for high confidence
                elif avg_confidence < 0.5:
                    base_threshold *= 1.1  # Higher threshold for low confidence
            
            # Adjust based on alert type
            if 'tsunami' in key.lower() or 'volcanic' in key.lower():
                base_threshold *= 0.7  # More sensitive for critical events
            elif 'minor' in key.lower() or 'low' in key.lower():
                base_threshold *= 1.3  # Less sensitive for minor events
            
            return np.clip(base_threshold, 0.2, 0.8)
            
        except Exception as e:
            self.logger.error(f"Error calculating adaptive threshold: {str(e)}")
            return 0.5
    
    async def _get_volcanic_regions_near_location(self, lat: float, lon: float) -> List[Dict]:
        """Get volcanic regions near the given location using comprehensive database integration."""
        try:
            nearby_regions = []
            
            # Primary: Query PostgreSQL/PostGIS database for volcanic regions and chambers
            if hasattr(self, 'database_integration') and self.database_integration:
                try:
                    db_regions = await self._query_volcanic_database_comprehensive(lat, lon)
                    if db_regions:
                        nearby_regions.extend(db_regions)
                        self.logger.info(f"Retrieved {len(db_regions)} volcanic regions from database")
                        return nearby_regions
                except Exception as db_e:
                    self.logger.warning(f"Database query failed, falling back to external sources: {db_e}")
            
            # Secondary: External APIs and real-time data sources
            external_regions = await self._query_external_volcanic_sources(lat, lon)
            if external_regions:
                nearby_regions.extend(external_regions)
                self.logger.info(f"Retrieved {len(external_regions)} volcanic regions from external sources")
                return nearby_regions
            
            # Fallback: Enhanced static data with ML inference
            fallback_regions = await self._get_enhanced_static_volcanic_regions(lat, lon)
            if fallback_regions:
                nearby_regions.extend(fallback_regions)
            
            return nearby_regions
            
        except Exception as e:
            self.logger.error(f"Error getting volcanic regions: {str(e)}")
            return await self._get_minimal_volcanic_fallback(lat, lon)
    
    async def _query_volcanic_database_comprehensive(self, lat: float, lon: float) -> List[Dict]:
        """Comprehensive volcanic regions query using PostgreSQL/PostGIS database with advanced spatial analysis."""
        try:
            from .database_integration import DatabaseManager, DatabaseConfig
            import asyncio
            
            # Initialize database connection with enhanced configuration
            db_config = DatabaseConfig(
                host=os.getenv('POSTGRES_HOST', 'localhost'),
                port=int(os.getenv('POSTGRES_PORT', '5432')),
                database=os.getenv('POSTGRES_DB', 'prometheus_geo'),
                username=os.getenv('POSTGRES_USER', 'prometheus_user'),
                password=os.getenv('POSTGRES_PASSWORD', 'prometheus_password'),
                enable_postgis=True,
                enable_timescaledb=True
            )
            
            db_manager = DatabaseManager(db_config)
            volcanic_regions = []
            
            async with db_manager.get_async_session() as session:
                # Comprehensive volcanic analysis query with multiple data sources
                comprehensive_query = """
                WITH volcanic_analysis AS (
                    -- Active volcanoes with recent activity
                    SELECT 
                        'active_volcano' as region_type,
                        v.volcano_id,
                        v.volcano_name as name,
                        ST_X(v.location::geometry) as longitude,
                        ST_Y(v.location::geometry) as latitude,
                        ST_Z(v.location::geometry) as elevation_m,
                        ST_Distance(v.location::geography, ST_Point(%s, %s)::geography) / 1000.0 as distance_km,
                        v.volcano_type,
                        v.vei_max,
                        v.last_eruption_date,
                        v.eruption_probability,
                        v.hazard_level,
                        v.monitoring_status,
                        CASE 
                            WHEN v.last_eruption_date > NOW() - INTERVAL '100 years' THEN 'very_high'
                            WHEN v.last_eruption_date > NOW() - INTERVAL '1000 years' THEN 'high'
                            WHEN v.last_eruption_date > NOW() - INTERVAL '10000 years' THEN 'moderate'
                            ELSE 'low'
                        END as activity_level,
                        v.tectonic_setting,
                        v.rock_composition,
                        v.geothermal_features
                    FROM volcanoes v
                    WHERE ST_DWithin(v.location::geography, ST_Point(%s, %s)::geography, 500000)
                    AND v.status IN ('active', 'potentially_active', 'dormant')
                    
                    UNION ALL
                    
                    -- Volcanic chambers and magma systems
                    SELECT 
                        'volcanic_chamber' as region_type,
                        vc.chamber_id::text as volcano_id,
                        CONCAT('Magma Chamber ', vc.chamber_id) as name,
                        ST_X(vc.location::geometry) as longitude,
                        ST_Y(vc.location::geometry) as latitude,
                        -vc.chamber_depth_km * 1000 as elevation_m,
                        ST_Distance(vc.location::geography, ST_Point(%s, %s)::geography) / 1000.0 as distance_km,
                        'magma_chamber' as volcano_type,
                        NULL as vei_max,
                        NULL as last_eruption_date,
                        vc.eruption_probability,
                        CASE 
                            WHEN vc.melt_fraction > 0.4 THEN 'critical'
                            WHEN vc.melt_fraction > 0.2 THEN 'high'
                            ELSE 'moderate'
                        END as hazard_level,
                        vc.monitoring_status,
                        CASE 
                            WHEN vc.temperature_c > 1000 AND vc.melt_fraction > 0.3 THEN 'very_high'
                            WHEN vc.temperature_c > 800 AND vc.melt_fraction > 0.2 THEN 'high'
                            ELSE 'moderate'
                        END as activity_level,
                        vc.tectonic_setting,
                        vc.magma_composition as rock_composition,
                        jsonb_build_object(
                            'chamber_volume_km3', vc.chamber_volume_km3,
                            'melt_fraction', vc.melt_fraction,
                            'temperature_c', vc.temperature_c,
                            'pressure_mpa', vc.pressure_mpa,
                            'volatile_content', vc.volatile_content
                        ) as geothermal_features
                    FROM volcanic_chambers vc
                    WHERE ST_DWithin(vc.location::geography, ST_Point(%s, %s)::geography, 200000)
                    AND vc.chamber_volume_km3 > 0.1
                    
                    UNION ALL
                    
                    -- Volcanic regions and provinces
                    SELECT 
                        'volcanic_region' as region_type,
                        vr.region_id::text as volcano_id,
                        vr.region_name as name,
                        ST_X(ST_Centroid(vr.region_geometry)::geometry) as longitude,
                        ST_Y(ST_Centroid(vr.region_geometry)::geometry) as latitude,
                        vr.avg_elevation_m as elevation_m,
                        ST_Distance(vr.region_geometry::geography, ST_Point(%s, %s)::geography) / 1000.0 as distance_km,
                        vr.dominant_volcano_type as volcano_type,
                        vr.max_vei_recorded as vei_max,
                        vr.last_regional_activity as last_eruption_date,
                        vr.regional_hazard_probability as eruption_probability,
                        vr.regional_hazard_level as hazard_level,
                        vr.monitoring_density as monitoring_status,
                        vr.activity_classification as activity_level,
                        vr.tectonic_setting,
                        vr.dominant_composition as rock_composition,
                        jsonb_build_object(
                            'volcano_count', vr.volcano_count,
                            'area_km2', vr.area_km2,
                            'avg_spacing_km', vr.avg_volcano_spacing_km
                        ) as geothermal_features
                    FROM volcanic_regions vr
                    WHERE ST_DWithin(vr.region_geometry::geography, ST_Point(%s, %s)::geography, 800000)
                    AND vr.volcano_count > 0
                )
                SELECT 
                    *,
                    -- Calculate risk score based on multiple factors
                    CASE 
                        WHEN activity_level = 'very_high' AND distance_km < 50 THEN 10
                        WHEN activity_level = 'high' AND distance_km < 100 THEN 8
                        WHEN activity_level = 'moderate' AND distance_km < 200 THEN 6
                        WHEN distance_km < 500 THEN 4
                        ELSE 2
                    END as risk_score,
                    -- Add metadata for enhanced analysis
                    jsonb_build_object(
                        'data_source', 'database',
                        'query_timestamp', NOW(),
                        'spatial_accuracy', 'high',
                        'temporal_resolution', 'real_time'
                    ) as metadata
                FROM volcanic_analysis
                ORDER BY risk_score DESC, distance_km ASC
                LIMIT 50;
                """
                
                # Execute query with proper parameters
                result = await session.execute(comprehensive_query, (lon, lat, lon, lat, lon, lat, lon, lat, lon, lat))
                rows = result.fetchall()
                
                # Process results into structured format
                for row in rows:
                    volcanic_regions.append({
                        'region_type': row['region_type'],
                        'volcano_id': row['volcano_id'],
                        'name': row['name'],
                        'lat': row['latitude'],
                        'lon': row['longitude'],
                        'elevation_m': row['elevation_m'],
                        'distance_km': row['distance_km'],
                        'volcano_type': row['volcano_type'],
                        'vei_max': row['vei_max'],
                        'last_eruption_date': row['last_eruption_date'],
                        'eruption_probability': row['eruption_probability'],
                        'hazard_level': row['hazard_level'],
                        'monitoring_status': row['monitoring_status'],
                        'activity_level': row['activity_level'],
                        'tectonic_setting': row['tectonic_setting'],
                        'rock_composition': row['rock_composition'],
                        'geothermal_features': row['geothermal_features'],
                        'risk_score': row['risk_score'],
                        'metadata': row['metadata'],
                        'data_quality': 'high',
                        'confidence': 0.95
                    })
            
            self.logger.info(f"Database query returned {len(volcanic_regions)} volcanic regions")
            return volcanic_regions
            
        except Exception as e:
            self.logger.error(f"Database volcanic query failed: {e}")
            return []
    
    async def _query_external_volcanic_sources(self, lat: float, lon: float) -> List[Dict]:
        """Query external volcanic data sources including USGS, GVP, and real-time monitoring systems."""
        try:
            from .external_data_connectors import (
                USGSVolcanoConnector, GlobalVolcanismProgramConnector, 
                VAACConnector, ModisVolcanicThermalConnector
            )
            import asyncio
            
            volcanic_regions = []
            
            # Initialize external data connectors
            usgs_connector = USGSVolcanoConnector()
            gvp_connector = GlobalVolcanismProgramConnector()
            vaac_connector = VAACConnector()
            modis_connector = ModisVolcanicThermalConnector()
            
            # Parallel queries to external sources
            async def query_usgs():
                try:
                    return await usgs_connector.get_volcanoes_near_location(lat, lon, radius_km=500)
                except Exception as e:
                    self.logger.warning(f"USGS volcano query failed: {e}")
                    return []
            
            async def query_gvp():
                try:
                    return await gvp_connector.get_regional_volcanoes(lat, lon, radius_km=800)
                except Exception as e:
                    self.logger.warning(f"GVP query failed: {e}")
                    return []
            
            async def query_vaac():
                try:
                    return await vaac_connector.get_volcanic_ash_advisories(lat, lon)
                except Exception as e:
                    self.logger.warning(f"VAAC query failed: {e}")
                    return []
            
            async def query_modis():
                try:
                    return await modis_connector.get_thermal_anomalies(lat, lon, radius_km=300)
                except Exception as e:
                    self.logger.warning(f"MODIS thermal query failed: {e}")
                    return []
            
            # Execute all queries concurrently
            usgs_data, gvp_data, vaac_data, modis_data = await asyncio.gather(
                query_usgs(), query_gvp(), query_vaac(), query_modis(),
                return_exceptions=True
            )
            
            # Process USGS data
            if isinstance(usgs_data, list) and usgs_data:
                for volcano in usgs_data:
                    volcanic_regions.append({
                        'region_type': 'monitored_volcano',
                        'volcano_id': volcano.get('volcano_id'),
                        'name': volcano.get('name'),
                        'lat': volcano.get('latitude'),
                        'lon': volcano.get('longitude'),
                        'elevation_m': volcano.get('elevation'),
                        'distance_km': volcano.get('distance_km'),
                        'volcano_type': volcano.get('type'),
                        'hazard_level': volcano.get('alert_level'),
                        'monitoring_status': volcano.get('monitoring_status'),
                        'activity_level': volcano.get('activity_level'),
                        'last_eruption_date': volcano.get('last_eruption'),
                        'data_source': 'usgs',
                        'confidence': 0.9,
                        'metadata': volcano
                    })
            
            # Process GVP data
            if isinstance(gvp_data, list) and gvp_data:
                for volcano in gvp_data:
                    volcanic_regions.append({
                        'region_type': 'catalogued_volcano',
                        'volcano_id': volcano.get('vnum'),
                        'name': volcano.get('volcano_name'),
                        'lat': volcano.get('latitude'),
                        'lon': volcano.get('longitude'),
                        'elevation_m': volcano.get('elevation'),
                        'distance_km': volcano.get('distance_km'),
                        'volcano_type': volcano.get('primary_volcano_type'),
                        'tectonic_setting': volcano.get('tectonic_settings'),
                        'rock_composition': volcano.get('dominant_rock_type'),
                        'last_eruption_date': volcano.get('last_known_eruption'),
                        'data_source': 'gvp',
                        'confidence': 0.85,
                        'metadata': volcano
                    })
            
            # Process VAAC data (volcanic ash advisories)
            if isinstance(vaac_data, list) and vaac_data:
                for advisory in vaac_data:
                    volcanic_regions.append({
                        'region_type': 'active_ash_advisory',
                        'volcano_id': advisory.get('volcano_id'),
                        'name': advisory.get('volcano_name'),
                        'lat': advisory.get('latitude'),
                        'lon': advisory.get('longitude'),
                        'distance_km': advisory.get('distance_km'),
                        'hazard_level': 'critical',
                        'activity_level': 'very_high',
                        'monitoring_status': 'active_advisory',
                        'data_source': 'vaac',
                        'confidence': 0.95,
                        'metadata': advisory
                    })
            
            # Process MODIS thermal data
            if isinstance(modis_data, list) and modis_data:
                for anomaly in modis_data:
                    volcanic_regions.append({
                        'region_type': 'thermal_anomaly',
                        'volcano_id': f"thermal_{anomaly.get('anomaly_id')}",
                        'name': f"Thermal Anomaly {anomaly.get('anomaly_id')}",
                        'lat': anomaly.get('latitude'),
                        'lon': anomaly.get('longitude'),
                        'distance_km': anomaly.get('distance_km'),
                        'activity_level': 'thermal_active',
                        'data_source': 'modis',
                        'confidence': 0.75,
                        'metadata': anomaly
                    })
            
            self.logger.info(f"External sources returned {len(volcanic_regions)} volcanic regions")
            return volcanic_regions
            
        except Exception as e:
            self.logger.error(f"External volcanic sources query failed: {e}")
            return []
    
