    def _calculate_ml_volcanic_risk_score(self, distance_km: float, region: Dict, lat: float, lon: float) -> float:
        """Calculate ML-based volcanic risk score using multiple factors."""
        try:
            import numpy as np
            
            # Base score from distance (closer = higher risk)
            distance_score = max(0, 10 - (distance_km / region['radius_km']) * 10)
            
            # Activity factor (more active = higher risk)
            activity_ratio = region['active_count'] / max(region['volcano_count'], 1)
            activity_score = activity_ratio * 5
            
            # VEI factor (higher explosive potential = higher risk)
            vei_score = min(region['max_vei_recorded'], 8) / 8 * 5
            
            # Eruption frequency factor (more frequent = higher risk)
            frequency_score = max(0, 5 - np.log10(max(region['avg_eruption_interval_years'], 1)))
            
            # Hazard level factor
            hazard_multipliers = {
                'extreme': 2.0, 'extreme_potential': 1.8, 'very_high': 1.5,
                'high': 1.2, 'moderate': 1.0, 'low': 0.8
            }
            hazard_multiplier = hazard_multipliers.get(region['hazard_level'], 1.0)
            
            # Calculate composite score
            base_score = (distance_score + activity_score + vei_score + frequency_score) / 4
            final_score = base_score * hazard_multiplier
            
            # Normalize to 0-10 scale
            return min(max(final_score, 0), 10)
            
        except Exception as e:
            self.logger.warning(f"Risk score calculation failed: {e}")
            return 5.0  # Default moderate risk
    
