class ABTestingManager:
    """Advanced multi-variate A/B testing system with geological domain awareness."""
    
    def __init__(self):
        self.active_tests = {}
        self.test_history = {}
        self.statistical_engine = StatisticalTestingEngine()
        self.geological_context_manager = GeologicalContextManager()
        self.power_analysis_engine = PowerAnalysisEngine()
        self.sequential_testing_framework = SequentialTestingFramework()
        
    def is_active(self) -> bool:
        """Check if any A/B tests are currently active."""
        try:
            # Check for active tests across multiple dimensions
            active_count = sum(1 for test in self.active_tests.values() 
                             if test.get('status') == 'active')
            
            # Validate test integrity
            for test_id, test_data in self.active_tests.items():
                if test_data.get('status') == 'active':
                    if not self._validate_test_integrity(test_id, test_data):
                        self._pause_test(test_id, reason="integrity_failure")
                        
            return active_count > 0
            
        except Exception as e:
            logging.error(f"Error checking A/B test status: {e}")
            return False
    
    async def start_test(self, config: Dict) -> str:
        """Start sophisticated multi-phase A/B test with geological context."""
        try:
            # Generate unique test ID with geological context
            geological_context = await self.geological_context_manager.get_current_context()
            test_id = f"test_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{geological_context.get('region_id', 'global')}"
            
            # Validate test configuration
            validation_result = await self._validate_test_config(config)
            if not validation_result['valid']:
                raise ValueError(f"Invalid test configuration: {validation_result['errors']}")
            
            # Power analysis for sample size determination
            power_analysis = await self.power_analysis_engine.calculate_required_sample_size(
                effect_size=config.get('expected_effect_size', 0.05),
                alpha=config.get('alpha', 0.05),
                power=config.get('power', 0.8),
                geological_variance=geological_context.get('variance_factors', {})
            )
            
            # Initialize multi-arm bandit for adaptive allocation
            bandit_config = await self._setup_adaptive_allocation(config, power_analysis)
            
            # Create test structure
            test_structure = {
                'test_id': test_id,
                'status': 'active',
                'start_time': datetime.now(),
                'config': config,
                'power_analysis': power_analysis,
                'bandit_config': bandit_config,
                'geological_context': geological_context,
                'arms': await self._initialize_test_arms(config),
                'allocation_strategy': config.get('allocation_strategy', 'uniform'),
                'sequential_boundaries': await self._calculate_sequential_boundaries(config),
                'interim_analyses': [],
                'participants': {},
                'metrics': {
                    'primary': config.get('primary_metrics', []),
                    'secondary': config.get('secondary_metrics', []),
                    'geological': await self._get_geological_metrics(geological_context)
                }
            }
            
            # Store test
            self.active_tests[test_id] = test_structure
            
            # Initialize monitoring
            await self._setup_test_monitoring(test_id, test_structure)
            
            # Log test start
            logging.info(f"Started A/B test {test_id} with {len(test_structure['arms'])} arms")
            
            return test_id
            
        except Exception as e:
            logging.error(f"Error starting A/B test: {e}")
            raise
    
    async def _validate_test_config(self, config: Dict) -> Dict[str, Any]:
        """Validate comprehensive test configuration."""
        errors = []
        
        # Required fields
        required_fields = ['name', 'description', 'primary_metrics', 'test_arms']
        for field in required_fields:
            if field not in config:
                errors.append(f"Missing required field: {field}")
        
        # Validate test arms
        if 'test_arms' in config:
            if len(config['test_arms']) < 2:
                errors.append("At least 2 test arms required")
            
            for i, arm in enumerate(config['test_arms']):
                if 'name' not in arm:
                    errors.append(f"Test arm {i} missing name")
                if 'treatment' not in arm:
                    errors.append(f"Test arm {i} missing treatment definition")
        
        # Validate metrics
        if 'primary_metrics' in config:
            for metric in config['primary_metrics']:
                if not await self._validate_metric_definition(metric):
                    errors.append(f"Invalid metric definition: {metric}")
        
        return {
            'valid': len(errors) == 0,
            'errors': errors
        }
    
    async def _setup_adaptive_allocation(self, config: Dict, power_analysis: Dict) -> Dict:
        """Setup multi-arm bandit for adaptive allocation."""
        return {
            'algorithm': config.get('bandit_algorithm', 'thompson_sampling'),
            'exploration_rate': config.get('exploration_rate', 0.1),
            'minimum_allocation': config.get('minimum_allocation', 0.05),
            'update_frequency': config.get('update_frequency', 100),
            'geological_priors': await self._get_geological_priors(config)
        }
    
    def _validate_test_integrity(self, test_id: str, test_data: Dict) -> bool:
        """Validate ongoing test integrity."""
        try:
            # Check data consistency
            expected_participants = sum(arm.get('allocated_count', 0) 
                                      for arm in test_data.get('arms', []))
            actual_participants = len(test_data.get('participants', {}))
            
            if abs(expected_participants - actual_participants) > 0.01 * expected_participants:
                logging.warning(f"Participant count mismatch in test {test_id}")
                return False
            
            # Check for statistical significance leakage
            if self._detect_peeking_problem(test_data):
                logging.warning(f"Detected multiple testing problem in test {test_id}")
                return False
            
            return True
            
        except Exception as e:
            logging.error(f"Error validating test integrity for {test_id}: {e}")
            return False

class ModelComparisonEngine:
    """Advanced multi-dimensional model version comparison with geological domain expertise."""
    
    def __init__(self):
        self.comparison_metrics = ComparisonMetricsCalculator()
        self.statistical_tests = StatisticalTestSuite()
        self.geological_validator = GeologicalModelValidator()
        self.performance_profiler = ModelPerformanceProfiler()
        self.significance_analyzer = StatisticalSignificanceAnalyzer()
        self.regression_detector = ModelRegressionDetector()
        
    async def compare_model_versions(self, model_state: Dict, training_step: int) -> Dict[str, Any]:
        """Comprehensive multi-dimensional model version comparison."""
        try:
            # Extract model metadata
            current_version = model_state.get('version', 'unknown')
            model_architecture = model_state.get('architecture', {})
            
            # Get historical versions for comparison
            historical_versions = await self._get_historical_versions(
                model_state.get('model_id'), 
                training_step
            )
            
            if not historical_versions:
                return await self._initialize_baseline_comparison(model_state, training_step)
            
            comparison_results = {}
            
            # 1. Performance Comparison
            performance_analysis = await self._compare_performance_metrics(
                model_state, historical_versions, training_step
            )
            comparison_results['performance'] = performance_analysis
            
            # 2. Geological Domain Validation
            geological_validation = await self.geological_validator.validate_geological_consistency(
                model_state, historical_versions
            )
            comparison_results['geological_validation'] = geological_validation
            
            # 3. Statistical Significance Testing
            significance_results = await self._perform_statistical_tests(
                model_state, historical_versions
            )
            comparison_results['statistical_significance'] = significance_results
            
            # 4. Architecture Evolution Analysis
            architecture_analysis = await self._analyze_architecture_evolution(
                model_architecture, historical_versions
            )
            comparison_results['architecture_evolution'] = architecture_analysis
            
            # 5. Regression Detection
            regression_analysis = await self.regression_detector.detect_regressions(
                model_state, historical_versions
            )
            comparison_results['regression_analysis'] = regression_analysis
            
            # 6. Computational Efficiency Analysis
            efficiency_analysis = await self._analyze_computational_efficiency(
                model_state, historical_versions, training_step
            )
            comparison_results['efficiency_analysis'] = efficiency_analysis
            
            # 7. Robustness Comparison
            robustness_analysis = await self._compare_model_robustness(
                model_state, historical_versions
            )
            comparison_results['robustness'] = robustness_analysis
            
            # 8. Generate Overall Assessment
            overall_assessment = await self._generate_overall_assessment(comparison_results)
            comparison_results['overall_assessment'] = overall_assessment
            
            # Log comprehensive comparison
            logging.info(f"Model comparison completed for version {current_version} at step {training_step}")
            
            return comparison_results
            
        except Exception as e:
            logging.error(f"Error in model version comparison: {e}")
            return {'error': str(e), 'comparison_results': 'failed', 'confidence': 0.0}
    
    async def _compare_performance_metrics(self, current_model: Dict, historical_versions: List[Dict], training_step: int) -> Dict:
        """Compare performance metrics across model versions."""
        try:
            performance_comparison = {
                'accuracy_evolution': [],
                'loss_evolution': [],
                'geological_metrics_evolution': [],
                'relative_improvements': {},
                'performance_stability': {},
                'outlier_detection': {}
            }
            
            # Extract current metrics
            current_metrics = current_model.get('performance_metrics', {})
            
            # Compare with each historical version
            for hist_version in historical_versions[-10:]:  # Last 10 versions
                hist_metrics = hist_version.get('performance_metrics', {})
                
                # Calculate relative improvements
                for metric_name, current_value in current_metrics.items():
                    if metric_name in hist_metrics:
                        hist_value = hist_metrics[metric_name]
                        if hist_value != 0:
                            improvement = (current_value - hist_value) / abs(hist_value)
                            if metric_name not in performance_comparison['relative_improvements']:
                                performance_comparison['relative_improvements'][metric_name] = []
                            performance_comparison['relative_improvements'][metric_name].append(improvement)
            
            # Statistical analysis of improvements
            for metric_name, improvements in performance_comparison['relative_improvements'].items():
                if improvements:
                    performance_comparison['performance_stability'][metric_name] = {
                        'mean_improvement': np.mean(improvements),
                        'std_improvement': np.std(improvements),
                        'trend': self._calculate_trend(improvements),
                        'is_improving': np.mean(improvements) > 0
                    }
            
            return performance_comparison
            
        except Exception as e:
            logging.error(f"Error comparing performance metrics: {e}")
            return {'error': str(e)}

class RetrainingTriggerSystem:
    """Intelligent multi-criteria retraining trigger system with adaptive thresholds."""
    
    def __init__(self):
        self.threshold_manager = AdaptiveThresholdManager()
        self.drift_detector = ConceptDriftDetector()
        self.performance_monitor = PerformanceMonitor()
        self.geological_change_detector = GeologicalChangeDetector()
        self.cost_benefit_analyzer = CostBenefitAnalyzer()
        self.trigger_history = []
        
    def evaluate_action_trigger(self, performance_data: Dict, history: Dict) -> Dict[str, Any]:
        """Evaluate comprehensive multi-criteria retraining triggers."""
        try:
            trigger_evaluation = {
                'timestamp': datetime.now(),
                'criteria_analysis': {},
                'overall_recommendation': 'continue',
                'confidence': 0.0,
                'trigger_reasons': [],
                'cost_benefit': {},
                'urgency_level': 'normal'
            }
            
            # 1. Performance Degradation Detection
            performance_trigger = self._evaluate_performance_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['performance'] = performance_trigger
            
            # 2. Concept Drift Detection
            drift_trigger = self._evaluate_drift_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['concept_drift'] = drift_trigger
            
            # 3. Data Distribution Changes
            distribution_trigger = self._evaluate_distribution_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['data_distribution'] = distribution_trigger
            
            # 4. Geological Context Changes
            geological_trigger = self._evaluate_geological_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['geological_context'] = geological_trigger
            
            # 5. Model Staleness Assessment
            staleness_trigger = self._evaluate_staleness_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['model_staleness'] = staleness_trigger
            
            # 6. Resource Availability Assessment
            resource_trigger = self._evaluate_resource_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['resource_availability'] = resource_trigger
            
            # 7. Business Impact Assessment
            business_trigger = self._evaluate_business_trigger(performance_data, history)
            trigger_evaluation['criteria_analysis']['business_impact'] = business_trigger
            
            # 8. Adaptive Threshold Evaluation
            adaptive_trigger = self._evaluate_adaptive_thresholds(performance_data, history)
            trigger_evaluation['criteria_analysis']['adaptive_thresholds'] = adaptive_trigger
            
            # Aggregate triggers using weighted voting
            overall_assessment = self._aggregate_trigger_criteria(trigger_evaluation['criteria_analysis'])
            trigger_evaluation.update(overall_assessment)
            
            # Cost-benefit analysis
            if trigger_evaluation['overall_recommendation'] == 'retrain':
                cost_benefit = self.cost_benefit_analyzer.analyze_retraining_decision(
                    performance_data, history, trigger_evaluation
                )
                trigger_evaluation['cost_benefit'] = cost_benefit
                
                # Adjust recommendation based on cost-benefit
                if cost_benefit.get('net_benefit', 0) < 0:
                    trigger_evaluation['overall_recommendation'] = 'defer'
                    trigger_evaluation['trigger_reasons'].append('negative_cost_benefit')
            
            # Update trigger history
            self.trigger_history.append(trigger_evaluation)
            
            # Log trigger evaluation
            logging.info(f"Retraining trigger evaluation: {trigger_evaluation['overall_recommendation']} "
                        f"(confidence: {trigger_evaluation['confidence']:.3f})")
            
            return trigger_evaluation
            
        except Exception as e:
            logging.error(f"Error evaluating retraining trigger: {e}")
            return {
                'recommendation': 'continue',
                'confidence': 0.0,
                'error': str(e)
            }
    
    def _evaluate_performance_trigger(self, performance_data: Dict, history: Dict) -> Dict:
        """Evaluate performance-based retraining triggers."""
        try:
            current_performance = performance_data.get('current_metrics', {})
            historical_performance = history.get('performance_history', [])
            
            if not historical_performance:
                return {'trigger': False, 'reason': 'insufficient_history', 'confidence': 0.0}
            
            # Calculate performance trends
            recent_performance = historical_performance[-10:] if len(historical_performance) >= 10 else historical_performance
            performance_trend = self._calculate_performance_trend(recent_performance)
            
            # Detect significant degradation
            degradation_detected = False
            degradation_severity = 0.0
            
            for metric_name, current_value in current_performance.items():
                if metric_name in ['accuracy', 'f1_score', 'auc_roc']:
                    # Higher is better metrics
                    historical_values = [p.get(metric_name, 0) for p in recent_performance]
                    if historical_values:
                        baseline = np.mean(historical_values)
                        degradation = (baseline - current_value) / baseline if baseline > 0 else 0
                        if degradation > 0.05:  # 5% degradation threshold
                            degradation_detected = True
                            degradation_severity = max(degradation_severity, degradation)
                
                elif metric_name in ['loss', 'mse', 'rmse']:
                    # Lower is better metrics
                    historical_values = [p.get(metric_name, float('inf')) for p in recent_performance]
                    if historical_values and all(v != float('inf') for v in historical_values):
                        baseline = np.mean(historical_values)
                        degradation = (current_value - baseline) / baseline if baseline > 0 else 0
                        if degradation > 0.05:  # 5% degradation threshold
                            degradation_detected = True
                            degradation_severity = max(degradation_severity, degradation)
            
            return {
                'trigger': degradation_detected,
                'reason': 'performance_degradation' if degradation_detected else 'performance_stable',
                'confidence': min(degradation_severity * 2, 1.0),
                'degradation_severity': degradation_severity,
                'performance_trend': performance_trend
            }
            
        except Exception as e:
            logging.error(f"Error evaluating performance trigger: {e}")
            return {'trigger': False, 'reason': 'evaluation_error', 'confidence': 0.0}

class PerformanceDegradationDetector:
    """Advanced multi-modal performance degradation detection with geological domain awareness."""
    
    def __init__(self):
        self.statistical_analyzer = StatisticalDegradationAnalyzer()
        self.anomaly_detector = AnomalyDetectionEngine()
        self.geological_pattern_analyzer = GeologicalPatternAnalyzer()
        self.temporal_analyzer = TemporalDegradationAnalyzer()
        self.multivariate_analyzer = MultivariateDegradationAnalyzer()
        self.degradation_history = []
        
    async def analyze_training_step(self, training_data: Dict, history: Dict) -> Dict[str, Any]:
        """Comprehensive multi-dimensional degradation analysis for training step."""
        try:
            analysis_result = {
                'timestamp': datetime.now(),
                'training_step': training_data.get('step', 0),
                'degradation_detected': False,
                'severity': 'none',
                'degradation_types': [],
                'confidence_scores': {},
                'geological_context': {},
                'remediation_suggestions': [],
                'early_warning_signals': []
            }
            
            # 1. Statistical Degradation Analysis
            statistical_analysis = await self._analyze_statistical_degradation(training_data, history)
            analysis_result['statistical_analysis'] = statistical_analysis
            
            # 2. Anomaly-based Degradation Detection
            anomaly_analysis = await self._detect_anomalous_degradation(training_data, history)
            analysis_result['anomaly_analysis'] = anomaly_analysis
            
            # 3. Geological Pattern Degradation
            geological_analysis = await self._analyze_geological_degradation(training_data, history)
            analysis_result['geological_analysis'] = geological_analysis
            
            # 4. Temporal Pattern Analysis
            temporal_analysis = await self._analyze_temporal_degradation(training_data, history)
            analysis_result['temporal_analysis'] = temporal_analysis
            
            # 5. Multivariate Degradation Analysis
            multivariate_analysis = await self._analyze_multivariate_degradation(training_data, history)
            analysis_result['multivariate_analysis'] = multivariate_analysis
            
            # 6. Loss Landscape Analysis
            loss_landscape_analysis = await self._analyze_loss_landscape_degradation(training_data, history)
            analysis_result['loss_landscape_analysis'] = loss_landscape_analysis
            
            # 7. Gradient Flow Analysis
            gradient_analysis = await self._analyze_gradient_degradation(training_data, history)
            analysis_result['gradient_analysis'] = gradient_analysis
            
            # 8. Overfitting Detection
            overfitting_analysis = await self._detect_overfitting_degradation(training_data, history)
            analysis_result['overfitting_analysis'] = overfitting_analysis
            
            # Aggregate all analyses
            overall_assessment = await self._aggregate_degradation_analyses(analysis_result)
            analysis_result.update(overall_assessment)
            
            # Generate remediation suggestions
            if analysis_result['degradation_detected']:
                analysis_result['remediation_suggestions'] = await self._generate_remediation_suggestions(
                    analysis_result
                )
            
            # Update degradation history
            self.degradation_history.append(analysis_result)
            
            # Early warning system
            early_warnings = await self._detect_early_warning_signals(training_data, history, analysis_result)
            analysis_result['early_warning_signals'] = early_warnings
            
            # Log analysis
            if analysis_result['degradation_detected']:
                logging.warning(f"Performance degradation detected at step {training_data.get('step', 0)}: "
                               f"{analysis_result['severity']} severity")
            
            return analysis_result
            
        except Exception as e:
            logging.error(f"Error analyzing training step degradation: {e}")
            return {
                'degradation_detected': False,
                'severity': 'none',
                'error': str(e)
            }
    
    async def _analyze_statistical_degradation(self, training_data: Dict, history: Dict) -> Dict:
        """Analyze degradation using statistical methods."""
        try:
            current_metrics = training_data.get('metrics', {})
            historical_metrics = history.get('metrics_history', [])
            
            if len(historical_metrics) < 10:
                return {'degradation_detected': False, 'reason': 'insufficient_history'}
            
            degradation_signals = {}
            
            # Analyze each metric
            for metric_name, current_value in current_metrics.items():
                if isinstance(current_value, (int, float)):
                    historical_values = [
                        h.get('metrics', {}).get(metric_name, None) 
                        for h in historical_metrics[-50:]  # Last 50 steps
                    ]
                    historical_values = [v for v in historical_values if v is not None]
                    
                    if len(historical_values) >= 5:
                        # Statistical tests for degradation
                        degradation_signal = await self._statistical_degradation_test(
                            current_value, historical_values, metric_name
                        )
                        degradation_signals[metric_name] = degradation_signal
            
            # Aggregate statistical signals
            overall_degradation = any(signal.get('degradation_detected', False) 
                                    for signal in degradation_signals.values())
            
            return {
                'degradation_detected': overall_degradation,
                'metric_analyses': degradation_signals,
                'statistical_confidence': np.mean([s.get('confidence', 0) for s in degradation_signals.values()])
            }
            
        except Exception as e:
            logging.error(f"Error in statistical degradation analysis: {e}")
            return {'degradation_detected': False, 'error': str(e)}
    
    async def _statistical_degradation_test(self, current_value: float, historical_values: List[float], metric_name: str) -> Dict:
        """Perform statistical test for metric degradation."""
        try:
            # Calculate baseline statistics
            baseline_mean = np.mean(historical_values)
            baseline_std = np.std(historical_values)
            
            # Z-score test for outlier detection
            z_score = abs(current_value - baseline_mean) / baseline_std if baseline_std > 0 else 0
            
            # Trend analysis
            trend_slope = self._calculate_trend_slope(historical_values + [current_value])
            
            # Change point detection
            change_point_detected = await self._detect_change_point(historical_values + [current_value])
            
            # Determine if degradation (depends on metric type)
            is_degradation = False
            if metric_name in ['accuracy', 'f1_score', 'auc_roc', 'precision', 'recall']:
                # Higher is better
                is_degradation = current_value < baseline_mean - 2 * baseline_std
            elif metric_name in ['loss', 'mse', 'rmse', 'mae']:
                # Lower is better
                is_degradation = current_value > baseline_mean + 2 * baseline_std
            
            confidence = min(z_score / 3.0, 1.0) if is_degradation else 0.0
            
            return {
                'degradation_detected': is_degradation,
                'confidence': confidence,
                'z_score': z_score,
                'trend_slope': trend_slope,
                'change_point_detected': change_point_detected,
                'baseline_mean': baseline_mean,
                'baseline_std': baseline_std
            }
            
        except Exception as e:
            logging.error(f"Error in statistical degradation test for {metric_name}: {e}")
            return {'degradation_detected': False, 'error': str(e)}

class GeologicalKPITracker:
    """Advanced geological domain-specific KPI tracking with multi-dimensional analysis."""
    
    def __init__(self):
        self.geological_metrics = GeologicalMetricsEngine()
        self.seismic_analyzer = SeismicMetricsAnalyzer()
        self.volcanic_monitor = VolcanicActivityMonitor()
        self.tectonic_assessor = TectonicMovementAssessor()
        self.hydrogeological_tracker = HydrogeologicalTracker()
        self.kpi_history = []
        self.real_time_monitors = {}
        self.alert_thresholds = {}
        
    def update_action_kpis(self, performance_data: Dict, validation: Dict):
        """Update comprehensive geological KPIs from action with multi-source validation."""
        try:
            timestamp = datetime.now()
            
            # Extract geological context
            geological_context = performance_data.get('geological_context', {})
            location = geological_context.get('location', {})
            
            # 1. Seismic Activity KPIs
            seismic_kpis = self._update_seismic_kpis(performance_data, validation, timestamp)
            
            # 2. Volcanic Activity KPIs
            volcanic_kpis = self._update_volcanic_kpis(performance_data, validation, timestamp)
            
            # 3. Tectonic Movement KPIs
            tectonic_kpis = self._update_tectonic_kpis(performance_data, validation, timestamp)
            
            # 4. Hydrogeological KPIs
            hydro_kpis = self._update_hydrogeological_kpis(performance_data, validation, timestamp)
            
            # 5. Geochemical KPIs
            geochem_kpis = self._update_geochemical_kpis(performance_data, validation, timestamp)
            
            # 6. Geological Hazard KPIs
            hazard_kpis = self._update_hazard_kpis(performance_data, validation, timestamp)
            
            # 7. Model Performance vs Geological Truth KPIs
            truth_validation_kpis = self._update_geological_truth_kpis(performance_data, validation, timestamp)
            
            # 8. Temporal Evolution KPIs
            evolution_kpis = self._update_temporal_evolution_kpis(performance_data, validation, timestamp)
            
            # Aggregate all KPIs
            comprehensive_kpis = {
                'timestamp': timestamp,
                'location': location,
                'seismic_kpis': seismic_kpis,
                'volcanic_kpis': volcanic_kpis,
                'tectonic_kpis': tectonic_kpis,
                'hydrogeological_kpis': hydro_kpis,
                'geochemical_kpis': geochem_kpis,
                'hazard_kpis': hazard_kpis,
                'geological_truth_kpis': truth_validation_kpis,
                'temporal_evolution_kpis': evolution_kpis
            }
            
            # Store in history
            self.kpi_history.append(comprehensive_kpis)
            
            # Real-time monitoring updates
            self._update_real_time_monitors(comprehensive_kpis)
            
            # Alert evaluation
            alerts = self._evaluate_kpi_alerts(comprehensive_kpis)
            if alerts:
                self._trigger_geological_alerts(alerts)
            
            # Log KPI update
            logging.info(f"Updated geological KPIs at {timestamp} for location {location}")
            
            return comprehensive_kpis
            
        except Exception as e:
            logging.error(f"Error updating geological KPIs: {e}")
            return {'error': str(e), 'timestamp': datetime.now()}
    
    def _update_seismic_kpis(self, performance_data: Dict, validation: Dict, timestamp: datetime) -> Dict:
        """Update seismic activity KPIs."""
        try:
            seismic_data = performance_data.get('seismic_data', {})
            validation_seismic = validation.get('seismic_validation', {})
            
            return {
                'magnitude_prediction_accuracy': self._calculate_magnitude_accuracy(seismic_data, validation_seismic),
                'location_prediction_error': self._calculate_location_error(seismic_data, validation_seismic),
                'timing_prediction_accuracy': self._calculate_timing_accuracy(seismic_data, validation_seismic),
                'b_value_estimation_quality': self._assess_b_value_quality(seismic_data, validation_seismic),
                'aftershock_sequence_prediction': self._evaluate_aftershock_prediction(seismic_data, validation_seismic),
                'focal_mechanism_accuracy': self._assess_focal_mechanism_accuracy(seismic_data, validation_seismic),
                'ground_motion_prediction_skill': self._calculate_ground_motion_skill(seismic_data, validation_seismic),
                'seismic_hazard_assessment_reliability': self._assess_hazard_reliability(seismic_data, validation_seismic)
            }
            
        except Exception as e:
            logging.error(f"Error updating seismic KPIs: {e}")
            return {'error': str(e)}
    
    def _update_volcanic_kpis(self, performance_data: Dict, validation: Dict, timestamp: datetime) -> Dict:
        """Update volcanic activity KPIs."""
        try:
            volcanic_data = performance_data.get('volcanic_data', {})
            validation_volcanic = validation.get('volcanic_validation', {})
            
            return {
                'eruption_forecast_accuracy': self._calculate_eruption_forecast_accuracy(volcanic_data, validation_volcanic),
                'vei_prediction_skill': self._assess_vei_prediction(volcanic_data, validation_volcanic),
                'precursor_detection_sensitivity': self._evaluate_precursor_detection(volcanic_data, validation_volcanic),
                'magma_chamber_monitoring_quality': self._assess_magma_monitoring(volcanic_data, validation_volcanic),
                'gas_emission_tracking_accuracy': self._evaluate_gas_tracking(volcanic_data, validation_volcanic),
                'deformation_prediction_skill': self._assess_deformation_prediction(volcanic_data, validation_volcanic),
                'thermal_anomaly_detection_rate': self._calculate_thermal_detection_rate(volcanic_data, validation_volcanic),
                'volcanic_hazard_mapping_quality': self._assess_hazard_mapping_quality(volcanic_data, validation_volcanic)
            }
            
        except Exception as e:
            logging.error(f"Error updating volcanic KPIs: {e}")
            return {'error': str(e)}

