    def _identify_primary_causes(self, attribution_results: Dict) -> List[str]:
        """Identify primary causal factors from comprehensive analysis."""
        try:
            primary_causes = []
            
            # Extract from structural causal model
            scm_causes = attribution_results.get('structural_causal_model', {}).get('causal_variables', {})
            
            # Extract from causal strength analysis
            strength_analysis = attribution_results.get('causal_strength', {}).get('strongest_causal_factors', [])
            
            # Extract from counterfactual analysis
            counterfactual_causes = attribution_results.get('counterfactual_analysis', {}).get('strongest_interventions', [])
            
            # Combine and rank
            all_causes = set()
            if isinstance(scm_causes, dict):
                all_causes.update(scm_causes.keys())
            if isinstance(strength_analysis, list):
                all_causes.update([cause for cause in strength_analysis if isinstance(cause, str)])
            if isinstance(counterfactual_causes, list):
                all_causes.update([cause for cause in counterfactual_causes if isinstance(cause, str)])
            
            # Filter and rank by importance
            ranked_causes = self._rank_causes_by_importance(all_causes, attribution_results)
            primary_causes = ranked_causes[:10]  # Top 10 primary causes
            
            return primary_causes if primary_causes else ['insufficient_data']
            
        except Exception as e:
            logging.error(f"Error identifying primary causes: {e}")
            return ['error_in_identification']
    
    def _calculate_attribution_scores(self, attribution_results: Dict) -> Dict[str, float]:
        """Calculate attribution scores for identified causal factors."""
        try:
            attribution_scores = {}
            
            # Get causal strength scores
            causal_strengths = attribution_results.get('causal_strength', {}).get('causal_strengths', {})
            
            for factor, strength_data in causal_strengths.items():
                if isinstance(strength_data, dict):
                    composite_strength = strength_data.get('composite_strength', 0)
                    attribution_scores[factor] = max(0, min(1, composite_strength))
                else:
                    attribution_scores[factor] = max(0, min(1, float(strength_data) if strength_data else 0))
            
            # Normalize scores
            total_score = sum(attribution_scores.values())
            if total_score > 0:
                attribution_scores = {k: v / total_score for k, v in attribution_scores.items()}
            
            return attribution_scores
            
        except Exception as e:
            logging.error(f"Error calculating attribution scores: {e}")
            return {'error': 1.0}
    
    # Additional helper methods for comprehensive causal analysis
    def _identify_causal_variables(self, state: Dict, actions: Dict, performance_data: Dict, geological_context: Dict) -> Dict[str, Any]:
        """Identify relevant causal variables from input data."""
        causal_variables = {}
        
        # Extract state variables
        for key, value in state.items():
            if isinstance(value, (int, float)) and key not in ['timestamp', 'id']:
                causal_variables[f'state_{key}'] = value
        
        # Extract action variables
        for key, value in actions.items():
            if isinstance(value, (int, float, bool)):
                causal_variables[f'action_{key}'] = float(value) if isinstance(value, bool) else value
        
        # Extract performance variables
        for key, value in performance_data.items():
            if isinstance(value, (int, float)) and key not in ['timestamp', 'id']:
                causal_variables[f'performance_{key}'] = value
        
        # Extract geological variables
        for key, value in geological_context.items():
            if isinstance(value, (int, float)) and key not in ['timestamp', 'location']:
                causal_variables[f'geological_{key}'] = value
        
        return causal_variables
    
    def _build_causal_graph(self, causal_variables: Dict, geological_context: Dict) -> Dict[str, Any]:
        """Build causal graph structure based on domain knowledge."""
        causal_graph = {
            'nodes': list(causal_variables.keys()),
            'edges': [],
            'edge_weights': {}
        }
        
        # Add edges based on geological domain knowledge
        geological_chains = self.geological_causal_knowledge.get('seismic_causal_chains', {})
        
        for chain_name, chain_variables in geological_chains.items():
            for i in range(len(chain_variables) - 1):
                source = chain_variables[i]
                target = chain_variables[i + 1]
                
                # Find matching variables in our data
                source_vars = [var for var in causal_variables.keys() if source.replace('_', '').lower() in var.replace('_', '').lower()]
                target_vars = [var for var in causal_variables.keys() if target.replace('_', '').lower() in var.replace('_', '').lower()]
                
                for s_var in source_vars:
                    for t_var in target_vars:
                        edge = (s_var, t_var)
                        if edge not in causal_graph['edges']:
                            causal_graph['edges'].append(edge)
                            causal_graph['edge_weights'][edge] = 0.7  # Default geological causality weight
        
        return causal_graph
    
    def _calculate_composite_strength(self, strength_values: List[float]) -> float:
        """Calculate composite causal strength from multiple measures."""
        if not strength_values:
            return 0.0
        
        # Remove None values and convert to float
        valid_values = [float(v) for v in strength_values if v is not None and not math.isnan(float(v))]
        
        if not valid_values:
            return 0.0
        
        # Weighted average with higher weight on geological causality
        weights = [0.15, 0.2, 0.2, 0.15, 0.3][:len(valid_values)]
        weighted_sum = sum(w * v for w, v in zip(weights, valid_values))
        weight_sum = sum(weights[:len(valid_values)])
        
        return weighted_sum / weight_sum if weight_sum > 0 else 0.0
    
    def _generate_causal_insights(self, attribution_results: Dict) -> List[str]:
        """Generate interpretable causal insights."""
        insights = []
        
