                vae_counterfactuals = self._generate_vae_counterfactuals(
                    counterfactual_generator, action_array, state_array
                )
                
                # 3. Apply geological physics constraints
                physics_filtered_counterfactuals = self._apply_geological_physics_constraints(
                    vae_counterfactuals, actions, state
                )
                
                # 4. Ensemble counterfactual generation
