    async def _perform_cross_temporal_validation(self, history):
        """Perform advanced cross-temporal validation using time series cross-validation and causal model robustness testing."""
        try:
            import numpy as np
            from scipy import stats
            from sklearn.model_selection import TimeSeriesSplit
            from sklearn.metrics import mean_squared_error, mean_absolute_error
            from sklearn.ensemble import RandomForestRegressor
            from sklearn.linear_model import LinearRegression, Ridge
            
            if not history or not isinstance(history, dict):
                return {'error': 'Invalid history data'}
            
            temporal_data = self._extract_temporal_sequences(history)
            if not temporal_data:
                return {'error': 'No temporal data found'}
            
            validation_results = {
                'time_series_cv': {},
                'causal_model_robustness': {},
                'temporal_stability': {},
                'out_of_sample_performance': {},
                'regime_generalization': {},
                'bootstrap_validation': {}
            }
            
            variable_names = list(temporal_data.keys())
            
            # 1. Time Series Cross-Validation
            if len(variable_names) >= 2:
                # Prepare target and features
                for target_var in variable_names:
                    feature_vars = [v for v in variable_names if v != target_var]
                    if not feature_vars:
                        continue
                    
                    y = np.array(temporal_data[target_var])
                    X = np.column_stack([temporal_data[var] for var in feature_vars])
                    
                    if len(y) < 100:  # Need sufficient data for CV
                        continue
                    
                    # Time series split with multiple models
                    tscv = TimeSeriesSplit(n_splits=5)
                    models = {
                        'linear': LinearRegression(),
                        'ridge': Ridge(alpha=1.0),
                        'random_forest': RandomForestRegressor(n_estimators=50, random_state=42)
                    }
                    
                    cv_scores = {}
                    for model_name, model in models.items():
                        fold_scores = []
                        temporal_consistency = []
                        
                        for train_idx, test_idx in tscv.split(X):
                            X_train, X_test = X[train_idx], X[test_idx]
                            y_train, y_test = y[train_idx], y[test_idx]
                            
                            try:
                                model.fit(X_train, y_train)
                                y_pred = model.predict(X_test)
                                
                                # Calculate performance metrics
                                mse = mean_squared_error(y_test, y_pred)
                                mae = mean_absolute_error(y_test, y_pred)
                                
                                # Temporal consistency (correlation between predicted and actual trends)
                                if len(y_test) > 1:
                                    actual_trend = np.diff(y_test)
                                    pred_trend = np.diff(y_pred)
                                    trend_corr = stats.pearsonr(actual_trend, pred_trend)[0]
                                    temporal_consistency.append(abs(trend_corr) if not np.isnan(trend_corr) else 0)
                                
                                fold_scores.append({'mse': mse, 'mae': mae})
                            except:
                                continue
                        
                        if fold_scores:
                            cv_scores[model_name] = {
                                'mean_mse': float(np.mean([s['mse'] for s in fold_scores])),
                                'std_mse': float(np.std([s['mse'] for s in fold_scores])),
                                'mean_mae': float(np.mean([s['mae'] for s in fold_scores])),
                                'temporal_consistency': float(np.mean(temporal_consistency)) if temporal_consistency else 0.0,
                                'stability': float(1.0 / (1.0 + np.std([s['mse'] for s in fold_scores])))
                            }
                    
                    validation_results['time_series_cv'][target_var] = cv_scores
            
            # 2. Causal model robustness testing
            robustness_results = await self._test_causal_model_robustness(temporal_data)
            validation_results['causal_model_robustness'] = robustness_results
            
            # 3. Temporal stability validation
            stability_validation = await self._validate_temporal_stability(temporal_data)
            validation_results['temporal_stability'] = stability_validation
            
            # 4. Out-of-sample performance assessment
            out_sample_performance = await self._assess_out_of_sample_performance(temporal_data)
            validation_results['out_of_sample_performance'] = out_sample_performance
            
            # 5. Regime-specific generalization
            regime_generalization = await self._assess_regime_generalization(temporal_data)
            validation_results['regime_generalization'] = regime_generalization
            
            # 6. Bootstrap validation
            bootstrap_validation = await self._perform_bootstrap_validation(temporal_data)
            validation_results['bootstrap_validation'] = bootstrap_validation
            
            # Calculate overall validation score
            overall_score = self._calculate_overall_validation_score(validation_results)
            temporal_generalization = overall_score > 0.6
            
            return {
                'validation_score': overall_score,
                'temporal_generalization': temporal_generalization,
                'detailed_validation': validation_results,
                'confidence': self._calculate_validation_confidence(validation_results)
            }
            
        except Exception as e:
            self.logger.error(f"Cross-temporal validation failed: {e}")
            return {
                'error': str(e),
                'validation_score': 0.0,
                'temporal_generalization': False
            }
    
    async def _build_predictive_causal_models(self, history):
        """Build advanced predictive models using causal discovery, deep learning, and ensemble methods."""
        try:
            import numpy as np
            from scipy import stats
            from sklearn.ensemble import RandomForestRegressor, GradientBoostingRegressor
            from sklearn.neural_network import MLPRegressor
            from sklearn.linear_model import ElasticNet, BayesianRidge
            from sklearn.preprocessing import StandardScaler
            from sklearn.model_selection import TimeSeriesSplit
            from sklearn.metrics import mean_squared_error, r2_score
            
            if not history or not isinstance(history, dict):
                return {'error': 'Invalid history data'}
            
            temporal_data = self._extract_temporal_sequences(history)
            if not temporal_data:
                return {'error': 'No temporal data found'}
            
            prediction_results = {
                'causal_structure_models': {},
                'ensemble_predictions': {},
                'temporal_forecasting': {},
                'regime_aware_models': {},
                'uncertainty_quantification': {},
                'model_interpretability': {}
            }
            
            variable_names = list(temporal_data.keys())
            
            # 1. Causal Structure-Based Models
            for target_var in variable_names:
                feature_vars = [v for v in variable_names if v != target_var]
                if not feature_vars or len(temporal_data[target_var]) < 100:
                    continue
                
                y = np.array(temporal_data[target_var])
                X = np.column_stack([temporal_data[var] for var in feature_vars])
                
                # Add lagged features for temporal dependencies
                X_temporal = self._create_temporal_features(X, y, max_lags=5)
                
                # Split data temporally
                split_point = int(len(y) * 0.8)
                X_train, X_test = X_temporal[:split_point], X_temporal[split_point:]
                y_train, y_test = y[:split_point], y[split_point:]
                
                if len(X_test) < 10:  # Need reasonable test set
                    continue
                
                # Scale features
                scaler = StandardScaler()
                X_train_scaled = scaler.fit_transform(X_train)
                X_test_scaled = scaler.transform(X_test)
                
                # Build ensemble of causal models
                models = {
                    'elastic_net': ElasticNet(alpha=0.1, l1_ratio=0.5, random_state=42),
                    'bayesian_ridge': BayesianRidge(),
                    'random_forest': RandomForestRegressor(n_estimators=100, random_state=42),
                    'gradient_boost': GradientBoostingRegressor(n_estimators=100, random_state=42),
                    'neural_network': MLPRegressor(hidden_layer_sizes=(100, 50), max_iter=500, random_state=42)
                }
                
                model_performances = {}
                predictions = {}
                
                for model_name, model in models.items():
                    try:
                        model.fit(X_train_scaled, y_train)
                        y_pred = model.predict(X_test_scaled)
                        
                        # Calculate performance metrics
                        mse = mean_squared_error(y_test, y_pred)
                        r2 = r2_score(y_test, y_pred)
                        
                        # Next period prediction (1-step ahead)
                        next_pred = model.predict(X_test_scaled[-1:].reshape(1, -1))[0]
                        
                        model_performances[model_name] = {
                            'mse': float(mse),
                            'r2': float(r2),
                            'next_period_pred': float(next_pred)
                        }
                        predictions[model_name] = y_pred.tolist()
                        
                    except Exception as model_error:
                        self.logger.warning(f"Model {model_name} failed for {target_var}: {model_error}")
                        continue
                
                # Ensemble prediction (weighted by R²)
                if model_performances:
                    weights = np.array([max(0, perf['r2']) for perf in model_performances.values()])
                    weights = weights / np.sum(weights) if np.sum(weights) > 0 else np.ones(len(weights)) / len(weights)
                    
                    ensemble_pred = np.average(
                        [predictions[model] for model in model_performances.keys()],
                        weights=weights, axis=0
                    )
                    
                    ensemble_mse = mean_squared_error(y_test, ensemble_pred)
                    ensemble_r2 = r2_score(y_test, ensemble_pred)
                    
                    prediction_results['causal_structure_models'][target_var] = {
                        'individual_models': model_performances,
                        'ensemble_performance': {
                            'mse': float(ensemble_mse),
                            'r2': float(ensemble_r2),
                            'next_period_accuracy': float(1.0 - abs(ensemble_pred[-1] - y_test[-1]) / (abs(y_test[-1]) + 1e-10))
                        },
                        'model_weights': {model: float(w) for model, w in zip(model_performances.keys(), weights)}
                    }
            
            # 2. Multi-step forecasting
            forecasting_results = await self._build_multi_step_forecasting_models(temporal_data)
            prediction_results['temporal_forecasting'] = forecasting_results
            
            # 3. Regime-aware predictive models
            regime_models = await self._build_regime_aware_models(temporal_data)
            prediction_results['regime_aware_models'] = regime_models
            
            # 4. Uncertainty quantification
            uncertainty_results = await self._quantify_prediction_uncertainty(temporal_data)
            prediction_results['uncertainty_quantification'] = uncertainty_results
            
            # 5. Model interpretability analysis
            interpretability_results = await self._analyze_model_interpretability(temporal_data)
            prediction_results['model_interpretability'] = interpretability_results
            
            # Calculate overall accuracy metrics
            accuracy_summary = self._calculate_prediction_accuracy_summary(prediction_results)
            
            return {
                'accuracy': accuracy_summary,
                'detailed_models': prediction_results,
                'confidence': self._calculate_prediction_confidence(prediction_results)
            }
            
        except Exception as e:
            self.logger.error(f"Predictive causal model building failed: {e}")
            return {
                'error': str(e),
                'accuracy': {'next_period': 0.0, 'long_term': 0.0}
            }
    
