    def _preprocess_temporal_data(self, temporal_data):
        """Preprocess temporal data."""
        try:
            import numpy as np
            # Basic preprocessing - normalization and outlier removal
            data_array = np.array(temporal_data)
            # Remove outliers using IQR method
            Q1, Q3 = np.percentile(data_array, [25, 75])
            IQR = Q3 - Q1
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            filtered_data = data_array[(data_array >= lower_bound) & (data_array <= upper_bound)]
            return filtered_data.tolist() if len(filtered_data) > 0 else temporal_data
        except Exception:
            return temporal_data

