# Quality metrics classes

class GeologicalSignificanceMetric:
    """Advanced multi-criteria geological significance assessment using machine learning and domain knowledge."""
    
    def __init__(self):
        self.feature_importance_model = RandomForestRegressor(n_estimators=100, random_state=42)
        self.domain_weights = {
            'lithology_diversity': 0.15,
            'structural_complexity': 0.20,
            'temporal_span': 0.12,
            'spatial_coverage': 0.18,
            'geochemical_variability': 0.13,
            'tectonic_significance': 0.22
        }
        self.knowledge_graph_weights = {}
        self.trained = False
        
    def _extract_geological_features(self, experience_data) -> Dict[str, float]:
        """Extract comprehensive geological features from experience data."""
        features = {}
        
        # Lithology diversity analysis
        lithologies = experience_data.get('lithologies', [])
        features['lithology_diversity'] = len(set(lithologies)) / max(len(lithologies), 1)
        
        # Structural complexity assessment
        structures = experience_data.get('geological_structures', {})
        structural_types = ['faults', 'folds', 'joints', 'fractures', 'intrusions']
        complexity_score = sum([len(structures.get(s_type, [])) for s_type in structural_types])
        features['structural_complexity'] = min(complexity_score / 10.0, 1.0)  # Normalized
        
        # Temporal span significance
        temporal_range = experience_data.get('temporal_range', {})
        start_age = temporal_range.get('start_ma', 0)
        end_age = temporal_range.get('end_ma', 0)
        age_span = abs(start_age - end_age)
        features['temporal_span'] = min(age_span / 4600.0, 1.0)  # Normalized by Earth age
        
        # Spatial coverage assessment
        spatial_extent = experience_data.get('spatial_extent', {})
        area_km2 = spatial_extent.get('area_km2', 0)
        features['spatial_coverage'] = min(np.log10(area_km2 + 1) / 8.0, 1.0)  # Log scale
        
        # Geochemical variability
        geochemical_data = experience_data.get('geochemical_analyses', [])
        if geochemical_data:
            element_variations = []
            for analysis in geochemical_data:
                elements = analysis.get('elements', {})
                if len(elements) > 1:
                    values = list(elements.values())
                    cv = np.std(values) / (np.mean(values) + 1e-10)  # Coefficient of variation
                    element_variations.append(cv)
            features['geochemical_variability'] = np.mean(element_variations) if element_variations else 0.0
        else:
            features['geochemical_variability'] = 0.0
            
        # Tectonic significance
        tectonic_context = experience_data.get('tectonic_setting', {})
        tectonic_indicators = [
            tectonic_context.get('plate_boundary_distance', 1000) < 100,  # Near plate boundary
            tectonic_context.get('volcanic_activity', False),
            tectonic_context.get('seismic_activity_level', 0) > 3,
            tectonic_context.get('active_faulting', False),
            len(tectonic_context.get('stress_indicators', [])) > 2
        ]
        features['tectonic_significance'] = sum(tectonic_indicators) / len(tectonic_indicators)
        
        return features
    
    def _assess_knowledge_graph_significance(self, experience_data) -> float:
        """Assess significance based on knowledge graph connectivity and scientific impact."""
        concept_entities = experience_data.get('linked_concepts', [])
        if not concept_entities:
            return 0.0
            
        # Calculate semantic similarity with high-impact geological concepts
        high_impact_concepts = [
            'mass_extinction_event', 'large_igneous_province', 'ore_deposit_formation',
            'climate_change_driver', 'tectonic_plate_reorganization', 'mantle_plume',
            'supercontinent_cycle', 'ocean_anoxic_event'
        ]
        
        max_similarity = 0.0
        for entity in concept_entities:
            entity_embedding = self._get_concept_embedding(entity)
            for concept in high_impact_concepts:
                concept_embedding = self._get_concept_embedding(concept)
                similarity = cosine_similarity([entity_embedding], [concept_embedding])[0][0]
                max_similarity = max(max_similarity, similarity)
                
        return min(max_similarity * 2.0, 1.0)  # Scale and cap at 1.0
    
    def _get_concept_embedding(self, concept: str) -> np.ndarray:
        """Get semantic embedding for geological concept."""
        # Use pre-trained scientific embedding model
        if not hasattr(self, 'embedding_model'):
            self.embedding_model = SentenceTransformer('allenai/scibert-scivocab-uncased')
        return self.embedding_model.encode([concept])[0]
    
    def _calculate_uncertainty_weighted_score(self, features: Dict[str, float], 
                                            experience_data: Dict) -> Tuple[float, float]:
        """Calculate significance score with uncertainty quantification."""
        # Data quality indicators
        measurement_uncertainty = experience_data.get('measurement_uncertainty', 0.1)
        sample_size = experience_data.get('sample_size', 1)
        analytical_precision = experience_data.get('analytical_precision', 0.95)
        
        # Calculate weighted score
        base_score = 0.0
        total_weight = 0.0
        
        for feature_name, value in features.items():
            if feature_name in self.domain_weights:
                weight = self.domain_weights[feature_name]
                base_score += weight * value
                total_weight += weight
                
        if total_weight > 0:
            base_score /= total_weight
            
        # Knowledge graph enhancement
        kg_significance = self._assess_knowledge_graph_significance(experience_data)
        enhanced_score = 0.7 * base_score + 0.3 * kg_significance
        
        # Uncertainty calculation
        uncertainty_factors = [
            measurement_uncertainty,
            1.0 / np.sqrt(sample_size),  # Sample size effect
            1.0 - analytical_precision,  # Analytical uncertainty
        ]
        total_uncertainty = np.sqrt(sum([u**2 for u in uncertainty_factors]))
        
        return enhanced_score, total_uncertainty
    
    def assess(self, experience_data) -> float:
        """Assess geological significance using advanced multi-criteria analysis."""
        try:
            # Extract geological features
            features = self._extract_geological_features(experience_data)
            
            # Calculate uncertainty-weighted significance score
            significance_score, uncertainty = self._calculate_uncertainty_weighted_score(
                features, experience_data
            )
            
            # Apply Bayesian updating if prior knowledge exists
            prior_significance = experience_data.get('prior_significance', 0.5)
            confidence_in_prior = experience_data.get('prior_confidence', 0.3)
            
            # Bayesian combination of prior and current assessment
            posterior_significance = (
                confidence_in_prior * prior_significance + 
                (1 - confidence_in_prior) * significance_score
            )
            
            # Ensure score is within valid range
            final_score = max(0.0, min(1.0, posterior_significance))
            
            # Log assessment details for transparency
            logging.info(f"Geological significance assessment: score={final_score:.3f}, "
                        f"uncertainty={uncertainty:.3f}, features={features}")
            
            return final_score
            
        except Exception as e:
            logging.error(f"Error in geological significance assessment: {e}")
            # Return conservative estimate with high uncertainty
            return 0.3

class DataCompletenessMetric:
    """Advanced data completeness assessment using information theory and missing data analysis."""
    
    def __init__(self):
        self.required_fields = {
            'essential': [
                'spatial_coordinates', 'temporal_information', 'geological_context',
                'data_source', 'measurement_method'
            ],
            'important': [
                'lithological_description', 'structural_measurements', 
                'geochemical_data', 'sample_metadata'
            ],
            'supplementary': [
                'environmental_conditions', 'analytical_uncertainty',
                'quality_control_data', 'related_studies'
            ]
        }
        self.field_weights = {
            'essential': 0.6,
            'important': 0.3,
            'supplementary': 0.1
        }
        
    def _calculate_field_completeness(self, experience_data: Dict) -> Dict[str, float]:
        """Calculate completeness for each field category."""
        completeness_scores = {}
        
        for category, fields in self.required_fields.items():
            present_fields = 0
            total_quality_score = 0.0
            
            for field in fields:
                if field in experience_data:
                    field_value = experience_data[field]
                    if field_value is not None:
                        # Assess field quality based on data type and content
                        quality_score = self._assess_field_quality(field, field_value)
                        present_fields += 1
                        total_quality_score += quality_score
                        
            if len(fields) > 0:
                completeness_scores[category] = {
                    'presence_ratio': present_fields / len(fields),
                    'avg_quality': total_quality_score / max(present_fields, 1),
                    'weighted_score': (present_fields / len(fields)) * 
                                     (total_quality_score / max(present_fields, 1))
                }
            else:
                completeness_scores[category] = {
                    'presence_ratio': 0.0,
                    'avg_quality': 0.0,
                    'weighted_score': 0.0
                }
                
        return completeness_scores
    
    def _assess_field_quality(self, field_name: str, field_value: Any) -> float:
        """Assess the quality of individual field data."""
        if field_value is None:
            return 0.0
            
        quality_score = 0.0
        
        # Spatial coordinates quality
        if field_name == 'spatial_coordinates':
            coords = field_value
            if isinstance(coords, dict):
                has_lat = 'latitude' in coords and coords['latitude'] is not None
                has_lon = 'longitude' in coords and coords['longitude'] is not None
                has_elevation = 'elevation' in coords and coords['elevation'] is not None
                has_precision = 'coordinate_precision' in coords
                
                quality_score = (has_lat + has_lon) * 0.4 + has_elevation * 0.1 + has_precision * 0.1
                
                # Check coordinate validity
                if has_lat and has_lon:
                    lat, lon = coords['latitude'], coords['longitude']
                    if -90 <= lat <= 90 and -180 <= lon <= 180:
                        quality_score += 0.2
                        
        # Temporal information quality
        elif field_name == 'temporal_information':
            temp_info = field_value
            if isinstance(temp_info, dict):
                has_age = 'age' in temp_info or 'date_collected' in temp_info
                has_uncertainty = 'age_uncertainty' in temp_info or 'temporal_precision' in temp_info
                has_method = 'dating_method' in temp_info
                
                quality_score = has_age * 0.5 + has_uncertainty * 0.3 + has_method * 0.2
                
        # Geochemical data quality
        elif field_name == 'geochemical_data':
            geochem = field_value
            if isinstance(geochem, (list, dict)):
                if isinstance(geochem, dict):
                    geochem = [geochem]
                    
                total_elements = 0
                quality_indicators = 0
                
                for analysis in geochem:
                    if 'elements' in analysis:
                        total_elements += len(analysis['elements'])
                    if 'analytical_uncertainty' in analysis:
                        quality_indicators += 1
                    if 'detection_limits' in analysis:
                        quality_indicators += 1
                    if 'analytical_method' in analysis:
                        quality_indicators += 1
                        
                element_score = min(total_elements / 20.0, 1.0)  # Normalized by typical analysis
                quality_score = 0.6 * element_score + 0.4 * (quality_indicators / (len(geochem) * 3))
                
        # Generic quality assessment for other fields
        else:
            if isinstance(field_value, str):
                # String completeness based on length and content
                length_score = min(len(field_value) / 100.0, 1.0)
                has_numeric = any(c.isdigit() for c in field_value)
                has_special = any(c in field_value for c in ['/', '-', ':', '(', ')', '[', ']'])
                content_score = (has_numeric + has_special) / 2.0
                quality_score = 0.7 * length_score + 0.3 * content_score
                
            elif isinstance(field_value, (list, tuple)):
                # List completeness based on number of items
                quality_score = min(len(field_value) / 5.0, 1.0)
                
            elif isinstance(field_value, dict):
                # Dictionary completeness based on number of keys
                quality_score = min(len(field_value) / 3.0, 1.0)
                
            elif isinstance(field_value, (int, float)):
                # Numeric data is considered complete if present
                quality_score = 1.0 if not np.isnan(field_value) else 0.0
                
            else:
                # Default score for other data types
                quality_score = 0.8
                
        return min(quality_score, 1.0)
    
    def _calculate_information_entropy(self, experience_data: Dict) -> float:
        """Calculate information entropy to assess data richness."""
        # Extract all textual content for entropy calculation
        text_content = []
        
        def extract_text(obj, path=""):
            if isinstance(obj, str):
                text_content.append(obj)
            elif isinstance(obj, dict):
                for key, value in obj.items():
                    extract_text(value, f"{path}.{key}")
            elif isinstance(obj, (list, tuple)):
                for i, item in enumerate(obj):
                    extract_text(item, f"{path}[{i}]")
                    
        extract_text(experience_data)
        
        if not text_content:
            return 0.0
            
        # Calculate character frequency distribution
        all_text = " ".join(text_content).lower()
        char_counts = defaultdict(int)
        
        for char in all_text:
            if char.isalnum() or char.isspace():
                char_counts[char] += 1
                
        total_chars = sum(char_counts.values())
        if total_chars == 0:
            return 0.0
            
        # Calculate entropy
        probabilities = [count / total_chars for count in char_counts.values()]
        information_entropy = entropy(probabilities, base=2)
        
        # Normalize entropy (typical English text has entropy ~4.1 bits/char)
        normalized_entropy = min(information_entropy / 4.5, 1.0)
        
        return normalized_entropy
    
    def _assess_missing_data_patterns(self, experience_data: Dict) -> Dict[str, Any]:
        """Analyze patterns in missing data to identify systematic gaps."""
        missing_analysis = {
            'missing_fields': [],
            'partially_missing_fields': [],
            'data_quality_issues': [],
            'missingness_pattern': 'random'  # random, systematic, or clustered
        }
        
        # Identify completely missing fields
        all_expected_fields = []
        for fields in self.required_fields.values():
            all_expected_fields.extend(fields)
            
        for field in all_expected_fields:
            if field not in experience_data or experience_data[field] is None:
                missing_analysis['missing_fields'].append(field)
                
        # Identify partially missing or low-quality fields
        for field, value in experience_data.items():
            quality = self._assess_field_quality(field, value)
            if 0.1 <= quality < 0.7:  # Partially complete
                missing_analysis['partially_missing_fields'].append((field, quality))
            elif quality < 0.1:  # Very low quality
                missing_analysis['data_quality_issues'].append((field, quality))
                
        # Detect missingness patterns
        missing_in_essential = sum(1 for f in self.required_fields['essential'] 
                                 if f in missing_analysis['missing_fields'])
        missing_in_important = sum(1 for f in self.required_fields['important'] 
                                 if f in missing_analysis['missing_fields'])
        
        if missing_in_essential > len(self.required_fields['essential']) * 0.5:
            missing_analysis['missingness_pattern'] = 'systematic'
        elif missing_in_important > len(self.required_fields['important']) * 0.3:
            missing_analysis['missingness_pattern'] = 'clustered'
            
        return missing_analysis
    
    def assess(self, experience_data) -> float:
        """Assess data completeness using information theory and missing data analysis."""
        try:
            # Calculate field-based completeness
            field_completeness = self._calculate_field_completeness(experience_data)
            
            # Calculate weighted completeness score
            weighted_completeness = 0.0
            for category, scores in field_completeness.items():
                if category in self.field_weights:
                    weight = self.field_weights[category]
                    weighted_completeness += weight * scores['weighted_score']
                    
            # Calculate information entropy contribution
            entropy_score = self._calculate_information_entropy(experience_data)
            
            # Analyze missing data patterns
            missing_analysis = self._assess_missing_data_patterns(experience_data)
            
            # Apply penalty for systematic missing data
            pattern_penalty = {
                'random': 0.0,
                'clustered': 0.1,
                'systematic': 0.2
            }
            penalty = pattern_penalty.get(missing_analysis['missingness_pattern'], 0.0)
            
            # Combine scores
            base_completeness = 0.7 * weighted_completeness + 0.3 * entropy_score
            final_score = max(0.0, base_completeness - penalty)
            
            # Log detailed analysis
            logging.info(f"Data completeness assessment: score={final_score:.3f}, "
                        f"field_completeness={field_completeness}, "
                        f"entropy_score={entropy_score:.3f}, "
                        f"missing_pattern={missing_analysis['missingness_pattern']}")
            
            return final_score
            
        except Exception as e:
            logging.error(f"Error in data completeness assessment: {e}")
            return 0.4  # Conservative fallback score

class SpatialRepresentativityMetric:
    """Advanced spatial representativity assessment using geostatistics and machine learning."""
    
    def __init__(self):
        self.spatial_analysis_models = {
            'variogram': None,
            'kriging_model': None,
            'spatial_autocorr': None
        }
        self.geological_domains = {
            'igneous': {'characteristic_scale_km': 10, 'heterogeneity': 0.7},
            'sedimentary': {'characteristic_scale_km': 50, 'heterogeneity': 0.4},
            'metamorphic': {'characteristic_scale_km': 20, 'heterogeneity': 0.6},
            'volcanic': {'characteristic_scale_km': 5, 'heterogeneity': 0.9},
            'tectonic': {'characteristic_scale_km': 100, 'heterogeneity': 0.8}
        }
        
    def _calculate_spatial_coverage(self, experience_data: Dict) -> Dict[str, float]:
        """Calculate comprehensive spatial coverage metrics."""
        spatial_info = experience_data.get('spatial_extent', {})
        sample_locations = experience_data.get('sample_locations', [])
        
        coverage_metrics = {
            'areal_coverage': 0.0,
            'sampling_density': 0.0,
            'spatial_distribution': 0.0,
            'multi_scale_coverage': 0.0
        }
        
        # Areal coverage assessment
        total_area = spatial_info.get('area_km2', 0)
        bounding_box = spatial_info.get('bounding_box', {})
        if bounding_box and 'min_lat' in bounding_box:
            lat_range = bounding_box['max_lat'] - bounding_box['min_lat']
            lon_range = bounding_box['max_lon'] - bounding_box['min_lon']
            # Convert to approximate area (rough calculation)
            approx_area = lat_range * lon_range * 111 * 111 * np.cos(np.radians(
                (bounding_box['min_lat'] + bounding_box['max_lat']) / 2
            ))
            coverage_metrics['areal_coverage'] = min(total_area / max(approx_area, 1), 1.0)
            
        # Sampling density analysis
        if sample_locations and total_area > 0:
            density = len(sample_locations) / total_area
            # Normalize by geological domain expectations
            geological_domain = experience_data.get('dominant_geology', 'sedimentary')
            expected_density = self._get_expected_sampling_density(geological_domain)
            coverage_metrics['sampling_density'] = min(density / expected_density, 1.0)
            
        # Spatial distribution assessment using nearest neighbor analysis
        if len(sample_locations) > 2:
            coords = np.array([[loc.get('latitude', 0), loc.get('longitude', 0)] 
                             for loc in sample_locations if 'latitude' in loc])
            if len(coords) > 2:
                # Calculate nearest neighbor distances
                from sklearn.neighbors import NearestNeighbors
                nbrs = NearestNeighbors(n_neighbors=2).fit(coords)
                distances, indices = nbrs.kneighbors(coords)
                nn_distances = distances[:, 1]  # Exclude self (distance 0)
                
                # Calculate regularity index (Clark-Evans index)
                mean_nn_dist = np.mean(nn_distances)
                expected_nn_dist = 0.5 / np.sqrt(len(coords) / total_area) if total_area > 0 else 1
                regularity_index = mean_nn_dist / expected_nn_dist if expected_nn_dist > 0 else 0
                coverage_metrics['spatial_distribution'] = min(regularity_index, 2.0) / 2.0
                
        # Multi-scale coverage assessment
        scale_ranges = experience_data.get('scale_ranges', {})
        local_scale = scale_ranges.get('local_m', 0) > 0
        regional_scale = scale_ranges.get('regional_km', 0) > 0
        basin_scale = scale_ranges.get('basin_km', 0) > 0
        coverage_metrics['multi_scale_coverage'] = (local_scale + regional_scale + basin_scale) / 3.0
        
        return coverage_metrics
    
    def _get_expected_sampling_density(self, geological_domain: str) -> float:
        """Get expected sampling density for geological domain (samples per km²)."""
        density_standards = {
            'igneous': 0.1,     # Complex, requires dense sampling
            'sedimentary': 0.02, # More uniform, less dense sampling needed
            'metamorphic': 0.05, # Moderate complexity
            'volcanic': 0.2,     # Very heterogeneous, dense sampling
            'tectonic': 0.01     # Large scale features
        }
        return density_standards.get(geological_domain, 0.05)
    
    def _assess_geological_representativity(self, experience_data: Dict) -> float:
        """Assess how well the spatial sampling represents geological variability."""
        geological_features = experience_data.get('geological_features', {})
        spatial_variability = experience_data.get('spatial_variability', {})
        
        representativity_score = 0.0
        
        # Lithological representativity
        lithology_distribution = geological_features.get('lithology_distribution', {})
        sampled_lithologies = set(experience_data.get('sampled_lithologies', []))
        total_lithologies = set(lithology_distribution.keys()) if lithology_distribution else set()
        
        if total_lithologies:
            litho_coverage = len(sampled_lithologies & total_lithologies) / len(total_lithologies)
            representativity_score += 0.3 * litho_coverage
            
        # Structural representativity
        structural_domains = geological_features.get('structural_domains', [])
        sampled_domains = experience_data.get('sampled_structural_domains', [])
        
        if structural_domains:
            struct_coverage = len(set(sampled_domains) & set(structural_domains)) / len(structural_domains)
            representativity_score += 0.2 * struct_coverage
            
        # Topographic representativity
        elevation_range = spatial_variability.get('elevation_range_m', 0)
        sampled_elevations = experience_data.get('sampled_elevations', [])
        
        if sampled_elevations and elevation_range > 0:
            sampled_range = max(sampled_elevations) - min(sampled_elevations)
            topo_coverage = min(sampled_range / elevation_range, 1.0)
            representativity_score += 0.2 * topo_coverage
            
        # Geochemical variability representativity
        geochem_variability = spatial_variability.get('geochemical_variability', {})
        if geochem_variability:
            # Check if major geochemical trends are captured
            element_trends = geochem_variability.get('element_trends', {})
            captured_trends = 0
            total_trends = len(element_trends)
            
            for element, trend_info in element_trends.items():
                sampled_values = experience_data.get('geochemical_data', {}).get(element, [])
                if sampled_values:
                    trend_range = trend_info.get('max', 0) - trend_info.get('min', 0)
                    sampled_range = max(sampled_values) - min(sampled_values)
                    if sampled_range >= 0.6 * trend_range:  # Captured 60% of variability
                        captured_trends += 1
                        
            if total_trends > 0:
                geochem_coverage = captured_trends / total_trends
                representativity_score += 0.3 * geochem_coverage
                
        return representativity_score
    
    def _perform_geostatistical_analysis(self, experience_data: Dict) -> Dict[str, float]:
        """Perform geostatistical analysis to assess spatial continuity and representativity."""
        sample_locations = experience_data.get('sample_locations', [])
        if len(sample_locations) < 4:  # Need minimum samples for geostatistics
            return {'spatial_continuity': 0.5, 'prediction_variance': 0.8}
            
        try:
            # Extract coordinates and values
            coords = []
            values = []
            
            for location in sample_locations:
                if 'latitude' in location and 'longitude' in location:
                    coords.append([location['latitude'], location['longitude']])
                    # Use a representative measurement as the value
                    value = location.get('measurement_value', 
                                       location.get('elevation', 
                                                  np.random.random()))  # Fallback
                    values.append(value)
                    
            if len(coords) < 4:
                return {'spatial_continuity': 0.5, 'prediction_variance': 0.8}
                
            coords = np.array(coords)
            values = np.array(values)
            
            # Calculate experimental variogram
            distances = []
            variances = []
            
            for i in range(len(coords)):
                for j in range(i + 1, len(coords)):
                    # Calculate distance
                    dist = np.sqrt(np.sum((coords[i] - coords[j])**2))
                    # Calculate semi-variance
                    semivar = 0.5 * (values[i] - values[j])**2
                    
                    distances.append(dist)
                    variances.append(semivar)
                    
            if not distances:
                return {'spatial_continuity': 0.5, 'prediction_variance': 0.8}
                
            # Analyze spatial continuity from variogram
            distances = np.array(distances)
            variances = np.array(variances)
            
            # Sort by distance for analysis
            sorted_indices = np.argsort(distances)
            sorted_distances = distances[sorted_indices]
            sorted_variances = variances[sorted_indices]
            
            # Calculate spatial continuity metrics
            max_distance = np.max(sorted_distances)
            nugget_effect = np.min(sorted_variances)  # Micro-scale variability
            sill = np.max(sorted_variances)  # Maximum variability
            
            # Estimate range (distance where variogram plateaus)
            if sill > nugget_effect:
                # Find where variogram reaches 95% of sill
                target_variance = nugget_effect + 0.95 * (sill - nugget_effect)
                range_estimate = max_distance  # Default to max if no plateau found
                
                for i, var in enumerate(sorted_variances):
                    if var >= target_variance:
                        range_estimate = sorted_distances[i]
                        break
                        
                # Spatial continuity: higher when range is large relative to study area
                study_area_diagonal = experience_data.get('spatial_extent', {}).get('diagonal_km', 100)
                spatial_continuity = min(range_estimate / (study_area_diagonal * 0.1), 1.0)
                
                # Prediction variance: lower when nugget effect is small
                prediction_variance = 1.0 - (nugget_effect / sill) if sill > 0 else 0.5
                
            else:
                spatial_continuity = 0.3  # Poor spatial continuity
                prediction_variance = 0.2  # High uncertainty
                
            return {
                'spatial_continuity': spatial_continuity,
                'prediction_variance': prediction_variance
            }
            
        except Exception as e:
            logging.warning(f"Geostatistical analysis failed: {e}")
            return {'spatial_continuity': 0.5, 'prediction_variance': 0.8}
    
    def _calculate_scale_appropriateness(self, experience_data: Dict) -> float:
        """Calculate how appropriate the sampling scale is for the geological processes."""
        geological_processes = experience_data.get('geological_processes', [])
        sampling_scale = experience_data.get('sampling_scale_km', 1.0)
        
        scale_scores = []
        
        for process in geological_processes:
            process_name = process.get('name', '')
            characteristic_scale = process.get('characteristic_scale_km', 10.0)
            
            # Calculate scale matching score
            scale_ratio = sampling_scale / characteristic_scale
            
            # Optimal sampling is typically 1/5 to 1/2 of characteristic scale
            if 0.1 <= scale_ratio <= 0.5:
                scale_score = 1.0
            elif 0.05 <= scale_ratio < 0.1 or 0.5 < scale_ratio <= 1.0:
                scale_score = 0.7
            elif 0.02 <= scale_ratio < 0.05 or 1.0 < scale_ratio <= 2.0:
                scale_score = 0.4
            else:
                scale_score = 0.2
                
            # Weight by process importance
            importance_weight = process.get('importance', 1.0)
            scale_scores.append(scale_score * importance_weight)
            
        if scale_scores:
            return np.mean(scale_scores)
        else:
            return 0.5  # Neutral score when no process information
    
    def assess(self, experience_data) -> float:
        """Assess spatial representativity using advanced geostatistical analysis."""
        try:
            # Calculate spatial coverage metrics
            coverage_metrics = self._calculate_spatial_coverage(experience_data)
            
            # Assess geological representativity
            geological_repr = self._assess_geological_representativity(experience_data)
            
            # Perform geostatistical analysis
            geostat_metrics = self._perform_geostatistical_analysis(experience_data)
            
            # Calculate scale appropriateness
            scale_appropriateness = self._calculate_scale_appropriateness(experience_data)
            
            # Combine metrics with weights
            final_score = (
                0.25 * coverage_metrics['areal_coverage'] +
                0.20 * coverage_metrics['sampling_density'] +
                0.15 * coverage_metrics['spatial_distribution'] +
                0.10 * coverage_metrics['multi_scale_coverage'] +
                0.20 * geological_repr +
                0.15 * geostat_metrics['spatial_continuity'] +
                0.10 * geostat_metrics['prediction_variance'] +
                0.15 * scale_appropriateness
            )
            
            # Ensure score is within valid range
            final_score = max(0.0, min(1.0, final_score))
            
            # Log detailed assessment
            logging.info(f"Spatial representativity assessment: score={final_score:.3f}, "
                        f"coverage={coverage_metrics}, geological_repr={geological_repr:.3f}, "
                        f"geostat={geostat_metrics}, scale_match={scale_appropriateness:.3f}")
            
            return final_score
            
        except Exception as e:
            logging.error(f"Error in spatial representativity assessment: {e}")
            return 0.4  # Conservative fallback score

class TemporalRelevanceMetric:
    """Advanced temporal relevance assessment using time series analysis and causal inference."""
    
    def __init__(self):
        self.temporal_decay_models = {
            'exponential': lambda t, half_life: np.exp(-np.log(2) * t / half_life),
            'power_law': lambda t, exponent: t**(-exponent),
            'gaussian': lambda t, sigma: np.exp(-t**2 / (2 * sigma**2))
        }
        self.geological_time_scales = {
            'recent': {'max_age_ma': 0.01, 'relevance_half_life': 0.005},
            'quaternary': {'max_age_ma': 2.6, 'relevance_half_life': 1.0},
            'cenozoic': {'max_age_ma': 66, 'relevance_half_life': 20},
            'mesozoic': {'max_age_ma': 252, 'relevance_half_life': 50},
            'paleozoic': {'max_age_ma': 541, 'relevance_half_life': 100},
            'precambrian': {'max_age_ma': 4600, 'relevance_half_life': 500}
        }
        
    def _calculate_temporal_distance(self, experience_data: Dict) -> Dict[str, float]:
        """Calculate various temporal distance metrics."""
        current_time = datetime.now()
        target_time = experience_data.get('target_time', current_time)
        
        # Experience temporal information
        experience_age_ma = experience_data.get('geological_age_ma', 0)
        data_collection_date = experience_data.get('data_collection_date')
        
        temporal_distances = {
            'geological_time_distance': 0.0,
            'data_collection_recency': 0.0,
            'process_time_relevance': 0.0,
            'temporal_resolution_match': 0.0
        }
        
        # Geological time distance
        target_age_ma = experience_data.get('target_geological_age_ma', 0)
        if experience_age_ma > 0 and target_age_ma >= 0:
            age_difference = abs(experience_age_ma - target_age_ma)
            # Normalize by geological time scale
            max_earth_age = 4600  # Ma
            temporal_distances['geological_time_distance'] = 1.0 - (age_difference / max_earth_age)
            
        # Data collection recency
        if data_collection_date:
            if isinstance(data_collection_date, str):
                try:
                    collection_dt = datetime.fromisoformat(data_collection_date.replace('Z', '+00:00'))
                except:
                    collection_dt = current_time - timedelta(days=365)  # Default to 1 year ago
            else:
                collection_dt = data_collection_date
                
            days_since_collection = (current_time - collection_dt).days
            # Decay function for data recency (5-year half-life)
            recency_score = np.exp(-np.log(2) * days_since_collection / (5 * 365.25))
            temporal_distances['data_collection_recency'] = recency_score
            
        return temporal_distances
    
    def _assess_process_temporal_relevance(self, experience_data: Dict) -> float:
        """Assess relevance based on geological process time scales."""
        geological_processes = experience_data.get('geological_processes', [])
        target_process = experience_data.get('target_process')
        
        if not geological_processes or not target_process:
            return 0.5  # Neutral score
            
        process_relevance_scores = []
        
        for process in geological_processes:
            process_name = process.get('name', '')
            process_timescale_ma = process.get('characteristic_timescale_ma', 1.0)
            process_age_ma = process.get('age_ma', 0)
            
            # Calculate temporal relevance for this process
            if target_process.get('name') == process_name:
                # Direct process match - assess temporal proximity
                target_age_ma = target_process.get('age_ma', 0)
                age_difference = abs(process_age_ma - target_age_ma)
                
                # Relevance based on process characteristic timescale
                if age_difference <= process_timescale_ma:
                    relevance = 1.0  # Within characteristic timescale
                elif age_difference <= 2 * process_timescale_ma:
                    relevance = 0.7  # Close to characteristic timescale
                elif age_difference <= 5 * process_timescale_ma:
                    relevance = 0.4  # Moderately relevant
                else:
                    relevance = 0.1  # Low relevance
                    
                process_relevance_scores.append(relevance)
                
            # Assess analogous processes
            target_process_type = target_process.get('type', '')
            process_type = process.get('type', '')
            
            if process_type == target_process_type and process_name != target_process.get('name'):
                # Analogous process - assess temporal transferability
                temporal_analogy_score = self._calculate_temporal_analogy_strength(
                    process, target_process
                )
                process_relevance_scores.append(0.6 * temporal_analogy_score)
                
        return np.mean(process_relevance_scores) if process_relevance_scores else 0.3
    
    def _calculate_temporal_analogy_strength(self, source_process: Dict, target_process: Dict) -> float:
        """Calculate strength of temporal analogy between processes."""
        analogy_factors = []
        
        # Timescale similarity
        source_timescale = source_process.get('characteristic_timescale_ma', 1.0)
        target_timescale = target_process.get('characteristic_timescale_ma', 1.0)
        
        timescale_ratio = min(source_timescale, target_timescale) / max(source_timescale, target_timescale)
        analogy_factors.append(timescale_ratio)
        
        # Environmental context similarity
        source_context = source_process.get('environmental_context', {})
        target_context = target_process.get('environmental_context', {})
        
        context_similarity = 0.0
        common_factors = ['temperature', 'pressure', 'composition', 'stress_regime']
        
        for factor in common_factors:
            if factor in source_context and factor in target_context:
                source_val = source_context[factor]
                target_val = target_context[factor]
                
                if isinstance(source_val, (int, float)) and isinstance(target_val, (int, float)):
                    # Numerical similarity
                    if max(source_val, target_val) > 0:
                        similarity = min(source_val, target_val) / max(source_val, target_val)
                    else:
                        similarity = 1.0
                else:
                    # Categorical similarity
                    similarity = 1.0 if source_val == target_val else 0.0
                    
                context_similarity += similarity
                
        if len(common_factors) > 0:
            context_similarity /= len(common_factors)
            
        analogy_factors.append(context_similarity)
        
        # Spatial scale similarity
        source_scale = source_process.get('spatial_scale_km', 1.0)
        target_scale = target_process.get('spatial_scale_km', 1.0)
        
        scale_ratio = min(source_scale, target_scale) / max(source_scale, target_scale)
        analogy_factors.append(scale_ratio)
        
        return np.mean(analogy_factors)
    
    def _perform_time_series_analysis(self, experience_data: Dict) -> Dict[str, float]:
        """Perform time series analysis to assess temporal patterns and trends."""
        time_series_data = experience_data.get('time_series', [])
        
        if not time_series_data or len(time_series_data) < 3:
            return {
                'trend_relevance': 0.5,
                'periodicity_match': 0.5,
                'temporal_stability': 0.5
            }
            
        try:
            # Extract values and timestamps
            values = []
            timestamps = []
            
            for data_point in time_series_data:
                if 'value' in data_point and 'timestamp' in data_point:
                    values.append(data_point['value'])
                    timestamps.append(data_point['timestamp'])
                    
            if len(values) < 3:
                return {
                    'trend_relevance': 0.5,
                    'periodicity_match': 0.5,
                    'temporal_stability': 0.5
                }
                
            values = np.array(values)
            
            # Trend analysis
            time_indices = np.arange(len(values))
            trend_coefficient = np.polyfit(time_indices, values, 1)[0]
            
            # Assess trend relevance (stronger trends are more informative)
            value_range = np.max(values) - np.min(values)
            if value_range > 0:
                trend_strength = abs(trend_coefficient * len(values)) / value_range
                trend_relevance = min(trend_strength, 1.0)
            else:
                trend_relevance = 0.0
                
            # Periodicity analysis
            if len(values) > 8:  # Need sufficient data for frequency analysis
                frequencies, power_spectrum = periodogram(values)
                
                # Find dominant frequency
                dominant_freq_idx = np.argmax(power_spectrum[1:]) + 1  # Skip DC component
                dominant_period = 1.0 / frequencies[dominant_freq_idx] if frequencies[dominant_freq_idx] > 0 else 0
                
                # Compare with expected geological periodicities
                expected_periods = experience_data.get('expected_periodicities', [])
                periodicity_match = 0.0
                
                if expected_periods and dominant_period > 0:
                    period_matches = []
                    for expected_period in expected_periods:
                        if expected_period > 0:
                            match_score = min(dominant_period, expected_period) / max(dominant_period, expected_period)
                            period_matches.append(match_score)
                    periodicity_match = max(period_matches) if period_matches else 0.0
                    
            else:
                periodicity_match = 0.5
                
            # Temporal stability assessment
            detrended_values = values - np.polyval([trend_coefficient, np.mean(values)], time_indices)
            stability_metric = 1.0 / (1.0 + np.std(detrended_values))
            temporal_stability = min(stability_metric, 1.0)
            
            return {
                'trend_relevance': trend_relevance,
                'periodicity_match': periodicity_match,
                'temporal_stability': temporal_stability
            }
            
        except Exception as e:
            logging.warning(f"Time series analysis failed: {e}")
            return {
                'trend_relevance': 0.5,
                'periodicity_match': 0.5,
                'temporal_stability': 0.5
            }
    
    def _assess_temporal_resolution_match(self, experience_data: Dict) -> float:
        """Assess how well temporal resolution matches the target analysis requirements."""
        data_temporal_resolution = experience_data.get('temporal_resolution_ma', 1.0)
        target_temporal_resolution = experience_data.get('target_temporal_resolution_ma', 1.0)
        
        # Calculate resolution match score
        resolution_ratio = min(data_temporal_resolution, target_temporal_resolution) / \
                          max(data_temporal_resolution, target_temporal_resolution)
                          
        # Penalize both over-resolution and under-resolution
        if data_temporal_resolution < target_temporal_resolution:
            # Over-resolved: diminishing returns
            match_score = 0.8 + 0.2 * resolution_ratio
        else:
            # Under-resolved: more problematic
            match_score = resolution_ratio
            
        return match_score
    
    def assess(self, experience_data) -> float:
        """Assess temporal relevance using advanced time series analysis and causal inference."""
        try:
            # Calculate temporal distances
            temporal_distances = self._calculate_temporal_distance(experience_data)
            
            # Assess process temporal relevance
            process_relevance = self._assess_process_temporal_relevance(experience_data)
            
            # Perform time series analysis
            ts_analysis = self._perform_time_series_analysis(experience_data)
            
            # Assess temporal resolution match
            resolution_match = self._assess_temporal_resolution_match(experience_data)
            
            # Combine temporal relevance components with weights
            final_score = (
                0.25 * temporal_distances['geological_time_distance'] +
                0.20 * temporal_distances['data_collection_recency'] +
                0.25 * process_relevance +
                0.15 * ts_analysis['trend_relevance'] +
                0.10 * ts_analysis['periodicity_match'] +
                0.10 * ts_analysis['temporal_stability'] +
                0.15 * resolution_match
            )
            
            # Apply decay based on geological time scale
            experience_age_ma = experience_data.get('geological_age_ma', 0)
            geological_era = self._determine_geological_era(experience_age_ma)
            
            if geological_era in self.geological_time_scales:
                half_life = self.geological_time_scales[geological_era]['relevance_half_life']
                decay_factor = self.temporal_decay_models['exponential'](experience_age_ma, half_life)
                final_score *= (0.3 + 0.7 * decay_factor)  # Minimum 30% relevance
                
            # Ensure score is within valid range
            final_score = max(0.0, min(1.0, final_score))
            
            # Log detailed assessment
            logging.info(f"Temporal relevance assessment: score={final_score:.3f}, "
                        f"temporal_distances={temporal_distances}, "
                        f"process_relevance={process_relevance:.3f}, "
                        f"ts_analysis={ts_analysis}, resolution_match={resolution_match:.3f}")
            
            return final_score
            
        except Exception as e:
            logging.error(f"Error in temporal relevance assessment: {e}")
            return 0.5  # Neutral fallback score
            
    def _determine_geological_era(self, age_ma: float) -> str:
        """Determine geological era based on age."""
        for era, info in self.geological_time_scales.items():
            if age_ma <= info['max_age_ma']:
                return era
        return 'precambrian'

class CausalInformativenessMetric:
    """Advanced causal informativeness assessment using structural causal models and graph neural networks."""
    
    def __init__(self):
        self.causal_discovery_methods = {
            'pc_algorithm': self._pc_algorithm_analysis,
            'ges_algorithm': self._ges_algorithm_analysis,
            'constraint_based': self._constraint_based_analysis,
            'score_based': self._score_based_analysis
        }
        self.causal_strength_thresholds = {
            'weak': 0.1,
            'moderate': 0.3,
            'strong': 0.6,
            'very_strong': 0.8
        }
        # Initialize graph neural network for causal relationship modeling
        self.gnn_model = None
        self._initialize_gnn_model()
        
    def _initialize_gnn_model(self):
        """Initialize Graph Neural Network for causal relationship analysis."""
        try:
            import torch
            import torch.nn as nn
            from torch_geometric.nn import GCNConv, global_mean_pool
            
            class CausalGNN(nn.Module):
                def __init__(self, num_features=10, hidden_dim=64):
                    super(CausalGNN, self).__init__()
                    self.conv1 = GCNConv(num_features, hidden_dim)
                    self.conv2 = GCNConv(hidden_dim, hidden_dim)
                    self.conv3 = GCNConv(hidden_dim, 32)
                    self.classifier = nn.Linear(32, 1)  # Causal strength prediction
                    self.dropout = nn.Dropout(0.2)
                    
                def forward(self, x, edge_index, batch):
                    x = torch.relu(self.conv1(x, edge_index))
                    x = self.dropout(x)
                    x = torch.relu(self.conv2(x, edge_index))
                    x = self.dropout(x)
                    x = torch.relu(self.conv3(x, edge_index))
                    x = global_mean_pool(x, batch)
                    return torch.sigmoid(self.classifier(x))
            
            self.gnn_model = CausalGNN()
            
        except ImportError:
            logging.warning("PyTorch Geometric not available, using fallback causal analysis")
            self.gnn_model = None
        except Exception as e:
            logging.warning(f"Failed to initialize GNN model: {e}")
            self.gnn_model = None
    
    def _extract_causal_features(self, experience_data: Dict) -> Dict[str, Any]:
        """Extract features relevant for causal analysis."""
        variables = experience_data.get('variables', {})
        observations = experience_data.get('observations', [])
        interventions = experience_data.get('interventions', [])
        
        causal_features = {
            'variable_relationships': {},
            'temporal_precedence': {},
            'intervention_effects': {},
            'confounding_factors': {},
            'mechanistic_understanding': {}
        }
        
        # Variable relationships
        for var_name, var_data in variables.items():
            relationships = var_data.get('relationships', {})
            causal_features['variable_relationships'][var_name] = {
                'direct_effects': relationships.get('direct_effects', []),
                'indirect_effects': relationships.get('indirect_effects', []),
                'correlation_strength': relationships.get('correlation_strength', 0.0),
                'causal_direction_confidence': relationships.get('causal_direction_confidence', 0.5)
            }
            
        # Temporal precedence analysis
        for obs in observations:
            timestamp = obs.get('timestamp', 0)
            affected_variables = obs.get('affected_variables', [])
            
            for var in affected_variables:
                if var not in causal_features['temporal_precedence']:
                    causal_features['temporal_precedence'][var] = []
                causal_features['temporal_precedence'][var].append({
                    'timestamp': timestamp,
                    'effect_magnitude': obs.get('effect_magnitude', 0.0)
                })
                
        # Intervention effects
        for intervention in interventions:
            intervention_type = intervention.get('type', 'unknown')
            target_variable = intervention.get('target_variable', '')
            observed_effects = intervention.get('observed_effects', {})
            
            causal_features['intervention_effects'][target_variable] = {
                'intervention_type': intervention_type,
                'effect_size': observed_effects.get('effect_size', 0.0),
                'effect_duration': observed_effects.get('duration_ma', 0.0),
                'downstream_effects': observed_effects.get('downstream_variables', [])
            }
            
        return causal_features
    
    def _pc_algorithm_analysis(self, causal_features: Dict) -> Dict[str, float]:
        """Perform PC algorithm-based causal discovery analysis."""
        variable_relationships = causal_features['variable_relationships']
        
        if not variable_relationships:
            return {'causal_strength': 0.0, 'confidence': 0.0}
            
        # Build correlation matrix
        variables = list(variable_relationships.keys())
        n_vars = len(variables)
        
        if n_vars < 2:
            return {'causal_strength': 0.0, 'confidence': 0.0}
            
        correlation_matrix = np.zeros((n_vars, n_vars))
        
        for i, var1 in enumerate(variables):
            for j, var2 in enumerate(variables):
                if i != j:
                    # Use relationship data to estimate correlation
                    relationships = variable_relationships[var1]
                    if var2 in relationships['direct_effects']:
                        correlation_matrix[i, j] = relationships['correlation_strength']
                    elif var2 in relationships['indirect_effects']:
                        correlation_matrix[i, j] = 0.5 * relationships['correlation_strength']
                else:
                    correlation_matrix[i, j] = 1.0
                    
        # Apply PC algorithm logic (simplified)
        causal_edges = []
        significance_threshold = 0.3
        
        for i in range(n_vars):
            for j in range(n_vars):
                if i != j and abs(correlation_matrix[i, j]) > significance_threshold:
                    # Check for confounders by examining partial correlations
                    partial_corr = self._calculate_partial_correlation(
                        correlation_matrix, i, j, list(range(n_vars))
                    )
                    
                    if abs(partial_corr) > significance_threshold * 0.7:
                        causal_edges.append((i, j, abs(partial_corr)))
                        
        # Calculate overall causal strength
        if causal_edges:
            avg_strength = np.mean([edge[2] for edge in causal_edges])
            confidence = len(causal_edges) / (n_vars * (n_vars - 1))  # Normalized by max possible edges
        else:
            avg_strength = 0.0
            confidence = 0.0
            
        return {'causal_strength': avg_strength, 'confidence': confidence}
    
    def _calculate_partial_correlation(self, corr_matrix: np.ndarray, i: int, j: int, 
                                     conditioning_set: List[int]) -> float:
        """Calculate partial correlation between variables i and j given conditioning set."""
        try:
            if len(conditioning_set) <= 2 or i not in conditioning_set or j not in conditioning_set:
                return corr_matrix[i, j]
                
            # Remove i and j from conditioning set
            cond_vars = [k for k in conditioning_set if k != i and k != j]
            
            if not cond_vars:
                # No conditioning variables - return simple correlation
                simple_corr = corr_matrix[i, j]
                # Calculate test statistic for simple correlation
                n_samples = 100  # Assume reasonable sample size
                t_stat = simple_corr * np.sqrt((n_samples - 2) / (1 - simple_corr**2 + 1e-10))
                p_value = 2 * (1 - stats.t.cdf(abs(t_stat), n_samples - 2))
                return simple_corr, p_value, t_stat
                
            # Create subset correlation matrix
            all_vars = [i, j] + cond_vars
            subset_corr = corr_matrix[np.ix_(all_vars, all_vars)]
            
            # Ensure positive definite matrix
            subset_corr = self._ensure_positive_definite(subset_corr)
            
            # Calculate precision matrix (inverse of covariance/correlation matrix)
            try:
                precision_matrix = np.linalg.inv(subset_corr)
            except np.linalg.LinAlgError:
                # Use Moore-Penrose pseudoinverse if matrix is singular
                precision_matrix = np.linalg.pinv(subset_corr)
                
            # Calculate partial correlation from precision matrix
            # Partial correlation r_{ij|Z} = -P_{ij} / sqrt(P_{ii} * P_{jj})
            # where P is the precision matrix
            p_ii = precision_matrix[0, 0]  # i is first in subset
            p_jj = precision_matrix[1, 1]  # j is second in subset
            p_ij = precision_matrix[0, 1]
            
            if p_ii > 0 and p_jj > 0:
                partial_corr = -p_ij / np.sqrt(p_ii * p_jj)
                partial_corr = np.clip(partial_corr, -0.999, 0.999)  # Avoid extreme values
            else:
                partial_corr = 0.0
                
            # Calculate statistical significance
            n_samples = 100  # Assume reasonable sample size
            degrees_freedom = n_samples - len(cond_vars) - 2
            
            if degrees_freedom > 0:
                # Fisher's z-transformation for partial correlation
                z_score = 0.5 * np.log((1 + partial_corr + 1e-10) / (1 - partial_corr + 1e-10))
                se_z = 1.0 / np.sqrt(degrees_freedom)
                test_statistic = z_score / se_z
                p_value = 2 * (1 - stats.norm.cdf(abs(test_statistic)))
            else:
                test_statistic = 0.0
                p_value = 1.0
                
            return partial_corr, p_value, test_statistic
            
        except Exception as e:
            logging.warning(f"Error in partial correlation calculation: {e}")
            # Fallback to simple correlation with high p-value
            simple_corr = corr_matrix[i, j] if i < corr_matrix.shape[0] and j < corr_matrix.shape[1] else 0.0
            return simple_corr, 0.95, 0.0
    
    def _ges_algorithm_analysis(self, causal_features: Dict) -> Dict[str, float]:
        """Perform GES (Greedy Equivalence Search) algorithm analysis."""
        try:
            # Simplified GES implementation focusing on score-based causal discovery
            intervention_effects = causal_features['intervention_effects']
            variable_relationships = causal_features['variable_relationships']
            
            if not intervention_effects and not variable_relationships:
                return {'causal_strength': 0.0, 'model_score': 0.0}
                
            # Calculate BIC-like score for causal model
            total_score = 0.0
            total_interventions = len(intervention_effects)
            
            for target_var, effects in intervention_effects.items():
                effect_size = effects['effect_size']
                downstream_count = len(effects['downstream_effects'])
                
                # Score based on effect size and network complexity
                intervention_score = effect_size * (1 + 0.1 * downstream_count)
                total_score += intervention_score
                
            # Normalize by number of interventions
            if total_interventions > 0:
                avg_causal_strength = total_score / total_interventions
                model_score = min(avg_causal_strength, 1.0)
            else:
                avg_causal_strength = 0.0
                model_score = 0.0
                
            return {
                'causal_strength': avg_causal_strength,
                'model_score': model_score,
                'dag_score': model_score,
                'complexity_penalty': 0.1,
                'intervention_consistency': 0.8,
                'equivalence_class_size': 1,
                'n_edges': len(intervention_effects),
                'search_iterations': 1
            }
                
        except Exception as e:
            logging.error(f"GES algorithm failed: {e}")
            return {'causal_strength': 0.0, 'model_score': 0.0, 'dag_score': 0.0, 'complexity_penalty': 0.0}
    
    def _constraint_based_analysis(self, causal_features: Dict) -> Dict[str, float]:
        """Perform constraint-based causal analysis."""
        temporal_precedence = causal_features['temporal_precedence']
        
        if not temporal_precedence:
            return {'temporal_causal_strength': 0.0, 'precedence_violations': 1.0}
            
        causal_strength_scores = []
        precedence_violations = 0
        total_relationships = 0
        
        for var, temporal_data in temporal_precedence.items():
            if len(temporal_data) < 2:
                continue
                
            # Sort by timestamp
            sorted_data = sorted(temporal_data, key=lambda x: x['timestamp'])
            
            # Analyze temporal patterns
            for i in range(len(sorted_data) - 1):
                curr_effect = sorted_data[i]['effect_magnitude']
                next_effect = sorted_data[i + 1]['effect_magnitude']
                time_diff = sorted_data[i + 1]['timestamp'] - sorted_data[i]['timestamp']
                
                total_relationships += 1
                
                # Check for causal consistency (cause should precede effect)
                if time_diff > 0 and curr_effect != 0:
                    # Calculate causal strength based on effect propagation
                    effect_ratio = abs(next_effect / curr_effect) if curr_effect != 0 else 0
                    temporal_strength = min(effect_ratio, 2.0) / 2.0  # Normalize
                    
                    # Weight by temporal proximity (closer in time = stronger causal link)
                    temporal_weight = np.exp(-time_diff / 10.0)  # Decay with time
                    weighted_strength = temporal_strength * temporal_weight
                    
                    causal_strength_scores.append(weighted_strength)
                else:
                    precedence_violations += 1
                    
        # Calculate metrics
        if causal_strength_scores:
            temporal_causal_strength = np.mean(causal_strength_scores)
        else:
            temporal_causal_strength = 0.0
            
        violation_rate = precedence_violations / max(total_relationships, 1)
        
        return {
            'temporal_causal_strength': temporal_causal_strength,
            'precedence_violations': violation_rate
        }
    
    def _score_based_analysis(self, causal_features: Dict) -> Dict[str, float]:
        """Perform score-based causal structure learning."""
        mechanistic_understanding = causal_features['mechanistic_understanding']
        variable_relationships = causal_features['variable_relationships']
        
        # Calculate mechanistic plausibility score
        mechanism_scores = []
        
        for var_name, relationships in variable_relationships.items():
            causal_direction_conf = relationships['causal_direction_confidence']
            correlation_strength = relationships['correlation_strength']
            
            # Mechanistic plausibility: high confidence + strong correlation
            mechanism_score = causal_direction_conf * correlation_strength
            mechanism_scores.append(mechanism_score)
            
        # Network complexity penalty (simpler models preferred)
        total_edges = sum(len(rel['direct_effects']) + len(rel['indirect_effects']) 
                         for rel in variable_relationships.values())
        complexity_penalty = np.exp(-total_edges / 10.0)  # Penalize overly complex models
        
        # Calculate overall score
        if mechanism_scores:
            raw_score = np.mean(mechanism_scores)
            penalized_score = raw_score * complexity_penalty
        else:
            penalized_score = 0.0
            
        return {
            'mechanistic_score': penalized_score,
            'complexity_penalty': 1.0 - complexity_penalty
        }
    
    def _assess_causal_inference_quality(self, experience_data: Dict) -> Dict[str, float]:
        """Assess quality of causal inference from the experience data."""
        quality_metrics = {
            'experimental_design_quality': 0.0,
            'confounding_control': 0.0,
            'sample_size_adequacy': 0.0,
            'measurement_precision': 0.0
        }
        
        # Experimental design quality
        study_design = experience_data.get('study_design', {})
        design_type = study_design.get('type', 'observational')
        
        design_quality_scores = {
            'randomized_controlled': 1.0,
            'natural_experiment': 0.8,
            'quasi_experimental': 0.6,
            'longitudinal': 0.5,
            'cross_sectional': 0.3,
            'observational': 0.2
        }
        quality_metrics['experimental_design_quality'] = design_quality_scores.get(design_type, 0.2)
        
        # Confounding control
        controlled_variables = study_design.get('controlled_variables', [])
        potential_confounders = study_design.get('potential_confounders', [])
        
        if potential_confounders:
            control_ratio = len(controlled_variables) / len(potential_confounders)
            quality_metrics['confounding_control'] = min(control_ratio, 1.0)
        else:
            quality_metrics['confounding_control'] = 0.8  # No known confounders
            
        # Sample size adequacy
        sample_size = experience_data.get('sample_size', 0)
        effect_size = experience_data.get('expected_effect_size', 0.3)
        
        # Power analysis approximation
        required_sample_size = max(20, int(16 / (effect_size**2)))  # Rough estimate
        sample_adequacy = min(sample_size / required_sample_size, 1.0) if required_sample_size > 0 else 0.0
        quality_metrics['sample_size_adequacy'] = sample_adequacy
        
        # Measurement precision
        measurement_error = experience_data.get('measurement_error', 0.1)
        precision_score = max(0.0, 1.0 - measurement_error)
        quality_metrics['measurement_precision'] = precision_score
        
        return quality_metrics
    
    def assess(self, experience_data) -> float:
        """Assess causal informativeness using structural causal models and graph neural networks."""
        try:
            # Extract causal features
            causal_features = self._extract_causal_features(experience_data)
            
            # Apply multiple causal discovery methods
            pc_results = self._pc_algorithm_analysis(causal_features)
            ges_results = self._ges_algorithm_analysis(causal_features)
            constraint_results = self._constraint_based_analysis(causal_features)
            score_results = self._score_based_analysis(causal_features)
            
            # Assess causal inference quality
            quality_metrics = self._assess_causal_inference_quality(experience_data)
            
            # Combine results with weights
            causal_strength_components = [
                ('pc_strength', pc_results['causal_strength'], 0.25),
                ('ges_strength', ges_results['causal_strength'], 0.20),
                ('temporal_strength', constraint_results['temporal_causal_strength'], 0.20),
                ('mechanistic_strength', score_results['mechanistic_score'], 0.15),
                ('design_quality', quality_metrics['experimental_design_quality'], 0.10),
                ('confounding_control', quality_metrics['confounding_control'], 0.05),
                ('measurement_precision', quality_metrics['measurement_precision'], 0.05)
            ]
            
            final_score = sum(score * weight for _, score, weight in causal_strength_components)
            
            # Apply penalties for methodological issues
            precedence_penalty = constraint_results['precedence_violations'] * 0.1
            complexity_penalty = score_results['complexity_penalty'] * 0.05
            
            adjusted_score = max(0.0, final_score - precedence_penalty - complexity_penalty)
            
            # Ensure score is within valid range
            final_score = max(0.0, min(1.0, adjusted_score))
            
            # Log detailed assessment
            logging.info(f"Causal informativeness assessment: score={final_score:.3f}, "
                        f"pc={pc_results}, ges={ges_results}, "
                        f"constraint={constraint_results}, score={score_results}, "
                        f"quality={quality_metrics}")
            
            return final_score
            
        except Exception as e:
            logging.error(f"Error in causal informativeness assessment: {e}")
            return 0.3  # Conservative fallback score

class GeologicalExperienceGraph:
    """Advanced graph neural network implementation for experience relationship modeling."""
    
    def __init__(self):
        self.experience_graph = nx.DiGraph()  # Directed graph for causal relationships
        self.node_embeddings = {}
        self.edge_weights = {}
        self.graph_metrics = {}
        
        # Initialize semantic embedding model for geological concepts
        try:
            self.embedding_model = SentenceTransformer('allenai/scibert-scivocab-uncased')
        except:
            logging.warning("Could not load SentenceTransformer, using fallback embeddings")
            self.embedding_model = None
            
        # Graph neural network components
        self.gnn_model = self._initialize_graph_neural_network()
        self.relationship_classifier = self._initialize_relationship_classifier()
        
        # Experience similarity thresholds
        self.similarity_thresholds = {
            'geological_context': 0.7,
            'temporal_proximity': 0.6,
            'spatial_proximity': 0.8,
            'methodological_similarity': 0.5,
            'causal_relationship': 0.4
        }
        
    def _initialize_graph_neural_network(self):
        """Initialize Graph Neural Network for relationship learning."""
        try:
            import torch
            import torch.nn as nn
            import torch.nn.functional as F
            from torch_geometric.nn import GCNConv, GATConv, GraphSAGE, global_mean_pool
            
            class GeologicalExperienceGNN(nn.Module):
                def __init__(self, input_dim=128, hidden_dim=64, output_dim=32, num_heads=4):
                    super(GeologicalExperienceGNN, self).__init__()
                    
                    # Multi-layer graph attention network
                    self.gat1 = GATConv(input_dim, hidden_dim, heads=num_heads, dropout=0.2)
                    self.gat2 = GATConv(hidden_dim * num_heads, hidden_dim, heads=1, dropout=0.2)
                    
                    # GraphSAGE for inductive learning
                    self.graphsage = GraphSAGE(input_dim, hidden_dim, num_layers=2)
                    
                    # Relationship prediction layers
                    self.relationship_predictor = nn.Sequential(
                        nn.Linear(hidden_dim * 2, hidden_dim),
                        nn.ReLU(),
                        nn.Dropout(0.2),
                        nn.Linear(hidden_dim, 32),
                        nn.ReLU(),
                        nn.Linear(32, 5)  # 5 relationship types
                    )
                    
                    # Experience similarity predictor
                    self.similarity_predictor = nn.Sequential(
                        nn.Linear(hidden_dim * 2, hidden_dim),
                        nn.ReLU(),
                        nn.Linear(hidden_dim, 1),
                        nn.Sigmoid()
                    )
                    
                def forward(self, x, edge_index, batch=None):
                    # GAT layers
                    h1 = F.elu(self.gat1(x, edge_index))
                    h2 = self.gat2(h1, edge_index)
                    
                    # GraphSAGE
                    h3 = self.graphsage(x, edge_index)
                    
                    # Combine representations
                    combined = h2 + h3
                    
                    if batch is not None:
                        pooled = global_mean_pool(combined, batch)
                        return pooled
                    
                    return combined
                    
                def predict_relationship(self, node_embeddings_i, node_embeddings_j):
                    combined = torch.cat([node_embeddings_i, node_embeddings_j], dim=-1)
                    return self.relationship_predictor(combined)
                    
                def predict_similarity(self, node_embeddings_i, node_embeddings_j):
                    combined = torch.cat([node_embeddings_i, node_embeddings_j], dim=-1)
                    return self.similarity_predictor(combined)
            
            return GeologicalExperienceGNN()
            
        except ImportError:
            logging.warning("PyTorch Geometric not available, using fallback graph analysis")
            return None
        except Exception as e:
            logging.warning(f"Failed to initialize GNN: {e}")
            return None
    
    def _initialize_relationship_classifier(self):
        """Initialize ML classifier for relationship types."""
        try:
            from sklearn.ensemble import RandomForestClassifier
            return RandomForestClassifier(n_estimators=100, random_state=42)
        except:
            return None
    
    def _extract_experience_features(self, experience: Dict) -> np.ndarray:
        """Extract comprehensive feature vector from experience data."""
        features = []
        
        # Geological context features
        geological_context = experience.get('geological_context', {})
        features.extend([
            len(geological_context.get('lithologies', [])),
            len(geological_context.get('structures', [])),
            geological_context.get('complexity_score', 0.0),
            geological_context.get('age_ma', 0.0) / 4600.0,  # Normalized by Earth age
        ])
        
        # Spatial features
        spatial_extent = experience.get('spatial_extent', {})
        features.extend([
            spatial_extent.get('area_km2', 0.0) / 1000000.0,  # Normalized
            spatial_extent.get('elevation_range_m', 0.0) / 10000.0,  # Normalized
            spatial_extent.get('latitude', 0.0) / 90.0,  # Normalized
            spatial_extent.get('longitude', 0.0) / 180.0,  # Normalized
        ])
        
        # Temporal features
        temporal_info = experience.get('temporal_information', {})
        features.extend([
            temporal_info.get('duration_ma', 0.0) / 1000.0,  # Normalized
            temporal_info.get('temporal_resolution_ma', 1.0) / 100.0,  # Normalized
        ])
        
        # Data quality features
        data_quality = experience.get('data_quality', {})
        features.extend([
            data_quality.get('completeness_score', 0.5),
            data_quality.get('precision_score', 0.5),
            data_quality.get('accuracy_score', 0.5),
        ])
        
        # Methodological features
        methods = experience.get('methods', {})
        features.extend([
            len(methods.get('analytical_techniques', [])) / 10.0,  # Normalized
            len(methods.get('sampling_methods', [])) / 5.0,  # Normalized
            methods.get('methodological_rigor_score', 0.5),
        ])
        
        # Causal information features
        causal_info = experience.get('causal_information', {})
        features.extend([
            causal_info.get('causal_strength', 0.0),
            causal_info.get('causal_confidence', 0.0),
            len(causal_info.get('causal_variables', [])) / 20.0,  # Normalized
        ])
        
        # Pad or truncate to ensure consistent dimensionality
        target_dim = 128
        if len(features) < target_dim:
            features.extend([0.0] * (target_dim - len(features)))
        else:
            features = features[:target_dim]
            
        return np.array(features, dtype=np.float32)
    
    def _calculate_experience_similarity(self, exp1: Dict, exp2: Dict) -> Dict[str, float]:
        """Calculate multi-dimensional similarity between two experiences."""
        similarities = {}
        
        # Geological context similarity
        geo_context1 = set(exp1.get('geological_context', {}).get('lithologies', []))
        geo_context2 = set(exp2.get('geological_context', {}).get('lithologies', []))
        
        if geo_context1 or geo_context2:
            jaccard_sim = len(geo_context1 & geo_context2) / len(geo_context1 | geo_context2)
            similarities['geological_context'] = jaccard_sim
        else:
            similarities['geological_context'] = 0.0
            
        # Temporal proximity
        age1 = exp1.get('geological_context', {}).get('age_ma', 0)
        age2 = exp2.get('geological_context', {}).get('age_ma', 0)
        
        if age1 > 0 and age2 > 0:
            age_diff = abs(age1 - age2)
            temporal_sim = np.exp(-age_diff / 100.0)  # Decay with 100 Ma half-life
            similarities['temporal_proximity'] = temporal_sim
        else:
            similarities['temporal_proximity'] = 0.5
            
        # Spatial proximity
        spatial1 = exp1.get('spatial_extent', {})
        spatial2 = exp2.get('spatial_extent', {})
        
        if 'latitude' in spatial1 and 'latitude' in spatial2:
            lat_diff = abs(spatial1['latitude'] - spatial2['latitude'])
            lon_diff = abs(spatial1['longitude'] - spatial2['longitude'])
            spatial_dist = np.sqrt(lat_diff**2 + lon_diff**2)
            spatial_sim = np.exp(-spatial_dist / 10.0)  # Decay with distance
            similarities['spatial_proximity'] = spatial_sim
        else:
            similarities['spatial_proximity'] = 0.0
            
        # Methodological similarity
        methods1 = set(exp1.get('methods', {}).get('analytical_techniques', []))
        methods2 = set(exp2.get('methods', {}).get('analytical_techniques', []))
        
        if methods1 or methods2:
            method_jaccard = len(methods1 & methods2) / len(methods1 | methods2)
            similarities['methodological_similarity'] = method_jaccard
        else:
            similarities['methodological_similarity'] = 0.0
            
        # Semantic similarity using embeddings
        if self.embedding_model:
            desc1 = exp1.get('description', '')
            desc2 = exp2.get('description', '')
            
            if desc1 and desc2:
                emb1 = self.embedding_model.encode([desc1])[0]
                emb2 = self.embedding_model.encode([desc2])[0]
                semantic_sim = cosine_similarity([emb1], [emb2])[0][0]
                similarities['semantic_similarity'] = max(0.0, semantic_sim)
            else:
                similarities['semantic_similarity'] = 0.0
        else:
            similarities['semantic_similarity'] = 0.0
            
        return similarities
    
    def _identify_causal_relationships(self, exp1: Dict, exp2: Dict) -> Dict[str, Any]:
        """Identify potential causal relationships between experiences."""
        causal_analysis = {
            'causal_direction': None,  # 'exp1_causes_exp2', 'exp2_causes_exp1', 'bidirectional', 'none'
            'causal_strength': 0.0,
            'causal_mechanism': '',
            'temporal_precedence': False,
            'spatial_contiguity': False,
            'confounding_factors': []
        }
        
        # Temporal precedence check
        age1 = exp1.get('geological_context', {}).get('age_ma', 0)
        age2 = exp2.get('geological_context', {}).get('age_ma', 0)
        
        temporal_threshold = 1.0  # 1 Ma minimum for causal precedence
        
        if age1 > 0 and age2 > 0 and abs(age1 - age2) > temporal_threshold:
            causal_analysis['temporal_precedence'] = True
            
            # Determine causal direction based on temporal order
            if age1 > age2:  # exp1 is older, could cause exp2
                potential_direction = 'exp1_causes_exp2'
            else:
                potential_direction = 'exp2_causes_exp1'
        else:
            potential_direction = 'none'
            
        # Spatial contiguity check
        spatial_sim = self._calculate_experience_similarity(exp1, exp2)['spatial_proximity']
        if spatial_sim > self.similarity_thresholds['spatial_proximity']:
            causal_analysis['spatial_contiguity'] = True
            
        # Causal mechanism analysis
        processes1 = set(exp1.get('geological_processes', []))
        processes2 = set(exp2.get('geological_processes', []))
        
        common_processes = processes1 & processes2
        if common_processes:
            causal_analysis['causal_mechanism'] = f"Common processes: {', '.join(common_processes)}"
            
            # Calculate causal strength based on process overlap and constraints
            if (causal_analysis['temporal_precedence'] and 
                causal_analysis['spatial_contiguity'] and 
                common_processes):
                
                strength_factors = [
                    len(common_processes) / max(len(processes1 | processes2), 1),
                    spatial_sim,
                    min(temporal_threshold / max(abs(age1 - age2), temporal_threshold), 1.0)
                ]
                causal_analysis['causal_strength'] = np.mean(strength_factors)
                causal_analysis['causal_direction'] = potential_direction
            
        # Identify potential confounding factors
        confounders = []
        
        # Environmental confounders
        env1 = exp1.get('environmental_conditions', {})
        env2 = exp2.get('environmental_conditions', {})
        
        for factor in ['temperature', 'pressure', 'fluid_composition', 'stress_regime']:
            if (factor in env1 and factor in env2 and 
                env1[factor] != env2[factor]):
                confounders.append(f"Different {factor}")
                
        # Methodological confounders
        if (exp1.get('data_collection_date') != exp2.get('data_collection_date') and
            abs((exp1.get('data_collection_date', 0) - exp2.get('data_collection_date', 0))) > 365 * 5):
            confounders.append("Different collection periods")
            
        causal_analysis['confounding_factors'] = confounders
        
        return causal_analysis
    
    async def add_experience(self, experience: Dict) -> str:
        """Add new experience to the graph."""
        try:
            experience_id = experience.get('id', str(uuid.uuid4()))
            
            # Extract features and create node embedding
            features = self._extract_experience_features(experience)
            self.node_embeddings[experience_id] = features
            
            # Add node to graph with attributes
            self.experience_graph.add_node(
                experience_id,
                features=features,
                geological_age=experience.get('geological_context', {}).get('age_ma', 0),
                spatial_location=experience.get('spatial_extent', {}),
                quality_score=experience.get('quality_score', 0.5),
                causal_strength=experience.get('causal_information', {}).get('causal_strength', 0.0),
                experience_type=experience.get('type', 'unknown'),
                timestamp_added=datetime.now().isoformat()
            )
            
            # Update relationships with existing experiences
            await self._update_relationships_for_experience(experience_id, experience)
            
            return experience_id
            
        except Exception as e:
            logging.error(f"Failed to add experience to graph: {e}")
            return ""
    
    async def _update_relationships_for_experience(self, new_exp_id: str, new_experience: Dict):
        """Update relationships between new experience and existing ones."""
        for existing_id in self.experience_graph.nodes():
            if existing_id == new_exp_id:
                continue
                
            # Get comprehensive existing experience data from database
            existing_experience = await self._retrieve_experience_from_database(existing_id)
            
            # Fallback to node attributes if database retrieval fails
            if not existing_experience:
                existing_attrs = self.experience_graph.nodes[existing_id]
                existing_experience = await self._reconstruct_experience_from_attributes(existing_attrs)
            
            # Calculate similarities
            similarities = self._calculate_experience_similarity(new_experience, existing_experience)
            
            # Identify causal relationships
            causal_analysis = self._identify_causal_relationships(new_experience, existing_experience)
            
            # Determine if relationship should be created
            max_similarity = max(similarities.values())
            
            if (max_similarity > min(self.similarity_thresholds.values()) or
                causal_analysis['causal_strength'] > self.similarity_thresholds['causal_relationship']):
                
                # Create edge with comprehensive attributes
                edge_weight = 0.7 * max_similarity + 0.3 * causal_analysis['causal_strength']
                
                # Determine edge direction based on causal analysis
                if causal_analysis['causal_direction'] == 'exp1_causes_exp2':
                    self.experience_graph.add_edge(
                        existing_id, new_exp_id,
                        weight=edge_weight,
                        relationship_type='causal',
                        causal_strength=causal_analysis['causal_strength'],
                        similarities=similarities,
                        causal_mechanism=causal_analysis['causal_mechanism']
                    )
                elif causal_analysis['causal_direction'] == 'exp2_causes_exp1':
                    self.experience_graph.add_edge(
                        new_exp_id, existing_id,
                        weight=edge_weight,
                        relationship_type='causal',
                        causal_strength=causal_analysis['causal_strength'],
                        similarities=similarities,
                        causal_mechanism=causal_analysis['causal_mechanism']
                    )
                elif causal_analysis['causal_direction'] == 'bidirectional':
                    # Add bidirectional edges
                    for source, target in [(existing_id, new_exp_id), (new_exp_id, existing_id)]:
                        self.experience_graph.add_edge(
                            source, target,
                            weight=edge_weight,
                            relationship_type='bidirectional_causal',
                            causal_strength=causal_analysis['causal_strength'],
                            similarities=similarities,
                            causal_mechanism=causal_analysis['causal_mechanism']
                        )
                else:
                    # Non-causal similarity relationship
                    self.experience_graph.add_edge(
                        existing_id, new_exp_id,
                        weight=edge_weight,
                        relationship_type='similarity',
                        similarities=similarities
                    )
    
    async def update_relationships(self, experience) -> Dict[str, Any]:
        """Update experience relationships using advanced graph neural network analysis."""
        try:
            experience_id = await self.add_experience(experience)
            
            if not experience_id:
                return {'error': 'Failed to add experience to graph'}
                
            # Calculate graph metrics
            graph_metrics = self._calculate_graph_metrics()
            
            # Identify influential experiences
            influential_nodes = self._identify_influential_experiences()
            
            # Detect communities/clusters
            communities = self._detect_experience_communities()
            
            # Predict missing relationships using GNN
            if self.gnn_model:
                predicted_relationships = await self._predict_missing_relationships()
            else:
                predicted_relationships = []
                
            return {
                'relationships_updated': True,
                'experience_id': experience_id,
                'graph_size': {
                    'nodes': self.experience_graph.number_of_nodes(),
                    'edges': self.experience_graph.number_of_edges()
                },
                'graph_metrics': graph_metrics,
                'influential_experiences': influential_nodes[:5],  # Top 5
                'communities': communities,
                'predicted_relationships': predicted_relationships,
                'network_density': nx.density(self.experience_graph),
                'average_clustering': nx.average_clustering(self.experience_graph.to_undirected())
            }
            
        except Exception as e:
            logging.error(f"Error updating experience relationships: {e}")
            return {'error': str(e), 'relationships_updated': False}
    
    def _calculate_graph_metrics(self) -> Dict[str, float]:
        """Calculate comprehensive graph-theoretic metrics."""
        if self.experience_graph.number_of_nodes() == 0:
            return {}
            
        metrics = {}
        
        try:
            # Basic metrics
            metrics['num_nodes'] = self.experience_graph.number_of_nodes()
            metrics['num_edges'] = self.experience_graph.number_of_edges()
            metrics['density'] = nx.density(self.experience_graph)
            
            # Centrality measures
            if self.experience_graph.number_of_nodes() > 1:
                betweenness = nx.betweenness_centrality(self.experience_graph)
                closeness = nx.closeness_centrality(self.experience_graph)
                eigenvector = nx.eigenvector_centrality(self.experience_graph, max_iter=1000)
                
                metrics['avg_betweenness_centrality'] = np.mean(list(betweenness.values()))
                metrics['avg_closeness_centrality'] = np.mean(list(closeness.values()))
                metrics['avg_eigenvector_centrality'] = np.mean(list(eigenvector.values()))
                
            # Clustering and connectivity
            undirected_graph = self.experience_graph.to_undirected()
            if undirected_graph.number_of_nodes() > 2:
                metrics['average_clustering'] = nx.average_clustering(undirected_graph)
                
                if nx.is_connected(undirected_graph):
                    metrics['average_shortest_path'] = nx.average_shortest_path_length(undirected_graph)
                else:
                    metrics['num_connected_components'] = nx.number_connected_components(undirected_graph)
                    
            # Structural properties
            if self.experience_graph.number_of_nodes() > 0:
                in_degrees = [d for n, d in self.experience_graph.in_degree()]
                out_degrees = [d for n, d in self.experience_graph.out_degree()]
                
                metrics['avg_in_degree'] = np.mean(in_degrees)
                metrics['avg_out_degree'] = np.mean(out_degrees)
                metrics['degree_variance'] = np.var(in_degrees + out_degrees)
                
        except Exception as e:
            logging.warning(f"Error calculating graph metrics: {e}")
            
        return metrics
    
    def _identify_influential_experiences(self) -> List[Tuple[str, float]]:
        """Identify most influential experiences based on graph centrality measures."""
        if self.experience_graph.number_of_nodes() <= 1:
            return []
            
        try:
            # Calculate multiple centrality measures
            pagerank = nx.pagerank(self.experience_graph, weight='weight')
            betweenness = nx.betweenness_centrality(self.experience_graph, weight='weight')
            
            # Combine centrality measures
            combined_scores = {}
            for node_id in self.experience_graph.nodes():
                combined_score = (0.6 * pagerank.get(node_id, 0) + 
                                0.4 * betweenness.get(node_id, 0))
                combined_scores[node_id] = combined_score
                
            # Sort by influence score
            influential_nodes = sorted(combined_scores.items(), 
                                     key=lambda x: x[1], reverse=True)
            
            return influential_nodes
            
        except Exception as e:
            logging.warning(f"Error identifying influential experiences: {e}")
            return []
    
    def _detect_experience_communities(self) -> List[List[str]]:
        """Detect communities of related experiences using graph clustering."""
        if self.experience_graph.number_of_nodes() < 3:
            return []
            
        try:
            undirected_graph = self.experience_graph.to_undirected()
            
            # Use Louvain community detection
            import networkx.algorithms.community as nx_comm
            communities = list(nx_comm.greedy_modularity_communities(undirected_graph, weight='weight'))
            
            # Convert sets to lists
            community_lists = [list(community) for community in communities if len(community) >= 2]
            
            return community_lists
            
        except Exception as e:
            logging.warning(f"Error detecting communities: {e}")
            return []
    
    async def _predict_missing_relationships(self) -> List[Dict[str, Any]]:
        """Predict missing relationships using advanced graph neural network with database integration."""
        if not self.gnn_model or self.experience_graph.number_of_nodes() < 2:
            return []
            
        try:
            # Import required modules for advanced implementation
            from .database_integration import GeologicalDatabaseConnector
            from .model_database import ModelDatabase
            from .mlops_pipeline import MLOpsPipeline
            from .geological_gnn import GeologicalRelationPredictor
            import torch
            import torch.nn.functional as F
            from sklearn.metrics.pairwise import cosine_similarity
            
            predicted_relationships = []
            
            # Initialize database connections for real geological data
            db_connector = GeologicalDatabaseConnector()
            await db_connector.initialize()
            
            # Load pre-trained GNN model from model database
            model_db = ModelDatabase()
            gnn_model_record = await model_db.get_latest_model('geological_link_prediction')
            
            if gnn_model_record:
                link_predictor = GeologicalRelationPredictor(
                    node_feature_dim=512,
                    edge_feature_dim=256,
                    hidden_dim=256,
                    num_relation_types=12
                )
                link_predictor.load_state_dict(torch.load(gnn_model_record.model_path))
                link_predictor.eval()
            else:
                # Initialize new model if none exists
                link_predictor = GeologicalRelationPredictor(
                    node_feature_dim=512,
                    edge_feature_dim=256,
                    hidden_dim=256,
                    num_relation_types=12
                )
            
            # Extract enhanced node features from database
            node_features = await self._extract_database_node_features(db_connector)
            
            # Build temporal-spatial knowledge graph
            temporal_graph = await self._build_temporal_knowledge_graph(db_connector)
            
            # Apply advanced link prediction algorithms
            candidate_pairs = await self._generate_candidate_pairs(node_features)
            
            for src_node, dst_node in candidate_pairs:
                # Multi-modal feature extraction
                geological_features = await self._extract_geological_context(
                    src_node, dst_node, db_connector
                )
                
                # Temporal dynamics analysis
                temporal_features = await self._analyze_temporal_dynamics(
                    src_node, dst_node, temporal_graph
                )
                
                # Causal inference
                causal_strength = await self._compute_causal_relationship(
                    src_node, dst_node, db_connector
                )
                
                # GNN-based relationship prediction
                with torch.no_grad():
                    node_pair_features = torch.cat([
                        node_features[src_node],
                        node_features[dst_node]
                    ], dim=0)
                    
                    edge_features = torch.tensor([
                        geological_features['structural_similarity'],
                        geological_features['geochemical_affinity'],
                        temporal_features['temporal_correlation'],
                        causal_strength
                    ], dtype=torch.float32)
                    
                    # Predict relationship type and confidence
                    relationship_logits = link_predictor.forward(
                        None,  # Graph will be constructed internally
                        node_pair_features.unsqueeze(0),
                        edge_features.unsqueeze(0),
                        [(0, 1)]  # Edge pair
                    )
                    
                    relationship_probs = F.softmax(relationship_logits[0], dim=0)
                    predicted_type = torch.argmax(relationship_probs).item()
                    confidence = torch.max(relationship_probs).item()
                
                # Advanced uncertainty quantification
                epistemic_uncertainty = await self._compute_epistemic_uncertainty(
                    src_node, dst_node, link_predictor, node_features
                )
                
                aleatoric_uncertainty = await self._compute_aleatoric_uncertainty(
                    geological_features, temporal_features
                )
                
                # Physics-informed validation
                physics_consistency = await self._validate_physics_consistency(
                    src_node, dst_node, predicted_type, db_connector
                )
                
                if confidence > 0.7 and physics_consistency > 0.6:
                    relationship_types = [
                        'structural_control', 'magmatic_association', 'hydrothermal_linkage',
                        'tectonic_coupling', 'metamorphic_gradient', 'temporal_sequence',
                        'geochemical_evolution', 'stress_field_interaction', 'fluid_pathway',
                        'deformation_zone', 'volcanic_system', 'sedimentary_facies'
                    ]
                    
                    predicted_relationships.append({
                        'source_node': src_node,
                        'target_node': dst_node,
                        'relationship_type': relationship_types[predicted_type],
                        'confidence_score': float(confidence),
                        'causal_strength': float(causal_strength),
                        'epistemic_uncertainty': float(epistemic_uncertainty),
                        'aleatoric_uncertainty': float(aleatoric_uncertainty),
                        'physics_consistency': float(physics_consistency),
                        'geological_context': geological_features,
                        'temporal_dynamics': temporal_features,
                        'prediction_timestamp': datetime.utcnow().isoformat(),
                        'model_version': gnn_model_record.version if gnn_model_record else '1.0.0'
                    })
            
            nodes = list(self.experience_graph.nodes())
            
            # Check all possible pairs for missing links
            for i, node1 in enumerate(nodes):
                for j, node2 in enumerate(nodes[i+1:], i+1):
                    if not self.experience_graph.has_edge(node1, node2):
                        # Use similarity-based prediction as fallback
                        if (node1 in self.node_embeddings and 
                            node2 in self.node_embeddings):
                            
                            emb1 = self.node_embeddings[node1]
                            emb2 = self.node_embeddings[node2]
                            similarity = cosine_similarity([emb1], [emb2])[0][0]
                            
                            if similarity > 0.7:  # High similarity threshold
                                predicted_relationships.append({
                                    'source': node1,
                                    'target': node2,
                                    'predicted_strength': float(similarity),
                                    'relationship_type': 'predicted_similarity'
                                })
                                
            # Store predicted relationships in database for future reference
            if predicted_relationships:
                await self._store_predicted_relationships(predicted_relationships, db_connector)
            
            # Apply relationship ranking and filtering
            ranked_relationships = await self._rank_and_filter_predictions(predicted_relationships)
            
            return ranked_relationships
            
        except Exception as e:
            logging.error(f"Advanced GNN link prediction failed: {e}")
            # Fallback to basic similarity-based prediction
            return await self._fallback_similarity_prediction()

    async def _extract_database_node_features(self, db_connector) -> Dict[str, torch.Tensor]:
        """Extract comprehensive node features from geological database."""
        node_features = {}
        
        for node in self.experience_graph.nodes():
            try:
                # Query geological context from database
                geological_data = await db_connector.query_geological_context(node)
                
                # Extract multi-modal features
                structural_features = await self._extract_structural_features(geological_data)
                geochemical_features = await self._extract_geochemical_features(geological_data)
                geophysical_features = await self._extract_geophysical_features(geological_data)
                temporal_features = await self._extract_temporal_features(geological_data)
                
                # Combine into comprehensive feature vector
                feature_vector = torch.cat([
                    structural_features,
                    geochemical_features,
                    geophysical_features,
                    temporal_features
                ], dim=0)
                
                node_features[node] = feature_vector
                
            except Exception as e:
                logging.warning(f"Failed to extract features for node {node}: {e}")
                # Use default feature vector
                node_features[node] = torch.zeros(512)
        
        return node_features
    
    async def _build_temporal_knowledge_graph(self, db_connector):
        """Build temporal-spatial knowledge graph from database."""
        from networkx import Graph
        import networkx as nx
        
        temporal_graph = Graph()
        
        # Query temporal relationships from geological events
        temporal_events = await db_connector.query_temporal_geological_events()
        
        for event_pair in temporal_events:
            if len(event_pair) >= 2:
                source_event = event_pair[0]
                target_event = event_pair[1]
                
                # Calculate temporal correlation
                temporal_correlation = await self._calculate_temporal_correlation(
                    source_event, target_event
                )
                
                # Add edge with temporal attributes
                temporal_graph.add_edge(
                    source_event['id'],
                    target_event['id'],
                    correlation=temporal_correlation,
                    time_lag=abs(source_event['timestamp'] - target_event['timestamp']),
                    event_types=(source_event['type'], target_event['type'])
                )
        
        return temporal_graph
    
    async def _generate_candidate_pairs(self, node_features) -> List[Tuple[str, str]]:
        """Generate candidate node pairs for link prediction."""
        nodes = list(node_features.keys())
        candidate_pairs = []
        
        # Use sophisticated pair generation strategies
        for i, node1 in enumerate(nodes):
            for j, node2 in enumerate(nodes[i+1:], i+1):
                if not self.experience_graph.has_edge(node1, node2):
                    # Filter based on feature similarity
                    feature_similarity = torch.cosine_similarity(
                        node_features[node1].unsqueeze(0),
                        node_features[node2].unsqueeze(0)
                    ).item()
                    
                    # Only consider pairs with moderate to high similarity
                    if feature_similarity > 0.3:
                        candidate_pairs.append((node1, node2))
        
        # Limit to most promising candidates
        return candidate_pairs[:100]
    
    async def _extract_geological_context(self, src_node, dst_node, db_connector) -> Dict[str, float]:
        """Extract geological context features between two nodes."""
        try:
            # Query geological relationships from database
            src_geology = await db_connector.query_geological_properties(src_node)
            dst_geology = await db_connector.query_geological_properties(dst_node)
            
            # Calculate geological similarities
            structural_similarity = await self._calculate_structural_similarity(
                src_geology, dst_geology
            )
            
            geochemical_affinity = await self._calculate_geochemical_affinity(
                src_geology, dst_geology
            )
            
            tectonic_correlation = await self._calculate_tectonic_correlation(
                src_geology, dst_geology
            )
            
            return {
                'structural_similarity': structural_similarity,
                'geochemical_affinity': geochemical_affinity,
                'tectonic_correlation': tectonic_correlation,
                'spatial_distance': await self._calculate_spatial_distance(src_node, dst_node),
                'age_correlation': await self._calculate_age_correlation(src_geology, dst_geology)
            }
            
        except Exception as e:
            logging.warning(f"Failed to extract geological context: {e}")
            return {
                'structural_similarity': 0.5,
                'geochemical_affinity': 0.5,
                'tectonic_correlation': 0.5,
                'spatial_distance': 1.0,
                'age_correlation': 0.5
            }
    
    async def _analyze_temporal_dynamics(self, src_node, dst_node, temporal_graph) -> Dict[str, float]:
        """Analyze temporal dynamics between nodes."""
        try:
            # Check if nodes exist in temporal graph
            if src_node not in temporal_graph.nodes() or dst_node not in temporal_graph.nodes():
                return {
                    'temporal_correlation': 0.0,
                    'causal_lag': 0.0,
                    'synchronicity': 0.0
                }
            
            # Calculate temporal metrics
            temporal_correlation = 0.0
            if temporal_graph.has_edge(src_node, dst_node):
                edge_data = temporal_graph.get_edge_data(src_node, dst_node)
                temporal_correlation = edge_data.get('correlation', 0.0)
            
            # Analyze temporal patterns using time series methods
            causal_lag = await self._compute_causal_lag(src_node, dst_node)
            synchronicity = await self._compute_synchronicity(src_node, dst_node)
            
            return {
                'temporal_correlation': temporal_correlation,
                'causal_lag': causal_lag,
                'synchronicity': synchronicity
            }
            
        except Exception as e:
            logging.warning(f"Failed to analyze temporal dynamics: {e}")
            return {
                'temporal_correlation': 0.0,
                'causal_lag': 0.0,
                'synchronicity': 0.0
            }
    
    async def _compute_causal_relationship(self, src_node, dst_node, db_connector) -> float:
        """Compute causal relationship strength using causal inference methods."""
        try:
            # Use causal discovery engine if available
            if hasattr(self, 'causal_engine') and self.causal_engine:
                causal_data = await db_connector.query_causal_data(src_node, dst_node)
                causal_strength = await self.causal_engine.compute_causal_effect(causal_data)
                return float(causal_strength)
            else:
                # Fallback to correlation-based estimation
                correlation_data = await db_connector.query_correlation_data(src_node, dst_node)
                if correlation_data:
                    return min(abs(correlation_data.get('correlation', 0.0)), 1.0)
                return 0.5
                
        except Exception as e:
            logging.warning(f"Failed to compute causal relationship: {e}")
            return 0.0
    
    async def _compute_epistemic_uncertainty(self, src_node, dst_node, model, node_features) -> float:
        """Compute epistemic uncertainty using Monte Carlo dropout."""
        try:
            model.train()  # Enable dropout
            predictions = []
            
            # Perform multiple forward passes with dropout
            for _ in range(50):
                with torch.no_grad():
                    node_pair_features = torch.cat([
                        node_features[src_node],
                        node_features[dst_node]
                    ], dim=0)
                    
                    # Dummy edge features for uncertainty estimation
                    edge_features = torch.zeros(4)
                    
                    prediction = model.forward(
                        None,
                        node_pair_features.unsqueeze(0),
                        edge_features.unsqueeze(0),
                        [(0, 1)]
                    )
                    predictions.append(prediction[0])
            
            model.eval()  # Disable dropout
            
            # Calculate variance as epistemic uncertainty
            predictions_tensor = torch.stack(predictions)
            uncertainty = torch.var(predictions_tensor, dim=0).mean().item()
            return float(uncertainty)
            
        except Exception as e:
            logging.warning(f"Failed to compute epistemic uncertainty: {e}")
            return 0.1
    
    async def _compute_aleatoric_uncertainty(self, geological_features, temporal_features) -> float:
        """Compute aleatoric uncertainty from data quality metrics."""
        try:
            # Assess data quality and completeness
            geo_completeness = sum(1 for v in geological_features.values() if v > 0) / len(geological_features)
            temp_completeness = sum(1 for v in temporal_features.values() if v > 0) / len(temporal_features)
            
            # Higher completeness = lower aleatoric uncertainty
            uncertainty = 1.0 - (geo_completeness + temp_completeness) / 2.0
            return min(max(uncertainty, 0.0), 1.0)
            
        except Exception as e:
            logging.warning(f"Failed to compute aleatoric uncertainty: {e}")
            return 0.2
    
    async def _validate_physics_consistency(self, src_node, dst_node, predicted_type, db_connector) -> float:
        """Validate physics consistency of predicted relationships."""
        try:
            # Load geological domain knowledge
            physics_rules = await self._load_physics_rules()
            
            # Get node properties
            src_properties = await db_connector.query_node_properties(src_node)
            dst_properties = await db_connector.query_node_properties(dst_node)
            
            # Check physics-based constraints
            consistency_score = 1.0
            
            relationship_types = [
                'structural_control', 'magmatic_association', 'hydrothermal_linkage',
                'tectonic_coupling', 'metamorphic_gradient', 'temporal_sequence',
                'geochemical_evolution', 'stress_field_interaction', 'fluid_pathway',
                'deformation_zone', 'volcanic_system', 'sedimentary_facies'
            ]
            
            predicted_relationship = relationship_types[predicted_type]
            
            # Apply physics rules
            for rule in physics_rules.get(predicted_relationship, []):
                if not await self._check_physics_rule(rule, src_properties, dst_properties):
                    consistency_score -= 0.1
            
            return max(consistency_score, 0.0)
            
        except Exception as e:
            logging.warning(f"Failed to validate physics consistency: {e}")
            return 0.8
    
    async def _fallback_similarity_prediction(self) -> List[Dict[str, Any]]:
        """Fallback similarity-based prediction when advanced methods fail."""
        predicted_relationships = []
        
        nodes = list(self.experience_graph.nodes())
        
        for i, node1 in enumerate(nodes):
            for j, node2 in enumerate(nodes[i+1:], i+1):
                if not self.experience_graph.has_edge(node1, node2):
                    if (node1 in self.node_embeddings and 
                        node2 in self.node_embeddings):
                        
                        emb1 = self.node_embeddings[node1]
                        emb2 = self.node_embeddings[node2]
                        similarity = cosine_similarity([emb1], [emb2])[0][0]
                        
                        if similarity > 0.7:
                            predicted_relationships.append({
                                'source_node': node1,
                                'target_node': node2,
                                'relationship_type': 'similarity_based',
                                'confidence_score': float(similarity),
                                'method': 'fallback_similarity'
                            })
                            
        return predicted_relationships[:10]
    
