            # Initialize external data connector for integrated sources
            self.external_connector = ExternalDataConnector()
            await self.external_connector.initialize()
            
            # Initialize cache for performance
            self._experience_cache = {}
            self._cache_ttl = 3600  # 1 hour TTL
