    def _detect_gpu_resources(self) -> int:
        """Detect available GPU resources for parallel thermodynamic calculations"""
        try:
            import pynvml
            pynvml.nvmlInit()
            return pynvml.nvmlDeviceGetCount()
        except:
            try:
                import tensorflow as tf
                gpus = tf.config.list_physical_devices('GPU')
                return len(gpus)
            except:
                return 0
    
