    def _merge_rock_properties(self, property_sources):
        """Merge rock properties from multiple sources with confidence weighting"""
        merged = {}
        
        for properties, confidence in property_sources:
            for rock_type, props in properties.items():
                if rock_type not in merged:
                    merged[rock_type] = {'mechanical': {}, 'thermal': {}, 'dynamic': {}}
                
                # Merge each property category with confidence weighting
                for category in ['mechanical', 'thermal', 'dynamic']:
                    if category in props:
                        for prop_name, prop_value in props[category].items():
                            if prop_value is not None:
                                if prop_name not in merged[rock_type][category]:
                                    merged[rock_type][category][prop_name] = []
                                merged[rock_type][category][prop_name].append(
                                    (prop_value, confidence)
                                )
        
        # Calculate weighted averages for each property
        for rock_type in merged:
            for category in ['mechanical', 'thermal', 'dynamic']:
                for prop_name in list(merged[rock_type][category].keys()):
                    values = merged[rock_type][category][prop_name]
                    if values:
                        total_weight = sum(conf for _, conf in values)
                        weighted_avg = sum(val * conf for val, conf in values) / total_weight
                        merged[rock_type][category][prop_name] = weighted_avg
        
        self.rock_properties = merged
    
    def _validate_and_interpolate_properties(self):
        """Validate and interpolate missing rock properties using physical relationships"""
        
        for rock_type, props in self.rock_properties.items():
            mech = props.get('mechanical', {})
            
            # Interpolate missing elastic properties using relationships
            if 'elastic_modulus' in mech and 'poisson_ratio' in mech:
                E = mech['elastic_modulus']
                nu = mech['poisson_ratio']
                
                if 'shear_modulus' not in mech:
                    mech['shear_modulus'] = E / (2 * (1 + nu))
                
                if 'bulk_modulus' not in mech:
                    mech['bulk_modulus'] = E / (3 * (1 - 2 * nu))
            
            # Estimate missing strength properties
            if 'ucs' in mech:
                if 'tensile_strength' not in mech:
                    # Typical tensile/compressive strength ratio
                    mech['tensile_strength'] = mech['ucs'] / 10
                
                if 'cohesion' not in mech and 'friction_angle' in mech:
                    phi = np.radians(mech['friction_angle'])
                    # Estimate cohesion from UCS and friction angle
                    mech['cohesion'] = mech['ucs'] * (1 - np.sin(phi)) / (2 * np.cos(phi))
            
            # Estimate dynamic properties from static
            if 'elastic_modulus' in mech and 'density' in props.get('dynamic', {}):
                dyn = props['dynamic']
                rho = dyn['density']
                
                if 'p_wave_velocity' not in dyn:
                    # Estimate P-wave velocity
                    E_dyn = mech['elastic_modulus'] * 1.3  # Dynamic typically higher
                    nu = mech.get('poisson_ratio', 0.25)
                    M = E_dyn * (1 - nu) / ((1 + nu) * (1 - 2 * nu))
                    dyn['p_wave_velocity'] = np.sqrt(M / rho)
    
