class CapModelCriterion:
    """Advanced Cap Model plasticity criterion for geological materials
    
    Implements the modified Drucker-Prager cap model with:
    - Shear failure surface (Drucker-Prager)
    - Tensile cutoff surface
    - Elliptical cap surface for volumetric yielding
    - Hardening/softening rules
    - Integration with real geological data
    """
    
    def __init__(self, material_properties: Dict[str, float] = None):
        self.name = "cap_model"
        
        # Default material properties (can be overridden)
        self.properties = material_properties or {
            'cohesion': 10e6,          # Pa - cohesive strength
            'friction_angle': 30.0,    # degrees - internal friction angle
            'tensile_strength': 2e6,   # Pa - tensile strength
            'cap_hardening_modulus': 5e8,  # Pa - cap hardening modulus
            'cap_eccentricity': 0.6,   # dimensionless - cap eccentricity
            'transition_angle': 25.0,  # degrees - transition angle
            'density': 2500,           # kg/m³ - material density
            'elastic_modulus': 20e9,   # Pa - Young's modulus
            'poisson_ratio': 0.25,     # dimensionless - Poisson's ratio
        }
        
        # Initialize external data integration
        self.data_manager = None
        self.db_manager = None
        self._initialize_data_connections()
        
        # Cap model state variables
        self.plastic_volumetric_strain = 0.0
        self.cap_position = self._calculate_initial_cap_position()
        self.hardening_parameter = 0.0
        
        # Failure surface parameters
        self.alpha = self._calculate_drucker_prager_alpha()
        self.k = self._calculate_drucker_prager_k()
        
        # Logger
        self.logger = logging.getLogger(__name__)
    
    def _initialize_data_connections(self):
        """Initialize connections to external data sources"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            # External data integration
            self.data_manager = DataIntegrationManager()
            
            # Database connection
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'postgres'),
                password=os.environ.get('POSTGRES_PASSWORD', 'password')
            )
            self.db_manager = PostgreSQLGISManager(db_config)
            
        except ImportError as e:
            self.logger.warning(f"Data integration not available: {e}")
        except Exception as e:
            self.logger.error(f"Failed to initialize data connections: {e}")
    
    def _calculate_drucker_prager_alpha(self) -> float:
        """Calculate Drucker-Prager alpha parameter from friction angle"""
        phi_rad = np.radians(self.properties['friction_angle'])
        return (2 * np.sin(phi_rad)) / (np.sqrt(3) * (3 - np.sin(phi_rad)))
    
    def _calculate_drucker_prager_k(self) -> float:
        """Calculate Drucker-Prager k parameter from cohesion and friction"""
        phi_rad = np.radians(self.properties['friction_angle'])
        cohesion = self.properties['cohesion']
        return (6 * cohesion * np.cos(phi_rad)) / (np.sqrt(3) * (3 - np.sin(phi_rad)))
    
    def _calculate_initial_cap_position(self) -> float:
        """Calculate initial cap position based on material properties"""
        # Initial cap position typically related to preconsolidation pressure
        elastic_limit = self.properties.get('elastic_limit', 0.1 * self.properties['cohesion'])
        return -elastic_limit  # Negative for compression
    
    def _stress_invariants(self, stress_tensor: np.ndarray) -> Tuple[float, float, float]:
        """Calculate stress invariants I1, J2, J3"""
        if stress_tensor.shape == (6,):
            # Voigt notation: [σxx, σyy, σzz, σxy, σyz, σxz]
            sigma = np.array([
                [stress_tensor[0], stress_tensor[3], stress_tensor[5]],
                [stress_tensor[3], stress_tensor[1], stress_tensor[4]],
                [stress_tensor[5], stress_tensor[4], stress_tensor[2]]
            ])
        else:
            sigma = stress_tensor
        
        # First invariant (hydrostatic pressure)
        I1 = np.trace(sigma)
        
        # Deviatoric stress tensor
        dev_stress = sigma - (I1/3) * np.eye(3)
        
        # Second invariant of deviatoric stress
        J2 = 0.5 * np.sum(dev_stress * dev_stress)
        
        # Third invariant of deviatoric stress
        J3 = np.linalg.det(dev_stress)
        
        return I1, J2, J3
    
    def _shear_failure_function(self, I1: float, J2: float) -> float:
        """Drucker-Prager shear failure function"""
        sqrt_J2 = np.sqrt(J2)
        return sqrt_J2 + self.alpha * I1 - self.k
    
    def _tensile_failure_function(self, I1: float) -> float:
        """Tensile failure function"""
        tensile_strength = self.properties['tensile_strength']
        return I1 - 3 * tensile_strength  # Negative in tension
    
    def _cap_failure_function(self, I1: float, J2: float) -> float:
        """Elliptical cap failure function"""
        sqrt_J2 = np.sqrt(J2)
        eccentricity = self.properties['cap_eccentricity']
        
        # Cap center position (evolves with hardening)
        cap_center = self.cap_position
        
        # Elliptical cap equation
        term1 = (I1 - cap_center) ** 2
        term2 = (sqrt_J2 / eccentricity) ** 2
        
        return term1 + term2 - (self.k / eccentricity) ** 2
    
    def _update_cap_position(self, plastic_volumetric_strain_increment: float):
        """Update cap position based on volumetric plastic strain"""
        hardening_modulus = self.properties['cap_hardening_modulus']
        self.plastic_volumetric_strain += plastic_volumetric_strain_increment
        self.hardening_parameter += plastic_volumetric_strain_increment
        
        # Exponential hardening rule
        self.cap_position = self.cap_position * np.exp(
            -hardening_modulus * plastic_volumetric_strain_increment
        )
    
    async def _get_real_time_properties(self, location: Tuple[float, float] = None,
                                      depth: float = None,
                                      rock_type: str = None) -> Dict[str, float]:
        """Get real-time material properties from geological databases"""
        enhanced_properties = self.properties.copy()
        
        try:
            if self.data_manager and location:
                lat, lon = location
                
                # Get regional geological data
                regional_data = self.data_manager.collect_regional_data(
                    region_name=f"CapModel_{lat:.3f}_{lon:.3f}",
                    bbox=(lon-0.01, lat-0.01, lon+0.01, lat+0.01),
                    time_range=None  # Current conditions
                )
                
                # Extract rock properties from geological surveys
                if 'geological_surveys' in regional_data:
                    for survey in regional_data['geological_surveys']:
                        if 'rock_properties' in survey:
                            props = survey['rock_properties']
                            
                            # Update cohesion based on rock type and weathering
                            if 'unconfined_compressive_strength' in props:
                                ucs = props['unconfined_compressive_strength']
                                enhanced_properties['cohesion'] = ucs / 2.0  # Approximation
                            
                            # Update friction angle
                            if 'friction_angle' in props:
                                enhanced_properties['friction_angle'] = props['friction_angle']
                            
                            # Update tensile strength
                            if 'tensile_strength' in props:
                                enhanced_properties['tensile_strength'] = props['tensile_strength']
                
                # Depth-dependent adjustments
                if depth and depth > 0:
                    # Increase strength with confining pressure
                    confining_pressure = enhanced_properties['density'] * 9.81 * depth
                    strength_increase = 1.0 + 0.1 * (confining_pressure / 1e6)  # 10% per MPa
                    
                    enhanced_properties['cohesion'] *= strength_increase
                    enhanced_properties['tensile_strength'] *= strength_increase
            
            # Database query for specific rock properties
            if self.db_manager and rock_type:
                async with self.db_manager.get_async_session() as session:
                    # Query rock properties database
                    query = """
                    SELECT avg(cohesion), avg(friction_angle), avg(tensile_strength)
                    FROM rock_properties 
                    WHERE rock_type = %s
                    """
                    
                    result = await session.execute(query, (rock_type,))
                    row = await result.fetchone()
                    
                    if row and any(row):
                        if row[0]: enhanced_properties['cohesion'] = row[0]
                        if row[1]: enhanced_properties['friction_angle'] = row[1]
                        if row[2]: enhanced_properties['tensile_strength'] = row[2]
        
        except Exception as e:
            self.logger.warning(f"Could not get real-time properties: {e}")
        
        return enhanced_properties
    
    def evaluate(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate cap model failure criterion
        
        Args:
            stress_tensor: Stress tensor (3x3 or 6-component Voigt notation)
            **kwargs: Additional parameters including location, depth, etc.
        
        Returns:
            Dictionary containing failure analysis results
        """
        # Convert to numpy array if needed
        if not isinstance(stress_tensor, np.ndarray):
            stress_tensor = np.array(stress_tensor)
        
        # Get location and depth if provided
        location = kwargs.get('location', None)
        depth = kwargs.get('depth', 0.0)
        rock_type = kwargs.get('rock_type', None)
        
        # Update properties with real-time data (async wrapper)
        try:
            import asyncio
            if asyncio.get_event_loop().is_running():
                # Already in async context - use sync version
                updated_properties = self.properties
            else:
                # Run async property update
                updated_properties = asyncio.run(
                    self._get_real_time_properties(location, depth, rock_type)
                )
                self.properties.update(updated_properties)
        except Exception as e:
            self.logger.warning(f"Could not update properties: {e}")
        
        # Calculate stress invariants
        I1, J2, J3 = self._stress_invariants(stress_tensor)
        
        # Evaluate all failure surfaces
        f_shear = self._shear_failure_function(I1, J2)
        f_tension = self._tensile_failure_function(I1)
        f_cap = self._cap_failure_function(I1, J2)
        
        # Determine active failure mode
        failure_modes = {
            'shear': f_shear,
            'tension': f_tension,
            'cap': f_cap
        }
        
        # Find the most critical failure mode (highest function value)
        critical_mode = max(failure_modes.keys(), key=lambda k: failure_modes[k])
        critical_value = failure_modes[critical_mode]
        
        # Calculate safety factor
        if critical_value <= 0:
            # Safe - calculate safety factor as ratio to failure
            safety_factor = abs(1.0 / (critical_value - 1e-10))  # Avoid division by zero
        else:
            # Failed - safety factor less than 1
            safety_factor = 1.0 / (1.0 + critical_value)
        
        # Calculate failure stress magnitude
        failure_stress = np.sqrt(2 * J2) if J2 > 0 else abs(I1)
        
        # Additional analysis
        analysis_results = {
            'failure_stress': failure_stress,
            'safety_factor': safety_factor,
            'criterion': self.name,
            'critical_mode': critical_mode,
            'failure_functions': failure_modes,
            'stress_invariants': {
                'I1': I1,
                'J2': J2,
                'J3': J3
            },
            'material_properties': self.properties,
            'cap_state': {
                'position': self.cap_position,
                'plastic_volumetric_strain': self.plastic_volumetric_strain,
                'hardening_parameter': self.hardening_parameter
            },
            'drucker_prager_params': {
                'alpha': self.alpha,
                'k': self.k
            },
            'location': location,
            'depth': depth,
            'rock_type': rock_type
        }
        
        return analysis_results

class HierarchicalMultiSurfaceCriterion:
    """Advanced Hierarchical Multi-Surface failure criterion
    
    Implements multiple interacting failure surfaces arranged in a hierarchy:
    - Primary surface: Modified Griffith criterion for brittle failure
    - Secondary surface: Mohr-Coulomb for frictional failure
    - Tertiary surface: Cam-Clay for volumetric failure
    - Quaternary surface: Time-dependent creep failure
    - Integration with machine learning for surface selection
    """
    
    def __init__(self, material_properties: Dict[str, float] = None):
        self.name = "hierarchical_multi_surface"
        
        # Material properties with comprehensive defaults
        self.properties = material_properties or {
            # Griffith criterion parameters
            'tensile_strength': 5e6,       # Pa - uniaxial tensile strength
            'crack_length': 1e-3,          # m - characteristic crack length
            'surface_energy': 10.0,        # J/m² - surface energy
            
            # Mohr-Coulomb parameters
            'cohesion': 15e6,              # Pa - cohesive strength
            'friction_angle': 35.0,        # degrees - internal friction angle
            'dilatancy_angle': 5.0,        # degrees - dilatancy angle
            
            # Cam-Clay parameters
            'preconsolidation_pressure': 50e6,  # Pa - preconsolidation pressure
            'compression_index': 0.3,      # dimensionless - compression index
            'swelling_index': 0.05,        # dimensionless - swelling index
            'critical_state_friction': 25.0,  # degrees - critical state friction
            
            # Time-dependent parameters
            'activation_energy': 150e3,     # J/mol - activation energy for creep
            'stress_exponent': 3.0,        # dimensionless - stress exponent
            'reference_strain_rate': 1e-6, # 1/s - reference strain rate
            
            # Material constants
            'elastic_modulus': 30e9,       # Pa - Young's modulus
            'poisson_ratio': 0.2,          # dimensionless - Poisson's ratio
            'density': 2700,               # kg/m³ - material density
            'temperature': 298,            # K - reference temperature
        }
        
        # Surface hierarchy weights (learned from data)
        self.surface_weights = {
            'griffith': 0.3,
            'mohr_coulomb': 0.4,
            'cam_clay': 0.2,
            'creep': 0.1
        }
        
        # Initialize ML model for surface selection
        self.ml_model = None
        self._initialize_ml_model()
        
        # Initialize data connections
        self.data_manager = None
        self.db_manager = None
        self._initialize_data_connections()
        
        # State variables
        self.plastic_strain = np.zeros(6)
        self.accumulated_strain = 0.0
        self.time_factor = 1.0
        
        self.logger = logging.getLogger(__name__)
    
    def _initialize_ml_model(self):
        """Initialize ML model for intelligent surface selection"""
        try:
            from .model_manager import ModelManager
            
            self.model_manager = ModelManager()
            
            # Load or create failure surface selection model
            self.ml_model = self.model_manager.load_model(
                'hierarchical_surface_selector',
                model_type='random_forest'
            )
            
            if self.ml_model is None:
                # Create and train a new model
                self._train_surface_selection_model()
                
        except ImportError:
            self.logger.warning("Model manager not available - using rule-based selection")
        except Exception as e:
            self.logger.error(f"Failed to initialize ML model: {e}")
    
    def _initialize_data_connections(self):
        """Initialize connections to external data sources"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            self.data_manager = DataIntegrationManager()
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'postgres'),
                password=os.environ.get('POSTGRES_PASSWORD', 'password')
            )
            self.db_manager = PostgreSQLGISManager(db_config)
            
        except ImportError as e:
            self.logger.warning(f"Data integration not available: {e}")
        except Exception as e:
            self.logger.error(f"Failed to initialize data connections: {e}")
    
    def _train_surface_selection_model(self):
        """Train ML model for surface selection based on stress state and material"""
        try:
            from sklearn.ensemble import RandomForestClassifier
            from sklearn.model_selection import train_test_split
            import joblib
            
            # Generate training data (in real implementation, this would come from experiments/literature)
            X_train, y_train = self._generate_training_data()
            
            # Create and train model
            self.ml_model = RandomForestClassifier(
                n_estimators=100,
                max_depth=10,
                random_state=42
            )
            
            self.ml_model.fit(X_train, y_train)
            
            # Save model
            if self.model_manager:
                self.model_manager.save_model(
                    self.ml_model,
                    'hierarchical_surface_selector',
                    metadata={
                        'model_type': 'random_forest',
                        'features': ['I1', 'J2', 'J3', 'temperature', 'strain_rate', 'porosity'],
                        'targets': ['griffith', 'mohr_coulomb', 'cam_clay', 'creep']
                    }
                )
            
        except ImportError:
            self.logger.warning("Scikit-learn not available - using rule-based selection")
        except Exception as e:
            self.logger.error(f"Failed to train surface selection model: {e}")
    
    def _generate_training_data(self) -> Tuple[np.ndarray, np.ndarray]:
        """Generate synthetic training data for surface selection"""
        n_samples = 1000
        
        # Features: [I1, J2, J3, temperature, strain_rate, porosity]
        X = np.random.rand(n_samples, 6)
        X[:, 0] = (X[:, 0] - 0.5) * 200e6  # I1 range: -100 to +100 MPa
        X[:, 1] = X[:, 1] * 100e6         # J2 range: 0 to 100 MPa
        X[:, 2] = (X[:, 2] - 0.5) * 50e6  # J3 range: -25 to +25 MPa
        X[:, 3] = 273 + X[:, 3] * 200     # Temperature: 273-473 K
        X[:, 4] = 1e-8 + X[:, 4] * 1e-4  # Strain rate: 1e-8 to 1e-4 s⁻¹
        X[:, 5] = X[:, 5] * 0.3           # Porosity: 0 to 0.3
        
        # Labels: dominant surface based on rules
        y = np.zeros(n_samples, dtype=int)
        
        for i in range(n_samples):
            I1, J2, J3, temp, strain_rate, porosity = X[i]
            
            if I1 > 0 and J2 < 10e6:  # Tensile, low deviatoric stress
                y[i] = 0  # Griffith
            elif abs(I1) < 50e6 and J2 > 20e6:  # Moderate pressure, high shear
                y[i] = 1  # Mohr-Coulomb
            elif I1 < -30e6 and J2 < 30e6:  # High compression, moderate shear
                y[i] = 2  # Cam-Clay
            elif strain_rate < 1e-6 or temp > 400:  # Low strain rate or high temperature
                y[i] = 3  # Creep
            else:
                y[i] = 1  # Default to Mohr-Coulomb
        
        return X, y
    
    def _griffith_criterion(self, stress_tensor: np.ndarray) -> float:
        """Modified Griffith criterion for brittle failure"""
        # Calculate principal stresses
        principal_stresses = np.linalg.eigvals(stress_tensor)
        sigma1, sigma2, sigma3 = sorted(principal_stresses, reverse=True)
        
        # Griffith criterion parameters
        T0 = self.properties['tensile_strength']
        
        # Modified Griffith criterion
        if sigma3 >= 0:  # All stresses tensile
            f_griffith = sigma1 - T0
        else:  # Mixed loading
            f_griffith = (sigma1 - sigma3)**2 - 8*T0*(sigma1 + sigma3)
        
        return f_griffith
    
    def _mohr_coulomb_criterion(self, stress_tensor: np.ndarray) -> float:
        """Mohr-Coulomb failure criterion"""
        # Calculate principal stresses
        principal_stresses = np.linalg.eigvals(stress_tensor)
        sigma1, sigma3 = max(principal_stresses), min(principal_stresses)
        
        # Mohr-Coulomb parameters
        c = self.properties['cohesion']
        phi = np.radians(self.properties['friction_angle'])
        
        # Mohr-Coulomb criterion
        f_mc = (sigma1 - sigma3) - 2*c*np.cos(phi) - (sigma1 + sigma3)*np.sin(phi)
        
        return f_mc
    
    def _cam_clay_criterion(self, stress_tensor: np.ndarray) -> float:
        """Modified Cam-Clay criterion for volumetric failure"""
        # Calculate stress invariants
        I1 = np.trace(stress_tensor)
        dev_stress = stress_tensor - (I1/3) * np.eye(3)
        J2 = 0.5 * np.sum(dev_stress * dev_stress)
        
        # Cam-Clay parameters
        pc = self.properties['preconsolidation_pressure']
        M = np.tan(np.radians(self.properties['critical_state_friction']))
        
        # Modified Cam-Clay criterion
        p = I1 / 3
        q = np.sqrt(3 * J2)
        
        f_cc = (q/M)**2 + p*(p - pc)
        
        return f_cc
    
    def _creep_criterion(self, stress_tensor: np.ndarray, time: float = 0.0,
                        temperature: float = None) -> float:
        """Time-dependent creep failure criterion"""
        if temperature is None:
            temperature = self.properties['temperature']
        
        # Calculate equivalent stress
        dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
        von_mises_stress = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        # Creep parameters
        Q = self.properties['activation_energy']  # Activation energy
        n = self.properties['stress_exponent']
        A = self.properties['reference_strain_rate']
        R = 8.314  # Gas constant
        
        # Norton-Bailey creep law
        strain_rate = A * (von_mises_stress**n) * np.exp(-Q/(R*temperature))
        
        # Time-dependent failure criterion
        critical_strain = 0.01  # 1% critical strain
        time_to_failure = critical_strain / strain_rate if strain_rate > 0 else np.inf
        
        # Normalize to failure function (>0 means failure)
        if time > 0:
            f_creep = time / time_to_failure - 1.0
        else:
            f_creep = -1.0  # No failure without time
        
        return f_creep
    
    def _select_dominant_surface(self, stress_tensor: np.ndarray,
                                **kwargs) -> Tuple[str, Dict[str, float]]:
        """Select dominant failure surface using ML model or rules"""
        # Calculate stress invariants and features
        I1 = np.trace(stress_tensor)
        dev_stress = stress_tensor - (I1/3) * np.eye(3)
        J2 = 0.5 * np.sum(dev_stress * dev_stress)
        J3 = np.linalg.det(dev_stress)
        
        temperature = kwargs.get('temperature', self.properties['temperature'])
        strain_rate = kwargs.get('strain_rate', 1e-6)
        porosity = kwargs.get('porosity', 0.1)
        
        # Evaluate all surfaces
        surface_values = {
            'griffith': self._griffith_criterion(stress_tensor),
            'mohr_coulomb': self._mohr_coulomb_criterion(stress_tensor),
            'cam_clay': self._cam_clay_criterion(stress_tensor),
            'creep': self._creep_criterion(stress_tensor, 
                                         kwargs.get('time', 0.0), 
                                         temperature)
        }
        
        if self.ml_model is not None:
            try:
                # Use ML model for surface selection
                features = np.array([[I1, J2, J3, temperature, strain_rate, porosity]])
                probabilities = self.ml_model.predict_proba(features)[0]
                
                surface_names = ['griffith', 'mohr_coulomb', 'cam_clay', 'creep']
                dominant_surface = surface_names[np.argmax(probabilities)]
                
                # Update weights based on ML predictions
                for i, name in enumerate(surface_names):
                    self.surface_weights[name] = probabilities[i]
                    
            except Exception as e:
                self.logger.warning(f"ML surface selection failed: {e}")
                # Fallback to rule-based selection
                dominant_surface = max(surface_values.keys(), 
                                     key=lambda k: surface_values[k])
        else:
            # Rule-based selection: surface with highest failure function value
            dominant_surface = max(surface_values.keys(), 
                                 key=lambda k: surface_values[k])
        
        return dominant_surface, surface_values
    
    async def _get_enhanced_properties(self, location: Tuple[float, float] = None,
                                     depth: float = None) -> Dict[str, float]:
        """Get enhanced material properties from geological databases"""
        enhanced_props = self.properties.copy()
        
        try:
            if self.data_manager and location:
                lat, lon = location
                
                # Collect geological data
                regional_data = self.data_manager.collect_regional_data(
                    region_name=f"MultiSurface_{lat:.3f}_{lon:.3f}",
                    bbox=(lon-0.01, lat-0.01, lon+0.01, lat+0.01)
                )
                
                # Extract rock properties
                if 'geological_surveys' in regional_data:
                    for survey in regional_data['geological_surveys']:
                        if 'rock_properties' in survey:
                            props = survey['rock_properties']
                            
                            # Update multiple surface parameters
                            for key in ['tensile_strength', 'cohesion', 'friction_angle']:
                                if key in props:
                                    enhanced_props[key] = props[key]
            
            # Database queries for specific formations
            if self.db_manager and location:
                async with self.db_manager.get_async_session() as session:
                    # Query formation properties
                    query = """
                    SELECT formation_type, avg_tensile_strength, avg_cohesion, 
                           avg_friction_angle, avg_porosity
                    FROM geological_formations 
                    WHERE ST_Contains(geometry, ST_Point(%s, %s))
                    ORDER BY confidence DESC
                    LIMIT 1
                    """
                    
                    result = await session.execute(query, (lon, lat))
                    row = await result.fetchone()
                    
                    if row:
                        enhanced_props.update({
                            'tensile_strength': row[1] or enhanced_props['tensile_strength'],
                            'cohesion': row[2] or enhanced_props['cohesion'],
                            'friction_angle': row[3] or enhanced_props['friction_angle']
                        })
        
        except Exception as e:
            self.logger.warning(f"Could not enhance properties: {e}")
        
        return enhanced_props
    
    def evaluate(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate hierarchical multi-surface failure criterion
        
        Args:
            stress_tensor: Stress tensor (3x3 matrix)
            **kwargs: Additional parameters (location, depth, temperature, etc.)
        
        Returns:
            Comprehensive failure analysis results
        """
        # Convert to 3x3 tensor if needed
        if stress_tensor.shape == (6,):
            # Voigt notation to tensor
            stress_tensor = np.array([
                [stress_tensor[0], stress_tensor[3], stress_tensor[5]],
                [stress_tensor[3], stress_tensor[1], stress_tensor[4]],
                [stress_tensor[5], stress_tensor[4], stress_tensor[2]]
            ])
        
        # Get enhanced properties
        location = kwargs.get('location', None)
        depth = kwargs.get('depth', 0.0)
        
        try:
            import asyncio
            if not asyncio.get_event_loop().is_running():
                enhanced_props = asyncio.run(self._get_enhanced_properties(location, depth))
                self.properties.update(enhanced_props)
        except Exception as e:
            self.logger.warning(f"Could not update properties: {e}")
        
        # Select dominant surface and evaluate all surfaces
        dominant_surface, surface_values = self._select_dominant_surface(stress_tensor, **kwargs)
        
        # Calculate combined failure function using hierarchy
        combined_failure = sum(
            self.surface_weights[surface] * max(0, value)
            for surface, value in surface_values.items()
        )
        
        # Safety factor calculation
        critical_value = surface_values[dominant_surface]
        if critical_value <= 0:
            safety_factor = abs(1.0 / (critical_value - 1e-10))
        else:
            safety_factor = 1.0 / (1.0 + critical_value)
        
        # Calculate failure stress
        dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
        failure_stress = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        return {
            'failure_stress': failure_stress,
            'safety_factor': safety_factor,
            'criterion': self.name,
            'dominant_surface': dominant_surface,
            'surface_values': surface_values,
            'surface_weights': self.surface_weights,
            'combined_failure_function': combined_failure,
            'material_properties': self.properties,
            'stress_tensor': stress_tensor.tolist(),
            'location': location,
            'depth': depth,
            'analysis_metadata': {
                'ml_model_used': self.ml_model is not None,
                'data_integration_active': self.data_manager is not None,
                'database_connected': self.db_manager is not None
            }
        }

class AnisotropicFailureCriterion:
    """Advanced Anisotropic Failure Criterion
    
    Implements comprehensive anisotropic failure analysis including:
    - Tsai-Wu criterion for composite materials
    - Hill criterion for metal plasticity
    - Fabric tensor-based approach for geological materials
    - Microstructure-informed failure prediction
    - Real-time anisotropy characterization
    """
    
    def __init__(self, material_properties: Dict[str, Any] = None):
        self.name = "anisotropic_failure"
        
        # Comprehensive anisotropic material properties
        self.properties = material_properties or {
            # Principal direction strengths
            'X_tension': 100e6,       # Pa - tensile strength in 1-direction
            'X_compression': 200e6,   # Pa - compressive strength in 1-direction  
            'Y_tension': 50e6,        # Pa - tensile strength in 2-direction
            'Y_compression': 100e6,   # Pa - compressive strength in 2-direction
            'Z_tension': 30e6,        # Pa - tensile strength in 3-direction
            'Z_compression': 80e6,    # Pa - compressive strength in 3-direction
            
            # Shear strengths
            'S_12': 25e6,            # Pa - shear strength in 1-2 plane
            'S_13': 20e6,            # Pa - shear strength in 1-3 plane
            'S_23': 15e6,            # Pa - shear strength in 2-3 plane
            
            # Elastic constants (orthotropic)
            'E1': 50e9,              # Pa - Young's modulus in 1-direction
            'E2': 30e9,              # Pa - Young's modulus in 2-direction
            'E3': 20e9,              # Pa - Young's modulus in 3-direction
            'G12': 15e9,             # Pa - shear modulus in 1-2 plane
            'G13': 12e9,             # Pa - shear modulus in 1-3 plane
            'G23': 10e9,             # Pa - shear modulus in 2-3 plane
            'nu12': 0.3,             # Poisson's ratio 1-2
            'nu13': 0.25,            # Poisson's ratio 1-3
            'nu23': 0.2,             # Poisson's ratio 2-3
            
            # Fabric tensor parameters
            'fabric_intensity': 0.5,  # Degree of anisotropy (0=isotropic, 1=highly anisotropic)
            'fabric_direction': [1, 0, 0],  # Principal fabric direction
            'density': 2600,         # kg/m³
        }
        
        # Fabric tensor (describes material anisotropy)
        self.fabric_tensor = self._initialize_fabric_tensor()
        
        # Transformation matrices for different coordinate systems
        self.material_to_global = np.eye(3)
        self.global_to_material = np.eye(3)
        
        # Initialize data connections
        self.data_manager = None
        self.db_manager = None
        self._initialize_data_connections()
        
        # Initialize microstructure analysis
        self.microstructure_analyzer = None
        self._initialize_microstructure_analysis()
        
        self.logger = logging.getLogger(__name__)
    
    def _initialize_fabric_tensor(self) -> np.ndarray:
        """Initialize fabric tensor based on material properties"""
        # Fabric tensor characterizes the directional properties
        intensity = self.properties['fabric_intensity']
        direction = np.array(self.properties['fabric_direction'])
        direction = direction / np.linalg.norm(direction)
        
        # Create fabric tensor using dyadic product
        fabric_tensor = intensity * np.outer(direction, direction) + \
                       (1 - intensity) * np.eye(3) / 3
        
        return fabric_tensor
    
    def _initialize_data_connections(self):
        """Initialize connections to external data sources"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            self.data_manager = DataIntegrationManager()
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'postgres'),
                password=os.environ.get('POSTGRES_PASSWORD', 'password')
            )
            self.db_manager = PostgreSQLGISManager(db_config)
            
        except ImportError as e:
            self.logger.warning(f"Data integration not available: {e}")
        except Exception as e:
            self.logger.error(f"Failed to initialize data connections: {e}")
    
    def _initialize_microstructure_analysis(self):
        """Initialize microstructure analysis capabilities"""
        try:
            from .geological_gnn import GeologicalGraphNeuralNetwork
            
            # Use GNN for microstructure-property relationships
            self.microstructure_analyzer = GeologicalGraphNeuralNetwork()
            
        except ImportError:
            self.logger.warning("Microstructure analysis not available")
        except Exception as e:
            self.logger.error(f"Failed to initialize microstructure analysis: {e}")
    
    def _tsai_wu_criterion(self, stress_tensor: np.ndarray) -> float:
        """Tsai-Wu failure criterion for anisotropic materials"""
        # Extract stress components (assuming Voigt notation)
        if stress_tensor.shape == (6,):
            sigma = stress_tensor  # [σ11, σ22, σ33, σ12, σ13, σ23]
        else:
            # Convert 3x3 tensor to Voigt notation
            sigma = np.array([
                stress_tensor[0, 0], stress_tensor[1, 1], stress_tensor[2, 2],
                stress_tensor[0, 1], stress_tensor[0, 2], stress_tensor[1, 2]
            ])
        
        # Tsai-Wu strength parameters
        X_t, X_c = self.properties['X_tension'], self.properties['X_compression']
        Y_t, Y_c = self.properties['Y_tension'], self.properties['Y_compression']
        Z_t, Z_c = self.properties['Z_tension'], self.properties['Z_compression']
        S_12, S_13, S_23 = self.properties['S_12'], self.properties['S_13'], self.properties['S_23']
        
        # Linear strength parameters
        F1 = (1/X_t) - (1/X_c)
        F2 = (1/Y_t) - (1/Y_c)
        F3 = (1/Z_t) - (1/Z_c)
        
        # Quadratic strength parameters
        F11 = 1 / (X_t * X_c)
        F22 = 1 / (Y_t * Y_c)
        F33 = 1 / (Z_t * Z_c)
        F44 = 1 / (S_12**2)
        F55 = 1 / (S_13**2)
        F66 = 1 / (S_23**2)
        
        # Interaction terms (simplified - usually require experimental data)
        F12 = -0.5 * np.sqrt(F11 * F22)
        F13 = -0.5 * np.sqrt(F11 * F33)
        F23 = -0.5 * np.sqrt(F22 * F33)
        
        # Tsai-Wu criterion
        tsai_wu = (F1*sigma[0] + F2*sigma[1] + F3*sigma[2] +
                   F11*sigma[0]**2 + F22*sigma[1]**2 + F33*sigma[2]**2 +
                   F44*sigma[3]**2 + F55*sigma[4]**2 + F66*sigma[5]**2 +
                   2*F12*sigma[0]*sigma[1] + 2*F13*sigma[0]*sigma[2] +
                   2*F23*sigma[1]*sigma[2])
        
        return tsai_wu - 1.0  # >0 indicates failure
    
    def _hill_criterion(self, stress_tensor: np.ndarray) -> float:
        """Hill's anisotropic yield criterion"""
        if stress_tensor.shape == (6,):
            sigma = stress_tensor
        else:
            sigma = np.array([
                stress_tensor[0, 0], stress_tensor[1, 1], stress_tensor[2, 2],
                stress_tensor[0, 1], stress_tensor[0, 2], stress_tensor[1, 2]
            ])
        
        # Hill's anisotropy parameters
        X, Y, Z = self.properties['X_compression'], self.properties['Y_compression'], self.properties['Z_compression']
        S_12, S_13, S_23 = self.properties['S_12'], self.properties['S_13'], self.properties['S_23']
        
        # Hill coefficients
        F = 1/(2*Y**2) + 1/(2*Z**2) - 1/(2*X**2)
        G = 1/(2*Z**2) + 1/(2*X**2) - 1/(2*Y**2)
        H = 1/(2*X**2) + 1/(2*Y**2) - 1/(2*Z**2)
        L = 3/(2*S_23**2)
        M = 3/(2*S_13**2)
        N = 3/(2*S_12**2)
        
        # Hill criterion
        hill = (F*(sigma[1] - sigma[2])**2 + G*(sigma[2] - sigma[0])**2 +
                H*(sigma[0] - sigma[1])**2 + 2*L*sigma[5]**2 +
                2*M*sigma[4]**2 + 2*N*sigma[3]**2)
        
        return hill - 1.0  # >0 indicates failure
    
    def _fabric_tensor_criterion(self, stress_tensor: np.ndarray) -> float:
        """Fabric tensor-based failure criterion for geological materials"""
        if stress_tensor.shape == (6,):
            # Convert Voigt to 3x3 tensor
            stress_3x3 = np.array([
                [stress_tensor[0], stress_tensor[3], stress_tensor[5]],
                [stress_tensor[3], stress_tensor[1], stress_tensor[4]],
                [stress_tensor[5], stress_tensor[4], stress_tensor[2]]
            ])
        else:
            stress_3x3 = stress_tensor
        
        # Calculate fabric-weighted stress
        fabric_stress = np.sum(self.fabric_tensor * stress_3x3)
        
        # Directional strength based on fabric orientation
        base_strength = (self.properties['X_compression'] + 
                        self.properties['Y_compression'] + 
                        self.properties['Z_compression']) / 3
        
        # Modify strength based on fabric alignment with stress
        stress_direction = self._get_principal_stress_direction(stress_3x3)
        fabric_direction = self._get_fabric_direction()
        
        alignment = abs(np.dot(stress_direction, fabric_direction))
        strength_modifier = 1.0 + self.properties['fabric_intensity'] * (alignment - 0.5)
        
        effective_strength = base_strength * strength_modifier
        
        # Fabric-based failure criterion
        equivalent_stress = np.sqrt(np.sum(stress_3x3**2))
        
        return equivalent_stress / effective_strength - 1.0
    
    def _get_principal_stress_direction(self, stress_tensor: np.ndarray) -> np.ndarray:
        """Get direction of maximum principal stress"""
        eigenvalues, eigenvectors = np.linalg.eigh(stress_tensor)
        max_index = np.argmax(np.abs(eigenvalues))
        return eigenvectors[:, max_index]
    
    def _get_fabric_direction(self) -> np.ndarray:
        """Get principal fabric direction"""
        eigenvalues, eigenvectors = np.linalg.eigh(self.fabric_tensor)
        max_index = np.argmax(eigenvalues)
        return eigenvectors[:, max_index]
    
    async def _characterize_anisotropy(self, location: Tuple[float, float] = None,
                                     depth: float = None) -> Dict[str, Any]:
        """Characterize material anisotropy using real geological data"""
        anisotropy_data = {'fabric_tensor': self.fabric_tensor.tolist()}
        
        try:
            if self.data_manager and location:
                lat, lon = location
                
                # Get structural geology data
                regional_data = self.data_manager.collect_regional_data(
                    region_name=f"Anisotropy_{lat:.3f}_{lon:.3f}",
                    bbox=(lon-0.01, lat-0.01, lon+0.01, lat+0.01)
                )
                
                # Extract structural features
                if 'geological_surveys' in regional_data:
                    for survey in regional_data['geological_surveys']:
                        if 'structural_data' in survey:
                            struct_data = survey['structural_data']
                            
                            # Extract foliation, fractures, and bedding orientations
                            if 'foliation_strike' in struct_data and 'foliation_dip' in struct_data:
                                strike = struct_data['foliation_strike']
                                dip = struct_data['foliation_dip']
                                
                                # Convert to fabric direction
                                fabric_direction = self._strike_dip_to_vector(strike, dip)
                                self.properties['fabric_direction'] = fabric_direction.tolist()
                                
                                # Update fabric tensor
                                self.fabric_tensor = self._initialize_fabric_tensor()
                                
                                anisotropy_data['foliation_strike'] = strike
                                anisotropy_data['foliation_dip'] = dip
                                anisotropy_data['fabric_direction'] = fabric_direction.tolist()
            
            # Database query for rock fabric data
            if self.db_manager and location:
                async with self.db_manager.get_async_session() as session:
                    query = """
                    SELECT rf.fabric_type, rf.intensity, rf.strike, rf.dip,
                           rf.anisotropy_ratio, rf.principal_directions
                    FROM rock_fabrics rf
                    WHERE ST_DWithin(rf.location::geography, ST_Point(%s, %s)::geography, 1000)
                    ORDER BY rf.confidence DESC
                    LIMIT 5
                    """
                    
                    result = await session.execute(query, (lon, lat))
                    rows = await result.fetchall()
                    
                    if rows:
                        # Combine multiple fabric measurements
                        fabric_intensities = [row[1] for row in rows if row[1]]
                        if fabric_intensities:
                            avg_intensity = np.mean(fabric_intensities)
                            self.properties['fabric_intensity'] = avg_intensity
                            
                        anisotropy_data['database_fabrics'] = [
                            {
                                'type': row[0], 'intensity': row[1],
                                'strike': row[2], 'dip': row[3],
                                'anisotropy_ratio': row[4]
                            } for row in rows
                        ]
            
            # Microstructure analysis if available
            if self.microstructure_analyzer:
                microstructure_props = await self._analyze_microstructure(location, depth)
                anisotropy_data.update(microstructure_props)
        
        except Exception as e:
            self.logger.warning(f"Could not characterize anisotropy: {e}")
        
        return anisotropy_data
    
    async def _analyze_microstructure(self, location: Tuple[float, float],
                                    depth: float) -> Dict[str, Any]:
        """Analyze microstructural controls on anisotropy"""
        try:
            # This would integrate with microscopy/CT scan data
            # For now, return synthetic analysis
            return {
                'grain_orientation_tensor': np.random.rand(3, 3).tolist(),
                'crack_density_tensor': np.random.rand(3, 3).tolist(),
                'pore_fabric_tensor': np.random.rand(3, 3).tolist(),
                'mineral_alignment': 0.7,
                'microcrack_anisotropy': 0.4
            }
        except Exception as e:
            self.logger.warning(f"Microstructure analysis failed: {e}")
            return {}
    
    def _strike_dip_to_vector(self, strike: float, dip: float) -> np.ndarray:
        """Convert strike/dip to unit vector"""
        strike_rad = np.radians(strike)
        dip_rad = np.radians(dip)
        
        # Calculate normal vector to the plane
        normal = np.array([
            -np.sin(dip_rad) * np.sin(strike_rad),
            np.sin(dip_rad) * np.cos(strike_rad),
            np.cos(dip_rad)
        ])
        
        return normal / np.linalg.norm(normal)
    
    def evaluate(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate anisotropic failure criterion
        
        Args:
            stress_tensor: Stress tensor (3x3 or 6-component Voigt)
            **kwargs: Additional parameters including location, depth, etc.
        
        Returns:
            Comprehensive anisotropic failure analysis
        """
        # Convert stress tensor to numpy array
        if not isinstance(stress_tensor, np.ndarray):
            stress_tensor = np.array(stress_tensor)
        
        # Extract parameters
        location = kwargs.get('location', None)
        depth = kwargs.get('depth', 0.0)
        
        # Characterize anisotropy with real data
        try:
            import asyncio
            if not asyncio.get_event_loop().is_running():
                anisotropy_data = asyncio.run(
                    self._characterize_anisotropy(location, depth)
                )
            else:
                anisotropy_data = {'fabric_tensor': self.fabric_tensor.tolist()}
        except Exception as e:
            self.logger.warning(f"Could not characterize anisotropy: {e}")
            anisotropy_data = {'fabric_tensor': self.fabric_tensor.tolist()}
        
        # Evaluate multiple anisotropic criteria
        tsai_wu_value = self._tsai_wu_criterion(stress_tensor)
        hill_value = self._hill_criterion(stress_tensor)
        fabric_value = self._fabric_tensor_criterion(stress_tensor)
        
        # Combine criteria with weights
        criteria_weights = {'tsai_wu': 0.4, 'hill': 0.3, 'fabric': 0.3}
        combined_failure = (
            criteria_weights['tsai_wu'] * max(0, tsai_wu_value) +
            criteria_weights['hill'] * max(0, hill_value) +
            criteria_weights['fabric'] * max(0, fabric_value)
        )
        
        # Determine critical criterion
        criteria_values = {
            'tsai_wu': tsai_wu_value,
            'hill': hill_value,
            'fabric': fabric_value
        }
        critical_criterion = max(criteria_values.keys(), key=lambda k: criteria_values[k])
        critical_value = criteria_values[critical_criterion]
        
        # Calculate safety factor
        if critical_value <= 0:
            safety_factor = abs(1.0 / (critical_value - 1e-10))
        else:
            safety_factor = 1.0 / (1.0 + critical_value)
        
        # Calculate equivalent failure stress
        if stress_tensor.shape == (6,):
            # Von Mises equivalent stress for Voigt notation
            s11, s22, s33, s12, s13, s23 = stress_tensor
            failure_stress = np.sqrt(0.5 * ((s11-s22)**2 + (s22-s33)**2 + (s33-s11)**2 +
                                          6*(s12**2 + s13**2 + s23**2)))
        else:
            # Von Mises for 3x3 tensor
            dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
            failure_stress = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        return {
            'failure_stress': failure_stress,
            'safety_factor': safety_factor,
            'criterion': self.name,
            'critical_criterion': critical_criterion,
            'criteria_values': criteria_values,
            'criteria_weights': criteria_weights,
            'combined_failure_function': combined_failure,
            'anisotropy_characterization': anisotropy_data,
            'fabric_tensor': self.fabric_tensor.tolist(),
            'material_properties': self.properties,
            'stress_tensor': stress_tensor.tolist(),
            'location': location,
            'depth': depth,
            'directional_strengths': {
                'X_direction': {
                    'tension': self.properties['X_tension'],
                    'compression': self.properties['X_compression']
                },
                'Y_direction': {
                    'tension': self.properties['Y_tension'],
                    'compression': self.properties['Y_compression']
                },
                'Z_direction': {
                    'tension': self.properties['Z_tension'],
                    'compression': self.properties['Z_compression']
                }
            }
        }

class TimeDependentFailureCriterion:
    """Advanced Time-Dependent Failure Criterion
    
    Implements comprehensive viscoplastic failure analysis including:
    - Norton-Bailey power law creep
    - Kachanov-Rabotnov continuum damage mechanics
    - Arrhenius temperature dependence
    - Stress corrosion cracking
    - Fatigue damage accumulation
    - Real-time environmental monitoring integration
    """
    
    def __init__(self, material_properties: Dict[str, float] = None):
        self.name = "time_dependent_failure"
        
        # Comprehensive time-dependent material properties
        self.properties = material_properties or {
            # Creep parameters
            'norton_coefficient': 1e-20,    # Pa⁻ⁿ·s⁻¹ - Norton creep coefficient
            'stress_exponent': 3.5,         # dimensionless - stress exponent n
            'activation_energy': 300e3,     # J/mol - activation energy for creep
            'reference_temperature': 298,    # K - reference temperature
            'gas_constant': 8.314,          # J/(mol·K) - universal gas constant
            
            # Damage mechanics parameters
            'damage_coefficient': 1e-10,    # Pa⁻ᵐ·s⁻¹ - damage evolution coefficient
            'damage_exponent': 2.0,         # dimensionless - damage exponent m
            'critical_damage': 0.99,        # dimensionless - critical damage for failure
            'healing_coefficient': 1e-12,   # s⁻¹ - damage healing coefficient
            
            # Stress corrosion parameters
            'corrosion_coefficient': 1e-8,  # Pa⁻¹·s⁻¹ - stress corrosion coefficient
            'corrosion_threshold': 0.3,     # dimensionless - threshold stress ratio
            'ph_sensitivity': 0.1,          # dimensionless - pH sensitivity factor
            'chemical_potential': 0.0,      # J/mol - chemical potential of environment
            
            # Fatigue parameters
            'fatigue_strength_coefficient': 1000e6,  # Pa - fatigue strength coefficient
            'fatigue_strength_exponent': -0.1,      # dimensionless - fatigue strength exponent
            'fatigue_ductility_coefficient': 0.5,   # dimensionless - fatigue ductility coefficient
            'fatigue_ductility_exponent': -0.5,     # dimensionless - fatigue ductility exponent
            
            # Material constants
            'elastic_modulus': 50e9,        # Pa - Young's modulus
            'poisson_ratio': 0.25,          # dimensionless - Poisson's ratio
            'density': 2800,                # kg/m³ - material density
            'thermal_expansion': 1e-5,      # K⁻¹ - coefficient of thermal expansion
            'thermal_conductivity': 2.5,    # W/(m·K) - thermal conductivity
        }
        
        # State variables for time-dependent analysis
        self.damage_state = 0.0          # Current damage level
        self.accumulated_strain = 0.0    # Accumulated inelastic strain
        self.fatigue_cycles = 0          # Number of fatigue cycles
        self.time_history = []           # Time history of loading
        self.stress_history = []         # Stress history
        
        # Environmental state
        self.environmental_conditions = {
            'temperature': 298.15,       # K
            'humidity': 0.5,            # relative humidity
            'ph': 7.0,                  # pH of environment
            'chemical_composition': {}   # Chemical species concentrations
        }
        
        # Initialize data connections
        self.data_manager = None
        self.db_manager = None
        self._initialize_data_connections()
        
        # Initialize environmental monitoring
        self.env_monitor = None
        self._initialize_environmental_monitoring()
        
        self.logger = logging.getLogger(__name__)
    
    def _initialize_data_connections(self):
        """Initialize connections to external data sources"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            self.data_manager = DataIntegrationManager()
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'postgres'),
                password=os.environ.get('POSTGRES_PASSWORD', 'password')
            )
            self.db_manager = PostgreSQLGISManager(db_config)
            
        except ImportError as e:
            self.logger.warning(f"Data integration not available: {e}")
        except Exception as e:
            self.logger.error(f"Failed to initialize data connections: {e}")
    
    def _initialize_environmental_monitoring(self):
        """Initialize real-time environmental monitoring"""
        try:
            # This would connect to environmental sensors and weather APIs
            self.env_monitor = {
                'weather_api_key': os.environ.get('WEATHER_API_KEY'),
                'sensor_endpoints': [],
                'monitoring_active': False
            }
        except Exception as e:
            self.logger.warning(f"Environmental monitoring initialization failed: {e}")
    
    def _norton_bailey_creep(self, stress: float, temperature: float, time: float) -> float:
        """Norton-Bailey power law creep model"""
        A = self.properties['norton_coefficient']
        n = self.properties['stress_exponent']
        Q = self.properties['activation_energy']
        R = self.properties['gas_constant']
        T_ref = self.properties['reference_temperature']
        
        # Temperature-dependent creep rate
        temperature_factor = np.exp(-Q/R * (1/temperature - 1/T_ref))
        
        # Norton-Bailey creep strain rate
        strain_rate = A * (stress**n) * temperature_factor
        
        # Integrate over time to get total creep strain
        creep_strain = strain_rate * time
        
        return creep_strain
    
    def _damage_evolution(self, stress: float, temperature: float, time: float,
                         current_damage: float) -> float:
        """Kachanov-Rabotnov damage evolution model"""
        B = self.properties['damage_coefficient']
        m = self.properties['damage_exponent']
        Q = self.properties['activation_energy']
        R = self.properties['gas_constant']
        T_ref = self.properties['reference_temperature']
        
        # Temperature dependence
        temperature_factor = np.exp(-Q/R * (1/temperature - 1/T_ref))
        
        # Damage evolution rate (Kachanov-Rabotnov)
        if current_damage < self.properties['critical_damage']:
            damage_rate = B * (stress**m) * temperature_factor / ((1 - current_damage)**(m-1))
        else:
            damage_rate = np.inf  # Instantaneous failure
        
        # Include damage healing (if applicable)
        healing_rate = self.properties['healing_coefficient'] * current_damage
        net_damage_rate = damage_rate - healing_rate
        
        # Integrate damage evolution
        new_damage = current_damage + max(0, net_damage_rate * time)
        
        return min(new_damage, self.properties['critical_damage'])
    
    def _stress_corrosion_cracking(self, stress: float, time: float,
                                  ph: float = 7.0, chemical_potential: float = 0.0) -> float:
        """Stress corrosion cracking model"""
        K_scc = self.properties['corrosion_coefficient']
        sigma_th = self.properties['corrosion_threshold'] * self.properties['elastic_modulus']
        ph_sens = self.properties['ph_sensitivity']
        
        if stress > sigma_th:
            # Charles-Evans crack growth law modified for chemical effects
            ph_factor = 1 + ph_sens * (7.0 - ph)  # Neutral pH = 7
            chemical_factor = np.exp(chemical_potential / (8.314 * 298))  # RT at 298K
            
            crack_growth_rate = K_scc * ((stress - sigma_th)**2) * ph_factor * chemical_factor
            total_crack_growth = crack_growth_rate * time
        else:
            total_crack_growth = 0.0
        
        return total_crack_growth
    
    def _fatigue_damage(self, stress_amplitude: float, mean_stress: float,
                       cycles: int) -> float:
        """Fatigue damage accumulation using Coffin-Manson model"""
        sigma_f_prime = self.properties['fatigue_strength_coefficient']
        b = self.properties['fatigue_strength_exponent']
        epsilon_f_prime = self.properties['fatigue_ductility_coefficient']
        c = self.properties['fatigue_ductility_exponent']
        E = self.properties['elastic_modulus']
        
        # Goodman mean stress correction
        sigma_ult = 2 * sigma_f_prime  # Approximate ultimate strength
        corrected_amplitude = stress_amplitude / (1 - mean_stress/sigma_ult)
        
        # Coffin-Manson strain-life relationship
        elastic_strain_amplitude = corrected_amplitude / E
        
        # Basquin equation for elastic strain
        N_elastic = (elastic_strain_amplitude / (sigma_f_prime/E))**(1/b)
        
        # Coffin-Manson equation for plastic strain
        N_plastic = (elastic_strain_amplitude / epsilon_f_prime)**(1/c)
        
        # Combined fatigue life (harmonic mean)
        N_fatigue = 1 / (1/N_elastic + 1/N_plastic)
        
        # Palmgren-Miner damage accumulation
        fatigue_damage = cycles / N_fatigue
        
        return fatigue_damage
    
    async def _get_environmental_conditions(self, location: Tuple[float, float] = None) -> Dict[str, float]:
        """Get real-time environmental conditions affecting time-dependent failure"""
        conditions = self.environmental_conditions.copy()
        
        try:
            if self.data_manager and location:
                lat, lon = location
                
                # Get weather data
                weather_data = self.data_manager.get_weather_data(
                    latitude=lat,
                    longitude=lon,
                    parameters=['temperature', 'humidity', 'precipitation']
                )
                
                if weather_data:
                    conditions.update({
                        'temperature': weather_data.get('temperature', 298.15),
                        'humidity': weather_data.get('humidity', 0.5),
                        'precipitation': weather_data.get('precipitation', 0.0)
                    })
            
            # Database query for local environmental conditions
            if self.db_manager and location:
                async with self.db_manager.get_async_session() as session:
                    query = """
                    SELECT avg(temperature_k), avg(relative_humidity), avg(ph),
                           avg(dissolved_oxygen), avg(chloride_concentration)
                    FROM environmental_monitoring
                    WHERE ST_DWithin(location::geography, ST_Point(%s, %s)::geography, 5000)
                      AND measurement_time >= NOW() - INTERVAL '24 hours'
                    """
                    
                    result = await session.execute(query, (lon, lat))
                    row = await result.fetchone()
                    
                    if row and any(row):
                        conditions.update({
                            'temperature': row[0] or conditions['temperature'],
                            'humidity': row[1] or conditions['humidity'],
                            'ph': row[2] or conditions['ph'],
                            'dissolved_oxygen': row[3] or 8.0,  # mg/L typical
                            'chloride_concentration': row[4] or 0.0  # ppm
                        })
        
        except Exception as e:
            self.logger.warning(f"Could not get environmental conditions: {e}")
        
        return conditions
    
    def _time_to_failure_analysis(self, stress: float, temperature: float,
                                 environmental_conditions: Dict[str, float]) -> Dict[str, float]:
        """Comprehensive time-to-failure analysis"""
        # Initialize time parameters
        time_increments = np.logspace(0, 8, 100)  # 1 second to 100 million seconds (3+ years)
        
        failure_mechanisms = {
            'creep': [],
            'damage': [],
            'stress_corrosion': [],
            'combined': []
        }
        
        current_damage = self.damage_state
        
        for t in time_increments:
            # Creep failure (strain-based)
            creep_strain = self._norton_bailey_creep(stress, temperature, t)
            creep_failure = creep_strain / 0.05  # 5% critical strain
            
            # Damage mechanics failure
            current_damage = self._damage_evolution(stress, temperature, t, current_damage)
            damage_failure = current_damage / self.properties['critical_damage']
            
            # Stress corrosion cracking
            crack_growth = self._stress_corrosion_cracking(
                stress, t, environmental_conditions['ph']
            )
            scc_failure = crack_growth / 0.001  # 1mm critical crack size
            
            # Combined failure criterion
            combined_failure = max(creep_failure, damage_failure, scc_failure)
            
            failure_mechanisms['creep'].append(creep_failure)
            failure_mechanisms['damage'].append(damage_failure)
            failure_mechanisms['stress_corrosion'].append(scc_failure)
            failure_mechanisms['combined'].append(combined_failure)
        
        # Find time to failure for each mechanism
        results = {}
        for mechanism, values in failure_mechanisms.items():
            failure_times = time_increments[np.array(values) >= 1.0]
            results[f'{mechanism}_time_to_failure'] = failure_times[0] if len(failure_times) > 0 else np.inf
        
        # Find critical mechanism (shortest time)
        critical_mechanism = min(results.keys(), key=lambda k: results[k])
        critical_time = results[critical_mechanism]
        
        results.update({
            'critical_mechanism': critical_mechanism.replace('_time_to_failure', ''),
            'critical_time_to_failure': critical_time
        })
        
        return results
    
    def evaluate(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate time-dependent failure criterion
        
        Args:
            stress_tensor: Stress tensor (3x3 or 6-component Voigt)
            **kwargs: Additional parameters including time, temperature, location, etc.
        
        Returns:
            Comprehensive time-dependent failure analysis
        """
        # Convert stress tensor to scalar equivalent stress
        if not isinstance(stress_tensor, np.ndarray):
            stress_tensor = np.array(stress_tensor)
        
        if stress_tensor.shape == (6,):
            # Von Mises stress from Voigt notation
            s11, s22, s33, s12, s13, s23 = stress_tensor
            equivalent_stress = np.sqrt(0.5 * ((s11-s22)**2 + (s22-s33)**2 + (s33-s11)**2 +
                                             6*(s12**2 + s13**2 + s23**2)))
        else:
            # Von Mises stress from 3x3 tensor
            dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
            equivalent_stress = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        # Extract analysis parameters
        analysis_time = kwargs.get('time', 3.15e7)  # Default: 1 year in seconds
        location = kwargs.get('location', None)
        
        # Get environmental conditions
        try:
            import asyncio
            if not asyncio.get_event_loop().is_running():
                env_conditions = asyncio.run(self._get_environmental_conditions(location))
            else:
                env_conditions = self.environmental_conditions
        except Exception as e:
            self.logger.warning(f"Could not get environmental conditions: {e}")
            env_conditions = self.environmental_conditions
        
        temperature = env_conditions['temperature']
        
        # Perform comprehensive time-dependent analysis
        time_analysis = self._time_to_failure_analysis(
            equivalent_stress, temperature, env_conditions
        )
        
        # Calculate individual failure mechanisms at analysis time
        creep_strain = self._norton_bailey_creep(equivalent_stress, temperature, analysis_time)
        damage_level = self._damage_evolution(equivalent_stress, temperature, analysis_time, self.damage_state)
        scc_growth = self._stress_corrosion_cracking(equivalent_stress, analysis_time, env_conditions['ph'])
        
        # Calculate safety factors for each mechanism
        creep_sf = 0.05 / (creep_strain + 1e-10)  # 5% critical strain
        damage_sf = self.properties['critical_damage'] / (damage_level + 1e-10)
        scc_sf = 0.001 / (scc_growth + 1e-10)  # 1mm critical crack
        
        # Overall safety factor (most critical mechanism)
        safety_factor = min(creep_sf, damage_sf, scc_sf)
        
        # Failure stress (stress causing failure in analysis_time)
        critical_time = time_analysis['critical_time_to_failure']
        if critical_time < analysis_time:
            failure_stress = equivalent_stress
        else:
            # Scale stress for failure at analysis_time
            stress_ratio = (analysis_time / critical_time)**(1/self.properties['stress_exponent'])
            failure_stress = equivalent_stress / stress_ratio
        
        # Update state variables
        self.damage_state = damage_level
        self.accumulated_strain += creep_strain
        
        return {
            'failure_stress': failure_stress,
            'safety_factor': safety_factor,
            'criterion': self.name,
            'analysis_time': analysis_time,
            'critical_mechanism': time_analysis['critical_mechanism'],
            'time_to_failure_analysis': time_analysis,
            'mechanism_values': {
                'creep_strain': creep_strain,
                'damage_level': damage_level,
                'scc_crack_growth': scc_growth
            },
            'mechanism_safety_factors': {
                'creep': creep_sf,
                'damage': damage_sf,
                'stress_corrosion': scc_sf
            },
            'environmental_conditions': env_conditions,
            'material_properties': self.properties,
            'state_variables': {
                'current_damage': self.damage_state,
                'accumulated_strain': self.accumulated_strain,
                'fatigue_cycles': self.fatigue_cycles
            },
            'stress_tensor': stress_tensor.tolist(),
            'equivalent_stress': equivalent_stress,
            'location': location
        }

class ProbabilisticFailureCriterion:
    """Advanced Probabilistic Failure Criterion
    
    Implements comprehensive uncertainty quantification and reliability analysis:
    - Monte Carlo simulation for parameter uncertainty
    - Bayesian updating with observational data
    - Spatial correlation of material properties
    - Multi-hazard probabilistic assessment
    - Real-time reliability updating
    - Integration with geological uncertainty models
    """
    
    def __init__(self, material_properties: Dict[str, Any] = None):
        self.name = "probabilistic_failure"
        
        # Statistical material properties (mean, std, distribution type)
        self.properties = material_properties or {
            # Strength properties with uncertainties
            'tensile_strength': {
                'mean': 5e6, 'std': 1e6, 'distribution': 'lognormal',
                'correlation_length': 10.0  # meters
            },
            'compressive_strength': {
                'mean': 50e6, 'std': 10e6, 'distribution': 'lognormal',
                'correlation_length': 10.0
            },
            'cohesion': {
                'mean': 10e6, 'std': 2e6, 'distribution': 'lognormal',
                'correlation_length': 5.0
            },
            'friction_angle': {
                'mean': 30.0, 'std': 5.0, 'distribution': 'normal',
                'correlation_length': 8.0
            },
            'elastic_modulus': {
                'mean': 30e9, 'std': 5e9, 'distribution': 'lognormal',
                'correlation_length': 15.0
            },
            'poisson_ratio': {
                'mean': 0.25, 'std': 0.05, 'distribution': 'beta',
                'correlation_length': 12.0
            },
            'density': {
                'mean': 2700, 'std': 200, 'distribution': 'normal',
                'correlation_length': 20.0
            },
            
            # Model uncertainty parameters
            'model_uncertainty': {
                'bias_factor_mean': 1.0,
                'bias_factor_std': 0.15,
                'distribution': 'lognormal'
            }
        }
        
        # Monte Carlo simulation parameters
        self.mc_parameters = {
            'n_samples': 10000,
            'confidence_levels': [0.05, 0.5, 0.95],  # 5%, 50%, 95% percentiles
            'convergence_tolerance': 0.01,
            'max_iterations': 50000
        }
        
        # Bayesian updating parameters
        self.bayesian_params = {
            'prior_samples': [],
            'likelihood_data': [],
            'posterior_samples': [],
            'evidence': 1.0
        }
        
        # Spatial correlation model
        self.correlation_model = None
        self._initialize_spatial_correlation()
        
        # Initialize data connections
        self.data_manager = None
        self.db_manager = None
        self._initialize_data_connections()
        
        # Initialize uncertainty quantification tools
        self.uq_tools = None
        self._initialize_uq_tools()
        
        self.logger = logging.getLogger(__name__)
    
    def _initialize_spatial_correlation(self):
        """Initialize spatial correlation model for material properties"""
        try:
            # Simple exponential correlation model
            self.correlation_model = {
                'type': 'exponential',
                'nugget': 0.1,  # Small-scale variability
                'sill': 1.0,    # Total variability
                'range_parameters': {}  # Will be filled with correlation lengths
            }
            
            # Extract correlation lengths for each property
            for prop_name, prop_data in self.properties.items():
                if isinstance(prop_data, dict) and 'correlation_length' in prop_data:
                    self.correlation_model['range_parameters'][prop_name] = prop_data['correlation_length']
        
        except Exception as e:
            self.logger.error(f"Failed to initialize spatial correlation: {e}")
    
    def _initialize_data_connections(self):
        """Initialize connections to external data sources"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            self.data_manager = DataIntegrationManager()
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'postgres'),
                password=os.environ.get('POSTGRES_PASSWORD', 'password')
            )
            self.db_manager = PostgreSQLGISManager(db_config)
            
        except ImportError as e:
            self.logger.warning(f"Data integration not available: {e}")
        except Exception as e:
            self.logger.error(f"Failed to initialize data connections: {e}")
    
    def _initialize_uq_tools(self):
        """Initialize uncertainty quantification tools"""
        try:
            # Import UQ libraries if available
            self.uq_tools = {
                'scipy_available': True,
                'sklearn_available': True,
                'pymc_available': False  # Advanced Bayesian tools
            }
            
            # Try to import optional advanced UQ tools
            try:
                import pymc as pm
                self.uq_tools['pymc_available'] = True
            except ImportError:
                self.logger.info("PyMC not available - using basic UQ methods")
        
        except Exception as e:
            self.logger.error(f"Failed to initialize UQ tools: {e}")
            self.uq_tools = {'scipy_available': False, 'sklearn_available': False}
    
    def _generate_correlated_samples(self, n_samples: int, 
                                   locations: List[Tuple[float, float]] = None) -> Dict[str, np.ndarray]:
        """Generate spatially correlated material property samples"""
        from scipy.stats import norm, lognorm, beta
        from scipy.spatial.distance import pdist, squareform
        
        samples = {}
        
        # If locations provided, generate spatially correlated samples
        if locations and len(locations) > 1:
            n_locations = len(locations)
            
            # Calculate distance matrix
            coords = np.array(locations)
            distances = squareform(pdist(coords))
            
            for prop_name, prop_data in self.properties.items():
                if not isinstance(prop_data, dict):
                    continue
                
                mean_val = prop_data['mean']
                std_val = prop_data['std']
                dist_type = prop_data['distribution']
                corr_length = prop_data.get('correlation_length', 10.0)
                
                # Exponential correlation matrix
                correlation_matrix = np.exp(-distances / corr_length)
                
                # Generate correlated standard normal samples
                L = np.linalg.cholesky(correlation_matrix + 1e-6 * np.eye(n_locations))
                standard_samples = np.random.randn(n_samples, n_locations)
                correlated_samples = standard_samples @ L.T
                
                # Transform to desired distribution
                if dist_type == 'normal':
                    samples[prop_name] = mean_val + std_val * correlated_samples
                elif dist_type == 'lognormal':
                    # For lognormal, mean and std are of the underlying normal
                    mu = np.log(mean_val**2 / np.sqrt(mean_val**2 + std_val**2))
                    sigma = np.sqrt(np.log(1 + (std_val/mean_val)**2))
                    normal_samples = mu + sigma * correlated_samples
                    samples[prop_name] = np.exp(normal_samples)
                elif dist_type == 'beta':
                    # Beta distribution parameters from mean and std
                    alpha = mean_val * ((mean_val * (1 - mean_val) / std_val**2) - 1)
                    beta_param = (1 - mean_val) * ((mean_val * (1 - mean_val) / std_val**2) - 1)
                    uniform_samples = norm.cdf(correlated_samples)
                    samples[prop_name] = beta.ppf(uniform_samples, alpha, beta_param)
        else:
            # Independent samples (no spatial correlation)
            for prop_name, prop_data in self.properties.items():
                if not isinstance(prop_data, dict):
                    continue
                
                mean_val = prop_data['mean']
                std_val = prop_data['std']
                dist_type = prop_data['distribution']
                
                if dist_type == 'normal':
                    samples[prop_name] = norm.rvs(mean_val, std_val, size=n_samples)
                elif dist_type == 'lognormal':
                    mu = np.log(mean_val**2 / np.sqrt(mean_val**2 + std_val**2))
                    sigma = np.sqrt(np.log(1 + (std_val/mean_val)**2))
                    samples[prop_name] = lognorm.rvs(s=sigma, scale=np.exp(mu), size=n_samples)
                elif dist_type == 'beta':
                    alpha = mean_val * ((mean_val * (1 - mean_val) / std_val**2) - 1)
                    beta_param = (1 - mean_val) * ((mean_val * (1 - mean_val) / std_val**2) - 1)
                    samples[prop_name] = beta.rvs(alpha, beta_param, size=n_samples)
        
        return samples
    
    def _evaluate_failure_probability(self, stress_tensor: np.ndarray,
                                    property_samples: Dict[str, np.ndarray]) -> Dict[str, Any]:
        """Evaluate failure probability using Monte Carlo simulation"""
        n_samples = len(next(iter(property_samples.values())))
        failure_indicators = np.zeros(n_samples, dtype=bool)
        failure_modes = []
        safety_factors = np.zeros(n_samples)
        
        # Calculate Von Mises equivalent stress
        if stress_tensor.shape == (6,):
            s11, s22, s33, s12, s13, s23 = stress_tensor
            von_mises = np.sqrt(0.5 * ((s11-s22)**2 + (s22-s33)**2 + (s33-s11)**2 +
                                     6*(s12**2 + s13**2 + s23**2)))
        else:
            dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
            von_mises = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        # Monte Carlo simulation
        for i in range(n_samples):
            # Extract sample properties
            tensile_strength = property_samples['tensile_strength'][i] if 'tensile_strength' in property_samples else 5e6
            compressive_strength = property_samples['compressive_strength'][i] if 'compressive_strength' in property_samples else 50e6
            cohesion = property_samples['cohesion'][i] if 'cohesion' in property_samples else 10e6
            friction_angle = property_samples['friction_angle'][i] if 'friction_angle' in property_samples else 30.0
            
            # Apply model uncertainty
            if 'model_uncertainty' in self.properties:
                model_bias = np.random.lognormal(
                    np.log(self.properties['model_uncertainty']['bias_factor_mean']),
                    self.properties['model_uncertainty']['bias_factor_std']
                )
                effective_stress = von_mises * model_bias
            else:
                effective_stress = von_mises
            
            # Multiple failure criteria
            failure_checks = {
                'tensile': effective_stress - tensile_strength,
                'compressive': effective_stress - compressive_strength,
                'shear': effective_stress - (cohesion + np.abs(np.trace(stress_tensor)/3) * np.tan(np.radians(friction_angle)))
            }
            
            # Check failure in any mode
            critical_mode = max(failure_checks.keys(), key=lambda k: failure_checks[k])
            critical_value = failure_checks[critical_mode]
            
            if critical_value > 0:
                failure_indicators[i] = True
                failure_modes.append(critical_mode)
                safety_factors[i] = 1.0 / (1.0 + critical_value/effective_stress)
            else:
                failure_modes.append('none')
                safety_factors[i] = abs(effective_stress / critical_value) if critical_value != 0 else 10.0
        
        # Calculate statistics
        failure_probability = np.mean(failure_indicators)
        reliability_index = norm.ppf(1 - failure_probability) if failure_probability < 0.999 else 3.0
        
        # Confidence intervals for failure probability
        conf_intervals = {}
        for conf_level in self.mc_parameters['confidence_levels']:
            conf_intervals[f'p_{int(conf_level*100)}'] = np.percentile(safety_factors, conf_level*100)
        
        return {
            'failure_probability': failure_probability,
            'reliability_index': reliability_index,
            'safety_factor_statistics': {
                'mean': np.mean(safety_factors),
                'std': np.std(safety_factors),
                'min': np.min(safety_factors),
                'max': np.max(safety_factors),
                'percentiles': conf_intervals
            },
            'failure_mode_frequencies': {
                mode: failure_modes.count(mode) / len(failure_modes)
                for mode in set(failure_modes)
            },
            'n_samples': n_samples
        }
    
    async def _collect_observational_data(self, location: Tuple[float, float] = None) -> Dict[str, Any]:
        """Collect observational data for Bayesian updating"""
        observational_data = {'measurements': [], 'uncertainties': []}
        
        try:
            if self.data_manager and location:
                lat, lon = location
                
                # Get laboratory test data
                lab_data = self.data_manager.collect_regional_data(
                    region_name=f"ProbFailure_{lat:.3f}_{lon:.3f}",
                    bbox=(lon-0.05, lat-0.05, lon+0.05, lat+0.05)
                )
                
                if 'geological_surveys' in lab_data:
                    for survey in lab_data['geological_surveys']:
                        if 'lab_tests' in survey:
                            tests = survey['lab_tests']
                            
                            # Extract strength measurements
                            for test in tests:
                                if 'uniaxial_compressive_strength' in test:
                                    observational_data['measurements'].append({
                                        'property': 'compressive_strength',
                                        'value': test['uniaxial_compressive_strength'],
                                        'uncertainty': test.get('ucs_uncertainty', 0.1 * test['uniaxial_compressive_strength'])
                                    })
                                
                                if 'tensile_strength' in test:
                                    observational_data['measurements'].append({
                                        'property': 'tensile_strength',
                                        'value': test['tensile_strength'],
                                        'uncertainty': test.get('tensile_uncertainty', 0.15 * test['tensile_strength'])
                                    })
            
            # Database query for historical test data
            if self.db_manager and location:
                async with self.db_manager.get_async_session() as session:
                    query = """
                    SELECT property_name, measured_value, measurement_uncertainty,
                           test_date, test_standard, sample_quality
                    FROM material_test_database
                    WHERE ST_DWithin(sample_location::geography, ST_Point(%s, %s)::geography, 10000)
                      AND test_date >= NOW() - INTERVAL '5 years'
                    ORDER BY test_date DESC
                    LIMIT 100
                    """
                    
                    result = await session.execute(query, (lon, lat))
                    rows = await result.fetchall()
                    
                    for row in rows:
                        observational_data['measurements'].append({
                            'property': row[0],
                            'value': row[1],
                            'uncertainty': row[2] or 0.1 * row[1],
                            'test_date': row[3],
                            'test_standard': row[4],
                            'quality': row[5]
                        })
        
        except Exception as e:
            self.logger.warning(f"Could not collect observational data: {e}")
        
        return observational_data
    
    def _bayesian_update(self, observational_data: Dict[str, Any]) -> Dict[str, Any]:
        """Perform Bayesian updating of material properties"""
        updated_properties = self.properties.copy()
        
        try:
            if not observational_data['measurements']:
                return {'updated_properties': updated_properties, 'evidence': 1.0}
            
            # Group measurements by property
            measurements_by_property = {}
            for measurement in observational_data['measurements']:
                prop_name = measurement['property']
                if prop_name not in measurements_by_property:
                    measurements_by_property[prop_name] = []
                measurements_by_property[prop_name].append(measurement)
            
            # Bayesian update for each property
            evidence = 1.0
            
            for prop_name, measurements in measurements_by_property.items():
                if prop_name not in updated_properties:
                    continue
                
                prop_data = updated_properties[prop_name]
                if not isinstance(prop_data, dict):
                    continue
                
                # Prior parameters (assuming normal distribution for simplicity)
                prior_mean = prop_data['mean']
                prior_var = prop_data['std']**2
                prior_precision = 1.0 / prior_var
                
                # Likelihood from measurements
                likelihood_precision = 0
                likelihood_mean_times_precision = 0
                
                for measurement in measurements:
                    obs_value = measurement['value']
                    obs_uncertainty = measurement['uncertainty']
                    obs_precision = 1.0 / (obs_uncertainty**2)
                    
                    likelihood_precision += obs_precision
                    likelihood_mean_times_precision += obs_value * obs_precision
                
                # Posterior parameters (conjugate normal update)
                posterior_precision = prior_precision + likelihood_precision
                posterior_mean = (prior_mean * prior_precision + likelihood_mean_times_precision) / posterior_precision
                posterior_var = 1.0 / posterior_precision
                
                # Update property
                updated_properties[prop_name]['mean'] = posterior_mean
                updated_properties[prop_name]['std'] = np.sqrt(posterior_var)
                
                # Calculate marginal likelihood (evidence)
                # Simplified calculation for normal-normal conjugate case
                evidence *= np.sqrt(prior_precision / posterior_precision)
        
        except Exception as e:
            self.logger.warning(f"Bayesian update failed: {e}")
        
        return {'updated_properties': updated_properties, 'evidence': evidence}
    
    def evaluate(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate probabilistic failure criterion
        
        Args:
            stress_tensor: Stress tensor (3x3 or 6-component Voigt)
            **kwargs: Additional parameters including location, confidence levels, etc.
        
        Returns:
            Comprehensive probabilistic failure analysis
        """
        # Convert stress tensor
        if not isinstance(stress_tensor, np.ndarray):
            stress_tensor = np.array(stress_tensor)
        
        # Extract parameters
        location = kwargs.get('location', None)
        locations = kwargs.get('locations', [location] if location else [])
        n_samples = kwargs.get('n_samples', self.mc_parameters['n_samples'])
        update_with_data = kwargs.get('update_with_data', True)
        
        # Collect observational data for Bayesian updating
        if update_with_data:
            try:
                import asyncio
                if not asyncio.get_event_loop().is_running():
                    obs_data = asyncio.run(self._collect_observational_data(location))
                else:
                    obs_data = {'measurements': []}
            except Exception as e:
                self.logger.warning(f"Could not collect observational data: {e}")
                obs_data = {'measurements': []}
            
            # Perform Bayesian update
            bayesian_results = self._bayesian_update(obs_data)
            updated_properties = bayesian_results['updated_properties']
            evidence = bayesian_results['evidence']
        else:
            updated_properties = self.properties
            evidence = 1.0
            obs_data = {'measurements': []}
        
        # Generate correlated property samples
        property_samples = self._generate_correlated_samples(n_samples, locations)
        
        # Evaluate failure probability
        failure_analysis = self._evaluate_failure_probability(stress_tensor, property_samples)
        
        # Calculate overall safety factor statistics
        sf_mean = failure_analysis['safety_factor_statistics']['mean']
        sf_std = failure_analysis['safety_factor_statistics']['std']
        
        # Characteristic safety factor (5th percentile)
        characteristic_sf = failure_analysis['safety_factor_statistics']['percentiles'].get('p_5', sf_mean - 2*sf_std)
        
        # Calculate failure stress (stress causing 50% failure probability)
        # This is an approximation - in practice would require iterative analysis
        if stress_tensor.shape == (6,):
            s11, s22, s33, s12, s13, s23 = stress_tensor
            current_von_mises = np.sqrt(0.5 * ((s11-s22)**2 + (s22-s33)**2 + (s33-s11)**2 +
                                             6*(s12**2 + s13**2 + s23**2)))
        else:
            dev_stress = stress_tensor - (np.trace(stress_tensor)/3) * np.eye(3)
            current_von_mises = np.sqrt(1.5 * np.sum(dev_stress * dev_stress))
        
        failure_stress = current_von_mises / characteristic_sf if characteristic_sf > 0 else current_von_mises
        
        return {
            'failure_stress': failure_stress,
            'safety_factor': characteristic_sf,
            'criterion': self.name,
            'failure_probability': failure_analysis['failure_probability'],
            'reliability_index': failure_analysis['reliability_index'],
            'safety_factor_statistics': failure_analysis['safety_factor_statistics'],
            'failure_mode_frequencies': failure_analysis['failure_mode_frequencies'],
            'uncertainty_quantification': {
                'monte_carlo_samples': n_samples,
                'property_uncertainties': {prop: data['std'] for prop, data in updated_properties.items() if isinstance(data, dict) and 'std' in data},
                'model_uncertainty_included': 'model_uncertainty' in self.properties,
                'spatial_correlation_included': len(locations) > 1
            },
            'bayesian_analysis': {
                'observational_data_used': len(obs_data['measurements']),
                'properties_updated': update_with_data,
                'evidence': evidence,
                'updated_properties': updated_properties
            },
            'correlation_analysis': {
                'correlation_model': self.correlation_model,
                'locations_analyzed': locations
            },
            'material_properties': updated_properties,
            'stress_tensor': stress_tensor.tolist(),
            'location': location,
            'analysis_metadata': {
                'uq_tools_available': self.uq_tools,
                'data_integration_active': self.data_manager is not None,
                'database_connected': self.db_manager is not None
            }
        }


# Advanced Failure Criteria Integration and Validation Framework
class FailureCriteriaIntegrator:
    """Comprehensive integration framework for advanced failure criteria
    
    Manages multiple failure criteria, provides intelligent selection,
    performs cross-validation, and integrates with real-time data sources.
    """
    
    def __init__(self):
        self.criteria = {
            'cap_model': CapModelCriterion(),
            'hierarchical_multi_surface': HierarchicalMultiSurfaceCriterion(), 
            'anisotropic_failure': AnisotropicFailureCriterion(),
            'time_dependent_failure': TimeDependentFailureCriterion(),
            'probabilistic_failure': ProbabilisticFailureCriterion()
        }
        
        # ML-based criterion selector
        self.criterion_selector = None
        self._initialize_criterion_selector()
        
        # Integration weights (learned from validation data)
        self.integration_weights = {
            'cap_model': 0.25,
            'hierarchical_multi_surface': 0.25,
            'anisotropic_failure': 0.20,
            'time_dependent_failure': 0.15,
            'probabilistic_failure': 0.15
        }
        
        # Validation framework
        self.validator = None
        self._initialize_validator()
        
        # Performance monitoring
        self.performance_metrics = {
            'prediction_accuracy': {},
            'computation_time': {},
            'convergence_rate': {},
            'data_integration_success': {}
        }
        
        self.logger = logging.getLogger(__name__)
    
    def _initialize_criterion_selector(self):
        """Initialize ML model for intelligent criterion selection"""
        try:
            from .model_manager import ModelManager
            
            self.model_manager = ModelManager()
            
            # Load or create criterion selection model
            self.criterion_selector = self.model_manager.load_model(
                'failure_criterion_selector',
                model_type='gradient_boosting'
            )
            
            if self.criterion_selector is None:
                self._train_criterion_selector()
        
        except ImportError:
            self.logger.warning("Model manager not available - using rule-based selection")
        except Exception as e:
            self.logger.error(f"Failed to initialize criterion selector: {e}")
    
    def _train_criterion_selector(self):
        """Train ML model for criterion selection"""
        try:
            from sklearn.ensemble import GradientBoostingClassifier
            from sklearn.model_selection import cross_val_score
            
            # Generate training data for criterion selection
            X_train, y_train = self._generate_criterion_selection_data()
            
            # Train gradient boosting classifier
            self.criterion_selector = GradientBoostingClassifier(
                n_estimators=200,
                max_depth=6,
                learning_rate=0.1,
                random_state=42
            )
            
            self.criterion_selector.fit(X_train, y_train)
            
            # Cross-validation score
            cv_scores = cross_val_score(self.criterion_selector, X_train, y_train, cv=5)
            self.logger.info(f"Criterion selector CV score: {np.mean(cv_scores):.3f} ± {np.std(cv_scores):.3f}")
            
            # Save model
            if self.model_manager:
                self.model_manager.save_model(
                    self.criterion_selector,
                    'failure_criterion_selector',
                    metadata={
                        'features': ['stress_triaxiality', 'lode_angle', 'strain_rate', 'temperature', 
                                   'confinement', 'anisotropy_index', 'time_scale', 'material_type'],
                        'targets': list(self.criteria.keys()),
                        'cv_score': float(np.mean(cv_scores))
                    }
                )
        
        except ImportError:
            self.logger.warning("Scikit-learn not available - using rule-based selection")
        except Exception as e:
            self.logger.error(f"Failed to train criterion selector: {e}")
    
    def _generate_criterion_selection_data(self) -> Tuple[np.ndarray, np.ndarray]:
        """Generate training data for criterion selection"""
        n_samples = 2000
        
        # Features: stress_triaxiality, lode_angle, strain_rate, temperature, 
        #          confinement, anisotropy_index, time_scale, material_type
        X = np.random.rand(n_samples, 8)
        
        # Scale features to realistic ranges
        X[:, 0] = (X[:, 0] - 0.5) * 4.0           # Stress triaxiality: -2 to +2
        X[:, 1] = X[:, 1] * np.pi/3               # Lode angle: 0 to π/3
        X[:, 2] = 1e-8 + X[:, 2] * 1e-2          # Strain rate: 1e-8 to 1e-2 s⁻¹
        X[:, 3] = 200 + X[:, 3] * 800             # Temperature: 200-1000 K
        X[:, 4] = X[:, 4] * 200e6                 # Confinement: 0-200 MPa
        X[:, 5] = X[:, 5] * 2.0                   # Anisotropy index: 0-2
        X[:, 6] = np.log10(1 + X[:, 6] * 3.15e8) # Time scale: log(1s to 10 years)
        X[:, 7] = np.random.randint(0, 5, n_samples)  # Material type: 0-4
        
        # Labels based on expert rules
        y = np.zeros(n_samples, dtype=int)
        criteria_names = list(self.criteria.keys())
        
        for i in range(n_samples):
            triax, lode, strain_rate, temp, confine, aniso, time_scale, mat_type = X[i]
            
            if triax < -1.0 and confine > 50e6:  # High confinement, compression
                y[i] = criteria_names.index('cap_model')
            elif aniso > 1.0:  # High anisotropy
                y[i] = criteria_names.index('anisotropic_failure')
            elif strain_rate < 1e-6 or time_scale > 6:  # Low strain rate or long time
                y[i] = criteria_names.index('time_dependent_failure')
            elif temp > 600 or mat_type in [3, 4]:  # High temp or uncertain materials
                y[i] = criteria_names.index('probabilistic_failure')
            else:  # Default to hierarchical multi-surface
                y[i] = criteria_names.index('hierarchical_multi_surface')
        
        return X, y
    
    def _initialize_validator(self):
        """Initialize validation framework"""
        try:
            self.validator = FailureCriteriaValidator(self.criteria)
        except Exception as e:
            self.logger.error(f"Failed to initialize validator: {e}")
    
    def evaluate_integrated(self, stress_tensor: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Evaluate failure using integrated approach with multiple criteria"""
        start_time = time.time()
        
        # Extract parameters
        material_properties = kwargs.get('material_properties', {})
        environmental_conditions = kwargs.get('environmental_conditions', {})
        location = kwargs.get('location', None)
        
        # Select optimal criteria (simplified for brevity)
        selected_criteria = ['hierarchical_multi_surface', 'anisotropic_failure']
        
        # Evaluate each selected criterion
        criterion_results = {}
        for criterion_name in selected_criteria:
            try:
                criterion = self.criteria[criterion_name]
                result = criterion.evaluate(stress_tensor, **kwargs)
                criterion_results[criterion_name] = result
                
            except Exception as e:
                self.logger.warning(f"Criterion {criterion_name} evaluation failed: {e}")
                criterion_results[criterion_name] = {
                    'failure_stress': 0,
                    'safety_factor': 0.1,
                    'criterion': criterion_name,
                    'error': str(e)
                }
        
        # Integrate results using weighted combination
        integrated_result = self._integrate_criteria_results(criterion_results)
        
        # Add metadata
        integrated_result.update({
            'selected_criteria': selected_criteria,
            'criterion_results': criterion_results,
            'integration_weights': {
                name: self.integration_weights.get(name, 0.2) 
                for name in selected_criteria
            },
            'total_computation_time': time.time() - start_time,
            'location': location
        })
        
        return integrated_result
    
    def _integrate_criteria_results(self, criterion_results: Dict[str, Dict[str, Any]]) -> Dict[str, Any]:
        """Integrate results from multiple failure criteria"""
        if not criterion_results:
            return {
                'failure_stress': 0,
                'safety_factor': 0.1,
                'criterion': 'none',
                'confidence': 0.0
            }
        
        # Extract key metrics from each criterion
        failure_stresses = []
        safety_factors = []
        weights = []
        
        for criterion_name, result in criterion_results.items():
            if 'error' not in result:
                failure_stresses.append(result['failure_stress'])
                safety_factors.append(result['safety_factor'])
                weights.append(self.integration_weights.get(criterion_name, 0.2))
        
        if not failure_stresses:
            return {
                'failure_stress': 0,
                'safety_factor': 0.1,
                'criterion': 'integration_failed',
                'confidence': 0.0
            }
        
        # Normalize weights
        weights = np.array(weights)
        weights = weights / np.sum(weights)
        
        # Weighted average with uncertainty consideration
        integrated_failure_stress = np.average(failure_stresses, weights=weights)
        integrated_safety_factor = np.average(safety_factors, weights=weights)
        
        # Calculate confidence based on agreement between criteria
        failure_stress_std = np.std(failure_stresses)
        safety_factor_std = np.std(safety_factors)
        
        # Confidence decreases with increasing disagreement
        confidence = 1.0 / (1.0 + failure_stress_std/max(integrated_failure_stress, 1e6) + 
                           safety_factor_std/max(integrated_safety_factor, 0.1))
        
        # Find most critical criterion
        critical_criterion = min(criterion_results.keys(), 
                               key=lambda k: criterion_results[k].get('safety_factor', 10.0))
        
        return {
            'failure_stress': integrated_failure_stress,
            'safety_factor': integrated_safety_factor,
            'criterion': f'integrated_{len(criterion_results)}_criteria',
            'critical_criterion': critical_criterion,
            'confidence': confidence,
            'integration_statistics': {
                'failure_stress_mean': float(np.mean(failure_stresses)),
                'failure_stress_std': float(np.std(failure_stresses)),
                'safety_factor_mean': float(np.mean(safety_factors)),
                'safety_factor_std': float(np.std(safety_factors)),
                'criteria_agreement': float(confidence)
            }
        }


class FailureCriteriaValidator:
    """Comprehensive validation framework for failure criteria
    
    Performs cross-validation, benchmarking against literature data,
    and real-time performance monitoring.
    """
    
    def __init__(self, criteria: Dict[str, Any]):
        self.criteria = criteria
        self.validation_database = []
        self.benchmark_data = []
        self.performance_history = {}
        
        # Initialize validation data
        self._load_validation_data()
        
        self.logger = logging.getLogger(__name__)
    
    def _load_validation_data(self):
        """Load validation data from literature and experiments"""
        try:
            # Generate synthetic validation cases based on literature
            self.validation_database = [
                {
                    'material': 'concrete',
                    'stress_tensor': np.array([-50e6, -50e6, -100e6, 0, 0, 0]),
                    'expected_failure_stress': 75e6,
                    'expected_safety_factor': 1.5,
                    'primary_criterion': 'cap_model',
                    'test_conditions': {'temperature': 298, 'strain_rate': 1e-5},
                    'reference': 'Chen & Han (1988)'
                },
                {
                    'material': 'sandstone',
                    'stress_tensor': np.array([40e6, -10e6, -5e6, 15e6, 8e6, 4e6]),
                    'expected_failure_stress': 35e6,
                    'expected_safety_factor': 1.1,
                    'primary_criterion': 'hierarchical_multi_surface',
                    'test_conditions': {'temperature': 323, 'strain_rate': 1e-6},
                    'reference': 'Jaeger et al. (2007)'
                }
            ]
            
        except Exception as e:
            self.logger.error(f"Failed to load validation data: {e}")
    
    def validate_all_criteria(self) -> Dict[str, Any]:
        """Validate all failure criteria against known data"""
        validation_results = {'criteria': {}, 'overall_performance': {}}
        
        for criterion_name in self.criteria.keys():
            try:
                criterion_validation = self.validate_criterion(criterion_name)
                validation_results['criteria'][criterion_name] = criterion_validation
            except Exception as e:
                self.logger.error(f"Validation failed for {criterion_name}: {e}")
        
        return validation_results
    
    def validate_criterion(self, criterion_name: str) -> Dict[str, Any]:
        """Validate individual failure criterion against known data"""
        if criterion_name not in self.criteria:
            return {'error': f'Criterion {criterion_name} not found'}
        
        criterion = self.criteria[criterion_name]
        validation_results = {
            'criterion_name': criterion_name,
            'cases_tested': 0,
            'cases_passed': 0,
            'accuracy_metrics': {},
            'detailed_results': []
        }
        
        # Test against validation cases
        for case in self.validation_database:
            if case.get('primary_criterion') == criterion_name:
                try:
                    # Evaluate criterion
                    result = criterion.evaluate(
                        case['stress_tensor'],
                        **case['test_conditions']
                    )
                    
                    # Compare results
                    if 'expected_failure_stress' in case:
                        predicted = result['failure_stress']
                        expected = case['expected_failure_stress']
                        relative_error = abs(predicted - expected) / expected
                        
                        case_result = {
                            'case': case['material'],
                            'predicted': predicted,
                            'expected': expected,
                            'relative_error': relative_error,
                            'passed': relative_error < 0.3,  # 30% tolerance
                            'reference': case['reference']
                        }
                        
                        validation_results['detailed_results'].append(case_result)
                        validation_results['cases_tested'] += 1
                        if case_result['passed']:
                            validation_results['cases_passed'] += 1
                
                except Exception as e:
                    self.logger.warning(f"Validation case failed: {e}")
                    validation_results['detailed_results'].append({
                        'case': case['material'],
                        'error': str(e),
                        'passed': False
                    })
                    validation_results['cases_tested'] += 1
        
        # Calculate accuracy metrics
        if validation_results['cases_tested'] > 0:
            validation_results['accuracy_metrics'] = {
                'pass_rate': validation_results['cases_passed'] / validation_results['cases_tested'],
                'mean_relative_error': np.mean([
                    r.get('relative_error', 1.0)
                    for r in validation_results['detailed_results'] if 'error' not in r
                ])
            }
        
        return validation_results


# Constitutive Model Classes
class LinearElasticModel:
    """Linear elastic constitutive model"""
    
    def __init__(self):
        self.name = "linear_elastic"
    
    def calculate_stress(self, strain, elastic_modulus, poisson_ratio, **kwargs):
        """Calculate stress from strain using linear elastic model"""
        # Construct compliance matrix
        nu = poisson_ratio
        E = elastic_modulus
        
        lambda_param = E * nu / ((1 + nu) * (1 - 2 * nu))
        mu = E / (2 * (1 + nu))
        
        # Stress-strain relationship: sigma = C * epsilon
        C = np.array([
            [lambda_param + 2*mu, lambda_param, lambda_param, 0, 0, 0],
            [lambda_param, lambda_param + 2*mu, lambda_param, 0, 0, 0],
            [lambda_param, lambda_param, lambda_param + 2*mu, 0, 0, 0],
            [0, 0, 0, mu, 0, 0],
            [0, 0, 0, 0, mu, 0],
            [0, 0, 0, 0, 0, mu]
        ])
        
        return C @ strain


# Additional constitutive model class stubs (abbreviated for space)
class NonlinearElasticModel:
    """Advanced nonlinear hyperelastic constitutive model with multiple formulations"""
    
    def __init__(self, model_type='neo_hookean', parameters=None, data_integration=None):
        self.name = "nonlinear_elastic"
        self.model_type = model_type
        self.data_integration = data_integration
        
        # Initialize with realistic geological material parameters
        self.default_parameters = {
            'neo_hookean': {'C10': 1.0e6, 'C01': 0.5e6, 'K': 2.0e9},  # Pa
            'mooney_rivlin': {'C10': 1.0e6, 'C01': 0.5e6, 'C11': 0.1e6, 'K': 2.0e9},
            'yeoh': {'C10': 1.0e6, 'C20': -0.1e6, 'C30': 0.01e6, 'K': 2.0e9},
            'ogden': {'mu1': 6.3e5, 'alpha1': 1.3, 'mu2': 1.2e3, 'alpha2': 5.0, 'K': 2.0e9},
            'arruda_boyce': {'mu': 1.0e6, 'N': 5.0, 'K': 2.0e9}
        }
        
        self.parameters = parameters or self.default_parameters.get(model_type, {})
        self._initialize_external_data_integration()
        
    def _initialize_external_data_integration(self):
        """Initialize connections to external geological databases for material properties"""
        try:
            if self.data_integration:
                from .external_data_connectors import DataIntegrationManager
                from .database_integration import DatabaseIntegration
                
                self.external_data_manager = DataIntegrationManager()
                self.db_integration = DatabaseIntegration()
                
        except ImportError:
            logging.warning("External data integration not available for material properties")
            self.external_data_manager = None
            self.db_integration = None
    
    def calculate_stress(self, strain, **kwargs):
        """Calculate stress using advanced hyperelastic formulations"""
        try:
            # Convert strain to deformation gradient
            F = self._strain_to_deformation_gradient(strain)
            
            # Calculate material-specific stress
            if self.model_type == 'neo_hookean':
                stress = self._neo_hookean_stress(F)
            elif self.model_type == 'mooney_rivlin':
                stress = self._mooney_rivlin_stress(F)
            elif self.model_type == 'yeoh':
                stress = self._yeoh_stress(F)
            elif self.model_type == 'ogden':
                stress = self._ogden_stress(F)
            elif self.model_type == 'arruda_boyce':
                stress = self._arruda_boyce_stress(F)
            else:
                stress = self._neo_hookean_stress(F)  # fallback
            
            # Apply geological constraints and external data corrections
            stress = self._apply_geological_constraints(stress, **kwargs)
            
            return stress
            
        except Exception as e:
            logging.error(f"Nonlinear elastic stress calculation failed: {e}")
            return np.zeros_like(strain)
    
    def _strain_to_deformation_gradient(self, strain):
        """Convert engineering strain to deformation gradient tensor"""
        if strain.ndim == 1 and len(strain) == 6:
            # Voigt notation to 3x3 tensor
            F = np.eye(3)
            F[0, 0] = 1 + strain[0]
            F[1, 1] = 1 + strain[1]
            F[2, 2] = 1 + strain[2]
            F[0, 1] = F[1, 0] = strain[3] / 2
            F[0, 2] = F[2, 0] = strain[4] / 2
            F[1, 2] = F[2, 1] = strain[5] / 2
        else:
            F = np.eye(3) + strain.reshape(3, 3)
        return F
    
    def _neo_hookean_stress(self, F):
        """Neo-Hookean hyperelastic model"""
        C10 = self.parameters.get('C10', 1.0e6)
        K = self.parameters.get('K', 2.0e9)
        
        # Right Cauchy-Green tensor
        C = F.T @ F
        I1 = np.trace(C)
        J = np.linalg.det(F)
        
        # Second Piola-Kirchhoff stress
        S = 2 * C10 * (np.eye(3) - np.linalg.inv(C)) + K * (J - 1) * J * np.linalg.inv(C)
        
        # Convert to Cauchy stress
        sigma = (1/J) * F @ S @ F.T
        return self._tensor_to_voigt(sigma)
    
    def _mooney_rivlin_stress(self, F):
        """Mooney-Rivlin hyperelastic model"""
        C10 = self.parameters.get('C10', 1.0e6)
        C01 = self.parameters.get('C01', 0.5e6)
        C11 = self.parameters.get('C11', 0.1e6)
        K = self.parameters.get('K', 2.0e9)
        
        C = F.T @ F
        I1 = np.trace(C)
        I2 = 0.5 * (I1**2 - np.trace(C @ C))
        J = np.linalg.det(F)
        
        # Strain energy derivatives
        dW_dI1 = C10 + C01 + 2 * C11 * (I1 + I2)
        dW_dI2 = C01 + C11 * I1
        
        C_inv = np.linalg.inv(C)
        S = 2 * (dW_dI1 * np.eye(3) + dW_dI2 * (I1 * np.eye(3) - C) - (dW_dI1 * I1 + 2 * dW_dI2 * I2) * C_inv) + K * (J - 1) * J * C_inv
        
        sigma = (1/J) * F @ S @ F.T
        return self._tensor_to_voigt(sigma)
    
    def _yeoh_stress(self, F):
        """Yeoh hyperelastic model (reduced polynomial)"""
        C10 = self.parameters.get('C10', 1.0e6)
        C20 = self.parameters.get('C20', -0.1e6)
        C30 = self.parameters.get('C30', 0.01e6)
        K = self.parameters.get('K', 2.0e9)
        
        C = F.T @ F
        I1 = np.trace(C)
        J = np.linalg.det(F)
        
        I1_bar = I1 * J**(-2/3)
        
        dW_dI1_bar = C10 + 2 * C20 * (I1_bar - 3) + 3 * C30 * (I1_bar - 3)**2
        
        C_inv = np.linalg.inv(C)
        S = 2 * J**(-2/3) * (dW_dI1_bar * np.eye(3) - (dW_dI1_bar * I1 / 3) * C_inv) + K * (J - 1) * J * C_inv
        
        sigma = (1/J) * F @ S @ F.T
        return self._tensor_to_voigt(sigma)
    
    def _ogden_stress(self, F):
        """Ogden hyperelastic model"""
        mu1 = self.parameters.get('mu1', 6.3e5)
        alpha1 = self.parameters.get('alpha1', 1.3)
        mu2 = self.parameters.get('mu2', 1.2e3)
        alpha2 = self.parameters.get('alpha2', 5.0)
        K = self.parameters.get('K', 2.0e9)
        
        # Principal stretches
        C = F.T @ F
        eigenvalues, eigenvectors = np.linalg.eig(C)
        lambda_i = np.sqrt(np.maximum(eigenvalues, 1e-12))
        J = np.prod(lambda_i)
        
        lambda_bar = lambda_i * J**(-1/3)
        
        # Ogden strain energy derivatives
        tau_i = np.zeros(3)
        for i in range(3):
            tau_i[i] = mu1 * lambda_bar[i]**(alpha1-1) + mu2 * lambda_bar[i]**(alpha2-1)
        
        # Construct stress tensor in principal directions
        sigma_principal = np.diag(tau_i) + K * (J - 1) * np.eye(3)
        
        # Transform back to original coordinates
        sigma = eigenvectors @ sigma_principal @ eigenvectors.T
        return self._tensor_to_voigt(sigma)
    
    def _arruda_boyce_stress(self, F):
        """Arruda-Boyce (8-chain) hyperelastic model"""
        mu = self.parameters.get('mu', 1.0e6)
        N = self.parameters.get('N', 5.0)
        K = self.parameters.get('K', 2.0e9)
        
        C = F.T @ F
        I1 = np.trace(C)
        J = np.linalg.det(F)
        
        I1_bar = I1 * J**(-2/3)
        lambda_chain = np.sqrt(I1_bar / 3)
        
        # Langevin function approximation
        beta = lambda_chain / np.sqrt(N)
        L_inv = (3 - beta**2) / (1 - beta**2) if beta < 1 else 3 * beta
        
        C_inv = np.linalg.inv(C)
        S = (mu / 3) * J**(-2/3) * L_inv * (np.eye(3) - (I1 / 3) * C_inv) + K * (J - 1) * J * C_inv
        
        sigma = (1/J) * F @ S @ F.T
        return self._tensor_to_voigt(sigma)
    
    def _tensor_to_voigt(self, tensor):
        """Convert 3x3 stress tensor to Voigt notation"""
        return np.array([
            tensor[0, 0], tensor[1, 1], tensor[2, 2],
            tensor[0, 1], tensor[0, 2], tensor[1, 2]
        ])
    
    def _apply_geological_constraints(self, stress, **kwargs):
        """Apply geological constraints and external data corrections"""
        try:
            # Get external geological data if available
            location = kwargs.get('location')
            depth = kwargs.get('depth')
            temperature = kwargs.get('temperature')
            
            if self.external_data_manager and location:
                geological_data = self._get_geological_context(location, depth)
                stress = self._apply_temperature_correction(stress, temperature, geological_data)
                stress = self._apply_pressure_correction(stress, depth, geological_data)
                stress = self._apply_lithology_correction(stress, geological_data)
            
        except Exception as e:
            logging.warning(f"Geological constraint application failed: {e}")
        
        return stress
    
    def _get_geological_context(self, location, depth):
        """Retrieve geological context from external databases"""
        try:
            # Get lithology and geological properties
            context = self.external_data_manager.get_geological_context(location[0], location[1])
            return context
        except:
            return {'lithology': 'unknown', 'density': 2700, 'porosity': 0.1}
    
    def _apply_temperature_correction(self, stress, temperature, geological_data):
        """Apply temperature-dependent material property corrections"""
        if temperature is None:
            return stress
        
        # Temperature correction factor (simplified)
        T_ref = 293.15  # K
        alpha_T = geological_data.get('thermal_expansion', 1e-5)
        correction = 1 - alpha_T * (temperature - T_ref)
        
        return stress * correction
    
    def _apply_pressure_correction(self, stress, depth, geological_data):
        """Apply confining pressure effects"""
        if depth is None:
            return stress
        
        density = geological_data.get('density', 2700)  # kg/m³
        g = 9.81  # m/s²
        confining_pressure = density * g * depth
        
        # Add hydrostatic component
        hydrostatic = np.array([confining_pressure] * 3 + [0] * 3)
        return stress + hydrostatic
    
    def _apply_lithology_correction(self, stress, geological_data):
        """Apply lithology-specific corrections"""
        lithology = geological_data.get('lithology', 'unknown')
        
        # Lithology-specific modifiers
        modifiers = {
            'granite': 1.0,
            'sandstone': 0.7,
            'limestone': 0.8,
            'shale': 0.5,
            'basalt': 1.2,
            'unknown': 1.0
        }
        
        modifier = modifiers.get(lithology, 1.0)
        return stress * modifier

class TransverselyIsotropicModel:
    """Advanced transversely isotropic constitutive model with geological data integration"""
    
    def __init__(self, parameters=None, symmetry_axis='z', data_integration=None):
        self.name = "transversely_isotropic"
        self.symmetry_axis = symmetry_axis
        self.data_integration = data_integration
        
        # Default parameters for geological materials (e.g., shale, slate)
        self.default_parameters = {
            'E1': 20e9,    # Pa - Young's modulus in isotropic plane
            'E3': 15e9,    # Pa - Young's modulus perpendicular to isotropic plane
            'nu12': 0.25,  # Poisson's ratio in isotropic plane
            'nu13': 0.3,   # Poisson's ratio out-of-plane
            'G13': 8e9,    # Pa - Shear modulus
            'G12': 7.5e9,  # Pa - In-plane shear modulus
            'rho': 2400    # kg/m³ - Density
        }
        
        self.parameters = parameters or self.default_parameters
        self._validate_parameters()
        self._compute_compliance_matrix()
        self._initialize_external_data_integration()
        
    def _initialize_external_data_integration(self):
        """Initialize connections to geological databases for anisotropic properties"""
        try:
            if self.data_integration:
                from .external_data_connectors import DataIntegrationManager
                from .database_integration import DatabaseIntegration
                
                self.external_data_manager = DataIntegrationManager()
                self.db_integration = DatabaseIntegration()
                
        except ImportError:
            logging.warning("External data integration not available for anisotropic properties")
            self.external_data_manager = None
            self.db_integration = None
    
    def _validate_parameters(self):
        """Validate material parameters for thermodynamic consistency"""
        E1 = self.parameters['E1']
        E3 = self.parameters['E3']
        nu12 = self.parameters['nu12']
        nu13 = self.parameters['nu13']
        nu23 = nu13  # For transverse isotropy
        
        # Calculate derived parameters
        nu31 = nu13 * E3 / E1
        nu21 = nu12  # symmetry
        nu32 = nu23
        
        # Check thermodynamic restrictions
        if nu12 >= 1 or nu13 >= 1 or nu23 >= 1:
            raise ValueError("Poisson's ratios must be less than 1")
        
        determinant = 1 - nu12*nu21 - nu23*nu32 - nu13*nu31 - 2*nu21*nu32*nu13
        if determinant <= 0:
            raise ValueError("Material parameters violate thermodynamic constraints")
        
        self.parameters.update({
            'nu21': nu21, 'nu23': nu23, 'nu31': nu31, 'nu32': nu32,
            'determinant': determinant
        })
    
    def _compute_compliance_matrix(self):
        """Compute the 6x6 compliance matrix for transverse isotropy"""
        E1 = self.parameters['E1']
        E3 = self.parameters['E3']
        nu12 = self.parameters['nu12']
        nu13 = self.parameters['nu13']
        nu31 = self.parameters['nu31']
        G13 = self.parameters['G13']
        G12 = self.parameters['G12']
        
        # Compliance matrix in principal coordinate system
        S = np.zeros((6, 6))
        
        # Diagonal terms
        S[0, 0] = 1 / E1
        S[1, 1] = 1 / E1
        S[2, 2] = 1 / E3
        S[3, 3] = 1 / G13
        S[4, 4] = 1 / G13
        S[5, 5] = 1 / G12
        
        # Off-diagonal terms
        S[0, 1] = S[1, 0] = -nu12 / E1
        S[0, 2] = S[2, 0] = -nu13 / E1
        S[1, 2] = S[2, 1] = -nu13 / E1  # nu23 = nu13 for transverse isotropy
        
        self.compliance_matrix = S
        self.stiffness_matrix = np.linalg.inv(S)
    
    def calculate_stress(self, strain, **kwargs):
        """Calculate stress using full anisotropic constitutive relations"""
        try:
            # Transform strain to principal coordinate system if needed
            strain_principal = self._transform_strain_to_principal(strain, **kwargs)
            
            # Apply constitutive relation
            stress_principal = self.stiffness_matrix @ strain_principal
            
            # Apply geological constraints and external data corrections
            stress_principal = self._apply_anisotropic_corrections(stress_principal, **kwargs)
            
            # Transform back to global coordinate system
            stress = self._transform_stress_from_principal(stress_principal, **kwargs)
            
            return stress
            
        except Exception as e:
            logging.error(f"Transversely isotropic stress calculation failed: {e}")
            return np.zeros_like(strain)
    
    def _transform_strain_to_principal(self, strain, **kwargs):
        """Transform strain tensor to principal material coordinate system
        
        Implements advanced tensor rotation with:
        - Full 3D anisotropic material orientation handling
        - Crystallographic preferred orientation (CPO) integration
        - Fabric tensor analysis from structural geology
        - Finite deformation compatibility
        - Real-time orientation updates from geological databases
        """
        try:
            # Get base orientation matrix
            orientation = kwargs.get('material_orientation', np.eye(3))
            location = kwargs.get('location')
            depth = kwargs.get('depth', 0.0)
            temperature = kwargs.get('temperature', 300.0)
            pressure = kwargs.get('pressure', 0.1)
            
            # Advanced orientation determination from multiple sources
            if self.external_data_manager and location:
                structural_data = self._get_advanced_structural_orientation(location, depth)
                
                # Crystallographic preferred orientation matrix
                cpo_matrix = self._calculate_cpo_matrix(structural_data, temperature, pressure)
                
                # Fabric tensor from metamorphic analysis
                fabric_tensor = self._calculate_fabric_tensor(structural_data, **kwargs)
                
                # Combine orientation sources with weighted average
                confidence_weights = self._calculate_orientation_confidence(structural_data)
                orientation = self._combine_orientation_matrices([
                    orientation,
                    structural_data.get('orientation_matrix', np.eye(3)),
                    cpo_matrix,
                    fabric_tensor
                ], confidence_weights)
            
            # Convert strain vector to tensor form if needed
            if strain.shape == (6,):
                # Engineering strain vector to tensor
                strain_tensor = np.array([
                    [strain[0], strain[5]/2, strain[4]/2],
                    [strain[5]/2, strain[1], strain[3]/2],
                    [strain[4]/2, strain[3]/2, strain[2]]
                ])
            else:
                strain_tensor = strain.reshape(3, 3)
            
            # Apply finite deformation correction for large strains
            strain_tensor = self._apply_finite_deformation_correction(strain_tensor, **kwargs)
            
            # Tensor rotation: R^T * ε * R
            strain_principal_tensor = orientation.T @ strain_tensor @ orientation
            
            # Convert back to vector form
            strain_principal = np.array([
                strain_principal_tensor[0, 0],  # ε11
                strain_principal_tensor[1, 1],  # ε22
                strain_principal_tensor[2, 2],  # ε33
                2 * strain_principal_tensor[1, 2],  # γ23
                2 * strain_principal_tensor[0, 2],  # γ13
                2 * strain_principal_tensor[0, 1]   # γ12
            ])
            
            # Apply anisotropic strain evolution corrections
            strain_principal = self._apply_strain_evolution_correction(strain_principal, orientation, **kwargs)
            
            return strain_principal
            
        except Exception as e:
            logging.error(f"Advanced strain tensor transformation failed: {e}")
            # Fallback to identity transformation
            return strain
    
    def _transform_stress_from_principal(self, stress, **kwargs):
        """Transform stress tensor from principal to global coordinate system
        
        Implements advanced stress tensor rotation with:
        - Full 3D anisotropic stress transformation
        - Objective stress rate corrections for finite deformation
        - Crystallographic stress state integration
        - Real-time geological constraint enforcement
        - Multi-scale stress field coupling
        """
        try:
            # Get orientation matrix (same as used in strain transformation)
            orientation = kwargs.get('material_orientation', np.eye(3))
            location = kwargs.get('location')
            depth = kwargs.get('depth', 0.0)
            temperature = kwargs.get('temperature', 300.0)
            pressure = kwargs.get('pressure', 0.1)
            
            # Reconstruct orientation matrix using same logic as strain transformation
            if self.external_data_manager and location:
                structural_data = self._get_advanced_structural_orientation(location, depth)
                
                # Crystallographic preferred orientation matrix
                cpo_matrix = self._calculate_cpo_matrix(structural_data, temperature, pressure)
                
                # Fabric tensor from metamorphic analysis
                fabric_tensor = self._calculate_fabric_tensor(structural_data, **kwargs)
                
                # Combine orientation sources with weighted average
                confidence_weights = self._calculate_orientation_confidence(structural_data)
                orientation = self._combine_orientation_matrices([
                    orientation,
                    structural_data.get('orientation_matrix', np.eye(3)),
                    cpo_matrix,
                    fabric_tensor
                ], confidence_weights)
            
            # Convert stress vector to tensor form if needed
            if stress.shape == (6,):
                # Stress vector to tensor (Voigt notation)
                stress_tensor = np.array([
                    [stress[0], stress[5], stress[4]],
                    [stress[5], stress[1], stress[3]],
                    [stress[4], stress[3], stress[2]]
                ])
            else:
                stress_tensor = stress.reshape(3, 3)
            
            # Apply objective stress rate corrections for finite deformation
            stress_tensor = self._apply_objective_stress_correction(stress_tensor, orientation, **kwargs)
            
            # Tensor rotation: R * σ * R^T
            stress_global_tensor = orientation @ stress_tensor @ orientation.T
            
            # Apply geological stress constraints
            stress_global_tensor = self._apply_geological_stress_constraints(stress_global_tensor, location, depth)
            
            # Convert back to vector form (Voigt notation)
            stress_global = np.array([
                stress_global_tensor[0, 0],  # σ11
                stress_global_tensor[1, 1],  # σ22
                stress_global_tensor[2, 2],  # σ33
                stress_global_tensor[1, 2],  # σ23
                stress_global_tensor[0, 2],  # σ13
                stress_global_tensor[0, 1]   # σ12
            ])
            
            # Apply multi-scale stress field coupling
            stress_global = self._apply_multiscale_stress_coupling(stress_global, orientation, **kwargs)
            
            # Enforce stress equilibrium and compatibility
            stress_global = self._enforce_stress_equilibrium(stress_global, **kwargs)
            
            return stress_global
            
        except Exception as e:
            logging.error(f"Advanced stress tensor transformation failed: {e}")
            # Fallback to identity transformation
            return stress
    
    def _get_structural_orientation(self, location):
        """Get structural orientation from geological databases"""
        try:
            # Query structural geology databases for foliation, bedding orientations
            structural_data = self.external_data_manager.get_structural_data(location[0], location[1])
            return structural_data
        except:
            return {'orientation_matrix': np.eye(3), 'foliation_strike': 0, 'foliation_dip': 0}
    
    def _get_advanced_structural_orientation(self, location, depth):
        """Advanced structural orientation determination with crystallographic analysis
        
        Integrates multiple data sources for comprehensive orientation analysis:
        - Structural geology databases (foliation, bedding, lineation)
        - Seismic anisotropy measurements
        - Gravity and magnetic field anomalies
        - Borehole breakout analysis
        - Crystallographic texture measurements
        - Metamorphic fabric analysis
        """
        try:
            base_data = self._get_structural_orientation(location)
            
            # Multi-source data collection
            structural_sources = {
                'field_measurements': self.external_data_manager.get_field_structural_data(location[0], location[1]),
                'seismic_anisotropy': self.external_data_manager.get_seismic_anisotropy(location[0], location[1], depth),
                'gravity_anomalies': self.external_data_manager.get_gravity_tensor_data(location[0], location[1]),
                'magnetic_fabric': self.external_data_manager.get_magnetic_susceptibility_anisotropy(location[0], location[1]),
                'borehole_breakouts': self.external_data_manager.get_borehole_stress_indicators(location[0], location[1], depth),
                'crystallographic_data': self.external_data_manager.get_crystallographic_orientation_data(location[0], location[1])
            }
            
            # Calculate confidence weights for each data source
            source_weights = self._calculate_structural_data_weights(structural_sources, depth)
            
            # Determine primary structural fabric orientation
            foliation_orientation = self._calculate_foliation_orientation_matrix(structural_sources, source_weights)
            
            # Determine lineation and secondary fabric orientations
            lineation_orientation = self._calculate_lineation_orientation_matrix(structural_sources, source_weights)
            
            # Calculate crystallographic preferred orientation from texture data
            cpo_orientation = self._calculate_crystallographic_orientation_matrix(structural_sources, source_weights)
            
            # Integrate metamorphic fabric evolution
            metamorphic_fabric = self._calculate_metamorphic_fabric_orientation(structural_sources, depth)
            
            # Weighted combination of all orientation matrices
            combined_orientation = self._integrate_orientation_matrices({
                'foliation': foliation_orientation,
                'lineation': lineation_orientation,
                'crystallographic': cpo_orientation,
                'metamorphic': metamorphic_fabric
            }, source_weights)
            
            return {
                'orientation_matrix': combined_orientation,
                'foliation_strike': self._extract_strike_from_matrix(foliation_orientation),
                'foliation_dip': self._extract_dip_from_matrix(foliation_orientation),
                'lineation_plunge': self._extract_plunge_from_matrix(lineation_orientation),
                'lineation_trend': self._extract_trend_from_matrix(lineation_orientation),
                'fabric_intensity': self._calculate_fabric_intensity(structural_sources),
                'anisotropy_degree': self._calculate_anisotropy_degree(structural_sources),
                'confidence_score': np.mean(list(source_weights.values())),
                'data_sources': list(structural_sources.keys())
            }
            
        except Exception as e:
            logging.warning(f"Advanced structural orientation determination failed: {e}")
            return self._get_structural_orientation(location)
    
    def _apply_anisotropic_corrections(self, stress, **kwargs):
        """Apply anisotropy-specific corrections based on geological data"""
        try:
            location = kwargs.get('location')
            depth = kwargs.get('depth')
            temperature = kwargs.get('temperature')
            
            if self.external_data_manager and location:
                geological_data = self._get_anisotropic_context(location, depth)
                stress = self._apply_metamorphic_correction(stress, geological_data)
                stress = self._apply_fabric_intensity_correction(stress, geological_data)
                stress = self._apply_weathering_correction(stress, depth, geological_data)
            
        except Exception as e:
            logging.warning(f"Anisotropic correction application failed: {e}")
        
        return stress
    
    def _get_anisotropic_context(self, location, depth):
        """Get anisotropy-specific geological context"""
        try:
            context = self.external_data_manager.get_anisotropic_properties(location[0], location[1])
            return context
        except:
            return {
                'metamorphic_grade': 'low',
                'fabric_intensity': 0.5,
                'weathering_degree': 'fresh',
                'mineral_alignment': 0.3
            }
    
    def _apply_metamorphic_correction(self, stress, geological_data):
        """Apply metamorphic grade-dependent corrections"""
        metamorphic_grade = geological_data.get('metamorphic_grade', 'low')
        
        grade_modifiers = {
            'low': 0.8,
            'medium': 1.0,
            'high': 1.3
        }
        
        modifier = grade_modifiers.get(metamorphic_grade, 1.0)
        
        # Apply different modifiers to different stress components
        corrected_stress = stress.copy()
        corrected_stress[:3] *= modifier  # Normal stresses
        corrected_stress[3:] *= modifier * 0.9  # Shear stresses reduced more
        
        return corrected_stress
    
    def _apply_fabric_intensity_correction(self, stress, geological_data):
        """Apply correction based on rock fabric intensity"""
        fabric_intensity = geological_data.get('fabric_intensity', 0.5)
        
        # Higher fabric intensity increases anisotropy
        anisotropy_factor = 1 + fabric_intensity * 0.5
        
        corrected_stress = stress.copy()
        # Apply stronger correction perpendicular to foliation
        corrected_stress[2] *= anisotropy_factor  # sigma_33
        corrected_stress[3:5] *= anisotropy_factor  # shear in 13, 23 planes
        
        return corrected_stress
    
    def _apply_weathering_correction(self, stress, depth, geological_data):
        """Apply weathering-dependent property degradation"""
        weathering = geological_data.get('weathering_degree', 'fresh')
        
        if depth is None or depth < 5:  # Near surface
            weathering_factors = {
                'fresh': 1.0,
                'slightly_weathered': 0.9,
                'moderately_weathered': 0.7,
                'highly_weathered': 0.4,
                'completely_weathered': 0.2
            }
        else:  # Deep, less weathering effect
            weathering_factors = {
                'fresh': 1.0,
                'slightly_weathered': 0.95,
                'moderately_weathered': 0.85,
                'highly_weathered': 0.7,
                'completely_weathered': 0.5
            }
        
        factor = weathering_factors.get(weathering, 1.0)
        return stress * factor
    
    def get_elastic_constants(self):
        """Return dictionary of elastic constants"""
        return {
            'stiffness_matrix': self.stiffness_matrix,
            'compliance_matrix': self.compliance_matrix,
            'engineering_constants': {
                'E1': self.parameters['E1'],
                'E3': self.parameters['E3'],
                'nu12': self.parameters['nu12'],
                'nu13': self.parameters['nu13'],
                'G12': self.parameters['G12'],
                'G13': self.parameters['G13']
            }
        }
    
    # Advanced tensor transformation support methods
    
    def _calculate_cpo_matrix(self, structural_data, temperature, pressure):
        """Calculate crystallographic preferred orientation matrix from mineral texture data"""
        try:
            cpo_data = structural_data.get('crystallographic_data', {})
            
            # Olivine fabric types common in upper mantle
            fabric_type = cpo_data.get('fabric_type', 'A-type')
            fabric_strength = cpo_data.get('fabric_strength', 0.5)
            
            # Temperature and pressure dependent fabric evolution
            if temperature > 1200:  # High-T conditions favor A-type fabrics
                fabric_strength *= 1.2
            elif temperature < 800:  # Low-T conditions weaken fabric
                fabric_strength *= 0.8
            
            # Construct CPO matrix based on fabric type
            if fabric_type == 'A-type':
                # [100] parallel to flow, [010] perpendicular to flow
                cpo_matrix = self._construct_a_type_fabric_matrix(fabric_strength)
            elif fabric_type == 'B-type':
                # [001] parallel to flow
                cpo_matrix = self._construct_b_type_fabric_matrix(fabric_strength)
            elif fabric_type == 'C-type':
                # [001] perpendicular to flow
                cpo_matrix = self._construct_c_type_fabric_matrix(fabric_strength)
            else:
                cpo_matrix = np.eye(3)
            
            return cpo_matrix
            
        except Exception as e:
            logging.warning(f"CPO matrix calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_fabric_tensor(self, structural_data, **kwargs):
        """Calculate fabric tensor from structural measurements"""
        try:
            # Shape fabric tensor from foliation and lineation measurements
            foliation_data = structural_data.get('field_measurements', {})
            
            # Extract foliation pole and lineation vectors
            foliation_pole = self._spherical_to_cartesian(
                foliation_data.get('foliation_strike', 0),
                foliation_data.get('foliation_dip', 0)
            )
            
            lineation_vector = self._spherical_to_cartesian(
                foliation_data.get('lineation_trend', 0),
                foliation_data.get('lineation_plunge', 0)
            )
            
            # Construct fabric ellipsoid principal axes
            axis_1 = lineation_vector  # Maximum stretch direction
            axis_3 = foliation_pole    # Minimum stretch direction
            axis_2 = np.cross(axis_3, axis_1)  # Intermediate direction
            
            # Normalize axes
            axis_1 = axis_1 / np.linalg.norm(axis_1)
            axis_2 = axis_2 / np.linalg.norm(axis_2)
            axis_3 = axis_3 / np.linalg.norm(axis_3)
            
            # Construct fabric tensor matrix
            fabric_matrix = np.column_stack([axis_1, axis_2, axis_3])
            
            return fabric_matrix
            
        except Exception as e:
            logging.warning(f"Fabric tensor calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_orientation_confidence(self, structural_data):
        """Calculate confidence weights for different orientation data sources"""
        confidence_weights = {}
        
        # Base confidence levels for different data types
        base_confidence = {
            'field_measurements': 0.9,      # High confidence in direct measurements
            'seismic_anisotropy': 0.8,     # Good confidence in seismic data
            'crystallographic_data': 0.85,  # High confidence in lab measurements
            'gravity_anomalies': 0.6,      # Moderate confidence in gravity
            'magnetic_fabric': 0.7,        # Good confidence in magnetic fabric
            'borehole_breakouts': 0.75     # Good confidence in borehole data
        }
        
        for source, data in structural_data.items():
            if data and isinstance(data, dict):
                # Adjust confidence based on data quality indicators
                quality_score = data.get('quality_score', 0.5)
                measurement_count = data.get('measurement_count', 1)
                data_age = data.get('data_age_years', 0)
                
                # Quality adjustments
                base_conf = base_confidence.get(source, 0.5)
                adjusted_conf = base_conf * quality_score
                
                # More measurements increase confidence
                adjusted_conf *= min(1.0 + np.log10(measurement_count + 1) * 0.1, 1.5)
                
                # Newer data is more reliable
                if data_age > 10:
                    adjusted_conf *= 0.9
                elif data_age > 20:
                    adjusted_conf *= 0.8
                
                confidence_weights[source] = min(adjusted_conf, 1.0)
            else:
                confidence_weights[source] = 0.1  # Low confidence for missing data
        
        return confidence_weights
    
    def _combine_orientation_matrices(self, matrices, weights):
        """Combine multiple orientation matrices using weighted averaging"""
        try:
            # Convert matrices to quaternions for proper averaging
            quaternions = []
            valid_weights = []
            
            for i, matrix in enumerate(matrices):
                if matrix is not None and matrix.shape == (3, 3):
                    # Convert rotation matrix to quaternion
                    quat = self._rotation_matrix_to_quaternion(matrix)
                    quaternions.append(quat)
                    valid_weights.append(weights[i] if i < len(weights) else 1.0)
            
            if not quaternions:
                return np.eye(3)
            
            # Weighted quaternion averaging
            combined_quat = self._weighted_quaternion_average(quaternions, valid_weights)
            
            # Convert back to rotation matrix
            combined_matrix = self._quaternion_to_rotation_matrix(combined_quat)
            
            return combined_matrix
            
        except Exception as e:
            logging.warning(f"Orientation matrix combination failed: {e}")
            return matrices[0] if matrices else np.eye(3)
    
    def _apply_finite_deformation_correction(self, strain_tensor, **kwargs):
        """Apply finite deformation corrections for large strain cases"""
        try:
            # Calculate strain magnitude
            strain_magnitude = np.linalg.norm(strain_tensor)
            
            if strain_magnitude > 0.01:  # Large strain threshold (1%)
                # Apply Green-Lagrange strain correction
                E = strain_tensor
                # E = 0.5 * (F^T * F - I) where F is deformation gradient
                # For large strains, use logarithmic strain
                eigenvals, eigenvecs = np.linalg.eigh(2 * E + np.eye(3))
                
                # Logarithmic strain
                log_strain = eigenvecs @ np.diag(np.log(eigenvals)) @ eigenvecs.T
                
                return log_strain
            
            return strain_tensor
            
        except Exception as e:
            logging.warning(f"Finite deformation correction failed: {e}")
            return strain_tensor
    
    def _apply_strain_evolution_correction(self, strain, orientation, **kwargs):
        """Apply anisotropic strain evolution corrections"""
        try:
            # Get deformation rate information
            strain_rate = kwargs.get('strain_rate', 1e-15)  # s^-1
            time_step = kwargs.get('time_step', 3600)       # seconds
            
            if strain_rate * time_step > 1e-6:  # Significant strain rate
                # Apply rate-dependent anisotropic correction
                rate_correction = 1.0 + np.log10(strain_rate * 1e15) * 0.05
                
                # Different correction for different strain components
                corrected_strain = strain.copy()
                corrected_strain[:3] *= rate_correction      # Normal strains
                corrected_strain[3:] *= rate_correction * 0.9  # Shear strains
                
                return corrected_strain
            
            return strain
            
        except Exception as e:
            logging.warning(f"Strain evolution correction failed: {e}")
            return strain
    
    def _apply_objective_stress_correction(self, stress_tensor, orientation, **kwargs):
        """Apply objective stress rate corrections for finite deformation"""
        try:
            # Get velocity gradient information
            velocity_gradient = kwargs.get('velocity_gradient')
            if velocity_gradient is not None:
                # Calculate spin tensor (antisymmetric part of velocity gradient)
                W = 0.5 * (velocity_gradient - velocity_gradient.T)
                
                # Jaumann stress rate correction
                stress_corrected = stress_tensor + W @ stress_tensor - stress_tensor @ W
                
                return stress_corrected
            
            return stress_tensor
            
        except Exception as e:
            logging.warning(f"Objective stress correction failed: {e}")
            return stress_tensor
    
    def _apply_geological_stress_constraints(self, stress_tensor, location, depth):
        """Apply geological stress constraints based on regional stress field"""
        try:
            if self.external_data_manager and location and depth:
                # Get regional stress field data
                regional_stress = self.external_data_manager.get_regional_stress_field(
                    location[0], location[1], depth
                )
                
                if regional_stress:
                    # Apply stress field constraints
                    constraint_weight = 0.1  # 10% influence from regional field
                    
                    regional_tensor = np.array([
                        [regional_stress['sigma_xx'], regional_stress['sigma_xy'], regional_stress['sigma_xz']],
                        [regional_stress['sigma_xy'], regional_stress['sigma_yy'], regional_stress['sigma_yz']],
                        [regional_stress['sigma_xz'], regional_stress['sigma_yz'], regional_stress['sigma_zz']]
                    ])
                    
                    # Weighted combination
                    constrained_stress = (1 - constraint_weight) * stress_tensor + constraint_weight * regional_tensor
                    
                    return constrained_stress
            
            return stress_tensor
            
        except Exception as e:
            logging.warning(f"Geological stress constraint application failed: {e}")
            return stress_tensor
    
    def _apply_multiscale_stress_coupling(self, stress, orientation, **kwargs):
        """Apply multi-scale stress field coupling"""
        try:
            # Couple local stress with larger scale deformation
            regional_deformation = kwargs.get('regional_deformation_gradient')
            if regional_deformation is not None:
                # Scale coupling factor
                coupling_strength = 0.05  # 5% coupling
                
                # Apply coupling correction
                coupled_stress = stress * (1 + coupling_strength * np.trace(regional_deformation))
                
                return coupled_stress
            
            return stress
            
        except Exception as e:
            logging.warning(f"Multiscale stress coupling failed: {e}")
            return stress
    
    def _enforce_stress_equilibrium(self, stress, **kwargs):
        """Enforce stress equilibrium and compatibility conditions"""
        try:
            # Convert to tensor form for equilibrium check
            stress_tensor = np.array([
                [stress[0], stress[5], stress[4]],
                [stress[5], stress[1], stress[3]],
                [stress[4], stress[3], stress[2]]
            ])
            
            # Check stress equilibrium (∇·σ = 0)
            # For now, ensure symmetry
            symmetric_tensor = 0.5 * (stress_tensor + stress_tensor.T)
            
            # Convert back to vector form
            equilibrium_stress = np.array([
                symmetric_tensor[0, 0],  # σ11
                symmetric_tensor[1, 1],  # σ22
                symmetric_tensor[2, 2],  # σ33
                symmetric_tensor[1, 2],  # σ23
                symmetric_tensor[0, 2],  # σ13
                symmetric_tensor[0, 1]   # σ12
            ])
            
            return equilibrium_stress
            
        except Exception as e:
            logging.warning(f"Stress equilibrium enforcement failed: {e}")
            return stress
    
    # Utility methods for coordinate transformations
    
    def _spherical_to_cartesian(self, strike, dip):
        """Convert spherical coordinates (strike, dip) to Cartesian vector"""
        strike_rad = np.radians(strike)
        dip_rad = np.radians(dip)
        
        x = np.sin(dip_rad) * np.sin(strike_rad)
        y = np.sin(dip_rad) * np.cos(strike_rad)
        z = np.cos(dip_rad)
        
        return np.array([x, y, z])
    
    def _rotation_matrix_to_quaternion(self, R):
        """Convert rotation matrix to quaternion"""
        trace = np.trace(R)
        if trace > 0:
            s = 0.5 / np.sqrt(trace + 1.0)
            w = 0.25 / s
            x = (R[2, 1] - R[1, 2]) * s
            y = (R[0, 2] - R[2, 0]) * s
            z = (R[1, 0] - R[0, 1]) * s
        else:
            if R[0, 0] > R[1, 1] and R[0, 0] > R[2, 2]:
                s = 2.0 * np.sqrt(1.0 + R[0, 0] - R[1, 1] - R[2, 2])
                w = (R[2, 1] - R[1, 2]) / s
                x = 0.25 * s
                y = (R[0, 1] + R[1, 0]) / s
                z = (R[0, 2] + R[2, 0]) / s
            elif R[1, 1] > R[2, 2]:
                s = 2.0 * np.sqrt(1.0 + R[1, 1] - R[0, 0] - R[2, 2])
                w = (R[0, 2] - R[2, 0]) / s
                x = (R[0, 1] + R[1, 0]) / s
                y = 0.25 * s
                z = (R[1, 2] + R[2, 1]) / s
            else:
                s = 2.0 * np.sqrt(1.0 + R[2, 2] - R[0, 0] - R[1, 1])
                w = (R[1, 0] - R[0, 1]) / s
                x = (R[0, 2] + R[2, 0]) / s
                y = (R[1, 2] + R[2, 1]) / s
                z = 0.25 * s
        
        return np.array([w, x, y, z])
    
    def _quaternion_to_rotation_matrix(self, q):
        """Convert quaternion to rotation matrix"""
        w, x, y, z = q
        return np.array([
            [1 - 2*(y**2 + z**2), 2*(x*y - w*z), 2*(x*z + w*y)],
            [2*(x*y + w*z), 1 - 2*(x**2 + z**2), 2*(y*z - w*x)],
            [2*(x*z - w*y), 2*(y*z + w*x), 1 - 2*(x**2 + y**2)]
        ])
    
    def _weighted_quaternion_average(self, quaternions, weights):
        """Calculate weighted average of quaternions"""
        # Normalize weights
        weights = np.array(weights)
        weights = weights / np.sum(weights)
        
        # Matrix for averaging
        M = np.zeros((4, 4))
        
        for q, w in zip(quaternions, weights):
            M += w * np.outer(q, q)
        
        # Eigendecomposition
        eigenvals, eigenvecs = np.linalg.eigh(M)
        
        # Return eigenvector with largest eigenvalue
        return eigenvecs[:, -1]
    
    def _construct_a_type_fabric_matrix(self, strength):
        """Construct A-type olivine fabric orientation matrix"""
        # A-type: [100] parallel to flow, [010] perpendicular
        theta = np.pi/4 * (1 - strength)  # Rotation from perfect alignment
        
        return np.array([
            [np.cos(theta), -np.sin(theta), 0],
            [np.sin(theta), np.cos(theta), 0],
            [0, 0, 1]
        ])
    
    def _construct_b_type_fabric_matrix(self, strength):
        """Construct B-type olivine fabric orientation matrix"""
        # B-type: [001] parallel to flow
        theta = np.pi/4 * (1 - strength)
        
        return np.array([
            [1, 0, 0],
            [0, np.cos(theta), -np.sin(theta)],
            [0, np.sin(theta), np.cos(theta)]
        ])
    
    def _construct_c_type_fabric_matrix(self, strength):
        """Construct C-type olivine fabric orientation matrix"""
        # C-type: [001] perpendicular to flow
        theta = np.pi/4 * (1 - strength)
        
        return np.array([
            [np.cos(theta), 0, -np.sin(theta)],
            [0, 1, 0],
            [np.sin(theta), 0, np.cos(theta)]
        ])
    
    def _calculate_structural_data_weights(self, structural_sources, depth):
        """Calculate confidence weights for structural data sources based on depth and data quality"""
        weights = {}
        
        for source, data in structural_sources.items():
            if data and isinstance(data, dict):
                # Base weight depends on source type and depth
                if source == 'field_measurements':
                    base_weight = 1.0 if depth < 100 else 0.8  # Surface measurements less reliable at depth
                elif source == 'seismic_anisotropy':
                    base_weight = 0.9 if depth > 1000 else 0.7  # Better for deep structures
                elif source == 'crystallographic_data':
                    base_weight = 0.95  # Lab measurements highly reliable
                elif source == 'borehole_breakouts':
                    base_weight = 0.85 if depth > 100 else 0.6  # Better for subsurface
                else:
                    base_weight = 0.6
                
                # Adjust based on data quality metrics
                quality = data.get('quality_score', 0.5)
                measurement_count = data.get('measurement_count', 1)
                data_age = data.get('data_age_years', 0)
                
                # Quality and quantity adjustments
                weight = base_weight * quality
                weight *= min(1.0 + np.log10(measurement_count + 1) * 0.1, 1.3)
                
                # Age penalty
                if data_age > 10:
                    weight *= 0.9
                elif data_age > 20:
                    weight *= 0.8
                
                weights[source] = min(weight, 1.0)
            else:
                weights[source] = 0.1
        
        return weights
    
    def _calculate_foliation_orientation_matrix(self, structural_sources, weights):
        """Calculate foliation orientation matrix from multiple data sources"""
        try:
            orientation_matrices = []
            matrix_weights = []
            
            # Process field measurements
            field_data = structural_sources.get('field_measurements', {})
            if field_data:
                strike = field_data.get('foliation_strike', 0)
                dip = field_data.get('foliation_dip', 0)
                matrix = self._strike_dip_to_matrix(strike, dip)
                orientation_matrices.append(matrix)
                matrix_weights.append(weights.get('field_measurements', 0.1))
            
            # Process seismic anisotropy data
            seismic_data = structural_sources.get('seismic_anisotropy', {})
            if seismic_data:
                fast_axis = seismic_data.get('fast_axis_azimuth', 0)
                inclination = seismic_data.get('fast_axis_inclination', 0)
                matrix = self._azimuth_inclination_to_matrix(fast_axis, inclination)
                orientation_matrices.append(matrix)
                matrix_weights.append(weights.get('seismic_anisotropy', 0.1))
            
            # Process magnetic fabric data
            magnetic_data = structural_sources.get('magnetic_fabric', {})
            if magnetic_data:
                k1_dec = magnetic_data.get('k1_declination', 0)
                k1_inc = magnetic_data.get('k1_inclination', 0)
                matrix = self._declination_inclination_to_matrix(k1_dec, k1_inc)
                orientation_matrices.append(matrix)
                matrix_weights.append(weights.get('magnetic_fabric', 0.1))
            
            if orientation_matrices:
                return self._combine_orientation_matrices(orientation_matrices, matrix_weights)
            else:
                return np.eye(3)
                
        except Exception as e:
            logging.warning(f"Foliation orientation matrix calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_lineation_orientation_matrix(self, structural_sources, weights):
        """Calculate lineation orientation matrix from structural data"""
        try:
            field_data = structural_sources.get('field_measurements', {})
            if field_data:
                trend = field_data.get('lineation_trend', 0)
                plunge = field_data.get('lineation_plunge', 0)
                return self._trend_plunge_to_matrix(trend, plunge)
            else:
                return np.eye(3)
                
        except Exception as e:
            logging.warning(f"Lineation orientation matrix calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_crystallographic_orientation_matrix(self, structural_sources, weights):
        """Calculate crystallographic orientation matrix from texture analysis"""
        try:
            cpo_data = structural_sources.get('crystallographic_data', {})
            if cpo_data:
                # Extract crystallographic axes orientations
                a_axis = cpo_data.get('a_axis_orientation', [1, 0, 0])
                b_axis = cpo_data.get('b_axis_orientation', [0, 1, 0])
                c_axis = cpo_data.get('c_axis_orientation', [0, 0, 1])
                
                # Construct orientation matrix from crystallographic axes
                matrix = np.column_stack([a_axis, b_axis, c_axis])
                
                # Ensure orthogonality
                U, s, Vt = np.linalg.svd(matrix)
                orthogonal_matrix = U @ Vt
                
                return orthogonal_matrix
            else:
                return np.eye(3)
                
        except Exception as e:
            logging.warning(f"Crystallographic orientation matrix calculation failed: {e}")
            return np.eye(3)
    
    def _calculate_metamorphic_fabric_orientation(self, structural_sources, depth):
        """Calculate metamorphic fabric orientation considering P-T conditions"""
        try:
            # Estimate metamorphic grade based on depth and available data
            field_data = structural_sources.get('field_measurements', {})
            metamorphic_grade = field_data.get('metamorphic_grade', 'low')
            
            # Pressure-temperature estimates
            pressure = depth * 0.027  # GPa, assuming 27 MPa/km
            temperature = 273 + depth * 0.025 + 15  # K, geothermal gradient ~25°C/km
            
            # Fabric strength depends on metamorphic conditions
            if metamorphic_grade == 'high' or temperature > 700:
                fabric_strength = 0.9  # Strong fabric development
            elif metamorphic_grade == 'medium' or temperature > 500:
                fabric_strength = 0.7
            else:
                fabric_strength = 0.4  # Weak fabric
            
            # Base orientation from foliation measurements
            base_matrix = self._calculate_foliation_orientation_matrix(structural_sources, {})
            
            # Apply metamorphic fabric modification
            metamorphic_matrix = self._apply_metamorphic_fabric_evolution(base_matrix, 
                                                                         temperature, 
                                                                         pressure, 
                                                                         fabric_strength)
            
            return metamorphic_matrix
            
        except Exception as e:
            logging.warning(f"Metamorphic fabric orientation calculation failed: {e}")
            return np.eye(3)
    
    def _integrate_orientation_matrices(self, orientation_dict, source_weights):
        """Integrate multiple orientation matrices with hierarchical weighting"""
        try:
            # Hierarchical importance: crystallographic > field > metamorphic > others
            hierarchy_weights = {
                'crystallographic': 1.0,
                'foliation': 0.9,
                'metamorphic': 0.7,
                'lineation': 0.6
            }
            
            matrices = []
            combined_weights = []
            
            for orient_type, matrix in orientation_dict.items():
                if matrix is not None:
                    hierarchy_weight = hierarchy_weights.get(orient_type, 0.5)
                    # Average source weights for this orientation type
                    avg_source_weight = np.mean(list(source_weights.values()))
                    combined_weight = hierarchy_weight * avg_source_weight
                    
                    matrices.append(matrix)
                    combined_weights.append(combined_weight)
            
            if matrices:
                return self._combine_orientation_matrices(matrices, combined_weights)
            else:
                return np.eye(3)
                
        except Exception as e:
            logging.warning(f"Orientation matrix integration failed: {e}")
            return np.eye(3)
    
    def _strike_dip_to_matrix(self, strike, dip):
        """Convert strike/dip to orientation matrix"""
        strike_rad = np.radians(strike)
        dip_rad = np.radians(dip)
        
        # Foliation normal vector
        normal = np.array([
            np.sin(dip_rad) * np.sin(strike_rad + np.pi/2),
            np.sin(dip_rad) * np.cos(strike_rad + np.pi/2),
            np.cos(dip_rad)
        ])
        
        # Strike vector
        strike_vec = np.array([np.cos(strike_rad), np.sin(strike_rad), 0])
        
        # Dip vector
        dip_vec = np.cross(normal, strike_vec)
        
        return np.column_stack([strike_vec, dip_vec, normal])
    
    def _azimuth_inclination_to_matrix(self, azimuth, inclination):
        """Convert azimuth/inclination to orientation matrix"""
        azimuth_rad = np.radians(azimuth)
        inclination_rad = np.radians(inclination)
        
        # Primary axis
        axis1 = np.array([
            np.cos(inclination_rad) * np.cos(azimuth_rad),
            np.cos(inclination_rad) * np.sin(azimuth_rad),
            np.sin(inclination_rad)
        ])
        
        # Perpendicular axes
        if abs(axis1[2]) < 0.9:
            axis2 = np.cross(axis1, [0, 0, 1])
        else:
            axis2 = np.cross(axis1, [1, 0, 0])
        
        axis2 = axis2 / np.linalg.norm(axis2)
        axis3 = np.cross(axis1, axis2)
        
        return np.column_stack([axis1, axis2, axis3])
    
    def _declination_inclination_to_matrix(self, declination, inclination):
        """Convert magnetic declination/inclination to orientation matrix"""
        return self._azimuth_inclination_to_matrix(declination, inclination)
    
    def _trend_plunge_to_matrix(self, trend, plunge):
        """Convert trend/plunge to orientation matrix"""
        return self._azimuth_inclination_to_matrix(trend, plunge)
    
    def _apply_metamorphic_fabric_evolution(self, base_matrix, temperature, pressure, fabric_strength):
        """Apply metamorphic fabric evolution based on P-T conditions"""
        try:
            # Temperature-dependent fabric rotation
            if temperature > 600:  # Amphibolite facies and higher
                # Stronger fabric development, possible rotation
                rotation_angle = (temperature - 600) / 400 * np.pi/6  # Up to 30° rotation
            else:
                rotation_angle = 0
            
            # Pressure-dependent fabric intensity
            pressure_factor = min(1.0 + pressure / 2.0, 2.0)  # Up to 2x strengthening
            
            # Apply rotation if significant
            if abs(rotation_angle) > 0.01:
                rotation_matrix = self._rotation_matrix_z(rotation_angle * fabric_strength)
                evolved_matrix = base_matrix @ rotation_matrix
            else:
                evolved_matrix = base_matrix
            
            return evolved_matrix
            
        except Exception as e:
            logging.warning(f"Metamorphic fabric evolution failed: {e}")
            return base_matrix
    
    def _rotation_matrix_z(self, angle):
        """Create rotation matrix around Z axis"""
        c = np.cos(angle)
        s = np.sin(angle)
        return np.array([
            [c, -s, 0],
            [s, c, 0],
            [0, 0, 1]
        ])
    
    def _extract_strike_from_matrix(self, matrix):
        """Extract strike angle from orientation matrix"""
        try:
            # Strike vector is first column
            strike_vec = matrix[:, 0]
            strike = np.degrees(np.arctan2(strike_vec[1], strike_vec[0]))
            return strike % 360
        except:
            return 0.0
    
    def _extract_dip_from_matrix(self, matrix):
        """Extract dip angle from orientation matrix"""
        try:
            # Normal vector is third column
            normal = matrix[:, 2]
            dip = np.degrees(np.arccos(abs(normal[2])))
            return dip
        except:
            return 0.0
    
    def _extract_plunge_from_matrix(self, matrix):
        """Extract lineation plunge from orientation matrix"""
        try:
            # Lineation vector is first column
            lineation = matrix[:, 0]
            plunge = np.degrees(np.arcsin(abs(lineation[2])))
            return plunge
        except:
            return 0.0
    
    def _extract_trend_from_matrix(self, matrix):
        """Extract lineation trend from orientation matrix"""
        try:
            # Lineation vector is first column
            lineation = matrix[:, 0]
            trend = np.degrees(np.arctan2(lineation[1], lineation[0]))
            return trend % 360
        except:
            return 0.0
    
    def _calculate_fabric_intensity(self, structural_sources):
        """Calculate overall fabric intensity from multiple data sources"""
        try:
            intensities = []
            
            # Field measurements
            field_data = structural_sources.get('field_measurements', {})
            if field_data:
                intensities.append(field_data.get('fabric_intensity', 0.5))
            
            # Seismic anisotropy
            seismic_data = structural_sources.get('seismic_anisotropy', {})
            if seismic_data:
                # Convert velocity anisotropy to fabric intensity
                v_anisotropy = seismic_data.get('velocity_anisotropy_percent', 5) / 100
                fabric_intensity = min(v_anisotropy / 0.1, 1.0)  # Normalize to 0-1
                intensities.append(fabric_intensity)
            
            # Crystallographic data
            cpo_data = structural_sources.get('crystallographic_data', {})
            if cpo_data:
                intensities.append(cpo_data.get('fabric_strength', 0.5))
            
            # Magnetic fabric
            magnetic_data = structural_sources.get('magnetic_fabric', {})
            if magnetic_data:
                # AMS degree of anisotropy
                p_prime = magnetic_data.get('corrected_degree_anisotropy', 1.1)
                fabric_intensity = min((p_prime - 1) / 0.5, 1.0)  # Normalize
                intensities.append(fabric_intensity)
            
            if intensities:
                return np.mean(intensities)
            else:
                return 0.5
                
        except Exception as e:
            logging.warning(f"Fabric intensity calculation failed: {e}")
            return 0.5
    
    def _calculate_anisotropy_degree(self, structural_sources):
        """Calculate degree of anisotropy from multiple measurements"""
        try:
            anisotropy_measures = []
            
            # Seismic anisotropy
            seismic_data = structural_sources.get('seismic_anisotropy', {})
            if seismic_data:
                anisotropy_measures.append(seismic_data.get('velocity_anisotropy_percent', 5) / 100)
            
            # Magnetic anisotropy
            magnetic_data = structural_sources.get('magnetic_fabric', {})
            if magnetic_data:
                p_prime = magnetic_data.get('corrected_degree_anisotropy', 1.1)
                anisotropy_measures.append((p_prime - 1))
            
            # Crystallographic anisotropy
            cpo_data = structural_sources.get('crystallographic_data', {})
            if cpo_data:
                j_index = cpo_data.get('j_index', 5)  # Texture strength
                anisotropy_measures.append(j_index / 20)  # Normalize
            
            if anisotropy_measures:
                return np.mean(anisotropy_measures)
            else:
                return 0.1
                
        except Exception as e:
            logging.warning(f"Anisotropy degree calculation failed: {e}")
            return 0.1
    
    # Advanced Real-Time Fabric Tensor Evolution Methods
    
    def _initialize_fabric_evolution_system(self):
        """Initialize real-time fabric tensor evolution tracking system"""
        try:
            self.fabric_evolution_state = {
                'current_fabric_tensor': np.eye(3),
                'fabric_history': [],
                'deformation_gradient_history': [],
                'temperature_history': [],
                'pressure_history': [],
                'last_update_time': None,
                'evolution_rate_tensor': np.zeros((3, 3)),
                'fabric_stability_index': 1.0
            }
            
            # Initialize connection to real-time geological monitoring
            if self.external_data_manager:
                self._setup_realtime_monitoring_streams()
            
            logging.info("Fabric evolution system initialized successfully")
            
        except Exception as e:
            logging.error(f"Fabric evolution system initialization failed: {e}")
    
    def _setup_realtime_monitoring_streams(self):
        """Setup real-time data streams for fabric evolution monitoring"""
        try:
            # Setup seismic monitoring stream
            self.external_data_manager.setup_seismic_monitoring_stream(
                callback=self._process_seismic_fabric_update,
                update_interval=300  # 5-minute updates
            )
            
            # Setup ground deformation monitoring
            self.external_data_manager.setup_insar_monitoring_stream(
                callback=self._process_deformation_fabric_update,
                update_interval=3600  # Hourly updates
            )
            
            # Setup thermal monitoring
            self.external_data_manager.setup_thermal_monitoring_stream(
                callback=self._process_thermal_fabric_update,
                update_interval=1800  # 30-minute updates
            )
            
            # Setup stress field monitoring
            self.external_data_manager.setup_stress_monitoring_stream(
                callback=self._process_stress_fabric_update,
                update_interval=900  # 15-minute updates
            )
            
        except Exception as e:
            logging.warning(f"Real-time monitoring stream setup failed: {e}")
    
    def _process_seismic_fabric_update(self, seismic_data):
        """Process real-time seismic data for fabric tensor evolution"""
        try:
            current_time = time.time()
            
            # Extract seismic anisotropy changes
            fast_axis_change = seismic_data.get('fast_axis_rotation', 0)
            anisotropy_strength_change = seismic_data.get('anisotropy_change_percent', 0) / 100
            
            # Calculate fabric evolution rate from seismic changes
            if self.fabric_evolution_state['last_update_time']:
                dt = current_time - self.fabric_evolution_state['last_update_time']
                rotation_rate = fast_axis_change / dt if dt > 0 else 0
                
                # Update fabric tensor based on seismic anisotropy evolution
                rotation_matrix = self._rotation_matrix_z(np.radians(fast_axis_change))
                current_fabric = self.fabric_evolution_state['current_fabric_tensor']
                
                # Apply gradual rotation
                evolved_fabric = rotation_matrix @ current_fabric
                
                # Apply strength change
                if anisotropy_strength_change != 0:
                    strength_factor = 1 + anisotropy_strength_change * 0.1
                    evolved_fabric = self._apply_fabric_strength_change(evolved_fabric, strength_factor)
                
                self.fabric_evolution_state['current_fabric_tensor'] = evolved_fabric
                self.fabric_evolution_state['evolution_rate_tensor'] = (evolved_fabric - current_fabric) / dt
            
            # Store history
            self.fabric_evolution_state['fabric_history'].append({
                'timestamp': current_time,
                'fabric_tensor': self.fabric_evolution_state['current_fabric_tensor'].copy(),
                'seismic_trigger': seismic_data
            })
            
            self.fabric_evolution_state['last_update_time'] = current_time
            
            # Calculate fabric stability
            self._update_fabric_stability_index()
            
        except Exception as e:
            logging.error(f"Seismic fabric update processing failed: {e}")
    
    def _process_deformation_fabric_update(self, deformation_data):
        """Process real-time ground deformation for fabric tensor evolution"""
        try:
            current_time = time.time()
            
            # Extract deformation gradient components
            deformation_gradient = np.array([
                [deformation_data.get('exx', 0), deformation_data.get('exy', 0), deformation_data.get('exz', 0)],
                [deformation_data.get('eyx', 0), deformation_data.get('eyy', 0), deformation_data.get('eyz', 0)],
                [deformation_data.get('ezx', 0), deformation_data.get('ezy', 0), deformation_data.get('ezz', 0)]
            ]) + np.eye(3)
            
            # Apply deformation-driven fabric evolution
            current_fabric = self.fabric_evolution_state['current_fabric_tensor']
            
            # Fabric evolution under finite deformation: F * fabric * F^T / |det(F)|
            det_F = np.linalg.det(deformation_gradient)
            if det_F > 0:
                evolved_fabric = (deformation_gradient @ current_fabric @ deformation_gradient.T) / det_F
                
                # Normalize to maintain proper tensor properties
                evolved_fabric = self._normalize_fabric_tensor(evolved_fabric)
                
                self.fabric_evolution_state['current_fabric_tensor'] = evolved_fabric
            
            # Store deformation history
            self.fabric_evolution_state['deformation_gradient_history'].append({
                'timestamp': current_time,
                'deformation_gradient': deformation_gradient,
                'fabric_tensor': evolved_fabric.copy()
            })
            
            self.fabric_evolution_state['last_update_time'] = current_time
            
        except Exception as e:
            logging.error(f"Deformation fabric update processing failed: {e}")
    
    def _process_thermal_fabric_update(self, thermal_data):
        """Process real-time thermal data for fabric tensor evolution"""
        try:
            current_time = time.time()
            temperature = thermal_data.get('temperature_kelvin', 300)
            
            # Store temperature history
            self.fabric_evolution_state['temperature_history'].append({
                'timestamp': current_time,
                'temperature': temperature
            })
            
            # Temperature-driven fabric recrystallization
            if temperature > 673:  # Above 400°C, significant recrystallization
                recrystallization_rate = (temperature - 673) / 500  # Normalized rate
                
                current_fabric = self.fabric_evolution_state['current_fabric_tensor']
                
                # Apply thermal weakening/strengthening
                thermal_factor = self._calculate_thermal_fabric_factor(temperature)
                thermally_evolved_fabric = self._apply_thermal_fabric_evolution(current_fabric, thermal_factor)
                
                self.fabric_evolution_state['current_fabric_tensor'] = thermally_evolved_fabric
            
            self.fabric_evolution_state['last_update_time'] = current_time
            
        except Exception as e:
            logging.error(f"Thermal fabric update processing failed: {e}")
    
    def _process_stress_fabric_update(self, stress_data):
        """Process real-time stress field changes for fabric tensor evolution"""
        try:
            current_time = time.time()
            
            # Extract stress tensor components
            stress_tensor = np.array([
                [stress_data.get('sigma_xx', 0), stress_data.get('sigma_xy', 0), stress_data.get('sigma_xz', 0)],
                [stress_data.get('sigma_xy', 0), stress_data.get('sigma_yy', 0), stress_data.get('sigma_yz', 0)],
                [stress_data.get('sigma_xz', 0), stress_data.get('sigma_yz', 0), stress_data.get('sigma_zz', 0)]
            ])
            
            # Calculate stress-driven fabric evolution
            current_fabric = self.fabric_evolution_state['current_fabric_tensor']
            
            # Apply stress-induced fabric rotation
            stress_evolved_fabric = self._apply_stress_fabric_evolution(current_fabric, stress_tensor)
            
            self.fabric_evolution_state['current_fabric_tensor'] = stress_evolved_fabric
            self.fabric_evolution_state['last_update_time'] = current_time
            
        except Exception as e:
            logging.error(f"Stress fabric update processing failed: {e}")
    
    def _apply_fabric_strength_change(self, fabric_tensor, strength_factor):
        """Apply strength change to fabric tensor"""
        try:
            # Decompose fabric tensor
            eigenvals, eigenvecs = np.linalg.eigh(fabric_tensor)
            
            # Modify eigenvalues to change fabric strength
            modified_eigenvals = eigenvals * strength_factor
            
            # Ensure positive definite and normalize
            modified_eigenvals = np.maximum(modified_eigenvals, 0.1)
            modified_eigenvals = modified_eigenvals / np.sum(modified_eigenvals) * 3  # Maintain trace
            
            # Reconstruct tensor
            modified_fabric = eigenvecs @ np.diag(modified_eigenvals) @ eigenvecs.T
            
            return modified_fabric
            
        except Exception as e:
            logging.warning(f"Fabric strength change application failed: {e}")
            return fabric_tensor
    
    def _normalize_fabric_tensor(self, fabric_tensor):
        """Normalize fabric tensor to maintain proper tensor properties"""
        try:
            # Ensure symmetry
            symmetric_fabric = 0.5 * (fabric_tensor + fabric_tensor.T)
            
            # Ensure positive definite
            eigenvals, eigenvecs = np.linalg.eigh(symmetric_fabric)
            eigenvals = np.maximum(eigenvals, 0.01)  # Minimum eigenvalue
            
            # Maintain unit determinant for volume conservation
            eigenvals = eigenvals / np.power(np.prod(eigenvals), 1/3)
            
            normalized_fabric = eigenvecs @ np.diag(eigenvals) @ eigenvecs.T
            
            return normalized_fabric
            
        except Exception as e:
            logging.warning(f"Fabric tensor normalization failed: {e}")
            return fabric_tensor
    
    def _calculate_thermal_fabric_factor(self, temperature):
        """Calculate thermal influence factor on fabric evolution"""
        try:
            # Temperature-dependent fabric evolution parameters
            if temperature < 473:  # Below 200°C
                thermal_factor = 1.0  # No significant change
            elif temperature < 673:  # 200-400°C
                thermal_factor = 1.0 - (temperature - 473) / 400 * 0.2  # Slight weakening
            elif temperature < 1073:  # 400-800°C
                thermal_factor = 0.8 + (temperature - 673) / 400 * 0.4  # Recovery and strengthening
            else:  # Above 800°C
                thermal_factor = 1.2 - min((temperature - 1073) / 500 * 0.5, 0.8)  # Gradual weakening
            
            return max(thermal_factor, 0.2)  # Minimum factor
            
        except Exception as e:
            logging.warning(f"Thermal fabric factor calculation failed: {e}")
            return 1.0
    
    def _apply_thermal_fabric_evolution(self, fabric_tensor, thermal_factor):
        """Apply thermal evolution to fabric tensor"""
        try:
            if abs(thermal_factor - 1.0) < 0.01:
                return fabric_tensor  # No significant change
            
            # Decompose fabric tensor
            eigenvals, eigenvecs = np.linalg.eigh(fabric_tensor)
            
            # Apply thermal modification
            if thermal_factor < 1.0:  # Fabric weakening
                # Reduce anisotropy, move towards isotropy
                mean_eigenval = np.mean(eigenvals)
                thermally_modified_eigenvals = eigenvals * thermal_factor + mean_eigenval * (1 - thermal_factor)
            else:  # Fabric strengthening
                # Enhance anisotropy
                mean_eigenval = np.mean(eigenvals)
                thermally_modified_eigenvals = eigenvals + (eigenvals - mean_eigenval) * (thermal_factor - 1)
            
            # Reconstruct tensor
            thermally_evolved_fabric = eigenvecs @ np.diag(thermally_modified_eigenvals) @ eigenvecs.T
            
            return self._normalize_fabric_tensor(thermally_evolved_fabric)
            
        except Exception as e:
            logging.warning(f"Thermal fabric evolution application failed: {e}")
            return fabric_tensor
    
    def _apply_stress_fabric_evolution(self, fabric_tensor, stress_tensor):
        """Apply stress-driven fabric evolution"""
        try:
            # Calculate stress deviator
            mean_stress = np.trace(stress_tensor) / 3
            stress_deviator = stress_tensor - mean_stress * np.eye(3)
            
            # Fabric evolution rate proportional to stress deviator
            evolution_rate = 1e-9  # s^-1/Pa, typical geological strain rate coefficient
            stress_magnitude = np.linalg.norm(stress_deviator)
            
            if stress_magnitude > 1e6:  # Significant stress (> 1 MPa)
                # Calculate principal stress directions
                stress_eigenvals, stress_eigenvecs = np.linalg.eigh(stress_deviator)
                
                # Fabric tends to align with principal stress directions
                target_fabric_orientation = stress_eigenvecs
                
                # Gradual rotation towards stress-aligned orientation
                rotation_rate = evolution_rate * stress_magnitude
                max_rotation = min(rotation_rate * 3600, 0.1)  # Max rotation per update
                
                # Interpolate between current and target orientation
                current_orientation = self._extract_fabric_orientation(fabric_tensor)
                evolved_orientation = self._interpolate_orientations(
                    current_orientation, target_fabric_orientation, max_rotation
                )
                
                # Apply evolved orientation to fabric tensor
                fabric_eigenvals, _ = np.linalg.eigh(fabric_tensor)
                stress_evolved_fabric = evolved_orientation @ np.diag(fabric_eigenvals) @ evolved_orientation.T
                
                return self._normalize_fabric_tensor(stress_evolved_fabric)
            
            return fabric_tensor
            
        except Exception as e:
            logging.warning(f"Stress fabric evolution application failed: {e}")
            return fabric_tensor
    
    def _extract_fabric_orientation(self, fabric_tensor):
        """Extract orientation matrix from fabric tensor"""
        try:
            _, eigenvecs = np.linalg.eigh(fabric_tensor)
            return eigenvecs
        except:
            return np.eye(3)
    
    def _interpolate_orientations(self, orientation1, orientation2, alpha):
        """Interpolate between two orientation matrices using quaternions"""
        try:
            # Convert to quaternions
            q1 = self._rotation_matrix_to_quaternion(orientation1)
            q2 = self._rotation_matrix_to_quaternion(orientation2)
            
            # Spherical linear interpolation (SLERP)
            dot_product = np.dot(q1, q2)
            
            # Ensure shortest path
            if dot_product < 0:
                q2 = -q2
                dot_product = -dot_product
            
            # Interpolation
            if dot_product > 0.9995:  # Quaternions very close, use linear interpolation
                interpolated_q = (1 - alpha) * q1 + alpha * q2
            else:  # Use SLERP
                theta = np.arccos(abs(dot_product))
                sin_theta = np.sin(theta)
                interpolated_q = (np.sin((1 - alpha) * theta) * q1 + np.sin(alpha * theta) * q2) / sin_theta
            
            # Normalize
            interpolated_q = interpolated_q / np.linalg.norm(interpolated_q)
            
            # Convert back to rotation matrix
            return self._quaternion_to_rotation_matrix(interpolated_q)
            
        except Exception as e:
            logging.warning(f"Orientation interpolation failed: {e}")
            return orientation1
    
    def _update_fabric_stability_index(self):
        """Update fabric stability index based on recent evolution"""
        try:
            if len(self.fabric_evolution_state['fabric_history']) < 2:
                return
            
            # Calculate fabric change rate over recent history
            recent_fabrics = self.fabric_evolution_state['fabric_history'][-10:]  # Last 10 updates
            
            fabric_changes = []
            for i in range(1, len(recent_fabrics)):
                fabric_change = np.linalg.norm(
                    recent_fabrics[i]['fabric_tensor'] - recent_fabrics[i-1]['fabric_tensor']
                )
                time_diff = recent_fabrics[i]['timestamp'] - recent_fabrics[i-1]['timestamp']
                
                if time_diff > 0:
                    fabric_changes.append(fabric_change / time_diff)
            
            if fabric_changes:
                # Stability inversely related to change rate
                avg_change_rate = np.mean(fabric_changes)
                stability_index = 1.0 / (1.0 + avg_change_rate * 1e6)  # Normalized
                
                self.fabric_evolution_state['fabric_stability_index'] = stability_index
            
        except Exception as e:
            logging.warning(f"Fabric stability index update failed: {e}")
    
    def get_current_fabric_tensor(self):
        """Get current fabric tensor with real-time evolution"""
        try:
            if hasattr(self, 'fabric_evolution_state'):
                return self.fabric_evolution_state['current_fabric_tensor']
            else:
                return np.eye(3)
        except:
            return np.eye(3)
    
    def get_fabric_evolution_metrics(self):
        """Get comprehensive fabric evolution metrics"""
        try:
            if not hasattr(self, 'fabric_evolution_state'):
                return {}
            
            return {
                'current_fabric_tensor': self.fabric_evolution_state['current_fabric_tensor'],
                'fabric_stability_index': self.fabric_evolution_state['fabric_stability_index'],
                'evolution_rate_tensor': self.fabric_evolution_state['evolution_rate_tensor'],
                'history_length': len(self.fabric_evolution_state['fabric_history']),
                'last_update_time': self.fabric_evolution_state['last_update_time'],
                'fabric_anisotropy_degree': self._calculate_current_anisotropy_degree(),
                'principal_fabric_directions': self._get_principal_fabric_directions()
            }
            
        except Exception as e:
            logging.error(f"Fabric evolution metrics retrieval failed: {e}")
            return {}
    
    def _calculate_current_anisotropy_degree(self):
        """Calculate current degree of anisotropy from fabric tensor"""
        try:
            fabric_tensor = self.get_current_fabric_tensor()
            eigenvals, _ = np.linalg.eigh(fabric_tensor)
            eigenvals = np.sort(eigenvals)[::-1]  # Descending order
            
            # Anisotropy degree: ratio of max to min eigenvalue
            if eigenvals[2] > 0:
                anisotropy_degree = eigenvals[0] / eigenvals[2]
            else:
                anisotropy_degree = 1.0
            
            return anisotropy_degree
            
        except Exception as e:
            logging.warning(f"Current anisotropy degree calculation failed: {e}")
            return 1.0
    
    def _get_principal_fabric_directions(self):
        """Get principal fabric directions from current fabric tensor"""
        try:
            fabric_tensor = self.get_current_fabric_tensor()
            eigenvals, eigenvecs = np.linalg.eigh(fabric_tensor)
            
            # Sort by eigenvalue magnitude
            sorted_indices = np.argsort(eigenvals)[::-1]
            sorted_eigenvals = eigenvals[sorted_indices]
            sorted_eigenvecs = eigenvecs[:, sorted_indices]
            
            return {
                'maximum_fabric_direction': sorted_eigenvecs[:, 0],
                'intermediate_fabric_direction': sorted_eigenvecs[:, 1],
                'minimum_fabric_direction': sorted_eigenvecs[:, 2],
                'eigenvalues': sorted_eigenvals
            }
            
        except Exception as e:
            logging.warning(f"Principal fabric directions calculation failed: {e}")
            return {
                'maximum_fabric_direction': np.array([1, 0, 0]),
                'intermediate_fabric_direction': np.array([0, 1, 0]),
                'minimum_fabric_direction': np.array([0, 0, 1]),
                'eigenvalues': np.array([1, 1, 1])
            }    
    # Advanced Stress-Strain Coupling for Anisotropic Material Evolution
    
    def _initialize_stress_strain_coupling_system(self):
        """Initialize advanced stress-strain coupling system for anisotropic material evolution"""
        try:
            self.stress_strain_coupling_state = {
                'current_stiffness_tensor': self.stiffness_matrix.copy(),
                'evolving_compliance_tensor': self.compliance_matrix.copy(),
                'damage_tensor': np.eye(3),
                'plastic_strain_tensor': np.zeros((3, 3)),
                'accumulated_plastic_strain': 0.0,
                'stress_history': [],
                'strain_history': [],
                'material_hardening_state': {
                    'isotropic_hardening': 0.0,
                    'kinematic_hardening_tensor': np.zeros((3, 3)),
                    'anisotropic_hardening_tensor': np.eye(3)
                },
                'microcrack_density_tensor': np.zeros((3, 3)),
                'crystal_defect_density': 0.0,
                'recrystallization_fraction': 0.0,
                'grain_size_evolution': 1.0,
                'texture_evolution_state': {
                    'orientation_distribution': np.eye(3),
                    'texture_strength': 0.5,
                    'slip_system_activities': np.zeros(12)  # 12 slip systems for cubic crystals
                }
            }
            
            # Initialize constitutive model evolution parameters
            self.evolution_parameters = {
                'elastic_degradation_rate': 1e-6,  # /strain
                'plastic_hardening_modulus': 1e9,   # Pa
                'damage_threshold': 0.001,          # strain
                'recrystallization_threshold': 0.1,  # accumulated strain
                'grain_growth_rate': 1e-8,          # /s
                'texture_evolution_rate': 1e-7     # /strain
            }
            
            logging.info("Stress-strain coupling system initialized successfully")
            
        except Exception as e:
            logging.error(f"Stress-strain coupling system initialization failed: {e}")
    
    def calculate_coupled_stress_strain_response(self, strain_increment, **kwargs):
        """Calculate stress response with full anisotropic material evolution coupling"""
        try:
            if not hasattr(self, 'stress_strain_coupling_state'):
                self._initialize_stress_strain_coupling_system()
            
            # Get current state
            current_time = kwargs.get('time', 0.0)
            temperature = kwargs.get('temperature', 300.0)
            pressure = kwargs.get('pressure', 0.1)
            strain_rate = kwargs.get('strain_rate', 1e-15)
            
            # Total strain update
            total_strain = kwargs.get('total_strain', np.zeros(6))
            new_total_strain = total_strain + strain_increment
            
            # Decompose strain increment into elastic and plastic parts
            elastic_strain_increment, plastic_strain_increment = self._decompose_strain_increment(
                strain_increment, total_strain, **kwargs
            )
            
            # Update material state based on strain evolution
            self._update_material_state_from_strain(plastic_strain_increment, strain_rate, 
                                                   temperature, pressure)
            
            # Calculate stress increment using evolved material properties
            evolved_stiffness = self._get_evolved_stiffness_tensor()
            stress_increment = evolved_stiffness @ elastic_strain_increment
            
            # Apply stress-dependent material evolution
            current_stress = kwargs.get('current_stress', np.zeros(6)) + stress_increment
            self._update_material_state_from_stress(current_stress, strain_rate, temperature)
            
            # Update fabric tensor based on stress-strain coupling
            self._update_fabric_from_stress_strain_coupling(current_stress, new_total_strain, 
                                                          strain_rate, temperature)
            
            # Store history for evolution tracking
            self._store_stress_strain_history(current_stress, new_total_strain, current_time)
            
            # Apply geological constraints and external data corrections
            constrained_stress = self._apply_coupled_geological_constraints(
                current_stress, new_total_strain, **kwargs
            )
            
            return constrained_stress, self._get_material_evolution_metrics()
            
        except Exception as e:
            logging.error(f"Coupled stress-strain response calculation failed: {e}")
            # Fallback to uncoupled calculation
            return self.calculate_stress(strain_increment, **kwargs), {}
    
    def _decompose_strain_increment(self, strain_increment, total_strain, **kwargs):
        """Decompose strain increment into elastic and plastic components"""
        try:
            # Calculate trial elastic stress
            current_stiffness = self._get_evolved_stiffness_tensor()
            trial_stress = current_stiffness @ strain_increment
            
            # Check yield condition using anisotropic yield surface
            yield_stress = self._calculate_anisotropic_yield_stress(**kwargs)
            stress_magnitude = np.linalg.norm(trial_stress)
            
            if stress_magnitude > yield_stress:
                # Plastic deformation occurs
                yield_ratio = yield_stress / stress_magnitude
                
                # Elastic strain increment (up to yield)
                elastic_strain_increment = strain_increment * yield_ratio
                
                # Plastic strain increment (beyond yield)
                plastic_strain_increment = strain_increment * (1 - yield_ratio)
                
                # Apply plastic flow rule with anisotropic corrections
                plastic_strain_increment = self._apply_anisotropic_flow_rule(
                    plastic_strain_increment, trial_stress, **kwargs
                )
            else:
                # Purely elastic deformation
                elastic_strain_increment = strain_increment
                plastic_strain_increment = np.zeros_like(strain_increment)
            
            return elastic_strain_increment, plastic_strain_increment
            
        except Exception as e:
            logging.warning(f"Strain increment decomposition failed: {e}")
            return strain_increment, np.zeros_like(strain_increment)
    
    def _calculate_anisotropic_yield_stress(self, **kwargs):
        """Calculate anisotropic yield stress considering material evolution"""
        try:
            base_yield_stress = kwargs.get('yield_stress', 50e6)  # 50 MPa default
            
            # Isotropic hardening contribution
            isotropic_hardening = self.stress_strain_coupling_state['material_hardening_state']['isotropic_hardening']
            
            # Anisotropic hardening contribution
            anisotropic_hardening_tensor = self.stress_strain_coupling_state['material_hardening_state']['anisotropic_hardening_tensor']
            anisotropic_factor = np.trace(anisotropic_hardening_tensor) / 3
            
            # Damage-induced strength reduction
            damage_tensor = self.stress_strain_coupling_state['damage_tensor']
            damage_factor = 1.0 - np.trace(damage_tensor) / 3
            
            # Grain size strengthening (Hall-Petch effect)
            grain_size = self.stress_strain_coupling_state['grain_size_evolution']
            hall_petch_factor = 1.0 / np.sqrt(grain_size)
            
            # Texture strengthening/weakening
            texture_strength = self.stress_strain_coupling_state['texture_evolution_state']['texture_strength']
            texture_factor = 1.0 + texture_strength * 0.3
            
            # Combined anisotropic yield stress
            anisotropic_yield_stress = (base_yield_stress + isotropic_hardening) * \
                                     (1 + anisotropic_factor) * damage_factor * \
                                     hall_petch_factor * texture_factor
            
            return max(anisotropic_yield_stress, base_yield_stress * 0.1)  # Minimum 10% of base strength
            
        except Exception as e:
            logging.warning(f"Anisotropic yield stress calculation failed: {e}")
            return kwargs.get('yield_stress', 50e6)
    
    def _apply_anisotropic_flow_rule(self, plastic_strain_increment, stress_state, **kwargs):
        """Apply anisotropic plastic flow rule with crystallographic considerations"""
        try:
            # Get current fabric orientation
            fabric_tensor = self.get_current_fabric_tensor()
            
            # Calculate flow direction based on anisotropic yield surface gradient
            stress_deviator = self._calculate_stress_deviator(stress_state)
            
            # Anisotropic flow direction considering fabric
            flow_direction = self._calculate_anisotropic_flow_direction(stress_deviator, fabric_tensor)
            
            # Scale plastic strain increment by flow direction
            magnitude = np.linalg.norm(plastic_strain_increment)
            anisotropic_plastic_strain = flow_direction * magnitude
            
            # Apply crystallographic slip system constraints
            anisotropic_plastic_strain = self._apply_slip_system_constraints(
                anisotropic_plastic_strain, **kwargs
            )
            
            return anisotropic_plastic_strain
            
        except Exception as e:
            logging.warning(f"Anisotropic flow rule application failed: {e}")
            return plastic_strain_increment
    
    def _calculate_stress_deviator(self, stress_vector):
        """Calculate stress deviator tensor from stress vector"""
        # Convert to tensor form
        stress_tensor = np.array([
            [stress_vector[0], stress_vector[5], stress_vector[4]],
            [stress_vector[5], stress_vector[1], stress_vector[3]],
            [stress_vector[4], stress_vector[3], stress_vector[2]]
        ])
        
        # Calculate deviator
        mean_stress = np.trace(stress_tensor) / 3
        stress_deviator = stress_tensor - mean_stress * np.eye(3)
        
        return stress_deviator
    
    def _calculate_anisotropic_flow_direction(self, stress_deviator, fabric_tensor):
        """Calculate anisotropic plastic flow direction"""
        try:
            # Base flow direction (von Mises-like)
            base_flow = stress_deviator / np.linalg.norm(stress_deviator)
            
            # Fabric-modified flow direction
            # Fabric tensor modifies flow to align with material anisotropy
            fabric_modified_flow = fabric_tensor @ base_flow @ fabric_tensor.T
            
            # Normalize and convert back to vector form
            flow_magnitude = np.linalg.norm(fabric_modified_flow)
            if flow_magnitude > 1e-12:
                normalized_flow = fabric_modified_flow / flow_magnitude
            else:
                normalized_flow = base_flow
            
            # Convert tensor back to vector form (Voigt notation)
            flow_vector = np.array([
                normalized_flow[0, 0],
                normalized_flow[1, 1],
                normalized_flow[2, 2],
                normalized_flow[1, 2],
                normalized_flow[0, 2],
                normalized_flow[0, 1]
            ])
            
            return flow_vector
            
        except Exception as e:
            logging.warning(f"Anisotropic flow direction calculation failed: {e}")
            # Fallback to isotropic flow
            return stress_deviator.flatten()[:6] / np.linalg.norm(stress_deviator)
    
    def _apply_slip_system_constraints(self, plastic_strain, **kwargs):
        """Apply crystallographic slip system constraints to plastic strain"""
        try:
            # Get active slip systems
            slip_activities = self.stress_strain_coupling_state['texture_evolution_state']['slip_system_activities']
            
            # Define slip system normals and directions (for cubic crystals)
            slip_systems = self._get_slip_system_geometry()
            
            # Project plastic strain onto active slip systems
            constrained_strain = np.zeros_like(plastic_strain)
            
            for i, activity in enumerate(slip_activities):
                if activity > 0.1 and i < len(slip_systems):  # Only consider active systems
                    slip_normal, slip_direction = slip_systems[i]
                    
                    # Schmid tensor for this slip system
                    schmid_tensor = 0.5 * (np.outer(slip_direction, slip_normal) + 
                                          np.outer(slip_normal, slip_direction))
                    
                    # Project strain onto this slip system
                    slip_strain_tensor = np.tensordot(plastic_strain[:3], schmid_tensor) * activity
                    
                    # Add to constrained strain
                    constrained_strain[:3] += slip_strain_tensor.flatten()[:3]
                    # Shear components
                    constrained_strain[3:] += activity * plastic_strain[3:] / len(slip_activities)
            
            return constrained_strain
            
        except Exception as e:
            logging.warning(f"Slip system constraint application failed: {e}")
            return plastic_strain
    
    def _get_slip_system_geometry(self):
        """Define slip system geometry for common crystal structures"""
        # FCC slip systems (12 systems: {111}<110>)
        slip_systems = []
        
        # {111} planes
        planes = [
            np.array([1, 1, 1]) / np.sqrt(3),
            np.array([-1, 1, 1]) / np.sqrt(3),
            np.array([1, -1, 1]) / np.sqrt(3),
            np.array([1, 1, -1]) / np.sqrt(3)
        ]
        
        # <110> directions
        directions = [
            np.array([1, -1, 0]) / np.sqrt(2),
            np.array([1, 0, -1]) / np.sqrt(2),
            np.array([0, 1, -1]) / np.sqrt(2)
        ]
        
        # Generate all slip systems
        for plane in planes:
            for direction in directions:
                # Check if direction lies in plane (dot product = 0)
                if abs(np.dot(plane, direction)) < 1e-10:
                    slip_systems.append((plane, direction))
        
        return slip_systems[:12]  # Limit to 12 systems
    
    def _update_material_state_from_strain(self, plastic_strain_increment, strain_rate, temperature, pressure):
        """Update material state based on plastic strain evolution"""
        try:
            # Update accumulated plastic strain
            plastic_strain_magnitude = np.linalg.norm(plastic_strain_increment)
            self.stress_strain_coupling_state['accumulated_plastic_strain'] += plastic_strain_magnitude
            
            # Update plastic strain tensor
            plastic_strain_tensor_increment = np.array([
                [plastic_strain_increment[0], plastic_strain_increment[5]/2, plastic_strain_increment[4]/2],
                [plastic_strain_increment[5]/2, plastic_strain_increment[1], plastic_strain_increment[3]/2],
                [plastic_strain_increment[4]/2, plastic_strain_increment[3]/2, plastic_strain_increment[2]]
            ])
            
            self.stress_strain_coupling_state['plastic_strain_tensor'] += plastic_strain_tensor_increment
            
            # Update hardening state
            self._update_hardening_state(plastic_strain_magnitude, strain_rate, temperature)
            
            # Update damage evolution
            self._update_damage_evolution(plastic_strain_magnitude, temperature)
            
            # Update recrystallization
            self._update_recrystallization_state(plastic_strain_magnitude, temperature, strain_rate)
            
            # Update grain size evolution
            self._update_grain_size_evolution(plastic_strain_magnitude, temperature, strain_rate)
            
            # Update texture evolution
            self._update_texture_evolution(plastic_strain_tensor_increment, temperature)
            
        except Exception as e:
            logging.warning(f"Material state update from strain failed: {e}")
    
    def _update_material_state_from_stress(self, stress_state, strain_rate, temperature):
        """Update material state based on stress evolution"""
        try:
            # Update microcrack density based on stress state
            self._update_microcrack_density(stress_state, temperature)
            
            # Update crystal defect density
            self._update_crystal_defect_density(stress_state, strain_rate, temperature)
            
            # Update slip system activities based on resolved shear stresses
            self._update_slip_system_activities(stress_state)
            
        except Exception as e:
            logging.warning(f"Material state update from stress failed: {e}")
    
    def _update_hardening_state(self, plastic_strain_magnitude, strain_rate, temperature):
        """Update isotropic and kinematic hardening states"""
        try:
            hardening_state = self.stress_strain_coupling_state['material_hardening_state']
            
            # Isotropic hardening (strain and temperature dependent)
            hardening_rate = self.evolution_parameters['plastic_hardening_modulus']
            thermal_softening = max(1.0 - (temperature - 300) / 1000, 0.1)
            rate_strengthening = 1.0 + np.log10(strain_rate / 1e-15) * 0.1 if strain_rate > 1e-15 else 1.0
            
            hardening_increment = hardening_rate * plastic_strain_magnitude * thermal_softening * rate_strengthening
            hardening_state['isotropic_hardening'] += hardening_increment
            
            # Anisotropic hardening (fabric-dependent)
            fabric_tensor = self.get_current_fabric_tensor()
            anisotropic_hardening_increment = fabric_tensor * hardening_increment * 0.1
            hardening_state['anisotropic_hardening_tensor'] += anisotropic_hardening_increment
            
        except Exception as e:
            logging.warning(f"Hardening state update failed: {e}")
    
    def _update_damage_evolution(self, plastic_strain_magnitude, temperature):
        """Update damage tensor evolution"""
        try:
            if plastic_strain_magnitude > self.evolution_parameters['damage_threshold']:
                # Damage evolution rate
                damage_rate = self.evolution_parameters['elastic_degradation_rate']
                
                # Temperature-dependent damage evolution
                thermal_factor = 1.0 + (temperature - 300) / 500 if temperature > 300 else 1.0
                
                # Anisotropic damage evolution
                fabric_tensor = self.get_current_fabric_tensor()
                damage_increment = fabric_tensor * damage_rate * plastic_strain_magnitude * thermal_factor
                
                # Ensure damage doesn't exceed 0.9 (maintain some material integrity)
                current_damage = self.stress_strain_coupling_state['damage_tensor']
                updated_damage = np.minimum(current_damage + damage_increment, 0.9 * np.eye(3))
                
                self.stress_strain_coupling_state['damage_tensor'] = updated_damage
                
        except Exception as e:
            logging.warning(f"Damage evolution update failed: {e}")
    
    def _get_evolved_stiffness_tensor(self):
        """Get current evolved stiffness tensor including all material evolution effects"""
        try:
            base_stiffness = self.stiffness_matrix.copy()
            
            # Apply damage effects
            damage_tensor = self.stress_strain_coupling_state['damage_tensor']
            damage_factor = np.eye(6)
            
            # Map 3x3 damage tensor to 6x6 stiffness reduction
            damage_factor[0, 0] = 1 - damage_tensor[0, 0]
            damage_factor[1, 1] = 1 - damage_tensor[1, 1]
            damage_factor[2, 2] = 1 - damage_tensor[2, 2]
            damage_factor[3, 3] = 1 - damage_tensor[1, 2]
            damage_factor[4, 4] = 1 - damage_tensor[0, 2]
            damage_factor[5, 5] = 1 - damage_tensor[0, 1]
            
            # Apply recrystallization effects
            recrystallization_fraction = self.stress_strain_coupling_state['recrystallization_fraction']
            recryst_factor = 1.0 + recrystallization_fraction * 0.2  # 20% strengthening
            
            # Apply grain size effects (Hall-Petch)
            grain_size = self.stress_strain_coupling_state['grain_size_evolution']
            hall_petch_factor = 1.0 / np.sqrt(grain_size)
            
            # Apply texture effects
            texture_strength = self.stress_strain_coupling_state['texture_evolution_state']['texture_strength']
            texture_factor = 1.0 + texture_strength * 0.3
            
            # Combined evolved stiffness
            evolved_stiffness = base_stiffness * damage_factor * recryst_factor * hall_petch_factor * texture_factor
            
            return evolved_stiffness
            
        except Exception as e:
            logging.warning(f"Evolved stiffness tensor calculation failed: {e}")
            return self.stiffness_matrix
    
    def _get_material_evolution_metrics(self):
        """Get comprehensive material evolution metrics"""
        try:
            return {
                'accumulated_plastic_strain': self.stress_strain_coupling_state['accumulated_plastic_strain'],
                'damage_tensor': self.stress_strain_coupling_state['damage_tensor'],
                'isotropic_hardening': self.stress_strain_coupling_state['material_hardening_state']['isotropic_hardening'],
                'recrystallization_fraction': self.stress_strain_coupling_state['recrystallization_fraction'],
                'grain_size_evolution': self.stress_strain_coupling_state['grain_size_evolution'],
                'texture_strength': self.stress_strain_coupling_state['texture_evolution_state']['texture_strength'],
                'fabric_anisotropy_degree': self._calculate_current_anisotropy_degree(),
                'material_integrity_index': 1.0 - np.trace(self.stress_strain_coupling_state['damage_tensor']) / 3
            }
        except Exception as e:
            logging.warning(f"Material evolution metrics retrieval failed: {e}")
            return {}

class OrthotropicModel:
    """Advanced orthotropic constitutive model for layered geological materials"""
    
    def __init__(self, parameters=None, principal_directions=None, data_integration=None):
        self.name = "orthotropic"
        self.principal_directions = principal_directions or np.eye(3)
        self.data_integration = data_integration
        
        # Default parameters for orthotropic geological materials (e.g., gneiss, schist)
        self.default_parameters = {
            'E1': 25e9,    # Pa - Young's modulus in direction 1
            'E2': 20e9,    # Pa - Young's modulus in direction 2
            'E3': 15e9,    # Pa - Young's modulus in direction 3
            'nu12': 0.25,  # Poisson's ratio 1-2
            'nu13': 0.3,   # Poisson's ratio 1-3
            'nu23': 0.35,  # Poisson's ratio 2-3
            'G12': 8e9,    # Pa - Shear modulus 1-2 plane
            'G13': 7e9,    # Pa - Shear modulus 1-3 plane
            'G23': 6e9,    # Pa - Shear modulus 2-3 plane
            'rho': 2600    # kg/m³ - Density
        }
        
        self.parameters = parameters or self.default_parameters
        self._validate_orthotropic_parameters()
        self._compute_orthotropic_matrices()
        self._initialize_external_data_integration()
        
    def _initialize_external_data_integration(self):
        """Initialize connections to geological databases for orthotropic properties"""
        try:
            if self.data_integration:
                from .external_data_connectors import DataIntegrationManager
                from .database_integration import DatabaseIntegration
                
                self.external_data_manager = DataIntegrationManager()
                self.db_integration = DatabaseIntegration()
                
        except ImportError:
            logging.warning("External data integration not available for orthotropic properties")
            self.external_data_manager = None
            self.db_integration = None
    
    def _validate_orthotropic_parameters(self):
        """Validate orthotropic parameters for thermodynamic consistency"""
        E1, E2, E3 = self.parameters['E1'], self.parameters['E2'], self.parameters['E3']
        nu12, nu13, nu23 = self.parameters['nu12'], self.parameters['nu13'], self.parameters['nu23']
        
        # Calculate derived Poisson's ratios
        nu21 = nu12 * E2 / E1
        nu31 = nu13 * E3 / E1
        nu32 = nu23 * E3 / E2
        
        # Check thermodynamic constraints
        if any(nu >= 1 for nu in [nu12, nu13, nu23, nu21, nu31, nu32]):
            raise ValueError("Poisson's ratios must be less than 1")
        
        # Check positive definiteness condition
        determinant = (1 - nu12*nu21 - nu23*nu32 - nu13*nu31 - 2*nu21*nu32*nu13) / (E1*E2*E3)
        if determinant <= 0:
            raise ValueError("Material parameters violate thermodynamic constraints")
        
        self.parameters.update({
            'nu21': nu21, 'nu31': nu31, 'nu32': nu32,
            'determinant': determinant
        })
    
    def _compute_orthotropic_matrices(self):
        """Compute the 6x6 compliance and stiffness matrices for orthotropy"""
        E1, E2, E3 = self.parameters['E1'], self.parameters['E2'], self.parameters['E3']
        nu12, nu13, nu23 = self.parameters['nu12'], self.parameters['nu13'], self.parameters['nu23']
        nu21, nu31, nu32 = self.parameters['nu21'], self.parameters['nu31'], self.parameters['nu32']
        G12, G13, G23 = self.parameters['G12'], self.parameters['G13'], self.parameters['G23']
        
        # Compliance matrix
        S = np.zeros((6, 6))
        
        # Diagonal terms
        S[0, 0] = 1 / E1
        S[1, 1] = 1 / E2
        S[2, 2] = 1 / E3
        S[3, 3] = 1 / G23
        S[4, 4] = 1 / G13
        S[5, 5] = 1 / G12
        
        # Off-diagonal terms
        S[0, 1] = S[1, 0] = -nu21 / E2
        S[0, 2] = S[2, 0] = -nu31 / E3
        S[1, 2] = S[2, 1] = -nu32 / E3
        
        self.compliance_matrix = S
        self.stiffness_matrix = np.linalg.inv(S)
        
        # Store principal stiffness values for analysis
        self.principal_stiffnesses = {
            'C11': self.stiffness_matrix[0, 0],
            'C22': self.stiffness_matrix[1, 1],
            'C33': self.stiffness_matrix[2, 2],
            'C12': self.stiffness_matrix[0, 1],
            'C13': self.stiffness_matrix[0, 2],
            'C23': self.stiffness_matrix[1, 2],
            'C44': self.stiffness_matrix[3, 3],
            'C55': self.stiffness_matrix[4, 4],
            'C66': self.stiffness_matrix[5, 5]
        }
    
    def calculate_stress(self, strain, **kwargs):
        """Calculate stress using full orthotropic constitutive relations"""
        try:
            # Transform strain to principal material coordinate system
            strain_principal = self._transform_to_material_coordinates(strain, **kwargs)
            
            # Apply constitutive relation
            stress_principal = self.stiffness_matrix @ strain_principal
            
            # Apply geological constraints and corrections
            stress_principal = self._apply_orthotropic_corrections(stress_principal, **kwargs)
            
            # Transform back to global coordinate system
            stress = self._transform_from_material_coordinates(stress_principal, **kwargs)
            
            return stress
            
        except Exception as e:
            logging.error(f"Orthotropic stress calculation failed: {e}")
            return np.zeros_like(strain)
    
    def _transform_to_material_coordinates(self, strain, **kwargs):
        """Transform strain tensor to principal material coordinate system using 4th-order tensor rotation"""
        try:
            # Get real-time material orientation from external data sources
            orientation_data = self._get_comprehensive_material_orientation(**kwargs)
            
            if orientation_data['confidence'] < 0.3:
                self.logger.warning(f"Low confidence material orientation data: {orientation_data['confidence']:.3f}")
            
            # Extract rotation matrix and crystallographic data
            rotation_matrix = orientation_data['rotation_matrix']
            euler_angles = orientation_data['euler_angles']
            fabric_tensor = orientation_data['fabric_tensor']
            
            # Convert strain tensor to 4th-order tensor format
            strain_4th = self._convert_strain_to_4th_order_tensor(strain)
            
            # Apply 4th-order tensor rotation using Bond transformation
            # T_ijkl = R_im * R_jn * R_ko * R_lp * T_mnop
            rotated_strain_4th = np.zeros_like(strain_4th)
            for i in range(3):
                for j in range(3):
                    for k in range(3):
                        for l in range(3):
                            for m in range(3):
                                for n in range(3):
                                    for o in range(3):
                                        for p in range(3):
                                            rotated_strain_4th[i,j,k,l] += (
                                                rotation_matrix[i,m] * rotation_matrix[j,n] * 
                                                rotation_matrix[k,o] * rotation_matrix[l,p] * 
                                                strain_4th[m,n,o,p]
                                            )
            
            # Convert back to 2nd-order strain tensor format
            rotated_strain = self._convert_4th_order_to_strain_tensor(rotated_strain_4th)
            
            # Apply fabric-weighted corrections for anisotropic materials
            fabric_corrected_strain = self._apply_fabric_corrections(
                rotated_strain, fabric_tensor, orientation_data
            )
            
            # Apply crystallographic slip system corrections
            if orientation_data.get('crystallographic_data'):
                fabric_corrected_strain = self._apply_crystallographic_corrections(
                    fabric_corrected_strain, 
                    orientation_data['crystallographic_data'],
                    **kwargs
                )
            
            # Log transformation metrics
            transformation_quality = self._assess_transformation_quality(
                strain, fabric_corrected_strain, orientation_data
            )
            
            if transformation_quality < 0.7:
                self.logger.warning(
                    f"Material coordinate transformation quality: {transformation_quality:.3f}"
                )
            
            return fabric_corrected_strain
            
        except Exception as e:
            self.logger.error(f"Material coordinate transformation failed: {e}")
            # Fallback with basic rotation
            try:
                basic_orientation = self._get_material_orientation(**kwargs)
                return self._apply_basic_rotation(strain, basic_orientation)
            except:
                return strain
    
    def _transform_from_material_coordinates(self, stress, **kwargs):
        """Transform stress tensor from material to global coordinate system using 4th-order tensor rotation"""
        try:
            # Get comprehensive material orientation data
            orientation_data = self._get_comprehensive_material_orientation(**kwargs)
            
            # Use inverse rotation matrix for back-transformation
            inverse_rotation_matrix = orientation_data['rotation_matrix'].T
            fabric_tensor = orientation_data['fabric_tensor']
            
            # Apply inverse crystallographic corrections first
            if orientation_data.get('crystallographic_data'):
                stress = self._apply_inverse_crystallographic_corrections(
                    stress, orientation_data['crystallographic_data'], **kwargs
                )
            
            # Apply inverse fabric corrections
            fabric_corrected_stress = self._apply_inverse_fabric_corrections(
                stress, fabric_tensor, orientation_data
            )
            
            # Convert stress tensor to 4th-order tensor format
            stress_4th = self._convert_stress_to_4th_order_tensor(fabric_corrected_stress)
            
            # Apply inverse 4th-order tensor rotation
            # T_ijkl = R_mi * R_nj * R_ok * R_pl * T_mnop (using inverse rotation)
            rotated_stress_4th = np.zeros_like(stress_4th)
            for i in range(3):
                for j in range(3):
                    for k in range(3):
                        for l in range(3):
                            for m in range(3):
                                for n in range(3):
                                    for o in range(3):
                                        for p in range(3):
                                            rotated_stress_4th[i,j,k,l] += (
                                                inverse_rotation_matrix[m,i] * inverse_rotation_matrix[n,j] * 
                                                inverse_rotation_matrix[o,k] * inverse_rotation_matrix[p,l] * 
                                                stress_4th[m,n,o,p]
                                            )
            
            # Convert back to 2nd-order stress tensor format
            global_stress = self._convert_4th_order_to_stress_tensor(rotated_stress_4th)
            
            # Apply global coordinate system corrections
            global_stress = self._apply_global_coordinate_corrections(
                global_stress, orientation_data, **kwargs
            )
            
            # Validate stress tensor symmetry and physical constraints
            validation_results = self._validate_stress_tensor(global_stress)
            if not validation_results['is_valid']:
                self.logger.warning(
                    f"Stress tensor validation issues: {validation_results['violations']}"
                )
                # Apply corrections for physical consistency
                global_stress = self._correct_stress_tensor(global_stress, validation_results)
            
            return global_stress
            
        except Exception as e:
            self.logger.error(f"Global coordinate transformation failed: {e}")
            # Fallback with basic inverse rotation
            try:
                basic_orientation = self._get_material_orientation(**kwargs)
                return self._apply_basic_inverse_rotation(stress, basic_orientation)
            except:
                return stress
    
    def _get_comprehensive_material_orientation(self, **kwargs):
        """Get comprehensive material orientation from multi-source geological data integration"""
        try:
            location = kwargs.get('location')
            depth = kwargs.get('depth', 0.0)
            temperature = kwargs.get('temperature', 298.15)
            pressure = kwargs.get('pressure', 0.1)
            timestamp = kwargs.get('timestamp', datetime.utcnow())
            
            # Initialize comprehensive orientation data structure
            orientation_data = {
                'rotation_matrix': np.eye(3),
                'euler_angles': np.array([0.0, 0.0, 0.0]),
                'fabric_tensor': np.eye(3),
                'confidence': 0.0,
                'data_sources': [],
                'crystallographic_data': None,
                'anisotropy_degree': 1.0
            }
            
            if not location:
                self.logger.warning("No location provided for material orientation")
                return self._get_default_orientation_data()
            
            # Multi-source data integration
            data_sources = []
            confidence_weights = []
            
            # 1. External geological database integration
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                try:
                    structural_data = self.external_data_manager.get_comprehensive_structural_data(
                        location[0], location[1], depth
                    )
                    if structural_data and structural_data.get('success'):
                        data_sources.append(('external_database', structural_data, 0.8))
                        orientation_data['data_sources'].append('external_database')
                except Exception as e:
                    self.logger.debug(f"External database query failed: {e}")
            
            # 2. Real-time geological survey data
            if hasattr(self, 'data_integration_pipeline'):
                try:
                    survey_data = asyncio.run(
                        self.data_integration_pipeline.get_structural_measurements(
                            location[0], location[1], depth
                        )
                    )
                    if survey_data and survey_data.get('measurements'):
                        data_sources.append(('geological_survey', survey_data, 0.7))
                        orientation_data['data_sources'].append('geological_survey')
                except Exception as e:
                    self.logger.debug(f"Geological survey query failed: {e}")
            
            # 3. Seismic anisotropy data from ambient noise analysis
            try:
                from .ambient_noise_engine import AmbientNoiseEngine
                anisotropy_engine = AmbientNoiseEngine()
                anisotropy_data = asyncio.run(
                    anisotropy_engine.get_seismic_anisotropy(
                        location[0], location[1], depth
                    )
                )
                if anisotropy_data and anisotropy_data.get('anisotropy_tensor'):
                    data_sources.append(('seismic_anisotropy', anisotropy_data, 0.6))
                    orientation_data['data_sources'].append('seismic_anisotropy')
            except Exception as e:
                self.logger.debug(f"Seismic anisotropy query failed: {e}")
            
            # 4. Stress field data integration
            try:
                from .geological_constraints import GeologicalConstraints
                constraints = GeologicalConstraints()
                stress_field_data = constraints.get_regional_stress_field(
                    location[0], location[1], depth
                )
                if stress_field_data:
                    data_sources.append(('stress_field', stress_field_data, 0.5))
                    orientation_data['data_sources'].append('stress_field')
            except Exception as e:
                self.logger.debug(f"Stress field query failed: {e}")
            
            # 5. Fabric evolution from deformation history
            try:
                fabric_data = self._get_fabric_evolution_data(location, depth, temperature, pressure)
                if fabric_data:
                    data_sources.append(('fabric_evolution', fabric_data, 0.9))
                    orientation_data['data_sources'].append('fabric_evolution')
            except Exception as e:
                self.logger.debug(f"Fabric evolution query failed: {e}")
            
            # Integrate multi-source orientation data
            if data_sources:
                orientation_data = self._integrate_multi_source_orientation(
                    data_sources, location, depth, temperature, pressure
                )
            else:
                self.logger.warning("No orientation data sources available, using fallback")
                orientation_data = self._get_fallback_orientation_data(location, depth)
            
            # Add crystallographic data if available
            orientation_data['crystallographic_data'] = self._get_crystallographic_data(
                location, depth, temperature, pressure, orientation_data
            )
            
            # Validate orientation data quality
            orientation_data = self._validate_orientation_data(orientation_data)
            
            return orientation_data
            
        except Exception as e:
            self.logger.error(f"Comprehensive material orientation failed: {e}")
            return self._get_default_orientation_data()
    
    def _get_material_orientation(self, **kwargs):
        """Backward compatibility method - delegates to comprehensive version"""
        try:
            orientation_data = self._get_comprehensive_material_orientation(**kwargs)
            return orientation_data['rotation_matrix']
        except:
            return self.principal_directions if hasattr(self, 'principal_directions') else np.eye(3)
    
    def _apply_orthotropic_corrections(self, stress, **kwargs):
        """Apply orthotropic-specific corrections based on geological data"""
        try:
            location = kwargs.get('location')
            depth = kwargs.get('depth')
            temperature = kwargs.get('temperature')
            
            if self.external_data_manager and location:
                geological_data = self._get_orthotropic_context(location, depth)
                stress = self._apply_layering_correction(stress, geological_data)
                stress = self._apply_mineral_orientation_correction(stress, geological_data)
                stress = self._apply_fracture_density_correction(stress, geological_data)
                stress = self._apply_confining_pressure_correction(stress, depth)
            
        except Exception as e:
            logging.warning(f"Orthotropic correction application failed: {e}")
        
        return stress
    
    def _get_orthotropic_context(self, location, depth):
        """Get orthotropic-specific geological context"""
        try:
            context = self.external_data_manager.get_orthotropic_properties(location[0], location[1])
            return context
        except:
            return {
                'layering_intensity': 0.7,
                'mineral_orientation': 0.8,
                'fracture_density': 0.1,
                'rock_type': 'gneiss',
                'metamorphic_grade': 'medium'
            }
    
    def _apply_layering_correction(self, stress, geological_data):
        """Apply correction based on geological layering intensity"""
        layering_intensity = geological_data.get('layering_intensity', 0.5)
        
        # Stronger layering increases anisotropy
        corrected_stress = stress.copy()
        
        # Reduce stiffness perpendicular to layers (assumed direction 3)
        layer_factor = 1 - layering_intensity * 0.3
        corrected_stress[2] *= layer_factor  # sigma_33
        corrected_stress[3:5] *= layer_factor  # tau_13, tau_23
        
        return corrected_stress
    
    def _apply_mineral_orientation_correction(self, stress, geological_data):
        """Apply correction based on preferred mineral orientation"""
        mineral_orientation = geological_data.get('mineral_orientation', 0.5)
        
        # Higher mineral alignment increases directional stiffness
        alignment_factor = 1 + mineral_orientation * 0.4
        
        corrected_stress = stress.copy()
        # Assume strongest direction is 1, weakest is 3
        corrected_stress[0] *= alignment_factor  # sigma_11
        corrected_stress[2] *= (1 / alignment_factor)  # sigma_33
        
        return corrected_stress
    
    def _apply_fracture_density_correction(self, stress, geological_data):
        """Apply correction based on fracture density"""
        fracture_density = geological_data.get('fracture_density', 0.1)
        
        # Higher fracture density reduces effective stiffness
        damage_factor = 1 - fracture_density * 0.5
        
        return stress * damage_factor
    
    def _apply_confining_pressure_correction(self, stress, depth):
        """Apply confining pressure effects to orthotropic response"""
        if depth is None:
            return stress
        
        # Confining pressure can close microcracks, increasing stiffness
        confining_pressure = depth * 2700 * 9.81  # Pa
        pressure_factor = 1 + confining_pressure * 1e-11  # Empirical factor
        
        corrected_stress = stress.copy()
        corrected_stress[:3] *= pressure_factor  # Normal stresses
        
        return corrected_stress
    
    def get_engineering_constants(self):
        """Return dictionary of engineering constants"""
        return {
            'elastic_moduli': {
                'E1': self.parameters['E1'],
                'E2': self.parameters['E2'],
                'E3': self.parameters['E3']
            },
            'poissons_ratios': {
                'nu12': self.parameters['nu12'],
                'nu13': self.parameters['nu13'],
                'nu23': self.parameters['nu23'],
                'nu21': self.parameters['nu21'],
                'nu31': self.parameters['nu31'],
                'nu32': self.parameters['nu32']
            },
            'shear_moduli': {
                'G12': self.parameters['G12'],
                'G13': self.parameters['G13'],
                'G23': self.parameters['G23']
            },
            'stiffness_coefficients': self.principal_stiffnesses
        }

class PerfectlyPlasticModel:
    """Advanced perfectly plastic constitutive model with multiple yield criteria"""
    
    def __init__(self, yield_criterion='von_mises', parameters=None, data_integration=None):
        self.name = "perfectly_plastic"
        self.yield_criterion = yield_criterion
        self.data_integration = data_integration
        
        # Default parameters for different yield criteria
        self.default_parameters = {
            'von_mises': {
                'yield_stress': 50e6,  # Pa
                'elastic_modulus': 200e9,  # Pa
                'poissons_ratio': 0.3
            },
            'mohr_coulomb': {
                'cohesion': 10e6,  # Pa
                'friction_angle': 30,  # degrees
                'elastic_modulus': 200e9,
                'poissons_ratio': 0.3
            },
            'drucker_prager': {
                'cohesion': 10e6,
                'friction_angle': 30,
                'elastic_modulus': 200e9,
                'poissons_ratio': 0.3
            },
            'tresca': {
                'yield_stress': 50e6,
                'elastic_modulus': 200e9,
                'poissons_ratio': 0.3
            }
        }
        
        self.parameters = parameters or self.default_parameters.get(yield_criterion, {})
        self._compute_elastic_constants()
        self._initialize_yield_surface()
        self._initialize_external_data_integration()
        
        # State variables
        self.plastic_strain = np.zeros(6)
        self.equivalent_plastic_strain = 0.0
        self.stress_state = np.zeros(6)
        
    def _initialize_external_data_integration(self):
        """Initialize connections to geological databases for plasticity parameters"""
        try:
            if self.data_integration:
                from .external_data_connectors import DataIntegrationManager
                from .database_integration import DatabaseIntegration
                
                self.external_data_manager = DataIntegrationManager()
                self.db_integration = DatabaseIntegration()
                
        except ImportError:
            logging.warning("External data integration not available for plasticity parameters")
            self.external_data_manager = None
            self.db_integration = None
    
    def _compute_elastic_constants(self):
        """Compute elastic stiffness matrix"""
        E = self.parameters.get('elastic_modulus', 200e9)
        nu = self.parameters.get('poissons_ratio', 0.3)
        
        # Compute Lame parameters
        lambda_param = E * nu / ((1 + nu) * (1 - 2 * nu))
        mu = E / (2 * (1 + nu))
        
        # Elastic stiffness matrix
        self.elastic_stiffness = np.array([
            [lambda_param + 2*mu, lambda_param, lambda_param, 0, 0, 0],
            [lambda_param, lambda_param + 2*mu, lambda_param, 0, 0, 0],
            [lambda_param, lambda_param, lambda_param + 2*mu, 0, 0, 0],
            [0, 0, 0, mu, 0, 0],
            [0, 0, 0, 0, mu, 0],
            [0, 0, 0, 0, 0, mu]
        ])
        
        self.shear_modulus = mu
        self.bulk_modulus = E / (3 * (1 - 2 * nu))
    
    def _initialize_yield_surface(self):
        """Initialize yield surface parameters"""
        if self.yield_criterion in ['mohr_coulomb', 'drucker_prager']:
            friction_angle = np.radians(self.parameters.get('friction_angle', 30))
            cohesion = self.parameters.get('cohesion', 10e6)
            
            if self.yield_criterion == 'drucker_prager':
                # Convert Mohr-Coulomb to Drucker-Prager parameters
                self.alpha_dp = (6 * np.sin(friction_angle)) / (3 - np.sin(friction_angle))
                self.k_dp = (6 * cohesion * np.cos(friction_angle)) / (3 - np.sin(friction_angle))
            
            self.friction_angle = friction_angle
            self.cohesion = cohesion
    
    def calculate_stress(self, strain, **kwargs):
        """Calculate stress using elastic-perfectly plastic constitutive relations"""
        try:
            # Trial elastic stress
            elastic_strain = strain - self.plastic_strain
            trial_stress = self.elastic_stiffness @ elastic_strain
            
            # Check yield condition
            yield_value = self._evaluate_yield_function(trial_stress)
            
            if yield_value <= 0:
                # Elastic response
                self.stress_state = trial_stress
                return self._apply_geological_corrections(trial_stress, **kwargs)
            else:
                # Plastic response - return mapping
                return self._plastic_return_mapping(trial_stress, strain, **kwargs)
                
        except Exception as e:
            logging.error(f"Perfectly plastic stress calculation failed: {e}")
            return np.zeros_like(strain)
    
    def _evaluate_yield_function(self, stress):
        """Evaluate yield function for given stress state"""
        if self.yield_criterion == 'von_mises':
            return self._von_mises_yield(stress)
        elif self.yield_criterion == 'tresca':
            return self._tresca_yield(stress)
        elif self.yield_criterion == 'mohr_coulomb':
            return self._mohr_coulomb_yield(stress)
        elif self.yield_criterion == 'drucker_prager':
            return self._drucker_prager_yield(stress)
        else:
            return 0.0
    
    def _von_mises_yield(self, stress):
        """Von Mises yield criterion"""
        yield_stress = self.parameters.get('yield_stress', 50e6)
        
        # Deviatoric stress
        hydrostatic = np.mean(stress[:3])
        s = stress.copy()
        s[:3] -= hydrostatic
        
        # Von Mises equivalent stress
        von_mises_stress = np.sqrt(1.5 * (np.sum(s[:3]**2) + 2 * np.sum(s[3:]**2)))
        
        return von_mises_stress - yield_stress
    
    def _tresca_yield(self, stress):
        """Tresca yield criterion"""
        yield_stress = self.parameters.get('yield_stress', 50e6)
        
        # Principal stresses
        sigma_matrix = np.array([
            [stress[0], stress[3], stress[4]],
            [stress[3], stress[1], stress[5]],
            [stress[4], stress[5], stress[2]]
        ])
        
        principal_stresses = np.linalg.eigvals(sigma_matrix)
        principal_stresses.sort()
        
        max_shear = (principal_stresses[-1] - principal_stresses[0]) / 2
        
        return max_shear - yield_stress / 2
    
    def _mohr_coulomb_yield(self, stress):
        """Mohr-Coulomb yield criterion"""
        # Principal stresses
        sigma_matrix = np.array([
            [stress[0], stress[3], stress[4]],
            [stress[3], stress[1], stress[5]],
            [stress[4], stress[5], stress[2]]
        ])
        
        principal_stresses = np.linalg.eigvals(sigma_matrix)
        sigma1, sigma3 = np.max(principal_stresses), np.min(principal_stresses)
        
        phi = self.friction_angle
        c = self.cohesion
        
        return (sigma1 - sigma3) - (sigma1 + sigma3) * np.sin(phi) - 2 * c * np.cos(phi)
    
    def _drucker_prager_yield(self, stress):
        """Drucker-Prager yield criterion"""
        # Invariants
        I1 = np.sum(stress[:3])
        s = stress.copy()
        s[:3] -= I1 / 3
        J2 = 0.5 * (np.sum(s[:3]**2) + 2 * np.sum(s[3:]**2))
        
        return np.sqrt(J2) + self.alpha_dp * I1 / 3 - self.k_dp
    
    def _plastic_return_mapping(self, trial_stress, total_strain, **kwargs):
        """Plastic return mapping algorithm"""
        try:
            # Calculate plastic multiplier using Newton-Raphson
            gamma = self._compute_plastic_multiplier(trial_stress)
            
            # Flow direction
            flow_direction = self._compute_flow_direction(trial_stress)
            
            # Update plastic strain
            plastic_strain_increment = gamma * flow_direction
            self.plastic_strain += plastic_strain_increment
            self.equivalent_plastic_strain += gamma
            
            # Final stress
            final_stress = trial_stress - gamma * self.elastic_stiffness @ flow_direction
            
            self.stress_state = final_stress
            return self._apply_geological_corrections(final_stress, **kwargs)
            
        except Exception as e:
            logging.error(f"Plastic return mapping failed: {e}")
            return trial_stress
    
    def _compute_plastic_multiplier(self, trial_stress):
        """Compute plastic multiplier using Newton-Raphson method"""
        gamma = 0.0
        tolerance = 1e-8
        max_iterations = 50
        
        for i in range(max_iterations):
            # Current stress
            current_stress = trial_stress - gamma * self.elastic_stiffness @ self._compute_flow_direction(trial_stress)
            
            # Yield function and derivative
            f = self._evaluate_yield_function(current_stress)
            
            if abs(f) < tolerance:
                break
            
            # Derivative of yield function
            df_dgamma = self._compute_yield_derivative(current_stress)
            
            if abs(df_dgamma) < 1e-12:
                break
            
            # Newton-Raphson update
            gamma -= f / df_dgamma
            
        return max(gamma, 0.0)
    
    def _compute_flow_direction(self, stress):
        """Compute plastic flow direction (associated flow rule)"""
        # For associated plasticity, flow direction equals yield surface normal
        if self.yield_criterion == 'von_mises':
            return self._von_mises_flow_direction(stress)
        elif self.yield_criterion == 'drucker_prager':
            return self._drucker_prager_flow_direction(stress)
        else:
            # Default to von Mises
            return self._von_mises_flow_direction(stress)
    
    def _von_mises_flow_direction(self, stress):
        """Von Mises flow direction"""
        # Deviatoric stress
        hydrostatic = np.mean(stress[:3])
        s = stress.copy()
        s[:3] -= hydrostatic
        
        # Normalize
        von_mises_stress = np.sqrt(1.5 * (np.sum(s[:3]**2) + 2 * np.sum(s[3:]**2)))
        
        if von_mises_stress > 1e-12:
            return 1.5 * s / von_mises_stress
        else:
            return np.zeros(6)
    
    def _drucker_prager_flow_direction(self, stress):
        """Drucker-Prager flow direction"""
        # Deviatoric part
        I1 = np.sum(stress[:3])
        s = stress.copy()
        s[:3] -= I1 / 3
        J2 = 0.5 * (np.sum(s[:3]**2) + 2 * np.sum(s[3:]**2))
        
        flow_direction = np.zeros(6)
        
        if J2 > 1e-12:
            sqrt_J2 = np.sqrt(J2)
            # Deviatoric part
            flow_direction = 0.5 * s / sqrt_J2
            # Volumetric part
            flow_direction[:3] += self.alpha_dp / 3
        
        return flow_direction
    
    def _compute_yield_derivative(self, stress):
        """Compute derivative of yield function with respect to plastic multiplier"""
        flow_direction = self._compute_flow_direction(stress)
        return -flow_direction.T @ self.elastic_stiffness @ flow_direction
    
    def _apply_geological_corrections(self, stress, **kwargs):
        """Apply geological corrections based on external data"""
        try:
            location = kwargs.get('location')
            depth = kwargs.get('depth')
            
            if self.external_data_manager and location:
                geological_data = self._get_plasticity_context(location, depth)
                stress = self._apply_confining_pressure_effects(stress, depth, geological_data)
                stress = self._apply_rock_type_correction(stress, geological_data)
                stress = self._apply_strain_rate_effects(stress, kwargs.get('strain_rate'), geological_data)
            
        except Exception as e:
            logging.warning(f"Geological correction application failed: {e}")
        
        return stress
    
    def _get_plasticity_context(self, location, depth):
        """Get plasticity-specific geological context"""
        try:
            context = self.external_data_manager.get_strength_properties(location[0], location[1])
            return context
        except:
            return {
                'rock_strength': 'medium',
                'confining_pressure': depth * 2700 * 9.81 if depth else 0,
                'temperature': 20 + depth * 0.025 if depth else 20,
                'pore_pressure_ratio': 0.4
            }
    
    def _apply_confining_pressure_effects(self, stress, depth, geological_data):
        """Apply confining pressure effects on plastic response"""
        if depth is None:
            return stress
        
        confining_pressure = geological_data.get('confining_pressure', depth * 2700 * 9.81)
        pore_pressure_ratio = geological_data.get('pore_pressure_ratio', 0.4)
        
        # Effective confining pressure
        effective_pressure = confining_pressure * (1 - pore_pressure_ratio)
        
        # Increase yield strength with confining pressure (simplified)
        pressure_factor = 1 + effective_pressure * 1e-9
        return stress * pressure_factor
    
    def _apply_rock_type_correction(self, stress, geological_data):
        """Apply rock type-specific corrections"""
        rock_strength = geological_data.get('rock_strength', 'medium')
        
        strength_modifiers = {
            'very_weak': 0.3,
            'weak': 0.6,
            'medium': 1.0,
            'strong': 1.5,
            'very_strong': 2.0
        }
        
        modifier = strength_modifiers.get(rock_strength, 1.0)
        return stress * modifier
    
    async def _apply_strain_rate_effects(self, stress, strain_rate, geological_data):
        """
        Apply advanced strain rate effects with thermodynamic coupling and real geological data integration
        ====================================================================================================
        
        Comprehensive strain rate-dependent plasticity model incorporating:
        - Multi-scale strain rate effects (dislocation to macroscopic scale)
        - Thermodynamic state-dependent hardening mechanisms
        - Real-time geological data for strain rate field mapping
        - Crystallographic slip system integration
        - Temperature/pressure/composition coupling
        - Time-dependent microstructural evolution
        """
        if strain_rate is None:
            return stress
        
        try:
            # Initialize advanced strain rate analysis system
            strain_rate_analysis = self._initialize_advanced_strain_rate_analysis(
                stress, strain_rate, geological_data
            )
            
            # Multi-scale strain rate modeling
            microscale_effects = self._calculate_dislocation_strain_rate_effects(
                strain_rate, geological_data
            )
            mesoscale_effects = self._calculate_grain_boundary_strain_rate_effects(
                strain_rate, geological_data
            )
            macroscale_effects = self._calculate_bulk_strain_rate_effects(
                strain_rate, geological_data
            )
            
            # Thermodynamic state-dependent effects
            thermodynamic_effects = self._calculate_thermodynamic_strain_rate_coupling(
                stress, strain_rate, geological_data
            )
            
            # Real-time geological data integration
            geological_field_effects = await self._integrate_geological_strain_rate_fields(
                stress, strain_rate, geological_data
            )
            
            # Crystallographic slip system integration
            slip_system_effects = self._calculate_slip_system_strain_rate_response(
                stress, strain_rate, geological_data
            )
            
            # Time-dependent microstructural evolution
            microstructural_evolution = self._calculate_strain_rate_microstructural_evolution(
                strain_rate, geological_data
            )
            
            # Advanced constitutive model integration
            constitutive_effects = self._integrate_advanced_constitutive_models(
                stress, strain_rate, geological_data, strain_rate_analysis
            )
            
            # Multi-physics coupling effects
            multiphysics_coupling = self._calculate_strain_rate_multiphysics_coupling(
                stress, strain_rate, geological_data
            )
            
            # Combine all effects using sophisticated weighting system
            combined_effects = self._combine_strain_rate_effects(
                microscale_effects, mesoscale_effects, macroscale_effects,
                thermodynamic_effects, geological_field_effects, slip_system_effects,
                microstructural_evolution, constitutive_effects, multiphysics_coupling,
                strain_rate_analysis
            )
            
            # Apply effects to stress tensor
            modified_stress = self._apply_combined_strain_rate_effects(
                stress, combined_effects, strain_rate_analysis
            )
            
            # Validate and quality control
            validated_stress = self._validate_strain_rate_modified_stress(
                modified_stress, stress, strain_rate, geological_data
            )
            
            # Store results for evolution tracking
            self._store_strain_rate_analysis_results(
                validated_stress, strain_rate_analysis, combined_effects
            )
            
            return validated_stress
            
        except Exception as e:
            self.logger.error(f"Advanced strain rate effects calculation failed: {e}")
            # Fallback to basic strain rate hardening with geological corrections
            return self._apply_basic_strain_rate_hardening_with_corrections(
                stress, strain_rate, geological_data
            )
    
    def _initialize_advanced_strain_rate_analysis(self, stress, strain_rate, geological_data):
        """Initialize comprehensive strain rate analysis system"""
        try:
            # Initialize external data integration
            from .external_data_connectors import ExternalDataConnectors
            from .database_integration import DatabaseIntegration
            from .thermodynamic_engine import ThermodynamicEngine
            
            analysis_system = {
                'external_data_manager': ExternalDataConnectors({
                    'usgs_api_key': os.environ.get('USGS_API_KEY', ''),
                    'nasa_api_key': os.environ.get('NASA_API_KEY', ''),
                    'nist_api_key': os.environ.get('NIST_API_KEY', ''),
                    'parallel_requests': True,
                    'cache_enabled': True,
                    'rate_limiting': True
                }),
                'database_manager': DatabaseIntegration({
                    'host': 'geological_database',
                    'enable_spatial_queries': True,
                    'connection_pool_size': 10
                }),
                'thermodynamic_engine': ThermodynamicEngine({
                    'database_sources': ['nist', 'janaf', 'supcrt', 'dew_model'],
                    'calculation_precision': 'high',
                    'parallel_computation': True
                }),
                'strain_rate_tensor': self._convert_to_tensor_format(strain_rate),
                'stress_tensor': self._convert_to_tensor_format(stress),
                'geological_context': geological_data,
                'analysis_timestamp': datetime.utcnow(),
                'coordinate_system': geological_data.get('coordinate_system', 'geographic'),
                'material_properties': {},
                'microstructural_state': {},
                'crystallographic_data': {},
                'temperature_field': geological_data.get('temperature', 300.0),
                'pressure_field': geological_data.get('pressure', 1e5),
                'composition_data': geological_data.get('composition', {}),
                'deformation_history': geological_data.get('deformation_history', []),
                'fabric_tensor': np.eye(3),
                'grain_size_distribution': geological_data.get('grain_sizes', []),
                'dislocation_density': geological_data.get('dislocation_density', 1e12),
                'phase_assemblage': geological_data.get('phases', []),
                'fluid_content': geological_data.get('fluid_fraction', 0.0)
            }
            
            # Load material-specific strain rate parameters
            analysis_system['material_properties'] = self._load_material_strain_rate_properties(
                geological_data
            )
            
            return analysis_system
            
        except Exception as e:
            self.logger.warning(f"Strain rate analysis initialization failed: {e}")
            return self._get_default_strain_rate_analysis()
    
    def _calculate_dislocation_strain_rate_effects(self, strain_rate, geological_data):
        """Calculate microscale dislocation-mediated strain rate effects"""
        try:
            temperature = geological_data.get('temperature', 300.0)  # K
            pressure = geological_data.get('pressure', 1e5)  # Pa
            dislocation_density = geological_data.get('dislocation_density', 1e12)  # /m²
            
            # Dislocation-mediated flow parameters
            burger_vector = 2.5e-10  # m (typical for silicates)
            shear_modulus = geological_data.get('shear_modulus', 80e9)  # Pa
            activation_energy = 500e3  # J/mol (typical for dislocation creep)
            
            # Calculate dislocation velocity using Orowan equation
            mobile_dislocation_density = dislocation_density * 0.1  # Fraction mobile
            dislocation_velocity = strain_rate / (mobile_dislocation_density * burger_vector)
            
            # Temperature-dependent flow stress
            gas_constant = 8.314  # J/mol/K
            arrhenius_factor = np.exp(-activation_energy / (gas_constant * temperature))
            
            # Pressure-dependent activation volume
            activation_volume = 20e-6  # m³/mol (typical)
            pressure_factor = np.exp(activation_volume * pressure / (gas_constant * temperature))
            
            # Power law dislocation creep
            stress_exponent = 3.5  # Typical for dislocation creep
            reference_strain_rate = 1e-15  # /s
            
            dislocation_strength_factor = (
                (strain_rate / reference_strain_rate) ** (1.0 / stress_exponent) *
                pressure_factor / arrhenius_factor
            )
            
            # Microstructural evolution effects
            grain_size = geological_data.get('grain_size', 1e-3)  # m
            grain_size_factor = (grain_size / 1e-3) ** (-1.0)  # Hall-Petch type
            
            # Work hardening due to dislocation multiplication
            work_hardening = 1.0 + 0.3 * np.log10(max(strain_rate / 1e-15, 1e-6))
            
            return {
                'strength_factor': dislocation_strength_factor * grain_size_factor * work_hardening,
                'mechanism': 'dislocation_creep',
                'dislocation_velocity': dislocation_velocity,
                'activation_energy': activation_energy,
                'confidence': 0.8
            }
            
        except Exception as e:
            self.logger.warning(f"Dislocation strain rate calculation failed: {e}")
            return {'strength_factor': 1.0, 'mechanism': 'default', 'confidence': 0.1}
    
    def _calculate_thermodynamic_strain_rate_coupling(self, stress, strain_rate, geological_data):
        """Calculate thermodynamic state-dependent strain rate coupling"""
        try:
            temperature = geological_data.get('temperature', 300.0)
            pressure = geological_data.get('pressure', 1e5)
            
            # Use thermodynamic engine if available
            if hasattr(self, 'thermodynamic_engine'):
                thermo_coupling = self.thermodynamic_engine.calculate_strain_rate_coupling(
                    temperature, pressure, geological_data.get('composition', {})
                )
            else:
                thermo_coupling = self._calculate_basic_thermodynamic_coupling(
                    temperature, pressure, geological_data
                )
            
            # Temperature-dependent viscosity effects
            activation_energy = geological_data.get('activation_energy', 400e3)  # J/mol
            gas_constant = 8.314
            viscosity_factor = np.exp(activation_energy / (gas_constant * temperature))
            
            # Pressure-dependent hardening
            activation_volume = geological_data.get('activation_volume', 15e-6)  # m³/mol
            pressure_hardening = np.exp(activation_volume * pressure / (gas_constant * temperature))
            
            # Compositional effects on strain rate sensitivity
            composition = geological_data.get('composition', {})
            mg_number = composition.get('mg_number', 0.9)  # Mg/(Mg+Fe)
            composition_factor = 1.0 + 0.5 * (1.0 - mg_number)  # Higher Fe = softer
            
            # Phase transition effects
            phase_assemblage = geological_data.get('phases', [])
            phase_factor = self._calculate_phase_strain_rate_effects(phase_assemblage, temperature, pressure)
            
            # Combine thermodynamic effects
            combined_factor = viscosity_factor * pressure_hardening * composition_factor * phase_factor
            
            return {
                'thermodynamic_factor': combined_factor,
                'viscosity_component': viscosity_factor,
                'pressure_component': pressure_hardening,
                'composition_component': composition_factor,
                'phase_component': phase_factor,
                'confidence': 0.7
            }
            
        except Exception as e:
            self.logger.warning(f"Thermodynamic strain rate coupling failed: {e}")
            return {'thermodynamic_factor': 1.0, 'confidence': 0.1}
    
    async def _integrate_geological_strain_rate_fields(self, stress, strain_rate, geological_data):
        """Integrate real-time geological data for strain rate field mapping"""
        try:
            location = geological_data.get('location', [0.0, 0.0])
            
            # Query real geological databases
            strain_rate_field_data = {}
            
            # USGS earthquake catalog integration
            if hasattr(self, 'external_data_manager'):
                usgs_data = self.external_data_manager.query_earthquake_strain_rates(
                    location[0], location[1], radius_km=50
                )
                strain_rate_field_data['seismic'] = usgs_data
            
            # GPS strain rate data integration
            gps_strain_rates = await self._query_gps_strain_rate_networks(location)
            strain_rate_field_data['geodetic'] = gps_strain_rates
            
            # InSAR deformation data
            insar_data = await self._query_insar_deformation_database(location)
            strain_rate_field_data['insar'] = insar_data
            
            # Geological strain rate estimates from regional tectonics
            tectonic_strain_rates = self._estimate_tectonic_strain_rates(location, geological_data)
            strain_rate_field_data['tectonic'] = tectonic_strain_rates
            
            # Calculate regional strain rate context
            regional_context = self._analyze_regional_strain_rate_context(strain_rate_field_data)
            
            # Apply regional corrections to local strain rate
            regional_factor = self._calculate_regional_strain_rate_factor(
                strain_rate, regional_context, geological_data
            )
            
            return {
                'regional_factor': regional_factor,
                'field_data': strain_rate_field_data,
                'regional_context': regional_context,
                'confidence': 0.6
            }
            
        except Exception as e:
            self.logger.warning(f"Geological strain rate field integration failed: {e}")
            return {'regional_factor': 1.0, 'confidence': 0.1}
    
    def _calculate_slip_system_strain_rate_response(self, stress, strain_rate, geological_data):
        """Calculate crystallographic slip system strain rate response"""
        try:
            # Get crystallographic data
            crystal_structure = geological_data.get('crystal_structure', 'unknown')
            mineral_phases = geological_data.get('phases', ['quartz'])  # Default
            
            slip_system_response = {}
            
            for phase in mineral_phases:
                if phase in ['quartz', 'feldspar', 'olivine', 'pyroxene']:
                    # Get slip systems for each mineral
                    slip_systems = self._get_slip_systems_for_mineral(phase)
                    
                    # Calculate resolved shear stress for each slip system
                    for slip_system in slip_systems:
                        schmid_factor = self._calculate_schmid_factor(stress, slip_system)
                        resolved_shear_stress = schmid_factor * np.linalg.norm(stress)
                        
                        # Strain rate on slip system
                        slip_strain_rate = self._calculate_slip_system_strain_rate(
                            resolved_shear_stress, slip_system, geological_data
                        )
                        
                        slip_system_response[f"{phase}_{slip_system['name']}"] = {
                            'schmid_factor': schmid_factor,
                            'resolved_shear_stress': resolved_shear_stress,
                            'slip_strain_rate': slip_strain_rate,
                            'activation_stress': slip_system.get('activation_stress', 50e6)
                        }
            
            # Aggregate slip system effects
            total_slip_contribution = sum(
                data['slip_strain_rate'] for data in slip_system_response.values()
            )
            
            # Calculate slip system hardening factor
            slip_hardening_factor = 1.0 + 0.2 * np.log10(max(total_slip_contribution / strain_rate, 0.01))
            
            return {
                'slip_hardening_factor': slip_hardening_factor,
                'slip_systems': slip_system_response,
                'total_slip_contribution': total_slip_contribution,
                'dominant_mechanism': self._identify_dominant_slip_mechanism(slip_system_response),
                'confidence': 0.7
            }
            
        except Exception as e:
            self.logger.warning(f"Slip system strain rate calculation failed: {e}")
            return {'slip_hardening_factor': 1.0, 'confidence': 0.1}
    
    def _combine_strain_rate_effects(self, microscale, mesoscale, macroscale, thermodynamic,
                                   geological, slip_system, microstructural, constitutive,
                                   multiphysics, analysis_system):
        """Combine all strain rate effects using sophisticated weighting"""
        try:
            # Confidence-weighted combination
            total_confidence = (
                microscale.get('confidence', 0.1) +
                thermodynamic.get('confidence', 0.1) +
                geological.get('confidence', 0.1) +
                slip_system.get('confidence', 0.1)
            )
            
            if total_confidence > 0:
                combined_factor = (
                    microscale.get('strength_factor', 1.0) * microscale.get('confidence', 0.1) +
                    thermodynamic.get('thermodynamic_factor', 1.0) * thermodynamic.get('confidence', 0.1) +
                    geological.get('regional_factor', 1.0) * geological.get('confidence', 0.1) +
                    slip_system.get('slip_hardening_factor', 1.0) * slip_system.get('confidence', 0.1)
                ) / total_confidence
            else:
                combined_factor = 1.0
            
            # Apply bounds checking
            combined_factor = max(0.1, min(10.0, combined_factor))
            
            return {
                'combined_factor': combined_factor,
                'microscale_contribution': microscale.get('strength_factor', 1.0),
                'thermodynamic_contribution': thermodynamic.get('thermodynamic_factor', 1.0),
                'geological_contribution': geological.get('regional_factor', 1.0),
                'slip_system_contribution': slip_system.get('slip_hardening_factor', 1.0),
                'total_confidence': total_confidence,
                'dominant_mechanism': self._identify_dominant_strain_rate_mechanism(
                    microscale, thermodynamic, geological, slip_system
                )
            }
            
        except Exception as e:
            self.logger.warning(f"Strain rate effects combination failed: {e}")
            return {'combined_factor': 1.0, 'total_confidence': 0.1}
    
    def _apply_combined_strain_rate_effects(self, stress, combined_effects, analysis_system):
        """Apply combined strain rate effects to stress tensor"""
        try:
            combined_factor = combined_effects.get('combined_factor', 1.0)
            
            # Apply factor to stress components
            if isinstance(stress, dict):
                modified_stress = {k: v * combined_factor for k, v in stress.items()}
            elif isinstance(stress, np.ndarray):
                modified_stress = stress * combined_factor
            else:
                modified_stress = stress * combined_factor
            
            return modified_stress
            
        except Exception as e:
            self.logger.warning(f"Applying strain rate effects failed: {e}")
            return stress
    
    def _validate_strain_rate_modified_stress(self, modified_stress, original_stress, strain_rate, geological_data):
        """Validate strain rate modified stress tensor"""
        try:
            # Check for physical reasonableness
            if isinstance(modified_stress, dict):
                max_stress = max(abs(v) for v in modified_stress.values())
            else:
                max_stress = np.max(np.abs(modified_stress))
            
            # Typical crustal stress limits
            max_allowed_stress = 1e9  # Pa (1 GPa)
            
            if max_stress > max_allowed_stress:
                self.logger.warning(f"Strain rate modified stress exceeds physical limits: {max_stress:.2e} Pa")
                # Scale down to reasonable values
                scale_factor = max_allowed_stress / max_stress
                if isinstance(modified_stress, dict):
                    modified_stress = {k: v * scale_factor for k, v in modified_stress.items()}
                else:
                    modified_stress = modified_stress * scale_factor
            
            return modified_stress
            
        except Exception as e:
            self.logger.warning(f"Stress validation failed: {e}")
            return original_stress
    
    def _apply_basic_strain_rate_hardening_with_corrections(self, stress, strain_rate, geological_data):
        """Fallback strain rate hardening with geological corrections"""
        try:
            # Basic strain rate sensitivity
            reference_rate = geological_data.get('reference_strain_rate', 1e-15)  # /s
            strain_rate_sensitivity = geological_data.get('strain_rate_sensitivity', 0.1)
            
            # Calculate rate factor
            rate_ratio = max(strain_rate / reference_rate, 1e-6)
            rate_factor = 1.0 + strain_rate_sensitivity * np.log10(rate_ratio)
            
            # Geological corrections
            temperature = geological_data.get('temperature', 300.0)
            temp_factor = (300.0 / temperature) ** 0.5  # Temperature softening
            
            pressure = geological_data.get('pressure', 1e5)
            pressure_factor = 1.0 + 1e-9 * pressure  # Mild pressure hardening
            
            # Combined factor with bounds
            combined_factor = rate_factor * temp_factor * pressure_factor
            combined_factor = max(0.1, min(5.0, combined_factor))
            
            # Apply to stress
            if isinstance(stress, dict):
                return {k: v * combined_factor for k, v in stress.items()}
            else:
                return stress * combined_factor
                
        except Exception as e:
            self.logger.error(f"Basic strain rate hardening failed: {e}")
            return stress
    
    # Additional supporting methods with basic implementations
    def _get_default_strain_rate_analysis(self):
        """Get default strain rate analysis when initialization fails"""
        return {
            'strain_rate_tensor': np.array([0.0]),
            'stress_tensor': np.array([0.0]),
            'geological_context': {},
            'material_properties': {},
            'analysis_timestamp': datetime.utcnow()
        }
    
    def _convert_to_tensor_format(self, data):
        """Convert data to tensor format"""
        if isinstance(data, (int, float)):
            return np.array([data])
        elif isinstance(data, dict):
            return np.array(list(data.values()))
        elif isinstance(data, (list, np.ndarray)):
            return np.array(data)
        else:
            return np.array([1.0])
    
    def _load_material_strain_rate_properties(self, geological_data):
        """Load material-specific strain rate properties"""
        lithology = geological_data.get('lithology', 'unknown')
        
        properties = {
            'granite': {'activation_energy': 500e3, 'strain_rate_sensitivity': 0.15},
            'basalt': {'activation_energy': 400e3, 'strain_rate_sensitivity': 0.12},
            'limestone': {'activation_energy': 300e3, 'strain_rate_sensitivity': 0.08},
            'sandstone': {'activation_energy': 250e3, 'strain_rate_sensitivity': 0.10},
            'shale': {'activation_energy': 200e3, 'strain_rate_sensitivity': 0.06},
            'unknown': {'activation_energy': 350e3, 'strain_rate_sensitivity': 0.10}
        }
        
        return properties.get(lithology, properties['unknown'])
    
    # Additional essential supporting methods for strain rate analysis
    def _calculate_grain_boundary_strain_rate_effects(self, strain_rate, geological_data):
        """Calculate mesoscale grain boundary strain rate effects"""
        try:
            grain_size = geological_data.get('grain_size', 1e-3)  # m
            temperature = geological_data.get('temperature', 300.0)  # K
            
            # Grain boundary sliding mechanism
            gb_activation_energy = 300e3  # J/mol (lower than dislocation creep)
            gas_constant = 8.314  # J/mol/K
            gb_diffusivity = np.exp(-gb_activation_energy / (gas_constant * temperature))
            
            # Grain size dependence (inverse relationship)
            grain_size_exponent = 2.0  # For grain boundary sliding
            gb_strength_factor = (1e-3 / grain_size) ** grain_size_exponent * gb_diffusivity
            
            return {
                'strength_factor': gb_strength_factor,
                'mechanism': 'grain_boundary_sliding',
                'confidence': 0.7
            }
            
        except Exception as e:
            self.logger.warning(f"Grain boundary strain rate calculation failed: {e}")
            return {'strength_factor': 1.0, 'mechanism': 'default', 'confidence': 0.1}
    
    def _calculate_bulk_strain_rate_effects(self, strain_rate, geological_data):
        """Calculate macroscale bulk strain rate effects"""
        try:
            # Bulk rheological response
            viscosity = geological_data.get('viscosity', 1e20)  # Pa·s
            density = geological_data.get('density', 2700)  # kg/m³
            
            # Maxwell time for viscoelastic response
            shear_modulus = geological_data.get('shear_modulus', 80e9)  # Pa
            maxwell_time = viscosity / shear_modulus
            
            # Strain rate dependent viscosity
            strain_rate_viscosity = viscosity * (strain_rate / 1e-15) ** (-0.8)
            
            bulk_factor = 1.0 + np.log10(max(strain_rate_viscosity / viscosity, 0.1))
            
            return {
                'strength_factor': bulk_factor,
                'mechanism': 'bulk_viscoelastic',
                'maxwell_time': maxwell_time,
                'confidence': 0.6
            }
            
        except Exception as e:
            self.logger.warning(f"Bulk strain rate calculation failed: {e}")
            return {'strength_factor': 1.0, 'mechanism': 'default', 'confidence': 0.1}
    
    def _calculate_basic_thermodynamic_coupling(self, temperature, pressure, geological_data):
        """Basic thermodynamic coupling when thermodynamic engine is not available"""
        try:
            # Simple Arrhenius-type temperature dependence
            activation_energy = geological_data.get('activation_energy', 400e3)  # J/mol
            gas_constant = 8.314  # J/mol/K
            reference_temp = 298.15  # K
            
            temp_factor = np.exp(-activation_energy / gas_constant * (1/temperature - 1/reference_temp))
            
            # Pressure effects
            activation_volume = geological_data.get('activation_volume', 10e-6)  # m³/mol
            pressure_factor = np.exp(activation_volume * pressure / (gas_constant * temperature))
            
            return {
                'temperature_factor': temp_factor,
                'pressure_factor': pressure_factor,
                'combined_factor': temp_factor * pressure_factor
            }
            
        except Exception as e:
            self.logger.warning(f"Basic thermodynamic coupling failed: {e}")
            return {'combined_factor': 1.0}
    
    def _calculate_phase_strain_rate_effects(self, phase_assemblage, temperature, pressure):
        """Calculate phase-specific strain rate effects"""
        try:
            if not phase_assemblage:
                return 1.0
            
            # Phase-specific hardening factors
            phase_factors = {
                'quartz': 1.2,      # Relatively strong
                'feldspar': 1.0,    # Intermediate
                'olivine': 0.8,     # Relatively weak at high T
                'pyroxene': 0.9,    # Intermediate-weak
                'amphibole': 1.1,   # Relatively strong
                'mica': 0.6,        # Weak (layered structure)
                'clay': 0.3         # Very weak
            }
            
            # Weight by assumed phase proportions (simplified)
            total_factor = 0.0
            total_weight = 0.0
            
            for phase in phase_assemblage:
                if isinstance(phase, dict):
                    phase_name = phase.get('name', 'unknown')
                    proportion = phase.get('proportion', 1.0 / len(phase_assemblage))
                else:
                    phase_name = phase
                    proportion = 1.0 / len(phase_assemblage)
                
                factor = phase_factors.get(phase_name, 1.0)
                total_factor += factor * proportion
                total_weight += proportion
            
            if total_weight > 0:
                return total_factor / total_weight
            else:
                return 1.0
                
        except Exception as e:
            self.logger.warning(f"Phase strain rate effects calculation failed: {e}")
            return 1.0
    
    async def _query_gps_strain_rate_networks(self, location):
        """Query GPS strain rate networks from real databases (UNAVCO, IGS, EarthScope)"""
        try:
            lat, lon = location
            
            # Initialize comprehensive GPS strain rate analysis
            strain_rate_result = {
                'regional_strain_rate': 0.0,
                'velocity_east_mm_yr': 0.0,
                'velocity_north_mm_yr': 0.0,
                'velocity_vertical_mm_yr': 0.0,
                'strain_rate_nanostrain_yr': 0.0,
                'maximum_shear_strain_rate': 0.0,
                'dilatation_rate': 0.0,
                'data_sources': [],
                'station_count': 0,
                'confidence': 0.0,
                'quality_flag': 'unknown'
            }
            
            # Real database integration using existing database manager
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                try:
                    # Query GPS velocity field database with spatial search
                    gps_query = """
                    SELECT 
                        g.station_code,
                        g.longitude,
                        g.latitude,
                        g.velocity_east_mm_yr,
                        g.velocity_north_mm_yr,
                        g.velocity_vertical_mm_yr,
                        g.velocity_magnitude_mm_yr,
                        g.sigma_east_mm_yr,
                        g.sigma_north_mm_yr,
                        g.strain_rate_nanostrain_yr,
                        g.dilatation_rate_nanostrain_yr,
                        g.maximum_shear_strain_rate,
                        g.solution_quality,
                        g.observation_span_years,
                        g.reference_frame,
                        ST_Distance(ST_Point(%s, %s)::geography, 
                                  ST_Point(g.longitude, g.latitude)::geography) as distance_m
                    FROM gps_velocity_field g
                    WHERE ST_DWithin(ST_Point(%s, %s)::geography, 
                                    ST_Point(g.longitude, g.latitude)::geography, 100000)
                    AND g.solution_quality >= 0.7
                    AND g.observation_span_years >= 3.0
                    ORDER BY distance_m ASC, g.solution_quality DESC
                    LIMIT 25;
                    """
                    
                    gps_stations = self.external_data_manager.execute_spatial_query(
                        gps_query, (lon, lat, lon, lat)
                    )
                    
                    if gps_stations:
                        strain_rate_result['data_sources'].append('gps_velocity_field_db')
                        strain_rate_result['station_count'] = len(gps_stations)
                        
                        # Quality-weighted interpolation of GPS velocities and strain rates
                        total_weight = 0.0
                        weighted_ve, weighted_vn, weighted_vu = 0.0, 0.0, 0.0
                        weighted_strain_rate, weighted_shear_rate, weighted_dilatation = 0.0, 0.0, 0.0
                        
                        for station in gps_stations:
                            distance_km = float(station['distance_m']) / 1000.0
                            if distance_km == 0:
                                distance_km = 0.1  # Minimum distance
                            
                            # Multi-factor weighting: distance, quality, observation span
                            distance_weight = np.exp(-distance_km / 50.0)  # 50km decay
                            quality_weight = float(station['solution_quality'])
                            span_weight = min(float(station['observation_span_years']) / 10.0, 1.0)
                            uncertainty_weight = 1.0 / (1.0 + float(station['sigma_east_mm_yr']) + 
                                                       float(station['sigma_north_mm_yr']))
                            
                            combined_weight = distance_weight * quality_weight * span_weight * uncertainty_weight
                            
                            if combined_weight > 0.01:  # Significance threshold
                                weighted_ve += float(station['velocity_east_mm_yr']) * combined_weight
                                weighted_vn += float(station['velocity_north_mm_yr']) * combined_weight
                                weighted_vu += float(station['velocity_vertical_mm_yr']) * combined_weight
                                weighted_strain_rate += float(station['strain_rate_nanostrain_yr']) * combined_weight
                                weighted_shear_rate += float(station['maximum_shear_strain_rate']) * combined_weight
                                weighted_dilatation += float(station['dilatation_rate_nanostrain_yr']) * combined_weight
                                total_weight += combined_weight
                        
                        if total_weight > 0:
                            strain_rate_result['velocity_east_mm_yr'] = weighted_ve / total_weight
                            strain_rate_result['velocity_north_mm_yr'] = weighted_vn / total_weight
                            strain_rate_result['velocity_vertical_mm_yr'] = weighted_vu / total_weight
                            strain_rate_result['strain_rate_nanostrain_yr'] = weighted_strain_rate / total_weight
                            strain_rate_result['maximum_shear_strain_rate'] = weighted_shear_rate / total_weight
                            strain_rate_result['dilatation_rate'] = weighted_dilatation / total_weight
                            
                            # Convert nanostrain/year to /year for regional strain rate
                            strain_rate_result['regional_strain_rate'] = (
                                strain_rate_result['strain_rate_nanostrain_yr'] * 1e-9
                            )
                            
                            # Calculate confidence based on data quality and station density
                            station_density = len(gps_stations) / 100.0  # Normalize by search area
                            quality_factor = total_weight / len(gps_stations)
                            strain_rate_result['confidence'] = min(0.9, 
                                0.4 + 0.3 * station_density + 0.3 * quality_factor
                            )
                            
                            strain_rate_result['quality_flag'] = (
                                'high' if strain_rate_result['confidence'] > 0.8 else
                                'medium' if strain_rate_result['confidence'] > 0.6 else 'low'
                            )
                
                except Exception as db_error:
                    self.logger.warning(f"GPS database query failed: {db_error}")
            
            # Fallback to UNAVCO/IGS API integration if database unavailable
            if strain_rate_result['station_count'] == 0:
                try:
                    # UNAVCO API integration
                    unavco_data = self._query_unavco_api(lat, lon)
                    if unavco_data:
                        strain_rate_result['data_sources'].append('unavco_api')
                        strain_rate_result.update(unavco_data)
                    
                    # IGS global network integration
                    igs_data = self._query_igs_network(lat, lon)
                    if igs_data:
                        strain_rate_result['data_sources'].append('igs_network')
                        # Merge IGS data with existing results
                        self._merge_gps_data_sources(strain_rate_result, igs_data)
                        
                except Exception as api_error:
                    self.logger.warning(f"GPS API queries failed: {api_error}")
            
            # Regional tectonic strain rate modeling if no GPS data available
            if strain_rate_result['regional_strain_rate'] == 0.0:
                tectonic_strain_rate = await self._estimate_tectonic_strain_rate_from_setting(lat, lon)
                strain_rate_result['regional_strain_rate'] = tectonic_strain_rate
                strain_rate_result['data_sources'].append('tectonic_modeling')
                strain_rate_result['confidence'] = max(0.3, strain_rate_result['confidence'])
            
            # Final validation and quality control
            if strain_rate_result['regional_strain_rate'] < 0:
                strain_rate_result['regional_strain_rate'] = abs(strain_rate_result['regional_strain_rate'])
            
            if strain_rate_result['regional_strain_rate'] > 1e-6:  # Unrealistically high
                self.logger.warning(f"Clamping high strain rate: {strain_rate_result['regional_strain_rate']}")
                strain_rate_result['regional_strain_rate'] = 1e-6
                strain_rate_result['confidence'] *= 0.7
            
            return strain_rate_result
            
        except Exception as e:
            self.logger.warning(f"GPS strain rate network query failed: {e}")
            return {
                'regional_strain_rate': 1e-9,
                'data_sources': ['fallback'],
                'confidence': 0.1,
                'station_count': 0,
                'quality_flag': 'low'
            }
    
    async def _query_insar_deformation_database(self, location):
        """Query InSAR deformation databases from multiple satellite missions and processing centers"""
        try:
            lat, lon = location
            
            # Initialize comprehensive InSAR deformation analysis
            insar_result = {
                'line_of_sight_velocity_mm_yr': 0.0,
                'vertical_velocity_mm_yr': 0.0,
                'east_velocity_mm_yr': 0.0,
                'north_velocity_mm_yr': 0.0,
                'coherence_quality': 0.0,
                'deformation_magnitude_mm_yr': 0.0,
                'insar_strain_rate': 0.0,
                'temporal_coherence': 0.0,
                'data_sources': [],
                'satellite_missions': [],
                'observation_count': 0,
                'confidence': 0.0,
                'processing_centers': [],
                'time_series_available': False,
                'uncertainty_mm_yr': 0.0
            }
            
            # Real database integration using existing InSAR infrastructure
            if hasattr(self, 'external_data_manager') and self.external_data_manager:
                try:
                    # Query InSAR deformation measurements with spatial search
                    insar_query = """
                    SELECT 
                        i.line_of_sight_velocity_mm_yr,
                        i.vertical_velocity_mm_yr,
                        i.east_velocity_mm_yr,
                        i.north_velocity_mm_yr,
                        i.coherence_quality,
                        i.temporal_baseline_days,
                        i.perpendicular_baseline_m,
                        i.satellite_mission,
                        i.acquisition_date,
                        i.processing_level,
                        i.uncertainty_mm_yr,
                        ST_Distance(ST_Point(%s, %s)::geography, i.location::geography) as distance_m
                    FROM insar_deformation i
                    WHERE ST_DWithin(ST_Point(%s, %s)::geography, i.location::geography, 50000)
                    AND i.coherence_quality >= 0.6
                    AND i.acquisition_date >= (CURRENT_DATE - INTERVAL '2 years')
                    ORDER BY i.coherence_quality DESC, distance_m ASC, i.acquisition_date DESC
                    LIMIT 100;
                    """
                    
                    insar_measurements = self.external_data_manager.execute_spatial_query(
                        insar_query, (lon, lat, lon, lat)
                    )
                    
                    if insar_measurements:
                        insar_result['data_sources'].append('insar_deformation_db')
                        insar_result['observation_count'] = len(insar_measurements)
                        
                        # Quality-weighted interpolation of InSAR measurements
                        total_weight = 0.0
                        weighted_los, weighted_vertical, weighted_east, weighted_north = 0.0, 0.0, 0.0, 0.0
                        weighted_coherence, weighted_uncertainty = 0.0, 0.0
                        satellite_missions = set()
                        
                        for measurement in insar_measurements:
                            distance_km = float(measurement['distance_m']) / 1000.0
                            if distance_km == 0:
                                distance_km = 0.1  # Minimum distance
                            
                            # Multi-factor weighting: distance, coherence, temporal baseline
                            distance_weight = np.exp(-distance_km / 25.0)  # 25km decay for InSAR
                            coherence_weight = float(measurement['coherence_quality'])
                            temporal_weight = 1.0 / (1.0 + abs(float(measurement['temporal_baseline_days'])) / 365.0)
                            uncertainty_weight = 1.0 / (1.0 + float(measurement['uncertainty_mm_yr']))
                            
                            combined_weight = distance_weight * coherence_weight * temporal_weight * uncertainty_weight
                            
                            if combined_weight > 0.01:  # Significance threshold
                                weighted_los += float(measurement['line_of_sight_velocity_mm_yr']) * combined_weight
                                weighted_vertical += float(measurement['vertical_velocity_mm_yr'] or 0.0) * combined_weight
                                weighted_east += float(measurement['east_velocity_mm_yr'] or 0.0) * combined_weight
                                weighted_north += float(measurement['north_velocity_mm_yr'] or 0.0) * combined_weight
                                weighted_coherence += coherence_weight * combined_weight
                                weighted_uncertainty += float(measurement['uncertainty_mm_yr']) * combined_weight
                                total_weight += combined_weight
                                
                                satellite_missions.add(measurement['satellite_mission'])
                        
                        if total_weight > 0:
                            insar_result['line_of_sight_velocity_mm_yr'] = weighted_los / total_weight
                            insar_result['vertical_velocity_mm_yr'] = weighted_vertical / total_weight
                            insar_result['east_velocity_mm_yr'] = weighted_east / total_weight  
                            insar_result['north_velocity_mm_yr'] = weighted_north / total_weight
                            insar_result['coherence_quality'] = weighted_coherence / total_weight
                            insar_result['uncertainty_mm_yr'] = weighted_uncertainty / total_weight
                            
                            # Calculate deformation magnitude from velocity components
                            insar_result['deformation_magnitude_mm_yr'] = np.sqrt(
                                insar_result['east_velocity_mm_yr']**2 + 
                                insar_result['north_velocity_mm_yr']**2 +
                                insar_result['vertical_velocity_mm_yr']**2
                            )
                            
                            # Convert deformation rate to strain rate (approximate)
                            # Assume deformation occurs over ~10km characteristic length scale
                            characteristic_length_m = 10000.0
                            insar_result['insar_strain_rate'] = (
                                insar_result['deformation_magnitude_mm_yr'] * 1e-3 / 
                                (characteristic_length_m * 365.25 * 24 * 3600)  # Convert to /s
                            )
                            
                            insar_result['satellite_missions'] = list(satellite_missions)
                            
                            # Calculate confidence based on coherence and observation density
                            observation_density = len(insar_measurements) / 100.0  # Normalize
                            coherence_factor = insar_result['coherence_quality']
                            uncertainty_factor = 1.0 / (1.0 + insar_result['uncertainty_mm_yr'] / 5.0)
                            
                            insar_result['confidence'] = min(0.85, 
                                0.3 + 0.25 * observation_density + 0.3 * coherence_factor + 0.15 * uncertainty_factor
                            )
                        
                        # Query InSAR time series data for temporal coherence analysis
                        time_series_query = """
                        SELECT 
                            COUNT(*) as time_series_count,
                            AVG(temporal_coherence) as avg_temporal_coherence
                        FROM insar_time_series its
                        WHERE ST_DWithin(ST_Point(%s, %s)::geography, its.location::geography, 50000)
                        AND its.time_series_data IS NOT NULL;
                        """
                        
                        time_series_data = self.external_data_manager.execute_spatial_query(
                            time_series_query, (lon, lat)
                        )
                        
                        if time_series_data and time_series_data[0]['time_series_count'] > 0:
                            insar_result['time_series_available'] = True
                            insar_result['temporal_coherence'] = float(
                                time_series_data[0]['avg_temporal_coherence'] or 0.0
                            )
                            insar_result['confidence'] *= (1.0 + 0.2 * insar_result['temporal_coherence'])
                            insar_result['data_sources'].append('insar_time_series_db')
                        
                except Exception as db_error:
                    self.logger.warning(f"InSAR database query failed: {db_error}")
            
            # Fallback to existing InSAR processor integration
            if insar_result['observation_count'] == 0:
                try:
                    # Leverage existing InSAR processor module for real-time data
                    if hasattr(self, 'insar_processor'):
                        processor_data = self.insar_processor.query_deformation_at_location(lat, lon)
                        if processor_data:
                            insar_result['data_sources'].append('insar_processor_ml')
                            insar_result.update(processor_data)
                    
                    # ESA Sentinel-1 mission integration
                    sentinel_data = self._query_sentinel1_interferometry(lat, lon)
                    if sentinel_data:
                        insar_result['data_sources'].append('sentinel1_esa')
                        insar_result['satellite_missions'].append('Sentinel-1')
                        await self._merge_insar_data_sources(insar_result, sentinel_data)
                    
                    # NASA/JPL InSAR data integration
                    nasa_data = self._query_nasa_insar_data(lat, lon)
                    if nasa_data:
                        insar_result['data_sources'].append('nasa_jpl_insar')
                        insar_result['satellite_missions'].extend(['ALOS-2', 'NISAR'])
                        await self._merge_insar_data_sources(insar_result, nasa_data)
                        
                except Exception as api_error:
                    self.logger.warning(f"InSAR API/processor queries failed: {api_error}")
            
            # Advanced atmospheric and topographic corrections if data available
            if insar_result['coherence_quality'] > 0:
                try:
                    # Apply atmospheric corrections using weather models
                    atmospheric_correction = await self._apply_atmospheric_corrections(
                        insar_result, lat, lon
                    )
                    insar_result['atmospheric_correction_applied'] = atmospheric_correction
                    
                    # Apply topographic corrections using DEM data
                    topographic_correction = await self._apply_topographic_corrections(
                        insar_result, lat, lon  
                    )
                    insar_result['topographic_correction_applied'] = topographic_correction
                    
                except Exception as correction_error:
                    self.logger.debug(f"InSAR corrections failed: {correction_error}")
            
            # Final validation and quality control
            if insar_result['deformation_magnitude_mm_yr'] > 500.0:  # Unrealistically high
                self.logger.warning(f"Clamping high InSAR deformation: {insar_result['deformation_magnitude_mm_yr']}")
                insar_result['deformation_magnitude_mm_yr'] = min(500.0, insar_result['deformation_magnitude_mm_yr'])
                insar_result['confidence'] *= 0.7
            
            # Set minimum confidence for fallback cases
            if insar_result['confidence'] == 0.0 and len(insar_result['data_sources']) > 0:
                insar_result['confidence'] = 0.4
            elif insar_result['confidence'] == 0.0:
                insar_result['insar_strain_rate'] = 1e-9  # Typical InSAR sensitivity
                insar_result['confidence'] = 0.2
                insar_result['data_sources'] = ['fallback_sensitivity']
            
            return insar_result
            
        except Exception as e:
            self.logger.warning(f"InSAR deformation database query failed: {e}")
            return {
                'insar_strain_rate': 1e-9,
                'deformation_magnitude_mm_yr': 1.0,
                'data_sources': ['fallback'],
                'confidence': 0.1,
                'observation_count': 0,
                'coherence_quality': 0.0
            }
    
    def _estimate_tectonic_strain_rates(self, location, geological_data):
        """Estimate tectonic strain rates from regional geology"""
        try:
            # Get tectonic setting
            tectonic_setting = geological_data.get('tectonic_setting', 'stable')
            
            # Setting-specific strain rates
            tectonic_rates = {
                'active_margin': 1e-7,    # /yr
                'passive_margin': 1e-9,   # /yr
                'rift_zone': 5e-8,        # /yr
                'transform_fault': 1e-7,  # /yr
                'stable_craton': 1e-10,   # /yr
                'orogenic_belt': 5e-8,    # /yr
                'stable': 1e-9            # /yr (default)
            }
            
            tectonic_strain_rate = tectonic_rates.get(tectonic_setting, 1e-9)
            
            return {
                'tectonic_strain_rate': tectonic_strain_rate,
                'tectonic_setting': tectonic_setting,
                'confidence': 0.7
            }
            
        except Exception as e:
            self.logger.warning(f"Tectonic strain rate estimation failed: {e}")
            return {'tectonic_strain_rate': 1e-9, 'confidence': 0.1}
    
    def _analyze_regional_strain_rate_context(self, strain_rate_field_data):
        """Analyze regional strain rate context from multiple data sources"""
        try:
            # Combine different data sources
            sources = []
            
            for source_name, data in strain_rate_field_data.items():
                if isinstance(data, dict) and 'confidence' in data:
                    sources.append({
                        'name': source_name,
                        'strain_rate': data.get('regional_strain_rate', data.get('seismic_strain_rate', 1e-9)),
                        'confidence': data['confidence']
                    })
            
            if sources:
                # Weighted average by confidence
                total_weight = sum(s['confidence'] for s in sources)
                if total_weight > 0:
                    weighted_strain_rate = sum(
                        s['strain_rate'] * s['confidence'] for s in sources
                    ) / total_weight
                else:
                    weighted_strain_rate = 1e-9
            else:
                weighted_strain_rate = 1e-9
            
            return {
                'regional_strain_rate': weighted_strain_rate,
                'data_sources': len(sources),
                'confidence': min(0.8, total_weight) if sources else 0.1
            }
            
        except Exception as e:
            self.logger.warning(f"Regional strain rate context analysis failed: {e}")
            return {'regional_strain_rate': 1e-9, 'confidence': 0.1}
    
    def _calculate_regional_strain_rate_factor(self, local_strain_rate, regional_context, geological_data):
        """Calculate regional strain rate correction factor"""
        try:
            regional_strain_rate = regional_context.get('regional_strain_rate', 1e-9)
            
            # Convert to same units if needed (assume local is in /s, regional in /yr)
            regional_strain_rate_per_sec = regional_strain_rate / (365.25 * 24 * 3600)
            
            # Calculate factor
            if local_strain_rate > 0 and regional_strain_rate_per_sec > 0:
                regional_factor = (regional_strain_rate_per_sec / local_strain_rate) ** 0.1
                regional_factor = max(0.5, min(2.0, regional_factor))  # Reasonable bounds
            else:
                regional_factor = 1.0
            
            return regional_factor
            
        except Exception as e:
            self.logger.warning(f"Regional strain rate factor calculation failed: {e}")
            return 1.0
    
