    async def _get_cached_data(self, cache_key):
        """Retrieve cached data with intelligent validation"""
        try:
            cache_manager = getattr(self, 'cache_manager', None)
            if cache_manager:
                return await cache_manager.get(cache_key)
            return None
        except Exception:
            return None
    
    async def _cache_data(self, cache_key, data, ttl=3600):
        """Cache data with configurable TTL"""
        try:
            cache_manager = getattr(self, 'cache_manager', None)
            if cache_manager:
                await cache_manager.set(cache_key, data, ttl=ttl)
        except Exception as e:
            self.logger.warning(f"Caching failed: {e}")
    
    def _generate_cache_key(self, source, location, geological_context, **kwargs):
        """Generate intelligent cache key"""
        import hashlib
        import json
        
        key_data = {
            'source': source,
            'location': location[:2],  # lat, lon only
            'geological_context': {k: v for k, v in geological_context.items() if k in ['rock_types', 'tectonic_setting', 'age_range']},
            'search_radius': kwargs.get('search_radius', 50),
            'quality_filter': kwargs.get('min_quality', 'good')
        }
        
        key_string = json.dumps(key_data, sort_keys=True)
        return f"geochem_{source}_{hashlib.md5(key_string.encode()).hexdigest()}"
    
    async def _get_cached_geochemical_data(self, location, geological_context):
        """Get cached geochemical data as fallback"""
        try:
            fallback_key = self._generate_cache_key('fallback', location, geological_context)
            cached = await self._get_cached_data(fallback_key)
            if cached:
                return cached
            
            # Return empty structure if no cache
            return {
                'major_elements': {},
                'trace_elements': {},
                'isotope_ratios': {},
                'data_quality': 'unavailable',
                'sample_count': 0
            }
        except Exception:
            return {'major_elements': {}, 'trace_elements': {}, 'isotope_ratios': {}}
    
    async def _store_geochemical_composition(self, db_manager, location, composition_data):
        """Store composition data in database"""
        try:
            from datetime import datetime
            
            lat, lon = location[:2]
            
            # Prepare data for database storage
            storage_data = {
                'latitude': lat,
                'longitude': lon,
                'sample_location': f'POINT({lon} {lat})',
                'major_elements': json.dumps(composition_data.get('major_elements', {})),
                'trace_elements': json.dumps(composition_data.get('trace_elements', {})),
                'isotope_ratios': json.dumps(composition_data.get('isotope_ratios', {})),
                'data_quality_score': composition_data.get('data_quality_score', 0.5),
                'sample_count': composition_data.get('sample_count', 0),
                'query_timestamp': datetime.utcnow(),
                'integration_method': 'advanced_parallel_query'
            }
            
            # Insert into geochemical_composition table
            await db_manager.execute_query(
                """
                INSERT INTO geochemical_composition 
                (latitude, longitude, sample_location, major_elements, trace_elements, 
                 isotope_ratios, data_quality_score, sample_count, query_timestamp, integration_method)
                VALUES (%(latitude)s, %(longitude)s, ST_GeomFromText(%(sample_location)s, 4326), 
                        %(major_elements)s, %(trace_elements)s, %(isotope_ratios)s,
                        %(data_quality_score)s, %(sample_count)s, %(query_timestamp)s, %(integration_method)s)
                ON CONFLICT (latitude, longitude) DO UPDATE SET
                major_elements = EXCLUDED.major_elements,
                trace_elements = EXCLUDED.trace_elements,
                isotope_ratios = EXCLUDED.isotope_ratios,
                data_quality_score = EXCLUDED.data_quality_score,
                sample_count = EXCLUDED.sample_count,
                query_timestamp = EXCLUDED.query_timestamp
                """,
                storage_data
            )
            
        except Exception as e:
            self.logger.warning(f"Database storage failed: {e}")
    
    def _calculate_cipw_norm(self, major_elements):
        """Calculate CIPW normative minerals from major element composition"""
        try:
            # Simplified CIPW norm calculation
            sio2 = major_elements.get('SiO2', 65.0)
            al2o3 = major_elements.get('Al2O3', 15.0)
            fe2o3 = major_elements.get('Fe2O3', 5.0)
            mgo = major_elements.get('MgO', 3.0)
            cao = major_elements.get('CaO', 5.0)
            na2o = major_elements.get('Na2O', 3.0)
            k2o = major_elements.get('K2O', 2.0)
            
            # Normative mineral calculations (simplified)
            quartz = max(0, sio2 - 60.0)  # Excess silica becomes quartz
            orthoclase = k2o * 5.56  # K2O -> Or conversion factor
            albite = na2o * 5.24     # Na2O -> Ab conversion factor
            anorthite = min(cao, al2o3 - na2o - k2o) * 2.78 if al2o3 > (na2o + k2o) else 0
            
            # Mafic minerals
            enstatite = mgo * 1.66   # MgO -> En
            magnetite = fe2o3 * 1.39 # Fe2O3 -> Mt
            
            # Normalize to 100%
            total = quartz + orthoclase + albite + anorthite + enstatite + magnetite
            if total > 0:
                norm_factor = 100.0 / total
                normative = {
                    'quartz': quartz * norm_factor,
                    'orthoclase': orthoclase * norm_factor,
                    'albite': albite * norm_factor,
                    'anorthite': anorthite * norm_factor,
                    'enstatite': enstatite * norm_factor,
                    'magnetite': magnetite * norm_factor
                }
            else:
                normative = {'quartz': 50, 'feldspar': 50}
            
            return normative
            
        except Exception as e:
            self.logger.warning(f"CIPW norm calculation failed: {e}")
            return {'quartz': 30, 'feldspar': 40, 'mica': 20, 'other': 10}
    
    def _get_schmid_factor_limits(self, slip_system):
        """Get theoretical Schmid factor limits for slip system"""
        try:
            crystal_system = slip_system.get('crystal_system', 'cubic')
            
            limits = {
                'cubic': {'min': 0.0, 'max': 0.5},
                'hexagonal': {'min': 0.0, 'max': 0.5},
                'orthorhombic': {'min': 0.0, 'max': 0.5},
                'monoclinic': {'min': 0.0, 'max': 0.5},
                'triclinic': {'min': 0.0, 'max': 0.5}
            }
            
            return limits.get(crystal_system, {'min': 0.0, 'max': 0.5})
            
        except Exception:
            return {'min': 0.0, 'max': 0.5}
    
    def _get_temperature_coefficient(self, slip_system):
        """Get temperature dependence coefficient for slip system"""
        try:
            # Temperature dependence varies by mineral and slip system
            base_coeff = slip_system.get('activation_energy', 2.0e-19) / (8.314 * 298.15)  # Boltzmann factor
            
            crystal_system = slip_system.get('crystal_system', 'cubic')
            system_modifier = {
                'cubic': 1.0,
                'hexagonal': 1.2,
                'orthorhombic': 1.1, 
                'monoclinic': 1.3,
                'triclinic': 1.4
            }.get(crystal_system, 1.0)
            
            return base_coeff * system_modifier
            
        except Exception:
            return 1.0
    
    def _get_pressure_coefficient(self, slip_system):
        """Get pressure dependence coefficient for slip system"""
        try:
            # Pressure coefficient based on activation volume
            activation_volume = slip_system.get('activation_volume', 1e-29)  # m³
            
            # Pressure coefficient in units of 1/Pa
            return activation_volume / (8.314 * 298.15)
            
        except Exception:
            return 0.0
    
    def _calculate_texture_evolution(self, slip_system_activities, deformation_history):
        """Calculate crystallographic texture evolution from slip system activities"""
        try:
            # Initialize orientation distribution function (ODF)
            initial_texture = deformation_history.get('initial_texture', 'random')
            
            if initial_texture == 'random':
                # Start with random texture
                odf = self._initialize_random_odf()
            else:
                # Use specified initial texture
                odf = deformation_history.get('initial_odf', self._initialize_random_odf())
            
            # Evolve texture based on slip system activities
            for slip_name, activity_data in slip_system_activities.items():
                activity = activity_data.get('slip_strain_rate', 0.0)
                
                if activity > 1e-18:  # Only consider active systems
                    # Get slip system geometry
                    slip_system = activity_data.get('slip_system', {})
                    plane_normal = np.array(slip_system.get('plane', [1,0,0]))
                    slip_direction = np.array(slip_system.get('direction', [0,1,0]))
                    
                    # Update ODF based on slip activity
                    odf = self._update_odf_for_slip(odf, plane_normal, slip_direction, activity)
            
            # Calculate texture strength and symmetry
            texture_strength = self._calculate_texture_strength(odf)
            texture_symmetry = self._identify_texture_symmetry(odf)
            
            # Calculate preferred orientations
            preferred_orientations = self._find_preferred_orientations(odf)
            
            return {
                'odf': odf,
                'texture_strength': texture_strength,
                'texture_symmetry': texture_symmetry,
                'preferred_orientations': preferred_orientations,
                'fabric_tensor': self._calculate_fabric_tensor_from_odf(odf)
            }
            
        except Exception as e:
            self.logger.warning(f"Texture evolution calculation failed: {e}")
            return {'texture_strength': 1.0, 'texture_symmetry': 'random'}
    
    def _initialize_random_odf(self):
        """Initialize random orientation distribution function"""
        try:
            # Create random ODF on SO(3) space
            # This is a simplified representation - real implementation would use spherical harmonics
            n_orientations = 1000
            orientations = np.random.random((n_orientations, 3, 3))
            
            # Orthogonalize to ensure proper rotation matrices
            for i in range(n_orientations):
                U, _, Vt = np.linalg.svd(orientations[i])
                orientations[i] = U @ Vt
                
                # Ensure determinant = 1 (proper rotation)
                if np.linalg.det(orientations[i]) < 0:
                    orientations[i][0] *= -1
            
            weights = np.ones(n_orientations) / n_orientations
            
            return {'orientations': orientations, 'weights': weights}
            
        except Exception as e:
            self.logger.warning(f"Random ODF initialization failed: {e}")
            return {'orientations': np.array([np.eye(3)]), 'weights': np.array([1.0])}
    
    def _update_odf_for_slip(self, odf, plane_normal, slip_direction, activity):
        """Update ODF based on slip system activity"""
        try:
            orientations = odf['orientations']
            weights = odf['weights'].copy()
            
            # Normalize vectors
            plane_normal = plane_normal / np.linalg.norm(plane_normal)
            slip_direction = slip_direction / np.linalg.norm(slip_direction)
            
            # Update weights based on Schmid factor and activity
            for i, orientation in enumerate(orientations):
                # Transform slip system to sample coordinates
                transformed_normal = orientation @ plane_normal
                transformed_direction = orientation @ slip_direction
                
                # Calculate alignment factor (simplified)
                alignment = np.abs(np.dot(transformed_direction, [1,0,0]))  # Alignment with loading direction
                
                # Update weight based on activity and alignment
                weight_change = activity * 1e15 * alignment  # Scale factor
                weights[i] *= (1.0 + weight_change)
            
            # Renormalize weights
            weights = weights / np.sum(weights)
            
            return {'orientations': orientations, 'weights': weights}
            
        except Exception as e:
            self.logger.warning(f"ODF update for slip failed: {e}")
            return odf
    
    def _calculate_texture_strength(self, odf):
        """Calculate texture strength from ODF"""
        try:
            weights = odf['weights']
            
            # Texture strength as standard deviation of weights
            mean_weight = np.mean(weights)
            texture_strength = np.sqrt(np.mean((weights - mean_weight)**2)) / mean_weight
            
            return texture_strength
            
        except Exception as e:
            self.logger.warning(f"Texture strength calculation failed: {e}")
            return 1.0
    
    def _identify_texture_symmetry(self, odf):
        """Identify texture symmetry from ODF"""
        try:
            # This would involve complex crystallographic analysis
            # For now, return simplified classification
            texture_strength = self._calculate_texture_strength(odf)
            
            if texture_strength < 0.1:
                return 'random'
            elif texture_strength < 0.3:
                return 'weak_preferred'
            elif texture_strength < 0.6:
                return 'moderate_preferred' 
            else:
                return 'strong_preferred'
                
        except Exception as e:
            self.logger.warning(f"Texture symmetry identification failed: {e}")
            return 'unknown'
    
    def _find_preferred_orientations(self, odf):
        """Find preferred crystallographic orientations"""
        try:
            orientations = odf['orientations']
            weights = odf['weights']
            
            # Find orientations with highest weights
            top_indices = np.argsort(weights)[-5:]  # Top 5 orientations
            
            preferred_orientations = []
            for idx in top_indices:
                if weights[idx] > np.mean(weights) * 1.5:
                    # Convert rotation matrix to Euler angles
                    euler_angles = self._rotation_matrix_to_euler(orientations[idx])
                    preferred_orientations.append({
                        'euler_angles': euler_angles,
                        'weight': weights[idx],
                        'rotation_matrix': orientations[idx]
                    })
            
            return preferred_orientations
            
        except Exception as e:
            self.logger.warning(f"Preferred orientation calculation failed: {e}")
            return []
    
    def _rotation_matrix_to_euler(self, R):
        """Convert rotation matrix to Euler angles (ZXZ convention)"""
        try:
            # ZXZ Euler angles
            phi1 = np.arctan2(R[0,2], -R[1,2])
            Phi = np.arccos(R[2,2])
            phi2 = np.arctan2(R[2,0], R[2,1])
            
            return [np.degrees(phi1), np.degrees(Phi), np.degrees(phi2)]
            
        except Exception as e:
            self.logger.warning(f"Euler angle conversion failed: {e}")
            return [0.0, 0.0, 0.0]
    
    def _calculate_fabric_tensor_from_odf(self, odf):
        """Calculate fabric tensor from orientation distribution function"""
        try:
            orientations = odf['orientations']
            weights = odf['weights']
            
            # Calculate 2nd order fabric tensor
            fabric_tensor = np.zeros((3, 3))
            
            for i, orientation in enumerate(orientations):
                # Extract c-axis or principal direction from orientation
                c_axis = orientation[:, 2]  # Assume c-axis is third column
                
                # Add weighted contribution to fabric tensor
                fabric_tensor += weights[i] * np.outer(c_axis, c_axis)
            
            return fabric_tensor
            
        except Exception as e:
            self.logger.warning(f"Fabric tensor calculation from ODF failed: {e}")
            return np.eye(3)
    
