    def _calculate_strain_rate_multiphysics_coupling(self, stress, strain_rate, geological_data):
        """Advanced multi-physics coupling calculation with thermomechanical, chemical, and electromagnetic interactions"""
        try:
            from .thermodynamic_integration import ThermodynamicIntegration
            from .hydrothermal_flow_engine import HydrothermalFlowEngine
            from .multi_physics_coupling_engine import MultiPhysicsCouplingEngine
            
            # Initialize advanced physics engines if not already done
            if not hasattr(self, '_thermo_engine'):
                self._thermo_engine = ThermodynamicIntegration({
                    'temperature_coupling': True,
                    'pressure_coupling': True,
                    'chemical_coupling': True,
                    'phase_transitions': True
                })
            
            if not hasattr(self, '_hydrothermal_engine'):
                self._hydrothermal_engine = HydrothermalFlowEngine({
                    'fluid_coupling': True,
                    'pore_pressure_effects': True,
                    'permeability_evolution': True,
                    'chemical_alteration': True
                })
            
            if not hasattr(self, '_multiphysics_engine'):
                self._multiphysics_engine = MultiPhysicsCouplingEngine({
                    'electromagnetic_coupling': True,
                    'poroelastic_coupling': True,
                    'thermoelastic_coupling': True,
                    'chemomechanical_coupling': True,
                    'viscoplastic_coupling': True
                })
            
            # Extract physical parameters
            temperature = geological_data.get('temperature', 300.0)  # K
            pressure = geological_data.get('pressure', 1e5)  # Pa
            porosity = geological_data.get('porosity', 0.1)
            permeability = geological_data.get('permeability', 1e-15)  # m^2
            fluid_density = geological_data.get('fluid_density', 1000.0)  # kg/m^3
            rock_composition = geological_data.get('composition', {})
            
            # 1. Thermomechanical coupling
            thermo_results = self._thermo_engine.calculate_thermomechanical_coupling(
                stress_tensor=stress,
                strain_rate_tensor=strain_rate,
                temperature=temperature,
                pressure=pressure,
                composition=rock_composition
            )
            
            # 2. Poroelastic coupling with fluid flow
            poro_results = self._hydrothermal_engine.calculate_poroelastic_coupling(
                effective_stress=stress,
                strain_rate=strain_rate,
                porosity=porosity,
                permeability=permeability,
                fluid_pressure=geological_data.get('fluid_pressure', pressure * 0.4),
                fluid_density=fluid_density
            )
            
            # 3. Chemical-mechanical coupling
            chemical_results = self._multiphysics_engine.calculate_chemomechanical_coupling(
                stress=stress,
                strain_rate=strain_rate,
                temperature=temperature,
                ph=geological_data.get('ph', 7.0),
                ionic_strength=geological_data.get('ionic_strength', 0.1),
                mineral_phases=rock_composition
            )
            
            # 4. Electromagnetic coupling (for conductive minerals/fluids)
            em_results = self._multiphysics_engine.calculate_electromagnetic_coupling(
                stress=stress,
                strain_rate=strain_rate,
                conductivity=geological_data.get('electrical_conductivity', 1e-6),
                magnetic_susceptibility=geological_data.get('magnetic_susceptibility', 1e-5),
                temperature=temperature
            )
            
            # 5. Viscoplastic coupling for time-dependent behavior
            viscoplastic_results = self._multiphysics_engine.calculate_viscoplastic_coupling(
                stress=stress,
                strain_rate=strain_rate,
                temperature=temperature,
                grain_size=geological_data.get('grain_size', 1e-3),  # m
                activation_energy=geological_data.get('activation_energy', 300e3),  # J/mol
                stress_exponent=geological_data.get('stress_exponent', 3.5)
            )
            
            # Integrate all coupling effects with physics-based weighting
            total_coupling_factor = 1.0
            confidence_factors = []
            
            # Thermomechanical contribution (temperature-dependent)
            if thermo_results.get('success', False):
                thermal_factor = thermo_results['thermal_expansion_coefficient'] * \
                               (temperature - 273.15) * thermo_results['coupling_strength']
                total_coupling_factor += thermal_factor
                confidence_factors.append(thermo_results.get('confidence', 0.0))
            
            # Poroelastic contribution (pressure-dependent)
            if poro_results.get('success', False):
                poro_factor = poro_results['biot_coefficient'] * \
                             poro_results['fluid_pressure_effect'] * \
                             poro_results['coupling_strength']
                total_coupling_factor *= (1.0 + poro_factor)
                confidence_factors.append(poro_results.get('confidence', 0.0))
            
            # Chemical contribution (composition-dependent)
            if chemical_results.get('success', False):
                chemical_factor = chemical_results['reaction_rate'] * \
                                chemical_results['volume_change'] * \
                                chemical_results['coupling_strength']
                total_coupling_factor *= (1.0 + chemical_factor)
                confidence_factors.append(chemical_results.get('confidence', 0.0))
            
            # Electromagnetic contribution (for conductive materials)
            if em_results.get('success', False):
                em_factor = em_results['magnetostriction_coefficient'] * \
                           em_results['joule_heating_effect'] * \
                           em_results['coupling_strength']
                total_coupling_factor *= (1.0 + em_factor)
                confidence_factors.append(em_results.get('confidence', 0.0))
            
            # Viscoplastic contribution (time and rate-dependent)
            if viscoplastic_results.get('success', False):
                visco_factor = viscoplastic_results['creep_rate_enhancement'] * \
                              viscoplastic_results['strain_rate_sensitivity'] * \
                              viscoplastic_results['coupling_strength']
                total_coupling_factor *= (1.0 + visco_factor)
                confidence_factors.append(viscoplastic_results.get('confidence', 0.0))
            
            # Calculate overall confidence using harmonic mean (conservative)
            if confidence_factors:
                overall_confidence = len(confidence_factors) / sum(1.0/max(c, 1e-6) for c in confidence_factors)
            else:
                overall_confidence = 0.1
            
            # Apply physical bounds and stability checks
            total_coupling_factor = max(0.1, min(total_coupling_factor, 10.0))  # Physical bounds
            
            # Advanced uncertainty quantification
            uncertainty_sources = {
                'model_uncertainty': 0.15,  # Inherent model limitations
                'parameter_uncertainty': np.std(confidence_factors) if confidence_factors else 0.3,
                'coupling_nonlinearity': abs(total_coupling_factor - 1.0) * 0.1,
                'measurement_uncertainty': 0.05,
                'temporal_variability': 0.1
            }
            
            total_uncertainty = np.sqrt(sum(u**2 for u in uncertainty_sources.values()))
            final_confidence = max(0.0, overall_confidence - total_uncertainty)
            
            # Store detailed results for analysis and validation
            detailed_results = {
                'coupling_factor': float(total_coupling_factor),
                'confidence': float(final_confidence),
                'uncertainty': float(total_uncertainty),
                'component_contributions': {
                    'thermomechanical': thermo_results,
                    'poroelastic': poro_results,
                    'chemical': chemical_results,
                    'electromagnetic': em_results,
                    'viscoplastic': viscoplastic_results
                },
                'uncertainty_breakdown': uncertainty_sources,
                'physical_bounds_applied': total_coupling_factor != (total_coupling_factor if 0.1 <= total_coupling_factor <= 10.0 else max(0.1, min(total_coupling_factor, 10.0))),
                'analysis_metadata': {
                    'temperature_k': temperature,
                    'pressure_pa': pressure,
                    'porosity': porosity,
                    'permeability_m2': permeability,
                    'computation_timestamp': datetime.utcnow().isoformat(),
                    'physics_engines_used': ['thermodynamic', 'hydrothermal', 'multiphysics']
                }
            }
            
            return detailed_results
            
        except ImportError as e:
            self.logger.warning(f"Advanced physics engines not available: {e}. Using fallback calculation.")
            return self._calculate_strain_rate_coupling_fallback(stress, strain_rate, geological_data)
        except Exception as e:
            self.logger.error(f"Multi-physics coupling calculation failed: {e}")
            return self._calculate_strain_rate_coupling_fallback(stress, strain_rate, geological_data)
    
    def _calculate_strain_rate_coupling_fallback(self, stress, strain_rate, geological_data):
        """Fallback calculation using simplified physics-based approach"""
        try:
            # Physics-based fallback using fundamental relationships
            temperature = geological_data.get('temperature', 300.0)
            pressure = geological_data.get('pressure', 1e5)
            
            # Temperature dependence (Arrhenius-like)
            thermal_factor = np.exp(-50000 / (8.314 * temperature))  # Simplified activation
            
            # Pressure dependence (linear approximation)
            pressure_factor = 1.0 + (pressure - 1e5) / 1e9
            
            # Strain rate dependence (power law)
            rate_factor = (strain_rate / 1e-15) ** 0.1 if strain_rate > 0 else 1.0
            
            coupling_factor = thermal_factor * pressure_factor * rate_factor
            coupling_factor = max(0.5, min(coupling_factor, 3.0))  # Reasonable bounds
            
            return {
                'coupling_factor': float(coupling_factor),
                'confidence': 0.4,  # Lower confidence for fallback
                'fallback_method': True,
                'temperature_factor': float(thermal_factor),
                'pressure_factor': float(pressure_factor),
                'rate_factor': float(rate_factor)
            }
            
        except Exception as e:
            self.logger.warning(f"Fallback coupling calculation failed: {e}")
            return {'coupling_factor': 1.0, 'confidence': 0.1, 'error': str(e)}
    
    async def _store_strain_rate_analysis_results(self, validated_stress, analysis_system, combined_effects):
        """Advanced database integration for strain rate analysis results with real-time processing"""
        try:
            from .database_integration import DatabaseIntegration
            from .model_database import ModelDatabase
            from .stream_processing import StreamProcessor
            import asyncio
            import hashlib
            import json
            
            # Initialize database connections if not already done
            if not hasattr(self, '_db_integration'):
                self._db_integration = DatabaseIntegration({
                    'host': os.environ.get('PROMETHEUS_DB_HOST', 'localhost'),
                    'port': int(os.environ.get('PROMETHEUS_DB_PORT', '5432')),
                    'database': os.environ.get('PROMETHEUS_DB_NAME', 'prometheus_geo'),
                    'username': os.environ.get('PROMETHEUS_DB_USER', 'prometheus_user'),
                    'password': os.environ.get('PROMETHEUS_DB_PASSWORD', 'prometheus_password'),
                    'enable_timescaledb': True,
                    'enable_postgis': True,
                    'connection_pool_size': 20
                })
            
            if not hasattr(self, '_model_db'):
                self._model_db = ModelDatabase(self._db_integration)
            
            if not hasattr(self, '_stream_processor'):
                self._stream_processor = StreamProcessor({
                    'kafka_brokers': os.environ.get('KAFKA_BROKERS', 'localhost:9092').split(','),
                    'redis_host': os.environ.get('REDIS_HOST', 'localhost'),
                    'redis_port': int(os.environ.get('REDIS_PORT', '6379')),
                    'enable_real_time': True
                })
            
            current_time = datetime.utcnow()
            
            # Create comprehensive result entry with enhanced metadata
            result_entry = {
                'analysis_id': str(uuid.uuid4()),
                'timestamp': current_time,
                'validated_stress': self._serialize_tensor_data(validated_stress),
                'combined_effects': combined_effects,
                'analysis_system': analysis_system,
                'computation_metadata': {
                    'enkf_iteration': getattr(self, 'current_iteration', None),
                    'convergence_status': getattr(self, 'convergence_status', 'unknown'),
                    'computational_cost_seconds': getattr(self, 'last_computation_time', 0.0),
                    'memory_usage_mb': getattr(self, 'memory_usage', 0.0),
                    'parallel_processes_used': getattr(self, 'parallel_processes', 1)
                },
                'quality_metrics': {
                    'stress_tensor_conditioning': self._calculate_tensor_conditioning(validated_stress),
                    'analysis_confidence': combined_effects.get('confidence', 0.0),
                    'uncertainty_bounds': combined_effects.get('uncertainty', {}),
                    'validation_score': self._calculate_validation_score(validated_stress, combined_effects),
                    'consistency_check': self._perform_consistency_check(validated_stress, analysis_system)
                },
                'geological_context': {
                    'location': getattr(self, 'current_location', {'lat': None, 'lon': None}),
                    'depth_km': getattr(self, 'analysis_depth', None),
                    'geological_unit': getattr(self, 'geological_unit', None),
                    'tectonic_setting': getattr(self, 'tectonic_setting', None)
                }
            }
            
            # Generate content hash for deduplication
            content_hash = hashlib.sha256(
                json.dumps(result_entry, sort_keys=True, default=str).encode()
            ).hexdigest()
            result_entry['content_hash'] = content_hash
            
            # Store in multiple systems asynchronously for redundancy and performance
            storage_tasks = []
            
            # 1. Store in TimescaleDB for time-series analysis
            storage_tasks.append(
                self._store_in_timescaledb(result_entry, 'strain_rate_analysis_results')
            )
            
            # 2. Store in PostGIS for spatial analysis
            if result_entry['geological_context']['location']['lat'] is not None:
                storage_tasks.append(
                    self._store_in_postgis(result_entry, 'spatial_strain_analysis')
                )
            
            # 3. Store in model database for ML training data
            storage_tasks.append(
                self._model_db.store_training_sample(
                    input_features=self._extract_features_for_ml(validated_stress, analysis_system),
                    target_values=combined_effects,
                    metadata=result_entry['computation_metadata'],
                    sample_type='strain_rate_analysis'
                )
            )
            
            # 4. Stream to real-time processing pipeline
            storage_tasks.append(
                self._stream_processor.publish_message(
                    topic='strain_rate_updates',
                    message={
                        'event_type': 'strain_rate_analysis_complete',
                        'analysis_id': result_entry['analysis_id'],
                        'timestamp': current_time.isoformat(),
                        'summary': {
                            'max_stress': float(np.max(np.abs(validated_stress))),
                            'coupling_factor': combined_effects.get('coupling_factor', 1.0),
                            'confidence': combined_effects.get('confidence', 0.0)
                        },
                        'location': result_entry['geological_context']['location']
                    }
                )
            )
            
            # 5. Update in-memory cache for rapid access
            storage_tasks.append(
                self._update_memory_cache(result_entry)
            )
            
            # Execute all storage operations concurrently
            results = await asyncio.gather(*storage_tasks, return_exceptions=True)
            
            # Process results and handle any failures
            successful_stores = 0
            failed_stores = []
            
            for i, result in enumerate(results):
                if isinstance(result, Exception):
                    failed_stores.append(f"Task {i}: {result}")
                    self.logger.warning(f"Storage task {i} failed: {result}")
                else:
                    successful_stores += 1
            
            # Log storage summary
            self.logger.info(
                f"Strain rate analysis results stored: {successful_stores}/{len(storage_tasks)} successful. "
                f"Analysis ID: {result_entry['analysis_id']}"
            )
            
            if failed_stores:
                self.logger.warning(f"Some storage operations failed: {failed_stores}")
            
            # Maintain local backup for critical data
            await self._maintain_local_backup(result_entry)
            
            # Trigger data quality validation
            await self._validate_stored_data(result_entry['analysis_id'])
            
            # Update system metrics
            self._update_analysis_metrics(successful_stores, len(storage_tasks))
            
            return {
                'success': successful_stores > 0,
                'analysis_id': result_entry['analysis_id'],
                'stores_completed': successful_stores,
                'stores_failed': len(failed_stores),
                'content_hash': content_hash
            }
            
        except ImportError as e:
            self.logger.warning(f"Advanced database integration not available: {e}. Using fallback storage.")
            return await self._store_strain_rate_results_fallback(validated_stress, analysis_system, combined_effects)
        except Exception as e:
            self.logger.error(f"Advanced strain rate result storage failed: {e}")
            return await self._store_strain_rate_results_fallback(validated_stress, analysis_system, combined_effects)
    
    async def _store_in_timescaledb(self, result_entry, table_name):
        """Store results in TimescaleDB for time-series analysis"""
        try:
            async with self._db_integration.get_async_connection() as conn:
                await conn.execute("""
                    INSERT INTO strain_rate_analysis_timeseries 
                    (analysis_id, timestamp, stress_data, effects_data, metadata, content_hash)
                    VALUES ($1, $2, $3, $4, $5, $6)
                    ON CONFLICT (content_hash) DO UPDATE SET
                    last_updated = EXCLUDED.timestamp
                """, (
                    result_entry['analysis_id'],
                    result_entry['timestamp'],
                    json.dumps(result_entry['validated_stress']),
                    json.dumps(result_entry['combined_effects']),
                    json.dumps(result_entry['computation_metadata']),
                    result_entry['content_hash']
                ))
            return True
        except Exception as e:
            self.logger.error(f"TimescaleDB storage failed: {e}")
            raise
    
    async def _store_in_postgis(self, result_entry, table_name):
        """Store results in PostGIS for spatial analysis"""
        try:
            location = result_entry['geological_context']['location']
            if location['lat'] is None or location['lon'] is None:
                return False
            
            async with self._db_integration.get_async_connection() as conn:
                await conn.execute("""
                    INSERT INTO spatial_strain_analysis 
                    (analysis_id, timestamp, location, depth_km, stress_magnitude, 
                     coupling_factor, confidence, geological_metadata)
                    VALUES ($1, $2, ST_SetSRID(ST_MakePoint($3, $4), 4326), $5, $6, $7, $8, $9)
                """, (
                    result_entry['analysis_id'],
                    result_entry['timestamp'],
                    location['lon'],
                    location['lat'],
                    result_entry['geological_context']['depth_km'],
                    float(np.max(np.abs(result_entry['validated_stress']))),
                    result_entry['combined_effects'].get('coupling_factor', 1.0),
                    result_entry['combined_effects'].get('confidence', 0.0),
                    json.dumps(result_entry['geological_context'])
                ))
            return True
        except Exception as e:
            self.logger.error(f"PostGIS storage failed: {e}")
            raise
    
    async def _update_memory_cache(self, result_entry):
        """Update in-memory cache for rapid access"""
        if not hasattr(self, 'strain_rate_cache'):
            self.strain_rate_cache = {}
        
        # Maintain cache with LRU eviction
        cache_key = result_entry['analysis_id']
        self.strain_rate_cache[cache_key] = {
            'timestamp': result_entry['timestamp'],
            'summary': {
                'coupling_factor': result_entry['combined_effects'].get('coupling_factor', 1.0),
                'confidence': result_entry['combined_effects'].get('confidence', 0.0),
                'stress_magnitude': float(np.max(np.abs(result_entry['validated_stress'])))
            }
        }
        
        # Keep only recent entries (last 1000)
        if len(self.strain_rate_cache) > 1000:
            # Remove oldest entries
            sorted_entries = sorted(
                self.strain_rate_cache.items(),
                key=lambda x: x[1]['timestamp']
            )
            for key, _ in sorted_entries[:-1000]:
                del self.strain_rate_cache[key]
        
        return True
    
    async def _store_strain_rate_results_fallback(self, validated_stress, analysis_system, combined_effects):
        """Fallback storage using simple file-based approach"""
        try:
            if not hasattr(self, 'strain_rate_history'):
                self.strain_rate_history = []
            
            result_entry = {
                'analysis_id': str(uuid.uuid4()),
                'timestamp': datetime.utcnow(),
                'stress': self._serialize_tensor_data(validated_stress),
                'combined_effects': combined_effects,
                'analysis_system': analysis_system
            }
            
            self.strain_rate_history.append(result_entry)
            
            # Keep only recent history (last 500 entries for fallback)
            if len(self.strain_rate_history) > 500:
                self.strain_rate_history = self.strain_rate_history[-500:]
            
            # Save to backup file
            backup_file = f"strain_rate_backup_{datetime.now().strftime('%Y%m%d')}.json"
            try:
                with open(backup_file, 'w') as f:
                    json.dump(self.strain_rate_history[-10:], f, default=str, indent=2)  # Save recent entries
            except Exception as backup_error:
                self.logger.warning(f"Backup file write failed: {backup_error}")
            
            return {
                'success': True,
                'analysis_id': result_entry['analysis_id'],
                'fallback_method': True,
                'entries_stored': len(self.strain_rate_history)
            }
            
        except Exception as e:
            self.logger.error(f"Fallback strain rate storage failed: {e}")
            return {'success': False, 'error': str(e)}
    
    # Advanced supporting methods for the comprehensive implementations
    
    def _analyze_nested_structure(self, data, max_depth=5, current_depth=0):
        """Analyze nested data structure for serialization optimization"""
        if current_depth >= max_depth:
            return {'max_depth_reached': True}
        
        try:
            structure_info = {
                'type': type(data).__name__,
                'size': len(data) if hasattr(data, '__len__') else 1
            }
            
            if isinstance(data, (list, tuple)):
                if data:
                    first_element = data[0]
                    structure_info['element_type'] = type(first_element).__name__
                    if isinstance(first_element, (list, tuple, dict)):
                        structure_info['nested_structure'] = self._analyze_nested_structure(
                            first_element, max_depth, current_depth + 1
                        )
            elif isinstance(data, dict):
                if data:
                    first_value = next(iter(data.values()))
                    structure_info['value_type'] = type(first_value).__name__
                    if isinstance(first_value, (list, tuple, dict)):
                        structure_info['nested_structure'] = self._analyze_nested_structure(
                            first_value, max_depth, current_depth + 1
                        )
            
            return structure_info
            
        except Exception:
            return {'analysis_failed': True}
    
    def _calculate_condition_number_robust(self, tensor):
        """Calculate condition number with robust handling of edge cases"""
        try:
            if not isinstance(tensor, np.ndarray) or tensor.ndim < 2:
                return 1.0
            
            # Handle different tensor shapes
            if tensor.ndim > 2:
                # For higher dimensions, work with the first 2D slice
                tensor_2d = tensor.reshape(tensor.shape[0], -1)
            else:
                tensor_2d = tensor
            
            # Multiple condition number calculations
            try:
                cond_2 = np.linalg.cond(tensor_2d, p=2)
                return float(cond_2) if np.isfinite(cond_2) else float('inf')
            except Exception:
                # Fallback using SVD
                try:
                    U, s, Vt = np.linalg.svd(tensor_2d, full_matrices=False)
                    nonzero_s = s[s > 1e-16]
                    if len(nonzero_s) > 0:
                        return float(np.max(nonzero_s) / np.min(nonzero_s))
                    else:
                        return float('inf')
                except Exception:
                    return float('inf')
                    
        except Exception:
            return float('inf')
    
    def _calculate_tensor_rank_advanced(self, tensor):
        """Calculate tensor rank with numerical stability considerations"""
        try:
            if not isinstance(tensor, np.ndarray) or tensor.ndim < 2:
                return tensor.size if hasattr(tensor, 'size') else 1
            
            if tensor.ndim > 2:
                tensor_2d = tensor.reshape(tensor.shape[0], -1)
            else:
                tensor_2d = tensor
            
            # Use SVD for rank calculation
            s = np.linalg.svd(tensor_2d, compute_uv=False)
            
            # Multiple tolerance levels for rank determination
            tolerances = [1e-12, 1e-10, 1e-8, 1e-6]
            ranks = {}
            
            max_singular_value = np.max(s) if len(s) > 0 else 1.0
            
            for tol in tolerances:
                threshold = max_singular_value * tol
                rank = np.sum(s > threshold)
                ranks[f'rank_tol_1e{int(np.log10(tol))}'] = int(rank)
            
            # Return numerical rank (most conservative)
            return ranks.get('rank_tol_1e-12', 0)
            
        except Exception:
            return 0
    
    def _calculate_eigenvalue_summary(self, tensor):
        """Calculate eigenvalue summary for square tensors"""
        try:
            if not isinstance(tensor, np.ndarray) or tensor.ndim != 2 or tensor.shape[0] != tensor.shape[1]:
                return {'not_applicable': 'non_square_tensor'}
            
            eigenvals = np.linalg.eigvals(tensor)
            
            return {
                'count': len(eigenvals),
                'real_eigenvalues': int(np.sum(np.abs(np.imag(eigenvals)) < 1e-12)),
                'complex_eigenvalues': int(np.sum(np.abs(np.imag(eigenvals)) >= 1e-12)),
                'positive_eigenvalues': int(np.sum(np.real(eigenvals) > 1e-12)),
                'negative_eigenvalues': int(np.sum(np.real(eigenvals) < -1e-12)),
                'zero_eigenvalues': int(np.sum(np.abs(eigenvals) < 1e-12)),
                'spectral_radius': float(np.max(np.abs(eigenvals))),
                'condition_number_eigenvalue': float(np.max(np.abs(eigenvals)) / (np.min(np.abs(eigenvals[np.abs(eigenvals) > 1e-16])) + 1e-16))
            }
            
        except Exception:
            return {'eigenvalue_analysis_failed': True}
    
