    async def _perform_comprehensive_uncertainty_analysis(self, features, processing_result):
        """Perform comprehensive uncertainty analysis across all feature types"""
        try:
            uncertainty_analysis = {
                'total_uncertainty_score': 0.0,
                'uncertainty_sources': {},
                'confidence_intervals': {},
                'propagation_matrix': {}
            }
            
            # Observational uncertainty
            obs_uncertainty = self._calculate_observational_uncertainty(processing_result)
            uncertainty_analysis['uncertainty_sources']['observational'] = obs_uncertainty
            
            # Model uncertainty
            model_uncertainty = await self._calculate_model_uncertainty(features)
            uncertainty_analysis['uncertainty_sources']['model'] = model_uncertainty
            
            # Systematic uncertainty
            systematic_uncertainty = self._calculate_systematic_uncertainty(features)
            uncertainty_analysis['uncertainty_sources']['systematic'] = systematic_uncertainty
            
            # Total uncertainty propagation
            total_uncertainty = np.sqrt(obs_uncertainty**2 + model_uncertainty**2 + systematic_uncertainty**2)
            uncertainty_analysis['total_uncertainty_score'] = float(total_uncertainty)
            
            # Feature-specific confidence intervals
            for feature_name, feature_value in features.items():
                if isinstance(feature_value, (int, float)):
                    ci = self._calculate_confidence_interval(feature_value, total_uncertainty)
                    uncertainty_analysis['confidence_intervals'][feature_name] = ci
            
            return uncertainty_analysis
            
        except Exception as e:
            self.logger.error(f"Comprehensive uncertainty analysis failed: {e}")
            return {'error': str(e), 'total_uncertainty_score': 1.0}
    
