    async def _calculate_feature_importance_scores(self, features, lat, lon):
        """Calculate feature importance scores using domain knowledge and ML models"""
        try:
            importance_scores = {}
            
            # Domain knowledge-based importance
            domain_importance = {
                'velocity_magnitude_mm_yr': 0.9,
                'max_shear_strain_nanostrain_yr': 0.8,
                'station_count': 0.7,
                'spatial_resolution_km': 0.6,
                'temporal_coherence_score': 0.7
            }
            
            # ML-based importance scoring
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    importance_model = await self.model_manager.load_model('feature_importance_scorer')
                    if importance_model:
                        ml_importance = await importance_model.score_features(features)
                        # Combine domain and ML importance
                        for feature, score in ml_importance.items():
                            domain_score = domain_importance.get(feature, 0.5)
                            importance_scores[feature] = 0.6 * score + 0.4 * domain_score
                except Exception as e:
                    self.logger.warning(f"ML importance scoring failed: {e}")
            
            # Use domain knowledge if ML fails
            if not importance_scores:
                importance_scores = domain_importance
            
            return importance_scores
            
        except Exception as e:
            self.logger.error(f"Feature importance calculation failed: {e}")
            return {}
    
    async def _validate_extracted_features(self, features):
        """Validate extracted features using geological constraints and quality checks"""
        try:
            validation_passed = True
            validation_errors = []
            
            # Physical constraint validation
            if 'velocity_magnitude_mm_yr' in features:
                if features['velocity_magnitude_mm_yr'] > 1000:  # > 1 m/year is unlikely
                    validation_errors.append('Velocity magnitude exceeds physical limits')
                    validation_passed = False
            
            if 'max_shear_strain_nanostrain_yr' in features:
                if abs(features['max_shear_strain_nanostrain_yr']) > 10000:  # > 10 microstrain/year
                    validation_errors.append('Strain rate exceeds typical tectonic values')
                    validation_passed = False
            
            # Data quality validation
            if features.get('station_count', 0) < 3:
                validation_errors.append('Insufficient station coverage')
                validation_passed = False
            
            # Uncertainty validation
            if 'total_uncertainty_score' in features.get('uncertainty_analysis', {}):
                if features['uncertainty_analysis']['total_uncertainty_score'] > 0.8:
                    validation_errors.append('High uncertainty in feature extraction')
                    validation_passed = False
            
            features['validation_errors'] = validation_errors
            return validation_passed
            
        except Exception as e:
            self.logger.error(f"Feature validation failed: {e}")
            return False
    
    async def _store_features_in_database(self, features, lat, lon):
        """Store extracted features in model database for training and analysis"""
        try:
            if not hasattr(self, 'model_database') or not self.model_database:
                return
            
            # Prepare feature data for database storage
            feature_record = {
                'location': f'POINT({lon} {lat})',
                'feature_vector': json.dumps(features),
                'extraction_timestamp': features.get('extraction_timestamp'),
                'feature_version': features.get('feature_version', '2.1.0'),
                'quality_score': features.get('quality_metrics', {}).get('overall_quality', 0.5),
                'validation_passed': features.get('validation_passed', False)
            }
            
            # Store in ml_features table
            await self.model_database.store_ml_features(feature_record)
            
        except Exception as e:
            self.logger.error(f"Feature database storage failed: {e}")
    
