    async def _store_velocity_data(self, velocity_field, lat, lon):
        """Store velocity field data in database using real PostgreSQL connection"""
        try:
            # Use real database connection via database manager
            if not hasattr(self, 'database_manager') or not self.database_manager:
                if ADVANCED_DATA_INTEGRATION_AVAILABLE:
                    from .database_integration import DatabaseManager, DatabaseConfig
                    # Initialize database connection if not available
                    db_config = DatabaseConfig(
                        host='localhost',
                        port=5432,
                        database='prometheus_geo',
                        user='prometheus_admin',
                        password='GeoPhys2024!PrometheusDB#'
                    )
                    self.database_manager = DatabaseManager(db_config)
                    await self.database_manager.initialize()
                else:
                    self.logger.warning("Database integration not available, storing to local cache")
                    return await self._store_to_local_cache('velocity', velocity_field, lat, lon)
            
            # Extract velocity components
            velocity_data = velocity_field.get('velocity_mm_yr', {})
            velocity_east = velocity_data.get('east', 0.0)
            velocity_north = velocity_data.get('north', 0.0) 
            velocity_up = velocity_data.get('up', 0.0)
            
            # Calculate derived parameters
            velocity_magnitude = np.sqrt(velocity_east**2 + velocity_north**2 + velocity_up**2)
            azimuth_degrees = np.degrees(np.arctan2(velocity_east, velocity_north)) % 360
            
            # Determine solution quality based on uncertainties
            uncertainty = velocity_field.get('uncertainty_mm_yr', {})
            max_uncertainty = max(uncertainty.get('east', 1.0), 
                                uncertainty.get('north', 1.0), 
                                uncertainty.get('up', 2.0))
            
            if max_uncertainty <= 0.5:
                solution_quality = 'A'
            elif max_uncertainty <= 1.0:
                solution_quality = 'B'
            elif max_uncertainty <= 2.0:
                solution_quality = 'C'
            else:
                solution_quality = 'D'
            
            # Insert into GPS stations table (create station record if needed)
            station_code = f"GPS_{lat:.4f}_{lon:.4f}"
            station_insert_query = """
                INSERT INTO gps_stations 
                (station_code, location, velocity_east_mm_yr, velocity_north_mm_yr, 
                 velocity_up_mm_yr, uncertainty_east_mm_yr, uncertainty_north_mm_yr, 
                 uncertainty_up_mm_yr, solution_quality, last_update)
                VALUES (%s, ST_Point(%s, %s), %s, %s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (station_code) DO UPDATE SET
                velocity_east_mm_yr = EXCLUDED.velocity_east_mm_yr,
                velocity_north_mm_yr = EXCLUDED.velocity_north_mm_yr,
                velocity_up_mm_yr = EXCLUDED.velocity_up_mm_yr,
                uncertainty_east_mm_yr = EXCLUDED.uncertainty_east_mm_yr,
                uncertainty_north_mm_yr = EXCLUDED.uncertainty_north_mm_yr,
                uncertainty_up_mm_yr = EXCLUDED.uncertainty_up_mm_yr,
                solution_quality = EXCLUDED.solution_quality,
                last_update = NOW()
            """
            
            station_params = [
                station_code, lon, lat,
                float(velocity_east), float(velocity_north), float(velocity_up),
                float(uncertainty.get('east', 1.0)), 
                float(uncertainty.get('north', 1.0)),
                float(uncertainty.get('up', 2.0)),
                solution_quality
            ]
            
            # Execute database insertion
            result = await self.database_manager.execute_query(
                station_insert_query, station_params
            )
            
            # Also insert into velocity gradients table if gradient data available
            if 'gradients' in velocity_field:
                await self._store_velocity_gradients(velocity_field['gradients'], lat, lon)
            
            # Log successful storage
            self.logger.info(f"Stored velocity data for {station_code}: "
                           f"VE={velocity_east:.2f}, VN={velocity_north:.2f}, VU={velocity_up:.2f} mm/yr")
            
            return {
                'success': True,
                'station_code': station_code,
                'magnitude_mm_yr': float(velocity_magnitude),
                'azimuth_deg': float(azimuth_degrees),
                'quality': solution_quality
            }
            
        except Exception as e:
            self.logger.error(f"Velocity data storage failed: {e}")
            # Fallback to local storage
            return await self._store_to_local_cache('velocity', velocity_field, lat, lon)
    
