    def _extract_key_findings(self, results):
        """Extract key findings for executive summary"""
        findings = []
        
        # Velocity findings
        if 'velocity_field' in results and not results['velocity_field'].get('error'):
            vel_mag = results['velocity_field'].get('velocity_mm_yr', {}).get('horizontal_magnitude', 0)
            if vel_mag > 10:
                findings.append(f"Significant crustal motion detected: {vel_mag:.1f} mm/yr")
            elif vel_mag < 2:
                findings.append("Minimal crustal motion - stable tectonic setting")
            else:
                findings.append(f"Moderate crustal motion: {vel_mag:.1f} mm/yr")
        
        # Strain findings  
        if 'strain_rate_tensor' in results and not results['strain_rate_tensor'].get('error'):
            principals = results['strain_rate_tensor'].get('principal_strains', {})
            regime = principals.get('strain_regime', 'unknown')
            max_shear = principals.get('max_shear_nanostrain_yr', 0)
            
            if regime != 'stable' and max_shear > 15:
                findings.append(f"Active deformation detected - {regime} regime with {max_shear:.1f} nanostrain/yr maximum shear")
            elif regime == 'stable':
                findings.append("Stable crustal conditions with minimal strain accumulation")
        
        # Anomaly findings
        if 'anomaly_detection' in results:
            anomaly = results['anomaly_detection']
            if anomaly.get('is_anomalous', False):
                anomaly_type = anomaly.get('anomaly_type', 'unknown')
                findings.append(f"Anomalous deformation pattern detected: {anomaly_type}")
        
        # Quality findings
        if 'enhanced_quality_assessment' in results:
            quality = results['enhanced_quality_assessment']
            grade = quality.get('quality_grade', 'Unknown')
            findings.append(f"Data quality assessment: Grade {grade}")
        
        return findings[:5]  # Limit to top 5 findings
    
    def _generate_comprehensive_recommendations(self, results):
        """Generate comprehensive recommendations based on analysis results"""
        recommendations = {
            'immediate_actions': [],
            'monitoring_suggestions': [],
            'data_improvement': [],
            'follow_up_studies': []
        }
        
        # Quality-based recommendations
        if 'enhanced_quality_assessment' in results:
            quality_recs = results['enhanced_quality_assessment'].get('recommendations', [])
            recommendations['data_improvement'].extend(quality_recs)
        
        # Deformation-based recommendations
        if 'deformation_analysis' in results and not results['deformation_analysis'].get('error'):
            deform = results['deformation_analysis']
            hazard_level = deform.get('hazard_assessment', {}).get('hazard_level', 'unknown')
            
            if hazard_level == 'high':
                recommendations['immediate_actions'].append(
                    "Implement enhanced seismic monitoring due to high strain accumulation"
                )
                recommendations['monitoring_suggestions'].append(
                    "Increase GPS observation frequency to daily or sub-daily"
                )
            elif hazard_level == 'moderate':
                recommendations['monitoring_suggestions'].append(
                    "Maintain regular GPS monitoring and establish baseline measurements"
                )
        
        # ML enhancement recommendations
        if results.get('ml_enhancement_applied'):
            if 'anomaly_detection' in results and results['anomaly_detection'].get('is_anomalous'):
                recommendations['follow_up_studies'].append(
                    "Investigate anomalous deformation pattern with targeted field studies"
                )
        
        # General recommendations
        recommendations['monitoring_suggestions'].append(
            "Continue long-term geodetic monitoring to establish velocity trends"
        )
        
        recommendations['follow_up_studies'].append(
            "Correlate geodetic results with seismic and geological data"
        )
        
        return recommendations
    
    async def _fallback_to_cached_data(self, lat, lon, time_range):
        """Fallback to cached/database data when UNAVCO API fails"""
        try:
            if hasattr(self, 'database_integration'):
                # Try to retrieve cached data from database
                cached_result = await self._retrieve_cached_geodetic_data(lat, lon, time_range)
                if cached_result:
                    cached_result['data_source'] = 'cached_database'
                    cached_result['fallback_used'] = True
                    return cached_result
            
            # Final fallback to minimal response
            return {
                'error': 'UNAVCO API unavailable and no cached data found',
                'fallback_used': True,
                'data_source': 'none',
                'location': {'lat': lat, 'lon': lon},
                'timestamp': datetime.utcnow().isoformat(),
                'recommendations': [
                    'Retry analysis when UNAVCO services are available',
                    'Check network connectivity and API authentication',
                    'Consider alternative GPS data sources (IGS, regional networks)'
                ]
            }
            
        except Exception as e:
            self.logger.error(f"Fallback data retrieval failed: {e}")
            return {
                'error': f'Complete data retrieval failure: {str(e)}',
                'fallback_failed': True,
                'location': {'lat': lat, 'lon': lon}
            }
    
    async def _retrieve_cached_geodetic_data(self, lat, lon, time_range):
        """Advanced geodetic data retrieval with multi-tier caching, ML optimization, and real-time integration"""
        try:
            # Import required modules for comprehensive data access
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            from .external_data_connectors import ExternalDataConnectors
            from .model_manager import ModelManager, ModelConfig
            from .edge_computing import EdgeComputingManager
            import asyncpg
            import redis
            import hashlib
            import pickle
            from datetime import datetime, timedelta
            import numpy as np
            
            # Initialize multi-tier caching system
            cache_tiers = {
                'l1_memory': {},  # In-memory cache for ultra-fast access
                'l2_redis': None,  # Redis distributed cache
                'l3_edge': None,   # Edge computing cache nodes
                'l4_database': None  # PostgreSQL/PostGIS persistent storage
            }
            
            # Generate cache key based on spatial-temporal parameters
            cache_key = hashlib.sha256(
                f"{lat:.6f}_{lon:.6f}_{time_range[0].isoformat()}_{time_range[1].isoformat()}".encode()
            ).hexdigest()
            
            # Level 1: Check in-memory cache (microsecond latency)
            if hasattr(self, '_geodetic_cache_memory'):
                if cache_key in self._geodetic_cache_memory:
                    cache_entry = self._geodetic_cache_memory[cache_key]
                    if (datetime.utcnow() - cache_entry['timestamp']).seconds < 300:  # 5-minute TTL
                        self.logger.debug(f"L1 cache hit for geodetic data at {lat}, {lon}")
                        return cache_entry['data']
            else:
                self._geodetic_cache_memory = {}
            
            # Level 2: Check Redis distributed cache (millisecond latency)
            try:
                redis_client = redis.Redis(
                    host=os.environ.get('REDIS_HOST', 'localhost'),
                    port=int(os.environ.get('REDIS_PORT', 6379)),
                    password=os.environ.get('REDIS_PASSWORD', ''),
                    db=int(os.environ.get('REDIS_GEODETIC_DB', 1)),
                    decode_responses=False
                )
                
                redis_key = f"geodetic:cache:{cache_key}"
                cached_data = redis_client.get(redis_key)
                
                if cached_data:
                    geodetic_data = pickle.loads(cached_data)
                    self.logger.debug(f"L2 Redis cache hit for geodetic data at {lat}, {lon}")
                    
                    # Update L1 cache
                    self._geodetic_cache_memory[cache_key] = {
                        'data': geodetic_data,
                        'timestamp': datetime.utcnow()
                    }
                    
                    return geodetic_data
                    
            except Exception as redis_error:
                self.logger.warning(f"Redis cache access failed: {redis_error}")
            
            # Level 3: Check edge computing nodes (low latency for regional data)
            try:
                if hasattr(self, 'edge_computing_manager'):
                    edge_data = await self.edge_computing_manager.query_geodetic_cache(
                        lat, lon, time_range, search_radius_km=50.0
                    )
                    if edge_data:
                        self.logger.debug(f"L3 edge cache hit for geodetic data at {lat}, {lon}")
                        
                        # Propagate to higher cache levels
                        await self._update_cache_levels(cache_key, edge_data, cache_tiers)
                        
                        return edge_data
            except Exception as edge_error:
                self.logger.warning(f"Edge computing cache access failed: {edge_error}")
            
            # Level 4: Query PostgreSQL/PostGIS database with advanced spatial-temporal indexing
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db_manager:
                # Advanced spatial-temporal query with multiple data sources
                query = """
                WITH geodetic_search AS (
                    -- GPS/GNSS station data with time series
                    SELECT 
                        'gps' as data_type,
                        gs.station_id,
                        gs.location,
                        ST_Distance(gs.location, ST_Point(%s, %s)::geography) as distance_m,
                        gts.timestamp,
                        gts.displacement_x,
                        gts.displacement_y,
                        gts.displacement_z,
                        gts.velocity_east_mm_yr,
                        gts.velocity_north_mm_yr,
                        gts.velocity_up_mm_yr,
                        gts.uncertainty_x,
                        gts.uncertainty_y,
                        gts.uncertainty_z,
                        gs.solution_quality,
                        gs.reference_frame
                    FROM gps_stations gs
                    JOIN gps_time_series gts ON gs.station_id = gts.station_id
                    WHERE ST_DWithin(gs.location, ST_Point(%s, %s)::geography, %s)
                    AND gts.timestamp BETWEEN %s AND %s
                    
                    UNION ALL
                    
                    -- InSAR deformation data
                    SELECT 
                        'insar' as data_type,
                        id.acquisition_id as station_id,
                        id.location,
                        ST_Distance(id.location, ST_Point(%s, %s)::geography) as distance_m,
                        id.acquisition_date as timestamp,
                        id.los_displacement as displacement_x,
                        0.0 as displacement_y,
                        id.vertical_displacement as displacement_z,
                        id.los_velocity as velocity_east_mm_yr,
                        0.0 as velocity_north_mm_yr,
                        id.vertical_velocity as velocity_up_mm_yr,
                        id.coherence as uncertainty_x,
                        id.std_deviation as uncertainty_y,
                        id.quality_flag as uncertainty_z,
                        id.processing_method as solution_quality,
                        id.satellite_mission as reference_frame
                    FROM insar_deformation id
                    WHERE ST_DWithin(id.location, ST_Point(%s, %s)::geography, %s)
                    AND id.acquisition_date BETWEEN %s AND %s
                    
                    UNION ALL
                    
                    -- Leveling and gravity measurements
                    SELECT 
                        'leveling' as data_type,
                        lm.benchmark_id as station_id,
                        lm.location,
                        ST_Distance(lm.location, ST_Point(%s, %s)::geography) as distance_m,
                        lm.measurement_date as timestamp,
                        0.0 as displacement_x,
                        0.0 as displacement_y,
                        lm.elevation_change as displacement_z,
                        0.0 as velocity_east_mm_yr,
                        0.0 as velocity_north_mm_yr,
                        lm.vertical_rate as velocity_up_mm_yr,
                        lm.measurement_error as uncertainty_x,
                        lm.adjustment_error as uncertainty_y,
                        lm.network_error as uncertainty_z,
                        lm.survey_quality as solution_quality,
                        lm.datum as reference_frame
                    FROM leveling_measurements lm
                    WHERE ST_DWithin(lm.location, ST_Point(%s, %s)::geography, %s)
                    AND lm.measurement_date BETWEEN %s AND %s
                ),
                ranked_data AS (
                    SELECT *,
                        ROW_NUMBER() OVER (
                            PARTITION BY data_type 
                            ORDER BY distance_m, timestamp DESC
                        ) as rank
                    FROM geodetic_search
                ),
                aggregated_results AS (
                    SELECT 
                        data_type,
                        COUNT(*) as measurement_count,
                        AVG(distance_m) as avg_distance,
                        MIN(distance_m) as min_distance,
                        ARRAY_AGG(
                            jsonb_build_object(
                                'station_id', station_id,
                                'distance_m', distance_m,
                                'timestamp', timestamp,
                                'displacement', ARRAY[displacement_x, displacement_y, displacement_z],
                                'velocity', ARRAY[velocity_east_mm_yr, velocity_north_mm_yr, velocity_up_mm_yr],
                                'uncertainty', ARRAY[uncertainty_x, uncertainty_y, uncertainty_z],
                                'quality', solution_quality,
                                'reference_frame', reference_frame
                            ) ORDER BY distance_m
                        ) FILTER (WHERE rank <= 10) as measurements
                    FROM ranked_data
                    GROUP BY data_type
                )
                SELECT 
                    jsonb_object_agg(data_type, 
                        jsonb_build_object(
                            'count', measurement_count,
                            'avg_distance_m', avg_distance,
                            'min_distance_m', min_distance,
                            'measurements', measurements
                        )
                    ) as geodetic_data,
                    NOW() as query_timestamp
                FROM aggregated_results;
                """
                
                # Execute query with spatial-temporal parameters
                search_radius_m = 50000  # 50 km radius
                results = await db_manager.execute_query(
                    query,
                    lon, lat, lon, lat, search_radius_m, time_range[0], time_range[1],  # GPS
                    lon, lat, lon, lat, search_radius_m, time_range[0], time_range[1],  # InSAR
                    lon, lat, lon, lat, search_radius_m, time_range[0], time_range[1]   # Leveling
                )
                
                if results and results[0]['geodetic_data']:
                    geodetic_data = results[0]['geodetic_data']
                    
                    # Apply ML-based data quality assessment and fusion
                    if hasattr(self, 'model_manager'):
                        geodetic_data = await self._apply_ml_data_fusion(geodetic_data, lat, lon)
                    
                    # Update all cache levels
                    await self._update_cache_levels(cache_key, geodetic_data, cache_tiers)
                    
                    self.logger.info(f"Retrieved geodetic data from database for {lat}, {lon}")
                    return geodetic_data
            
            # If no cached data found, fetch from external sources
            return await self._fetch_real_time_geodetic_data(lat, lon, time_range)
            
        except Exception as e:
            self.logger.error(f"Advanced geodetic data retrieval failed: {e}")
            # Fallback to real-time data fetching
            return await self._fetch_real_time_geodetic_data(lat, lon, time_range)
    
    async def _fetch_real_time_geodetic_data(self, lat, lon, time_range):
        """Fetch real-time geodetic data from external sources"""
        try:
            from .external_data_connectors import ExternalDataConnectors
            
            # Initialize external data connectors
            external_connectors = ExternalDataConnectors({
                'unavco_api_key': os.environ.get('UNAVCO_API_KEY', ''),
                'igs_api_key': os.environ.get('IGS_API_KEY', ''),
                'nasa_earthdata_token': os.environ.get('NASA_EARTHDATA_TOKEN', ''),
                'esa_scihub_credentials': {
                    'username': os.environ.get('ESA_SCIHUB_USER', ''),
                    'password': os.environ.get('ESA_SCIHUB_PASS', '')
                }
            })
            
            # Fetch data from multiple sources in parallel
            import asyncio
            
            tasks = [
                external_connectors.fetch_unavco_gps_data(lat, lon, time_range),
                external_connectors.fetch_igs_gnss_data(lat, lon, time_range),
                external_connectors.fetch_sentinel1_insar(lat, lon, time_range),
                external_connectors.fetch_nasa_gedi_elevation(lat, lon, time_range)
            ]
            
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Combine and process results
            combined_data = {
                'gps': results[0] if not isinstance(results[0], Exception) else None,
                'gnss': results[1] if not isinstance(results[1], Exception) else None,
                'insar': results[2] if not isinstance(results[2], Exception) else None,
                'elevation': results[3] if not isinstance(results[3], Exception) else None,
                'timestamp': datetime.utcnow().isoformat(),
                'location': {'lat': lat, 'lon': lon}
            }
            
            return combined_data
            
        except Exception as e:
            self.logger.error(f"Real-time geodetic data fetch failed: {e}")
            return None
    
    async def _apply_ml_data_fusion(self, geodetic_data, lat, lon):
        """Apply ML-based data fusion and quality enhancement"""
        try:
            from .model_manager import ModelManager, ModelConfig
            import numpy as np
            
            # Initialize ML model for geodetic data fusion
            model_config = ModelConfig(
                model_type='geodetic_fusion',
                hyperparameters={
                    'fusion_algorithm': 'attention_weighted',
                    'quality_threshold': 0.7,
                    'outlier_detection': 'isolation_forest',
                    'uncertainty_propagation': 'monte_carlo'
                }
            )
            
            model_manager = ModelManager(model_config)
            
            # Prepare feature vectors from multi-source data
            features = []
            weights = []
            
            for data_type, data in geodetic_data.items():
                if data and 'measurements' in data:
                    for measurement in data['measurements']:
                        feature_vector = np.array([
                            measurement['displacement'],
                            measurement['velocity'],
                            measurement['uncertainty']
                        ]).flatten()
                        
                        # Calculate quality-based weight
                        quality_weight = self._calculate_measurement_weight(
                            measurement, data_type, lat, lon
                        )
                        
                        features.append(feature_vector)
                        weights.append(quality_weight)
            
            if features:
                # Apply ML fusion model
                fused_result = await model_manager.fuse_geodetic_measurements(
                    np.array(features),
                    np.array(weights),
                    metadata={'location': {'lat': lat, 'lon': lon}}
                )
                
                geodetic_data['ml_fusion'] = fused_result
                geodetic_data['fusion_confidence'] = fused_result.get('confidence', 0.0)
            
            return geodetic_data
            
        except Exception as e:
            self.logger.warning(f"ML data fusion failed: {e}")
            return geodetic_data
    
    def _calculate_measurement_weight(self, measurement, data_type, lat, lon):
        """Calculate quality-based weight for measurement fusion"""
        try:
            # Base weight by data type
            type_weights = {
                'gps': 0.9,
                'gnss': 0.85,
                'insar': 0.8,
                'leveling': 0.95,
                'gravity': 0.75
            }
            
            base_weight = type_weights.get(data_type, 0.5)
            
            # Adjust by distance (closer is better)
            distance_m = measurement.get('distance_m', 50000)
            distance_weight = np.exp(-distance_m / 10000)  # Exponential decay
            
            # Adjust by uncertainty
            uncertainties = measurement.get('uncertainty', [1.0, 1.0, 1.0])
            avg_uncertainty = np.mean([u for u in uncertainties if u is not None])
            uncertainty_weight = 1.0 / (1.0 + avg_uncertainty)
            
            # Adjust by data freshness
            timestamp = measurement.get('timestamp')
            if timestamp:
                age_days = (datetime.utcnow() - timestamp).days
                freshness_weight = np.exp(-age_days / 30)  # 30-day half-life
            else:
                freshness_weight = 0.5
            
            # Combine weights
            final_weight = base_weight * distance_weight * uncertainty_weight * freshness_weight
            
            return min(1.0, max(0.0, final_weight))
            
        except Exception:
            return 0.5
    
    async def _update_cache_levels(self, cache_key, data, cache_tiers):
        """Update all cache levels with new data"""
        try:
            import pickle
            import redis
            from datetime import datetime, timedelta
            
            # Update L1 memory cache
            self._geodetic_cache_memory[cache_key] = {
                'data': data,
                'timestamp': datetime.utcnow()
            }
            
            # Implement LRU eviction if cache is too large
            if len(self._geodetic_cache_memory) > 1000:
                # Remove oldest entries
                sorted_keys = sorted(
                    self._geodetic_cache_memory.keys(),
                    key=lambda k: self._geodetic_cache_memory[k]['timestamp']
                )
                for old_key in sorted_keys[:100]:
                    del self._geodetic_cache_memory[old_key]
            
            # Update L2 Redis cache
            try:
                redis_client = redis.Redis(
                    host=os.environ.get('REDIS_HOST', 'localhost'),
                    port=int(os.environ.get('REDIS_PORT', 6379)),
                    password=os.environ.get('REDIS_PASSWORD', ''),
                    db=int(os.environ.get('REDIS_GEODETIC_DB', 1)),
                    decode_responses=False
                )
                
                redis_key = f"geodetic:cache:{cache_key}"
                redis_client.setex(
                    redis_key,
                    timedelta(hours=6),  # 6-hour TTL
                    pickle.dumps(data)
                )
                
                # Also update geospatial index in Redis
                if 'location' in data:
                    lat, lon = data['location']['lat'], data['location']['lon']
                    redis_client.geoadd(
                        'geodetic:spatial:index',
                        lon, lat, cache_key
                    )
                    
            except Exception as redis_error:
                self.logger.warning(f"Redis cache update failed: {redis_error}")
            
            # Update L3 edge computing cache
            if hasattr(self, 'edge_computing_manager'):
                await self.edge_computing_manager.update_geodetic_cache(
                    cache_key, data
                )
            
            # Store in L4 database for persistence
            await self._store_geodetic_cache_database(cache_key, data)
            
        except Exception as e:
            self.logger.warning(f"Cache update failed: {e}")
    
    async def _store_geodetic_cache_database(self, cache_key, data):
        """Store geodetic data in database with spatial indexing"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            import json
            
            db_config = DatabaseConfig(
                host=os.environ.get('POSTGRES_HOST', 'localhost'),
                port=int(os.environ.get('POSTGRES_PORT', 5432)),
                database=os.environ.get('POSTGRES_DB', 'prometheus_geo'),
                username=os.environ.get('POSTGRES_USER', 'prometheus_admin'),
                password=os.environ.get('POSTGRES_PASSWORD', 'GeoPhys2024!PrometheusDB#')
            )
            
            async with PostgreSQLGISManager(db_config) as db_manager:
                # Create table if not exists
                await db_manager.execute_query("""
                    CREATE TABLE IF NOT EXISTS geodetic_analysis_cache (
                        cache_key VARCHAR(64) PRIMARY KEY,
                        location GEOGRAPHY(POINTZ, 4326),
                        analysis_timestamp TIMESTAMPTZ,
                        data_json JSONB,
                        data_types TEXT[],
                        measurement_count INTEGER,
                        fusion_confidence REAL,
                        created_at TIMESTAMPTZ DEFAULT NOW(),
                        updated_at TIMESTAMPTZ DEFAULT NOW(),
                        access_count INTEGER DEFAULT 1,
                        last_accessed TIMESTAMPTZ DEFAULT NOW()
                    );
                    
                    CREATE INDEX IF NOT EXISTS idx_geodetic_cache_location 
                    ON geodetic_analysis_cache USING GIST (location);
                    
                    CREATE INDEX IF NOT EXISTS idx_geodetic_cache_timestamp 
                    ON geodetic_analysis_cache (analysis_timestamp DESC);
                    
                    CREATE INDEX IF NOT EXISTS idx_geodetic_cache_confidence 
                    ON geodetic_analysis_cache (fusion_confidence DESC);
                """)
                
                # Insert or update cache entry
                location = data.get('location', {})
                lat = location.get('lat', 0)
                lon = location.get('lon', 0)
                
                # Extract data types and count
                data_types = list(data.keys())
                measurement_count = sum(
                    len(d.get('measurements', [])) 
                    for d in data.values() 
                    if isinstance(d, dict)
                )
                
                await db_manager.execute_query("""
                    INSERT INTO geodetic_analysis_cache (
                        cache_key, location, analysis_timestamp, data_json,
                        data_types, measurement_count, fusion_confidence
                    ) VALUES (
                        %s, ST_Point(%s, %s)::geography, %s, %s, %s, %s, %s
                    )
                    ON CONFLICT (cache_key) DO UPDATE SET
                        data_json = EXCLUDED.data_json,
                        updated_at = NOW(),
                        access_count = geodetic_analysis_cache.access_count + 1,
                        last_accessed = NOW(),
                        fusion_confidence = EXCLUDED.fusion_confidence;
                """, cache_key, lon, lat, datetime.utcnow(), json.dumps(data),
                    data_types, measurement_count, data.get('fusion_confidence', 0.0))
                
        except Exception as e:
            self.logger.warning(f"Database cache storage failed: {e}")
    
    # Comprehensive validation helper methods
    
    def _validate_stress_tensor_physics(self, stress, depth, temperature, pressure):
        """Validate stress tensor against advanced physical principles with real calculations"""
        try:
            import numpy as np
            from typing import Dict, Any
            
            # Convert stress to proper tensor format
            if not isinstance(stress, np.ndarray):
                stress = np.asarray(stress)
            
            # Ensure proper tensor format (3x3 or 6-component)
            if stress.size == 6:
                # Convert Voigt notation to full tensor
                stress_tensor = np.array([
                    [stress[0], stress[3], stress[4]],
                    [stress[3], stress[1], stress[5]],
                    [stress[4], stress[5], stress[2]]
                ])
            elif stress.shape == (3, 3):
                stress_tensor = stress
            else:
                # Fallback for other formats
                stress_tensor = np.diag(stress.flatten()[:3]) if stress.size >= 3 else np.eye(3) * stress.flatten()[0]
            
            analysis = {
                'tensor_properties': {},
                'physical_constraints': {},
                'geological_context': {},
                'thermomechanical_coupling': {},
                'validation_details': {}
            }
            
            # 1. TENSOR MATHEMATICAL PROPERTIES
            eigenvalues = np.linalg.eigvals(stress_tensor)
            eigenvalues = np.real(eigenvalues)  # Take real part
            principal_stresses = np.sort(eigenvalues)[::-1]  # σ1 ≥ σ2 ≥ σ3
            
            analysis['tensor_properties'] = {
                'principal_stresses': principal_stresses.tolist(),
                'maximum_shear_stress': 0.5 * (principal_stresses[0] - principal_stresses[2]),
                'mean_stress': np.mean(principal_stresses),
                'deviatoric_stress_invariant': np.sqrt(0.5 * np.sum((stress_tensor - np.eye(3) * np.trace(stress_tensor)/3)**2)),
                'von_mises_stress': np.sqrt(0.5 * ((principal_stresses[0] - principal_stresses[1])**2 + 
                                                   (principal_stresses[1] - principal_stresses[2])**2 + 
                                                   (principal_stresses[2] - principal_stresses[0])**2)),
                'determinant': np.linalg.det(stress_tensor),
                'trace': np.trace(stress_tensor),
                'is_positive_definite': bool(np.all(eigenvalues > 1e-12))
            }
            
            # 2. DEPTH-DEPENDENT VALIDATION
            depth_m = max(0, depth)
            lithostatic_pressure = 2700 * 9.81 * depth_m  # Assuming average crustal density
            expected_vertical_stress = lithostatic_pressure
            
            # Tectonic stress ratio validation (typical ranges)
            k0_normal = 0.5  # At-rest earth pressure coefficient
            k0_range = (0.3, 1.5)  # Geological range
            
            vertical_stress = principal_stresses[2] if depth_m > 0 else principal_stresses[0]
            horizontal_stresses = principal_stresses[:2] if depth_m > 0 else principal_stresses[1:]
            
            analysis['geological_context'] = {
                'expected_vertical_stress_MPa': expected_vertical_stress / 1e6,
                'actual_vertical_stress_MPa': vertical_stress / 1e6,
                'stress_gradient_consistency': abs(vertical_stress - expected_vertical_stress) / max(expected_vertical_stress, 1e6),
                'horizontal_to_vertical_ratios': [h / max(abs(vertical_stress), 1e6) for h in horizontal_stresses],
                'tectonic_regime_indicator': 'compressional' if all(h > vertical_stress for h in horizontal_stresses) else 
                                           'extensional' if all(h < vertical_stress for h in horizontal_stresses) else 'strike_slip'
            }
            
            # 3. THERMOMECHANICAL COUPLING VALIDATION
            # Temperature-dependent elastic properties
            reference_temp = 298.15  # K
            temp_factor = 1.0 - 5e-4 * (temperature - reference_temp)  # Thermal softening
            expected_elastic_modulus = 70e9 * temp_factor  # GPa, temperature corrected
            
            # Pressure-dependent properties
            pressure_factor = 1.0 + 1e-11 * pressure  # Pressure hardening
            corrected_modulus = expected_elastic_modulus * pressure_factor
            
            # Thermal stress estimation
            thermal_expansion = 3e-5  # 1/K, typical for rocks
            thermal_stress = corrected_modulus * thermal_expansion * (temperature - reference_temp)
            
            analysis['thermomechanical_coupling'] = {
                'temperature_correction_factor': temp_factor,
                'pressure_correction_factor': pressure_factor,
                'estimated_thermal_stress_MPa': thermal_stress / 1e6,
                'elastic_modulus_corrected_GPa': corrected_modulus / 1e9,
                'thermal_expansion_strain': thermal_expansion * (temperature - reference_temp)
            }
            
            # 4. PHYSICAL CONSTRAINT VALIDATION
            constraints_satisfied = 0
            total_constraints = 8
            
            # Constraint 1: Stress magnitudes within geological bounds (1 kPa to 10 GPa)
            stress_magnitudes = np.abs(principal_stresses)
            reasonable_stress_range = np.all((stress_magnitudes >= 1e3) & (stress_magnitudes <= 10e9))
            if reasonable_stress_range:
                constraints_satisfied += 1
            
            # Constraint 2: Tensor symmetry (should be symmetric for static equilibrium)
            symmetry_error = np.max(np.abs(stress_tensor - stress_tensor.T))
            is_symmetric = symmetry_error < 1e-10 * np.max(np.abs(stress_tensor))
            if is_symmetric:
                constraints_satisfied += 1
            
            # Constraint 3: Finite and real eigenvalues
            finite_eigenvalues = np.all(np.isfinite(eigenvalues))
            if finite_eigenvalues:
                constraints_satisfied += 1
            
            # Constraint 4: Depth consistency
            depth_consistent = True
            if depth_m > 100:  # Only check for significant depths
                expected_min_stress = 0.3 * lithostatic_pressure
                depth_consistent = np.min(np.abs(principal_stresses)) >= expected_min_stress
            if depth_consistent:
                constraints_satisfied += 1
            
            # Constraint 5: Temperature consistency
            temp_reasonable = 200 <= temperature <= 2000  # Reasonable geological range in K
            if temp_reasonable:
                constraints_satisfied += 1
            
            # Constraint 6: Pressure consistency  
            pressure_reasonable = 1e3 <= pressure <= 50e9  # 1 kPa to 50 GPa
            if pressure_reasonable:
                constraints_satisfied += 1
            
            # Constraint 7: Mohr-Coulomb failure criterion check
            friction_angle = np.radians(30)  # Typical internal friction angle
            cohesion = 10e6  # Pa
            max_shear = analysis['tensor_properties']['maximum_shear_stress']
            normal_stress = analysis['tensor_properties']['mean_stress']
            mohr_coulomb_satisfied = max_shear <= cohesion + normal_stress * np.tan(friction_angle)
            if mohr_coulomb_satisfied:
                constraints_satisfied += 1
            
            # Constraint 8: Deviatoric stress reasonableness
            deviatoric_reasonable = analysis['tensor_properties']['deviatoric_stress_invariant'] < 5e9  # < 5 GPa
            if deviatoric_reasonable:
                constraints_satisfied += 1
            
            analysis['physical_constraints'] = {
                'total_constraints': total_constraints,
                'constraints_satisfied': constraints_satisfied,
                'constraint_details': {
                    'stress_magnitude_reasonable': reasonable_stress_range,
                    'tensor_symmetric': is_symmetric,
                    'eigenvalues_finite': finite_eigenvalues,
                    'depth_consistent': depth_consistent,
                    'temperature_reasonable': temp_reasonable,
                    'pressure_reasonable': pressure_reasonable,
                    'mohr_coulomb_satisfied': mohr_coulomb_satisfied,
                    'deviatoric_stress_reasonable': deviatoric_reasonable
                },
                'symmetry_error': float(symmetry_error),
                'stress_magnitude_range_Pa': [float(np.min(stress_magnitudes)), float(np.max(stress_magnitudes))]
            }
            
            # 5. INTEGRATE WITH EXTERNAL VALIDATION
            external_validation_score = 0.0
            if hasattr(self, 'external_data_connectors') and self.external_data_connectors:
                try:
                    # Use rock properties database for validation
                    from .geological_statistics import GeologicalStatistics
                    if hasattr(self, 'geological_stats') or hasattr(self, '_geological_stats'):
                        geo_stats = getattr(self, 'geological_stats', getattr(self, '_geological_stats', None))
                        if geo_stats:
                            stat_validation = geo_stats.validate_stress_statistics(stress_tensor, depth_m, temperature)
                            external_validation_score = stat_validation.get('confidence', 0.5)
                except:
                    external_validation_score = 0.5
            
            # 6. CALCULATE FINAL SCORE
            base_score = constraints_satisfied / total_constraints
            
            # Bonus for exceptional physical consistency
            bonus_factors = 0.0
            if analysis['tensor_properties']['is_positive_definite']:
                bonus_factors += 0.05
            if symmetry_error < 1e-12 * np.max(np.abs(stress_tensor)):
                bonus_factors += 0.05
            if 0.2 <= analysis['geological_context']['horizontal_to_vertical_ratios'][0] <= 3.0:
                bonus_factors += 0.05
            
            # Integration with thermodynamic consistency
            thermodynamic_bonus = 0.0
            if hasattr(self, 'thermodynamic_engine') or hasattr(self, '_thermo_engine'):
                thermo_engine = getattr(self, 'thermodynamic_engine', getattr(self, '_thermo_engine', None))
                if thermo_engine:
                    try:
                        # Validate thermodynamic consistency
                        thermo_result = thermo_engine.validate_stress_thermodynamics(
                            stress_tensor, temperature, pressure
                        )
                        thermodynamic_bonus = 0.1 * thermo_result.get('consistency_score', 0.5)
                    except:
                        thermodynamic_bonus = 0.02
            
            final_score = min(1.0, base_score + bonus_factors + thermodynamic_bonus + 0.1 * external_validation_score)
            
            analysis['validation_details'] = {
                'base_score': base_score,
                'bonus_factors': bonus_factors,
                'thermodynamic_bonus': thermodynamic_bonus,
                'external_validation_contribution': 0.1 * external_validation_score,
                'methodology': 'comprehensive_tensor_physics_validation_v3.0'
            }
            
            return {
                'score': float(final_score),
                'analysis': analysis,
                'validation_type': 'advanced_physics_validation',
                'confidence': min(0.95, 0.7 + 0.25 * final_score)
            }
            
        except Exception as e:
            self.logger.error(f"Advanced stress tensor physics validation failed: {e}")
            # Fallback to basic validation
            return {
                'score': 0.6,
                'analysis': f'validation_error_{str(e)[:50]}',
                'validation_type': 'fallback_validation',
                'error': str(e)
            }
    
