    def _process_stress_tensor(self, stress):
        """Process and validate stress tensor input"""
        try:
            stress_array = np.asarray(stress)
            
            if stress_array.ndim == 0:
                # Scalar stress - convert to 3D stress tensor
                return np.diag([float(stress_array), float(stress_array), float(stress_array)])
            elif stress_array.size == 3:
                # Principal stresses
                return np.diag(stress_array)
            elif stress_array.size == 6:
                # Voigt notation: [σ11, σ22, σ33, σ23, σ13, σ12]
                tensor = np.zeros((3, 3))
                tensor[0, 0], tensor[1, 1], tensor[2, 2] = stress_array[0], stress_array[1], stress_array[2]
                tensor[1, 2] = tensor[2, 1] = stress_array[3]
                tensor[0, 2] = tensor[2, 0] = stress_array[4]
                tensor[0, 1] = tensor[1, 0] = stress_array[5]
                return tensor
            elif stress_array.shape == (3, 3):
                # Full tensor
                return stress_array
            else:
                # Fallback to isotropic
                mean_stress = np.mean(stress_array) if stress_array.size > 1 else float(stress_array)
                return np.diag([mean_stress, mean_stress, mean_stress])
                
        except Exception as e:
            self.logger.warning(f"Stress tensor processing failed: {e}")
            # Fallback to isotropic stress
            mean_stress = 1e6  # 1 MPa default
            return np.diag([mean_stress, mean_stress, mean_stress])
    
    def _calculate_advanced_elastic_energy(self, stress_tensor, temperature, pressure, db_integration, external_connector):
        """Calculate elastic strain energy using real material properties from database"""
        try:
            elastic_analysis = {
                'strain_energy_density': 0.0,
                'elastic_constants': {},
                'temperature_corrections': {},
                'pressure_corrections': {},
                'anisotropy_factor': 1.0,
                'confidence': 0.5
            }
            
            # Query rock mechanical properties from database
            if db_integration:
                rock_properties = db_integration.execute_query("""
                    SELECT elastic_modulus_gpa, poisson_ratio, thermal_expansion_per_k,
                           unconfined_compressive_strength_mpa, tensile_strength_mpa
                    FROM rock_mechanical_properties 
                    WHERE data_quality_grade IN ('A', 'B')
                    AND temperature_c BETWEEN %s AND %s
                    AND ABS(pressure_mpa - %s) < %s
                    ORDER BY data_quality_grade ASC, ABS(temperature_c - %s) ASC
                    LIMIT 10
                """, (temperature - 273.15 - 50, temperature - 273.15 + 50, 
                      pressure/1e6, pressure/1e6 * 0.5, temperature - 273.15))
                
                if rock_properties:
                    # Use weighted average of database properties
                    weights = [1.0 if row[0] == 'A' else 0.7 for row in rock_properties]
                    elastic_modulus = np.average([row[0] * 1e9 for row in rock_properties], weights=weights)
                    poisson_ratio = np.average([row[1] for row in rock_properties], weights=weights)
                    thermal_expansion = np.average([row[2] for row in rock_properties], weights=weights)
                    elastic_analysis['confidence'] = 0.9
                else:
                    # Literature values with external validation
                    if external_connector:
                        lit_props = external_connector.query_literature_rock_properties(
                            temperature=temperature, pressure=pressure
                        )
                        elastic_modulus = lit_props.get('elastic_modulus', 70e9)
                        poisson_ratio = lit_props.get('poisson_ratio', 0.25)
                        thermal_expansion = lit_props.get('thermal_expansion', 3e-5)
                        elastic_analysis['confidence'] = 0.6
                    else:
                        # Fallback values with temperature/pressure corrections
                        elastic_modulus = self._calculate_temperature_dependent_elastic_modulus(temperature)
                        poisson_ratio = self._calculate_pressure_dependent_poisson_ratio(pressure)
                        thermal_expansion = 3e-5
                        elastic_analysis['confidence'] = 0.4
            else:
                elastic_modulus = 70e9  # Pa
                poisson_ratio = 0.25
                thermal_expansion = 3e-5
                elastic_analysis['confidence'] = 0.3
            
            # Calculate strain from stress using full elastic tensor
            strain_tensor = self._calculate_strain_from_stress(stress_tensor, elastic_modulus, poisson_ratio)
            
            # Strain energy density calculation
            strain_energy_density = 0.5 * np.sum(stress_tensor * strain_tensor)
            
            # Temperature corrections
            reference_temp = 298.15
            thermal_strain = thermal_expansion * (temperature - reference_temp)
            thermal_stress_correction = elastic_modulus * thermal_strain
            
            # Apply corrections
            corrected_energy = strain_energy_density + 0.5 * thermal_stress_correction**2 / elastic_modulus
            
            elastic_analysis.update({
                'strain_energy_density': float(corrected_energy),
                'elastic_constants': {
                    'elastic_modulus': float(elastic_modulus),
                    'poisson_ratio': float(poisson_ratio),
                    'thermal_expansion': float(thermal_expansion)
                },
                'temperature_corrections': {
                    'thermal_strain': float(thermal_strain),
                    'thermal_stress_correction': float(thermal_stress_correction)
                },
                'strain_tensor': strain_tensor.tolist(),
                'stress_invariants': {
                    'I1': float(np.trace(stress_tensor)),
                    'J2': float(0.5 * np.sum((stress_tensor - np.trace(stress_tensor)/3 * np.eye(3))**2)),
                    'J3': float(np.linalg.det(stress_tensor - np.trace(stress_tensor)/3 * np.eye(3)))
                }
            })
            
            return elastic_analysis
            
        except Exception as e:
            self.logger.error(f"Advanced elastic energy calculation failed: {e}")
            return {
                'strain_energy_density': 1e5,  # Fallback value
                'confidence': 0.2,
                'error': str(e)
            }
    
    def _calculate_thermodynamic_thermal_energy(self, temperature, pressure, effects, thermo_engine):
        """Calculate thermal energy using ThermodynamicEngine"""
        try:
            # Get composition from effects or use default rock composition
            composition = effects.get('composition', {
                'SiO2': 60.0, 'Al2O3': 15.0, 'Fe2O3': 8.0, 'MgO': 6.0,
                'CaO': 5.0, 'Na2O': 3.0, 'K2O': 2.5, 'TiO2': 0.5
            })
            
            # Calculate thermodynamic properties
            thermo_props = thermo_engine.calculate_thermodynamic_properties(
                composition, temperature, pressure
            )
            
            # Enthalpy calculation with phase transitions
            enthalpy = thermo_props.get('enthalpy', 0.0)
            
            # Heat capacity integration
            heat_capacity = thermo_props.get('heat_capacity', 1000.0)
            reference_temp = 298.15
            sensible_heat = heat_capacity * (temperature - reference_temp)
            
            # Phase transition enthalpies
            phase_transition_enthalpy = 0.0
            if 'phase_transitions' in thermo_props:
                for transition in thermo_props['phase_transitions']:
                    if transition['temperature'] <= temperature:
                        phase_transition_enthalpy += transition.get('enthalpy_change', 0.0)
            
            total_thermal_energy = sensible_heat + phase_transition_enthalpy + enthalpy
            
            return {
                'thermal_energy_density': float(total_thermal_energy),
                'sensible_heat': float(sensible_heat),
                'phase_transition_enthalpy': float(phase_transition_enthalpy),
                'enthalpy': float(enthalpy),
                'heat_capacity': float(heat_capacity),
                'thermodynamic_properties': thermo_props,
                'confidence': 0.9
            }
            
        except Exception as e:
            self.logger.error(f"Thermodynamic thermal energy calculation failed: {e}")
            return self._fallback_thermal_energy_calculation(temperature, pressure)
    
    def _calculate_database_thermal_energy(self, temperature, pressure, db_integration):
        """Calculate thermal energy using database thermal properties"""
        try:
            if not db_integration:
                return self._fallback_thermal_energy_calculation(temperature, pressure)
            
            # Query thermal properties from database
            thermal_props = db_integration.execute_query("""
                SELECT thermal_conductivity_w_m_k, porosity, lithology
                FROM rock_mechanical_properties 
                WHERE ABS(temperature_c - %s) < 100
                AND data_quality_grade IN ('A', 'B', 'C')
                LIMIT 5
            """, (temperature - 273.15,))
            
            if thermal_props:
                # Calculate average thermal properties
                thermal_conductivity = np.mean([row[0] for row in thermal_props])
                porosity = np.mean([row[1] for row in thermal_props])
                
                # Thermal energy calculation
                density = 2700 * (1 - porosity)  # kg/m³
                heat_capacity = self._estimate_heat_capacity_from_lithology(thermal_props[0][2])
                
                reference_temp = 298.15
                thermal_energy_density = density * heat_capacity * (temperature - reference_temp)
                
                return {
                    'thermal_energy_density': float(thermal_energy_density),
                    'thermal_conductivity': float(thermal_conductivity),
                    'density': float(density),
                    'heat_capacity': float(heat_capacity),
                    'porosity': float(porosity),
                    'confidence': 0.7
                }
            else:
                return self._fallback_thermal_energy_calculation(temperature, pressure)
                
        except Exception as e:
            self.logger.error(f"Database thermal energy calculation failed: {e}")
            return self._fallback_thermal_energy_calculation(temperature, pressure)
    
    def _calculate_real_time_kinetic_energy(self, stress_tensor, effects, external_connector):
        """Calculate kinetic energy from real-time deformation and seismic data"""
        try:
            kinetic_analysis = {
                'kinetic_energy_density': 0.0,
                'deformation_rate': 0.0,
                'seismic_velocity': 0.0,
                'confidence': 0.5
            }
            
            # Get deformation rate from effects
            deformation_rate = effects.get('deformation_rate', 0.0)  # strain/s
            
            # Query real-time seismic data if available
            if external_connector:
                try:
                    # Get latest seismic activity
                    location = effects.get('location', {'lat': 0, 'lon': 0})
                    seismic_data = external_connector.query_usgs_earthquake_data(
                        latitude=location['lat'],
                        longitude=location['lon'],
                        radius_km=50,
                        time_window_hours=24
                    )
                    
                    if seismic_data and seismic_data['features']:
                        # Calculate representative seismic velocity from recent events
                        magnitudes = [event['properties']['mag'] for event in seismic_data['features'] if event['properties']['mag']]
                        if magnitudes:
                            avg_magnitude = np.mean(magnitudes)
                            # Convert magnitude to velocity (simplified relationship)
                            seismic_velocity = 10**(avg_magnitude - 3)  # m/s
                            kinetic_analysis['seismic_velocity'] = seismic_velocity
                            kinetic_analysis['confidence'] = 0.8
                except Exception as e:
                    self.logger.debug(f"Seismic data query failed: {e}")
            
            # Estimate material velocity from stress state
            stress_magnitude = np.sqrt(np.sum(stress_tensor**2))
            density = effects.get('density', 2700)  # kg/m³
            
            # Stress wave velocity estimation
            if stress_magnitude > 0:
                elastic_modulus = effects.get('elastic_modulus', 70e9)
                p_wave_velocity = np.sqrt(elastic_modulus / density)
                material_velocity = min(p_wave_velocity * 0.1, 100)  # m/s, capped
            else:
                material_velocity = 0.001  # m/s, minimal velocity
            
            # Total kinetic energy density
            total_velocity = kinetic_analysis['seismic_velocity'] + material_velocity + deformation_rate * 1000
            kinetic_energy_density = 0.5 * density * total_velocity**2
            
            kinetic_analysis.update({
                'kinetic_energy_density': float(kinetic_energy_density),
                'deformation_rate': float(deformation_rate),
                'material_velocity': float(material_velocity),
                'total_velocity': float(total_velocity),
                'density': float(density)
            })
            
            return kinetic_analysis
            
        except Exception as e:
            self.logger.error(f"Real-time kinetic energy calculation failed: {e}")
            return {
                'kinetic_energy_density': 1e3,  # Fallback
                'confidence': 0.2,
                'error': str(e)
            }
    
    def _calculate_gravitational_potential_energy(self, pressure, external_connector, db_integration):
        """Calculate gravitational potential energy using topographic data"""
        try:
            gravitational_analysis = {
                'potential_energy_density': 0.0,
                'elevation': 0.0,
                'gravity_acceleration': 9.81,
                'confidence': 0.5
            }
            
            # Estimate depth from pressure
            density = 2700  # kg/m³
            g = 9.81  # m/s²
            depth = pressure / (density * g)
            
            # Get real topographic data if available
            if external_connector:
                try:
                    location = getattr(self, '_current_location', {'lat': 0, 'lon': 0})
                    topo_data = external_connector.query_nasa_earth_data(
                        dataset='SRTM',
                        latitude=location['lat'],
                        longitude=location['lon']
                    )
                    
                    if topo_data:
                        elevation = topo_data.get('elevation', 0)  # m
                        gravitational_analysis['elevation'] = elevation
                        gravitational_analysis['confidence'] = 0.8
                    else:
                        elevation = 0  # Sea level assumption
                except Exception as e:
                    self.logger.debug(f"Topographic data query failed: {e}")
                    elevation = 0
            else:
                elevation = 0
            
            # Calculate gravitational potential energy
            # Reference level at center of mass
            reference_depth = depth / 2
            potential_energy_density = density * g * (elevation - reference_depth)
            
            gravitational_analysis.update({
                'potential_energy_density': float(potential_energy_density),
                'depth': float(depth),
                'reference_depth': float(reference_depth),
                'density': float(density)
            })
            
            return gravitational_analysis
            
        except Exception as e:
            self.logger.error(f"Gravitational potential energy calculation failed: {e}")
            return {
                'potential_energy_density': 1e4,  # Fallback
                'confidence': 0.2,
                'error': str(e)
            }
    
    def _calculate_chemical_potential_energy(self, temperature, pressure, effects, thermo_engine, db_integration):
        """Calculate chemical potential energy from phase transitions and reactions"""
        try:
            chemical_analysis = {
                'chemical_energy_density': 0.0,
                'phase_transitions': [],
                'reaction_enthalpies': [],
                'confidence': 0.5
            }
            
            if thermo_engine:
                # Get composition
                composition = effects.get('composition', {
                    'SiO2': 60.0, 'Al2O3': 15.0, 'Fe2O3': 8.0, 'MgO': 6.0
                })
                
                # Calculate chemical potentials
                chemical_potentials = thermo_engine.calculate_chemical_potentials(
                    composition, temperature, pressure
                )
                
                # Phase equilibria analysis
                phase_equilibria = thermo_engine.solve_multicomponent_equilibrium(
                    composition, temperature, pressure
                )
                
                # Sum chemical potential contributions
                total_chemical_energy = sum(chemical_potentials.values()) if chemical_potentials else 0.0
                
                chemical_analysis.update({
                    'chemical_energy_density': float(total_chemical_energy),
                    'chemical_potentials': chemical_potentials,
                    'phase_equilibria': phase_equilibria,
                    'confidence': 0.9
                })
            else:
                # Database-based estimation
                if db_integration:
                    try:
                        # Query volcanic chamber data for chemical information
                        volcanic_data = db_integration.execute_query("""
                            SELECT melt_fraction, volatile_content, temperature_c
                            FROM volcanic_chambers
                            WHERE ABS(temperature_c - %s) < 200
                            AND chamber_volume_km3 > 0.1
                            LIMIT 5
                        """, (temperature - 273.15,))
                        
                        if volcanic_data:
                            avg_melt_fraction = np.mean([row[0] for row in volcanic_data])
                            # Estimate chemical energy from melt fraction
                            latent_heat_fusion = 400000  # J/kg
                            density = 2700  # kg/m³
                            chemical_energy = avg_melt_fraction * latent_heat_fusion * density
                            chemical_analysis['confidence'] = 0.6
                        else:
                            chemical_energy = 1e4  # Minimal chemical energy
                            chemical_analysis['confidence'] = 0.3
                    except Exception:
                        chemical_energy = 1e4
                        chemical_analysis['confidence'] = 0.3
                else:
                    chemical_energy = 1e4
                    chemical_analysis['confidence'] = 0.2
                
                chemical_analysis['chemical_energy_density'] = float(chemical_energy)
            
            return chemical_analysis
            
        except Exception as e:
            self.logger.error(f"Chemical potential energy calculation failed: {e}")
            return {
                'chemical_energy_density': 1e4,  # Fallback
                'confidence': 0.2,
                'error': str(e)
            }
    
    def _calculate_dissipative_energy(self, stress_tensor, temperature, pressure, thermo_engine):
        """Calculate energy dissipated through non-conservative processes"""
        try:
            dissipative_analysis = {
                'dissipative_energy_density': 0.0,
                'viscous_dissipation': 0.0,
                'plastic_dissipation': 0.0,
                'thermal_dissipation': 0.0,
                'confidence': 0.6
            }
            
            # Viscous dissipation
            if thermo_engine:
                try:
                    viscosity = thermo_engine.calculate_viscosity(temperature, pressure)
                    strain_rate = 1e-15  # Typical geological strain rate (1/s)
                    
                    # Viscous dissipation rate
                    stress_magnitude = np.sqrt(np.sum(stress_tensor**2))
                    viscous_dissipation = stress_magnitude * strain_rate
                    
                    dissipative_analysis['viscous_dissipation'] = float(viscous_dissipation)
                    dissipative_analysis['viscosity'] = float(viscosity)
                except Exception:
                    viscous_dissipation = 1e2
            else:
                viscous_dissipation = 1e2
            
            # Plastic dissipation (yielding)
            yield_strength = 100e6  # Pa, typical rock yield strength
            stress_magnitude = np.sqrt(np.sum(stress_tensor**2))
            
            if stress_magnitude > yield_strength:
                plastic_strain = (stress_magnitude - yield_strength) / 70e9  # Elastic modulus
                plastic_dissipation = yield_strength * plastic_strain
            else:
                plastic_dissipation = 0.0
            
            # Thermal dissipation (heat conduction losses)
            thermal_conductivity = 2.5  # W/(m·K)
            temperature_gradient = 0.025  # K/m typical geothermal gradient
            thermal_dissipation = thermal_conductivity * temperature_gradient * temperature / 1000  # Normalized
            
            total_dissipative_energy = viscous_dissipation + plastic_dissipation + thermal_dissipation
            
            dissipative_analysis.update({
                'dissipative_energy_density': float(total_dissipative_energy),
                'plastic_dissipation': float(plastic_dissipation),
                'thermal_dissipation': float(thermal_dissipation),
                'yield_strength': float(yield_strength),
                'stress_magnitude': float(stress_magnitude)
            })
            
            return dissipative_analysis
            
        except Exception as e:
            self.logger.error(f"Dissipative energy calculation failed: {e}")
            return {
                'dissipative_energy_density': 1e3,  # Fallback
                'confidence': 0.2,
                'error': str(e)
            }
    
    def _predict_energy_conservation_ml(self, stress_tensor, temperature, pressure, effects, model_manager):
        """ML-based energy conservation predictions for validation"""
        try:
            ml_predictions = {
                'predicted_total_energy': 0.0,
                'energy_distribution': {},
                'conservation_score': 0.5,
                'model_confidence': 0.5,
                'ensemble_predictions': []
            }
            
            # Prepare feature vector
            features = np.array([
                np.trace(stress_tensor),  # I1 invariant
                np.sqrt(0.5 * np.sum((stress_tensor - np.trace(stress_tensor)/3 * np.eye(3))**2)),  # J2 invariant
                temperature,
                pressure,
                effects.get('depth', 0),
                effects.get('deformation_rate', 0),
                len(effects.get('composition', {}))
            ]).reshape(1, -1)
            
            # Energy prediction model
            try:
                energy_model = model_manager.load_model('energy_conservation_predictor')
                if energy_model:
                    predicted_energy = energy_model.predict(features)[0]
                    model_confidence = energy_model.predict_proba(features).max() if hasattr(energy_model, 'predict_proba') else 0.7
                    
                    ml_predictions.update({
                        'predicted_total_energy': float(predicted_energy),
                        'model_confidence': float(model_confidence)
                    })
            except Exception as e:
                self.logger.debug(f"Energy prediction model failed: {e}")
            
            # Ensemble predictions
            for model_name in ['energy_predictor_1', 'energy_predictor_2', 'energy_predictor_ensemble']:
                try:
                    model = model_manager.load_model(model_name)
                    if model:
                        ensemble_pred = model.predict(features)[0]
                        ml_predictions['ensemble_predictions'].append({
                            'model': model_name,
                            'prediction': float(ensemble_pred)
                        })
                except Exception:
                    continue
            
            # Energy component distribution prediction
            try:
                distribution_model = model_manager.load_model('energy_distribution_classifier')
                if distribution_model:
                    distribution_pred = distribution_model.predict(features)[0]
                    ml_predictions['energy_distribution'] = {
                        'elastic_fraction': float(distribution_pred[0]) if len(distribution_pred) > 0 else 0.4,
                        'thermal_fraction': float(distribution_pred[1]) if len(distribution_pred) > 1 else 0.3,
                        'kinetic_fraction': float(distribution_pred[2]) if len(distribution_pred) > 2 else 0.1,
                        'other_fraction': float(distribution_pred[3]) if len(distribution_pred) > 3 else 0.2
                    }
            except Exception as e:
                self.logger.debug(f"Energy distribution model failed: {e}")
                ml_predictions['energy_distribution'] = {
                    'elastic_fraction': 0.4,
                    'thermal_fraction': 0.3,
                    'kinetic_fraction': 0.1,
                    'other_fraction': 0.2
                }
            
            return ml_predictions
            
        except Exception as e:
            self.logger.error(f"ML energy prediction failed: {e}")
            return {
                'predicted_total_energy': 1e6,  # Fallback
                'model_confidence': 0.2,
                'error': str(e)
            }
    
    def _calculate_total_energy_with_conservation_check(self, energy_components):
        """Calculate total energy and check conservation principles"""
        try:
            total_energy = 0.0
            
            # Sum all energy components
            for component_name, component_data in energy_components.items():
                if isinstance(component_data, dict):
                    energy_value = component_data.get(f'{component_name}_energy_density', 0.0)
                    if component_name == 'elastic':
                        energy_value = component_data.get('strain_energy_density', 0.0)
                    elif component_name == 'thermal':
                        energy_value = component_data.get('thermal_energy_density', 0.0)
                    elif component_name == 'kinetic':
                        energy_value = component_data.get('kinetic_energy_density', 0.0)
                    elif component_name == 'gravitational':
                        energy_value = component_data.get('potential_energy_density', 0.0)
                    elif component_name == 'chemical':
                        energy_value = component_data.get('chemical_energy_density', 0.0)
                    elif component_name == 'dissipative':
                        # Dissipative energy is lost, so subtract from total
                        energy_value = -component_data.get('dissipative_energy_density', 0.0)
                    
                    total_energy += energy_value
                else:
                    total_energy += float(component_data) if component_data else 0.0
            
            return total_energy
            
        except Exception as e:
            self.logger.error(f"Total energy calculation failed: {e}")
            return 1e6  # Fallback
    
    def _detect_conservation_violations(self, energy_components, total_energy):
        """Detect violations of energy conservation principles"""
        try:
            violations = []
            
            # Check for negative total energy (unphysical)
            if total_energy < 0:
                violations.append({
                    'type': 'negative_total_energy',
                    'severity': 'high',
                    'value': total_energy,
                    'description': 'Total energy is negative, violating physical principles'
                })
            
            # Check for unreasonably high energy densities
            if total_energy > 1e10:  # J/m³
                violations.append({
                    'type': 'excessive_energy_density',
                    'severity': 'medium',
                    'value': total_energy,
                    'description': 'Energy density exceeds reasonable geological values'
                })
            
            # Check energy component ratios
            elastic_energy = energy_components.get('elastic', {}).get('strain_energy_density', 0)
            thermal_energy = energy_components.get('thermal', {}).get('thermal_energy_density', 0)
            
            if elastic_energy > 0 and thermal_energy > 0:
                ratio = thermal_energy / elastic_energy
                if ratio > 1000:  # Thermal dominance check
                    violations.append({
                        'type': 'thermal_dominance',
                        'severity': 'low',
                        'ratio': ratio,
                        'description': 'Thermal energy significantly exceeds elastic energy'
                    })
            
            # Check for conservation in time (if temporal data available)
            # This would require previous energy calculations for comparison
            
            return violations
            
        except Exception as e:
            self.logger.error(f"Conservation violation detection failed: {e}")
            return [{'type': 'detection_error', 'error': str(e)}]
    
    def _validate_energy_conservation_real_time(self, energy_analysis, external_connector):
        """Real-time validation using external monitoring data"""
        try:
            validation = {
                'seismic_validation': {},
                'thermal_validation': {},
                'deformation_validation': {},
                'overall_score': 0.5
            }
            
            if external_connector:
                # Seismic energy validation
                try:
                    location = getattr(self, '_current_location', {'lat': 40.0, 'lon': -100.0})
                    seismic_data = external_connector.query_usgs_earthquake_data(
                        latitude=location['lat'],
                        longitude=location['lon'],
                        radius_km=100,
                        time_window_hours=168  # 1 week
                    )
                    
                    if seismic_data and seismic_data['features']:
                        # Calculate total seismic energy release
                        total_seismic_energy = 0
                        for event in seismic_data['features']:
                            mag = event['properties'].get('mag', 0)
                            if mag:
                                # Magnitude to energy conversion (log scale)
                                energy_joules = 10**(1.5 * mag + 4.8)
                                total_seismic_energy += energy_joules
                        
                        # Compare with calculated kinetic energy
                        calculated_kinetic = energy_analysis['energy_components'].get('kinetic', {}).get('kinetic_energy_density', 0)
                        
                        if total_seismic_energy > 0 and calculated_kinetic > 0:
                            # Rough comparison accounting for volume differences
                            validation['seismic_validation'] = {
                                'total_seismic_energy': total_seismic_energy,
                                'calculated_kinetic_energy': calculated_kinetic,
                                'energy_ratio': total_seismic_energy / (calculated_kinetic * 1e9),  # Volume scaling
                                'correlation_score': 0.7
                            }
                except Exception as e:
                    self.logger.debug(f"Seismic validation failed: {e}")
                
                # Thermal validation with geothermal data
                try:
                    thermal_data = external_connector.query_noaa_thermal_data(
                        latitude=location['lat'],
                        longitude=location['lon']
                    )
                    
                    if thermal_data:
                        observed_heat_flow = thermal_data.get('heat_flow_mW_m2', 60)
                        calculated_thermal = energy_analysis['energy_components'].get('thermal', {}).get('thermal_energy_density', 0)
                        
                        # Convert calculated thermal energy to heat flow estimate
                        estimated_heat_flow = calculated_thermal / 1000  # Rough conversion
                        
                        validation['thermal_validation'] = {
                            'observed_heat_flow': observed_heat_flow,
                            'estimated_heat_flow': estimated_heat_flow,
                            'heat_flow_ratio': estimated_heat_flow / observed_heat_flow if observed_heat_flow > 0 else 0,
                            'correlation_score': 0.6
                        }
                except Exception as e:
                    self.logger.debug(f"Thermal validation failed: {e}")
            
            # Calculate overall validation score
            scores = []
            if validation['seismic_validation']:
                scores.append(validation['seismic_validation'].get('correlation_score', 0.5))
            if validation['thermal_validation']:
                scores.append(validation['thermal_validation'].get('correlation_score', 0.5))
            
            validation['overall_score'] = np.mean(scores) if scores else 0.4
            
            return validation
            
        except Exception as e:
            self.logger.error(f"Real-time energy validation failed: {e}")
            return {
                'overall_score': 0.3,
                'error': str(e)
            }
    
    def _calculate_energy_conservation_score(self, energy_analysis, conservation_violations):
        """Calculate comprehensive energy conservation score"""
        try:
            base_score = 0.8
            
            # Penalize violations
            violation_penalty = 0.0
            for violation in conservation_violations:
                if violation['severity'] == 'high':
                    violation_penalty += 0.3
                elif violation['severity'] == 'medium':
                    violation_penalty += 0.2
                elif violation['severity'] == 'low':
                    violation_penalty += 0.1
            
            # Consider confidence scores of components
            component_confidences = []
            for component_data in energy_analysis['energy_components'].values():
                if isinstance(component_data, dict):
                    confidence = component_data.get('confidence', 0.5)
                    component_confidences.append(confidence)
            
            avg_confidence = np.mean(component_confidences) if component_confidences else 0.5
            
            # ML prediction agreement
            ml_agreement = 0.5
            if energy_analysis['ml_predictions']:
                predicted_energy = energy_analysis['ml_predictions'].get('predicted_total_energy', 0)
                actual_energy = energy_analysis['total_energy_density']
                
                if predicted_energy > 0 and actual_energy > 0:
                    ratio = min(predicted_energy, actual_energy) / max(predicted_energy, actual_energy)
                    ml_agreement = ratio
            
            # Real-time validation score
            real_time_score = energy_analysis['real_time_validation'].get('overall_score', 0.4)
            
            # Uncertainty penalty
            uncertainty_penalty = 0.0
            if energy_analysis['uncertainty_analysis']:
                avg_uncertainty = energy_analysis['uncertainty_analysis'].get('average_uncertainty', 0.2)
                uncertainty_penalty = avg_uncertainty * 0.2
            
            # Final score calculation
            final_score = (
                base_score * 0.3 +
                avg_confidence * 0.25 +
                ml_agreement * 0.2 +
                real_time_score * 0.25 -
                violation_penalty -
                uncertainty_penalty
            )
            
            return max(0.0, min(1.0, final_score))
            
        except Exception as e:
            self.logger.error(f"Energy conservation scoring failed: {e}")
            return 0.4
    
    def _fallback_energy_analysis(self, stress, temperature, pressure, effects):
        """Fallback energy analysis when advanced methods fail"""
        try:
            # Simple energy conservation analysis as fallback
            stress_array = np.asarray(stress)
            mean_stress = np.mean(stress_array) if stress_array.size > 0 else 1e6
            
            # Basic elastic energy
            elastic_modulus = 70e9  # Pa
            strain_energy_density = (mean_stress**2) / (2 * elastic_modulus)
            
            # Basic thermal energy
            heat_capacity = 1000  # J/(kg*K)
            density = 2700  # kg/m³
            thermal_energy_density = heat_capacity * density * (temperature - 298.15)
            
            total_energy_density = strain_energy_density + abs(thermal_energy_density)
            
            return {
                'total_energy_density': float(total_energy_density),
                'energy_components': {
                    'elastic': {'strain_energy_density': float(strain_energy_density), 'confidence': 0.3},
                    'thermal': {'thermal_energy_density': float(thermal_energy_density), 'confidence': 0.3}
                },
                'conservation_violations': [],
                'uncertainty_analysis': {'average_uncertainty': 0.5},
                'ml_predictions': {},
                'real_time_validation': {'overall_score': 0.3},
                'score': 0.4,
                'method': 'fallback_analysis'
            }
            
        except Exception as e:
            self.logger.error(f"Fallback energy analysis failed: {e}")
            return {
                'total_energy_density': 1e6,
                'score': 0.2,
                'error': f'Complete failure: {str(e)}'
            }
    
    # Supporting utility methods
    def _calculate_temperature_dependent_elastic_modulus(self, temperature):
        """Calculate temperature-dependent elastic modulus"""
        try:
            # Base elastic modulus at reference temperature
            E0 = 70e9  # Pa at 298.15 K
            T0 = 298.15  # K
            
            # Temperature dependence coefficient (typical for rocks)
            dE_dT = -40e6  # Pa/K
            
            elastic_modulus = E0 + dE_dT * (temperature - T0)
            
            # Ensure positive value
            return max(1e9, elastic_modulus)
            
        except Exception:
            return 70e9
    
    def _calculate_pressure_dependent_poisson_ratio(self, pressure):
        """Calculate pressure-dependent Poisson's ratio"""
        try:
            # Base Poisson's ratio
            nu0 = 0.25
            
            # Pressure dependence (slight increase with pressure)
            dnu_dP = 1e-11  # 1/Pa
            
            poisson_ratio = nu0 + dnu_dP * pressure
            
            # Physical constraints
            return max(0.1, min(0.49, poisson_ratio))
            
        except Exception:
            return 0.25
    
    def _calculate_strain_from_stress(self, stress_tensor, elastic_modulus, poisson_ratio):
        """Calculate strain tensor from stress tensor"""
        try:
            # Compliance matrix for isotropic material
            E = elastic_modulus
            nu = poisson_ratio
            
            # Principal strains calculation (simplified)
            trace_stress = np.trace(stress_tensor)
            strain_tensor = (1/E) * ((1+nu) * stress_tensor - nu * trace_stress * np.eye(3))
            
            return strain_tensor
            
        except Exception:
            # Fallback to simple relationship
            return stress_tensor / elastic_modulus
    
    def _estimate_heat_capacity_from_lithology(self, lithology):
        """Estimate heat capacity based on lithology"""
        try:
            heat_capacities = {
                'granite': 790,
                'basalt': 840,
                'limestone': 920,
                'sandstone': 920,
                'shale': 800,
                'quartzite': 820,
                'gneiss': 780,
                'schist': 760
            }
            
            lithology_lower = lithology.lower() if lithology else 'granite'
            
            for rock_type, heat_cap in heat_capacities.items():
                if rock_type in lithology_lower:
                    return heat_cap
            
            return 1000  # Default value
            
        except Exception:
            return 1000
    
    def _fallback_thermal_energy_calculation(self, temperature, pressure):
        """Fallback thermal energy calculation"""
        try:
            heat_capacity = 1000  # J/(kg*K)
            density = 2700  # kg/m³
            reference_temp = 298.15  # K
            
            thermal_energy_density = heat_capacity * density * (temperature - reference_temp)
            
            return {
                'thermal_energy_density': float(thermal_energy_density),
                'heat_capacity': float(heat_capacity),
                'density': float(density),
                'confidence': 0.3,
                'method': 'fallback'
            }
            
        except Exception:
            return {
                'thermal_energy_density': 1e5,
                'confidence': 0.2,
                'error': 'fallback_calculation_failed'
            }

    def _validate_hydromechanical_coupling(self, stress, fluid_pressure, porosity, permeability, effects):
        """Validate hydromechanical coupling"""
        try:
            # Effective stress principle: σ' = σ - αPf
            biot_coefficient = effects.get('biot_coefficient', 0.7)
            effective_stress = stress - biot_coefficient * fluid_pressure if isinstance(stress, (int, float)) else stress
            
            # Porosity-stress relationship
            reference_porosity = effects.get('reference_porosity', 0.1)
            compressibility = effects.get('rock_compressibility', 1e-9)  # 1/Pa
            
            stress_magnitude = np.linalg.norm(stress) if isinstance(stress, np.ndarray) else abs(stress)
            expected_porosity_change = -compressibility * stress_magnitude * reference_porosity
            expected_porosity = reference_porosity + expected_porosity_change
            
            # Porosity consistency
            porosity_deviation = abs(porosity - expected_porosity) / max(expected_porosity, 0.01)
            porosity_score = max(0.2, 1.0 - porosity_deviation)
            
            # Permeability-porosity coupling (Kozeny-Carman type relationship)
            reference_permeability = effects.get('reference_permeability', 1e-15)
            porosity_ratio = porosity / max(reference_porosity, 0.01)
            expected_permeability = reference_permeability * (porosity_ratio ** 3)
            
            permeability_ratio = permeability / max(expected_permeability, 1e-20)
            permeability_score = 1.0 - min(1.0, abs(np.log10(max(permeability_ratio, 1e-10))) / 3.0)
            
            # Fluid pressure effects on stress
            pressure_effect_score = 0.8
            if fluid_pressure > 1e6:  # Significant fluid pressure
                pressure_stress_ratio = fluid_pressure / max(stress_magnitude, 1e6)
                if 0.01 <= pressure_stress_ratio <= 1.0:  # Reasonable range
                    pressure_effect_score = 0.9
                else:
                    pressure_effect_score = 0.5
            
            final_score = 0.4 * porosity_score + 0.3 * permeability_score + 0.3 * pressure_effect_score
            
            return {
                'score': max(0.0, min(1.0, final_score)),
                'expected_porosity': float(expected_porosity),
                'porosity_deviation': float(porosity_deviation),
                'expected_permeability': float(expected_permeability),
                'permeability_ratio': float(permeability_ratio),
                'pressure_stress_ratio': float(pressure_stress_ratio) if fluid_pressure > 1e6 else None,
                'coupling_method': 'effective_stress_kozeny_carman_analysis'
            }
            
        except Exception:
            return {'score': 0.5, 'error': 'hydromechanical_coupling_failed'}
    
    def _validate_chemomechanical_coupling(self, stress, composition, temperature, effects):
        """Validate chemomechanical coupling"""
        try:
            score = 0.7  # Base score
            
            # Chemical composition effects on mechanical properties
            if isinstance(composition, dict) and composition:
                # Common rock-forming minerals and their effects
                mineral_effects = {
                    'quartz': {'strength_factor': 1.2, 'stiffness_factor': 1.1},
                    'feldspar': {'strength_factor': 1.0, 'stiffness_factor': 1.0},
                    'mica': {'strength_factor': 0.7, 'stiffness_factor': 0.8},
                    'calcite': {'strength_factor': 0.8, 'stiffness_factor': 0.9},
                    'clay': {'strength_factor': 0.5, 'stiffness_factor': 0.6}
                }
                
                weighted_strength = 0.0
                total_fraction = 0.0
                
                for mineral, fraction in composition.items():
                    if isinstance(fraction, (int, float)) and mineral.lower() in mineral_effects:
                        mineral_props = mineral_effects[mineral.lower()]
                        weighted_strength += fraction * mineral_props['strength_factor']
                        total_fraction += fraction
                
                if total_fraction > 0:
                    average_strength_factor = weighted_strength / total_fraction
                    
                    # Validate stress against composition-modified strength
                    base_strength = 200e6  # Pa
                    expected_strength = base_strength * average_strength_factor
                    
                    stress_magnitude = np.linalg.norm(stress) if isinstance(stress, np.ndarray) else abs(stress)
                    strength_ratio = stress_magnitude / expected_strength
                    
                    if strength_ratio <= 1.0:  # Below failure
                        score = 0.9
                    elif strength_ratio <= 2.0:  # Potentially failed
                        score = 0.6
                    else:  # Well above failure
                        score = 0.3
            
            # Temperature effects on chemical reactions
            if temperature > 373:  # Above water boiling point
                # Enhanced chemical weathering and alteration
                alteration_factor = min(2.0, (temperature - 373) / 500)  # Scales up to 873K
                if effects.get('alteration_present', False):
                    score += 0.1 * alteration_factor
                else:
                    score -= 0.05 * alteration_factor  # Inconsistency
            
            # pH effects (if available)
            ph = effects.get('ph', 7.0)
            if ph < 6.0 or ph > 8.0:  # Acidic or basic conditions
                # Enhanced chemical weathering expected
                if effects.get('chemical_weathering', 0) > 0.1:
                    score += 0.05
                else:
                    score -= 0.05
            
            return {
                'score': max(0.0, min(1.0, score)),
                'composition_analyzed': bool(isinstance(composition, dict) and composition),
                'temperature_effects': temperature > 373,
                'ph_effects': ph < 6.0 or ph > 8.0,
                'coupling_method': 'mineral_composition_strength_analysis'
            }
            
        except Exception:
            return {'score': 0.6, 'error': 'chemomechanical_coupling_failed'}
    
    def _validate_electromagnetic_coupling(self, stress, electric_field, magnetic_field, effects):
        """Validate electromagnetic coupling"""
        try:
            score = 0.6  # Base score (EM coupling often weak in geological systems)
            
            # Convert fields to arrays
            E_field = np.asarray(electric_field) if electric_field else np.zeros(3)
            B_field = np.asarray(magnetic_field) if magnetic_field else np.zeros(3)
            
            E_magnitude = np.linalg.norm(E_field)
            B_magnitude = np.linalg.norm(B_field)
            
            # Piezoelectric effects (if applicable)
            piezoelectric_materials = ['quartz', 'tourmaline', 'berlinite']
            composition = effects.get('composition', {})
            
            has_piezoelectric = False
            if isinstance(composition, dict):
                for material in piezoelectric_materials:
                    if any(material in str(key).lower() for key in composition.keys()):
                        has_piezoelectric = True
                        break
            
            if has_piezoelectric and E_magnitude > 0:
                # Piezoelectric coupling validation
                piezoelectric_coefficient = 2.3e-12  # C/N for quartz
                stress_magnitude = np.linalg.norm(stress) if isinstance(stress, np.ndarray) else abs(stress)
                
                expected_polarization = piezoelectric_coefficient * stress_magnitude
                # This is a simplified check - real implementation would be more complex
                if expected_polarization > 1e-15:  # Significant polarization
                    score += 0.2
            
            # Magnetostrictive effects (rare in geological materials)
            magnetostrictive_materials = ['magnetite', 'pyrrhotite']
            has_magnetostrictive = False
            
            if isinstance(composition, dict):
                for material in magnetostrictive_materials:
                    if any(material in str(key).lower() for key in composition.keys()):
                        has_magnetostrictive = True
                        break
            
            if has_magnetostrictive and B_magnitude > 0:
                score += 0.1
            
            # Electromagnetic field consistency
            if E_magnitude > 0 or B_magnitude > 0:
                # Check for reasonable field magnitudes
                if 1e-6 <= E_magnitude <= 1e6:  # Reasonable E-field range (V/m)
                    score += 0.05
                if 1e-9 <= B_magnitude <= 1e-3:  # Reasonable B-field range (T)
                    score += 0.05
            
            return {
                'score': max(0.0, min(1.0, score)),
                'electric_field_magnitude': float(E_magnitude),
                'magnetic_field_magnitude': float(B_magnitude),
                'has_piezoelectric_materials': has_piezoelectric,
                'has_magnetostrictive_materials': has_magnetostrictive,
                'coupling_method': 'piezoelectric_magnetostrictive_analysis'
            }
            
        except Exception:
            return {'score': 0.5, 'error': 'electromagnetic_coupling_failed'}
    
    def _validate_poroelastic_coupling(self, stress, fluid_pressure, porosity, effects):
        """Validate poroelastic coupling (Biot theory)"""
        try:
            # Biot poroelastic parameters
            biot_coefficient = effects.get('biot_coefficient', 0.7)
            biot_modulus = effects.get('biot_modulus', 10e9)  # Pa
            drained_bulk_modulus = effects.get('drained_bulk_modulus', 30e9)  # Pa
            
            # Effective stress
            stress_magnitude = np.linalg.norm(stress) if isinstance(stress, np.ndarray) else abs(stress)
            effective_stress = stress_magnitude - biot_coefficient * fluid_pressure
            
            # Poroelastic coupling validation
            score = 0.7  # Base score
            
            # Check Biot coefficient reasonableness (0 < α ≤ 1)
            if 0 < biot_coefficient <= 1.0:
                score += 0.1
            else:
                score -= 0.2
            
            # Undrained vs drained response
            if fluid_pressure > 1e6:  # Significant fluid pressure
                # Skempton's coefficient B = α/K_u * K_s
                skempton_B = biot_coefficient  # Simplified
                
                if 0.3 <= skempton_B <= 1.0:  # Typical range for rocks
                    score += 0.1
                else:
                    score -= 0.1
            
            # Porosity change validation
            reference_porosity = effects.get('reference_porosity', 0.1)
            expected_porosity_change = -(effective_stress / biot_modulus) * reference_porosity
            expected_porosity = reference_porosity + expected_porosity_change
            
            porosity_deviation = abs(porosity - expected_porosity) / max(expected_porosity, 0.01)
            porosity_consistency = max(0.2, 1.0 - porosity_deviation)
            
            final_score = 0.7 * score + 0.3 * porosity_consistency
            
            return {
                'score': max(0.0, min(1.0, final_score)),
                'effective_stress': float(effective_stress),
                'biot_coefficient': biot_coefficient,
                'expected_porosity': float(expected_porosity),
                'porosity_deviation': float(porosity_deviation),
                'coupling_method': 'biot_poroelastic_theory'
            }
            
        except Exception:
            return {'score': 0.5, 'error': 'poroelastic_coupling_failed'}
    
    def _validate_viscoplastic_coupling(self, stress, temperature, effects):
        """Validate viscoplastic coupling"""
        try:
            # Temperature-dependent viscosity
            activation_energy = effects.get('activation_energy', 540e3)  # J/mol, typical for olivine
            gas_constant = 8.314  # J/(mol·K)
            reference_viscosity = effects.get('reference_viscosity', 1e19)  # Pa·s
            reference_temp = effects.get('reference_temperature', 1600)  # K
            
            # Arrhenius law
            viscosity = reference_viscosity * np.exp(activation_energy/gas_constant * (1/temperature - 1/reference_temp))
            
            # Stress-dependent viscosity (power law)
            stress_magnitude = np.linalg.norm(stress) if isinstance(stress, np.ndarray) else abs(stress)
            stress_exponent = effects.get('stress_exponent', 3.5)  # Typical for rocks
            reference_stress = effects.get('reference_stress', 1e6)  # Pa
            
            stress_dependent_viscosity = viscosity * (stress_magnitude / reference_stress) ** (-stress_exponent + 1)
            
            # Validate viscosity range
            score = 0.7  # Base score
            
            if 1e10 <= stress_dependent_viscosity <= 1e25:  # Reasonable geological range
                score = 0.9
            elif 1e8 <= stress_dependent_viscosity <= 1e27:  # Extended range
                score = 0.7
            else:
                score = 0.4
            
            # Strain rate consistency
            strain_rate = effects.get('strain_rate', 1e-15)  # 1/s
            expected_strain_rate = stress_magnitude / (2 * stress_dependent_viscosity)
            
            strain_rate_ratio = strain_rate / max(expected_strain_rate, 1e-20)
            if 0.1 <= strain_rate_ratio <= 10.0:
                score += 0.1
            
            return {
                'score': max(0.0, min(1.0, score)),
                'calculated_viscosity': float(stress_dependent_viscosity),
                'expected_strain_rate': float(expected_strain_rate),
                'strain_rate_ratio': float(strain_rate_ratio),
                'coupling_method': 'arrhenius_power_law_rheology'
            }
            
        except Exception:
            return {'score': 0.6, 'error': 'viscoplastic_coupling_failed'}
    
    def _analyze_coupling_consistency(self, *coupling_results):
        """Analyze consistency between different coupling mechanisms"""
        try:
            scores = [result.get('score', 0.5) for result in coupling_results if isinstance(result, dict)]
            
            if not scores:
                return {'score': 0.4, 'reason': 'no_coupling_results'}
            
            # Statistical consistency analysis
            mean_score = np.mean(scores)
            std_score = np.std(scores)
            min_score = np.min(scores)
            max_score = np.max(scores)
            
            # Consistency based on agreement between couplings
            consistency_score = 1.0 - min(1.0, 2 * std_score)  # Lower std = higher consistency
            range_penalty = (max_score - min_score) * 0.5  # Penalty for large score ranges
            
            final_consistency = max(0.1, consistency_score - range_penalty)
            
            return {
                'score': float(final_consistency),
                'mean_coupling_score': float(mean_score),
                'coupling_std': float(std_score),
                'score_range': float(max_score - min_score),
                'num_couplings': len(scores),
                'consistency_method': 'statistical_agreement_analysis'
            }
            
        except Exception:
            return {'score': 0.5, 'error': 'coupling_consistency_analysis_failed'}
    
    def _analyze_field_interactions(self, stress, effects):
        """Analyze interactions between different physical fields"""
        try:
            # Field interaction strength based on available parameters
            temperature = effects.get('temperature', 298.15)
            pressure = effects.get('pressure', 101325)
            fluid_pressure = effects.get('fluid_pressure', pressure)
            electric_field = effects.get('electric_field', [0, 0, 0])
            
            # Calculate interaction strengths
            thermal_mechanical = min(1.0, abs(temperature - 298.15) / 1000.0)  # Normalized temp difference
            hydraulic_mechanical = min(1.0, abs(fluid_pressure - pressure) / 100e6)  # Normalized pressure diff
            electric_mechanical = min(1.0, np.linalg.norm(electric_field) / 1e6) if electric_field else 0.0
            
            # Overall interaction strength
            interaction_strength = (thermal_mechanical + hydraulic_mechanical + electric_mechanical) / 3.0
            
            # Field coupling indicators
            strong_interactions = sum([
                thermal_mechanical > 0.5,
                hydraulic_mechanical > 0.3,
                electric_mechanical > 0.1
            ])
            
            return {
                'interaction_strength': float(interaction_strength),
                'thermal_mechanical_strength': float(thermal_mechanical),
                'hydraulic_mechanical_strength': float(hydraulic_mechanical),
                'electric_mechanical_strength': float(electric_mechanical),
                'strong_interactions_count': strong_interactions,
                'dominant_interaction': 'thermal' if thermal_mechanical > max(hydraulic_mechanical, electric_mechanical) 
                                     else 'hydraulic' if hydraulic_mechanical > electric_mechanical 
                                     else 'electric' if electric_mechanical > 0 else 'none'
            }
            
        except Exception:
            return {'interaction_strength': 0.3, 'error': 'field_interaction_analysis_failed'}
    
