    async def _extract_advanced_location_features(self, location):
        """Extract comprehensive location-based geological features"""
        try:
            lat, lon = location[0], location[1] if len(location) >= 2 else (0, 0)
            
            # Basic geographic features
            features = {
                'latitude': lat,
                'longitude': lon,
                'distance_from_equator': abs(lat),
                'hemisphere': 1 if lat >= 0 else -1
            }
            
            # Tectonic plate analysis
            try:
                from .plate_evolution_engine import PlateEvolutionEngine
                plate_engine = PlateEvolutionEngine()
                plate_info = await plate_engine.get_plate_at_location(lat, lon)
                features.update({
                    'tectonic_plate': plate_info.get('plate_name', 'unknown'),
                    'plate_velocity_x': plate_info.get('velocity', {}).get('x', 0),
                    'plate_velocity_y': plate_info.get('velocity', {}).get('y', 0),
                    'distance_to_plate_boundary': plate_info.get('distance_to_boundary', 1000),
                    'boundary_type': plate_info.get('boundary_type', 'unknown')
                })
            except:
                features.update({
                    'tectonic_plate': 'unknown',
                    'plate_velocity_x': 0,
                    'plate_velocity_y': 0,
                    'distance_to_plate_boundary': 1000,
                    'boundary_type': 'unknown'
                })
            
            # Seismic hazard context
            seismic_features = await self._get_seismic_hazard_features(lat, lon)
            features.update(seismic_features)
            
            # Volcanic context
            volcanic_features = await self._get_volcanic_context_features(lat, lon)
            features.update(volcanic_features)
            
            # Elevation and topographic features
            topo_features = await self._get_topographic_features(lat, lon)
            features.update(topo_features)
            
            return features
            
        except Exception as e:
            self.logger.error(f"Advanced location feature extraction failed: {e}")
            return self._extract_location_features_enhanced(location)
            
    def _extract_location_features_enhanced(self, location):
        """Enhanced fallback location feature extraction"""
        lat, lon = location[0], location[1] if len(location) >= 2 else (0, 0)
        
        # Enhanced geographic analysis
        return {
            'latitude': lat,
            'longitude': lon,
            'distance_from_equator': abs(lat),
            'hemisphere': 1 if lat >= 0 else -1,
            'latitude_zone': self._classify_latitude_zone(lat),
            'longitude_zone': self._classify_longitude_zone(lon),
            'coordinate_precision': len(str(lat).split('.')[-1]) if '.' in str(lat) else 0,
            'ocean_proximity': self._estimate_ocean_proximity(lat, lon)
        }
    
