    def _calculate_advanced_stress_invariants(self, tensor):
        """Calculate advanced stress tensor invariants and characteristics"""
        try:
            import numpy as np
            from scipy import linalg
            
            # Calculate eigenvalues (principal stresses)
            eigenvals = np.sort(linalg.eigvals(tensor))[::-1]  # Sort descending
            sigma1, sigma2, sigma3 = eigenvals[0], eigenvals[1], eigenvals[2]
            
            # Calculate invariants
            I1 = np.trace(tensor)  # First invariant
            I2 = 0.5 * (I1**2 - np.trace(tensor @ tensor))  # Second invariant
            I3 = linalg.det(tensor)  # Third invariant (determinant)
            
            # Deviatoric tensor and invariants
            dev_tensor = tensor - (I1/3) * np.eye(3)
            J2 = 0.5 * np.trace(dev_tensor @ dev_tensor)
            J3 = linalg.det(dev_tensor)
            
            # Stress ratios and shape parameters
            stress_ratio = (sigma2 - sigma3) / (sigma1 - sigma3) if (sigma1 - sigma3) != 0 else 0
            lode_parameter = (2*sigma2 - sigma1 - sigma3) / (sigma1 - sigma3) if (sigma1 - sigma3) != 0 else 0
            
            return {
                'stress_invariant_I1': float(I1),
                'stress_invariant_I2': float(I2),
                'stress_invariant_I3': float(I3),
                'deviatoric_J2': float(J2),
                'deviatoric_J3': float(J3),
                'principal_stress_sigma1': float(sigma1),
                'principal_stress_sigma2': float(sigma2),
                'principal_stress_sigma3': float(sigma3),
                'stress_ratio': float(stress_ratio),
                'lode_parameter': float(lode_parameter),
                'mean_stress_advanced': float(I1/3),
                'equivalent_stress': float(np.sqrt(3*J2)),
                'stress_triaxiality': float(I1/3 / np.sqrt(3*J2)) if J2 > 0 else 0
            }
        except Exception as e:
            self.logger.error(f"Stress invariant calculation failed: {e}")
            return {'stress_invariants_error': True}
    
