    async def _calculate_coulomb_stress_features(self, coulomb_modeler, earthquake_data, lat, lon, depth):
        """Calculate Coulomb stress changes from regional earthquakes"""
        try:
            if not earthquake_data:
                return {'coulomb_stress_change': 0, 'triggering_probability': 0}
                
            from .coulomb_stress_modeler import StressCalculationPoint, EarthquakeEvent
            from datetime import datetime
            
            # Create calculation point
            calc_point = StressCalculationPoint(
                latitude=lat,
                longitude=lon,
                depth=depth,
                target_strike=0,  # Default values, should be from geological data
                target_dip=90,
                target_rake=0
            )
            
            # Convert earthquake data to events
            events = []
            for eq_data in earthquake_data[:10]:  # Limit to 10 most significant events
                if hasattr(eq_data, 'coordinates') and hasattr(eq_data, 'properties'):
                    eq_lat, eq_lon, eq_depth = eq_data.coordinates
                    magnitude = eq_data.properties.get('magnitude', 0)
                    
                    if magnitude >= 3.0:  # Only consider M3+ events
                        event = EarthquakeEvent(
                            event_id=eq_data.record_id,
                            latitude=eq_lat,
                            longitude=eq_lon,
                            depth=eq_depth,
                            magnitude=magnitude,
                            timestamp=eq_data.timestamp
                        )
                        events.append(event)
            
            if events:
                # Calculate cumulative Coulomb stress change
                total_stress_change = await coulomb_modeler.calculate_stress_change_cumulative(
                    events, [calc_point]
                )
                
                # Calculate triggering probability based on stress change
                stress_change = total_stress_change[0] if total_stress_change else 0
                triggering_prob = self._calculate_triggering_probability(stress_change)
                
                return {
                    'coulomb_stress_change': float(stress_change),
                    'triggering_probability': float(triggering_prob),
                    'contributing_events': len(events),
                    'max_contributing_magnitude': max([e.magnitude for e in events])
                }
            
            return {'coulomb_stress_change': 0, 'triggering_probability': 0, 'contributing_events': 0}
            
        except Exception as e:
            self.logger.error(f"Coulomb stress calculation failed: {e}")
            return {'coulomb_stress_change': 0, 'triggering_probability': 0, 'coulomb_error': True}
    
