    async def _get_formation_stress_properties(self, lat, lon, depth):
        """Get geological formation stress properties from database"""
        try:
            from .database_integration import DatabaseManager
            import asyncio
            
            db_manager = DatabaseManager()
            
            # Query rock mechanical properties from database
            query = """
            SELECT 
                unconfined_compressive_strength_mpa,
                tensile_strength_mpa,
                cohesion_mpa,
                friction_angle_deg,
                elastic_modulus_gpa,
                poisson_ratio
            FROM rock_mechanical_properties rmp
            JOIN geological_formations gf ON rmp.formation_id = gf.formation_id
            WHERE ST_DWithin(gf.location::geography, ST_Point(%s, %s)::geography, 10000)
            AND ABS(ST_Z(gf.location) - %s) < 5
            ORDER BY ST_Distance(gf.location::geography, ST_Point(%s, %s)::geography)
            LIMIT 5
            """
            
            results = await db_manager.execute_query(query, [lon, lat, depth, lon, lat])
            
            if results:
                # Calculate average properties
                avg_properties = {
                    'formation_compressive_strength': sum(r[0] for r in results if r[0]) / len(results),
                    'formation_tensile_strength': sum(r[1] for r in results if r[1]) / len(results),
                    'formation_cohesion': sum(r[2] for r in results if r[2]) / len(results),
                    'formation_friction_angle': sum(r[3] for r in results if r[3]) / len(results),
                    'formation_elastic_modulus': sum(r[4] for r in results if r[4]) / len(results),
                    'formation_poisson_ratio': sum(r[5] for r in results if r[5]) / len(results),
                    'formation_data_points': len(results)
                }
                return avg_properties
            
            return {'formation_data_available': False}
            
        except Exception as e:
            self.logger.error(f"Formation stress properties query failed: {e}")
            return {'formation_query_error': True}
    
    def _extract_temporal_stress_patterns(self, temporal_data):
        """Extract temporal stress evolution patterns"""
        try:
            import numpy as np
            from scipy.stats import linregress
            
            if not temporal_data or len(temporal_data) < 3:
                return {'temporal_analysis_insufficient_data': True}
            
            # Extract time series data
            times = [entry.get('timestamp', 0) for entry in temporal_data]
            magnitudes = [entry.get('magnitude', 0) for entry in temporal_data]
            orientations = [entry.get('orientation', 0) for entry in temporal_data]
            
            # Calculate trends
            if len(set(times)) > 1:  # Need different time points
                mag_trend = linregress(times, magnitudes)
                orientation_trend = linregress(times, orientations)
                
                return {
                    'stress_magnitude_trend': float(mag_trend.slope),
                    'stress_magnitude_r2': float(mag_trend.rvalue**2),
                    'stress_orientation_trend': float(orientation_trend.slope),
                    'stress_orientation_stability': 1.0 - np.std(orientations) / 180.0,
                    'temporal_data_points': len(temporal_data),
                    'stress_evolution_confidence': min(mag_trend.rvalue**2, orientation_trend.rvalue**2)
                }
            
            return {
                'stress_magnitude_variability': float(np.std(magnitudes)),
                'stress_orientation_variability': float(np.std(orientations)),
                'temporal_data_points': len(temporal_data)
            }
            
        except Exception as e:
            self.logger.error(f"Temporal stress pattern analysis failed: {e}")
            return {'temporal_analysis_error': True}
    
