    def _calculate_triggering_probability(self, stress_change):
        """Calculate earthquake triggering probability from Coulomb stress change"""
        try:
            import numpy as np
            # Based on empirical relationships (King et al., 1994; Stein, 1999)
            # P = 1 / (1 + exp(-alpha * delta_CFS))
            alpha = 10.0  # Empirical parameter (1/MPa)
            probability = 1.0 / (1.0 + np.exp(-alpha * stress_change))
            return min(max(probability, 0.0), 1.0)  # Clamp to [0, 1]
        except:
            return 0.5  # Default probability
    
    async def _classify_tectonic_setting_ml(self, location, depth, tectonic_context):
        """ML-based tectonic setting classification using trained models"""
        try:
            from .model_manager import ModelManager
            import numpy as np
            
            # Load pre-trained tectonic classification model
            if not hasattr(self, 'tectonic_classifier'):
                model_config = {
                    'model_type': 'tectonic_classifier',
                    'azure_vm_endpoint': 'https://prometheus-ml.azurewebsites.net',
                    'dataset_path': '/data/tectonic_classification/',
                    'model_save_path': '/models/tectonic_classifier/'
                }
                self.tectonic_classifier = ModelManager(model_config)
            
            # Prepare input features
            input_features = np.array([
                location[0],  # latitude
                location[1],  # longitude
                depth,
                tectonic_context.get('elevation', 0),
                tectonic_context.get('distance_to_coast', 100),
                tectonic_context.get('regional_seismicity', 0.5)
            ]).reshape(1, -1)
            
            # Get ML prediction
            prediction = await self.tectonic_classifier.predict(input_features)
            
            # Map prediction to tectonic settings
            tectonic_classes = [
                'extensional', 'compressional', 'strike_slip', 'transtensional',
                'transpressional', 'stable', 'rift', 'subduction', 'transform',
                'back_arc', 'fore_arc', 'intraplate', 'volcanic_arc'
            ]
            
            predicted_class = tectonic_classes[np.argmax(prediction['probabilities'])]
            confidence = float(np.max(prediction['probabilities']))
            
            return {
                'ml_tectonic_setting': predicted_class,
                'ml_tectonic_confidence': confidence,
                'ml_tectonic_probabilities': {
                    cls: float(prob) for cls, prob in zip(tectonic_classes, prediction['probabilities'])
                }
            }
            
        except Exception as e:
            self.logger.error(f"ML tectonic classification failed: {e}")
            return {
                'ml_tectonic_setting': 'unknown',
                'ml_tectonic_confidence': 0.0,
                'ml_classification_error': True
            }
    
