    # Helper methods for location features
    
    def _classify_latitude_zone(self, lat):
        """Classify latitude into geological zones"""
        if abs(lat) <= 23.5:
            return 'tropical'
        elif abs(lat) <= 66.5:
            return 'temperate'
        else:
            return 'polar'
    
    def _classify_longitude_zone(self, lon):
        """Classify longitude into major geological provinces"""
        # Simplified continental classification
        if -180 <= lon <= -30:
            return 'americas'
        elif -30 <= lon <= 60:
            return 'africa_europe'
        elif 60 <= lon <= 180:
            return 'asia_pacific'
        else:
            return 'unknown'
    
    def _estimate_ocean_proximity(self, lat, lon):
        """Estimate proximity to ocean (simplified coastal distance)"""
        # This is a simplified approximation
        # In production, use actual coastline databases
        coastal_proximity_score = min(abs(lat) / 90.0, abs(lon) / 180.0)
        return 1.0 - coastal_proximity_score  # Higher score = closer to coast
    
    def _categorize_depth(self, depth):
        """Categorize depth into geological zones"""
        if depth <= 1:
            return 'surface'
        elif depth <= 5:
            return 'shallow'
        elif depth <= 15:
            return 'intermediate'
        elif depth <= 35:
            return 'deep_crustal'
        else:
            return 'mantle'
    
