    async def _analyze_tectonic_evolution(self, temporal_data, location):
        """Analyze temporal evolution of tectonic processes"""
        try:
            import numpy as np
            from scipy.signal import find_peaks
            from scipy.stats import pearsonr
            
            if len(temporal_data) < 5:
                return {'temporal_evolution_insufficient_data': True}
            
            # Extract time series
            times = np.array([d.get('timestamp', 0) for d in temporal_data])
            settings = [d.get('tectonic_setting', 'unknown') for d in temporal_data]
            stress_magnitudes = np.array([d.get('stress_magnitude', 0) for d in temporal_data])
            
            # Analyze evolution patterns
            evolution_features = {
                'setting_stability': len(set(settings)) / len(settings),  # Lower = more stable
                'stress_trend': np.polyfit(times, stress_magnitudes, 1)[0] if len(times) > 1 else 0,
                'stress_cyclicity': self._detect_cyclicity(times, stress_magnitudes),
                'evolution_complexity': np.std(stress_magnitudes) / np.mean(stress_magnitudes) if np.mean(stress_magnitudes) > 0 else 0,
                'temporal_correlation': pearsonr(times, stress_magnitudes)[0] if len(times) > 1 else 0
            }
            
            return evolution_features
            
        except Exception as e:
            self.logger.error(f"Tectonic evolution analysis failed: {e}")
            return {'temporal_evolution_error': True}
    
