    # Utility methods for calculations
    
    async def _calculate_dominant_orientation(self, orientations, location=None, depth=None):
        """Advanced structural orientation analysis with geological database integration"""
        try:
            from .database_integration import DatabaseIntegration, DatabaseConfig
            from .external_data_connectors import USGSConnector, GeologicalDataConnector
            from .geological_statistics import StructuralStatistics, OrientationAnalysis
            from scipy.stats import vonmises, circstd
            from sklearn.mixture import GaussianMixture
            import asyncio
            
            if not orientations or not any(o is not None for o in orientations):
                # Query regional structural database for contextual orientation
                return await self._query_regional_structural_orientation(location, depth)
            
            valid_orientations = np.array([o for o in orientations if o is not None and not np.isnan(o)])
            if len(valid_orientations) == 0:
                return await self._query_regional_structural_orientation(location, depth)
            
            # Advanced multi-modal orientation analysis
            result = {
                'dominant_orientation': 0,
                'confidence': 0,
                'modal_orientations': [],
                'structural_regime': 'unknown',
                'database_correlation': None
            }
            
            # 1. CIRCULAR STATISTICAL ANALYSIS
            angles_rad = valid_orientations * np.pi / 180
            
            # Fisher distribution for concentrated data
            if len(valid_orientations) >= 3:
                # Calculate resultant vector
                R = np.sqrt(np.sum(np.cos(angles_rad))**2 + np.sum(np.sin(angles_rad))**2)
                n = len(angles_rad)
                
                # Mean resultant length (concentration parameter)
                mean_R = R / n
                
                if mean_R > 0.7:  # Highly concentrated
                    dominant_angle = np.arctan2(np.sum(np.sin(angles_rad)), np.sum(np.cos(angles_rad)))
                    result['dominant_orientation'] = float((dominant_angle * 180 / np.pi) % 360)
                    result['confidence'] = float(mean_R)
                    result['structural_regime'] = 'highly_oriented'
                else:
                    # Multi-modal analysis using Gaussian Mixture Model
                    gm = GaussianMixture(n_components=min(3, len(valid_orientations)//2))
                    orientations_2d = np.column_stack([np.cos(angles_rad), np.sin(angles_rad)])
                    gm.fit(orientations_2d)
                    
                    # Extract modal orientations
                    modal_angles = []
                    for mean in gm.means_:
                        modal_angle = np.arctan2(mean[1], mean[0]) * 180 / np.pi
                        modal_angles.append(float(modal_angle % 360))
                    
                    result['modal_orientations'] = modal_angles
                    result['dominant_orientation'] = modal_angles[0] if modal_angles else 0
                    result['confidence'] = float(np.max(gm.weights_))
                    result['structural_regime'] = 'multi_modal'
            else:
                # Simple circular mean for small datasets
                dominant_angle = np.arctan2(np.mean(np.sin(angles_rad)), np.mean(np.cos(angles_rad)))
                result['dominant_orientation'] = float((dominant_angle * 180 / np.pi) % 360)
                result['confidence'] = 0.5
                result['structural_regime'] = 'simple'
            
            # 2. DATABASE CORRELATION AND VALIDATION
            if location and hasattr(self, 'database_managers'):
                try:
                    regional_data = await self._correlate_with_structural_database(
                        result['dominant_orientation'], location, depth
                    )
                    result['database_correlation'] = regional_data
                    
                    # Adjust confidence based on regional consistency
                    if regional_data and regional_data.get('consistency_score', 0) > 0.7:
                        result['confidence'] *= 1.2  # Boost confidence
                        result['confidence'] = min(1.0, result['confidence'])
                        
                except Exception as e:
                    self.logger.warning(f"Database correlation failed: {e}")
            
            # 3. EXTERNAL DATA INTEGRATION
            if location and hasattr(self, 'external_data_connectors'):
                try:
                    external_validation = await self._validate_with_external_structural_data(
                        result['dominant_orientation'], location
                    )
                    if external_validation:
                        result['external_validation'] = external_validation
                        
                except Exception as e:
                    self.logger.warning(f"External validation failed: {e}")
            
            return result['dominant_orientation']
            
        except Exception as e:
            self.logger.error(f"Advanced orientation calculation failed: {e}")
            # Fallback to basic calculation
            if orientations and any(o is not None for o in orientations):
                valid_orientations = [o for o in orientations if o is not None]
                if valid_orientations:
                    angles_rad = np.array(valid_orientations) * np.pi / 180
                    x = np.mean(np.cos(angles_rad))
                    y = np.mean(np.sin(angles_rad))
                    dominant_angle = np.arctan2(y, x) * 180 / np.pi
                    return float(dominant_angle % 360)
            return 0
    
    async def _detect_cyclicity(self, times, values, location=None, parameter_type=None):
        """Advanced multi-method cyclical pattern detection with geological context"""
        try:
            from scipy import signal, stats
            from scipy.fft import fft, fftfreq, fftshift
            from scipy.signal import periodogram, welch, lombscargle, find_peaks
            from sklearn.preprocessing import StandardScaler
            from .geological_statistics import TimeSeriesAnalysis, SpectralAnalysis
            from .database_integration import DatabaseIntegration
            import asyncio
            
            if len(values) < 10 or len(times) < 10:
                return await self._query_expected_cyclicity(location, parameter_type)
            
            # Ensure equal length arrays
            min_len = min(len(times), len(values))
            times = np.array(times[:min_len])
            values = np.array(values[:min_len])
            
            # Remove NaN values
            valid_mask = ~(np.isnan(times) | np.isnan(values))
            times = times[valid_mask]
            values = values[valid_mask]
            
            if len(values) < 5:
                return await self._query_expected_cyclicity(location, parameter_type)
            
            cyclicity_result = {
                'dominant_periods': [],
                'cyclicity_strength': 0,
                'spectral_peaks': [],
                'geological_context': None,
                'analysis_methods': []
            }
            
            # 1. ADVANCED SPECTRAL ANALYSIS
            
            # A) Lomb-Scargle for irregular time series
            if len(np.unique(np.diff(times))) > 1:  # Irregular sampling
                cyclicity_result['analysis_methods'].append('lomb_scargle')
                try:
                    # Normalize time to handle various units
                    time_norm = (times - np.min(times)) / (np.max(times) - np.min(times))
                    freqs = np.linspace(0.01, 0.5, 1000)
                    
                    pgram = lombscargle(time_norm, values, freqs, normalize=True)
                    
                    # Find significant peaks
                    peaks, properties = find_peaks(pgram, height=0.1, distance=20)
                    
                    if len(peaks) > 0:
                        # Convert back to original time units
                        time_span = np.max(times) - np.min(times)
                        dominant_periods = time_span / freqs[peaks]
                        cyclicity_result['dominant_periods'].extend(dominant_periods.tolist())
                        cyclicity_result['spectral_peaks'].extend(pgram[peaks].tolist())
                        cyclicity_result['cyclicity_strength'] = float(np.max(pgram[peaks]))
                        
                except Exception as e:
                    self.logger.warning(f"Lomb-Scargle analysis failed: {e}")
            
            # B) Classical FFT for regular time series
            else:
                cyclicity_result['analysis_methods'].append('fft')
                try:
                    # Detrend and normalize
                    detrended = signal.detrend(values)
                    scaler = StandardScaler()
                    normalized = scaler.fit_transform(detrended.reshape(-1, 1)).flatten()
                    
                    # Apply windowing
                    windowed = normalized * signal.windows.hann(len(normalized))
                    
                    # Compute FFT
                    fft_vals = np.abs(fft(windowed))
                    freqs = fftfreq(len(windowed), d=np.mean(np.diff(times)))
                    
                    # Focus on positive frequencies
                    pos_freqs = freqs[:len(freqs)//2]
                    pos_fft = fft_vals[:len(fft_vals)//2]
                    
                    # Find peaks with minimum distance constraint
                    peaks, properties = find_peaks(pos_fft, height=np.std(pos_fft), distance=5)
                    
                    if len(peaks) > 0:
                        periods = 1.0 / pos_freqs[peaks]
                        valid_periods = periods[periods > 0]
                        cyclicity_result['dominant_periods'].extend(valid_periods.tolist())
                        cyclicity_result['spectral_peaks'].extend(pos_fft[peaks].tolist())
                        cyclicity_result['cyclicity_strength'] = max(cyclicity_result['cyclicity_strength'],
                                                                   float(np.max(pos_fft[peaks]) / np.sum(pos_fft)))
                        
                except Exception as e:
                    self.logger.warning(f"FFT analysis failed: {e}")
            
            # C) Welch's method for robust power spectral density
            cyclicity_result['analysis_methods'].append('welch')
            try:
                if len(values) >= 20:  # Minimum required for Welch
                    freqs_welch, psd = welch(values, fs=1.0/np.mean(np.diff(times)), nperseg=min(len(values)//4, 256))
                    
                    peaks, _ = find_peaks(psd, height=np.percentile(psd, 75))
                    
                    if len(peaks) > 0:
                        periods_welch = 1.0 / freqs_welch[peaks]
                        valid_periods_welch = periods_welch[periods_welch > 0]
                        cyclicity_result['dominant_periods'].extend(valid_periods_welch.tolist())
                        
                        # Update strength if stronger signal found
                        welch_strength = np.max(psd[peaks]) / np.sum(psd)
                        cyclicity_result['cyclicity_strength'] = max(cyclicity_result['cyclicity_strength'], float(welch_strength))
                        
            except Exception as e:
                self.logger.warning(f"Welch analysis failed: {e}")
            
            # 2. GEOLOGICAL PATTERN RECOGNITION
            
            # A) Volcanic eruption cycles
            if parameter_type in ['volcanic', 'eruption', 'gas', 'deformation']:
                cyclicity_result['analysis_methods'].append('volcanic_pattern_recognition')
                volcanic_cycles = await self._detect_volcanic_cycles(times, values, location)
                if volcanic_cycles:
                    cyclicity_result['geological_context'] = volcanic_cycles
                    if volcanic_cycles.get('repose_periods'):
                        cyclicity_result['dominant_periods'].extend(volcanic_cycles['repose_periods'])
            
            # B) Seismic cycles
            elif parameter_type in ['seismic', 'earthquake', 'stress']:
                cyclicity_result['analysis_methods'].append('seismic_pattern_recognition')
                seismic_cycles = await self._detect_seismic_cycles(times, values, location)
                if seismic_cycles:
                    cyclicity_result['geological_context'] = seismic_cycles
                    if seismic_cycles.get('recurrence_intervals'):
                        cyclicity_result['dominant_periods'].extend(seismic_cycles['recurrence_intervals'])
            
            # C) Tidal and atmospheric cycles
            elif parameter_type in ['deformation', 'tilt', 'strain']:
                cyclicity_result['analysis_methods'].append('tidal_pattern_recognition')
                tidal_cycles = self._detect_tidal_atmospheric_cycles(times, values)
                if tidal_cycles:
                    cyclicity_result['geological_context'] = tidal_cycles
                    cyclicity_result['dominant_periods'].extend(tidal_cycles.get('periods', []))
            
            # 3. DATABASE CORRELATION
            if location and hasattr(self, 'database_managers'):
                try:
                    historical_cyclicity = await self._query_historical_cyclicity(
                        location, parameter_type, cyclicity_result['dominant_periods']
                    )
                    if historical_cyclicity:
                        cyclicity_result['database_correlation'] = historical_cyclicity
                        # Validate detected cycles against historical data
                        validated_strength = self._validate_cyclicity_with_history(
                            cyclicity_result['cyclicity_strength'],
                            historical_cyclicity
                        )
                        cyclicity_result['cyclicity_strength'] = validated_strength
                        
                except Exception as e:
                    self.logger.warning(f"Database cyclicity correlation failed: {e}")
            
            # 4. STATISTICAL SIGNIFICANCE TESTING
            if cyclicity_result['cyclicity_strength'] > 0:
                try:
                    # Monte Carlo significance test
                    n_bootstrap = 1000
                    bootstrap_strengths = []
                    
                    for _ in range(n_bootstrap):
                        # Shuffle values to destroy temporal patterns
                        shuffled_values = np.random.permutation(values)
                        
                        # Quick FFT analysis on shuffled data
                        fft_shuffled = np.abs(fft(shuffled_values))
                        if len(fft_shuffled) > 1:
                            max_strength = np.max(fft_shuffled[1:len(fft_shuffled)//2]) / np.sum(fft_shuffled)
                            bootstrap_strengths.append(max_strength)
                    
                    # Calculate p-value
                    p_value = np.mean(np.array(bootstrap_strengths) >= cyclicity_result['cyclicity_strength'])
                    cyclicity_result['statistical_significance'] = {
                        'p_value': float(p_value),
                        'significant': p_value < 0.05
                    }
                    
                    # Adjust strength based on significance
                    if p_value > 0.1:  # Not significant
                        cyclicity_result['cyclicity_strength'] *= 0.5
                        
                except Exception as e:
                    self.logger.warning(f"Statistical significance testing failed: {e}")
            
            # Remove duplicate periods and sort
            if cyclicity_result['dominant_periods']:
                unique_periods = list(set([float(p) for p in cyclicity_result['dominant_periods'] if p > 0]))
                cyclicity_result['dominant_periods'] = sorted(unique_periods)
            
            return float(cyclicity_result['cyclicity_strength'])
            
        except Exception as e:
            self.logger.error(f"Advanced cyclicity detection failed: {e}")
            # Fallback to basic FFT if advanced methods fail
            try:
                from scipy.fft import fft, fftfreq
                if len(values) >= 10:
                    fft_vals = np.abs(fft(values))
                    if len(fft_vals) > 2:
                        dominant_freq_idx = np.argmax(fft_vals[1:len(fft_vals)//2]) + 1
                        cyclicity_strength = fft_vals[dominant_freq_idx] / np.sum(fft_vals)
                        return float(cyclicity_strength)
            except:
                pass
            return 0
    
    async def _calculate_scale_interactions(self, local, regional, plate, location=None):
        """Advanced multi-scale geological interaction analysis with physics-based modeling"""
        try:
            from .geological_statistics import MultiScaleAnalysis, InteractionMetrics
            from .database_integration import DatabaseIntegration
            from .external_data_connectors import USGSConnector, GeologicalDataConnector
            from .plate_evolution_engine import PlateEvolutionEngine
            from .stress_field_mapper import StressFieldMapper
            from .geological_complexity_assessment import ComplexityAnalysis
            from sklearn.metrics import mutual_info_score
            from scipy.stats import pearsonr, spearmanr
            import asyncio
            
            interaction_analysis = {
                'complexity_score': 0.5,
                'coupling_strength': 0.0,
                'scale_hierarchy': [],
                'interaction_mechanisms': [],
                'database_validation': None,
                'physics_based_score': None
            }
            
            # 1. ENHANCED SCALE METRIC EXTRACTION
            local_metrics = self._extract_comprehensive_scale_metrics(local, 'local')
            regional_metrics = self._extract_comprehensive_scale_metrics(regional, 'regional') 
            plate_metrics = self._extract_comprehensive_scale_metrics(plate, 'plate')
            
            # 2. MULTI-DIMENSIONAL INTERACTION ANALYSIS
            
            # A) Statistical coupling analysis
            scale_vectors = {
                'local': np.array(list(local_metrics.values())),
                'regional': np.array(list(regional_metrics.values())),
                'plate': np.array(list(plate_metrics.values()))
            }
            
            # Cross-correlations between scales
            correlations = {}
            for scale1 in scale_vectors:
                for scale2 in scale_vectors:
                    if scale1 != scale2:
                        try:
                            corr, p_value = pearsonr(scale_vectors[scale1], scale_vectors[scale2])
                            correlations[f'{scale1}_{scale2}'] = {'correlation': float(corr), 'p_value': float(p_value)}
                        except:
                            correlations[f'{scale1}_{scale2}'] = {'correlation': 0.0, 'p_value': 1.0}
            
            # B) Mutual information analysis
            try:
                mutual_info = {}
                for scale1 in scale_vectors:
                    for scale2 in scale_vectors:
                        if scale1 != scale2:
                            # Discretize for mutual information
                            v1_discrete = np.digitize(scale_vectors[scale1], bins=5)
                            v2_discrete = np.digitize(scale_vectors[scale2], bins=5)
                            mi = mutual_info_score(v1_discrete, v2_discrete)
                            mutual_info[f'{scale1}_{scale2}'] = float(mi)
                
                interaction_analysis['coupling_strength'] = np.mean(list(mutual_info.values()))
                
            except Exception as e:
                self.logger.warning(f"Mutual information analysis failed: {e}")
            
            # 3. PHYSICS-BASED INTERACTION MODELING
            
            if location:
                try:
                    # Stress field coupling analysis
                    stress_mapper = StressFieldMapper()
                    
                    # Local stress perturbations
                    local_stress = stress_mapper.calculate_local_stress_field(
                        location, local_metrics
                    )
                    
                    # Regional stress influences  
                    regional_stress = stress_mapper.calculate_regional_stress_influence(
                        location, regional_metrics
                    )
                    
                    # Plate-scale tectonic loading
                    plate_stress = stress_mapper.calculate_plate_stress_loading(
                        location, plate_metrics
                    )
                    
                    # Stress interaction tensor analysis
                    stress_interaction = stress_mapper.analyze_stress_interactions(
                        local_stress, regional_stress, plate_stress
                    )
                    
                    interaction_analysis['physics_based_score'] = stress_interaction.get('interaction_strength', 0.5)
                    interaction_analysis['interaction_mechanisms'].append('stress_field_coupling')
                    
                except Exception as e:
                    self.logger.warning(f"Stress field analysis failed: {e}")
            
            # 4. GEOLOGICAL DATABASE INTEGRATION
            
            if hasattr(self, 'database_managers') and location:
                try:
                    db_manager = self.database_managers.get('postgresql')
                    if db_manager:
                        # Query multi-scale geological interactions from database
                        interaction_query = """
                        SELECT 
                            interaction_type,
                            local_dominance,
                            regional_influence, 
                            plate_control,
                            coupling_strength,
                            complexity_index
                        FROM multi_scale_interactions msi
                        JOIN geological_locations gl ON ST_DWithin(gl.location, ST_Point(%s, %s), 50000)
                        WHERE msi.location_id = gl.id
                        ORDER BY coupling_strength DESC
                        LIMIT 10
                        """
                        
                        lat, lon = location if isinstance(location, (list, tuple)) else (0, 0)
                        db_results = await db_manager.execute_query_async(interaction_query, (lon, lat))
                        
                        if db_results:
                            # Calculate database-informed complexity
                            db_complexity_scores = [r['complexity_index'] for r in db_results if r['complexity_index']]
                            if db_complexity_scores:
                                interaction_analysis['database_validation'] = {
                                    'historical_complexity': float(np.mean(db_complexity_scores)),
                                    'complexity_std': float(np.std(db_complexity_scores)),
                                    'sample_size': len(db_complexity_scores)
                                }
                                
                                # Bias toward database-informed values
                                db_weight = 0.3
                                current_complexity = interaction_analysis['complexity_score']
                                db_complexity = np.mean(db_complexity_scores)
                                
                                interaction_analysis['complexity_score'] = (
                                    (1 - db_weight) * current_complexity + db_weight * db_complexity
                                )
                                
                except Exception as e:
                    self.logger.warning(f"Database integration failed: {e}")
            
            # 5. EXTERNAL DATA VALIDATION
            
            if hasattr(self, 'external_data_connectors') and location:
                try:
                    usgs_connector = self.external_data_connectors.get('usgs_earthquakes')
                    if usgs_connector:
                        # Query recent seismic activity for scale interaction validation
                        seismic_data = await usgs_connector.query_seismic_activity(
                            location=location,
                            time_window_days=365,
                            magnitude_threshold=2.0
                        )
                        
                        if seismic_data:
                            # Analyze multi-scale seismic patterns
                            seismic_interaction = self._analyze_seismic_scale_interactions(seismic_data)
                            if seismic_interaction:
                                interaction_analysis['interaction_mechanisms'].append('seismic_coupling')
                                # Incorporate seismic evidence into complexity score
                                seismic_weight = 0.2
                                interaction_analysis['complexity_score'] = (
                                    interaction_analysis['complexity_score'] * (1 - seismic_weight) +
                                    seismic_interaction.get('complexity', 0.5) * seismic_weight
                                )
                                
                except Exception as e:
                    self.logger.warning(f"External seismic validation failed: {e}")
            
            # 6. ADVANCED COMPLEXITY METRICS
            
            # Hierarchical interaction strength
            try:
                scale_values = [local_metrics, regional_metrics, plate_metrics]
                
                # Calculate hierarchical coupling
                hierarchical_coupling = self._calculate_hierarchical_coupling(scale_values)
                
                # Information-theoretic complexity
                information_complexity = self._calculate_information_complexity(scale_values)
                
                # Fractal dimension analysis
                fractal_complexity = self._calculate_fractal_complexity(scale_values)
                
                # Combine complexity measures
                complexity_measures = [
                    interaction_analysis['complexity_score'],
                    hierarchical_coupling,
                    information_complexity,
                    fractal_complexity
                ]
                
                # Robust complexity estimate (median)
                interaction_analysis['complexity_score'] = float(np.median([c for c in complexity_measures if not np.isnan(c)]))
                
                # Establish scale hierarchy
                scale_strengths = {
                    'local': np.mean(list(local_metrics.values())),
                    'regional': np.mean(list(regional_metrics.values())),
                    'plate': np.mean(list(plate_metrics.values()))
                }
                
                interaction_analysis['scale_hierarchy'] = sorted(
                    scale_strengths.items(), key=lambda x: x[1], reverse=True
                )
                
            except Exception as e:
                self.logger.warning(f"Advanced complexity calculation failed: {e}")
            
            # 7. FINAL VALIDATION AND BOUNDS CHECK
            
            # Ensure complexity score is within reasonable bounds
            interaction_analysis['complexity_score'] = max(0.0, min(2.0, interaction_analysis['complexity_score']))
            
            # Add confidence metrics
            interaction_analysis['confidence_metrics'] = {
                'data_completeness': self._assess_data_completeness(local, regional, plate),
                'method_consistency': len(interaction_analysis['interaction_mechanisms']) / 5.0,  # Max 5 methods
                'database_support': 1.0 if interaction_analysis['database_validation'] else 0.5
            }
            
            return float(interaction_analysis['complexity_score'])
            
        except Exception as e:
            self.logger.error(f"Advanced scale interaction analysis failed: {e}")
            # Enhanced fallback calculation
            try:
                scales = [
                    local.get('dominance_score', 0.5) if isinstance(local, dict) else 0.5,
                    regional.get('influence_factor', 0.5) if isinstance(regional, dict) else 0.5,
                    plate.get('control_factor', 0.5) if isinstance(plate, dict) else 0.5
                ]
                # Use coefficient of variation instead of standard deviation for scale-invariant measure
                mean_scale = np.mean(scales)
                if mean_scale > 0:
                    return float(np.std(scales) / mean_scale)
                else:
                    return float(np.std(scales))
            except:
                return 0.5
    
    def _identify_dominant_scale(self, local, regional, plate):
        """Identify the dominant tectonic scale"""
        scales = {
            'local': local.get('dominance_score', 0.5),
            'regional': regional.get('influence_factor', 0.5),
            'plate': plate.get('control_factor', 0.5)
        }
        return max(scales, key=scales.get)
    
    def _estimate_b_value(self, magnitudes):
        """Estimate Gutenberg-Richter b-value"""
        try:
            if len(magnitudes) < 5:
                return 1.0
            
            # Simple b-value estimation using maximum likelihood
            mags = np.array([m for m in magnitudes if m > 0])
            if len(mags) == 0:
                return 1.0
            
            min_mag = np.min(mags)
            mean_mag = np.mean(mags)
            
            b_value = 1.0 / (np.log(10) * (mean_mag - min_mag + 0.05))
            return float(max(0.3, min(2.0, b_value)))  # Reasonable bounds
            
        except:
            return 1.0
    
