    async def _monitor_feature_extraction_performance(self, method_name, execution_time, result, error=None):
        """Monitor performance of feature extraction methods"""
        try:
            if not hasattr(self, 'monitoring_pipeline'):
                return
            
            # Record performance metrics
            from datetime import datetime
            metrics = {
                'method_name': method_name,
                'execution_time': execution_time,
                'success': error is None,
                'result_size': len(result) if isinstance(result, dict) else 0,
                'error_type': type(error).__name__ if error else None,
                'timestamp': datetime.now().isoformat()
            }
            
            await self.monitoring_pipeline.log_performance_metrics(
                component_name=method_name,
                metrics=metrics
            )
            
            # Check for performance alerts
            if execution_time > 10.0:  # Alert if extraction takes > 10 seconds
                await self.monitoring_pipeline.trigger_alert(
                    alert_type='performance_degradation',
                    component=method_name,
                    message=f"Feature extraction taking {execution_time:.2f}s",
                    severity='warning'
                )
            
            if error:
                await self.monitoring_pipeline.trigger_alert(
                    alert_type='extraction_error',
                    component=method_name,
                    message=f"Feature extraction failed: {error}",
                    severity='error'
                )
            
        except Exception as e:
            self.logger.error(f"Performance monitoring failed: {e}")
    
