    async def _validate_against_seismicity(self, stress, earthquake_data):
        """Validate stress against regional seismicity"""
        try:
            if not earthquake_data:
                return {'validation_score': 0.5, 'note': 'no_seismic_data'}
            
            # Analyze stress orientation consistency with focal mechanisms
            stress_orientation = stress.get('orientation', 0)
            focal_mechanisms = [eq.get('focal_mechanism', {}) for eq in earthquake_data if 'focal_mechanism' in eq]
            
            if focal_mechanisms:
                orientation_consistency = self._calculate_orientation_consistency(
                    stress_orientation, focal_mechanisms
                )
                return {
                    'validation_score': orientation_consistency,
                    'earthquakes_analyzed': len(focal_mechanisms),
                    'orientation_match': orientation_consistency > 0.7
                }
            
            return {'validation_score': 0.5, 'note': 'no_focal_mechanism_data'}
        except Exception as e:
            self.logger.error(f"Seismicity validation failed: {e}")
            return {'validation_score': 0.3, 'error': str(e)}
    
    def _calculate_orientation_consistency(self, stress_orientation, focal_mechanisms):
        """Calculate consistency between stress orientation and focal mechanisms"""
        if not focal_mechanisms:
            return 0.5
        
        # Extract P and T axes from focal mechanisms
        p_axes = []
        for fm in focal_mechanisms:
            if 'p_axis' in fm:
                p_axes.append(fm['p_axis'].get('azimuth', 0))
        
        if not p_axes:
            return 0.5
        
        # Calculate angular differences
        angular_diffs = [abs(stress_orientation - p_axis) for p_axis in p_axes]
        angular_diffs = [min(diff, 360 - diff) for diff in angular_diffs]  # Handle wraparound
        
        # Convert to consistency score (smaller differences = higher consistency)
        consistency_scores = [1.0 - (diff / 90.0) for diff in angular_diffs]  # 90° is quarter circle
        consistency_scores = [max(0, score) for score in consistency_scores]
        
        return np.mean(consistency_scores) if consistency_scores else 0.5
    
    async def _validate_against_geodetic_strain(self, stress, geodetic_data):
        """Validate stress against geodetic strain measurements"""
        try:
            if not geodetic_data:
                return {'validation_score': 0.5, 'note': 'no_geodetic_data'}
            
            # Extract strain rates and orientations
            strain_rates = [gd.get('strain_rate', {}) for gd in geodetic_data if 'strain_rate' in gd]
            
            if strain_rates:
                strain_consistency = self._calculate_strain_stress_consistency(
                    stress, strain_rates
                )
                return {
                    'validation_score': strain_consistency,
                    'strain_measurements': len(strain_rates),
                    'strain_match': strain_consistency > 0.6
                }
            
            return {'validation_score': 0.5, 'note': 'no_strain_rate_data'}
        except Exception as e:
            self.logger.error(f"Geodetic strain validation failed: {e}")
            return {'validation_score': 0.3, 'error': str(e)}
    
    def _calculate_strain_stress_consistency(self, stress, strain_rates):
        """Calculate consistency between stress and strain rates"""
        stress_magnitude = stress.get('magnitude', 0)
        stress_orientation = stress.get('orientation', 0)
        
        consistency_scores = []
        for strain_rate in strain_rates:
            if 'principal_strain_rate' in strain_rate and 'orientation' in strain_rate:
                # Simple consistency check based on orientation alignment
                strain_orientation = strain_rate['orientation']
                angular_diff = abs(stress_orientation - strain_orientation)
                angular_diff = min(angular_diff, 360 - angular_diff)
                
                orientation_consistency = 1.0 - (angular_diff / 90.0)
                consistency_scores.append(max(0, orientation_consistency))
        
        return np.mean(consistency_scores) if consistency_scores else 0.5
    
    def _extract_stress_matrix(self, stress):
        """Extract stress tensor matrix from stress data"""
        try:
            if 'tensor_matrix' in stress:
                return np.array(stress['tensor_matrix'])
            elif 'principal_stresses' in stress:
                # Create diagonal matrix from principal stresses
                principal = stress['principal_stresses']
                if len(principal) >= 3:
                    return np.diag(principal[:3])
            
            # Create approximate matrix from magnitude and orientation
            magnitude = stress.get('magnitude', 0)
            return np.diag([magnitude, magnitude * 0.7, magnitude * 0.4])
        except Exception:
            return np.eye(3)
    
    async def _extract_stress_vector(self, stress):
        """Extract comprehensive stress vector representation with advanced tensor analysis and database integration"""
        try:
            from .geological_statistics import GeologicalStatistics
            from scipy.spatial.transform import Rotation as R
            import asyncio
            
            # Initialize advanced analysis components
            stress_analysis = {
                'tensor_components': np.zeros(6),  # [σxx, σyy, σzz, σxy, σxz, σyz] Voigt notation
                'principal_stresses': np.zeros(3),
                'principal_directions': np.eye(3),
                'stress_invariants': {},
                'strain_energy_density': 0.0,
                'von_mises_equivalent': 0.0,
                'tresca_equivalent': 0.0,
                'hydrostatic_stress': 0.0,
                'deviatoric_stress': np.zeros((3, 3)),
                'stress_anisotropy': {},
                'confidence_metrics': {},
                'database_validation': {}
            }
            
            # Process different stress input formats
            if isinstance(stress, dict):
                # Extract comprehensive tensor from dictionary format
                magnitude = stress.get('magnitude', 0)
                orientation = stress.get('orientation', 0)  # azimuth in degrees
                plunge = stress.get('plunge', 0)  # plunge angle in degrees
                
                # Extract additional stress components if available
                tensor_full = stress.get('tensor', None)
                principal = stress.get('principal_stresses', None)
                
                if tensor_full is not None:
                    # Full stress tensor provided
                    tensor_array = np.asarray(tensor_full)
                    if tensor_array.shape == (3, 3):
                        stress_analysis['tensor_components'] = np.array([
                            tensor_array[0,0], tensor_array[1,1], tensor_array[2,2],
                            tensor_array[0,1], tensor_array[0,2], tensor_array[1,2]
                        ])
                    elif tensor_array.shape == (6,):
                        stress_analysis['tensor_components'] = tensor_array.copy()
                        
                elif principal is not None:
                    # Principal stresses provided
                    principal_array = np.asarray(principal)
                    if len(principal_array) >= 3:
                        stress_analysis['principal_stresses'] = principal_array[:3]
                        # Construct tensor in principal coordinate system
                        stress_analysis['tensor_components'][:3] = principal_array[:3]
                        
                else:
                    # Construct from magnitude and orientation
                    if magnitude > 0:
                        # Convert orientation to stress tensor using advanced geomechanics
                        azimuth_rad = np.radians(orientation)
                        plunge_rad = np.radians(plunge)
                        
                        # Calculate direction cosines for principal stress
                        l = np.cos(plunge_rad) * np.cos(azimuth_rad)
                        m = np.cos(plunge_rad) * np.sin(azimuth_rad)
                        n = np.sin(plunge_rad)
                        
                        # Assume maximum principal stress in this direction
                        # with appropriate stress ratios based on tectonic regime
                        tectonic_regime = stress.get('regime', 'normal_faulting')
                        stress_ratios = self._get_stress_ratios_for_regime(tectonic_regime)
                        
                        sigma_1 = magnitude
                        sigma_2 = magnitude * stress_ratios['s2_s1_ratio']
                        sigma_3 = magnitude * stress_ratios['s3_s1_ratio']
                        
                        stress_analysis['principal_stresses'] = np.array([sigma_1, sigma_2, sigma_3])
                        stress_analysis['principal_directions'] = np.array([[l, m, n],
                                                                          [-m, l, 0],  # perpendicular horizontal
                                                                          [-l*n, -m*n, l*l+m*m]])  # vertical
            
            elif isinstance(stress, (np.ndarray, list)):
                stress_array = np.asarray(stress)
                if stress_array.size == 3:
                    stress_analysis['principal_stresses'] = stress_array
                    stress_analysis['tensor_components'][:3] = stress_array
                elif stress_array.size == 6:
                    stress_analysis['tensor_components'] = stress_array
                elif stress_array.shape == (3, 3):
                    stress_analysis['tensor_components'] = np.array([
                        stress_array[0,0], stress_array[1,1], stress_array[2,2],
                        stress_array[0,1], stress_array[0,2], stress_array[1,2]
                    ])
            
            # Calculate advanced stress metrics
            await self._calculate_advanced_stress_metrics(stress_analysis)
            
            # Database validation against regional stress measurements
            if hasattr(self, '_db_integration') and self._db_integration:
                location = stress.get('location', {}) if isinstance(stress, dict) else {}
                lat = location.get('latitude', 0)
                lon = location.get('longitude', 0)
                depth = location.get('depth', 0)
                
                db_validation = await self._validate_stress_against_database(
                    stress_analysis, lat, lon, depth
                )
                stress_analysis['database_validation'] = db_validation
            
            # Uncertainty quantification using geological statistics
            if hasattr(self, '_geo_stats') and self._geo_stats:
                uncertainty_analysis = await self._quantify_stress_uncertainty(
                    stress_analysis
                )
                stress_analysis['confidence_metrics'] = uncertainty_analysis
            
            return stress_analysis
            
        except Exception as e:
            self.logger.error(f"Advanced stress vector extraction failed: {e}")
            # Fallback to basic stress vector
            basic_stress = np.array([1e6, 0, 0])  # 1 MPa default
            if isinstance(stress, dict):
                basic_stress[0] = stress.get('magnitude', 1e6)
                basic_stress[1] = stress.get('orientation', 0)
                basic_stress[2] = stress.get('plunge', 0)
            
            return {
                'tensor_components': np.array([basic_stress[0], basic_stress[0]*0.7, basic_stress[0]*0.4, 0, 0, 0]),
                'principal_stresses': np.array([basic_stress[0], basic_stress[0]*0.7, basic_stress[0]*0.4]),
                'error': str(e),
                'fallback_mode': True
            }
    
