    def _detect_validation_outliers(self, score_values):
        """Detect outliers in validation scores using multiple methods"""
        try:
            from sklearn.ensemble import IsolationForest
            import scipy.stats as stats
            
            scores = np.array(score_values)
            if len(scores) < 3:
                return {'outliers_detected': False, 'method': 'insufficient_data'}
            
            outlier_results = {}
            
            # Method 1: Statistical outliers (Z-score)
            z_scores = np.abs(stats.zscore(scores))
            z_outliers = z_scores > 2.5
            outlier_results['z_score'] = {
                'outliers_detected': bool(np.any(z_outliers)),
                'outlier_indices': np.where(z_outliers)[0].tolist(),
                'z_scores': z_scores.tolist()
            }
            
            # Method 2: IQR method
            Q1, Q3 = np.percentile(scores, [25, 75])
            IQR = Q3 - Q1
            lower_bound = Q1 - 1.5 * IQR
            upper_bound = Q3 + 1.5 * IQR
            iqr_outliers = (scores < lower_bound) | (scores > upper_bound)
            outlier_results['iqr'] = {
                'outliers_detected': bool(np.any(iqr_outliers)),
                'outlier_indices': np.where(iqr_outliers)[0].tolist(),
                'bounds': {'lower': float(lower_bound), 'upper': float(upper_bound)}
            }
            
            # Method 3: Isolation Forest (if sufficient data)
            if len(scores) >= 5:
                try:
                    iso_forest = IsolationForest(contamination=0.1, random_state=42)
                    outlier_labels = iso_forest.fit_predict(scores.reshape(-1, 1))
                    iso_outliers = outlier_labels == -1
                    outlier_results['isolation_forest'] = {
                        'outliers_detected': bool(np.any(iso_outliers)),
                        'outlier_indices': np.where(iso_outliers)[0].tolist()
                    }
                except:
                    outlier_results['isolation_forest'] = {'error': 'computation_failed'}
            
            return outlier_results
            
        except Exception as e:
            return {'error': str(e), 'outliers_detected': False}
    
    def _calculate_weighted_validation_score(self, scores):
        """Calculate weighted aggregate validation score"""
        try:
            total_weight = 0
            weighted_sum = 0
            confidence_sum = 0
            
            weights = {
                'usgs_seismic': 1.2,
                'world_stress_map': 1.0,
                'regional_surveys': 1.1,
                'literature_database': 0.8,
                'monitoring_networks': 1.3
            }
            
            for score_data in scores:
                if isinstance(score_data, dict) and 'score' in score_data:
                    source = score_data.get('data_source', 'unknown')
                    weight = weights.get(source, 1.0)
                    confidence = score_data.get('confidence', 0.5)
                    
                    adjusted_weight = weight * confidence
                    weighted_sum += score_data['score'] * adjusted_weight
                    total_weight += adjusted_weight
                    confidence_sum += confidence
            
            if total_weight > 0:
                weighted_score = weighted_sum / total_weight
                avg_confidence = confidence_sum / len(scores)
                
                return {
                    'weighted_score': float(weighted_score),
                    'total_weight': float(total_weight),
                    'average_confidence': float(avg_confidence),
                    'sources_count': len(scores)
                }
            else:
                return {
                    'weighted_score': 0.5,
                    'total_weight': 0.0,
                    'average_confidence': 0.3,
                    'sources_count': 0
                }
                
        except Exception as e:
            return {
                'weighted_score': 0.5,
                'error': str(e),
                'sources_count': len(scores) if isinstance(scores, (list, tuple)) else 0
            }
    
    def _calculate_validation_confidence(self, scores):
        """Calculate comprehensive confidence metrics"""
        try:
            if not scores:
                return {'overall_confidence': 0.3, 'confidence_factors': []}
            
            confidence_factors = []
            
            # Factor 1: Number of validation sources
            source_count = len(scores)
            source_confidence = min(1.0, source_count / 5.0)  # Normalize to max 5 sources
            confidence_factors.append({'factor': 'source_count', 'value': source_confidence})
            
            # Factor 2: Agreement between sources
            score_values = [s.get('score', 0) for s in scores if isinstance(s, dict)]
            if len(score_values) > 1:
                agreement = 1.0 - (np.std(score_values) / np.mean(score_values) if np.mean(score_values) > 0 else 0.5)
                confidence_factors.append({'factor': 'source_agreement', 'value': float(agreement)})
            
            # Factor 3: Individual source confidences
            individual_confidences = [s.get('confidence', 0.5) for s in scores if isinstance(s, dict)]
            if individual_confidences:
                mean_individual_confidence = np.mean(individual_confidences)
                confidence_factors.append({'factor': 'individual_confidence', 'value': float(mean_individual_confidence)})
            
            # Factor 4: Data quality indicators
            quality_indicators = []
            for score_data in scores:
                if isinstance(score_data, dict):
                    if score_data.get('measurements_count', 0) > 10:
                        quality_indicators.append(0.8)
                    elif score_data.get('studies_analyzed', 0) > 5:
                        quality_indicators.append(0.7)
                    elif 'error' not in score_data:
                        quality_indicators.append(0.6)
                    else:
                        quality_indicators.append(0.3)
            
            if quality_indicators:
                data_quality = np.mean(quality_indicators)
                confidence_factors.append({'factor': 'data_quality', 'value': float(data_quality)})
            
            # Calculate overall confidence
            if confidence_factors:
                factor_values = [cf['value'] for cf in confidence_factors]
                overall_confidence = np.mean(factor_values)
            else:
                overall_confidence = 0.3
            
            return {
                'overall_confidence': float(overall_confidence),
                'confidence_factors': confidence_factors,
                'confidence_level': 'high' if overall_confidence > 0.8 else 'medium' if overall_confidence > 0.5 else 'low'
            }
            
        except Exception as e:
            return {
                'overall_confidence': 0.3,
                'error': str(e),
                'confidence_level': 'low'
            }
    
    async def _calculate_physical_score(self, physics_checks):
        """Calculate comprehensive physics-informed consistency score with real data integration"""
        try:
            from scipy.stats import norm
            from scipy.spatial.distance import euclidean
            import asyncio
            
            # Initialize database connection for real-time physics constraints
            if not hasattr(self, 'physics_db_manager'):
                await self._initialize_physics_database_connections()
            
            # Initialize external data connectors for constraint validation
            if not hasattr(self, 'physics_data_connectors'):
                await self._initialize_physics_data_connectors()
            
            total_score = 0.0
            weight_sum = 0.0
            detailed_scores = {}
            
            # 1. Stress tensor physics constraints (25% weight)
            if 'stress_tensor' in physics_checks:
                stress_score = await self._evaluate_stress_tensor_physics(
                    physics_checks['stress_tensor']
                )
                total_score += stress_score * 0.25
                weight_sum += 0.25
                detailed_scores['stress_tensor_physics'] = stress_score
            
            # 2. Deformation compatibility (20% weight)
            if 'deformation_tensor' in physics_checks:
                deformation_score = await self._evaluate_deformation_compatibility(
                    physics_checks['deformation_tensor']
                )
                total_score += deformation_score * 0.20
                weight_sum += 0.20
                detailed_scores['deformation_compatibility'] = deformation_score
            
            # 3. Thermodynamic consistency (15% weight)
            if 'temperature' in physics_checks and 'pressure' in physics_checks:
                thermo_score = await self._evaluate_thermodynamic_constraints(
                    physics_checks['temperature'], physics_checks['pressure']
                )
                total_score += thermo_score * 0.15
                weight_sum += 0.15
                detailed_scores['thermodynamic_consistency'] = thermo_score
            
            # 4. Elastic moduli relationships (15% weight)
            if 'elastic_properties' in physics_checks:
                elastic_score = await self._evaluate_elastic_physics(
                    physics_checks['elastic_properties']
                )
                total_score += elastic_score * 0.15
                weight_sum += 0.15
                detailed_scores['elastic_physics'] = elastic_score
            
            # 5. Geological process consistency (10% weight)
            if 'geological_process' in physics_checks:
                process_score = await self._evaluate_geological_process_physics(
                    physics_checks['geological_process']
                )
                total_score += process_score * 0.10
                weight_sum += 0.10
                detailed_scores['geological_process_physics'] = process_score
            
            # 6. Field observations validation (10% weight)
            if 'field_observations' in physics_checks:
                field_score = await self._validate_against_field_observations(
                    physics_checks['field_observations']
                )
                total_score += field_score * 0.10
                weight_sum += 0.10
                detailed_scores['field_validation'] = field_score
            
            # 7. Multi-physics coupling (5% weight)
            if len(physics_checks) > 1:
                coupling_score = await self._evaluate_multi_physics_coupling(physics_checks)
                total_score += coupling_score * 0.05
                weight_sum += 0.05
                detailed_scores['multi_physics_coupling'] = coupling_score
            
            # Normalize score
            final_score = total_score / weight_sum if weight_sum > 0 else 0.5
            
            # Apply uncertainty quantification
            uncertainty = await self._quantify_physics_score_uncertainty(
                physics_checks, detailed_scores
            )
            
            # Store results in database for analysis tracking
            await self._store_physics_score_results({
                'final_score': final_score,
                'detailed_scores': detailed_scores,
                'uncertainty': uncertainty,
                'timestamp': datetime.now(),
                'input_checks': len(physics_checks)
            })
            
            return {
                'score': final_score,
                'detailed_scores': detailed_scores,
                'uncertainty': uncertainty,
                'confidence_level': 'high' if uncertainty < 0.1 else 'medium' if uncertainty < 0.2 else 'low'
            }
            
        except Exception as e:
            self.logger.error(f"Physics score calculation failed: {e}")
            return {
                'score': 0.3,
                'error': str(e),
                'confidence_level': 'low',
                'fallback_used': True
            }
    
