    async def _evaluate_stress_tensor_physics(self, stress_tensor):
        """Evaluate stress tensor against known physics constraints"""
        try:
            score = 1.0
            
            # Extract tensor components
            if isinstance(stress_tensor, dict):
                sigma_xx = stress_tensor.get('xx', 0)
                sigma_yy = stress_tensor.get('yy', 0)
                sigma_zz = stress_tensor.get('zz', 0)
                sigma_xy = stress_tensor.get('xy', 0)
                sigma_xz = stress_tensor.get('xz', 0)
                sigma_yz = stress_tensor.get('yz', 0)
            else:
                # Assume 3x3 numpy array
                sigma_xx, sigma_yy, sigma_zz = stress_tensor[0,0], stress_tensor[1,1], stress_tensor[2,2]
                sigma_xy, sigma_xz, sigma_yz = stress_tensor[0,1], stress_tensor[0,2], stress_tensor[1,2]
            
            # Physics constraint 1: Realistic stress magnitudes for geological environments
            stress_magnitudes = [abs(sigma_xx), abs(sigma_yy), abs(sigma_zz)]
            max_stress = max(stress_magnitudes)
            
            if max_stress > 1e9:  # > 1 GPa - unrealistic for most geological settings
                score *= 0.3
            elif max_stress > 5e8:  # > 500 MPa - high but possible in deep crust
                score *= 0.7
            elif max_stress < 1e6:  # < 1 MPa - very low stress
                score *= 0.8
            
            # Physics constraint 2: Shear stress limitations (Tresca criterion)
            max_shear = max([abs(sigma_xy), abs(sigma_xz), abs(sigma_yz)])
            principal_diff = max(stress_magnitudes) - min(stress_magnitudes)
            
            if max_shear > 0.5 * principal_diff:  # Violates Tresca criterion
                score *= 0.4
            
            # Physics constraint 3: Validate against regional stress database
            if self.physics_db_manager:
                regional_stress = await self._get_regional_stress_constraints()
                if regional_stress:
                    regional_score = self._compare_with_regional_stress(
                        stress_tensor, regional_stress
                    )
                    score *= regional_score
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Stress tensor physics evaluation failed: {e}")
            return 0.5
    
    async def _evaluate_deformation_compatibility(self, deformation_tensor):
        """Evaluate deformation tensor compatibility constraints"""
        try:
            score = 1.0
            
            # Saint-Venant compatibility equations for small strain theory
            if isinstance(deformation_tensor, np.ndarray) and deformation_tensor.shape == (3, 3):
                # Symmetric strain tensor requirement
                asymmetry = np.linalg.norm(deformation_tensor - deformation_tensor.T)
                if asymmetry > 1e-6:
                    score *= 0.6  # Penalize non-symmetric strain tensors
                
                # Compatibility constraint: ∇²ε_ij + ∂²ε_kk/∂x_i∂x_j = ∂²ε_ik/∂x_j∂x_k + ∂²ε_jk/∂x_i∂x_k
                # Simplified check: trace should be reasonable for geological deformation
                trace = np.trace(deformation_tensor)
                if abs(trace) > 0.1:  # Volumetric strain > 10%
                    score *= 0.7
                
                # Check eigenvalues for physical realizability
                eigenvalues = np.linalg.eigvals(deformation_tensor)
                if any(abs(ev) > 0.5 for ev in eigenvalues):  # Very large strains
                    score *= 0.5
            
            # Validate against deformation database
            if self.physics_db_manager:
                deformation_constraints = await self._get_deformation_constraints()
                if deformation_constraints:
                    constraint_score = self._validate_deformation_constraints(
                        deformation_tensor, deformation_constraints
                    )
                    score *= constraint_score
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Deformation compatibility evaluation failed: {e}")
            return 0.5
    
    async def _evaluate_thermodynamic_constraints(self, temperature, pressure):
        """Evaluate thermodynamic consistency with geological conditions"""
        try:
            score = 1.0
            
            # Temperature constraints
            if temperature < 273.15:  # Below freezing
                score *= 0.8
            elif temperature > 1800:  # Above mantle temperatures
                score *= 0.3
            elif temperature > 1200:  # Very high crustal temperatures
                score *= 0.7
            
            # Pressure constraints
            if pressure < 0:  # Negative pressure (tension)
                score *= 0.4
            elif pressure > 15e9:  # > 150 kbar - lower mantle pressures
                score *= 0.3
            elif pressure > 3e9:  # > 30 kbar - deep crustal pressures
                score *= 0.8
            
            # Geotherm consistency
            expected_temp = await self._calculate_geotherm_temperature(pressure)
            if expected_temp and abs(temperature - expected_temp) / expected_temp > 0.5:
                score *= 0.6  # Temperature-pressure inconsistency
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Thermodynamic constraint evaluation failed: {e}")
            return 0.5
    
    async def _evaluate_elastic_physics(self, elastic_properties):
        """Evaluate elastic property relationships"""
        try:
            score = 1.0
            
            if isinstance(elastic_properties, dict):
                young_modulus = elastic_properties.get('E', 0)
                poisson_ratio = elastic_properties.get('nu', 0)
                shear_modulus = elastic_properties.get('G', 0)
                bulk_modulus = elastic_properties.get('K', 0)
                
                # Poisson's ratio bounds (-1 < ν < 0.5 for stability)
                if poisson_ratio <= -1 or poisson_ratio >= 0.5:
                    score *= 0.2
                elif poisson_ratio < 0 or poisson_ratio > 0.45:
                    score *= 0.6
                
                # Elastic moduli relationships
                if young_modulus > 0 and shear_modulus > 0:
                    expected_g = young_modulus / (2 * (1 + poisson_ratio))
                    if abs(shear_modulus - expected_g) / expected_g > 0.2:
                        score *= 0.7
                
                if bulk_modulus > 0 and young_modulus > 0:
                    expected_k = young_modulus / (3 * (1 - 2 * poisson_ratio))
                    if abs(bulk_modulus - expected_k) / expected_k > 0.2:
                        score *= 0.7
                
                # Realistic ranges for geological materials
                if young_modulus > 500e9 or young_modulus < 1e6:
                    score *= 0.5
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Elastic physics evaluation failed: {e}")
            return 0.5
    
    async def _evaluate_geological_process_physics(self, geological_process):
        """Evaluate geological process consistency"""
        try:
            score = 1.0
            
            process_type = geological_process.get('type', '')
            timescale = geological_process.get('timescale', 0)
            magnitude = geological_process.get('magnitude', 0)
            
            # Process-specific physics constraints
            if process_type == 'volcanic_eruption':
                if timescale < 3600 or timescale > 3.15e7:  # 1 hour to 1 year
                    score *= 0.7
                if magnitude < 1e12 or magnitude > 1e18:  # Energy range for eruptions
                    score *= 0.6
                    
            elif process_type == 'earthquake':
                if timescale < 1 or timescale > 600:  # Seconds to minutes
                    score *= 0.8
                if magnitude < 1e6 or magnitude > 1e18:  # Energy range for earthquakes
                    score *= 0.5
                    
            elif process_type == 'mountain_building':
                if timescale < 3.15e13 or timescale > 3.15e15:  # Million to 100 million years
                    score *= 0.6
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Geological process physics evaluation failed: {e}")
            return 0.5
    
    async def _validate_against_field_observations(self, field_observations):
        """Validate against real field observation database"""
        try:
            if not self.physics_data_connectors:
                return 0.7  # Neutral score if no connectors available
            
            score = 1.0
            
            # Query USGS database for regional observations
            usgs_connector = self.physics_data_connectors.get('usgs')
            if usgs_connector and 'location' in field_observations:
                location = field_observations['location']
                regional_data = await usgs_connector.get_regional_geological_data(
                    lat=location.get('lat', 0),
                    lon=location.get('lon', 0),
                    radius_km=50
                )
                
                if regional_data:
                    consistency_score = self._compare_with_regional_observations(
                        field_observations, regional_data
                    )
                    score *= consistency_score
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Field observation validation failed: {e}")
            return 0.6
    
    async def _evaluate_multi_physics_coupling(self, physics_checks):
        """Evaluate multi-physics coupling consistency"""
        try:
            score = 1.0
            
            # Check thermal-mechanical coupling
            if 'temperature' in physics_checks and 'stress_tensor' in physics_checks:
                temp = physics_checks['temperature']
                stress = physics_checks['stress_tensor']
                
                # High temperature should correlate with thermal stress
                if temp > 800 and isinstance(stress, dict):
                    thermal_stress_expected = (temp - 273.15) * 2e4  # Simplified thermal stress
                    actual_stress = max([abs(stress.get('xx', 0)), abs(stress.get('yy', 0)), abs(stress.get('zz', 0))])
                    
                    if abs(actual_stress - thermal_stress_expected) / thermal_stress_expected > 0.8:
                        score *= 0.7
            
            # Check pressure-deformation coupling
            if 'pressure' in physics_checks and 'deformation_tensor' in physics_checks:
                pressure = physics_checks['pressure']
                deformation = physics_checks['deformation_tensor']
                
                if isinstance(deformation, np.ndarray):
                    volumetric_strain = np.trace(deformation)
                    expected_strain = -pressure / 50e9  # Simplified bulk compressibility
                    
                    if abs(volumetric_strain - expected_strain) > abs(expected_strain) * 0.5:
                        score *= 0.8
            
            return max(0.0, min(1.0, score))
            
        except Exception as e:
            self.logger.error(f"Multi-physics coupling evaluation failed: {e}")
            return 0.7
    
    async def _quantify_physics_score_uncertainty(self, physics_checks, detailed_scores):
        """Quantify uncertainty in physics score calculation"""
        try:
            uncertainties = []
            
            # Data quality based uncertainty
            for check_type, data in physics_checks.items():
                if isinstance(data, dict) and 'uncertainty' in data:
                    uncertainties.append(data['uncertainty'])
                else:
                    # Default uncertainty based on data type
                    if check_type in ['stress_tensor', 'deformation_tensor']:
                        uncertainties.append(0.15)  # 15% uncertainty
                    else:
                        uncertainties.append(0.10)  # 10% uncertainty
            
            # Score consistency based uncertainty
            score_values = list(detailed_scores.values())
            if len(score_values) > 1:
                score_std = np.std(score_values)
                uncertainties.append(score_std)
            
            # Model uncertainty from ML predictions
            if hasattr(self, 'physics_model_manager'):
                model_uncertainty = await self._get_model_prediction_uncertainty(
                    physics_checks
                )
                if model_uncertainty is not None:
                    uncertainties.append(model_uncertainty)
            
            # Combined uncertainty using error propagation
            total_uncertainty = np.sqrt(sum(u**2 for u in uncertainties))
            return min(0.5, total_uncertainty)  # Cap at 50% uncertainty
            
        except Exception as e:
            self.logger.error(f"Uncertainty quantification failed: {e}")
            return 0.2  # Default 20% uncertainty
    
    async def _store_physics_score_results(self, results):
        """Store physics score results in database for tracking"""
        try:
            if self.physics_db_manager:
                await self.physics_db_manager.execute_query(
                    """
                    INSERT INTO physics_score_analysis 
                    (final_score, detailed_scores, uncertainty, timestamp, input_checks)
                    VALUES (%s, %s, %s, %s, %s)
                    """,
                    (
                        results['final_score'],
                        json.dumps(results['detailed_scores']),
                        results['uncertainty'],
                        results['timestamp'],
                        results['input_checks']
                    )
                )
        except Exception as e:
            self.logger.warning(f"Could not store physics score results: {e}")
    
    # Advanced geological interpretation helper methods for tensor analysis
    
    async def _calculate_deviatoric_invariant(self, tensor):
        """Calculate comprehensive deviatoric stress invariant with advanced geological analysis"""
        try:
            if tensor is None or not isinstance(tensor, np.ndarray):
                return {'J2': 0.0, 'error': 'Invalid tensor input'}
            
            # Ensure 3x3 tensor
            if tensor.shape != (3, 3):
                if tensor.size == 6:  # Voigt notation
                    tensor = self._voigt_to_tensor(tensor)
                elif tensor.size == 9:
                    tensor = tensor.reshape(3, 3)
                else:
                    return {'J2': 0.0, 'error': f'Invalid tensor shape: {tensor.shape}'}
            
            # Calculate trace and deviatoric tensor
            trace = np.trace(tensor)
            mean_stress = trace / 3.0
            deviatoric = tensor - mean_stress * np.eye(3)
            
            # Second invariant J2 (von Mises equivalent stress)
            J2 = 0.5 * np.trace(deviatoric @ deviatoric)
            
            # Third invariant J3 (related to Lode angle)
            J3 = np.linalg.det(deviatoric)
            
            # Von Mises equivalent stress
            von_mises = np.sqrt(3 * J2)
            
            # Lode angle (stress triaxiality)
            if J2 > 1e-12:
                lode_angle = (1/3) * np.arcsin(-1.5 * np.sqrt(3) * J3 / (J2**(3/2)))
            else:
                lode_angle = 0.0
            
            # Stress triaxiality parameter
            if von_mises > 1e-12:
                triaxiality = mean_stress / von_mises
            else:
                triaxiality = 0.0
            
            # Principal deviatoric stresses
            dev_eigenvals = np.linalg.eigvals(deviatoric)
            dev_eigenvals.sort()
            
            # Advanced geological interpretation
            geological_analysis = await self._analyze_deviatoric_geology(
                J2, J3, von_mises, lode_angle, triaxiality
            )
            
            # Failure analysis using multiple criteria
            failure_analysis = await self._analyze_failure_potential(
                tensor, deviatoric, J2, von_mises, mean_stress
            )
            
            # Database integration for stress regime classification
            stress_regime = await self._classify_stress_regime_advanced(
                tensor, deviatoric, triaxiality, lode_angle
            )
            
            return {
                'J2': float(J2),
                'J3': float(J3),
                'von_mises_stress': float(von_mises),
                'mean_stress': float(mean_stress),
                'lode_angle_deg': float(np.degrees(lode_angle)),
                'stress_triaxiality': float(triaxiality),
                'principal_deviatoric_stresses': dev_eigenvals.tolist(),
                'geological_analysis': geological_analysis,
                'failure_analysis': failure_analysis,
                'stress_regime': stress_regime,
                'analysis_timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Deviatoric invariant calculation failed: {e}")
            return {
                'J2': 0.0,
                'error': str(e),
                'fallback_used': True
            }
    
    async def _classify_stress_regime_advanced(self, tensor, deviatoric, triaxiality, lode_angle):
        """Advanced stress regime classification using multiple parameters and database integration"""
        try:
            # Basic Anderson faulting classification
            eigenvals, eigenvecs = np.linalg.eigh(tensor)
            eigenvals = eigenvals[np.argsort(eigenvals)[::-1]]  # Sort descending
            sigma1, sigma2, sigma3 = eigenvals
            
            # Stress regime classification
            if sigma1 > sigma2 > sigma3:
                if abs(sigma1) > abs(sigma3):  # Compressive dominant
                    if sigma3 < 0:  # All compressive
                        anderson_regime = 'reverse_faulting'
                    else:  # Mixed
                        anderson_regime = 'strike_slip'
                else:
                    anderson_regime = 'normal_faulting'
            else:
                anderson_regime = 'complex'
            
            # Refined classification using stress ratios
            if abs(sigma3) > 1e-6:  # Avoid division by zero
                R1 = (sigma1 - sigma2) / (sigma1 - sigma3)  # Shape ratio
                R2 = sigma2 / sigma3  # Intermediate stress ratio
            else:
                R1, R2 = 1.0, 1.0
            
            # Classify based on R-value and triaxiality
            if R1 < 0.5:
                detailed_regime = 'uniaxial_dominant'
            elif R1 > 0.5:
                detailed_regime = 'biaxial_dominant'
            else:
                detailed_regime = 'triaxial_balanced'
            
            # Geological context from database
            regional_context = await self._get_regional_stress_context()
            
            # Tectonic setting inference
            tectonic_setting = self._infer_tectonic_setting(
                anderson_regime, triaxiality, lode_angle, R1
            )
            
            # Depth-dependent stress state
            depth_analysis = await self._analyze_depth_dependent_stress(
                tensor, triaxiality
            )
            
            return {
                'anderson_regime': anderson_regime,
                'detailed_regime': detailed_regime,
                'principal_stresses': {'sigma1': float(sigma1), 'sigma2': float(sigma2), 'sigma3': float(sigma3)},
                'stress_ratios': {'R1': float(R1), 'R2': float(R2)},
                'triaxiality': float(triaxiality),
                'lode_angle_deg': float(np.degrees(lode_angle)),
                'tectonic_setting': tectonic_setting,
                'regional_context': regional_context,
                'depth_analysis': depth_analysis,
                'confidence': self._calculate_regime_confidence(
                    anderson_regime, R1, triaxiality
                )
            }
            
        except Exception as e:
            self.logger.error(f"Advanced stress regime classification failed: {e}")
            # Fallback to simple classification
            det_val = np.linalg.det(tensor) if tensor.shape == (3, 3) else 0
            trace_val = np.trace(tensor) if tensor.shape == (3, 3) else 0
            
            if det_val > 0 and trace_val < 0:
                return {'anderson_regime': 'compressive_triaxial', 'confidence': 0.3}
            elif det_val < 0 and trace_val > 0:
                return {'anderson_regime': 'extensional_regime', 'confidence': 0.3}
            elif det_val > 0 and trace_val > 0:
                return {'anderson_regime': 'mixed_stress_state', 'confidence': 0.3}
            else:
                return {'anderson_regime': 'indeterminate_regime', 'confidence': 0.1}
    
    async def _analyze_failure_potential(self, tensor, deviatoric, J2, von_mises, mean_stress):
        """Comprehensive failure analysis using multiple geological failure criteria"""
        try:
            failure_analysis = {'criteria': {}, 'overall_risk': 'low', 'mechanisms': []}
            
            # Material properties from database or defaults
            material_props = await self._get_material_properties()
            cohesion = material_props.get('cohesion', 10e6)  # 10 MPa default
            friction_angle = material_props.get('friction_angle', np.radians(30))  # 30° default
            tensile_strength = material_props.get('tensile_strength', 5e6)  # 5 MPa default
            
            # 1. Mohr-Coulomb failure criterion
            sigma1 = np.max(np.linalg.eigvals(tensor))
            sigma3 = np.min(np.linalg.eigvals(tensor))
            
            mc_shear_strength = cohesion + sigma3 * np.tan(friction_angle)
            mc_stress = (sigma1 - sigma3) / 2
            mc_factor = mc_stress / mc_shear_strength if mc_shear_strength > 0 else 0
            
            failure_analysis['criteria']['mohr_coulomb'] = {
                'safety_factor': 1/mc_factor if mc_factor > 0 else float('inf'),
                'failure_likely': mc_factor >= 1.0,
                'stress_ratio': mc_factor
            }
            
            # 2. Von Mises failure criterion (for ductile failure)
            yield_strength = material_props.get('yield_strength', 100e6)  # 100 MPa default
            vm_factor = von_mises / yield_strength if yield_strength > 0 else 0
            
            failure_analysis['criteria']['von_mises'] = {
                'safety_factor': 1/vm_factor if vm_factor > 0 else float('inf'),
                'failure_likely': vm_factor >= 1.0,
                'stress_ratio': vm_factor
            }
            
            # 3. Tensile failure criterion
            if sigma1 > 0:  # Tension
                tensile_factor = sigma1 / tensile_strength
                failure_analysis['criteria']['tensile'] = {
                    'safety_factor': 1/tensile_factor if tensile_factor > 0 else float('inf'),
                    'failure_likely': tensile_factor >= 1.0,
                    'stress_ratio': tensile_factor
                }
            
            # 4. Griffith-Murrell criterion (for brittle materials with tensile cutoff)
            if sigma3 < 0:  # Compressive minimum stress
                gm_factor = (sigma1 - sigma3)**2 / (4 * tensile_strength * (sigma1 + 3 * sigma3))
                failure_analysis['criteria']['griffith_murrell'] = {
                    'safety_factor': 1/gm_factor if gm_factor > 0 else float('inf'),
                    'failure_likely': gm_factor >= 1.0,
                    'stress_ratio': gm_factor
                }
            
            # 5. Hoek-Brown failure criterion (for rock masses)
            if 'hoek_brown_m' in material_props and 'hoek_brown_s' in material_props:
                m = material_props['hoek_brown_m']
                s = material_props['hoek_brown_s']
                ucs = material_props.get('ucs', 50e6)  # Unconfined compressive strength
                
                hb_factor = (sigma1 - sigma3) / ucs - np.sqrt(m * sigma3 / ucs + s)
                failure_analysis['criteria']['hoek_brown'] = {
                    'safety_factor': 1/abs(hb_factor) if hb_factor != 0 else float('inf'),
                    'failure_likely': hb_factor >= 0,
                    'stress_ratio': abs(hb_factor)
                }
            
            # Determine overall failure risk and mechanisms
            failure_risks = []
            for criterion, analysis in failure_analysis['criteria'].items():
                if analysis['failure_likely']:
                    failure_risks.append(criterion)
                    
                    # Add likely failure mechanisms
                    if criterion == 'mohr_coulomb':
                        failure_analysis['mechanisms'].append('shear_fracture')
                    elif criterion == 'von_mises':
                        failure_analysis['mechanisms'].append('ductile_yielding')
                    elif criterion == 'tensile':
                        failure_analysis['mechanisms'].append('tensile_fracture')
                    elif criterion == 'griffith_murrell':
                        failure_analysis['mechanisms'].append('brittle_fracture')
                    elif criterion == 'hoek_brown':
                        failure_analysis['mechanisms'].append('rock_mass_failure')
            
            # Overall risk assessment
            if len(failure_risks) >= 3:
                failure_analysis['overall_risk'] = 'critical'
            elif len(failure_risks) >= 2:
                failure_analysis['overall_risk'] = 'high'
            elif len(failure_risks) == 1:
                failure_analysis['overall_risk'] = 'moderate'
            else:
                # Check if we're close to failure
                min_safety_factor = min(
                    [analysis['safety_factor'] for analysis in failure_analysis['criteria'].values()]
                )
                if min_safety_factor < 1.5:
                    failure_analysis['overall_risk'] = 'moderate'
                elif min_safety_factor < 2.0:
                    failure_analysis['overall_risk'] = 'low_moderate'
                else:
                    failure_analysis['overall_risk'] = 'low'
            
            # Add confidence assessment
            failure_analysis['confidence'] = await self._assess_failure_analysis_confidence(
                material_props, failure_analysis
            )
            
            return failure_analysis
            
        except Exception as e:
            self.logger.error(f"Failure analysis failed: {e}")
            # Fallback to simple determinant-based analysis
            abs_det = abs(np.linalg.det(tensor)) if tensor.shape == (3, 3) else 0
            if abs_det > 1e15:
                return {'overall_risk': 'high', 'mechanisms': ['brittle_fracture'], 'confidence': 0.3}
            elif abs_det > 1e12:
                return {'overall_risk': 'moderate', 'mechanisms': ['ductile_flow'], 'confidence': 0.3}
            else:
                return {'overall_risk': 'low', 'mechanisms': ['elastic_deformation'], 'confidence': 0.3}
    
    async def _classify_deformation_type_advanced(self, tensor):
        """Advanced deformation type classification with geological context"""
        try:
            if tensor is None or not isinstance(tensor, np.ndarray):
                return {'type': 'invalid', 'confidence': 0.0}
            
            det_val = np.linalg.det(tensor)
            trace_val = np.trace(tensor)
            
            # Eigenvalue analysis for comprehensive classification
            eigenvals = np.linalg.eigvals(tensor)
            eigenvals = np.sort(eigenvals)  # Sort ascending
            e1, e2, e3 = eigenvals
            
            # Volume change analysis
            volumetric_strain = trace_val
            deviatoric_strain = eigenvals - np.mean(eigenvals)
            
            # Shape parameters
            if abs(e3 - e1) > 1e-12:
                k_ratio = (e2 - e1) / (e3 - e1)  # Flinn parameter
            else:
                k_ratio = 0.0
            
            # Deformation intensity
            strain_intensity = np.sqrt(np.sum(eigenvals**2))
            
            # Primary classification based on determinant and volume change
            if abs(det_val) < 1e-12:
                primary_type = 'singular_deformation'
                geological_process = 'localized_shear_zone'
            elif abs(volumetric_strain) > 0.1:  # >10% volume change
                if volumetric_strain > 0:
                    primary_type = 'volume_expansion'
                    geological_process = 'thermal_expansion_or_fluid_injection'
                else:
                    primary_type = 'volume_compression'
                    geological_process = 'compaction_or_consolidation'
            elif abs(det_val - 1.0) < 0.05:  # Nearly isochoric
                primary_type = 'isochoric_deformation'
                geological_process = 'pure_shear_or_simple_shear'
            else:
                primary_type = 'general_deformation'
                geological_process = 'combined_volumetric_and_shear'
            
            # Strain ellipsoid classification
            if abs(e1 - e2) < 1e-6 and abs(e2 - e3) < 1e-6:
                ellipsoid_type = 'sphere'
            elif abs(e1 - e2) < 1e-6:
                ellipsoid_type = 'prolate_ellipsoid'  # Cigar-shaped
            elif abs(e2 - e3) < 1e-6:
                ellipsoid_type = 'oblate_ellipsoid'  # Pancake-shaped
            else:
                ellipsoid_type = 'triaxial_ellipsoid'
            
            # Tectonic regime inference
            if k_ratio < 0.5:
                tectonic_regime = 'extension_dominated'
            elif k_ratio > 2.0:
                tectonic_regime = 'compression_dominated'
            else:
                tectonic_regime = 'transpression_or_transtension'
            
            # Database comparison for regional consistency
            regional_consistency = await self._check_regional_deformation_consistency(
                tensor, primary_type
            )
            
            # Geological time scale estimation
            timescale_estimate = await self._estimate_deformation_timescale(
                strain_intensity, geological_process
            )
            
            return {
                'primary_type': primary_type,
                'ellipsoid_type': ellipsoid_type,
                'tectonic_regime': tectonic_regime,
                'geological_process': geological_process,
                'parameters': {
                    'determinant': float(det_val),
                    'trace': float(trace_val),
                    'volumetric_strain': float(volumetric_strain),
                    'k_ratio': float(k_ratio),
                    'strain_intensity': float(strain_intensity)
                },
                'principal_strains': {
                    'e1_min': float(e1),
                    'e2_intermediate': float(e2),
                    'e3_max': float(e3)
                },
                'regional_consistency': regional_consistency,
                'timescale_estimate': timescale_estimate,
                'confidence': self._calculate_deformation_confidence(
                    tensor, primary_type, regional_consistency
                )
            }
            
        except Exception as e:
            self.logger.error(f"Advanced deformation classification failed: {e}")
            # Fallback to simple classification
            det_val = np.linalg.det(tensor) if tensor.shape == (3, 3) else 0
            
            if abs(det_val) < 1e-12:
                return {'primary_type': 'singular_deformation', 'confidence': 0.3}
            elif abs(det_val) < 0.1:
                return {'primary_type': 'large_volume_change', 'confidence': 0.3}
            elif 0.9 <= abs(det_val) <= 1.1:
                return {'primary_type': 'isochoric_deformation', 'confidence': 0.3}
            else:
                return {'primary_type': 'anisotropic_deformation', 'confidence': 0.3}
    
    async def _infer_geological_process_advanced(self, tensor, geological_context=None):
        """Advanced geological process inference using multi-parameter analysis and database integration"""
        try:
            if tensor is None or not isinstance(tensor, np.ndarray):
                return {'process': 'unknown', 'confidence': 0.0}
            
            det_val = np.linalg.det(tensor)
            trace_val = np.trace(tensor)
            eigenvals = np.linalg.eigvals(tensor)
            eigenvals = np.sort(eigenvals)[::-1]  # Sort descending
            
            # Multi-parameter analysis
            processes = []
            confidence_scores = []
            
            # 1. Volumetric deformation analysis
            volumetric_strain = trace_val
            if abs(volumetric_strain) > 0.01:  # >1% volume change
                if volumetric_strain > 0:
                    processes.extend([
                        'thermal_expansion',
                        'fluid_injection',
                        'magma_intrusion',
                        'mineral_alteration_expansion'
                    ])
                    confidence_scores.extend([0.8, 0.7, 0.9, 0.6])
                else:
                    processes.extend([
                        'compaction',
                        'consolidation',
                        'elastic_compression',
                        'phase_transition'
                    ])
                    confidence_scores.extend([0.8, 0.7, 0.6, 0.5])
            
            # 2. Deviatoric deformation analysis
            deviatoric = tensor - (trace_val / 3.0) * np.eye(3)
            max_shear = np.max(np.abs(eigenvals)) / 2
            
            if max_shear > abs(volumetric_strain):
                # Shear-dominated processes
                processes.extend([
                    'fault_slip',
                    'ductile_shear',
                    'tectonic_deformation',
                    'landslide_deformation'
                ])
                confidence_scores.extend([0.9, 0.8, 0.8, 0.6])
            
            # 3. Determinant-based analysis
            if det_val < 0:
                processes.extend([
                    'shear_zone_development',
                    'fault_zone_deformation',
                    'folding_mechanisms'
                ])
                confidence_scores.extend([0.8, 0.7, 0.6])
            elif det_val > 1.2:
                processes.extend([
                    'dilation',
                    'fracture_opening',
                    'hydrothermal_alteration'
                ])
                confidence_scores.extend([0.7, 0.8, 0.6])
            
            # 4. Time-dependent process inference
            strain_rate_estimate = await self._estimate_strain_rate(tensor)
            if strain_rate_estimate:
                if strain_rate_estimate > 1e-6:  # High strain rate
                    processes.extend([
                        'seismic_slip',
                        'explosive_volcanic_activity',
                        'landslide_acceleration'
                    ])
                    confidence_scores.extend([0.8, 0.7, 0.6])
                elif strain_rate_estimate < 1e-15:  # Very slow
                    processes.extend([
                        'long_term_creep',
                        'glacial_isostatic_adjustment',
                        'slow_tectonic_loading'
                    ])
                    confidence_scores.extend([0.7, 0.6, 0.8])
            
            # 5. Regional geological context integration
            if geological_context:
                regional_processes = await self._get_regional_geological_processes(
                    geological_context.get('location', {})
                )
                if regional_processes:
                    for proc in regional_processes:
                        if proc not in processes:
                            processes.append(proc)
                            confidence_scores.append(0.6)
            
            # 6. Database-informed process correlation
            similar_deformations = await self._find_similar_deformation_patterns(
                tensor
            )
            if similar_deformations:
                for similar in similar_deformations:
                    proc = similar.get('geological_process')
                    if proc and proc not in processes:
                        processes.append(proc)
                        confidence_scores.append(similar.get('similarity_score', 0.5))
            
            # Rank processes by confidence
            if processes:
                process_ranking = list(zip(processes, confidence_scores))
                process_ranking.sort(key=lambda x: x[1], reverse=True)
                
                primary_process = process_ranking[0][0]
                primary_confidence = process_ranking[0][1]
                
                # Multi-process analysis for complex deformation
                if len(process_ranking) > 1:
                    secondary_processes = [p[0] for p in process_ranking[1:4]]  # Top 3 secondary
                else:
                    secondary_processes = []
                
                # Process mechanism details
                mechanism_details = await self._analyze_process_mechanisms(
                    primary_process, tensor, geological_context
                )
                
                return {
                    'primary_process': primary_process,
                    'primary_confidence': float(primary_confidence),
                    'secondary_processes': secondary_processes,
                    'all_candidates': dict(process_ranking),
                    'mechanism_details': mechanism_details,
                    'analysis_parameters': {
                        'determinant': float(det_val),
                        'trace': float(trace_val),
                        'volumetric_strain': float(volumetric_strain),
                        'max_shear': float(max_shear),
                        'strain_rate_estimate': strain_rate_estimate
                    },
                    'geological_context_used': geological_context is not None
                }
            else:
                # Fallback to simple analysis
                if det_val > 1.0 and trace_val > 0:
                    return {'primary_process': 'thermal_expansion', 'primary_confidence': 0.5}
                elif det_val < 1.0 and trace_val < 0:
                    return {'primary_process': 'compression_compaction', 'primary_confidence': 0.5}
                elif det_val < 0:
                    return {'primary_process': 'shear_dominated_deformation', 'primary_confidence': 0.5}
                else:
                    return {'primary_process': 'complex_mixed_process', 'primary_confidence': 0.3}
                    
        except Exception as e:
            self.logger.error(f"Advanced geological process inference failed: {e}")
            # Simple fallback
            det_val = np.linalg.det(tensor) if tensor.shape == (3, 3) else 0
            trace_val = np.trace(tensor) if tensor.shape == (3, 3) else 0
            
            if det_val > 1.0 and trace_val > 0:
                return {'primary_process': 'thermal_expansion', 'primary_confidence': 0.3}
            elif det_val < 1.0 and trace_val < 0:
                return {'primary_process': 'compression_compaction', 'primary_confidence': 0.3}
            elif det_val < 0:
                return {'primary_process': 'shear_dominated_deformation', 'primary_confidence': 0.3}
            else:
                return {'primary_process': 'complex_mixed_process', 'primary_confidence': 0.1}
    
    # Essential helper methods for advanced geological tensor analysis
    
    def _voigt_to_tensor(self, voigt_vector):
        """Convert Voigt notation to 3x3 tensor"""
        try:
            if len(voigt_vector) == 6:
                return np.array([
                    [voigt_vector[0], voigt_vector[5], voigt_vector[4]],
                    [voigt_vector[5], voigt_vector[1], voigt_vector[3]],
                    [voigt_vector[4], voigt_vector[3], voigt_vector[2]]
                ])
            return voigt_vector.reshape(3, 3)
        except:
            return np.eye(3)
    
    async def _analyze_deviatoric_geology(self, J2, J3, von_mises, lode_angle, triaxiality):
        """Geological interpretation of deviatoric stress invariants"""
        try:
            analysis = {}
            
            # Stress state classification with geological context
            if abs(triaxiality) < 0.3:
                analysis['stress_state'] = 'pure_shear_dominated'
                analysis['geological_context'] = 'transform_fault_zone'
            elif triaxiality > 0.6:
                analysis['stress_state'] = 'tension_dominated'
                analysis['geological_context'] = 'extensional_rift'
            elif triaxiality < -0.6:
                analysis['stress_state'] = 'compression_dominated'
                analysis['geological_context'] = 'compressive_orogen'
            else:
                analysis['stress_state'] = 'mixed_stress_state'
                analysis['geological_context'] = 'transpressive_zone'
            
            # Geological environment from stress magnitude
            if von_mises > 100e6:  # >100 MPa
                analysis['geological_environment'] = 'deep_crustal'
                analysis['estimated_depth_km'] = von_mises / (25e6)
            elif von_mises > 10e6:  # >10 MPa
                analysis['geological_environment'] = 'shallow_crustal'
                analysis['estimated_depth_km'] = von_mises / (25e6)
            else:
                analysis['geological_environment'] = 'near_surface'
                analysis['estimated_depth_km'] = 0.5
            
            # Deformation mechanism from Lode angle
            lode_deg = np.degrees(lode_angle)
            if -30 <= lode_deg <= 30:
                analysis['deformation_mechanism'] = 'axial_compression_extension'
                analysis['expected_structures'] = ['normal_faults', 'reverse_faults']
            elif 30 < abs(lode_deg) <= 60:
                analysis['deformation_mechanism'] = 'general_triaxial'
                analysis['expected_structures'] = ['conjugate_fault_sets', 'shear_zones']
            else:
                analysis['deformation_mechanism'] = 'plane_strain'
                analysis['expected_structures'] = ['strike_slip_faults', 'fold_structures']
            
            return analysis
            
        except Exception as e:
            self.logger.error(f"Deviatoric geology analysis failed: {e}")
            return {'error': str(e), 'stress_state': 'unknown'}
    
    async def _get_regional_stress_constraints(self):
        """Get regional stress constraints from comprehensive database"""
        try:
            constraints = []
            
            if self.physics_db_manager:
                query = """
                SELECT avg(principal_stress_s1_mpa) as s1_avg, 
                       avg(principal_stress_s2_mpa) as s2_avg, 
                       avg(principal_stress_s3_mpa) as s3_avg, 
                       stress_regime, count(*) as data_points
                FROM stress_measurements 
                WHERE reliability_score > 0.7 
                  AND measurement_date > NOW() - INTERVAL '10 years'
                GROUP BY stress_regime
                HAVING count(*) >= 5
                """
                
                try:
                    results = await self.physics_db_manager.execute_query(query)
                    if results:
                        constraints.extend(results)
                except Exception as e:
                    self.logger.warning(f"Stress constraint query failed: {e}")
            
            # Fallback constraints if no database data
            if not constraints:
                constraints = [
                    (50e6, 30e6, 10e6, 'normal_faulting', 10),
                    (200e6, 150e6, 100e6, 'reverse_faulting', 15),
                    (100e6, 80e6, 60e6, 'strike_slip', 12)
                ]
            
            return constraints
            
        except Exception as e:
            self.logger.error(f"Failed to get regional stress constraints: {e}")
            return None
    
    def _compare_with_regional_stress(self, stress_tensor, regional_constraints):
        """Compare tensor with regional stress patterns"""
        try:
            if not regional_constraints:
                return 0.7
            
            best_score = 0.0
            
            if isinstance(stress_tensor, np.ndarray) and stress_tensor.shape == (3, 3):
                tensor_eigenvals = np.linalg.eigvals(stress_tensor)
                tensor_eigenvals = np.sort(tensor_eigenvals)[::-1]
            else:
                return 0.5
            
            for constraint in regional_constraints:
                if len(constraint) >= 4:
                    s1_ref, s2_ref, s3_ref, regime = constraint[:4]
                    
                    if all(val is not None for val in [s1_ref, s2_ref, s3_ref]):
                        ref_stresses = np.array([s1_ref, s2_ref, s3_ref])
                        
                        if len(tensor_eigenvals) == 3:
                            # Normalize for comparison
                            tensor_norm = tensor_eigenvals / np.max(np.abs(tensor_eigenvals)) if np.max(np.abs(tensor_eigenvals)) > 0 else np.ones(3)
                            ref_norm = ref_stresses / np.max(np.abs(ref_stresses)) if np.max(np.abs(ref_stresses)) > 0 else np.ones(3)
                            
                            # Calculate correlation
                            correlation = np.corrcoef(tensor_norm, ref_norm)[0, 1]
                            if not np.isnan(correlation):
                                similarity_score = (correlation + 1) / 2
                                best_score = max(best_score, similarity_score)
            
            return max(0.0, min(1.0, best_score))
            
        except Exception as e:
            self.logger.error(f"Regional stress comparison failed: {e}")
            return 0.6
    
