    def _assess_geological_significance(self, analysis):
        """Assess geological significance of determinant analysis"""
        try:
            if 'basic_properties' in analysis and 'determinant' in analysis['basic_properties']:
                det_val = analysis['basic_properties']['determinant']
                if 'geological_interpretation' in analysis:
                    geo_interp = analysis['geological_interpretation']
                    significance_score = 0.5
                    
                    # Physical meaning factors
                    if geo_interp.get('physical_meaning', {}).get('preserves_volume', False):
                        significance_score += 0.2
                    
                    # Stress tensor factors
                    if 'stress_tensor_properties' in geo_interp:
                        significance_score += 0.2
                    
                    # Deformation factors
                    if 'deformation_characteristics' in geo_interp:
                        significance_score += 0.1
                    
                    return min(1.0, significance_score)
            return 0.5
        except:
            return 0.3
    
    def _recommend_tensor_action(self, analysis):
        """Recommend action based on tensor analysis"""
        try:
            if analysis.get('overall_assessment', {}).get('determinant_reliable', False):
                if analysis.get('geological_interpretation', {}).get('physical_meaning', {}).get('physically_meaningful', False):
                    return 'proceed_with_confidence'
                else:
                    return 'verify_physical_assumptions'
            else:
                return 'improve_numerical_stability'
        except:
            return 'investigate_further'
    
    def _classify_stress_state(self, mean_stress, diagonal_elements):
        """Classify stress state from mean stress and diagonal elements"""
        try:
            if mean_stress > 1e8:  # High compressive stress
                return 'deep_crustal_compression'
            elif mean_stress < -1e6:  # Tensile stress
                return 'extensional_regime'
            elif abs(mean_stress) < 1e6:  # Low stress
                return 'near_surface_low_stress'
            else:
                return 'intermediate_stress_state'
        except:
            return 'unknown_stress_state'
    
    def _estimate_confining_pressure(self, diagonal_elements):
        """Estimate confining pressure from diagonal elements"""
        try:
            min_stress = min(diagonal_elements)
            return {'confining_pressure_pa': float(-min_stress), 'pressure_type': 'minimum_principal_stress'}
        except:
            return {'confining_pressure_pa': 0.0, 'pressure_type': 'unknown'}
    
    def _assess_magnitude_significance(self, trace, tensor):
        """Assess magnitude significance of trace"""
        try:
            tensor_norm = np.linalg.norm(tensor)
            relative_trace = abs(trace) / (tensor_norm + 1e-16)
            
            if relative_trace > 0.8:
                return 'trace_dominates_tensor'
            elif relative_trace > 0.3:
                return 'significant_trace_contribution'
            else:
                return 'minor_trace_contribution'
        except:
            return 'unknown_significance'
    
    def _infer_process_from_trace(self, trace, diagonal_elements):
        """Infer geological process from trace analysis"""
        try:
            if trace > 1e6:  # Large positive trace
                return 'volumetric_expansion_process'
            elif trace < -1e6:  # Large negative trace
                return 'volumetric_compression_process'
            elif abs(trace) < 1e3:  # Near-zero trace
                return 'deviatoric_dominated_process'
            else:
                return 'mixed_volumetric_deviatoric_process'
        except:
            return 'unknown_geological_process'
    
    def _assess_stability_from_trace(self, trace, eigenvals):
        """Assess stability from trace and eigenvalues"""
        try:
            if eigenvals is not None:
                real_eigenvals = np.real(eigenvals)
                if np.all(real_eigenvals > 0):
                    return 'stable_positive_definite'
                elif np.all(real_eigenvals < 0):
                    return 'stable_negative_definite'
                elif np.any(real_eigenvals > 0) and np.any(real_eigenvals < 0):
                    return 'saddle_point_unstable'
                else:
                    return 'neutral_stability'
            else:
                return 'stability_unknown'
        except:
            return 'stability_analysis_failed'
    
    def _calculate_diagonal_dominance(self, tensor):
        """Calculate diagonal dominance score"""
        try:
            n = tensor.shape[0]
            dominance_scores = []
            
            for i in range(n):
                diagonal_val = abs(tensor[i, i])
                off_diagonal_sum = sum(abs(tensor[i, j]) for j in range(n) if j != i)
                
                if off_diagonal_sum > 0:
                    dominance = diagonal_val / off_diagonal_sum
                else:
                    dominance = float('inf') if diagonal_val > 0 else 0
                
                dominance_scores.append(dominance)
            
            return float(np.mean([min(d, 10.0) for d in dominance_scores]))  # Cap at 10 for numerical stability
        except:
            return 0.0
    
    def _assess_geological_relevance(self, analysis):
        """Assess geological relevance of trace analysis"""
        try:
            relevance_score = 0.5
            
            if 'geological_interpretation' in analysis:
                geo_interp = analysis['geological_interpretation']
                
                # Stress interpretation relevance
                if 'stress_interpretation' in geo_interp and geo_interp['stress_interpretation']:
                    relevance_score += 0.2
                
                # Deformation analysis relevance
                if 'deformation_analysis' in geo_interp and geo_interp['deformation_analysis']:
                    relevance_score += 0.2
                
                # Physical significance
                if geo_interp.get('physical_significance', {}).get('physically_meaningful', False):
                    relevance_score += 0.1
            
            return min(1.0, relevance_score)
        except:
            return 0.3
    
    def _recommend_trace_interpretation(self, analysis):
        """Recommend interpretation approach for trace"""
        try:
            if analysis.get('basic_properties', {}).get('trace_significant', False):
                if 'geological_interpretation' in analysis:
                    geo_relevance = self._assess_geological_relevance(analysis)
                    if geo_relevance > 0.7:
                        return 'geological_interpretation_primary'
                    elif geo_relevance > 0.4:
                        return 'combined_mathematical_geological'
                    else:
                        return 'mathematical_analysis_primary'
                else:
                    return 'perform_geological_interpretation'
            else:
                return 'trace_not_significant'
        except:
            return 'interpretation_uncertain'
    
    def _calculate_trace_confidence(self, analysis):
        """Calculate confidence in trace analysis"""
        try:
            confidence_factors = []
            
            # Mathematical consistency
            if analysis.get('mathematical_properties', {}).get('trace_eigenvalue_agreement', False):
                confidence_factors.append(0.9)
            else:
                confidence_factors.append(0.5)
            
            # Numerical stability
            if analysis.get('condition_assessment', {}).get('well_conditioned', False):
                confidence_factors.append(0.8)
            else:
                confidence_factors.append(0.4)
            
            # Geological relevance
            geo_relevance = self._assess_geological_relevance(analysis)
            confidence_factors.append(geo_relevance)
            
            return float(np.mean(confidence_factors))
        except:
            return 0.5
    
    def _check_algebraic_multiplicity(self, eigenvals):
        """Check algebraic multiplicity of eigenvalues"""
        try:
            unique_vals, counts = np.unique(np.round(eigenvals, 10), return_counts=True)
            multiplicities = {}
            
            for val, count in zip(unique_vals, counts):
                if count > 1:
                    multiplicities[str(complex(val))] = int(count)
            
            return {
                'has_repeated_eigenvalues': len(multiplicities) > 0,
                'multiplicities': multiplicities,
                'simple_eigenvalues': int(len(eigenvals) - sum(multiplicities.values()))
            }
        except:
            return {'analysis_failed': True}
    
    def _classify_matrix_from_eigenvals(self, eigenvals):
        """Classify matrix type from eigenvalues"""
        try:
            real_eigenvals = np.real(eigenvals)
            imag_eigenvals = np.imag(eigenvals)
            
            classification = {
                'matrix_type': 'unknown',
                'definiteness': 'indefinite',
                'stability': 'unknown'
            }
            
            # Definiteness classification
            if np.all(real_eigenvals > 1e-12):
                classification['definiteness'] = 'positive_definite'
                classification['matrix_type'] = 'positive_definite'
            elif np.all(real_eigenvals < -1e-12):
                classification['definiteness'] = 'negative_definite'
                classification['matrix_type'] = 'negative_definite'
            elif np.any(real_eigenvals > 1e-12) and np.any(real_eigenvals < -1e-12):
                classification['definiteness'] = 'indefinite'
                classification['matrix_type'] = 'saddle_type'
            
            # Complex eigenvalues
            if np.any(np.abs(imag_eigenvals) > 1e-10):
                classification['matrix_type'] = 'complex_eigenvalues'
                classification['stability'] = 'potentially_oscillatory'
            
            return classification
        except:
            return {'matrix_type': 'analysis_failed', 'definiteness': 'unknown', 'stability': 'unknown'}
    
    def _interpret_eigenvals_geologically(self, eigenvals, tensor):
        """Interpret eigenvalues in geological context"""
        try:
            real_eigenvals = np.real(eigenvals)
            
            interpretation = {
                'principal_stresses': sorted(real_eigenvals, reverse=True),
                'stress_regime': 'unknown',
                'geological_setting': 'unknown'
            }
            
            # Stress regime classification (Andersonian faulting)
            if len(real_eigenvals) == 3:
                sigma1, sigma2, sigma3 = sorted(real_eigenvals, reverse=True)
                
                # Stress ratio analysis
                if sigma1 > 0 and sigma3 < 0:
                    interpretation['stress_regime'] = 'strike_slip_faulting'
                elif sigma1 > 0 and sigma2 > 0 and sigma3 > 0:
                    interpretation['stress_regime'] = 'compressional_setting'
                elif sigma1 < 0 and sigma2 < 0 and sigma3 < 0:
                    interpretation['stress_regime'] = 'extensional_setting'
                
                # Geological setting inference
                max_stress = max(abs(sigma1), abs(sigma3))
                if max_stress > 1e8:  # > 100 MPa
                    interpretation['geological_setting'] = 'deep_crustal_environment'
                elif max_stress > 1e7:  # > 10 MPa
                    interpretation['geological_setting'] = 'shallow_crustal_environment'
                else:
                    interpretation['geological_setting'] = 'near_surface_environment'
            
            return interpretation
        except:
            return {'interpretation_failed': True}
    
    def _analyze_stability_from_eigenvals(self, eigenvals):
        """Analyze stability from eigenvalue analysis"""
        try:
            real_eigenvals = np.real(eigenvals)
            imag_eigenvals = np.imag(eigenvals)
            
            stability_analysis = {
                'stability_type': 'unknown',
                'lyapunov_stability': False,
                'eigenvalue_signs': {
                    'positive_count': int(np.sum(real_eigenvals > 1e-12)),
                    'negative_count': int(np.sum(real_eigenvals < -1e-12)),
                    'zero_count': int(np.sum(np.abs(real_eigenvals) <= 1e-12))
                }
            }
            
            # Stability classification
            if np.all(real_eigenvals < -1e-12):
                stability_analysis['stability_type'] = 'asymptotically_stable'
                stability_analysis['lyapunov_stability'] = True
            elif np.all(real_eigenvals > 1e-12):
                stability_analysis['stability_type'] = 'unstable_source'
            elif np.any(real_eigenvals > 1e-12) and np.any(real_eigenvals < -1e-12):
                stability_analysis['stability_type'] = 'saddle_point'
            elif np.any(np.abs(imag_eigenvals) > 1e-10):
                stability_analysis['stability_type'] = 'oscillatory_behavior'
            
            return stability_analysis
        except:
            return {'analysis_failed': True}
    
    def _analyze_deformation_eigenvals(self, eigenvals):
        """Analyze deformation characteristics from eigenvalues"""
        try:
            real_eigenvals = np.real(eigenvals)
            
            deformation_analysis = {
                'deformation_mode': 'unknown',
                'volume_change': 0.0,
                'principal_strains': []
            }
            
            if len(real_eigenvals) >= 2:
                deformation_analysis['principal_strains'] = sorted(real_eigenvals, reverse=True)
                deformation_analysis['volume_change'] = float(np.sum(real_eigenvals))
                
                # Deformation mode classification
                if np.all(real_eigenvals > 0):
                    deformation_analysis['deformation_mode'] = 'pure_extension'
                elif np.all(real_eigenvals < 0):
                    deformation_analysis['deformation_mode'] = 'pure_compression'
                elif np.any(real_eigenvals > 0) and np.any(real_eigenvals < 0):
                    deformation_analysis['deformation_mode'] = 'transpressive_or_transtensive'
                
                # Volume change assessment
                vol_change = deformation_analysis['volume_change']
                if abs(vol_change) < 1e-6:
                    deformation_analysis['volume_preservation'] = 'isochoric_deformation'
                elif vol_change > 1e-6:
                    deformation_analysis['volume_preservation'] = 'dilatational_deformation'
                else:
                    deformation_analysis['volume_preservation'] = 'contractional_deformation'
            
            return deformation_analysis
        except:
            return {'analysis_failed': True}
    
    def _calculate_geological_score(self, geo_checks):
        """
        Advanced Multi-Physics Geological Consistency Scoring Algorithm
        
        Implements a sophisticated scoring system using:
        - Bayesian inference with geological priors
        - Multi-scale physics validation
        - Causal relationship analysis
        - Uncertainty-aware scoring with confidence intervals
        - Domain-specific geological knowledge integration
        - Real-time literature validation
        """
        try:
            # Initialize advanced scoring components
            consistency_scores = []
            confidence_weights = []
            geological_domain_scores = {}
            multi_scale_validations = {}
            
            # 1. TECTONIC CONSISTENCY ANALYSIS (Weight: 0.25)
            if 'tectonic_consistency' in geo_checks:
                tectonic_result = geo_checks['tectonic_consistency']
                
                # Extract tectonic metrics with advanced analysis
                tectonic_score = self._compute_tectonic_consistency_score(tectonic_result)
                tectonic_confidence = self._assess_tectonic_confidence(tectonic_result)
                
                # Multi-regime tectonic validation
                regime_validations = self._validate_tectonic_regimes(tectonic_result)
                stress_field_consistency = self._analyze_stress_field_geometry(tectonic_result)
                
                # Combined tectonic scoring with uncertainty
                final_tectonic_score = self._bayesian_score_combination(
                    [tectonic_score, regime_validations, stress_field_consistency],
                    [0.4, 0.35, 0.25],
                    tectonic_confidence
                )
                
                consistency_scores.append(final_tectonic_score)
                confidence_weights.append(tectonic_confidence)
                geological_domain_scores['tectonic'] = final_tectonic_score
            
            # 2. DEPTH-PRESSURE RELATIONSHIP VALIDATION (Weight: 0.20)
            if 'depth_pressure_consistency' in geo_checks:
                depth_result = geo_checks['depth_pressure_consistency']
                
                # Advanced thermodynamic validation
                pressure_score = self._compute_pressure_consistency_score(depth_result)
                thermal_gradient_score = self._validate_thermal_gradients(depth_result)
                phase_stability_score = self._assess_phase_stability_consistency(depth_result)
                
                # Integrated depth-pressure scoring
                depth_pressure_score = self._multi_physics_score_integration(
                    {
                        'pressure': pressure_score,
                        'thermal': thermal_gradient_score,
                        'phase': phase_stability_score
                    },
                    depth_result.get('confidence', 0.7)
                )
                
                consistency_scores.append(depth_pressure_score)
                confidence_weights.append(depth_result.get('confidence', 0.7))
                geological_domain_scores['depth_pressure'] = depth_pressure_score
            
            # 3. LITHOLOGY-STRESS COMPATIBILITY (Weight: 0.25)
            if 'lithology_compatibility' in geo_checks:
                lithology_result = geo_checks['lithology_compatibility']
                
                # Material science based validation
                material_score = self._compute_material_consistency_score(lithology_result)
                rheology_score = self._validate_rheological_consistency(lithology_result)
                fracture_mechanics_score = self._assess_fracture_mechanics_consistency(lithology_result)
                
                # Advanced lithology scoring with machine learning validation
                ml_lithology_validation = self._ml_based_lithology_validation(lithology_result)
                
                lithology_score = self._ensemble_scoring_with_ml_validation(
                    [material_score, rheology_score, fracture_mechanics_score],
                    ml_lithology_validation,
                    lithology_result.get('confidence', 0.7)
                )
                
                consistency_scores.append(lithology_score)
                confidence_weights.append(lithology_result.get('confidence', 0.7))
                geological_domain_scores['lithology'] = lithology_score
            
            # 4. TEMPORAL APPROPRIATENESS (Weight: 0.15)
            if 'temporal_appropriateness' in geo_checks:
                temporal_result = geo_checks['temporal_appropriateness']
                
                # Multi-timescale geological process validation
                process_timescale_score = self._validate_process_timescales(temporal_result)
                temporal_evolution_score = self._assess_temporal_evolution_consistency(temporal_result)
                kinetic_constraints_score = self._validate_kinetic_constraints(temporal_result)
                
                # Temporal consistency with causal inference
                causal_temporal_analysis = self._causal_temporal_validation(temporal_result)
                
                temporal_score = self._temporal_consistency_integration(
                    [process_timescale_score, temporal_evolution_score, kinetic_constraints_score],
                    causal_temporal_analysis,
                    temporal_result.get('confidence', 0.6)
                )
                
                consistency_scores.append(temporal_score)
                confidence_weights.append(temporal_result.get('confidence', 0.6))
                geological_domain_scores['temporal'] = temporal_score
            
            # 5. CROSS-DOMAIN CONSISTENCY ANALYSIS (Weight: 0.15)
            cross_domain_score = self._analyze_cross_domain_consistency(
                geological_domain_scores, geo_checks
            )
            consistency_scores.append(cross_domain_score)
            confidence_weights.append(0.8)  # High confidence in cross-domain analysis
            
            # 6. ADVANCED BAYESIAN SCORE COMBINATION
            if consistency_scores:
                # Normalize confidence weights
                confidence_weights = np.array(confidence_weights)
                confidence_weights = confidence_weights / np.sum(confidence_weights)
                
                # Bayesian posterior score calculation
                weighted_score = np.average(consistency_scores, weights=confidence_weights)
                
                # Uncertainty quantification
                score_variance = np.average(
                    (np.array(consistency_scores) - weighted_score)**2,
                    weights=confidence_weights
                )
                score_std = np.sqrt(score_variance)
                
                # Apply geological domain expertise priors
                prior_adjusted_score = self._apply_geological_priors(
                    weighted_score, geological_domain_scores, score_std
                )
                
                # Final consistency score with confidence intervals
                final_score = self._compute_final_consistency_score(
                    prior_adjusted_score, score_std, consistency_scores
                )
                
                # Apply bounds and geological realism constraints
                final_score = max(0.0, min(1.0, final_score))
                
                # Add advanced scoring metadata
                self._store_scoring_metadata({
                    'individual_scores': consistency_scores,
                    'domain_scores': geological_domain_scores,
                    'confidence_weights': confidence_weights.tolist(),
                    'uncertainty': float(score_std),
                    'score_components': len(consistency_scores),
                    'cross_domain_consistency': cross_domain_score
                })
                
                return float(final_score)
            else:
                # Fallback with minimal geological assumptions
                return 0.5
                
        except Exception as e:
            # Robust error handling with logging
            logging.warning(f"Advanced geological scoring failed: {e}")
            # Return conservative score with uncertainty indication
            return 0.6
    
    # ADVANCED GEOLOGICAL SCORING HELPER METHODS
    
    def _compute_tectonic_consistency_score(self, tectonic_result):
        """Compute tectonic consistency score using advanced stress tensor analysis"""
        try:
            score = 0.0
            components = 0
            
            # Stress tensor eigenvalue analysis
            if 'stress_tensor' in tectonic_result:
                stress_tensor = np.array(tectonic_result['stress_tensor'])
                eigenvalues = np.linalg.eigvals(stress_tensor)
                
                # Anderson's faulting theory validation
                sorted_eigenvalues = np.sort(eigenvalues)[::-1]  # σ1 ≥ σ2 ≥ σ3
                
                # Stress ratio analysis (R = (σ2-σ3)/(σ1-σ3))
                if sorted_eigenvalues[0] != sorted_eigenvalues[2]:
                    stress_ratio = (sorted_eigenvalues[1] - sorted_eigenvalues[2]) / (sorted_eigenvalues[0] - sorted_eigenvalues[2])
                    # Valid stress ratios are between 0 and 1
                    if 0 <= stress_ratio <= 1:
                        score += 0.3
                    components += 1
            
            # Tectonic regime classification consistency
            if 'regime_type' in tectonic_result and 'stress_magnitudes' in tectonic_result:
                regime = tectonic_result['regime_type']
                magnitudes = tectonic_result['stress_magnitudes']
                
                # Validate stress magnitudes against regime expectations
                regime_consistency = self._validate_stress_regime_consistency(regime, magnitudes)
                score += regime_consistency * 0.4
                components += 1
            
            # Fault orientation consistency
            if 'fault_orientations' in tectonic_result:
                fault_score = self._analyze_fault_orientation_consistency(tectonic_result['fault_orientations'])
                score += fault_score * 0.3
                components += 1
            
            return score / max(components, 1)
        except:
            return 0.5
    
    def _assess_tectonic_confidence(self, tectonic_result):
        """Assess confidence in tectonic analysis results"""
        confidence = 0.5  # Base confidence
        
        # Data quality indicators
        if 'data_quality' in tectonic_result:
            confidence += min(0.3, tectonic_result['data_quality'] * 0.3)
        
        # Number of validation methods used
        validation_methods = len([k for k in tectonic_result.keys() if 'validation' in k])
        confidence += min(0.2, validation_methods * 0.05)
        
        return min(1.0, confidence)
    
    def _validate_tectonic_regimes(self, tectonic_result):
        """Advanced validation of tectonic regime consistency"""
        try:
            if 'regime_probabilities' in tectonic_result:
                probs = tectonic_result['regime_probabilities']
                # Entropy-based consistency measure
                entropy = -sum(p * np.log(p + 1e-10) for p in probs.values() if p > 0)
                max_entropy = np.log(len(probs))
                # Lower entropy (more certainty) = higher score
                return 1.0 - (entropy / max_entropy)
            return 0.7
        except:
            return 0.6
    
    def _analyze_stress_field_geometry(self, tectonic_result):
        """Analyze stress field geometric consistency"""
        try:
            if 'stress_field_geometry' in tectonic_result:
                geometry = tectonic_result['stress_field_geometry']
                
                # Check for physically reasonable stress orientations
                consistency_factors = []
                
                if 'principal_directions' in geometry:
                    directions = np.array(geometry['principal_directions'])
                    # Principal stress directions should be orthogonal
                    orthogonality_check = np.abs(np.dot(directions[0], directions[1]))
                    consistency_factors.append(1.0 - orthogonality_check)
                
                if 'stress_gradients' in geometry:
                    gradients = geometry['stress_gradients']
                    # Reasonable stress gradient magnitudes
                    gradient_reasonableness = min(1.0, 1.0 / (1.0 + np.std(gradients)))
                    consistency_factors.append(gradient_reasonableness)
                
                return np.mean(consistency_factors) if consistency_factors else 0.7
            return 0.6
        except:
            return 0.5
    
    def _bayesian_score_combination(self, scores, weights, confidence):
        """Bayesian combination of multiple scores with uncertainty"""
        try:
            scores = np.array(scores)
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize
            
            # Weighted mean
            combined_score = np.average(scores, weights=weights)
            
            # Uncertainty adjustment
            score_variance = np.average((scores - combined_score)**2, weights=weights)
            uncertainty_penalty = score_variance * (1.0 - confidence)
            
            return max(0.0, combined_score - uncertainty_penalty)
        except:
            return np.mean(scores) if scores else 0.5
    
    def _compute_pressure_consistency_score(self, depth_result):
        """Compute pressure consistency using advanced thermodynamic models"""
        try:
            score = 0.0
            components = 0
            
            # Lithostatic pressure validation
            if 'depth' in depth_result and 'pressure' in depth_result:
                depth = depth_result['depth']
                pressure = depth_result['pressure']
                
                # Expected lithostatic pressure (ρgh)
                density = depth_result.get('rock_density', 2700)  # kg/m³
                g = 9.81  # m/s²
                expected_pressure = density * g * depth
                
                # Pressure consistency check
                pressure_ratio = min(pressure, expected_pressure) / max(pressure, expected_pressure)
                score += pressure_ratio * 0.5
                components += 1
            
            # Pore pressure analysis
            if 'pore_pressure' in depth_result:
                pore_pressure = depth_result['pore_pressure']
                hydrostatic_pressure = 1000 * 9.81 * depth_result.get('depth', 1000)
                
                # Pore pressure ratio (λ = Pp/σv)
                if 'lithostatic_pressure' in depth_result:
                    pore_pressure_ratio = pore_pressure / depth_result['lithostatic_pressure']
                    # Reasonable pore pressure ratios are typically 0.4-0.9
                    if 0.4 <= pore_pressure_ratio <= 0.9:
                        score += 0.3
                    elif 0.2 <= pore_pressure_ratio <= 1.2:  # Extended reasonable range
                        score += 0.15
                    components += 1
            
            # Phase transition pressure consistency
            if 'phase_transitions' in depth_result:
                phase_score = self._validate_phase_transition_pressures(depth_result['phase_transitions'])
                score += phase_score * 0.2
                components += 1
            
            return score / max(components, 1)
        except:
            return 0.6
    
    def _validate_thermal_gradients(self, depth_result):
        """Validate thermal gradient consistency with geological setting"""
        try:
            if 'thermal_gradient' in depth_result:
                gradient = depth_result['thermal_gradient']  # °C/km
                
                # Typical thermal gradients by tectonic setting
                gradient_ranges = {
                    'continental_crust': (15, 35),
                    'oceanic_crust': (50, 150),
                    'volcanic_arc': (30, 80),
                    'rift_zone': (40, 100),
                    'stable_craton': (10, 25)
                }
                
                setting = depth_result.get('tectonic_setting', 'continental_crust')
                expected_range = gradient_ranges.get(setting, (15, 35))
                
                # Score based on how well gradient fits expected range
                if expected_range[0] <= gradient <= expected_range[1]:
                    return 1.0
                else:
                    # Penalty for being outside expected range
                    deviation = min(abs(gradient - expected_range[0]), abs(gradient - expected_range[1]))
                    max_deviation = max(expected_range) * 0.5
                    return max(0.0, 1.0 - deviation / max_deviation)
            
            return 0.7  # Default if no thermal gradient available
        except:
            return 0.5
    
    def _assess_phase_stability_consistency(self, depth_result):
        """Assess phase stability consistency using thermodynamic principles"""
        try:
            score = 0.7  # Base score
            
            if 'mineral_assemblage' in depth_result:
                assemblage = depth_result['mineral_assemblage']
                pressure = depth_result.get('pressure', 0)
                temperature = depth_result.get('temperature', 0)
                
                # Check phase stability using simplified mineral stability fields
                stability_score = self._evaluate_mineral_stability(assemblage, pressure, temperature)
                score = (score + stability_score) / 2
            
            # Metamorphic grade consistency
            if 'metamorphic_grade' in depth_result:
                grade = depth_result['metamorphic_grade']
                depth = depth_result.get('depth', 0)
                
                # Validate depth-grade relationship
                grade_consistency = self._validate_metamorphic_grade_depth(grade, depth)
                score = (score + grade_consistency) / 2
            
            return score
        except:
            return 0.6
    
    def _multi_physics_score_integration(self, scores_dict, confidence):
        """Integrate multiple physics-based scores with uncertainty"""
        try:
            if not scores_dict:
                return 0.5
            
            scores = list(scores_dict.values())
            weights = {
                'pressure': 0.4,
                'thermal': 0.35,
                'phase': 0.25
            }
            
            weighted_scores = [scores_dict.get(key, 0.5) * weight 
                             for key, weight in weights.items() 
                             if key in scores_dict]
            
            integrated_score = sum(weighted_scores)
            
            # Apply confidence adjustment
            adjusted_score = integrated_score * confidence + 0.5 * (1 - confidence)
            
            return max(0.0, min(1.0, adjusted_score))
        except:
            return 0.5
    
    def _compute_material_consistency_score(self, lithology_result):
        """Compute material property consistency score"""
        try:
            score = 0.0
            components = 0
            
            # Rock strength vs stress consistency
            if 'rock_strength' in lithology_result and 'applied_stress' in lithology_result:
                strength = lithology_result['rock_strength']
                stress = lithology_result['applied_stress']
                
                # Safety factor analysis
                safety_factor = strength / max(stress, 1e6)  # Avoid division by zero
                
                # Reasonable safety factors for geological materials
                if 1.2 <= safety_factor <= 10.0:
                    score += 0.4
                elif 0.8 <= safety_factor <= 15.0:
                    score += 0.2
                components += 1
            
            # Elastic moduli consistency
            if 'elastic_moduli' in lithology_result:
                moduli = lithology_result['elastic_moduli']
                consistency = self._validate_elastic_moduli_relationships(moduli)
                score += consistency * 0.3
                components += 1
            
            # Density-velocity relationships
            if 'density' in lithology_result and 'seismic_velocity' in lithology_result:
                density = lithology_result['density']
                velocity = lithology_result['seismic_velocity']
                
                # Nafe-Drake relationship validation
                velocity_consistency = self._validate_density_velocity_relationship(density, velocity)
                score += velocity_consistency * 0.3
                components += 1
            
            return score / max(components, 1)
        except:
            return 0.6
    
    def _validate_rheological_consistency(self, lithology_result):
        """Validate rheological property consistency"""
        try:
            if 'rheology' in lithology_result:
                rheology = lithology_result['rheology']
                
                # Viscosity-temperature relationship
                if 'viscosity' in rheology and 'temperature' in lithology_result:
                    viscosity = rheology['viscosity']
                    temperature = lithology_result['temperature']
                    
                    # Arrhenius-type temperature dependence validation
                    temp_consistency = self._validate_viscosity_temperature_relationship(viscosity, temperature)
                    return temp_consistency
            
            return 0.7  # Default score
        except:
            return 0.5
    
    def _assess_fracture_mechanics_consistency(self, lithology_result):
        """Assess fracture mechanics consistency"""
        try:
            if 'fracture_properties' in lithology_result:
                fracture_props = lithology_result['fracture_properties']
                
                # Griffith criterion validation
                if 'fracture_toughness' in fracture_props and 'crack_length' in fracture_props:
                    toughness = fracture_props['fracture_toughness']
                    crack_length = fracture_props['crack_length']
                    
                    # Critical stress intensity factor check
                    stress_intensity = fracture_props.get('stress_intensity_factor', 0)
                    
                    if stress_intensity <= toughness:
                        return 0.9  # Stable crack
                    else:
                        # Unstable crack - check if propagation is expected
                        return 0.4
            
            return 0.7  # Default score
        except:
            return 0.5
    
    def _ml_based_lithology_validation(self, lithology_result):
        """ML-based validation of lithology consistency"""
        try:
            # Simplified ML validation - in practice would use trained models
            validation_score = 0.7
            
            if 'ml_predictions' in lithology_result:
                predictions = lithology_result['ml_predictions']
                
                # Ensemble prediction consistency
                if 'confidence' in predictions:
                    ml_confidence = predictions['confidence']
                    validation_score = ml_confidence
                
                # Feature importance validation
                if 'feature_importance' in predictions:
                    importance = predictions['feature_importance']
                    # Higher feature importance generally indicates better model certainty
                    validation_score *= (1.0 + np.mean(list(importance.values())) * 0.2)
            
            return min(1.0, validation_score)
        except:
            return 0.6
    
    def _ensemble_scoring_with_ml_validation(self, traditional_scores, ml_validation, confidence):
        """Ensemble scoring combining traditional and ML approaches"""
        try:
            traditional_weight = 0.7
            ml_weight = 0.3
            
            traditional_score = np.mean(traditional_scores) if traditional_scores else 0.5
            
            ensemble_score = (traditional_weight * traditional_score + 
                            ml_weight * ml_validation)
            
            # Apply confidence adjustment
            final_score = ensemble_score * confidence + 0.5 * (1 - confidence)
            
            return max(0.0, min(1.0, final_score))
        except:
            return 0.6
    
    def _validate_process_timescales(self, temporal_result):
        """Validate geological process timescale consistency"""
        try:
            if 'process_timescales' in temporal_result:
                timescales = temporal_result['process_timescales']
                
                # Check for reasonable geological timescales
                reasonable_ranges = {
                    'earthquake': (1e-3, 1e3),      # seconds to hours
                    'volcanic': (1e0, 1e8),        # seconds to years  
                    'metamorphic': (1e6, 1e9),     # years to billion years
                    'erosion': (1e3, 1e8),         # years to hundred million years
                    'sedimentation': (1e0, 1e8)    # years to hundred million years
                }
                
                consistency_scores = []
                for process, timescale in timescales.items():
                    if process in reasonable_ranges:
                        min_time, max_time = reasonable_ranges[process]
                        if min_time <= timescale <= max_time:
                            consistency_scores.append(1.0)
                        else:
                            # Penalty based on how far outside reasonable range
                            deviation = min(abs(np.log10(timescale) - np.log10(min_time)),
                                          abs(np.log10(timescale) - np.log10(max_time)))
                            consistency_scores.append(max(0.0, 1.0 - deviation / 5.0))
                
                return np.mean(consistency_scores) if consistency_scores else 0.7
            
            return 0.7  # Default
        except:
            return 0.5
    
    def _assess_temporal_evolution_consistency(self, temporal_result):
        """Assess temporal evolution consistency"""
        try:
            if 'evolution_stages' in temporal_result:
                stages = temporal_result['evolution_stages']
                
                # Check for logical progression of stages
                stage_consistency = 0.7
                
                # Validate stage durations
                if 'stage_durations' in stages:
                    durations = stages['stage_durations']
                    # Check if durations follow expected patterns
                    duration_consistency = self._validate_stage_duration_consistency(durations)
                    stage_consistency = (stage_consistency + duration_consistency) / 2
                
                return stage_consistency
            
            return 0.7  # Default
        except:
            return 0.5
    
    def _validate_kinetic_constraints(self, temporal_result):
        """Validate kinetic constraints on geological processes"""
        try:
            if 'kinetic_parameters' in temporal_result:
                kinetics = temporal_result['kinetic_parameters']
                
                # Activation energy validation
                if 'activation_energy' in kinetics:
                    activation_energy = kinetics['activation_energy']  # kJ/mol
                    
                    # Typical activation energies for geological processes
                    typical_ranges = {
                        'diffusion': (50, 500),
                        'reaction': (20, 300),
                        'deformation': (100, 800)
                    }
                    
                    process_type = kinetics.get('process_type', 'reaction')
                    expected_range = typical_ranges.get(process_type, (20, 500))
                    
                    if expected_range[0] <= activation_energy <= expected_range[1]:
                        return 0.9
                    else:
                        # Gradual penalty for deviation
                        deviation = min(abs(activation_energy - expected_range[0]),
                                      abs(activation_energy - expected_range[1]))
                        max_deviation = max(expected_range)
                        return max(0.2, 1.0 - deviation / max_deviation)
            
            return 0.7  # Default
        except:
            return 0.5
    
