    def _apply_geological_priors(self, score, domain_scores, uncertainty):
        """Apply geological domain expertise as Bayesian priors"""
        try:
            # Conservative geological prior (slightly pessimistic)
            geological_prior = 0.65
            
            # Weight based on uncertainty - higher uncertainty = more prior influence
            uncertainty_weight = min(0.3, uncertainty * 2.0)
            score_weight = 1.0 - uncertainty_weight
            
            prior_adjusted_score = score_weight * score + uncertainty_weight * geological_prior
            
            # Domain-specific adjustments
            if 'tectonic' in domain_scores and domain_scores['tectonic'] > 0.8:
                prior_adjusted_score *= 1.05  # Bonus for strong tectonic consistency
            
            if 'lithology' in domain_scores and domain_scores['lithology'] > 0.8:
                prior_adjusted_score *= 1.05  # Bonus for strong lithology consistency
            
            return max(0.0, min(1.0, prior_adjusted_score))
        except:
            return score
    
    def _compute_final_consistency_score(self, score, uncertainty, individual_scores):
        """Compute final consistency score with confidence intervals"""
        try:
            # Penalize high uncertainty
            uncertainty_penalty = min(0.2, uncertainty * 0.5)
            uncertainty_adjusted_score = score - uncertainty_penalty
            
            # Bonus for having many consistent individual scores
            if len(individual_scores) >= 4:
                score_std = np.std(individual_scores)
                if score_std < 0.1:  # Very consistent individual scores
                    uncertainty_adjusted_score = min(1.0, uncertainty_adjusted_score * 1.03)
            
            return max(0.0, min(1.0, uncertainty_adjusted_score))
        except:
            return score
    
