    async def _reconstruct_metamorphic_pt_path(self, grade, depth, geological_context):
        """Reconstruct pressure-temperature-time path for metamorphic rocks"""
        try:
            import numpy as np
            from scipy.interpolate import interp1d
            
            # Standard P-T conditions for metamorphic grades
            pt_conditions = {
                'diagenesis': {'pressure_range': (0.1, 0.5), 'temperature_range': (50, 200)},
                'low': {'pressure_range': (0.3, 1.0), 'temperature_range': (150, 450)},
                'medium': {'pressure_range': (0.8, 2.5), 'temperature_range': (400, 700)},
                'high': {'pressure_range': (2.0, 6.0), 'temperature_range': (600, 900)}
            }
            
            base_conditions = pt_conditions.get(grade, pt_conditions['medium'])
            
            # Calculate expected pressure from depth
            expected_pressure = depth * 0.027  # GPa, assuming 27 MPa/km
            
            # P-T path consistency
            pressure_range = base_conditions['pressure_range']
            temperature_range = base_conditions['temperature_range']
            
            pressure_consistency = 1.0 if pressure_range[0] <= expected_pressure <= pressure_range[1] else \
                                 max(0.2, 1.0 - abs(expected_pressure - np.mean(pressure_range)) / np.mean(pressure_range))
            
            # Temperature-depth relationship
            geothermal_gradient = 25  # °C/km, typical
            expected_temp = 15 + depth * geothermal_gradient  # Surface temp + geothermal
            
            temp_consistency = 1.0 if temperature_range[0] <= expected_temp <= temperature_range[1] else \
                             max(0.2, 1.0 - abs(expected_temp - np.mean(temperature_range)) / np.mean(temperature_range))
            
            overall_consistency = 0.6 * pressure_consistency + 0.4 * temp_consistency
            
            return {
                'consistency_score': float(overall_consistency),
                'expected_pressure': float(expected_pressure),
                'expected_temperature': float(expected_temp),
                'pressure_consistency': float(pressure_consistency),
                'temperature_consistency': float(temp_consistency),
                'pt_conditions': base_conditions,
                'confidence': 0.8
            }
            
        except Exception as e:
            self.logger.error(f"P-T path reconstruction failed: {e}")
            return {'consistency_score': 0.5, 'confidence': 0.4}
    
    async def _advanced_geothermal_gradient_analysis(self, depth, geological_context):
        """Advanced geothermal gradient analysis with geodynamic context"""
        try:
            import numpy as np
            
            # Base geothermal gradients by tectonic setting
            gradient_settings = {
                'oceanic': 30.0,  # °C/km
                'continental': 25.0,
                'subduction': 15.0,
                'rift': 40.0,
                'hotspot': 50.0
            }
            
            # Get tectonic setting from geological context
            tectonic_setting = 'continental'  # default
            if geological_context:
                tectonic_setting = geological_context.get('tectonic_setting', 'continental')
            
            base_gradient = gradient_settings.get(tectonic_setting, 25.0)
            
            # Depth-dependent gradient (decreases with depth)
            depth_factor = 1.0 - 0.1 * np.log10(max(1.0, depth))
            adjusted_gradient = base_gradient * depth_factor
            
            # Calculate temperature at depth
            surface_temp = 15.0  # °C
            temperature_at_depth = surface_temp + adjusted_gradient * depth
            
            # Validity assessment based on reasonable temperature ranges
            reasonable_temp_range = (0, 1500)  # °C
            validity_score = 1.0 if reasonable_temp_range[0] <= temperature_at_depth <= reasonable_temp_range[1] else 0.3
            
            return {
                'validity_score': float(validity_score),
                'geothermal_gradient': float(adjusted_gradient),
                'temperature_at_depth': float(temperature_at_depth),
                'tectonic_setting': tectonic_setting,
                'base_gradient': float(base_gradient),
                'depth_factor': float(depth_factor),
                'confidence': 0.75
            }
            
        except Exception as e:
            self.logger.error(f"Geothermal gradient analysis failed: {e}")
            return {'validity_score': 0.5, 'confidence': 0.4}
    
