    def _validate_elastic_moduli_relationships(self, moduli):
        """Validate elastic moduli relationships"""
        try:
            # Check Poisson's ratio constraints
            if 'bulk_modulus' in moduli and 'shear_modulus' in moduli:
                K = moduli['bulk_modulus']
                G = moduli['shear_modulus']
                
                # Poisson's ratio should be between -1 and 0.5 for stable materials
                nu = (3*K - 2*G) / (6*K + 2*G)
                
                if -1 <= nu <= 0.5:
                    return 0.9
                else:
                    return 0.3
            
            return 0.7
        except:
            return 0.5
    
    def _validate_density_velocity_relationship(self, density, velocity):
        """Validate density-velocity relationship using empirical laws"""
        try:
            # Nafe-Drake relationship: Vp ≈ 2.0 + 2.5 * (ρ - 2.0)
            # where Vp is in km/s and ρ is in g/cm³
            density_gcm3 = density / 1000  # Convert from kg/m³ to g/cm³
            expected_velocity = 2.0 + 2.5 * (density_gcm3 - 2.0)
            
            velocity_ratio = min(velocity, expected_velocity) / max(velocity, expected_velocity)
            
            # Allow 20% deviation from expected relationship
            if velocity_ratio >= 0.8:
                return 0.9
            elif velocity_ratio >= 0.6:
                return 0.6
            else:
                return 0.3
        except:
            return 0.7
    
    def _validate_viscosity_temperature_relationship(self, viscosity, temperature):
        """Validate viscosity-temperature relationship"""
        try:
            # Arrhenius relationship: η = A * exp(E/RT)
            # At higher temperatures, viscosity should be lower
            
            # This is a simplified check - in practice would use actual activation energies
            reference_temp = 1000  # K
            reference_viscosity = 1e18  # Pa·s
            
            # Expected viscosity based on temperature
            if temperature > 0:
                temp_ratio = reference_temp / temperature
                expected_log_viscosity = np.log10(reference_viscosity) + 5 * (temp_ratio - 1)
                actual_log_viscosity = np.log10(viscosity)
                
                # Check if within reasonable range (2 orders of magnitude)
                log_difference = abs(actual_log_viscosity - expected_log_viscosity)
                
                if log_difference <= 2:
                    return 0.9
                elif log_difference <= 4:
                    return 0.6
                else:
                    return 0.3
            
            return 0.7
        except:
            return 0.5
    
    def _validate_stage_duration_consistency(self, durations):
        """Validate geological stage duration consistency"""
        try:
            # Check for reasonable progression of stage durations
            duration_values = list(durations.values())
            
            # Geological processes often follow power-law or exponential patterns
            # Check for reasonable ordering and magnitudes
            
            consistency_score = 0.7  # Base score
            
            # Check if durations are within reasonable geological ranges
            reasonable_durations = sum(1 for d in duration_values if 1e3 <= d <= 1e9)  # 1000 years to 1 billion years
            consistency_score *= (reasonable_durations / max(len(duration_values), 1))
            
            return min(1.0, consistency_score)
        except:
            return 0.6
    
