    async def _calculate_phase_uncertainty(self, transition_type, pressure, temperature, ensemble_score):
        """Calculate uncertainty bounds for phase transition predictions"""
        try:
            # Monte Carlo uncertainty propagation
            n_samples = 1000
            pressure_std = pressure * 0.05  # 5% uncertainty
            temperature_std = temperature * 0.03  # 3% uncertainty
            
            scores = []
            for _ in range(n_samples):
                p_sample = np.random.normal(pressure, pressure_std)
                t_sample = np.random.normal(temperature, temperature_std)
                
                # Simplified uncertainty calculation
                variation = 0.1 * np.random.randn()
                sample_score = ensemble_score + variation
                scores.append(np.clip(sample_score, 0, 1))
            
            scores = np.array(scores)
            
            return {
                'lower_bound': float(np.percentile(scores, 2.5)),
                'upper_bound': float(np.percentile(scores, 97.5)),
                'standard_deviation': float(np.std(scores)),
                'confidence_interval_95': [float(np.percentile(scores, 2.5)), 
                                         float(np.percentile(scores, 97.5))]
            }
            
        except Exception as e:
            self.logger.warning(f"Phase uncertainty calculation failed: {e}")
            return {'lower_bound': 0.0, 'upper_bound': 1.0, 'standard_deviation': 0.5}
    
