    async def _chemical_equilibrium_analysis(self, mineral, pressure, temperature):
        """Multi-component chemical equilibrium analysis"""
        try:
            from scipy.optimize import minimize
            import numpy as np
            
            # Get mineral composition
            composition = await self._get_mineral_composition(mineral)
            
            # Define equilibrium reactions
            reactions = await self._get_equilibrium_reactions(mineral)
            
            # Chemical potential calculations
            chemical_potentials = []
            
            for reaction in reactions:
                # Calculate reaction Gibbs energy
                delta_G_r = await self._calculate_reaction_gibbs_energy(
                    reaction, pressure, temperature
                )
                
                # Equilibrium constant
                K_eq = np.exp(-delta_G_r / (8.314 * temperature))
                
                # Activity product calculation
                activity_product = await self._calculate_activity_product(
                    reaction, composition, pressure, temperature
                )
                
                # Equilibrium assessment
                equilibrium_score = 1.0 - abs(np.log10(activity_product) - np.log10(K_eq))
                chemical_potentials.append(max(0, equilibrium_score))
            
            # Overall chemical equilibrium score
            if chemical_potentials:
                equilibrium_score = np.mean(chemical_potentials)
            else:
                equilibrium_score = 0.5
            
            return {
                'stability_score': float(equilibrium_score),
                'confidence': 0.8,
                'equilibrium_reactions': len(reactions),
                'chemical_potentials': chemical_potentials
            }
            
        except Exception as e:
            self.logger.warning(f"Chemical equilibrium analysis failed: {e}")
            return {'stability_score': 0.5, 'confidence': 0.3}
    
    async def _solid_solution_stability_analysis(self, mineral, pressure, temperature):
        """Advanced solid solution and substitution effects analysis"""
        try:
            # Solid solution thermodynamics using regular solution theory
            import numpy as np
            
            # Get solid solution parameters
            ss_data = await self._get_solid_solution_data(mineral)
            
            if not ss_data:
                return {'stability_score': 0.7, 'confidence': 0.5}  # Neutral assumption
            
            # Regular solution model parameters
            interaction_parameters = ss_data.get('interaction_parameters', {})
            end_member_compositions = ss_data.get('end_members', [])
            
            # Calculate mixing free energy
            stability_scores = []
            
            for composition in end_member_compositions:
                # Configurational entropy
                S_config = -8.314 * sum(x * np.log(x) for x in composition if x > 0)
                
                # Enthalpy of mixing (regular solution)
                H_mix = 0
                for i in range(len(composition)):
                    for j in range(i + 1, len(composition)):
                        W_ij = interaction_parameters.get(f'{i}_{j}', 0)
                        H_mix += W_ij * composition[i] * composition[j]
                
                # Free energy of mixing
                G_mix = H_mix - temperature * S_config
                
                # Stability based on mixing energy
                stability = 1.0 / (1.0 + np.exp(G_mix / (8.314 * temperature)))
                stability_scores.append(stability)
            
            # Overall solid solution stability
            if stability_scores:
                avg_stability = np.mean(stability_scores)
            else:
                avg_stability = 0.7
            
            return {
                'stability_score': float(avg_stability),
                'confidence': 0.75,
                'solid_solution_effects': stability_scores,
                'mixing_contributions': {
                    'enthalpic': float(np.mean([abs(h) for h in [H_mix]])),
                    'entropic': float(abs(S_config))
                }
            }
            
        except Exception as e:
            self.logger.warning(f"Solid solution analysis failed: {e}")
            return {'stability_score': 0.7, 'confidence': 0.3}
    
