    async def _estimate_atmospheric_phase_screen(self, weather_data, lat, lon, insar_result):
        """Estimate atmospheric phase screen using ML and weather models"""
        try:
            phase_screen = {
                'tropospheric_delay': {},
                'ionospheric_delay': {},
                'stratified_component': {},
                'turbulent_component': {}
            }
            
            # Tropospheric delay calculation
            if 'weather_models' in weather_data:
                tropospheric_delay = await self._calculate_tropospheric_delay(weather_data, lat, lon)
                phase_screen['tropospheric_delay'] = tropospheric_delay
            
            # Ionospheric delay estimation
            ionospheric_delay = await self._estimate_ionospheric_delay(lat, lon, insar_result)
            phase_screen['ionospheric_delay'] = ionospheric_delay
            
            # ML-based phase screen refinement
            if hasattr(self, 'model_manager'):
                ml_correction = await self._apply_ml_phase_screen_correction(
                    phase_screen, weather_data, lat, lon
                )
                phase_screen['ml_correction'] = ml_correction
            
            # Calculate total phase screen and uncertainty
            total_delay = 0.0
            delay_uncertainty = 0.0
            
            for component, delay_data in phase_screen.items():
                if isinstance(delay_data, dict) and 'delay_mm' in delay_data:
                    total_delay += delay_data['delay_mm']
                    delay_uncertainty += delay_data.get('uncertainty_mm', 0.0) ** 2
            
            phase_screen['total_delay_mm'] = total_delay
            phase_screen['total_uncertainty_mm'] = np.sqrt(delay_uncertainty)
            phase_screen['rms_error'] = min(5.0, phase_screen['total_uncertainty_mm'])
            
            return phase_screen
            
        except Exception as e:
            self.logger.error(f"Phase screen estimation failed: {e}")
            return {'total_delay_mm': 0.0, 'rms_error': 2.0}

    async def _apply_multi_layer_corrections(self, insar_result, phase_screen, weather_data):
        """Apply multi-layer atmospheric corrections"""
        try:
            corrected_result = insar_result.copy()
            
            # Convert phase delay to velocity correction (approximate)
            # Assuming C-band SAR (wavelength ~56mm) and 12-day repeat cycle
            wavelength_mm = 56.0
            repeat_days = 12.0
            
            total_delay_mm = phase_screen.get('total_delay_mm', 0.0)
            velocity_correction_mm_yr = (total_delay_mm * 365.25) / (repeat_days * 2)  # Factor of 2 for round-trip
            
            # Apply corrections to velocity measurements
            for key in ['line_of_sight_velocity_mm_yr', 'vertical_velocity_mm_yr']:
                if key in corrected_result:
                    corrected_result[key] -= velocity_correction_mm_yr
            
            # Apply component-specific corrections
            if 'tropospheric_delay' in phase_screen and 'delay_mm' in phase_screen['tropospheric_delay']:
                tropo_correction = (phase_screen['tropospheric_delay']['delay_mm'] * 365.25) / (repeat_days * 2)
                corrected_result['tropospheric_correction_mm_yr'] = tropo_correction
            
            if 'ionospheric_delay' in phase_screen and 'delay_mm' in phase_screen['ionospheric_delay']:
                iono_correction = (phase_screen['ionospheric_delay']['delay_mm'] * 365.25) / (repeat_days * 2)
                corrected_result['ionospheric_correction_mm_yr'] = iono_correction
            
            # Update confidence based on correction quality
            correction_quality = 1.0 - min(0.5, phase_screen.get('rms_error', 2.0) / 10.0)
            corrected_result['confidence'] = min(0.95, corrected_result.get('confidence', 0.5) * correction_quality + 0.1)
            
            return corrected_result
            
        except Exception as e:
            self.logger.error(f"Multi-layer correction application failed: {e}")
            return insar_result

    async def _validate_atmospheric_correction(self, corrected_result, weather_data):
        """Validate atmospheric correction quality"""
        try:
            validation_metrics = {
                'quality_score': 0.5,
                'data_consistency': 0.5,
                'temporal_stability': 0.5
            }
            
            # Check data consistency
            weather_quality = weather_data.get('quality_metrics', {}).get('overall_quality', 0.5)
            validation_metrics['data_consistency'] = weather_quality
            
            # Check correction magnitude reasonableness
            correction_keys = ['tropospheric_correction_mm_yr', 'ionospheric_correction_mm_yr']
            correction_magnitudes = []
            
            for key in correction_keys:
                if key in corrected_result:
                    correction_magnitudes.append(abs(corrected_result[key]))
            
            if correction_magnitudes:
                avg_correction = np.mean(correction_magnitudes)
                # Reasonable corrections are typically < 20 mm/yr
                magnitude_score = 1.0 if avg_correction < 10.0 else max(0.1, 20.0 / avg_correction)
                validation_metrics['temporal_stability'] = magnitude_score
            
            # Overall quality score
            validation_metrics['quality_score'] = np.mean(list(validation_metrics.values()))
            
            return validation_metrics
            
        except Exception as e:
            self.logger.error(f"Atmospheric correction validation failed: {e}")
            return {'quality_score': 0.3}

    async def _apply_climatological_correction(self, insar_result, lat, lon):
        """Apply climatological atmospheric correction as fallback"""
        try:
            # Simple climatological correction based on location and season
            import datetime
            current_month = datetime.datetime.now().month
            
            # Seasonal atmospheric correction factors
            seasonal_factors = {
                'winter': 0.92,  # Drier, less atmospheric delay
                'spring': 0.94,
                'summer': 0.88,  # More humid, higher atmospheric delay
                'autumn': 0.95
            }
            
            if current_month in [12, 1, 2]:
                correction_factor = seasonal_factors['winter']
            elif current_month in [3, 4, 5]:
                correction_factor = seasonal_factors['spring']
            elif current_month in [6, 7, 8]:
                correction_factor = seasonal_factors['summer']
            else:
                correction_factor = seasonal_factors['autumn']
            
            # Apply simple correction
            for key in ['line_of_sight_velocity_mm_yr', 'vertical_velocity_mm_yr']:
                if key in insar_result:
                    insar_result[key] *= correction_factor
            
            insar_result['correction_type'] = 'climatological'
            insar_result['correction_factor'] = correction_factor
            
            return True
            
        except Exception as e:
            self.logger.error(f"Climatological correction failed: {e}")
            return False

