    async def _apply_ml_station_quality_filter(self, stations, target_lat, target_lon):
        """Apply machine learning models for station quality assessment"""
        try:
            filtered_stations = []
            
            for station in stations:
                # Extract ML features for quality assessment
                features = self._extract_weather_quality_features(station)
                
                # Apply Bayesian quality assessment
                quality_score = await self._bayesian_quality_assessment(features)
                
                # Physical consistency checks
                consistency_score = self._validate_physical_consistency(station['measurements'])
                
                # Combined quality score
                combined_score = 0.6 * quality_score + 0.4 * consistency_score
                
                if combined_score > 0.5:  # Quality threshold
                    station['ml_quality_score'] = combined_score
                    station['quality_grade'] = self._numeric_to_quality_grade(combined_score)
                    filtered_stations.append(station)
            
            return filtered_stations
        
        except Exception as e:
            self.logger.warning(f"ML quality filtering failed: {e}")
            return stations
    
    async def _apply_spatial_temporal_interpolation(self, station_results, target_lat, target_lon):
        """Apply spatial-temporal interpolation for data gap filling"""
        try:
            stations = station_results['stations']
            
            # Kriging-based spatial interpolation
            interpolated_data = await self._kriging_interpolation(stations, target_lat, target_lon)
            
            # Temporal interpolation for missing time series
            for station in stations:
                if station['measurements']:
                    station['measurements'] = await self._temporal_interpolation(
                        station['measurements']
                    )
            
            # Calculate spatial coverage metrics
            station_results['spatial_coverage'] = self._calculate_spatial_coverage(
                stations, target_lat, target_lon
            )
            
            # Add interpolated virtual stations if coverage is insufficient
            if station_results['spatial_coverage'] < 0.7:
                virtual_stations = await self._generate_virtual_stations(
                    stations, target_lat, target_lon, interpolated_data
                )
                station_results['stations'].extend(virtual_stations)
            
            return station_results
        
        except Exception as e:
            self.logger.warning(f"Spatial-temporal interpolation failed: {e}")
            return station_results
    
    async def _calculate_station_quality_metrics(self, stations):
        """Calculate comprehensive quality metrics for station network"""
        try:
            if not stations:
                return {'overall_quality': 0.0, 'station_count': 0}
            
            quality_scores = [s.get('ml_quality_score', 0.5) for s in stations]
            
            metrics = {
                'overall_quality': np.mean(quality_scores),
                'quality_std': np.std(quality_scores),
                'station_count': len(stations),
                'high_quality_stations': len([s for s in quality_scores if s > 0.8]),
                'data_completeness': np.mean([
                    self._calculate_data_completeness(s.get('measurements', {}))
                    for s in stations
                ]),
                'temporal_coverage_hours': self._calculate_temporal_coverage(stations),
                'spatial_distribution_score': self._calculate_spatial_distribution(stations),
                'uncertainty_bounds': self._calculate_uncertainty_bounds(stations)
            }
            
            return metrics
        
        except Exception as e:
            self.logger.warning(f"Quality metrics calculation failed: {e}")
            return {'overall_quality': 0.0, 'station_count': 0}
    
