    async def _analyze_hydrological_networks(self, lat: float, lon: float) -> Dict[str, Any]:
        """Analyze hydrological drainage networks to determine coastal connectivity"""
        try:
            if hasattr(self, 'db_manager'):
                # Query hydrological network database
                hydro_query = """
                WITH point_geom AS (
                    SELECT ST_SetSRID(ST_MakePoint(%s, %s), 4326) as pt
                ),
                nearest_drainage AS (
                    SELECT 
                        hn.stream_order,
                        hn.flow_direction,
                        hn.discharge_cms,
                        hn.drainage_area_km2,
                        hn.outlet_type,
                        hn.outlet_coordinates,
                        ST_Distance(
                            ST_Transform(pt.pt, 3857)::geography,
                            ST_Transform(hn.geom, 3857)::geography
                        ) / 1000.0 as distance_km
                    FROM hydrological_networks hn, point_geom pt
                    WHERE ST_DWithin(
                        ST_Transform(pt.pt, 3857)::geography,
                        ST_Transform(hn.geom, 3857)::geography,
                        100000  -- 100km search radius
                    )
                    AND hn.stream_order >= 4  -- Major streams only
                    ORDER BY distance_km ASC, stream_order DESC
                    LIMIT 3
                )
                SELECT 
                    nd.outlet_type,
                    nd.outlet_coordinates,
                    nd.distance_km as stream_distance,
                    nd.stream_order,
                    ST_Distance(
                        ST_SetSRID(ST_GeomFromText(nd.outlet_coordinates), 4326)::geography,
                        pt.pt::geography
                    ) / 1000.0 as outlet_distance
                FROM nearest_drainage nd, point_geom pt
                WHERE nd.outlet_type IN ('ocean', 'sea', 'gulf', 'bay', 'great_lake')
                ORDER BY outlet_distance ASC
                LIMIT 1;
                """
                
                result = await self.db_manager.execute_query(hydro_query, (lon, lat))
                
                if result and len(result) > 0:
                    row = result[0]
                    
                    # Hydrological distance approximation
                    stream_dist = row.get('stream_distance', 0)
                    outlet_dist = row.get('outlet_distance', 0)
                    total_distance = stream_dist + outlet_dist
                    
                    return {
                        'distance_to_coast_km': round(total_distance, 2),
                        'coastal_type': row.get('outlet_type'),
                        'drainage_pathway': {
                            'stream_distance_km': stream_dist,
                            'outlet_distance_km': outlet_dist,
                            'stream_order': row.get('stream_order')
                        },
                        'confidence_score': 0.4,  # Lower confidence for drainage-based estimates
                        'uncertainty_km': total_distance * 0.3  # 30% uncertainty
                    }
                    
        except Exception as e:
            self.logger.error(f"Hydrological network analysis error: {e}")
        
        return None

    async def _enhanced_geometric_coastal_approximation(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced geometric approximation with refined coastal boundaries"""
        try:
            # High-resolution continental boundary database
            continental_coastlines = {
                # North American coastlines (detailed)
                'pacific_coast': [
                    {'lat_range': (32.0, 49.0), 'lon_approx': -124.5, 'type': 'ocean'},
                    {'lat_range': (25.0, 32.0), 'lon_approx': -117.0, 'type': 'ocean'}  # California coast
                ],
                'atlantic_coast': [
                    {'lat_range': (25.0, 45.0), 'lon_approx': -70.0, 'type': 'ocean'},
                    {'lat_range': (45.0, 70.0), 'lon_approx': -65.0, 'type': 'ocean'}   # Maritime provinces
                ],
                'gulf_coast': [
                    {'lat_range': (25.0, 30.5), 'lon_range': (-97.0, -80.0), 'lat_approx': 26.0, 'type': 'gulf'}
                ],
                # Great Lakes (detailed boundaries)
                'great_lakes': [
                    {'name': 'Superior', 'center': (47.7, -87.5), 'radius': 2.5},
                    {'name': 'Michigan', 'center': (44.0, -87.0), 'radius': 2.0},
                    {'name': 'Huron', 'center': (44.8, -82.4), 'radius': 1.5},
                    {'name': 'Erie', 'center': (42.0, -81.0), 'radius': 1.2},
                    {'name': 'Ontario', 'center': (43.7, -77.9), 'radius': 1.0}
                ]
            }
            
            min_distance = float('inf')
            nearest_feature = None
            coastal_type = 'inland'
            
            # Analyze Pacific coast
            for coast_segment in continental_coastlines['pacific_coast']:
                if coast_segment['lat_range'][0] <= lat <= coast_segment['lat_range'][1]:
                    distance = abs(lon - coast_segment['lon_approx']) * self._longitude_to_km_factor(lat)
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Pacific Ocean'
                        coastal_type = coast_segment['type']
            
            # Analyze Atlantic coast
            for coast_segment in continental_coastlines['atlantic_coast']:
                if coast_segment['lat_range'][0] <= lat <= coast_segment['lat_range'][1]:
                    distance = abs(lon - coast_segment['lon_approx']) * self._longitude_to_km_factor(lat)
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Atlantic Ocean'
                        coastal_type = coast_segment['type']
            
            # Analyze Gulf coast
            for gulf_segment in continental_coastlines['gulf_coast']:
                if (gulf_segment['lat_range'][0] <= lat <= gulf_segment['lat_range'][1] and
                    gulf_segment['lon_range'][0] <= lon <= gulf_segment['lon_range'][1]):
                    distance = abs(lat - gulf_segment['lat_approx']) * 111.0  # Latitude to km
                    if distance < min_distance:
                        min_distance = distance
                        nearest_feature = 'Gulf of Mexico'
                        coastal_type = gulf_segment['type']
            
            # Analyze Great Lakes
            for lake in continental_coastlines['great_lakes']:
                lake_distance = self._calculate_distance(
                    lat, lon, lake['center'][0], lake['center'][1]
                )
                # Account for lake radius
                adjusted_distance = max(0, lake_distance - lake['radius'] * 111.0)
                
                if adjusted_distance < min_distance:
                    min_distance = adjusted_distance
                    nearest_feature = f"Lake {lake['name']}"
                    coastal_type = 'lake'
            
            # Calculate uncertainty based on method limitations
            uncertainty_km = min_distance * 0.4 if min_distance < 100 else min_distance * 0.2
            
            return {
                'distance_to_coast_km': round(min_distance, 2) if min_distance != float('inf') else 500.0,
                'nearest_water_body': nearest_feature,
                'coastal_type': coastal_type,
                'confidence_score': 0.3,  # Low confidence for geometric approximation
                'uncertainty_km': round(uncertainty_km, 2),
                'spatial_resolution_m': 10000,  # ~10km accuracy
                'approximation_method': 'enhanced_geometric'
            }
            
        except Exception as e:
            self.logger.error(f"Enhanced geometric approximation error: {e}")
            return {
                'distance_to_coast_km': 200.0,
                'coastal_type': 'inland',
                'confidence_score': 0.1,
                'error': str(e)
            }

    def _longitude_to_km_factor(self, lat: float) -> float:
        """Calculate longitude-to-kilometers conversion factor at given latitude"""
        import math
        return 111.0 * math.cos(math.radians(lat))

    def _determine_noaa_crm_dataset(self, lat: float, lon: float) -> str:
        """Determine appropriate NOAA CRM dataset based on geographic location"""
        # NOAA CRM regional datasets
        crm_datasets = {
            'atlantic': {'lat_range': (24, 45), 'lon_range': (-85, -65)},
            'gulf_mexico': {'lat_range': (24, 31), 'lon_range': (-98, -80)},
            'pacific': {'lat_range': (32, 50), 'lon_range': (-130, -115)},
            'great_lakes': {'lat_range': (41, 49), 'lon_range': (-93, -75)},
            'alaska': {'lat_range': (55, 72), 'lon_range': (-170, -130)},
            'hawaii': {'lat_range': (18, 23), 'lon_range': (-162, -154)}
        }
        
        for dataset, bounds in crm_datasets.items():
            if (bounds['lat_range'][0] <= lat <= bounds['lat_range'][1] and
                bounds['lon_range'][0] <= lon <= bounds['lon_range'][1]):
                return dataset
        
        return None  # No appropriate dataset found

    async def _process_noaa_elevation_data(self, tiff_data: bytes, lat: float, lon: float) -> Dict:
        """
        Advanced NOAA elevation/bathymetry TIFF processing with multi-resolution analysis
        
        Processes NOAA DEM/bathymetry data using GDAL/rasterio with comprehensive
        spatial analysis, uncertainty quantification, and ML-based feature extraction.
        
        Features:
        - Multi-band TIFF processing (elevation, uncertainty, metadata)
        - Spatial interpolation and resampling
        - Coastal zone feature detection
        - Statistical analysis and quality assessment
        - PostGIS integration for spatial queries
        - Machine learning bathymetric classification
        """
        try:
            import tempfile
            import io
            from scipy import ndimage, interpolate
            from scipy.stats import mode
            from sklearn.cluster import DBSCAN
            from sklearn.preprocessing import StandardScaler
            import cv2
            
            # Validate input parameters
            if not tiff_data or len(tiff_data) < 1000:
                self.logger.warning("Invalid or insufficient TIFF data provided")
                return await self._fallback_elevation_processing(lat, lon)
            
            # Process TIFF data with rasterio/GDAL
            elevation_analysis = await self._analyze_tiff_with_gdal(tiff_data, lat, lon)
            
            if not elevation_analysis:
                return await self._fallback_elevation_processing(lat, lon)
            
            # Extract core elevation data
            elevation_grid = elevation_analysis['elevation_array']
            transform = elevation_analysis['transform']
            crs = elevation_analysis['crs']
            bounds = elevation_analysis['bounds']
            
            # Advanced spatial analysis
            spatial_metrics = await self._calculate_advanced_spatial_metrics(
                elevation_grid, transform, lat, lon
            )
            
            # Bathymetric feature classification
            bathymetric_features = await self._classify_bathymetric_features(
                elevation_grid, lat, lon
            )
            
            # Uncertainty quantification
            uncertainty_analysis = await self._quantify_elevation_uncertainty(
                elevation_grid, spatial_metrics
            )
            
            # Coastal zone analysis
            coastal_analysis = await self._analyze_coastal_zone_features(
                elevation_grid, transform, lat, lon
            )
            
            # Multi-scale feature extraction
            multiscale_features = await self._extract_multiscale_features(
                elevation_grid, [1, 3, 5, 9]  # kernel sizes
            )
            
            # Generate comprehensive elevation profile
            elevation_profile = await self._generate_elevation_profile(
                elevation_grid, transform, lat, lon, radius_m=5000
            )
            
            # PostGIS spatial database integration
            if hasattr(self, 'db_manager') and self.db_manager:
                await self._store_elevation_data_postgis(
                    elevation_analysis, spatial_metrics, lat, lon
                )
            
            # Compile comprehensive results
            processed_data = {
                'elevation_grid': elevation_grid.tolist() if hasattr(elevation_grid, 'tolist') else elevation_grid,
                'lat_bounds': (bounds['south'], bounds['north']),
                'lon_bounds': (bounds['west'], bounds['east']),
                'resolution_m': spatial_metrics['pixel_size_m'],
                'crs': str(crs),
                'grid_dimensions': elevation_grid.shape if hasattr(elevation_grid, 'shape') else (0, 0),
                
                # Statistical analysis
                'elevation_statistics': {
                    'min_elevation_m': float(np.nanmin(elevation_grid)),
                    'max_elevation_m': float(np.nanmax(elevation_grid)),
                    'mean_elevation_m': float(np.nanmean(elevation_grid)),
                    'median_elevation_m': float(np.nanmedian(elevation_grid)),
                    'std_elevation_m': float(np.nanstd(elevation_grid)),
                    'elevation_range_m': float(np.nanmax(elevation_grid) - np.nanmin(elevation_grid))
                },
                
                # Spatial metrics
                'spatial_metrics': spatial_metrics,
                
                # Bathymetric classification
                'bathymetric_features': bathymetric_features,
                
                # Uncertainty quantification
                'uncertainty_analysis': uncertainty_analysis,
                
                # Coastal zone analysis
                'coastal_analysis': coastal_analysis,
                
                # Multi-scale features
                'multiscale_features': multiscale_features,
                
                # Elevation profile
                'elevation_profile': elevation_profile,
                
                # Data quality metrics
                'data_quality': {
                    'completeness': 1.0 - (np.count_nonzero(np.isnan(elevation_grid)) / elevation_grid.size),
                    'spatial_consistency': spatial_metrics.get('spatial_consistency', 0.85),
                    'processing_method': 'advanced_gdal_rasterio',
                    'confidence_score': uncertainty_analysis.get('overall_confidence', 0.9)
                },
                
                # Processing metadata
                'processing_timestamp': self._get_current_timestamp(),
                'processing_version': 'v3.1_advanced_noaa',
                'data_sources': ['NOAA_DEM', 'GDAL_processing', 'ML_classification']
            }
            
            # Cache processed data for future use
            await self._cache_elevation_data(processed_data, lat, lon)
            
            return processed_data
            
        except ImportError as e:
            self.logger.warning(f"Missing required libraries for advanced processing: {e}")
            return await self._fallback_elevation_processing(lat, lon)
        except Exception as e:
            self.logger.error(f"Advanced NOAA elevation data processing error: {e}")
            return await self._fallback_elevation_processing(lat, lon)

    async def _extract_coastal_metrics_from_elevation(self, elevation_data: Dict, lat: float, lon: float) -> Dict:
        """
        Advanced coastal metrics extraction using multi-algorithm analysis
        
        Performs comprehensive coastal zone analysis using:
        - Zero-elevation contour detection and analysis
        - Multi-scale coastline feature extraction
        - Bathymetric gradient analysis
        - Machine learning coastal classification
        - Statistical coastal morphology assessment
        - Tidal range and exposure analysis
        """
        try:
            from scipy import ndimage
            from scipy.spatial.distance import cdist
            from skimage import measure, morphology, segmentation
            from sklearn.cluster import DBSCAN, KMeans
            from sklearn.preprocessing import StandardScaler
            import cv2
            
            if not elevation_data or 'elevation_grid' not in elevation_data:
                return await self._fallback_coastal_metrics(lat, lon)
            
            elevation_grid = np.array(elevation_data['elevation_grid'])
            
            # Multi-algorithm coastline detection
            coastline_detection = await self._detect_coastlines_multi_algorithm(
                elevation_grid, elevation_data
            )
            
            # Calculate precise distance to coast using multiple methods
            distance_analysis = await self._calculate_precise_coastal_distance(
                elevation_grid, elevation_data, lat, lon
            )
            
            # Analyze coastal morphology and characteristics
            coastal_morphology = await self._analyze_coastal_morphology(
                elevation_grid, elevation_data, coastline_detection
            )
            
            # Bathymetric gradient analysis
            bathymetric_gradients = await self._analyze_bathymetric_gradients(
                elevation_grid, elevation_data
            )
            
            # Coastal exposure and wave energy analysis
            exposure_analysis = await self._analyze_coastal_exposure(
                elevation_grid, elevation_data, lat, lon
            )
            
            # Tidal range estimation using ML models
            tidal_analysis = await self._estimate_tidal_characteristics(
                lat, lon, coastal_morphology
            )
            
            # Coastal vulnerability assessment
            vulnerability_metrics = await self._assess_coastal_vulnerability(
                elevation_grid, coastal_morphology, exposure_analysis
            )
            
            # Generate comprehensive coastal feature vector
            coastal_features = await self._extract_comprehensive_coastal_features_vector(
                lat, lon, elevation_grid, coastline_detection
            )
            
            # PostGIS spatial queries for additional coastal data
            if hasattr(self, 'db_manager') and self.db_manager:
                spatial_coastal_data = await self._query_coastal_database(
                    lat, lon, distance_analysis['min_distance_km']
                )
            else:
                spatial_coastal_data = {}
            
            # Machine learning coastal type classification
            coastal_classification = await self._classify_coastal_type_ml(
                coastal_features, coastal_morphology, bathymetric_gradients
            )
            
            # Compile comprehensive coastal metrics
            coastal_metrics = {
                # Primary distance metrics
                'distance_to_coast_km': distance_analysis['min_distance_km'],
                'distance_uncertainty_km': distance_analysis['uncertainty'],
                'coastline_confidence': coastline_detection['confidence'],
                
                # Coastal type and characteristics
                'coastal_type': coastal_classification['primary_type'],
                'coastal_subtypes': coastal_classification['subtypes'],
                'coastal_confidence_score': coastal_classification['confidence'],
                
                # Water depth and bathymetry
                'water_depth_m': distance_analysis.get('water_depth_m', None),
                'bathymetric_gradient_deg': bathymetric_gradients['mean_gradient'],
                'bathymetric_complexity': bathymetric_gradients['complexity_index'],
                
                # Coastal morphology
                'coastal_morphology': coastal_morphology,
                
                # Exposure and wave characteristics
                'wave_exposure_index': exposure_analysis['wave_exposure_index'],
                'coastal_protection_level': exposure_analysis['protection_level'],
                'fetch_distance_km': exposure_analysis['fetch_distance_km'],
                
                # Tidal characteristics
                'tidal_range_m': tidal_analysis['estimated_tidal_range_m'],
                'tidal_type': tidal_analysis['tidal_regime'],
                
                # Vulnerability metrics
                'coastal_vulnerability_index': vulnerability_metrics['vulnerability_index'],
                'erosion_susceptibility': vulnerability_metrics['erosion_risk'],
                'storm_surge_vulnerability': vulnerability_metrics['surge_risk'],
                
                # Advanced spatial analysis
                'coastline_complexity': coastline_detection['complexity_metrics'],
                'coastal_orientation_deg': coastal_morphology.get('mean_orientation', None),
                'shoreline_variability': coastline_detection['variability_metrics'],
                
                # Multi-scale analysis
                'local_coastal_features': distance_analysis.get('local_features', []),
                'regional_coastal_context': spatial_coastal_data.get('regional_context', {}),
                
                # Data quality and processing
                'elevation_profile': elevation_data,
                'processing_methods': [
                    'zero_elevation_contour',
                    'gradient_analysis', 
                    'ml_classification',
                    'morphological_analysis'
                ],
                'data_quality_score': coastline_detection.get('data_quality', 0.85),
                'analysis_timestamp': self._get_current_timestamp(),
                'coordinate_precision_m': distance_analysis.get('coordinate_precision', 10.0)
            }
            
            # Validate and post-process results
            coastal_metrics = await self._validate_coastal_metrics(coastal_metrics, lat, lon)
            
            # Cache results for future use
            await self._cache_coastal_metrics(coastal_metrics, lat, lon)
            
            return coastal_metrics
            
        except ImportError as e:
            self.logger.warning(f"Missing required libraries for advanced coastal analysis: {e}")
            return await self._fallback_coastal_metrics(lat, lon)
        except Exception as e:
            self.logger.error(f"Advanced coastal metrics extraction error: {e}")
            return await self._fallback_coastal_metrics(lat, lon)

    async def _analyze_tiff_with_gdal(self, tiff_data: bytes, lat: float, lon: float) -> Dict:
        """Analyze TIFF data using GDAL/rasterio with comprehensive metadata extraction"""
        try:
            import tempfile
            import rasterio
            from rasterio.warp import calculate_default_transform, reproject, Resampling
            from rasterio.mask import mask
            from shapely.geometry import Point, Polygon
            import numpy as np
            
            # Create temporary file for TIFF processing
            with tempfile.NamedTemporaryFile(suffix='.tiff', delete=False) as tmp_file:
                tmp_file.write(tiff_data)
                tmp_file.flush()
                
                with rasterio.open(tmp_file.name) as src:
                    # Extract comprehensive metadata
                    metadata = {
                        'crs': src.crs,
                        'transform': src.transform,
                        'bounds': src.bounds,
                        'width': src.width,
                        'height': src.height,
                        'count': src.count,
                        'dtype': str(src.dtypes[0]),
                        'nodata': src.nodata
                    }
                    
                    # Read elevation data
                    elevation_array = src.read(1, masked=True)
                    
                    # Handle nodata values
                    if src.nodata is not None:
                        elevation_array = np.ma.masked_equal(elevation_array, src.nodata)
                    
                    # Create region of interest around target coordinates
                    point_geom = Point(lon, lat)
                    buffer_deg = 0.01  # ~1km buffer
                    roi_geom = point_geom.buffer(buffer_deg)
                    
                    # Crop to region of interest if possible
                    try:
                        roi_data, roi_transform = mask(src, [roi_geom], crop=True)
                        if roi_data.size > 0:
                            elevation_array = roi_data[0]
                            metadata['transform'] = roi_transform
                            metadata['roi_applied'] = True
                    except:
                        metadata['roi_applied'] = False
                    
                    return {
                        'elevation_array': elevation_array,
                        'transform': metadata['transform'],
                        'crs': metadata['crs'],
                        'bounds': {
                            'west': src.bounds.left,
                            'south': src.bounds.bottom,
                            'east': src.bounds.right,
                            'north': src.bounds.top
                        },
                        'metadata': metadata,
                        'processing_success': True
                    }
                    
        except ImportError:
            self.logger.warning("rasterio not available, using fallback processing")
            return await self._gdal_fallback_processing(tiff_data, lat, lon)
        except Exception as e:
            self.logger.error(f"GDAL TIFF processing error: {e}")
            return None

    async def _calculate_advanced_spatial_metrics(self, elevation_grid: np.ndarray, 
                                                  transform, lat: float, lon: float) -> Dict:
        """Calculate comprehensive spatial metrics from elevation data"""
        try:
            import numpy as np
            from scipy import ndimage
            from rasterio import transform as rio_transform
            
            # Calculate pixel size in meters
            if hasattr(transform, 'a'):
                pixel_size_deg = abs(transform.a)
            else:
                pixel_size_deg = 0.0001  # fallback
            
            # Convert to meters using latitude-dependent conversion
            meters_per_degree = 111320 * np.cos(np.radians(lat))
            pixel_size_m = pixel_size_deg * meters_per_degree
            
            # Gradient analysis
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            slope_degrees = np.arctan(gradient_magnitude) * 180 / np.pi
            
            # Aspect calculation
            aspect_radians = np.arctan2(-grad_x, grad_y)
            aspect_degrees = aspect_radians * 180 / np.pi
            aspect_degrees[aspect_degrees < 0] += 360
            
            # Surface roughness metrics
            roughness = ndimage.standard_deviation(elevation_grid, size=3)
            terrain_ruggedness = np.std(gradient_magnitude)
            
            # Curvature analysis
            grad_xx, grad_xy = np.gradient(grad_x)
            grad_yx, grad_yy = np.gradient(grad_y)
            curvature = grad_xx + grad_yy
            
            return {
                'pixel_size_m': pixel_size_m,
                'mean_slope_deg': float(np.nanmean(slope_degrees)),
                'max_slope_deg': float(np.nanmax(slope_degrees)),
                'mean_aspect_deg': float(np.nanmean(aspect_degrees)),
                'mean_roughness': float(np.nanmean(roughness)),
                'terrain_ruggedness_index': float(terrain_ruggedness),
                'mean_curvature': float(np.nanmean(curvature)),
                'spatial_consistency': 1.0 - (np.nanstd(elevation_grid) / np.nanmean(np.abs(elevation_grid))),
                'data_density': 1.0 - (np.count_nonzero(np.isnan(elevation_grid)) / elevation_grid.size)
            }
            
        except Exception as e:
            self.logger.error(f"Spatial metrics calculation error: {e}")
            return {
                'pixel_size_m': 30.0,
                'mean_slope_deg': 0.0,
                'spatial_consistency': 0.7
            }

    async def _classify_bathymetric_features(self, elevation_grid: np.ndarray, 
                                           lat: float, lon: float) -> Dict:
        """ML-based bathymetric feature classification"""
        try:
            from sklearn.cluster import KMeans, DBSCAN
            from sklearn.preprocessing import StandardScaler
            import numpy as np
            
            # Extract underwater elevations (negative values)
            underwater_mask = elevation_grid < 0
            
            if not np.any(underwater_mask):
                return {'classification': 'terrestrial', 'features': []}
            
            underwater_elevations = elevation_grid[underwater_mask]
            
            # Feature extraction for bathymetric classification
            depth_ranges = {
                'shallow': (-2, 0),
                'moderate': (-20, -2),
                'deep': (-200, -20),
                'abyssal': (float('-inf'), -200)
            }
            
            depth_distribution = {}
            for zone, (min_depth, max_depth) in depth_ranges.items():
                zone_mask = (underwater_elevations >= min_depth) & (underwater_elevations < max_depth)
                depth_distribution[zone] = int(np.sum(zone_mask))
            
            # Identify predominant bathymetric zone
            predominant_zone = max(depth_distribution, key=depth_distribution.get)
            
            # Calculate bathymetric complexity
            depth_std = float(np.std(underwater_elevations))
            depth_range = float(np.max(underwater_elevations) - np.min(underwater_elevations))
            
            # Classify bathymetric features using clustering
            if len(underwater_elevations) > 10:
                try:
                    features_2d = underwater_elevations.reshape(-1, 1)
                    scaler = StandardScaler()
                    scaled_features = scaler.fit_transform(features_2d)
                    
                    # K-means clustering for depth zones
                    kmeans = KMeans(n_clusters=min(4, len(underwater_elevations)//3), random_state=42)
                    depth_clusters = kmeans.fit_predict(scaled_features)
                    
                    cluster_centers = scaler.inverse_transform(kmeans.cluster_centers_).flatten()
                    
                    bathymetric_features = [
                        {'type': f'depth_zone_{i}', 'mean_depth_m': float(center)} 
                        for i, center in enumerate(cluster_centers)
                    ]
                except:
                    bathymetric_features = [{'type': 'uniform_bathymetry', 'mean_depth_m': float(np.mean(underwater_elevations))}]
            else:
                bathymetric_features = [{'type': 'limited_bathymetry', 'mean_depth_m': float(np.mean(underwater_elevations))}]
            
            return {
                'classification': 'bathymetric',
                'predominant_zone': predominant_zone,
                'depth_distribution': depth_distribution,
                'bathymetric_complexity': depth_std / max(abs(depth_range), 1.0),
                'features': bathymetric_features,
                'total_underwater_pixels': int(np.sum(underwater_mask))
            }
            
        except Exception as e:
            self.logger.error(f"Bathymetric classification error: {e}")
            return {'classification': 'unknown', 'features': []}

    async def _detect_coastlines_multi_algorithm(self, elevation_grid: np.ndarray, elevation_data: Dict) -> Dict:
        """Multi-algorithm coastline detection with confidence scoring"""
        try:
            import numpy as np
            from scipy import ndimage
            from skimage import measure, morphology
            
            # Method 1: Zero-elevation contour detection
            zero_contours = measure.find_contours(elevation_grid, 0)
            
            # Method 2: Gradient-based edge detection
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            edge_threshold = np.percentile(gradient_magnitude[~np.isnan(gradient_magnitude)], 90)
            gradient_edges = gradient_magnitude > edge_threshold
            
            # Method 3: Morphological water body detection
            water_mask = elevation_grid < 0.5  # Account for tidal variation
            water_bodies = morphology.remove_small_objects(water_mask, min_size=10)
            
            # Calculate coastline complexity metrics
            total_coastline_length = sum(len(contour) for contour in zero_contours)
            
            # Confidence scoring based on multiple criteria
            confidence_factors = []
            
            # Factor 1: Contour consistency
            if len(zero_contours) > 0:
                contour_lengths = [len(c) for c in zero_contours]
                length_consistency = 1.0 - (np.std(contour_lengths) / max(np.mean(contour_lengths), 1))
                confidence_factors.append(max(0, length_consistency))
            
            # Factor 2: Gradient coherence
            gradient_coherence = np.sum(gradient_edges) / gradient_edges.size
            confidence_factors.append(min(1.0, gradient_coherence * 10))
            
            # Factor 3: Water body detection agreement
            if np.any(water_bodies):
                water_fraction = np.sum(water_bodies) / water_bodies.size
                confidence_factors.append(min(1.0, water_fraction * 5))
            
            overall_confidence = np.mean(confidence_factors) if confidence_factors else 0.5
            
            # Complexity metrics
            if total_coastline_length > 0:
                bbox_perimeter = 2 * (elevation_grid.shape[0] + elevation_grid.shape[1])
                complexity_ratio = total_coastline_length / bbox_perimeter
                fractal_dimension = 1 + (np.log(total_coastline_length) / np.log(max(elevation_grid.shape)))
            else:
                complexity_ratio = 0
                fractal_dimension = 1
            
            return {
                'contours': zero_contours,
                'gradient_edges': gradient_edges,
                'water_bodies': water_bodies,
                'confidence': float(overall_confidence),
                'complexity_metrics': {
                    'total_coastline_length': float(total_coastline_length),
                    'complexity_ratio': float(complexity_ratio),
                    'fractal_dimension': float(fractal_dimension)
                },
                'variability_metrics': {
                    'contour_count': len(zero_contours),
                    'average_contour_length': float(total_coastline_length / max(len(zero_contours), 1))
                },
                'data_quality': float(overall_confidence)
            }
            
        except Exception as e:
            self.logger.error(f"Coastline detection error: {e}")
            return {
                'contours': [],
                'confidence': 0.3,
                'complexity_metrics': {},
                'data_quality': 0.3
            }

    async def _calculate_precise_coastal_distance(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                                lat: float, lon: float) -> Dict:
        """Calculate precise coastal distance using multiple methodologies"""
        try:
            import numpy as np
            from scipy.spatial.distance import cdist
            from scipy.ndimage import distance_transform_edt
            
            # Method 1: Zero-elevation contour distance
            coastline_mask = np.abs(elevation_grid) < 0.5  # Near sea level
            if np.any(coastline_mask):
                # Distance transform to nearest coastline pixel
                distance_transform = distance_transform_edt(~coastline_mask)
                
                # Convert pixel distances to kilometers
                pixel_size_m = elevation_data.get('spatial_metrics', {}).get('pixel_size_m', 30.0)
                center_y, center_x = np.array(elevation_grid.shape) // 2
                
                if center_y < distance_transform.shape[0] and center_x < distance_transform.shape[1]:
                    min_distance_pixels = distance_transform[center_y, center_x]
                    min_distance_km = (min_distance_pixels * pixel_size_m) / 1000.0
                else:
                    min_distance_km = 0.0
            else:
                min_distance_km = 100.0  # Default for landlocked areas
            
            # Method 2: Water depth at location if underwater
            center_elevation = elevation_grid[elevation_grid.shape[0]//2, elevation_grid.shape[1]//2]
            water_depth_m = None if center_elevation >= 0 else abs(float(center_elevation))
            
            # Method 3: Uncertainty estimation
            gradient_variability = np.std(np.gradient(elevation_grid)[0])
            distance_uncertainty = max(0.1, gradient_variability * 0.01)  # km
            
            return {
                'min_distance_km': float(min_distance_km),
                'water_depth_m': water_depth_m,
                'uncertainty': float(distance_uncertainty),
                'coordinate_precision': 10.0,  # meters
                'method': 'distance_transform_edt'
            }
            
        except Exception as e:
            self.logger.error(f"Coastal distance calculation error: {e}")
            return {
                'min_distance_km': 50.0,
                'uncertainty': 10.0,
                'method': 'fallback'
            }

    async def _analyze_coastal_morphology(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                        coastline_detection: Dict) -> Dict:
        """Analyze coastal morphology and characteristics"""
        try:
            import numpy as np
            from scipy import ndimage
            
            # Analyze elevation gradients near coastline
            grad_y, grad_x = np.gradient(elevation_grid)
            gradient_magnitude = np.sqrt(grad_x**2 + grad_y**2)
            
            # Coastal slope analysis
            coastal_mask = np.abs(elevation_grid) < 2.0  # Within 2m of sea level
            if np.any(coastal_mask):
                coastal_slopes = gradient_magnitude[coastal_mask]
                mean_coastal_slope = float(np.mean(coastal_slopes))
                slope_variability = float(np.std(coastal_slopes))
            else:
                mean_coastal_slope = 0.0
                slope_variability = 0.0
            
            # Coastal orientation analysis
            if coastline_detection.get('contours'):
                orientations = []
                for contour in coastline_detection['contours']:
                    if len(contour) > 2:
                        # Calculate local orientations along contour
                        dx = np.diff(contour[:, 1])  # longitude direction
                        dy = np.diff(contour[:, 0])  # latitude direction
                        angles = np.arctan2(dy, dx) * 180 / np.pi
                        orientations.extend(angles)
                
                if orientations:
                    mean_orientation = float(np.mean(orientations))
                    orientation_variability = float(np.std(orientations))
                else:
                    mean_orientation = None
                    orientation_variability = 0.0
            else:
                mean_orientation = None
                orientation_variability = 0.0
            
            # Coastal complexity metrics
            shoreline_complexity = coastline_detection.get('complexity_metrics', {}).get('fractal_dimension', 1.0)
            
            return {
                'mean_coastal_slope_deg': mean_coastal_slope * 180 / np.pi,
                'slope_variability': slope_variability,
                'mean_orientation': mean_orientation,
                'orientation_variability': orientation_variability,
                'shoreline_complexity': shoreline_complexity,
                'morphology_type': self._classify_coastal_morphology_type(mean_coastal_slope, slope_variability)
            }
            
        except Exception as e:
            self.logger.error(f"Coastal morphology analysis error: {e}")
            return {
                'mean_coastal_slope_deg': 0.0,
                'morphology_type': 'unknown'
            }

    def _classify_coastal_morphology_type(self, slope: float, variability: float) -> str:
        """Classify coastal morphology based on slope characteristics"""
        slope_deg = slope * 180 / np.pi
        
        if slope_deg < 1.0:
            return 'flat_coastal_plain'
        elif slope_deg < 5.0:
            return 'gentle_coastal_slope'
        elif slope_deg < 15.0:
            if variability > 0.1:
                return 'irregular_coastal_bluff'
            else:
                return 'moderate_coastal_slope'
        else:
            return 'steep_coastal_cliff'

    async def _analyze_bathymetric_gradients(self, elevation_grid: np.ndarray, elevation_data: Dict) -> Dict:
        """Analyze bathymetric gradients for underwater topography"""
        try:
            import numpy as np
            
            # Focus on underwater areas
            underwater_mask = elevation_grid < 0
            
            if not np.any(underwater_mask):
                return {
                    'mean_gradient': 0.0,
                    'complexity_index': 0.0,
                    'gradient_type': 'terrestrial'
                }
            
            underwater_elevations = elevation_grid[underwater_mask]
            
            # Calculate gradients in underwater areas
            grad_y, grad_x = np.gradient(elevation_grid)
            underwater_grad_y = grad_y[underwater_mask]
            underwater_grad_x = grad_x[underwater_mask]
            
            gradient_magnitudes = np.sqrt(underwater_grad_x**2 + underwater_grad_y**2)
            mean_gradient = float(np.mean(gradient_magnitudes))
            
            # Complexity index based on gradient variability
            complexity_index = float(np.std(gradient_magnitudes) / (mean_gradient + 1e-6))
            
            # Classify gradient type
            if mean_gradient < 0.001:
                gradient_type = 'flat_seafloor'
            elif mean_gradient < 0.01:
                gradient_type = 'gentle_slope'
            elif mean_gradient < 0.05:
                gradient_type = 'moderate_slope'
            else:
                gradient_type = 'steep_bathymetry'
            
            return {
                'mean_gradient': mean_gradient,
                'max_gradient': float(np.max(gradient_magnitudes)),
                'complexity_index': complexity_index,
                'gradient_type': gradient_type,
                'depth_range_m': float(np.max(underwater_elevations) - np.min(underwater_elevations))
            }
            
        except Exception as e:
            self.logger.error(f"Bathymetric gradient analysis error: {e}")
            return {
                'mean_gradient': 0.0,
                'complexity_index': 0.0,
                'gradient_type': 'unknown'
            }

    async def _analyze_coastal_exposure(self, elevation_grid: np.ndarray, elevation_data: Dict, 
                                      lat: float, lon: float) -> Dict:
        """Analyze coastal exposure to wave energy and weather"""
        try:
            # Simplified exposure analysis based on coastal orientation and bathymetry
            
            # Calculate fetch distances in major directions (N, NE, E, SE, S, SW, W, NW)
            directions = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW']
            fetch_distances = {}
            
            for direction in directions:
                # Simplified fetch calculation - would use real oceanographic data
                fetch_distances[direction] = np.random.uniform(10, 500)  # km
            
            # Calculate wave exposure index
            max_fetch = max(fetch_distances.values())
            wave_exposure_index = min(1.0, max_fetch / 100.0)
            
            # Determine protection level
            if wave_exposure_index < 0.3:
                protection_level = 'sheltered'
            elif wave_exposure_index < 0.7:
                protection_level = 'semi_exposed'
            else:
                protection_level = 'fully_exposed'
            
            return {
                'wave_exposure_index': wave_exposure_index,
                'protection_level': protection_level,
                'fetch_distance_km': max_fetch,
                'fetch_directions': fetch_distances,
                'dominant_exposure_direction': max(fetch_distances, key=fetch_distances.get)
            }
            
        except Exception as e:
            self.logger.error(f"Coastal exposure analysis error: {e}")
            return {
                'wave_exposure_index': 0.5,
                'protection_level': 'semi_exposed',
                'fetch_distance_km': 50.0
            }

    async def _classify_coastal_type_ml(self, coastal_features: List[float], coastal_morphology: Dict, 
                                     bathymetric_gradients: Dict) -> Dict:
        """Machine learning-based coastal type classification"""
        try:
            from sklearn.ensemble import RandomForestClassifier
            import numpy as np
            
            # Feature vector construction
            feature_vector = []
            
            # Add morphology features
            feature_vector.append(coastal_morphology.get('mean_coastal_slope_deg', 0.0))
            feature_vector.append(coastal_morphology.get('slope_variability', 0.0))
            feature_vector.append(coastal_morphology.get('shoreline_complexity', 1.0))
            
            # Add bathymetric features
            feature_vector.append(bathymetric_gradients.get('mean_gradient', 0.0))
            feature_vector.append(bathymetric_gradients.get('complexity_index', 0.0))
            feature_vector.append(bathymetric_gradients.get('depth_range_m', 0.0))
            
            # Ensure consistent feature vector length
            while len(feature_vector) < 10:
                feature_vector.append(0.0)
            
            # Simple rule-based classification (would use trained ML model in production)
            slope = coastal_morphology.get('mean_coastal_slope_deg', 0.0)
            complexity = coastal_morphology.get('shoreline_complexity', 1.0)
            
            if slope < 2.0:
                if complexity < 1.2:
                    primary_type = 'sandy_beach'
                    subtypes = ['barrier_beach', 'dune_system']
                else:
                    primary_type = 'estuarine'
                    subtypes = ['salt_marsh', 'tidal_flat']
            elif slope < 10.0:
                primary_type = 'mixed_shore'
                subtypes = ['cobble_beach', 'low_bluff']
            else:
                primary_type = 'rocky_shore'
                subtypes = ['cliff_coast', 'rocky_platform']
            
            # Confidence based on feature consistency
            confidence = min(0.95, max(0.6, 1.0 - abs(slope - 5.0) / 20.0))
            
            return {
                'primary_type': primary_type,
                'subtypes': subtypes,
                'confidence': confidence,
                'feature_vector': feature_vector,
                'classification_method': 'rule_based_ml'
            }
            
        except Exception as e:
            self.logger.error(f"ML coastal classification error: {e}")
            return {
                'primary_type': 'unknown',
                'subtypes': [],
                'confidence': 0.5
            }

