    async def _store_elevation_data_postgis(self, elevation_analysis: Dict, spatial_metrics: Dict, 
                                          lat: float, lon: float):
        """Store elevation data in PostGIS spatial database"""
        try:
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return
            
            # Prepare spatial data for storage
            spatial_data = {
                'location': f'POINT({lon} {lat})',
                'elevation_min_m': elevation_analysis.get('elevation_statistics', {}).get('min_elevation_m', 0),
                'elevation_max_m': elevation_analysis.get('elevation_statistics', {}).get('max_elevation_m', 0),
                'elevation_mean_m': elevation_analysis.get('elevation_statistics', {}).get('mean_elevation_m', 0),
                'slope_deg': spatial_metrics.get('mean_slope_deg', 0),
                'roughness': spatial_metrics.get('mean_roughness', 0),
                'pixel_size_m': spatial_metrics.get('pixel_size_m', 30),
                'processing_timestamp': self._get_current_timestamp(),
                'data_quality_score': elevation_analysis.get('data_quality', {}).get('confidence_score', 0.8)
            }
            
            # Insert into elevation_data table (assumes table exists from schema)
            insert_query = """
                INSERT INTO elevation_data (location, elevation_min_m, elevation_max_m, elevation_mean_m, 
                                          slope_deg, roughness, pixel_size_m, processing_timestamp, data_quality_score)
                VALUES (ST_GeomFromText(%(location)s, 4326), %(elevation_min_m)s, %(elevation_max_m)s, 
                       %(elevation_mean_m)s, %(slope_deg)s, %(roughness)s, %(pixel_size_m)s, 
                       %(processing_timestamp)s, %(data_quality_score)s)
                ON CONFLICT (location) DO UPDATE SET
                    elevation_min_m = EXCLUDED.elevation_min_m,
                    elevation_max_m = EXCLUDED.elevation_max_m,
                    elevation_mean_m = EXCLUDED.elevation_mean_m,
                    slope_deg = EXCLUDED.slope_deg,
                    roughness = EXCLUDED.roughness,
                    processing_timestamp = EXCLUDED.processing_timestamp,
                    data_quality_score = EXCLUDED.data_quality_score
            """
            
            await self.db_manager.execute_query(insert_query, spatial_data)
            self.logger.info(f"Stored elevation data in PostGIS for location ({lat}, {lon})")
            
        except Exception as e:
            self.logger.error(f"PostGIS elevation data storage error: {e}")

    async def _query_coastal_database(self, lat: float, lon: float, distance_km: float) -> Dict:
        """Query PostGIS database for additional coastal information"""
        try:
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return {}
            
            # Query for nearby coastal features within specified distance
            query = """
                SELECT 
                    ST_AsText(location) as location_text,
                    distance_to_coast_km,
                    coastal_type,
                    water_depth_m,
                    data_quality_score,
                    ST_Distance(location, ST_GeomFromText('POINT(%s %s)', 4326)) * 111.32 as distance_km
                FROM coastal_metrics 
                WHERE ST_DWithin(location, ST_GeomFromText('POINT(%s %s)', 4326), %s / 111.32)
                ORDER BY distance_km
                LIMIT 10
            """
            
            params = [lon, lat, lon, lat, distance_km]
            results = await self.db_manager.fetch_all(query, params)
            
            if results:
                regional_context = {
                    'nearby_coastal_points': len(results),
                    'average_coastal_distance_km': sum(r['distance_to_coast_km'] for r in results) / len(results),
                    'predominant_coastal_type': max(set(r['coastal_type'] for r in results if r['coastal_type']), 
                                                  key=[r['coastal_type'] for r in results].count),
                    'data_density': len(results) / max(1, distance_km**2),
                    'quality_distribution': {
                        'high': sum(1 for r in results if r['data_quality_score'] > 0.8),
                        'medium': sum(1 for r in results if 0.5 < r['data_quality_score'] <= 0.8),
                        'low': sum(1 for r in results if r['data_quality_score'] <= 0.5)
                    }
                }
            else:
                regional_context = {
                    'nearby_coastal_points': 0,
                    'data_density': 0,
                    'note': 'No coastal data within query radius'
                }
            
            return {'regional_context': regional_context}
            
        except Exception as e:
            self.logger.error(f"Coastal database query error: {e}")
            return {}

    async def _quantify_elevation_uncertainty(self, elevation_grid: np.ndarray, spatial_metrics: Dict) -> Dict:
        """Quantify uncertainty in elevation data processing"""
        try:
            import numpy as np
            from scipy import stats
            
            # Statistical uncertainty analysis
            elevation_variance = float(np.var(elevation_grid))
            elevation_skewness = float(stats.skew(elevation_grid.flatten()))
            elevation_kurtosis = float(stats.kurtosis(elevation_grid.flatten()))
            
            # Data completeness assessment
            valid_pixels = np.count_nonzero(~np.isnan(elevation_grid))
            total_pixels = elevation_grid.size
            completeness = valid_pixels / total_pixels
            
            # Spatial consistency metrics
            spatial_consistency = spatial_metrics.get('spatial_consistency', 0.8)
            
            # Overall confidence calculation
            confidence_factors = [
                min(1.0, completeness),
                spatial_consistency,
                min(1.0, 1.0 / (1.0 + abs(elevation_skewness))),  # Lower skewness = higher confidence
                min(1.0, 1.0 / (1.0 + abs(elevation_kurtosis - 3.0) / 10.0))  # Normal kurtosis = higher confidence
            ]
            
            overall_confidence = float(np.mean(confidence_factors))
            
            # Uncertainty estimates
            elevation_uncertainty_m = float(np.sqrt(elevation_variance)) * (1.0 - overall_confidence)
            
            return {
                'overall_confidence': overall_confidence,
                'elevation_uncertainty_m': elevation_uncertainty_m,
                'data_completeness': completeness,
                'statistical_measures': {
                    'variance': elevation_variance,
                    'skewness': elevation_skewness,
                    'kurtosis': elevation_kurtosis
                },
                'spatial_consistency': spatial_consistency,
                'confidence_factors': confidence_factors
            }
            
        except Exception as e:
            self.logger.error(f"Uncertainty quantification error: {e}")
            return {
                'overall_confidence': 0.7,
                'elevation_uncertainty_m': 5.0
            }

    async def _analyze_coastal_zone_features(self, elevation_grid: np.ndarray, transform, 
                                           lat: float, lon: float) -> Dict:
        """Analyze coastal zone features and characteristics"""
        try:
            import numpy as np
            from scipy import ndimage
            
            # Define coastal zone (areas within 5m of sea level)
            coastal_zone_mask = np.abs(elevation_grid) <= 5.0
            
            if not np.any(coastal_zone_mask):
                return {
                    'coastal_zone_present': False,
                    'analysis': 'No coastal zone detected in elevation data'
                }
            
            coastal_elevations = elevation_grid[coastal_zone_mask]
            
            # Analyze coastal zone characteristics
            zone_stats = {
                'mean_elevation_m': float(np.mean(coastal_elevations)),
                'elevation_range_m': float(np.max(coastal_elevations) - np.min(coastal_elevations)),
                'coastal_zone_area_pixels': int(np.sum(coastal_zone_mask)),
                'elevation_variability': float(np.std(coastal_elevations))
            }
            
            # Identify potential coastal features
            features = []
            
            # Beach/dune systems (positive elevations 0-3m)
            beach_mask = (elevation_grid >= 0) & (elevation_grid <= 3) & coastal_zone_mask
            if np.any(beach_mask):
                features.append({
                    'type': 'beach_dune_system',
                    'area_pixels': int(np.sum(beach_mask)),
                    'mean_elevation_m': float(np.mean(elevation_grid[beach_mask]))
                })
            
            # Tidal zones (elevations -2 to 2m)
            tidal_mask = (elevation_grid >= -2) & (elevation_grid <= 2) & coastal_zone_mask
            if np.any(tidal_mask):
                features.append({
                    'type': 'tidal_zone',
                    'area_pixels': int(np.sum(tidal_mask)),
                    'elevation_range_m': float(np.max(elevation_grid[tidal_mask]) - np.min(elevation_grid[tidal_mask]))
                })
            
            # Shallow water areas (-5 to 0m)
            shallow_water_mask = (elevation_grid >= -5) & (elevation_grid < 0) & coastal_zone_mask
            if np.any(shallow_water_mask):
                features.append({
                    'type': 'shallow_water',
                    'area_pixels': int(np.sum(shallow_water_mask)),
                    'mean_depth_m': float(abs(np.mean(elevation_grid[shallow_water_mask])))
                })
            
            return {
                'coastal_zone_present': True,
                'zone_statistics': zone_stats,
                'identified_features': features,
                'feature_count': len(features),
                'analysis_method': 'elevation_threshold_analysis'
            }
            
        except Exception as e:
            self.logger.error(f"Coastal zone analysis error: {e}")
            return {
                'coastal_zone_present': False,
                'analysis': f'Error in analysis: {str(e)}'
            }

    async def _extract_multiscale_features(self, elevation_grid: np.ndarray, kernel_sizes: List[int]) -> Dict:
        """Extract multi-scale features from elevation data"""
        try:
            import numpy as np
            from scipy import ndimage
            
            multiscale_features = {}
            
            for kernel_size in kernel_sizes:
                # Apply Gaussian filter at different scales
                smoothed = ndimage.gaussian_filter(elevation_grid, sigma=kernel_size/3.0)
                
                # Calculate features at this scale
                scale_features = {
                    'mean_elevation': float(np.nanmean(smoothed)),
                    'elevation_std': float(np.nanstd(smoothed)),
                    'local_extrema_count': self._count_local_extrema(smoothed),
                    'gradient_magnitude': float(np.nanmean(np.sqrt(np.sum(np.array(np.gradient(smoothed))**2, axis=0))))
                }
                
                multiscale_features[f'scale_{kernel_size}'] = scale_features
            
            # Calculate cross-scale relationships
            scale_consistency = self._calculate_scale_consistency(multiscale_features)
            
            return {
                'scale_features': multiscale_features,
                'scale_consistency': scale_consistency,
                'analyzed_scales': kernel_sizes
            }
            
        except Exception as e:
            self.logger.error(f"Multiscale feature extraction error: {e}")
            return {
                'scale_features': {},
                'analyzed_scales': []
            }

    def _count_local_extrema(self, data: np.ndarray) -> int:
        """Count local extrema (peaks and valleys) in elevation data"""
        try:
            from scipy.signal import find_peaks
            
            # Flatten data for 1D analysis
            data_1d = data.flatten()
            
            # Find peaks and valleys
            peaks, _ = find_peaks(data_1d)
            valleys, _ = find_peaks(-data_1d)
            
            return len(peaks) + len(valleys)
            
        except:
            return 0

    def _calculate_scale_consistency(self, multiscale_features: Dict) -> float:
        """Calculate consistency across different scales"""
        try:
            import numpy as np
            
            if not multiscale_features:
                return 0.0
            
            # Extract mean elevations across scales
            mean_elevations = [features['mean_elevation'] for features in multiscale_features.values()]
            
            if len(mean_elevations) < 2:
                return 1.0
            
            # Calculate coefficient of variation across scales
            cv = np.std(mean_elevations) / (abs(np.mean(mean_elevations)) + 1e-6)
            
            # Convert to consistency score (0-1, higher is more consistent)
            consistency = max(0.0, 1.0 - cv)
            
            return float(consistency)
            
        except:
            return 0.5

    async def _generate_elevation_profile(self, elevation_grid: np.ndarray, transform, 
                                        lat: float, lon: float, radius_m: float = 5000) -> Dict:
        """Generate radial elevation profile around target location"""
        try:
            import numpy as np
            
            center_y, center_x = np.array(elevation_grid.shape) // 2
            
            # Create radial profile
            y_indices, x_indices = np.ogrid[:elevation_grid.shape[0], :elevation_grid.shape[1]]
            distances = np.sqrt((y_indices - center_y)**2 + (x_indices - center_x)**2)
            
            # Bin by distance
            max_distance = min(center_y, center_x, elevation_grid.shape[0] - center_y, elevation_grid.shape[1] - center_x)
            distance_bins = np.linspace(0, max_distance, 20)
            
            profile_elevations = []
            profile_distances = []
            
            for i in range(len(distance_bins) - 1):
                mask = (distances >= distance_bins[i]) & (distances < distance_bins[i + 1])
                if np.any(mask):
                    mean_elevation = float(np.nanmean(elevation_grid[mask]))
                    mean_distance = float((distance_bins[i] + distance_bins[i + 1]) / 2)
                    profile_elevations.append(mean_elevation)
                    profile_distances.append(mean_distance)
            
            return {
                'radial_distances': profile_distances,
                'elevations': profile_elevations,
                'profile_length': len(profile_elevations),
                'max_radius_pixels': float(max_distance)
            }
            
        except Exception as e:
            self.logger.error(f"Elevation profile generation error: {e}")
            return {
                'radial_distances': [],
                'elevations': [],
                'profile_length': 0
            }

    async def _cache_elevation_data(self, processed_data: Dict, lat: float, lon: float):
        """Cache processed elevation data for future use"""
        try:
            if hasattr(self, '_elevation_cache'):
                cache_key = f"{lat:.6f}_{lon:.6f}"
                self._elevation_cache[cache_key] = {
                    'data': processed_data,
                    'timestamp': self._get_current_timestamp()
                }
                
                # Limit cache size
                if len(self._elevation_cache) > 100:
                    oldest_key = min(self._elevation_cache.keys(), 
                                   key=lambda k: self._elevation_cache[k]['timestamp'])
                    del self._elevation_cache[oldest_key]
        except Exception as e:
            self.logger.error(f"Elevation data caching error: {e}")

