    async def _validate_coastal_metrics(self, coastal_metrics: Dict, lat: float, lon: float) -> Dict:
        """Validate and post-process coastal metrics"""
        try:
            # Validate distance ranges
            distance = coastal_metrics.get('distance_to_coast_km', 0)
            if distance < 0:
                coastal_metrics['distance_to_coast_km'] = 0.0
            elif distance > 10000:  # Unlikely to be more than 10,000 km from coast
                coastal_metrics['distance_to_coast_km'] = 10000.0
            
            # Validate depth values
            if 'water_depth_m' in coastal_metrics and coastal_metrics['water_depth_m'] is not None:
                if coastal_metrics['water_depth_m'] < 0:
                    coastal_metrics['water_depth_m'] = 0.0
            
            # Ensure confidence scores are in valid range
            for key in ['coastal_confidence_score', 'coastline_confidence']:
                if key in coastal_metrics:
                    coastal_metrics[key] = max(0.0, min(1.0, coastal_metrics[key]))
            
            return coastal_metrics
            
        except Exception as e:
            self.logger.error(f"Coastal metrics validation error: {e}")
            return coastal_metrics

