    async def _extract_comprehensive_coastal_features(self, lat: float, lon: float) -> List[float]:
        """Extract comprehensive feature vector for ML coastal analysis"""
        try:
            features = [lat, lon]
            
            # Add elevation if available
            elevation = await self._get_elevation_data(lat, lon)
            features.append(elevation if elevation is not None else 0.0)
            
            # Add precipitation/climate data
            precipitation = await self._get_climate_data(lat, lon, 'precipitation')
            features.append(precipitation if precipitation is not None else 500.0)
            
            # Add temperature data
            temperature = await self._get_climate_data(lat, lon, 'temperature')
            features.append(temperature if temperature is not None else 15.0)
            
            # Add vegetation index (NDVI) if available
            ndvi = await self._get_vegetation_index(lat, lon)
            features.append(ndvi if ndvi is not None else 0.5)
            
            # Add geological features
            geology_features = await self._get_geological_features(lat, lon)
            features.extend(geology_features)
            
            # Add hydrological connectivity
            hydro_connectivity = await self._calculate_hydrological_connectivity(lat, lon)
            features.append(hydro_connectivity)
            
            return features[:15]  # Limit to 15 features for model consistency
            
        except Exception as e:
            self.logger.error(f"Coastal feature extraction error: {e}")
            return [lat, lon] + [0.0] * 13  # Fallback minimal features

    async def _get_elevation_data(self, lat: float, lon: float) -> float:
        """Get elevation data using multi-source integration with database caching"""
        try:
            from .external_data_connectors import DataIntegrationManager
            from datetime import datetime
            import aiohttp
            
            # First check database cache
            cache_key = f"elevation_{lat:.6f}_{lon:.6f}"
            
            # Try multiple elevation sources in priority order
            elevation_sources = [
                self._get_srtm_elevation,
                self._get_usgs_elevation, 
                self._get_nasa_dem_elevation,
                self._get_open_topography_elevation
            ]
            
            for source_func in elevation_sources:
                try:
                    elevation = await source_func(lat, lon)
                    if elevation is not None and elevation > -1000:  # Valid elevation
                        # Cache result for future use
                        await self._cache_elevation_data(lat, lon, elevation, source_func.__name__)
                        return float(elevation)
                except Exception as e:
                    self.logger.warning(f"Elevation source {source_func.__name__} failed: {e}")
                    continue
            
            # Fallback: interpolate from nearby cached points
            nearby_elevation = await self._interpolate_nearby_elevation(lat, lon)
            if nearby_elevation is not None:
                return float(nearby_elevation)
            
            # Final fallback: use geological structure data
            return await self._estimate_elevation_from_geology(lat, lon)
            
        except Exception as e:
            self.logger.error(f"All elevation sources failed for {lat}, {lon}: {e}")
            return 0.0
    
    async def _get_srtm_elevation(self, lat: float, lon: float) -> Optional[float]:
        """Get elevation from SRTM (Shuttle Radar Topography Mission) data"""
        try:
            import aiohttp
            
            # USGS Elevation Point Query Service
            url = "https://nationalmap.gov/epqs/pqs.php"
            params = {
                'x': lon,
                'y': lat,
                'units': 'Meters',
                'output': 'json'
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(url, params=params, timeout=10) as response:
                    if response.status == 200:
                        data = await response.json()
                        if 'USGS_Elevation_Point_Query_Service' in data:
                            result = data['USGS_Elevation_Point_Query_Service']['Elevation_Query']
                            if result['Elevation'] != -1000000:  # Valid elevation
                                return float(result['Elevation'])
            return None
        except Exception:
            return None
    
    async def _get_usgs_elevation(self, lat: float, lon: float) -> Optional[float]:
        """Get elevation from USGS National Elevation Dataset using existing connector"""
        try:
            from .external_data_connectors import USGSConnector
            
            # Use external data connector for USGS data
            usgs_connector = USGSConnector(rate_limit=1.0)
            
            # Query geological data with elevation info in nearby area
            bbox = (lon - 0.01, lat - 0.01, lon + 0.01, lat + 0.01)
            geological_data = usgs_connector.get_mineral_resources_data(bbox=bbox)
            
            if geological_data:
                # Use elevation from nearest geological feature
                min_distance = float('inf')
                best_elevation = None
                
                for record in geological_data:
                    if hasattr(record, 'coordinates') and len(record.coordinates) > 2:
                        record_lat, record_lon, record_elev = record.coordinates
                        distance = ((lat - record_lat)**2 + (lon - record_lon)**2)**0.5
                        if distance < min_distance and record_elev > -1000:
                            min_distance = distance
                            best_elevation = record_elev
                
                return best_elevation
            return None
        except Exception:
            return None
    
