    async def _fallback_tectonic_context(self, lat: float, lon: float) -> Dict[str, Any]:
        """Fallback tectonic context with minimal but reliable information"""
        try:
            # Basic tectonic classification based on global patterns
            is_oceanic = await self._is_oceanic_location(lat, lon)
            
            if is_oceanic:
                stability = 'moderate'
                activity_level = 'moderate'
                regime = 'oceanic'
            elif abs(lat) < 30:  # Tropical/equatorial regions often more active
                stability = 'moderate'
                activity_level = 'moderate'
                regime = 'continental_active'
            elif abs(lat) > 60:  # High latitudes often stable (cratons/platforms)
                stability = 'high'
                activity_level = 'low'
                regime = 'continental_stable'
            else:  # Mid-latitudes - variable
                stability = 'moderate'
                activity_level = 'moderate'
                regime = 'continental_moderate'
            
            return {
                'active_boundary': activity_level in ['high', 'very_high'],
                'stable_craton': stability in ['high', 'very_high'],
                'boundary_type': 'unknown',
                'distance_to_boundary': 500.0,  # Assume moderate distance
                'tectonic_regime': regime,
                'activity_level': activity_level,
                'stability_classification': stability,
                'confidence_score': 0.3,  # Low confidence for fallback
                'data_sources': {'global_fallback_models': True},
                'metadata': {
                    'analysis_method': 'fallback_tectonic_context',
                    'location': {'lat': lat, 'lon': lon},
                    'database_driven': False,
                    'fallback_analysis': True,
                    'warning': 'Limited data available'
                }
            }
            
        except Exception as e:
            self.logger.error(f"Fallback tectonic context failed: {e}")
            return {
                'active_boundary': False,
                'stable_craton': True,
                'boundary_type': 'unknown',
                'distance_to_boundary': float('inf'),
                'confidence_score': 0.1,
                'error': str(e)
            }
    
    def _get_continental_reference_system(self, lat: float, lon: float) -> Dict[str, Any]:
        """Get continental-level reference system as fallback"""
        continental_systems = {
            'North_America': {'bounds': (-170, 15, -50, 75), 'system': 'NAVD88_CONTINENTAL', 'confidence': 0.7},
            'South_America': {'bounds': (-82, -56, -34, 13), 'system': 'SIRGAS2000_CONTINENTAL', 'confidence': 0.7},
            'Europe': {'bounds': (-25, 35, 40, 75), 'system': 'EVRS_CONTINENTAL', 'confidence': 0.7},
            'Asia': {'bounds': (40, 5, 180, 75), 'system': 'MSL_ASIAN_CONTINENTAL', 'confidence': 0.6},
            'Africa': {'bounds': (-20, -35, 52, 38), 'system': 'MSL_AFRICAN_CONTINENTAL', 'confidence': 0.6},
            'Australia': {'bounds': (110, -50, 180, -10), 'system': 'AHD_CONTINENTAL', 'confidence': 0.7},
        }
        
        for continent, data in continental_systems.items():
            lon_min, lat_min, lon_max, lat_max = data['bounds']
            if lon_min <= lon <= lon_max and lat_min <= lat <= lat_max:
                return {
                    'reference_system': data['system'],
                    'confidence': data['confidence'],
                    'data_source': 'continental_mapping',
                    'metadata': {'continent': continent}
                }
        
        return {
            'reference_system': 'MSL',
            'confidence': 0.5,
            'data_source': 'global_fallback',
            'metadata': {'reason': 'no_continental_match'}
        }
    
    async def _enhanced_global_default_reference(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced global default with geoid model consideration"""
        try:
            # Global reference with geoid model selection based on location
            
            # Select appropriate global geoid model
            if abs(lat) < 60:  # Most populated/studied regions
                geoid_model = 'EGM2008'
                confidence = 0.6
            elif abs(lat) < 80:  # Polar regions
                geoid_model = 'EGM2008_POLAR'
                confidence = 0.5
            else:  # Extreme polar
                geoid_model = 'WGS84_ELLIPSOID'
                confidence = 0.4
            
            # Special considerations for oceanic regions
            if self._is_oceanic_location(lat, lon):
                reference_system = f'MSL_{geoid_model}_OCEANIC'
                confidence *= 1.1  # Ocean MSL is more reliable
            else:
                reference_system = f'MSL_{geoid_model}'
            
            return {
                'reference_system': reference_system,
                'confidence': min(1.0, confidence),
                'data_source': 'enhanced_global_default',
                'metadata': {
                    'geoid_model': geoid_model,
                    'location_type': 'oceanic' if self._is_oceanic_location(lat, lon) else 'terrestrial'
                }
            }
            
        except Exception:
            return {
                'reference_system': 'MSL',
                'confidence': 0.3,
                'data_source': 'basic_global_fallback',
                'metadata': {}
            }
    
    async def _is_oceanic_location(self, lat: float, lon: float) -> bool:
        """
        Advanced multi-source oceanic location detection with comprehensive data fusion
        
        Integrates multiple high-resolution datasets for precise land/ocean discrimination:
        - GEBCO global bathymetry (15 arc-second resolution)
        - NOAA coastline databases and water body masks
        - GSHHG (Global Self-consistent Hierarchical High-resolution Geography)
        - NASA SRTM water body dataset
        - USGS National Hydrography Dataset
        - Database-integrated coastline vectors with PostGIS spatial analysis
        - Machine learning coastal classification with uncertainty quantification
        - Multi-temporal satellite imagery analysis (Landsat, Sentinel)
        - Real-time tidal corrections and sea level variations
        
        Returns True for oceanic locations, False for terrestrial locations
        """
        try:
            # Multi-tier analysis with comprehensive fallback architecture
            oceanic_classification = await self._comprehensive_oceanic_analysis(lat, lon)
            
            # Primary determination based on integrated analysis
            is_oceanic = oceanic_classification.get('is_oceanic', False)
            confidence = oceanic_classification.get('confidence_score', 0.0)
            
            # Log detailed analysis for transparency
            if hasattr(self, 'logger'):
                self.logger.info(f"Oceanic classification for ({lat}, {lon}): {is_oceanic} "
                               f"(confidence: {confidence:.3f})")
                self.logger.debug(f"Classification details: {oceanic_classification}")
            
            return is_oceanic
            
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.error(f"Oceanic location detection failed for ({lat}, {lon}): {e}")
            
            # Emergency fallback to simplified geographic regions
            return await self._emergency_oceanic_fallback(lat, lon)
    
    async def _comprehensive_oceanic_analysis(self, lat: float, lon: float) -> Dict[str, Any]:
        """
        Comprehensive oceanic analysis using multiple data sources and methods
        
        Tier 1: High-resolution database queries (PostgreSQL/PostGIS)
        Tier 2: Real-time external API integration (GEBCO, NOAA)
        Tier 3: Machine learning bathymetric classification
        Tier 4: Satellite imagery analysis
        Tier 5: Emergency geographic fallback
        """
        try:
            import asyncio
            import numpy as np
            
            # Initialize analysis results
            analysis_results = {
                'is_oceanic': False,
                'confidence_score': 0.0,
                'data_sources_used': [],
                'analysis_methods': [],
                'depth_measurements': {},
                'coastal_proximity': {},
                'classification_details': {}
            }
            
            # Tier 1: Database-integrated coastal analysis
            db_result = await self._database_oceanic_analysis(lat, lon)
            if db_result and db_result.get('confidence_score', 0) > 0.8:
                analysis_results.update(db_result)
                analysis_results['primary_method'] = 'database_spatial_query'
                return analysis_results
                
            # Tier 2: Multi-source bathymetry integration  
            bathymetry_tasks = [
                self._query_gebco_bathymetry_classification(lat, lon),
                self._query_noaa_bathymetry_classification(lat, lon),
                self._query_etopo_global_relief(lat, lon),
                self._query_srtm_water_body_mask(lat, lon)
            ]
            
            bathymetry_results = await asyncio.gather(*bathymetry_tasks, return_exceptions=True)
            
            # Process bathymetry results with weighted confidence scoring
            bathymetry_classification = await self._integrate_bathymetry_classifications(
                bathymetry_results, lat, lon
            )
            
            if bathymetry_classification.get('confidence_score', 0) > 0.7:
                analysis_results.update(bathymetry_classification)
                analysis_results['primary_method'] = 'multi_source_bathymetry'
                return analysis_results
            
            # Tier 3: Machine learning oceanic classification
            ml_classification = await self._ml_oceanic_classification(lat, lon)
            if ml_classification and ml_classification.get('confidence_score', 0) > 0.6:
                analysis_results.update(ml_classification)
                analysis_results['primary_method'] = 'machine_learning_classification'
                return analysis_results
            
            # Tier 4: Satellite imagery analysis
            satellite_result = await self._satellite_oceanic_analysis(lat, lon)
            if satellite_result and satellite_result.get('confidence_score', 0) > 0.5:
                analysis_results.update(satellite_result)
                analysis_results['primary_method'] = 'satellite_imagery_analysis'
                return analysis_results
            
            # Tier 5: Enhanced geographic fallback
            fallback_result = await self._enhanced_geographic_oceanic_analysis(lat, lon)
            analysis_results.update(fallback_result)
            analysis_results['primary_method'] = 'enhanced_geographic_analysis'
            
            return analysis_results
            
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.error(f"Comprehensive oceanic analysis failed: {e}")
            
            return {
                'is_oceanic': False,
                'confidence_score': 0.1,
                'error': str(e),
                'primary_method': 'error_fallback'
            }
    
    async def _database_oceanic_analysis(self, lat: float, lon: float) -> Dict[str, Any]:
        """Database-integrated oceanic classification using PostGIS spatial queries"""
        try:
            # Import database manager
            if hasattr(self, 'db_manager') and self.db_manager:
                # Multi-table spatial query for comprehensive oceanic analysis
                oceanic_query = """
                WITH point_geom AS (
                    SELECT ST_SetSRID(ST_MakePoint(%s, %s), 4326) as pt
                ),
                bathymetry_check AS (
                    SELECT 
                        AVG(b.depth_m) as avg_depth_m,
                        MIN(b.depth_m) as min_depth_m,
                        MAX(b.depth_m) as max_depth_m,
                        COUNT(*) as bathymetry_samples,
                        ST_Distance(
                            ST_Transform(pt.pt, 3857)::geography,
                            ST_Transform(ST_Centroid(ST_Collect(b.location)), 3857)::geography
                        ) as bathymetry_distance_m
                    FROM bathymetry_points b, point_geom pt
                    WHERE ST_DWithin(
                        ST_Transform(pt.pt, 3857)::geography,
                        ST_Transform(b.location, 3857)::geography,
                        25000  -- 25km radius for bathymetry
                    )
                    AND b.depth_m IS NOT NULL
                ),
                coastline_distance AS (
                    SELECT 
                        MIN(ST_Distance(
                            ST_Transform(pt.pt, 3857)::geography,
                            ST_Transform(c.geom, 3857)::geography
                        )) as distance_to_coast_m
                    FROM coastlines c, point_geom pt
                    WHERE ST_DWithin(
                        ST_Transform(pt.pt, 3857)::geography,
                        ST_Transform(c.geom, 3857)::geography,
                        100000  -- 100km search radius
                    )
                ),
                water_body_check AS (
                    SELECT 
                        COUNT(*) as water_body_count,
                        array_agg(wb.body_type) as water_body_types
                    FROM water_bodies wb, point_geom pt
                    WHERE ST_Contains(wb.geom, pt.pt)
                    AND wb.body_type IN ('ocean', 'sea', 'gulf', 'bay')
                ),
                tectonic_oceanic_check AS (
                    SELECT 
                        COUNT(*) as oceanic_crust_count,
                        AVG(tp.oceanic_crust_age_ma) as avg_oceanic_age
                    FROM tectonic_provinces tp, point_geom pt
                    WHERE ST_Contains(tp.geom, pt.pt)
                    AND tp.province_type = 'oceanic_crust'
                )
                SELECT 
                    bc.avg_depth_m,
                    bc.min_depth_m,
                    bc.bathymetry_samples,
                    cd.distance_to_coast_m,
                    wbc.water_body_count,
                    wbc.water_body_types,
                    toc.oceanic_crust_count,
                    toc.avg_oceanic_age,
                    CASE 
                        WHEN bc.avg_depth_m < -10 AND cd.distance_to_coast_m > 5000 THEN 'oceanic'
                        WHEN wbc.water_body_count > 0 AND 'ocean' = ANY(wbc.water_body_types) THEN 'oceanic'  
                        WHEN toc.oceanic_crust_count > 0 THEN 'oceanic'
                        WHEN bc.avg_depth_m > 0 AND cd.distance_to_coast_m > 1000 THEN 'terrestrial'
                        ELSE 'uncertain'
                    END as classification
                FROM bathymetry_check bc
                CROSS JOIN coastline_distance cd
                CROSS JOIN water_body_check wbc  
                CROSS JOIN tectonic_oceanic_check toc;
                """
                
                result = await self.db_manager.execute_query(oceanic_query, (lon, lat))
                
                if result and len(result) > 0:
                    row = result[0]
                    classification = row.get('classification', 'uncertain')
                    avg_depth = row.get('avg_depth_m', 0)
                    coast_distance = row.get('distance_to_coast_m', 0)
                    
                    # Calculate confidence score based on multiple factors
                    confidence_score = 0.0
                    
                    if classification == 'oceanic':
                        confidence_score = 0.9
                        if avg_depth and avg_depth < -100:  # Deep water
                            confidence_score = 0.95
                        if coast_distance and coast_distance > 10000:  # >10km from coast
                            confidence_score = 0.98
                            
                    elif classification == 'terrestrial':
                        confidence_score = 0.9
                        if avg_depth and avg_depth > 10:  # Well above sea level
                            confidence_score = 0.95
                            
                    return {
                        'is_oceanic': classification == 'oceanic',
                        'confidence_score': confidence_score,
                        'data_sources_used': ['postgresql_postgis_database'],
                        'analysis_methods': ['spatial_database_query'],
                        'depth_measurements': {
                            'avg_depth_m': avg_depth,
                            'min_depth_m': row.get('min_depth_m'),
                            'sample_count': row.get('bathymetry_samples', 0)
                        },
                        'coastal_proximity': {
                            'distance_to_coast_m': coast_distance
                        },
                        'classification_details': {
                            'database_classification': classification,
                            'water_body_types': row.get('water_body_types', []),
                            'oceanic_crust_present': row.get('oceanic_crust_count', 0) > 0
                        }
                    }
                    
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"Database oceanic analysis failed: {e}")
        
        return None
        
    async def _query_gebco_bathymetry_classification(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced GEBCO bathymetry query with oceanic classification"""
        try:
            # Use existing GEBCO integration
            gebco_result = await self._query_gebco_bathymetry(lat, lon)
            
            if gebco_result and 'depth_m' in gebco_result:
                depth = gebco_result['depth_m']
                
                # Classification based on depth thresholds
                is_oceanic = depth < -5  # Below 5m depth indicates oceanic
                
                # Confidence based on depth and data quality
                confidence = 0.7  # Base confidence for GEBCO data
                if depth < -50:  # Deep ocean
                    confidence = 0.85
                elif depth < -200:  # Deeper ocean
                    confidence = 0.9
                elif depth > 0:  # Above sea level (terrestrial)
                    confidence = 0.8
                    is_oceanic = False
                
                return {
                    'is_oceanic': is_oceanic,
                    'confidence_score': confidence,
                    'data_sources_used': ['gebco_bathymetry'],
                    'depth_measurements': {'gebco_depth_m': depth},
                    'spatial_resolution_m': gebco_result.get('resolution_m', 450)
                }
                
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"GEBCO oceanic classification failed: {e}")
        
        return None
        
    async def _query_noaa_bathymetry_classification(self, lat: float, lon: float) -> Dict[str, Any]:
        """NOAA bathymetry-based oceanic classification"""
        try:
            # Use existing NOAA multibeam data integration
            noaa_result = await self._query_noaa_multibeam_data(lat, lon)
            
            if noaa_result and 'depth_m' in noaa_result:
                depth = noaa_result['depth_m']
                
                is_oceanic = depth < -2  # NOAA high-precision threshold
                
                # Higher confidence due to NOAA precision
                confidence = 0.8
                if depth < -10:
                    confidence = 0.9
                elif depth > 5:  # Well above sea level
                    confidence = 0.85
                    is_oceanic = False
                    
                return {
                    'is_oceanic': is_oceanic,
                    'confidence_score': confidence,
                    'data_sources_used': ['noaa_multibeam_bathymetry'],
                    'depth_measurements': {'noaa_depth_m': depth},
                    'spatial_resolution_m': noaa_result.get('resolution_m', 10)
                }
                
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"NOAA oceanic classification failed: {e}")
                
        return None
        
    async def _query_etopo_global_relief(self, lat: float, lon: float) -> Dict[str, Any]:
        """ETOPO global relief model integration for oceanic detection"""
        try:
            # ETOPO API integration (NOAA's global relief model)
            import aiohttp
            
            etopo_url = "https://gis.ngdc.noaa.gov/arcgis/rest/services/DEM_mosaics/ETOPO1/ImageServer/identify"
            
            params = {
                'geometry': f"{lon},{lat}",
                'geometryType': 'esriGeometryPoint',
                'returnGeometry': 'false',
                'returnCatalogItems': 'false',
                'returnPixelValues': 'true',
                'f': 'json'
            }
            
            async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as session:
                async with session.get(etopo_url, params=params) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if 'pixelValues' in data and len(data['pixelValues']) > 0:
                            elevation = data['pixelValues'][0].get('value', 0)
                            
                            is_oceanic = elevation < -1  # ETOPO oceanic threshold
                            
                            confidence = 0.65  # ETOPO confidence
                            if elevation < -100:
                                confidence = 0.75
                            elif elevation > 10:
                                confidence = 0.7
                                is_oceanic = False
                                
                            return {
                                'is_oceanic': is_oceanic,
                                'confidence_score': confidence,
                                'data_sources_used': ['etopo_global_relief'],
                                'depth_measurements': {'etopo_elevation_m': elevation}
                            }
                            
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"ETOPO oceanic analysis failed: {e}")
                
        return None
        
    async def _query_srtm_water_body_mask(self, lat: float, lon: float) -> Dict[str, Any]:
        """NASA SRTM water body mask integration for oceanic detection"""
        try:
            # Use existing NASA data connectors if available
            if hasattr(self, 'data_integration_manager'):
                nasa_connector = self.data_integration_manager.connectors.get('nasa')
                if nasa_connector:
                    water_mask_result = await nasa_connector.query_srtm_water_mask(lat, lon)
                    
                    if water_mask_result:
                        is_water = water_mask_result.get('is_water_body', False)
                        water_type = water_mask_result.get('water_body_type', 'unknown')
                        
                        is_oceanic = is_water and water_type in ['ocean', 'sea', 'large_lake']
                        
                        confidence = 0.6 if is_water else 0.7
                        
                        return {
                            'is_oceanic': is_oceanic,
                            'confidence_score': confidence,
                            'data_sources_used': ['nasa_srtm_water_mask'],
                            'water_body_classification': {
                                'is_water': is_water,
                                'body_type': water_type
                            }
                        }
                        
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"SRTM water mask analysis failed: {e}")
                
        return None
        
    async def _integrate_bathymetry_classifications(self, bathymetry_results: List, lat: float, lon: float) -> Dict[str, Any]:
        """Integrate multiple bathymetry classification results with weighted confidence"""
        try:
            valid_results = [r for r in bathymetry_results if isinstance(r, dict) and r is not None]
            
            if not valid_results:
                return {'confidence_score': 0.0}
            
            # Weight different data sources based on reliability
            source_weights = {
                'gebco_bathymetry': 0.7,
                'noaa_multibeam_bathymetry': 0.9,
                'etopo_global_relief': 0.6,
                'nasa_srtm_water_mask': 0.5
            }
            
            weighted_oceanic_scores = []
            combined_data_sources = []
            combined_depth_measurements = {}
            
            for result in valid_results:
                data_sources = result.get('data_sources_used', [])
                is_oceanic = result.get('is_oceanic', False)
                confidence = result.get('confidence_score', 0.0)
                
                for source in data_sources:
                    weight = source_weights.get(source, 0.5)
                    oceanic_score = 1.0 if is_oceanic else 0.0
                    weighted_oceanic_scores.append(oceanic_score * confidence * weight)
                    combined_data_sources.extend(data_sources)
                    
                # Combine depth measurements
                depth_measurements = result.get('depth_measurements', {})
                combined_depth_measurements.update(depth_measurements)
            
            if not weighted_oceanic_scores:
                return {'confidence_score': 0.0}
            
            # Calculate final oceanic classification
            avg_weighted_score = sum(weighted_oceanic_scores) / len(weighted_oceanic_scores)
            final_is_oceanic = avg_weighted_score > 0.5
            
            # Calculate confidence based on agreement between sources
            oceanic_votes = sum(1 for r in valid_results if r.get('is_oceanic', False))
            total_votes = len(valid_results)
            agreement_factor = max(oceanic_votes, total_votes - oceanic_votes) / total_votes
            
            final_confidence = min(0.9, avg_weighted_score * agreement_factor + 0.1)
            
            return {
                'is_oceanic': final_is_oceanic,
                'confidence_score': final_confidence,
                'data_sources_used': list(set(combined_data_sources)),
                'analysis_methods': ['weighted_multi_source_integration'],
                'depth_measurements': combined_depth_measurements,
                'integration_details': {
                    'source_count': total_votes,
                    'oceanic_votes': oceanic_votes,
                    'terrestrial_votes': total_votes - oceanic_votes,
                    'weighted_score': avg_weighted_score,
                    'agreement_factor': agreement_factor
                }
            }
            
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.error(f"Bathymetry integration failed: {e}")
            return {'confidence_score': 0.0}
    
    async def _ml_oceanic_classification(self, lat: float, lon: float) -> Dict[str, Any]:
        """Machine learning-based oceanic classification using existing model infrastructure"""
        try:
            # Use existing ModelManager for ML-based classification
            if hasattr(self, 'model_manager'):
                # Feature vector for oceanic classification
                features = {
                    'latitude': lat,
                    'longitude': lon,
                    'abs_latitude': abs(lat),
                    'distance_from_equator': abs(lat),
                    'longitude_normalized': (lon + 180) / 360,  # Normalize to 0-1
                }
                
                # Try oceanic classification model
                oceanic_prediction = await self.model_manager.predict(
                    model_type='oceanic_classifier',
                    input_data=features,
                    prediction_type='classification'
                )
                
                if oceanic_prediction and oceanic_prediction.get('success', False):
                    prediction_result = oceanic_prediction.get('prediction', {})
                    is_oceanic = prediction_result.get('class', 'terrestrial') == 'oceanic'
                    confidence = prediction_result.get('confidence', 0.5)
                    
                    return {
                        'is_oceanic': is_oceanic,
                        'confidence_score': confidence,
                        'data_sources_used': ['ml_oceanic_classifier'],
                        'analysis_methods': ['machine_learning_classification'],
                        'ml_details': {
                            'model_type': 'oceanic_classifier',
                            'prediction_class': prediction_result.get('class', 'unknown'),
                            'class_probabilities': prediction_result.get('probabilities', {})
                        }
                    }
                    
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"ML oceanic classification failed: {e}")
                
        return None
        
    async def _satellite_oceanic_analysis(self, lat: float, lon: float) -> Dict[str, Any]:
        """Multi-spectral satellite imagery analysis for oceanic detection"""
        try:
            # Use existing satellite imagery analysis from the codebase
            satellite_result = await self._analyze_satellite_coastal_imagery(lat, lon)
            
            if satellite_result:
                # Extract oceanic indicators from satellite analysis
                coastal_features = satellite_result.get('coastal_features', [])
                water_index = satellite_result.get('water_index', 0)
                land_water_ratio = satellite_result.get('land_water_ratio', 1.0)
                
                # Classify as oceanic if predominantly water with oceanic characteristics
                is_oceanic = (
                    water_index > 0.7 and 
                    land_water_ratio < 0.3 and
                    any(f.get('type') in ['open_water', 'deep_water'] for f in coastal_features)
                )
                
                # Confidence based on satellite analysis quality
                confidence = min(0.8, satellite_result.get('confidence_score', 0.5) + 0.2)
                
                return {
                    'is_oceanic': is_oceanic,
                    'confidence_score': confidence,
                    'data_sources_used': ['satellite_multispectral_imagery'],
                    'analysis_methods': ['multispectral_water_classification'],
                    'satellite_details': {
                        'water_index': water_index,
                        'land_water_ratio': land_water_ratio,
                        'coastal_features': coastal_features
                    }
                }
                
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.debug(f"Satellite oceanic analysis failed: {e}")
                
        return None
        
    async def _enhanced_geographic_oceanic_analysis(self, lat: float, lon: float) -> Dict[str, Any]:
        """Enhanced geographic analysis with improved oceanic region detection"""
        try:
            import math
            
            # Define comprehensive oceanic regions with improved boundaries
            oceanic_regions = [
                # Pacific Ocean - divided into sub-regions for better accuracy
                {'name': 'North Pacific', 'bounds': [(-180, 10, -100, 70), (140, 10, 180, 70)], 'confidence': 0.8},
                {'name': 'Central Pacific', 'bounds': [(-180, -10, -100, 10), (140, -10, 180, 10)], 'confidence': 0.85},
                {'name': 'South Pacific', 'bounds': [(-180, -60, -70, -10), (140, -60, 180, -10)], 'confidence': 0.8},
                
                # Atlantic Ocean - improved boundaries  
                {'name': 'North Atlantic', 'bounds': [(-80, 10, -10, 70)], 'confidence': 0.8},
                {'name': 'Central Atlantic', 'bounds': [(-60, -10, -10, 10)], 'confidence': 0.85},
                {'name': 'South Atlantic', 'bounds': [(-60, -60, 10, -10)], 'confidence': 0.8},
                
                # Indian Ocean
                {'name': 'Indian Ocean', 'bounds': [(20, -60, 130, 30)], 'confidence': 0.8},
                
                # Arctic Ocean  
                {'name': 'Arctic Ocean', 'bounds': [(-180, 65, 180, 90)], 'confidence': 0.7},
                
                # Southern Ocean
                {'name': 'Southern Ocean', 'bounds': [(-180, -90, 180, -60)], 'confidence': 0.8},
                
                # Mediterranean and enclosed seas
                {'name': 'Mediterranean Sea', 'bounds': [(-6, 30, 42, 48)], 'confidence': 0.7},
                {'name': 'Black Sea', 'bounds': [(27, 40, 42, 48)], 'confidence': 0.7},
                {'name': 'Baltic Sea', 'bounds': [(10, 53, 30, 66)], 'confidence': 0.6},
                {'name': 'Red Sea', 'bounds': [(32, 12, 44, 30)], 'confidence': 0.7},
                {'name': 'Persian Gulf', 'bounds': [(48, 24, 57, 31)], 'confidence': 0.7}
            ]
            
            # Check if location falls within any oceanic region
            for region in oceanic_regions:
                for bounds in region['bounds']:
                    lon_min, lat_min, lon_max, lat_max = bounds
                    
                    # Handle longitude wraparound
                    if lon_min > lon_max:  # Crosses dateline
                        if (lon >= lon_min or lon <= lon_max) and lat_min <= lat <= lat_max:
                            distance_from_center = math.sqrt(
                                ((lat - (lat_min + lat_max) / 2) * 111)**2 +
                                ((lon - (lon_min + lon_max) / 2) * 111 * math.cos(math.radians(lat)))**2
                            )
                            
                            # Reduce confidence for locations near boundaries
                            boundary_factor = min(1.0, distance_from_center / 100)  # Within 100km of center
                            adjusted_confidence = region['confidence'] * (0.7 + 0.3 * boundary_factor)
                            
                            return {
                                'is_oceanic': True,
                                'confidence_score': adjusted_confidence,
                                'data_sources_used': ['enhanced_geographic_regions'],
                                'analysis_methods': ['improved_geographic_classification'],
                                'geographic_details': {
                                    'region_name': region['name'],
                                    'distance_from_center_km': distance_from_center,
                                    'boundary_adjustment_factor': boundary_factor
                                }
                            }
                    else:  # Normal bounds
                        if lon_min <= lon <= lon_max and lat_min <= lat <= lat_max:
                            # Calculate distance from region center
                            center_lat = (lat_min + lat_max) / 2
                            center_lon = (lon_min + lon_max) / 2
                            
                            distance_from_center = math.sqrt(
                                ((lat - center_lat) * 111)**2 +
                                ((lon - center_lon) * 111 * math.cos(math.radians(lat)))**2
                            )
                            
                            # Adjust confidence based on distance from center
                            region_size = max((lat_max - lat_min) * 111, 
                                            (lon_max - lon_min) * 111 * math.cos(math.radians(lat)))
                            
                            center_factor = max(0.5, 1.0 - (distance_from_center / (region_size / 2)))
                            adjusted_confidence = region['confidence'] * center_factor
                            
                            return {
                                'is_oceanic': True,
                                'confidence_score': adjusted_confidence,
                                'data_sources_used': ['enhanced_geographic_regions'],
                                'analysis_methods': ['improved_geographic_classification'],
                                'geographic_details': {
                                    'region_name': region['name'],
                                    'distance_from_center_km': distance_from_center,
                                    'center_adjustment_factor': center_factor
                                }
                            }
            
            # If not in any oceanic region, classify as terrestrial
            return {
                'is_oceanic': False,
                'confidence_score': 0.6,
                'data_sources_used': ['enhanced_geographic_regions'],
                'analysis_methods': ['improved_geographic_classification'],
                'geographic_details': {
                    'region_name': 'terrestrial_or_inland',
                    'classification_reason': 'outside_known_oceanic_regions'
                }
            }
            
        except Exception as e:
            if hasattr(self, 'logger'):
                self.logger.error(f"Enhanced geographic oceanic analysis failed: {e}")
                
            return {
                'is_oceanic': False,
                'confidence_score': 0.3,
                'error': str(e)
            }
            
    async def _emergency_oceanic_fallback(self, lat: float, lon: float) -> bool:
        """Emergency fallback oceanic detection using simplified geographic regions"""
        try:
            # Simplified oceanic regions for emergency fallback
            simple_oceanic_regions = [
                # Pacific Ocean (simplified)
                (-180, -60, -70, 60),
                (130, -60, 180, 60),
                # Atlantic Ocean (simplified) 
                (-70, -60, -10, 70),
                # Indian Ocean (simplified)
                (20, -60, 130, 30),
                # Arctic Ocean (simplified)
                (-180, 60, 180, 90),
                # Southern Ocean (simplified)
                (-180, -90, 180, -60)
            ]
            
            for lon_min, lat_min, lon_max, lat_max in simple_oceanic_regions:
                if lon_min <= lon <= lon_max and lat_min <= lat <= lat_max:
                    return True
            
            return False
            
        except Exception:
            # Ultimate fallback - assume terrestrial if everything fails
            return False
    
    async def _fallback_elevation_reference(self, lat: float, lon: float) -> str:
        """Fallback elevation reference determination with enhanced regional logic"""
        try:
            # Enhanced fallback with better regional precision
            if -180 <= lon <= 180 and -90 <= lat <= 90:
                # North America (enhanced regions)
                if -170 <= lon <= -50 and 15 <= lat <= 75:
                    if -170 <= lon <= -140 and lat > 60:  # Alaska
                        return 'NAVD88_ALASKA'
                    elif -140 <= lon <= -52 and lat > 49:  # Canada  
                        return 'CGVD2013'
                    elif -125 <= lon <= -66 and 24 <= lat <= 49:  # CONUS
                        return 'NAVD88'
                    else:  # Mexico/Central America
                        return 'NGVD29_MEX'
                
                # Europe (enhanced regions)
                elif -25 <= lon <= 40 and 35 <= lat <= 75:
                    if lat > 60:  # Nordic countries
                        return 'NN2000'
                    elif lon < 5 and lat < 45:  # Western Europe
                        return 'NGF_IGN69'
                    else:  # Continental Europe
                        return 'EVRS'
                
                # Asia-Pacific
                elif 90 <= lon <= 180 and -50 <= lat <= 75:
                    if 129 <= lon <= 146 and 30 <= lat <= 46:  # Japan
                        return 'JGD2011_HEIGHT'
                    elif 110 <= lon <= 155 and -45 <= lat <= -10:  # Australia
                        return 'AHD'
                    else:
                        return 'MSL_REGIONAL'
                
                # Global enhanced fallback
                else:
                    if abs(lat) > 60:  # Polar regions
                        return 'WGS84_ELLIPSOID'
                    else:
                        return 'MSL'
            
            return 'UNKNOWN'
            
        except Exception:
            return 'MSL'
    
