    async def _update_spatial_aggregates(self, conn, lat: float, lon: float, parameter: str, value: float, timestamp):
        """Update spatial aggregation tables for efficient region-based queries"""
        try:
            # Create or update grid-based aggregates (e.g., 0.1° grid cells)
            grid_size = 0.1  # degrees
            grid_lat = round(lat / grid_size) * grid_size
            grid_lon = round(lon / grid_size) * grid_size
            
            await conn.execute("""
                INSERT INTO climate_spatial_aggregates (
                    grid_lat, grid_lon, parameter_name, 
                    avg_value, min_value, max_value, count_values,
                    last_updated
                ) VALUES ($1, $2, $3, $4, $5, $6, 1, $7)
                ON CONFLICT (grid_lat, grid_lon, parameter_name) DO UPDATE SET
                    avg_value = ((climate_spatial_aggregates.avg_value * climate_spatial_aggregates.count_values) + $4) / 
                                (climate_spatial_aggregates.count_values + 1),
                    min_value = LEAST(climate_spatial_aggregates.min_value, $5),
                    max_value = GREATEST(climate_spatial_aggregates.max_value, $6),
                    count_values = climate_spatial_aggregates.count_values + 1,
                    last_updated = $7
            """, grid_lat, grid_lon, parameter, value, value, value, timestamp)
            
        except Exception as e:
            self.logger.debug(f"Spatial aggregates update failed: {e}")
    
    async def _trigger_quality_control(self, conn, cache_id: str, parameter: str, value: float, lat: float, lon: float):
        """Trigger automatic quality control procedures"""
        try:
            # Check for anomalous values compared to nearby stations
            anomaly_check = await conn.fetchval("""
                WITH nearby_values AS (
                    SELECT parameter_value, quality_score
                    FROM climate_data_cache 
                    WHERE parameter_name = $1
                    AND ST_DWithin(location_point, ST_GeogFromText('POINT(' || $3 || ' ' || $2 || ')'), 50000)
                    AND timestamp > NOW() - INTERVAL '7 days'
                    AND quality_score >= 0.7
                    LIMIT 20
                )
                SELECT 
                    CASE 
                        WHEN ABS($4 - AVG(parameter_value)) > 3 * STDDEV(parameter_value) THEN 'anomaly'
                        WHEN ABS($4 - AVG(parameter_value)) > 2 * STDDEV(parameter_value) THEN 'outlier'
                        ELSE 'normal'
                    END as anomaly_status
                FROM nearby_values
                WHERE STDDEV(parameter_value) > 0
            """, parameter, lat, lon, value)
            
            if anomaly_check in ['anomaly', 'outlier']:
                # Flag for manual review
                await conn.execute("""
                    INSERT INTO climate_quality_flags (
                        cache_id, flag_type, flag_reason, created_at
                    ) VALUES ($1, $2, $3, NOW())
                """, cache_id, anomaly_check, f"Statistical {anomaly_check} detected")
                
        except Exception as e:
            self.logger.debug(f"Quality control trigger failed: {e}")
    
    async def _update_cache_statistics(self, parameter: str, source: str, quality_score: float):
        """Update cache performance statistics"""
        try:
            # This would update statistics in a monitoring table
            self.cache_stats = getattr(self, 'cache_stats', {})
            key = f"{parameter}_{source}"
            if key not in self.cache_stats:
                self.cache_stats[key] = {'count': 0, 'total_quality': 0.0}
            
            self.cache_stats[key]['count'] += 1
            self.cache_stats[key]['total_quality'] += quality_score
            
        except Exception as e:
            self.logger.debug(f"Cache statistics update failed: {e}")
    
    async def _fallback_cache_climate_data(self, lat: float, lon: float, parameter: str, value: float, source: str) -> str:
        """Fallback caching to local SQLite database"""
        try:
            import sqlite3
            import json
            from datetime import datetime
            
            # Create fallback cache ID
            cache_id = f"fallback_{parameter}_{lat}_{lon}_{int(datetime.now().timestamp())}"
            
            # Connect to local SQLite
            conn = sqlite3.connect('climate_cache_fallback.db')
            cursor = conn.cursor()
            
            # Create table if not exists
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS climate_cache_fallback (
                    cache_id TEXT PRIMARY KEY,
                    latitude REAL,
                    longitude REAL,
                    parameter_name TEXT,
                    parameter_value REAL,
                    data_source TEXT,
                    timestamp TEXT,
                    quality_score REAL,
                    created_at TEXT DEFAULT CURRENT_TIMESTAMP
                )
            """)
            
            # Insert data
            cursor.execute("""
                INSERT OR REPLACE INTO climate_cache_fallback
                (cache_id, latitude, longitude, parameter_name, parameter_value, 
                 data_source, timestamp, quality_score)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, (cache_id, lat, lon, parameter, value, source, 
                  datetime.now().isoformat(), 0.5))  # Default quality for fallback
            
            conn.commit()
            conn.close()
            
            self.logger.info(f"Fallback cached: {cache_id}")
            return cache_id
            
        except Exception as e:
            self.logger.error(f"Fallback caching failed: {e}")
            return f"failed_{int(datetime.now().timestamp())}"
    
    def _get_parameter_correlation_length(self, parameter: str) -> float:
        """Get typical spatial correlation length for parameter in kilometers"""
        correlation_lengths = {
            'temperature': 100.0,     # Temperature varies smoothly over ~100km
            'precipitation': 25.0,    # Precipitation more localized
            'humidity': 50.0,         # Humidity intermediate scale
            'pressure': 200.0,        # Pressure varies on synoptic scale
            'wind_speed': 30.0,       # Wind influenced by local topography
            'solar_radiation': 150.0  # Solar radiation broad scale
        }
        
        parameter_lower = parameter.lower()
        for param_key, length in correlation_lengths.items():
            if param_key in parameter_lower:
                return length
                
        return 75.0  # Default correlation length
    
    async def _query_alternative_climate_sources(self, lat: float, lon: float, parameter: str, search_radius_km: float) -> List[Dict]:
        """Query alternative data sources when primary database has insufficient data"""
        try:
            alternative_data = []
            
            # Try external data connectors from the existing infrastructure
            try:
                from .external_data_connectors import DataIntegrationManager
                
                integration_manager = DataIntegrationManager()
                
                # Query nearby region data
                bbox = (
                    lon - search_radius_km/111.0,  # Approximate degree conversion
                    lat - search_radius_km/111.0,
                    lon + search_radius_km/111.0,
                    lat + search_radius_km/111.0
                )
                
                # Collect regional data that might contain climate information
                regional_data = integration_manager.collect_regional_data(
                    region_name=f"climate_query_{lat}_{lon}",
                    bbox=bbox
                )
                
                # Extract climate-relevant data
                for source_name, data_list in regional_data.items():
                    if isinstance(data_list, list):
                        for record in data_list[:5]:  # Limit to 5 per source
                            if hasattr(record, 'properties') and record.properties:
                                # Look for climate-related properties
                                props = record.properties
                                climate_value = None
                                
                                # Extract relevant climate parameters
                                if parameter.lower() in ['temperature', 'temp']:
                                    climate_value = props.get('temperature') or props.get('temp')
                                elif parameter.lower() in ['precipitation', 'precip', 'rainfall']:
                                    climate_value = props.get('precipitation') or props.get('rainfall')
                                # Add more parameter mappings as needed
                                
                                if climate_value is not None and hasattr(record, 'coordinates'):
                                    coords = record.coordinates
                                    if len(coords) >= 2:
                                        distance = self._calculate_distance(lat, lon, coords[0], coords[1])
                                        if distance <= search_radius_km:
                                            alternative_data.append({
                                                'lat': coords[0],
                                                'lon': coords[1],
                                                'value': float(climate_value),
                                                'distance_km': distance,
                                                'quality': 0.6,  # Moderate quality for alternative source
                                                'weight': 0.5,
                                                'uncertainty': abs(climate_value) * 0.2,
                                                'age_hours': 24,  # Assume 24 hours old
                                                'source': f"external_{source_name}"
                                            })
                
            except Exception as e:
                self.logger.debug(f"External connector query failed: {e}")
                
            return alternative_data
            
        except Exception as e:
            self.logger.warning(f"Alternative source query failed: {e}")
            return []
    
    def _calculate_distance(self, lat1: float, lon1: float, lat2: float, lon2: float) -> float:
        """Calculate haversine distance between two points in kilometers"""
        from math import radians, sin, cos, asin, sqrt
        
        lat1, lon1, lat2, lon2 = map(radians, [lat1, lon1, lat2, lon2])
        dlat = lat2 - lat1
        dlon = lon2 - lon1
        a = sin(dlat/2)**2 + cos(lat1) * cos(lat2) * sin(dlon/2)**2
        return 2 * asin(sqrt(a)) * 6371  # Earth radius in km
    
    def _project_coordinates(self, coords: np.ndarray) -> np.ndarray:
        """Project lat/lon coordinates to local Cartesian system"""
        try:
            import pyproj
            
            # Use appropriate projection based on coordinate extent
            center_lat = np.mean(coords[:, 0])
            center_lon = np.mean(coords[:, 1])
            
            # UTM zone calculation
            utm_zone = int((center_lon + 180) / 6) + 1
            
            # Create projection
            proj_string = f"+proj=utm +zone={utm_zone} +ellps=WGS84 +datum=WGS84 +units=m +no_defs"
            transformer = pyproj.Transformer.from_crs("EPSG:4326", proj_string, always_xy=True)
            
            # Transform coordinates
            projected = np.zeros_like(coords)
            for i, (lat, lon) in enumerate(coords):
                x, y = transformer.transform(lon, lat)
                projected[i] = [x, y]
                
            return projected
            
        except Exception:
            # Fallback to simple degree-to-meter conversion
            center_lat = np.mean(coords[:, 0])
            lat_to_m = 111000  # meters per degree latitude
            lon_to_m = 111000 * np.cos(np.radians(center_lat))  # adjust for latitude
            
            projected = coords.copy()
            projected[:, 0] *= lat_to_m
            projected[:, 1] *= lon_to_m
            
            return projected
    
    def _estimate_spatial_correlation_length(self, coords: np.ndarray, values: np.ndarray) -> float:
        """Estimate spatial correlation length from data"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            # Calculate pairwise distances and value differences
            distances = squareform(pdist(coords))
            value_diffs = np.abs(values[:, np.newaxis] - values[np.newaxis, :])
            
            # Find correlation length where correlation drops to 1/e
            distance_bins = np.linspace(0, np.max(distances) * 0.5, 20)
            correlations = []
            
            for i in range(len(distance_bins) - 1):
                mask = (distances >= distance_bins[i]) & (distances < distance_bins[i + 1])
                if np.sum(mask) > 0:
                    avg_diff = np.mean(value_diffs[mask])
                    total_variance = np.var(values)
                    correlation = max(0, 1 - avg_diff**2 / (2 * total_variance))
                    correlations.append(correlation)
                else:
                    correlations.append(0)
            
            # Find where correlation drops below 1/e ≈ 0.37
            target_correlation = 1.0 / np.e
            for i, corr in enumerate(correlations):
                if corr < target_correlation:
                    return distance_bins[i]
                    
            return distance_bins[len(distance_bins) // 2]  # Fallback to middle distance
            
        except Exception:
            return 50000.0  # Default 50km correlation length
    
    async def _estimate_rbf_uncertainty(self, coords: np.ndarray, values: np.ndarray, 
                                       target_point: np.ndarray, rbf_interpolator) -> float:
        """Estimate RBF interpolation uncertainty using leave-one-out cross-validation"""
        try:
            n_points = len(coords)
            if n_points < 3:
                return abs(values[0]) * 0.2  # Default uncertainty
                
            errors = []
            
            # Perform leave-one-out cross-validation on subset for efficiency
            n_cv = min(10, n_points)  # Limit CV iterations
            indices = np.random.choice(n_points, n_cv, replace=False)
            
            for i in indices:
                # Remove point i
                train_coords = np.delete(coords, i, axis=0)
                train_values = np.delete(values, i)
                
                try:
                    # Create new RBF interpolator
                    cv_rbf = RBFInterpolator(
                        train_coords, train_values,
                        kernel='thin_plate_spline',
                        degree=1
                    )
                    
                    # Predict removed point
                    predicted = cv_rbf(coords[i:i+1])[0]
                    actual = values[i]
                    errors.append(abs(predicted - actual))
                    
                except Exception:
                    continue
                    
            if errors:
                return float(np.mean(errors))
            else:
                return abs(np.mean(values)) * 0.15  # Fallback uncertainty
                
        except Exception:
            return abs(np.mean(values)) * 0.15  # Default uncertainty
    
    async def _simple_distance_average(self, lat: float, lon: float, parameter: str) -> Optional[float]:
        """Simple distance-weighted average as last resort"""
        try:
            # Get database config
            db_config = self._get_database_config()
            
            async with asyncpg.connect(
                host=db_config.get('host', 'localhost'),
                port=db_config.get('port', 5432),
                user=db_config.get('username', 'prometheus_admin'),
                password=db_config.get('password', 'GeoPhys2024!PrometheusDB#'),
                database=db_config.get('database', 'prometheus_geo')
            ) as conn:
                
                # Get nearest 3 points within large radius
                results = await conn.fetch("""
                    SELECT parameter_value, 
                           ST_Distance(
                               ST_GeogFromText('POINT(' || $2 || ' ' || $1 || ')'),
                               location_point
                           ) / 1000.0 as distance_km
                    FROM climate_data_cache
                    WHERE parameter_name = $3
                    AND ST_DWithin(
                        ST_GeogFromText('POINT(' || $2 || ' ' || $1 || ')'),
                        location_point,
                        500000  -- 500km max distance
                    )
                    AND quality_score >= 0.3
                    ORDER BY distance_km
                    LIMIT 3
                """, lat, lon, parameter)
                
                if len(results) == 0:
                    return None
                    
                # Simple inverse distance weighting
                total_weight = 0.0
                weighted_sum = 0.0
                
                for row in results:
                    value = float(row['parameter_value'])
                    distance = max(0.1, float(row['distance_km']))  # Avoid division by zero
                    weight = 1.0 / distance
                    
                    weighted_sum += weight * value
                    total_weight += weight
                    
                if total_weight > 0:
                    result = weighted_sum / total_weight
                    self.logger.info(f"Simple distance average for {parameter}: {result:.3f}")
                    return result
                    
                return None
                
        except Exception as e:
            self.logger.error(f"Simple distance average failed: {e}")
            return None
    
    async def _is_ocean_location(self, lat: float, lon: float) -> bool:
        """Check if coordinates are over ocean (simplified land/sea mask)"""
        try:
            # This is a simplified implementation
            # In production, you'd use a proper land/sea mask dataset
            
            # Major continental boundaries (very rough approximation)
            continental_bounds = [
                # North America
                (-170, -50, 15, 75),
                # South America
                (-85, -30, -60, 15),
                # Europe + Asia
                (-25, 180, 35, 80),
                # Africa
                (-25, 55, -40, 35),
                # Australia
                (110, 155, -45, -10)
            ]
            
            for min_lon, max_lon, min_lat, max_lat in continental_bounds:
                if min_lon <= lon <= max_lon and min_lat <= lat <= max_lat:
                    return False  # Over land
                    
            return True  # Assume ocean
            
        except Exception:
            return False  # Default to land
    
