    async def _get_real_elevation_data(self, lat: float, lon: float) -> Optional[float]:
        """Get real elevation data using comprehensive DEM sources"""
        try:
            from .external_data_connectors import USGSConnector, NASAEarthDataConnector
            
            # Try cached elevation first
            cached_elevation = await self._get_cached_elevation(lat, lon)
            if cached_elevation is not None:
                return cached_elevation
            
            # Priority-based elevation data sources
            elevation_sources = [
                ('USGS_NED', self._get_usgs_ned_elevation),
                ('NASA_SRTM', self._get_nasa_srtm_elevation),
                ('NASA_ASTER', self._get_nasa_aster_elevation),
                ('ETOPO1', self._get_etopo1_elevation),
                ('Global_Model', self._get_global_elevation_model)
            ]
            
            for source_name, elevation_method in elevation_sources:
                try:
                    elevation = await elevation_method(lat, lon)
                    if elevation is not None and -500 <= elevation <= 9000:  # Reasonable elevation range
                        await self._cache_elevation_point(lat, lon, elevation, source_name)
                        return elevation
                except Exception as e:
                    self.logger.debug(f"Failed to get elevation from {source_name}: {e}")
                    continue
            
            # Emergency fallback using statistical models
            return self._estimate_elevation_from_regional_model(lat, lon)
            
        except Exception as e:
            self.logger.warning(f"Failed to get real elevation data: {e}")
            return None

