    def _calculate_topographic_amplification(self, elevation: float, lat: float, lon: float) -> float:
        """Calculate topographic amplification factor using Boore (2004) model"""
        try:
            # Boore (2004) topographic amplification model
            # Fa = 1.0 + c1 * ln(elevation/c2) for elevation > c2
            c1 = 0.1  # Amplification coefficient
            c2 = 600.0  # Reference elevation (m)
            
            if elevation > c2:
                amplification = 1.0 + c1 * np.log(elevation / c2)
                return min(amplification, 2.0)  # Cap at 2.0
            else:
                # For low elevations, use minimal amplification
                return 1.0 + 0.01 * (elevation / c2)
                
        except Exception as e:
            self.logger.debug(f"Topographic amplification calculation failed: {e}")
            return 1.0

    async def _calculate_terrain_slope(self, lat: float, lon: float, center_elevation: float) -> float:
        """Calculate terrain slope using surrounding elevation points"""
        try:
            # Sample points in a small grid around the center point
            delta = 0.001  # ~100m at equator
            sample_points = [
                (lat + delta, lon),      # North
                (lat - delta, lon),      # South  
                (lat, lon + delta),      # East
                (lat, lon - delta)       # West
            ]
            
            elevations = [center_elevation]
            
            for sample_lat, sample_lon in sample_points:
                try:
                    elevation = await self._get_real_elevation_data(sample_lat, sample_lon)
                    if elevation is not None:
                        elevations.append(elevation)
                except:
                    continue
            
            if len(elevations) < 3:
                return 0.0  # Not enough data for slope calculation
            
            # Calculate approximate slope as maximum elevation difference
            max_elevation = max(elevations)
            min_elevation = min(elevations)
            elevation_diff = max_elevation - min_elevation
            
            # Approximate distance for slope calculation (~100m)
            distance = 100.0
            slope_radians = np.arctan(elevation_diff / distance)
            slope_degrees = np.degrees(slope_radians)
            
            return min(slope_degrees, 45.0)  # Cap at 45 degrees
            
        except Exception as e:
            self.logger.debug(f"Terrain slope calculation failed: {e}")
            return 0.0

    def _calculate_slope_amplification(self, slope_degrees: float, vs30: float) -> float:
        """Calculate slope-based site amplification using Stewart & Boore (2008)"""
        try:
            # Stewart & Boore (2008) slope-based amplification
            # Accounts for topographic and site coupling effects
            
            if slope_degrees < 5.0:
                # Flat terrain - minimal slope effects
                return 0.0
            
            # Slope amplification factor
            slope_factor = min(slope_degrees / 30.0, 1.0)  # Normalize by 30 degrees
            
            # Site-slope coupling (softer sites show more slope effects)
            vs30_factor = max(0.5, 760.0 / vs30) if vs30 > 0 else 1.0
            
            amplification = 0.1 * slope_factor * vs30_factor
            return min(amplification, 0.5)  # Cap at 0.5
            
        except Exception as e:
            self.logger.debug(f"Slope amplification calculation failed: {e}")
            return 0.0

    def _estimate_regional_topographic_amplification(self, lat: float, lon: float) -> float:
        """Estimate topographic amplification using regional models"""
        try:
            # Regional topographic characteristics based on latitude/longitude
            # This is a simplified model - in practice would use detailed regional data
            
            # Mountain ranges and high-elevation regions
            mountain_regions = [
                {'lat_range': (35, 50), 'lon_range': (-125, -100), 'base_amp': 1.2},  # US West Coast
                {'lat_range': (25, 45), 'lon_range': (-85, -65), 'base_amp': 1.1},   # Appalachians
                {'lat_range': (-60, -30), 'lon_range': (-80, -60), 'base_amp': 1.3}, # Andes
                {'lat_range': (25, 50), 'lon_range': (60, 100), 'base_amp': 1.25},   # Himalayas
                {'lat_range': (35, 50), 'lon_range': (5, 20), 'base_amp': 1.15}      # Alps
            ]
            
            for region in mountain_regions:
                if (region['lat_range'][0] <= lat <= region['lat_range'][1] and
                    region['lon_range'][0] <= lon <= region['lon_range'][1]):
                    return region['base_amp']
            
            # Default for other regions
            return 1.0
            
        except Exception as e:
            self.logger.debug(f"Regional topographic estimation failed: {e}")
            return 1.0

    def _estimate_elevation_from_regional_model(self, lat: float, lon: float) -> float:
        """Emergency fallback elevation estimation using statistical regional models"""
        try:
            # Very simplified regional elevation model
            # In practice, would use detailed regional statistics
            
            # Basic elevation estimates by latitude bands
            if abs(lat) < 30:  # Tropical/equatorial
                base_elevation = 200.0
            elif abs(lat) < 45:  # Temperate
                base_elevation = 400.0
            else:  # High latitude
                base_elevation = 100.0
            
            # Longitude adjustments for major continental features
            if -180 <= lon <= -60:  # Americas
                elevation_adjustment = 300.0 if abs(lat) > 25 else 100.0
            elif -20 <= lon <= 60:  # Africa/Europe
                elevation_adjustment = 200.0 if abs(lat) < 35 else 50.0
            elif 60 <= lon <= 180:  # Asia/Oceania
                elevation_adjustment = 400.0 if 25 <= lat <= 45 else 150.0
            else:
                elevation_adjustment = 0.0
            
            estimated_elevation = base_elevation + elevation_adjustment
            return max(0.0, estimated_elevation)
            
        except Exception as e:
            self.logger.debug(f"Regional elevation estimation failed: {e}")
            return 0.0

    async def _get_vegetation_index(self, lat: float, lon: float) -> float:
        """Get vegetation index (NDVI) from multiple satellite sources with advanced processing"""
        try:
            from .external_data_connectors import NASAEarthDataConnector
            import aiohttp
            import numpy as np
            from datetime import datetime, timedelta
            
            # Priority-based NDVI sources
            ndvi_sources = [
                self._get_modis_ndvi,
                self._get_landsat_ndvi,
                self._get_sentinel_ndvi,
                self._get_viirs_ndvi
            ]
            
            valid_ndvi_values = []
            
            for source_func in ndvi_sources:
                try:
                    ndvi = await source_func(lat, lon)
                    if ndvi is not None and -1.0 <= ndvi <= 1.0:  # Valid NDVI range
                        valid_ndvi_values.append(ndvi)
                        # Cache successful result
                        await self._cache_ndvi_data(lat, lon, ndvi, source_func.__name__)
                except Exception as e:
                    self.logger.warning(f"NDVI source {source_func.__name__} failed: {e}")
                    continue
            
            if valid_ndvi_values:
                # Use median of valid values to reduce noise
                return float(np.median(valid_ndvi_values))
            
            # Fallback to interpolation from nearby cached values
            interpolated_ndvi = await self._interpolate_ndvi_data(lat, lon)
            if interpolated_ndvi is not None:
                return float(interpolated_ndvi)
            
            # Final fallback based on land cover classification
            return await self._estimate_ndvi_from_landcover(lat, lon)
            
        except Exception as e:
            self.logger.error(f"All NDVI sources failed for {lat}, {lon}: {e}")
            return 0.5  # Neutral NDVI value
    
    async def _get_modis_ndvi(self, lat: float, lon: float) -> Optional[float]:
        """Get NDVI from MODIS Terra/Aqua satellites via NASA LAADS DAAC"""
        try:
            from .external_data_connectors import NASAEarthDataConnector
            
            nasa_connector = NASAEarthDataConnector(rate_limit=1.0)
            
            # Search for recent MODIS data
            bbox = (lon - 0.01, lat - 0.01, lon + 0.01, lat + 0.01)
            end_date = datetime.utcnow()
            start_date = end_date - timedelta(days=16)  # MODIS 16-day composite
            
            # Search for MODIS vegetation index products
            satellite_data = nasa_connector.search_landsat_data(
                bbox=bbox,
                start_date=start_date,
                end_date=end_date,
                cloud_cover_max=30.0
            )
            
            if satellite_data:
                # Process MODIS NDVI from metadata or direct calculation
                for record in satellite_data:
                    if hasattr(record, 'properties') and 'ndvi' in record.properties:
                        return float(record.properties['ndvi'])
                    
                    # Calculate NDVI from red and NIR bands if available
                    if (hasattr(record, 'properties') and 
                        'red_band' in record.properties and 
                        'nir_band' in record.properties):
                        
                        red = record.properties['red_band']
                        nir = record.properties['nir_band']
                        
                        if nir + red != 0:
                            ndvi = (nir - red) / (nir + red)
                            return float(ndvi)
            
            return None
        except Exception:
            return None
    
