    async def _query_sentinel_database(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query local database for cached Sentinel-2 NDVI data"""
        try:
            from .database_integration import PostgreSQLGISManager, DatabaseConfig
            
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return None
            
            # Spatial query for nearby Sentinel-2 observations within 1km and 30 days
            query = """
                SELECT ndvi_value, acquisition_date, cloud_cover_percent, 
                       quality_flag, processing_level, ST_Distance(
                           ST_Point(%s, %s)::geography, 
                           location::geography
                       ) as distance_m
                FROM satellite_ndvi_archive 
                WHERE sensor_type = 'Sentinel-2' 
                AND ST_DWithin(location::geography, ST_Point(%s, %s)::geography, 1000)
                AND acquisition_date >= NOW() - INTERVAL '30 days'
                AND quality_flag >= 0.7
                ORDER BY distance_m ASC, acquisition_date DESC
                LIMIT 5;
            """
            
            result = await self.db_manager.execute_query(
                query, (lon, lat, lon, lat)
            )
            
            if result:
                # Select best quality observation with temporal weighting
                best_obs = max(result, key=lambda x: (
                    x['quality_flag'] * 0.6 + 
                    (1 - x['cloud_cover_percent']/100) * 0.3 +
                    (1 - min(x['distance_m']/1000, 1)) * 0.1
                ))
                
                return {
                    'ndvi': best_obs['ndvi_value'],
                    'quality': best_obs['quality_flag'],
                    'source': 'database_sentinel',
                    'acquisition_date': best_obs['acquisition_date'],
                    'cloud_cover': best_obs['cloud_cover_percent'],
                    'distance_m': best_obs['distance_m']
                }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Database Sentinel query failed: {e}")
            return None
    
    async def _query_copernicus_sentinel_hub(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query Copernicus Sentinel Hub for real-time NDVI data"""
        try:
            import aiohttp
            import asyncio
            from datetime import datetime, timedelta
            
            # Copernicus Sentinel Hub Configuration
            sentinel_hub_config = {
                'base_url': 'https://services.sentinel-hub.com',
                'client_id': os.environ.get('COPERNICUS_CLIENT_ID'),
                'client_secret': os.environ.get('COPERNICUS_CLIENT_SECRET'),
                'instance_id': os.environ.get('COPERNICUS_INSTANCE_ID')
            }
            
            if not all(sentinel_hub_config.values()):
                return None
            
            # Get OAuth2 token
            token = await self._get_copernicus_oauth_token(sentinel_hub_config)
            if not token:
                return None
            
            # Define search area (1km x 1km bbox)
            bbox_offset = 0.005  # ~500m
            bbox = [
                lon - bbox_offset, lat - bbox_offset,
                lon + bbox_offset, lat + bbox_offset
            ]
            
            # Process request for NDVI calculation
            headers = {
                'Authorization': f'Bearer {token}',
                'Content-Type': 'application/json'
            }
            
            # Sentinel-2 NDVI calculation request
            payload = {
                'input': {
                    'bounds': {
                        'bbox': bbox,
                        'properties': {'crs': 'http://www.opengis.net/def/crs/EPSG/0/4326'}
                    },
                    'data': [{
                        'type': 'S2L2A',
                        'dataFilter': {
                            'timeRange': {
                                'from': (datetime.now() - timedelta(days=30)).strftime('%Y-%m-%dT00:00:00Z'),
                                'to': datetime.now().strftime('%Y-%m-%dT23:59:59Z')
                            },
                            'maxCloudCoverage': 30
                        }
                    }]
                },
                'output': {
                    'width': 32,
                    'height': 32,
                    'responses': [{
                        'identifier': 'ndvi',
                        'format': {'type': 'image/tiff'}
                    }]
                },
                'evalscript': """
                    function setup() {
                        return {
                            input: ['B04', 'B08', 'CLM', 'SCL'],
                            output: { bands: 1, sampleType: 'FLOAT32' }
                        };
                    }
                    
                    function evaluatePixel(sample) {
                        // Cloud and quality masking
                        if (sample.CLM > 0 || sample.SCL === 3 || sample.SCL === 8 || sample.SCL === 9) {
                            return [NaN];
                        }
                        
                        // NDVI calculation with atmospheric correction
                        let ndvi = (sample.B08 - sample.B04) / (sample.B08 + sample.B04);
                        return [ndvi];
                    }
                """
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.post(
                    f"{sentinel_hub_config['base_url']}/api/v1/process",
                    headers=headers,
                    json=payload,
                    timeout=aiohttp.ClientTimeout(total=60)
                ) as response:
                    if response.status == 200:
                        # Process TIFF response and calculate mean NDVI
                        ndvi_result = await self._process_sentinel_tiff_response(response, lat, lon)
                        if ndvi_result:
                            return {
                                'ndvi': ndvi_result['mean_ndvi'],
                                'quality': ndvi_result['quality_score'],
                                'source': 'copernicus_sentinel_hub',
                                'valid_pixels': ndvi_result['valid_pixels'],
                                'total_pixels': ndvi_result['total_pixels'],
                                'std_dev': ndvi_result.get('std_dev', 0)
                            }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"Copernicus Sentinel Hub query failed: {e}")
            return None
    
    async def _query_esa_scihub_sentinel(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query ESA Copernicus Open Access Hub for Sentinel data"""
        try:
            import aiohttp
            from datetime import datetime, timedelta
            
            # ESA SciHub credentials
            username = os.environ.get('ESA_SCIHUB_USERNAME')
            password = os.environ.get('ESA_SCIHUB_PASSWORD')
            
            if not username or not password:
                return None
            
            # Search parameters
            bbox_size = 0.01  # ~1km
            start_date = (datetime.now() - timedelta(days=30)).strftime('%Y-%m-%d')
            end_date = datetime.now().strftime('%Y-%m-%d')
            
            # OpenSearch API query
            search_url = 'https://apihub.copernicus.eu/apihub/search'
            query_params = {
                'q': (
                    f'platformname:Sentinel-2 AND '
                    f'producttype:S2MSI2A AND '
                    f'footprint:"Intersects(POLYGON(({lon-bbox_size} {lat-bbox_size},' 
                    f'{lon+bbox_size} {lat-bbox_size},{lon+bbox_size} {lat+bbox_size},' 
                    f'{lon-bbox_size} {lat+bbox_size},{lon-bbox_size} {lat-bbox_size})))" AND '
                    f'beginposition:[{start_date}T00:00:00.000Z TO {end_date}T23:59:59.999Z] AND '
                    f'cloudcoverpercentage:[0 TO 30]'
                ),
                'rows': 5,
                'orderby': 'beginposition desc',
                'format': 'json'
            }
            
            auth = aiohttp.BasicAuth(username, password)
            
            async with aiohttp.ClientSession(auth=auth) as session:
                async with session.get(
                    search_url, 
                    params=query_params,
                    timeout=aiohttp.ClientTimeout(total=60)
                ) as response:
                    if response.status == 200:
                        data = await response.json()
                        
                        if data.get('feed', {}).get('entry'):
                            # Process the most recent suitable product
                            best_product = await self._select_best_sentinel_product(
                                data['feed']['entry'], lat, lon
                            )
                            
                            if best_product:
                                # Download and process NDVI from selected product
                                ndvi_result = await self._process_sentinel_product_ndvi(
                                    best_product, lat, lon, session
                                )
                                if ndvi_result:
                                    return {
                                        'ndvi': ndvi_result['ndvi'],
                                        'quality': ndvi_result['quality'],
                                        'source': 'esa_scihub',
                                        'product_id': best_product.get('id'),
                                        'acquisition_date': best_product.get('date')
                                    }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"ESA SciHub query failed: {e}")
            return None
    
    async def _query_nasa_lance_viirs(self, lat: float, lon: float) -> Optional[Dict[str, Any]]:
        """Query NASA LANCE for near real-time VIIRS vegetation indices"""
        try:
            import aiohttp
            from datetime import datetime, timedelta
            
            # NASA LANCE MODIS/VIIRS Land Global Browse Images
            lance_base_url = 'https://lance.modaps.eosdis.nasa.gov/api/v2'
            
            # VIIRS vegetation index parameters
            params = {
                'product': 'VNP13A1',  # VIIRS 16-Day NDVI
                'coordinates': f'{lat},{lon}',
                'date': (datetime.now() - timedelta(days=16)).strftime('%Y-%m-%d'),
                'kmAboveBelow': 5,
                'kmLeftRight': 5
            }
            
            headers = {
                'Authorization': f'Bearer {os.environ.get("NASA_EARTHDATA_TOKEN")}',
                'User-Agent': 'Prometheus-Geological-System/1.0'
            }
            
            async with aiohttp.ClientSession() as session:
                async with session.get(
                    f'{lance_base_url}/imagery',
                    params=params,
                    headers=headers,
                    timeout=aiohttp.ClientTimeout(total=45)
                ) as response:
                    if response.status == 200:
                        viirs_data = await response.json()
                        
                        if viirs_data and 'data' in viirs_data:
                            # Process VIIRS NDVI data
                            ndvi_result = await self._process_viirs_ndvi_data(
                                viirs_data['data'], lat, lon
                            )
                            
                            if ndvi_result:
                                return {
                                    'ndvi': ndvi_result['ndvi'],
                                    'quality': ndvi_result['quality'],
                                    'source': 'nasa_lance_viirs',
                                    'pixel_reliability': ndvi_result.get('reliability', 0)
                                }
            
            return None
            
        except Exception as e:
            self.logger.warning(f"NASA LANCE VIIRS query failed: {e}")
            return None
    
    async def _cache_ndvi_data(self, lat: float, lon: float, ndvi: float, source: str, metadata: Dict = None):
        """Cache NDVI data in PostGIS time-series database with comprehensive metadata"""
        try:
            from datetime import datetime
            from .database_integration import PostgreSQLGISManager
            
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return
            
            cache_entry = {
                'location': f'POINT({lon} {lat})',
                'ndvi_value': float(ndvi),
                'sensor_type': source.replace('_', ' ').title(),
                'acquisition_date': datetime.utcnow(),
                'quality_flag': metadata.get('quality', 0.85) if metadata else 0.85,
                'cloud_cover_percent': metadata.get('cloud_cover', 0) if metadata else 0,
                'processing_level': metadata.get('processing_level', 'L2A') if metadata else 'L2A',
                'spatial_resolution_m': metadata.get('resolution', 10) if metadata else 10,
                'metadata_json': json.dumps(metadata) if metadata else '{}'
            }
            
            # Insert into satellite_ndvi_archive table
            insert_query = """
                INSERT INTO satellite_ndvi_archive 
                (location, ndvi_value, sensor_type, acquisition_date, 
                 quality_flag, cloud_cover_percent, processing_level,
                 spatial_resolution_m, metadata_json, created_at)
                VALUES (ST_GeomFromText(%(location)s, 4326), %(ndvi_value)s, 
                        %(sensor_type)s, %(acquisition_date)s, %(quality_flag)s,
                        %(cloud_cover_percent)s, %(processing_level)s, 
                        %(spatial_resolution_m)s, %(metadata_json)s, NOW())
                ON CONFLICT (location, sensor_type, acquisition_date) 
                DO UPDATE SET 
                    ndvi_value = EXCLUDED.ndvi_value,
                    quality_flag = EXCLUDED.quality_flag,
                    updated_at = NOW();
            """
            
            await self.db_manager.execute_query(insert_query, cache_entry)
            
            self.logger.debug(f"Cached NDVI data for {lat}, {lon} from {source}")
            
        except Exception as e:
            self.logger.warning(f"Failed to cache NDVI data: {e}")
    
    async def _interpolate_ndvi_data(self, lat: float, lon: float, radius_km: float = 10.0) -> Optional[float]:
        """Spatial interpolation of NDVI using Kriging and IDW methods"""
        try:
            from scipy.spatial.distance import cdist
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, WhiteKernel
            import numpy as np
            
            if not hasattr(self, 'db_manager') or not self.db_manager:
                return None
            
            # Query nearby NDVI observations within radius
            query = """
                SELECT ST_X(location::geometry) as lon, 
                       ST_Y(location::geometry) as lat,
                       ndvi_value, quality_flag,
                       ST_Distance(location::geography, 
                                  ST_Point(%s, %s)::geography) as distance_m
                FROM satellite_ndvi_archive 
                WHERE ST_DWithin(location::geography, 
                                ST_Point(%s, %s)::geography, %s)
                AND acquisition_date >= NOW() - INTERVAL '60 days'
                AND quality_flag >= 0.6
                ORDER BY distance_m ASC
                LIMIT 20;
            """
            
            result = await self.db_manager.execute_query(
                query, (lon, lat, lon, lat, radius_km * 1000)
            )
            
            if len(result) < 3:  # Need minimum points for interpolation
                return None
            
            # Prepare data for interpolation
            coordinates = np.array([[r['lon'], r['lat']] for r in result])
            ndvi_values = np.array([r['ndvi_value'] for r in result])
            weights = np.array([r['quality_flag'] for r in result])
            
            # Gaussian Process Regression for spatial interpolation
            kernel = RBF(length_scale=0.01) + WhiteKernel(noise_level=0.01)
            gpr = GaussianProcessRegressor(kernel=kernel, alpha=1e-6)
            
            # Fit with quality-weighted samples
            sample_weight = weights / np.sum(weights)
            gpr.fit(coordinates, ndvi_values, sample_weight=sample_weight)
            
            # Predict NDVI at target location
            target_coords = np.array([[lon, lat]])
            ndvi_pred, std_pred = gpr.predict(target_coords, return_std=True)
            
            # Validate prediction quality
            if std_pred[0] > 0.3:  # High uncertainty
                # Fallback to Inverse Distance Weighting
                return await self._idw_ndvi_interpolation(coordinates, ndvi_values, weights, lon, lat)
            
            return max(-1.0, min(1.0, float(ndvi_pred[0])))
            
        except Exception as e:
            self.logger.warning(f"NDVI interpolation failed: {e}")
            return None
    
    async def _advanced_landcover_ndvi_estimation(self, lat: float, lon: float, sensor_type: str) -> float:
        """Advanced NDVI estimation using multiple land cover databases and climate data"""
        try:
            import numpy as np
            from datetime import datetime
            
            # Multi-source land cover analysis
            landcover_sources = await asyncio.gather(
                self._query_modis_landcover(lat, lon),
                self._query_esa_worldcover(lat, lon),
                self._query_dynamic_world_landcover(lat, lon),
                return_exceptions=True
            )
            
            # Process and validate land cover data
            valid_landcover = []
            for result in landcover_sources:
                if not isinstance(result, Exception) and result:
                    valid_landcover.append(result)
            
            if not valid_landcover:
                # Final fallback to climate-based estimation
                return await self._climate_based_ndvi_estimation(lat, lon)
            
            # Enhanced NDVI estimation based on land cover consensus
            landcover_consensus = await self._analyze_landcover_consensus(valid_landcover)
            
            # NDVI lookup table based on comprehensive literature and satellite observations
            ndvi_lookup = {
                'evergreen_forest': {'mean': 0.75, 'std': 0.12, 'seasonal': 0.05},
                'deciduous_forest': {'mean': 0.68, 'std': 0.18, 'seasonal': 0.25},
                'mixed_forest': {'mean': 0.71, 'std': 0.15, 'seasonal': 0.15},
                'cropland': {'mean': 0.65, 'std': 0.22, 'seasonal': 0.35},
                'grassland': {'mean': 0.45, 'std': 0.18, 'seasonal': 0.28},
                'shrubland': {'mean': 0.35, 'std': 0.15, 'seasonal': 0.20},
                'wetland': {'mean': 0.55, 'std': 0.12, 'seasonal': 0.10},
                'urban': {'mean': 0.25, 'std': 0.10, 'seasonal': 0.08},
                'barren': {'mean': 0.15, 'std': 0.08, 'seasonal': 0.05},
                'water': {'mean': -0.05, 'std': 0.05, 'seasonal': 0.02},
                'snow_ice': {'mean': 0.10, 'std': 0.05, 'seasonal': 0.15}
            }
            
            # Apply climate and phenological corrections
            base_ndvi = ndvi_lookup.get(landcover_consensus, ndvi_lookup['grassland'])['mean']
            seasonal_amplitude = ndvi_lookup.get(landcover_consensus, ndvi_lookup['grassland'])['seasonal']
            
            # Add seasonal variation based on location and current date
            seasonal_correction = await self._calculate_seasonal_ndvi_correction(
                lat, lon, seasonal_amplitude, datetime.now()
            )
            
            # Add climate zone correction
            climate_correction = await self._calculate_climate_ndvi_correction(lat, lon)
            
            # Sensor-specific correction factors
            sensor_corrections = {
                'sentinel': 1.0,
                'landsat': 0.98,
                'viirs': 1.02,
                'modis': 0.99
            }
            
            sensor_factor = sensor_corrections.get(sensor_type.lower(), 1.0)
            
            final_ndvi = (base_ndvi + seasonal_correction + climate_correction) * sensor_factor
            
            return max(-1.0, min(1.0, final_ndvi))
            
        except Exception as e:
            self.logger.error(f"Advanced land cover NDVI estimation failed: {e}")
            # Ultra-fallback to basic geographic estimation
            abs_lat = abs(lat)
            if abs_lat < 23.5:
                return 0.65  # Tropical
            elif abs_lat < 35:
                return 0.50  # Subtropical
            elif abs_lat < 50:
                return 0.45  # Temperate
            elif abs_lat < 66.5:
                return 0.30  # Subpolar
            else:
                return 0.15  # Polar
    
