    async def _calculate_seasonal_ndvi_correction(self, lat: float, lon: float, 
                                                amplitude: float, current_date: datetime) -> float:
        """Calculate seasonal NDVI correction based on location and date"""
        try:
            import math
            
            # Day of year (1-365)
            day_of_year = current_date.timetuple().tm_yday
            
            # Northern/Southern hemisphere seasonal offset
            if lat >= 0:  # Northern hemisphere
                # Peak growing season around day 180 (late June)
                seasonal_phase = 2 * math.pi * (day_of_year - 180) / 365
            else:  # Southern hemisphere
                # Peak growing season around day 15 (mid January)
                seasonal_phase = 2 * math.pi * (day_of_year - 15) / 365
            
            # Latitude-based amplitude scaling
            latitude_factor = max(0.1, abs(lat) / 90)  # Higher latitudes have more seasonal variation
            
            seasonal_correction = amplitude * latitude_factor * math.cos(seasonal_phase)
            
            return seasonal_correction
            
        except Exception as e:
            self.logger.warning(f"Seasonal correction calculation failed: {e}")
            return 0.0
    
    async def _idw_ndvi_interpolation(self, coordinates: np.ndarray, values: np.ndarray, 
                                    weights: np.ndarray, target_lon: float, target_lat: float) -> float:
        """Inverse Distance Weighting interpolation for NDVI"""
        try:
            from scipy.spatial.distance import cdist
            
            target_point = np.array([[target_lon, target_lat]])
            distances = cdist(coordinates, target_point, metric='euclidean').flatten()
            
            # Avoid division by zero
            distances = np.maximum(distances, 1e-8)
            
            # IDW with power parameter p=2
            idw_weights = (1 / (distances ** 2)) * weights
            idw_weights /= np.sum(idw_weights)
            
            interpolated_ndvi = np.sum(values * idw_weights)
            
            return max(-1.0, min(1.0, interpolated_ndvi))
            
        except Exception as e:
            self.logger.error(f"IDW interpolation failed: {e}")
            return None
    
    async def _process_satellite_record_advanced(self, record) -> Optional[Dict[str, Any]]:
        """Advanced processing of satellite record for NDVI calculation"""
        try:
            # Determine satellite type and processing approach
            satellite_type = self._identify_satellite_type(record)
            
            if satellite_type == 'landsat':
                return await self._process_landsat_record_advanced(record)
            elif satellite_type == 'sentinel':
                return await self._process_sentinel_record_advanced(record)
            elif satellite_type == 'modis':
                return await self._process_modis_record_advanced(record)
            elif satellite_type == 'viirs':
                return await self._process_viirs_record_advanced(record)
            else:
                # Generic processing for unknown satellites
                return await self._process_generic_satellite_record(record)
                
        except Exception as e:
            self.logger.error(f"Advanced satellite record processing failed: {e}")
            return None
    
    async def _process_landsat_record_advanced(self, record) -> Optional[Dict[str, Any]]:
        """Advanced Landsat-specific NDVI processing with full atmospheric correction"""
        try:
            # Extract coordinates
            if hasattr(record, 'coordinates') and len(record.coordinates) >= 2:
                lat, lon = record.coordinates[:2]
            else:
                lat, lon = 0, 0
            
            # Get comprehensive Landsat band data
            band_data = await self._extract_landsat_bands_comprehensive(record)
            if not band_data:
                return None
            
            # Apply Level-2 surface reflectance processing
            surface_reflectance = await self._apply_landsat_surface_reflectance(band_data, record)
            if not surface_reflectance:
                return None
            
            # Extract Red and NIR bands (Landsat 8/9 OLI)
            red_band = surface_reflectance.get('SR_B4')  # Red: 630-680nm
            nir_band = surface_reflectance.get('SR_B5')  # NIR: 845-885nm
            
            if red_band is None or nir_band is None:
                return None
            
            # Apply pixel quality assessment
            qa_pixel = surface_reflectance.get('QA_PIXEL', 0)
            qa_radsat = surface_reflectance.get('QA_RADSAT', 0)
            
            # Check for clouds, shadows, snow, water
            quality_mask = await self._evaluate_landsat_quality_mask(qa_pixel, qa_radsat)
            if not quality_mask['usable']:
                return None
            
            # Calculate NDVI with uncertainty estimation
            if (nir_band + red_band) != 0:
                ndvi = (nir_band - red_band) / (nir_band + red_band)
                
                # Uncertainty propagation
                red_uncertainty = surface_reflectance.get('SR_B4_uncertainty', 0.02)
                nir_uncertainty = surface_reflectance.get('SR_B5_uncertainty', 0.02)
                
                # NDVI uncertainty calculation
                denominator = nir_band + red_band
                ndvi_uncertainty = 2 * np.sqrt(
                    (red_band * nir_uncertainty / denominator**2)**2 +
                    (nir_band * red_uncertainty / denominator**2)**2
                )
                
                # Apply additional corrections
                corrected_ndvi = await self._apply_landsat_geometric_corrections(
                    ndvi, record, surface_reflectance
                )
                
                return {
                    'ndvi': max(-1.0, min(1.0, corrected_ndvi)),
                    'uncertainty': min(0.5, ndvi_uncertainty),
                    'resolution_m': 30,
                    'atm_corrected': True,
                    'cloud_masked': quality_mask['cloud_free'],
                    'processing_level': 'L2SR',
                    'quality_flags': quality_mask
                }
            
            return None
            
        except Exception as e:
            self.logger.error(f"Landsat advanced processing failed: {e}")
            return None
    
    async def _calculate_composite_quality_score(self, record, ndvi_result: Dict) -> float:
        """Calculate composite quality score considering multiple factors"""
        try:
            base_score = getattr(record, 'quality_score', 0.5)
            
            # Atmospheric correction bonus
            atm_bonus = 0.2 if ndvi_result.get('atm_corrected', False) else 0
            
            # Cloud masking bonus
            cloud_bonus = 0.15 if ndvi_result.get('cloud_masked', False) else 0
            
            # Spatial resolution factor (higher resolution = higher quality)
            resolution = ndvi_result.get('resolution_m', 30)
            resolution_factor = max(0.8, min(1.2, 30 / resolution))
            
            # Uncertainty penalty
            uncertainty = ndvi_result.get('uncertainty', 0.1)
            uncertainty_penalty = min(0.3, uncertainty * 2)
            
            # Temporal recency factor
            recency_factor = 1.0
            if hasattr(record, 'timestamp') and record.timestamp:
                days_old = (datetime.now() - record.timestamp).days
                recency_factor = max(0.5, 1.0 - (days_old / 365))  # Decay over year
            
            composite_score = (
                (base_score + atm_bonus + cloud_bonus) * 
                resolution_factor * recency_factor - uncertainty_penalty
            )
            
            return max(0.0, min(1.0, composite_score))
            
        except Exception as e:
            self.logger.warning(f"Quality score calculation failed: {e}")
            return 0.5
    
    async def _select_optimal_ndvi_estimate(self, candidates: List[Dict]) -> Optional[Dict]:
        """Multi-criteria selection of optimal NDVI estimate"""
        try:
            if not candidates:
                return None
            
            # Sort by composite quality score
            candidates_sorted = sorted(
                candidates, 
                key=lambda x: x['quality_score'], 
                reverse=True
            )
            
            # Check if top candidate is significantly better
            best_candidate = candidates_sorted[0]
            
            if len(candidates_sorted) > 1:
                second_best = candidates_sorted[1]
                
                # If quality scores are close, consider ensemble approach
                if (best_candidate['quality_score'] - second_best['quality_score']) < 0.1:
                    # Weighted ensemble of top candidates
                    ensemble_ndvi = await self._ensemble_ndvi_estimates(
                        candidates_sorted[:3]  # Top 3 candidates
                    )
                    
                    if ensemble_ndvi is not None:
                        best_candidate = {
                            'ndvi': ensemble_ndvi,
                            'quality_score': best_candidate['quality_score'],
                            'source': 'ensemble',
                            'uncertainty': np.mean([c['uncertainty'] for c in candidates_sorted[:3]])
                        }
            
            return best_candidate
            
        except Exception as e:
            self.logger.error(f"Optimal NDVI selection failed: {e}")
            return candidates[0] if candidates else None
    
    def _identify_satellite_type(self, record) -> str:
        """Identify satellite type from record metadata"""
        try:
            if hasattr(record, 'source'):
                source_lower = record.source.lower()
                if 'landsat' in source_lower:
                    return 'landsat'
                elif 'sentinel' in source_lower:
                    return 'sentinel'
                elif 'modis' in source_lower:
                    return 'modis'
                elif 'viirs' in source_lower:
                    return 'viirs'
            
            if hasattr(record, 'properties') and record.properties:
                platform = record.properties.get('platform', '').lower()
                if 'landsat' in platform:
                    return 'landsat'
                elif 'sentinel' in platform:
                    return 'sentinel'
            
            return 'generic'
            
        except Exception:
            return 'generic'

