    async def _find_nearby_airports(self, lat, lon, radius_km):
        """Advanced airport discovery using multiple real-time aviation databases"""
        try:
            airports = []
            
            # Tier 1: OurAirports Database Integration
            ourairports_data = await self._query_ourairports_database(lat, lon, radius_km)
            if ourairports_data:
                airports.extend(ourairports_data)
            
            # Tier 2: Aviation Edge API Integration
            aviation_edge_data = await self._query_aviation_edge_api(lat, lon, radius_km)
            if aviation_edge_data:
                airports.extend(aviation_edge_data)
            
            # Tier 3: ICAO Airport Database Integration
            icao_data = await self._query_icao_database(lat, lon, radius_km)
            if icao_data:
                airports.extend(icao_data)
            
            # Tier 4: FAA Airport Database Integration  
            faa_data = await self._query_faa_database(lat, lon, radius_km)
            if faa_data:
                airports.extend(faa_data)
            
            # Remove duplicates and rank by data quality
            airports = await self._deduplicate_and_rank_airports(airports)
            
            # Advanced proximity filtering with great circle distance
            filtered_airports = []
            for airport in airports:
                distance = self._calculate_vincenty_distance(
                    lat, lon, airport['location']['lat'], airport['location']['lon']
                )
                
                if distance <= radius_km:
                    airport['distance_km'] = distance
                    airport['bearing_deg'] = self._calculate_bearing(lat, lon, 
                                                                   airport['location']['lat'], 
                                                                   airport['location']['lon'])
                    filtered_airports.append(airport)
            
            # Sort by composite score: distance, runway length, service level
            return sorted(filtered_airports, 
                         key=lambda x: self._calculate_airport_priority_score(x))
            
        except Exception as e:
            self.logger.error(f"Advanced airport discovery failed: {e}")
            return await self._fallback_airport_database(lat, lon, radius_km)
    
