    async def _enhanced_fallback_extraction(self, text):
        """Enhanced fallback geological entity extraction with external validation"""
        try:
            # Advanced pattern-based extraction with geological knowledge
            geological_entities = []
            
            # Comprehensive geological material dictionary with confidence scores
            geological_materials = {
                'igneous': ['granite', 'basalt', 'rhyolite', 'andesite', 'diorite', 'gabbro', 'obsidian', 'pumice'],
                'sedimentary': ['limestone', 'sandstone', 'shale', 'conglomerate', 'breccia', 'mudstone', 'siltstone'],
                'metamorphic': ['marble', 'quartzite', 'gneiss', 'schist', 'slate', 'phyllite', 'amphibolite', 'serpentine'],
                'minerals': ['quartz', 'feldspar', 'mica', 'olivine', 'pyroxene', 'amphibole', 'calcite', 'dolomite'],
                'structures': ['fault', 'fold', 'joint', 'fracture', 'dike', 'sill', 'batholith', 'pluton'],
                'processes': ['weathering', 'erosion', 'deposition', 'metamorphism', 'intrusion', 'extrusion']
            }
            
            text_lower = text.lower()
            
            for category, materials in geological_materials.items():
                for material in materials:
                    if material in text_lower:
                        start_pos = text_lower.find(material)
                        
                        # Enhanced confidence scoring based on context
                        context_window = text_lower[max(0, start_pos-50):start_pos+len(material)+50]
                        confidence = await self._calculate_contextual_confidence(material, context_window, category)
                        
                        geological_entity = {
                            'text': material,
                            'label': f'geological_{category}',
                            'start': start_pos,
                            'end': start_pos + len(material),
                            'confidence': confidence,
                            'model': 'enhanced_fallback',
                            'category': category,
                            'provenance': {
                                'extraction_method': 'pattern_matching_with_context',
                                'context_validated': True
                            }
                        }
                        geological_entities.append(geological_entity)
            
            # Validate against external databases if available
            if hasattr(self, 'data_integration_manager'):
                geological_entities = await self._validate_fallback_entities(geological_entities)
            
            return geological_entities
            
        except Exception as e:
            self.logger.error(f"Enhanced fallback extraction failed: {e}")
            return []
    
    async def _calculate_contextual_confidence(self, material, context, category):
        """Calculate confidence score based on geological context"""
        try:
            base_confidence = 0.6
            
            # Geological context indicators
            geological_indicators = {
                'formation', 'outcrop', 'intrusion', 'deposit', 'layer', 'bed', 
                'crystalline', 'texture', 'composition', 'age', 'environment'
            }
            
            # Scientific context indicators
            scientific_indicators = {
                'analysis', 'sample', 'study', 'research', 'measurement', 'composition',
                'microscopic', 'chemical', 'mineral', 'petrographic'
            }
            
            context_score = 0.0
            
            # Check for geological context
            for indicator in geological_indicators:
                if indicator in context:
                    context_score += 0.05
            
            # Check for scientific context
            for indicator in scientific_indicators:
                if indicator in context:
                    context_score += 0.03
            
            # Category-specific boosts
            if category == 'igneous' and any(term in context for term in ['magma', 'volcanic', 'plutonic', 'crystallization']):
                context_score += 0.1
            elif category == 'sedimentary' and any(term in context for term in ['deposition', 'layers', 'strata', 'basin']):
                context_score += 0.1
            elif category == 'metamorphic' and any(term in context for term in ['pressure', 'temperature', 'recrystallization']):
                context_score += 0.1
            
            final_confidence = min(0.95, base_confidence + context_score)
            return final_confidence
            
        except Exception as e:
            self.logger.error(f"Contextual confidence calculation failed: {e}")
            return 0.5
    
    async def _extract_rich_context(self, text, match, geological_entities):
        """Advanced context extraction with multi-scale geological analysis and uncertainty quantification"""
        # Multi-scale context windows for different geological phenomena
        context_windows = {
            'micro': (50, 50),      # Fine-grained material properties
            'meso': (200, 200),     # Local geological structures  
            'macro': (500, 500),    # Regional geological context
            'basin': (1000, 1000)   # Basin-scale context
        }
        
        enriched_contexts = {}
        
        for scale, (pre_window, post_window) in context_windows.items():
            start_pos = max(0, match.start() - pre_window)
            end_pos = min(len(text), match.end() + post_window)
            context_text = text[start_pos:end_pos]
            
            # Extract entities within this window
            context_entities = [
                entity for entity in geological_entities
                if start_pos <= entity['start'] <= end_pos
            ]
            
            # Perform semantic analysis using transformer models
            semantic_features = await self._extract_semantic_features(context_text)
            
            # Geological relationship mapping
            geological_relationships = await self._map_geological_relationships(
                context_text, context_entities
            )
            
            # Uncertainty quantification for context reliability
            context_uncertainty = await self._quantify_context_uncertainty(
                context_text, geological_entities, scale
            )
            
            enriched_contexts[scale] = {
                'text': context_text,
                'entities': context_entities,
                'match_position': match.start() - start_pos,
                'semantic_features': semantic_features,
                'geological_relationships': geological_relationships,
                'uncertainty_metrics': context_uncertainty,
                'confidence_score': 1.0 - context_uncertainty.get('total_uncertainty', 0.5)
            }
        
        # Cross-scale consistency analysis
        consistency_score = await self._analyze_cross_scale_consistency(enriched_contexts)
        
        # Database validation of extracted context
        validated_context = await self._validate_context_against_database(
            enriched_contexts, geological_entities
        )
        
        return {
            'multi_scale_contexts': enriched_contexts,
            'cross_scale_consistency': consistency_score,
            'database_validated': validated_context,
            'extraction_confidence': min(consistency_score, validated_context.get('validation_confidence', 0.5))
        }
    
    async def _identify_material_with_confidence(self, context, entities, geological_entities):
        """Advanced geological material identification using neural ensemble and real-time database integration"""
        
        # Initialize neural material classification models
        if not hasattr(self, '_material_classifiers_initialized'):
            await self._initialize_material_classification_models()
        
        material_candidates = []
        
        try:
            # Extract multi-scale contexts
            multi_scale_contexts = context.get('multi_scale_contexts', {})
            
            for scale, scale_context in multi_scale_contexts.items():
                context_text = scale_context.get('text', '')
                context_entities = scale_context.get('entities', [])
                
                # 1. Neural NER-based material extraction
                ner_materials = await self._extract_materials_neural_ner(
                    context_text, scale
                )
                
                # 2. Transformer-based geological material classification
                transformer_materials = await self._classify_materials_transformer(
                    context_text, context_entities, scale
                )
                
                # 3. Knowledge graph-based material reasoning
                kg_materials = await self._reason_materials_knowledge_graph(
                    context_text, context_entities, scale_context.get('semantic_features', {})
                )
                
                # 4. Database-validated material identification
                db_materials = await self._identify_materials_database_validation(
                    context_text, context_entities
                )
                
                # Combine and weight material candidates by scale and method
                scale_weight = {
                    'micro': 1.2,  # Fine-grained properties are most reliable
                    'meso': 1.0,   # Standard geological context
                    'macro': 0.8,  # Regional context less specific
                    'basin': 0.6   # Basin-scale less material-specific
                }.get(scale, 1.0)
                
                for method_name, materials in [
                    ('ner', ner_materials),
                    ('transformer', transformer_materials), 
                    ('knowledge_graph', kg_materials),
                    ('database', db_materials)
                ]:
                    for material in materials:
                        material_candidates.append({
                            'material': material['material'],
                            'confidence': material['confidence'] * scale_weight,
                            'method': method_name,
                            'scale': scale,
                            'evidence': material.get('evidence', {}),
                            'uncertainty': material.get('uncertainty', 0.3)
                        })
            
            # Ensemble voting and confidence aggregation
            final_material_info = await self._ensemble_material_classification(
                material_candidates
            )
            
            # Real-time geological database validation
            validated_material = await self._validate_material_geological_databases(
                final_material_info, context, entities
            )
            
            # Geochemical and petrological consistency checking
            consistency_checked = await self._check_geochemical_consistency(
                validated_material, multi_scale_contexts
            )
            
            # Calculate final confidence with uncertainty propagation
            final_confidence = await self._calculate_material_confidence_with_uncertainty(
                consistency_checked, material_candidates
            )
            
            return {
                'material': consistency_checked.get('material', 'unknown'),
                'confidence': final_confidence,
                'material_candidates': material_candidates,
                'validation_evidence': consistency_checked.get('validation_evidence', {}),
                'uncertainty_bounds': consistency_checked.get('uncertainty_bounds', {}),
                'geological_context': consistency_checked.get('geological_context', {}),
                'classification_methods_used': list(set([c['method'] for c in material_candidates]))
            }
            
        except Exception as e:
            self.logger.error(f"Advanced material identification failed: {e}")
            
            # Graceful fallback with database lookup
            fallback_material = await self._fallback_material_identification(context, entities)
            return fallback_material
    
    async def _apply_discovered_pattern(self, pattern, text, entities, pattern_type):
        """Advanced pattern application using graph neural networks and physics-informed constraints"""
        
        extracted_values = []
        
