    async def _retrieve_historical_uncertainty_data(self, material: str, property_name: str, 
                                                   features: Dict) -> List[Dict]:
        """Retrieve historical uncertainty data from database"""
        try:
            import psycopg2
            from contextlib import closing
            
            # Connect to PostgreSQL database
            conn = psycopg2.connect(
                host="localhost",
                database="prometheus_geo",
                user="prometheus_admin",
                password="GeoPhys2024!PrometheusDB#"
            )
            
            historical_data = []
            
            with closing(conn.cursor()) as cursor:
                # Query historical uncertainty data
                query = """
                    SELECT 
                        rmp.id,
                        rmp.lithology,
                        rmp.unconfined_compressive_strength_mpa,
                        rmp.tensile_strength_mpa,
                        rmp.elastic_modulus_gpa,
                        rmp.poisson_ratio,
                        rmp.data_quality_grade,
                        rmp.test_standard,
                        ST_X(rmp.sample_location::geometry) as longitude,
                        ST_Y(rmp.sample_location::geometry) as latitude,
                        ST_Z(rmp.sample_location::geometry) as depth,
                        lrp.property_value,
                        lrp.confidence_level,
                        lrp.sample_size,
                        lrp.test_conditions
                    FROM rock_mechanical_properties rmp
                    LEFT JOIN literature_rock_properties lrp 
                        ON LOWER(rmp.lithology) = LOWER(lrp.rock_type)
                        AND LOWER(lrp.property_name) = LOWER(%s)
                    WHERE LOWER(rmp.lithology) LIKE LOWER(%s)
                    ORDER BY rmp.data_quality_grade, lrp.confidence_level DESC
                    LIMIT 1000
                """
                
                cursor.execute(query, (property_name, f"%{material}%"))
                rows = cursor.fetchall()
                
                for row in rows:
                    historical_data.append({
                        'id': row[0],
                        'lithology': row[1],
                        'ucs_mpa': row[2],
                        'tensile_mpa': row[3],
                        'elastic_modulus_gpa': row[4],
                        'poisson_ratio': row[5],
                        'quality_grade': row[6],
                        'test_standard': row[7],
                        'location': {'lon': row[8], 'lat': row[9], 'depth': row[10]},
                        'literature_value': row[11],
                        'confidence': row[12] if row[12] else 0.5,
                        'sample_size': row[13] if row[13] else 1,
                        'test_conditions': row[14] if row[14] else {}
                    })
            
            conn.close()
            return historical_data
            
        except Exception as e:
            self.logger.error(f"Failed to retrieve historical data: {e}")
            return []
    
    async def _construct_bayesian_prior(self, historical_data: List[Dict], 
                                       value_info: Dict, external_context: Dict) -> Dict:
        """Construct informative Bayesian prior from historical data"""
        try:
            import numpy as np
            from scipy import stats
            
            if not historical_data:
                # Use weakly informative prior
                return {
                    'distribution': 'normal',
                    'mean': value_info.get('value', 0.0),
                    'std': abs(value_info.get('value', 1.0)) * 0.5,
                    'confidence': 0.1
                }
            
            # Extract relevant values from historical data
            values = []
            weights = []
            
            for record in historical_data:
                if record.get('literature_value') is not None:
                    values.append(float(record['literature_value']))
                    # Weight by quality grade and confidence
                    quality_weight = {'A': 1.0, 'B': 0.8, 'C': 0.6, 'D': 0.4}.get(
                        record.get('quality_grade', 'D'), 0.3
                    )
                    confidence_weight = float(record.get('confidence', 0.5))
                    sample_weight = np.log1p(record.get('sample_size', 1)) / 10.0
                    
                    weights.append(quality_weight * confidence_weight + sample_weight)
            
            if not values:
                return {
                    'distribution': 'normal',
                    'mean': value_info.get('value', 0.0),
                    'std': abs(value_info.get('value', 1.0)) * 0.5,
                    'confidence': 0.2
                }
            
            values = np.array(values)
            weights = np.array(weights)
            weights = weights / np.sum(weights)  # Normalize weights
            
            # Fit multiple distributions and select best via AIC
            distributions = {
                'normal': stats.norm,
                'lognormal': stats.lognorm,
                'gamma': stats.gamma,
                'beta': stats.beta
            }
            
            best_dist = None
            best_aic = np.inf
            best_params = {}
            
            for dist_name, dist_class in distributions.items():
                try:
                    # Fit weighted distribution
                    if dist_name == 'normal':
                        mean = np.average(values, weights=weights)
                        std = np.sqrt(np.average((values - mean)**2, weights=weights))
                        params = (mean, std)
                        aic = 2 * 2 - 2 * np.sum(weights * np.log(dist_class.pdf(values, mean, std) + 1e-10))
                    else:
                        params = dist_class.fit(values)
                        aic = 2 * len(params) - 2 * np.sum(np.log(dist_class.pdf(values, *params) + 1e-10))
                    
                    if aic < best_aic:
                        best_aic = aic
                        best_dist = dist_name
                        best_params = params
                        
                except:
                    continue
            
            # Construct prior parameters
            prior = {
                'distribution': best_dist,
                'params': best_params,
                'aic': best_aic,
                'mean': np.average(values, weights=weights),
                'std': np.sqrt(np.average((values - np.average(values, weights=weights))**2, weights=weights)),
                'median': np.median(values),
                'quantiles': {
                    '5%': np.percentile(values, 5),
                    '25%': np.percentile(values, 25),
                    '75%': np.percentile(values, 75),
                    '95%': np.percentile(values, 95)
                },
                'confidence': float(np.mean(weights)),
                'n_samples': len(values)
            }
            
            return prior
            
        except Exception as e:
            self.logger.error(f"Prior construction failed: {e}")
            return {
                'distribution': 'normal',
                'mean': value_info.get('value', 0.0),
                'std': abs(value_info.get('value', 1.0)) * 0.3,
                'confidence': 0.3
            }
    
