    async def _extract_materials_neural_ner(self, context_text, scale):
        """Extract materials using neural NER models"""
        try:
            import torch
            
            # Tokenize and encode text
            inputs = self.geological_bert_tokenizer(
                context_text, 
                return_tensors="pt",
                truncation=True,
                max_length=512,
                padding=True
            )
            
            with torch.no_grad():
                outputs = self.geological_bert_model(**inputs)
                embeddings = outputs.last_hidden_state
            
            # Apply geological NER classification
            materials = await self._classify_geological_entities(embeddings, context_text)
            
            # Filter for material entities and calculate confidence
            material_results = []
            for material in materials:
                if material['entity_type'] == 'geological_material':
                    confidence = material['confidence']
                    # Scale-based confidence adjustment
                    if scale == 'micro':
                        confidence *= 1.2
                    elif scale == 'basin':
                        confidence *= 0.8
                    
                    material_results.append({
                        'material': material['text'],
                        'confidence': min(1.0, confidence),
                        'uncertainty': 1.0 - confidence,
                        'evidence': {
                            'ner_score': material['confidence'],
                            'context_length': len(context_text),
                            'scale': scale
                        }
                    })
            
            return material_results[:10]  # Top 10 candidates
            
        except Exception as e:
            self.logger.error(f"Neural NER material extraction failed: {e}")
            return []
    
    async def _classify_materials_transformer(self, context_text, context_entities, scale):
        """Classify materials using transformer models"""
        try:
            import torch
            
            # Enhanced context with entity information
            enhanced_context = f"{context_text}\n\nEntities: {[e.get('text', '') for e in context_entities]}"
            
            inputs = self.geological_transformer_tokenizer(
                enhanced_context,
                return_tensors="pt", 
                truncation=True,
                max_length=512
            )
            
            with torch.no_grad():
                outputs = self.geological_transformer_model(**inputs)
                pooled_output = torch.mean(outputs.last_hidden_state, dim=1)
            
            # Apply geological material classification head
            material_predictions = await self._geological_material_classification_head(
                pooled_output, context_text, scale
            )
            
            return material_predictions
            
        except Exception as e:
            self.logger.error(f"Transformer material classification failed: {e}")
            return []
    
    async def _reason_materials_knowledge_graph(self, context_text, context_entities, semantic_features):
        """Reason about materials using geological knowledge graph"""
        try:
            # Query Neo4j knowledge graph for geological relationships
            with self.neo4j_driver.session() as session:
                # Build context query
                entity_texts = [e.get('text', '') for e in context_entities]
                
                cypher_query = """
                MATCH (m:Material)-[r:OCCURS_IN|ASSOCIATED_WITH|FORMED_BY]-(context)
                WHERE ANY(entity IN $entities WHERE context.name CONTAINS entity)
                RETURN m.name as material, m.properties as properties, 
                       r.confidence as relationship_confidence,
                       collect(context.name) as context_elements
                ORDER BY relationship_confidence DESC
                LIMIT 20
                """
                
                result = session.run(cypher_query, entities=entity_texts)
                
                kg_materials = []
                for record in result:
                    material_confidence = float(record['relationship_confidence'] or 0.5)
                    
                    # Enhance confidence with semantic similarity
                    semantic_boost = await self._calculate_semantic_similarity(
                        context_text, record['context_elements'], semantic_features
                    )
                    
                    final_confidence = min(1.0, material_confidence * (1 + semantic_boost))
                    
                    kg_materials.append({
                        'material': record['material'],
                        'confidence': final_confidence,
                        'uncertainty': 1.0 - final_confidence,
                        'evidence': {
                            'kg_confidence': material_confidence,
                            'semantic_boost': semantic_boost,
                            'context_elements': record['context_elements'],
                            'properties': record['properties']
                        }
                    })
                
                return kg_materials
                
        except Exception as e:
            self.logger.error(f"Knowledge graph material reasoning failed: {e}")
            return []
    
    async def _identify_materials_database_validation(self, context_text, context_entities):
        """Validate material identification against geological databases"""
        try:
            # Query geological database for material validation
            cursor = self.geological_db_conn.cursor()
            
            # Extract potential material names from context
            potential_materials = await self._extract_potential_material_names(
                context_text, context_entities
            )
            
            validated_materials = []
            
            for material in potential_materials:
                # Query rock_mechanical_properties table
                cursor.execute("""
                    SELECT lithology, COUNT(*) as occurrences, 
                           AVG(data_quality_grade::int) as avg_quality
                    FROM rock_mechanical_properties 
                    WHERE LOWER(lithology) LIKE LOWER(%s)
                    GROUP BY lithology
                    ORDER BY occurrences DESC, avg_quality DESC
                """, (f'%{material}%',))
                
                results = cursor.fetchall()
                
                for lithology, occurrences, avg_quality in results:
                    # Calculate confidence based on database evidence
                    confidence = min(1.0, (occurrences / 100.0) * (avg_quality / 4.0))
                    
                    validated_materials.append({
                        'material': lithology,
                        'confidence': confidence,
                        'uncertainty': 1.0 - confidence,
                        'evidence': {
                            'db_occurrences': occurrences,
                            'avg_quality': avg_quality,
                            'validation_source': 'internal_geological_db'
                        }
                    })
            
            return validated_materials[:15]
            
        except Exception as e:
            self.logger.error(f"Database material validation failed: {e}")
            return []
    
    async def _ensemble_material_classification(self, material_candidates):
        """Ensemble classification using multiple material identification methods"""
        try:
            if not material_candidates:
                return {'material': 'unknown', 'confidence': 0.1}
            
            # Group candidates by material name
            material_groups = {}
            for candidate in material_candidates:
                material_name = candidate['material'].lower()
                if material_name not in material_groups:
                    material_groups[material_name] = []
                material_groups[material_name].append(candidate)
            
            # Calculate ensemble scores for each material
            ensemble_scores = []
            
            for material_name, candidates in material_groups.items():
                # Weighted ensemble voting
                method_weights = {
                    'ner': 0.25,
                    'transformer': 0.30,
                    'knowledge_graph': 0.25, 
                    'database': 0.20
                }
                
                total_weighted_confidence = 0.0
                total_weight = 0.0
                evidence_aggregation = {}
                
                for candidate in candidates:
                    method = candidate['method']
                    weight = method_weights.get(method, 0.1)
                    confidence = candidate['confidence']
                    
                    total_weighted_confidence += weight * confidence
                    total_weight += weight
                    
                    # Aggregate evidence
                    if method not in evidence_aggregation:
                        evidence_aggregation[method] = []
                    evidence_aggregation[method].append(candidate['evidence'])
                
                if total_weight > 0:
                    ensemble_confidence = total_weighted_confidence / total_weight
                else:
                    ensemble_confidence = 0.1
                
                ensemble_scores.append({
                    'material': material_name,
                    'confidence': ensemble_confidence,
                    'method_count': len(candidates),
                    'evidence': evidence_aggregation
                })
            
            # Select best ensemble result
            best_result = max(ensemble_scores, key=lambda x: x['confidence'])
            return best_result
            
        except Exception as e:
            self.logger.error(f"Ensemble material classification failed: {e}")
            return {'material': 'unknown', 'confidence': 0.1}
    
