    def _update_monitoring_metrics(self, start_time, validated_values):
        """Update monitoring metrics after extraction"""
        try:
            import time
            
            # Update performance metrics
            extraction_time = time.time() - start_time
            self.performance_metrics['extraction_times'].append(extraction_time)
            
            # Keep only recent metrics (last 1000)
            if len(self.performance_metrics['extraction_times']) > 1000:
                self.performance_metrics['extraction_times'] = self.performance_metrics['extraction_times'][-1000:]
            
            # Update confidence tracking
            if validated_values:
                confidences = [v.get('confidence', 0) for v in validated_values]
                avg_confidence = sum(confidences) / len(confidences)
                
                # Update rolling average
                current_avg = self.extraction_log['average_confidence']
                total_extractions = self.extraction_log['total_extractions']
                
                self.extraction_log['average_confidence'] = (
                    (current_avg * (total_extractions - 1) + avg_confidence) / total_extractions
                )
            
            # Update property distribution
            for value_info in validated_values:
                material = value_info.get('material', 'unknown')
                if material not in self.extraction_log['material_distribution']:
                    self.extraction_log['material_distribution'][material] = 0
                self.extraction_log['material_distribution'][material] += 1
                
        except Exception as e:
            self.logger.error(f"Error updating monitoring metrics: {e}")
    
