    async def _fallback_extraction(self, text, entities):
        """Fallback extraction when advanced systems fail"""
        try:
            # Use basic pattern matching as fallback
            values = []
            
            for pattern in getattr(self, 'regex_patterns', []):
                matches = pattern.finditer(text)
                for match in matches:
                    try:
                        value_str = match.group(1)
                        unit = match.group(2) if match.lastindex > 1 else None
                        
                        value = float(value_str)
                        standardized_value = self._basic_unit_conversion(value, unit)
                        
                        values.append({
                            'value': standardized_value,
                            'original_value': value,
                            'unit': unit,
                            'confidence': 0.5,  # Low confidence for fallback
                            'extraction_method': 'fallback_pattern',
                            'material': 'unknown'
                        })
                        
                    except (ValueError, TypeError):
                        continue
            
            return values
            
        except Exception as e:
            self.logger.error(f"Fallback extraction failed: {e}")
            return []
    
    def _basic_unit_conversion(self, value, unit):
        """Basic unit conversion for fallback"""
        if not unit:
            return value
        
        unit = unit.upper()
        
        # Basic pressure conversions
        if unit in ['MPA', 'MПАMPA']:
            return value * 1e6
        elif unit in ['KPA', 'KПАKPA']:
            return value * 1e3
        elif unit in ['GPA', 'GПАGPA']:
            return value * 1e9
        
        # Basic density conversions
        elif unit in ['G/CM³', 'G/CM3']:
            return value * 1000
        
        return value

