    async def _query_database_satellite_cache(self, lat: float, lon: float) -> List[Dict]:
        """Query local database cache for satellite geological data"""
        try:
            # Access database integration module
            if hasattr(self, 'data_integration_manager') and hasattr(self.data_integration_manager, 'db_manager'):
                db_manager = self.data_integration_manager.db_manager
                
                # Query cached satellite geological interpretations
                query = """
                SELECT sg.interpreted_rock_type, sg.spectral_signature, sg.mineral_composition,
                       sg.surface_texture, sg.weathering_degree, sg.interpretation_confidence,
                       sg.satellite_source, sg.acquisition_date, sg.spatial_resolution,
                       ST_Distance(ST_Point(%s, %s)::geography, sg.geom::geography) as distance_m
                FROM satellite_geological_interpretation sg
                WHERE ST_DWithin(ST_Point(%s, %s)::geography, sg.geom::geography, 50000)
                ORDER BY distance_m ASC, interpretation_confidence DESC
                LIMIT 20
                """
                
                results = await db_manager.execute_query(query, (lon, lat, lon, lat))
                
                geological_records = []
                for result in results:
                    record = {
                        'source': 'database_cache',
                        'coordinates': (lat, lon),
                        'properties': {
                            'rock_type': result[0],
                            'spectral_signature': result[1],
                            'mineral_composition': result[2],
                            'surface_texture': result[3],
                            'weathering_degree': result[4]
                        },
                        'confidence': result[5],
                        'satellite_source': result[6],
                        'acquisition_date': result[7],
                        'spatial_resolution': result[8],
                        'distance_m': result[9],
                        'quality_score': 0.9
                    }
                    geological_records.append(record)
                
                return geological_records
            
            return []
            
        except Exception as e:
            self.logger.error(f"Database satellite cache query failed: {e}")
            return []
    
