async def _extract_comprehensive_text_content(article, logger):
    """Extract comprehensive text content from article with preprocessing"""
    
    text_content = {
        'title': article.get('title', ''),
        'abstract': article.get('abstract', ''),
        'full_text': article.get('full_text', ''),
        'keywords': article.get('keywords', []),
        'sections': {},
        'references': [],
        'figures': [],
        'tables': []
    }
    
    # Advanced text preprocessing and section extraction
    full_text = article.get('full_text', '')
    
    if full_text:
        # Extract sections using pattern matching (would be neural in production)
        sections = await _extract_document_sections(full_text, logger)
        text_content['sections'] = sections
        
        # Extract references and citations
        references = await _extract_references_and_citations(full_text, logger)
        text_content['references'] = references
    
    # Combine all text for comprehensive analysis
    combined_text = ' '.join([
        text_content['title'],
        text_content['abstract'],
        text_content['full_text']
    ])
    
    return combined_text

async def _extract_document_sections(text, logger):
    """Extract document sections (simplified implementation)"""
    sections = {}
    # Pattern-based section detection (would be neural in production)
    section_patterns = {
        'introduction': r'(?i)introduction',
        'methodology': r'(?i)method(?:ology|s)?',
        'results': r'(?i)results?',
        'discussion': r'(?i)discussion',
        'conclusion': r'(?i)conclusion'
    }
    
    for section_name, pattern in section_patterns.items():
        matches = re.search(pattern, text)
        if matches:
            sections[section_name] = {'found': True, 'position': matches.start()}
        else:
            sections[section_name] = {'found': False, 'position': -1}
    
    return sections

async def _extract_references_and_citations(text, logger):
    """Extract references and citations from text"""
    references = []
    # Pattern for DOI extraction
    doi_pattern = r'10\.\d{4,}/[^\s]+'
    dois = re.findall(doi_pattern, text)
    
    for doi in dois:
        references.append({'type': 'doi', 'identifier': doi})
    
    return references

async def _extract_multimodal_content(article, table_extractor, figure_analyzer, chart_reader, logger):
    """Extract and analyze multi-modal content from scientific articles"""
    
    multimodal_content = {
        'tables': [],
        'figures': [],
        'charts': [],
        'equations': [],
        'structured_data': {}
    }
    
    try:
        # Extract and analyze tables
        if 'tables' in article:
            for table_data in article['tables']:
                extracted_table = await table_extractor.extract_table_data(table_data)
                if extracted_table:
                    multimodal_content['tables'].append(extracted_table)
        
        # Analyze figures and diagrams
        if 'figures' in article:
            for figure_data in article['figures']:
                analyzed_figure = await figure_analyzer.analyze_figure(figure_data)
                if analyzed_figure:
                    multimodal_content['figures'].append(analyzed_figure)
        
        # Extract data from charts and graphs
        if 'charts' in article:
            for chart_data in article['charts']:
                extracted_chart = await chart_reader.extract_chart_data(chart_data)
                if extracted_chart:
                    multimodal_content['charts'].append(extracted_chart)
        
    except Exception as e:
        logger.warning(f"Error in multimodal content extraction: {str(e)}")
    
    return multimodal_content

async def _perform_neural_entity_extraction(text, geological_ner, nlp, scibert_model, scibert_tokenizer, logger):
    """Perform advanced neural entity recognition and classification"""
    
    entities = {
        'geological_materials': [],
        'properties': [],
        'measurements': [],
        'locations': [],
        'processes': [],
        'instruments': [],
        'temporal_references': []
    }
    
    try:
        # spaCy NER extraction
        if nlp:
            doc = nlp(text)
            for ent in doc.ents:
                entity_info = {
                    'text': ent.text,
                    'label': ent.label_,
                    'start': ent.start_char,
                    'end': ent.end_char,
                    'confidence': getattr(ent, 'confidence', 0.8),
                    'extraction_method': 'spacy'
                }
                
                # Classify entity type based on label and context
                entity_type = _classify_geological_entity(ent.label_, ent.text.lower())
                if entity_type in entities:
                    entities[entity_type].append(entity_info)
        
        # Geological NER pipeline
        if geological_ner:
            geological_entities = geological_ner(text[:1000])  # Limit text length
            for ent in geological_entities:
                if ent['score'] > 0.7:  # High confidence threshold
                    entity_info = {
                        'text': ent['word'],
                        'label': ent['entity_group'],
                        'start': ent['start'],
                        'end': ent['end'],
                        'confidence': ent['score'],
                        'extraction_method': 'geological_ner'
                    }
                    
                    entity_type = _classify_geological_entity(ent['entity_group'], ent['word'].lower())
                    if entity_type in entities:
                        entities[entity_type].append(entity_info)
        
        # Custom geological pattern matching
        custom_entities = await _extract_custom_geological_entities(
            text, scibert_model, scibert_tokenizer, logger
        )
        
        # Merge custom entities
        for entity_type, entity_list in custom_entities.items():
            if entity_type in entities:
                entities[entity_type].extend(entity_list)
        
    except Exception as e:
        logger.error(f"Error in neural entity extraction: {str(e)}")
    
    return entities

def _classify_geological_entity(label, text):
    """Classify entity into geological categories"""
    
    # Material classification
    materials = ['granite', 'basalt', 'limestone', 'sandstone', 'shale', 'marble', 'quartzite']
    if any(material in text for material in materials):
        return 'geological_materials'
    
    # Property classification
    properties = ['strength', 'modulus', 'density', 'porosity', 'permeability']
    if any(prop in text for prop in properties):
        return 'properties'
    
    # Location classification
    if label in ['GPE', 'LOC'] or 'location' in text:
        return 'locations'
    
    # Default classification
    return 'geological_materials'

async def _extract_custom_geological_entities(text, scibert_model, scibert_tokenizer, logger):
    """Extract geological entities using custom patterns and neural validation"""
    
    entities = {
        'geological_materials': [],
        'properties': [],
        'measurements': []
    }
    
    try:
        # Define geological material patterns
        material_patterns = [
            r'\b(?:granite|basalt|limestone|sandstone|shale|marble|quartzite|gneiss|schist)\b',
            r'\b(?:igneous|sedimentary|metamorphic)\s+rocks?\b',
            r'\b(?:crystalline|volcanic|plutonic)\s+rocks?\b'
        ]
        
        for pattern in material_patterns:
            matches = re.finditer(pattern, text, re.IGNORECASE)
            for match in matches:
                entities['geological_materials'].append({
                    'text': match.group(),
                    'start': match.start(),
                    'end': match.end(),
                    'confidence': 0.8,
                    'extraction_method': 'pattern'
                })
        
        # Property patterns
        property_patterns = [
            r'\b(?:compressive|tensile)\s+strength\b',
            r'\b(?:elastic|Young\'?s)\s+modulus\b',
            r'\bpoisson\'?s?\s+ratio\b'
        ]
        
        for pattern in property_patterns:
            matches = re.finditer(pattern, text, re.IGNORECASE)
            for match in matches:
                entities['properties'].append({
                    'text': match.group(),
                    'start': match.start(),
                    'end': match.end(),
                    'confidence': 0.8,
                    'extraction_method': 'pattern'
                })
        
    except Exception as e:
        logger.error(f"Error in custom entity extraction: {str(e)}")
    
    return entities

async def _extract_properties_with_neural_models(text, entities, property_extractors, geobert_model, geobert_tokenizer, logger):
    """Extract properties using neural models"""
    
    extracted_properties = {}
    
    try:
        for extractor_name, extractor in property_extractors.items():
            properties = await extractor.extract(text, entities)
            if properties:
                category, prop_name = extractor_name.split('.', 1)
                if category not in extracted_properties:
                    extracted_properties[category] = {}
                extracted_properties[category][prop_name] = properties
        
    except Exception as e:
        logger.error(f"Error in neural property extraction: {str(e)}")
    
    return extracted_properties

async def _discover_semantic_relationships(text, entities, relation_extractor, sentence_model, logger):
    """Discover semantic relationships between entities"""
    
    relationships = []
    
    try:
        # Extract relationships using pattern matching (simplified)
        relationship_patterns = {
            'composed_of': r'(\w+)\s+(?:is\s+)?composed\s+of\s+(\w+)',
            'contains': r'(\w+)\s+contains?\s+(\w+)',
            'measured_at': r'(\w+)\s+(?:was\s+)?measured\s+at\s+(\w+)',
            'associated_with': r'(\w+)\s+(?:is\s+)?associated\s+with\s+(\w+)'
        }
        
        for relation_type, pattern in relationship_patterns.items():
            matches = re.finditer(pattern, text, re.IGNORECASE)
            for match in matches:
                relationships.append({
                    'source': match.group(1),
                    'target': match.group(2),
                    'type': relation_type,
                    'confidence': 0.7,
                    'evidence': [match.group()]
                })
        
    except Exception as e:
        logger.error(f"Error in relationship discovery: {str(e)}")
    
    return relationships

