    def _load_nist_pure_compounds(self) -> Dict[str, Any]:
        """Load NIST pure compound database"""
        compounds = {}
        
        # Priority compounds for geological systems
        geological_compounds = [
            'water', 'carbon_dioxide', 'methane', 'hydrogen_sulfide', 'nitrogen',
            'oxygen', 'hydrogen', 'helium', 'argon', 'ethane', 'propane',
            'benzene', 'toluene', 'cyclohexane', 'n-hexane', 'iso-octane',
            'sodium_chloride', 'calcium_chloride', 'magnesium_chloride'
        ]
        
        for compound in geological_compounds:
            try:
                # Fetch compound data from NIST via external connector
                compound_data = self._fetch_nist_compound_data(compound)
                if compound_data:
                    compounds[compound] = compound_data
            except Exception as e:
                self.logger.warning(f"Failed to load NIST data for {compound}: {e}")
                
        return compounds
    
    def _fetch_nist_compound_data(self, compound: str) -> Dict[str, Any]:
        """Fetch specific compound data from NIST"""
        import requests
        import time
        
        try:
            # NIST WebBook API endpoint
            base_url = "https://webbook.nist.gov/cgi/cbook.cgi"
            
            # Request thermochemical data
            params = {
                'Name': compound,
                'Units': 'SI',
                'Mask': '7FF'  # All available data types
            }
            
            # Rate limiting
            time.sleep(2)  # Respect NIST rate limits
            
            response = requests.get(base_url, params=params, timeout=30)
            
            if response.status_code == 200:
                # Parse NIST data (simplified - would need full HTML/XML parser)
                data = self._parse_nist_response(response.text, compound)
                return data
            else:
                self.logger.warning(f"NIST request failed for {compound}: {response.status_code}")
                return {}
                
        except Exception as e:
            self.logger.error(f"Error fetching NIST data for {compound}: {e}")
            return {}
    
    def _parse_nist_response(self, html_content: str, compound: str) -> Dict[str, Any]:
        """Advanced NIST WebBook HTML parser with comprehensive data extraction"""
        try:
            from bs4 import BeautifulSoup
            import re
            import asyncio
            import aiohttp
            from scipy.interpolate import CubicSpline, UnivariateSpline
            from sklearn.ensemble import RandomForestRegressor
            import torch
            import torch.nn as nn
            from .external_data_connectors import ExternalDataConnectors
            from .database_integration import DatabaseIntegration
            from .thermodynamic_engine import ThermodynamicEngine
            
            # Initialize advanced parsers and connectors
            soup = BeautifulSoup(html_content, 'html.parser')
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            # Extract all available data sections
            compound_data = {
                'name': compound,
                'timestamp': datetime.now().isoformat(),
                'data_sources': [],
                'confidence_scores': {}
            }
            
            # 1. Extract molecular properties
            mol_props = self._extract_molecular_properties(soup)
            if mol_props:
                compound_data.update(mol_props)
                compound_data['data_sources'].append('nist_molecular')
            
            # 2. Extract thermochemical data
            thermochem_data = self._extract_thermochemical_data(soup)
            if thermochem_data:
                compound_data.update(thermochem_data)
                compound_data['data_sources'].append('nist_thermochemical')
            
            # 3. Extract phase transition data
            phase_data = self._extract_phase_transition_data(soup)
            if phase_data:
                compound_data['phase_transitions'] = phase_data
                compound_data['data_sources'].append('nist_phase')
            
            # 4. Extract spectroscopic data
            spectro_data = self._extract_spectroscopic_data(soup)
            if spectro_data:
                compound_data['spectroscopic'] = spectro_data
                compound_data['data_sources'].append('nist_spectroscopic')
            
            # 5. Extract transport properties
            transport_data = self._extract_transport_properties(soup)
            if transport_data:
                compound_data['transport'] = transport_data
                compound_data['data_sources'].append('nist_transport')
            
            # 6. Query external databases for additional data
            external_data = asyncio.run(self._fetch_external_databases(compound))
            if external_data:
                compound_data['external_sources'] = external_data
                compound_data['data_sources'].extend(external_data.keys())
            
            # 7. Apply machine learning models for property prediction
            ml_predictions = self._apply_ml_property_models(compound_data)
            if ml_predictions:
                compound_data['ml_predictions'] = ml_predictions
                compound_data['data_sources'].append('ml_models')
            
            # 8. Calculate derived properties using advanced thermodynamic models
            derived_props = self._calculate_derived_properties(compound_data)
            if derived_props:
                compound_data['derived_properties'] = derived_props
                compound_data['data_sources'].append('calculated')
            
            # 9. Perform data validation and uncertainty quantification
            validation_results = self._validate_and_quantify_uncertainty(compound_data)
            compound_data['validation'] = validation_results
            
            # 10. Store in database for future use
            db_integration.store_compound_data(compound, compound_data)
            
            return compound_data
            
        except ImportError as e:
            self.logger.warning(f"Missing dependencies for advanced parsing: {e}")
            return self._get_fallback_data(compound)
        except Exception as e:
            self.logger.error(f"Error in advanced NIST parsing: {e}")
            return self._get_fallback_data(compound)
    
    def _extract_molecular_properties(self, soup) -> Dict[str, Any]:
        """Extract molecular properties from parsed HTML"""
        properties = {}
        
        # Find molecular weight section
        mw_section = soup.find('td', string=re.compile('Molecular Weight'))
        if mw_section:
            value = mw_section.find_next_sibling('td')
            if value:
                properties['molecular_weight'] = float(re.findall(r'[\d.]+', value.text)[0])
        
        # Find critical properties
        crit_section = soup.find('h2', string=re.compile('Critical Constants'))
        if crit_section:
            crit_table = crit_section.find_next('table')
            if crit_table:
                for row in crit_table.find_all('tr'):
                    cells = row.find_all('td')
                    if len(cells) >= 2:
                        prop_name = cells[0].text.strip().lower()
                        prop_value = cells[1].text.strip()
                        
                        if 'temperature' in prop_name:
                            properties['critical_temperature'] = self._parse_value_with_unit(prop_value, 'K')
                        elif 'pressure' in prop_name:
                            properties['critical_pressure'] = self._parse_value_with_unit(prop_value, 'bar')
                        elif 'density' in prop_name:
                            properties['critical_density'] = self._parse_value_with_unit(prop_value, 'kg/m3')
        
        # Extract additional molecular descriptors
        properties['dipole_moment'] = self._extract_property(soup, 'Dipole Moment', 'Debye')
        properties['polarizability'] = self._extract_property(soup, 'Polarizability', 'angstrom3')
        properties['ionization_energy'] = self._extract_property(soup, 'Ionization Energy', 'eV')
        properties['electron_affinity'] = self._extract_property(soup, 'Electron Affinity', 'eV')
        
        return properties
    
    def _extract_thermochemical_data(self, soup) -> Dict[str, Any]:
        """Extract thermochemical data with uncertainties"""
        thermo_data = {}
        
        # Find thermochemistry section
        thermo_section = soup.find('h2', string=re.compile('Thermochemistry'))
        if not thermo_section:
            return thermo_data
        
        thermo_table = thermo_section.find_next('table')
        if thermo_table:
            for row in thermo_table.find_all('tr'):
                cells = row.find_all('td')
                if len(cells) >= 2:
                    prop_name = cells[0].text.strip()
                    prop_value = cells[1].text.strip()
                    
                    # Parse with uncertainty
                    value_dict = self._parse_value_with_uncertainty(prop_value)
                    
                    if 'ΔfH' in prop_name or 'enthalpy of formation' in prop_name.lower():
                        thermo_data['enthalpy_of_formation'] = value_dict['value']
                        thermo_data['enthalpy_uncertainty'] = value_dict['uncertainty']
                    elif 'ΔfG' in prop_name or 'gibbs' in prop_name.lower():
                        thermo_data['gibbs_energy_of_formation'] = value_dict['value']
                        thermo_data['gibbs_uncertainty'] = value_dict['uncertainty']
                    elif 'S°' in prop_name or 'entropy' in prop_name.lower():
                        thermo_data['entropy_298'] = value_dict['value']
                        thermo_data['entropy_uncertainty'] = value_dict['uncertainty']
                    elif 'Cp' in prop_name or 'heat capacity' in prop_name.lower():
                        thermo_data['heat_capacity_298'] = value_dict['value']
                        thermo_data['heat_capacity_uncertainty'] = value_dict['uncertainty']
        
        # Extract temperature-dependent heat capacity
        cp_coeffs = self._extract_heat_capacity_coefficients(soup)
        if cp_coeffs:
            thermo_data['heat_capacity_constants'] = cp_coeffs
        
        return thermo_data
    
    async def _fetch_external_databases(self, compound: str) -> Dict[str, Any]:
        """Fetch data from multiple external databases concurrently"""
        external_data = {}
        
        async with aiohttp.ClientSession() as session:
            tasks = []
            
            # 1. PubChem API
            tasks.append(self._fetch_pubchem_data(session, compound))
            
            # 2. ChemSpider API
            tasks.append(self._fetch_chemspider_data(session, compound))
            
            # 3. RRUFF Mineral Database
            tasks.append(self._fetch_rruff_data(session, compound))
            
            # 4. Materials Project API
            tasks.append(self._fetch_materials_project_data(session, compound))
            
            # 5. CSD (Cambridge Structural Database)
            tasks.append(self._fetch_csd_data(session, compound))
            
            # 6. ICSD (Inorganic Crystal Structure Database)
            tasks.append(self._fetch_icsd_data(session, compound))
            
            # Execute all tasks concurrently
            results = await asyncio.gather(*tasks, return_exceptions=True)
            
            # Process results
            sources = ['pubchem', 'chemspider', 'rruff', 'materials_project', 'csd', 'icsd']
            for source, result in zip(sources, results):
                if result and not isinstance(result, Exception):
                    external_data[source] = result
        
        return external_data
    
    def _apply_ml_property_models(self, compound_data: Dict[str, Any]) -> Dict[str, Any]:
        """Apply advanced ML models for property prediction"""
        predictions = {}
        
        try:
            # Prepare feature vector
            features = self._prepare_ml_features(compound_data)
            
            # 1. Deep Neural Network for thermodynamic properties
            dnn_model = self._load_or_train_dnn_model()
            dnn_predictions = dnn_model.predict(features)
            predictions['dnn_thermodynamic'] = dnn_predictions
            
            # 2. Graph Neural Network for molecular properties
            if 'smiles' in compound_data or 'structure' in compound_data:
                gnn_model = self._load_or_train_gnn_model()
                molecular_graph = self._create_molecular_graph(compound_data)
                gnn_predictions = gnn_model.predict(molecular_graph)
                predictions['gnn_molecular'] = gnn_predictions
            
            # 3. Random Forest for phase behavior
            rf_model = self._load_or_train_rf_model()
            phase_predictions = rf_model.predict(features)
            predictions['rf_phase_behavior'] = phase_predictions
            
            # 4. Gaussian Process for uncertainty quantification
            gp_model = self._load_or_train_gp_model()
            gp_mean, gp_std = gp_model.predict(features, return_std=True)
            predictions['gp_predictions'] = {'mean': gp_mean, 'std': gp_std}
            
            # 5. Ensemble predictions
            ensemble = self._ensemble_predictions(predictions)
            predictions['ensemble'] = ensemble
            
        except Exception as e:
            self.logger.error(f"ML prediction error: {e}")
        
        return predictions
    
    def _calculate_derived_properties(self, compound_data: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate derived properties using advanced thermodynamic models"""
        derived = {}
        
        try:
            # Temperature and pressure ranges for calculations
            T_range = np.linspace(273.15, 1273.15, 100)  # 0-1000°C
            P_range = np.logspace(5, 9, 50)  # 1 bar to 10 kbar
            
            # 1. Equation of State calculations
            eos_results = self._calculate_eos_properties(compound_data, T_range, P_range)
            derived['eos_properties'] = eos_results
            
            # 2. Phase diagram construction
            phase_diagram = self._construct_phase_diagram(compound_data, T_range, P_range)
            derived['phase_diagram'] = phase_diagram
            
            # 3. Transport properties
            transport = self._calculate_transport_properties(compound_data, T_range, P_range)
            derived['transport_properties'] = transport
            
            # 4. Thermodynamic cycles
            cycles = self._calculate_thermodynamic_cycles(compound_data)
            derived['thermodynamic_cycles'] = cycles
            
            # 5. Mixing rules and excess properties
            if 'mixture_components' in compound_data:
                mixing = self._calculate_mixing_properties(compound_data)
                derived['mixing_properties'] = mixing
            
        except Exception as e:
            self.logger.error(f"Derived property calculation error: {e}")
        
        return derived
    
