    def _parse_value_with_unit(self, text: str, target_unit: str) -> float:
        """Parse value with unit conversion"""
        import re
        
        # Extract number and unit
        match = re.search(r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*(\w+)?', text)
        if not match:
            return 0.0
        
        value = float(match.group(1))
        unit = match.group(2) if match.group(2) else ''
        
        # Unit conversion factors
        conversions = {
            'K': {'C': lambda x: x + 273.15, 'F': lambda x: (x - 32) * 5/9 + 273.15},
            'bar': {'Pa': lambda x: x / 1e5, 'atm': lambda x: x * 1.01325, 'psi': lambda x: x * 0.0689476},
            'kg/m3': {'g/cm3': lambda x: x * 1000, 'lb/ft3': lambda x: x * 16.0185},
            'Debye': {'C*m': lambda x: x * 3.33564e-30},
            'eV': {'kJ/mol': lambda x: x * 96.485, 'kcal/mol': lambda x: x * 23.061}
        }
        
        # Apply conversion if needed
        if target_unit in conversions and unit in conversions[target_unit]:
            value = conversions[target_unit][unit](value)
        
        return value
    
    def _parse_value_with_uncertainty(self, text: str) -> Dict[str, float]:
        """Parse value with uncertainty (e.g., '298.15 ± 0.05')"""
        import re
        
        # Pattern for value ± uncertainty
        pattern = r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)\s*(?:±|\\pm|\\+-)\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)'
        match = re.search(pattern, text)
        
        if match:
            return {
                'value': float(match.group(1)),
                'uncertainty': float(match.group(2))
            }
        
        # Try to extract just the value
        value_match = re.search(r'([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)', text)
        if value_match:
            return {
                'value': float(value_match.group(1)),
                'uncertainty': 0.0
            }
        
        return {'value': 0.0, 'uncertainty': 0.0}
    
    def _extract_property(self, soup, property_name: str, unit: str) -> float:
        """Extract a specific property from parsed HTML"""
        prop_elem = soup.find('td', string=re.compile(property_name, re.IGNORECASE))
        if prop_elem:
            value_elem = prop_elem.find_next_sibling('td')
            if value_elem:
                return self._parse_value_with_unit(value_elem.text, unit)
        return 0.0
    
    def _extract_phase_transition_data(self, soup) -> List[Dict[str, Any]]:
        """Extract phase transition data"""
        transitions = []
        
        phase_section = soup.find('h2', string=re.compile('Phase'))
        if phase_section:
            phase_table = phase_section.find_next('table')
            if phase_table:
                for row in phase_table.find_all('tr')[1:]:  # Skip header
                    cells = row.find_all('td')
                    if len(cells) >= 3:
                        transitions.append({
                            'type': cells[0].text.strip(),
                            'temperature': self._parse_value_with_unit(cells[1].text, 'K'),
                            'enthalpy': self._parse_value_with_unit(cells[2].text, 'kJ/mol') if len(cells) > 2 else None,
                            'pressure': self._parse_value_with_unit(cells[3].text, 'bar') if len(cells) > 3 else 101325
                        })
        
        return transitions
    
    def _extract_spectroscopic_data(self, soup) -> Dict[str, Any]:
        """Extract spectroscopic data"""
        spectro_data = {}
        
        # IR spectrum
        ir_section = soup.find('h3', string=re.compile('Infrared'))
        if ir_section:
            spectro_data['ir_peaks'] = self._extract_spectrum_peaks(ir_section)
        
        # Raman spectrum
        raman_section = soup.find('h3', string=re.compile('Raman'))
        if raman_section:
            spectro_data['raman_peaks'] = self._extract_spectrum_peaks(raman_section)
        
        # UV-Vis spectrum
        uv_section = soup.find('h3', string=re.compile('UV'))
        if uv_section:
            spectro_data['uv_vis_peaks'] = self._extract_spectrum_peaks(uv_section)
        
        return spectro_data
    
    def _extract_spectrum_peaks(self, section) -> List[Dict[str, float]]:
        """Extract spectroscopic peak data"""
        peaks = []
        table = section.find_next('table')
        if table:
            for row in table.find_all('tr')[1:]:
                cells = row.find_all('td')
                if len(cells) >= 2:
                    peaks.append({
                        'wavenumber': float(cells[0].text.strip()),
                        'intensity': float(cells[1].text.strip()) if len(cells) > 1 else 1.0,
                        'assignment': cells[2].text.strip() if len(cells) > 2 else ''
                    })
        return peaks
    
    def _extract_transport_properties(self, soup) -> Dict[str, Any]:
        """Extract transport properties"""
        transport = {}
        
        # Viscosity
        visc_elem = soup.find('td', string=re.compile('Viscosity'))
        if visc_elem:
            transport['viscosity'] = self._parse_value_with_unit(visc_elem.find_next_sibling('td').text, 'Pa.s')
        
        # Thermal conductivity
        thermal_elem = soup.find('td', string=re.compile('Thermal Conductivity'))
        if thermal_elem:
            transport['thermal_conductivity'] = self._parse_value_with_unit(thermal_elem.find_next_sibling('td').text, 'W/m/K')
        
        # Diffusion coefficient
        diff_elem = soup.find('td', string=re.compile('Diffusion'))
        if diff_elem:
            transport['diffusion_coefficient'] = self._parse_value_with_unit(diff_elem.find_next_sibling('td').text, 'm2/s')
        
        return transport
    
    def _extract_heat_capacity_coefficients(self, soup) -> Dict[str, float]:
        """Extract heat capacity polynomial coefficients"""
        coeffs = {}
        
        cp_section = soup.find('h3', string=re.compile('Heat Capacity'))
        if cp_section:
            # Look for Shomate equation coefficients
            shomate_table = cp_section.find_next('table', {'class': 'shomate'})
            if shomate_table:
                coeffs['type'] = 'shomate'
                for row in shomate_table.find_all('tr'):
                    cells = row.find_all('td')
                    if len(cells) >= 2:
                        param = cells[0].text.strip()
                        value = float(cells[1].text.strip())
                        coeffs[param] = value
            else:
                # Look for polynomial coefficients
                poly_text = cp_section.find_next('p')
                if poly_text:
                    import re
                    # Extract A + B*T + C*T^2 + D*T^3 coefficients
                    coeffs['type'] = 'polynomial'
                    patterns = {
                        'A': r'A\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)',
                        'B': r'B\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)',
                        'C': r'C\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)',
                        'D': r'D\s*=\s*([-+]?\d*\.?\d+(?:[eE][-+]?\d+)?)'
                    }
                    for param, pattern in patterns.items():
                        match = re.search(pattern, poly_text.text)
                        if match:
                            coeffs[param] = float(match.group(1))
        
        return coeffs
    
    async def _fetch_pubchem_data(self, session, compound: str) -> Dict[str, Any]:
        """Fetch data from PubChem API"""
        try:
            base_url = "https://pubchem.ncbi.nlm.nih.gov/rest/pug"
            
            # Search for compound
            search_url = f"{base_url}/compound/name/{compound}/property/MolecularWeight,MolecularFormula,InChI,InChIKey,CanonicalSMILES,IUPACName/JSON"
            
            async with session.get(search_url, timeout=10) as response:
                if response.status == 200:
                    data = await response.json()
                    if 'PropertyTable' in data and 'Properties' in data['PropertyTable']:
                        props = data['PropertyTable']['Properties'][0]
                        
                        # Get additional properties
                        cid = props.get('CID')
                        if cid:
                            # Fetch 3D structure
                            struct_url = f"{base_url}/compound/cid/{cid}/SDF"
                            async with session.get(struct_url) as struct_response:
                                if struct_response.status == 200:
                                    props['structure_3d'] = await struct_response.text()
                        
                        return props
        except Exception as e:
            self.logger.error(f"PubChem fetch error: {e}")
        
        return {}
    
    async def _fetch_chemspider_data(self, session, compound: str) -> Dict[str, Any]:
        """Fetch data from ChemSpider API"""
        try:
            api_key = os.environ.get('CHEMSPIDER_API_KEY', '')
            if not api_key:
                return {}
            
            base_url = "https://api.rsc.org/compounds/v1"
            headers = {'apikey': api_key}
            
            # Search for compound
            search_url = f"{base_url}/filter/name"
            search_data = {'name': compound}
            
            async with session.post(search_url, json=search_data, headers=headers) as response:
                if response.status == 200:
                    result = await response.json()
                    if result.get('queryId'):
                        # Get results
                        results_url = f"{base_url}/filter/{result['queryId']}/results"
                        async with session.get(results_url, headers=headers) as results_response:
                            if results_response.status == 200:
                                compounds = await results_response.json()
                                if compounds:
                                    # Get detailed data for first match
                                    record_id = compounds[0].get('recordId')
                                    if record_id:
                                        details_url = f"{base_url}/records/{record_id}/details"
                                        async with session.get(details_url, headers=headers) as details_response:
                                            if details_response.status == 200:
                                                return await details_response.json()
        except Exception as e:
            self.logger.error(f"ChemSpider fetch error: {e}")
        
        return {}
    
    async def _fetch_rruff_data(self, session, compound: str) -> Dict[str, Any]:
        """Fetch mineral data from RRUFF database"""
        try:
            base_url = "https://rruff.info"
            
            # Search for mineral
            search_url = f"{base_url}/mineral_list/search.php"
            params = {'mineral': compound}
            
            async with session.get(search_url, params=params) as response:
                if response.status == 200:
                    # Parse HTML response (simplified)
                    html = await response.text()
                    # Extract mineral data (would need proper HTML parsing)
                    return {'mineral_name': compound, 'source': 'RRUFF'}
        except Exception as e:
            self.logger.error(f"RRUFF fetch error: {e}")
        
        return {}
    
    async def _fetch_materials_project_data(self, session, compound: str) -> Dict[str, Any]:
        """Fetch data from Materials Project API"""
        try:
            api_key = os.environ.get('MATERIALS_PROJECT_API_KEY', '')
            if not api_key:
                return {}
            
            base_url = "https://api.materialsproject.org"
            headers = {'X-API-KEY': api_key}
            
            # Search for material
            search_url = f"{base_url}/materials/summary"
            params = {'formula': compound}
            
            async with session.get(search_url, params=params, headers=headers) as response:
                if response.status == 200:
                    data = await response.json()
                    if data.get('data'):
                        return data['data'][0]  # Return first match
        except Exception as e:
            self.logger.error(f"Materials Project fetch error: {e}")
        
        return {}
    
    async def _fetch_csd_data(self, session, compound: str) -> Dict[str, Any]:
        """
        Advanced Cambridge Structural Database (CSD) integration with comprehensive
        crystal structure analysis, ML-based property prediction, and database storage
        """
        try:
            # Multi-tier CSD data fetching strategy
            csd_data = {}
            
            # Tier 1: Direct CSD API access (requires institutional license)
            api_data = await self._fetch_direct_csd_api(session, compound)
            if api_data:
                csd_data.update(api_data)
            
            # Tier 2: CSD Web Service integration
            web_service_data = await self._fetch_csd_web_service(session, compound)
            if web_service_data:
                csd_data.update(web_service_data)
            
            # Tier 3: Academic CSD mirror databases
            mirror_data = await self._fetch_csd_academic_mirrors(session, compound)
            if mirror_data:
                csd_data.update(mirror_data)
            
            # Tier 4: Cross-reference with COD for open structures
            cod_cross_ref = await self._cross_reference_cod_structures(session, compound)
            if cod_cross_ref:
                csd_data['cod_cross_reference'] = cod_cross_ref
            
            # Apply advanced crystal structure analysis
            if csd_data:
                csd_data = await self._analyze_crystal_structures(csd_data, compound)
                
                # ML-based property prediction from structure
                ml_predictions = await self._predict_properties_from_structure(csd_data)
                if ml_predictions:
                    csd_data['ml_predictions'] = ml_predictions
                
                # Cache results in database
                await self._cache_csd_data(compound, csd_data)
                
                # Update knowledge graph
                await self._update_csd_knowledge_graph(compound, csd_data)
                
                self.logger.info(f"Advanced CSD data fetched for {compound}: "
                               f"{len(csd_data.get('structures', []))} structures, "
                               f"{len(csd_data.get('polymorphs', []))} polymorphs")
            
            return csd_data
            
        except Exception as e:
            self.logger.error(f"CSD data fetching failed for {compound}: {e}")
            # Fallback to cached data
            cached_data = await self._get_cached_csd_data(compound)
            return cached_data or {}
    
    async def _fetch_direct_csd_api(self, session, compound: str) -> Dict[str, Any]:
        """Direct CSD API access with advanced authentication and query optimization"""
        try:
            # Check for CSD API credentials
            csd_api_key = os.environ.get('CSD_API_KEY')
            csd_username = os.environ.get('CSD_USERNAME')
            csd_password = os.environ.get('CSD_PASSWORD')
            
            if not (csd_api_key or (csd_username and csd_password)):
                return {}
            
            # CSD ConQuest API endpoint
            base_url = "https://csd.ccdc.cam.ac.uk/api/v1"
            
            # Authentication headers
            headers = {
                'User-Agent': 'Prometheus-Geological-System/2.0',
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
            
            if csd_api_key:
                headers['Authorization'] = f'Bearer {csd_api_key}'
            else:
                # Basic authentication
                import base64
                credentials = base64.b64encode(f"{csd_username}:{csd_password}".encode()).decode()
                headers['Authorization'] = f'Basic {credentials}'
            
            # Advanced search query construction
            search_queries = self._construct_csd_search_queries(compound)
            
            all_results = {}
            for query_type, query_params in search_queries.items():
                try:
                    search_url = f"{base_url}/search/{query_type}"
                    
                    # Implement rate limiting
                    await asyncio.sleep(0.5)  # 2 requests per second limit
                    
                    timeout = aiohttp.ClientTimeout(total=30)
                    async with session.post(search_url, 
                                          json=query_params, 
                                          headers=headers,
                                          timeout=timeout) as response:
                        
                        if response.status == 200:
                            data = await response.json()
                            if data.get('results'):
                                all_results[query_type] = data['results']
                        elif response.status == 401:
                            self.logger.warning("CSD API authentication failed")
                            break
                        elif response.status == 429:
                            # Rate limited - wait and retry
                            await asyncio.sleep(2)
                            continue
                        
                except asyncio.TimeoutError:
                    self.logger.warning(f"CSD API timeout for query type: {query_type}")
                    continue
            
            if all_results:
                # Process and structure the results
                processed_data = await self._process_csd_api_results(all_results, compound)
                return processed_data
            
        except Exception as e:
            self.logger.debug(f"Direct CSD API access failed: {e}")
        
        return {}
    
    async def _fetch_csd_web_service(self, session, compound: str) -> Dict[str, Any]:
        """CSD Web Service integration for broader accessibility"""
        try:
            # CCDC WebCSD service
            webcsd_url = "https://www.ccdc.cam.ac.uk/structures"
            
            # Construct search parameters
            search_params = {
                'searchType': 'compound',
                'searchTerm': compound,
                'format': 'json',
                'maxResults': 50
            }
            
            # Add molecular formula variants
            formula_variants = self._generate_formula_variants(compound)
            
            all_structures = []
            
            for variant in formula_variants[:5]:  # Limit to 5 variants
                params = search_params.copy()
                params['searchTerm'] = variant
                
                try:
                    await asyncio.sleep(0.5)  # Rate limiting
                    
                    async with session.get(webcsd_url, params=params) as response:
                        if response.status == 200:
                            # Parse response (would depend on actual WebCSD response format)
                            content = await response.text()
                            structures = self._parse_webcsd_response(content, variant)
                            if structures:
                                all_structures.extend(structures)
                        
                except Exception as e:
                    self.logger.debug(f"WebCSD query failed for variant {variant}: {e}")
                    continue
            
            if all_structures:
                return {
                    'web_service_structures': all_structures,
                    'source': 'CSD_WebService',
                    'query_variants': formula_variants,
                    'total_structures': len(all_structures)
                }
                
        except Exception as e:
            self.logger.debug(f"CSD Web Service access failed: {e}")
        
        return {}
    
