    async def _perform_structural_analysis(self, structures: List[Dict]) -> Dict[str, Any]:
        """Comprehensive structural analysis of crystal structures"""
        if not structures:
            return {}
        
        analysis = {
            'space_group_distribution': {},
            'cell_parameter_statistics': {},
            'symmetry_analysis': {},
            'structural_motifs': []
        }
        
        try:
            # Space group analysis
            space_groups = [s.get('space_group', 'unknown') for s in structures]
            unique_groups = set(space_groups)
            analysis['space_group_distribution'] = {
                sg: space_groups.count(sg) for sg in unique_groups
            }
            
            # Cell parameter statistics
            cell_volumes = [s.get('cell_volume', 0) for s in structures if s.get('cell_volume')]
            if cell_volumes:
                analysis['cell_parameter_statistics'] = {
                    'volume_mean': np.mean(cell_volumes),
                    'volume_std': np.std(cell_volumes),
                    'volume_range': [min(cell_volumes), max(cell_volumes)]
                }
            
            # Additional structural analysis would go here
            
        except Exception as e:
            self.logger.error(f"Structural analysis failed: {e}")
        
        return analysis
    
    async def _detect_polymorphs(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Advanced polymorph detection and classification"""
        if len(structures) < 2:
            return {}
        
        try:
            polymorphs = {
                'polymorph_count': 0,
                'polymorphs': [],
                'phase_diagram': {}
            }
            
            # Group structures by space group and cell parameters
            structure_groups = {}
            for i, structure in enumerate(structures):
                key = f"{structure.get('space_group', 'unknown')}_{structure.get('cell_volume', 0):.2f}"
                if key not in structure_groups:
                    structure_groups[key] = []
                structure_groups[key].append((i, structure))
            
            # Identify potential polymorphs
            if len(structure_groups) > 1:
                polymorphs['polymorph_count'] = len(structure_groups)
                
                for group_key, group_structures in structure_groups.items():
                    representative = group_structures[0][1]
                    polymorphs['polymorphs'].append({
                        'variant': group_key,
                        'structure_count': len(group_structures),
                        'representative_structure': representative,
                        'space_group': representative.get('space_group'),
                        'cell_parameters': representative.get('cell_parameters', {})
                    })
            
            return polymorphs
            
        except Exception as e:
            self.logger.error(f"Polymorph detection failed: {e}")
            return {}
    
    async def _map_phase_relationships(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """
        Advanced phase relationship mapping using crystallographic analysis,
        thermodynamic modeling, and machine learning predictions
        """
        phase_analysis = {
            'phases': [],
            'stability_regions': {},
            'transition_temperatures': [],
            'phase_diagram': {},
            'polymorphs': {},
            'pressure_temperature_relationships': {}
        }
        
        if not structures:
            return phase_analysis
        
        try:
            # Group structures by space group and composition
            space_group_analysis = await self._analyze_space_groups(structures, compound)
            phase_analysis['space_group_distribution'] = space_group_analysis
            
            # Identify unique phases based on structural similarity
            unique_phases = await self._identify_unique_phases(structures)
            phase_analysis['phases'] = unique_phases
            
            # Calculate stability fields using Gibbs free energy approximation
            stability_analysis = await self._calculate_stability_fields(structures, compound)
            phase_analysis['stability_regions'] = stability_analysis
            
            # Predict phase transition temperatures using ML and thermodynamic data
            transition_temps = await self._predict_phase_transitions(structures, compound)
            phase_analysis['transition_temperatures'] = transition_temps
            
            # Generate P-T phase diagram coordinates
            pt_diagram = await self._generate_pt_diagram(structures, compound)
            phase_analysis['phase_diagram'] = pt_diagram
            
            # Advanced polymorph analysis with structural descriptors
            polymorph_analysis = await self._advanced_polymorph_analysis(structures, compound)
            phase_analysis['polymorphs'] = polymorph_analysis
            
            # Pressure-temperature stability predictions
            pt_stability = await self._predict_pt_stability(structures, compound)
            phase_analysis['pressure_temperature_relationships'] = pt_stability
            
        except Exception as e:
            self.logger.error(f"Error in phase relationship mapping for {compound}: {e}")
            phase_analysis['error'] = str(e)
        
        return phase_analysis
    
    async def _analyze_space_groups(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Analyze space group distribution and crystal systems"""
        space_groups = {}
        crystal_systems = defaultdict(int)
        
        for structure in structures:
            sg = structure.get('space_group', 'Unknown')
            if sg not in space_groups:
                space_groups[sg] = {
                    'count': 0,
                    'structures': [],
                    'average_volume': 0,
                    'density_range': [float('inf'), float('-inf')]
                }
            
            space_groups[sg]['count'] += 1
            space_groups[sg]['structures'].append(structure)
            
            # Calculate crystal system from space group
            crystal_system = self._get_crystal_system(sg)
            crystal_systems[crystal_system] += 1
            
            # Update volume and density statistics
            if 'cell_volume' in structure:
                current_avg = space_groups[sg]['average_volume']
                count = space_groups[sg]['count']
                space_groups[sg]['average_volume'] = (current_avg * (count-1) + structure['cell_volume']) / count
            
            if 'density' in structure:
                density = structure['density']
                space_groups[sg]['density_range'][0] = min(space_groups[sg]['density_range'][0], density)
                space_groups[sg]['density_range'][1] = max(space_groups[sg]['density_range'][1], density)
        
        return {
            'space_groups': dict(space_groups),
            'crystal_systems': dict(crystal_systems),
            'most_common_space_group': max(space_groups.keys(), key=lambda x: space_groups[x]['count']) if space_groups else None,
            'total_unique_space_groups': len(space_groups)
        }
    
    async def _identify_unique_phases(self, structures: List[Dict]) -> List[Dict[str, Any]]:
        """Identify unique crystalline phases using structural similarity"""
        phases = []
        
        # Group structures by structural similarity
        similarity_threshold = 0.85
        processed_indices = set()
        
        for i, structure in enumerate(structures):
            if i in processed_indices:
                continue
                
            # Create new phase
            phase = {
                'phase_id': len(phases) + 1,
                'representative_structure': structure,
                'member_structures': [structure],
                'space_group': structure.get('space_group', 'Unknown'),
                'crystal_system': self._get_crystal_system(structure.get('space_group', '')),
                'cell_parameters': structure.get('cell_parameters', {}),
                'density': structure.get('density', 0),
                'stability_score': 0
            }
            
            processed_indices.add(i)
            
            # Find similar structures
            for j, other_structure in enumerate(structures):
                if j <= i or j in processed_indices:
                    continue
                
                similarity = await self._calculate_structural_similarity(structure, other_structure)
                if similarity > similarity_threshold:
                    phase['member_structures'].append(other_structure)
                    processed_indices.add(j)
            
            phases.append(phase)
        
        # Calculate stability scores for each phase
        for phase in phases:
            phase['stability_score'] = await self._calculate_phase_stability_score(phase)
        
        # Sort phases by stability
        phases.sort(key=lambda x: x['stability_score'], reverse=True)
        
        return phases
    
    async def _calculate_stability_fields(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Calculate thermodynamic stability fields for different phases"""
        stability_fields = {}
        
        # Get thermodynamic data for the compound
        thermo_data = await self._get_thermodynamic_data(compound)
        
        # Calculate stability for each unique phase
        unique_phases = await self._identify_unique_phases(structures)
        
        for phase in unique_phases:
            phase_id = phase['phase_id']
            
            # Calculate Gibbs free energy as function of P,T
            stability_field = {
                'pressure_range': [0, 100],  # GPa
                'temperature_range': [0, 3000],  # K
                'stability_boundaries': [],
                'dominant_conditions': {}
            }
            
            # Use crystallographic data to estimate stability
            if phase.get('density') and thermo_data:
                # Higher density phases more stable at high pressure
                p_stability = min(100, phase['density'] * 10)  # Rough approximation
                stability_field['pressure_range'][1] = p_stability
                
                # Use melting point data if available
                if 'melting_point' in thermo_data:
                    mp = thermo_data['melting_point']
                    stability_field['temperature_range'][1] = mp * 0.9  # Below melting
            
            stability_fields[f'phase_{phase_id}'] = stability_field
        
        return stability_fields
    
    async def _predict_phase_transitions(self, structures: List[Dict], compound: str) -> List[Dict[str, Any]]:
        """Predict phase transition temperatures using ML and thermodynamics"""
        transitions = []
        
        unique_phases = await self._identify_unique_phases(structures)
        
        # Sort phases by density (proxy for pressure stability)
        phases_by_density = sorted(unique_phases, key=lambda x: x.get('density', 0))
        
        for i in range(len(phases_by_density) - 1):
            low_p_phase = phases_by_density[i]
            high_p_phase = phases_by_density[i + 1]
            
            # Estimate transition conditions using Clapeyron equation approximation
            delta_v = (1/high_p_phase.get('density', 1)) - (1/low_p_phase.get('density', 1))
            
            # Rough estimation of transition temperature
            # This would use actual thermodynamic data in production
            base_temp = 300  # Room temperature
            transition_temp = base_temp + (high_p_phase.get('density', 1) - low_p_phase.get('density', 1)) * 100
            
            transition = {
                'from_phase': low_p_phase['phase_id'],
                'to_phase': high_p_phase['phase_id'],
                'transition_temperature': transition_temp,
                'transition_pressure': (high_p_phase.get('density', 1) / low_p_phase.get('density', 1)) * 10,
                'volume_change': delta_v,
                'transition_type': 'first_order' if abs(delta_v) > 0.1 else 'second_order'
            }
            
            transitions.append(transition)
        
        return transitions
    
    async def _generate_pt_diagram(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Generate pressure-temperature phase diagram data"""
        pt_diagram = {
            'pressure_points': np.linspace(0, 100, 50),  # GPa
            'temperature_points': np.linspace(0, 3000, 50),  # K
            'phase_fields': {},
            'phase_boundaries': [],
            'triple_points': [],
            'critical_points': []
        }
        
        # Get stability fields
        stability_fields = await self._calculate_stability_fields(structures, compound)
        
        # Map phase stability across P-T space
        P, T = np.meshgrid(pt_diagram['pressure_points'], pt_diagram['temperature_points'])
        
        for phase_name, field_data in stability_fields.items():
            # Create stability matrix
            stability_matrix = np.zeros_like(P)
            
            p_range = field_data['pressure_range']
            t_range = field_data['temperature_range']
            
            # Simple rectangular stability field (would be more complex in reality)
            mask = ((P >= p_range[0]) & (P <= p_range[1]) & 
                   (T >= t_range[0]) & (T <= t_range[1]))
            
            stability_matrix[mask] = 1.0
            pt_diagram['phase_fields'][phase_name] = stability_matrix.tolist()
        
        return pt_diagram
    
    async def _advanced_polymorph_analysis(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Advanced analysis of polymorphic relationships"""
        polymorph_analysis = {
            'total_polymorphs': 0,
            'polymorph_groups': [],
            'structural_relationships': {},
            'transformation_pathways': [],
            'energy_differences': {}
        }
        
        # Group by formula to find polymorphs
        formula_groups = defaultdict(list)
        for structure in structures:
            formula = structure.get('formula', compound)
            formula_groups[formula].append(structure)
        
        for formula, formula_structures in formula_groups.items():
            if len(formula_structures) > 1:
                # Multiple structures with same formula = polymorphs
                polymorph_group = {
                    'formula': formula,
                    'polymorph_count': len(formula_structures),
                    'space_groups': [s.get('space_group', 'Unknown') for s in formula_structures],
                    'density_range': [
                        min(s.get('density', 0) for s in formula_structures),
                        max(s.get('density', 0) for s in formula_structures)
                    ],
                    'volume_range': [
                        min(s.get('cell_volume', 0) for s in formula_structures),
                        max(s.get('cell_volume', 0) for s in formula_structures)
                    ]
                }
                
                polymorph_analysis['polymorph_groups'].append(polymorph_group)
                polymorph_analysis['total_polymorphs'] += len(formula_structures)
        
        return polymorph_analysis
    
    async def _predict_pt_stability(self, structures: List[Dict], compound: str) -> Dict[str, Any]:
        """Predict pressure-temperature stability using ML models"""
        pt_stability = {
            'stability_predictions': {},
            'confidence_intervals': {},
            'phase_transition_predictions': [],
            'optimal_synthesis_conditions': {}
        }
        
        # Extract features for ML prediction
        features = []
        for structure in structures:
            feature_vector = [
                structure.get('density', 0),
                structure.get('cell_volume', 0),
                len(structure.get('space_group', '')),  # Proxy for complexity
                structure.get('formula_weight', 0) if 'formula_weight' in structure else 0
            ]
            features.append(feature_vector)
        
        if features:
            features_array = np.array(features)
            
            # Use Gaussian Process for uncertainty quantification
            gp = GaussianProcessRegressor(
                kernel=RBF(length_scale=1.0) + WhiteKernel(noise_level=1e-5),
                alpha=1e-10,
                normalize_y=True
            )
            
            # Mock target values (would use actual stability data)
            targets = np.random.random(len(features)) * 1000  # Mock stability temperatures
            
            try:
                gp.fit(features_array, targets)
                
                # Predict stability for pressure/temperature grid
                test_conditions = np.array([[d, v, sg, fw] for d, v, sg, fw in features])
                predictions, uncertainties = gp.predict(test_conditions, return_std=True)
                
                pt_stability['stability_predictions'] = predictions.tolist()
                pt_stability['confidence_intervals'] = uncertainties.tolist()
                
            except Exception as e:
                self.logger.warning(f"ML stability prediction failed: {e}")
        
        return pt_stability
    
    def _get_crystal_system(self, space_group: str) -> str:
        """Determine crystal system from space group"""
        if not space_group or space_group == 'Unknown':
            return 'Unknown'
        
        # Space group to crystal system mapping (simplified)
        if any(sg in space_group for sg in ['P1', 'P-1']):
            return 'Triclinic'
        elif any(sg in space_group for sg in ['P2', 'P21', 'C2', 'Pm', 'Pc', 'Cm', 'Cc']):
            return 'Monoclinic'
        elif any(sg in space_group for sg in ['P222', 'P2221', 'P21212', 'P212121', 'C2221', 'C222', 'F222', 'I222', 'I212121']):
            return 'Orthorhombic'
        elif any(sg in space_group for sg in ['P4', 'P41', 'P42', 'P43', 'I4', 'I41']):
            return 'Tetragonal'
        elif any(sg in space_group for sg in ['R3', 'R-3', 'P3', 'P31', 'P32', 'P6', 'P61', 'P65', 'P62', 'P64', 'P63']):
            return 'Trigonal/Hexagonal'
        elif any(sg in space_group for sg in ['P23', 'F23', 'I23', 'P213', 'I213', 'Pm3', 'Pn3', 'Fm3', 'Fd3', 'Im3', 'Pa3', 'Ia3']):
            return 'Cubic'
        else:
            return 'Unknown'
    
    async def _calculate_structural_similarity(self, struct1: Dict, struct2: Dict) -> float:
        """Calculate structural similarity between two crystal structures"""
        similarity = 0.0
        
        # Space group similarity (exact match = 1.0)
        if struct1.get('space_group') == struct2.get('space_group'):
            similarity += 0.4
        
        # Cell parameter similarity
        params1 = struct1.get('cell_parameters', {})
        params2 = struct2.get('cell_parameters', {})
        
        if params1 and params2:
            param_sim = 0
            common_params = set(params1.keys()) & set(params2.keys())
            
            for param in common_params:
                val1, val2 = params1[param], params2[param]
                if val1 > 0 and val2 > 0:
                    ratio = min(val1, val2) / max(val1, val2)
                    param_sim += ratio
            
            if common_params:
                similarity += 0.3 * (param_sim / len(common_params))
        
        # Density similarity
        dens1 = struct1.get('density', 0)
        dens2 = struct2.get('density', 0)
        if dens1 > 0 and dens2 > 0:
            density_ratio = min(dens1, dens2) / max(dens1, dens2)
            similarity += 0.3 * density_ratio
        
        return similarity
    
    async def _calculate_phase_stability_score(self, phase: Dict) -> float:
        """Calculate relative stability score for a phase"""
        score = 0.0
        
        # More structures in phase = higher stability
        structure_count = len(phase.get('member_structures', []))
        score += min(structure_count * 0.1, 1.0)
        
        # Higher density often indicates stability
        density = phase.get('density', 0)
        if density > 0:
            score += min(density / 10.0, 1.0)  # Normalize density contribution
        
        # Common space groups tend to be more stable
        space_group = phase.get('space_group', '')
        if space_group in ['Fm-3m', 'Pm-3m', 'P63/mmc', 'Fd-3m']:  # Common stable structures
            score += 0.5
        
        return score
    
