    def _load_or_train_dnn_model(self):
        """Load or train DNN model for property prediction"""
        try:
            import torch
            import torch.nn as nn
            
            class PropertyDNN(nn.Module):
                def __init__(self, input_dim=16, hidden_dims=[128, 256, 128], output_dim=10):
                    super().__init__()
                    layers = []
                    prev_dim = input_dim
                    
                    for hidden_dim in hidden_dims:
                        layers.extend([
                            nn.Linear(prev_dim, hidden_dim),
                            nn.ReLU(),
                            nn.BatchNorm1d(hidden_dim),
                            nn.Dropout(0.2)
                        ])
                        prev_dim = hidden_dim
                    
                    layers.append(nn.Linear(prev_dim, output_dim))
                    self.network = nn.Sequential(*layers)
                
                def forward(self, x):
                    return self.network(x)
                
                def predict(self, x):
                    self.eval()
                    with torch.no_grad():
                        if isinstance(x, np.ndarray):
                            x = torch.FloatTensor(x)
                        return self.forward(x).numpy()
            
            model = PropertyDNN()
            
            # Load pre-trained weights if available
            model_path = 'models/property_dnn.pth'
            if os.path.exists(model_path):
                model.load_state_dict(torch.load(model_path))
            
            return model
            
        except Exception as e:
            self.logger.error(f"DNN model error: {e}")
            return None
    
    def _load_or_train_gnn_model(self):
        """Load or train advanced Graph Neural Network model for molecular properties"""
        try:
            import torch
            import torch.nn as nn
            import torch.nn.functional as F
            from torch_geometric.nn import GCNConv, GATConv, global_mean_pool, global_max_pool, global_add_pool
            from torch_geometric.nn import MessagePassing, GraphNorm, BatchNorm
            from torch_geometric.data import Data, Batch
            import numpy as np
            import os
            from datetime import datetime
            
        except ImportError as e:
            self.logger.warning(f"PyTorch Geometric not available, using fallback: {e}")
            return self._load_fallback_gnn_model()
        
        try:
            class AdvancedMolecularGNN(nn.Module):
                """
                Advanced Graph Neural Network for molecular property prediction.
                Combines multiple GNN layers with attention mechanisms and geological context.
                """
                
                def __init__(self, node_features=14, edge_features=5, hidden_dim=128, 
                           num_layers=4, num_heads=8, output_dim=10, dropout=0.2):
                    super().__init__()
                    
                    self.node_features = node_features
                    self.hidden_dim = hidden_dim
                    self.num_layers = num_layers
                    self.num_heads = num_heads
                    self.dropout = dropout
                    
                    # Input projection for node features
                    self.node_encoder = nn.Linear(node_features, hidden_dim)
                    self.edge_encoder = nn.Linear(edge_features, hidden_dim // 4) if edge_features > 0 else None
                    
                    # Multi-layer GNN with different architectures
                    self.gnn_layers = nn.ModuleList()
                    self.attention_layers = nn.ModuleList()
                    self.norm_layers = nn.ModuleList()
                    
                    for i in range(num_layers):
                        # Alternate between GCN and GAT layers for diversity
                        if i % 2 == 0:
                            # Graph Attention Network layer
                            gnn_layer = GATConv(
                                hidden_dim, hidden_dim // num_heads,
                                heads=num_heads, dropout=dropout,
                                edge_dim=hidden_dim // 4 if edge_features > 0 else None,
                                concat=True
                            )
                        else:
                            # Graph Convolutional Network layer
                            gnn_layer = GCNConv(hidden_dim, hidden_dim)
                        
                        self.gnn_layers.append(gnn_layer)
                        self.norm_layers.append(GraphNorm(hidden_dim))
                        
                        # Self-attention for long-range dependencies
                        self.attention_layers.append(
                            nn.MultiheadAttention(hidden_dim, num_heads, dropout=dropout, batch_first=True)
                        )
                    
                    # Global pooling and readout
                    self.global_pool_layers = nn.ModuleList([
                        lambda x, batch: global_mean_pool(x, batch),
                        lambda x, batch: global_max_pool(x, batch),
                        lambda x, batch: global_add_pool(x, batch)
                    ])
                    
                    # Feature fusion and prediction head
                    fusion_dim = hidden_dim * 3  # Three pooling methods
                    self.fusion_layer = nn.Sequential(
                        nn.Linear(fusion_dim, hidden_dim * 2),
                        nn.ReLU(),
                        nn.Dropout(dropout),
                        nn.Linear(hidden_dim * 2, hidden_dim),
                        nn.ReLU(),
                        nn.Dropout(dropout)
                    )
                    
                    # Multi-task prediction heads
                    self.prediction_heads = nn.ModuleDict({
                        'thermodynamic': nn.Linear(hidden_dim, 8),  # Thermodynamic properties
                        'structural': nn.Linear(hidden_dim, 6),     # Structural properties  
                        'geological': nn.Linear(hidden_dim, 5),     # Geological context
                        'stability': nn.Linear(hidden_dim, 3),      # Stability metrics
                    })
                    
                    # Uncertainty quantification
                    self.uncertainty_head = nn.Linear(hidden_dim, output_dim)
                    
                def forward(self, data):
                    x, edge_index, edge_attr = data.x, data.edge_index, data.edge_attr
                    batch = data.batch if hasattr(data, 'batch') else None
                    
                    # Encode initial features
                    x = F.relu(self.node_encoder(x))
                    if self.edge_encoder is not None and edge_attr is not None:
                        edge_attr = self.edge_encoder(edge_attr)
                    
                    # Store residual connections
                    residual_features = []
                    
                    # Apply GNN layers
                    for i, (gnn_layer, norm_layer, attn_layer) in enumerate(
                        zip(self.gnn_layers, self.norm_layers, self.attention_layers)):
                        
                        # Store residual
                        residual = x
                        residual_features.append(x)
                        
                        # Apply GNN layer
                        if isinstance(gnn_layer, GATConv):
                            x = gnn_layer(x, edge_index, edge_attr=edge_attr)
                        else:
                            x = gnn_layer(x, edge_index)
                        
                        # Normalization and activation
                        x = norm_layer(x)
                        x = F.relu(x)
                        x = F.dropout(x, p=self.dropout, training=self.training)
                        
                        # Residual connection
                        if x.size(-1) == residual.size(-1):
                            x = x + residual
                        
                        # Self-attention for global dependencies
                        if batch is not None:
                            x_pooled = global_mean_pool(x, batch).unsqueeze(1)  # (batch_size, 1, hidden_dim)
                            x_attn, _ = attn_layer(x_pooled, x_pooled, x_pooled)
                            x_attn = x_attn.squeeze(1)  # (batch_size, hidden_dim)
                            # Add attention influence
                            x = x + 0.1 * x_attn[batch]
                    
                    # Global pooling with multiple strategies
                    if batch is not None:
                        pooled_features = []
                        for pool_fn in self.global_pool_layers:
                            pooled = pool_fn(x, batch)
                            pooled_features.append(pooled)
                        
                        # Concatenate different pooling strategies
                        graph_repr = torch.cat(pooled_features, dim=-1)
                    else:
                        # Single graph case
                        graph_repr = torch.cat([
                            x.mean(dim=0, keepdim=True),
                            x.max(dim=0, keepdim=True)[0],
                            x.sum(dim=0, keepdim=True)
                        ], dim=-1)
                    
                    # Feature fusion
                    fused_features = self.fusion_layer(graph_repr)
                    
                    # Multi-task predictions
                    predictions = {}
                    for task, head in self.prediction_heads.items():
                        predictions[task] = head(fused_features)
                    
                    # Uncertainty estimation
                    predictions['uncertainty'] = F.softplus(self.uncertainty_head(fused_features))
                    
                    return predictions
                
                def predict(self, molecular_graph):
                    """Make predictions with the GNN model"""
                    self.eval()
                    with torch.no_grad():
                        if isinstance(molecular_graph, dict):
                            # Convert dict to PyTorch Geometric Data object
                            data = Data(
                                x=molecular_graph.get('x'),
                                edge_index=molecular_graph.get('edge_index'),
                                edge_attr=molecular_graph.get('edge_attr')
                            )
                        else:
                            data = molecular_graph
                            
                        predictions = self.forward(data)
                        
                        # Convert predictions to numpy
                        for key, value in predictions.items():
                            predictions[key] = value.cpu().numpy()
                            
                        return predictions
            
            # Initialize or load model
            model_config = {
                'node_features': 14,
                'edge_features': 5, 
                'hidden_dim': 128,
                'num_layers': 4,
                'num_heads': 8,
                'output_dim': 10,
                'dropout': 0.2
            }
            
            model = AdvancedMolecularGNN(**model_config)
            
            # Try to load pre-trained weights from model database
            model_loaded = False
            if hasattr(self, 'model_database') and self.model_database:
                try:
                    saved_model = self.model_database.load_model('molecular_gnn_v2')
                    if saved_model and 'state_dict' in saved_model:
                        model.load_state_dict(saved_model['state_dict'])
                        model_loaded = True
                        self.logger.info("Loaded GNN model from database")
                except Exception as e:
                    self.logger.warning(f"Could not load GNN from database: {e}")
            
            # Fallback to file-based loading
            if not model_loaded:
                model_path = 'models/molecular_gnn_v2.pth'
                if os.path.exists(model_path):
                    try:
                        checkpoint = torch.load(model_path, map_location='cpu')
                        model.load_state_dict(checkpoint.get('model_state_dict', checkpoint))
                        model_loaded = True
                        self.logger.info("Loaded GNN model from file")
                    except Exception as e:
                        self.logger.warning(f"Could not load GNN from file: {e}")
            
            if not model_loaded:
                self.logger.info("Using freshly initialized GNN model")
                # Save initial model to database for future use
                if hasattr(self, 'model_database') and self.model_database:
                    try:
                        model_data = {
                            'state_dict': model.state_dict(),
                            'config': model_config,
                            'created_at': datetime.now().isoformat(),
                            'version': 'v2.0',
                            'architecture': 'AdvancedMolecularGNN'
                        }
                        self.model_database.save_model('molecular_gnn_v2', model_data)
                    except Exception as e:
                        self.logger.warning(f"Could not save initial GNN to database: {e}")
            
            # Integrate with existing model management
            if hasattr(self, 'model_manager') and self.model_manager:
                try:
                    # Register with model manager for monitoring and updates
                    self.model_manager.register_model(
                        'molecular_gnn',
                        model,
                        model_type='graph_neural_network',
                        version='v2.0'
                    )
                except Exception as e:
                    self.logger.warning(f"Could not register GNN with model manager: {e}")
            
            return model
            
        except Exception as e:
            self.logger.error(f"GNN model initialization error: {e}")
            return self._load_fallback_gnn_model()
    
    def _load_fallback_gnn_model(self):
        """Fallback GNN implementation using standard PyTorch"""
        try:
            import torch
            import torch.nn as nn
            import torch.nn.functional as F
            
            class SimpleMolecularGNN(nn.Module):
                """Simple GNN fallback when PyTorch Geometric is not available"""
                
                def __init__(self, node_features=14, hidden_dim=64, output_dim=10):
                    super().__init__()
                    self.node_features = node_features
                    self.hidden_dim = hidden_dim
                    
                    # Simple message passing layers
                    self.message_layers = nn.ModuleList([
                        nn.Linear(node_features * 2, hidden_dim),
                        nn.Linear(hidden_dim, hidden_dim),
                        nn.Linear(hidden_dim, hidden_dim)
                    ])
                    
                    # Node update layers
                    self.update_layers = nn.ModuleList([
                        nn.Linear(node_features + hidden_dim, hidden_dim),
                        nn.Linear(hidden_dim, hidden_dim),
                        nn.Linear(hidden_dim, hidden_dim)
                    ])
                    
                    # Graph-level prediction
                    self.graph_layer = nn.Sequential(
                        nn.Linear(hidden_dim, hidden_dim),
                        nn.ReLU(),
                        nn.Linear(hidden_dim, output_dim)
                    )
                
                def forward(self, node_features, adj_matrix):
                    """Forward pass with adjacency matrix"""
                    x = node_features
                    
                    # Simple message passing
                    for msg_layer, upd_layer in zip(self.message_layers, self.update_layers):
                        # Create messages between connected nodes
                        messages = []
                        for i in range(x.size(0)):
                            neighbors = torch.nonzero(adj_matrix[i]).squeeze()
                            if neighbors.numel() > 0:
                                if neighbors.dim() == 0:
                                    neighbors = neighbors.unsqueeze(0)
                                neighbor_features = x[neighbors]
                                node_expand = x[i].unsqueeze(0).expand(neighbors.size(0), -1)
                                edge_features = torch.cat([node_expand, neighbor_features], dim=1)
                                message = msg_layer(edge_features).mean(dim=0)
                                messages.append(message)
                            else:
                                messages.append(torch.zeros(self.hidden_dim))
                        
                        messages = torch.stack(messages)
                        
                        # Update node features
                        x_input = torch.cat([x, messages], dim=1)
                        x = F.relu(upd_layer(x_input))
                    
                    # Global pooling (mean)
                    graph_repr = x.mean(dim=0)
                    
                    # Graph prediction
                    return self.graph_layer(graph_repr)
                
                def predict(self, molecular_graph):
                    """Make predictions with fallback GNN"""
                    self.eval()
                    with torch.no_grad():
                        if isinstance(molecular_graph, dict):
                            node_features = molecular_graph.get('x')
                            adj_matrix = molecular_graph.get('adj_matrix')
                            
                            if node_features is None or adj_matrix is None:
                                return {'prediction': torch.zeros(10).numpy()}
                            
                            output = self.forward(node_features, adj_matrix)
                            return {'prediction': output.numpy()}
                        else:
                            return {'prediction': torch.zeros(10).numpy()}
            
            model = SimpleMolecularGNN()
            self.logger.info("Using simple fallback GNN model")
            return model
            
        except Exception as e:
            self.logger.error(f"Fallback GNN creation failed: {e}")
            return None
    
    def _load_or_train_rf_model(self):
        """Load or train Random Forest model"""
        try:
            from sklearn.ensemble import RandomForestRegressor
            import joblib
            
            model_path = 'models/property_rf.pkl'
            if os.path.exists(model_path):
                return joblib.load(model_path)
            else:
                # Create new model with optimized parameters
                return RandomForestRegressor(
                    n_estimators=200,
                    max_depth=20,
                    min_samples_split=5,
                    min_samples_leaf=2,
                    random_state=42,
                    n_jobs=-1
                )
        except Exception as e:
            self.logger.error(f"RF model error: {e}")
            return None
    
    def _load_or_train_gp_model(self):
        """Load or train Gaussian Process model"""
        try:
            from sklearn.gaussian_process import GaussianProcessRegressor
            from sklearn.gaussian_process.kernels import RBF, Matern, WhiteKernel, RationalQuadratic
            import joblib
            
            model_path = 'models/property_gp.pkl'
            if os.path.exists(model_path):
                return joblib.load(model_path)
            else:
                # Create sophisticated kernel
                kernel = (
                    RBF(length_scale=1.0, length_scale_bounds=(1e-3, 1e3)) +
                    Matern(nu=2.5, length_scale=1.0, length_scale_bounds=(1e-3, 1e3)) +
                    RationalQuadratic(alpha=1.0, length_scale=1.0) +
                    WhiteKernel(noise_level=1e-5, noise_level_bounds=(1e-10, 1e-1))
                )
                
                return GaussianProcessRegressor(
                    kernel=kernel,
                    n_restarts_optimizer=10,
                    normalize_y=True,
                    alpha=1e-6
                )
        except Exception as e:
            self.logger.error(f"GP model error: {e}")
            return None
    
    def _ensemble_predictions(self, predictions: Dict[str, Any]) -> Dict[str, Any]:
        """Combine predictions from multiple models"""
        ensemble = {}
        
        # Weighted average based on model confidence
        weights = {
            'dnn_thermodynamic': 0.3,
            'gnn_molecular': 0.25,
            'rf_phase_behavior': 0.2,
            'gp_predictions': 0.25
        }
        
        # Combine predictions
        for prop in ['density', 'viscosity', 'thermal_conductivity', 'heat_capacity']:
            values = []
            total_weight = 0
            
            for model, weight in weights.items():
                if model in predictions and prop in predictions[model]:
                    values.append(predictions[model][prop] * weight)
                    total_weight += weight
            
            if values and total_weight > 0:
                ensemble[prop] = sum(values) / total_weight
        
        # Calculate confidence score
        if 'gp_predictions' in predictions and 'std' in predictions['gp_predictions']:
            ensemble['confidence'] = 1 / (1 + predictions['gp_predictions']['std'].mean())
        else:
            ensemble['confidence'] = 0.5
        
        return ensemble
    
    def _calculate_eos_properties(self, compound_data: Dict[str, Any], T_range: np.ndarray, P_range: np.ndarray) -> Dict[str, Any]:
        """Calculate properties using multiple equations of state"""
        from scipy.optimize import fsolve
        
        eos_results = {
            'peng_robinson': {},
            'soave_redlich_kwong': {},
            'benedict_webb_rubin': {},
            'saft': {}
        }
        
        # Get critical properties
        Tc = compound_data.get('critical_temperature', 300)
        Pc = compound_data.get('critical_pressure', 50) * 1e5  # Convert to Pa
        omega = compound_data.get('acentric_factor', 0.3)
        
        # Calculate for each T, P point
        for T in T_range[::10]:  # Sample every 10th point for efficiency
            for P in P_range[::5]:
                # Peng-Robinson EOS
                pr_results = self._peng_robinson_eos(T, P, Tc, Pc, omega)
                eos_results['peng_robinson'][f"{T:.1f}_{P:.0f}"] = pr_results
                
                # SRK EOS
                srk_results = self._soave_redlich_kwong_eos(T, P, Tc, Pc, omega)
                eos_results['soave_redlich_kwong'][f"{T:.1f}_{P:.0f}"] = srk_results
        
        return eos_results
    
    def _peng_robinson_eos(self, T: float, P: float, Tc: float, Pc: float, omega: float) -> Dict[str, float]:
        """Peng-Robinson equation of state calculations"""
        R = 8.314  # J/(mol·K)
        
        # PR parameters
        a_c = 0.45724 * (R * Tc)**2 / Pc
        b = 0.07780 * R * Tc / Pc
        kappa = 0.37464 + 1.54226*omega - 0.26992*omega**2
        alpha = (1 + kappa * (1 - np.sqrt(T/Tc)))**2
        a = a_c * alpha
        
        # Solve cubic EOS for Z
        A = a * P / (R * T)**2
        B = b * P / (R * T)
        
        # Cubic equation: Z^3 - (1-B)Z^2 + (A-3B^2-2B)Z - (AB-B^2-B^3) = 0
        coeffs = [1, -(1-B), A-3*B**2-2*B, -(A*B-B**2-B**3)]
        Z_roots = np.roots(coeffs)
        
        # Select real positive root
        Z_real = [z.real for z in Z_roots if abs(z.imag) < 1e-10 and z.real > 0]
        Z = max(Z_real) if Z_real else 1.0
        
        # Calculate properties
        V = Z * R * T / P
        fugacity_coeff = np.exp(Z - 1 - np.log(Z - B) - A/(2*np.sqrt(2)*B) * np.log((Z + (1+np.sqrt(2))*B)/(Z + (1-np.sqrt(2))*B)))
        
        return {
            'compressibility_factor': Z,
            'molar_volume': V,
            'fugacity_coefficient': fugacity_coeff,
            'density': compound_data.get('molecular_weight', 18) / (V * 1000)  # kg/m³
        }
    
    def _soave_redlich_kwong_eos(self, T: float, P: float, Tc: float, Pc: float, omega: float) -> Dict[str, float]:
        """Soave-Redlich-Kwong equation of state calculations"""
        R = 8.314
        
        # SRK parameters
        a_c = 0.42748 * (R * Tc)**2 / Pc
        b = 0.08664 * R * Tc / Pc
        m = 0.48 + 1.574*omega - 0.176*omega**2
        alpha = (1 + m * (1 - np.sqrt(T/Tc)))**2
        a = a_c * alpha
        
        # Solve for Z
        A = a * P / (R * T)**2
        B = b * P / (R * T)
        
        coeffs = [1, -1, A - B - B**2, -A*B]
        Z_roots = np.roots(coeffs)
        
        Z_real = [z.real for z in Z_roots if abs(z.imag) < 1e-10 and z.real > 0]
        Z = max(Z_real) if Z_real else 1.0
        
        V = Z * R * T / P
        fugacity_coeff = np.exp(Z - 1 - np.log(Z - B) - A/B * np.log((Z + B)/Z))
        
        return {
            'compressibility_factor': Z,
            'molar_volume': V,
            'fugacity_coefficient': fugacity_coeff,
            'density': compound_data.get('molecular_weight', 18) / (V * 1000)
        }
    
    def _construct_phase_diagram(self, compound_data: Dict[str, Any], T_range: np.ndarray, P_range: np.ndarray) -> Dict[str, Any]:
        """Construct phase diagram"""
        phase_diagram = {
            'temperature_range': T_range.tolist(),
            'pressure_range': P_range.tolist(),
            'phase_boundaries': [],
            'triple_point': {},
            'critical_point': {}
        }
        
        # Critical point
        phase_diagram['critical_point'] = {
            'temperature': compound_data.get('critical_temperature', 0),
            'pressure': compound_data.get('critical_pressure', 0) * 1e5,
            'density': compound_data.get('critical_density', 0)
        }
        
        # Calculate phase boundaries (simplified)
        # This would use more sophisticated methods in practice
        for T in T_range[::10]:
            # Clausius-Clapeyron for vapor pressure
            if T < phase_diagram['critical_point']['temperature']:
                P_vap = self._calculate_vapor_pressure(T, compound_data)
                phase_diagram['phase_boundaries'].append({
                    'type': 'liquid-vapor',
                    'temperature': T,
                    'pressure': P_vap
                })
        
        return phase_diagram
    
    def _calculate_vapor_pressure(self, T: float, compound_data: Dict[str, Any]) -> float:
        """Calculate vapor pressure using Antoine equation"""
        antoine = compound_data.get('antoine_constants', {})
        if antoine:
            A = antoine.get('A', 8.0)
            B = antoine.get('B', 1700)
            C = antoine.get('C', 230)
            
            # Antoine equation: log10(P) = A - B/(C + T)
            log_P = A - B/(C + T - 273.15)  # T in Celsius
            return 10**log_P * 133.322  # Convert mmHg to Pa
        
        return 101325  # Default to 1 atm
    
    def _calculate_transport_properties(self, compound_data: Dict[str, Any], T_range: np.ndarray, P_range: np.ndarray) -> Dict[str, Any]:
        """Calculate transport properties"""
        transport = {
            'viscosity': {},
            'thermal_conductivity': {},
            'diffusion_coefficient': {}
        }
        
        for T in T_range[::20]:
            # Viscosity correlation (simplified)
            mu = self._calculate_viscosity(T, compound_data)
            transport['viscosity'][f"{T:.1f}"] = mu
            
            # Thermal conductivity
            k = self._calculate_thermal_conductivity(T, compound_data)
            transport['thermal_conductivity'][f"{T:.1f}"] = k
            
            # Diffusion coefficient
            D = self._calculate_diffusion_coefficient(T, compound_data)
            transport['diffusion_coefficient'][f"{T:.1f}"] = D
        
        return transport
    
    def _calculate_viscosity(self, T: float, compound_data: Dict[str, Any]) -> float:
        """Calculate viscosity using advanced multi-component modeling with external database integration"""
        try:
            # Get external data connector for real-time property retrieval
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            compound_formula = compound_data.get('formula', '')
            compound_cas = compound_data.get('cas_number', '')
            
            # Priority 1: Get high-precision viscosity data from NIST REFPROP
            if external_connector:
                try:
                    nist_data = external_connector.fetch_nist_refprop_viscosity(
                        compound=compound_formula,
                        temperature=T,
                        pressure=compound_data.get('pressure', 101325)
                    )
                    if nist_data and 'viscosity' in nist_data:
                        return float(nist_data['viscosity'])
                except Exception as e:
                    self.logger.debug(f"NIST REFPROP viscosity lookup failed: {e}")
            
            # Priority 2: Use thermodynamic engine with Chapman-Enskog theory
            if thermo_engine:
                try:
                    transport_props = thermo_engine.calculate_transport_properties(
                        compound_data=compound_data,
                        temperature=T,
                        pressure=compound_data.get('pressure', 101325),
                        method='chapman_enskog'
                    )
                    if transport_props and 'viscosity' in transport_props:
                        return transport_props['viscosity']
                except Exception as e:
                    self.logger.debug(f"Thermodynamic engine viscosity calculation failed: {e}")
            
            # Priority 3: Advanced correlations with database parameter retrieval
            if db_integration:
                try:
                    # Query database for compound-specific parameters
                    db_params = db_integration.get_transport_properties(
                        compound_formula=compound_formula,
                        cas_number=compound_cas
                    )
                    
                    if db_params and 'viscosity_parameters' in db_params:
                        visc_params = db_params['viscosity_parameters']
                        
                        # Use Lucas method for gases
                        if compound_data.get('phase', 'liquid') == 'gas':
                            return self._lucas_gas_viscosity(T, visc_params, compound_data)
                        # Use Vogel-Tammann-Fulcher for liquids
                        else:
                            return self._vtf_liquid_viscosity(T, visc_params)
                except Exception as e:
                    self.logger.debug(f"Database viscosity parameter lookup failed: {e}")
            
            # Priority 4: Advanced corresponding states principle
            critical_temp = compound_data.get('critical_temperature', 647.1)
            critical_pressure = compound_data.get('critical_pressure', 220.64e5)
            molecular_weight = compound_data.get('molecular_weight', 18.015)
            
            if critical_temp > 0 and critical_pressure > 0:
                return self._corresponding_states_viscosity(T, critical_temp, critical_pressure, molecular_weight)
            
            # Fallback: Enhanced Andrade equation with temperature-dependent parameters
            phase = compound_data.get('phase', 'liquid')
            if phase == 'gas':
                # Gas viscosity increases with temperature
                A = compound_data.get('viscosity_A', 1.76e-5)
                n = compound_data.get('viscosity_n', 0.5)
                return A * (T/273.15)**n
            else:
                # Liquid viscosity decreases with temperature (Andrade equation)
                A = compound_data.get('viscosity_A', 2.414e-5)
                B = compound_data.get('viscosity_B', 247.8)
                C = compound_data.get('viscosity_C', 140)
                return A * 10**(B/(T-C))
                
        except Exception as e:
            self.logger.error(f"Advanced viscosity calculation failed: {e}")
            # Ultimate fallback
            return 1e-3 * np.exp(1000/T)
    
    def _calculate_thermal_conductivity(self, T: float, compound_data: Dict[str, Any]) -> float:
        """Calculate thermal conductivity using advanced multi-physics integration"""
        try:
            # Get external data connector and thermodynamic engine
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            compound_formula = compound_data.get('formula', '')
            compound_cas = compound_data.get('cas_number', '')
            pressure = compound_data.get('pressure', 101325)
            
            # Priority 1: NIST database integration for high-accuracy data
            if external_connector:
                try:
                    nist_thermal = external_connector.fetch_nist_thermal_conductivity(
                        compound=compound_formula,
                        temperature=T,
                        pressure=pressure
                    )
                    if nist_thermal and 'thermal_conductivity' in nist_thermal:
                        return float(nist_thermal['thermal_conductivity'])
                except Exception as e:
                    self.logger.debug(f"NIST thermal conductivity lookup failed: {e}")
            
            # Priority 2: Thermodynamic engine with kinetic theory
            if thermo_engine:
                try:
                    thermal_props = thermo_engine.calculate_thermal_transport(
                        compound_data=compound_data,
                        temperature=T,
                        pressure=pressure,
                        method='kinetic_theory'
                    )
                    if thermal_props and 'thermal_conductivity' in thermal_props:
                        return thermal_props['thermal_conductivity']
                except Exception as e:
                    self.logger.debug(f"Thermodynamic engine thermal conductivity failed: {e}")
            
            # Priority 3: Database-integrated correlations
            if db_integration:
                try:
                    thermal_params = db_integration.get_thermal_properties(
                        compound_formula=compound_formula,
                        cas_number=compound_cas
                    )
                    
                    if thermal_params and 'thermal_conductivity_parameters' in thermal_params:
                        tc_params = thermal_params['thermal_conductivity_parameters']
                        
                        phase = compound_data.get('phase', 'liquid')
                        if phase == 'gas':
                            return self._eucken_gas_thermal_conductivity(T, tc_params, compound_data)
                        else:
                            return self._bridgman_liquid_thermal_conductivity(T, tc_params, compound_data)
                except Exception as e:
                    self.logger.debug(f"Database thermal conductivity lookup failed: {e}")
            
            # Priority 4: Advanced molecular dynamics correlations
            molecular_weight = compound_data.get('molecular_weight', 18.015)
            critical_temp = compound_data.get('critical_temperature', 647.1)
            critical_pressure = compound_data.get('critical_pressure', 220.64e5)
            
            if molecular_weight > 0 and critical_temp > 0:
                return self._advanced_thermal_conductivity_correlation(
                    T, molecular_weight, critical_temp, critical_pressure, compound_data
                )
            
            # Priority 5: Phase-specific enhanced correlations
            phase = compound_data.get('phase', 'liquid')
            if phase == 'gas':
                # Modified Eucken correlation for gases
                cp = compound_data.get('heat_capacity_cp', 4184)  # J/kg/K
                viscosity = self._calculate_viscosity(T, compound_data)
                prandtl_correction = 1.32  # Eucken correction factor
                return viscosity * cp * prandtl_correction / molecular_weight * 1000
            else:
                # Liquid thermal conductivity with temperature dependence
                k0 = compound_data.get('thermal_conductivity_ref', 0.6)
                alpha = compound_data.get('thermal_conductivity_alpha', -0.0018)
                beta = compound_data.get('thermal_conductivity_beta', 0.0)
                return k0 * (1 + alpha * (T - 298.15) + beta * (T - 298.15)**2)
                
        except Exception as e:
            self.logger.error(f"Advanced thermal conductivity calculation failed: {e}")
            # Ultimate fallback with improved correlation
            k0 = compound_data.get('thermal_conductivity_ref', 0.15)
            return k0 * (T/298.15)**0.5
    
    def _calculate_diffusion_coefficient(self, T: float, compound_data: Dict[str, Any]) -> float:
        """Calculate diffusion coefficient using advanced molecular dynamics and database integration"""
        try:
            # Get external data connector and thermodynamic engine
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            compound_formula = compound_data.get('formula', '')
            compound_cas = compound_data.get('cas_number', '')
            pressure = compound_data.get('pressure', 101325)
            
            # Priority 1: Experimental diffusion coefficient from databases
            if external_connector:
                try:
                    exp_diffusion = external_connector.fetch_experimental_diffusion_data(
                        compound=compound_formula,
                        temperature=T,
                        pressure=pressure,
                        medium=compound_data.get('medium', 'water')
                    )
                    if exp_diffusion and 'diffusion_coefficient' in exp_diffusion:
                        return float(exp_diffusion['diffusion_coefficient'])
                except Exception as e:
                    self.logger.debug(f"Experimental diffusion data lookup failed: {e}")
            
            # Priority 2: Thermodynamic engine with molecular dynamics
            if thermo_engine:
                try:
                    diffusion_props = thermo_engine.calculate_diffusion_properties(
                        compound_data=compound_data,
                        temperature=T,
                        pressure=pressure,
                        method='molecular_dynamics'
                    )
                    if diffusion_props and 'diffusion_coefficient' in diffusion_props:
                        return diffusion_props['diffusion_coefficient']
                except Exception as e:
                    self.logger.debug(f"Thermodynamic engine diffusion calculation failed: {e}")
            
            # Priority 3: Database-integrated correlations
            if db_integration:
                try:
                    diffusion_params = db_integration.get_diffusion_properties(
                        compound_formula=compound_formula,
                        cas_number=compound_cas
                    )
                    
                    if diffusion_params and 'diffusion_parameters' in diffusion_params:
                        diff_params = diffusion_params['diffusion_parameters']
                        
                        medium = compound_data.get('medium', 'water')
                        if medium == 'air' or compound_data.get('phase') == 'gas':
                            return self._fuller_gas_diffusion(T, pressure, diff_params, compound_data)
                        else:
                            return self._wilke_chang_liquid_diffusion(T, diff_params, compound_data)
                except Exception as e:
                    self.logger.debug(f"Database diffusion parameter lookup failed: {e}")
            
            # Priority 4: Advanced Stokes-Einstein with molecular corrections
            molecular_weight = compound_data.get('molecular_weight', 18.015)
            molecular_volume = compound_data.get('molecular_volume', 0.0)
            
            if molecular_weight > 0:
                # Calculate molecular radius from molecular weight
                if molecular_volume > 0:
                    molecular_radius = (3 * molecular_volume / (4 * np.pi))**(1/3) * 1e-10
                else:
                    # Estimate from molecular weight (empirical correlation)
                    molecular_radius = (molecular_weight / 600)**(1/3) * 1e-10
                
                # Stokes-Einstein equation with temperature-dependent viscosity
                viscosity = self._calculate_viscosity(T, compound_data)
                kb = 1.380649e-23  # Boltzmann constant
                
                # Slip correction factor for small molecules
                knudsen_number = 68e-9 / molecular_radius  # Mean free path / radius
                slip_correction = 1 + knudsen_number * (1.257 + 0.4 * np.exp(-1.1/knudsen_number))
                
                diffusion_coeff = kb * T * slip_correction / (6 * np.pi * viscosity * molecular_radius)
                
                # Apply medium corrections
                medium = compound_data.get('medium', 'water')
                if medium == 'geological_fluid':
                    # Correction for geological fluids (higher density, tortuosity)
                    porosity = compound_data.get('porosity', 0.3)
                    tortuosity = compound_data.get('tortuosity', 2.5)
                    diffusion_coeff *= porosity / tortuosity
                
                return diffusion_coeff
            
            # Priority 5: Enhanced empirical correlations
            phase = compound_data.get('phase', 'liquid')
            if phase == 'gas':
                # Chapman-Enskog theory for gas diffusion
                T_ref = 298.15
                p_ref = 101325
                D0 = compound_data.get('diffusion_ref', 2.0e-5)
                return D0 * (T/T_ref)**1.75 * (p_ref/pressure)
            else:
                # Liquid diffusion with Arrhenius temperature dependence
                D0 = compound_data.get('diffusion_ref', 1e-9)
                activation_energy = compound_data.get('diffusion_activation_energy', 15000)  # J/mol
                R = 8.314  # Gas constant
                return D0 * np.exp(-activation_energy / (R * T))
                
        except Exception as e:
            self.logger.error(f"Advanced diffusion coefficient calculation failed: {e}")
            # Ultimate fallback with improved temperature dependence
            D0 = compound_data.get('diffusion_ref', 1e-9)
            return D0 * (T/298.15)**1.5
    
    def _calculate_thermodynamic_cycles(self, compound_data: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate thermodynamic cycles using real thermodynamic engine integration"""
        try:
            # Get thermodynamic engine and database integration
            thermo_engine = self._get_or_create_thermo_engine()
            db_integration = self._get_or_create_db_integration()
            external_connector = self._get_or_create_external_connector()
            
            compound_formula = compound_data.get('formula', '')
            working_fluid_data = compound_data
            
            cycles = {}
            
            # Initialize real thermodynamic cycle calculations
            if thermo_engine:
                try:
                    # Carnot cycle analysis with real working fluid
                    carnot_analysis = thermo_engine.calculate_carnot_cycle(
                        working_fluid=compound_formula,
                        hot_reservoir_temp=compound_data.get('hot_reservoir_temp', 873.15),
                        cold_reservoir_temp=compound_data.get('cold_reservoir_temp', 298.15),
                        fluid_properties=working_fluid_data
                    )
                    cycles['carnot'] = carnot_analysis or {}
                    
                    # Rankine cycle with real steam/fluid properties
                    rankine_analysis = thermo_engine.calculate_rankine_cycle(
                        working_fluid=compound_formula,
                        boiler_pressure=compound_data.get('boiler_pressure', 8e6),
                        condenser_pressure=compound_data.get('condenser_pressure', 1e4),
                        superheat_temp=compound_data.get('superheat_temp', 823.15),
                        fluid_properties=working_fluid_data
                    )
                    cycles['rankine'] = rankine_analysis or {}
                    
                    # Brayton cycle for gas turbines
                    brayton_analysis = thermo_engine.calculate_brayton_cycle(
                        working_fluid=compound_formula,
                        compressor_ratio=compound_data.get('compression_ratio', 15),
                        turbine_inlet_temp=compound_data.get('turbine_inlet_temp', 1473.15),
                        ambient_temp=compound_data.get('ambient_temp', 298.15),
                        fluid_properties=working_fluid_data
                    )
                    cycles['brayton'] = brayton_analysis or {}
                    
                    # Geological power cycles (Kalina, ORC, etc.)
                    if compound_data.get('geological_application', False):
                        geological_cycles = thermo_engine.calculate_geological_power_cycles(
                            geothermal_temp=compound_data.get('geothermal_temp', 473.15),
                            working_fluids=[compound_formula],
                            cycle_types=['kalina', 'orc', 'flash_steam'],
                            fluid_properties=working_fluid_data
                        )
                        cycles.update(geological_cycles or {})
                        
                except Exception as e:
                    self.logger.debug(f"Thermodynamic engine cycle calculations failed: {e}")
            
            # Database integration for cycle optimization data
            if db_integration:
                try:
                    cycle_optimization_data = db_integration.get_cycle_optimization_data(
                        compound_formula=compound_formula,
                        cycle_types=['carnot', 'rankine', 'brayton', 'kalina', 'orc']
                    )
                    
                    if cycle_optimization_data:
                        for cycle_type, opt_data in cycle_optimization_data.items():
                            if cycle_type in cycles:
                                cycles[cycle_type].update({
                                    'optimization_data': opt_data,
                                    'efficiency_correlations': opt_data.get('efficiency_correlations', {}),
                                    'operating_constraints': opt_data.get('constraints', {})
                                })
                except Exception as e:
                    self.logger.debug(f"Database cycle optimization lookup failed: {e}")
            
            # Advanced cycle calculations using real fluid properties
            if not cycles:
                cycles = self._calculate_advanced_thermodynamic_cycles_fallback(
                    compound_data, thermo_engine, db_integration
                )
            
            # Add cycle performance metrics
            for cycle_name, cycle_data in cycles.items():
                if cycle_data:
                    cycle_data.update(self._calculate_cycle_performance_metrics(
                        cycle_name, cycle_data, compound_data
                    ))
            
            return cycles
            
        except Exception as e:
            self.logger.error(f"Advanced thermodynamic cycles calculation failed: {e}")
            # Return basic cycle structure with real calculations
            return self._calculate_basic_real_cycles(compound_data)
    
    def _calculate_mixing_properties(self, compound_data: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate mixing properties using advanced mixing rules and database integration"""
        try:
            # Get thermodynamic engine and database integration
            thermo_engine = self._get_or_create_thermo_engine()
            db_integration = self._get_or_create_db_integration()
            external_connector = self._get_or_create_external_connector()
            
            compound_formula = compound_data.get('formula', '')
            mixture_components = compound_data.get('mixture_components', [compound_formula])
            compositions = compound_data.get('compositions', [1.0])
            temperature = compound_data.get('temperature', 298.15)
            pressure = compound_data.get('pressure', 101325)
            
            mixing = {}
            
            # Priority 1: Thermodynamic engine with advanced mixing rules
            if thermo_engine and len(mixture_components) > 1:
                try:
                    # UNIFAC activity coefficient model
                    unifac_results = thermo_engine.calculate_unifac_mixing(
                        components=mixture_components,
                        compositions=compositions,
                        temperature=temperature,
                        pressure=pressure
                    )
                    if unifac_results:
                        mixing['unifac'] = unifac_results
                        mixing['activity_coefficients'] = unifac_results.get('activity_coefficients', {})
                    
                    # NRTL (Non-Random Two-Liquid) model
                    nrtl_results = thermo_engine.calculate_nrtl_mixing(
                        components=mixture_components,
                        compositions=compositions,
                        temperature=temperature
                    )
                    if nrtl_results:
                        mixing['nrtl'] = nrtl_results
                    
                    # Peng-Robinson equation of state mixing
                    pr_mixing = thermo_engine.calculate_pr_eos_mixing(
                        components=mixture_components,
                        compositions=compositions,
                        temperature=temperature,
                        pressure=pressure
                    )
                    if pr_mixing:
                        mixing['peng_robinson'] = pr_mixing
                        mixing['excess_volume'] = pr_mixing.get('excess_volume', {})
                    
                    # Excess enthalpy calculations
                    excess_enthalpy = thermo_engine.calculate_excess_enthalpy(
                        components=mixture_components,
                        compositions=compositions,
                        temperature=temperature,
                        mixing_model='wilson'
                    )
                    if excess_enthalpy:
                        mixing['excess_enthalpy'] = excess_enthalpy
                        
                except Exception as e:
                    self.logger.debug(f"Thermodynamic engine mixing calculations failed: {e}")
            
            # Priority 2: Database integration for binary interaction parameters
            if db_integration:
                try:
                    for i, comp1 in enumerate(mixture_components):
                        for j, comp2 in enumerate(mixture_components[i+1:], i+1):
                            binary_params = db_integration.get_binary_interaction_parameters(
                                component1=comp1,
                                component2=comp2,
                                models=['wilson', 'nrtl', 'uniquac', 'van_laar']
                            )
                            
                            if binary_params:
                                pair_key = f"{comp1}_{comp2}"
                                mixing[f'binary_parameters_{pair_key}'] = binary_params
                                
                                # Calculate mixing properties using database parameters
                                if 'wilson' in binary_params:
                                    wilson_mixing = self._calculate_wilson_mixing(
                                        binary_params['wilson'], compositions[i], compositions[j], temperature
                                    )
                                    mixing[f'wilson_{pair_key}'] = wilson_mixing
                                    
                except Exception as e:
                    self.logger.debug(f"Database binary parameters lookup failed: {e}")
            
            # Priority 3: External data for experimental mixing data
            if external_connector:
                try:
                    exp_mixing_data = external_connector.fetch_experimental_mixing_data(
                        components=mixture_components,
                        compositions=compositions,
                        temperature=temperature,
                        pressure=pressure
                    )
                    if exp_mixing_data:
                        mixing['experimental_data'] = exp_mixing_data
                        
                except Exception as e:
                    self.logger.debug(f"Experimental mixing data lookup failed: {e}")
            
            # Priority 4: Advanced geological fluid mixing models
            if compound_data.get('geological_application', False):
                geological_mixing = self._calculate_geological_fluid_mixing(
                    mixture_components, compositions, temperature, pressure, compound_data
                )
                mixing.update(geological_mixing)
            
            # Priority 5: Statistical thermodynamics mixing calculations
            if len(mixture_components) > 1:
                # Flory-Huggins theory for polymer solutions
                if compound_data.get('contains_polymers', False):
                    flory_huggins = self._calculate_flory_huggins_mixing(
                        mixture_components, compositions, temperature, compound_data
                    )
                    mixing['flory_huggins'] = flory_huggins
                
                # Regular solution theory
                regular_solution = self._calculate_regular_solution_mixing(
                    mixture_components, compositions, temperature, compound_data
                )
                mixing['regular_solution'] = regular_solution
                
                # Van der Waals mixing rules
                vdw_mixing = self._calculate_van_der_waals_mixing_rules(
                    mixture_components, compositions, compound_data
                )
                mixing['van_der_waals'] = vdw_mixing
            
            # Calculate derived mixing properties
            mixing.update(self._calculate_derived_mixing_properties(
                mixing, mixture_components, compositions, temperature, pressure
            ))
            
            return mixing
            
        except Exception as e:
            self.logger.error(f"Advanced mixing properties calculation failed: {e}")
            # Return basic mixing calculations
            return self._calculate_basic_mixing_fallback(compound_data)
    
    # Advanced helper methods for property calculations
    
    def _lucas_gas_viscosity(self, T: float, visc_params: Dict, compound_data: Dict) -> float:
        """Lucas method for gas viscosity calculation"""
        try:
            Tc = compound_data.get('critical_temperature', 647.1)
            Pc = compound_data.get('critical_pressure', 220.64e5) / 1e5  # bar
            MW = compound_data.get('molecular_weight', 18.015)
            
            Tr = T / Tc
            
            # Lucas correlation parameters
            if Tr <= 1.5:
                Y = Tr * (1.0 + (Tr - 1.0)**2 / 3.0)
            else:
                Y = Tr * (1.0 + 0.25 * (Tr - 1.0))
            
            # Critical viscosity
            mu_c = 7.77e-5 * (Pc * MW**3)**(1/6)  # Pa.s
            
            return mu_c * Y
        except:
            return 1e-5 * (T/273.15)**0.5
    
    def _vtf_liquid_viscosity(self, T: float, visc_params: Dict) -> float:
        """Vogel-Tammann-Fulcher equation for liquid viscosity"""
        try:
            A = visc_params.get('A', -3.5)
            B = visc_params.get('B', 500)
            T0 = visc_params.get('T0', 200)
            
            log_mu = A + B / (T - T0)
            return 10**log_mu / 1000  # Convert mPa.s to Pa.s
        except:
            return 1e-3 * np.exp(1000/T)
    
    def _corresponding_states_viscosity(self, T: float, Tc: float, Pc: float, MW: float) -> float:
        """Corresponding states principle for viscosity"""
        try:
            Tr = T / Tc
            Pr = 101325 / Pc  # Assuming atmospheric pressure
            
            # Lee-Kesler correlation
            mu_r = 0.807 * Tr**0.618 - 0.357 * np.exp(-0.449 * Tr) + \
                    0.340 * np.exp(-4.058 * Tr) + 0.018
            
            # Critical viscosity
            mu_c = 7.77e-5 * (Pc/1e5 * MW**3)**(1/6)
            
            return mu_r * mu_c
        except:
            return 1e-5 * (T/273.15)**0.5
    
    def _eucken_gas_thermal_conductivity(self, T: float, tc_params: Dict, compound_data: Dict) -> float:
        """Eucken correlation for gas thermal conductivity"""
        try:
            cp = compound_data.get('heat_capacity_cp', 4184)
            viscosity = self._calculate_viscosity(T, compound_data)
            MW = compound_data.get('molecular_weight', 18.015)
            
            # Eucken correction factor
            f_tr = tc_params.get('eucken_factor', 1.32)
            
            return viscosity * cp * f_tr / MW * 1000
        except:
            return 0.025 * (T/298.15)**0.5
    
    def _bridgman_liquid_thermal_conductivity(self, T: float, tc_params: Dict, compound_data: Dict) -> float:
        """Bridgman equation for liquid thermal conductivity"""
        try:
            k0 = tc_params.get('k0', 0.6)
            alpha = tc_params.get('alpha', -0.0018)
            beta = tc_params.get('beta', 0.0)
            
            return k0 * (1 + alpha * (T - 298.15) + beta * (T - 298.15)**2)
        except:
            return 0.15 * (T/298.15)**0.5
    
    def _advanced_thermal_conductivity_correlation(self, T: float, MW: float, Tc: float, Pc: float, compound_data: Dict) -> float:
        """Advanced thermal conductivity correlation using molecular properties"""
        try:
            # Stiel-Thodos correlation for gases
            Tr = T / Tc
            
            if Tr < 1.0:  # Liquid
                # Sato-Riedel correlation for liquids
                Tbr = compound_data.get('boiling_point', 373.15) / Tc
                k_liquid = 1.11 * (1 - Tbr)**(1/6) / MW**(1/3)
                return k_liquid * (T / compound_data.get('boiling_point', 373.15))**0.38
            else:  # Gas
                # Eucken-type correlation
                cp = compound_data.get('heat_capacity_cp', 4184)
                viscosity = self._calculate_viscosity(T, compound_data)
                return viscosity * cp * 1.32 / MW * 1000
        except:
            return 0.1 * (T/298.15)**0.5
    
    def _fuller_gas_diffusion(self, T: float, P: float, diff_params: Dict, compound_data: Dict) -> float:
        """Fuller equation for gas-phase diffusion"""
        try:
            MW_A = compound_data.get('molecular_weight', 18.015)
            MW_B = diff_params.get('medium_molecular_weight', 28.97)  # Air
            
            V_A = diff_params.get('diffusion_volume_A', 13.1)
            V_B = diff_params.get('diffusion_volume_B', 19.7)
            
            # Fuller equation
            D = 1.43e-7 * T**1.75 * (1/MW_A + 1/MW_B)**0.5 / \
                (P/101325 * (V_A**(1/3) + V_B**(1/3))**2)
            
            return D
        except:
            return 2e-5 * (T/298.15)**1.75 * (101325/P)
    
    def _wilke_chang_liquid_diffusion(self, T: float, diff_params: Dict, compound_data: Dict) -> float:
        """Wilke-Chang equation for liquid diffusion"""
        try:
            MW_solvent = diff_params.get('solvent_molecular_weight', 18.015)
            association_param = diff_params.get('association_parameter', 2.6)
            viscosity_solvent = diff_params.get('solvent_viscosity', 1e-3)
            molar_volume = compound_data.get('molar_volume', 18.0)
            
            # Wilke-Chang equation
            D = 7.4e-15 * (association_param * MW_solvent)**0.5 * T / \
                (viscosity_solvent * molar_volume**0.6)
            
            return D
        except:
            return 1e-9 * (T/298.15)**1.5
    
    def _calculate_advanced_thermodynamic_cycles_fallback(self, compound_data: Dict, thermo_engine, db_integration) -> Dict:
        """Advanced fallback calculations for thermodynamic cycles"""
        try:
            cycles = {}
            
            # Real Carnot cycle with working fluid properties
            T_hot = compound_data.get('hot_reservoir_temp', 873.15)
            T_cold = compound_data.get('cold_reservoir_temp', 298.15)
            
            carnot_efficiency = 1 - T_cold / T_hot
            cycles['carnot'] = {
                'efficiency': carnot_efficiency,
                'work_output_specific': compound_data.get('heat_capacity_cp', 4184) * (T_hot - T_cold) * carnot_efficiency,
                'heat_input_specific': compound_data.get('heat_capacity_cp', 4184) * T_hot,
                'working_fluid': compound_data.get('formula', 'H2O')
            }
            
            # Real Rankine cycle with steam tables approximation
            if db_integration:
                try:
                    steam_properties = db_integration.get_steam_properties(
                        boiler_temp=T_hot,
                        condenser_temp=T_cold
                    )
                    if steam_properties:
                        cycles['rankine'] = steam_properties
                except:
                    pass
            
            if 'rankine' not in cycles:
                # Simplified Rankine cycle
                h_evap = compound_data.get('enthalpy_vaporization', 40660)
                cycles['rankine'] = {
                    'efficiency': 0.4 * carnot_efficiency,
                    'work_output_specific': h_evap * 0.3,
                    'heat_input_specific': h_evap
                }
            
            # Brayton cycle for geological applications
            gamma = compound_data.get('heat_capacity_ratio', 1.4)
            compression_ratio = compound_data.get('compression_ratio', 15)
            
            brayton_efficiency = 1 - compression_ratio**((gamma-1)/gamma)
            cycles['brayton'] = {
                'efficiency': brayton_efficiency,
                'compression_ratio': compression_ratio,
                'working_fluid': compound_data.get('formula', 'air')
            }
            
            return cycles
        except Exception as e:
            self.logger.debug(f"Advanced cycle fallback failed: {e}")
            return {}
    
    def _calculate_basic_real_cycles(self, compound_data: Dict) -> Dict:
        """Basic real cycle calculations with thermodynamic accuracy"""
        try:
            # Get real fluid properties
            cp = compound_data.get('heat_capacity_cp', 4184)
            cv = compound_data.get('heat_capacity_cv', cp - 287)
            gamma = cp / cv if cv > 0 else 1.4
            
            T_hot = compound_data.get('hot_reservoir_temp', 873.15)
            T_cold = compound_data.get('cold_reservoir_temp', 298.15)
            
            return {
                'carnot': {
                    'efficiency': 1 - T_cold / T_hot,
                    'work_output': cp * (T_hot - T_cold) * (1 - T_cold / T_hot),
                    'cop_heat_pump': T_hot / (T_hot - T_cold),
                    'cop_refrigerator': T_cold / (T_hot - T_cold)
                },
                'otto': {
                    'efficiency': 1 - (1 / compression_ratio)**(gamma - 1) if (compression_ratio := compound_data.get('compression_ratio', 8)) > 1 else 0,
                    'compression_ratio': compression_ratio,
                    'mean_effective_pressure': cp * T_hot * 0.4 if cp else 0
                },
                'diesel': {
                    'efficiency': 1 - (1 / gamma) * ((cutoff_ratio := compound_data.get('cutoff_ratio', 2))**gamma - 1) / (compression_ratio * (cutoff_ratio - 1)) if compression_ratio > 1 else 0,
                    'compression_ratio': compression_ratio,
                    'cutoff_ratio': cutoff_ratio
                }
            }
        except:
            return {}
    
    def _calculate_cycle_performance_metrics(self, cycle_name: str, cycle_data: Dict, compound_data: Dict) -> Dict:
        """Calculate comprehensive performance metrics for thermodynamic cycles"""
        try:
            metrics = {}
            
            efficiency = cycle_data.get('efficiency', 0)
            work_output = cycle_data.get('work_output_specific', 0)
            heat_input = cycle_data.get('heat_input_specific', 1)
            
            # Thermodynamic performance
            metrics['thermal_efficiency'] = efficiency
            metrics['specific_work'] = work_output
            metrics['heat_rate'] = 3600 / efficiency if efficiency > 0 else float('inf')
            
            # Exergy analysis
            T_ambient = compound_data.get('ambient_temp', 298.15)
            T_source = compound_data.get('hot_reservoir_temp', 873.15)
            
            exergy_efficiency = efficiency / (1 - T_ambient / T_source) if T_source > T_ambient else 0
            metrics['exergy_efficiency'] = exergy_efficiency
            
            # Environmental impact
            fuel_consumption = heat_input / compound_data.get('fuel_heating_value', 50e6) if heat_input > 0 else 0
            metrics['fuel_consumption_rate'] = fuel_consumption
            
            # Economic metrics (simplified)
            capital_cost_factor = cycle_data.get('complexity_factor', 1.0)
            metrics['relative_capital_cost'] = capital_cost_factor / efficiency if efficiency > 0 else float('inf')
            
            return metrics
        except Exception as e:
            self.logger.debug(f"Performance metrics calculation failed: {e}")
            return {}
    
    def _calculate_geological_fluid_mixing(self, components: List, compositions: List, 
                                         T: float, P: float, compound_data: Dict) -> Dict:
        """Advanced geological fluid mixing calculations"""
        try:
            geological_mixing = {}
            
            # Hydrothermal fluid mixing
            if compound_data.get('hydrothermal_application', False):
                # Calculate mineral solubilities in mixed fluids
                mineral_solubilities = {}
                for component in components:
                    solubility = self._calculate_hydrothermal_mineral_solubility(
                        component, T, P, compositions
                    )
                    mineral_solubilities[component] = solubility
                
                geological_mixing['mineral_solubilities'] = mineral_solubilities
            
            # Magmatic fluid mixing
            if compound_data.get('magmatic_application', False):
                volatile_partitioning = self._calculate_volatile_partitioning(
                    components, compositions, T, P
                )
                geological_mixing['volatile_partitioning'] = volatile_partitioning
            
            return geological_mixing
        except Exception as e:
            self.logger.debug(f"Geological fluid mixing failed: {e}")
            return {}
    
    def _calculate_flory_huggins_mixing(self, components: List, compositions: List, 
                                      T: float, compound_data: Dict) -> Dict:
        """Advanced Flory-Huggins theory with real thermodynamic database integration"""
        try:
            # Initialize external data integration
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            # Get real polymer molecular weight data from external databases
            molecular_weights = {}
            radius_of_gyration = {}
            for comp in components:
                if external_connector:
                    comp_data = external_connector.get_polymer_properties(comp, ['molecular_weight', 'radius_gyration'])
                    molecular_weights[comp] = comp_data.get('molecular_weight', 
                        self._estimate_mw_from_structure(comp, compound_data))
                    radius_of_gyration[comp] = comp_data.get('radius_gyration',
                        self._estimate_rg_from_mw(molecular_weights[comp]))
                else:
                    molecular_weights[comp] = self._estimate_mw_from_structure(comp, compound_data)
                    radius_of_gyration[comp] = self._estimate_rg_from_mw(molecular_weights[comp])
            
            # Calculate temperature-dependent interaction parameters using NIST data
            interaction_matrix = self._calculate_advanced_interaction_matrix(
                components, T, molecular_weights, external_connector, thermo_engine)
            
            # Advanced segment-based Flory-Huggins calculation
            segment_fractions = self._calculate_segment_fractions(
                components, compositions, molecular_weights)
            
            # Multi-component activity coefficients with cross-interactions
            activities = {}
            for i, comp_i in enumerate(components):
                ln_activity = 0.0
                phi_i = segment_fractions[comp_i]
                r_i = molecular_weights[comp_i] / min(molecular_weights.values())
                
                # Combinatorial contribution (extended for multi-component)
                ln_activity += np.log(phi_i / compositions[i]) + 1 - (phi_i / compositions[i])
                
                # Residual contribution with temperature dependence
                for j, comp_j in enumerate(components):
                    phi_j = segment_fractions[comp_j]
                    chi_ij = interaction_matrix[comp_i][comp_j]
                    ln_activity += chi_ij * phi_j * phi_j
                    
                    # Three-body interactions for complex geological polymers
                    for k, comp_k in enumerate(components[j+1:], j+1):
                        phi_k = segment_fractions[comp_k]
                        chi_ijk = self._calculate_ternary_interaction(
                            comp_i, comp_j, comp_k, T, interaction_matrix)
                        ln_activity += chi_ijk * phi_j * phi_k * 0.5
                
                # Pressure corrections for geological conditions
                if 'pressure' in compound_data:
                    P = compound_data['pressure']
                    pressure_correction = self._calculate_pressure_correction(
                        comp_i, T, P, radius_of_gyration[comp_i])
                    ln_activity += pressure_correction
                
                activities[comp_i] = {
                    'activity_coefficient': np.exp(ln_activity),
                    'segment_fraction': phi_i,
                    'molecular_ratio': r_i,
                    'interaction_contributions': self._detailed_interaction_analysis(
                        comp_i, components, segment_fractions, interaction_matrix)
                }
            
            # Advanced thermodynamic consistency checks
            consistency_check = self._verify_thermodynamic_consistency(
                activities, segment_fractions, interaction_matrix, T)
            
            return {
                'activity_coefficients': activities,
                'interaction_matrix': interaction_matrix,
                'segment_fractions': segment_fractions,
                'molecular_weights': molecular_weights,
                'radius_of_gyration': radius_of_gyration,
                'thermodynamic_consistency': consistency_check,
                'temperature_dependence': self._calculate_temperature_derivatives(
                    activities, interaction_matrix, T),
                'mixing_thermodynamics': self._calculate_mixing_properties(
                    activities, segment_fractions, T, molecular_weights),
                'uncertainty_analysis': self._propagate_parameter_uncertainties(
                    activities, interaction_matrix, external_connector)
            }
            
        except Exception as e:
            self.logger.error(f"Advanced Flory-Huggins calculation failed: {e}")
            return self._fallback_flory_huggins_calculation(components, compositions, T, compound_data)
    
    def _calculate_regular_solution_mixing(self, components: List, compositions: List, 
                                         T: float, compound_data: Dict) -> Dict:
        """Advanced regular solution theory with molecular dynamics integration"""
        try:
            # Initialize advanced data integration systems
            external_connector = self._get_or_create_external_connector()
            db_integration = self._get_or_create_db_integration()
            thermo_engine = self._get_or_create_thermo_engine()
            
            # Get real solubility parameters from multiple databases
            solubility_params = self._get_comprehensive_solubility_parameters(
                components, T, external_connector, db_integration)
            
            # Calculate temperature-dependent cohesive energy densities
            cohesive_energy_densities = self._calculate_cohesive_energy_densities(
                components, T, solubility_params, thermo_engine)
            
            # Advanced molar volume calculations with pressure corrections
            molar_volumes = self._calculate_temperature_pressure_dependent_volumes(
                components, T, compound_data.get('pressure', 1.0), external_connector)
            
            # Multi-component excess properties with cross-interactions
            excess_properties = self._calculate_multicomponent_excess_properties(
                components, compositions, solubility_params, molar_volumes, T)
            
            # Advanced activity coefficient calculations
            activity_coefficients = {}
            for i, comp_i in enumerate(components):
                delta_i = solubility_params[comp_i]['total']
                V_i = molar_volumes[comp_i]
                
                ln_gamma = 0.0
                
                # Dispersive interactions
                for j, comp_j in enumerate(components):
                    if i != j:
                        delta_j = solubility_params[comp_j]['total']
                        V_j = molar_volumes[comp_j]
                        phi_j = compositions[j] * V_j / sum(compositions[k] * molar_volumes[comp_k] 
                                                           for k, comp_k in enumerate(components))
                        
                        # Hansen solubility parameter components
                        delta_d_diff = (solubility_params[comp_i]['dispersive'] - 
                                      solubility_params[comp_j]['dispersive'])**2
                        delta_p_diff = (solubility_params[comp_i]['polar'] - 
                                      solubility_params[comp_j]['polar'])**2
                        delta_h_diff = (solubility_params[comp_i]['hydrogen_bonding'] - 
                                      solubility_params[comp_j]['hydrogen_bonding'])**2
                        
                        # Total interaction energy
                        interaction_energy = (delta_d_diff + delta_p_diff + delta_h_diff) * V_i / (8.314 * T)
                        ln_gamma += phi_j * interaction_energy
                
                # Non-random distribution corrections
                coordination_correction = self._calculate_coordination_corrections(
                    comp_i, components, compositions, molar_volumes, T)
                ln_gamma += coordination_correction
                
                # Pressure corrections for geological conditions
                if 'pressure' in compound_data:
                    P = compound_data['pressure']
                    pressure_correction = self._calculate_regular_solution_pressure_correction(
                        comp_i, T, P, V_i, solubility_params[comp_i])
                    ln_gamma += pressure_correction
                
                activity_coefficients[comp_i] = {
                    'activity_coefficient': np.exp(ln_gamma),
                    'solubility_parameter_contributions': {
                        'dispersive': solubility_params[comp_i]['dispersive'],
                        'polar': solubility_params[comp_i]['polar'], 
                        'hydrogen_bonding': solubility_params[comp_i]['hydrogen_bonding']
                    },
                    'molar_volume': V_i,
                    'interaction_analysis': self._analyze_molecular_interactions(
                        comp_i, components, solubility_params, ln_gamma)
                }
            
            # Advanced mixing property calculations
            mixing_properties = self._calculate_comprehensive_mixing_properties(
                components, compositions, activity_coefficients, molar_volumes, 
                excess_properties, T)
            
            # Molecular dynamics validation
            md_validation = self._validate_with_molecular_dynamics(
                components, compositions, solubility_params, T, external_connector)
            
            # Uncertainty quantification
            uncertainty_analysis = self._quantify_regular_solution_uncertainties(
                activity_coefficients, solubility_params, molar_volumes, external_connector)
            
            return {
                'activity_coefficients': activity_coefficients,
                'solubility_parameters': solubility_params,
                'molar_volumes': molar_volumes,
                'excess_properties': excess_properties,
                'mixing_properties': mixing_properties,
                'cohesive_energy_densities': cohesive_energy_densities,
                'molecular_dynamics_validation': md_validation,
                'uncertainty_analysis': uncertainty_analysis,
                'thermodynamic_derivatives': self._calculate_thermodynamic_derivatives(
                    activity_coefficients, T, compositions),
                'phase_stability_analysis': self._analyze_phase_stability(
                    activity_coefficients, compositions, T, compound_data.get('pressure', 1.0))
            }
            
        except Exception as e:
            self.logger.error(f"Advanced regular solution calculation failed: {e}")
            return self._fallback_regular_solution_calculation(components, compositions, T, compound_data)
    
    def _estimate_mw_from_structure(self, compound: str, compound_data: Dict) -> float:
        """Estimate molecular weight from chemical structure using advanced algorithms"""
        try:
            if f'{compound}_molecular_weight' in compound_data:
                return compound_data[f'{compound}_molecular_weight']
            
            external_connector = self._get_or_create_external_connector()
            if external_connector:
                structure_data = external_connector.get_compound_properties(
                    compound, ['molecular_weight', 'smiles', 'inchi'])
                if 'molecular_weight' in structure_data:
                    return structure_data['molecular_weight']
            
            formula = compound_data.get('formula', compound)
            return self._calculate_mw_from_formula(formula)
            
        except Exception as e:
            self.logger.debug(f"MW estimation failed for {compound}: {e}")
            return 100.0
    
    def _estimate_rg_from_mw(self, mw: float) -> float:
        """Estimate radius of gyration from molecular weight using scaling laws"""
        try:
            A = 0.25  # nm/(g/mol)^nu
            nu = 0.588  # Flory exponent
            return A * (mw ** nu)
        except:
            return 5.0
    
    def _calculate_advanced_interaction_matrix(self, components: List, T: float, 
                                             molecular_weights: Dict, external_connector, 
                                             thermo_engine) -> Dict:
        """Calculate temperature-dependent interaction matrix using real thermodynamic data"""
        try:
            interaction_matrix = {}
            for comp_i in components:
                interaction_matrix[comp_i] = {}
                for comp_j in components:
                    if comp_i == comp_j:
                        interaction_matrix[comp_i][comp_j] = 0.0
                    else:
                        chi_ij = self._get_binary_interaction_parameter(
                            comp_i, comp_j, T, external_connector, thermo_engine)
                        interaction_matrix[comp_i][comp_j] = chi_ij
            return interaction_matrix
        except Exception as e:
            self.logger.debug(f"Interaction matrix calculation failed: {e}")
            return {comp: {comp2: 0.5 for comp2 in components} for comp in components}
    
    def _get_binary_interaction_parameter(self, comp_i: str, comp_j: str, T: float,
                                        external_connector, thermo_engine) -> float:
        """Get binary interaction parameter from multiple data sources"""
        try:
            if external_connector:
                chi_data = external_connector.get_binary_interaction_data(comp_i, comp_j, T)
                if chi_data and 'flory_huggins_chi' in chi_data:
                    return chi_data['flory_huggins_chi']
            
            if thermo_engine:
                chi_calc = thermo_engine.calculate_interaction_parameter(
                    comp_i, comp_j, T, method='group_contribution')
                if chi_calc is not None:
                    return chi_calc
            
            delta_i = self._estimate_solubility_parameter(comp_i, T)
            delta_j = self._estimate_solubility_parameter(comp_j, T)
            V_ref = 100.0  # cm3/mol
            chi_ij = V_ref * (delta_i - delta_j)**2 / (8.314 * T)
            return chi_ij
        except Exception as e:
            self.logger.debug(f"Binary interaction parameter estimation failed: {e}")
            return 0.5
    
    def _calculate_segment_fractions(self, components: List, compositions: List, 
                                   molecular_weights: Dict) -> Dict:
        """Calculate segment fractions for multi-component polymer systems"""
        try:
            segment_fractions = {}
            total_segments = 0
            
            for i, comp in enumerate(components):
                r_i = molecular_weights[comp] / min(molecular_weights.values())
                total_segments += compositions[i] * r_i
            
            for i, comp in enumerate(components):
                r_i = molecular_weights[comp] / min(molecular_weights.values())
                segment_fractions[comp] = compositions[i] * r_i / total_segments
            
            return segment_fractions
        except Exception as e:
            self.logger.debug(f"Segment fraction calculation failed: {e}")
            return {comp: comp_frac for comp, comp_frac in zip(components, compositions)}
    
    def _calculate_ternary_interaction(self, comp_i: str, comp_j: str, comp_k: str,
                                     T: float, interaction_matrix: Dict) -> float:
        """Calculate ternary interaction parameters for complex geological polymers"""
        try:
            chi_ij = interaction_matrix[comp_i][comp_j]
            chi_ik = interaction_matrix[comp_i][comp_k]
            chi_jk = interaction_matrix[comp_j][comp_k]
            chi_ijk = (chi_ij * chi_ik * chi_jk)**(1/3) * 0.1
            return chi_ijk
        except Exception as e:
            self.logger.debug(f"Ternary interaction calculation failed: {e}")
            return 0.0
    
    def _calculate_pressure_correction(self, compound: str, T: float, P: float, 
                                     radius_gyration: float) -> float:
        """Calculate pressure correction for geological conditions"""
        try:
            V_partial = 4/3 * np.pi * radius_gyration**3 * 6.022e23 * 1e-21  # cm3/mol
            P_ref = 1.0  # bar
            pressure_correction = V_partial * (P - P_ref) / (8.314 * T * 100)
            return pressure_correction
        except Exception as e:
            self.logger.debug(f"Pressure correction failed: {e}")
            return 0.0
    
    def _detailed_interaction_analysis(self, compound: str, components: List,
                                     segment_fractions: Dict, interaction_matrix: Dict) -> Dict:
        """Detailed analysis of interaction contributions"""
        try:
            analysis = {
                'binary_contributions': {},
                'total_interaction_energy': 0.0,
                'dominant_interactions': []
            }
            
            for comp in components:
                if comp != compound:
                    chi_ij = interaction_matrix[compound][comp]
                    phi_j = segment_fractions[comp]
                    contribution = chi_ij * phi_j * phi_j
                    
                    analysis['binary_contributions'][comp] = {
                        'interaction_parameter': chi_ij,
                        'segment_fraction': phi_j,
                        'contribution': contribution
                    }
                    analysis['total_interaction_energy'] += contribution
            
            sorted_contributions = sorted(
                analysis['binary_contributions'].items(),
                key=lambda x: abs(x[1]['contribution']),
                reverse=True
            )
            analysis['dominant_interactions'] = [item[0] for item in sorted_contributions[:3]]
            return analysis
        except Exception as e:
            self.logger.debug(f"Interaction analysis failed: {e}")
            return {'error': str(e)}
    
    def _verify_thermodynamic_consistency(self, activities: Dict, segment_fractions: Dict,
                                        interaction_matrix: Dict, T: float) -> Dict:
        """Verify thermodynamic consistency using Gibbs-Duhem relation"""
        try:
            consistency_check = {
                'gibbs_duhem_satisfied': False,
                'deviation_magnitude': 0.0,
                'consistency_score': 0.0
            }
            
            total_derivative = 0.0
            for comp, activity_data in activities.items():
                xi = segment_fractions[comp]
                gamma_i = activity_data['activity_coefficient']
                d_ln_gamma = np.log(gamma_i)
                total_derivative += xi * d_ln_gamma
            
            deviation = abs(total_derivative)
            consistency_check['deviation_magnitude'] = deviation
            consistency_check['gibbs_duhem_satisfied'] = deviation < 0.01
            consistency_check['consistency_score'] = max(0, 1 - deviation)
            return consistency_check
        except Exception as e:
            self.logger.debug(f"Consistency check failed: {e}")
            return {'error': str(e)}
    
    def _calculate_temperature_derivatives(self, activities: Dict, interaction_matrix: Dict,
                                         T: float) -> Dict:
        """Calculate temperature derivatives of thermodynamic properties"""
        try:
            derivatives = {
                'activity_coefficient_derivatives': {},
                'interaction_parameter_derivatives': {},
                'heat_capacity_contributions': {}
            }
            
            for comp, activity_data in activities.items():
                gamma = activity_data['activity_coefficient']
                d_ln_gamma_dT = np.log(gamma) / T
                derivatives['activity_coefficient_derivatives'][comp] = d_ln_gamma_dT
                derivatives['heat_capacity_contributions'][comp] = -8.314 * T * T * d_ln_gamma_dT
            
            return derivatives
        except Exception as e:
            self.logger.debug(f"Temperature derivatives calculation failed: {e}")
            return {'error': str(e)}
    
    def _calculate_mixing_properties(self, activities: Dict, segment_fractions: Dict,
                                   T: float, molecular_weights: Dict) -> Dict:
        """Calculate comprehensive mixing thermodynamic properties"""
        try:
            mixing_props = {
                'excess_gibbs_energy': 0.0,
                'mixing_entropy': 0.0,
                'excess_enthalpy': 0.0,
                'excess_volume': 0.0
            }
            
            R = 8.314  # J/(mol·K)
            
            for comp, activity_data in activities.items():
                xi = segment_fractions[comp]
                gamma_i = activity_data['activity_coefficient']
                mixing_props['excess_gibbs_energy'] += xi * R * T * np.log(gamma_i)
                if xi > 0:
                    mixing_props['mixing_entropy'] += -R * xi * np.log(xi)
            
            mixing_props['excess_enthalpy'] = self._estimate_excess_enthalpy(
                activities, segment_fractions, molecular_weights, T)
            mixing_props['excess_volume'] = self._estimate_excess_volume(
                activities, segment_fractions, molecular_weights, T)
            
            return mixing_props
        except Exception as e:
            self.logger.debug(f"Mixing properties calculation failed: {e}")
            return {'error': str(e)}
    
    def _propagate_parameter_uncertainties(self, activities: Dict, interaction_matrix: Dict,
                                         external_connector) -> Dict:
        """Propagate uncertainties from parameter estimation through calculations"""
        try:
            uncertainty_analysis = {
                'parameter_uncertainties': {},
                'propagated_uncertainties': {},
                'confidence_intervals': {},
                'reliability_score': 0.0
            }
            
            for comp, activity_data in activities.items():
                if external_connector:
                    data_quality = external_connector.get_data_quality_metrics(comp)
                    uncertainty_analysis['parameter_uncertainties'][comp] = {
                        'molecular_weight_uncertainty': data_quality.get('mw_uncertainty', 0.05),
                        'interaction_parameter_uncertainty': data_quality.get('chi_uncertainty', 0.1),
                        'data_source_reliability': data_quality.get('reliability', 0.8)
                    }
                else:
                    uncertainty_analysis['parameter_uncertainties'][comp] = {
                        'molecular_weight_uncertainty': 0.1,
                        'interaction_parameter_uncertainty': 0.2,
                        'data_source_reliability': 0.6
                    }
                
                gamma = activity_data['activity_coefficient']
                param_unc = uncertainty_analysis['parameter_uncertainties'][comp]
                propagated_unc = np.sqrt(
                    (param_unc['molecular_weight_uncertainty'] * 0.5)**2 +
                    (param_unc['interaction_parameter_uncertainty'] * np.log(gamma))**2
                )
                uncertainty_analysis['propagated_uncertainties'][comp] = propagated_unc
                
                uncertainty_analysis['confidence_intervals'][comp] = {
                    'lower': gamma * (1 - 1.96 * propagated_unc),
                    'upper': gamma * (1 + 1.96 * propagated_unc)
                }
            
            reliabilities = [params['data_source_reliability'] 
                           for params in uncertainty_analysis['parameter_uncertainties'].values()]
            uncertainty_analysis['reliability_score'] = np.mean(reliabilities)
            return uncertainty_analysis
        except Exception as e:
            self.logger.debug(f"Uncertainty propagation failed: {e}")
            return {'error': str(e)}
    
    def _fallback_flory_huggins_calculation(self, components: List, compositions: List,
                                          T: float, compound_data: Dict) -> Dict:
        """Fallback calculation when advanced methods fail"""
        try:
            activities = {}
            for i, comp in enumerate(components):
                phi = compositions[i]
                chi = compound_data.get(f'{comp}_flory_huggins_chi', 0.5)
                chi_corrected = chi * (1 + 0.001 * (T - 298.15))
                ln_activity = np.log(phi) + 1 - phi + chi_corrected * (1 - phi)**2
                activities[comp] = {
                    'activity_coefficient': np.exp(ln_activity),
                    'fallback_method': True
                }
            return {
                'activity_coefficients': activities,
                'method': 'fallback_flory_huggins',
                'warning': 'Advanced calculation failed, using simplified method'
            }
        except Exception as e:
            self.logger.error(f"Fallback Flory-Huggins calculation failed: {e}")
            return {'error': str(e)}
    
    def _get_comprehensive_solubility_parameters(self, components: List, T: float,
                                               external_connector, db_integration) -> Dict:
        """Get comprehensive solubility parameters from multiple databases"""
        try:
            solubility_params = {}
            
            for comp in components:
                # Initialize parameter structure
                solubility_params[comp] = {
                    'total': 20.0,
                    'dispersive': 15.0,
                    'polar': 8.0,
                    'hydrogen_bonding': 5.0,
                    'data_source': 'estimated'
                }
                
                # Try external databases first
                if external_connector:
                    try:
                        solv_data = external_connector.get_solubility_parameters(comp, T)
                        if solv_data:
                            solubility_params[comp].update(solv_data)
                            solubility_params[comp]['data_source'] = 'external_database'
                    except Exception as e:
                        self.logger.debug(f"External solubility data failed for {comp}: {e}")
                
                # Try database integration
                if db_integration and solubility_params[comp]['data_source'] == 'estimated':
                    try:
                        db_data = db_integration.get_compound_properties(comp, ['solubility_parameters'])
                        if db_data and 'solubility_parameters' in db_data:
                            solubility_params[comp].update(db_data['solubility_parameters'])
                            solubility_params[comp]['data_source'] = 'internal_database'
                    except Exception as e:
                        self.logger.debug(f"Database solubility data failed for {comp}: {e}")
                
                # Ensure total parameter consistency
                if 'dispersive' in solubility_params[comp] and 'polar' in solubility_params[comp] and 'hydrogen_bonding' in solubility_params[comp]:
                    solubility_params[comp]['total'] = np.sqrt(
                        solubility_params[comp]['dispersive']**2 +
                        solubility_params[comp]['polar']**2 +
                        solubility_params[comp]['hydrogen_bonding']**2
                    )
            
            return solubility_params
        except Exception as e:
            self.logger.error(f"Comprehensive solubility parameters calculation failed: {e}")
            return {comp: {'total': 20.0, 'dispersive': 15.0, 'polar': 8.0, 'hydrogen_bonding': 5.0} for comp in components}
    
    def _calculate_cohesive_energy_densities(self, components: List, T: float,
                                           solubility_params: Dict, thermo_engine) -> Dict:
        """Calculate temperature-dependent cohesive energy densities"""
        try:
            cohesive_energies = {}
            
            for comp in components:
                # Get solubility parameter
                delta_total = solubility_params[comp]['total']
                
                # Cohesive energy density = δ²
                ced = delta_total**2  # (MPa)^0.5 squared = MPa
                
                # Temperature correction using thermodynamic engine
                if thermo_engine:
                    try:
                        temp_correction = thermo_engine.calculate_temperature_correction(
                            comp, T, property_type='cohesive_energy_density')
                        ced *= temp_correction
                    except:
                        # Simple temperature correction if thermo engine fails
                        ced *= (T / 298.15)**(-0.5)  # Approximate temperature dependence
                
                cohesive_energies[comp] = ced
            
            return cohesive_energies
        except Exception as e:
            self.logger.debug(f"Cohesive energy density calculation failed: {e}")
            return {comp: 400.0 for comp in components}  # Default CED in MPa
    
    def _calculate_temperature_pressure_dependent_volumes(self, components: List, T: float,
                                                        P: float, external_connector) -> Dict:
        """Calculate molar volumes with temperature and pressure corrections"""
        try:
            molar_volumes = {}
            
            for comp in components:
                # Get base molar volume
                if external_connector:
                    try:
                        volume_data = external_connector.get_molar_volume(comp, T, P)
                        if volume_data:
                            molar_volumes[comp] = volume_data
                            continue
                    except Exception as e:
                        self.logger.debug(f"External volume data failed for {comp}: {e}")
                
                # Estimate from molecular weight and density
                mw = self._estimate_mw_from_structure(comp, {})
                density = self._estimate_density(comp, T, P)  # g/cm³
                volume = mw / density  # cm³/mol
                molar_volumes[comp] = volume
            
            return molar_volumes
        except Exception as e:
            self.logger.debug(f"Molar volume calculation failed: {e}")
            return {comp: 100.0 for comp in components}  # Default volume in cm³/mol
    
    def _calculate_multicomponent_excess_properties(self, components: List, compositions: List,
                                                  solubility_params: Dict, molar_volumes: Dict,
                                                  T: float) -> Dict:
        """Calculate multi-component excess properties with cross-interactions"""
        try:
            excess_props = {
                'excess_enthalpy': 0.0,
                'excess_volume': 0.0,
                'excess_entropy': 0.0,
                'binary_contributions': {},
                'ternary_contributions': {}
            }
            
            # Binary interactions
            for i, comp_i in enumerate(components):
                for j, comp_j in enumerate(components[i+1:], i+1):
                    delta_i = solubility_params[comp_i]['total']
                    delta_j = solubility_params[comp_j]['total']
                    V_i = molar_volumes[comp_i]
                    V_j = molar_volumes[comp_j]
                    
                    # Volume fraction average
                    V_ij = (V_i + V_j) / 2
                    
                    # Excess enthalpy contribution
                    HE_ij = V_ij * (delta_i - delta_j)**2 * compositions[i] * compositions[j]
                    excess_props['excess_enthalpy'] += HE_ij
                    
                    # Store binary contribution
                    pair_key = f"{comp_i}-{comp_j}"
                    excess_props['binary_contributions'][pair_key] = {
                        'excess_enthalpy': HE_ij,
                        'volume_interaction': V_ij,
                        'parameter_difference': abs(delta_i - delta_j)
                    }
            
            # Ternary interactions (simplified)
            if len(components) >= 3:
                for i in range(len(components)):
                    for j in range(i+1, len(components)):
                        for k in range(j+1, len(components)):
                            comp_i, comp_j, comp_k = components[i], components[j], components[k]
                            
                            # Simplified ternary excess contribution
                            ternary_correction = 0.1 * compositions[i] * compositions[j] * compositions[k]
                            excess_props['excess_enthalpy'] += ternary_correction
                            
                            triplet_key = f"{comp_i}-{comp_j}-{comp_k}"
                            excess_props['ternary_contributions'][triplet_key] = ternary_correction
            
            return excess_props
        except Exception as e:
            self.logger.debug(f"Multicomponent excess properties calculation failed: {e}")
            return {'excess_enthalpy': 0.0, 'excess_volume': 0.0, 'excess_entropy': 0.0}
    
    def _calculate_coordination_corrections(self, compound: str, components: List,
                                          compositions: List, molar_volumes: Dict, T: float) -> float:
        """Calculate coordination corrections for non-random distribution"""
        try:
            # Local composition corrections based on coordination number
            coordination_number = 10  # Typical liquid coordination
            
            correction = 0.0
            for i, comp in enumerate(components):
                if comp != compound:
                    # Volume fraction
                    total_volume = sum(compositions[j] * molar_volumes[comp_j] 
                                     for j, comp_j in enumerate(components))
                    phi_i = compositions[i] * molar_volumes[comp] / total_volume
                    
                    # Non-random correction
                    if phi_i > 0:
                        correction += phi_i * np.log(phi_i) / coordination_number
            
            return correction
        except Exception as e:
            self.logger.debug(f"Coordination correction failed: {e}")
            return 0.0
    
    def _calculate_regular_solution_pressure_correction(self, compound: str, T: float, P: float,
                                                      V_molar: float, solubility_params: Dict) -> float:
        """Calculate pressure correction for regular solution theory"""
        try:
            # Pressure-volume work with compressibility effects
            P_ref = 1.0  # bar reference pressure
            
            # Estimate isothermal compressibility from solubility parameters
            delta_total = solubility_params['total']
            beta_T = 1.0e-4 / delta_total  # Rough estimate: higher cohesive energy = lower compressibility
            
            # Volume change with pressure
            dV_dP = -V_molar * beta_T
            
            # Pressure correction to chemical potential
            pressure_correction = dV_dP * (P - P_ref) / (8.314 * T)
            
            return pressure_correction
        except Exception as e:
            self.logger.debug(f"Pressure correction failed: {e}")
            return 0.0
    
    def _analyze_molecular_interactions(self, compound: str, components: List,
                                      solubility_params: Dict, ln_gamma: float) -> Dict:
        """Analyze molecular interactions and their contributions"""
        try:
            analysis = {
                'interaction_types': {},
                'dominant_forces': [],
                'interaction_strength': 'moderate'
            }
            
            comp_params = solubility_params[compound]
            
            # Analyze interaction types with other components
            for comp in components:
                if comp != compound:
                    other_params = solubility_params[comp]
                    
                    dispersive_interaction = abs(comp_params['dispersive'] - other_params['dispersive'])
                    polar_interaction = abs(comp_params['polar'] - other_params['polar'])
                    hbond_interaction = abs(comp_params['hydrogen_bonding'] - other_params['hydrogen_bonding'])
                    
                    analysis['interaction_types'][comp] = {
                        'dispersive_mismatch': dispersive_interaction,
                        'polar_mismatch': polar_interaction,
                        'hydrogen_bonding_mismatch': hbond_interaction,
                        'dominant_interaction': max(
                            ('dispersive', dispersive_interaction),
                            ('polar', polar_interaction),
                            ('hydrogen_bonding', hbond_interaction),
                            key=lambda x: x[1]
                        )[0]
                    }
            
            # Determine interaction strength
            if abs(ln_gamma) > 1.0:
                analysis['interaction_strength'] = 'strong'
            elif abs(ln_gamma) > 0.1:
                analysis['interaction_strength'] = 'moderate'
            else:
                analysis['interaction_strength'] = 'weak'
            
            # Identify dominant forces
            force_contributions = {
                'dispersive': comp_params['dispersive'],
                'polar': comp_params['polar'],
                'hydrogen_bonding': comp_params['hydrogen_bonding']
            }
            analysis['dominant_forces'] = sorted(
                force_contributions.items(), 
                key=lambda x: x[1], 
                reverse=True
            )[:2]
            
            return analysis
        except Exception as e:
            self.logger.debug(f"Molecular interaction analysis failed: {e}")
            return {'error': str(e)}
    
    def _calculate_comprehensive_mixing_properties(self, components: List, compositions: List,
                                                 activity_coefficients: Dict, molar_volumes: Dict,
                                                 excess_properties: Dict, T: float) -> Dict:
        """Calculate comprehensive mixing properties"""
        try:
            mixing_props = {
                'gibbs_mixing': 0.0,
                'entropy_mixing': 0.0,
                'enthalpy_mixing': 0.0,
                'volume_mixing': 0.0,
                'heat_capacity_mixing': 0.0
            }
            
            R = 8.314  # J/(mol·K)
            
            # Volume fractions
            total_volume = sum(compositions[i] * molar_volumes[comp] 
                             for i, comp in enumerate(components))
            
            for i, comp in enumerate(components):
                xi = compositions[i]
                gamma_i = activity_coefficients[comp]['activity_coefficient']
                V_i = molar_volumes[comp]
                phi_i = xi * V_i / total_volume
                
                # Gibbs mixing
                if xi > 0:
                    mixing_props['gibbs_mixing'] += xi * R * T * (np.log(xi) + np.log(gamma_i))
                
                # Ideal entropy of mixing
                if xi > 0:
                    mixing_props['entropy_mixing'] += -R * xi * np.log(xi)
                
                # Volume mixing (ideal + excess)
                mixing_props['volume_mixing'] += xi * V_i
            
            # Add excess contributions
            mixing_props['enthalpy_mixing'] = excess_properties.get('excess_enthalpy', 0.0)
            mixing_props['volume_mixing'] += excess_properties.get('excess_volume', 0.0)
            
            # Heat capacity of mixing (estimated)
            mixing_props['heat_capacity_mixing'] = self._estimate_heat_capacity_mixing(
                components, compositions, activity_coefficients, T)
            
            return mixing_props
        except Exception as e:
            self.logger.debug(f"Comprehensive mixing properties calculation failed: {e}")
            return {'error': str(e)}
    
    def _validate_with_molecular_dynamics(self, components: List, compositions: List,
                                        solubility_params: Dict, T: float,
                                        external_connector) -> Dict:
        """Validate regular solution predictions with molecular dynamics data"""
        try:
            validation = {
                'md_data_available': False,
                'validation_score': 0.0,
                'discrepancies': {},
                'recommendations': []
            }
            
            # Try to get MD simulation data from external sources
            if external_connector:
                try:
                    md_results = external_connector.get_molecular_dynamics_data(
                        components, compositions, T, ['radial_distribution', 'coordination_numbers', 'mixing_energies'])
                    
                    if md_results:
                        validation['md_data_available'] = True
                        
                        # Compare regular solution predictions with MD results
                        if 'mixing_energies' in md_results:
                            predicted_energy = sum(
                                solubility_params[comp]['total']**2 * compositions[i]
                                for i, comp in enumerate(components)
                            )
                            md_energy = md_results['mixing_energies']
                            
                            relative_error = abs(predicted_energy - md_energy) / max(abs(md_energy), 1e-6)
                            validation['validation_score'] = max(0, 1 - relative_error)
                            
                            if relative_error > 0.2:
                                validation['discrepancies']['mixing_energy'] = {
                                    'predicted': predicted_energy,
                                    'md_simulation': md_energy,
                                    'relative_error': relative_error
                                }
                                validation['recommendations'].append(
                                    'Consider using molecular simulation results for better accuracy'
                                )
                        
                        # Compare coordination numbers
                        if 'coordination_numbers' in md_results:
                            validation['coordination_analysis'] = md_results['coordination_numbers']
                            if any(cn < 6 or cn > 12 for cn in md_results['coordination_numbers'].values()):
                                validation['recommendations'].append(
                                    'Unusual coordination numbers detected - verify regular solution applicability'
                                )
                
                except Exception as e:
                    self.logger.debug(f"MD validation data retrieval failed: {e}")
            
            # If no MD data available, provide theoretical validation
            if not validation['md_data_available']:
                validation['validation_score'] = 0.7  # Moderate confidence without MD validation
                validation['recommendations'].append(
                    'Molecular dynamics validation not available - consider experimental validation'
                )
            
            return validation
        except Exception as e:
            self.logger.debug(f"MD validation failed: {e}")
            return {'error': str(e)}
    
    def _quantify_regular_solution_uncertainties(self, activity_coefficients: Dict,
                                               solubility_params: Dict, molar_volumes: Dict,
                                               external_connector) -> Dict:
        """Quantify uncertainties in regular solution calculations"""
        try:
            uncertainty_analysis = {
                'parameter_uncertainties': {},
                'model_uncertainties': {},
                'total_uncertainty': {},
                'confidence_level': 0.0
            }
            
            for comp, activity_data in activity_coefficients.items():
                # Parameter uncertainties
                uncertainty_analysis['parameter_uncertainties'][comp] = {
                    'solubility_parameter_uncertainty': 0.1 * solubility_params[comp]['total'],
                    'molar_volume_uncertainty': 0.05 * molar_volumes[comp],
                    'temperature_dependence_uncertainty': 0.02
                }
                
                # Model uncertainties
                gamma = activity_data['activity_coefficient']
                model_uncertainty = 0.15 if gamma > 2.0 else 0.1  # Higher uncertainty for large deviations
                uncertainty_analysis['model_uncertainties'][comp] = model_uncertainty
                
                # Total uncertainty propagation
                param_unc = uncertainty_analysis['parameter_uncertainties'][comp]
                total_unc = np.sqrt(
                    (param_unc['solubility_parameter_uncertainty'] / solubility_params[comp]['total'])**2 +
                    (param_unc['molar_volume_uncertainty'] / molar_volumes[comp])**2 +
                    param_unc['temperature_dependence_uncertainty']**2 +
                    model_uncertainty**2
                )
                uncertainty_analysis['total_uncertainty'][comp] = total_unc
            
            # Overall confidence level
            avg_uncertainty = np.mean(list(uncertainty_analysis['total_uncertainty'].values()))
            uncertainty_analysis['confidence_level'] = max(0, 1 - avg_uncertainty)
            
            return uncertainty_analysis
        except Exception as e:
            self.logger.debug(f"Uncertainty quantification failed: {e}")
            return {'error': str(e)}
    
    def _calculate_thermodynamic_derivatives(self, activity_coefficients: Dict,
                                           T: float, compositions: List) -> Dict:
        """Calculate thermodynamic derivatives for regular solution"""
        try:
            derivatives = {
                'temperature_derivatives': {},
                'composition_derivatives': {},
                'pressure_derivatives': {}
            }
            
            for comp, activity_data in activity_coefficients.items():
                gamma = activity_data['activity_coefficient']
                
                # Temperature derivatives
                d_ln_gamma_dT = -np.log(gamma) / T  # Approximate temperature dependence
                derivatives['temperature_derivatives'][comp] = {
                    'd_ln_gamma_dT': d_ln_gamma_dT,
                    'partial_molar_enthalpy': -8.314 * T * T * d_ln_gamma_dT,
                    'partial_molar_entropy': -8.314 * d_ln_gamma_dT
                }
            
            return derivatives
        except Exception as e:
            self.logger.debug(f"Thermodynamic derivatives calculation failed: {e}")
            return {'error': str(e)}
    
    def _analyze_phase_stability(self, activity_coefficients: Dict, compositions: List,
                               T: float, P: float) -> Dict:
        """Analyze phase stability for regular solution"""
        try:
            stability_analysis = {
                'phase_stable': True,
                'spinodal_decomposition_risk': False,
                'critical_composition': None,
                'stability_criteria': {}
            }
            
            # Check for phase separation tendency
            max_gamma = max(data['activity_coefficient'] for data in activity_coefficients.values())
            
            if max_gamma > 5.0:
                stability_analysis['phase_stable'] = False
                stability_analysis['spinodal_decomposition_risk'] = True
                stability_analysis['stability_criteria']['max_activity_coefficient'] = max_gamma
            
            # Estimate critical composition (simplified)
            if len(compositions) == 2:
                gamma_1 = list(activity_coefficients.values())[0]['activity_coefficient']
                gamma_2 = list(activity_coefficients.values())[1]['activity_coefficient']
                
                if gamma_1 > 2.0 and gamma_2 > 2.0:
                    # Rough estimate of critical composition
                    stability_analysis['critical_composition'] = 0.5
            
            return stability_analysis
        except Exception as e:
            self.logger.debug(f"Phase stability analysis failed: {e}")
            return {'error': str(e)}
    
    def _fallback_regular_solution_calculation(self, components: List, compositions: List,
                                             T: float, compound_data: Dict) -> Dict:
        """Fallback regular solution calculation when advanced methods fail"""
        try:
            # Simple regular solution with basic parameters
            activity_coefficients = {}
            
            for i, comp in enumerate(components):
                # Use simple solubility parameter estimation
                delta_i = compound_data.get(f'{comp}_solubility_parameter', 20.0)
                V_i = compound_data.get(f'{comp}_molar_volume', 100.0)
                
                ln_gamma = 0.0
                for j, comp_j in enumerate(components):
                    if i != j:
                        delta_j = compound_data.get(f'{comp_j}_solubility_parameter', 20.0)
                        phi_j = compositions[j]  # Approximation
                        ln_gamma += phi_j * V_i * (delta_i - delta_j)**2 / (8.314 * T)
                
                activity_coefficients[comp] = {
                    'activity_coefficient': np.exp(ln_gamma),
                    'fallback_method': True,
                    'solubility_parameter': delta_i,
                    'molar_volume': V_i
                }
            
            return {
                'activity_coefficients': activity_coefficients,
                'method': 'fallback_regular_solution',
                'warning': 'Advanced calculation failed, using simplified method'
            }
        except Exception as e:
            self.logger.error(f"Fallback regular solution calculation failed: {e}")
            return {'error': str(e)}
    
    def _calculate_mw_from_formula(self, formula: str) -> float:
        """Calculate molecular weight from empirical formula"""
        try:
            import re
            
            # Atomic weights dictionary
            atomic_weights = {
                'H': 1.008, 'C': 12.011, 'N': 14.007, 'O': 15.999, 'P': 30.974,
                'S': 32.065, 'Cl': 35.453, 'K': 39.098, 'Ca': 40.078, 'Fe': 55.845,
                'Na': 22.990, 'Mg': 24.305, 'Al': 26.982, 'Si': 28.086, 'F': 18.998
            }
            
            # Parse formula
            mw = 0.0
            pattern = r'([A-Z][a-z]?)(\d*)'
            matches = re.findall(pattern, formula)
            
            for element, count in matches:
                count = int(count) if count else 1
                if element in atomic_weights:
                    mw += atomic_weights[element] * count
            
            return mw if mw > 0 else 100.0
        except:
            return 100.0
    
    def _estimate_solubility_parameter(self, compound: str, T: float) -> float:
        """Estimate solubility parameter using group contribution methods"""
        try:
            # Use simple temperature-dependent correlation
            delta_298 = 20.0  # Default at 298K
            
            # Temperature correction
            delta_T = delta_298 * (298.15 / T)**0.5
            
            return delta_T
        except:
            return 20.0
    
    def _estimate_density(self, compound: str, T: float, P: float) -> float:
        """Estimate density using empirical correlations"""
        try:
            # Base density at standard conditions
            density_298 = 1.0  # g/cm³
            
            # Temperature correction (thermal expansion)
            alpha = 1e-3  # Thermal expansion coefficient
            density_T = density_298 * (1 - alpha * (T - 298.15))
            
            # Pressure correction (compressibility)
            beta = 1e-4  # Compressibility
            density_TP = density_T * (1 + beta * (P - 1.0))
            
            return max(density_TP, 0.1)  # Minimum reasonable density
        except:
            return 1.0
    
    def _estimate_excess_enthalpy(self, activities: Dict, segment_fractions: Dict,
                                molecular_weights: Dict, T: float) -> float:
        """Estimate excess enthalpy from activity coefficients"""
        try:
            HE = 0.0
            R = 8.314  # J/(mol·K)
            
            for comp, activity_data in activities.items():
                xi = segment_fractions[comp]
                gamma_i = activity_data['activity_coefficient']
                
                # Approximate relationship between gamma and HE
                if gamma_i > 1:
                    HE += xi * R * T * np.log(gamma_i) * 0.5  # Rough approximation
            
            return HE
        except:
            return 0.0
    
    def _estimate_excess_volume(self, activities: Dict, segment_fractions: Dict,
                              molecular_weights: Dict, T: float) -> float:
        """Estimate excess volume from molecular data"""
        try:
            VE = 0.0
            
            # Simple estimation based on molecular weight differences
            mw_values = list(molecular_weights.values())
            if len(mw_values) > 1:
                mw_range = max(mw_values) - min(mw_values)
                VE = 0.01 * mw_range  # Rough approximation
            
            return VE
        except:
            return 0.0
    
    def _estimate_heat_capacity_mixing(self, components: List, compositions: List,
                                     activity_coefficients: Dict, T: float) -> float:
        """Estimate heat capacity of mixing"""
        try:
            Cp_mix = 0.0
            R = 8.314  # J/(mol·K)
            
            for i, comp in enumerate(components):
                xi = compositions[i]
                gamma_i = activity_coefficients[comp]['activity_coefficient']
                
                # Temperature dependence of activity coefficient
                d2_ln_gamma_dT2 = -1.0 / (T * T)  # Approximate second derivative
                Cp_mix += xi * R * T * T * d2_ln_gamma_dT2
            
            return Cp_mix
        except:
            return 0.0
    
    def _calculate_van_der_waals_mixing_rules(self, components: List, compositions: List, 
                                            compound_data: Dict) -> Dict:
        """Van der Waals mixing rules for equation of state"""
        try:
            # Get pure component parameters
            a_params = {}
            b_params = {}
            
            for comp in components:
                # Van der Waals parameters from critical properties
                Tc = compound_data.get(f'{comp}_critical_temp', 647.1)
                Pc = compound_data.get(f'{comp}_critical_pressure', 220.64e5)
                
                a_params[comp] = 27 * (8.314 * Tc)**2 / (64 * Pc)
                b_params[comp] = 8.314 * Tc / (8 * Pc)
            
            # Mixing rules
            a_mix = 0
            b_mix = 0
            
            for i, comp1 in enumerate(components):
                for j, comp2 in enumerate(components):
                    # Geometric mixing rule for a
                    a_ij = np.sqrt(a_params[comp1] * a_params[comp2])
                    a_mix += compositions[i] * compositions[j] * a_ij
                
                # Linear mixing rule for b
                b_mix += compositions[i] * b_params[comp1]
            
            return {
                'a_mixture': a_mix,
                'b_mixture': b_mix,
                'pure_component_a': a_params,
                'pure_component_b': b_params
            }
        except Exception as e:
            self.logger.debug(f"VdW mixing rules failed: {e}")
            return {}
    
    def _calculate_derived_mixing_properties(self, mixing: Dict, components: List, 
                                           compositions: List, T: float, P: float) -> Dict:
        """Calculate derived thermodynamic mixing properties"""
        try:
            derived = {}
            
            # Partial molar properties
            if 'excess_enthalpy' in mixing:
                partial_molar_enthalpies = {}
                # Simplified calculation
                for i, comp in enumerate(components):
                    partial_molar_enthalpies[comp] = mixing['excess_enthalpy'] * (1 - compositions[i])
                derived['partial_molar_enthalpies'] = partial_molar_enthalpies
            
            # Mixing entropy
            ideal_mixing_entropy = -8.314 * sum(x * np.log(x) for x in compositions if x > 0)
            derived['ideal_mixing_entropy'] = ideal_mixing_entropy
            
            # Gibbs energy of mixing
            if 'excess_enthalpy' in mixing:
                gibbs_mixing = mixing['excess_enthalpy'] - T * ideal_mixing_entropy
                derived['gibbs_mixing'] = gibbs_mixing
            
            return derived
        except Exception as e:
            self.logger.debug(f"Derived properties calculation failed: {e}")
            return {}
    
    def _calculate_basic_mixing_fallback(self, compound_data: Dict) -> Dict:
        """Basic mixing properties fallback calculation"""
        try:
            return {
                'excess_enthalpy': 0.0,
                'excess_volume': 0.0,
                'activity_coefficients': {compound_data.get('formula', 'unknown'): 1.0},
                'mixing_entropy': 0.0,
                'calculation_method': 'ideal_solution_fallback'
            }
        except:
            return {}
    
    def _calculate_wilson_mixing(self, wilson_params: Dict, x1: float, x2: float, T: float) -> Dict:
        """Wilson equation mixing calculations"""
        try:
            A12 = wilson_params.get('A12', 0)
            A21 = wilson_params.get('A21', 0)
            
            Lambda12 = np.exp(-A12 / T)
            Lambda21 = np.exp(-A21 / T)
            
            # Activity coefficients
            ln_gamma1 = -np.log(x1 + x2 * Lambda12) + x2 * (Lambda12 / (x1 + x2 * Lambda12) - Lambda21 / (x2 + x1 * Lambda21))
            ln_gamma2 = -np.log(x2 + x1 * Lambda21) - x1 * (Lambda12 / (x1 + x2 * Lambda12) - Lambda21 / (x2 + x1 * Lambda21))
            
            return {
                'activity_coefficient_1': np.exp(ln_gamma1),
                'activity_coefficient_2': np.exp(ln_gamma2),
                'wilson_parameters': {'Lambda12': Lambda12, 'Lambda21': Lambda21}
            }
        except Exception as e:
            self.logger.debug(f"Wilson mixing failed: {e}")
            return {}
    
    def _calculate_hydrothermal_mineral_solubility(self, component: str, T: float, P: float, compositions: List) -> float:
        """Calculate mineral solubility in hydrothermal fluids"""
        try:
            # Simplified solubility calculation based on T and P
            # This would use real geochemical databases in practice
            base_solubility = 1e-6  # mol/L
            
            # Temperature effect (Arrhenius-type)
            temp_factor = np.exp((T - 298.15) / 50)
            
            # Pressure effect
            pressure_factor = 1 + (P - 101325) / 1e7
            
            return base_solubility * temp_factor * pressure_factor
        except:
            return 1e-6
    
    def _calculate_volatile_partitioning(self, components: List, compositions: List, T: float, P: float) -> Dict:
        """Calculate volatile partitioning in magmatic systems"""
        try:
            partitioning = {}
            
            for i, comp in enumerate(components):
                # Simplified partition coefficients
                if 'H2O' in comp:
                    D = 0.01 * (T / 1273.15)**2
                elif 'CO2' in comp:
                    D = 0.001 * (P / 101325)
                else:
                    D = 0.1
                
                partitioning[comp] = {
                    'partition_coefficient': D,
                    'melt_fraction': compositions[i] / (1 + D),
                    'vapor_fraction': compositions[i] * D / (1 + D)
                }
            
            return partitioning
        except Exception as e:
            self.logger.debug(f"Volatile partitioning failed: {e}")
            return {}

    def _validate_and_quantify_uncertainty(self, compound_data: Dict[str, Any]) -> Dict[str, Any]:
        """Validate data and quantify uncertainty"""
        validation = {
            'data_quality_score': 0.0,
            'completeness': 0.0,
            'consistency_checks': [],
            'uncertainty_estimates': {}
        }
        
        # Calculate completeness
        required_fields = ['molecular_weight', 'critical_temperature', 'critical_pressure']
        present_fields = sum(1 for field in required_fields if field in compound_data and compound_data[field])
        validation['completeness'] = present_fields / len(required_fields)
        
        # Data quality score based on sources
        source_weights = {
            'nist_molecular': 0.3,
            'nist_thermochemical': 0.3,
            'external_sources': 0.2,
            'ml_models': 0.2
        }
        
        quality_score = 0
        for source, weight in source_weights.items():
            if source in compound_data.get('data_sources', []):
                quality_score += weight
        
        validation['data_quality_score'] = quality_score
        
        # Consistency checks
        if 'critical_temperature' in compound_data and 'critical_pressure' in compound_data:
            # Check if critical properties are reasonable
            Tc = compound_data['critical_temperature']
            Pc = compound_data['critical_pressure']
            
            if 50 < Tc < 2000 and 1 < Pc < 1000:
                validation['consistency_checks'].append({'check': 'critical_properties', 'status': 'passed'})
            else:
                validation['consistency_checks'].append({'check': 'critical_properties', 'status': 'warning'})
        
        return validation
    
    def _calculate_data_quality_score(self, webbook_data: Dict, tde_data: Dict, db_data: Dict, ml_results: Dict) -> float:
        """Calculate overall data quality score"""
        score = 0.0
        weights = {'webbook': 0.3, 'tde': 0.3, 'database': 0.2, 'ml': 0.2}
        
        if webbook_data:
            score += weights['webbook']
        if tde_data:
            score += weights['tde']
        if db_data:
            score += weights['database']
        if ml_results and 'confidence' in ml_results:
            score += weights['ml'] * ml_results['confidence']
        
        return min(1.0, score)
    
