        """Load DIPPR correlation equations"""
        correlations = {
            'vapor_pressure': {
                'equation_type': 'Antoine_extended',
                'parameters': ['A', 'B', 'C', 'D', 'E'],
                'form': 'ln(P) = A + B/T + C*ln(T) + D*T^E'
            },
            'liquid_density': {
                'equation_type': 'DIPPR_116',
                'parameters': ['A', 'B', 'C', 'D'],
                'form': 'ρ = A/B^(1+(1-T/C)^D)'
            },
            'vapor_viscosity': {
                'equation_type': 'DIPPR_102',
                'parameters': ['A', 'B', 'C', 'D'],
                'form': 'μ = A*T^B/(1+C/T+D/T^2)'
            },
            'liquid_viscosity': {
                'equation_type': 'DIPPR_101',
                'parameters': ['A', 'B', 'C', 'D', 'E'],
                'form': 'ln(μ) = A + B/T + C*ln(T) + D*T^E'
            },
            'thermal_conductivity': {
                'equation_type': 'DIPPR_102',
                'parameters': ['A', 'B', 'C', 'D'],
                'form': 'k = A*T^B/(1+C/T+D/T^2)'
            },
            'heat_capacity': {
                'equation_type': 'DIPPR_107',
                'parameters': ['A', 'B', 'C', 'D', 'E'],
                'form': 'Cp = A + B*((C/T)/sinh(C/T))^2 + D*((E/T)/cosh(E/T))^2'
            }
        }
        
        # Load specific correlation parameters for geological fluids
        for compound in ['water', 'carbon_dioxide', 'methane', 'hydrogen_sulfide']:
            correlations[compound] = self._get_dippr_compound_parameters(compound)
            
        return correlations
    
