            self.transformer_model = self._build_temporal_transformer()
            self.rf_regressor = RandomForestRegressor(n_estimators=200, random_state=42)
            self.gb_regressor = GradientBoostingRegressor(n_estimators=150, random_state=42)
            
            # Scaling and preprocessing
