            # 3. Seasonal and long-term trends (months to years)
            lf_analysis = await self._analyze_long_term_patterns(temporal_data)
            validation_results['temporal_patterns']['long_term'] = lf_analysis
            
            # 4. Geological time scale analysis (years to millennia)
            geo_analysis = await self._analyze_geological_timescale_patterns(temporal_data)
