    def _build_kriging_model(self):
        """Build custom kriging interpolation model"""
        try:
            from pykrige import OrdinaryKriging
            return OrdinaryKriging
        except ImportError:
            self.logger.warning("PyKrige unavailable, using fallback interpolation")
            return None
    
    def _build_spatial_cnn(self):
        """Build CNN for spatial pattern recognition"""
        if not TORCH_AVAILABLE:
            return None
            
        class SpatialCNN(nn.Module):
            def __init__(self, input_channels=5, output_size=1):
                super().__init__()
                self.conv_layers = nn.Sequential(
                    nn.Conv2d(input_channels, 32, kernel_size=5, padding=2),
                    nn.ReLU(),
                    nn.MaxPool2d(2),
                    nn.Conv2d(32, 64, kernel_size=3, padding=1),
                    nn.ReLU(),
                    nn.MaxPool2d(2),
                    nn.Conv2d(64, 128, kernel_size=3, padding=1),
                    nn.ReLU(),
                    nn.AdaptiveAvgPool2d((4, 4))
                )
                
                self.fc_layers = nn.Sequential(
                    nn.Linear(128 * 4 * 4, 256),
                    nn.ReLU(),
                    nn.Dropout(0.3),
                    nn.Linear(256, 64),
                    nn.ReLU(),
                    nn.Linear(64, output_size)
                )
                
            def forward(self, x):
                x = self.conv_layers(x)
                x = x.view(x.size(0), -1)
                return self.fc_layers(x)
        
        return SpatialCNN()
    
    def _build_spatial_gnn(self):
        """Build Graph Neural Network for spatial relationships"""
        try:
            import torch_geometric.nn as pyg_nn
            from torch_geometric.nn import GCNConv, GraphSAGE, GAT
            
            class SpatialGNN(nn.Module):
                def __init__(self, input_dim=10, hidden_dim=64, output_dim=1):
                    super().__init__()
                    self.conv1 = GCNConv(input_dim, hidden_dim)
                    self.conv2 = GCNConv(hidden_dim, hidden_dim)
                    self.conv3 = GCNConv(hidden_dim, output_dim)
                    self.dropout = nn.Dropout(0.2)
                    
                def forward(self, x, edge_index, edge_weight=None):
                    x = torch.relu(self.conv1(x, edge_index, edge_weight))
                    x = self.dropout(x)
                    x = torch.relu(self.conv2(x, edge_index, edge_weight))
                    x = self.dropout(x)
                    x = self.conv3(x, edge_index, edge_weight)
                    return x
            
            return SpatialGNN()
            
        except ImportError:
            return None
        
    async def validate(self, metrics, geological_context, geo_stats):
        """
        Advanced spatial coherence validation with multi-scale analysis
        """
        try:
            # Extract spatial data from multiple sources
            spatial_data = await self._extract_spatial_data(geological_context)
            
            validation_results = {
                'score': 0.0,
                'confidence': 0.0,
                'details': {},
                'recommendations': [],
                'spatial_patterns': {},
                'coherence_metrics': {},
                'spatial_statistics': {},
                'anomaly_detection': {}
            }
            
            # 1. Local spatial coherence analysis (< 1km)
            local_coherence = await self._analyze_local_coherence(spatial_data)
            validation_results['spatial_patterns']['local'] = local_coherence
            
            # 2. Regional coherence analysis (1-10km)
            regional_coherence = await self._analyze_regional_coherence(spatial_data)
            validation_results['spatial_patterns']['regional'] = regional_coherence
            
            # 3. Large-scale coherence analysis (> 10km)
            large_scale_coherence = await self._analyze_large_scale_coherence(spatial_data)
            validation_results['spatial_patterns']['large_scale'] = large_scale_coherence
            
            # 4. Multi-scale integration analysis
            multi_scale_integration = await self._analyze_multi_scale_integration(
                local_coherence, regional_coherence, large_scale_coherence
            )
            validation_results['details']['multi_scale_integration'] = multi_scale_integration
            
            # 5. Geostatistical analysis
            geostatistical_results = await self._perform_geostatistical_analysis(spatial_data)
            validation_results['spatial_statistics'] = geostatistical_results
            
            # 6. Spatial anomaly detection
            anomaly_results = await self._detect_spatial_anomalies(spatial_data)
            validation_results['anomaly_detection'] = anomaly_results
            
            # 7. Geological structure alignment analysis
            structure_alignment = await self._analyze_geological_structure_alignment(
                spatial_data, geological_context
            )
            validation_results['coherence_metrics']['structure_alignment'] = structure_alignment
            
            # 8. Cross-validation with geological databases
            database_validation = await self._validate_against_geological_databases(
                spatial_data, geological_context
            )
            validation_results['coherence_metrics']['database_validation'] = database_validation
            
            # Calculate overall spatial coherence score
            coherence_scores = [
                local_coherence.get('coherence_score', 0.5),
                regional_coherence.get('coherence_score', 0.5),
                large_scale_coherence.get('coherence_score', 0.5),
                geostatistical_results.get('spatial_continuity', 0.5),
                structure_alignment.get('alignment_score', 0.5)
            ]
            
            validation_results['score'] = np.mean(coherence_scores)
            
            # Calculate confidence based on data quality and consistency
            validation_results['confidence'] = self._calculate_spatial_confidence(
                spatial_data, validation_results
            )
            
            # Generate recommendations
            validation_results['recommendations'] = await self._generate_spatial_recommendations(
                validation_results, geological_context
            )
            
            # Store results in database
            await self._store_spatial_validation_results(validation_results, geological_context)
            
            return validation_results
            
        except Exception as e:
            self.logger.error(f"Spatial validation error: {e}")
            return {
                'score': 0.4,
                'confidence': 0.3,
                'details': {'error': str(e)},
                'recommendations': ['Review spatial data quality', 'Check coordinate systems']
            }
    
    async def _extract_spatial_data(self, geological_context):
        """Extract comprehensive spatial data from multiple sources"""
        spatial_data = {
            'point_locations': [],
            'measurements': [],
            'geological_features': [],
            'structural_elements': [],
            'geophysical_data': [],
            'coordinate_systems': {},
            'spatial_extent': {}
        }
        
        try:
            # Extract location information
            location = geological_context.get('location', [0, 0])
            spatial_extent = geological_context.get('spatial_extent', {
                'min_lat': location[0] - 0.1,
                'max_lat': location[0] + 0.1,
                'min_lon': location[1] - 0.1,
                'max_lon': location[1] + 0.1
            })
            
            # Database queries for spatial geological data
            if hasattr(self, 'db_integration'):
                # Seismic events spatial distribution
                seismic_spatial_query = """
                SELECT ST_X(location) as lon, ST_Y(location) as lat, 
                       magnitude, depth, timestamp
                FROM seismic_events
                WHERE location && ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                AND timestamp > NOW() - INTERVAL '2 years'
                ORDER BY timestamp DESC;
                """
                
                seismic_spatial = await self.db_integration.execute_query(
                    seismic_spatial_query, (
                        spatial_extent['min_lon'], spatial_extent['min_lat'],
                        spatial_extent['max_lon'], spatial_extent['max_lat']
                    )
                )
                spatial_data['point_locations'].extend([
                    {'lat': row['lat'], 'lon': row['lon'], 
                     'value': row['magnitude'], 'type': 'seismic', 'depth': row['depth']}
                    for row in seismic_spatial
                ])
                
                # Geological formations and structures
                geological_structures_query = """
                SELECT ST_X(ST_Centroid(location)) as lon, ST_Y(ST_Centroid(location)) as lat,
                       structure_type, age, properties, length_km
                FROM geological_structures
                WHERE location && ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                ORDER BY age DESC;
                """
                
                geological_structures = await self.db_integration.execute_query(
                    geological_structures_query, (
                        spatial_extent['min_lon'], spatial_extent['min_lat'],
                        spatial_extent['max_lon'], spatial_extent['max_lat']
                    )
                )
                spatial_data['structural_elements'].extend(geological_structures)
                
                # Deformation measurements
                deformation_spatial_query = """
                SELECT ST_X(location) as lon, ST_Y(location) as lat,
                       displacement_mm, velocity_mm_year, measurement_time
                FROM deformation_measurements
                WHERE location && ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                AND measurement_time > NOW() - INTERVAL '1 year'
                ORDER BY measurement_time DESC;
                """
                
                deformation_spatial = await self.db_integration.execute_query(
                    deformation_spatial_query, (
                        spatial_extent['min_lon'], spatial_extent['min_lat'],
                        spatial_extent['max_lon'], spatial_extent['max_lat']
                    )
                )
                spatial_data['measurements'].extend([
                    {'lat': row['lat'], 'lon': row['lon'], 
                     'displacement': row['displacement_mm'], 'velocity': row['velocity_mm_year'],
                     'type': 'deformation', 'timestamp': row['measurement_time']}
                    for row in deformation_spatial
                ])
            
            # External data sources for spatial validation
            if hasattr(self, 'external_connectors'):
                # USGS geological map data
                usgs_geological_data = await self.external_connectors.fetch_geological_map_data(
                    spatial_extent
                )
                spatial_data['geological_features'].extend(usgs_geological_data)
                
                # Topographic and DEM data for terrain analysis
                terrain_data = await self.external_connectors.fetch_terrain_data(spatial_extent)
                spatial_data['terrain'] = terrain_data
            
            spatial_data['spatial_extent'] = spatial_extent
            spatial_data['total_points'] = (
                len(spatial_data['point_locations']) + 
                len(spatial_data['measurements'])
            )
            
        except Exception as e:
            self.logger.warning(f"Spatial data extraction error: {e}")
            
        return spatial_data
    
    async def _analyze_local_coherence(self, spatial_data):
        """Analyze local spatial coherence (< 1km scale)"""
        try:
            from scipy.spatial import cKDTree
            from scipy.stats import pearsonr
            
            coherence_results = {
                'coherence_score': 0.5,
                'local_clustering': {},
                'nearest_neighbor_analysis': {},
                'local_variability': {},
                'hotspot_detection': {}
            }
            
            points = spatial_data.get('point_locations', [])
            if len(points) > 10:
                # Extract coordinates and values
                coords = np.array([[p['lat'], p['lon']] for p in points])
                values = np.array([p.get('value', 0) for p in points])
                
                # Build spatial index
                tree = cKDTree(coords)
                
                # Nearest neighbor analysis
                local_correlations = []
                local_distances = []
                
                for i, point in enumerate(coords):
                    # Find neighbors within 1km (approximately 0.009 degrees)
                    neighbors = tree.query_ball_point(point, r=0.009)
                    
                    if len(neighbors) > 2:
                        neighbor_values = values[neighbors]
                        neighbor_distances = [
                            np.linalg.norm(coords[j] - point) * 111000  # Convert to meters
                            for j in neighbors if j != i
                        ]
                        
                        if len(neighbor_values) > 1 and len(neighbor_distances) > 1:
                            # Calculate local spatial autocorrelation
                            correlation, p_value = pearsonr(neighbor_distances, neighbor_values[1:])
                            if not np.isnan(correlation):
                                local_correlations.append(abs(correlation))
                                local_distances.extend(neighbor_distances)
                
                if local_correlations:
                    coherence_results['coherence_score'] = np.mean(local_correlations)
                    coherence_results['nearest_neighbor_analysis'] = {
                        'average_correlation': np.mean(local_correlations),
                        'correlation_std': np.std(local_correlations),
                        'average_neighbor_distance_m': np.mean(local_distances),
                        'min_distance_m': np.min(local_distances),
                        'max_distance_m': np.max(local_distances)
                    }
                
                # Local clustering analysis using DBSCAN
                if hasattr(self, 'spatial_tools') and len(coords) > 5:
                    clustering = self.spatial_tools['clustering']
                    clusters = clustering.fit_predict(coords)
                    
                    n_clusters = len(set(clusters)) - (1 if -1 in clusters else 0)
                    n_noise = list(clusters).count(-1)
                    
                    coherence_results['local_clustering'] = {
                        'n_clusters': n_clusters,
                        'n_noise_points': n_noise,
                        'clustering_ratio': (len(coords) - n_noise) / len(coords) if len(coords) > 0 else 0,
                        'silhouette_score': self._calculate_silhouette_score(coords, clusters)
                    }
                
                # Local variability assessment
                if len(values) > 5:
                    local_cv = np.std(values) / max(np.mean(values), 1e-10)
                    coherence_results['local_variability'] = {
                        'coefficient_of_variation': local_cv,
                        'value_range': np.max(values) - np.min(values),
                        'outlier_count': len([v for v in values if abs(v - np.mean(values)) > 2 * np.std(values)])
                    }
                    
                    # Adjust coherence score based on variability
                    variability_penalty = min(local_cv / 2.0, 0.3)
                    coherence_results['coherence_score'] = max(
                        0.1, coherence_results['coherence_score'] - variability_penalty
                    )
            
            return coherence_results
            
        except Exception as e:
            self.logger.error(f"Local coherence analysis error: {e}")
            return {'coherence_score': 0.3, 'error': str(e)}
    
    async def _analyze_regional_coherence(self, spatial_data):
        """Analyze regional spatial coherence (1-10km scale)"""
        try:
            from scipy.interpolate import griddata
            from scipy.stats import entropy
            
            coherence_results = {
                'coherence_score': 0.5,
                'regional_trends': {},
                'spatial_continuity': {},
                'gradient_analysis': {},
                'regional_patterns': {}
            }
            
            points = spatial_data.get('point_locations', [])
            measurements = spatial_data.get('measurements', [])
            all_points = points + measurements
            
            if len(all_points) > 20:
                # Extract coordinates and values for regional analysis
                coords = []
                values = []
                
                for point in all_points:
                    coords.append([point['lat'], point['lon']])
                    if 'value' in point:
                        values.append(point['value'])
                    elif 'displacement' in point:
                        values.append(point['displacement'])
                    else:
                        values.append(0)
                
                coords = np.array(coords)
                values = np.array(values)
                
                # Create regional grid for interpolation analysis
                extent = spatial_data.get('spatial_extent', {})
                grid_lat = np.linspace(
                    extent.get('min_lat', coords[:, 0].min()),
                    extent.get('max_lat', coords[:, 0].max()),
                    20
                )
                grid_lon = np.linspace(
                    extent.get('min_lon', coords[:, 1].min()),
                    extent.get('max_lon', coords[:, 1].max()),
                    20
                )
                grid_lats, grid_lons = np.meshgrid(grid_lat, grid_lon)
                
                # Interpolate values to regular grid
                try:
                    grid_values = griddata(
                        coords, values, (grid_lats, grid_lons), 
                        method='linear', fill_value=np.nan
                    )
                    
                    # Calculate regional spatial continuity
                    valid_mask = ~np.isnan(grid_values)
                    if np.sum(valid_mask) > 10:
                        # Gradient analysis
                        grad_lat, grad_lon = np.gradient(grid_values)
                        gradient_magnitude = np.sqrt(grad_lat**2 + grad_lon**2)
                        
                        coherence_results['gradient_analysis'] = {
                            'mean_gradient': np.nanmean(gradient_magnitude),
                            'max_gradient': np.nanmax(gradient_magnitude),
                            'gradient_variability': np.nanstd(gradient_magnitude),
                            'smooth_regions_ratio': np.sum(gradient_magnitude < np.nanpercentile(gradient_magnitude, 25)) / np.sum(valid_mask)
                        }
                        
                        # Regional trend analysis
                        valid_values = grid_values[valid_mask]
                        if len(valid_values) > 5:
                            # Calculate spatial entropy as measure of pattern complexity
                            hist, _ = np.histogram(valid_values, bins=10, density=True)
                            spatial_entropy = entropy(hist + 1e-10)  # Add small constant to avoid log(0)
                            
                            coherence_results['regional_patterns'] = {
                                'spatial_entropy': spatial_entropy,
                                'pattern_complexity': 'high' if spatial_entropy > 2 else 'medium' if spatial_entropy > 1 else 'low',
                                'value_distribution_skew': float(scipy_stats.skew(valid_values)) if len(valid_values) > 3 else 0
                            }
                            
                            # Calculate coherence score based on gradient smoothness and pattern regularity
                            gradient_coherence = 1.0 - min(np.nanmean(gradient_magnitude) / np.nanmax(gradient_magnitude), 1.0)
                            entropy_coherence = max(0, 1.0 - spatial_entropy / 3.0)
                            
                            coherence_results['coherence_score'] = (gradient_coherence + entropy_coherence) / 2
                
                except Exception as interp_e:
                    self.logger.warning(f"Regional interpolation failed: {interp_e}")
                    
                # Alternative: direct distance-based regional correlation
                if len(coords) > 10:
                    regional_correlations = []
                    for i in range(len(coords)):
                        # Find points within regional distance (1-10 km)
                        distances = np.array([
                            np.linalg.norm(coords[j] - coords[i]) * 111000  # Convert to meters
                            for j in range(len(coords)) if j != i
                        ])
                        
                        regional_neighbors = np.where((distances >= 1000) & (distances <= 10000))[0]
                        
                        if len(regional_neighbors) > 2:
                            neighbor_values = values[regional_neighbors]
                            neighbor_distances = distances[regional_neighbors]
                            
                            if len(set(neighbor_values)) > 1:  # Avoid constant values
                                correlation = np.corrcoef(neighbor_distances, neighbor_values)[0, 1]
                                if not np.isnan(correlation):
                                    regional_correlations.append(abs(correlation))
                    
                    if regional_correlations:
                        coherence_results['spatial_continuity'] = {
                            'regional_correlation': np.mean(regional_correlations),
                            'correlation_consistency': 1.0 - np.std(regional_correlations),
                            'n_regional_correlations': len(regional_correlations)
                        }
                        
                        # Update coherence score if not already calculated
                        if coherence_results['coherence_score'] == 0.5:
                            coherence_results['coherence_score'] = np.mean(regional_correlations)
            
            return coherence_results
            
        except Exception as e:
            self.logger.error(f"Regional coherence analysis error: {e}")
            return {'coherence_score': 0.4, 'error': str(e)}
    
    async def _analyze_large_scale_coherence(self, spatial_data):
        """Analyze large-scale spatial coherence (> 10km scale)"""
        try:
            from scipy.stats import linregress
            
            coherence_results = {
                'coherence_score': 0.5,
                'large_scale_trends': {},
                'basin_scale_patterns': {},
                'tectonic_alignment': {},
                'regional_domains': {}
            }
            
            # Large-scale analysis requires broader spatial coverage
            all_points = spatial_data.get('point_locations', []) + spatial_data.get('measurements', [])
            
            if len(all_points) > 50:
                coords = np.array([[p['lat'], p['lon']] for p in all_points])
                values = np.array([p.get('value', p.get('displacement', 0)) for p in all_points])
                
                # Large-scale trend analysis
                # Fit linear trends across the entire domain
                lat_trend = linregress(coords[:, 0], values)
                lon_trend = linregress(coords[:, 1], values)
                
                coherence_results['large_scale_trends'] = {
                    'north_south_trend': {
                        'slope': lat_trend.slope,
                        'r_squared': lat_trend.rvalue**2,
                        'p_value': lat_trend.pvalue,
                        'significance': 'significant' if lat_trend.pvalue < 0.05 else 'not_significant'
                    },
                    'east_west_trend': {
                        'slope': lon_trend.slope,
                        'r_squared': lon_trend.rvalue**2,
                        'p_value': lon_trend.pvalue,
                        'significance': 'significant' if lon_trend.pvalue < 0.05 else 'not_significant'
                    }
                }
                
                # Calculate coherence based on trend consistency
                trend_coherence = max(lat_trend.rvalue**2, lon_trend.rvalue**2)
                coherence_results['coherence_score'] = trend_coherence
                
                # Regional domain analysis using k-means clustering
                if hasattr(self, 'spatial_tools'):
                    try:
                        kmeans = self.spatial_tools['kmeans']
                        domain_labels = kmeans.fit_predict(coords)
                        
                        # Analyze domain characteristics
                        n_domains = len(set(domain_labels))
                        domain_stats = {}
                        
                        for domain_id in set(domain_labels):
                            domain_mask = domain_labels == domain_id
                            domain_values = values[domain_mask]
                            domain_coords = coords[domain_mask]
                            
                            if len(domain_values) > 3:
                                domain_stats[f'domain_{domain_id}'] = {
                                    'n_points': len(domain_values),
                                    'mean_value': np.mean(domain_values),
                                    'std_value': np.std(domain_values),
                                    'centroid': np.mean(domain_coords, axis=0).tolist(),
                                    'spatial_extent_km': self._calculate_domain_extent(domain_coords)
                                }
                        
                        coherence_results['regional_domains'] = {
                            'n_domains': n_domains,
                            'domain_statistics': domain_stats,
                            'domain_separation_quality': self._calculate_domain_separation(coords, domain_labels, values)
                        }
                        
                    except Exception as cluster_e:
                        self.logger.warning(f"Domain clustering failed: {cluster_e}")
                
                # Tectonic alignment analysis
                structural_elements = spatial_data.get('structural_elements', [])
                if structural_elements:
                    alignment_results = await self._analyze_tectonic_alignment(
                        coords, values, structural_elements
                    )
                    coherence_results['tectonic_alignment'] = alignment_results
            
            return coherence_results
            
        except Exception as e:
            self.logger.error(f"Large-scale coherence analysis error: {e}")
            return {'coherence_score': 0.4, 'error': str(e)}
    
    def _calculate_domain_extent(self, coords):
        """Calculate spatial extent of a domain in kilometers"""
        if len(coords) < 2:
            return 0
        
        lat_range = np.max(coords[:, 0]) - np.min(coords[:, 0])
        lon_range = np.max(coords[:, 1]) - np.min(coords[:, 1])
        
        # Convert to approximate kilometers (rough approximation)
        lat_km = lat_range * 111
        lon_km = lon_range * 111 * np.cos(np.radians(np.mean(coords[:, 0])))
        
        return np.sqrt(lat_km**2 + lon_km**2)
    
    def _calculate_domain_separation(self, coords, labels, values):
        """Calculate quality of domain separation"""
        try:
            from scipy.stats import f_oneway
            
            unique_labels = list(set(labels))
            if len(unique_labels) < 2:
                return 0
            
            domain_values = [values[labels == label] for label in unique_labels]
            
            # ANOVA test for significant differences between domains
            if all(len(dv) > 1 for dv in domain_values):
                f_stat, p_value = f_oneway(*domain_values)
                return 1.0 - p_value if not np.isnan(p_value) else 0.5
            
            return 0.5
            
        except Exception:
            return 0.5
    
    async def _analyze_tectonic_alignment(self, coords, values, structural_elements):
        """Analyze alignment with known tectonic structures"""
        try:
            alignment_results = {
                'structure_correlation': 0.5,
                'alignment_score': 0.5,
                'structure_influence': {}
            }
            
            if not structural_elements:
                return alignment_results
            
            # Calculate distances from measurement points to structural elements
            structure_distances = []
            structure_influences = []
            
            for struct in structural_elements:
                struct_lat = struct.get('lat', 0)
                struct_lon = struct.get('lon', 0)
                struct_type = struct.get('structure_type', 'unknown')
                
                if struct_lat != 0 and struct_lon != 0:
                    # Calculate distances from all measurement points to this structure
                    distances = np.array([
                        np.linalg.norm([coord[0] - struct_lat, coord[1] - struct_lon]) * 111000
                        for coord in coords
                    ])
                    
                    # Analyze correlation between distance and measured values
                    if len(distances) > 5 and len(set(values)) > 1:
                        correlation = np.corrcoef(distances, values)[0, 1]
                        if not np.isnan(correlation):
                            structure_distances.append(np.mean(distances))
                            structure_influences.append(abs(correlation))
                            
                            alignment_results['structure_influence'][struct_type] = {
                                'correlation': correlation,
                                'mean_distance_m': np.mean(distances),
                                'min_distance_m': np.min(distances)
                            }
            
            if structure_influences:
                alignment_results['structure_correlation'] = np.mean(structure_influences)
                alignment_results['alignment_score'] = np.mean(structure_influences)
            
            return alignment_results
            
        except Exception as e:
            self.logger.error(f"Tectonic alignment analysis error: {e}")
            return {'structure_correlation': 0.4, 'alignment_score': 0.4}
    
    async def _analyze_multi_scale_integration(self, local_coherence, regional_coherence, large_scale_coherence):
        """Analyze integration across multiple spatial scales"""
        try:
            integration_results = {
                'scale_consistency': 0.5,
                'scale_coupling': {},
                'emergent_patterns': {},
                'hierarchical_structure': {}
            }
            
            # Extract coherence scores
            local_score = local_coherence.get('coherence_score', 0.5)
            regional_score = regional_coherence.get('coherence_score', 0.5)
            large_scale_score = large_scale_coherence.get('coherence_score', 0.5)
            
            scores = np.array([local_score, regional_score, large_scale_score])
            
            # Scale consistency analysis
            scale_variance = np.std(scores)
            integration_results['scale_consistency'] = max(0, 1.0 - scale_variance)
            
            # Cross-scale coupling analysis
            integration_results['scale_coupling'] = {
                'local_regional_coupling': abs(np.corrcoef([local_score], [regional_score])[0, 1]) if not np.isnan(local_score) and not np.isnan(regional_score) else 0,
                'regional_large_coupling': abs(np.corrcoef([regional_score], [large_scale_score])[0, 1]) if not np.isnan(regional_score) and not np.isnan(large_scale_score) else 0,
                'local_large_coupling': abs(np.corrcoef([local_score], [large_scale_score])[0, 1]) if not np.isnan(local_score) and not np.isnan(large_scale_score) else 0
            }
            
            # Hierarchical structure analysis
            integration_results['hierarchical_structure'] = {
                'dominant_scale': ['local', 'regional', 'large_scale'][np.argmax(scores)],
                'scale_hierarchy': np.argsort(scores)[::-1].tolist(),
                'scale_dominance_ratio': np.max(scores) / max(np.mean(scores), 0.1)
            }
            
            # Emergent pattern detection
            pattern_complexity = np.sum(scores > 0.7) / len(scores)
            integration_results['emergent_patterns'] = {
                'high_coherence_scales': int(np.sum(scores > 0.7)),
                'pattern_complexity': pattern_complexity,
                'multi_scale_coherence': 'high' if pattern_complexity > 0.66 else 'medium' if pattern_complexity > 0.33 else 'low'
            }
            
            return integration_results
            
        except Exception as e:
            self.logger.error(f"Multi-scale integration analysis error: {e}")
            return {'scale_consistency': 0.4, 'error': str(e)}
    
    async def _perform_geostatistical_analysis(self, spatial_data):
        """Perform comprehensive geostatistical analysis"""
        try:
            from scipy.stats import normaltest
            
            geostat_results = {
                'spatial_continuity': 0.5,
                'variogram_analysis': {},
                'stationarity_tests': {},
                'anisotropy_analysis': {},
                'statistical_properties': {}
            }
            
            all_points = spatial_data.get('point_locations', []) + spatial_data.get('measurements', [])
            
            if len(all_points) > 30:
                coords = np.array([[p['lat'], p['lon']] for p in all_points])
                values = np.array([p.get('value', p.get('displacement', 0)) for p in all_points])
                
                # Basic statistical properties
                geostat_results['statistical_properties'] = {
                    'mean': np.mean(values),
                    'variance': np.var(values),
                    'skewness': float(scipy_stats.skew(values)),
                    'kurtosis': float(scipy_stats.kurtosis(values)),
                    'coefficient_of_variation': np.std(values) / max(abs(np.mean(values)), 1e-10)
                }
                
                # Normality test
                try:
                    normality_stat, normality_p = normaltest(values)
                    geostat_results['statistical_properties']['normality'] = {
                        'statistic': normality_stat,
                        'p_value': normality_p,
                        'is_normal': normality_p > 0.05
                    }
                except Exception:
                    pass
                
                # Empirical variogram calculation
                variogram_results = await self._calculate_empirical_variogram(coords, values)
                geostat_results['variogram_analysis'] = variogram_results
                
                # Spatial continuity assessment
                if 'range' in variogram_results:
                    spatial_range = variogram_results['range']
                    nugget = variogram_results.get('nugget', 0)
                    sill = variogram_results.get('sill', 1)
                    
                    # Continuity based on nugget-to-sill ratio
                    continuity_ratio = max(0, (sill - nugget) / max(sill, 1e-10))
                    geostat_results['spatial_continuity'] = continuity_ratio
                
                # Anisotropy analysis
                anisotropy_results = await self._analyze_spatial_anisotropy(coords, values)
                geostat_results['anisotropy_analysis'] = anisotropy_results
            
            return geostat_results
            
        except Exception as e:
            self.logger.error(f"Geostatistical analysis error: {e}")
            return {'spatial_continuity': 0.4, 'error': str(e)}
    
    async def _calculate_empirical_variogram(self, coords, values):
        """Calculate empirical variogram"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            variogram_results = {
                'lag_distances': [],
                'semivariances': [],
                'n_pairs': [],
                'range': 0,
                'sill': 0,
                'nugget': 0
            }
            
            # Calculate all pairwise distances and semivariances
            distances = squareform(pdist(coords)) * 111000  # Convert to meters
            value_diffs = np.abs(np.subtract.outer(values, values))
            semivariances = 0.5 * value_diffs**2
            
            # Create lag bins
            max_distance = np.max(distances[distances < np.inf])
            n_lags = min(15, int(max_distance / 1000))  # 1km lag spacing
            lag_bins = np.linspace(0, max_distance, n_lags + 1)
            
            for i in range(n_lags):
                lag_min = lag_bins[i]
                lag_max = lag_bins[i + 1]
                
                # Find pairs within this lag bin
                mask = (distances >= lag_min) & (distances < lag_max) & (distances > 0)
                
                if np.sum(mask) > 10:  # Require minimum number of pairs
                    lag_semivariances = semivariances[mask]
                    lag_distance = np.mean(distances[mask])
                    
                    variogram_results['lag_distances'].append(lag_distance)
                    variogram_results['semivariances'].append(np.mean(lag_semivariances))
                    variogram_results['n_pairs'].append(np.sum(mask) // 2)  # Each pair counted twice
            
            # Fit simple variogram model if we have enough points
            if len(variogram_results['semivariances']) > 3:
                semivar_array = np.array(variogram_results['semivariances'])
                
                # Estimate nugget (y-intercept), sill (plateau), and range
                variogram_results['nugget'] = semivar_array[0] if len(semivar_array) > 0 else 0
                variogram_results['sill'] = np.max(semivar_array) if len(semivar_array) > 0 else 1
                
                # Rough range estimate (distance at ~95% of sill)
                target_semivar = 0.95 * variogram_results['sill']
                range_indices = np.where(semivar_array >= target_semivar)[0]
                if len(range_indices) > 0:
                    variogram_results['range'] = variogram_results['lag_distances'][range_indices[0]]
                else:
                    variogram_results['range'] = max(variogram_results['lag_distances']) if variogram_results['lag_distances'] else 1000
            
            return variogram_results
            
        except Exception as e:
            self.logger.error(f"Variogram calculation error: {e}")
            return {'range': 1000, 'sill': 1, 'nugget': 0}
    
    async def _analyze_spatial_anisotropy(self, coords, values):
        """Analyze spatial anisotropy in the data"""
        try:
            anisotropy_results = {
                'anisotropy_ratio': 1.0,
                'principal_directions': {},
                'directional_variograms': {}
            }
            
            if len(coords) > 20:
                # Calculate directional variograms in different directions
                directions = [0, 45, 90, 135]  # degrees
                directional_ranges = []
                
                for direction in directions:
                    dir_variogram = await self._calculate_directional_variogram(
                        coords, values, direction, tolerance=22.5
                    )
                    anisotropy_results['directional_variograms'][f'{direction}_degrees'] = dir_variogram
                    
                    if 'range' in dir_variogram:
                        directional_ranges.append(dir_variogram['range'])
                
                # Calculate anisotropy ratio
                if len(directional_ranges) >= 2:
                    max_range = max(directional_ranges)
                    min_range = min(directional_ranges)
                    anisotropy_results['anisotropy_ratio'] = max_range / max(min_range, 1)
                    
                    # Identify principal directions
                    max_dir = directions[np.argmax(directional_ranges)]
                    min_dir = directions[np.argmin(directional_ranges)]
                    
                    anisotropy_results['principal_directions'] = {
                        'maximum_continuity_direction': max_dir,
                        'minimum_continuity_direction': min_dir,
                        'anisotropy_classification': (
                            'strong' if anisotropy_results['anisotropy_ratio'] > 3 else
                            'moderate' if anisotropy_results['anisotropy_ratio'] > 1.5 else
                            'weak'
                        )
                    }
            
            return anisotropy_results
            
        except Exception as e:
            self.logger.error(f"Anisotropy analysis error: {e}")
            return {'anisotropy_ratio': 1.0}
    
    async def _calculate_directional_variogram(self, coords, values, direction, tolerance=22.5):
        """Calculate variogram in a specific direction"""
        try:
            from scipy.spatial.distance import pdist, squareform
            
            # Convert direction to radians
            dir_rad = np.radians(direction)
            tol_rad = np.radians(tolerance)
            
            # Calculate all pairwise vectors
            n_points = len(coords)
            directional_pairs = []
            
            for i in range(n_points):
                for j in range(i + 1, n_points):
                    vector = coords[j] - coords[i]
                    angle = np.arctan2(vector[1], vector[0])
                    
                    # Normalize angle to [0, π]
                    if angle < 0:
                        angle += np.pi
                    if dir_rad < 0:
                        dir_rad += np.pi
                    
                    # Check if angle is within tolerance of direction
                    angle_diff = min(abs(angle - dir_rad), abs(angle - dir_rad + np.pi))
                    
                    if angle_diff <= tol_rad:
                        distance = np.linalg.norm(vector) * 111000  # Convert to meters
                        semivariance = 0.5 * (values[i] - values[j])**2
                        directional_pairs.append((distance, semivariance))
            
            if len(directional_pairs) > 5:
                distances, semivariances = zip(*directional_pairs)
                
                # Simple range estimation
                max_distance = max(distances)
                max_semivariance = max(semivariances)
                
                return {
                    'range': max_distance * 0.6,  # Rough approximation
                    'sill': max_semivariance,
                    'nugget': min(semivariances),
                    'n_pairs': len(directional_pairs)
                }
            
            return {'range': 1000, 'sill': 1, 'nugget': 0, 'n_pairs': 0}
            
        except Exception as e:
            self.logger.error(f"Directional variogram error: {e}")
            return {'range': 1000, 'sill': 1, 'nugget': 0}
    
    async def _detect_spatial_anomalies(self, spatial_data):
        """Detect spatial anomalies using multiple methods"""
        try:
            from scipy.stats import zscore
            from sklearn.ensemble import IsolationForest
            
            anomaly_results = {
                'anomaly_points': [],
                'anomaly_clusters': [],
                'statistical_outliers': {},
                'spatial_outliers': {},
                'anomaly_score': 0.0
            }
            
            all_points = spatial_data.get('point_locations', []) + spatial_data.get('measurements', [])
            
            if len(all_points) > 10:
                coords = np.array([[p['lat'], p['lon']] for p in all_points])
                values = np.array([p.get('value', p.get('displacement', 0)) for p in all_points])
                
                # Statistical outlier detection
                if len(values) > 3:
                    z_scores = np.abs(zscore(values))
                    statistical_outliers = np.where(z_scores > 2.5)[0]
                    
                    anomaly_results['statistical_outliers'] = {
                        'n_outliers': len(statistical_outliers),
                        'outlier_indices': statistical_outliers.tolist(),
                        'outlier_z_scores': z_scores[statistical_outliers].tolist(),
                        'outlier_threshold': 2.5
                    }
                
                # Isolation Forest for multivariate anomaly detection
                if len(all_points) > 20:
                    try:
                        # Combine spatial and value features
                        features = np.column_stack([coords, values])
                        
                        iso_forest = IsolationForest(contamination=0.1, random_state=42)
                        anomaly_labels = iso_forest.fit_predict(features)
                        anomaly_scores = iso_forest.score_samples(features)
                        
                        # Find anomalous points
                        anomalous_indices = np.where(anomaly_labels == -1)[0]
                        
                        anomaly_results['spatial_outliers'] = {
                            'n_anomalies': len(anomalous_indices),
                            'anomalous_indices': anomalous_indices.tolist(),
                            'anomaly_scores': anomaly_scores[anomalous_indices].tolist(),
                            'mean_anomaly_score': np.mean(anomaly_scores[anomalous_indices]) if len(anomalous_indices) > 0 else 0
                        }
                        
                        # Overall anomaly score
                        anomaly_results['anomaly_score'] = len(anomalous_indices) / len(all_points)
                        
                    except Exception as iso_e:
                        self.logger.warning(f"Isolation forest failed: {iso_e}")
                
                # Spatial clustering of anomalies
                all_anomaly_indices = set()
                if 'outlier_indices' in anomaly_results['statistical_outliers']:
                    all_anomaly_indices.update(anomaly_results['statistical_outliers']['outlier_indices'])
                if 'anomalous_indices' in anomaly_results['spatial_outliers']:
                    all_anomaly_indices.update(anomaly_results['spatial_outliers']['anomalous_indices'])
                
                if len(all_anomaly_indices) > 2:
                    anomaly_coords = coords[list(all_anomaly_indices)]
                    
                    # Simple clustering of anomalies
                    if hasattr(self, 'spatial_tools'):
                        try:
                            clustering = self.spatial_tools['clustering']
                            anomaly_clusters = clustering.fit_predict(anomaly_coords)
                            
                            n_clusters = len(set(anomaly_clusters)) - (1 if -1 in anomaly_clusters else 0)
                            
                            anomaly_results['anomaly_clusters'] = {
                                'n_anomaly_clusters': n_clusters,
                                'cluster_labels': anomaly_clusters.tolist(),
                                'clustered_anomalies': len(anomaly_clusters[anomaly_clusters != -1])
                            }
                            
                        except Exception as cluster_e:
                            self.logger.warning(f"Anomaly clustering failed: {cluster_e}")
            
            return anomaly_results
            
        except Exception as e:
            self.logger.error(f"Spatial anomaly detection error: {e}")
            return {'anomaly_score': 0.1, 'error': str(e)}
    
    def _calculate_silhouette_score(self, coords, labels):
        """Calculate silhouette score for clustering"""
        try:
            from sklearn.metrics import silhouette_score
            
            if len(set(labels)) > 1 and len(labels) > 2:
                # Filter out noise points (label -1)
                mask = labels != -1
                if np.sum(mask) > 2:
                    return silhouette_score(coords[mask], labels[mask])
            
            return 0.0
            
        except Exception:
            return 0.0
    
    def _custom_spatial_interpolator(self, coords, values, grid_coords):
        """Custom weighted spatial interpolation"""
        try:
            interpolated = np.zeros(len(grid_coords))
            
            for i, grid_point in enumerate(grid_coords):
                distances = np.array([
                    np.linalg.norm(coord - grid_point) for coord in coords
                ])
                
                # Inverse distance weighting with power of 2
                weights = 1.0 / (distances**2 + 1e-10)  # Add small constant to avoid division by zero
                weighted_values = weights * values
                
                interpolated[i] = np.sum(weighted_values) / np.sum(weights)
            
            return interpolated
            
        except Exception as e:
            self.logger.error(f"Custom interpolation error: {e}")
            return np.zeros(len(grid_coords))
    
    async def _analyze_geological_structure_alignment(self, spatial_data, geological_context):
        """Analyze alignment with known geological structures"""
        try:
            alignment_results = {
                'alignment_score': 0.5,
                'structure_correlations': {},
                'geological_control': {},
                'structural_influence_zones': {}
            }
            
            # This would typically query geological databases for known structures
            if hasattr(self, 'db_integration'):
                # Query for major geological structures in the region
                location = geological_context.get('location', [0, 0])
                extent = spatial_data.get('spatial_extent', {})
                
                structure_query = """
                SELECT ST_X(ST_Centroid(location)) as lon, ST_Y(ST_Centroid(location)) as lat,
                       structure_type, age, length_km, strike, dip
                FROM geological_structures
                WHERE location && ST_MakeEnvelope(%s, %s, %s, %s, 4326)
                ORDER BY length_km DESC;
                """
                
                structures = await self.db_integration.execute_query(
                    structure_query, (
                        extent.get('min_lon', location[1] - 0.1),
                        extent.get('min_lat', location[0] - 0.1),
                        extent.get('max_lon', location[1] + 0.1),
                        extent.get('max_lat', location[0] + 0.1)
                    )
                )
                
                if structures:
                    alignment_results['structural_influence_zones'] = {
                        'n_structures': len(structures),
                        'major_structures': [s for s in structures if s.get('length_km', 0) > 10],
                        'structure_types': list(set(s.get('structure_type', 'unknown') for s in structures))
                    }
                    
                    # Analyze spatial correlation with structures
                    all_points = spatial_data.get('point_locations', []) + spatial_data.get('measurements', [])
                    if all_points and structures:
                        structure_correlations = []
                        
                        for struct in structures:
                            struct_coord = np.array([struct['lat'], struct['lon']])
                            
                            # Calculate distances from all points to this structure
                            point_distances = []
                            point_values = []
                            
                            for point in all_points:
                                point_coord = np.array([point['lat'], point['lon']])
                                distance = np.linalg.norm(point_coord - struct_coord) * 111000  # to meters
                                value = point.get('value', point.get('displacement', 0))
                                
                                point_distances.append(distance)
                                point_values.append(value)
                            
                            # Calculate correlation between distance to structure and measured values
                            if len(point_distances) > 5 and len(set(point_values)) > 1:
                                correlation = np.corrcoef(point_distances, point_values)[0, 1]
                                if not np.isnan(correlation):
                                    structure_correlations.append(abs(correlation))
                                    
                                    alignment_results['structure_correlations'][struct.get('structure_type', 'unknown')] = {
                                        'correlation': correlation,
                                        'structure_length_km': struct.get('length_km', 0),
                                        'mean_distance_to_points_m': np.mean(point_distances)
                                    }
                        
                        if structure_correlations:
                            alignment_results['alignment_score'] = np.mean(structure_correlations)
            
            return alignment_results
            
        except Exception as e:
            self.logger.error(f"Structure alignment analysis error: {e}")
            return {'alignment_score': 0.4, 'error': str(e)}
    
    async def _validate_against_geological_databases(self, spatial_data, geological_context):
        """Cross-validate spatial patterns against external geological databases"""
        try:
            validation_results = {
                'database_consistency': 0.5,
                'external_correlations': {},
                'data_quality_assessment': {},
                'reference_comparisons': {}
            }
            
            # External validation using USGS and other geological databases
            if hasattr(self, 'external_connectors'):
                try:
                    # Fetch reference geological data
                    extent = spatial_data.get('spatial_extent', {})
                    
                    # USGS geological formations
                    usgs_formations = await self.external_connectors.fetch_geological_formations(extent)
                    
                    # Compare spatial patterns with reference data
                    if usgs_formations:
                        all_points = spatial_data.get('point_locations', []) + spatial_data.get('measurements', [])
                        
                        if all_points:
                            consistency_scores = []
                            
                            for formation in usgs_formations:
                                formation_center = np.array([formation.get('lat', 0), formation.get('lon', 0)])
                                
                                # Find nearby measurement points
                                nearby_points = []
                                for point in all_points:
                                    point_coord = np.array([point['lat'], point['lon']])
                                    distance = np.linalg.norm(point_coord - formation_center) * 111000
                                    
                                    if distance < 5000:  # Within 5km
                                        nearby_points.append(point)
                                
                                if len(nearby_points) > 3:
                                    # Assess consistency with expected geological properties
                                    values = [p.get('value', p.get('displacement', 0)) for p in nearby_points]
                                    expected_range = formation.get('expected_value_range', [0, 1])
                                    
                                    # Calculate how many points fall within expected range
                                    in_range_count = sum(
                                        expected_range[0] <= v <= expected_range[1] for v in values
                                    )
                                    consistency_score = in_range_count / len(values)
                                    consistency_scores.append(consistency_score)
                                    
                                    validation_results['reference_comparisons'][formation.get('name', 'unknown')] = {
                                        'consistency_score': consistency_score,
                                        'n_nearby_points': len(nearby_points),
                                        'expected_range': expected_range,
                                        'observed_range': [min(values), max(values)]
                                    }
                            
                            if consistency_scores:
                                validation_results['database_consistency'] = np.mean(consistency_scores)
                    
                except Exception as ext_e:
                    self.logger.warning(f"External validation failed: {ext_e}")
            
            return validation_results
            
        except Exception as e:
            self.logger.error(f"Database validation error: {e}")
            return {'database_consistency': 0.4, 'error': str(e)}
    
    def _calculate_spatial_confidence(self, spatial_data, validation_results):
        """Calculate overall confidence in spatial analysis"""
        try:
            confidence_factors = []
            
            # Data density factor
            total_points = spatial_data.get('total_points', 0)
            extent = spatial_data.get('spatial_extent', {})
            
            if extent:
                lat_range = extent.get('max_lat', 0) - extent.get('min_lat', 0)
                lon_range = extent.get('max_lon', 0) - extent.get('min_lon', 0)
                area_deg2 = lat_range * lon_range
                
                if area_deg2 > 0:
                    point_density = total_points / area_deg2
                    density_confidence = min(1.0, point_density / 100)  # Normalize to reasonable density
                    confidence_factors.append(density_confidence)
            
            # Pattern consistency factor
            spatial_patterns = validation_results.get('spatial_patterns', {})
            pattern_scores = []
            for scale in ['local', 'regional', 'large_scale']:
                pattern = spatial_patterns.get(scale, {})
                if 'coherence_score' in pattern:
                    pattern_scores.append(pattern['coherence_score'])
            
            if pattern_scores:
                pattern_consistency = 1.0 - np.std(pattern_scores) / max(np.mean(pattern_scores), 0.1)
                confidence_factors.append(max(0, pattern_consistency))
            
            # Geostatistical confidence
            geostat = validation_results.get('spatial_statistics', {})
            if 'spatial_continuity' in geostat:
                confidence_factors.append(geostat['spatial_continuity'])
            
            # Anomaly detection confidence (inverse relationship - fewer anomalies = higher confidence)
            anomalies = validation_results.get('anomaly_detection', {})
            anomaly_score = anomalies.get('anomaly_score', 0.1)
            anomaly_confidence = max(0, 1.0 - anomaly_score * 2)  # Scale anomaly impact
            confidence_factors.append(anomaly_confidence)
            
            # Database validation confidence
            db_validation = validation_results.get('coherence_metrics', {}).get('database_validation', {})
            if 'database_consistency' in db_validation:
                confidence_factors.append(db_validation['database_consistency'])
            
            return np.mean(confidence_factors) if confidence_factors else 0.5
            
        except Exception as e:
            self.logger.error(f"Confidence calculation error: {e}")
            return 0.5
    
    async def _generate_spatial_recommendations(self, validation_results, geological_context):
        """Generate actionable recommendations based on spatial analysis"""
        recommendations = []
        
        try:
            overall_score = validation_results.get('score', 0.5)
            confidence = validation_results.get('confidence', 0.5)
            
            # Score-based recommendations
            if overall_score < 0.4:
                recommendations.extend([
                    "Increase spatial sampling density for better coherence analysis",
                    "Investigate potential data quality issues in spatial measurements",
                    "Consider alternative spatial interpolation methods",
                    "Validate coordinate systems and spatial referencing"
                ])
            elif overall_score < 0.7:
                recommendations.extend([
                    "Enhance spatial coverage in low-coherence areas",
                    "Implement targeted sampling in anomalous regions",
                    "Consider multi-scale spatial analysis integration"
                ])
            else:
                recommendations.extend([
                    "Maintain current spatial sampling strategy",
                    "Consider predictive spatial modeling based on coherence patterns"
                ])
            
            # Confidence-based recommendations
            if confidence < 0.5:
                recommendations.extend([
                    "Increase data density for more reliable spatial analysis",
                    "Validate results with independent spatial datasets",
                    "Consider uncertainty quantification in spatial predictions"
                ])
            
            # Pattern-specific recommendations
            spatial_patterns = validation_results.get('spatial_patterns', {})
            
            local_patterns = spatial_patterns.get('local', {})
            if local_patterns.get('coherence_score', 0.5) < 0.4:
                recommendations.append("Investigate local-scale spatial variability sources")
            
            regional_patterns = spatial_patterns.get('regional', {})
            if regional_patterns.get('coherence_score', 0.5) < 0.4:
                recommendations.append("Analyze regional geological controls on spatial patterns")
            
            # Anomaly-based recommendations
            anomalies = validation_results.get('anomaly_detection', {})
            anomaly_score = anomalies.get('anomaly_score', 0.1)
            
            if anomaly_score > 0.2:
                recommendations.extend([
                    "Investigate high anomaly density - potential data quality issues",
                    "Focus additional sampling on anomalous spatial regions",
                    "Consider geological processes causing spatial anomalies"
                ])
            
            # Multi-scale integration recommendations
            integration = validation_results.get('details', {}).get('multi_scale_integration', {})
            scale_consistency = integration.get('scale_consistency', 0.5)
            
            if scale_consistency < 0.5:
                recommendations.append("Improve cross-scale spatial analysis integration")
            
            # Geostatistical recommendations
            geostat = validation_results.get('spatial_statistics', {})
            variogram = geostat.get('variogram_analysis', {})
            
            if variogram.get('nugget', 0) / max(variogram.get('sill', 1), 0.1) > 0.5:
                recommendations.append("High nugget effect detected - consider measurement error reduction")
            
            anisotropy = geostat.get('anisotropy_analysis', {})
            if anisotropy.get('anisotropy_ratio', 1) > 3:
                recommendations.append("Strong spatial anisotropy detected - consider directional sampling strategies")
            
        except Exception as e:
            self.logger.error(f"Spatial recommendation generation error: {e}")
            recommendations.append("Review spatial analysis implementation for potential issues")
        
        return recommendations
    
    async def _store_spatial_validation_results(self, validation_results, geological_context):
        """Store spatial validation results in database"""
        try:
            if hasattr(self, 'db_integration'):
                insert_query = """
                INSERT INTO spatial_geological_validation 
                (location, validation_score, confidence, spatial_patterns_data, 
                 coherence_metrics, recommendations, created_at)
                VALUES (ST_Point(%s, %s), %s, %s, %s, %s, %s, NOW())
                RETURNING id;
                """
                
                location = geological_context.get('location', [0, 0])
                patterns_json = json.dumps(validation_results.get('spatial_patterns', {}))
                coherence_json = json.dumps(validation_results.get('coherence_metrics', {}))
                recommendations_json = json.dumps(validation_results.get('recommendations', []))
                
                result = await self.db_integration.execute_query(
                    insert_query, (
                        location[1], location[0],
                        validation_results.get('score', 0),
                        validation_results.get('confidence', 0),
                        patterns_json,
                        coherence_json,
                        recommendations_json
                    )
                )
                
                if result:
                    self.logger.info(f"Stored spatial validation results with ID: {result[0]['id']}")
                    
        except Exception as e:
            self.logger.warning(f"Failed to store spatial validation results: {e}")
    
