    async def _update_intervention_model_performance(self, predictions: Dict[str, Any],
                                                   feasibility: Dict[str, Any]):
        """Update intervention model performance metrics."""
        try:
            if not hasattr(self, 'intervention_performance_metrics'):
                self.intervention_performance_metrics = {
                    'prediction_accuracy': 0.5,
                    'feasibility_alignment': 0.5,
                    'confidence_calibration': 0.5,
                    'total_predictions': 0
                }
            
            # Update performance metrics
            current_confidence = predictions.get('confidence', 0.5)
            current_feasibility = feasibility.get('overall_feasibility', 0.5)
            
            # Update using exponential moving average
            alpha = 0.1
            self.intervention_performance_metrics['prediction_accuracy'] = (
                alpha * current_confidence +
                (1 - alpha) * self.intervention_performance_metrics['prediction_accuracy']
            )
            
            self.intervention_performance_metrics['feasibility_alignment'] = (
                alpha * current_feasibility +
                (1 - alpha) * self.intervention_performance_metrics['feasibility_alignment']
            )
            
            self.intervention_performance_metrics['confidence_calibration'] = (
                alpha * abs(current_confidence - current_feasibility) +
                (1 - alpha) * self.intervention_performance_metrics['confidence_calibration']
            )
            
            self.intervention_performance_metrics['total_predictions'] += 1
            
            # Store performance metrics in model database
            if hasattr(self, 'model_database'):
                await self.model_database.store_performance_metrics(
                    model_id='intervention_exploration',
                    metrics=self.intervention_performance_metrics,
                    timestamp=datetime.now().isoformat()
                )
            
        except Exception as e:
            self.logger.error(f"Failed to update intervention model performance: {e}")
    
