    def _parse_petdb_composition(self, petdb_data, geological_context):
        """Parse PetDB API response for composition data"""
        try:
            # Parse actual PetDB response structure
            if isinstance(petdb_data, dict) and 'results' in petdb_data:
                results = petdb_data['results']
                if results:
                    # Extract major elements from first result
                    sample = results[0]
                    major_elements = {}
                    for element in ['SiO2', 'Al2O3', 'Fe2O3', 'MgO', 'CaO', 'Na2O', 'K2O']:
                        if element.lower() in sample:
                            major_elements[element] = sample[element.lower()]
                    
                    return {
                        'major_elements': major_elements,
                        'data_quality': 'petdb_real',
                        'sample_count': len(results)
                    }
            
            # Fallback to synthetic data if parsing fails
            return self._generate_synthetic_petdb_data(geological_context)
            
        except Exception as e:
            self.logger.warning(f"PetDB data parsing failed: {e}")
            return self._generate_synthetic_petdb_data(geological_context)
    
    def _calculate_mineral_stability(self, mineral_assemblage, location, **kwargs):
        """Calculate thermodynamic stability of mineral assemblage"""
        try:
            import numpy as np
            
            temperature = kwargs.get('temperature', 298.15)
            pressure = kwargs.get('pressure', 0.1)
            
            # Get stable assemblage
            stable_minerals = mineral_assemblage.get('stable_assemblage', {})
            
            # Calculate stability metrics for each mineral
            stability_metrics = {}
            for mineral, abundance in stable_minerals.items():
                
                # Temperature stability
                temp_stability = self._calculate_temperature_stability(
                    mineral, temperature, abundance
                )
                
                # Pressure stability  
                pressure_stability = self._calculate_pressure_stability(
                    mineral, pressure, abundance
                )
                
                # Chemical potential stability
                chemical_stability = self._calculate_chemical_stability(
                    mineral, stable_minerals, temperature, pressure
                )
                
                # Overall stability score
                overall_stability = (temp_stability + pressure_stability + chemical_stability) / 3.0
                
                stability_metrics[mineral] = {
                    'temperature_stability': temp_stability,
                    'pressure_stability': pressure_stability, 
                    'chemical_stability': chemical_stability,
                    'overall_stability': overall_stability
                }
            
            # Calculate assemblage stability
            assemblage_stability = np.mean([
                metrics['overall_stability'] 
                for metrics in stability_metrics.values()
            ])
            
            return {
                'mineral_stabilities': stability_metrics,
                'assemblage_stability': assemblage_stability,
                'stability_conditions': {
                    'temperature': temperature,
                    'pressure': pressure
                },
                'dominant_controls': self._identify_stability_controls(stability_metrics)
            }
            
        except Exception as e:
            self.logger.warning(f"Mineral stability calculation failed: {e}")
            return {'assemblage_stability': 0.7, 'mineral_stabilities': {}}
    
    def _analyze_mineral_evolution(self, mineral_assemblage, geological_context, **kwargs):
        """Analyze temporal evolution of mineral assemblage"""
        try:
            import numpy as np
            
            # Time scale analysis
            time_scale = geological_context.get('time_scale', 'geological')  # vs 'laboratory'
            
            # Get stable assemblage
            stable_minerals = mineral_assemblage.get('stable_assemblage', {})
            
            # Evolution pathways
            evolution_pathways = {}
            for mineral in stable_minerals.keys():
                
                # Reaction kinetics
                reaction_rate = self._calculate_reaction_kinetics(
                    mineral, kwargs.get('temperature', 298.15), 
                    kwargs.get('pressure', 0.1)
                )
                
                # Dissolution/precipitation rates
                dissolution_rate = self._calculate_dissolution_rate(
                    mineral, **kwargs
                )
                
                precipitation_rate = self._calculate_precipitation_rate(
                    mineral, **kwargs
                )
                
                # Grain growth kinetics
                growth_rate = self._calculate_grain_growth_rate(
                    mineral, **kwargs
                )
                
                evolution_pathways[mineral] = {
                    'reaction_rate': reaction_rate,
                    'dissolution_rate': dissolution_rate,
                    'precipitation_rate': precipitation_rate,
                    'growth_rate': growth_rate,
                    'net_change_rate': precipitation_rate - dissolution_rate
                }
            
            # Overall evolution metrics
            total_reaction_rate = sum(
                pathway['reaction_rate'] 
                for pathway in evolution_pathways.values()
            )
            
            evolution_timescale = self._estimate_evolution_timescale(
                evolution_pathways, time_scale
            )
            
            return {
                'evolution_pathways': evolution_pathways,
                'total_reaction_rate': total_reaction_rate,
                'evolution_timescale': evolution_timescale,
                'dominant_processes': self._identify_dominant_processes(evolution_pathways),
                'equilibration_status': self._assess_equilibration_status(evolution_pathways)
            }
            
        except Exception as e:
            self.logger.warning(f"Mineral evolution analysis failed: {e}")
            return {'evolution_timescale': '1e6 years', 'total_reaction_rate': 1e-15}
    
    def _calculate_composition_confidence(self, composition_data):
        """Calculate confidence metrics for composition analysis"""
        try:
            import numpy as np
            
            # Data source reliability scores
            source_weights = {
                'petdb_analysis': 0.9,
                'georoc_analysis': 0.8, 
                'earthchem_analysis': 0.85,
                'mindat_analysis': 0.7,
                'usgs_analysis': 0.8
            }
            
            # Calculate weighted confidence
            total_weight = 0
            weighted_confidence = 0
            
            for source, data in composition_data.items():
                if data:  # Source returned valid data
                    weight = source_weights.get(source, 0.5)
                    data_quality = self._assess_data_quality(data)
                    
                    weighted_confidence += weight * data_quality
                    total_weight += weight
            
            overall_confidence = weighted_confidence / total_weight if total_weight > 0 else 0.3
            
            # Additional metrics
            data_coverage = len([d for d in composition_data.values() if d]) / len(composition_data)
            consistency_score = self._calculate_data_consistency(composition_data)
            
            return {
                'overall_confidence': min(1.0, overall_confidence),
                'data_coverage': data_coverage,
                'consistency_score': consistency_score,
                'source_contributions': {
                    source: source_weights.get(source, 0.5) 
                    for source in composition_data.keys()
                },
                'confidence_level': self._classify_confidence_level(overall_confidence)
            }
            
        except Exception as e:
            self.logger.warning(f"Confidence calculation failed: {e}")
            return {'overall_confidence': 0.5, 'confidence_level': 'moderate'}
    
    def _validate_against_observations(self, stable_minerals, observed_assemblage):
        """Validate predicted assemblage against observations"""
        try:
            import numpy as np
            
            if not observed_assemblage:
                return stable_minerals  # No observations to validate against
            
            validated = {}
            
            # Check mineral presence agreement
            predicted_minerals = set(stable_minerals.keys())
            observed_minerals = set(observed_assemblage.keys())
            
            # Common minerals (high confidence)
            common_minerals = predicted_minerals.intersection(observed_minerals)
            for mineral in common_minerals:
                # Average predicted and observed abundances
                predicted_abundance = stable_minerals[mineral]
                observed_abundance = observed_assemblage[mineral]
                validated[mineral] = (predicted_abundance + observed_abundance) / 2.0
            
            # Predicted only (medium confidence)
            predicted_only = predicted_minerals - observed_minerals
            for mineral in predicted_only:
                validated[mineral] = stable_minerals[mineral] * 0.7  # Reduce confidence
            
            # Observed only (add with high confidence)
            observed_only = observed_minerals - predicted_minerals
            for mineral in observed_only:
                validated[mineral] = observed_assemblage[mineral]
            
            # Renormalize
            total = sum(validated.values())
            if total > 0:
                validated = {k: v/total*100 for k, v in validated.items()}
            
            return validated
            
        except Exception as e:
            self.logger.warning(f"Validation against observations failed: {e}")
            return stable_minerals
    
    def _calculate_assemblage_confidence(self, stable_minerals, observed_assemblage):
        """Calculate confidence in mineral assemblage prediction"""
        try:
            import numpy as np
            
            if not observed_assemblage:
                return 0.6  # Moderate confidence without observations
            
            # Calculate overlap between predicted and observed
            predicted_minerals = set(stable_minerals.keys())
            observed_minerals = set(observed_assemblage.keys())
            
            # Jaccard similarity coefficient
            intersection = len(predicted_minerals.intersection(observed_minerals))
            union = len(predicted_minerals.union(observed_minerals))
            jaccard = intersection / union if union > 0 else 0
            
            # Abundance similarity for common minerals
            abundance_similarity = 0
            common_minerals = predicted_minerals.intersection(observed_minerals)
            
            if common_minerals:
                similarities = []
                for mineral in common_minerals:
                    pred_abundance = stable_minerals[mineral]
                    obs_abundance = observed_assemblage[mineral]
                    similarity = 1.0 - abs(pred_abundance - obs_abundance) / max(pred_abundance, obs_abundance)
                    similarities.append(similarity)
                abundance_similarity = np.mean(similarities)
            
            # Combined confidence
            confidence = (jaccard * 0.6 + abundance_similarity * 0.4)
            
            return min(1.0, max(0.1, confidence))
            
        except Exception as e:
            self.logger.warning(f"Assemblage confidence calculation failed: {e}")
            return 0.5
    
    # Supporting methods for mineral analysis
    
    def _calculate_temperature_stability(self, mineral, temperature, abundance):
        """Calculate temperature stability for specific mineral"""
        try:
            # Mineral-specific temperature stability ranges (simplified)
            temp_ranges = {
                'quartz': {'min': 273, 'max': 1200, 'optimal': 800},
                'feldspar': {'min': 400, 'max': 1100, 'optimal': 750},
                'mica': {'min': 300, 'max': 900, 'optimal': 600},
                'garnet': {'min': 500, 'max': 1300, 'optimal': 900},
                'olivine': {'min': 800, 'max': 2000, 'optimal': 1200}
            }
            
            mineral_range = temp_ranges.get(mineral, {'min': 273, 'max': 1500, 'optimal': 700})
            
            # Calculate stability based on distance from optimal temperature
            optimal_temp = mineral_range['optimal']
            temp_deviation = abs(temperature - optimal_temp) / optimal_temp
            
            stability = max(0.1, 1.0 - temp_deviation)
            
            return min(1.0, stability)
            
        except Exception:
            return 0.7  # Default moderate stability
    
    def _calculate_pressure_stability(self, mineral, pressure, abundance):
        """Calculate pressure stability for specific mineral"""
        try:
            # Mineral-specific pressure stability (GPa)
            pressure_ranges = {
                'quartz': {'min': 0, 'max': 3, 'optimal': 0.5},
                'feldspar': {'min': 0, 'max': 2, 'optimal': 0.3},
                'garnet': {'min': 0.5, 'max': 10, 'optimal': 2},
                'olivine': {'min': 0, 'max': 25, 'optimal': 5}
            }
            
            mineral_range = pressure_ranges.get(mineral, {'min': 0, 'max': 5, 'optimal': 1})
            
            # Calculate stability
            optimal_pressure = mineral_range['optimal']
            if pressure < mineral_range['min'] or pressure > mineral_range['max']:
                stability = 0.1  # Outside stability field
            else:
                pressure_deviation = abs(pressure - optimal_pressure) / (optimal_pressure + 0.1)
                stability = max(0.3, 1.0 - pressure_deviation)
            
            return min(1.0, stability)
            
        except Exception:
            return 0.7  # Default moderate stability
    
    def _calculate_chemical_stability(self, mineral, assemblage, temperature, pressure):
        """Calculate chemical potential stability"""
        try:
            # Simplified chemical stability based on mineral compatibility
            compatible_minerals = {
                'quartz': ['feldspar', 'mica', 'garnet'],
                'feldspar': ['quartz', 'mica', 'hornblende'],
                'mica': ['quartz', 'feldspar', 'garnet'],
                'garnet': ['quartz', 'mica', 'pyroxene'],
                'olivine': ['pyroxene', 'plagioclase']
            }
            
            # Count compatible minerals in assemblage
            compatible_present = compatible_minerals.get(mineral, [])
            compatibility_score = sum(
                1 for comp_mineral in compatible_present 
                if comp_mineral in assemblage
            )
            
            # Normalize by number of possible compatible minerals
            max_compatibility = len(compatible_present)
            stability = compatibility_score / max_compatibility if max_compatibility > 0 else 0.5
            
            return max(0.2, min(1.0, stability))
            
        except Exception:
            return 0.6  # Default moderate stability
    
    def _assess_data_quality(self, data):
        """Assess quality of data from individual source"""
        try:
            quality_score = 0.5  # Base score
            
            # Check for major elements
            if 'major_elements' in data:
                major_elements = data['major_elements']
                element_count = len(major_elements)
                quality_score += min(0.3, element_count * 0.05)  # Bonus for more elements
                
                # Check for completeness of major elements
                key_elements = ['SiO2', 'Al2O3', 'Fe2O3', 'MgO', 'CaO']
                completeness = sum(1 for elem in key_elements if elem in major_elements)
                quality_score += completeness * 0.06
            
            # Check for trace elements
            if 'trace_elements' in data:
                quality_score += 0.15
            
            # Check for mineral assemblage
            if 'mineral_assemblage' in data:
                quality_score += 0.1
            
            # Penalize synthetic data
            if data.get('data_quality', '').startswith('synthetic'):
                quality_score *= 0.6
            
            return min(1.0, quality_score)
            
        except Exception:
            return 0.4  # Conservative default
    
    def _calculate_data_consistency(self, composition_data):
        """Calculate consistency between different data sources"""
        try:
            import numpy as np
            
            # Extract major elements from all sources
            all_major_elements = {}
            for source, data in composition_data.items():
                if data and 'major_elements' in data:
                    for element, value in data['major_elements'].items():
                        if element not in all_major_elements:
                            all_major_elements[element] = []
                        all_major_elements[element].append(value)
            
            # Calculate coefficient of variation for each element
            consistency_scores = []
            for element, values in all_major_elements.items():
                if len(values) > 1:
                    mean_val = np.mean(values)
                    std_val = np.std(values)
                    cv = std_val / mean_val if mean_val > 0 else 1.0
                    consistency_score = max(0.0, 1.0 - cv)  # Lower CV = higher consistency
                    consistency_scores.append(consistency_score)
            
            overall_consistency = np.mean(consistency_scores) if consistency_scores else 0.5
            
            return overall_consistency
            
        except Exception:
            return 0.5  # Default moderate consistency
    
    def _classify_confidence_level(self, confidence):
        """Classify confidence into descriptive levels"""
        if confidence >= 0.8:
            return 'high'
        elif confidence >= 0.6:
            return 'moderate'
        elif confidence >= 0.4:
            return 'low'
        else:
            return 'very_low'
    
