    def _fallback_cause_extraction(self, text, entities, cause):
        """Fallback method for causal factor extraction"""
        try:
            import re
            
            fallback_values = []
            
            # Simple pattern-based extraction as fallback
            value_pattern = r'(?P<value>\d+\.?\d*)\s*(?P<unit>[a-zA-Z/%°]+)?'
            
            for match in re.finditer(value_pattern, text):
                try:
                    fallback_values.append({
                        'value': float(match.group('value')),
                        'unit': match.group('unit') or '',
                        'confidence': 0.5,
                        'source': 'fallback_extraction',
                        'position': match.start()
                    })
                except ValueError:
                    continue
            
            return fallback_values[:5]  # Limit fallback results
            
        except Exception as e:
            logger.error(f"Fallback cause extraction failed: {e}")
            return []
    
    def _init_geological_knowledge_graph(self):
        """Initialize geological knowledge graph"""
        try:
            import networkx as nx
            
            self._kg_graph = nx.DiGraph()
            
            # Add basic geological relationships
            geological_relationships = [
                ('density', 'porosity', {'weight': 0.8, 'relationship': 'inverse'}),
                ('porosity', 'permeability', {'weight': 0.7, 'relationship': 'positive'}),
                ('temperature', 'pressure', {'weight': 0.6, 'relationship': 'positive'}),
                ('pressure', 'density', {'weight': 0.5, 'relationship': 'positive'}),
                ('grain_size', 'permeability', {'weight': 0.7, 'relationship': 'positive'}),
                ('depth', 'pressure', {'weight': 0.9, 'relationship': 'positive'}),
                ('depth', 'temperature', {'weight': 0.8, 'relationship': 'positive'}),
            ]
            
            for source, target, attrs in geological_relationships:
                self._kg_graph.add_edge(source, target, **attrs)
            
        except Exception as e:
            logger.warning(f"Knowledge graph initialization failed: {e}")
            self._kg_graph = None
    
    def _is_causal_relevant(self, entity_word, cause):
        """Check if entity word is causally relevant to the cause"""
        try:
            # Semantic similarity check
            causal_keywords = {
                'density': ['density', 'specific', 'gravity', 'weight', 'mass'],
                'porosity': ['porosity', 'pore', 'void', 'space', 'hole'],
                'permeability': ['permeability', 'flow', 'conductivity', 'transmissivity'],
                'temperature': ['temperature', 'thermal', 'heat', 'hot', 'cold'],
                'pressure': ['pressure', 'stress', 'force', 'load', 'compression']
            }
            
            cause_keywords = causal_keywords.get(cause.lower(), [])
            entity_lower = entity_word.lower()
            
            return any(keyword in entity_lower for keyword in cause_keywords)
            
        except Exception:
            return False
    
    def _extract_path_values(self, text, path, entity):
        """Extract values along causal path in knowledge graph"""
        try:
            path_values = []
            
            # Simple extraction based on path proximity
            for i, node in enumerate(path[:-1]):
                if node.lower() in text.lower():
                    # Look for values near this node mention
                    node_pos = text.lower().find(node.lower())
                    context_start = max(0, node_pos - 50)
                    context_end = min(len(text), node_pos + 50)
                    context = text[context_start:context_end]
                    
                    value_matches = re.findall(r'(\d+\.?\d*)\s*([a-zA-Z/%°]*)', context)
                    for value_str, unit in value_matches:
                        try:
                            path_values.append({
                                'value': float(value_str),
                                'unit': unit,
                                'confidence': 0.6 * (1 - i * 0.1),  # Decrease confidence with path length
                                'path_node': node,
                                'path_position': i
                            })
                        except ValueError:
                            continue
            
            return path_values
            
        except Exception as e:
            logger.warning(f"Path value extraction failed: {e}")
            return []
    
    def _validate_unit_for_property(self, property_name, unit):
        """Validate if unit is appropriate for property"""
        try:
            valid_units = {
                'density': ['g/cm³', 'g/cc', 'kg/m³', 'lb/ft³', 'g/mL'],
                'porosity': ['%', 'percent', 'fraction', 'ratio'],
                'permeability': ['mD', 'darcy', 'm²', 'cm/s', 'ft/day'],
                'temperature': ['°C', '°F', 'K', 'celsius', 'fahrenheit', 'kelvin'],
                'pressure': ['bar', 'psi', 'Pa', 'MPa', 'atm', 'kPa']
            }
            
            property_units = valid_units.get(property_name.lower(), [])
            return any(valid_unit.lower() in unit.lower() for valid_unit in property_units)
            
        except Exception:
            return False
    
    def _validate_and_score_values(self, candidates, text, cause):
        """Validate and score candidate values"""
        try:
            validated_values = []
            
            for candidate in candidates:
                validation_score = 1.0
                
                # Unit validation
                if not self._validate_unit_for_property(cause, candidate.get('unit', '')):
                    validation_score *= 0.8
                
                # Range validation (basic geological ranges)
                value = candidate.get('value', 0)
                if not self._validate_geological_range(cause, value):
                    validation_score *= 0.7
                
                # Context validation
                context_score = self._validate_geological_context(candidate, text)
                validation_score *= context_score
                
                candidate['validation_score'] = validation_score
                candidate['confidence'] = candidate.get('confidence', 0.5) * validation_score
                
                if validation_score > 0.3:  # Minimum validation threshold
                    validated_values.append(candidate)
            
            return validated_values
            
        except Exception as e:
            logger.warning(f"Value validation failed: {e}")
            return candidates
    
    def _validate_geological_range(self, property_name, value):
        """Validate if value is within reasonable geological range"""
        try:
            geological_ranges = {
                'density': (1.0, 20.0),  # g/cm³
                'porosity': (0.0, 50.0),  # %
                'permeability': (0.001, 1000000),  # mD
                'temperature': (-50, 1500),  # °C
                'pressure': (0.1, 10000)  # bar
            }
            
            min_val, max_val = geological_ranges.get(property_name.lower(), (0, float('inf')))
            return min_val <= value <= max_val
            
        except Exception:
            return True
    
    def _validate_geological_context(self, candidate, text):
        """Validate geological context of candidate"""
        try:
            # Simple context validation based on geological terms
            geological_terms = [
                'formation', 'rock', 'mineral', 'sediment', 'stratum',
                'geological', 'geologic', 'subsurface', 'reservoir',
                'aquifer', 'outcrop', 'core', 'sample', 'drilling'
            ]
            
            position = candidate.get('position', 0)
            context_start = max(0, position - 100)
            context_end = min(len(text), position + 100)
            context = text[context_start:context_end].lower()
            
            context_score = 0.5  # Base score
            for term in geological_terms:
                if term in context:
                    context_score += 0.1
                    if context_score >= 1.0:
                        break
            
            return min(1.0, context_score)
            
        except Exception:
            return 0.5
    
    def _ensemble_causal_values(self, validated_values, cause):
        """Ensemble aggregation of causal values"""
        try:
            if not validated_values:
                return []
            
            # Group by similar values (within 20% difference)
            value_groups = []
            for value_info in validated_values:
                value = value_info.get('value', 0)
                added_to_group = False
                
                for group in value_groups:
                    group_avg = np.mean([v.get('value', 0) for v in group])
                    if abs(value - group_avg) / max(group_avg, 1) < 0.2:
                        group.append(value_info)
                        added_to_group = True
                        break
                
                if not added_to_group:
                    value_groups.append([value_info])
            
            # Select best group and aggregate
            best_group = max(value_groups, key=lambda g: sum(v.get('confidence', 0) for v in g))
            
            # Weighted average within best group
            total_weight = sum(v.get('confidence', 0) for v in best_group)
            if total_weight > 0:
                weighted_value = sum(
                    v.get('value', 0) * v.get('confidence', 0) for v in best_group
                ) / total_weight
                
                ensemble_confidence = min(1.0, total_weight / len(best_group))
                
                return [{
                    'value': weighted_value,
                    'unit': best_group[0].get('unit', ''),
                    'confidence': ensemble_confidence,
                    'source': 'ensemble_aggregation',
                    'contributing_sources': [v.get('source', 'unknown') for v in best_group],
                    'group_size': len(best_group),
                    'total_candidates': len(validated_values)
                }]
            else:
                return [best_group[0]]  # Return first if no weights
                
        except Exception as e:
            logger.warning(f"Ensemble aggregation failed: {e}")
            return validated_values[:1] if validated_values else []
    
    def _log_extraction_results(self, cause, final_values, text_sample):
        """Log extraction results for model improvement"""
        try:
            extraction_log = {
                'timestamp': datetime.utcnow().isoformat(),
                'cause': cause,
                'text_sample': text_sample,
                'extracted_count': len(final_values),
                'confidence_scores': [v.get('confidence', 0) for v in final_values],
                'sources': [v.get('source', 'unknown') for v in final_values]
            }
            
            # Store in extraction history for analysis
            if not hasattr(self, '_extraction_history'):
                self._extraction_history = []
            
            self._extraction_history.append(extraction_log)
            
            # Keep only recent history (last 1000 extractions)
            if len(self._extraction_history) > 1000:
                self._extraction_history = self._extraction_history[-1000:]
                
        except Exception as e:
            logger.warning(f"Extraction logging failed: {e}")
    
