    def _validate_temp_pressure_database_consistency(self, temperature, pressure, rock_properties, volcanic_chambers):
        """Validate temperature-pressure consistency with database records"""
        try:
            consistency_metrics = {
                'rock_properties_consistency': {},
                'volcanic_chambers_consistency': {},
                'overall_consistency': {}
            }
            
            # 1. Rock Properties Temperature-Pressure Validation
            if rock_properties:
                temp_matches = []
                pressure_matches = []
                
                for rock in rock_properties:
                    # Estimate temperature from thermal conductivity and expansion
                    thermal_conductivity = rock.get('thermal_conductivity_w_m_k', 0)
                    thermal_expansion = rock.get('thermal_expansion_per_k', 0)
                    
                    if thermal_conductivity > 0 and thermal_expansion > 0:
                        # Empirical relationship for rock temperature estimation
                        estimated_temp = 298.15 + (thermal_expansion * 1e6 - 10) * 50  # Simplified model
                        temp_difference = abs(temperature - estimated_temp)
                        temp_matches.append(temp_difference < 100)  # Within 100K tolerance
                        
                        # Estimate pressure from elastic modulus and strength
                        elastic_modulus = rock.get('elastic_modulus_gpa', 0)
                        compressive_strength = rock.get('unconfined_compressive_strength_mpa', 0)
                        
                        if elastic_modulus > 0 and compressive_strength > 0:
                            # Empirical pressure-depth relationship
                            estimated_pressure = compressive_strength * 1e6 * 0.1  # Simplified conversion
                            pressure_difference = abs(pressure - estimated_pressure)
                            pressure_matches.append(pressure_difference < pressure * 0.5)  # 50% tolerance
                
                consistency_metrics['rock_properties_consistency'] = {
                    'temperature_match_rate': np.mean(temp_matches) if temp_matches else 0.0,
                    'pressure_match_rate': np.mean(pressure_matches) if pressure_matches else 0.0,
                    'total_records': len(rock_properties),
                    'analyzed_records': len(temp_matches)
                }
            
            # 2. Volcanic Chambers Temperature-Pressure Validation
            if volcanic_chambers:
                chamber_temp_matches = []
                chamber_pressure_matches = []
                
                for chamber in volcanic_chambers:
                    chamber_temp = chamber.get('temperature_c', 0)
                    chamber_pressure = chamber.get('pressure_mpa', 0)
                    confidence = chamber.get('confidence_level', 0.5)
                    
                    if chamber_temp > 0 and chamber_pressure > 0:
                        # Convert chamber temp to Kelvin for comparison
                        chamber_temp_k = chamber_temp + 273.15
                        chamber_pressure_pa = chamber_pressure * 1e6
                        
                        # Temperature consistency (weighted by confidence)
                        temp_difference = abs(temperature - chamber_temp_k)
                        temp_consistency = max(0, 1 - temp_difference / 500.0)  # Normalized by 500K range
                        chamber_temp_matches.append(temp_consistency * confidence)
                        
                        # Pressure consistency (weighted by confidence)
                        pressure_difference = abs(pressure - chamber_pressure_pa)
                        pressure_consistency = max(0, 1 - pressure_difference / (pressure + 1e6))
                        chamber_pressure_matches.append(pressure_consistency * confidence)
                
                consistency_metrics['volcanic_chambers_consistency'] = {
                    'weighted_temperature_consistency': np.mean(chamber_temp_matches) if chamber_temp_matches else 0.0,
                    'weighted_pressure_consistency': np.mean(chamber_pressure_matches) if chamber_pressure_matches else 0.0,
                    'total_chambers': len(volcanic_chambers),
                    'analyzed_chambers': len(chamber_temp_matches)
                }
            
            # 3. Overall Consistency Assessment
            rock_temp_score = consistency_metrics.get('rock_properties_consistency', {}).get('temperature_match_rate', 0.0)
            rock_pressure_score = consistency_metrics.get('rock_properties_consistency', {}).get('pressure_match_rate', 0.0)
            chamber_temp_score = consistency_metrics.get('volcanic_chambers_consistency', {}).get('weighted_temperature_consistency', 0.0)
            chamber_pressure_score = consistency_metrics.get('volcanic_chambers_consistency', {}).get('weighted_pressure_consistency', 0.0)
            
            # Weighted average (volcanic chambers weighted higher due to direct relevance)
            overall_temp_consistency = (rock_temp_score * 0.3 + chamber_temp_score * 0.7)
            overall_pressure_consistency = (rock_pressure_score * 0.3 + chamber_pressure_score * 0.7)
            overall_consistency_score = (overall_temp_consistency + overall_pressure_consistency) / 2.0
            
            consistency_metrics['overall_consistency'] = {
                'temperature_consistency': overall_temp_consistency,
                'pressure_consistency': overall_pressure_consistency,
                'consistency_score': overall_consistency_score,
                'quality_assessment': (
                    'excellent' if overall_consistency_score >= 0.8 else
                    'good' if overall_consistency_score >= 0.6 else
                    'fair' if overall_consistency_score >= 0.4 else
                    'poor'
                )
            }
            
            return consistency_metrics
            
        except Exception as e:
            self.logger.error(f"Temperature-pressure database validation failed: {e}")
            return {'consistency_score': 0.5, 'error': str(e)}
    
    def _validate_external_data_consistency(self, temperature, pressure, composition, earthquake_data, thermal_data, atmospheric_data):
        """Validate consistency with external data sources"""
        try:
            external_consistency = {
                'seismic_thermal_correlation': {},
                'nasa_thermal_validation': {},
                'atmospheric_pressure_validation': {},
                'multi_source_integration': {}
            }
            
            # 1. Seismic-Thermal Correlation Analysis
            if earthquake_data:
                seismic_temps = []
                seismic_pressures = []
                
                for earthquake in earthquake_data:
                    depth = earthquake.properties.get('depth', 0)  # km
                    magnitude = earthquake.properties.get('mag', 0)
                    
                    if depth > 0 and magnitude > 0:
                        # Estimate temperature from depth (geothermal gradient)
                        estimated_temp = 298.15 + depth * 25  # ~25K/km gradient
                        seismic_temps.append(estimated_temp)
                        
                        # Estimate pressure from depth and magnitude
                        estimated_pressure = depth * 1000 * 9.81 * 2700  # Lithostatic pressure
                        seismic_pressures.append(estimated_pressure)
                
                if seismic_temps and seismic_pressures:
                    avg_seismic_temp = np.mean(seismic_temps)
                    avg_seismic_pressure = np.mean(seismic_pressures)
                    
                    temp_correlation = max(0, 1 - abs(temperature - avg_seismic_temp) / 500.0)
                    pressure_correlation = max(0, 1 - abs(pressure - avg_seismic_pressure) / (pressure + 1e6))
                    
                    external_consistency['seismic_thermal_correlation'] = {
                        'temperature_correlation': temp_correlation,
                        'pressure_correlation': pressure_correlation,
                        'average_seismic_temperature': avg_seismic_temp,
                        'average_seismic_pressure': avg_seismic_pressure,
                        'data_points': len(earthquake_data)
                    }
            
            # 2. NASA Thermal Data Validation
            if thermal_data:
                nasa_temp_matches = []
                for thermal_record in thermal_data:
                    record_temp = thermal_record.properties.get('temperature', 0)
                    if record_temp > 0:
                        temp_difference = abs(temperature - record_temp)
                        temp_match = max(0, 1 - temp_difference / 200.0)  # 200K tolerance
                        nasa_temp_matches.append(temp_match)
                
                external_consistency['nasa_thermal_validation'] = {
                    'average_temperature_match': np.mean(nasa_temp_matches) if nasa_temp_matches else 0.0,
                    'data_points': len(thermal_data),
                    'match_threshold': 200.0  # Kelvin
                }
            
            # 3. Atmospheric Pressure Validation
            if atmospheric_data:
                pressure_matches = []
                for atm_record in atmospheric_data:
                    record_pressure = atm_record.properties.get('pressure', 0)
                    if record_pressure > 0:
                        # Convert to Pascal if needed
                        if record_pressure < 200000:  # Likely in Pa already
                            record_pressure_pa = record_pressure
                        else:
                            record_pressure_pa = record_pressure
                        
                        pressure_difference = abs(pressure - record_pressure_pa)
                        pressure_match = max(0, 1 - pressure_difference / (pressure * 0.3))  # 30% tolerance
                        pressure_matches.append(pressure_match)
                
                external_consistency['atmospheric_pressure_validation'] = {
                    'average_pressure_match': np.mean(pressure_matches) if pressure_matches else 0.0,
                    'data_points': len(atmospheric_data),
                    'match_tolerance': 0.3  # 30%
                }
            
            # 4. Multi-Source Integration Assessment
            consistency_scores = []
            
            # Collect all consistency scores
            if 'seismic_thermal_correlation' in external_consistency:
                seismic_score = (
                    external_consistency['seismic_thermal_correlation']['temperature_correlation'] +
                    external_consistency['seismic_thermal_correlation']['pressure_correlation']
                ) / 2.0
                consistency_scores.append(seismic_score)
            
            if 'nasa_thermal_validation' in external_consistency:
                nasa_score = external_consistency['nasa_thermal_validation']['average_temperature_match']
                consistency_scores.append(nasa_score)
            
            if 'atmospheric_pressure_validation' in external_consistency:
                atm_score = external_consistency['atmospheric_pressure_validation']['average_pressure_match']
                consistency_scores.append(atm_score)
            
            # Overall assessment
            if consistency_scores:
                overall_consistency = np.mean(consistency_scores)
                consistency_variance = np.var(consistency_scores)
                data_coverage = len([score for score in consistency_scores if score > 0])
                
                external_consistency['multi_source_integration'] = {
                    'overall_consistency': overall_consistency,
                    'consistency_variance': consistency_variance,
                    'data_source_coverage': data_coverage,
                    'individual_scores': consistency_scores,
                    'quality_rating': (
                        'excellent' if overall_consistency >= 0.8 else
                        'good' if overall_consistency >= 0.6 else
                        'fair' if overall_consistency >= 0.4 else
                        'poor'
                    )
                }
            else:
                external_consistency['multi_source_integration'] = {
                    'overall_consistency': 0.5,
                    'error': 'no_valid_external_data'
                }
            
            return external_consistency
            
        except Exception as e:
            self.logger.error(f"External data consistency validation failed: {e}")
            return {'overall_consistency': 0.5, 'error': str(e)}
    
