    async def _query_global_stress_measurements(self):
        """Query global stress measurement database"""
        try:
            if hasattr(self, 'database_managers') and 'postgresql' in self.database_managers:
                db_manager = self.database_managers['postgresql']
                query = """
                    SELECT stress_magnitude_mpa, stress_orientation_degrees, stress_regime,
                           depth_m, latitude, longitude, measurement_date, reliability_score
                    FROM stress_measurements
                    WHERE reliability_score >= 0.7
                    ORDER BY measurement_date DESC
                    LIMIT 1000
                """
                result = await db_manager.execute_query(query)
                return result.fetchall() if result else []
            return []
        except Exception as e:
            self.logger.error(f"Global stress query failed: {e}")
            return []
    
    def _validate_stress_magnitude(self, max_stress, mean_stress, stress_data):
        """Validate stress magnitude against database"""
        if not stress_data:
            return {'valid': True, 'confidence': 0.3, 'source': 'no_data'}
        
        # Statistical analysis of stress measurements
        measured_stresses = [row[0] * 1e6 for row in stress_data if row[0]]  # Convert MPa to Pa
        if measured_stresses:
            p25, p75 = np.percentile(measured_stresses, [25, 75])
            iqr = p75 - p25
            lower_bound = p25 - 1.5 * iqr
            upper_bound = p75 + 1.5 * iqr
            
            magnitude_valid = lower_bound <= max_stress <= upper_bound
            confidence = 0.9 if magnitude_valid else max(0.1, 1.0 - abs(max_stress - np.median(measured_stresses)) / np.median(measured_stresses))
            
            return {
                'valid': magnitude_valid,
                'confidence': confidence,
                'bounds': [lower_bound, upper_bound],
                'median_reference': np.median(measured_stresses),
                'source': 'global_database'
            }
        
        return {'valid': True, 'confidence': 0.3, 'source': 'insufficient_data'}
    
    async def _validate_depth_stress_relationship(self, max_stress, mean_stress):
        """Validate depth-stress relationship using lithostatic pressure"""
        try:
            # Query depth-stress relationships from database
            if hasattr(self, 'database_managers') and 'postgresql' in self.database_managers:
                db_manager = self.database_managers['postgresql']
                query = """
                    SELECT depth_m, vertical_stress_mpa, horizontal_stress_max_mpa
                    FROM insitu_stress_measurements
                    WHERE measurement_quality >= 0.7
                    ORDER BY depth_m
                """
                result = await db_manager.execute_query(query)
                depth_data = result.fetchall() if result else []
                
                if depth_data:
                    depths = [row[0] for row in depth_data]
                    v_stresses = [row[1] * 1e6 for row in depth_data if row[1]]  # Convert to Pa
                    h_stresses = [row[2] * 1e6 for row in depth_data if row[2]]
                    
                    if v_stresses and h_stresses:
                        # Calculate expected stress gradients
                        v_gradient = np.polyfit(depths, v_stresses, 1)[0]  # Pa/m
                        h_gradient = np.polyfit(depths, h_stresses, 1)[0]  # Pa/m
                        
                        # Typical depth (assume 5 km for analysis)
                        assumed_depth = 5000  # m
                        expected_v_stress = v_gradient * assumed_depth
                        expected_h_stress = h_gradient * assumed_depth
                        
                        v_agreement = 1.0 - min(1.0, abs(max_stress - expected_v_stress) / expected_v_stress)
                        h_agreement = 1.0 - min(1.0, abs(max_stress - expected_h_stress) / expected_h_stress)
                        
                        return {
                            'valid': max(v_agreement, h_agreement) > 0.6,
                            'confidence': max(v_agreement, h_agreement),
                            'vertical_gradient': v_gradient,
                            'horizontal_gradient': h_gradient,
                            'source': 'depth_analysis'
                        }
            
            # Fallback to theoretical lithostatic pressure
            rock_density = 2700  # kg/m³
            gravity = 9.81  # m/s²
            assumed_depth = 5000  # m
            lithostatic_pressure = rock_density * gravity * assumed_depth  # Pa
            
            agreement = 1.0 - min(1.0, abs(max_stress - lithostatic_pressure) / lithostatic_pressure)
            
            return {
                'valid': agreement > 0.5,
                'confidence': agreement,
                'lithostatic_reference': lithostatic_pressure,
                'source': 'theoretical'
            }
            
        except Exception as e:
            self.logger.error(f"Depth-stress validation failed: {e}")
            return {'valid': True, 'confidence': 0.3, 'source': 'error'}
    
    async def _validate_tectonic_stress_regime(self, max_stress, mean_stress):
        """Validate stress against tectonic setting"""
        try:
            if hasattr(self, 'database_managers') and 'postgresql' in self.database_managers:
                db_manager = self.database_managers['postgresql']
                query = """
                    SELECT stress_regime, AVG(stress_magnitude_mpa) as avg_stress,
                           STDDEV(stress_magnitude_mpa) as std_stress, COUNT(*) as count
                    FROM stress_measurements
                    WHERE stress_regime IS NOT NULL
                    GROUP BY stress_regime
                """
                result = await db_manager.execute_query(query)
                regime_data = result.fetchall() if result else []
                
                best_match = None
                best_score = 0
                
                for regime, avg_stress, std_stress, count in regime_data:
                    if avg_stress and std_stress and count > 10:
                        avg_stress_pa = avg_stress * 1e6
                        std_stress_pa = std_stress * 1e6
                        
                        # Calculate likelihood based on normal distribution
                        z_score = abs(max_stress - avg_stress_pa) / std_stress_pa
                        likelihood = np.exp(-0.5 * z_score**2) / (std_stress_pa * np.sqrt(2 * np.pi))
                        
                        if likelihood > best_score:
                            best_score = likelihood
                            best_match = regime
                
                if best_match:
                    return {
                        'valid': best_score > 0.1,
                        'confidence': min(1.0, best_score * 10),
                        'matched_regime': best_match,
                        'likelihood_score': best_score,
                        'source': 'tectonic_database'
                    }
            
            # Fallback tectonic analysis
            tectonic_regimes = {
                'normal_faulting': (1e7, 5e7),    # 10-50 MPa
                'strike_slip': (2e7, 1e8),       # 20-100 MPa
                'reverse_faulting': (3e7, 2e8),  # 30-200 MPa
                'compressive': (5e7, 5e8)        # 50-500 MPa
            }
            
            for regime, (min_stress, max_stress_regime) in tectonic_regimes.items():
                if min_stress <= max_stress <= max_stress_regime:
                    return {
                        'valid': True,
                        'confidence': 0.7,
                        'matched_regime': regime,
                        'source': 'theoretical_tectonic'
                    }
            
            return {'valid': False, 'confidence': 0.2, 'source': 'no_tectonic_match'}
            
        except Exception as e:
            self.logger.error(f"Tectonic validation failed: {e}")
            return {'valid': True, 'confidence': 0.3, 'source': 'error'}
    
    def _calculate_stress_likelihood(self, max_stress, mean_stress, stress_data):
        """Calculate statistical likelihood of stress values"""
        if not stress_data:
            return {'likelihood': 0.5, 'source': 'no_data'}
        
        measured_stresses = [row[0] * 1e6 for row in stress_data if row[0]]  # Convert to Pa
        
        if len(measured_stresses) < 10:
            return {'likelihood': 0.5, 'source': 'insufficient_data'}
        
        # Statistical analysis
        mu = np.mean(measured_stresses)
        sigma = np.std(measured_stresses)
        
        # Calculate likelihood using normal distribution
        likelihood = np.exp(-0.5 * ((max_stress - mu) / sigma)**2) / (sigma * np.sqrt(2 * np.pi))
        normalized_likelihood = min(1.0, likelihood * sigma / mu)  # Normalize
        
        return {
            'likelihood': normalized_likelihood,
            'mean_reference': mu,
            'std_reference': sigma,
            'z_score': (max_stress - mu) / sigma,
            'source': 'statistical_analysis'
        }
    
    async def _validate_temporal_stress_evolution(self, max_stress, mean_stress):
        """Validate stress evolution over time"""
        try:
            if hasattr(self, 'database_managers') and 'postgresql' in self.database_managers:
                db_manager = self.database_managers['postgresql']
                query = """
                    SELECT measurement_date, stress_magnitude_mpa
                    FROM stress_measurements
                    WHERE measurement_date >= NOW() - INTERVAL '10 years'
                    AND stress_magnitude_mpa IS NOT NULL
                    ORDER BY measurement_date
                """
                result = await db_manager.execute_query(query)
                temporal_data = result.fetchall() if result else []
                
                if len(temporal_data) > 20:
                    dates = [row[0] for row in temporal_data]
                    stresses = [row[1] * 1e6 for row in temporal_data]
                    
                    # Calculate temporal trend
                    timestamps = [(date - dates[0]).total_seconds() for date in dates]
                    trend_slope = np.polyfit(timestamps, stresses, 1)[0]
                    
                    # Current stress position relative to trend
                    latest_timestamp = timestamps[-1]
                    predicted_stress = stresses[0] + trend_slope * latest_timestamp
                    
                    agreement = 1.0 - min(1.0, abs(max_stress - predicted_stress) / predicted_stress)
                    
                    return {
                        'valid': agreement > 0.5,
                        'confidence': agreement,
                        'temporal_trend': trend_slope,
                        'predicted_stress': predicted_stress,
                        'source': 'temporal_analysis'
                    }
            
            return {'valid': True, 'confidence': 0.4, 'source': 'no_temporal_data'}
            
        except Exception as e:
            self.logger.error(f"Temporal validation failed: {e}")
            return {'valid': True, 'confidence': 0.3, 'source': 'error'}
    
