    def _compute_composite_validation_score(self, validation_results, geomech_analysis):
        """Compute composite validation score"""
        weights = {
            'magnitude_feasible': 0.25,
            'depth_consistency': 0.20,
            'tectonic_compatibility': 0.20,
            'statistical_likelihood': 0.15,
            'temporal_consistency': 0.10,
            'geomechanical': 0.10
        }
        
        total_score = 0
        total_weight = 0
        
        for criterion, weight in weights.items():
            if criterion == 'geomechanical':
                if geomech_analysis.get('analysis_quality') == 'advanced_geomechanical':
                    score = 0.8
                else:
                    score = 0.5
            else:
                result = validation_results.get(criterion, {})
                if isinstance(result, dict):
                    score = result.get('confidence', 0.5) if result.get('valid', True) else 0.2
                else:
                    score = 0.5
            
            total_score += score * weight
            total_weight += weight
        
        return total_score / total_weight if total_weight > 0 else 0.5
    
    def _generate_stress_recommendations(self, validation_results):
        """Generate recommendations based on validation results"""
        recommendations = []
        
        for criterion, result in validation_results.items():
            if isinstance(result, dict):
                if not result.get('valid', True) or result.get('confidence', 1.0) < 0.6:
                    if criterion == 'magnitude_feasible':
                        recommendations.append("Review stress magnitude - may be outside typical ranges")
                    elif criterion == 'depth_consistency':
                        recommendations.append("Check depth-stress relationship for lithostatic consistency")
                    elif criterion == 'tectonic_compatibility':
                        recommendations.append("Verify tectonic setting compatibility")
                    elif criterion == 'statistical_likelihood':
                        recommendations.append("Stress values have low statistical likelihood")
                    elif criterion == 'temporal_consistency':
                        recommendations.append("Review temporal stress evolution patterns")
        
        if not recommendations:
            recommendations.append("Stress assessment passes all validation criteria")
        
        return recommendations
    
