    def _extract_stress_tensor(self, stress):
        """Extract full stress tensor from input"""
        if isinstance(stress, np.ndarray):
            if stress.shape == (3, 3):
                return stress
            elif stress.shape == (6,):  # Voigt notation
                return np.array([
                    [stress[0], stress[3], stress[4]],
                    [stress[3], stress[1], stress[5]],
                    [stress[4], stress[5], stress[2]]
                ])
            elif len(stress) >= 3:
                # Assume principal stresses
                return np.diag(stress[:3])
        
        # Fallback to isotropic tensor
        mean_stress = np.mean(stress) if hasattr(stress, '__len__') else stress
        return np.eye(3) * mean_stress
    
    def _calculate_principal_stresses(self, stress_tensor):
        """Calculate principal stresses and directions"""
        eigenvals, eigenvecs = np.linalg.eigh(stress_tensor)
        
        # Sort in descending order (σ1 > σ2 > σ3)
        idx = np.argsort(eigenvals)[::-1]
        principal_stresses = eigenvals[idx]
        principal_directions = eigenvecs[:, idx]
        
        return {
            'sigma_1': principal_stresses[0],
            'sigma_2': principal_stresses[1],
            'sigma_3': principal_stresses[2],
            'directions': principal_directions,
            'mean_stress': np.mean(principal_stresses),
            'deviatoric_stress': principal_stresses[0] - principal_stresses[2],
            'stress_ratio': principal_stresses[2] / principal_stresses[0] if principal_stresses[0] != 0 else 0
        }
    
    async def _query_rock_properties_database(self):
        """Query rock properties from database"""
        try:
            if hasattr(self, 'database_managers') and 'postgresql' in self.database_managers:
                db_manager = self.database_managers['postgresql']
                query = """
                    SELECT rock_type, compressive_strength_mpa, tensile_strength_mpa,
                           cohesion_mpa, friction_angle_deg, elastic_modulus_gpa,
                           poisson_ratio, density_kg_m3
                    FROM rock_properties_enhanced
                    WHERE data_quality >= 0.7
                    ORDER BY frequency_weight DESC
                    LIMIT 50
                """
                result = await db_manager.execute_query(query)
                return result.fetchall() if result else []
            return []
        except Exception as e:
            self.logger.error(f"Rock properties query failed: {e}")
            return []
    
    # Advanced stress analysis implementations with real data integration
    async def _calculate_mohr_circle_parameters(self, max_stress, mean_stress, stress_tensor=None):
        """Advanced Mohr circle analysis with real geomechanical data integration"""
        try:
            # Connect to database for historical stress data
            if hasattr(self, 'database_integration') and self.database_integration:
                historical_data = await self.database_integration.query_stress_history(
                    location=getattr(self, 'current_location', None),
                    time_window=timedelta(days=365)
                )
            else:
                historical_data = None
            
            # Calculate principal stresses from tensor if available
            if stress_tensor is not None and isinstance(stress_tensor, np.ndarray):
                eigenvalues, eigenvectors = np.linalg.eig(stress_tensor)
                principal_stresses = np.sort(eigenvalues)[::-1]  # σ1 > σ2 > σ3
                sigma_1, sigma_2, sigma_3 = principal_stresses
                
                # Calculate all three Mohr circles
                circles = {
                    'major': {
                        'center': (sigma_1 + sigma_3) / 2,
                        'radius': (sigma_1 - sigma_3) / 2,
                        'tau_max': (sigma_1 - sigma_3) / 2
                    },
                    'intermediate': {
                        'center': (sigma_1 + sigma_2) / 2,
                        'radius': (sigma_1 - sigma_2) / 2,
                        'tau_max': (sigma_1 - sigma_2) / 2
                    },
                    'minor': {
                        'center': (sigma_2 + sigma_3) / 2,
                        'radius': (sigma_2 - sigma_3) / 2,
                        'tau_max': (sigma_2 - sigma_3) / 2
                    }
                }
                
                # Calculate stress ratio and orientation
                stress_ratio = (sigma_2 - sigma_3) / (sigma_1 - sigma_3) if (sigma_1 - sigma_3) != 0 else 0
                max_shear_plane_angle = np.arctan2(2 * stress_tensor[0, 1], 
                                                   stress_tensor[0, 0] - stress_tensor[1, 1]) / 2
                
                # Integrate with external seismic data for validation
                if hasattr(self, 'external_data_connector') and self.external_data_connector:
                    seismic_stress = await self.external_data_connector.get_regional_stress_field(
                        latitude=getattr(self, 'latitude', 0),
                        longitude=getattr(self, 'longitude', 0),
                        depth_km=getattr(self, 'depth_km', 10)
                    )
                    
                    # Validate against World Stress Map data
                    validation_score = self._validate_stress_orientation(
                        calculated=max_shear_plane_angle,
                        observed=seismic_stress.get('shmax_azimuth', None)
                    )
                else:
                    seismic_stress = None
                    validation_score = 1.0
                
            else:
                # Enhanced simple calculation with uncertainty quantification
                radius = abs(max_stress - mean_stress) / 2
                center = mean_stress
                
                # Estimate uncertainty based on data quality
                uncertainty = 0.1 * radius  # 10% baseline uncertainty
                
                if historical_data:
                    # Refine with historical statistics
                    hist_std = np.std([d['max_stress'] - d['mean_stress'] for d in historical_data])
                    uncertainty = min(uncertainty, hist_std / 2)
                
                circles = {
                    'estimated': {
                        'center': center,
                        'radius': radius,
                        'tau_max': radius,
                        'uncertainty': uncertainty
                    }
                }
                
                stress_ratio = 0.5  # Default assumption
                max_shear_plane_angle = np.pi / 4  # 45 degrees default
                validation_score = 0.5  # Lower confidence without full tensor
            
            # Calculate coulomb stress change if reference state available
            coulomb_stress_change = None
            if hasattr(self, 'reference_stress_state') and self.reference_stress_state:
                coulomb_stress_change = self._calculate_coulomb_stress_change(
                    current_state=stress_tensor if stress_tensor is not None else {'max': max_stress, 'mean': mean_stress},
                    reference_state=self.reference_stress_state,
                    friction_coefficient=getattr(self, 'friction_coefficient', 0.6)
                )
            
            # ML-based stress prediction for future states
            future_stress_prediction = None
            if hasattr(self, 'model_manager') and self.model_manager:
                features = np.array([max_stress, mean_stress, stress_ratio, 
                                   getattr(self, 'depth_km', 10),
                                   getattr(self, 'temperature_k', 300)])
                future_stress_prediction = await self.model_manager.predict_stress_evolution(
                    current_features=features,
                    time_horizon_hours=168  # 1 week prediction
                )
            
            return {
                'circles': circles,
                'principal_stresses': principal_stresses.tolist() if 'principal_stresses' in locals() else None,
                'stress_ratio': float(stress_ratio),
                'max_shear_plane_angle_rad': float(max_shear_plane_angle),
                'max_shear_plane_angle_deg': float(np.degrees(max_shear_plane_angle)),
                'coulomb_stress_change': coulomb_stress_change,
                'validation_score': validation_score,
                'future_prediction': future_stress_prediction,
                'data_source': 'integrated_real_time' if seismic_stress else 'calculated',
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Error in advanced Mohr circle calculation: {e}")
            # Fallback to simple calculation
            return {
                'circles': {'simple': {'center': mean_stress, 'radius': abs(max_stress - mean_stress)/2}},
                'error': str(e)
            }
    
    async def _calculate_failure_envelopes(self, max_stress, mean_stress, rock_props=None):
        """Advanced failure envelope calculations with real rock property data"""
        try:
            # Get real rock properties from database or external sources
            if rock_props is None and hasattr(self, 'database_integration'):
                rock_props = await self.database_integration.get_rock_properties(
                    rock_type=getattr(self, 'rock_type', 'granite'),
                    location=getattr(self, 'current_location', None)
                )
            
            if rock_props is None:
                # Use default values from literature
                rock_props = {
                    'cohesion_mpa': 50.0,  # Typical granite
                    'friction_angle_deg': 35.0,
                    'ucs_mpa': 200.0,  # Unconfined compressive strength
                    'tensile_strength_mpa': 10.0,
                    'mi': 25.0,  # Hoek-Brown material constant
                    'gsi': 75,  # Geological Strength Index
                    'disturbance_factor': 0.0
                }
            
            # Mohr-Coulomb failure envelope
            friction_angle_rad = np.radians(rock_props.get('friction_angle_deg', 35))
            cohesion = rock_props.get('cohesion_mpa', 50)
            
            # Calculate normal and shear stress range
            sigma_range = np.linspace(-rock_props.get('tensile_strength_mpa', 10), 
                                     max_stress * 1.5, 1000)
            
            # Mohr-Coulomb criterion: τ = c + σn * tan(φ)
            tau_mohr_coulomb = cohesion + sigma_range * np.tan(friction_angle_rad)
            tau_mohr_coulomb[sigma_range < 0] = np.nan  # No tensile strength in classic M-C
            
            # Hoek-Brown failure envelope (more accurate for rock masses)
            ucs = rock_props.get('ucs_mpa', 200)
            mi = rock_props.get('mi', 25)
            gsi = rock_props.get('gsi', 75)
            d = rock_props.get('disturbance_factor', 0)
            
            # Calculate Hoek-Brown parameters
            mb = mi * np.exp((gsi - 100) / (28 - 14 * d))
            s = np.exp((gsi - 100) / (9 - 3 * d))
            a = 0.5 + (np.exp(-gsi/15) - np.exp(-20/3)) / 6
            
            # Hoek-Brown criterion
            sigma3_range = np.linspace(0, max_stress, 1000)
            sigma1_hb = sigma3_range + ucs * (mb * sigma3_range / ucs + s) ** a
            
            # Convert to Mohr circle space (normal-shear)
            sigma_n_hb = (sigma1_hb + sigma3_range) / 2
            tau_hb = (sigma1_hb - sigma3_range) / 2
            
            # Modified Griffith criterion for tensile failure
            tensile_strength = rock_props.get('tensile_strength_mpa', 10)
            sigma_t_range = np.linspace(-tensile_strength, 0, 100)
            tau_griffith = 2 * np.sqrt(-tensile_strength * sigma_t_range)
            
            # Drucker-Prager criterion (3D extension)
            if hasattr(self, 'stress_tensor_3d') and self.stress_tensor_3d is not None:
                # Calculate Drucker-Prager parameters from M-C
                alpha_dp = 2 * np.sin(friction_angle_rad) / (3 - np.sin(friction_angle_rad))
                k_dp = 6 * cohesion * np.cos(friction_angle_rad) / (3 - np.sin(friction_angle_rad))
                
                # Calculate invariants
                i1 = np.trace(self.stress_tensor_3d)
                s_dev = self.stress_tensor_3d - np.eye(3) * i1 / 3
                j2 = 0.5 * np.sum(s_dev ** 2)
                
                drucker_prager_value = alpha_dp * i1 + np.sqrt(j2) - k_dp
                at_failure = drucker_prager_value >= 0
            else:
                drucker_prager_value = None
                at_failure = False
            
            # Calculate factor of safety
            if isinstance(max_stress, (int, float)) and isinstance(mean_stress, (int, float)):
                current_tau = abs(max_stress - mean_stress) / 2
                current_sigma = mean_stress
                
                # Distance to Mohr-Coulomb envelope
                tau_mc_at_sigma = cohesion + current_sigma * np.tan(friction_angle_rad)
                fos_mohr_coulomb = tau_mc_at_sigma / current_tau if current_tau > 0 else float('inf')
                
                # Distance to Hoek-Brown envelope (iterative)
                sigma3_current = current_sigma - current_tau
                sigma1_current = current_sigma + current_tau
                sigma1_hb_at_sigma3 = sigma3_current + ucs * (mb * sigma3_current / ucs + s) ** a
                fos_hoek_brown = sigma1_hb_at_sigma3 / sigma1_current if sigma1_current > 0 else float('inf')
            else:
                fos_mohr_coulomb = 1.0
                fos_hoek_brown = 1.0
            
            # Time-dependent strength degradation (if applicable)
            if hasattr(self, 'time_since_loading_hours'):
                # Subcritical crack growth model
                strength_reduction = np.exp(-self.time_since_loading_hours / 1000)  # Simplified
                fos_mohr_coulomb *= strength_reduction
                fos_hoek_brown *= strength_reduction
            
            # Temperature effects on strength
            if hasattr(self, 'temperature_k') and self.temperature_k > 300:
                temp_factor = 1 - 0.001 * (self.temperature_k - 300)  # 0.1% reduction per K
                fos_mohr_coulomb *= max(0.5, temp_factor)
                fos_hoek_brown *= max(0.5, temp_factor)
            
            return {
                'mohr_coulomb': {
                    'cohesion_mpa': float(cohesion),
                    'friction_angle_deg': float(rock_props.get('friction_angle_deg', 35)),
                    'envelope_sigma': sigma_range.tolist(),
                    'envelope_tau': tau_mohr_coulomb.tolist(),
                    'factor_of_safety': float(fos_mohr_coulomb),
                    'at_failure': fos_mohr_coulomb <= 1.0
                },
                'hoek_brown': {
                    'ucs_mpa': float(ucs),
                    'mi': float(mi),
                    'mb': float(mb),
                    's': float(s),
                    'a': float(a),
                    'gsi': float(gsi),
                    'envelope_sigma': sigma_n_hb.tolist(),
                    'envelope_tau': tau_hb.tolist(),
                    'factor_of_safety': float(fos_hoek_brown),
                    'at_failure': fos_hoek_brown <= 1.0
                },
                'griffith': {
                    'tensile_strength_mpa': float(tensile_strength),
                    'envelope_sigma': sigma_t_range.tolist(),
                    'envelope_tau': tau_griffith.tolist()
                },
                'drucker_prager': {
                    'value': float(drucker_prager_value) if drucker_prager_value is not None else None,
                    'at_failure': bool(at_failure)
                },
                'combined_fos': float(min(fos_mohr_coulomb, fos_hoek_brown)),
                'failure_mode': self._determine_failure_mode(fos_mohr_coulomb, fos_hoek_brown, mean_stress),
                'rock_properties_source': 'database' if rock_props else 'default',
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Error in failure envelope calculation: {e}")
            return {
                'mohr_coulomb_envelope': True, 
                'hoek_brown_envelope': True,
                'error': str(e)
            }
    
    async def _calculate_stress_invariants(self, max_stress, mean_stress, stress_tensor=None):
        """Advanced stress invariant calculations with full tensor analysis"""
        try:
            if stress_tensor is not None and isinstance(stress_tensor, np.ndarray):
                # Ensure 3x3 tensor
                if stress_tensor.shape != (3, 3):
                    stress_tensor = self._expand_to_3d_tensor(stress_tensor)
                
                # First invariant (trace)
                I1 = np.trace(stress_tensor)
                
                # Deviatoric stress tensor
                sigma_m = I1 / 3  # Mean stress
                s_ij = stress_tensor - sigma_m * np.eye(3)
                
                # Second invariant of deviatoric stress
                J2 = 0.5 * np.sum(s_ij ** 2)
                
                # Third invariant of deviatoric stress
                J3 = np.linalg.det(s_ij)
                
                # Lode angle (characterizes stress state)
                if J2 > 0:
                    lode_angle = np.arcsin(3 * np.sqrt(3) * J3 / (2 * J2 ** 1.5)) / 3
                    lode_angle_deg = np.degrees(lode_angle)
                else:
                    lode_angle = 0
                    lode_angle_deg = 0
                
                # Stress triaxiality ratio
                q = np.sqrt(3 * J2)  # von Mises equivalent stress
                eta = sigma_m / q if q > 0 else 0
                
                # Octahedral stresses
                sigma_oct = I1 / 3
                tau_oct = np.sqrt(2 * J2 / 3)
                
                # Principal stress differences
                eigenvalues = np.linalg.eigvalsh(stress_tensor)
                sigma_1, sigma_2, sigma_3 = np.sort(eigenvalues)[::-1]
                
                # Stress deviator magnitude
                s_mag = np.sqrt(2 * J2)
                
                # Normalized Lode parameter
                if (sigma_1 - sigma_3) != 0:
                    xi = (2 * sigma_2 - sigma_1 - sigma_3) / (sigma_1 - sigma_3)
                else:
                    xi = 0
                
            else:
                # Simplified calculation with assumptions
                I1 = 3 * mean_stress
                
                # Estimate J2 from max and mean stress
                q = abs(max_stress - mean_stress)  # Approximate von Mises
                J2 = q ** 2 / 3
                
                # Cannot calculate J3 without full tensor
                J3 = 0
                
                # Default values for simplified case
                lode_angle = 0
                lode_angle_deg = 0
                eta = mean_stress / q if q > 0 else 0
                sigma_oct = mean_stress
                tau_oct = q / np.sqrt(3)
                s_mag = q
                xi = 0
                
                sigma_1 = max_stress
                sigma_2 = mean_stress
                sigma_3 = 2 * mean_stress - max_stress
            
            # Calculate stress intensity factor (if crack geometry known)
            k_i = None
            if hasattr(self, 'crack_length_m') and self.crack_length_m > 0:
                # Mode I stress intensity factor (opening mode)
                k_i = max_stress * np.sqrt(np.pi * self.crack_length_m)
                
                # Check against fracture toughness
                if hasattr(self, 'fracture_toughness_mpa_m'):
                    crack_propagation = k_i > self.fracture_toughness_mpa_m
                else:
                    crack_propagation = None
            else:
                crack_propagation = None
            
            # Energy-based invariants
            elastic_energy_density = None
            if hasattr(self, 'elastic_modulus_gpa') and hasattr(self, 'poissons_ratio'):
                E = self.elastic_modulus_gpa * 1000  # Convert to MPa
                nu = self.poissons_ratio
                
                # Elastic strain energy density
                elastic_energy_density = (1 / (2 * E)) * (
                    I1 ** 2 * (1 - 2 * nu) / 3 + 2 * J2 * (1 + nu)
                )
            
            # Damage parameter based on invariants
            if hasattr(self, 'damage_model') and self.damage_model:
                damage_param = await self.damage_model.calculate_damage(I1, J2, J3)
            else:
                # Simple damage estimate
                damage_param = min(1.0, J2 / (100 ** 2))  # Normalized by typical rock strength
            
            # Store in database for trend analysis
            if hasattr(self, 'database_integration') and self.database_integration:
                await self.database_integration.store_stress_invariants({
                    'timestamp': datetime.utcnow(),
                    'location': getattr(self, 'current_location', None),
                    'I1': I1,
                    'J2': J2,
                    'J3': J3,
                    'lode_angle': lode_angle,
                    'stress_triaxiality': eta
                })
            
            return {
                'I1': float(I1),  # First invariant
                'I2': float(I1 ** 2 / 3 - 2 * J2),  # Second invariant (alternative form)
                'I3': float(np.linalg.det(stress_tensor)) if stress_tensor is not None else None,
                'J2': float(J2),  # Second deviatoric invariant
                'J3': float(J3),  # Third deviatoric invariant
                'lode_angle_rad': float(lode_angle),
                'lode_angle_deg': float(lode_angle_deg),
                'lode_parameter_xi': float(xi),
                'stress_triaxiality_eta': float(eta),
                'octahedral_normal_stress': float(sigma_oct),
                'octahedral_shear_stress': float(tau_oct),
                'deviatoric_stress_magnitude': float(s_mag),
                'principal_stresses': {
                    'sigma_1': float(sigma_1),
                    'sigma_2': float(sigma_2),
                    'sigma_3': float(sigma_3)
                },
                'stress_intensity_factor_mpa_sqrtm': float(k_i) if k_i is not None else None,
                'crack_will_propagate': crack_propagation,
                'elastic_energy_density_mpa': float(elastic_energy_density) if elastic_energy_density else None,
                'damage_parameter': float(damage_param),
                'stress_state_type': self._classify_stress_state(lode_angle_deg, eta),
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Error calculating stress invariants: {e}")
            return {
                'I1': 3 * mean_stress, 
                'J2': (max_stress - mean_stress) ** 2 / 3, 
                'J3': 0,
                'error': str(e)
            }
    
    async def _calculate_von_mises_stress(self, stress, temperature_k=None, strain_rate=None):
        """Advanced von Mises stress calculation with temperature and rate effects"""
        try:
            von_mises_base = 0.0
            
            if isinstance(stress, np.ndarray):
                if stress.shape == (3, 3):
                    # Full 3D stress tensor
                    s11, s22, s33 = stress[0,0], stress[1,1], stress[2,2]
                    s12, s13, s23 = stress[0,1], stress[0,2], stress[1,2]
                    
                    # Classical von Mises formula
                    von_mises_base = np.sqrt(0.5 * (
                        (s11 - s22) ** 2 + (s22 - s33) ** 2 + (s33 - s11) ** 2 +
                        6 * (s12 ** 2 + s13 ** 2 + s23 ** 2)
                    ))
                    
                    # Alternative calculation using invariants
                    i1 = np.trace(stress)
                    s_dev = stress - (i1 / 3) * np.eye(3)
                    j2 = 0.5 * np.sum(s_dev ** 2)
                    von_mises_invariant = np.sqrt(3 * j2)
                    
                    # Use average for robustness
                    von_mises_base = (von_mises_base + von_mises_invariant) / 2
                    
                elif stress.shape == (2, 2):
                    # 2D stress (plane stress assumption)
                    s11, s22 = stress[0,0], stress[1,1]
                    s12 = stress[0,1]
                    s33 = 0  # Plane stress assumption
                    
                    von_mises_base = np.sqrt(s11 ** 2 + s22 ** 2 - s11 * s22 + 3 * s12 ** 2)
                    
                elif stress.ndim == 1 and len(stress) == 6:
                    # Voigt notation [s11, s22, s33, s12, s13, s23]
                    s11, s22, s33, s12, s13, s23 = stress
                    
                    von_mises_base = np.sqrt(0.5 * (
                        (s11 - s22) ** 2 + (s22 - s33) ** 2 + (s33 - s11) ** 2 +
                        6 * (s12 ** 2 + s13 ** 2 + s23 ** 2)
                    ))
                else:
                    # Fallback for other array shapes
                    von_mises_base = float(np.max(np.abs(stress)))
                    
            else:
                # Scalar stress
                von_mises_base = abs(float(stress))
            
            # Temperature-dependent yield strength adjustment
            temperature_factor = 1.0
            if temperature_k is not None and temperature_k > 0:
                # Get material properties from database
                if hasattr(self, 'database_integration') and self.database_integration:
                    material_props = await self.database_integration.get_material_properties(
                        material_type=getattr(self, 'material_type', 'steel'),
                        temperature_k=temperature_k
                    )
                    
                    if material_props:
                        # Use actual temperature-dependent data
                        reference_temp = material_props.get('reference_temperature_k', 293)
                        temp_coefficient = material_props.get('strength_temp_coefficient', -0.0005)
                        temperature_factor = 1 + temp_coefficient * (temperature_k - reference_temp)
                    else:
                        # Simplified model for metals
                        if temperature_k < 300:
                            temperature_factor = 1.0
                        elif temperature_k < 600:
                            temperature_factor = 1 - 0.0003 * (temperature_k - 300)
                        elif temperature_k < 900:
                            temperature_factor = 0.91 - 0.001 * (temperature_k - 600)
                        else:
                            temperature_factor = 0.61 - 0.002 * (temperature_k - 900)
                else:
                    # Default temperature model
                    temperature_factor = max(0.3, 1 - 0.0005 * (temperature_k - 293))
            
            # Strain rate effects (for dynamic loading)
            strain_rate_factor = 1.0
            if strain_rate is not None and strain_rate > 0:
                # Johnson-Cook type model for strain rate sensitivity
                reference_rate = 0.001  # Reference strain rate (1/s)
                c_param = 0.014  # Strain rate sensitivity parameter
                
                if strain_rate > reference_rate:
                    strain_rate_factor = 1 + c_param * np.log(strain_rate / reference_rate)
            
            # Effective von Mises stress
            von_mises_effective = von_mises_base * temperature_factor * strain_rate_factor
            
            # Calculate equivalent plastic strain if yield stress is known
            equivalent_plastic_strain = None
            if hasattr(self, 'yield_stress_mpa') and self.yield_stress_mpa > 0:
                if von_mises_effective > self.yield_stress_mpa:
                    # Simple elastic-perfectly plastic model
                    if hasattr(self, 'elastic_modulus_gpa'):
                        E = self.elastic_modulus_gpa * 1000  # Convert to MPa
                        equivalent_plastic_strain = (von_mises_effective - self.yield_stress_mpa) / E
                    else:
                        equivalent_plastic_strain = (von_mises_effective / self.yield_stress_mpa) - 1
                else:
                    equivalent_plastic_strain = 0.0
            
            # Fatigue life estimation (if cyclic loading)
            fatigue_life_cycles = None
            if hasattr(self, 'loading_cycles') and self.loading_cycles > 0:
                # Basquin's equation for high-cycle fatigue
                if hasattr(self, 'fatigue_strength_mpa') and hasattr(self, 'fatigue_exponent'):
                    sigma_f = self.fatigue_strength_mpa
                    b = self.fatigue_exponent
                    fatigue_life_cycles = (von_mises_effective / sigma_f) ** (-1 / b)
                else:
                    # Simplified S-N curve
                    if von_mises_effective < 0.5 * self.yield_stress_mpa if hasattr(self, 'yield_stress_mpa') else 200:
                        fatigue_life_cycles = 1e7  # Infinite life
                    else:
                        fatigue_life_cycles = 1e6 * (200 / von_mises_effective) ** 3
            
            # Creep assessment (if temperature and time are significant)
            creep_rate = None
            if temperature_k is not None and temperature_k > 0.3 * getattr(self, 'melting_temperature_k', 1800):
                # Norton's power law for steady-state creep
                if hasattr(self, 'creep_parameters'):
                    A = self.creep_parameters.get('A', 1e-20)
                    n = self.creep_parameters.get('n', 3)
                    Q = self.creep_parameters.get('Q', 200000)  # Activation energy (J/mol)
                    R = 8.314  # Gas constant
                    
                    creep_rate = A * (von_mises_effective ** n) * np.exp(-Q / (R * temperature_k))
                else:
                    # Simplified creep model
                    creep_rate = 1e-10 * (von_mises_effective / 100) ** 3 * np.exp(-20000 / temperature_k)
            
            # Store result for ML training
            if hasattr(self, 'model_manager') and self.model_manager:
                await self.model_manager.log_stress_calculation({
                    'von_mises': von_mises_effective,
                    'temperature_k': temperature_k,
                    'strain_rate': strain_rate,
                    'timestamp': datetime.utcnow()
                })
            
            return {
                'von_mises_stress_mpa': float(von_mises_effective),
                'von_mises_base_mpa': float(von_mises_base),
                'temperature_factor': float(temperature_factor),
                'strain_rate_factor': float(strain_rate_factor),
                'temperature_k': float(temperature_k) if temperature_k else None,
                'strain_rate_per_s': float(strain_rate) if strain_rate else None,
                'equivalent_plastic_strain': float(equivalent_plastic_strain) if equivalent_plastic_strain is not None else None,
                'yielded': bool(von_mises_effective > getattr(self, 'yield_stress_mpa', float('inf'))),
                'fatigue_life_cycles': float(fatigue_life_cycles) if fatigue_life_cycles else None,
                'creep_rate_per_s': float(creep_rate) if creep_rate else None,
                'failure_probability': self._calculate_failure_probability(von_mises_effective),
                'safety_factor': float(getattr(self, 'ultimate_stress_mpa', 500) / von_mises_effective) if von_mises_effective > 0 else float('inf'),
                'stress_ratio': float(von_mises_effective / getattr(self, 'yield_stress_mpa', 250)) if hasattr(self, 'yield_stress_mpa') else None,
                'timestamp': datetime.utcnow().isoformat()
            }
            
        except Exception as e:
            self.logger.error(f"Error calculating von Mises stress: {e}")
            # Fallback calculation
            if hasattr(stress, '__len__'):
                return {'von_mises_stress_mpa': float(np.max(np.abs(stress))), 'error': str(e)}
            else:
                return {'von_mises_stress_mpa': abs(float(stress)), 'error': str(e)}
    
    def _expand_to_3d_tensor(self, stress):
        """Expand 2D stress to 3D tensor with assumptions"""
        if isinstance(stress, np.ndarray) and stress.shape == (2, 2):
            # Plane stress assumption
            stress_3d = np.zeros((3, 3))
            stress_3d[:2, :2] = stress
            return stress_3d
        return stress
    
    def _validate_stress_orientation(self, calculated, observed):
        """Validate calculated stress orientation against observations"""
        if observed is None:
            return 0.5  # No validation data
        
        # Angular difference
        diff = abs(calculated - np.radians(observed))
        diff = min(diff, 2 * np.pi - diff)  # Handle circular nature
        
        # Convert to score (1 = perfect match, 0 = 90 degrees off)
        return max(0, 1 - diff / (np.pi / 2))
    
    def _calculate_coulomb_stress_change(self, current_state, reference_state, friction_coefficient):
        """Calculate Coulomb stress change between states"""
        try:
            if isinstance(current_state, dict):
                # Simple calculation
                delta_tau = current_state['max'] - reference_state['max']
                delta_sigma = current_state['mean'] - reference_state['mean']
            else:
                # Tensor calculation
                delta_stress = current_state - reference_state
                # Project onto optimal failure plane
                delta_tau = np.max(np.abs(delta_stress[0, 1]))  # Simplified
                delta_sigma = delta_stress[0, 0]  # Normal stress change
            
            # Coulomb stress change
            return delta_tau + friction_coefficient * delta_sigma
            
        except Exception:
            return None
    
    def _determine_failure_mode(self, fos_mc, fos_hb, mean_stress):
        """Determine likely failure mode based on stress state"""
        if mean_stress < 0:
            return "tensile"
        elif fos_mc < fos_hb:
            return "shear_mohr_coulomb"
        elif fos_hb < fos_mc:
            return "shear_hoek_brown"
        elif mean_stress > 500:  # High confinement
            return "ductile"
        else:
            return "mixed_mode"
    
    def _classify_stress_state(self, lode_angle_deg, triaxiality):
        """Classify stress state based on invariants"""
        if abs(lode_angle_deg) < 10:
            state = "triaxial_extension"
        elif abs(lode_angle_deg - 30) < 10:
            state = "pure_shear"
        elif abs(lode_angle_deg + 30) < 10:
            state = "triaxial_compression"
        else:
            state = "general_3d"
        
        if triaxiality < -0.33:
            state += "_compressive"
        elif triaxiality > 0.33:
            state += "_tensile"
        else:
            state += "_shear_dominated"
        
        return state
    
    def _calculate_failure_probability(self, von_mises_stress):
        """Calculate failure probability using reliability methods"""
        if not hasattr(self, 'yield_stress_mpa'):
            return 0.0
        
        # Simple reliability index
        if hasattr(self, 'yield_stress_std_mpa'):
            # Account for uncertainty
            mean_margin = self.yield_stress_mpa - von_mises_stress
            std_margin = self.yield_stress_std_mpa
            
            if std_margin > 0:
                reliability_index = mean_margin / std_margin
                # Convert to probability using normal CDF approximation
                from scipy.stats import norm
                failure_prob = norm.cdf(-reliability_index)
            else:
                failure_prob = 1.0 if von_mises_stress > self.yield_stress_mpa else 0.0
        else:
            # Deterministic comparison
            failure_prob = min(1.0, von_mises_stress / self.yield_stress_mpa) if self.yield_stress_mpa > 0 else 0.0
        
        return float(failure_prob)
    
