    # Failure analysis supporting methods
    async def _mohr_coulomb_analysis(self, principal_stresses, rock_properties):
        """Mohr-Coulomb failure analysis"""
        cohesion = 10e6  # Pa default
        friction_angle = 30  # degrees default
        
        sigma_1 = principal_stresses['sigma_1']
        sigma_3 = principal_stresses['sigma_3']
        
        # Mohr-Coulomb criterion
        phi_rad = np.radians(friction_angle)
        tan_alpha = np.tan(np.pi/4 + phi_rad/2)
        failure_stress = sigma_3 * tan_alpha**2 + 2 * cohesion * tan_alpha
        
        safety_factor = failure_stress / sigma_1 if sigma_1 > 0 else float('inf')
        failure_probability = max(0, min(1, (sigma_1 - failure_stress) / failure_stress))
        
        return {
            'criterion': 'mohr_coulomb',
            'failure_stress': failure_stress,
            'safety_factor': safety_factor,
            'failure_probability': failure_probability,
            'failure_mode': 'shear' if safety_factor < 1 else 'stable'
        }
    
    async def _hoek_brown_analysis(self, principal_stresses, rock_properties):
        """Hoek-Brown failure analysis"""
        ucs = 100e6  # Pa default
        mi = 10  # Material constant
        
        sigma_1 = principal_stresses['sigma_1']
        sigma_3 = principal_stresses['sigma_3']
        
        # Hoek-Brown criterion
        sigma_3_norm = sigma_3 / ucs
        expected_sigma_1 = sigma_3 + ucs * np.sqrt(mi * sigma_3_norm + 1)
        
        safety_factor = expected_sigma_1 / sigma_1 if sigma_1 > 0 else float('inf')
        failure_probability = max(0, min(1, (sigma_1 - expected_sigma_1) / expected_sigma_1))
        
        return {
            'criterion': 'hoek_brown',
            'expected_sigma_1': expected_sigma_1,
            'safety_factor': safety_factor,
            'failure_probability': failure_probability,
            'failure_mode': 'rock_mass_failure' if safety_factor < 1 else 'stable'
        }
    
    async def _griffith_crack_analysis(self, principal_stresses, rock_properties):
        """Griffith crack propagation analysis"""
        tensile_strength = 5e6  # Pa default
        
        sigma_3 = principal_stresses['sigma_3']
        
        # Griffith criterion for tensile failure
        safety_factor = tensile_strength / abs(sigma_3) if sigma_3 < 0 else float('inf')
        failure_probability = max(0, min(1, 1 - 1/safety_factor)) if safety_factor < float('inf') else 0
        
        return {
            'criterion': 'griffith',
            'safety_factor': safety_factor,
            'failure_probability': failure_probability,
            'failure_mode': 'tensile_cracking' if safety_factor < 1 else 'stable'
        }
    
    # Simplified placeholder implementations for other analysis methods
    async def _drucker_prager_analysis(self, principal_stresses, rock_properties):
        """Advanced Drucker-Prager failure analysis with real database integration"""
        try:
            from scipy.stats import norm
            import numpy as np
            
            # Extract principal stress components
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            # Query real rock properties from database or use provided
            if hasattr(self, 'db_manager') and self.db_manager:
                db_properties = await self.db_manager.query(
                    """SELECT cohesion_mpa, friction_angle_deg, tensile_strength_mpa,
                       elastic_modulus_gpa, poisson_ratio
                       FROM rock_mechanical_properties
                       WHERE lithology = %s
                       ORDER BY data_quality_grade ASC LIMIT 1""",
                    [rock_properties.get('lithology', 'granite')]
                )
                if db_properties:
                    rock_properties.update(db_properties[0])
            
            # Material parameters with defaults from literature
            cohesion = rock_properties.get('cohesion_mpa', 27.0) * 1e6  # Convert to Pa
            friction_angle = np.radians(rock_properties.get('friction_angle_deg', 35.0))
            tensile_strength = rock_properties.get('tensile_strength_mpa', 10.0) * 1e6
            
            # Calculate stress invariants
            I1 = sigma_1 + sigma_2 + sigma_3  # First invariant
            mean_stress = I1 / 3.0
            
            # Deviatoric stresses
            s1 = sigma_1 - mean_stress
            s2 = sigma_2 - mean_stress
            s3 = sigma_3 - mean_stress
            
            # Second invariant of deviatoric stress
            J2 = (s1**2 + s2**2 + s3**2) / 2.0
            sqrt_J2 = np.sqrt(J2)
            
            # Third invariant of deviatoric stress
            J3 = s1 * s2 * s3
            
            # Lode angle for intermediate stress effects
            if sqrt_J2 > 0:
                lode_angle = np.arcsin(np.clip(-3*np.sqrt(3)*J3/(2*J2**1.5), -1, 1)) / 3.0
            else:
                lode_angle = 0.0
            
            # Drucker-Prager parameters from Mohr-Coulomb
            if friction_angle > 0:
                alpha = 2 * np.sin(friction_angle) / (np.sqrt(3) * (3 - np.sin(friction_angle)))
                k = 6 * cohesion * np.cos(friction_angle) / (np.sqrt(3) * (3 - np.sin(friction_angle)))
            else:
                alpha = 0.0
                k = 2 * cohesion / np.sqrt(3)
            
            # Modified Drucker-Prager with cap and tension cutoff
            # Shear failure function
            f_shear = sqrt_J2 + alpha * I1 - k
            
            # Tensile cutoff
            f_tension = I1 - 3 * tensile_strength
            
            # Cap yield surface for compaction
            cap_position = rock_properties.get('preconsolidation_pressure', 500e6)
            cap_eccentricity = rock_properties.get('cap_eccentricity', 0.7)
            if I1 > cap_position:
                f_cap = ((I1 - cap_position)**2 + (sqrt_J2/cap_eccentricity)**2) - (k/cap_eccentricity)**2
            else:
                f_cap = -1.0  # No cap yield
            
            # Determine active failure mode
            active_function = max(f_shear, f_tension, f_cap)
            
            # Calculate safety factor
            if active_function == f_shear:
                safety_factor = k / (sqrt_J2 + alpha * I1) if (sqrt_J2 + alpha * I1) > 0 else float('inf')
                failure_mode = 'shear'
            elif active_function == f_tension:
                safety_factor = (3 * tensile_strength) / I1 if I1 > 0 else float('inf')
                failure_mode = 'tensile'
            else:
                safety_factor = 1.0 / (1.0 + f_cap) if f_cap > 0 else float('inf')
                failure_mode = 'compaction'
            
            # Probabilistic failure assessment with uncertainty
            if safety_factor < float('inf'):
                # Log-normal distribution for strength uncertainty
                cov = rock_properties.get('strength_cov', 0.3)  # Coefficient of variation
                failure_probability = 1.0 - norm.cdf(np.log(safety_factor) / (cov * np.sqrt(2)))
            else:
                failure_probability = 0.0
            
            return {
                'criterion': 'drucker_prager_advanced',
                'failure_probability': min(1.0, max(0.0, failure_probability)),
                'safety_factor': min(100.0, safety_factor),
                'failure_mode': failure_mode,
                'stress_invariants': {
                    'I1': I1,
                    'J2': J2,
                    'J3': J3,
                    'lode_angle_deg': np.degrees(lode_angle)
                },
                'material_parameters': {
                    'alpha': alpha,
                    'k': k,
                    'cohesion_mpa': cohesion / 1e6,
                    'friction_angle_deg': np.degrees(friction_angle)
                },
                'yield_functions': {
                    'f_shear': f_shear,
                    'f_tension': f_tension,
                    'f_cap': f_cap
                }
            }
            
        except Exception as e:
            self.logger.error(f"Drucker-Prager analysis failed: {e}")
            return {
                'criterion': 'drucker_prager',
                'failure_probability': 0.5,
                'safety_factor': 1.0,
                'error': str(e)
            }
    
    async def _cam_clay_analysis(self, principal_stresses, rock_properties):
        """Advanced Modified Cam-Clay analysis for soil and soft rock behavior"""
        try:
            import numpy as np
            
            # Extract principal stresses
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            # Query soil/soft rock properties from database
            if hasattr(self, 'db_manager') and self.db_manager:
                db_properties = await self.db_manager.query(
                    """SELECT preconsolidation_pressure, critical_state_friction,
                       compression_index, recompression_index, void_ratio
                       FROM literature_rock_properties
                       WHERE rock_type = %s AND property_name IN 
                       ('preconsolidation_pressure', 'critical_state_friction')""",
                    [rock_properties.get('lithology', 'clay')]
                )
                if db_properties:
                    for prop in db_properties:
                        rock_properties[prop['property_name']] = prop['property_value']
            
            # Modified Cam-Clay parameters
            pc = rock_properties.get('preconsolidation_pressure', 10.0) * 1e6  # Pa
            M = rock_properties.get('critical_state_slope', 1.2)  # Critical state line slope
            lambda_cc = rock_properties.get('compression_index', 0.2)  # Virgin compression index
            kappa = rock_properties.get('recompression_index', 0.04)  # Recompression index
            e0 = rock_properties.get('initial_void_ratio', 0.8)  # Initial void ratio
            nu = rock_properties.get('poisson_ratio', 0.3)
            
            # Calculate stress invariants
            p = (sigma_1 + sigma_2 + sigma_3) / 3.0  # Mean effective stress
            
            # Deviatoric stress tensor
            s1 = sigma_1 - p
            s2 = sigma_2 - p
            s3 = sigma_3 - p
            
            # Deviatoric stress invariant
            q = np.sqrt(1.5 * (s1**2 + s2**2 + s3**2))  # Equivalent deviatoric stress
            
            # Stress ratio
            eta = q / p if p > 0 else 0.0
            
            # Modified Cam-Clay yield function
            # f = (q/M)^2 + p*(p - pc) = 0
            if p > 0:
                f_mcc = (q/M)**2 + p*(p - pc)
            else:
                f_mcc = -pc  # Tensile region
            
            # Calculate plastic potential and flow rule
            if f_mcc > 0:
                # Plastic state
                # Associated flow rule
                df_dp = 2*p - pc
                df_dq = 2*q/(M**2)
                
                # Plastic strain increment direction
                if df_dq > 0:
                    plastic_strain_ratio = df_dp / df_dq
                else:
                    plastic_strain_ratio = float('inf')
                
                # Hardening/softening parameter
                if p > pc/2:
                    # Hardening (wet side)
                    hardening_mode = 'hardening'
                    volumetric_behavior = 'contractive'
                else:
                    # Softening (dry side)
                    hardening_mode = 'softening'
                    volumetric_behavior = 'dilative'
            else:
                # Elastic state
                plastic_strain_ratio = 0.0
                hardening_mode = 'elastic'
                volumetric_behavior = 'elastic'
            
            # Calculate specific volume
            v = 1 + e0  # Specific volume
            
            # Normal consolidation line (NCL)
            if p > 0:
                v_ncl = v - lambda_cc * np.log(p/1e6)  # Reference at 1 MPa
            else:
                v_ncl = v
            
            # Critical state line (CSL)
            if p > 0:
                v_csl = v_ncl - (lambda_cc - kappa) * np.log(pc/p) if pc > p else v_ncl
            else:
                v_csl = v_ncl
            
            # Overconsolidation ratio (OCR)
            OCR = pc / p if p > 0 else float('inf')
            
            # Safety factor based on distance to yield surface
            if eta < M:
                # Below critical state line
                safety_factor = M / eta if eta > 0 else float('inf')
            else:
                safety_factor = 0.5  # Above critical state line (unstable)
            
            # Failure probability based on yield function
            if f_mcc > 0:
                # Already yielding
                failure_probability = min(1.0, 0.5 + f_mcc/(2*pc))
            else:
                # Elastic state - probability based on proximity to yield
                margin = abs(f_mcc) / pc
                failure_probability = max(0.0, 1.0 - margin)
            
            return {
                'criterion': 'modified_cam_clay',
                'failure_probability': min(1.0, max(0.0, failure_probability)),
                'safety_factor': min(100.0, safety_factor),
                'yield_function': f_mcc,
                'stress_state': {
                    'mean_stress_p': p / 1e6,  # MPa
                    'deviatoric_stress_q': q / 1e6,  # MPa
                    'stress_ratio_eta': eta,
                    'overconsolidation_ratio': min(100.0, OCR)
                },
                'material_state': {
                    'specific_volume': v,
                    'void_ratio': e0,
                    'ncl_specific_volume': v_ncl,
                    'csl_specific_volume': v_csl,
                    'hardening_mode': hardening_mode,
                    'volumetric_behavior': volumetric_behavior
                },
                'parameters': {
                    'preconsolidation_mpa': pc / 1e6,
                    'critical_state_slope_M': M,
                    'compression_index_lambda': lambda_cc,
                    'recompression_index_kappa': kappa
                }
            }
            
        except Exception as e:
            self.logger.error(f"Cam-Clay analysis failed: {e}")
            return {
                'criterion': 'cam_clay',
                'failure_probability': 0.5,
                'safety_factor': 1.0,
                'error': str(e)
            }
    
    async def _thermal_failure_analysis(self, principal_stresses, rock_properties):
        """Advanced thermo-mechanical coupled failure analysis"""
        try:
            from scipy.special import erf
            import numpy as np
            
            # Extract stresses and temperature
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            # Get temperature data from real-time monitoring or database
            temperature = rock_properties.get('temperature_c', 25.0)
            if hasattr(self, 'external_data_connectors') and 'NOAA' in self.external_data_connectors:
                # Query real-time temperature data if available
                try:
                    temp_data = await self.external_data_connectors['NOAA'].get_subsurface_temperature(
                        lat=rock_properties.get('latitude'),
                        lon=rock_properties.get('longitude'),
                        depth=rock_properties.get('depth_km', 0.0)
                    )
                    if temp_data:
                        temperature = temp_data.get('temperature_c', temperature)
                except:
                    pass
            
            # Query temperature-dependent properties from database
            if hasattr(self, 'db_manager') and self.db_manager:
                thermal_props = await self.db_manager.query(
                    """SELECT thermal_expansion_per_k, thermal_conductivity_w_m_k,
                       elastic_modulus_gpa, tensile_strength_mpa
                       FROM rock_mechanical_properties
                       WHERE lithology = %s""",
                    [rock_properties.get('lithology', 'granite')]
                )
                if thermal_props:
                    rock_properties.update(thermal_props[0])
            
            # Thermal properties
            alpha_thermal = rock_properties.get('thermal_expansion_per_k', 8e-6)  # 1/K
            k_thermal = rock_properties.get('thermal_conductivity_w_m_k', 2.5)  # W/(m·K)
            E = rock_properties.get('elastic_modulus_gpa', 50.0) * 1e9  # Pa
            nu = rock_properties.get('poisson_ratio', 0.25)
            cp = rock_properties.get('specific_heat_j_kg_k', 900.0)  # J/(kg·K)
            rho = rock_properties.get('density_kg_m3', 2700.0)  # kg/m³
            
            # Reference temperature (ambient)
            T_ref = rock_properties.get('reference_temperature_c', 20.0)
            delta_T = temperature - T_ref
            
            # Thermal stress calculation
            thermal_stress = E * alpha_thermal * delta_T / (1 - 2*nu)
            
            # Effective stresses including thermal effects
            sigma_1_eff = sigma_1 + thermal_stress
            sigma_2_eff = sigma_2 + thermal_stress
            sigma_3_eff = sigma_3 + thermal_stress
            
            # Temperature-dependent strength reduction
            T_melt = rock_properties.get('melting_temperature_c', 1200.0)
            if temperature < T_melt:
                strength_reduction = 1.0 - (temperature/T_melt)**2
            else:
                strength_reduction = 0.1  # Molten state
            
            # Modified tensile and compressive strengths
            tensile_strength_0 = rock_properties.get('tensile_strength_mpa', 10.0) * 1e6
            compressive_strength_0 = rock_properties.get('ucs_mpa', 100.0) * 1e6
            
            tensile_strength = tensile_strength_0 * strength_reduction
            compressive_strength = compressive_strength_0 * strength_reduction
            
            # Thermal shock analysis
            thermal_shock_param = 0.0
            characteristic_length = rock_properties.get('characteristic_length_m', 1.0)
            if 'temperature_history' in rock_properties:
                temp_history = rock_properties['temperature_history']
                if len(temp_history) > 1:
                    dT_dt = (temp_history[-1] - temp_history[-2]) / rock_properties.get('time_step', 1.0)
                    # Thermal diffusivity
                    thermal_diffusivity = k_thermal / (rho * cp)
                    thermal_shock_param = abs(dT_dt) * characteristic_length / thermal_diffusivity
                    
                    # Additional stress from thermal shock
                    if thermal_shock_param > 1.0:
                        thermal_shock_stress = E * alpha_thermal * abs(dT_dt) * characteristic_length / (2 * thermal_diffusivity)
                        sigma_1_eff += thermal_shock_stress
                        sigma_3_eff -= thermal_shock_stress
            
            # Thermal gradient stress
            thermal_gradient = rock_properties.get('thermal_gradient_k_m', 0.0)
            if thermal_gradient > 0:
                gradient_stress = E * alpha_thermal * thermal_gradient * characteristic_length / (1 - nu)
            else:
                gradient_stress = 0.0
            
            # Combined thermal failure criterion
            if sigma_3_eff < 0:  # Tensile
                f_tensile = abs(sigma_3_eff) - tensile_strength
            else:
                f_tensile = -tensile_strength
            
            # Von Mises criterion for compression
            von_mises = np.sqrt(0.5 * ((sigma_1_eff - sigma_2_eff)**2 + 
                                       (sigma_2_eff - sigma_3_eff)**2 + 
                                       (sigma_3_eff - sigma_1_eff)**2))
            f_compression = von_mises - compressive_strength
            
            # Thermal fatigue
            n_cycles = rock_properties.get('thermal_cycles', 0)
            if n_cycles > 0:
                C = 1e-12
                m = 3.0
                crack_growth_rate = C * (delta_T * E * alpha_thermal)**m
                accumulated_damage = crack_growth_rate * n_cycles
                fatigue_factor = 1.0 / (1.0 + accumulated_damage)
            else:
                fatigue_factor = 1.0
            
            # Determine dominant failure mode
            if f_tensile > f_compression:
                dominant_mode = 'thermal_tensile_cracking'
                safety_factor = tensile_strength / abs(sigma_3_eff) if sigma_3_eff < 0 else float('inf')
            else:
                dominant_mode = 'thermal_compression_failure'
                safety_factor = compressive_strength / von_mises if von_mises > 0 else float('inf')
            
            safety_factor *= fatigue_factor
            
            # Probabilistic assessment
            temp_uncertainty = rock_properties.get('temperature_uncertainty_c', 50.0)
            if safety_factor < float('inf'):
                z_score = (safety_factor - 1.0) / (temp_uncertainty / 100.0)
                failure_probability = 0.5 * (1.0 - erf(z_score / np.sqrt(2)))
            else:
                failure_probability = 0.0
            
            return {
                'criterion': 'thermal_failure_advanced',
                'failure_probability': min(1.0, max(0.0, failure_probability)),
                'safety_factor': min(100.0, safety_factor),
                'failure_mode': dominant_mode,
                'temperature_effects': {
                    'temperature_c': temperature,
                    'delta_T_c': delta_T,
                    'thermal_stress_mpa': thermal_stress / 1e6,
                    'strength_reduction_factor': strength_reduction,
                    'thermal_shock_parameter': thermal_shock_param,
                    'thermal_gradient_stress_mpa': gradient_stress / 1e6
                },
                'effective_stresses_mpa': {
                    'sigma_1_thermal': sigma_1_eff / 1e6,
                    'sigma_2_thermal': sigma_2_eff / 1e6,
                    'sigma_3_thermal': sigma_3_eff / 1e6,
                    'von_mises': von_mises / 1e6
                },
                'fatigue_analysis': {
                    'thermal_cycles': n_cycles,
                    'fatigue_damage_factor': 1.0 - fatigue_factor,
                    'remaining_life_fraction': fatigue_factor
                }
            }
            
        except Exception as e:
            self.logger.error(f"Thermal failure analysis failed: {e}")
            return {
                'criterion': 'thermal',
                'failure_probability': 0.5,
                'safety_factor': 1.0,
                'error': str(e)
            }
    
    async def _progressive_failure_modeling(self, principal_stresses, rock_properties):
        """Advanced progressive failure modeling with damage evolution"""
        try:
            import scipy.integrate as integrate
            import numpy as np
            
            # Extract stress components
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            # Query damage evolution parameters from database
            if hasattr(self, 'db_manager') and self.db_manager:
                damage_params = await self.db_manager.query(
                    """SELECT property_value FROM literature_rock_properties
                       WHERE rock_type = %s AND property_name LIKE '%damage%' OR property_name LIKE '%fracture_toughness%'""",
                    [rock_properties.get('lithology', 'granite')]
                )
                if damage_params:
                    for param in damage_params:
                        if 'fracture_toughness' in param.get('property_name', ''):
                            rock_properties['fracture_toughness_mpa_m05'] = param['property_value']
            
            # Damage mechanics parameters
            K_IC = rock_properties.get('fracture_toughness_mpa_m05', 2.0) * 1e6 * np.sqrt(1.0)  # Pa√m
            n = rock_properties.get('crack_growth_exponent', 3.0)
            D_threshold = rock_properties.get('damage_threshold', 0.1)
            D_critical = rock_properties.get('critical_damage', 0.8)
            E0 = rock_properties.get('elastic_modulus_gpa', 50.0) * 1e9  # Pa
            
            # Current damage state
            D_current = rock_properties.get('current_damage', 0.0)
            
            # Calculate effective stress considering existing damage
            stress_concentration = 1.0 / (1.0 - D_current) if D_current < 1.0 else float('inf')
            
            sigma_1_eff = sigma_1 * stress_concentration
            sigma_2_eff = sigma_2 * stress_concentration
            sigma_3_eff = sigma_3 * stress_concentration
            
            # Equivalent stress for damage evolution (von Mises)
            von_mises = np.sqrt(0.5 * ((sigma_1_eff - sigma_2_eff)**2 + 
                                       (sigma_2_eff - sigma_3_eff)**2 + 
                                       (sigma_3_eff - sigma_1_eff)**2))
            
            # Damage driving force
            Y = von_mises**2 / (2 * E0 * (1 - D_current)**2) if D_current < 1.0 else float('inf')
            
            # Damage evolution rate (Kachanov-Rabotnov model)
            if Y > 0:
                A = rock_properties.get('damage_rate_coefficient', 1e-10)
                dD_dt = A * (Y / K_IC)**n * (1 - D_current)**(n-1)
            else:
                dD_dt = 0.0
            
            # Time to failure prediction
            if dD_dt > 0 and D_current < D_critical:
                try:
                    time_to_failure = (D_critical - D_current) / dD_dt
                except:
                    time_to_failure = float('inf')
            else:
                time_to_failure = float('inf')
            
            # Identify failure stages based on current damage
            failure_stages = []
            
            if D_current < D_threshold:
                failure_stages.append({
                    'stage': 1,
                    'name': 'elastic',
                    'damage_range': [0, D_threshold],
                    'description': 'Elastic deformation with micro-crack initiation'
                })
            
            if D_threshold <= D_current < 0.3:
                failure_stages.append({
                    'stage': 2,
                    'name': 'stable_crack_growth',
                    'damage_range': [D_threshold, 0.3],
                    'description': 'Stable crack propagation with strain hardening'
                })
            
            if 0.3 <= D_current < 0.6:
                failure_stages.append({
                    'stage': 3,
                    'name': 'crack_coalescence',
                    'damage_range': [0.3, 0.6],
                    'description': 'Crack interaction and coalescence'
                })
            
            if 0.6 <= D_current < D_critical:
                failure_stages.append({
                    'stage': 4,
                    'name': 'unstable_propagation',
                    'damage_range': [0.6, D_critical],
                    'description': 'Unstable crack propagation approaching failure'
                })
            
            if D_current >= D_critical:
                failure_stages.append({
                    'stage': 5,
                    'name': 'failure',
                    'damage_range': [D_critical, 1.0],
                    'description': 'Complete failure with loss of load-bearing capacity'
                })
            
            # Current stage identification
            current_stage = len([s for s in failure_stages if s['damage_range'][0] <= D_current])
            
            # Remaining load capacity
            remaining_capacity = (1 - D_current) * rock_properties.get('ucs_mpa', 100.0)
            
            # Failure probability based on damage state
            if D_current >= D_critical:
                failure_probability = 1.0
            elif D_current >= D_threshold:
                # Weibull distribution for progressive failure
                m_weibull = rock_properties.get('weibull_modulus', 5.0)
                failure_probability = 1.0 - np.exp(-((D_current/D_critical)**m_weibull))
            else:
                failure_probability = 0.0
            
            return {
                'failure_stages': current_stage,
                'time_to_complete_failure': min(1e10, time_to_failure),
                'current_damage': D_current,
                'damage_rate': dD_dt,
                'damage_evolution': {
                    'damage_driving_force_Y': Y / 1e6,  # MPa
                    'stress_concentration_factor': stress_concentration,
                    'effective_von_mises_mpa': von_mises / 1e6
                },
                'stage_details': failure_stages,
                'remaining_capacity_mpa': remaining_capacity,
                'failure_probability': failure_probability,
                'critical_parameters': {
                    'damage_threshold': D_threshold,
                    'critical_damage': D_critical,
                    'fracture_toughness_mpa_sqrtm': K_IC / 1e6,
                    'damage_exponent': n
                }
            }
            
        except Exception as e:
            self.logger.error(f"Progressive failure modeling failed: {e}")
            return {
                'failure_stages': 1,
                'time_to_complete_failure': float('inf'),
                'error': str(e)
            }
    
    async def _temporal_failure_analysis(self, principal_stresses, rock_properties):
        """Advanced viscoelastic and creep failure analysis"""
        try:
            import numpy as np
            from scipy.special import gamma
            
            # Extract stresses
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            # Von Mises equivalent stress
            von_mises = np.sqrt(0.5 * ((sigma_1 - sigma_2)**2 + 
                                       (sigma_2 - sigma_3)**2 + 
                                       (sigma_3 - sigma_1)**2))
            
            # Temperature for creep calculations
            temperature = rock_properties.get('temperature_c', 25.0) + 273.15  # Kelvin
            
            # Query creep parameters from database
            if hasattr(self, 'db_manager') and self.db_manager:
                creep_params = await self.db_manager.query(
                    """SELECT property_value, property_name FROM literature_rock_properties
                       WHERE rock_type = %s AND (property_name LIKE '%creep%' OR 
                       property_name LIKE '%activation_energy%' OR property_name LIKE '%stress_exponent%')""",
                    [rock_properties.get('lithology', 'salt')]
                )
                if creep_params:
                    for param in creep_params:
                        rock_properties[param['property_name']] = param['property_value']
            
            # Creep parameters
            Q = rock_properties.get('activation_energy_j_mol', 200000.0)  # J/mol
            n = rock_properties.get('stress_exponent', 3.5)
            A = rock_properties.get('reference_strain_rate', 1e-10)  # 1/s
            R = 8.314  # Gas constant J/(mol·K)
            
            # Power-law creep (Norton-Bailey model)
            if von_mises > 0 and temperature > 0:
                strain_rate_steady = A * (von_mises/1e6)**n * np.exp(-Q/(R*temperature))
            else:
                strain_rate_steady = 0.0
            
            # Burger's viscoelastic model parameters
            E_maxwell = rock_properties.get('maxwell_modulus_gpa', 30.0) * 1e9  # Pa
            eta_maxwell = rock_properties.get('maxwell_viscosity_pa_s', 1e20)  # Pa·s
            E_kelvin = rock_properties.get('kelvin_modulus_gpa', 20.0) * 1e9  # Pa
            eta_kelvin = rock_properties.get('kelvin_viscosity_pa_s', 1e18)  # Pa·s
            
            # Relaxation times
            tau_maxwell = eta_maxwell / E_maxwell
            tau_kelvin = eta_kelvin / E_kelvin
            
            # Time since loading
            time_current = rock_properties.get('time_since_loading_s', 0.0)
            
            # Burger's model strain response
            if von_mises > 0:
                # Instantaneous elastic strain
                strain_elastic = von_mises / E_maxwell
                
                # Delayed elastic strain (Kelvin element)
                strain_kelvin = (von_mises / E_kelvin) * (1 - np.exp(-time_current/tau_kelvin))
                
                # Viscous strain (Maxwell dashpot)
                strain_viscous = (von_mises / eta_maxwell) * time_current
                
                # Total strain
                total_strain = strain_elastic + strain_kelvin + strain_viscous
            else:
                total_strain = 0.0
                strain_elastic = 0.0
                strain_kelvin = 0.0
                strain_viscous = 0.0
            
            # Tertiary creep and failure prediction (Monkman-Grant)
            if strain_rate_steady > 0:
                C_mg = rock_properties.get('monkman_grant_constant', 0.01)
                m_mg = rock_properties.get('monkman_grant_exponent', 1.0)
                
                time_to_rupture = C_mg / (strain_rate_steady**m_mg)
                
                # Current creep stage
                if time_current < 0.1 * time_to_rupture:
                    creep_stage = 'primary'
                    stage_description = 'Decelerating creep with strain hardening'
                elif time_current < 0.9 * time_to_rupture:
                    creep_stage = 'secondary'
                    stage_description = 'Steady-state creep'
                else:
                    creep_stage = 'tertiary'
                    stage_description = 'Accelerating creep approaching failure'
            else:
                time_to_rupture = float('inf')
                creep_stage = 'negligible'
                stage_description = 'Creep effects negligible'
            
            # Time-dependent strength degradation
            if time_current > 0 and time_to_rupture < float('inf'):
                strength_reduction = np.exp(-(time_current/time_to_rupture)**2)
            else:
                strength_reduction = 1.0
            
            # Effective time-dependent strength
            initial_strength = rock_properties.get('ucs_mpa', 100.0) * 1e6
            current_strength = initial_strength * strength_reduction
            
            # Safety factor
            if von_mises > 0:
                safety_factor = current_strength / von_mises
            else:
                safety_factor = float('inf')
            
            # Creep damage accumulation (Robinson's rule)
            if time_to_rupture > 0:
                damage_fraction = time_current / time_to_rupture
            else:
                damage_fraction = 0.0
            
            # Larson-Miller parameter for life prediction
            if temperature > 0 and time_to_rupture < float('inf'):
                C_lm = rock_properties.get('larson_miller_constant', 20.0)
                LMP = temperature * (C_lm + np.log10(time_to_rupture/3600))  # Hours
            else:
                LMP = 0.0
            
            return {
                'creep_rate': strain_rate_steady,
                'time_dependent_strength': strength_reduction,
                'viscoelastic_analysis': {
                    'total_strain': total_strain,
                    'elastic_strain': strain_elastic,
                    'kelvin_strain': strain_kelvin,
                    'viscous_strain': strain_viscous,
                    'relaxation_time_maxwell_s': tau_maxwell,
                    'relaxation_time_kelvin_s': tau_kelvin
                },
                'creep_analysis': {
                    'steady_state_rate': strain_rate_steady,
                    'time_to_rupture_s': time_to_rupture,
                    'current_stage': creep_stage,
                    'stage_description': stage_description,
                    'damage_fraction': damage_fraction,
                    'larson_miller_parameter': LMP
                },
                'strength_evolution': {
                    'initial_strength_mpa': initial_strength / 1e6,
                    'current_strength_mpa': current_strength / 1e6,
                    'strength_reduction_factor': strength_reduction,
                    'safety_factor': safety_factor
                },
                'material_parameters': {
                    'activation_energy_kj_mol': Q / 1000,
                    'stress_exponent': n,
                    'temperature_k': temperature
                }
            }
            
        except Exception as e:
            self.logger.error(f"Temporal failure analysis failed: {e}")
            return {
                'creep_rate': 0.0,
                'time_dependent_strength': 1.0,
                'error': str(e)
            }
    
    async def _correlate_microseismic_activity(self, principal_stresses):
        """Advanced microseismic correlation with real-time seismic data"""
        try:
            import numpy as np
            
            # Calculate stress magnitude for correlation
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            differential_stress = sigma_1 - sigma_3
            
            # Initialize seismic data sources
            seismic_data = []
            b_value = 1.0  # Default Gutenberg-Richter b-value
            
            # Query seismic data from local PostgreSQL database
            if hasattr(self, 'db_manager') and self.db_manager:
                try:
                    lat = principal_stresses.get('latitude', 0.0)
                    lon = principal_stresses.get('longitude', 0.0)
                    
                    # Query earthquakes from local database with PostGIS spatial indexing
                    earthquake_query = """
                    SELECT 
                        id,
                        ST_X(location) as longitude,
                        ST_Y(location) as latitude,
                        magnitude,
                        depth_km,
                        occurrence_time,
                        event_type,
                        magnitude_type,
                        data_source,
                        uncertainty_km,
                        quality_grade,
                        focal_mechanism,
                        ST_Distance(location::geography, ST_Point(%s, %s)::geography) / 1000 as distance_km
                    FROM earthquakes 
                    WHERE ST_DWithin(location::geography, ST_Point(%s, %s)::geography, 50000)
                    AND magnitude >= 0.5
                    AND occurrence_time >= NOW() - INTERVAL '24 hours'
                    AND quality_grade IN ('A', 'B', 'C')
                    ORDER BY occurrence_time DESC, magnitude DESC
                    LIMIT 100
                    """
                    
                    db_earthquakes = await self.db_manager.query(
                        earthquake_query, 
                        [lon, lat, lon, lat]
                    )
                    
                    # Convert database results to seismic data format
                    for eq in db_earthquakes:
                        seismic_event = {
                            'properties': {
                                'mag': eq['magnitude'],
                                'depth': eq['depth_km'],
                                'time': eq['occurrence_time'].timestamp() * 1000 if eq['occurrence_time'] else 0,
                                'place': f"{eq['distance_km']:.1f}km from query point",
                                'type': eq['event_type'] or 'earthquake',
                                'magType': eq['magnitude_type'] or 'ml'
                            },
                            'geometry': {
                                'coordinates': [eq['longitude'], eq['latitude'], eq['depth_km'] or 10.0]
                            },
                            'id': eq['id'],
                            'magnitude': eq['magnitude'],
                            'depth': eq['depth_km'] or 10.0,
                            'data_source': eq['data_source'] or 'local_db'
                        }
                        
                        # Add focal mechanism if available
                        if eq['focal_mechanism']:
                            seismic_event['focal_mechanism'] = eq['focal_mechanism']
                        
                        seismic_data.append(seismic_event)
                    
                    self.logger.info(f"Retrieved {len(db_earthquakes)} earthquakes from local database")
                    
                except Exception as e:
                    self.logger.error(f"Local database seismic query failed: {e}")
                    # Fallback to empty data rather than external API calls
                    seismic_data = []
            
            # Process seismic data
            if seismic_data:
                magnitudes = []
                depths = []
                times = []
                
                for event in seismic_data:
                    if isinstance(event, dict):
                        if 'properties' in event:  # GeoJSON format
                            props = event['properties']
                            if 'mag' in props:
                                magnitudes.append(props['mag'])
                            if 'depth' in props:
                                depths.append(props['depth'])
                            if 'time' in props:
                                times.append(props['time'])
                        elif 'magnitude' in event:  # Direct format
                            magnitudes.append(event['magnitude'])
                            if 'depth' in event:
                                depths.append(event['depth'])
                
                # Calculate Gutenberg-Richter b-value
                if len(magnitudes) >= 10:
                    magnitudes_sorted = sorted(magnitudes)
                    mag_min = magnitudes_sorted[0]
                    mag_mean = np.mean(magnitudes)
                    
                    # Maximum likelihood estimation
                    if mag_mean > mag_min:
                        b_value = 1.0 / ((mag_mean - mag_min) * np.log(10))
                        b_value = np.clip(b_value, 0.5, 2.0)
                
                # Calculate seismic moment release rate
                moment_rate = 0.0
                for mag in magnitudes:
                    # M0 = 10^(1.5*Mw + 9.1) in N·m
                    moment = 10**(1.5 * mag + 9.1)
                    moment_rate += moment
                
                if times:
                    time_span = (max(times) - min(times)) / 1000 / 86400  # Convert to days
                    if time_span > 0:
                        moment_rate /= time_span
                
                # Event rate calculation
                event_rate = len(seismic_data) / 24.0  # Events per hour
                
                # Average depth
                avg_depth = np.mean(depths) if depths else 10.0  # km
            else:
                event_rate = 0.0
                b_value = 1.0
                moment_rate = 0.0
                avg_depth = 10.0
            
            # Stress-induced seismicity correlation (Kaiser effect)
            if differential_stress > 0:
                # Empirical correlation between stress and seismicity
                stress_factor = np.log10(differential_stress / 1e6)  # Log of stress in MPa
                
                # Expected seismicity rate based on stress
                expected_rate = 10**(0.5 * stress_factor - 1.0)  # Empirical relationship
                
                # Anomaly detection
                if event_rate > 2 * expected_rate:
                    seismic_anomaly = 'elevated'
                    anomaly_factor = event_rate / expected_rate
                elif event_rate < 0.5 * expected_rate:
                    seismic_anomaly = 'suppressed'
                    anomaly_factor = event_rate / expected_rate
                else:
                    seismic_anomaly = 'normal'
                    anomaly_factor = 1.0
            else:
                expected_rate = 0.0
                seismic_anomaly = 'undefined'
                anomaly_factor = 1.0
            
            # Fractal dimension analysis for clustering
            if len(seismic_data) > 20:
                # Simple box-counting dimension estimate
                fractal_dimension = 1.5 + 0.5 * (2.0 - b_value)  # Empirical relationship
            else:
                fractal_dimension = 2.0  # Default for random distribution
            
            # Seismic hazard assessment
            if b_value < 0.8:
                hazard_level = 'high'  # Low b-value indicates stress accumulation
            elif b_value > 1.2:
                hazard_level = 'low'  # High b-value indicates stress release
            else:
                hazard_level = 'moderate'
            
            return {
                'microseismic_rate': event_rate,
                'b_value': b_value,
                'seismic_analysis': {
                    'total_events': len(seismic_data),
                    'moment_release_rate': moment_rate,
                    'average_depth_km': avg_depth,
                    'fractal_dimension': fractal_dimension,
                    'hazard_level': hazard_level
                },
                'stress_correlation': {
                    'differential_stress_mpa': differential_stress / 1e6,
                    'expected_seismicity_rate': expected_rate,
                    'observed_rate': event_rate,
                    'anomaly_status': seismic_anomaly,
                    'anomaly_factor': anomaly_factor
                },
                'data_sources': {
                    'usgs_events': len([e for e in seismic_data if 'usgs' in str(e).lower()]),
                    'iris_events': len([e for e in seismic_data if 'iris' in str(e).lower()]),
                    'time_window_hours': 24
                }
            }
            
        except Exception as e:
            self.logger.error(f"Microseismic correlation failed: {e}")
            return {
                'microseismic_rate': 0.0,
                'b_value': 1.0,
                'error': str(e)
            }
    
    async def _ml_failure_prediction(self, principal_stresses, rock_properties):
        """Advanced ML-based failure prediction using neural networks"""
        try:
            import numpy as np
            
            # Prepare input features
            features = []
            
            # Stress features
            sigma_1 = principal_stresses.get('sigma_1', 0.0)
            sigma_2 = principal_stresses.get('sigma_2', 0.0)
            sigma_3 = principal_stresses.get('sigma_3', 0.0)
            
            features.extend([
                sigma_1 / 1e6,  # MPa
                sigma_2 / 1e6,
                sigma_3 / 1e6,
                (sigma_1 - sigma_3) / 1e6,  # Differential stress
                (sigma_1 + sigma_2 + sigma_3) / 3e6,  # Mean stress
            ])
            
            # Material property features
            features.extend([
                rock_properties.get('elastic_modulus_gpa', 50.0),
                rock_properties.get('poisson_ratio', 0.25),
                rock_properties.get('cohesion_mpa', 10.0),
                rock_properties.get('friction_angle_deg', 30.0),
                rock_properties.get('tensile_strength_mpa', 5.0),
                rock_properties.get('ucs_mpa', 100.0),
                rock_properties.get('porosity', 0.1),
                rock_properties.get('temperature_c', 25.0)
            ])
            
            # Environmental features
            features.extend([
                rock_properties.get('depth_km', 1.0),
                rock_properties.get('pore_pressure_mpa', 10.0),
                rock_properties.get('strain_rate', 1e-6),
            ])
            
            # Try advanced ML approach with PyTorch
            try:
                import torch
                import torch.nn as nn
                import torch.nn.functional as F
                
                # Convert to tensor
                x = torch.tensor(features, dtype=torch.float32).unsqueeze(0)
                
                # Define advanced neural network architecture
                class FailurePredictionNet(nn.Module):
                    def __init__(self, input_dim=16):
                        super().__init__()
                        # Deep architecture with skip connections
                        self.fc1 = nn.Linear(input_dim, 128)
                        self.bn1 = nn.BatchNorm1d(128)
                        self.dropout1 = nn.Dropout(0.3)
                        
                        self.fc2 = nn.Linear(128, 256)
                        self.bn2 = nn.BatchNorm1d(256)
                        self.dropout2 = nn.Dropout(0.3)
                        
                        self.fc3 = nn.Linear(256, 128)
                        self.bn3 = nn.BatchNorm1d(128)
                        self.dropout3 = nn.Dropout(0.2)
                        
                        # Attention mechanism
                        self.attention = nn.MultiheadAttention(128, 4, batch_first=True)
                        
                        # Output layers
                        self.fc_prob = nn.Linear(128, 1)  # Failure probability
                        self.fc_mode = nn.Linear(128, 5)  # Failure mode classification
                        self.fc_time = nn.Linear(128, 1)  # Time to failure
                        
                    def forward(self, x):
                        # First block
                        h1 = F.relu(self.bn1(self.fc1(x)))
                        h1 = self.dropout1(h1)
                        
                        # Second block
                        h2 = F.relu(self.bn2(self.fc2(h1)))
                        h2 = self.dropout2(h2)
                        
                        # Third block with residual
                        h3 = F.relu(self.bn3(self.fc3(h2)))
                        h3 = self.dropout3(h3)
                        
                        # Self-attention
                        h3_reshaped = h3.unsqueeze(1)
                        attn_out, _ = self.attention(h3_reshaped, h3_reshaped, h3_reshaped)
                        h3 = attn_out.squeeze(1) + h3  # Residual connection
                        
                        # Outputs
                        prob = torch.sigmoid(self.fc_prob(h3))
                        mode = F.softmax(self.fc_mode(h3), dim=1)
                        time = F.softplus(self.fc_time(h3))  # Ensure positive
                        
                        return prob, mode, time
                
                # Load or create model
                model = FailurePredictionNet(len(features))
                
                # Try to load pre-trained weights if available
                if hasattr(self, 'model_manager'):
                    try:
                        model_state = await self.model_manager.load_model(
                            'failure_prediction_net',
                            version='latest'
                        )
                        if model_state:
                            model.load_state_dict(model_state)
                    except:
                        # Use untrained model with Xavier initialization
                        for m in model.modules():
                            if isinstance(m, nn.Linear):
                                nn.init.xavier_uniform_(m.weight)
                
                # Model inference
                model.eval()
                with torch.no_grad():
                    failure_prob, failure_modes, time_to_failure = model(x)
                
                # Extract predictions
                prob_value = failure_prob.item()
                mode_probs = failure_modes.squeeze().numpy()
                ttf_hours = time_to_failure.item() * 24  # Convert to hours
                
                # Failure mode mapping
                mode_names = ['shear', 'tensile', 'compressive', 'fatigue', 'thermal']
                mode_idx = np.argmax(mode_probs)
                predicted_mode = mode_names[mode_idx]
                
                # Ensemble with physics-based models for robustness
                if hasattr(self, 'ensemble_predictions'):
                    # Weighted average with other models
                    physics_prob = self.ensemble_predictions.get('physics_probability', prob_value)
                    ensemble_prob = 0.7 * prob_value + 0.3 * physics_prob
                else:
                    ensemble_prob = prob_value
                
                # Uncertainty quantification using dropout Monte Carlo
                n_samples = 10
                model.train()  # Enable dropout
                prob_samples = []
                
                with torch.no_grad():
                    for _ in range(n_samples):
                        prob_mc, _, _ = model(x)
                        prob_samples.append(prob_mc.item())
                
                prob_mean = np.mean(prob_samples)
                prob_std = np.std(prob_samples)
                
                # Confidence based on uncertainty
                if prob_std < 0.1:
                    confidence = 0.9
                elif prob_std < 0.2:
                    confidence = 0.7
                else:
                    confidence = 0.5
                
                return {
                    'ml_probability': ensemble_prob,
                    'confidence': confidence,
                    'predictions': {
                        'failure_probability': prob_value,
                        'ensemble_probability': ensemble_prob,
                        'predicted_mode': predicted_mode,
                        'time_to_failure_hours': ttf_hours,
                        'mode_probabilities': {
                            name: float(prob) for name, prob in zip(mode_names, mode_probs)
                        }
                    },
                    'uncertainty': {
                        'probability_mean': prob_mean,
                        'probability_std': prob_std,
                        'confidence_interval_95': [
                            max(0, prob_mean - 1.96*prob_std),
                            min(1, prob_mean + 1.96*prob_std)
                        ]
                    },
                    'model_info': {
                        'architecture': 'deep_neural_network_with_attention',
                        'input_features': len(features),
                        'ensemble_enabled': hasattr(self, 'ensemble_predictions')
                    }
                }
                
            except ImportError:
                # Fallback to simpler ML approach without PyTorch
                try:
                    from sklearn.ensemble import RandomForestClassifier, GradientBoostingRegressor
                    from sklearn.preprocessing import StandardScaler
                    
                    # Simple heuristic model as fallback
                    stress_ratio = features[0] / features[5] if features[5] > 0 else 0  # sigma1/E
                    ml_probability = 1.0 / (1.0 + np.exp(-5*(stress_ratio - 0.5)))
                    
                    return {
                        'ml_probability': ml_probability,
                        'confidence': 0.6,
                        'fallback_mode': 'heuristic'
                    }
                    
                except Exception as e2:
                    self.logger.error(f"ML fallback also failed: {e2}")
                    return {
                        'ml_probability': 0.5,
                        'confidence': 0.3,
                        'error': str(e2)
                    }
                    
        except Exception as e:
            self.logger.error(f"ML failure prediction failed: {e}")
            return {
                'ml_probability': 0.5,
                'confidence': 0.3,
                'error': str(e)
            }
    
    def _compute_composite_failure_assessment(self, failure_analyses, progressive_analysis, temporal_analysis, ml_prediction):
        """Compute composite failure assessment"""
        total_probability = 0
        count = 0
        critical_modes = []
        
        for criterion, analysis in failure_analyses.items():
            if 'failure_probability' in analysis:
                prob = analysis['failure_probability']
                total_probability += prob
                count += 1
                
                if prob > 0.7:
                    critical_modes.append(criterion)
        
        composite_probability = total_probability / count if count > 0 else 0
        time_to_failure = progressive_analysis.get('time_to_complete_failure', 1000) if progressive_analysis else 1000
        
        return {
            'failure_probability': composite_probability,
            'estimated_time_to_failure': time_to_failure,
            'critical_modes': critical_modes,
            'confidence': 0.8,
            'assessment_quality': 'comprehensive'
        }
    
    def _generate_safety_recommendations(self, composite_assessment):
        """Generate safety recommendations"""
        prob = composite_assessment.get('failure_probability', 0)
        recommendations = []
        
        if prob > 0.8:
            recommendations.append("CRITICAL: Immediate evacuation required")
        elif prob > 0.6:
            recommendations.append("HIGH RISK: Enhanced monitoring needed")
        elif prob > 0.4:
            recommendations.append("MODERATE RISK: Regular monitoring")
        else:
            recommendations.append("LOW RISK: Routine monitoring sufficient")
        
        return recommendations

