    def _get_critical_parameters(self, features, importances):
        """Identify critical parameters from feature importance"""
        feature_names = ['depth', 'temperature', 'pressure', 'magnitude', 'duration', 
                        'tectonic_setting', 'lithology', 'latitude', 'longitude']
        
        # Pair features with names and importance scores
        param_importance = list(zip(feature_names[:len(features)], importances[:len(features)]))
        
        # Sort by importance and return top parameters
        sorted_params = sorted(param_importance, key=lambda x: x[1], reverse=True)
        
        return [param for param, importance in sorted_params[:3]]
    
