    async def _parse_expression_to_csp(self, expression, analysis_system):
        """Parse logical expression into constraint satisfaction problem formulation"""
        try:
            import re
            from typing import Dict, List, Tuple
            
            # Advanced expression parsing with geological domain knowledge
            csp_variables = set()
            csp_constraints = []
            
            # Extract variables from expression
            variable_pattern = r'[a-zA-Z_][a-zA-Z0-9_]*'
            variables = re.findall(variable_pattern, expression)
            
            # Create variable domains based on geological constraints
            variable_domains = {}
            for var in variables:
                if var in analysis_system:
                    domain = await self._determine_variable_domain(var, analysis_system[var])
                    variable_domains[var] = domain
                    csp_variables.add(var)
            
            # Parse logical operators and create constraints
            constraint_patterns = [
                (r'([\\w.]+)\\s*([<>=!]+)\\s*([\\w.]+)', 'comparison'),
                (r'([\\w.]+)\\s+in\\s+\\[([^\\]]+)\\]', 'membership'),
                (r'abs\\(([^)]+)\\)\\s*([<>=]+)\\s*([\\w.]+)', 'absolute'),
                (r'sqrt\\(([^)]+)\\)\\s*([<>=]+)\\s*([\\w.]+)', 'square_root')
            ]
            
            for pattern, constraint_type in constraint_patterns:
                matches = re.findall(pattern, expression)
                for match in matches:
                    constraint = await self._create_csp_constraint(match, constraint_type, variable_domains)
                    csp_constraints.append(constraint)
            
            return {
                'variables': csp_variables,
                'domains': variable_domains,
                'constraints': csp_constraints,
                'expression': expression,
                'complexity_score': len(csp_constraints) * len(csp_variables)
            }
            
        except Exception as e:
            self.logger.error(f"Expression parsing to CSP failed: {e}")
            return {'variables': set(), 'domains': {}, 'constraints': [], 'expression': expression}
    
    async def _determine_variable_domain(self, variable_name, current_value):
        """Determine valid domain for geological variables using database constraints"""
        try:
            # Database query for variable constraints
            db_constraints = await self._query_database_constraints(variable_name)
            # Geological domain knowledge
            geological_bounds = {
                'temperature': {'min': -50, 'max': 1500, 'unit': 'celsius'},
                'pressure': {'min': 0, 'max': 100000, 'unit': 'mpa'},
                'depth': {'min': 0, 'max': 1000, 'unit': 'km'},
                'density': {'min': 1000, 'max': 8000, 'unit': 'kg/m3'},
                'porosity': {'min': 0, 'max': 0.5, 'unit': 'fraction'},
                'permeability': {'min': 1e-21, 'max': 1e-9, 'unit': 'm2'},
                'conductivity': {'min': 1e-6, 'max': 1e2, 'unit': 's/m'},
                'viscosity': {'min': 1e-6, 'max': 1e6, 'unit': 'pa.s'}
            }
            # Use database constraints if available, otherwise geological bounds
            if db_constraints and 'bounds' in db_constraints:
                domain_bounds = db_constraints['bounds']
            elif variable_name.lower() in geological_bounds:
                domain_bounds = geological_bounds[variable_name.lower()]
            else:
                # Dynamic bounds based on current value and uncertainty
                uncertainty_factor = 0.2
                domain_bounds = {
                    'min': current_value * (1 - uncertainty_factor),
                    'max': current_value * (1 + uncertainty_factor)
                }
            # Discretize continuous domains for CSP solving
            if isinstance(current_value, (int, float)):
                min_val = domain_bounds.get('min', current_value * 0.5)
                max_val = domain_bounds.get('max', current_value * 1.5)
                num_discrete_values = 100  # Configurable discretization
                domain = [
                    min_val + i * (max_val - min_val) / (num_discrete_values - 1)
                    for i in range(num_discrete_values)
                ]
            else:
                domain = [current_value]  # Categorical or unknown type
            return {
                'values': domain,
                'bounds': domain_bounds,
                'type': type(current_value).__name__,
                'constraints': db_constraints
            }
        except Exception as e:
            self.logger.error(f"Domain determination failed for {variable_name}: {e}")
            return {'values': [current_value], 'bounds': {}, 'type': 'unknown'}

