    async def _fallback_physics_validation(self, analysis_system, error_msg):
        """Fallback physics validation with basic constraint checking"""
        try:
            self.logger.warning(f"Using fallback physics validation due to: {error_msg}")
            # Basic parameter bounds checking
            basic_validation = {}
            # Temperature validation
            temperature = analysis_system.get('temperature', 0)
            basic_validation['temperature_valid'] = -50 <= temperature <= 1500
            # Pressure validation
            pressure = analysis_system.get('pressure', 0)
            basic_validation['pressure_valid'] = 0 <= pressure <= 100000
            # Depth validation
            depth = analysis_system.get('depth', 0)
            basic_validation['depth_valid'] = 0 <= depth <= 1000
            # Density validation
            density = analysis_system.get('density', 2500)
            basic_validation['density_valid'] = 1000 <= density <= 8000
            # Calculate overall validity score
            valid_count = sum(1 for valid in basic_validation.values() if valid)
            total_count = len(basic_validation)
            overall_validity = valid_count / total_count if total_count > 0 else 0.0
            return {
                'overall_validity': overall_validity,
                'confidence': 0.3,  # Low confidence for fallback
                'scale_validation': {'basic': basic_validation},
                'domain_validation': {'basic_bounds': basic_validation},
                'database_validation': {},
                'coupling_validation': {},
                'constraint_satisfaction': {'overall_score': overall_validity},
                'uncertainty_analysis': {'overall_confidence': 0.3},
                'validation_report': {
                    'method': 'fallback_validation',
                    'limitations': 'Basic bounds checking only',
                    'original_error': error_msg
                },
                'violated_constraints': [k for k, v in basic_validation.items() if not v],
                'recommendations': ['Verify input parameters', 'Check data quality']
            }
        except Exception as e:
            self.logger.error(f"Fallback physics validation failed: {e}")
            return {
                'overall_validity': 0.0,
                'confidence': 0.0,
                'error': f"All validation methods failed: {error_msg}, {str(e)}"
            }
    
    def _identify_uncertainty_sources(self, uncertainty_results):
        """Identify main sources of uncertainty"""
        sources = []
        
        if uncertainty_results.get('ensemble_std', 0) > 0.1:
            sources.append('model_uncertainty')
        
        if uncertainty_results.get('mc_relative_uncertainty', 0) > 0.15:
            sources.append('parameter_uncertainty')
        
        if uncertainty_results.get('historical_std_uncertainty', 0) > 0.2:
            sources.append('measurement_uncertainty')
        
        if not sources:
            sources.append('minimal_uncertainty')
        
        return sources
    
    def _generate_uncertainty_recommendations(self, uncertainty_results):
        """Generate recommendations for uncertainty reduction"""
        recommendations = []
        
        # Check if uncertainty is too high
        relative_uncertainty = uncertainty_results.get('relative_uncertainty', 0.05)
        
        if relative_uncertainty > 0.3:
            recommendations.append("Consider additional data collection to reduce uncertainty")
        elif relative_uncertainty > 0.2:
            recommendations.append("Moderate uncertainty - consider validation with independent methods")
        else:
            recommendations.append("Uncertainty levels are acceptable for current analysis")
        
        # Suggest specific improvements
        if 'ensemble_std' in uncertainty_results and uncertainty_results['ensemble_std'] > 0.1:
            recommendations.append("Model ensemble shows high variability - consider model refinement")
        
        if 'mc_relative_uncertainty' in uncertainty_results and uncertainty_results['mc_relative_uncertainty'] > 0.2:
            recommendations.append("Parameter uncertainty is significant - improve input parameter constraints")
        
        return recommendations

