    async def _detect_change_points_advanced(self, temporal_features: Dict[str, Any]) -> Dict[str, Any]:
        """Advanced change point detection using multiple algorithms"""
        try:
            from scipy import signal
            import numpy as np
            
            change_points = []
            all_change_points = []
            
            # Process each time series
            for ts_data in temporal_features.get('causal_time_series', []):
                series = np.array(ts_data['series'])
                
                # Method 1: CUSUM-based change point detection
                cumsum = np.cumsum(series - np.mean(series))
                cumsum_normalized = (cumsum - np.min(cumsum)) / (np.max(cumsum) - np.min(cumsum) + 1e-8)
                
                # Find peaks in CUSUM that indicate change points
                peaks, _ = signal.find_peaks(np.abs(np.diff(cumsum_normalized)), height=0.1)
                
                # Method 2: Variance change detection
                window_size = 50
                rolling_var = []
                for i in range(len(series) - window_size):
                    window_var = np.var(series[i:i+window_size])
                    rolling_var.append(window_var)
                
                rolling_var = np.array(rolling_var)
                if len(rolling_var) > 0:
                    var_peaks, _ = signal.find_peaks(np.abs(np.diff(rolling_var)), height=np.std(np.diff(rolling_var)))
                    var_peaks = var_peaks + window_size // 2  # Adjust for window offset
                else:
                    var_peaks = []
                
                # Combine change points
                combined_cps = list(set(list(peaks) + list(var_peaks)))
                combined_cps.sort()
                
                for cp in combined_cps:
                    change_points.append({
                        'relationship_id': ts_data['relationship_id'],
                        'change_point': int(cp),
                        'change_strength': float(np.abs(cumsum_normalized[min(cp, len(cumsum_normalized)-1)])),
                        'detection_method': 'cusum_variance'
                    })
                
                all_change_points.extend(combined_cps)
            
            return {
                'change_points': change_points,
                'total_change_points': len(all_change_points),
                'method': 'advanced_change_point_detection'
            }
            
        except Exception as e:
            self.logger.error(f"Change point detection failed: {e}")
            return {'change_points': [], 'total_change_points': 0, 'error': str(e)}

    async def _detect_periodic_anomalies_advanced(self, temporal_features: Dict[str, Any]) -> Dict[str, Any]:
        """Advanced periodic anomaly detection using spectral analysis"""
        try:
            from scipy import signal
            from scipy.fft import fft, fftfreq
            import numpy as np
            
            periodic_outliers = []
            anomalous_frequencies = []
            
            # Process each time series
            for ts_data in temporal_features.get('causal_time_series', []):
                series = np.array(ts_data['series'])
                
                # Spectral analysis
                fft_values = fft(series)
                freqs = fftfreq(len(series), d=1/temporal_features.get('sampling_rate', 1.0))
                power_spectrum = np.abs(fft_values) ** 2
                
                # Find dominant frequencies
                positive_freqs = freqs[:len(freqs)//2]
                positive_power = power_spectrum[:len(power_spectrum)//2]
                
                # Detect anomalous frequencies (much higher power than expected)
                power_threshold = np.mean(positive_power) + 3 * np.std(positive_power)
                anomalous_freq_indices = np.where(positive_power > power_threshold)[0]
                
                for freq_idx in anomalous_freq_indices:
                    anomalous_frequencies.append({
                        'relationship_id': ts_data['relationship_id'],
                        'frequency': float(positive_freqs[freq_idx]),
                        'power': float(positive_power[freq_idx]),
                        'threshold': float(power_threshold)
                    })
                
                # Periodogram-based outlier detection
                f, pxx = signal.periodogram(series, fs=temporal_features.get('sampling_rate', 1.0))
                
                # Find peaks in periodogram
                peaks, properties = signal.find_peaks(pxx, height=np.mean(pxx) + 2 * np.std(pxx))
                
                for peak in peaks:
                    periodic_outliers.append({
                        'relationship_id': ts_data['relationship_id'],
                        'frequency': float(f[peak]),
                        'power': float(pxx[peak]),
                        'detection_method': 'periodogram'
                    })
            
            return {
                'periodic_outliers': periodic_outliers,
                'anomalous_frequencies': anomalous_frequencies,
                'method': 'spectral_analysis'
            }
            
        except Exception as e:
            self.logger.error(f"Periodic anomaly detection failed: {e}")
            return {'periodic_outliers': [], 'anomalous_frequencies': [], 'error': str(e)}

