    # ADVANCED ENSEMBLE RESULT FUSION AND ANALYSIS  
    # =====================================================================================
    
    async def _advanced_ensemble_fusion(self, individual_results: List[Dict[str, Any]], 
                                      final_weights: Dict[str, float], 
                                      data: np.ndarray) -> Dict[str, Any]:
        """Advanced fusion of ensemble results with uncertainty quantification"""
        try:
            algorithms = list(final_weights.keys())
            n_algs = len(algorithms)
            
            # Initialize fusion result
            fusion_result = {
                'ensemble_method': 'advanced_weighted_fusion',
                'algorithms_used': algorithms,
                'final_weights': final_weights,
                'n_algorithms': n_algs,
                'timestamp': time.time()
            }
            
            # 1. Confidence Aggregation
            confidence_scores = []
            for i, result in enumerate(individual_results):
                alg = algorithms[i] if i < len(algorithms) else f"alg_{i}"
                weight = final_weights.get(alg, 0.0)
                conf = result.get('confidence', 0.5)
                if isinstance(conf, (list, np.ndarray)):
                    conf = np.mean(conf)
                confidence_scores.append(float(conf) * weight)
            
            fusion_result['confidence'] = np.sum(confidence_scores)
            fusion_result['confidence_std'] = np.std([
                result.get('confidence', 0.5) for result in individual_results
                if isinstance(result.get('confidence', 0.5), (int, float))
            ])
            
            # 2. Ensemble Diversity Metrics
            diversity_metrics = self._calculate_ensemble_diversity(
                individual_results, final_weights
            )
            fusion_result.update(diversity_metrics)
            
            # 3. Robustness Assessment
            robustness_metrics = await self._assess_ensemble_robustness(
                individual_results, final_weights, data
            )
            fusion_result['robustness'] = robustness_metrics
            
            # 4. Performance summary
            performance_summary = {
                'mean_individual_confidence': np.mean([
                    r.get('confidence', 0.5) for r in individual_results
                    if isinstance(r.get('confidence', 0.5), (int, float))
                ]),
                'ensemble_confidence': fusion_result.get('confidence', 0.5),
                'n_algorithms_used': len([w for w in final_weights.values() if w > 0.01])
            }
            
            # Calculate improvement
            if performance_summary['mean_individual_confidence'] > 0:
                performance_summary['confidence_improvement'] = (
                    (performance_summary['ensemble_confidence'] - 
                     performance_summary['mean_individual_confidence']) /
                    performance_summary['mean_individual_confidence']
                )
            
            fusion_result['performance_summary'] = performance_summary
            
            return fusion_result
            
        except Exception as e:
            self.logger.error(f"Advanced ensemble fusion failed: {e}")
            return {
                'error': str(e),
                'ensemble_weights': final_weights,
                'fallback_result': individual_results[0] if individual_results else {}
            }
    
    def _calculate_ensemble_diversity(self, results: List[Dict[str, Any]], 
                                    weights: Dict[str, float]) -> Dict[str, float]:
        """Calculate diversity metrics for the ensemble"""
        try:
            diversity_metrics = {}
            algorithms = list(weights.keys())
            n_algs = len(algorithms)
            
            if n_algs < 2:
                return {'overall_diversity': 0.0, 'weight_diversity': 0.0}
            
            # 1. Weight diversity (entropy of weights)
            weight_values = np.array(list(weights.values()))
            if np.sum(weight_values) > 0:
                normalized_weights = weight_values / np.sum(weight_values)
                weight_entropy = -np.sum(normalized_weights * np.log(normalized_weights + 1e-10))
                max_entropy = np.log(n_algs)
                diversity_metrics['weight_diversity'] = weight_entropy / max_entropy if max_entropy > 0 else 0.0
            else:
                diversity_metrics['weight_diversity'] = 0.0
            
            # 2. Confidence diversity
            confidences = []
            for result in results:
                conf = result.get('confidence', 0.5)
                if isinstance(conf, (list, np.ndarray)):
                    conf = np.mean(conf)
                confidences.append(float(conf))
            
            diversity_metrics['confidence_diversity'] = np.std(confidences) if len(confidences) > 1 else 0.0
            
            # 3. Overall diversity score
            diversity_metrics['overall_diversity'] = (
                diversity_metrics['weight_diversity'] * 0.7 +
                diversity_metrics['confidence_diversity'] * 0.3
            )
            
            return diversity_metrics
            
        except Exception as e:
            self.logger.error(f"Ensemble diversity calculation failed: {e}")
            return {'overall_diversity': 0.0, 'weight_diversity': 0.0}
    
    async def _assess_ensemble_robustness(self, individual_results: List[Dict[str, Any]], 
                                        weights: Dict[str, float], 
                                        data: np.ndarray) -> Dict[str, float]:
        """Assess robustness of ensemble results"""
        try:
            robustness_metrics = {}
            algorithms = list(weights.keys())
            
            # 1. Weight sensitivity analysis
            weight_perturbation = 0.1
            sensitivity_scores = []
            
            for alg in algorithms:
                original_weight = weights[alg]
                
                # Perturb weight
                for perturbation in [-weight_perturbation, weight_perturbation]:
                    perturbed_weights = weights.copy()
                    perturbed_weights[alg] = max(0.01, min(1.0, original_weight + perturbation))
                    
                    # Renormalize
                    total = sum(perturbed_weights.values())
                    if total > 0:
                        perturbed_weights = {k: v/total for k, v in perturbed_weights.items()}
                    
                    result_change = abs(perturbed_weights[alg] - original_weight)
                    sensitivity_scores.append(result_change)
            
            robustness_metrics['weight_sensitivity'] = 1.0 - np.mean(sensitivity_scores)
            
            # 2. Algorithm dropout robustness
            if len(algorithms) > 2:
                dropout_scores = []
                
                for alg in algorithms:
                    # Create weights without this algorithm
                    reduced_weights = {k: v for k, v in weights.items() if k != alg}
                    if reduced_weights:
                        total = sum(reduced_weights.values())
                        reduced_weights = {k: v/total for k, v in reduced_weights.items()}
                        
                        impact = weights[alg]  # Algorithm's original contribution
                        dropout_scores.append(1.0 - impact)
                
                robustness_metrics['dropout_robustness'] = np.mean(dropout_scores) if dropout_scores else 1.0
            else:
                robustness_metrics['dropout_robustness'] = 0.5
            
            # 3. Overall robustness score
            robustness_metrics['overall_robustness'] = (
                robustness_metrics['weight_sensitivity'] * 0.6 +
                robustness_metrics['dropout_robustness'] * 0.4
            )
            
            return robustness_metrics
            
        except Exception as e:
            self.logger.error(f"Robustness assessment failed: {e}")
            return {'overall_robustness': 0.5}
    
    def _generate_advanced_recommendations(self, ensemble_result: Dict[str, Any]) -> List[str]:
        """Generate recommendations based on ensemble results"""
        recommendations = []
        
        try:
            # Confidence-based recommendations
            confidence = ensemble_result.get('confidence', 0.0)
            if isinstance(confidence, (list, np.ndarray)):
                confidence = np.mean(confidence)
            
            if confidence < 0.6:
                recommendations.append("Low ensemble confidence detected. Consider collecting more data or using different algorithms.")
            elif confidence > 0.9:
                recommendations.append("High confidence achieved. Results are likely reliable for decision making.")
            
            # Diversity recommendations
            diversity = ensemble_result.get('overall_diversity', 0.0)
            if diversity < 0.3:
                recommendations.append("Low algorithm diversity. Consider adding more diverse causal discovery methods.")
            elif diversity > 0.8:
                recommendations.append("High diversity achieved. Ensemble effectively combines different approaches.")
            
            # Robustness recommendations
            robustness = ensemble_result.get('robustness', {}).get('overall_robustness', 0.0)
            if robustness < 0.5:
                recommendations.append("Low robustness detected. Results may be sensitive to parameter changes.")
            
            if not recommendations:
                recommendations.append("Ensemble analysis completed successfully. No specific concerns identified.")
            
            return recommendations
            
        except Exception as e:
            self.logger.warning(f"Recommendation generation failed: {e}")
            return ["Unable to generate specific recommendations due to processing error."]

