    async def _advanced_granger_causality_validation(self, time_series_data, causal_data, db_integration):
        """Advanced Granger causality validation with geological constraints"""
        try:
            import torch
            import torch.nn as nn
            from scipy.stats import f_oneway
            from sklearn.linear_model import LinearRegression
            from sklearn.preprocessing import StandardScaler
            
            # Load geological time series data from database
            geological_ts_data = await db_integration.fetch_geological_time_series(
                variables=list(causal_data.get('variables', [])),
                time_range=causal_data.get('time_range', '1Y')
            )
            
            granger_scores = []
            
            # Advanced neural Granger causality test
            class NeuralGrangerCausalityNet(nn.Module):
                def __init__(self, input_dim, hidden_dim=64, num_lags=10):
                    super().__init__()
                    self.num_lags = num_lags
                    
                    # Autoregressive component
                    self.ar_net = nn.Sequential(
                        nn.Linear(input_dim * num_lags, hidden_dim),
                        nn.ReLU(),
                        nn.Dropout(0.2),
                        nn.Linear(hidden_dim, hidden_dim // 2),
                        nn.ReLU(),
                        nn.Linear(hidden_dim // 2, 1)
                    )
                    
                    # Vector autoregressive component
                    self.var_net = nn.Sequential(
                        nn.Linear((input_dim + 1) * num_lags, hidden_dim),
                        nn.ReLU(),
                        nn.Dropout(0.2),
                        nn.Linear(hidden_dim, hidden_dim // 2),
                        nn.ReLU(),
                        nn.Linear(hidden_dim // 2, 1)
                    )
                
                def forward(self, x_lags, xy_lags):
                    ar_pred = self.ar_net(x_lags)
                    var_pred = self.var_net(xy_lags)
                    return ar_pred, var_pred
            
            # Process each causal relationship
            for cause_var, effect_var in causal_data.get('relationships', []):
                if cause_var in geological_ts_data and effect_var in geological_ts_data:
                    cause_series = np.array(geological_ts_data[cause_var])
                    effect_series = np.array(geological_ts_data[effect_var])
                    
                    # Normalize series
                    scaler = StandardScaler()
                    cause_series = scaler.fit_transform(cause_series.reshape(-1, 1)).flatten()
                    effect_series = scaler.fit_transform(effect_series.reshape(-1, 1)).flatten()
                    
                    # Neural Granger test
                    neural_granger = NeuralGrangerCausalityNet(1, hidden_dim=64, num_lags=10)
                    
                    # Create lagged features
                    def create_lags(series, num_lags):
                        lagged = np.column_stack([
                            np.roll(series, i) for i in range(1, num_lags + 1)
                        ])
                        return lagged[num_lags:]
                    
                    if len(cause_series) > 20:  # Minimum data requirement
                        cause_lags = create_lags(cause_series, 10)
                        effect_lags = create_lags(effect_series, 10)
                        combined_lags = np.column_stack([cause_lags, effect_lags])
                        
                        # Convert to tensors
                        cause_tensor = torch.FloatTensor(cause_lags)
                        combined_tensor = torch.FloatTensor(combined_lags)
                        target_tensor = torch.FloatTensor(effect_series[10:])
                        
                        # Train models
                        optimizer = torch.optim.Adam(neural_granger.parameters(), lr=0.001)
                        criterion = nn.MSELoss()
                        
                        # Training loop
                        for epoch in range(100):
                            optimizer.zero_grad()
                            ar_pred, var_pred = neural_granger(cause_tensor, combined_tensor)
                            
                            ar_loss = criterion(ar_pred.squeeze(), target_tensor)
                            var_loss = criterion(var_pred.squeeze(), target_tensor)
                            
                            loss = ar_loss + var_loss
                            loss.backward()
                            optimizer.step()
                        
                        # Compute Granger causality score
                        with torch.no_grad():
                            ar_pred, var_pred = neural_granger(cause_tensor, combined_tensor)
                            ar_mse = nn.MSELoss()(ar_pred.squeeze(), target_tensor)
                            var_mse = nn.MSELoss()(var_pred.squeeze(), target_tensor)
                            
                            granger_score = max(0, 1 - (var_mse / (ar_mse + 1e-8)))
                            granger_scores.append(float(granger_score))
                    
            return np.mean(granger_scores) if granger_scores else 0.5
            
        except Exception as e:
            self.logger.error(f"Advanced Granger causality validation failed: {e}")
            return 0.5
    
    async def _transfer_entropy_validation(self, temporal_sequences, causal_data, causal_engine):
        """Transfer entropy analysis for causal information flow validation"""
        try:
            import numpy as np
            from scipy.stats import entropy
            from sklearn.neighbors import NearestNeighbors
            
            def compute_transfer_entropy(source, target, k=3, lag=1):
                """Compute transfer entropy using k-nearest neighbors"""
                # Create embedding vectors
                def create_embedding(series, dim, delay):
                    N = len(series)
                    embedding = np.zeros((N - (dim-1)*delay, dim))
                    for i in range(dim):
                        start_idx = i * delay
                        end_idx = N - (dim-1)*delay + i*delay
                        embedding[:, i] = series[start_idx:end_idx]
                    return embedding
                
                if len(source) < 50 or len(target) < 50:
                    return 0.0
                
                # Create embeddings
                target_embed = create_embedding(target, k, 1)
                target_future = target[k:]
                source_embed = create_embedding(source[:-lag], k, 1)
                
                min_len = min(len(target_embed), len(source_embed))
                target_embed = target_embed[:min_len]
                target_future = target_future[:min_len]
                source_embed = source_embed[:min_len]
                
                # K-nearest neighbors approach
                knn = NearestNeighbors(n_neighbors=k+1)
                
                # Joint probability estimation
                joint_data = np.column_stack([target_embed, source_embed])
                knn.fit(joint_data)
                
                te_scores = []
                for i in range(len(joint_data)):
                    distances, indices = knn.kneighbors([joint_data[i]])
                    neighbors = indices[0][1:]  # Exclude self
                    
                    # Estimate conditional probabilities
                    neighbor_targets = target_future[neighbors]
                    current_target = target_future[i]
                    
                    # Transfer entropy approximation
                    if len(set(neighbor_targets)) > 1:
                        te_score = entropy(neighbor_targets) if len(neighbor_targets) > 0 else 0
                        te_scores.append(te_score)
                
                return np.mean(te_scores) if te_scores else 0.0
            
            te_validations = []
            
            # Process temporal sequences
            for seq_name, sequence_data in temporal_sequences.items():
                if isinstance(sequence_data, dict) and 'variables' in sequence_data:
                    variables = sequence_data['variables']
                    
                    for i, var1 in enumerate(variables):
                        for j, var2 in enumerate(variables):
                            if i != j and var1 in sequence_data and var2 in sequence_data:
                                source_seq = np.array(sequence_data[var1])
                                target_seq = np.array(sequence_data[var2])
                                
                                te_score = compute_transfer_entropy(source_seq, target_seq)
                                te_validations.append(te_score)
            
            # Validate against known causal relationships
            validation_score = 0.7
            if te_validations:
                avg_te = np.mean(te_validations)
                # Higher transfer entropy indicates stronger causal relationships
                validation_score = min(1.0, avg_te * 2.0)
            
            return validation_score
            
        except Exception as e:
            self.logger.error(f"Transfer entropy validation failed: {e}")
            return 0.5
    
    async def _structural_equation_validation(self, causal_data, temporal_result, model_db):
        """Structural equation model validation of causal relationships"""
        try:
            import torch
            import torch.nn as nn
            from sklearn.linear_model import LinearRegression
            from sklearn.metrics import r2_score
            
            # Load or create structural equation model
            sem_model = await model_db.get_latest_model('structural_equation_geological_v2')
            
            class GeologicalStructuralEquationNet(nn.Module):
                def __init__(self, num_variables, hidden_dim=128):
                    super().__init__()
                    self.num_variables = num_variables
                    
                    # Structural equation networks for each variable
                    self.equation_nets = nn.ModuleList([
                        nn.Sequential(
                            nn.Linear(num_variables - 1, hidden_dim),
                            nn.BatchNorm1d(hidden_dim),
                            nn.ReLU(),
                            nn.Dropout(0.3),
                            nn.Linear(hidden_dim, hidden_dim // 2),
                            nn.ReLU(),
                            nn.Linear(hidden_dim // 2, 1)
                        ) for _ in range(num_variables)
                    ])
                    
                    # Causal strength network
                    self.causal_strength_net = nn.Sequential(
                        nn.Linear(num_variables * num_variables, hidden_dim),
                        nn.ReLU(),
                        nn.Linear(hidden_dim, num_variables * num_variables),
                        nn.Sigmoid()
                    )
                
                def forward(self, x):
                    batch_size = x.size(0)
                    predictions = []
                    
                    for i, eq_net in enumerate(self.equation_nets):
                        # Use all variables except the target
                        input_vars = torch.cat([x[:, :i], x[:, i+1:]], dim=1)
                        pred = eq_net(input_vars)
                        predictions.append(pred)
                    
                    predictions = torch.cat(predictions, dim=1)
                    
                    # Compute causal strength matrix
                    causal_matrix = self.causal_strength_net(x.view(batch_size, -1))
                    causal_matrix = causal_matrix.view(batch_size, self.num_variables, self.num_variables)
                    
                    return predictions, causal_matrix
            
            # Extract variables from causal data
            variables = list(causal_data.get('variables', []))
            if len(variables) < 2:
                return 0.5
            
            # Create synthetic data for validation (in production, use real geological data)
            num_samples = 1000
            synthetic_data = np.random.randn(num_samples, len(variables))
            
            # Add causal relationships to synthetic data
            causal_strengths = causal_data.get('causal_strength', {})
            for i, var1 in enumerate(variables):
                for j, var2 in enumerate(variables):
                    if var1 in causal_strengths and var2 in causal_strengths[var1]:
                        strength = causal_strengths[var1][var2]
                        synthetic_data[:, j] += strength * synthetic_data[:, i] + 0.1 * np.random.randn(num_samples)
            
            # Train structural equation model
            data_tensor = torch.FloatTensor(synthetic_data)
            
            if sem_model is None:
                sem_net = GeologicalStructuralEquationNet(len(variables))
                optimizer = torch.optim.Adam(sem_net.parameters(), lr=0.001)
                criterion = nn.MSELoss()
                
                # Training
                for epoch in range(200):
                    optimizer.zero_grad()
                    predictions, causal_matrix = sem_net(data_tensor)
                    
                    # Structural equation loss
                    se_loss = criterion(predictions, data_tensor)
                    
                    # Causal consistency loss
                    known_causal_matrix = torch.zeros_like(causal_matrix[0])
                    for i, var1 in enumerate(variables):
                        for j, var2 in enumerate(variables):
                            if var1 in causal_strengths and var2 in causal_strengths[var1]:
                                known_causal_matrix[i, j] = causal_strengths[var1][var2]
                    
                    causal_loss = criterion(causal_matrix.mean(0), known_causal_matrix)
                    
                    total_loss = se_loss + 0.5 * causal_loss
                    total_loss.backward()
                    optimizer.step()
            else:
                sem_net = sem_model
            
            # Validation
            with torch.no_grad():
                predictions, causal_matrix = sem_net(data_tensor)
                validation_score = 1.0 - float(criterion(predictions, data_tensor))
                validation_score = max(0.0, min(1.0, validation_score))
            
            return validation_score
            
        except Exception as e:
            self.logger.error(f"Structural equation validation failed: {e}")
            return 0.5
    
    async def _dynamic_bayesian_validation(self, causal_data, temporal_result, knowledge_graph):
        """Dynamic Bayesian Network validation with geological knowledge"""
        try:
            import networkx as nx
            from scipy.stats import chi2_contingency
            
            # Create Dynamic Bayesian Network structure
            dbn_graph = nx.DiGraph()
            
            # Add nodes for variables
            variables = list(causal_data.get('variables', []))
            for var in variables:
                dbn_graph.add_node(f"{var}_t0")
                dbn_graph.add_node(f"{var}_t1")
                
                # Temporal edges (variable influences itself over time)
                dbn_graph.add_edge(f"{var}_t0", f"{var}_t1", weight=0.8)
            
            # Add causal edges based on causal_data
            causal_strengths = causal_data.get('causal_strength', {})
            for cause_var, effects in causal_strengths.items():
                for effect_var, strength in effects.items():
                    if cause_var in variables and effect_var in variables:
                        # Intra-time causal edges
                        dbn_graph.add_edge(f"{cause_var}_t0", f"{effect_var}_t0", weight=strength)
                        # Inter-time causal edges
                        dbn_graph.add_edge(f"{cause_var}_t0", f"{effect_var}_t1", weight=strength * 0.7)
            
            # Validate network structure using knowledge graph
            kg_validation_score = 0.7
            if knowledge_graph:
                try:
                    # Query knowledge graph for geological causal relationships
                    kg_relationships = await knowledge_graph.query_causal_relationships(variables)
                    
                    confirmed_relationships = 0
                    total_relationships = len(list(dbn_graph.edges()))
                    
                    for edge in dbn_graph.edges():
                        source_var = edge[0].split('_')[0]
                        target_var = edge[1].split('_')[0]
                        
                        # Check if relationship is supported by knowledge graph
                        if any(rel['source'] == source_var and rel['target'] == target_var 
                               for rel in kg_relationships):
                            confirmed_relationships += 1
                    
                    if total_relationships > 0:
                        kg_validation_score = confirmed_relationships / total_relationships
                
                except Exception as kg_error:
                    self.logger.warning(f"Knowledge graph validation failed: {kg_error}")
            
            # Compute network complexity penalty
            complexity_penalty = min(0.2, len(dbn_graph.edges()) / (len(variables) ** 2))
            
            # Final validation score
            validation_score = kg_validation_score - complexity_penalty
            return max(0.0, min(1.0, validation_score))
            
        except Exception as e:
            self.logger.error(f"Dynamic Bayesian validation failed: {e}")
            return 0.5
    
    async def _neural_causal_discovery_validation(self, causal_data, temporal_result, model_db):
        """Neural causal discovery validation using advanced neural networks"""
        try:
            import torch
            import torch.nn as nn
            import torch.nn.functional as F
            
            class AttentionCausalDiscovery(nn.Module):
                def __init__(self, num_variables, hidden_dim=128, num_heads=8):
                    super().__init__()
                    self.num_variables = num_variables
                    
                    # Multi-head attention for causal relationship discovery
                    self.causal_attention = nn.MultiheadAttention(
                        embed_dim=hidden_dim,
                        num_heads=num_heads,
                        dropout=0.1
                    )
                    
                    # Variable embedding
                    self.variable_embedding = nn.Linear(1, hidden_dim)
                    
                    # Causal strength predictor
                    self.causal_strength_predictor = nn.Sequential(
                        nn.Linear(hidden_dim * 2, hidden_dim),
                        nn.ReLU(),
                        nn.Dropout(0.3),
                        nn.Linear(hidden_dim, hidden_dim // 2),
                        nn.ReLU(),
                        nn.Linear(hidden_dim // 2, 1),
                        nn.Sigmoid()
                    )
                    
                    # Temporal dependency network
                    self.temporal_net = nn.LSTM(
                        input_size=hidden_dim,
                        hidden_size=hidden_dim // 2,
                        num_layers=2,
                        dropout=0.2,
                        batch_first=True
                    )
                
                def forward(self, variable_data, temporal_sequences=None):
                    batch_size, num_vars = variable_data.shape
                    
                    # Embed variables
                    embedded = self.variable_embedding(variable_data.unsqueeze(-1))  # [batch, vars, hidden]
                    
                    # Apply causal attention
                    attended, attention_weights = self.causal_attention(
                        embedded.transpose(0, 1),  # [vars, batch, hidden]
                        embedded.transpose(0, 1),
                        embedded.transpose(0, 1)
                    )
                    
                    attended = attended.transpose(0, 1)  # [batch, vars, hidden]
                    
                    # Compute pairwise causal strengths
                    causal_strengths = torch.zeros(batch_size, num_vars, num_vars)
                    
                    for i in range(num_vars):
                        for j in range(num_vars):
                            if i != j:
                                pair_input = torch.cat([attended[:, i], attended[:, j]], dim=1)
                                strength = self.causal_strength_predictor(pair_input)
                                causal_strengths[:, i, j] = strength.squeeze()
                    
                    # Process temporal sequences if available
                    temporal_output = None
                    if temporal_sequences is not None:
                        temporal_output, _ = self.temporal_net(attended)
                    
                    return causal_strengths, attention_weights, temporal_output
            
            # Load or create neural causal discovery model
            neural_model = await model_db.get_latest_model('neural_causal_discovery_v3')
            
            variables = list(causal_data.get('variables', []))
            if len(variables) < 2:
                return 0.5
            
            # Create validation data
            num_samples = 500
            variable_data = torch.randn(num_samples, len(variables))
            
            if neural_model is None:
                model = AttentionCausalDiscovery(len(variables))
                optimizer = torch.optim.Adam(model.parameters(), lr=0.001)
                
                # Training with known causal relationships
                known_strengths = torch.zeros(num_samples, len(variables), len(variables))
                causal_strengths_dict = causal_data.get('causal_strength', {})
                
                for i, var1 in enumerate(variables):
                    for j, var2 in enumerate(variables):
                        if var1 in causal_strengths_dict and var2 in causal_strengths_dict[var1]:
                            strength = causal_strengths_dict[var1][var2]
                            known_strengths[:, i, j] = strength
                
                # Training loop
                for epoch in range(100):
                    optimizer.zero_grad()
                    pred_strengths, _, _ = model(variable_data)
                    
                    loss = F.mse_loss(pred_strengths, known_strengths)
                    loss.backward()
                    optimizer.step()
            else:
                model = neural_model
            
            # Validation
            with torch.no_grad():
                pred_strengths, attention_weights, _ = model(variable_data)
                
                # Compare with known causal relationships
                validation_scores = []
                causal_strengths_dict = causal_data.get('causal_strength', {})
                
                for i, var1 in enumerate(variables):
                    for j, var2 in enumerate(variables):
                        if var1 in causal_strengths_dict and var2 in causal_strengths_dict[var1]:
                            known_strength = causal_strengths_dict[var1][var2]
                            pred_strength = torch.mean(pred_strengths[:, i, j]).item()
                            
                            # Compute validation score
                            error = abs(known_strength - pred_strength)
                            validation_score = max(0, 1 - 2 * error)  # Scale error to validation score
                            validation_scores.append(validation_score)
                
                return np.mean(validation_scores) if validation_scores else 0.5
            
        except Exception as e:
            self.logger.error(f"Neural causal discovery validation failed: {e}")
            return 0.5
    
    async def _knowledge_graph_causal_validation(self, causal_data, knowledge_graph, db_integration):
        """Validate causal relationships against geological knowledge graph"""
        try:
            if not knowledge_graph:
                return 0.5
            
            variables = list(causal_data.get('variables', []))
            causal_strengths = causal_data.get('causal_strength', {})
            
            # Query knowledge graph for expert geological relationships
            kg_relationships = await knowledge_graph.query_geological_causality(variables)
            
            validation_scores = []
            
            for cause_var, effects in causal_strengths.items():
                for effect_var, predicted_strength in effects.items():
                    # Check if this causal relationship exists in knowledge graph
                    kg_relationship = next((
                        rel for rel in kg_relationships 
                        if rel['cause'] == cause_var and rel['effect'] == effect_var
                    ), None)
                    
                    if kg_relationship:
                        # Compare predicted strength with expert knowledge
                        expert_strength = kg_relationship.get('strength', 0.5)
                        confidence = kg_relationship.get('confidence', 0.7)
                        
                        # Validation score based on agreement with expert knowledge
                        strength_error = abs(predicted_strength - expert_strength)
                        agreement_score = max(0, 1 - 2 * strength_error)
                        
                        # Weight by expert confidence
                        weighted_score = agreement_score * confidence
                        validation_scores.append(weighted_score)
                    else:
                        # Penalize relationships not found in knowledge graph
                        validation_scores.append(0.3)
            
            # Additional validation: check for missing important relationships
            important_relationships = await knowledge_graph.get_important_geological_relationships(variables)
            missing_penalty = 0
            
            for imp_rel in important_relationships:
                cause, effect = imp_rel['cause'], imp_rel['effect']
                if (cause not in causal_strengths or 
                    effect not in causal_strengths.get(cause, {})):
                    missing_penalty += 0.1 * imp_rel.get('importance', 0.5)
            
            base_validation = np.mean(validation_scores) if validation_scores else 0.3
            final_validation = max(0.0, base_validation - missing_penalty)
            
            return min(1.0, final_validation)
            
        except Exception as e:
            self.logger.error(f"Knowledge graph causal validation failed: {e}")
            return 0.5
    
    async def _advanced_temporal_consistency_validation(self, causal_data, temporal_result, causal_discovery):
        """Advanced temporal consistency validation with geological process timing"""
        try:
            consistency_metrics = {
                'lag_consistency': 0.0,
                'causality_direction_consistency': 0.0,
                'temporal_stability': 0.0,
                'process_timing_consistency': 0.0
            }
            
            variables = list(causal_data.get('variables', []))
            causal_strengths = causal_data.get('causal_strength', {})
            
            # 1. Validate causal lags against geological process timescales
            if 'temporal_lags' in causal_data:
                lag_validations = []
                expected_lags = await causal_discovery.get_geological_process_lags(variables)
                
                for cause_var, effects in causal_data['temporal_lags'].items():
                    for effect_var, predicted_lag in effects.items():
                        if cause_var in expected_lags and effect_var in expected_lags[cause_var]:
                            expected_lag = expected_lags[cause_var][effect_var]
                            
                            # Validate lag against geological expectations
                            lag_ratio = min(predicted_lag, expected_lag) / max(predicted_lag, expected_lag)
                            lag_validations.append(lag_ratio)
                
                consistency_metrics['lag_consistency'] = np.mean(lag_validations) if lag_validations else 0.5
            
            # 2. Validate causality direction consistency over time
            if 'temporal_sequences' in temporal_result:
                direction_consistencies = []
                
                for sequence_name, sequence_data in temporal_result['temporal_sequences'].items():
                    if 'variables' in sequence_data:
                        seq_variables = sequence_data['variables']
                        
                        # Check if causal directions remain consistent over time windows
                        window_size = len(sequence_data.get(seq_variables[0], [])) // 5
                        
                        for cause_var in seq_variables:
                            for effect_var in seq_variables:
                                if (cause_var in causal_strengths and 
                                    effect_var in causal_strengths[cause_var]):
                                    
                                    # Analyze causality in time windows
                                    window_strengths = []
                                    if cause_var in sequence_data and effect_var in sequence_data:
                                        cause_seq = sequence_data[cause_var]
                                        effect_seq = sequence_data[effect_var]
                                        
                                        for i in range(0, len(cause_seq) - window_size, window_size):
                                            window_cause = cause_seq[i:i+window_size]
                                            window_effect = effect_seq[i:i+window_size]
                                            
                                            # Simple correlation as proxy for causal strength
                                            if len(window_cause) > 1 and len(window_effect) > 1:
                                                corr = np.corrcoef(window_cause, window_effect)[0, 1]
                                                if not np.isnan(corr):
                                                    window_strengths.append(abs(corr))
                                        
                                        if window_strengths:
                                            # Consistency = 1 - variance of window strengths
                                            consistency = 1 - np.var(window_strengths)
                                            direction_consistencies.append(max(0, consistency))
                
                consistency_metrics['causality_direction_consistency'] = (
                    np.mean(direction_consistencies) if direction_consistencies else 0.5
                )
            
            # 3. Temporal stability validation
            if 'time_series_data' in temporal_result:
                stability_scores = []
                ts_data = temporal_result['time_series_data']
                
                for var in variables:
                    if var in ts_data:
                        series = np.array(ts_data[var])
                        if len(series) > 10:
                            # Compute stability using autocorrelation
                            autocorr = np.correlate(series, series, mode='full')
                            autocorr = autocorr[len(autocorr)//2:]
                            
                            # High autocorrelation indicates temporal stability
                            stability = np.mean(autocorr[:min(5, len(autocorr))])
                            stability_scores.append(max(0, min(1, stability)))
                
                consistency_metrics['temporal_stability'] = (
                    np.mean(stability_scores) if stability_scores else 0.5
                )
            
            # 4. Geological process timing consistency
            process_timing_score = await self._validate_geological_process_timing(
                causal_data, temporal_result
            )
            consistency_metrics['process_timing_consistency'] = process_timing_score
            
            # Weighted ensemble of consistency metrics
            weights = {
                'lag_consistency': 0.3,
                'causality_direction_consistency': 0.3,
                'temporal_stability': 0.2,
                'process_timing_consistency': 0.2
            }
            
            final_consistency = sum(
                consistency_metrics[metric] * weights[metric]
                for metric in consistency_metrics if metric in weights
            )
            
            return max(0.0, min(1.0, final_consistency))
            
        except Exception as e:
            self.logger.error(f"Advanced temporal consistency validation failed: {e}")
            return 0.5
    
    async def _validate_geological_process_timing(self, causal_data, temporal_result):
        """Validate causal relationships against known geological process timescales"""
        try:
            # Geological process timescales (in seconds)
            process_timescales = {
                'earthquake': {'immediate': 1, 'foreshock': 3600, 'aftershock': 86400},
                'volcanic_eruption': {'gas_emission': 3600, 'deformation': 86400, 'precursor': 604800},
                'landslide': {'precipitation_trigger': 7200, 'slope_failure': 300, 'aftereffects': 86400},
                'groundwater': {'recharge': 2592000, 'discharge': 86400, 'contamination': 604800},
                'tectonic': {'stress_buildup': 31536000, 'fault_activation': 1, 'deformation': 86400}
            }
            
            timing_validations = []
            variables = causal_data.get('variables', [])
            
            # Match variables to geological processes
            for var in variables:
                var_lower = var.lower()
                matched_processes = []
                
                for process, timescales in process_timescales.items():
                    if any(keyword in var_lower for keyword in process.split('_')):
                        matched_processes.append((process, timescales))
                
                # Validate timing for matched processes
                if matched_processes and 'temporal_lags' in causal_data:
                    for process, expected_timescales in matched_processes:
                        for cause_var, effects in causal_data['temporal_lags'].items():
                            if var == cause_var or var in effects:
                                for effect_var, predicted_lag in effects.items():
                                    # Find most appropriate expected timescale
                                    best_match_score = 0
                                    for scale_name, expected_lag in expected_timescales.items():
                                        # Score based on how close predicted lag is to expected
                                        if expected_lag > 0:
                                            ratio = min(predicted_lag, expected_lag) / max(predicted_lag, expected_lag)
                                            if ratio > best_match_score:
                                                best_match_score = ratio
                                    
                                    timing_validations.append(best_match_score)
            
            return np.mean(timing_validations) if timing_validations else 0.7
            
        except Exception as e:
            self.logger.error(f"Geological process timing validation failed: {e}")
            return 0.5
    
