    async def _fallback_causal_validation(self, temporal_result):
        """Fallback causal validation when advanced methods are unavailable"""
        try:
            if 'causal_relationships' in temporal_result:
                causal_data = temporal_result['causal_relationships']
                
                # Simple validation based on causal strength consistency
                if 'causal_strength' in causal_data:
                    strengths = causal_data['causal_strength']
                    if isinstance(strengths, dict):
                        all_strengths = []
                        for cause_strengths in strengths.values():
                            if isinstance(cause_strengths, dict):
                                all_strengths.extend(cause_strengths.values())
                        
                        if all_strengths:
                            avg_strength = np.mean(all_strengths)
                            strength_variance = np.var(all_strengths)
                            
                            # Higher average strength and lower variance = better validation
                            validation_score = avg_strength * (1 - strength_variance)
                            return max(0.3, min(1.0, validation_score))
                
                return 0.6
            
            return 0.5
            
        except Exception as e:
            self.logger.error(f"Fallback causal validation failed: {e}")
            return 0.5
    
    async def _fallback_consistency_integration(self, scores, causal_analysis, confidence):
        """Fallback consistency integration when advanced methods are unavailable"""
        try:
            traditional_scores = np.mean(scores) if scores else 0.5
            causal_score = float(causal_analysis) if causal_analysis else 0.5
            
            # Enhanced weighted integration with geological priors
            geological_prior = 0.65  # Conservative geological prior
            
            # Adaptive weighting based on confidence
            if confidence > 0.8:
                # High confidence: trust causal analysis more
                integrated_score = 0.3 * traditional_scores + 0.6 * causal_score + 0.1 * geological_prior
            elif confidence > 0.6:
                # Medium confidence: balanced weighting
                integrated_score = 0.5 * traditional_scores + 0.4 * causal_score + 0.1 * geological_prior
            else:
                # Low confidence: rely more on traditional scores and priors
                integrated_score = 0.6 * traditional_scores + 0.2 * causal_score + 0.2 * geological_prior
            
            # Apply confidence adjustment
            final_score = integrated_score * confidence + geological_prior * (1 - confidence)
            
            return max(0.0, min(1.0, final_score))
            
        except Exception as e:
            self.logger.error(f"Fallback consistency integration failed: {e}")
            return 0.6
    
    async def _fallback_cross_domain_analysis(self, domain_scores, geo_checks):
        """Fallback cross-domain analysis when advanced methods are unavailable"""
        try:
            if len(domain_scores) < 2:
                return 0.7
            
            scores = np.array(list(domain_scores.values()))
            
            # Enhanced statistical consistency analysis
            score_mean = np.mean(scores)
            score_std = np.std(scores)
            score_range = np.ptp(scores)
            
            # Consistency based on multiple factors
            consistency_factors = []
            
            # 1. Low variance indicates consistency
            variance_score = 1.0 / (1.0 + 3.0 * score_std)
            consistency_factors.append(variance_score)
            
            # 2. High mean scores indicate good overall performance
            mean_score = min(1.0, score_mean * 1.2)
            consistency_factors.append(mean_score)
            
            # 3. Reasonable range indicates balanced performance
            if score_range < 0.3:
                range_score = 1.0
            elif score_range < 0.6:
                range_score = 0.8
            else:
                range_score = 0.6
            consistency_factors.append(range_score)
            
            # 4. Bonus for multiple high-confidence domains
            high_confidence_ratio = np.mean(scores > 0.8)
            confidence_bonus = min(0.2, high_confidence_ratio * 0.3)
            
            # 5. Penalty for very low scores
            low_score_ratio = np.mean(scores < 0.3)
            low_score_penalty = low_score_ratio * 0.2
            
            base_consistency = np.mean(consistency_factors)
            final_consistency = base_consistency + confidence_bonus - low_score_penalty
            
            return max(0.0, min(1.0, final_consistency))
            
        except Exception as e:
            self.logger.error(f"Fallback cross-domain analysis failed: {e}")
            return 0.6

