    def _estimate_climate_from_geography(self, lat: float, lon: float) -> Dict[str, float]:
        """Estimate climate parameters from geographic location"""
        abs_lat = abs(lat)
        
        # Temperature patterns
        if abs_lat < 23.5:  # Tropics
            temp_range = 5
            annual_precip = 2000 + 500 * np.random.randn()
        elif abs_lat < 35:  # Subtropics
            temp_range = 15
            annual_precip = 800 + 400 * np.random.randn()
        elif abs_lat < 50:  # Temperate
            temp_range = 25
            annual_precip = 1000 + 300 * np.random.randn()
        else:  # Polar
            temp_range = 35
            annual_precip = 400 + 200 * np.random.randn()
        
        return {
            'precipitation_intensity': max(200, annual_precip),
            'temperature_range': temp_range,
            'aridity_index': max(0.1, min(2.0, 1.0 - annual_precip / 2000)),
            'pet_ratio': 0.5 + 0.5 * (abs_lat / 90),
            'seasonal_variability': 0.3 + 0.4 * (abs_lat / 45)
        }
    
