    def _calibrate_plausibility_score(self, weighted_score: float, components: Dict[str, float]) -> float:
        """Apply domain-specific calibration to plausibility score"""
        try:
            # Apply sigmoid calibration with geological expertise
            alpha = 2.0  # Steepness parameter
            beta = 0.5   # Midpoint parameter
            calibrated = 1.0 / (1.0 + np.exp(-alpha * (weighted_score - beta)))
            
            # Apply component-specific adjustments
            if components.get('physics', 0) < 0.3:
                calibrated *= 0.8  # Strong penalty for physics violations
            
            if components.get('thermodynamics', 0) < 0.3:
                calibrated *= 0.9  # Penalty for thermodynamic violations
            
            # Bonus for high mechanism validation
            if components.get('mechanisms', 0) > 0.8:
                calibrated *= 1.1
            
            return max(0.0, min(1.0, calibrated))
        except:
            return weighted_score

    def _quantify_plausibility_uncertainty(self, components: Dict[str, float]) -> float:
        """Quantify uncertainty in plausibility assessment"""
        try:
            # Calculate variance across components
            values = [v for v in components.values() if not np.isnan(v)]
            if len(values) < 2:
                return 0.5
            
            variance = np.var(values)
            
            # Calculate component disagreement
            disagreement = np.std(values)
            
            # Combine into uncertainty measure
            uncertainty = min(1.0, variance + 0.5 * disagreement)
            return uncertainty
        except:
            return 0.5

