    def _compute_information_complexity(self, data: np.ndarray) -> float:
        """Compute information-theoretic complexity measures"""
        try:
            complexity_measures = []
            
            # Shannon entropy
            shannon_entropy = self._calculate_shannon_entropy(data)
            complexity_measures.append(shannon_entropy)
            
            # Rényi entropy spectrum
            renyi_entropies = self._calculate_renyi_entropy_spectrum(data)
            complexity_measures.extend(renyi_entropies)
            
            # Tsallis entropy
            tsallis_entropy = self._calculate_tsallis_entropy(data)
            complexity_measures.append(tsallis_entropy)
            
            # Mutual information
            if data.ndim > 1 and data.shape[1] > 1:
                mi_complexity = self._calculate_mutual_information_complexity(data)
                complexity_measures.append(mi_complexity)
            
            # Transfer entropy
            if data.shape[0] > 50:  # Need sufficient samples for transfer entropy
                te_complexity = self._calculate_transfer_entropy_complexity(data)
                complexity_measures.append(te_complexity)
            
            return np.mean([c for c in complexity_measures if not np.isnan(c)])
        except:
            return 0.5

    def _compute_topological_complexity(self, data: np.ndarray) -> float:
        """Compute topological data analysis complexity"""
        try:
            # Persistent homology-based complexity
            persistence_complexity = self._calculate_persistence_complexity(data)
            
            # Mapper algorithm complexity
            mapper_complexity = self._calculate_mapper_complexity(data)
            
            # Witness complex complexity
            witness_complexity = self._calculate_witness_complex_complexity(data)
            
            complexities = [persistence_complexity, mapper_complexity, witness_complexity]
            return np.mean([c for c in complexities if not np.isnan(c)])
        except:
            return 0.5

    def _compute_fractal_complexity(self, data: np.ndarray) -> float:
        """Compute fractal dimension and related complexity measures"""
        try:
            # Box-counting dimension
            box_dimension = self._calculate_box_counting_dimension(data)
            
            # Correlation dimension
            correlation_dimension = self._calculate_correlation_dimension(data)
            
            # Information dimension
            information_dimension = self._calculate_information_dimension(data)
            
            # Lyapunov exponents
            if data.shape[0] > 100:
                lyapunov_complexity = self._calculate_lyapunov_complexity(data)
            else:
                lyapunov_complexity = 0.5
            
            dimensions = [box_dimension, correlation_dimension, information_dimension, lyapunov_complexity]
            return np.mean([d for d in dimensions if not np.isnan(d)])
        except:
            return 0.5

    def _compute_dynamical_complexity(self, data: np.ndarray) -> float:
        """Compute complexity from dynamical systems perspective"""
        try:
            # Recurrence quantification analysis
            rqa_complexity = self._calculate_rqa_complexity(data)
            
            # Phase space reconstruction complexity
            phase_space_complexity = self._calculate_phase_space_complexity(data)
            
            # Nonlinear prediction complexity
            prediction_complexity = self._calculate_prediction_complexity(data)
            
            # Surrogate data complexity
            surrogate_complexity = self._calculate_surrogate_complexity(data)
            
            complexities = [rqa_complexity, phase_space_complexity, prediction_complexity, surrogate_complexity]
            return np.mean([c for c in complexities if not np.isnan(c)])
        except:
            return 0.5

