    def _determine_complexity_weights(self, data: np.ndarray, measures: Dict[str, float]) -> Dict[str, float]:
        """Determine adaptive weights for complexity measures based on data characteristics"""
        try:
            weights = {
                'information': 0.15,
                'topological': 0.12,
                'fractal': 0.12,
                'dynamical': 0.15,
                'network': 0.10,
                'spectral': 0.12,
                'nonlinear': 0.12,
                'multiscale': 0.12
            }
            
            # Adjust weights based on data properties
            n_samples, n_features = data.shape[0], data.shape[1] if data.ndim > 1 else 1
            
            # For small datasets, rely more on robust measures
            if n_samples < 100:
                weights['information'] += 0.05
                weights['spectral'] += 0.05
                weights['dynamical'] -= 0.05
                weights['topological'] -= 0.05
            
            # For high-dimensional data, emphasize network measures
            if n_features > 10:
                weights['network'] += 0.08
                weights['information'] -= 0.04
                weights['fractal'] -= 0.04
            
            # For time series data, emphasize temporal measures
            if self._is_time_series(data):
                weights['dynamical'] += 0.05
                weights['spectral'] += 0.05
                weights['topological'] -= 0.05
                weights['network'] -= 0.05
            
            # Normalize weights
            total_weight = sum(weights.values())
            return {k: v/total_weight for k, v in weights.items()}
        except:
            return {
                'information': 0.125, 'topological': 0.125, 'fractal': 0.125, 'dynamical': 0.125,
                'network': 0.125, 'spectral': 0.125, 'nonlinear': 0.125, 'multiscale': 0.125
            }

    def _calibrate_geological_complexity(self, complexity: float, data: np.ndarray) -> float:
        """Apply geological domain-specific calibration to complexity score"""
        try:
            # Calibrate based on geological data characteristics
            calibrated = complexity
            
            # Seismic data typically has high spectral complexity
            if self._is_seismic_data(data):
                calibrated *= 1.1
            
            # Geochemical data often has moderate complexity
            if self._is_geochemical_data(data):
                calibrated *= 0.95
            
            # Geological structure data can have high topological complexity
            if self._is_structural_data(data):
                calibrated *= 1.05
            
            return max(0.0, min(1.0, calibrated))
        except:
            return complexity

    def _estimate_complexity_uncertainty(self, measures: Dict[str, float]) -> float:
        """Estimate uncertainty in complexity calculation"""
        try:
            values = [v for v in measures.values() if not np.isnan(v)]
            if len(values) < 2:
                return 0.5
            
            # Calculate coefficient of variation
            cv = np.std(values) / (np.mean(values) + 1e-10)
            
            # Convert to uncertainty measure
            uncertainty = min(1.0, cv)
            return uncertainty
        except:
            return 0.5

    # ====================================================================
    # INFORMATION THEORY HELPER METHODS
    # ====================================================================

    def _calculate_shannon_entropy(self, data: np.ndarray) -> float:
        """Calculate Shannon entropy"""
        try:
            # Discretize data for entropy calculation
            discretized = self._discretize_data(data.flatten(), bins=50)
            _, counts = np.unique(discretized, return_counts=True)
            probabilities = counts / len(discretized)
            
            # Shannon entropy
            entropy = -np.sum(probabilities * np.log2(probabilities + 1e-10))
            return entropy / np.log2(len(probabilities))  # Normalized
        except:
            return 0.5

    def _calculate_renyi_entropy_spectrum(self, data: np.ndarray) -> List[float]:
        """Calculate Rényi entropy for different orders"""
        try:
            discretized = self._discretize_data(data.flatten(), bins=50)
            _, counts = np.unique(discretized, return_counts=True)
            probabilities = counts / len(discretized)
            
            orders = [0.5, 2.0, np.inf]
            entropies = []
            
            for alpha in orders:
                if alpha == np.inf:
                    # Min-entropy
                    entropy = -np.log2(np.max(probabilities))
                else:
                    entropy = (1/(1-alpha)) * np.log2(np.sum(probabilities**alpha))
                entropies.append(entropy / np.log2(len(probabilities)))  # Normalized
            
            return entropies
        except:
            return [0.5, 0.5, 0.5]

    def _calculate_tsallis_entropy(self, data: np.ndarray) -> float:
        """Calculate Tsallis entropy"""
        try:
            discretized = self._discretize_data(data.flatten(), bins=50)
            _, counts = np.unique(discretized, return_counts=True)
            probabilities = counts / len(discretized)
            
            q = 1.5  # Tsallis parameter
            entropy = (1/(q-1)) * (1 - np.sum(probabilities**q))
            return max(0.0, min(1.0, entropy))
        except:
            return 0.5

    def _discretize_data(self, data: np.ndarray, bins: int = 50) -> np.ndarray:
        """Discretize continuous data for entropy calculations"""
        try:
            if len(np.unique(data)) <= bins:
                return data
            
            # Use equal-width binning
            bin_edges = np.linspace(np.min(data), np.max(data), bins + 1)
            discretized = np.digitize(data, bin_edges) - 1
            discretized = np.clip(discretized, 0, bins - 1)
            return discretized
        except:
            return np.zeros_like(data, dtype=int)

