    def _calculate_correlation_network_complexity(self, data: np.ndarray) -> float:
        """Calculate correlation network complexity"""
        try:
            if data.shape[1] < 2:
                return 0.5
            corr_matrix = np.corrcoef(data.T)
            # Network density as complexity proxy
            threshold = 0.5
            adj_matrix = np.abs(corr_matrix) > threshold
            density = np.sum(adj_matrix) / (adj_matrix.shape[0] * (adj_matrix.shape[0] - 1))
            return min(1.0, density)
        except:
            return 0.5

