            spectral_features['multitaper'] = self._compute_multitaper_spectrum(data)
            
            # 2. Continuous wavelet transform scalogram
            spectral_features['wavelet_scalogram'] = self._compute_cwt_scalogram(data)
            
            # 3. Short-time Fourier transform for time-frequency analysis
            spectral_features['stft_spectrogram'] = self._compute_stft_spectrogram(data)
            
            # 4. Welch's method for robust PSD estimation
            spectral_features['welch_psd'] = self._compute_welch_psd(data)
            
            # 5. Periodogram-based spectral features
            spectral_features['periodogram_features'] = self._extract_periodogram_features(data)
            
            # 6. Spectral entropy and complexity measures
            spectral_features['entropy_measures'] = self._compute_spectral_entropy_measures(data)
            
            # 7. Cross-spectral analysis (if multi-channel)
            if data.ndim > 1 and data.shape[-1] > 1:
                spectral_features['cross_spectral'] = self._compute_cross_spectral_features(data)
            
            # 8. Geological frequency band analysis
            spectral_features['geological_bands'] = self._analyze_geological_frequency_bands(data)
            
            # 9. Harmonic analysis for geological periodicity
            spectral_features['harmonic_analysis'] = self._analyze_geological_harmonics(data)
            
            # 10. Spectral peak characterization
