    def _compute_multitaper_spectrum(self, data):
        """Compute multitaper spectral estimate."""
        try:
            from scipy import signal
            data = np.asarray(data)
            if data.size < 8:
                return {'error': 'insufficient_data'}
            
            # Simplified multitaper approach using multiple windows
            freqs, psd = signal.welch(data, nperseg=min(64, len(data)//2))
            return {
                'frequencies': freqs.tolist(),
                'power_spectral_density': psd.tolist(),
                'spectral_resolution': freqs[1] - freqs[0] if len(freqs) > 1 else 1.0,
                'total_power': float(np.sum(psd))
            }
        except Exception:
            return {'error': 'computation_failed'}
    
    def _box_counting_dimension(self, data):
        """Compute box-counting fractal dimension."""
        try:
            data = np.asarray(data)
            if data.size < 10:
                return 1.5
            
            # Simplified box-counting using data range analysis
            data_range = np.max(data) - np.min(data)
            if data_range == 0:
                return 1.0
            
            # Estimate dimension based on data complexity
            normalized_variance = np.var(data) / (data_range**2) if data_range > 0 else 0
            estimated_dimension = 1.0 + normalized_variance
            
            return float(np.clip(estimated_dimension, 1.0, 2.0))
            
        except Exception:
            return 1.5
    
    def _classical_multiscale_entropy(self, data):
        """Compute classical multiscale entropy."""
        try:
            from scipy.stats import entropy
            
            data = np.asarray(data)
            if data.size < 10:
                return {'scales': [], 'entropies': []}
            
            scales = range(1, min(11, len(data)//4))
            entropies = []
            
            for scale in scales:
                # Coarse-grain the data
                coarse_grained = []
                for i in range(len(data) // scale):
                    window = data[i*scale:(i+1)*scale]
                    coarse_grained.append(np.mean(window))
                
                if len(coarse_grained) > 2:
                    # Compute sample entropy approximation
                    hist, _ = np.histogram(coarse_grained, bins=10)
                    hist = hist + 1e-10  # Avoid log(0)
                    ent = entropy(hist / np.sum(hist))
                    entropies.append(float(ent))
                else:
                    entropies.append(0.0)
            
            return {
                'scales': list(scales),
                'entropies': entropies,
                'complexity_index': float(np.mean(entropies)) if entropies else 0.0
            }
            
        except Exception:
            return {'scales': [1], 'entropies': [0.5], 'complexity_index': 0.5}
    
    def _identify_wavelet_temporal_scales(self, data):
        """Identify temporal scales using wavelet analysis."""
        try:
            import pywt
            
            data = np.asarray(data)
            if data.size < 16:
                return [1.0]
            
            # Continuous wavelet transform
            scales = np.arange(1, min(32, len(data)//4))
            coeffs, _ = pywt.cwt(data, scales, 'morl')
            
            # Find scales with significant energy
            scale_energy = np.mean(np.abs(coeffs)**2, axis=1)
            energy_threshold = np.mean(scale_energy) + np.std(scale_energy)
            
            significant_scales = scales[scale_energy > energy_threshold]
            
            return significant_scales.tolist() if len(significant_scales) > 0 else [1.0]
            
        except Exception:
            return [1.0]
    
    def _statistical_nonlinearity_tests(self, data):
        """Perform statistical tests for nonlinearity."""
        try:
            from scipy.stats import jarque_bera, normaltest
            
            data = np.asarray(data)
            if data.size < 8:
                return {'nonlinearity_score': 0.5}
            
            # Jarque-Bera test for normality
            jb_stat, jb_pval = jarque_bera(data)
            
            # Shapiro-Wilk approximation using higher moments
            skewness = float(np.abs(np.mean((data - np.mean(data))**3) / np.std(data)**3))
            kurtosis = float(np.abs(np.mean((data - np.mean(data))**4) / np.std(data)**4 - 3))
            
            # Nonlinearity score based on deviation from normality
            nonlinearity_score = min(1.0, (skewness + kurtosis) / 4.0)
            
            return {
                'nonlinearity_score': float(nonlinearity_score),
                'jarque_bera_statistic': float(jb_stat),
                'jarque_bera_pvalue': float(jb_pval),
                'skewness': skewness,
                'excess_kurtosis': kurtosis
            }
            
        except Exception:
            return {'nonlinearity_score': 0.5}
    
    def _compute_phase_stability_constraints(self, data, geological_context):
        """Compute phase stability constraints from thermodynamic principles."""
        try:
            data = np.asarray(data)
            if data.size == 0:
                return (0, 1)
            
            # Estimate temperature and pressure ranges based on data characteristics
            data_range = np.max(data) - np.min(data)
            data_mean = np.mean(data)
            
            # Phase stability depends on geological regime
            regime = geological_context.get('geological_regime', {})
            if isinstance(regime, dict):
                dominant_regime = regime.get('dominant_regime', 'unknown')
            else:
                dominant_regime = str(regime)
            
            # Define phase stability bounds based on regime
            if 'volcanic' in dominant_regime or 'magmatic' in dominant_regime:
                # High temperature, variable pressure
                stability_bounds = (data_mean - 2*data_range, data_mean + 3*data_range)
            elif 'metamorphic' in dominant_regime:
                # Moderate to high temperature and pressure
                stability_bounds = (data_mean - 1.5*data_range, data_mean + 2*data_range)
            elif 'sedimentary' in dominant_regime:
                # Low to moderate temperature and pressure
                stability_bounds = (data_mean - data_range, data_mean + 1.5*data_range)
            else:
                # Default bounds
                stability_bounds = (data_mean - data_range, data_mean + data_range)
            
            return stability_bounds
            
        except Exception:
            return (float(np.min(data)), float(np.max(data))) if data.size > 0 else (0, 1)

