    def _apply_elastic_moduli_constraints(self, threshold, data, petrophysical_properties, geological_context):
        """Apply constraints based on elastic moduli and rock physics relationships."""
        try:
            data = np.asarray(data)
            if data.size == 0:
                return threshold
            
            # Extract elastic properties
            bulk_modulus = petrophysical_properties.get('bulk_modulus', 50e9)
            shear_modulus = petrophysical_properties.get('shear_modulus', 30e9)
            youngs_modulus = petrophysical_properties.get('youngs_modulus', 70e9)
            poisson_ratio = petrophysical_properties.get('poisson_ratio', 0.25)
            
            # Apply Voigt-Reuss-Hill bounds
            vrh_bounds = self._calculate_voigt_reuss_hill_bounds(petrophysical_properties)
            
            # Apply Gassmann's equation for fluid effects
            gassmann_constraints = self._apply_gassmann_constraints(data, petrophysical_properties)
            
            # Apply Biot-Geertsma poroelastic constraints
            poroelastic_constraints = self._apply_biot_geertsma_constraints(data, petrophysical_properties)
            
            # Calculate effective medium constraints (self-consistent, differential effective medium)\n            effective_medium_constraints = self._apply_effective_medium_constraints(data, petrophysical_properties)
            
            # Combine elastic moduli constraints
            data_range = np.max(data) - np.min(data) if data.size > 1 else 1.0
            data_mean = np.mean(data)
            
            # Constraint factor based on elastic properties
            elastic_constraint_factor = self._calculate_elastic_constraint_factor(
                bulk_modulus, shear_modulus, youngs_modulus, poisson_ratio
            )
            
            constrained_threshold = np.clip(threshold,
                data_mean - elastic_constraint_factor * data_range,
                data_mean + elastic_constraint_factor * data_range
            )
            
            return constrained_threshold
            
        except Exception as e:
            self.logger.warning(f"Elastic moduli constraint application failed: {e}")
            return threshold
    
