    def _derive_igneous_petrophysical_properties(self, data, geological_context):
        """Derive petrophysical properties for igneous rocks."""
        try:
            data = np.asarray(data)
            properties = {}
            
            # Typical igneous rock properties
            properties['density'] = self._estimate_density_igneous(data, geological_context)
            properties['porosity'] = self._estimate_porosity_igneous(data, geological_context)
            properties['vp_vs_ratio'] = self._estimate_vp_vs_ratio_igneous(data, geological_context)
            properties['grain_size'] = self._estimate_grain_size_igneous(data, geological_context)
            properties['crystallinity'] = self._estimate_crystallinity_igneous(data, geological_context)
            properties['alteration_degree'] = self._estimate_alteration_igneous(data, geological_context)
            
            return properties
            
        except Exception:
            return {'density': 2700, 'porosity': 0.1, 'vp_vs_ratio': 1.73}
    
    def _calculate_bulk_modulus(self, properties, data):
        """Calculate bulk modulus from petrophysical properties."""
        try:
            density = properties.get('density', 2700)
            vp_vs_ratio = properties.get('vp_vs_ratio', 1.73)
            
            # Estimate from density and velocity ratios
            vs_estimate = 3500  # Default S-wave velocity
            vp_estimate = vs_estimate * vp_vs_ratio
            
            # Calculate bulk modulus
            mu = density * vs_estimate**2
            bulk_modulus = density * vp_estimate**2 - (4/3) * mu
            
            return float(max(1e9, bulk_modulus))  # Minimum 1 GPa
            
        except Exception:
            return 50e9  # 50 GPa default
    
    def _perform_multi_domain_spectral_analysis(self, data):
        """Perform multi-domain spectral analysis."""
        try:
            from scipy import signal
            from scipy.fft import fft, fftfreq
            
            data = np.asarray(data)
            analysis = {}
            
            # Standard FFT
            fft_result = fft(data)
            freqs = fftfreq(len(data))
            analysis['fft_magnitude'] = np.abs(fft_result)
            analysis['fft_phase'] = np.angle(fft_result)
            analysis['frequencies'] = freqs
            
            # Welch's method for PSD
            if len(data) > 8:
                freqs_welch, psd = signal.welch(data, nperseg=min(len(data)//2, 256))
                analysis['welch_frequencies'] = freqs_welch
                analysis['welch_psd'] = psd
            
            # Dominant frequency identification
            if len(analysis.get('welch_psd', [])) > 0:
                dominant_idx = np.argmax(analysis['welch_psd'])
                analysis['dominant_frequency'] = analysis['welch_frequencies'][dominant_idx]
            else:
                analysis['dominant_frequency'] = 1.0
            
            # Spectral centroid and bandwidth
            analysis['spectral_centroid'] = self._calculate_spectral_centroid_advanced(data)
            analysis['spectral_bandwidth'] = self._calculate_spectral_bandwidth_advanced(data)
            
            return analysis
            
        except Exception as e:
            return {'error': str(e), 'dominant_frequency': 1.0}
    
    def _calculate_spectral_centroid_advanced(self, data):
        """Calculate advanced spectral centroid."""
        try:
            from scipy.fft import fft, fftfreq
            
            data = np.asarray(data)
            if data.size < 4:
                return 1.0
            
            fft_result = fft(data)
            freqs = fftfreq(len(data))
            magnitude = np.abs(fft_result)
            
            # Calculate centroid
            centroid = np.sum(freqs * magnitude) / np.sum(magnitude)
            
            return float(abs(centroid))
            
        except Exception:
            return 1.0
    
